def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    zone_tiles = resm | comm | indm

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # All potential anchors: (plant_x, plant_y, wire_col, road_l, road_r)
    all_anchors = [
        # Primary row (y=50)
        (20, 50, 20, 19, 21),
        (60, 50, 60, 59, 61),
        (100, 50, 100, 99, 101),
        # Upper row (y=25)
        (20, 25, 20, 19, 21),
        (60, 25, 60, 59, 61),
        (100, 25, 100, 99, 101),
        # Lower row (y=75)
        (20, 75, 20, 19, 21),
        (60, 75, 60, 59, 61),
        (100, 75, 100, 99, 101),
        # Extra mid anchors
        (40, 37, 40, 39, 41),
        (80, 37, 80, 79, 81),
        (40, 62, 40, 39, 41),
        (80, 62, 80, 79, 81),
    ]

    def num_active():
        if pop < 50:   return 3
        if pop < 200:  return 4
        if pop < 500:  return 6
        if pop < 1000: return 9
        if pop < 2000: return 11
        return 13

    active_anchors = all_anchors[:num_active()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        has_plant = any(
            ib(px+dx, py+dy) and bool(pm[py+dy, px+dx])
            for dx in range(-3, 4) for dy in range(-3, 4)
            if ib(px+dx, py+dy)
        )
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 6):
                for dy2 in range(-r, r+1):
                    for dx2 in range(-r, r+1):
                        nx, ny = px+dx2, py+dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- HORIZONTAL WIRE CONNECTIONS between same-row anchors ----
    same_row_pairs = [
        (20, 60, 50), (60, 100, 50),
        (20, 60, 25), (60, 100, 25),
        (20, 60, 75), (60, 100, 75),
        (40, 80, 37), (40, 80, 62),
    ]
    for (x1, x2, ry) in same_row_pairs:
        for cx in range(min(x1,x2)+1, max(x1,x2)):
            if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                return (Tool.WIRE, cx, ry)

    # ---- VERTICAL WIRE SPINES ----
    pop_factor = min(40, pop // 8)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 18 - pop_factor)
        spine_bot = min(WORLD_H - 3, py + 18 + pop_factor)
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            for dy2 in range(-3, 4):
                ny = py + dy2
                if ib(wc, ny) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- ROAD COLUMNS flanking wire spines ----
    for (px, py, wc, rl, rr) in active_anchors:
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cyc = step % max(len(wire_rows), 1)
        for i in range(min(len(wire_rows), 4)):
            wr = wire_rows[(cyc + i) % len(wire_rows)]
            for rc in [rl, rr]:
                if ib(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

    # ---- HORIZONTAL CROSS-ROADS every 6 rows near each cluster ----
    for (px, py, wc, rl, rr) in active_anchors:
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        span_top = min(wire_rows)
        span_bot = max(wire_rows)
        for wr in range(span_top, span_bot+1, 6):
            x_lo = max(3, wc - 10)
            x_hi = min(WORLD_W-4, wc + 10)
            for rx in range(x_lo, x_hi+1):
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- PROXIMITY MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0=max(0,-dy2); sr1=min(WORLD_H,WORLD_H-dy2)
            sc0=max(0,-dx2); sc1=min(WORLD_W,WORLD_W-dx2)
            r0=max(0,dy2);   r1=min(WORLD_H,WORLD_H+dy2)
            c0=max(0,dx2);   c1=min(WORLD_W,WORLD_W+dx2)
            nbr_road[r0:r1,c0:c1] |= rm[sr0:sr1,sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-9, 10):
        for dx2 in range(-9, 10):
            sr0=max(0,-dy2); sr1=min(WORLD_H,WORLD_H-dy2)
            sc0=max(0,-dx2); sc1=min(WORLD_W,WORLD_W-dx2)
            r0=max(0,dy2);   r1=min(WORLD_H,WORLD_H+dy2)
            c0=max(0,dx2);   c1=min(WORLD_W,WORLD_W+dx2)
            nbr_wire[r0:r1,c0:c1] |= wm[sr0:sr1,sc0:sc1]
            nbr_wire[r0:r1,c0:c1] |= pm[sr0:sr1,sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2,nc2]) and not bool(zone_tiles[nr2,nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc) + np.abs(cys - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset*7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(nbr_wire[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 150:
        fire_spots = [
            (30,42),(70,42),(110,42),(30,58),(70,58),(110,58),
            (10,25),(50,25),(90,25),(10,75),(50,75),(90,75),
        ]
        for (sx,sy) in fire_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.FIRESTATION, sx, sy)
    if pop > 500:
        police_spots = [
            (30,35),(70,35),(110,35),(30,65),(70,65),(110,65),
            (10,40),(50,40),(90,40),(10,60),(50,60),(90,60),
        ]
        for (sx,sy) in police_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.POLICESTATION, sx, sy)
    if pop > 1000:
        stadiums = [(40,20),(80,20),(40,80),(80,80),(20,50),(100,50)]
        for (sx,sy) in stadiums:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)
    if pop > 2000:
        nuke_spots = [(30,12),(70,12),(30,87),(70,87)]
        for (sx,sy) in nuke_spots:
            has_p = any(
                ib(sx+dx,sy+dy) and bool(pm[sy+dy,sx+dx])
                for dx in range(-4,5) for dy in range(-4,5) if ib(sx+dx,sy+dy)
            )
            if not has_p and ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.NUCLEARPOWER, sx, sy)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step*13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset*5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap multiple power plants with wire and road connections."""
    actions = []
    # Three power plants: left, center, right
    # Center plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Left plant
    actions.append((Tool.COALPOWER, 25, 50))
    # Right plant
    actions.append((Tool.COALPOWER, 95, 50))

    # Wire spines for each plant
    for dy in range(-5, 6):
        actions.append((Tool.WIRE, 60, 50 + dy))
        actions.append((Tool.WIRE, 25, 50 + dy))
        actions.append((Tool.WIRE, 95, 50 + dy))

    # Initial roads flanking each wire spine
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone ratio targeting: balanced mix
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        # Industry first (provides jobs), then commercial (services), then residential
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of neighborhoods: 3 columns x 3 rows = 9 anchors
    # Each anchor has: (plant_x, plant_y, wire_col, road_left, road_right)
    all_anchors = [
        # Row 1 (top)
        (20, 20, 22, 21, 23),
        (60, 20, 62, 61, 63),
        (100, 20, 100, 98, 102),
        # Row 2 (middle)
        (20, 50, 22, 21, 23),
        (60, 50, 62, 61, 63),
        (95, 50, 95, 93, 97),
        # Row 3 (bottom)
        (20, 78, 22, 21, 23),
        (60, 78, 62, 61, 63),
        (100, 78, 100, 98, 102),
    ]

    def num_active_anchors():
        if pop < 100:
            return 1
        elif pop < 300:
            return 2
        elif pop < 700:
            return 4
        elif pop < 1500:
            return 6
        elif pop < 3000:
            return 8
        else:
            return len(all_anchors)

    active_anchors = all_anchors[:num_active_anchors()]

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py, wc, rl, rr) in active_anchors:
        # Check if there's a plant within 5 tiles
        has_plant = False
        for dx in range(-5, 6):
            for dy in range(-5, 6):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place at anchor location
            for r in range(0, 12):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE SPINES ----
    pop_factor = min(35, pop // 10)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 20 - pop_factor)
        spine_bot = min(WORLD_H - 3, py + 20 + pop_factor)

        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_col:
            # Seed wire near plant
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(wc, ny) and (bool(em[ny, wc]) or bool(wm[ny, wc])) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE CONNECTIONS (connect same-row anchors) ----
    # Connect all same-row pairs with horizontal wires
    row_groups = {}
    for i, (px, py, wc, rl, rr) in enumerate(active_anchors):
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append((wc, py))

    for row_y, cols in row_groups.items():
        if len(cols) < 2:
            continue
        cols_sorted = sorted(cols, key=lambda c: c[0])
        for i in range(len(cols_sorted) - 1):
            c1x = cols_sorted[i][0]
            c2x = cols_sorted[i + 1][0]
            for cx in range(c1x, c2x + 1):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- VERTICAL WIRE CONNECTIONS (connect same-column anchors) ----
    col_groups = {}
    for i, (px, py, wc, rl, rr) in enumerate(active_anchors):
        if wc not in col_groups:
            col_groups[wc] = []
        col_groups[wc].append((wc, py))

    for col_x, rows in col_groups.items():
        if len(rows) < 2:
            continue
        rows_sorted = sorted(rows, key=lambda r: r[1])
        for i in range(len(rows_sorted) - 1):
            r1y = rows_sorted[i][1]
            r2y = rows_sorted[i + 1][1]
            mid_y = (r1y + r2y) // 2
            if ib(col_x, mid_y) and bool(em[mid_y, col_x]) and not bool(pm[mid_y, col_x]):
                return (Tool.WIRE, col_x, mid_y)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 3) % 3
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at key y-levels ----
    # Connect neighborhoods horizontally
    if pop > 100:
        for conn_y in [20, 50, 78]:
            for cx in range(5, WORLD_W - 5):
                if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                    # Only build road here if near wire
                    near_wire = False
                    for dy2 in range(-6, 7):
                        for dx2 in range(-6, 7):
                            nx2, ny2 = cx + dx2, conn_y + dy2
                            if ib(nx2, ny2) and (bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                                near_wire = True
                                break
                        if near_wire:
                            break
                    if near_wire:
                        return (Tool.ROAD, cx, conn_y)

    # ---- BUILD PROXIMITY MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize by proximity to active anchors
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float) * 0.5
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 150:
        fire_spots = [
            (35, 20), (75, 20), (35, 50), (75, 50),
            (35, 78), (75, 78), (10, 35), (110, 35),
            (10, 65), (110, 65), (60, 10), (60, 90),
            (50, 35), (70, 35), (50, 65), (70, 65),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (30, 25), (80, 25), (30, 55), (80, 55),
            (30, 75), (80, 75), (55, 15), (55, 85),
            (15, 50), (105, 50), (60, 35), (60, 65),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1200:
        stadium_spots = [
            (45, 12), (75, 12), (45, 88), (75, 88),
            (10, 30), (110, 30), (10, 70), (110, 70),
            (60, 45), (40, 60),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        # Nuclear plants for extra power
        nuke_spots = [(40, 10), (80, 10), (40, 90), (80, 90)]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 4000:
        for asp in [(60, 8), (10, 50), (110, 50)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)
        for sp in [(10, 92), (110, 92), (60, 92)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- FALLBACK: extend wire laterally ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 25)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plants and initial infrastructure at multiple sites."""
    actions = []
    # Three power plants: left, center, right
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Wire spines from each plant
    for py in [50]:
        for px, wc in [(20, 22), (60, 62), (100, 102)]:
            for dy in range(-5, 6):
                actions.append((Tool.WIRE, wc, py + dy))
    # Initial roads flanking wire spines
    for py in [50]:
        for px, wc, rl, rr in [(20, 22, 21, 23), (60, 62, 61, 63), (100, 102, 101, 103)]:
            for dy in range(-5, 6):
                actions.append((Tool.ROAD, rl, py + dy))
                actions.append((Tool.ROAD, rr, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- NEIGHBORHOODS: (plant_x, plant_y, wire_col, road_l, road_r) ---
    # Dense grid covering the map with ~30-column spacing
    all_anchors = [
        # Row y=20
        (10, 20, 12, 11, 13),
        (40, 20, 42, 41, 43),
        (70, 20, 72, 71, 73),
        (100, 20, 102, 101, 103),
        # Row y=50 (center)
        (20, 50, 22, 21, 23),
        (50, 50, 52, 51, 53),
        (80, 50, 82, 81, 83),
        (110, 50, 112, 111, 113),
        # Row y=80
        (10, 80, 12, 11, 13),
        (40, 80, 42, 41, 43),
        (70, 80, 72, 71, 73),
        (100, 80, 102, 101, 103),
        # Extra mid-points
        (30, 35, 32, 31, 33),
        (60, 35, 62, 61, 63),
        (90, 35, 92, 91, 93),
        (30, 65, 32, 31, 33),
        (60, 65, 62, 61, 63),
        (90, 65, 92, 91, 93),
    ]

    # Unlock anchors progressively
    def num_active_anchors():
        if pop < 100:
            return 3
        elif pop < 500:
            return 5
        elif pop < 1000:
            return 8
        elif pop < 2000:
            return 12
        elif pop < 4000:
            return 15
        else:
            return len(all_anchors)

    active_anchors = all_anchors[:num_active_anchors()]

    # --- PHASE 1: ENSURE POWER PLANTS ---
    for (px, py, wc, rl, rr) in active_anchors:
        # Check if there's already a plant nearby (within 6 tiles)
        has_plant = False
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant at anchor position or nearby empty cell
            placed = False
            for r in range(8):
                if placed:
                    break
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: WIRE SPINE BUILDING (vertical) ---
    pop_factor = min(35, pop // 10)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 20 - pop_factor)
        spine_bot = min(WORLD_H - 3, py + 20 + pop_factor)

        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_col:
            # Seed wire near the plant
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(wc, ny) and (bool(em[ny, wc])) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            # Extend downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            # Extend upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # --- PHASE 3: HORIZONTAL WIRE CONNECTIONS ---
    # Connect anchors in same row and between rows
    for i in range(len(active_anchors)):
        for j in range(i + 1, len(active_anchors)):
            px1, py1, wc1, _, _ = active_anchors[i]
            px2, py2, wc2, _, _ = active_anchors[j]
            # Same row: connect wire columns horizontally
            if abs(py1 - py2) <= 5:
                mid_y = (py1 + py2) // 2
                min_x = min(wc1, wc2)
                max_x = max(wc1, wc2)
                if max_x - min_x < 60:  # only close anchors
                    for cx in range(min_x, max_x + 1):
                        if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                            # Only if at least one end has wire
                            if bool(wm[mid_y, max(0, cx-1)]) or bool(wm[mid_y, min(WORLD_W-1, cx+1)]):
                                return (Tool.WIRE, cx, mid_y)
            # Same column: connect vertically
            elif abs(wc1 - wc2) <= 5:
                conn_x = (wc1 + wc2) // 2
                min_y = min(py1, py2)
                max_y = max(py1, py2)
                if max_y - min_y < 50:
                    for cy in range(min_y, max_y + 1):
                        if ib(conn_x, cy) and bool(em[cy, conn_x]) and not bool(pm[cy, conn_x]):
                            if bool(wm[max(0, cy-1), conn_x]) or bool(wm[min(WORLD_H-1, cy+1), conn_x]):
                                return (Tool.WIRE, conn_x, cy)

    # --- PHASE 4: ROAD BUILDING flanking wire spines ---
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 3) % 6
        for wr in wire_in_col[cycle::6]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # --- PHASE 5: HORIZONTAL ROADS connecting neighborhoods ---
    # Build horizontal roads at strategic y levels
    for conn_y in [20, 35, 50, 65, 80]:
        found_wire_in_row = np.any(wm[conn_y, :]) or np.any(wm[max(0, conn_y-1), :]) or np.any(wm[min(WORLD_H-1, conn_y+1), :])
        if not found_wire_in_row:
            continue
        # Check if there are some roads already in this row
        road_in_row = int(np.sum(rm[conn_y, :]))
        if road_in_row < 5 or pop > 200:
            for cx in range(5, WORLD_W - 5):
                if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                    # Only place if adjacent wire or road exists
                    has_neighbor = False
                    for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx2, ny2 = cx + ddx, conn_y + ddy
                        if ib(nx2, ny2) and (bool(rm[ny2, nx2]) or bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                            has_neighbor = True
                            break
                    if has_neighbor:
                        return (Tool.ROAD, cx, conn_y)

    # --- BUILD PROXIMITY MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-10, 11):
        for dx in range(-10, 11):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near active anchor wire columns
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float) * 0.6
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES (scaled with population) ---
    if pop > 150:
        fire_spots = [
            (25, 20), (55, 20), (85, 20), (110, 20),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (25, 80), (55, 80), (85, 80), (110, 80),
            (35, 35), (65, 35), (95, 35),
            (35, 65), (65, 65), (95, 65),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (20, 25), (50, 25), (80, 25), (108, 25),
            (20, 45), (50, 45), (80, 45), (108, 45),
            (20, 55), (50, 55), (80, 55), (108, 55),
            (20, 75), (50, 75), (80, 75), (108, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (30, 10), (60, 10), (90, 10),
            (30, 90), (60, 90), (90, 90),
            (5, 30), (5, 70), (115, 30), (115, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuclear_spots = [
            (35, 10), (85, 10), (35, 90), (85, 90),
            (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        for asp in [(60, 8), (8, 50), (112, 50), (60, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)
        for sp in [(10, 92), (110, 92), (60, 92), (10, 8), (110, 8)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    if pop > 4000:
        # Parks for land value boost
        park_ys, park_xs = np.where(em)
        if len(park_xs) > 0:
            pk = (step * 17) % len(park_xs)
            for off in range(min(len(park_xs), 30)):
                k = (pk + off * 11) % len(park_xs)
                ppx, ppy = int(park_xs[k]), int(park_ys[k])
                if bool(nbr_road[ppy, ppx]):
                    return (Tool.PARK, ppx, ppy)

    # --- FALLBACK: extend wire laterally ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- ABSOLUTE FALLBACK: place coal plant if no power found ---
    if not np.any(pm):
        for y in range(10, 90):
            for x in range(10, 110):
                if bool(em[y, x]):
                    return (Tool.COALPOWER, x, y)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wires + seed roads for fast start"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Connect them with horizontal wire
    for x in range(32, 89):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(44, 57):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Seed roads flanking wire spines
    for y in range(44, 57):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
        actions.append((Tool.ROAD, 89, y))
        actions.append((Tool.ROAD, 91, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Population-based ratios ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    pop = obs.city_pop
    step = obs.step

    # --- Define plant hubs across the map ---
    # More plants = more zones possible
    base_plants = [(30, 50), (90, 50)]
    extra_plants = []
    if pop > 200:
        extra_plants += [(60, 25), (60, 75)]
    if pop > 500:
        extra_plants += [(10, 30), (110, 30), (10, 70), (110, 70)]
    if pop > 1000:
        extra_plants += [(30, 15), (90, 15), (30, 85), (90, 85)]
    if pop > 2000:
        extra_plants += [(60, 10), (60, 90), (20, 50), (100, 50)]

    all_plants = base_plants + extra_plants

    # --- Ensure plants exist ---
    for px, py in all_plants:
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            if ib(px, py):
                return (Tool.COALPOWER, px, py)

    # --- Build wire network: connect all plants ---
    # First ensure each plant has local wires around it
    for px, py in all_plants:
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and em[ny, nx] and not pm[ny, nx]:
                    # Check if this wire position is isolated
                    has_neighbor_wire = False
                    for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nnx, nny = nx+ddx, ny+ddy
                        if ib(nnx, nny) and (wm[nny, nnx] or pm[nny, nnx]):
                            has_neighbor_wire = True
                            break
                    if not has_neighbor_wire and not (wm[ny, nx] or pm[ny, nx]):
                        pass  # skip isolated positions for now

    # --- Grow wire from existing wire/plant toward uncovered zones ---
    # Reactively extend wires toward empty areas that need power
    wire_ys, wire_xs = np.where(wm | pm)

    # Find directions to grow wire to cover more of the map
    if len(wire_xs) > 0:
        # Target: extend wires in systematic grid pattern
        # Check if major horizontal/vertical corridors are wired

        # Horizontal wire spine at row 50 (main)
        for x in range(1, WORLD_W - 1):
            if em[50, x] and not pm[50, x]:
                # Check if neighbor has wire
                if (ib(x-1,50) and (wm[50,x-1] or pm[50,x-1])) or \
                   (ib(x+1,50) and (wm[50,x+1] or pm[50,x+1])):
                    return (Tool.WIRE, x, 50)

        # Vertical spines from plant hubs
        for px, py in all_plants:
            # Extend wire up and down from plant
            extent = min(35, 10 + pop // 100)
            spine_top = max(3, py - extent)
            spine_bot = min(WORLD_H - 4, py + extent)

            # Find current wire extent on this column
            col_wires = [r for r in range(WORLD_H) if ib(px, r) and (wm[r, px] or pm[r, px])]
            if col_wires:
                mn, mx = min(col_wires), max(col_wires)
                if mx < spine_bot:
                    ny = mx + 1
                    if ib(px, ny) and em[ny, px] and not pm[ny, px]:
                        return (Tool.WIRE, px, ny)
                if mn > spine_top:
                    ny = mn - 1
                    if ib(px, ny) and em[ny, px] and not pm[ny, px]:
                        return (Tool.WIRE, px, ny)

        # Horizontal cross-wires at various rows
        cross_rows = [25, 35, 45, 50, 55, 65, 75]
        if pop > 300:
            cross_rows += [15, 85]
        if pop > 800:
            cross_rows += [10, 90]

        for cr in cross_rows:
            if not ib(0, cr):
                continue
            row_has_wire = wm[cr, :] | pm[cr, :]
            # Find gaps and fill them if adjacent to wire
            for x in range(1, WORLD_W - 1):
                if em[cr, x] and not pm[cr, x]:
                    if row_has_wire[x-1] or (x+1 < WORLD_W and row_has_wire[x+1]):
                        return (Tool.WIRE, x, cr)

    # --- Build road network ---
    # Road grid: vertical roads flanking wire spines, horizontal cross-roads

    # Vertical road columns next to wire spines
    road_offsets = [-1, 1]
    for px, py in all_plants:
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (wm[r, px] or pm[r, px])]
        if not col_wires:
            continue
        mn_w, mx_w = min(col_wires), max(col_wires)
        for roff in road_offsets:
            rc = px + roff
            if not ib(rc, py):
                continue
            # Build road along wire extent
            for wr in range(mn_w, mx_w + 1):
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # Horizontal roads at cross-wire rows
    h_road_rows = [24, 34, 44, 51, 56, 64, 74]
    if pop > 300:
        h_road_rows += [14, 84]
    if pop > 800:
        h_road_rows += [9, 91]

    for hr in h_road_rows:
        if not ib(0, hr):
            continue
        # Build horizontal road across the map where wire is above/below
        wire_above = (hr > 0 and (wm[hr-1, :] | pm[hr-1, :]).any())
        wire_below = (hr < WORLD_H-1 and (wm[hr+1, :] | pm[hr+1, :]).any())
        if wire_above or wire_below:
            for x in range(2, WORLD_W - 2):
                if ib(x, hr) and em[hr, x] and not pm[hr, x]:
                    return (Tool.ROAD, x, hr)

    # --- Proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Prefer locations closest to plant hubs
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Services ---
    if pop > 100:
        fire_spots = [(28, 42), (32, 42), (88, 42), (92, 42),
                      (28, 58), (32, 58), (88, 58), (92, 58),
                      (58, 22), (62, 22), (58, 78), (62, 78)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if pop > 300:
        police_spots = [(25, 40), (35, 40), (85, 40), (95, 40),
                        (25, 60), (35, 60), (85, 60), (95, 60)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if pop > 600:
        for stx, sty in [(45, 35), (75, 35), (45, 65), (75, 65)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)
    if pop > 1000:
        for apx, apy in [(55, 20), (55, 80)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)
    if pop > 1500:
        for spx, spy in [(10, 50), (110, 50)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 50)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire ---
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a row with wire and road connections."""
    actions = []
