def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone ratio: balanced I/C/R mix
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE LOGIC based on population ---
    # Phase 0: Build power infrastructure
    # Phase 1: Expand roads + zones near power
    # Phase 2: Scale up infrastructure
    # Phase 3: Civic services + full map coverage

    # ---- BUILD POWER GRID ----
    # Define a grid of power plant locations across the map
    plant_targets = [
        (20, 25), (60, 25), (100, 25),
        (20, 50), (60, 50), (100, 50),
        (20, 75), (60, 75), (100, 75),
    ]
    # How many plants to have active depends on pop
    if pop < 200:
        n_plants = 3
    elif pop < 800:
        n_plants = 6
    else:
        n_plants = 9

    active_plants = plant_targets[:n_plants]

    # Check each plant target, place if missing
    for (px, py) in active_plants:
        has_plant = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Find nearby empty spot
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- BUILD WIRE NETWORK ----
    # Vertical wire columns at plant x positions: 20, 60, 100
    # Horizontal wire rows at y positions: 25, 50, 75
    wire_cols = [20, 60, 100]
    wire_rows = [25, 50, 75]

    # Extend vertical wire columns
    for col_x in wire_cols:
        for row_y in range(5, WORLD_H - 5):
            if ib(col_x, row_y):
                if bool(em[row_y, col_x]) and not bool(pm[row_y, col_x]):
                    # Only place if adjacent to existing wire or plant
                    adj_power = False
                    for dy in [-1, 1]:
                        ny = row_y + dy
                        if ib(col_x, ny) and (bool(wm[ny, col_x]) or bool(pm[ny, col_x])):
                            adj_power = True
                    if adj_power:
                        return (Tool.WIRE, col_x, row_y)

    # Extend horizontal wire rows
    for row_y in wire_rows:
        for col_x in range(5, WORLD_W - 5):
            if ib(col_x, row_y):
                if bool(em[row_y, col_x]) and not bool(pm[row_y, col_x]):
                    adj_power = False
                    for dx in [-1, 1]:
                        nx = col_x + dx
                        if ib(nx, row_y) and (bool(wm[row_y, nx]) or bool(pm[row_y, nx])):
                            adj_power = True
                    if adj_power:
                        return (Tool.WIRE, col_x, row_y)

    # ---- BUILD ROAD GRID ----
    # Roads parallel to wire columns (1 tile away on each side)
    # Road rows at regular intervals
    road_row_ys = list(range(10, WORLD_H - 10, 8))
    road_col_xs = [18, 22, 58, 62, 98, 102]

    # Add more road columns as population grows
    if pop > 300:
        road_col_xs += [38, 42, 78, 82]
    if pop > 800:
        road_col_xs += [8, 12, 48, 52, 68, 72, 108, 112]

    # Build vertical road columns
    for col_x in road_col_xs:
        if not ib(col_x, 0):
            continue
        # Check if road exists nearby
        col_roads = [r for r in range(WORLD_H) if ib(col_x, r) and bool(rm[r, col_x])]
        # Extend downward from existing roads
        if col_roads:
            max_r = max(col_roads)
            nr = max_r + 1
            if ib(col_x, nr) and bool(em[nr, col_x]) and not bool(pm[nr, col_x]):
                # Check near wire
                near_wire = any(
                    ib(col_x + dx, nr + dy) and (bool(wm[nr + dy, col_x + dx]) or bool(pm[nr + dy, col_x + dx]))
                    for dx in range(-8, 9) for dy in range(-8, 9)
                    if ib(col_x + dx, nr + dy)
                )
                if near_wire:
                    return (Tool.ROAD, col_x, nr)
            # Extend upward
            min_r = min(col_roads)
            nr = min_r - 1
            if ib(col_x, nr) and bool(em[nr, col_x]) and not bool(pm[nr, col_x]):
                near_wire = any(
                    ib(col_x + dx, nr + dy) and (bool(wm[nr + dy, col_x + dx]) or bool(pm[nr + dy, col_x + dx]))
                    for dx in range(-8, 9) for dy in range(-8, 9)
                    if ib(col_x + dx, nr + dy)
                )
                if near_wire:
                    return (Tool.ROAD, col_x, nr)
        else:
            # Seed road at middle if near wire
            mid_y = 50
            if ib(col_x, mid_y) and bool(em[mid_y, col_x]) and not bool(pm[mid_y, col_x]):
                near_wire = any(
                    ib(col_x + dx, mid_y + dy) and (bool(wm[mid_y + dy, col_x + dx]) or bool(pm[mid_y + dy, col_x + dx]))
                    for dx in range(-8, 9) for dy in range(-8, 9)
                    if ib(col_x + dx, mid_y + dy)
                )
                if near_wire:
                    return (Tool.ROAD, col_x, mid_y)

    # Build horizontal road rows
    for row_y in road_row_ys:
        row_roads = [c for c in range(WORLD_W) if ib(c, row_y) and bool(rm[row_y, c])]
        if row_roads:
            max_c = max(row_roads)
            nc = max_c + 1
            if ib(nc, row_y) and bool(em[row_y, nc]) and not bool(pm[row_y, nc]):
                near_wire = any(
                    ib(nc + dx, row_y + dy) and (bool(wm[row_y + dy, nc + dx]) or bool(pm[row_y + dy, nc + dx]))
                    for dx in range(-8, 9) for dy in range(-8, 9)
                    if ib(nc + dx, row_y + dy)
                )
                if near_wire:
                    return (Tool.ROAD, nc, row_y)
            min_c = min(row_roads)
            nc = min_c - 1
            if ib(nc, row_y) and bool(em[row_y, nc]) and not bool(pm[row_y, nc]):
                near_wire = any(
                    ib(nc + dx, row_y + dy) and (bool(wm[row_y + dy, nc + dx]) or bool(pm[row_y + dy, nc + dx]))
                    for dx in range(-8, 9) for dy in range(-8, 9)
                    if ib(nc + dx, row_y + dy)
                )
                if near_wire:
                    return (Tool.ROAD, nc, row_y)
        else:
            # Seed road row at x=20 if near wire
            for seed_x in [20, 60, 100]:
                if ib(seed_x, row_y) and bool(em[row_y, seed_x]) and not bool(pm[row_y, seed_x]):
                    near_wire = any(
                        ib(seed_x + dx, row_y + dy) and (bool(wm[row_y + dy, seed_x + dx]) or bool(pm[row_y + dy, seed_x + dx]))
                        for dx in range(-8, 9) for dy in range(-8, 9)
                        if ib(seed_x + dx, row_y + dy)
                    )
                    if near_wire:
                        return (Tool.ROAD, seed_x, row_y)

    # ---- ZONE PLACEMENT ----
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # Candidate cells: empty, near road, near wire, not edge
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: closer to road + closer to wire spine
        best_score = np.full(len(cxs), 1e9)
        for wc in wire_cols:
            for wr in wire_rows:
                d = np.abs(cxs - wc).astype(float) + np.abs(cys - wr).astype(float)
                best_score = np.minimum(best_score, d)
        order = np.argsort(best_score)
        # Stagger starting index by step to avoid always checking same spots
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 60)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- CIVIC SERVICES ----
    if pop > 150:
        fire_spots = [
            (30, 20), (70, 20), (110, 20),
            (10, 40), (50, 40), (90, 40),
            (30, 60), (70, 60), (110, 60),
            (10, 80), (50, 80), (90, 80),
            (40, 10), (80, 10), (40, 90), (80, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (35, 15), (75, 15), (115, 15),
            (15, 35), (55, 35), (95, 35),
            (35, 65), (75, 65), (115, 65),
            (15, 85), (55, 85), (95, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (45, 12), (85, 12), (10, 50), (110, 50),
            (45, 88), (85, 88), (60, 30), (60, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (40, 8), (80, 8), (40, 92), (80, 92),
            (8, 30), (112, 30), (8, 70), (112, 70),
        ]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 4000:
        airport_spots = [(60, 8), (10, 50), (110, 50), (60, 92)]
        for (ax, ay) in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)
        seaport_spots = [(10, 92), (110, 8), (10, 8), (110, 92)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    return None

def init(obs, state):
    """Bootstrap: place coal plants and initial roads/wires at 3 sites."""
    actions = []
    # Three power plants spread across the map
    for px, py in [(20, 50), (60, 50), (100, 50)]:
