def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- BUILD PROXIMITY MASKS ----
    # Road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/plant proximity (within 6 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Phase counter for rotating through tasks
    phase = state.get('phase', 0)
    state['phase'] = (phase + 1) % 100

    # ---- DEFINE ACTIVE PLANT COLUMNS based on population ----
    # We want many neighborhood columns: 7 wire columns across the map
    wire_cols = [10, 25, 40, 60, 75, 95, 110]
    plant_rows = [20, 50, 78]  # plant positions per column

    def num_active_cols():
        if pop < 50:
            return 1
        elif pop < 200:
            return 2
        elif pop < 500:
            return 3
        elif pop < 1000:
            return 4
        elif pop < 2000:
            return 5
        elif pop < 4000:
            return 6
        else:
            return 7

    n_cols = num_active_cols()
    active_cols = wire_cols[:n_cols]

    # ---- ENSURE POWER PLANTS in active columns ----
    for wc in active_cols:
        for pr in plant_rows[:max(1, n_cols // 3)]:
            # Check if there's a plant nearby
            has_plant = False
            for dx in range(-7, 8):
                for dy in range(-7, 8):
                    nx, ny = wc + dx, pr + dy
                    if ib(nx, ny) and bool(pm[ny, nx]):
                        has_plant = True
                        break
                if has_plant:
                    break
            if not has_plant:
                # Place plant at or near (wc, pr)
                for r in range(0, 15):
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if r > 0 and abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = wc + dx2, pr + dy2
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE SPINES from plants ----
    spine_half = min(40, 10 + pop // 20)
    for wc in active_cols:
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            # Seed wire near a plant in this column
            for pr in plant_rows:
                for dy2 in range(-8, 9):
                    ny = pr + dy2
                    if ib(wc, ny) and (bool(em[ny, wc]) or bool(wm[ny, wc])) and not bool(pm[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            target_top = max(2, 50 - spine_half)
            target_bot = min(WORLD_H - 3, 50 + spine_half)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- EXTEND ROADS flanking wire spines ----
    road_half = min(40, 8 + pop // 25)
    for idx, wc in enumerate(active_cols):
        rl, rr = wc - 1, wc + 1
        wire_in_col = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not wire_in_col:
            continue
        target_top = max(2, 50 - road_half)
        target_bot = min(WORLD_H - 3, 50 + road_half)
        # Build roads alongside wire
        cycle = (step + idx * 3) % 3
        for wr in wire_in_col[cycle::3]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL WIRE CONNECTIONS between neighboring columns ----
    for i in range(len(active_cols) - 1):
        c1 = active_cols[i]
        c2 = active_cols[i + 1]
        # Connect at multiple y-levels
        for conn_y in [20, 35, 50, 65, 80]:
            # Check if connection already exists
            connected = True
            for cx in range(c1, c2 + 1):
                if ib(cx, conn_y) and not bool(wm[conn_y, cx]) and not bool(pm[conn_y, cx]) and not bool(rm[conn_y, cx]):
                    connected = False
                    break
            if not connected:
                for cx in range(c1, c2 + 1):
                    if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                        return (Tool.WIRE, cx, conn_y)

    # ---- HORIZONTAL ROAD CONNECTIONS between columns ----
    if pop > 80:
        for conn_y in [18, 33, 48, 63, 78]:
            road_in_row = [c for c in range(WORLD_W) if ib(c, conn_y) and bool(rm[conn_y, c])]
            if not road_in_row:
                continue
            min_r = min(road_in_row)
            max_r = max(road_in_row)
            # Extend leftward to next active column
            for wc in sorted(active_cols):
                if wc - 1 < min_r:
                    for cx in range(wc - 1, min_r):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)
            # Extend rightward
            for wc in sorted(active_cols, reverse=True):
                if wc + 1 > max_r:
                    for cx in range(max_r + 1, wc + 2):
                        if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                            return (Tool.ROAD, cx, conn_y)

    # ---- ZONE PLACEMENT: place zones near road+wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active wire columns
        best_dist = np.full(len(cxs), 999999.0)
        for wc in active_cols:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - 50).astype(float) * 0.3
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- EXTEND ROADS from existing road ends near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 100:
        fire_spots = [
            (30, 30), (70, 30), (110, 30),
            (10, 50), (50, 50), (90, 50),
            (30, 70), (70, 70), (110, 70),
            (20, 15), (60, 15), (100, 15),
            (20, 85), (60, 85), (100, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (15, 25), (45, 25), (75, 25), (105, 25),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 75), (45, 75), (75, 75), (105, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (35, 12), (75, 12), (35, 88), (75, 88),
            (10, 35), (110, 35), (10, 65), (110, 65),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        # Nuclear plants for extra power coverage
        nuke_spots = [
            (35, 10), (85, 10), (35, 90), (85, 90),
            (10, 30), (110, 30), (10, 70), (110, 70),
        ]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3500:
        for asp in [(60, 8), (5, 50), (115, 50)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 90), (115, 90), (60, 95)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 300:
        park_cands = []
        zone_map = resm | comm | indm
        zone_ys, zone_xs = np.where(zone_map)
        for i in range(min(len(zone_xs), 20)):
            k = (step * 3 + i * 17) % len(zone_xs)
            zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
            for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3)]:
                nx2, ny2 = zx2 + dx2, zy2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 5 coal plants spread across map + connecting wires + seed roads"""
    actions = []
    # 5 plants: far-left, left-center, center, right-center, far-right
    plants = [(15, 50), (38, 50), (60, 50), (82, 50), (105, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spine connecting all plants
    for x in range(17, 38):
        actions.append((Tool.WIRE, x, 50))
    for x in range(40, 60):
        actions.append((Tool.WIRE, x, 50))
    for x in range(62, 82):
        actions.append((Tool.WIRE, x, 50))
    for x in range(84, 105):
        actions.append((Tool.WIRE, x, 50))
    # Seed vertical wires at each plant
    for px, py in plants:
        for dy in [-2, -1, 1, 2]:
            actions.append((Tool.WIRE, px, py + dy))
    # Seed roads above and below each plant
    for px, py in plants:
        for rx in range(px - 3, px + 4):
            actions.append((Tool.ROAD, rx, py - 3))
            actions.append((Tool.ROAD, rx, py + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- CLUSTER DEFINITIONS ----
    # 15 clusters covering the whole map in 3 rows x 5 columns
    all_clusters = [
        # Top row y=20
        {'cx': 15, 'cy': 20, 'wc': 15, 'rl': 14, 'rr': 16},
        {'cx': 38, 'cy': 20, 'wc': 38, 'rl': 37, 'rr': 39},
        {'cx': 60, 'cy': 20, 'wc': 60, 'rl': 59, 'rr': 61},
        {'cx': 82, 'cy': 20, 'wc': 82, 'rl': 81, 'rr': 83},
        {'cx': 105, 'cy': 20, 'wc': 105, 'rl': 104, 'rr': 106},
        # Middle row y=50
        {'cx': 15, 'cy': 50, 'wc': 15, 'rl': 14, 'rr': 16},
        {'cx': 38, 'cy': 50, 'wc': 38, 'rl': 37, 'rr': 39},
        {'cx': 60, 'cy': 50, 'wc': 60, 'rl': 59, 'rr': 61},
        {'cx': 82, 'cy': 50, 'wc': 82, 'rl': 81, 'rr': 83},
        {'cx': 105, 'cy': 50, 'wc': 105, 'rl': 104, 'rr': 106},
        # Bottom row y=80
        {'cx': 15, 'cy': 80, 'wc': 15, 'rl': 14, 'rr': 16},
        {'cx': 38, 'cy': 80, 'wc': 38, 'rl': 37, 'rr': 39},
        {'cx': 60, 'cy': 80, 'wc': 60, 'rl': 59, 'rr': 61},
        {'cx': 82, 'cy': 80, 'wc': 82, 'rl': 81, 'rr': 83},
        {'cx': 105, 'cy': 80, 'wc': 105, 'rl': 104, 'rr': 106},
    ]

    # Progressively unlock clusters based on population
    def num_active():
        if pop < 50:   return 5   # just middle row
        if pop < 200:  return 7
        if pop < 500:  return 10
        if pop < 1000: return 12
        return len(all_clusters)

    active_clusters = all_clusters[:num_active()]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    plant_targets = [
        (15, 50), (38, 50), (60, 50), (82, 50), (105, 50),
        (15, 20), (38, 20), (60, 20), (82, 20), (105, 20),
        (15, 80), (38, 80), (60, 80), (82, 80), (105, 80),
    ]
    n_plants_needed = 5 if pop < 200 else (10 if pop < 1000 else 15)
    for px, py in plant_targets[:n_plants_needed]:
        has_plant = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if ib(px, py):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: WIRE SPINE EXTENSION (vertical per cluster) ----
    pop_factor = min(30, pop // 15)
    spine_extent = 15 + pop_factor

    for cl in active_clusters:
        wc = cl['wc']
        cy = cl['cy']
        spine_top = max(2, cy - spine_extent)
        spine_bot = min(WORLD_H - 3, cy + spine_extent)

        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            for dy in range(-3, 4):
                ny = cy + dy
                if ib(wc, ny) and not bool(pm[ny, wc]) and bool(em[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # ---- PHASE 3: HORIZONTAL WIRE CONNECTIONS ----
    # Connect same-column clusters vertically (top-mid, mid-bottom)
    col_pairs = [
        (15, 20, 15, 50), (15, 50, 15, 80),
        (38, 20, 38, 50), (38, 50, 38, 80),
        (60, 20, 60, 50), (60, 50, 60, 80),
        (82, 20, 82, 50), (82, 50, 82, 80),
        (105, 20, 105, 50), (105, 50, 105, 80),
    ]
    for wc, y1, wc2, y2 in col_pairs:
        if wc not in [cl['wc'] for cl in active_clusters]:
            continue
        min_y, max_y = min(y1, y2), max(y1, y2)
        for cy in range(min_y, max_y + 1):
            if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                # Only extend if connected to existing wire
                has_nbr = False
                for dd in [-1, 1]:
                    ny2 = cy + dd
                    if ib(wc, ny2) and (bool(wm[ny2, wc]) or bool(pm[ny2, wc])):
                        has_nbr = True
                        break
                if has_nbr:
                    return (Tool.WIRE, wc, cy)

    # Connect horizontal wire between clusters in same row
    row_y_vals = [20, 50, 80]
    col_x_vals = [15, 38, 60, 82, 105]
    for ry in row_y_vals:
        for i in range(len(col_x_vals) - 1):
            x1, x2 = col_x_vals[i], col_x_vals[i + 1]
            # Check both clusters are active
            c1_active = any(cl['cx'] == x1 and cl['cy'] == ry for cl in active_clusters)
            c2_active = any(cl['cx'] == x2 and cl['cy'] == ry for cl in active_clusters)
            if not (c1_active and c2_active):
                continue
            for cx in range(x1 + 2, x2 - 1):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    # Check neighbor wire
                    has_nbr = False
                    for dd in [-1, 1]:
                        nx2 = cx + dd
                        if ib(nx2, ry) and (bool(wm[ry, nx2]) or bool(pm[ry, nx2])):
                            has_nbr = True
                            break
                    if has_nbr:
                        return (Tool.WIRE, cx, ry)

    # ---- PHASE 4: ROAD BUILDING ----
    for idx, cl in enumerate(active_clusters):
        wc = cl['wc']
        cy = cl['cy']
        rl = cl['rl']
        rr = cl['rr']
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = (step + idx * 4) % 8
        for wr in wire_rows[cycle::8]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- PHASE 5: HORIZONTAL ARTERIAL ROADS ----
    artery_ys = [20, 35, 50, 65, 80]
    for conn_y in artery_ys:
        has_wire = np.any(wm[max(0,conn_y-2):min(WORLD_H,conn_y+3), :])
        if not has_wire:
            continue
        road_count = int(np.sum(rm[conn_y, :]))
        if road_count < 80:  # keep extending
            for cx in range(3, WORLD_W - 3):
                if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                    # Check adjacency to road/wire/plant
                    has_nbr = False
                    for ddx, ddy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nx2, ny2 = cx + ddx, conn_y + ddy
                        if ib(nx2, ny2) and (bool(rm[ny2, nx2]) or bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                            has_nbr = True
                            break
                    if has_nbr:
                        return (Tool.ROAD, cx, conn_y)

    # ---- BUILD PROXIMITY MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for cl in active_clusters:
            d = np.abs(cxs - cl['cx']).astype(float) + np.abs(cys - cl['cy']).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 50)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scaled with population) ----
    if pop > 100:
        fire_spots = [
            (20, 20), (45, 20), (70, 20), (95, 20),
            (20, 50), (45, 50), (75, 50), (100, 50),
            (20, 80), (45, 80), (70, 80), (95, 80),
            (33, 35), (60, 35), (87, 35),
            (33, 65), (60, 65), (87, 65),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (25, 25), (50, 25), (75, 25), (100, 25),
            (25, 45), (50, 45), (75, 45), (100, 45),
            (25, 55), (50, 55), (75, 55), (100, 55),
            (25, 75), (50, 75), (75, 75), (100, 75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (30, 10), (60, 10), (90, 10),
            (30, 90), (60, 90), (90, 90),
            (5, 30), (115, 30), (5, 70), (115, 70),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        # Upgrade to nuclear for more power
        nuclear_spots = [
            (30, 10), (90, 10), (30, 90), (90, 90),
            (5, 50), (115, 50),
        ]
        for nx2, ny2 in nuclear_spots:
            has_plant = any(
                ib(nx2+dx, ny2+dy) and bool(pm[ny2+dy, nx2+dx])
                for dy in range(-5, 6) for dx in range(-5, 6) if ib(nx2+dx, ny2+dy)
            )
            if not has_plant:
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(60, 8), (8, 50), (112, 50), (60, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(10, 92), (110, 92), (10, 8), (110, 8)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    if pop > 4000:
        park_ys, park_xs = np.where(em & nbr_road)
        if len(park_xs) > 0:
            pk = (step * 17) % len(park_xs)
            for off in range(min(len(park_xs), 30)):
                k = (pk + off * 11) % len(park_xs)
                ppx, ppy = int(park_xs[k]), int(park_ys[k])
                return (Tool.PARK, ppx, ppy)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- ABSOLUTE FALLBACK ----
    if not np.any(pm):
        for y in range(10, 90, 5):
            for x in range(10, 110, 5):
                if bool(em[y, x]):
                    return (Tool.COALPOWER, x, y)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + initial wire spine + seed roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine going up and down from plant
    for y in range(43, 58):
        if y != 50:  # don't overwrite plant
            actions.append((Tool.WIRE, 60, y))
    # Flanking roads
    for y in range(43, 58):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    # Horizontal wire to connect future plants
    for x in range(30, 60):
        actions.append((Tool.WIRE, x, 50))
    for x in range(61, 91):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Zone counts ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Dynamic plant hub list based on population ---
    # Core plants placed early, more added as city grows
    base_plants = [(60, 50)]
    extra_plants = []
    if pop > 50 or step > 100:
        extra_plants += [(30, 50), (90, 50)]
    if pop > 200 or step > 300:
        extra_plants += [(60, 25), (60, 75)]
    if pop > 500 or step > 600:
        extra_plants += [(30, 25), (90, 25), (30, 75), (90, 75)]
    if pop > 1000 or step > 900:
        extra_plants += [(15, 50), (105, 50)]
    if pop > 2000 or step > 1200:
        extra_plants += [(15, 25), (105, 25), (15, 75), (105, 75)]
    if pop > 3000 or step > 1500:
        extra_plants += [(45, 12), (75, 12), (45, 87), (75, 87)]

    all_plants = base_plants + extra_plants

    # --- Ensure plants exist ---
    for px, py in all_plants:
        found = any(
            ib(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dy in range(-4, 5) for dx in range(-4, 5)
            if ib(px + dx, py + dy)
        )
        if not found and ib(px, py) and (bool(em[py, px]) or bool(wm[py, px])):
            return (Tool.COALPOWER, px, py)

    # --- Wire network: horizontal spines + vertical spines from plants ---
    # Main horizontal wire rows
    h_wire_rows = [50]
    if pop > 100 or step > 200:
        h_wire_rows += [25, 75]
    if pop > 400 or step > 500:
        h_wire_rows += [12, 37, 62, 87]

    for wr in h_wire_rows:
        if not ib(0, wr):
            continue
        for x in range(1, WORLD_W - 1):
            if bool(em[wr, x]) and not bool(pm[wr, x]):
                left_ok = ib(x - 1, wr) and (bool(wm[wr, x - 1]) or bool(pm[wr, x - 1]))
                right_ok = ib(x + 1, wr) and (bool(wm[wr, x + 1]) or bool(pm[wr, x + 1]))
                if left_ok or right_ok:
                    return (Tool.WIRE, x, wr)

    # Vertical wire spines from each plant hub
    for px, py in all_plants:
        extent = min(40, 12 + pop // 80)
        spine_top = max(3, py - extent)
        spine_bot = min(WORLD_H - 4, py + extent)
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if col_wires:
            mn, mx = min(col_wires), max(col_wires)
            if mx < spine_bot:
                ny = mx + 1
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
            if mn > spine_top:
                ny = mn - 1
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)

    # --- Road network: flanking roads along wire spines ---
    # Vertical roads flanking each plant's wire column
    for px, py in all_plants:
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not col_wires:
            continue
        mn_w, mx_w = min(col_wires), max(col_wires)
        for roff in [-1, 1]:
            rc = px + roff
            if not ib(rc, 0):
                continue
            for wr in range(mn_w, min(mx_w + 1, WORLD_H)):
                if ib(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

    # Horizontal roads flanking horizontal wire rows
    h_road_offsets = [-1, 1]
    for hwr in h_wire_rows:
        for roff in h_road_offsets:
            hr = hwr + roff
            if not ib(0, hr):
                continue
            # Build road across full width where wires present above/below
            wire_row = wm[hwr, :] | pm[hwr, :]
            if not wire_row.any():
                continue
            for x in range(2, WORLD_W - 2):
                if ib(x, hr) and bool(em[hr, x]) and not bool(pm[hr, x]):
                    return (Tool.ROAD, x, hr)

    # --- Proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones in powered, road-adjacent empty space ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Prefer closest to nearest plant hub
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px).astype(float) + np.abs(cys_arr - py).astype(float)
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # --- Services scaled to population ---
    if pop > 100:
        fire_spots = [(28, 42), (92, 42), (28, 58), (92, 58),
                      (60, 20), (60, 80), (45, 35), (75, 65)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if pop > 300:
        police_spots = [(25, 40), (95, 40), (25, 60), (95, 60),
                        (50, 20), (70, 80), (40, 50), (80, 50)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if pop > 600:
        for stx, sty in [(45, 30), (75, 30), (45, 70), (75, 70)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)
    if pop > 1200:
        for apx, apy in [(50, 15), (70, 85)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)
    if pop > 2000:
        for spx, spy in [(10, 50), (110, 50)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend roads near powered areas ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire ---
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

