            road_rows = [29, 31, 49, 51, 69, 71]
            road_cols = [19, 21, 39, 41, 59, 61, 79, 81, 99, 101]
        elif pop < 500:
            wire_cols = [10, 20, 35, 50, 60, 70, 85, 100, 110]
            wire_rows = [20, 35, 50, 65, 80]
            plant_targets = [(10, 50), (35, 50), (60, 50), (85, 50), (110, 50),
                             (20, 20), (60, 20), (100, 20), (20, 80), (60, 80), (100, 80)]
            road_rows = [19, 21, 34, 36, 49, 51, 64, 66, 79, 81]
            road_cols = [9, 11, 19, 21, 34, 36, 49, 51, 59, 61, 69, 71, 84, 86, 99, 101, 109, 111]
        else:
            wire_cols = [8, 18, 28, 38, 48, 58, 68, 78, 88, 98, 108, 118]
            wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
            plant_targets = [(8, 50), (38, 50), (68, 50), (98, 50), (18, 20), (58, 20),
                             (98, 20), (18, 80), (58, 80), (98, 80), (8, 10), (118, 10),
                             (8, 90), (118, 90)]
            road_rows = [9, 11, 19, 21, 29, 31, 39, 41, 49, 51, 59, 61, 69, 71, 79, 81, 89, 91]
            road_cols = []
            for wc in wire_cols:
                road_cols.extend([wc - 1, wc + 1])
        return wire_cols, wire_rows, plant_targets, road_rows, road_cols

    wire_cols, wire_rows, plant_targets, road_rows_list, road_cols_list = get_active_infrastructure()

    # --- PHASE 1: Ensure power plants at target locations ---
    for (px, py) in plant_targets:
        if not ib(px, py):
            continue
        # Check if plant already exists nearby
        has_plant = False
        for dy2 in range(-4, 5):
