                if ib(nx2, ny2) and bool(pm[ny2, nx2]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Place plant at nearest empty spot
            for r in range(0, 8):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx2, ny2 = px + dx2, py + dy2
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            return (Tool.COALPOWER, nx2, ny2)
                if placed:
                    break

