                continue
            # Fill horizontal wire segment between cols
        # Connect wire across the active columns at this row
        if len(wire_cols) >= 2:
            c_min = min(wire_cols)
            c_max = max(wire_cols)
            # Find gaps
            for cx in range(c_min, c_max + 1):
                if ib(cx, wr) and bool(em[wr, cx]) and not bool(pm[wr, cx]):
                    # Check if there's wire/plant on either side
                    has_left = any(bool(wm[wr, max(0, cx - k)]) or bool(pm[wr, max(0, cx - k)]) for k in range(1, 4))
                    has_right = any(bool(wm[wr, min(WORLD_W - 1, cx + k)]) or bool(pm[wr, min(WORLD_W - 1, cx + k)]) for k in range(1, 4))
                    if has_left or has_right:
                        return (Tool.WIRE, cx, wr)

    # --- PHASE 3: Vertical wire spines along active columns ---
    spine_extent = min(45, 8 + pop // 10)
    for wc in wire_cols:
        target_top = max(3, 50 - spine_extent)
        target_bot = min(WORLD_H - 4, 50 + spine_extent)
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]
        if not wire_in_col:
            # Seed from center
            for dy2 in range(-3, 4):
                ny2 = 50 + dy2
                if ib(wc, ny2) and bool(em[ny2, wc]) and not bool(pm[ny2, wc]):
                    return (Tool.WIRE, wc, ny2)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # --- PHASE 4: Road grid - horizontal roads flanking wire rows ---
    road_half = min(45, 8 + pop // 15)
    for wr in wire_rows:
        for offset_r in [-1, 1]:
            ry = wr + offset_r
            if not ib(0, ry):
                continue
            c_min = max(3, min(wire_cols) - 2)
            c_max = min(WORLD_W - 4, max(wire_cols) + 2)
            road_in_row = [c for c in range(WORLD_W) if ib(c, ry) and bool(rm[ry, c])]
            # Extend or fill road across the row
            for cx in range(c_min, c_max + 1):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    has_nbr = (bool(rm[ry, max(0, cx - 1)]) or bool(rm[ry, min(WORLD_W - 1, cx + 1)]) or
                               bool(rm[max(0, ry - 1), cx]) or bool(rm[min(WORLD_H - 1, ry + 1), cx]))
                    if has_nbr:
                        return (Tool.ROAD, cx, ry)
                    # Bootstrap if no road yet
                    if not road_in_row and cx == c_min:
                        # Find plant/wire near this row to start from
                        for wc in wire_cols:
                            if ib(wc, ry) and (bool(wm[ry, wc]) or bool(pm[ry, wc])):
                                if bool(em[ry, wc]):
                                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: Vertical roads flanking wire columns ---
    for idx, wc in enumerate(wire_cols):
        for offset_c in [-1, 1]:
            cx2 = wc + offset_c
            if not ib(cx2, 50):
                continue
            wire_in_col = sorted([r for r in range(WORLD_H) if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))])
            if not wire_in_col:
                continue
            target_top2 = max(3, min(wire_in_col))
            target_bot2 = min(WORLD_H - 4, max(wire_in_col))
            cycle2 = (step + idx * 5) % 5
            for wr2 in wire_in_col[cycle2::5]:
                if wr2 < target_top2 or wr2 > target_bot2:
                    continue
                if ib(cx2, wr2) and bool(em[wr2, cx2]) and not bool(pm[wr2, cx2]):
                    return (Tool.ROAD, cx2, wr2)

    # --- PHASE 6: Zone placement in areas with road AND wire ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates by proximity to wire columns
        best_dist = np.full(len(cxs), 999999.0)
        for wc in wire_cols:
            for wr in wire_rows:
                d = np.abs(cxs - wc).astype(float) * 1.0 + np.abs(cys - wr).astype(float) * 1.0
                best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 11) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # --- PHASE 7: Extend roads from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx2 + dx3, ry2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_wire[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # --- CIVIC SERVICES (closed-loop: only place when pop warrants) ---
    if pop > 60:
        fire_spots = [
            (30, 30), (60, 30), (90, 30), (30, 50), (60, 50), (90, 50),
            (30, 70), (60, 70), (90, 70), (10, 20), (110, 20), (10, 80), (110, 80),
            (50, 15), (70, 15), (50, 85), (70, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (15, 25), (45, 25), (75, 25), (105, 25),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 75), (45, 75), (75, 75), (105, 75),
            (30, 10), (60, 10), (90, 10),
            (30, 90), (60, 90), (90, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (25, 8), (60, 8), (95, 8),
            (25, 92), (60, 92), (95, 92),
            (5, 40), (5, 60), (115, 40), (115, 60),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (15, 5), (60, 5), (105, 5),
            (15, 95), (60, 95), (105, 95),
            (5, 15), (5, 50), (5, 85),
            (115, 15), (115, 50), (115, 85),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 95), (30, 5), (90, 5)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 95), (115, 95), (60, 97), (5, 5), (115, 5)]:
            sx3, sy3 = sp
            if ib(sx3, sy3) and bool(em[sy3, sx3]):
                return (Tool.SEAPORT, sx3, sy3)

    # --- Parks to boost land value near dense zones ---
    if pop > 150:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 5 + i * 19) % len(zone_xs2)
                zx3, zy3 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (0, 3), (-3, 0), (0, -3)]:
                    nx4, ny4 = zx3 + dx4, zy3 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and bool(nbr_road[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # --- Fallback: extend wire from existing wire ---
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k3 = (step * 17) % max(len(wire_xs3), 1)
        for offset in range(min(len(wire_xs3), 50)):
            k = (step_k3 + offset * 7) % len(wire_xs3)
            wx3, wy3 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx3 + dx5, wy3 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # --- Absolute fallback ---
    if not np.any(pm):
        for y5 in range(10, 90, 8):
            for x5 in range(10, 110, 8):
                if bool(em[y5, x5]):
                    return (Tool.COALPOWER, x5, y5)

    return None

def init(obs, state):
    """Bootstrap: central power plant with wire cross and road grid seed."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine horizontal through center
    for dx in range(-8, 9):
        actions.append((Tool.WIRE, 60 + dx, 50))
    # Wire spine vertical through center
    for dy in range(-8, 9):
        actions.append((Tool.WIRE, 60, 50 + dy))
    # Seed roads flanking the horizontal wire
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, 60 + dx, 49))
        actions.append((Tool.ROAD, 60 + dx, 51))
    # Seed roads flanking the vertical wire
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Balanced zone mix: 40% res, 35% com, 25% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Grid of neighborhoods: 4 columns x 3 rows of clusters
    # Each cluster has its own power plant + wire cross + road grid
    # Cluster centers spread across the map
    cluster_cols = [20, 45, 75, 100]
    cluster_rows = [18, 50, 82]

    # Scale active clusters with population
    def active_clusters():
        if pop < 100:   return [(60, 50)]
        if pop < 500:   return [(45, 50), (75, 50)]
        if pop < 1500:  return [(20, 50), (60, 50), (100, 50)]
        if pop < 3000:  return [(20, 18), (60, 18), (100, 18),
                                 (20, 50), (60, 50), (100, 50)]
        # Full 4x3 grid
        return [(cx, cy) for cy in cluster_rows for cx in cluster_cols]

    clusters = active_clusters()

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        # Check if plant exists near cluster center
        px0, px1 = max(0, cx - 10), min(WORLD_W, cx + 11)
        py0, py1 = max(0, cy - 10), min(WORLD_H, cy + 11)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            # Try to place plant at center
            for r in range(15):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE CROSSES FROM EACH PLANT ----
    # For each cluster, extend wire in + pattern from plant location
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(18, 5 + pop // 30)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            # Check if this plant belongs to an active cluster
            in_cluster = any(abs(px2 - cx) <= 12 and abs(py2 - cy) <= 12
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Extend wire horizontally
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3):
                        break
                    if bool(pm[ny3, nx3]):
                        break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            # Extend wire vertically
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3):
                        break
                    if bool(pm[ny3, nx3]):
                        break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH WIRE ----
    # Wire horizontal connections between adjacent cluster columns at cluster rows
    for cy in [r for r in cluster_rows if any(abs(cy - c[1]) <= 5 for c in clusters)]:
        sorted_cx = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 12])
        for i in range(len(sorted_cx) - 1):
            c1, c2 = sorted_cx[i], sorted_cx[i + 1]
            # Check if connected
            row_wire = [bool(wm[cy, x] or pm[cy, x]) for x in range(c1, c2 + 1) if ib(x, cy)]
            if not all(row_wire):
                for x in range(c1, c2 + 1):
                    if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]):
                        return (Tool.WIRE, x, cy)

    # Wire vertical connections between cluster rows at cluster columns
    active_cols_set = set(cx for cx, cy in clusters)
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    for cx in active_cols_set:
        for i in range(len(active_rows_set) - 1):
            r1, r2 = active_rows_set[i], active_rows_set[i + 1]
            col_wire = [bool(wm[y, cx] or pm[y, cx]) for y in range(r1, r2 + 1) if ib(cx, y)]
            if not all(col_wire):
                for y in range(r1, r2 + 1):
                    if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]):
                        return (Tool.WIRE, cx, y)

    # ---- BUILD ROAD GRID AROUND EACH CLUSTER ----
    # Road grid: horizontal roads at cy-2, cy+2; vertical roads at cx-2, cx+2
    road_reach = min(16, 4 + pop // 50)
    for cx, cy in clusters:
        # Horizontal roads above and below wire spine
        for road_y in [cy - 2, cy + 2]:
            if not ib(cx, road_y):
                continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)
        # Vertical roads left and right of wire spine
        for road_x in [cx - 2, cx + 2]:
            if not ib(road_x, cy):
                continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    # Connect clusters horizontally at cy rows
    if pop > 200:
        for cy in active_rows_set:
            sorted_cx2 = sorted(active_cols_set)
            for i in range(len(sorted_cx2) - 1):
                c1, c2 = sorted_cx2[i], sorted_cx2[i + 1]
                road_y_opts = [cy - 3, cy + 3]
                for road_y in road_y_opts:
                    if not (0 <= road_y < WORLD_H):
                        continue
                    row_roads2 = [x for x in range(c1, c2 + 1)
                                  if ib(x, road_y) and bool(rm[road_y, x])]
                    if not row_roads2:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: prefer near active clusters
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) * 1.0 +
                 np.abs(cys2 - cy).astype(float) * 1.0)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- CIVIC SERVICES (closed-loop, scaled with pop) ----
    if pop > 60:
        fire_spots = []
        for fy in range(10, 95, 20):
            for fx in range(10, 115, 22):
                fire_spots.append((fx, fy))
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = []
        for py in range(12, 90, 18):
            for px in range(12, 112, 25):
                police_spots.append((px, py))
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(30, 8), (70, 8), (110, 8),
                         (30, 90), (70, 90), (110, 90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        # Upgrade to nuclear power for more capacity
        nuke_spots = [(5, 18), (5, 50), (5, 82),
                      (115, 18), (115, 50), (115, 82),
                      (40, 5), (80, 5), (40, 94), (80, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 40)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 60)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire spines and flanking roads."""
    actions = []
    # Three power plants spread across the map
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
        # Short wire spine seeded from each plant
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px, 50 + dy))
        # Flanking roads
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Target power plant locations based on pop ---
    def desired_plants():
        pts = [(20, 50), (60, 50), (100, 50)]
        if pop > 200:
            pts += [(20, 20), (60, 20), (100, 20)]
        if pop > 500:
            pts += [(20, 80), (60, 80), (100, 80)]
        if pop > 1000:
            pts += [(40, 35), (80, 35), (40, 65), (80, 65)]
        if pop > 2000:
            pts += [(10, 10), (110, 10), (10, 90), (110, 90)]
        if pop > 3500:
            pts += [(40, 10), (80, 10), (40, 90), (80, 90)]
        return pts

    # --- 1. Ensure power plants near desired locations ---
    for (px, py) in desired_plants():
        # Check if there's a plant within 8 tiles
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find empty spot near target
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- 2. Extend wire from existing plants/wires ---
    # For each power plant, grow wire outward in a spine pattern
    # Wire grows toward target rows: multiple y-levels
    wire_target_rows = [20, 35, 50, 65, 80]
    wire_cols = []
    # Find plant x-positions
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # Unique columns with plants
        for px in np.unique(plant_xs):
            # Wire column slightly offset from plant
            wire_cols.append(int(px))

    if not wire_cols:
        wire_cols = [20, 60, 100]

    # Grow wire vertically in each wire column toward coverage
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        existing_wire = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        existing_plant_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(pm[r, wc])]
        all_powered = existing_wire + existing_plant_rows

        if not all_powered:
            continue

        min_r = min(all_powered)
        max_r = max(all_powered)
        target_top = 5
        target_bot = WORLD_H - 5

        # Extend upward
        if min_r > target_top:
            nr = min_r - 1
            if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                return (Tool.WIRE, wc, nr)

        # Extend downward
        if max_r < target_bot:
            nr = max_r + 1
            if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                return (Tool.WIRE, wc, nr)

    # --- 3. Horizontal wire connections between columns at key rows ---
    if len(wire_cols) >= 2:
        wire_cols_sorted = sorted(wire_cols)
        for wy in wire_target_rows:
            for i in range(len(wire_cols_sorted) - 1):
                c1 = wire_cols_sorted[i]
                c2 = wire_cols_sorted[i + 1]
                # Check if connected
                connected = True
                for cx in range(c1, c2 + 1):
                    if not (ib(cx, wy) and (bool(wm[wy, cx]) or bool(pm[wy, cx]) or bool(rm[wy, cx]))):
                        connected = False
                        break
                if not connected:
                    # Find gap and fill
                    for cx in range(c1, c2 + 1):
                        if ib(cx, wy) and bool(em[wy, cx]) and not bool(pm[wy, cx]):
                            return (Tool.WIRE, cx, wy)

    # --- 4. Build roads flanking wire columns ---
    # For each wire column, roads run on both sides
    for wc in wire_cols:
        for road_x in [wc - 1, wc + 1]:
            if not ib(road_x, 0):
                continue
            # Find wire rows in this column
            wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]
            if not wire_rows:
                continue
            # Build road alongside wire where empty
            cycle = (step + wc) % max(len(wire_rows), 1)
            for offset in range(min(len(wire_rows), 5)):
                wr = wire_rows[(cycle + offset) % len(wire_rows)]
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # --- 5. Horizontal roads at key y-levels ---
    h_road_ys = [20, 35, 50, 65, 80]
    for ry in h_road_ys:
        # Build road across map near wire
        nbr_wire_row = np.zeros(WORLD_W, dtype=bool)
        for dy2 in range(-4, 5):
            yr = ry + dy2
            if 0 <= yr < WORLD_H:
                nbr_wire_row |= wm[yr, :]
                nbr_wire_row |= pm[yr, :]
        for cx in range(3, WORLD_W - 3):
            if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]) and bool(nbr_wire_row[cx]):
                return (Tool.ROAD, cx, ry)

    # --- 6. Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- 7. Zone placement: fill areas near road+wire ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest wire column
        best_dist = np.full(len(cxs), 999999.0)
        for wc in wire_cols:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - 50).astype(float) * 0.3
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # --- 8. Extend roads from existing road ends ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- 9. Civic services scaled with pop ---
    if pop > 100:
        fire_spots = [
            (30, 20), (70, 20), (110, 20),
            (10, 35), (50, 35), (90, 35),
            (30, 50), (70, 50), (110, 50),
            (10, 65), (50, 65), (90, 65),
            (30, 80), (70, 80), (110, 80),
            (20, 10), (60, 10), (100, 10),
            (20, 90), (60, 90), (100, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (25, 25), (65, 25), (105, 25),
            (15, 50), (55, 50), (95, 50),
            (25, 75), (65, 75), (105, 75),
            (40, 10), (80, 10), (40, 90), (80, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (40, 15), (80, 15), (40, 85), (80, 85),
            (10, 30), (110, 30), (10, 70), (110, 70),
            (55, 45), (55, 60),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (35, 8), (75, 8), (35, 92), (75, 92),
            (8, 25), (112, 25), (8, 75), (112, 75),
        ]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3500:
        for asp in [(60, 6), (8, 50), (112, 50), (30, 6), (90, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)
        for sp in [(10, 94), (60, 94), (110, 94)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- 10. Fallback: extend wire laterally near empty land ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + horizontal wire spine + vertical spines + seed roads"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at row 50
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical spines from each plant
    for y in range(30, 71):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Seed horizontal roads above and below wire spine
    for x in range(20, 100):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    # Vertical roads flanking spines
    for y in range(30, 71):
