def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Four main clusters across the map
    clusters = [
        {'cx': 20,  'cy': 50},
        {'cx': 50,  'cy': 50},
        {'cx': 80,  'cy': 50},
        {'cx': 110, 'cy': 50},
    ]

    # ---- Ensure all primary plants exist ----
    for cl in clusters:
        px, py = cl['cx'], cl['cy']
        plant_there = any(
            in_bounds(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dy in range(-3, 4) for dx in range(-3, 4)
            if in_bounds(px + dx, py + dy)
        )
        if not plant_there:
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- Horizontal wire bridge between clusters (row 50) ----
    for x in range(22, 49):
        if in_bounds(x, 50) and bool(em[50, x]):
            return (Tool.WIRE, x, 50)
    for x in range(52, 79):
        if in_bounds(x, 50) and bool(em[50, x]):
            return (Tool.WIRE, x, 50)
    for x in range(82, 109):
        if in_bounds(x, 50) and bool(em[50, x]):
            return (Tool.WIRE, x, 50)

    # ---- Extend vertical wire spines adaptively ----
    pop_factor = min(35, obs.city_pop // 15)
    spine_extent = 18 + pop_factor

    for cl in clusters:
        wc = cl['cx']
        cy = cl['cy']
        spine_top = max(3, cy - spine_extent)
        spine_bot = min(WORLD_H - 4, cy + spine_extent)

        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]
        if not wire_rows:
            for dy in range(-2, 3):
                ny = cy + dy
                if in_bounds(wc, ny) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and not bool(pm[nr, wc]) and bool(em[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and not bool(pm[nr, wc]) and bool(em[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- Road columns flanking each cluster's wire spine ----
    for cl in clusters:
        wc = cl['cx']
        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]
        if not wire_rows:
            continue
        for road_off in [-1, 1]:
            rc = wc + road_off
            step_sub = obs.step % max(len(wire_rows), 1)
            for i in range(min(len(wire_rows), 4)):
                idx = (step_sub + i) % len(wire_rows)
                wr = wire_rows[idx]
                if in_bounds(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

    # ---- Additional nuclear plants at population thresholds ----
    if obs.city_pop > 600:
        nuke_positions = [(35, 25), (65, 25), (95, 25), (35, 75), (65, 75), (95, 75)]
        for npx, npy in nuke_positions:
            plant_there = any(
                in_bounds(npx + dx, npy + dy) and bool(pm[npy + dy, npx + dx])
                for dy in range(-4, 5) for dx in range(-4, 5)
                if in_bounds(npx + dx, npy + dy)
            )
            if not plant_there and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)
            elif not plant_there:
                # Connect horizontally to nearest wire spine
                nearest_wc = min([cl['cx'] for cl in clusters], key=lambda wc: abs(wc - npx))
                for wx in range(min(npx, nearest_wc) + 1, max(npx, nearest_wc)):
                    if in_bounds(wx, npy) and bool(em[npy, wx]):
                        return (Tool.WIRE, wx, npy)

    # ---- Extra coal plants for mid-game ----
    if 200 < obs.city_pop <= 600:
        for extra_px, extra_py in [(35, 50), (65, 50), (95, 50)]:
            plant_there = any(
                in_bounds(extra_px + dx, extra_py + dy) and bool(pm[extra_py + dy, extra_px + dx])
                for dy in range(-4, 5) for dx in range(-4, 5)
                if in_bounds(extra_px + dx, extra_py + dy)
            )
            if not plant_there and bool(em[extra_py, extra_px]):
                return (Tool.COALPOWER, extra_px, extra_py)

    # ---- Proximity masks for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance to nearest cluster center
        min_dist = np.full(len(cxs_arr), 999999.0)
        for cl in clusters:
            d = np.abs(cxs_arr - cl['cx']) + np.abs(cys_arr - cl['cy'])
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- Horizontal roads crossing wire spines every N rows ----
    for cl in clusters:
        wc = cl['cx']
        cy = cl['cy']
        pop_f = min(30, obs.city_pop // 15)
        spine_top = max(3, cy - min(18 + pop_f, 40))
        spine_bot = min(WORLD_H - 4, cy + min(18 + pop_f, 40))
        for wr in range(spine_top, spine_bot + 1, 5):
            x_lo = max(3, wc - 15)
            x_hi = min(WORLD_W - 4, wc + 15)
            for rx in range(x_lo, x_hi + 1):
                if in_bounds(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- Services at population thresholds ----
    if obs.city_pop > 100:
        for fsx, fsy in [(15, 42), (45, 42), (75, 42), (105, 42),
                          (15, 58), (45, 58), (75, 58), (105, 58)]:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 300:
        for psx, psy in [(25, 40), (55, 40), (85, 40), (115, 40),
                          (25, 60), (55, 60), (85, 60), (115, 60)]:
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 700:
        for stx, sty in [(30, 35), (60, 35), (90, 35), (30, 65), (60, 65), (90, 65)]:
            if in_bounds(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)
    if obs.city_pop > 1500:
        for aptx, apty in [(55, 15), (55, 85)]:
            if in_bounds(aptx, apty) and bool(em[apty, aptx]):
                return (Tool.AIRPORT, aptx, apty)
        for sptx, spty in [(10, 50), (110, 50)]:
            if in_bounds(sptx, spty) and bool(em[spty, sptx]):
                return (Tool.SEAPORT, sptx, spty)

    # ---- Add secondary horizontal wire spines at rows 30 and 70 ----
    if obs.city_pop > 50:
        for spine_y in [30, 70]:
            # Connect clusters horizontally at this row
            for x in range(3, WORLD_W - 3):
                if in_bounds(x, spine_y) and bool(em[spine_y, x]) and not bool(pm[spine_y, x]):
                    # Only place if near a cluster column
                    near_cluster = any(abs(x - cl['cx']) <= 20 for cl in clusters)
                    if near_cluster:
                        return (Tool.WIRE, x, spine_y)

    # ---- Extend roads near wire as fallback ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Expand wire as last fallback ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

