def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 45% res, 30% com, 25% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # 6 clusters across 2 rows, spread widely across the map
    # Scale active clusters with population
    cluster_cols = [20, 60, 100]
    cluster_rows = [25, 75]

    def active_clusters():
        if pop < 50:
            return [(30, 50), (90, 50)]
        if pop < 300:
            return [(20, 25), (60, 25), (20, 75), (60, 75)]
        if pop < 800:
            return [(20, 25), (60, 25), (100, 25),
                    (20, 75), (60, 75), (100, 75)]
        # Full grid with center column too
        return [(cx, cy) for cy in cluster_rows for cx in cluster_cols]

    clusters = active_clusters()
    cluster_set = set(clusters)

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(18):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- EXTEND WIRE CROSSES FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(22, 8 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 15 and abs(py2 - cy) <= 15
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS HORIZONTALLY WITH WIRE ----
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        row_clusters_cx = sorted(cx for cx, c_cy in clusters if c_cy == cy)
        for i in range(len(row_clusters_cx) - 1):
            c1, c2 = row_clusters_cx[i], row_clusters_cx[i + 1]
            for x in range(c1, c2 + 1):
                if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]) and not bool(wm[cy, x]):
                    return (Tool.WIRE, x, cy)

    # ---- CONNECT CLUSTERS VERTICALLY WITH WIRE ----
    for cx in active_cols_set:
        col_clusters_cy = sorted(cy for c_cx, cy in clusters if c_cx == cx)
        for i in range(len(col_clusters_cy) - 1):
            r1, r2 = col_clusters_cy[i], col_clusters_cy[i + 1]
            for y in range(r1, r2 + 1):
                if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]) and not bool(wm[y, cx]):
                    return (Tool.WIRE, cx, y)

    # ---- BUILD ROAD GRID AROUND EACH CLUSTER ----
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        # Horizontal roads at cy-3 and cy+3
        for road_y in [cy - 3, cy + 3]:
            if not ib(cx, road_y): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)
        # Vertical roads at cx-3 and cx+3
        for road_x in [cx - 3, cx + 3]:
            if not ib(road_x, cy): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)
        # Extra horizontal roads at cy-6 and cy+6 for denser grid
        if pop > 200:
            for road_y in [cy - 6, cy + 6]:
                if not ib(cx, road_y): continue
                for dx in range(-road_reach, road_reach + 1):
                    nx4, ny4 = cx + dx, road_y
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)
            for road_x in [cx - 6, cx + 6]:
                if not ib(road_x, cy): continue
                for dy in range(-road_reach, road_reach + 1):
                    nx4, ny4 = road_x, cy + dy
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS (horizontal) ----
    if pop > 150:
        for cy in active_rows_set:
            row_cx = sorted(cx for cx, c_cy in clusters if c_cy == cy)
            for i in range(len(row_cx) - 1):
                c1, c2 = row_cx[i], row_cx[i + 1]
                for road_y in [cy - 4, cy + 4]:
                    if not (0 <= road_y < WORLD_H): continue
                    has_road = any(bool(rm[road_y, x]) for x in range(c1, c2 + 1) if ib(x, road_y))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    # ---- INTER-CLUSTER ROADS (vertical) ----
    if pop > 300:
        for cx in active_cols_set:
            col_cy = sorted(cy for c_cx, cy in clusters if c_cx == cx)
            for i in range(len(col_cy) - 1):
                r1, r2 = col_cy[i], col_cy[i + 1]
                for road_x in [cx - 4, cx + 4]:
                    if not (0 <= road_x < WORLD_W): continue
                    has_road = any(bool(rm[y, road_x]) for y in range(r1, r2 + 1) if ib(road_x, y))
                    if not has_road:
                        for y in range(r1, r2 + 1):
                            if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                                return (Tool.ROAD, road_x, y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) +
                 np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = []
        for fy in range(8, 95, 18):
            for fx in range(8, 115, 20):
                fire_spots.append((fx, fy))
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = []
        for py_s in range(10, 92, 16):
            for px_s in range(10, 114, 22):
                police_spots.append((px_s, py_s))
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(15, 5), (60, 5), (105, 5),
                         (15, 93), (60, 93), (105, 93)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear power
        nuke_spots = [(5, 25), (5, 75), (115, 25), (115, 75),
                      (60, 5), (60, 93), (30, 5), (90, 5)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire crosses and road seeds."""
    actions = []
    # Two central power plants
    for px, py in [(40, 50), (80, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross
        for dx in range(-6, 7):
            if dx != 0:
                actions.append((Tool.WIRE, px + dx, py))
        for dy in range(-6, 7):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Road flanks
        for dx in range(-6, 7):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 7)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Cluster grid: 4 columns x 4 rows spread across the full map
    all_cluster_cols = [15, 40, 80, 105]
    all_cluster_rows = [15, 38, 62, 85]

    def active_clusters():
        if pop < 200:
            return [(40, 50), (80, 50)]
        if pop < 600:
            return [(40, 38), (80, 38), (40, 62), (80, 62)]
        if pop < 1500:
            return [(15, 38), (40, 38), (80, 38), (105, 38),
                    (15, 62), (40, 62), (80, 62), (105, 62)]
        if pop < 3000:
            return [(cx, cy) for cy in [15, 38, 62, 85]
                    for cx in [15, 40, 80, 105]
                    if not (cy in [15, 85] and cx in [15, 105])]
        # Full 4x4 grid
        return [(cx, cy) for cy in all_cluster_rows for cx in all_cluster_cols]

    clusters = active_clusters()

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(1, 18):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(22, 6 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Horizontal wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            # Vertical wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH HORIZONTAL WIRE ----
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        row_clusters = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 10])
        for i in range(len(row_clusters) - 1):
            c1, c2 = row_clusters[i], row_clusters[i + 1]
            for x in range(c1, c2 + 1):
                if ib(x, cy) and not bool(pm[cy, x]) and not bool(wm[cy, x]) and bool(em[cy, x]):
                    # Only fill gap if wires exist on at least one side
                    left_wire = any(bool(wm[cy, xx] or pm[cy, xx]) for xx in range(max(0, x-5), x))
                    right_wire = any(bool(wm[cy, xx] or pm[cy, xx]) for xx in range(x+1, min(WORLD_W, x+6)))
                    if left_wire or right_wire:
                        return (Tool.WIRE, x, cy)

    # ---- CONNECT CLUSTERS WITH VERTICAL WIRE ----
    for cx in active_cols_set:
        col_clusters = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 10])
        for i in range(len(col_clusters) - 1):
            r1, r2 = col_clusters[i], col_clusters[i + 1]
            for y in range(r1, r2 + 1):
                if ib(cx, y) and not bool(pm[y, cx]) and not bool(wm[y, cx]) and bool(em[y, cx]):
                    above = any(bool(wm[yy, cx] or pm[yy, cx]) for yy in range(max(0, y-5), y))
                    below = any(bool(wm[yy, cx] or pm[yy, cx]) for yy in range(y+1, min(WORLD_H, y+6)))
                    if above or below:
                        return (Tool.WIRE, cx, y)

    # ---- CROSS-WIRE AT STRATEGIC ROWS ----
    cross_rows = list(active_rows_set)
    if pop > 400:
        cross_rows += [r + 12 for r in active_rows_set if r + 12 < WORLD_H]
        cross_rows += [r - 12 for r in active_rows_set if r - 12 >= 0]
    for cr in set(cross_rows):
        for x in range(1, WORLD_W - 1):
            if bool(em[cr, x]) and not bool(pm[cr, x]) and not bool(wm[cr, x]):
                left_has = bool(wm[cr, x-1] or pm[cr, x-1])
                right_has = bool(wm[cr, x+1] or pm[cr, x+1])
                if left_has or right_has:
                    return (Tool.WIRE, x, cr)

    # ---- BUILD ROAD GRID AROUND EACH CLUSTER ----
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        for road_y in [cy - 2, cy + 2]:
            if not (0 <= road_y < WORLD_H):
                continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)
        for road_x in [cx - 2, cx + 2]:
            if not (0 <= road_x < WORLD_W):
                continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    if pop > 150:
        for cy in active_rows_set:
            sorted_cx2 = active_cols_set
            for i in range(len(sorted_cx2) - 1):
                c1, c2 = sorted_cx2[i], sorted_cx2[i + 1]
                for road_y in [cy - 3, cy + 3]:
                    if not (0 <= road_y < WORLD_H):
                        continue
                    has_gap = any(
                        ib(x, road_y) and not bool(rm[road_y, x]) and bool(em[road_y, x])
                        for x in range(c1, c2 + 1)
                    )
                    if has_gap:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]) and not bool(rm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    if pop > 300:
        for cx in active_cols_set:
            sorted_cy2 = active_rows_set
            for i in range(len(sorted_cy2) - 1):
                r1, r2 = sorted_cy2[i], sorted_cy2[i + 1]
                for road_x in [cx - 3, cx + 3]:
                    if not (0 <= road_x < WORLD_W):
                        continue
                    for y in range(r1, r2 + 1):
                        if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]) and not bool(rm[y, road_x]):
                            return (Tool.ROAD, road_x, y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float)
            best_dist = np.minimum(best_dist, d)
        # Blend with zone clustering
        if total_zones > 3:
            zone_ys3, zone_xs3 = np.where(zone_tiles)
            if len(zone_xs3) > 0:
                zone_dist = np.full(len(cxs2), 999999.0)
                step_s = max(1, len(zone_xs3) // 60)
                for i in range(0, len(zone_xs3), step_s):
                    d2 = np.abs(cxs2 - zone_xs3[i]).astype(float) + np.abs(cys2 - zone_ys3[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d2)
                combined = best_dist * 0.5 + zone_dist * 0.5
            else:
                combined = best_dist
        else:
            combined = best_dist

        order = np.argsort(combined)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fy in range(10, 95, 18) for fx in range(10, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px, py) for py in range(12, 90, 20) for px in range(12, 112, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        for stx, sty in [(20, 8), (60, 8), (100, 8),
                         (20, 92), (60, 92), (100, 92),
                         (5, 35), (5, 65), (115, 35), (115, 65)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuke_spots = [(5, 15), (5, 50), (5, 85),
                      (115, 15), (115, 50), (115, 85),
                      (30, 5), (60, 5), (90, 5),
                      (30, 95), (60, 95), (90, 95)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for ax, ay in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sx2, sy2 in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map2 = resm | comm | indm
        zone_ys4, zone_xs4 = np.where(zone_map2)
        if len(zone_xs4) > 0:
            for i in range(min(len(zone_xs4), 50)):
                k = (step * 5 + i * 13) % len(zone_xs4)
                zx3, zy3 = int(zone_xs4[k]), int(zone_ys4[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

# Ambitious closed-loop city builder
# Strategy: Grid of neighborhoods covering the full map
# Each neighborhood has its own coal plant, wire spine, road grid, and dense zoning
# Civic services placed reactively based on population thresholds

def init(obs, state):
    """Bootstrap: primary coal plant + wire + roads at center"""
    actions = []
    # Primary plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine vertical
    for dy in range(-3, 4):
        actions.append((Tool.WIRE, 62, 50 + dy))
    # Roads flanking
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 61, 50 + dy))
        actions.append((Tool.ROAD, 63, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    total_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID ----
    # 6 columns x 5 rows = 30 potential neighborhoods
    # Plant offset from anchor, wire col, left road, right road
    # Anchors spread across full 120x100 map with spacing ~20
    # Each neighborhood: plant at anchor, wire col at anchor+2, roads at anchor+1 and anchor+3

    col_xs = [10, 30, 50, 70, 90, 110]
    row_ys = [15, 35, 50, 65, 85]

    # Build anchor list: (plant_x, plant_y, wire_col_x, road_left_x, road_right_x)
    all_anchors = []
    for cx in col_xs:
        for cy in row_ys:
            px = max(4, min(WORLD_W - 5, cx - 2))
            wc = max(4, min(WORLD_W - 5, cx))
            rl = max(4, min(WORLD_W - 5, cx - 1))
            rr = max(4, min(WORLD_W - 5, cx + 1))
            all_anchors.append((px, cy, wc, rl, rr))

    # Unlock anchors progressively
    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 2
        if pop < 500:   return 4
        if pop < 1000:  return 7
        if pop < 2000:  return 12
        if pop < 4000:  return 18
        if pop < 7000:  return 24
        return 30

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # Spine extent based on pop
    pop_factor = min(40, pop // 8)
    spine_half = 12 + pop_factor // 2

    # ---- 1. ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        # Check if plant exists within 5 tiles of anchor
        has_plant = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Search nearby
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. WIRE SPINES ----
    for (px, py, wc, rl, rr) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)

        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_rows:
            # Connect plant to wire col
            for dy in range(-4, 5):
                ny = py + dy
                if ib(wc, ny) and not bool(pm[ny, wc]):
                    if bool(em[ny, wc]) or bool(wm[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            elif min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE CONNECTIONS (same row anchors) ----
    row_groups = {}
    for anc in active_anchors:
        py = anc[1]
        row_groups.setdefault(py, []).append(anc)

    for py, grp in row_groups.items():
        if len(grp) < 2:
            continue
        grp_sorted = sorted(grp, key=lambda a: a[2])
        for i in range(len(grp_sorted) - 1):
            wc1 = grp_sorted[i][2]
            wc2 = grp_sorted[i + 1][2]
            # Check if already connected
            for cx in range(wc1, wc2 + 1):
                if ib(cx, py) and not bool(wm[py, cx]) and not bool(pm[py, cx]) and bool(em[py, cx]):
                    return (Tool.WIRE, cx, py)

    # ---- 4. ROAD BUILDING along wire spines ----
    # Also build horizontal roads connecting neighborhoods
    for (px, py, wc, rl, rr) in active_anchors:
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = step % 6
        for wr in wire_rows[cycle::6]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 5. HORIZONTAL ROADS between same-row neighborhoods ----
    for py, grp in row_groups.items():
        if len(grp) < 2:
            continue
        grp_sorted = sorted(grp, key=lambda a: a[0])
        for i in range(len(grp_sorted) - 1):
            rx1 = grp_sorted[i][3]   # road_left of right anchor
            rx2 = grp_sorted[i + 1][4]  # road_right of left anchor
            mid_y = py
            for cx in range(min(rx1, rx2), max(rx1, rx2) + 1):
                if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                    return (Tool.ROAD, cx, mid_y)

    # ---- 6. ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.18:
            return Tool.INDUSTRIAL
        if c_r < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks efficiently
    # Road neighbor: within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire neighbor: within 6 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep border clearance
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active anchor wire columns
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step offset for variety
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- 7. EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- 8. CIVIC SERVICES (reactive to pop) ----
    if pop > 200:
        fire_spots = []
        for cx in col_xs[::2]:
            for cy in row_ys:
                fire_spots.append((cx + 5, cy + 5))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = []
        for cx in col_xs[1::2]:
            for cy in row_ys:
                police_spots.append((cx + 5, cy - 5))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadium_spots = [(55, 8), (55, 92), (10, 50), (110, 50), (35, 8), (85, 8), (35, 92), (85, 92)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        # Seaport and airport for high-pop cities
        if ib(5, 50) and bool(em[50, 5]):
            return (Tool.SEAPORT, 5, 50)
        if ib(115, 50) and bool(em[50, 115]):
            return (Tool.AIRPORT, 115, 50)

    # ---- 9. NUCLEAR POWER for high population ----
    if pop > 2000:
        nuclear_spots = [(20, 8), (100, 8), (20, 92), (100, 92), (60, 8), (60, 92)]
        for (nx, ny) in nuclear_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    # ---- 10. EXTEND WIRE laterally (fallback) ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in corners + center, wired spine, seed roads"""
    actions = []
    # Four corner-ish plants + center
    for (px, py) in [(20, 20), (100, 20), (20, 80), (100, 80), (60, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire at y=20, y=50, y=80
    for y in [20, 50, 80]:
        for x in range(1, WORLD_W - 1):
            actions.append((Tool.WIRE, x, y))
    # Vertical wire at x=20, x=60, x=100
    for x in [20, 60, 100]:
        for y in range(1, WORLD_H - 1):
            actions.append((Tool.WIRE, x, y))
    # Seed roads parallel to wire spines
    for y in [19, 21, 49, 51, 79, 81]:
        for x in range(2, WORLD_W - 2):
            actions.append((Tool.ROAD, x, y))
    for x in [19, 21, 59, 61, 99, 101]:
        for y in range(2, WORLD_H - 2):
            actions.append((Tool.ROAD, x, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Want ~20% industrial, ~25% commercial, rest residential
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dynamic plants: 5 base + more as pop grows
    base_plants = [(20, 20), (100, 20), (20, 80), (100, 80), (60, 50)]
    extra_plants = []
    if pop > 200:
        extra_plants += [(40, 50), (80, 50), (60, 20), (60, 80)]
    if pop > 600:
        extra_plants += [(10, 50), (110, 50), (40, 10), (80, 10), (40, 90), (80, 90)]
    if pop > 1200:
        extra_plants += [(20, 35), (20, 65), (100, 35), (100, 65),
                         (60, 10), (60, 90), (35, 50), (85, 50)]
    if pop > 2000:
        extra_plants += [(5, 10), (115, 10), (5, 90), (115, 90),
                         (50, 5), (70, 5), (50, 95), (70, 95)]
    if pop > 3500:
        extra_plants += [(5, 30), (115, 30), (5, 70), (115, 70),
                         (30, 5), (90, 5), (30, 95), (90, 95)]

    all_plants = base_plants + extra_plants

    # Ensure plants exist
    for px, py in all_plants:
        found = any(
            ib(px+dx, py+dy) and pm[py+dy, px+dx]
            for dy in range(-4, 5) for dx in range(-4, 5)
        )
        if not found and ib(px, py):
            return (Tool.COALPOWER, px, py)

    # Wire grid: horizontal spines every 10 rows
    wire_rows = list(range(10, WORLD_H, 10))
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        for x in range(1, WORLD_W - 1):
            if ib(x, wr) and em[wr, x] and not pm[wr, x] and not wm[wr, x]:
                left_has = ib(x-1, wr) and (wm[wr, x-1] or pm[wr, x-1])
                right_has = ib(x+1, wr) and (wm[wr, x+1] or pm[wr, x+1])
                if left_has or right_has:
                    return (Tool.WIRE, x, wr)

    # Wire grid: vertical spines every 10 cols
    wire_cols = list(range(10, WORLD_W, 10))
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        for y in range(1, WORLD_H - 1):
            if ib(wc, y) and em[y, wc] and not pm[y, wc] and not wm[y, wc]:
                above = ib(wc, y-1) and (wm[y-1, wc] or pm[y-1, wc])
                below = ib(wc, y+1) and (wm[y+1, wc] or pm[y+1, wc])
                if above or below:
                    return (Tool.WIRE, wc, y)

    # Road grid: roads offset from wire spines by 1
    road_rows = [r + 1 for r in wire_rows if ib(0, r+1)] + [r - 1 for r in wire_rows if ib(0, r-1)]
    road_cols = [c + 1 for c in wire_cols if ib(c+1, 0)] + [c - 1 for c in wire_cols if ib(c-1, 0)]

    for hr in sorted(set(road_rows)):
        if not ib(0, hr):
            continue
        # Check that there's a wire row nearby
        near_wire = any(abs(hr - wr) <= 2 and (wm[wr, :] | pm[wr, :]).any() for wr in wire_rows if ib(0, wr))
        if not near_wire:
            continue
        for x in range(2, WORLD_W - 2):
            if ib(x, hr) and em[hr, x] and not pm[hr, x] and not rm[hr, x]:
                return (Tool.ROAD, x, hr)

    for vc in sorted(set(road_cols)):
        if not ib(vc, 0):
            continue
        near_wire = any(abs(vc - wc) <= 2 and (wm[:, wc] | pm[:, wc]).any() for wc in wire_cols if ib(wc, 0))
        if not near_wire:
            continue
        for y in range(2, WORLD_H - 2):
            if ib(vc, y) and em[y, vc] and not pm[y, vc] and not rm[y, vc]:
                return (Tool.ROAD, vc, y)

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Place zones densely across the whole map
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Prefer spots that are close to any plant
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)

        # Also cluster near existing zones
        if total_zones > 5:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                sample = max(1, len(zone_xs) // 80)
                for i in range(0, len(zone_xs), sample):
                    d2 = np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])
                    zone_dist = np.minimum(zone_dist, d2)
                combined = min_dist * 0.5 + zone_dist * 0.5
            else:
                combined = min_dist
        else:
            combined = min_dist

        order = np.argsort(combined)
        step_off = (step * 11) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services scaled with population - spread across map
    if pop > 50:
        fire_spots = [
            (15, 15), (50, 15), (85, 15), (115, 15),
            (15, 50), (50, 50), (85, 50), (115, 50),
            (15, 85), (50, 85), (85, 85), (115, 85),
            (30, 30), (70, 30), (30, 70), (70, 70),
            (95, 30), (95, 70), (30, 95), (70, 95),
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [
            (25, 25), (60, 25), (95, 25),
            (25, 50), (60, 50), (95, 50),
            (25, 75), (60, 75), (95, 75),
            (10, 40), (110, 40), (10, 60), (110, 60),
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        for stx, sty in [
            (35, 35), (75, 35), (35, 65), (75, 65),
            (55, 15), (55, 85), (15, 50), (105, 50),
            (45, 45), (75, 45), (45, 55), (75, 55),
        ]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        for apx, apy in [
            (55, 5), (55, 93), (5, 45), (112, 45),
            (30, 5), (90, 5), (30, 93), (90, 93),
        ]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        for spx, spy in [
            (5, 50), (113, 50), (60, 3), (60, 95),
            (5, 20), (5, 80), (113, 20), (113, 80),
        ]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 300:
        park_spots = [
            (40, 40), (60, 40), (80, 40),
            (40, 60), (60, 60), (80, 60),
            (20, 30), (100, 30), (20, 70), (100, 70),
            (50, 25), (70, 25), (50, 75), (70, 75),
        ]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    # Fallback: extend roads near existing roads with wire access
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

