def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    pwr = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Determine desired plant locations based on pop
    plant_targets = [
        (60, 50), (20, 50), (100, 50),
        (60, 20), (60, 80),
        (20, 20), (100, 20), (20, 80), (100, 80),
    ]
    if pop > 300:
        plant_targets += [(40, 35), (80, 35), (40, 65), (80, 65)]
    if pop > 800:
        plant_targets += [(10, 35), (110, 35), (10, 65), (110, 65)]
        plant_targets += [(40, 10), (80, 10), (40, 90), (80, 90)]
    if pop > 1500:
        plant_targets += [(60, 5), (60, 95), (5, 50), (115, 50)]
        plant_targets += [(25, 5), (95, 5), (25, 95), (95, 95)]
    if pop > 3000:
        plant_targets += [(10, 10), (110, 10), (10, 90), (110, 90)]
        plant_targets += [(35, 50), (85, 50)]

    # Phase 1: Ensure plants exist
    for px, py in plant_targets:
        if not ib(px, py):
            continue
        # Check if plant already near this location
        found = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # Phase 2: Wire network - build a grid of horizontal and vertical wires
    # Horizontal wire rows
    wire_rows = [20, 35, 50, 65, 80]
    if pop > 200:
        wire_rows += [10, 90]
    if pop > 600:
        wire_rows += [5, 95]
    if pop > 1200:
        wire_rows += [27, 42, 57, 72]

    # Vertical wire cols
    wire_cols = [20, 40, 60, 80, 100]
    if pop > 200:
        wire_cols += [10, 110]
    if pop > 600:
        wire_cols += [5, 115]
    if pop > 1200:
        wire_cols += [30, 50, 70, 90]

    # Fill wire rows completely
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        for x in range(2, WORLD_W - 2):
            if ib(x, wr) and bool(em[wr, x]) and not bool(pm[wr, x]):
                # Only fill if adjacent to existing wire or plant
                adj_power = False
                for dx in [-1, 1]:
                    nx = x + dx
                    if ib(nx, wr) and (bool(wm[wr, nx]) or bool(pm[wr, nx])):
                        adj_power = True
                        break
                if adj_power:
                    return (Tool.WIRE, x, wr)

    # Fill wire cols completely
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        for y in range(2, WORLD_H - 2):
            if ib(wc, y) and bool(em[y, wc]) and not bool(pm[y, wc]):
                adj_power = False
                for dy in [-1, 1]:
                    ny = y + dy
                    if ib(wc, ny) and (bool(wm[ny, wc]) or bool(pm[ny, wc])):
                        adj_power = True
                        break
                if adj_power:
                    return (Tool.WIRE, wc, y)

    # Phase 3: Road network
    road_rows = [22, 37, 44, 56, 63, 78]
    if pop > 200:
        road_rows += [12, 88]
    if pop > 600:
        road_rows += [7, 93]
    if pop > 1200:
        road_rows += [29, 47, 53, 71]

    road_cols = [22, 42, 58, 78, 98]
    if pop > 200:
        road_cols += [12, 108]
    if pop > 600:
        road_cols += [7, 113]
    if pop > 1200:
        road_cols += [32, 48, 72, 88]

    # Compute wire proximity for road planning
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Fill road rows
    for rr in road_rows:
        if not ib(0, rr):
            continue
        if not nbr_wire[rr, :].any():
            continue
        for x in range(2, WORLD_W - 2):
            if ib(x, rr) and bool(em[rr, x]) and not bool(pm[rr, x]):
                adj_road = False
                for dx in [-1, 1]:
                    nx = x + dx
                    if ib(nx, rr) and bool(rm[rr, nx]):
                        adj_road = True
                        break
                if adj_road:
                    return (Tool.ROAD, x, rr)
        # Seed if empty
        if not rm[rr, :].any():
            for wc in wire_cols:
                if ib(wc, rr) and bool(em[rr, wc]) and not bool(pm[rr, wc]):
                    return (Tool.ROAD, wc, rr)

    # Fill road cols
    for rc in road_cols:
        if not ib(rc, 0):
            continue
        if not nbr_wire[:, rc].any():
            continue
        for y in range(2, WORLD_H - 2):
            if ib(rc, y) and bool(em[y, rc]) and not bool(pm[y, rc]):
                adj_road = False
                for dy in [-1, 1]:
                    ny = y + dy
                    if ib(rc, ny) and bool(rm[ny, rc]):
                        adj_road = True
                        break
                if adj_road:
                    return (Tool.ROAD, rc, y)
        if not rm[:, rc].any():
            for wr in wire_rows:
                if ib(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

    # Phase 4: Zone placement
    # Road proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire proximity (wider for zones)
    nbr_wire6 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire6[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire6[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire6
    cand[0:4, :] = False
    cand[WORLD_H-4:, :] = False
    cand[:, 0:4] = False
    cand[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score by proximity to nearest plant and existing zones
        min_plant_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in plant_targets[:9]:  # Use main plants
            if ib(px, py):
                d = np.abs(cxs_arr - px).astype(float) + np.abs(cys_arr - py).astype(float)
                min_plant_dist = np.minimum(min_plant_dist, d)

        if total_zones > 3:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            if len(zone_xs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zone_xs2) // 80)
                for i in range(0, len(zone_xs2), stride):
                    d2 = np.abs(cxs_arr - zone_xs2[i]).astype(float) + np.abs(cys_arr - zone_ys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d2)
                combined = min_plant_dist * 0.3 + zone_dist * 0.7
            else:
                combined = min_plant_dist
        else:
            combined = min_plant_dist

        order = np.argsort(combined)
        # Vary offset by step and pop for exploration
        off = (step * 11 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # Phase 5: Civic services
    if pop > 30:
        fire_locs = [
            (55, 44), (65, 44), (55, 56), (65, 56),
            (38, 38), (82, 38), (38, 62), (82, 62),
            (20, 44), (100, 44), (20, 56), (100, 56),
            (60, 25), (60, 75), (30, 30), (90, 30), (30, 70), (90, 70),
            (15, 20), (105, 20), (15, 80), (105, 80),
            (45, 12), (75, 12), (45, 88), (75, 88),
        ]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_locs = [
            (50, 42), (70, 42), (50, 58), (70, 58),
            (35, 35), (85, 35), (35, 65), (85, 65),
            (18, 42), (102, 42), (18, 58), (102, 58),
            (60, 22), (60, 78), (28, 28), (92, 28), (28, 72), (92, 72),
            (12, 18), (108, 18), (12, 82), (108, 82),
        ]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_locs = [
            (60, 47), (60, 53), (48, 50), (72, 50),
            (42, 40), (78, 40), (42, 60), (78, 60),
            (25, 32), (95, 32), (25, 68), (95, 68),
            (55, 30), (65, 30), (55, 70), (65, 70),
            (30, 50), (90, 50),
        ]
        for pkx, pky in park_locs:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [
            (45, 32), (75, 32), (45, 68), (75, 68),
            (22, 46), (98, 46), (22, 54), (98, 54),
            (60, 12), (60, 88),
            (18, 25), (102, 25), (18, 75), (102, 75),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 900:
        airport_locs = [
            (52, 8), (68, 8), (52, 92), (68, 92),
            (8, 40), (112, 40), (8, 60), (112, 60),
            (15, 12), (105, 12), (15, 88), (105, 88),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        seaport_locs = [
            (8, 50), (112, 50), (60, 6), (60, 94),
            (20, 6), (100, 6), (20, 94), (100, 94),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend roads near wire
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        sk = (step * 13 + pop) % len(rxs)
        for offset in range(min(len(rxs), 120)):
            k = (sk + offset * 7) % len(rxs)
            rx2, ry2 = int(rxs[k]), int(rys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 17 + pop) % len(wxs)
        for offset in range(min(len(wxs), 80)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: extend wire from plants
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk3 = step % len(pxs)
        px2, py2 = int(pxs[sk3]), int(pys[sk3])
        for dx4, dy4 in [(1,0),(-1,0),(0,1),(0,-1)]:
            nx4, ny4 = px2+dx4, py2+dy4
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.WIRE, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: place 4 coal plants with wire spines and flanking roads."""
    actions = []
    # Four plants spread across the middle
    for px in [15, 45, 75, 105]:
        actions.append((Tool.COALPOWER, px, 50))
        # Wire spine vertically
        for dy in range(-5, 6):
            actions.append((Tool.WIRE, px, 50 + dy))
        # Roads flanking wire
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood anchors: (plant_x, plant_y, wire_col, road_left, road_right)
    # 4 columns x 4 rows = 16 anchors across entire 120x100 map
    anchors = []
    for row_y in [18, 38, 62, 82]:
        for col_x in [15, 45, 75, 105]:
            wc = col_x
            rl = col_x - 1
            rr = col_x + 1
            anchors.append((col_x, row_y, wc, rl, rr))

    def num_active():
        if pop < 30:    return 1
        if pop < 100:   return 2
        if pop < 250:   return 4
        if pop < 500:   return 6
        if pop < 900:   return 8
        if pop < 1500:  return 10
        if pop < 2500:  return 12
        if pop < 4000:  return 14
        return 16

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        # Check if there's a plant within 5 tiles
        has_plant = False
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            # Try exact location first
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Search nearby empty tile
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE BUILDING (vertical) ----
    # Each anchor gets a vertical wire spine
    spine_half = min(22, 6 + pop // 20)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-3, 4):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            # Connect horizontally at anchor y-level
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    if n_active >= 5:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 50:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            # Two horizontal roads: above and below wire row
            for horiz_y in [yl - 2, yl + 2]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.2
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [
            (12, 28), (42, 28), (72, 28), (102, 28),
            (12, 48), (42, 48), (72, 48), (102, 48),
            (12, 68), (42, 68), (72, 68), (102, 68),
            (12, 88), (42, 88), (72, 88), (102, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (25, 28), (55, 28), (85, 28),
            (25, 48), (55, 48), (85, 48),
            (25, 68), (55, 68), (85, 68),
            (25, 88), (55, 88), (85, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (30, 10), (70, 10), (110, 10),
            (30, 90), (70, 90), (110, 90),
            (5, 30), (5, 60), (5, 90),
            (115, 30), (115, 60), (115, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (30, 5), (60, 5), (90, 5), (115, 5),
            (30, 95), (60, 95), (90, 95), (5, 50),
            (115, 50), (5, 20), (115, 20), (5, 80),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 300:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 20)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place 4 coal plants with wire spines and flanking roads in a grid."""
    actions = []
    # Plants at 4 corners of center area
    for px, py in [(25, 30), (75, 30), (25, 70), (75, 70)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertical
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Keep balance: ~30% ind, ~30% com, ~40% res
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- DEFINE NEIGHBORHOODS in a 5x4 grid covering the map ----
    # Each neighborhood: (plant_x, plant_y, wire_col, road_left, road_right)
    # 5 columns x 4 rows = 20 neighborhoods
    neighborhoods = []
    col_xs = [12, 36, 60, 84, 108]
    row_ys = [18, 40, 62, 84]
    for cy in row_ys:
        for cx in col_xs:
            wc = cx
            rl = cx - 3
            rr = cx + 3
            neighborhoods.append((cx, cy, wc, rl, rr))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 600:   return 9
        if pop < 1000:  return 12
        if pop < 2000:  return 15
        if pop < 4000:  return 18
        return 20

    n_active = min(num_active(), len(neighborhoods))
    active = neighborhoods[:n_active]

    # ---- ENSURE POWER PLANTS for each active neighborhood ----
    for (px, py, wc, rl, rr) in active:
        # Check if there's a plant within 6 tiles
        has_plant = False
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            # Try to place at px, py first
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Search nearby
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE: grow vertical wire from each plant ----
    spine_half = min(20, 6 + pop // 25)
    for (px, py, wc, rl, rr) in active:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            # Seed wire adjacent to plant
            for dy in range(-5, 6):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting neighborhoods in same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active))
    for yl in y_levels:
        row_a = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_a) - 1):
            wc1 = row_a[i][2]
            wc2 = row_a[i + 1][2]
            # Connect at y=yl
            for cx in range(wc1, wc2 + 1):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting rows ----
    if n_active >= 6:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active))
        for wc in wc_cols:
            col_a = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_a) - 1):
                py1 = col_a[i][1]
                py2 = col_a[i + 1][1]
                for cy in range(py1, py2 + 1):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active):
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = (step + idx * 7) % 6
        for wr in wire_rows[cycle::6]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS connecting neighborhoods in same row ----
    if pop > 80:
        for yl in y_levels:
            row_a = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active if py == yl],
                key=lambda a: a[3]
            )
            if len(row_a) < 2:
                continue
            rl0 = row_a[0][3]
            rr_last = row_a[-1][4]
            # Road above and below the wire level
            for horiz_y in [yl - 3, yl + 3]:
                if not ib(rl0, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl0, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active:
            d = (np.abs(cxs - wc).astype(float) +
                 np.abs(cys - py).astype(float) * 0.6)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 11) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 9) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 120:
        fire_spots = []
        for cy in row_ys:
            for cx in col_xs:
                fire_spots.append((cx + 7, cy))
                fire_spots.append((cx - 7, cy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = []
        for cy in row_ys:
            for cx in col_xs:
                police_spots.append((cx + 8, cy + 5))
                police_spots.append((cx - 8, cy - 5))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 900:
        stadium_spots = [(55, 9), (95, 9), (15, 9), (55, 92), (95, 92), (15, 92)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [(30, 6), (70, 6), (110, 6), (30, 94), (70, 94), (110, 94)]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3500:
        for asp in [(55, 5), (5, 48), (115, 48), (55, 95)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 95), (115, 95), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones to boost land value ----
    if pop > 300:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 20)):
                k = (step * 5 + i * 19) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3),
                                  (4, 0), (0, 4), (-4, 0), (0, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at corners + center, wire grid, seed roads"""
    actions = []
    # Four quadrant power plants
    plants = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spine at y=25, y=50, y=75
    for y in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, y))
    # Vertical wire spines at x=25, x=60, x=95
    for x in [25, 60, 95]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, x, y))
    # Seed roads parallel to wire spines
    for y in [24, 26, 49, 51, 74, 76]:
        for x in range(2, 118):
            actions.append((Tool.ROAD, x, y))
    for x in [24, 26, 59, 61, 94, 96]:
        for y in range(2, 98):
            actions.append((Tool.ROAD, x, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'wire'
        state['wire_idx'] = 0
        state['road_idx'] = 0
        state['zone_idx'] = 0
        state['service_idx'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target mix: 50% res, 25% com, 25% ind
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Power plants based on population growth
    plant_configs = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
    if pop > 200:
        plant_configs += [(10, 10), (110, 10), (10, 90), (110, 90)]
    if pop > 500:
        plant_configs += [(40, 10), (80, 10), (40, 90), (80, 90)]
    if pop > 1000:
        plant_configs += [(10, 50), (110, 50), (60, 10), (60, 90)]
    if pop > 2000:
        plant_configs += [(25, 50), (95, 50), (40, 30), (80, 30), (40, 70), (80, 70)]

    # Ensure power plants exist
    for px, py in plant_configs:
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px+dx, py+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found and ib(px, py):
            return (Tool.COALPOWER, px, py)

    # Wire grid: horizontal at every 12 rows, vertical at every 12 cols
    wire_rows = list(range(12, 99, 12))
    wire_cols = list(range(12, 119, 12))

    # Extend wire grid
    for wr in wire_rows:
        for x in range(1, WORLD_W - 1):
            if em[wr, x] and not pm[wr, x] and not wm[wr, x]:
                left_ok = (ib(x-1, wr) and (wm[wr, x-1] or pm[wr, x-1]))
                right_ok = (ib(x+1, wr) and (wm[wr, x+1] or pm[wr, x+1]))
                if left_ok or right_ok:
                    return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        for y in range(1, WORLD_H - 1):
            if em[y, wc] and not pm[y, wc] and not wm[y, wc]:
                up_ok = (ib(wc, y-1) and (wm[y-1, wc] or pm[y-1, wc]))
                dn_ok = (ib(wc, y+1) and (wm[y+1, wc] or pm[y+1, wc]))
                if up_ok or dn_ok:
                    return (Tool.WIRE, wc, y)

    # Road grid: parallel to wire grid with offset
    road_rows = list(range(11, 99, 12)) + list(range(13, 99, 12))
    road_cols = list(range(11, 119, 12)) + list(range(13, 119, 12))

    # Build horizontal roads
    for rr in road_rows:
        if not ib(0, rr):
            continue
        near_wire = (rr > 0 and (wm[rr-1, :] | pm[rr-1, :]).any()) or \
                    (rr < WORLD_H-1 and (wm[rr+1, :] | pm[rr+1, :]).any())
        if near_wire:
            for x in range(2, WORLD_W - 2):
                if ib(x, rr) and em[rr, x] and not pm[rr, x] and not rm[rr, x]:
                    return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        if not ib(rc, 0):
            continue
        near_wire = (rc > 0 and (wm[:, rc-1] | pm[:, rc-1]).any()) or \
                    (rc < WORLD_W-1 and (wm[:, rc+1] | pm[:, rc+1]).any())
        if near_wire:
            for y in range(2, WORLD_H - 2):
                if ib(rc, y) and em[y, rc] and not pm[y, rc] and not rm[y, rc]:
                    return (Tool.ROAD, rc, y)

    # Compute proximity masks for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Zone placement: spread across the map near infrastructure
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance from nearest power plant (spread evenly)
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in plant_configs:
            d = np.abs(cxs_arr - px) + np.abs(cys_arr - py)
            min_dist = np.minimum(min_dist, d)

        # Cluster bonus: prefer near existing zones
        if total_zones > 3:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zone_xs) // 80)
                for i in range(0, len(zone_xs), stride):
                    d2 = np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])
                    zone_dist = np.minimum(zone_dist, d2)
                combined = min_dist * 0.5 + zone_dist * 0.5
            else:
                combined = min_dist
        else:
            combined = min_dist

        order = np.argsort(combined)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # Services based on population - spread across map
    if pop > 50:
        fire_spots = [
            (22, 22), (98, 22), (22, 78), (98, 78), (60, 48),
            (40, 38), (80, 38), (40, 62), (80, 62), (60, 20),
            (60, 80), (10, 50), (110, 50), (15, 35), (105, 35),
            (15, 65), (105, 65)
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [
            (30, 30), (90, 30), (30, 70), (90, 70), (60, 55),
            (45, 45), (75, 45), (45, 55), (75, 55),
            (20, 45), (100, 45), (20, 55), (100, 55),
            (60, 35), (60, 65)
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        for stx, sty in [
            (35, 35), (85, 35), (35, 65), (85, 65),
            (60, 40), (60, 60), (20, 30), (100, 30),
            (20, 70), (100, 70)
        ]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        for apx, apy in [
            (55, 5), (55, 95), (5, 45), (115, 45),
            (5, 55), (115, 55)
        ]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        for spx, spy in [
            (5, 50), (115, 50), (60, 3), (60, 97),
            (30, 5), (90, 5), (30, 95), (90, 95)
        ]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Parks for land value
    if pop > 300:
        park_spots = [
            (48, 48), (72, 48), (48, 52), (72, 52),
            (36, 36), (84, 36), (36, 64), (84, 64),
            (60, 42), (60, 58), (30, 50), (90, 50)
        ]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    # Fallback: extend roads near wire
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# High-reactivity, ambitious multi-cluster policy
# Strategy: Build a dense grid of roads with power plants at intersections,
# then fill every road-adjacent, powered cell with zones.
# Uses multiple power plants spread across the map in a grid pattern.

def init(obs, state):
    """Bootstrap: place first coal plant and seed infrastructure."""
    actions = []
    # Primary plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire in all 4 directions from plant
    for d in range(1, 4):
        actions.append((Tool.WIRE, 60 + d, 50))
        actions.append((Tool.WIRE, 60 - d, 50))
        actions.append((Tool.WIRE, 60, 50 + d))
        actions.append((Tool.WIRE, 60, 50 - d))
    # Seed roads
    actions.append((Tool.ROAD, 64, 50))
    actions.append((Tool.ROAD, 56, 50))
    actions.append((Tool.ROAD, 60, 54))
    actions.append((Tool.ROAD, 60, 46))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    total_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- GRID OF POWER PLANTS ----
    # Place coal plants at a regular grid so power is everywhere
    # Plants at every 20 cols, 25 rows -> 6x4 = 24 plants
    plant_grid_xs = [20, 40, 60, 80, 100]
    plant_grid_ys = [15, 35, 55, 75, 92]

    # Unlock plants progressively
    def max_plants():
        if pop < 200: return 1
        if pop < 500: return 3
        if pop < 1000: return 6
        if pop < 2000: return 10
        if pop < 4000: return 16
        return 25

    plant_positions = []
    for py in plant_grid_ys:
        for px in plant_grid_xs:
            plant_positions.append((px, py))

    active_plants = plant_positions[:max_plants()]

    # Ensure each active plant exists
    for (px, py) in active_plants:
        has_plant = False
        for dx in range(-3, 4):
            for dy in range(-3, 4):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Place plant at px, py or nearby empty spot
            placed = False
            for r in range(5):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
            break

    # ---- BUILD HORIZONTAL AND VERTICAL ROAD GRID ----
    # Road grid: horizontal roads at every 6 rows, vertical roads at every 6 cols
    # This creates a dense mesh for zone access
    road_row_spacing = 6
    road_col_spacing = 6

    road_rows = list(range(8, WORLD_H - 4, road_row_spacing))
    road_cols = list(range(6, WORLD_W - 4, road_col_spacing))

    # Count how much road we have
    road_count = int(np.sum(rm))

    # How many road rows/cols to build based on population
    def max_road_rows():
        if pop < 100: return 3
        if pop < 300: return 5
        if pop < 800: return 8
        if pop < 2000: return 12
        return len(road_rows)

    def max_road_cols():
        if pop < 100: return 3
        if pop < 300: return 5
        if pop < 800: return 8
        if pop < 2000: return 12
        return len(road_cols)

    active_road_rows = road_rows[:max_road_rows()]
    active_road_cols = road_cols[:max_road_cols()]

    # ---- WIRE CONNECTIONS from plants to road grid ----
    # Build wires from each active plant to connect the power grid
    # Wire horizontally and vertically from plant positions

    # First priority: extend wires from existing wire/plant network
    # Find wire frontier and extend
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    plant_ys_arr, plant_xs_arr = np.where(pm)

    # Build a comprehensive wire network connecting all plants
    # Strategy: extend wire along road_rows and road_cols
    for ry in active_road_rows:
        wire_in_row = [c for c in range(WORLD_W) if ib(c, ry) and bool(wm[ry, c])]
        # Find gaps and extend
        if len(wire_in_row) > 0:
            # Extend leftward
            min_wc = min(wire_in_row)
            if min_wc > active_road_cols[0] if active_road_cols else 6:
                nc = min_wc - 1
                if ib(nc, ry) and bool(em[ry, nc]) and not bool(pm[ry, nc]):
                    return (Tool.WIRE, nc, ry)
            # Extend rightward
            max_wc = max(wire_in_row)
            target_right = active_road_cols[-1] if active_road_cols else WORLD_W - 6
            if max_wc < target_right:
                nc = max_wc + 1
                if ib(nc, ry) and bool(em[ry, nc]) and not bool(pm[ry, nc]):
                    return (Tool.WIRE, nc, ry)

    # Connect wires vertically between road rows near plant columns
    for (px, py) in active_plants:
        wire_in_col = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_in_col:
            # Place wire adjacent to plant
            for dy in [-1, 1, 0]:
                for dx in [-1, 0, 1]:
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            # Extend toward nearest road rows
            target_top = active_road_rows[0] if active_road_rows else 8
            target_bot = active_road_rows[-1] if active_road_rows else WORLD_H - 8
            if min_wr > target_top:
                nr = min_wr - 1
                if ib(px, nr) and bool(em[nr, px]) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if max_wr < target_bot:
                nr = max_wr + 1
                if ib(px, nr) and bool(em[nr, px]) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- ROAD GRID BUILDING ----
    # Build horizontal road rows
    for ry in active_road_rows:
        # Find gaps in this row
        row_road = [c for c in range(WORLD_W) if ib(c, ry) and bool(rm[ry, c])]
        target_left = 4
        target_right = WORLD_W - 5

        if len(row_road) == 0:
            # Start road near a plant or wire
            for cx in range(target_left, target_right):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    # Check if near wire
                    near_wire = any(
                        ib(cx + ddx, ry + ddy) and (bool(wm[ry + ddy, cx + ddx]) or bool(pm[ry + ddy, cx + ddx]))
                        for ddx in range(-3, 4) for ddy in range(-3, 4)
                    )
                    if near_wire:
                        return (Tool.ROAD, cx, ry)
        else:
            min_rc = min(row_road)
            max_rc = max(row_road)
            if min_rc > target_left:
                nc = min_rc - 1
                if ib(nc, ry) and bool(em[ry, nc]) and not bool(pm[ry, nc]):
                    return (Tool.ROAD, nc, ry)
            if max_rc < target_right:
                nc = max_rc + 1
                if ib(nc, ry) and bool(em[ry, nc]) and not bool(pm[ry, nc]):
                    return (Tool.ROAD, nc, ry)

    # Build vertical road cols
    for cx in active_road_cols:
        col_road = [r for r in range(WORLD_H) if ib(cx, r) and bool(rm[r, cx])]
        target_top = 4
        target_bot = WORLD_H - 5

        if len(col_road) == 0:
            for ry in range(target_top, target_bot):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    near_wire = any(
                        ib(cx + ddx, ry + ddy) and (bool(wm[ry + ddy, cx + ddx]) or bool(pm[ry + ddy, cx + ddx]))
                        for ddx in range(-3, 4) for ddy in range(-3, 4)
                    )
                    if near_wire:
                        return (Tool.ROAD, cx, ry)
        else:
            min_rr = min(col_road)
            max_rr = max(col_road)
            if min_rr > target_top:
                nr = min_rr - 1
                if ib(cx, nr) and bool(em[nr, cx]) and not bool(pm[nr, cx]):
                    return (Tool.ROAD, cx, nr)
            if max_rr < target_bot:
                nr = max_rr + 1
                if ib(cx, nr) and bool(em[nr, cx]) and not bool(pm[nr, cx]):
                    return (Tool.ROAD, cx, nr)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor wire mask (within 6 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep margin from edges
    cand_mask[:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, :3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near power plants and roads
        # Score by: close to plant (power), close to existing zones (density)
        best_score = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_score = np.minimum(best_score, d)

        order = np.argsort(best_score)
        # Use step to rotate through candidates for variety
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- CIVIC SERVICES based on population ----
    if pop > 200:
        fire_spots = [
            (30, 20), (60, 20), (90, 20),
            (30, 50), (90, 50),
            (30, 80), (60, 80), (90, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = [
            (20, 30), (50, 30), (80, 30), (110, 30),
            (20, 60), (50, 60), (80, 60), (110, 60),
            (20, 85), (50, 85), (80, 85), (110, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadium_spots = [(55, 8), (55, 90), (10, 50), (108, 50)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        # Add seaport and airport for big city
        for (sx, sy) in [(10, 15), (10, 80)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- EXTEND ROADS from existing road network near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place a new plant + seed ----
    # Find a large empty area and plant there
    for attempt in range(20):
        cx = ((step * 17 + attempt * 31) % (WORLD_W - 20)) + 10
        cy = ((step * 19 + attempt * 37) % (WORLD_H - 20)) + 10
        if ib(cx, cy) and bool(em[cy, cx]):
            return (Tool.COALPOWER, cx, cy)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spine + flanking roads"""
    actions = []
    # Primary coal plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Vertical wire spine right of plant
    for y in range(44, 57):
        actions.append((Tool.WIRE, 62, y))
    # Flanking roads
    for y in range(44, 57):
        actions.append((Tool.ROAD, 61, y))
        actions.append((Tool.ROAD, 63, y))
    # Horizontal wire connector
    for x in range(61, 63):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Dynamic plant network ---
    # Plants placed at strategic locations, added as city grows
    desired_plants = [(60, 50)]
    if pop > 100 or total_zones > 5:
        desired_plants += [(30, 50), (90, 50)]
    if pop > 400:
        desired_plants += [(60, 25), (60, 75)]
    if pop > 800:
        desired_plants += [(30, 25), (90, 25), (30, 75), (90, 75)]
    if pop > 1500:
        desired_plants += [(15, 50), (105, 50)]
    if pop > 2500:
        desired_plants += [(15, 25), (105, 25), (15, 75), (105, 75)]

    # Ensure each desired plant exists (check if plant nearby)
    plant_ys, plant_xs = np.where(pm)
    existing_plants = list(zip(plant_xs.tolist(), plant_ys.tolist()))

    for dpx, dpy in desired_plants:
        found = any(abs(epx - dpx) <= 5 and abs(epy - dpy) <= 5
                    for epx, epy in existing_plants)
        if not found:
            if ib(dpx, dpy) and (bool(em[dpy, dpx]) or bool(pm[dpy, dpx])):
                return (Tool.COALPOWER, dpx, dpy)

    # Rebuild existing_plants after potential placement
    plant_ys2, plant_xs2 = np.where(pm)
    existing_plants = list(zip(plant_xs2.tolist(), plant_ys2.tolist()))

    # --- Wire network: vertical spines + horizontal connectors ---
    # For each plant, build a vertical wire spine 2 tiles to the right
    for epx, epy in existing_plants:
        wc = epx + 2
        if not ib(wc, epy):
            wc = epx - 2
        if not ib(wc, epy):
            continue

        pop_factor = min(35, 5 + pop // 20)
        spine_top = max(3, epy - pop_factor)
        spine_bot = min(WORLD_H - 4, epy + pop_factor)

        wire_in_col = [r for r in range(WORLD_H)
                       if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]

        if not wire_in_col:
            # Seed wire adjacent to plant
            for dy in range(-1, 2):
                ny = epy + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and bool(em[nr, wc]) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and bool(em[nr, wc]) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # --- Horizontal wire connectors between plants ---
    if len(existing_plants) > 1:
        sorted_plants = sorted(existing_plants, key=lambda p: p[0])
        for i in range(len(sorted_plants) - 1):
            p1x, p1y = sorted_plants[i]
            p2x, p2y = sorted_plants[i + 1]
            # Connect at midpoint row
            mid_y = (p1y + p2y) // 2
            for x in range(p1x, p2x + 1):
                if ib(x, mid_y) and bool(em[mid_y, x]) and not bool(pm[mid_y, x]):
                    if not bool(wm[mid_y, x]):
                        # Check if adjacent to wire/plant
                        has_adj = False
                        for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                            nx2, ny2 = x+ddx, mid_y+ddy
                            if ib(nx2, ny2) and (bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                                has_adj = True
                                break
                        if has_adj:
                            return (Tool.WIRE, x, mid_y)

    # --- Cross-wire rows at various horizontal levels ---
    cross_rows = [25, 35, 45, 50, 55, 65, 75]
    if pop > 400:
        cross_rows += [15, 85]
    if pop > 1000:
        cross_rows += [10, 90]

    for cr in cross_rows:
        if not ib(0, cr):
            continue
        for x in range(1, WORLD_W - 1):
            if bool(em[cr, x]) and not bool(pm[cr, x]) and not bool(wm[cr, x]):
                # Only place if adjacent to wire/plant
                has_adj = False
                for ddx2, ddy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx3, ny3 = x+ddx2, cr+ddy2
                    if ib(nx3, ny3) and (bool(wm[ny3, nx3]) or bool(pm[ny3, nx3])):
                        has_adj = True
                        break
                if has_adj:
                    return (Tool.WIRE, x, cr)

    # --- Road grid: flanking roads for each wire spine ---
    for epx, epy in existing_plants:
        wc = epx + 2
        if not ib(wc, epy):
            wc = epx - 2
        if not ib(wc, epy):
            continue
        road_l = wc - 1
        road_r = wc + 1

        wire_in_col = [r for r in range(WORLD_H)
                       if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]

        for wr in wire_in_col:
            if ib(road_l, wr) and bool(em[wr, road_l]) and not bool(pm[wr, road_l]):
                return (Tool.ROAD, road_l, wr)
            if ib(road_r, wr) and bool(em[wr, road_r]) and not bool(pm[wr, road_r]):
                return (Tool.ROAD, road_r, wr)

    # --- Horizontal roads at cross-wire rows ---
    h_road_rows = [24, 26, 34, 36, 44, 46, 51, 54, 56, 64, 66, 74, 76]
    if pop > 400:
        h_road_rows += [14, 16, 84, 86]
    if pop > 1000:
        h_road_rows += [9, 11, 89, 91]

    for hr in h_road_rows:
        if not ib(0, hr):
            continue
        wire_above = hr > 0 and bool((wm[hr-1, :] | pm[hr-1, :]).any())
        wire_below = hr < WORLD_H-1 and bool((wm[hr+1, :] | pm[hr+1, :]).any())
        if wire_above or wire_below:
            for x in range(2, WORLD_W - 2):
                if ib(x, hr) and bool(em[hr, x]) and not bool(pm[hr, x]) and not bool(rm[hr, x]):
                    return (Tool.ROAD, x, hr)

    # --- Build proximity masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance to nearest plant
        min_dist = np.full(len(cxs_arr), 999999.0)
        for epx, epy in existing_plants:
            d = np.abs(cxs_arr - epx) + np.abs(cys_arr - epy)
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 150)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- Services based on population ---
    if pop > 100:
        fire_spots = []
        for epx, epy in existing_plants:
            fire_spots += [(epx - 12, epy - 12), (epx + 12, epy - 12),
                           (epx - 12, epy + 12), (epx + 12, epy + 12)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_spots = []
        for epx, epy in existing_plants:
            police_spots += [(epx - 8, epy - 8), (epx + 8, epy - 8),
                              (epx - 8, epy + 8), (epx + 8, epy + 8)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 600:
        for stx, sty in [(45, 35), (75, 35), (45, 65), (75, 65),
                          (20, 35), (100, 35), (20, 65), (100, 65)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        for apx, apy in [(55, 15), (55, 85), (15, 50), (105, 50)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        for spx, spy in [(10, 50), (110, 50), (60, 10), (60, 90)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire ---
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place a dense central power grid with roads."""
    actions = []
    # Place 6 coal plants in a 2x3 grid across the map center
    plant_positions = [
        (20, 25), (60, 25), (100, 25),
        (20, 75), (60, 75), (100, 75),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine horizontal and vertical
        for d in range(-5, 6):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px, py + d))
        # Roads flanking
        for d in range(-5, 6):
            actions.append((Tool.ROAD, px - 4, py + d))
            actions.append((Tool.ROAD, px + 4, py + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 40% RES, 35% COM, 25% IND
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define a dense 6x5 grid of neighborhood centers
    col_xs = [15, 35, 55, 75, 95, 115]
    row_ys = [15, 32, 50, 68, 85]

    # Each neighborhood: (center_x, center_y, wire_x, road_left, road_right)
    neighborhoods = []
    for cy in row_ys:
        for cx in col_xs:
            wc = cx
            rl = cx - 4
            rr = cx + 4
            neighborhoods.append((cx, cy, wc, rl, rr))

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 300:   return 10
        if pop < 600:   return 15
        if pop < 1000:  return 20
        if pop < 2000:  return 24
        if pop < 4000:  return 28
        return len(neighborhoods)

    n_active = min(num_active(), len(neighborhoods))
    # Activate neighborhoods from center outward
    center_x, center_y = 60, 50
    def dist_to_center(n):
        return abs(n[0] - center_x) + abs(n[1] - center_y)
    sorted_hoods = sorted(neighborhoods, key=dist_to_center)
    active = sorted_hoods[:n_active]

    # ---- ENSURE POWER PLANTS for each active neighborhood ----
    for (px, py, wc, rl, rr) in active:
        has_plant = False
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: connect all active plants ----
    # First, wire spine vertical for each column
    for (px, py, wc, rl, rr) in active:
        spine_half = min(18, 8 + pop // 20)
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            for dy in range(-6, 7):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    if bool(em[nr, wc]) or bool(wm[nr, wc]):
                        return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting neighborhoods in same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active))
    for yl in y_levels:
        row_a = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_a) - 1):
            wc1 = row_a[i][2]
            wc2 = row_a[i + 1][2]
            for cx in range(wc1, wc2 + 1):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting rows ----
    if n_active >= 6:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active))
        for wc in wc_cols:
            col_a = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_a) - 1):
                py1 = col_a[i][1]
                py2 = col_a[i + 1][1]
                for cy in range(py1, py2 + 1):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING ----
    # Flanking roads beside wire spines
    for idx, (px, py, wc, rl, rr) in enumerate(active):
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = (step + idx * 5) % 4
        for wr in wire_rows[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # Horizontal roads at each row level (grid roads)
    for yl in y_levels:
        row_a = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active if py == yl],
            key=lambda a: a[3]
        )
        if len(row_a) < 2:
            continue
        rl0 = row_a[0][3]
        rr_last = row_a[-1][4]
        for horiz_y in [yl - 4, yl + 4]:
            if not ib(rl0, horiz_y) or not ib(rr_last, horiz_y):
                continue
            for cx in range(rl0, rr_last + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # Vertical connecting roads between rows
    if n_active >= 10:
        for rl_x in [col_xs[0] - 4, col_xs[-1] + 4] + list(col_xs):
            r_col = rl_x - 4
            col_a = sorted(set(py for (_, py, _, _, _) in active))
            for i in range(len(col_a) - 1):
                py1 = col_a[i]
                py2 = col_a[i + 1]
                for cy in range(py1, py2 + 1):
                    if ib(r_col, cy) and bool(em[cy, r_col]) and not bool(pm[cy, r_col]):
                        return (Tool.ROAD, r_col, cy)

    # ---- NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active:
            d = (np.abs(cxs - px).astype(float) * 0.8 +
                 np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 13) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    # Fire stations in a grid
    if pop > 80:
        fire_grid = [(cx + 6, cy + 6) for cy in row_ys for cx in col_xs]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_grid = [(cx - 6, cy - 6) for cy in row_ys for cx in col_xs]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [(30, 8), (70, 8), (110, 8),
                         (30, 92), (70, 92), (110, 92)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [(10, 50), (50, 50), (90, 50), (110, 50)]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3000:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 95)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 5), (115, 5), (5, 95), (115, 95)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones to boost land value ----
    if pop > 200:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, -3), (3, -3), (-3, 3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 19) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 11) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

