def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    pwr = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---------- PHASE 1: Ensure power plants are placed ----------
    # Grid of plants covering the map
    plant_targets = []
    for py in range(20, 90, 20):
        for px in range(20, 110, 20):
            plant_targets.append((px, py))

    for px, py in plant_targets:
        if not ib(px, py):
            continue
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # ---------- PHASE 2: Wire grid ----------
    # Dense wire grid: every 10 rows/cols
    wire_rows = list(range(20, 90, 10))
    wire_cols = list(range(20, 110, 10))

    # Fill wire rows from existing wire/plant
    for wr in wire_rows:
        if not (0 <= wr < WORLD_H):
            continue
        row_has_power = bool(np.any(wm[wr, :] | pm[wr, :]))
        if not row_has_power:
            # Seed from plant intersection
            for wc in wire_cols:
                if ib(wc, wr) and pm[wr, wc]:
                    row_has_power = True
                    break
        if not row_has_power:
            continue
        for x in range(2, WORLD_W - 2):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                # Check adjacency to wire or plant
                adj = False
                for dx in [-1, 1]:
                    nx = x + dx
                    if ib(nx, wr) and (wm[wr, nx] or pm[wr, nx]):
                        adj = True
                        break
                if adj:
                    return (Tool.WIRE, x, wr)

    # Fill wire cols
    for wc in wire_cols:
        if not (0 <= wc < WORLD_W):
            continue
        col_has_power = bool(np.any(wm[:, wc] | pm[:, wc]))
        if not col_has_power:
            continue
        for y in range(2, WORLD_H - 2):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                adj = False
                for dy in [-1, 1]:
                    ny = y + dy
                    if ib(wc, ny) and (wm[ny, wc] or pm[ny, wc]):
                        adj = True
                        break
                if adj:
                    return (Tool.WIRE, wc, y)

    # ---------- PHASE 3: Road grid ----------
    # Roads 2 tiles offset from wire grid
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 2)
        road_rows.append(wr + 2)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 2)
        road_cols.append(wc + 2)

    road_rows = [r for r in road_rows if 2 <= r < WORLD_H - 2]
    road_cols = [c for c in road_cols if 2 <= c < WORLD_W - 2]

    # Precompute wire proximity (for road planning)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    for rr in road_rows:
        if not nbr_wire[rr, :].any():
            continue
        for x in range(2, WORLD_W - 2):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                adj = False
                for dx in [-1, 1]:
                    nx = x + dx
                    if ib(nx, rr) and rm[rr, nx]:
                        adj = True
                        break
                if adj:
                    return (Tool.ROAD, x, rr)
        # Seed road row at wire col intersection
        if not rm[rr, :].any():
            for wc in wire_cols:
                if ib(wc, rr) and em[rr, wc] and not pm[rr, wc] and nbr_wire[rr, wc]:
                    return (Tool.ROAD, wc, rr)

    for rc in road_cols:
        if not nbr_wire[:, rc].any():
            continue
        for y in range(2, WORLD_H - 2):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                adj = False
                for dy in [-1, 1]:
                    ny = y + dy
                    if ib(rc, ny) and rm[ny, rc]:
                        adj = True
                        break
                if adj:
                    return (Tool.ROAD, rc, y)
        if not rm[:, rc].any():
            for wr in wire_rows:
                if ib(rc, wr) and em[wr, rc] and not pm[wr, rc] and nbr_wire[wr, rc]:
                    return (Tool.ROAD, rc, wr)

    # ---------- PHASE 4: Zone placement ----------
    # Road proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire proximity for zones
    nbr_wire8 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire8[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire8[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire8
    cand[0:5, :] = False
    cand[WORLD_H-5:, :] = False
    cand[:, 0:5] = False
    cand[:, WORLD_W-5:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: prefer near existing zones and roads
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            zone_dist = np.full(len(cxs_arr), 999999.0)
            stride = max(1, len(zone_xs) // 100)
            for i in range(0, len(zone_xs), stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            score = zone_dist
        else:
            # First zone: place near center
            score = np.abs(cxs_arr - 60).astype(float) + np.abs(cys_arr - 50).astype(float)

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---------- PHASE 5: Civic services ----------
    if pop > 20:
        # Fire stations spread across the map
        fire_locs = []
        for fy in range(25, 90, 15):
            for fx in range(25, 110, 15):
                fire_locs.append((fx, fy))
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_locs = []
        for py2 in range(30, 85, 20):
            for px2 in range(30, 105, 20):
                police_locs.append((px2, py2))
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_locs = []
        for py3 in range(22, 90, 8):
            for px3 in range(22, 110, 8):
                park_locs.append((px3, py3))
        for pkx, pky in park_locs:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(40, 30), (80, 30), (40, 70), (80, 70),
                        (20, 50), (100, 50), (60, 15), (60, 85),
                        (25, 20), (95, 20), (25, 80), (95, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        airport_locs = [(50, 8), (70, 8), (50, 92), (70, 92),
                        (8, 42), (112, 42), (8, 58), (112, 58),
                        (15, 15), (105, 15), (15, 85), (105, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 92),
                        (25, 8), (95, 8), (25, 92), (95, 92),
                        (8, 30), (112, 30), (8, 70), (112, 70)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---------- Fallback: extend roads near wire ----------
    rys, rxs = np.where(rm)
    if len(rxs) > 0:
        sk = (step * 13 + pop) % len(rxs)
        for offset in range(min(len(rxs), 200)):
            k = (sk + offset * 7) % len(rxs)
            rx2, ry2 = int(rxs[k]), int(rys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---------- Fallback: extend wire ----------
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 17 + pop) % len(wxs)
        for offset in range(min(len(wxs), 100)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: extend wire from plants
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk3 = step % len(pxs)
        px2, py2 = int(pxs[sk3]), int(pys[sk3])
        for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx4, ny4 = px2 + dx4, py2 + dy4
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.WIRE, nx4, ny4)

    return None

