def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Count zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Zone balance picker
    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure power plants exist ---
    plant_ys, plant_xs = np.where(pm)
    n_plants = 0
    if len(plant_xs) > 0:
        # Count distinct plants (they're 3x3, so count clusters)
        n_plants = max(1, len(plant_xs) // 9)

    # Place additional plants based on population growth
    plant_targets = [
        (30, 50), (60, 50), (90, 50),
        (30, 25), (60, 25), (90, 25),
        (30, 75), (60, 75), (90, 75),
    ]

    needed_plants = 1
    if pop > 500: needed_plants = 2
    if pop > 1500: needed_plants = 3
    if pop > 3000: needed_plants = 4
    if pop > 5000: needed_plants = 6
    if pop > 8000: needed_plants = 9

    if len(plant_xs) == 0:
        return (Tool.COALPOWER, 30, 50)

    # Check if we need more plants
    for px_t, py_t in plant_targets[:needed_plants]:
        # Check if plant already exists nearby
        has_plant = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px_t + dx, py_t + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if in_bounds(px_t, py_t) and bool(em[py_t, px_t]):
                return (Tool.COALPOWER, px_t, py_t)

    # --- PHASE 2: Build wire network connecting all plants ---
    # Horizontal wire backbone at y=50, y=25, y=75
    backbone_ys = [50, 25, 75]
    for by in backbone_ys:
        for bx in range(2, WORLD_W - 2):
            if in_bounds(bx, by) and bool(em[by, bx]) and not bool(pm[by, bx]):
                # Check if this row needs wire (adjacent to existing wire or plant)
                has_wire_nearby = False
                for dx in [-1, 1]:
                    nx = bx + dx
                    if in_bounds(nx, by) and (bool(wm[by, nx]) or bool(pm[by, nx])):
                        has_wire_nearby = True
                        break
                if has_wire_nearby:
                    return (Tool.WIRE, bx, by)

    # Vertical wire spines at x=30, x=60, x=90 connecting backbones
    spine_xs = [30, 60, 90]
    for sx in spine_xs:
        for sy in range(2, WORLD_H - 2):
            if in_bounds(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                has_wire_nearby = False
                for dy in [-1, 1]:
                    ny = sy + dy
                    if in_bounds(sx, ny) and (bool(wm[ny, sx]) or bool(pm[ny, sx])):
                        has_wire_nearby = True
                        break
                if has_wire_nearby:
                    # Only extend spine in wired regions
                    return (Tool.WIRE, sx, sy)

    # --- PHASE 3: Build road grid ---
    # Road columns flanking each wire spine
    road_cols = [29, 31, 59, 61, 89, 91]
    road_row_ranges = [(3, 97)]  # full vertical range

    for rc in road_cols:
        if not in_bounds(rc, 50):
            continue
        # Find existing road in this column and extend
        road_in_col = [r for r in range(WORLD_H) if in_bounds(rc, r) and bool(rm[r, rc])]
        wire_in_col = [r for r in range(WORLD_H) if in_bounds(rc, r) and bool(wm[r, rc])]

        if not road_in_col and not wire_in_col:
            # Seed road near center
            if in_bounds(rc, 50) and bool(em[50, rc]):
                return (Tool.ROAD, rc, 50)
        else:
            # Extend road to cover wired rows
            target_rows = set()
            # Use wire in neighboring spine column as guide
            spine_col = 30 if rc in [29, 31] else (60 if rc in [59, 61] else 90)
            for r in range(WORLD_H):
                if in_bounds(spine_col, r) and (bool(wm[r, spine_col]) or bool(pm[r, spine_col])):
                    target_rows.add(r)

            covered = set(road_in_col)
            for tr in sorted(target_rows):
                if tr not in covered and in_bounds(rc, tr) and bool(em[tr, rc]) and not bool(pm[tr, rc]):
                    return (Tool.ROAD, rc, tr)

    # --- PHASE 4: Horizontal roads connecting neighborhoods ---
    # Cross-streets at regular intervals
    cross_street_ys = [38, 43, 48, 53, 58, 63,
                       15, 20, 25, 30, 35,
                       65, 70, 75, 80, 85]

    for csy in cross_street_ys:
        if not in_bounds(0, csy):
            continue
        # Extend existing roads horizontally
        road_in_row = [c for c in range(WORLD_W) if in_bounds(c, csy) and bool(rm[csy, c])]
        wire_in_row = [c for c in range(WORLD_W) if in_bounds(c, csy) and (bool(wm[csy, c]) or bool(pm[csy, c]))]

        if road_in_row and wire_in_row:
            # Extend road toward wire
            min_road = min(road_in_row)
            max_road = max(road_in_row)
            min_wire = min(wire_in_row)
            max_wire = max(wire_in_row)

            if min_road > min_wire + 1:
                nx = min_road - 1
                if in_bounds(nx, csy) and bool(em[csy, nx]) and not bool(pm[csy, nx]):
                    return (Tool.ROAD, nx, csy)
            if max_road < max_wire - 1:
                nx = max_road + 1
                if in_bounds(nx, csy) and bool(em[csy, nx]) and not bool(pm[csy, nx]):
                    return (Tool.ROAD, nx, csy)

    # --- PHASE 5: Place zones near roads and power ---
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Priority: close to multiple spine columns
        spine_dists = np.minimum(
            np.minimum(np.abs(cxs - 30), np.abs(cxs - 60)),
            np.abs(cxs - 90)
        )
        # Also consider vertical distance from backbone rows
        back_dists = np.minimum(
            np.minimum(np.abs(cys - 50), np.abs(cys - 25)),
            np.abs(cys - 75)
        )
        priority = spine_dists + back_dists // 2
        order = np.argsort(priority)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- PHASE 6: Services based on population ---
    service_placed = state.get('services', set())

    if pop > 300:
        svc_spots = [(28, 45), (32, 45), (58, 45), (62, 45), (88, 45), (92, 45)]
        for sx, sy in svc_spots:
            key = f'fire_{sx}_{sy}'
            if key not in service_placed and in_bounds(sx, sy) and bool(em[sy, sx]):
                state.setdefault('services', set()).add(key)
                return (Tool.FIRESTATION, sx, sy)

    if pop > 800:
        pol_spots = [(28, 55), (32, 55), (58, 55), (62, 55), (88, 55), (92, 55)]
        for sx, sy in pol_spots:
            key = f'police_{sx}_{sy}'
            if key not in service_placed and in_bounds(sx, sy) and bool(em[sy, sx]):
                state.setdefault('services', set()).add(key)
                return (Tool.POLICESTATION, sx, sy)

    if pop > 2000:
        stad_spots = [(45, 50), (75, 50), (45, 25), (75, 25)]
        for sx, sy in stad_spots:
            key = f'stad_{sx}_{sy}'
            if key not in service_placed and in_bounds(sx, sy) and bool(em[sy, sx]):
                state.setdefault('services', set()).add(key)
                return (Tool.STADIUM, sx, sy)

    # --- PHASE 7: Extend wire network to uncovered areas ---
    # Find wire frontier and expand
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    # Only extend if it brings wire closer to unserved zones
                    return (Tool.WIRE, nx3, ny3)

    # --- PHASE 8: Extend roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 20)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a grid with wire spines and flanking roads."""
    actions = []
    # Six plants: 3 columns x 2 rows
    for px in [20, 60, 100]:
        for py in [35, 65]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertically
            for dy in range(-6, 7):
                actions.append((Tool.WIRE, px, py + dy))
            # Roads flanking wire
            for dy in range(-6, 7):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% residential, 30% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 neighborhoods in a 3x2 grid covering the whole map
    # Each has its own wire col and flanking roads
    anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [35, 65]:
            wc = col_x
            rl = col_x - 1
            rr = col_x + 1
            anchors.append((col_x, row_y, wc, rl, rr))

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 350:   return 3
        if pop < 600:   return 4
        if pop < 1000:  return 5
        return 6

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        has_plant = False
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) ----
    spine_half = min(28, 8 + pop // 15)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    if n_active >= 3:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels (above and below) ----
    if pop > 30:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            for horiz_y in [yl - 3, yl + 3]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # Also add cross-roads connecting the two rows
    if pop > 80 and len(y_levels) >= 2:
        for col_x in [20, 60, 100]:
            y1 = min(y_levels)
            y2 = max(y_levels)
            # Road at col_x-2 connecting y rows
            for rx in [col_x - 3, col_x + 3]:
                if not ib(rx, y1) or not ib(rx, y2):
                    continue
                for cy in range(y1, y2 + 1):
                    if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                        return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (8, 20), (40, 20), (80, 20), (112, 20),
            (8, 50), (40, 50), (80, 50), (112, 50),
            (8, 80), (40, 80), (80, 80), (112, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 45), (55, 45), (85, 45), (115, 45),
            (25, 75), (55, 75), (85, 75), (115, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 90), (50, 90), (90, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

