            # Wire cross from each plant
            for d in range(-8, 9):
                actions.append((Tool.WIRE, px + d, py))
                actions.append((Tool.WIRE, px, py + d))
            # Flanking roads on both sides of wire
            for d in range(-7, 8):
                actions.append((Tool.ROAD, px - 1, py + d))
                actions.append((Tool.ROAD, px + 1, py + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 50% res, 30% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Full 5x5 grid of anchors covering the map
    all_anchors = []
    for col_x in [12, 32, 60, 88, 108]:
        for row_y in [15, 35, 55, 75, 90]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 500:   return 8
        if pop < 750:   return 10
        if pop < 1000:  return 12
        if pop < 1500:  return 16
        if pop < 2500:  return 20
        return len(all_anchors)

    n_active = num_active()
    # Spread active anchors across map by stepping through all_anchors
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS near each anchor ----
    for (ax, ay) in active_anchors:
        x0 = max(0, ax - 8); x1 = min(WORLD_W, ax + 9)
        y0 = max(0, ay - 8); y1 = min(WORLD_H, ay + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Try to place plant at anchor or nearby
        if ib(ax, ay) and bool(em[ay, ax]):
            return (Tool.COALPOWER, ax, ay)
        for r in range(1, 14):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = ax + dx, ay + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE CROSS FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    spine_reach = min(35, 8 + pop // 15)
    if len(plant_xs) > 0:
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - ax) <= 12 and abs(py2 - ay) <= 12
                             for ax, ay in active_anchors)
            if not in_cluster:
                continue
            # Horizontal wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            # Vertical wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH HORIZONTAL WIRE ----
    active_cols_set = sorted(set(ax for ax, ay in active_anchors))
    active_rows_set = sorted(set(ay for ax, ay in active_anchors))

    for ay in active_rows_set:
        row_anchors = sorted([ax for ax, acy in active_anchors if abs(acy - ay) <= 12])
        for i in range(len(row_anchors) - 1):
            c1, c2 = row_anchors[i], row_anchors[i + 1]
            for x in range(c1, c2 + 1):
                if ib(x, ay) and bool(em[ay, x]) and not bool(pm[ay, x]) and not bool(wm[ay, x]):
                    return (Tool.WIRE, x, ay)

    # ---- CONNECT CLUSTERS WITH VERTICAL WIRE ----
    for ax in active_cols_set:
        col_rows = sorted([ay for cax, ay in active_anchors if abs(cax - ax) <= 12])
        for i in range(len(col_rows) - 1):
            r1, r2 = col_rows[i], col_rows[i + 1]
            for y in range(r1, r2 + 1):
                if ib(ax, y) and bool(em[y, ax]) and not bool(pm[y, ax]) and not bool(wm[y, ax]):
                    return (Tool.WIRE, ax, y)

    # ---- BUILD ROAD GRID: flanking roads along wire spines ----
    road_reach = min(30, 8 + pop // 30)
    for ax, ay in active_anchors:
        # Horizontal roads above and below center
        for road_y in [ay - 2, ay + 2]:
            if not (0 <= road_y < WORLD_H): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = ax + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)
        # Vertical roads left and right of center
        for road_x in [ax - 2, ax + 2]:
            if not (0 <= road_x < WORLD_W): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, ay + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER HORIZONTAL ROADS ----
    if pop > 50:
        for ay in active_rows_set:
            row_anchors2 = sorted([ax for ax, acy in active_anchors if abs(acy - ay) <= 12])
            for i in range(len(row_anchors2) - 1):
                c1, c2 = row_anchors2[i], row_anchors2[i + 1]
                for road_y in [ay - 4, ay + 4]:
                    if not (0 <= road_y < WORLD_H): continue
                    for x in range(c1, c2 + 1):
                        if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                            return (Tool.ROAD, x, road_y)

    # ---- INTER-CLUSTER VERTICAL ROADS ----
    if pop > 80:
        for ax in active_cols_set:
            col_rows2 = sorted([ay for cax, ay in active_anchors if abs(cax - ax) <= 12])
            for i in range(len(col_rows2) - 1):
                r1, r2 = col_rows2[i], col_rows2[i + 1]
                for road_x in [ax - 4, ax + 4]:
                    if not (0 <= road_x < WORLD_W): continue
                    for y in range(r1, r2 + 1):
                        if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                            return (Tool.ROAD, road_x, y)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            for dx in range(-radius, radius + 1):
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 7)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for ax, ay in active_anchors:
            d = np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float) * 0.9
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 10), (35, 10), (65, 10), (95, 10), (115, 10),
            (8, 30), (35, 30), (65, 30), (95, 30), (115, 30),
            (8, 50), (35, 50), (65, 50), (95, 50), (115, 50),
            (8, 70), (35, 70), (65, 70), (95, 70), (115, 70),
            (8, 90), (35, 90), (65, 90), (95, 90), (115, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (12, 20), (45, 20), (75, 20), (108, 20),
            (12, 45), (45, 45), (75, 45), (108, 45),
            (12, 68), (45, 68), (75, 68), (108, 68),
            (12, 88), (45, 88), (75, 88), (108, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 6), (55, 6), (100, 6),
            (10, 93), (55, 93), (100, 93),
            (5, 45), (115, 45), (5, 65), (115, 65),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        airport_spots = [(55, 6), (5, 50), (115, 50), (55, 94), (30, 6), (90, 6), (30, 94), (90, 94)]
        for ax, ay in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        seaport_spots = [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5), (60, 3)]
        for sx2, sy2 in seaport_spots:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and seed roads"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
