def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Define plant hubs based on population ---
    # Start with center, expand outward as city grows
    base_plants = [(60, 50)]
    extra_plants = []
    if pop > 100 or step > 80:
        extra_plants += [(30, 50), (90, 50)]
    if pop > 300 or step > 200:
        extra_plants += [(60, 25), (60, 75)]
    if pop > 600 or step > 350:
        extra_plants += [(30, 25), (90, 25), (30, 75), (90, 75)]
    if pop > 1000:
        extra_plants += [(15, 50), (105, 50)]
    if pop > 1500:
        extra_plants += [(45, 12), (75, 12), (45, 87), (75, 87)]
    if pop > 2500:
        extra_plants += [(15, 25), (105, 25), (15, 75), (105, 75)]

    all_plants = base_plants + extra_plants

    # --- Ensure each plant exists ---
    for px, py in all_plants:
        found = any(
            ib(px+dx, py+dy) and bool(pm[py+dy, px+dx])
            for dy in range(-4, 5) for dx in range(-4, 5)
        )
        if not found and ib(px, py) and not bool(pm[py, px]):
            return (Tool.COALPOWER, px, py)

    # --- Wire network: vertical spines from each plant hub ---
    for px, py in all_plants:
        extent = min(40, 12 + pop // 80 + step // 30)
        spine_top = max(3, py - extent)
        spine_bot = min(WORLD_H - 4, py + extent)
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if col_wires:
            mn, mx = min(col_wires), max(col_wires)
            if mx < spine_bot:
                ny = mx + 1
                if ib(px, ny) and bool(em[ny, px]):
                    return (Tool.WIRE, px, ny)
            if mn > spine_top:
                ny = mn - 1
                if ib(px, ny) and bool(em[ny, px]):
                    return (Tool.WIRE, px, ny)

    # --- Horizontal wire connections between plants ---
    # Connect pairs of plants at same y-level
    plant_ys_set = set(py for _, py in all_plants)
    for target_y in plant_ys_set:
        row_plants_x = sorted([px for px, py in all_plants if py == target_y])
        if len(row_plants_x) >= 2:
            for i in range(len(row_plants_x) - 1):
                x1, x2 = row_plants_x[i], row_plants_x[i+1]
                for x in range(x1+1, x2):
                    if ib(x, target_y) and bool(em[target_y, x]) and not bool(pm[target_y, x]):
                        if (bool(wm[target_y, x-1]) or bool(pm[target_y, x-1])):
                            return (Tool.WIRE, x, target_y)

    # --- Horizontal cross-wires at intermediate rows ---
    # Pick rows between plant rows to bridge power coverage
    cross_rows = []
    sorted_py = sorted(set(py for _, py in all_plants))
    for i in range(len(sorted_py)-1):
        mid = (sorted_py[i] + sorted_py[i+1]) // 2
        cross_rows.append(mid)
    # Also add main horizontal at each plant y
    cross_rows += sorted_py

    for cr in cross_rows:
        if not ib(0, cr):
            continue
        row_wire = wm[cr, :] | pm[cr, :]
        for x in range(1, WORLD_W - 1):
            if bool(em[cr, x]) and not bool(pm[cr, x]):
                if (bool(row_wire[x-1]) or (x+1 < WORLD_W and bool(row_wire[x+1]))):
                    return (Tool.WIRE, x, cr)

    # --- Road network: vertical roads flanking wire spines ---
    for px, py in all_plants:
        col_wires = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not col_wires:
            continue
        mn_w, mx_w = min(col_wires), max(col_wires)
        for roff in [-1, 1]:
            rc = px + roff
            if not ib(rc, py):
                continue
            for wr in range(mn_w, mx_w + 1):
                if ib(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                    return (Tool.ROAD, rc, wr)

    # --- Horizontal roads flanking cross-wire rows ---
    h_road_offsets = [-1, 1]
    for cr in cross_rows:
        for roff in h_road_offsets:
            hr = cr + roff
            if not ib(0, hr):
                continue
            wire_adj = (hr > 0 and (wm[hr-1, :] | pm[hr-1, :]).any()) or \
                       (hr < WORLD_H-1 and (wm[hr+1, :] | pm[hr+1, :]).any())
            if wire_adj:
                for x in range(3, WORLD_W - 3):
                    if ib(x, hr) and bool(em[hr, x]) and not bool(pm[hr, x]):
                        return (Tool.ROAD, x, hr)

    # --- Proximity masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones near roads and power ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score: prefer close to any plant hub
        min_dist = np.full(len(cxs_arr), 999999.0)
        for px, py in all_plants:
            d = np.abs(cxs_arr - px).astype(float) + np.abs(cys_arr - py).astype(float)
            min_dist = np.minimum(min_dist, d)
        order = np.argsort(min_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # --- Services ---
    if pop > 80:
        fire_spots = []
        for px, py in all_plants:
            fire_spots += [(px-8, py-8), (px+8, py-8), (px-8, py+8), (px+8, py+8)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 250:
        police_spots = []
        for px, py in all_plants:
            police_spots += [(px-12, py), (px+12, py), (px, py-12), (px, py+12)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        for stx, sty in [(45, 35), (75, 35), (45, 65), (75, 65), (20, 50), (100, 50)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        for apx, apy in [(55, 15), (55, 85), (15, 30), (105, 30)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        for spx, spy in [(10, 50), (110, 50), (60, 5), (60, 94)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire ---
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at strategic positions with wire and roads."""
    actions = []
    # Plant at center-left, center-right, top-center, bottom-center
    plants = [(30, 50), (90, 50), (60, 25), (60, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Wire spine horizontally
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
        # Roads flanking wire vertically
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 55% res, 25% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 4x3 grid of neighborhoods covering the map better
    # Columns at x=15,45,75,105; rows at y=20,50,80
    all_anchors = []
    for col_x in [15, 45, 75, 105]:
        for row_y in [20, 50, 80]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 500:   return 8
        if pop < 800:   return 10
        if pop < 1200:  return 12
        return 12

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find closest empty spot to place plant
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: build cross-shaped wire from each plant ----
    # First find actual plant positions
    plant_ys, plant_xs = np.where(pm)

    # Build wire spines from each plant
    spine_reach = min(40, 15 + pop // 8)
    for pi in range(len(plant_xs)):
        px, py = int(plant_xs[pi]), int(plant_ys[pi])
        # Vertical wire
        for dy in range(-spine_reach, spine_reach + 1):
            ny = py + dy
            if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                return (Tool.WIRE, px, ny)
        # Horizontal wire
        for dx in range(-spine_reach, spine_reach + 1):
            nx = px + dx
            if ib(nx, py) and bool(em[py, nx]) and not bool(pm[py, nx]):
                return (Tool.WIRE, nx, py)

    # ---- CONNECT WIRE BETWEEN PLANTS (horizontal and vertical) ----
    # Find gaps in wire between anchor columns/rows
    active_xs = sorted(set(px for px, py in active_anchors))
    active_ys = sorted(set(py for px, py in active_anchors))

    # Connect horizontally at each row level
    for yl in active_ys:
        for i in range(len(active_xs) - 1):
            x1, x2 = active_xs[i], active_xs[i+1]
            # Check if wire exists between them
            wire_row = wm[yl, x1:x2+1]
            plant_row = pm[yl, x1:x2+1]
            combined = wire_row | plant_row
            if not np.all(combined):
                # Fill gaps
                for cx in range(x1, x2+1):
                    if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                        return (Tool.WIRE, cx, yl)

    # Connect vertically at each column
    for xl in active_xs:
        for i in range(len(active_ys) - 1):
            y1, y2 = active_ys[i], active_ys[i+1]
            wire_col = wm[y1:y2+1, xl]
            plant_col = pm[y1:y2+1, xl]
            combined = wire_col | plant_col
            if not np.all(combined):
                for cy in range(y1, y2+1):
                    if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                        return (Tool.WIRE, xl, cy)

    # ---- ROAD NETWORK: flanking roads along wire spines ----
    # Roads parallel to vertical wire spines (left and right of each anchor column)
    for xl in active_xs:
        for road_off in [-2, 2]:
            rx = xl + road_off
            if not ib(rx, 0):
                continue
            for yl in active_ys:
                road_top = max(2, yl - spine_reach)
                road_bot = min(WORLD_H - 3, yl + spine_reach)
                for ry in range(road_top, road_bot + 1):
                    if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # Roads parallel to horizontal wire spines (above and below each anchor row)
    for yl in active_ys:
        for road_off in [-2, 2]:
            ry = yl + road_off
            if not ib(0, ry):
                continue
            for xl in active_xs:
                road_left = max(2, xl - spine_reach)
                road_right = min(WORLD_W - 3, xl + spine_reach)
                for rx in range(road_left, road_right + 1):
                    if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # ---- CROSS ROADS connecting row levels ----
    if pop > 40:
        for xl in active_xs:
            for road_off in [-2, 2]:
                rx = xl + road_off
                for i in range(len(active_ys) - 1):
                    y1, y2 = active_ys[i], active_ys[i+1]
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    # Road proximity (zones need road within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/plant proximity (zones need power within 6 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        # Check 3x3 area centered at (zx,zy) is empty or already zoned
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: reactive to current road/wire coverage ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active anchors
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Also prefer spots near existing zones (clustering)
        zone_density = np.zeros((WORLD_H, WORLD_W), dtype=float)
        zone_ys_tmp, zone_xs_tmp = np.where(zone_tiles)
        for i in range(len(zone_xs_tmp)):
            zx2, zy2 = int(zone_xs_tmp[i]), int(zone_ys_tmp[i])
            y0 = max(0, zy2 - 5); y1 = min(WORLD_H, zy2 + 6)
            x0 = max(0, zx2 - 5); x1 = min(WORLD_W, zx2 + 6)
            zone_density[y0:y1, x0:x1] += 1.0

        density_at_cands = zone_density[cys, cxs]
        # Blend: close to anchor but also near existing zones
        score = best_dist - density_at_cands * 0.5
        order = np.argsort(score)

        # Use step offset for variety
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES based on current population ----
    if pop > 60:
        fire_spots = [
            (8, 12), (38, 12), (68, 12), (98, 12),
            (8, 35), (38, 35), (68, 35), (98, 35),
            (8, 58), (38, 58), (68, 58), (98, 58),
            (8, 82), (38, 82), (68, 82), (98, 82),
            (23, 20), (53, 20), (83, 20), (113, 20),
            (23, 65), (53, 65), (83, 65), (113, 65),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (12, 30), (42, 30), (72, 30), (102, 30),
            (12, 55), (42, 55), (72, 55), (102, 55),
            (12, 80), (42, 80), (72, 80), (102, 80),
            (27, 15), (57, 15), (87, 15), (117, 15),
            (27, 70), (57, 70), (87, 70), (117, 70),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 10), (60, 10), (110, 10),
            (10, 50), (110, 50),
            (10, 90), (60, 90), (110, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 48), (115, 48), (55, 93), (25, 5), (95, 5)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 92), (115, 92), (58, 96), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3),
                                  (4, 0), (-4, 0), (0, 4), (0, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: add road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder
# Strategy: 4 coal plants forming a spine, dense wire grid, balanced R/C/I zoning
# Multiple neighborhoods expanding outward from center, civic services early

def init(obs, state):
    """Bootstrap: 4 coal plants + wire connections + initial roads"""
    actions = []
    # Place 4 coal plants in a cross pattern
    plants = [(30, 30), (90, 30), (30, 70), (90, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire from each plant toward center (60,50)
    for px, py in plants:
        cx, cy = 60, 50
        # horizontal wire segment
        step_x = 1 if cx > px else -1
        for x in range(px + step_x, cx, step_x):
            actions.append((Tool.WIRE, x, py))
        # vertical wire segment
        step_y = 1 if cy > py else -1
        for y in range(py, cy + step_y, step_y):
            actions.append((Tool.WIRE, cx, y))
    # Initial roads near center
    for x in range(55, 66):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    for y in range(45, 56):
        actions.append((Tool.ROAD, 54, y))
        actions.append((Tool.ROAD, 66, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- ZONE COUNTS ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD DEFINITIONS ----
    # 16 neighborhoods arranged in a 4x4 grid covering the map
    # Each hood has a coal plant, wire grid, road grid, and zones
    nh_positions = []
    for row in range(4):
        for col in range(4):
            cx = 15 + col * 30  # 15, 45, 75, 105
            cy = 15 + row * 25  # 15, 40, 65, 90
            nh_positions.append((cx, cy))

    # Progressive unlock: start with center hoods, expand outward
    def get_active_hoods():
        if pop < 50:
            return nh_positions[5:7] + nh_positions[9:11]  # center 4
        elif pop < 200:
            return nh_positions[4:8] + nh_positions[8:12]  # middle 8
        elif pop < 500:
            return nh_positions[1:15]  # 14
        else:
            return nh_positions  # all 16

    active_hoods = get_active_hoods()

    # ---- HELPER: is area clear for 3x3 zone ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant near hood center
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD WIRE NETWORK ----
    # For each active hood, build a cross wire pattern
    # Also connect hoods via wire corridors

    # Build wire corridors along major axes
    # Horizontal corridors at y=15, 40, 65, 90
    # Vertical corridors at x=15, 45, 75, 105
    wire_rows = [15, 40, 65, 90]
    wire_cols = [15, 45, 75, 105]

    # Step-based round-robin for wire building
    wire_phase = step % 4

    if wire_phase == 0:
        # Build horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if ib(wx, wr) and not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    # Check adjacency to existing wire/plant
                    adj = False
                    for adx in [-1, 1]:
                        ax = wx + adx
                        if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                            adj = True
                            break
                    if adj and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif wire_phase == 1:
        # Build vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if ib(wc, wy) and not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    adj = False
                    for ady in [-1, 1]:
                        ay = wy + ady
                        if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                            adj = True
                            break
                    if adj and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif wire_phase == 2:
        # Extend wire spurs from corridors to uncovered hoods
        for (hx, hy) in active_hoods:
            if not bool(wm[hy, hx]) and not bool(pm[hy, hx]):
                # Try to connect to nearest wire
                best = None
                best_d = 999
                for wy_r in range(max(0, hy - 15), min(WORLD_H, hy + 16)):
                    for wy_c in range(max(0, hx - 15), min(WORLD_W, hx + 16)):
                        if bool(wm[wy_r, wy_c]) or bool(pm[wy_r, wy_c]):
                            d = abs(wy_r - hy) + abs(wy_c - hx)
                            if d < best_d:
                                best_d = d
                                best = (wy_c, wy_r)
                if best is not None:
                    bx, by = best
                    # Move one step toward best
                    dx = 0 if bx == hx else (1 if bx > hx else -1)
                    dy = 0 if by == hy else (1 if by > hy else -1)
                    # Prefer horizontal first
                    nx, ny = hx - dx, hy - dy  # step FROM hood TOWARD wire
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    else:
        # Fill wire gaps - connect disconnected wire segments
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            k = (step * 7) % len(wire_xs)
            for i in range(min(len(wire_xs), 30)):
                idx = (k + i) % len(wire_xs)
                wx2, wy2 = int(wire_xs[idx]), int(wire_ys[idx])
                for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx2, ny2 = wx2 + dx2, wy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        # Only extend if it leads toward an unconnected area
                        nx3, ny3 = nx2 + dx2, ny2 + dy2
                        if ib(nx3, ny3) and (bool(wm[ny3, nx3]) or bool(pm[ny3, nx3])):
                            return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 3: ROAD NETWORK ----
    # Roads at corridors +/-1 from wire corridors, plus cross streets every ~6 tiles
    road_phase = step % 3

    if road_phase == 0:
        # Roads parallel to wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not ib(0, ry):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Only if wire exists at wr,rx
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    elif road_phase == 1:
        # Roads parallel to wire columns
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not ib(rcx, 0):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if ib(rcx, ry) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    else:
        # Cross streets connecting road corridors
        # Every 6 tiles between wire columns, add a cross road
        for col_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[col_idx], wire_cols[col_idx + 1]
            for mid_x in range(c1 + 6, c2, 6):
                if not ib(mid_x, 0):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                        # Connect if near a wire row road
                        for wr in wire_rows:
                            if abs(ry - wr) <= 1:
                                break
                        else:
                            # extend road if adjacent to existing road
                            adj_road = False
                            for ady in [-1, 1]:
                                ay = ry + ady
                                if ib(mid_x, ay) and bool(rm[ay, mid_x]):
                                    adj_road = True
                                    break
                            if adj_road:
                                return (Tool.ROAD, mid_x, ry)

    # ---- PHASE 4: ZONE PLACEMENT ----
    # Balanced: 40% RES, 30% COM, 30% IND
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hood centers
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES - place early and often ----
    if pop > 100:
        fire_grid = [
            (20, 15), (60, 15), (100, 15),
            (20, 40), (60, 40), (100, 40),
            (20, 65), (60, 65), (100, 65),
            (20, 90), (60, 90), (100, 90),
        ]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_grid = [
            (35, 25), (75, 25),
            (15, 52), (55, 52), (95, 52),
            (35, 78), (75, 78),
        ]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(45, 50), (75, 50), (45, 25), (75, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(55, 5), (65, 5), (55, 95), (65, 95)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend road network ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant for uncovered hoods ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: compact powered cluster with roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross through center
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads in a grid around center
    for x in range(40, 81):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 40, y))
        actions.append((Tool.ROAD, 80, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone tool selection: 40% RES, 35% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Power plant positions: dense grid across map
    # 5x4 grid of plants
    plant_positions = []
    for px in [15, 35, 60, 85, 105]:
        for py in [15, 35, 65, 85]:
            plant_positions.append((px, py))
    # Extra edge plants
    if pop > 100:
        for px in [15, 35, 60, 85, 105]:
            plant_positions += [(px, 50)]
        for py in [15, 35, 50, 65, 85]:
            plant_positions += [(5, py), (115, py)]

    # Place missing power plants
    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        # Check if plant exists nearby (within 6 tiles)
        found = False
        for dy in range(-6, 7):
            for dx in range(-6, 7):
                nx, ny = ppx+dx, ppy+dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, ppx, ppy)

    # Wire network: horizontal spines every 10 rows, vertical every 10 cols
    wire_rows = list(range(10, 95, 10))
    wire_cols = list(range(10, 115, 10))

    # Ensure horizontal wires span the map
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Start wire from center
            if ib(60, wr) and em[wr, 60]:
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left, right):
            if em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Ensure vertical wires span the map
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot):
            if em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # Road network: between wire rows/cols
    # Roads at rows offset from wires, and cols offset from wires
    road_rows = []
    road_cols = []
    for wr in wire_rows:
        road_rows.append(wr - 4)
        road_rows.append(wr + 4)
    for wc in wire_cols:
        road_cols.append(wc - 4)
        road_cols.append(wc + 4)
    road_rows = [r for r in road_rows if 2 < r < WORLD_H - 2]
    road_cols = [c for c in road_cols if 2 < c < WORLD_W - 2]

    # Build horizontal roads
    for rr in road_rows:
        row_road = rm[rr, :]
        if not row_road.any():
            # Seed at center
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and em[rr, left-1] and not pm[rr, left-1]:
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-3 and em[rr, right+1] and not pm[rr, right+1]:
            return (Tool.ROAD, right+1, rr)
        for x in range(left, right):
            if em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and em[top-1, rc] and not pm[top-1, rc]:
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-3 and em[bot+1, rc] and not pm[bot+1, rc]:
            return (Tool.ROAD, rc, bot+1)
        for y in range(top, bot):
            if em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # Zone placement: near roads and wires
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: cluster near existing zones, also near roads
        zone_score = np.zeros(len(cxs_arr))
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 150)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist
        else:
            # Near center initially
            zone_score = np.abs(cxs_arr - 60).astype(float) + np.abs(cys_arr - 50).astype(float)

        # Spread out as pop grows - use multiple centers
        if pop > 500:
            centers = [(20, 20), (100, 20), (20, 80), (100, 80), (60, 50)]
            min_center_dist = np.full(len(cxs_arr), 999999.0)
            for cx, cy in centers:
                d = np.abs(cxs_arr - cx).astype(float) + np.abs(cys_arr - cy).astype(float)
                min_center_dist = np.minimum(min_center_dist, d)
            zone_score = zone_score * 0.4 + min_center_dist * 0.6

        order = np.argsort(zone_score)
        # Use step+pop to vary placement slightly
        off = (step * 3 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # Civic services based on population
    if pop > 30:
        fire_spots = [(fx, fy) for fy in range(14, 96, 12) for fx in range(14, 111, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(18, 92, 18) for px2 in range(18, 108, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(20, 88, 14) for pkx in range(22, 105, 18)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 500:
        stadium_spots = [
            (40, 30), (80, 30), (40, 70), (80, 70),
            (20, 50), (100, 50), (60, 20), (60, 80),
            (20, 30), (100, 30), (20, 70), (100, 70),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        airport_spots = [
            (55, 8), (65, 8), (55, 92), (65, 92),
            (8, 45), (112, 45), (8, 55), (112, 55),
            (30, 8), (90, 8), (30, 92), (90, 92),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1200:
        seaport_spots = [
            (8, 50), (112, 50), (60, 5), (60, 95),
            (25, 5), (95, 5), (25, 95), (95, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: add more wires near plants
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 40)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend roads near wires
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 60)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0,3),(0,-3),(3,0),(-3,0),(0,5),(0,-5),(5,0),(-5,0)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: multiple power plants with wire and road seeds across the map."""
    actions = []
    # Place 4 coal power plants in a cross pattern
    plants = [(30, 25), (90, 25), (30, 75), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for d in range(1, 8):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px - d, py))
            actions.append((Tool.WIRE, px, py + d))
            actions.append((Tool.WIRE, px, py - d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More aggressive zone mix: 35% res, 40% com, 25% ind (more commercial)
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.40:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # 6 clusters arranged in 2 rows x 3 cols, plus center cluster
    # Scale active clusters aggressively
    all_clusters = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]

    def active_clusters():
        if pop < 50:    return [(30, 25), (90, 25)]
        if pop < 200:   return [(30, 25), (90, 25), (30, 75), (90, 75)]
        if pop < 600:   return [(20, 20), (60, 20), (100, 20),
                                 (20, 50), (60, 50), (100, 50)]
        if pop < 1500:  return [(20, 20), (60, 20), (100, 20),
                                 (20, 50), (60, 50), (100, 50),
                                 (20, 80), (60, 80), (100, 80)]
        return all_clusters

    clusters = active_clusters()

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(15):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE GRID ----
    # Wire from each plant outward in + pattern
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(20, 6 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- WIRE HORIZONTAL CONNECTIONS BETWEEN CLUSTERS ----
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        row_clusters = sorted([cx for cx, c_cy in clusters if c_cy == cy])
        for i in range(len(row_clusters) - 1):
            c1, c2 = row_clusters[i], row_clusters[i + 1]
            for x in range(c1, c2 + 1):
                if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]) and not bool(wm[cy, x]):
                    return (Tool.WIRE, x, cy)

    # ---- WIRE VERTICAL CONNECTIONS BETWEEN CLUSTER ROWS ----
    for cx in active_cols_set:
        col_clusters = sorted([cy for c_cx, cy in clusters if c_cx == cx])
        for i in range(len(col_clusters) - 1):
            r1, r2 = col_clusters[i], col_clusters[i + 1]
            for y in range(r1, r2 + 1):
                if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]) and not bool(wm[y, cx]):
                    return (Tool.WIRE, cx, y)

    # ---- BUILD DENSE ROAD GRID AROUND EACH CLUSTER ----
    # Use multiple parallel roads at offsets for denser coverage
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        # Multiple horizontal road offsets: ±2, ±5, ±8
        for road_dy in [-5, -2, 2, 5]:
            road_y = cy + road_dy
            if not ib(cx, road_y): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)
        # Multiple vertical road offsets: ±2, ±5, ±8
        for road_dx in [-5, -2, 2, 5]:
            road_x = cx + road_dx
            if not ib(road_x, cy): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    if pop > 100:
        for cy in active_rows_set:
            row_clusters2 = sorted([cx for cx, c_cy in clusters if c_cy == cy])
            for i in range(len(row_clusters2) - 1):
                c1, c2 = row_clusters2[i], row_clusters2[i + 1]
                for road_dy in [-3, 3]:
                    road_y = cy + road_dy
                    if not (0 <= road_y < WORLD_H): continue
                    for x in range(c1, c2 + 1):
                        if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                            if not bool(rm[road_y, x]):
                                return (Tool.ROAD, x, road_y)
        for cx in active_cols_set:
            col_clusters2 = sorted([cy for c_cx, cy in clusters if c_cx == cx])
            for i in range(len(col_clusters2) - 1):
                r1, r2 = col_clusters2[i], col_clusters2[i + 1]
                for road_dx in [-3, 3]:
                    road_x = cx + road_dx
                    if not (0 <= road_x < WORLD_W): continue
                    for y in range(r1, r2 + 1):
                        if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                            if not bool(rm[y, road_x]):
                                return (Tool.ROAD, road_x, y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES (scaled with pop) ----
    if pop > 40:
        fire_spots = [(fx, fy) for fy in range(10, 95, 18) for fx in range(10, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px, py) for py in range(12, 90, 16) for px in range(12, 112, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(30, 8), (70, 8), (110, 8),
                         (30, 92), (70, 92), (110, 92),
                         (8, 35), (8, 65)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Nuclear upgrades for large city
        nuke_spots = [(5, 15), (5, 50), (5, 85),
                      (115, 15), (115, 50), (115, 85),
                      (40, 5), (80, 5), (40, 94), (80, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94), (10, 5), (110, 5)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 90), (115, 90), (5, 10), (115, 10), (60, 5), (60, 94)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 60)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4),
                                  (6, 0), (-6, 0), (0, 6), (0, -6)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

def init(obs, state):
