    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target: 45% res, 35% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 5 neighborhoods: 4 corners + center
    # Each has: plant center (px,py), wire col (wc), left road (rl), right road (rr)
    all_anchors = [
        (20, 20),
        (100, 20),
        (20, 80),
        (100, 80),
        (60, 50),
    ]

    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 3
        if pop < 600:   return 4
        return 5

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        for r in range(0, 15):
            found = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if found:
                break

    # ---- WIRE GRID: connect plants with horizontal + vertical wires ----
    # Build cross-wires between anchor rows and columns
    # Horizontal wires at y-levels
    y_set = sorted(set(py for (_, py) in active_anchors))
    x_set = sorted(set(px for (px, _) in active_anchors))

    # Connect horizontally at each y-level
    for yl in y_set:
        row_xs = sorted([px for (px, py) in active_anchors if py == yl])
        if len(row_xs) < 2:
            continue
        for i in range(len(row_xs) - 1):
            x1c, x2c = row_xs[i], row_xs[i + 1]
            for cx in range(x1c + 1, x2c):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # Connect vertically at each x-level
    for xl in x_set:
        col_ys = sorted([py for (px, py) in active_anchors if px == xl])
        if len(col_ys) < 2:
            continue
        for i in range(len(col_ys) - 1):
            y1c, y2c = col_ys[i], col_ys[i + 1]
            for cy in range(y1c + 1, y2c):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- WIRE SPINES radiating from each anchor ----
    spine_half = min(35, 8 + pop // 8)
    for (px, py) in active_anchors:
        for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            dx, dy = direction
            # Extend spine in this direction
            wire_count = 0
            for step_d in range(1, spine_half):
                nx, ny = px + dx * step_d, py + dy * step_d
                if not ib(nx, ny):
                    break
                if bool(pm[ny, nx]):
                    break
                if bool(wm[ny, nx]):
                    wire_count += 1
                    continue
                if bool(em[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- BUILD ROAD GRID around each anchor ----
    # Roads at offsets ±2 and ±4 from each anchor in both axes
    road_offsets = [-4, -2, 2, 4]
    for (px, py) in active_anchors:
        for off in road_offsets:
            # Horizontal roads (y offset, varying x)
            ry = py + off
            if not ib(px, ry):
                continue
            for cx in range(max(2, px - spine_half), min(WORLD_W - 2, px + spine_half)):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    return (Tool.ROAD, cx, ry)
            # Vertical roads (x offset, varying y)
            rx = px + off
            if not ib(rx, py):
                continue
            for cy in range(max(2, py - spine_half), min(WORLD_H - 2, py + spine_half)):
                if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                    return (Tool.ROAD, rx, cy)

    # ---- INTER-NEIGHBORHOOD ROADS ----
    if pop > 80:
        # Connect anchors with roads at midpoints
        anchor_pairs = []
        for i in range(len(active_anchors)):
            for j in range(i + 1, len(active_anchors)):
                anchor_pairs.append((active_anchors[i], active_anchors[j]))
        for ((x1a, y1a), (x2a, y2a)) in anchor_pairs:
            dist = abs(x1a - x2a) + abs(y1a - y2a)
            if dist > 60:
                continue
            # Horizontal segment at y1a
            for cx in range(min(x1a, x2a), max(x1a, x2a)):
                road_y = (y1a + y2a) // 2
                if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    return (Tool.ROAD, cx, road_y)
            # Vertical segment at x2a
            for cy in range(min(y1a, y2a), max(y1a, y2a)):
                road_x = (x1a + x2a) // 2
                if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [
            (10, 10), (35, 10), (65, 10), (95, 10), (115, 10),
            (10, 35), (35, 35), (65, 35), (95, 35), (115, 35),
            (10, 60), (35, 60), (65, 60), (95, 60), (115, 60),
            (10, 85), (35, 85), (65, 85), (95, 85), (115, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 25), (50, 25), (80, 25), (110, 25),
            (15, 55), (50, 55), (80, 55), (110, 55),
            (15, 80), (50, 80), (80, 80), (110, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (12, 12), (60, 12), (108, 12),
            (12, 90), (60, 90), (108, 90),
            (12, 50), (108, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [
            (7, 7), (113, 7), (7, 93), (113, 93),
            (60, 7), (60, 93), (7, 50), (113, 50),
            (35, 50), (85, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1800:
        for asp in [(55, 7), (7, 50), (113, 50), (55, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(7, 93), (113, 93), (60, 97), (7, 7), (113, 7)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near zones ----
    if pop > 120:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Closed-loop city builder with high reactivity
# Strategy: dense grid of neighborhoods with proper power+road infrastructure
# Each step reads tile_map and places the most needed item

def init(obs, state):
    """Bootstrap: place central coal plant + initial wires and roads."""
    actions = []
    # Central power plant
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from plant
    for d in range(1, 6):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Roads flanking wire spines
    for d in range(-4, 5):
        actions.append((Tool.ROAD, cx - 1, cy + d))
        actions.append((Tool.ROAD, cx + 1, cy + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD DEFINITIONS ----
    # Dense grid: 6 cols x 5 rows = 30 neighborhoods
    hood_cols = [12, 28, 44, 60, 76, 92, 108]
    hood_rows = [12, 28, 44, 60, 76, 92]
    all_hoods = [(c, r) for r in hood_rows for c in hood_cols]

    # Unlock more neighborhoods as population grows
    def n_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 9
        if pop < 2000:  return 12
        if pop < 3500:  return 16
        if pop < 5000:  return 20
        if pop < 8000:  return 25
        return len(all_hoods)

    na = n_active()
    # Spread active hoods evenly
    if na >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / na
        active_hoods = [all_hoods[int(i * step_size)] for i in range(na)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood needs a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at hood center or nearby empty spot
            for r in range(10):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = hx + dx2, hy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CONNECTIVITY ----
    # Build wire spines: vertical at hx, horizontal at hy for each hood
    # Connect plant to wire, extend wire spines

    plant_ys, plant_xs = np.where(pm)

    def nearest_plant(x, y):
        if len(plant_xs) == 0:
            return None
        dists = np.abs(plant_xs - x) + np.abs(plant_ys - y)
        k = np.argmin(dists)
        return int(plant_xs[k]), int(plant_ys[k])

    for (hx, hy) in active_hoods:
        # Vertical wire spine at column hx
        col_has_wire = bool(np.any(wm[:, hx]))
        col_has_plant = bool(np.any(pm[:, hx]))

        spine_top = max(2, hy - 14)
        spine_bot = min(WORLD_H - 3, hy + 14)
        spine_left = max(2, hx - 14)
        spine_right = min(WORLD_W - 3, hx + 14)

        # If no wire on this column, wire from the plant outward
        if col_has_plant and not col_has_wire:
            plant_rows = [r for r in range(WORLD_H) if bool(pm[r, hx])]
            if plant_rows:
                pr = plant_rows[0]
                for wy in [pr - 1, pr + 1, pr - 2, pr + 2]:
                    if ib(hx, wy) and bool(em[wy, hx]):
                        return (Tool.WIRE, hx, wy)

        if col_has_wire:
            # Extend vertical spine
            wire_rows = [r for r in range(WORLD_H) if bool(wm[r, hx])]
            if wire_rows:
                min_wr, max_wr = min(wire_rows), max(wire_rows)
                if max_wr < spine_bot:
                    nr = max_wr + 1
                    if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)
                if min_wr > spine_top:
                    nr = min_wr - 1
                    if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)

        # Horizontal wire spine at row hy
        row_has_wire = bool(np.any(wm[hy, :]))
        row_has_plant = bool(np.any(pm[hy, :]))

        if row_has_plant and not row_has_wire:
            plant_cols = [c for c in range(WORLD_W) if bool(pm[hy, c])]
            if plant_cols:
                pc = plant_cols[0]
                for wx in [pc - 1, pc + 1, pc - 2, pc + 2]:
                    if ib(wx, hy) and bool(em[hy, wx]):
                        return (Tool.WIRE, wx, hy)

        if row_has_wire:
            wire_cols = [c for c in range(WORLD_W) if bool(wm[hy, c])]
            if wire_cols:
                min_wc, max_wc = min(wire_cols), max(wire_cols)
                if max_wc < spine_right:
                    nc = max_wc + 1
                    if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)
                if min_wc > spine_left:
                    nc = min_wc - 1
                    if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    # Connect wire spines between adjacent hoods horizontally/vertically
    wire_ys_arr, wire_xs_arr = np.where(wm)

    # Connect hoods that are horizontally adjacent (same row, different col)
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods:
            if hx2 <= hx1 or abs(hy1 - hy2) > 8:
                continue
            mid_y = (hy1 + hy2) // 2
            # Check if already connected
            gap_filled = True
            for cx in range(hx1 + 1, hx2):
                if not (bool(wm[mid_y, cx]) or bool(pm[mid_y, cx])):
                    gap_filled = False
                    break
            if not gap_filled:
                for cx in range(hx1 + 1, hx2):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)

    # ---- PHASE 4: ROAD GRID ----
    # Roads flanking wire spines (at wire_col±1 and wire_row±1)
    # Build road coverage maps efficiently
    road_set = set(zip(wire_xs_arr.tolist(), wire_ys_arr.tolist()))

    for (hx, hy) in active_hoods:
        spine_top = max(2, hy - 14)
        spine_bot = min(WORLD_H - 3, hy + 14)
        spine_left = max(2, hx - 14)
        spine_right = min(WORLD_W - 3, hx + 14)

        # Vertical roads flanking wire column at hx
        wire_col_rows = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(wm[r, hx])]
        if wire_col_rows:
            # Stagger placement across steps
            for rx in [hx - 1, hx + 1]:
                if not ib(rx, hy):
                    continue
                # Use step modulo to spread work
                start_idx = (step * 3 + (1 if rx == hx + 1 else 0)) % max(len(wire_col_rows), 1)
                for di in range(min(3, len(wire_col_rows))):
                    ridx = (start_idx + di) % len(wire_col_rows)
                    wr = wire_col_rows[ridx]
                    if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                        return (Tool.ROAD, rx, wr)

        # Horizontal roads flanking wire row at hy
        wire_row_cols = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(wm[hy, c])]
        if wire_row_cols:
            for ry in [hy - 1, hy + 1]:
                if not ib(hx, ry):
                    continue
                start_idx = (step * 3 + (1 if ry == hy + 1 else 0)) % max(len(wire_row_cols), 1)
                for di in range(min(3, len(wire_row_cols))):
                    cidx = (start_idx + di) % len(wire_row_cols)
                    wc = wire_row_cols[cidx]
                    if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                        return (Tool.ROAD, wc, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        if total_zones < 3:
            return Tool.RESIDENTIAL
        i_r = ind_count / max(total_zones, 1)
        c_r = com_count / max(total_zones, 1)
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # Compute neighbor road coverage (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = r0 + (sr1 - sr0)
            c0 = max(0, dx2); c1 = c0 + (sc1 - sc0)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute neighbor power coverage (within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = r0 + (sr1 - sr0)
            c0 = max(0, dx2); c1 = c0 + (sc1 - sc0)
            if r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zones: empty, near road, near power, not at border
    cand_mask = em & nbr_road & nbr_power
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest active hood center
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- PHASE 6: ROAD EXTENSION from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 150:
        fire_grid = [(x, y) for x in range(20, WORLD_W - 10, 25) for y in range(20, WORLD_H - 10, 25)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_grid = [(x, y) for x in range(25, WORLD_W - 10, 30) for y in range(25, WORLD_H - 10, 30)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(35, 35), (85, 35), (35, 65), (85, 65), (60, 20), (60, 80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15), (60, 5), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for sx, sy in [(55, 8), (55, 88), (10, 50), (108, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: PARKS for land value ----
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- PHASE 9: WIRE EXTENSION FALLBACK ----
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- PHASE 10: PLACE EXTRA POWER PLANTS if needed ----
    # Place near active hoods that lack one
    if step % 20 == 0:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
            y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(5):
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = hx + dx2, hy + dy2
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a 2x3 grid with wire crosses and road flanks."""
    actions = []
    # Plant positions: 2 rows x 3 cols
    plant_positions = [(20, 30), (60, 30), (100, 30), (20, 65), (60, 65), (100, 65)]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross
        for d in range(-5, 6):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px, py + d))
        # Flanking roads
        for d in range(-4, 5):
            actions.append((Tool.ROAD, px - 2, py + d))
            actions.append((Tool.ROAD, px + 2, py + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- CLUSTER SYSTEM: scale with population ---
    # Full grid: 5 cols x 4 rows
    all_cols = [15, 35, 60, 85, 105]
    all_rows = [20, 40, 60, 80]

    def active_clusters():
        if pop < 60:
            return [(20, 30), (60, 30), (100, 30)]
        if pop < 150:
            return [(20, 30), (60, 30), (100, 30), (20, 65), (60, 65), (100, 65)]
        if pop < 400:
            return [(cx, cy) for cy in [30, 65] for cx in [15, 35, 60, 85, 105]]
        if pop < 900:
            return [(cx, cy) for cy in [20, 50, 80] for cx in [15, 35, 60, 85, 105]]
        # Full grid
        return [(cx, cy) for cy in all_rows for cx in all_cols]

    clusters = active_clusters()

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- 1. ENSURE POWER PLANTS FOR ACTIVE CLUSTERS ---
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 14), min(WORLD_W, cx + 15)
        py0, py1 = max(0, cy - 14), min(WORLD_H, cy + 15)
        if not np.any(pm[py0:py1, px0:px1]):
            for r in range(20):
                found = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if found:
                    break

    # --- 2. WIRE CROSS FROM EACH PLANT ---
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(28, 7 + pop // 20)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 16 and abs(py2 - cy) <= 16
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Horizontal wire arms
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            # Vertical wire arms
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # --- 3. CONNECT CLUSTERS WITH WIRE HORIZONTALLY ---
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        row_cls = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 16])
        for i in range(len(row_cls) - 1):
            c1, c2 = row_cls[i], row_cls[i + 1]
            gap_filled = all(
                bool(wm[cy, x]) or bool(pm[cy, x])
                for x in range(c1, c2 + 1) if ib(x, cy)
            )
            if not gap_filled:
                for x in range(c1, c2 + 1):
                    if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]):
                        return (Tool.WIRE, x, cy)

    # --- 4. CONNECT CLUSTERS WITH WIRE VERTICALLY ---
    for cx in active_cols_set:
        col_rows = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 16])
        for i in range(len(col_rows) - 1):
            r1, r2 = col_rows[i], col_rows[i + 1]
            gap_filled = all(
                bool(wm[y, cx]) or bool(pm[y, cx])
                for y in range(r1, r2 + 1) if ib(cx, y)
            )
            if not gap_filled:
                for y in range(r1, r2 + 1):
                    if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]):
                        return (Tool.WIRE, cx, y)

    # --- 5. BUILD ROAD GRID AROUND EACH CLUSTER ---
    road_reach = min(20, 6 + pop // 35)
    for cx, cy in clusters:
        # Horizontal roads above and below wire spine
        for road_y in [cy - 2, cy + 2]:
            if not ib(cx, road_y): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)
        # Vertical roads left and right of wire spine
        for road_x in [cx - 2, cx + 2]:
            if not ib(road_x, cy): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)

    # --- 6. INTER-CLUSTER ROADS (horizontal) ---
    if pop > 80:
        for cy in active_rows_set:
            row_cls2 = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 16])
            for i in range(len(row_cls2) - 1):
                c1, c2 = row_cls2[i], row_cls2[i + 1]
                for road_y in [cy - 3, cy + 3]:
                    if not (0 <= road_y < WORLD_H): continue
                    has_road = any(bool(rm[road_y, x]) for x in range(c1, c2 + 1) if ib(x, road_y))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    # --- 7. INTER-CLUSTER ROADS (vertical) ---
    if pop > 200:
        for cx in active_cols_set:
            col_rows2 = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 16])
            for i in range(len(col_rows2) - 1):
                r1, r2 = col_rows2[i], col_rows2[i + 1]
                for road_x in [cx - 3, cx + 3]:
                    if not (0 <= road_x < WORLD_W): continue
                    has_road = any(bool(rm[y, road_x]) for y in range(r1, r2 + 1) if ib(road_x, y))
                    if not has_road:
                        for y in range(r1, r2 + 1):
                            if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                                return (Tool.ROAD, road_x, y)

    # --- 8. ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # --- 9. CIVIC SERVICES ---
    if pop > 60:
        fire_spots = []
        for fy in range(12, 95, 16):
            for fx in range(8, 116, 18):
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = []
        for py2 in range(14, 90, 18):
            for px2 in range(10, 116, 20):
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        for sx, sy in [(25, 6), (60, 6), (95, 6), (25, 93), (60, 93), (95, 93),
                       (5, 50), (115, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [(5, 10), (5, 50), (5, 85),
                      (115, 10), (115, 50), (115, 85),
                      (40, 3), (80, 3), (40, 96), (80, 96)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for ax, ay in [(60, 4), (4, 50), (115, 50), (60, 94)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sx2, sy2 in [(4, 90), (115, 90), (4, 10), (115, 10)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- 10. PARKS near zones ---
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 40)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # --- 11. EXTEND ROADS NEAR WIRE (fallback) ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 100)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # --- 12. EXTEND WIRE (fallback) ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    # --- 13. ROAD NEAR ZONE (last resort) ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spines and flanking roads in a compact cluster."""
    actions = []
    # Three power plants
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
        # Wire spine
        for dy in range(-10, 11):
            actions.append((Tool.WIRE, px, 50 + dy))
        # Flanking roads
        for dy in range(-10, 11):
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    # Horizontal road connections at key y-levels
    for ry in [40, 50, 60]:
        for cx in range(19, 102):
            actions.append((Tool.ROAD, cx, ry))
