def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- BUILD PROXIMITY MASKS ----
    # Road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/plant proximity (within 6 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PLANNED INFRASTRUCTURE GRID ----
    # Wire columns: many vertical spines across entire map
    wire_cols = [8, 18, 28, 38, 48, 58, 68, 78, 88, 98, 108, 118]
    # Plant positions: 3 rows
    plant_rows = [20, 50, 80]
    # Road rows: horizontal arteries
    road_rows = [12, 22, 32, 42, 52, 62, 72, 82, 92]

    def num_active_cols():
        if pop < 100:    return 3
        elif pop < 300:  return 4
        elif pop < 700:  return 6
        elif pop < 1500: return 8
        elif pop < 3000: return 10
        else:            return 12

    def num_active_rows():
        if pop < 200:    return 3
        elif pop < 600:  return 5
        elif pop < 1500: return 7
        else:            return 9

    n_cols = num_active_cols()
    n_rows = num_active_rows()
    active_cols = wire_cols[:n_cols]
    active_road_rows = road_rows[:n_rows]
    active_plant_rows = plant_rows[:min(3, 1 + n_cols // 4)]

    # ---- ENSURE POWER PLANTS in active columns ----
    for wc in active_cols[::max(1, len(active_cols) // 4)]:  # every few columns
        for pr in active_plant_rows:
            # Check if plant exists nearby
            has_plant = False
            for dx in range(-8, 9):
                for dy in range(-8, 9):
                    nx, ny = wc + dx, pr + dy
                    if ib(nx, ny) and bool(pm[ny, nx]):
                        has_plant = True
                        break
                if has_plant:
                    break
            if not has_plant:
                # Find empty spot near (wc, pr)
                for r in range(0, 12):
                    for dy2 in range(-r, r + 1):
                        for dx2 in range(-r, r + 1):
                            if r > 0 and abs(dx2) != r and abs(dy2) != r:
                                continue
                            nx, ny = wc + dx2, pr + dy2
                            if ib(nx + 1, ny + 1) and ib(nx - 1, ny - 1):
                                if bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- VERTICAL WIRE SPINES ----
    spine_top = max(2, 10)
    spine_bot = min(WORLD_H - 3, 90)
    for wc in active_cols:
        # Find current wire extent in this column
        col_wire = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        col_plant = [r for r in range(WORLD_H) if ib(wc, r) and bool(pm[r, wc])]
        if not col_wire and not col_plant:
            # Seed wire near center
            for dy2 in range(0, 20):
                for sgn in [0, 1, -1]:
                    ny = 50 + sgn * dy2
                    if ib(wc, ny) and bool(em[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            all_powered = col_wire + col_plant
            if all_powered:
                min_wr = min(all_powered)
                max_wr = max(all_powered)
                if max_wr < spine_bot:
                    nr = max_wr + 1
                    if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                        return (Tool.WIRE, wc, nr)
                if min_wr > spine_top:
                    nr = min_wr - 1
                    if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                        return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL ROAD ARTERIES ----
    for rr in active_road_rows:
        # Build road across active columns
        road_in_row = sorted([c for c in range(WORLD_W) if ib(c, rr) and bool(rm[rr, c])])
        wire_in_row = sorted([c for c in range(WORLD_W) if ib(c, rr) and bool(wm[rr, c])])

        # Find leftmost and rightmost active col
        if not active_cols:
            continue
        left_col = active_cols[0] - 1
        right_col = active_cols[-1] + 1

        if road_in_row:
            min_r = min(road_in_row)
            max_r = max(road_in_row)
            if max_r < right_col:
                for cx in range(max_r + 1, min(right_col + 1, WORLD_W)):
                    if ib(cx, rr) and bool(em[rr, cx]) and not bool(pm[rr, cx]):
                        return (Tool.ROAD, cx, rr)
            if min_r > left_col:
                for cx in range(max(left_col, 0), min_r):
                    if ib(cx, rr) and bool(em[rr, cx]) and not bool(pm[rr, cx]):
                        return (Tool.ROAD, cx, rr)
        else:
            # Seed a road segment near a wire column at this row
            for wc in active_cols:
                if ib(wc - 1, rr) and bool(em[rr, wc - 1]) and not bool(pm[rr, wc - 1]):
                    return (Tool.ROAD, wc - 1, rr)
                if ib(wc + 1, rr) and bool(em[rr, wc + 1]) and not bool(pm[rr, wc + 1]):
                    return (Tool.ROAD, wc + 1, rr)

    # ---- VERTICAL ROADS alongside wire spines ----
    road_half = min(42, 10 + pop // 20)
    for idx, wc in enumerate(active_cols):
        rl, rr2 = wc - 1, wc + 1
        col_wire = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not col_wire:
            continue
        target_top = max(2, 50 - road_half)
        target_bot = min(WORLD_H - 3, 50 + road_half)
        cycle = (step + idx * 3) % 3
        for wr in col_wire[cycle::3]:
            if wr < target_top or wr > target_bot:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr2, wr) and bool(em[wr, rr2]) and not bool(pm[wr, rr2]):
                return (Tool.ROAD, rr2, wr)

    # ---- HORIZONTAL WIRE CONNECTIONS between columns ----
    for i in range(len(active_cols) - 1):
        c1 = active_cols[i]
        c2 = active_cols[i + 1]
        # Connect at plant row levels
        for conn_y in active_plant_rows + [50]:
            connected = True
            for cx in range(c1, c2 + 1):
                if ib(cx, conn_y) and not bool(wm[conn_y, cx]) and not bool(pm[conn_y, cx]) and not bool(rm[conn_y, cx]):
                    connected = False
                    break
            if not connected:
                for cx in range(c1, c2 + 1):
                    if ib(cx, conn_y) and bool(em[conn_y, cx]) and not bool(pm[conn_y, cx]):
                        return (Tool.WIRE, cx, conn_y)

    # ---- ZONE PLACEMENT: place zones near road+wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active wire columns and road rows
        best_dist = np.full(len(cxs), 999999.0)
        for wc in active_cols:
            d_col = np.abs(cxs - wc).astype(float)
            best_dist = np.minimum(best_dist, d_col)
        for rr3 in active_road_rows:
            d_row = np.abs(cys - rr3).astype(float)
            best_dist = np.minimum(best_dist, d_row)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled with pop ----
    if pop > 100:
        fire_spots = [
            (25, 25), (55, 25), (85, 25), (115, 25),
            (10, 45), (40, 45), (70, 45), (100, 45),
            (25, 65), (55, 65), (85, 65), (115, 65),
            (10, 85), (40, 85), (70, 85), (100, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (15, 17), (45, 17), (75, 17), (105, 17),
            (15, 37), (45, 37), (75, 37), (105, 37),
            (15, 57), (45, 57), (75, 57), (105, 57),
            (15, 77), (45, 77), (75, 77), (105, 77),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [
            (30, 8), (70, 8), (110, 8),
            (10, 35), (50, 35), (90, 35),
            (30, 92), (70, 92), (110, 92),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (30, 5), (90, 5), (5, 50), (115, 50),
            (30, 95), (90, 95),
        ]
        for (nx3, ny3) in nuke_spots:
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.NUCLEARPOWER, nx3, ny3)

    if pop > 3000:
        for asp in [(58, 5), (5, 50), (115, 50), (58, 95)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 95), (115, 95), (60, 95)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys, zone_xs = np.where(zone_map)
        if len(zone_xs) > 0:
            for i in range(min(len(zone_xs), 20)):
                k = (step * 3 + i * 17) % len(zone_xs)
                zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious closed-loop city builder v2
# Strategy: Dense grid infrastructure, rapid zone placement, aggressive civic services
# Key improvements: Better wire connectivity, faster zone filling, smarter road network

def init(obs, state):
    """Bootstrap: 2 central coal plants + spine roads + wire connections"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire spine connecting them
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spurs from center
    for y in range(44, 50):
        actions.append((Tool.WIRE, 40, y))
        actions.append((Tool.WIRE, 80, y))
    for y in range(51, 57):
        actions.append((Tool.WIRE, 40, y))
        actions.append((Tool.WIRE, 80, y))
    # Initial road grid near center
    for x in range(35, 86):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 35, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 85, y))
    return actions[:20]  # Keep init small


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- INFRASTRUCTURE TARGETS ----
    # Dense grid: roads every 4 tiles, wire corridors connecting all plants
    # 9 power plants arranged in 3x3 grid
    plant_targets = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]

    # Road corridors - horizontal and vertical grid every 6 tiles
    road_rows = list(range(9, 100, 6))   # y positions for horizontal roads
    road_cols = list(range(9, 120, 6))   # x positions for vertical roads

    # Wire corridors connecting plants
    wire_rows = [20, 50, 80]
    wire_cols = [20, 60, 100]

    # ---- PHASE DECISIONS based on step modulo ----
    phase = step % 10

    # ---- ENSURE POWER PLANTS EXIST ----
    # Always check if any plant target is missing
    for px, py in plant_targets:
        x0, x1 = max(0, px-5), min(WORLD_W, px+6)
        y0, y1 = max(0, py-5), min(WORLD_H, py+6)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        elif not has_plant:
            # Find nearby empty spot
            for r in range(1, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px+dx, py+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD WIRE NETWORK ----
    if phase in (0, 1, 2):
        # Horizontal wire corridors at wire_rows
        for wr in wire_rows:
            # Scan for gaps
            for wx in range(1, WORLD_W-1):
                if not ib(wx, wr): continue
                if bool(pm[wr, wx]): continue
                if bool(wm[wr, wx]): continue
                # Only place if adjacent to existing wire/plant
                adj = False
                for adx in [-1, 0, 1]:
                    for ady in [-1, 0, 1]:
                        if adx == 0 and ady == 0: continue
                        ax, ay = wx+adx, wr+ady
                        if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                            adj = True
                            break
                    if adj: break
                if adj and bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)

        # Vertical wire corridors at wire_cols
        for wc in wire_cols:
            for wy in range(1, WORLD_H-1):
                if not ib(wc, wy): continue
                if bool(pm[wy, wc]): continue
                if bool(wm[wy, wc]): continue
                adj = False
                for adx in [-1, 0, 1]:
                    for ady in [-1, 0, 1]:
                        if adx == 0 and ady == 0: continue
                        ax, ay = wc+adx, wy+ady
                        if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                            adj = True
                            break
                    if adj: break
                if adj and bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)

    # ---- BUILD ROAD NETWORK ----
    if phase in (3, 4, 5):
        # Horizontal roads
        for rr in road_rows:
            for rx in range(1, WORLD_W-1):
                if not ib(rx, rr): continue
                if bool(pm[rr, rx]): continue
                if bool(rm[rr, rx]): continue
                # Place if adjacent to existing road
                adj = False
                for adx in [-1, 1]:
                    ax = rx+adx
                    if ib(ax, rr) and bool(rm[rr, ax]):
                        adj = True
                        break
                # Or if we're at a column that already has vertical road
                if not adj:
                    for addy in [-1, 1]:
                        ay = rr+addy
                        if ib(rx, ay) and bool(rm[ay, rx]):
                            adj = True
                            break
                if adj and bool(em[rr, rx]):
                    return (Tool.ROAD, rx, rr)

        # Vertical roads
        for rc in road_cols:
            for ry in range(1, WORLD_H-1):
                if not ib(rc, ry): continue
                if bool(pm[ry, rc]): continue
                if bool(rm[ry, rc]): continue
                adj = False
                for ady in [-1, 1]:
                    ay = ry+ady
                    if ib(rc, ay) and bool(rm[ay, rc]):
                        adj = True
                        break
                if not adj:
                    for addx in [-1, 1]:
                        ax = rc+addx
                        if ib(ax, ry) and bool(rm[ry, ax]):
                            adj = True
                            break
                if adj and bool(em[ry, rc]):
                    return (Tool.ROAD, rc, ry)

    # ---- SEED ROADS if none exist near a corridor intersection ----
    # Check if road corridors are seeded at their intersections
    for rr in road_rows:
        for rc in road_cols:
            if ib(rc, rr) and bool(em[rr, rc]) and not bool(pm[rr, rc]):
                # Check neighborhood for any road
                y0, y1 = max(0, rr-3), min(WORLD_H, rr+4)
                x0, x1 = max(0, rc-3), min(WORLD_W, rc+4)
                has_road = bool(np.any(rm[y0:y1, x0:x1]))
                if not has_road:
                    return (Tool.ROAD, rc, rr)

    # ---- ZONE PLACEMENT ----
    # Determine zone type based on ratios
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr2 = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build proximity masks
    # Near road: within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H+dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W+dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Near power: within 5 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H+dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W+dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Candidate zone positions
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest plant (want to build around plants)
        best_dist = np.full(len(cxs), 999999.0)
        for px, py in plant_targets:
            d = np.abs(cxs - px) + np.abs(cys - py)
            best_dist = np.minimum(best_dist, d)

        # Prefer locations closer to plants but not on top of them
        # Also add some variety to avoid all clustering on one plant
        score = best_dist + np.random.RandomState(step).randint(0, 5, len(cxs))
        order = np.argsort(score)

        tool = pick_tool()
        for i in range(min(len(order), 200)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_locs = [
            (20, 15), (60, 15), (100, 15),
            (10, 40), (40, 40), (70, 40), (100, 40),
            (20, 65), (60, 65), (100, 65),
            (10, 85), (40, 85), (70, 85), (100, 85),
        ]
        for sx, sy in fire_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_locs = [
            (30, 25), (70, 25), (110, 25),
            (15, 50), (50, 50), (90, 50), (115, 50),
            (30, 75), (70, 75), (110, 75),
        ]
        for sx, sy in police_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(45, 35), (75, 35), (45, 65), (75, 65), (20, 50), (100, 50)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10), (60, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: extend wire from existing wire toward uncovered areas ----
    # Find wire/plant tiles and extend outward
    src_ys, src_xs = np.where(wm | pm)
    if len(src_xs) > 0:
        k = (step * 7) % len(src_xs)
        for i in range(min(len(src_xs), 50)):
            idx = (k + i) % len(src_xs)
            wx, wy = int(src_xs[idx]), int(src_ys[idx])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Extend toward target wire corridors
                    # Check if this direction helps coverage
                    target_covered = False
                    for wr in wire_rows:
                        if ny == wr:
                            target_covered = True
                            break
                    for wc in wire_cols:
                        if nx == wc:
                            target_covered = True
                            break
                    if target_covered:
                        return (Tool.WIRE, nx, ny)

    # ---- FALLBACK: extend road from existing road ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k = (step * 11) % len(road_xs2)
        for i in range(min(len(road_xs2), 60)):
            idx = (k + i * 7) % len(road_xs2)
            rx, ry = int(road_xs2[idx]), int(road_ys2[idx])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx+dx, ry+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- FALLBACK: generic wire extension ----
    if len(src_xs) > 0:
        k = (step * 13) % len(src_xs)
        for i in range(min(len(src_xs), 40)):
            idx = (k + i * 5) % len(src_xs)
            wx, wy = int(src_xs[idx]), int(src_ys[idx])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: multiple power plants connected by wires, plus initial road grid"""
    actions = []
    # Place 4 coal plants at quadrant centers
