def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone ratio target: 50% res, 30% com, 20% ind
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        # Use step-based cycling to mix zones more
        cycle = (step // 3) % 10
        if ir < 0.20 and cycle < 2:
            return Tool.INDUSTRIAL
        if cr < 0.30 and cycle < 5:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure multiple power plants covering entire map ----
    # Dense plant grid: every 20 tiles
    plant_grid = []
    for py in range(12, 95, 20):
        for px in range(12, 115, 20):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Dense road grid - horizontal roads every 6 rows, vertical every 6 cols ----
    # Build road grid at fixed intervals
    road_rows = list(range(6, 97, 6))
    road_cols = list(range(6, 115, 6))

    # Check if we need horizontal roads
    for ry in road_rows:
        # Check coverage: how many tiles in this row are roads?
        row_road_count = int(np.sum(rm[ry, 5:115]))
        if row_road_count < 100:  # Row not fully built
            # Find a segment to build
            for rx in range(5, 115):
                if bool(em[ry, rx]) and not bool(wm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Check if we need vertical roads
    for cx in road_cols:
        col_road_count = int(np.sum(rm[5:95, cx]))
        if col_road_count < 80:
            for ry in range(5, 95):
                if bool(em[ry, cx]) and not bool(wm[ry, cx]):
                    return (Tool.ROAD, cx, ry)

    # ---- PHASE 3: Wire expansion to cover unpowered zones ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    # Place wires to connect plants to road grid (on road intersections)
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        wire_cand = em & adj_to_power & ~zone_tiles
        wire_cand[0:3, :] = False
        wire_cand[WORLD_H-3:, :] = False
        wire_cand[:, 0:3] = False
        wire_cand[:, WORLD_W-3:] = False
        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            zys, zxs = np.where(unpowered_zones)
            best_dist = 1e9
            best_k = 0
            stride = max(1, len(wxs) // 200)
            for i in range(0, len(wxs), stride):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Also wire to uncovered plant grid areas
    uncovered_pg = [(px, py) for px, py in plant_grid
                    if ib(px, py) and not bool(near_power[py, px])]
    if uncovered_pg:
        wire_cand = em & adj_to_power & ~zone_tiles
        wire_cand[0:3, :] = False; wire_cand[WORLD_H-3:, :] = False
        wire_cand[:, 0:3] = False; wire_cand[:, WORLD_W-3:] = False
        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            best_dist = 1e9; best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in uncovered_pg)
                if d < best_dist:
                    best_dist = d; best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 4: Dense zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer near roads AND near existing zones (density bonus)
        road_ys, road_xs = np.where(rm)
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride_z = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride_z):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            # Seed near center of each quadrant
            zone_dist = np.ones(len(cxs_arr)) * 5.0

        if len(road_xs) > 0:
            stride_r = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride_r):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
            score = zone_dist * 0.3 + road_dist * 1.5
        else:
            score = zone_dist

        order = np.argsort(score)
        # Use step offset to vary placement and avoid getting stuck
        off = (step * 11 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled with pop ----
    if pop > 200:
        # Fire stations grid
        fire_grid = [(fx, fy) for fy in range(12, 92, 14) for fx in range(12, 112, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        police_grid = [(px2, py2) for py2 in range(16, 88, 16) for px2 in range(16, 108, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 600:
        park_grid = [(px3, py3) for py3 in range(10, 90, 10) for px3 in range(10, 110, 10)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 1000:
        stadium_locs = [(25, 20), (60, 20), (95, 20), (25, 50), (95, 50), (25, 80), (60, 80), (95, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 2000:
        # Nuclear for more capacity
        nuclear_locs = [(55, 8), (65, 8), (55, 91), (65, 91), (8, 48), (111, 48)]
        for npx, npy in nuclear_locs:
            if ib(npx, npy) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_locs = [(50, 8), (70, 8), (50, 91), (70, 91)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: wire from nearest plant toward zones ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious closed-loop city builder
# Strategy: 3x3 grid of coal plants covering the full map, dense wire/road/zone layout
# More aggressive zone placement, better power coverage, smarter civic services

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-4, 5):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-4, 5):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 6 cols x 5 rows = 30 neighborhoods ----
    # Spaced 18 apart horizontally, 18 apart vertically
    nh_cols = [12, 30, 48, 66, 84, 102]
    nh_rows = [12, 28, 46, 64, 82]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock
    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 3
        if pop < 500:   return 6
        if pop < 1000:  return 10
        if pop < 2000:  return 16
        if pop < 4000:  return 22
        if pop < 8000:  return 28
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from each plant ----
    spine_range = 10
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical wire at hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal wire at hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    # Build a wire mesh connecting all neighborhood nodes
    for (hx1, hy1) in active_hoods:
        # Connect to right neighbor
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx2 == hx1 + 18:
                mid_y = hy1
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Connect to bottom neighbor
            if hx1 == hx2 and hy2 == hy1 + 18:
                mid_x = hx1
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 2) % max(len(active_hoods), 1) not in range(max(1, len(active_hoods) // 2 + 1)):
            continue
        # Roads at hx-1 and hx+1 (flanking vertical spine)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Roads at hy-1 and hy+1 (flanking horizontal spine)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (placed densely) ----
    # Fire stations every 20 tiles
    if pop > 100:
        fire_spots = []
        for fx in range(15, WORLD_W, 20):
            for fy in range(15, WORLD_H, 20):
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = []
        for px2 in range(20, WORLD_W, 25):
            for py2 in range(20, WORLD_H, 25):
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (10, 50), (110, 50),
                    (45, 50), (75, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 45), (6, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop cities ----
    if pop > 3000 and step % 5 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 200 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Ambitious closed-loop policy: dense multi-neighborhood city
# Strategy: Build a grid of power plants connected by wires, with road grids
# between them, and fill the spaces with zones. Scale across the entire map.

def init(obs, state):
    """Bootstrap: place first coal plant and initial wire/road infrastructure."""
    actions = []
    # Primary plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Seed wires in cardinal directions
    for dx in range(-4, 5):
        if dx != 0:
            actions.append((Tool.WIRE, 60 + dx, 50))
    for dy in range(-4, 5):
        if dy != 0:
            actions.append((Tool.WIRE, 60, 50 + dy))
    # Seed roads adjacent to wire
    for dx in range(-3, 4):
        actions.append((Tool.ROAD, 60 + dx, 51))
        actions.append((Tool.ROAD, 60 + dx, 49))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Power plant grid: plants spaced 20 apart in x, 20 apart in y
    # This creates a dense power grid across the entire 120x100 map
    plant_positions = []
    for px in range(10, WORLD_W - 5, 20):
        for py in range(10, WORLD_H - 5, 20):
            plant_positions.append((px, py))

    # How many plants to activate based on population
    def num_active_plants():
        if pop < 200:
            return 1
        elif pop < 600:
            return 3
        elif pop < 1500:
            return 6
        elif pop < 3000:
            return 10
        elif pop < 6000:
            return 15
        else:
            return len(plant_positions)

    active_plants = plant_positions[:num_active_plants()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        # Check if plant exists near this position
        has_plant = False
        for dx in range(-4, 5):
            for dy in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant - avoid placing on road/wire if possible
            for r in range(6):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break
            # Force placement (auto-bulldoze handles clearing)
            return (Tool.COALPOWER, px, py)

    # ---- BUILD WIRE GRID connecting all plants ----
    # Connect plants horizontally and vertically with wires
    # Wire runs along plant rows (same y) and columns (same x)

    # Collect all plant actual positions
    actual_plants = []
    pys_arr, pxs_arr = np.where(pm)
    if len(pxs_arr) > 0:
        actual_plants = list(zip(pxs_arr.tolist(), pys_arr.tolist()))

    # Build horizontal wire connections between plants at same approximate y
    if len(actual_plants) >= 2:
        # Group by approximate y band
        by_y = {}
        for (apx, apy) in actual_plants:
            band = apy // 20
            if band not in by_y:
                by_y[band] = []
            by_y[band].append((apx, apy))

        for band, pts in by_y.items():
            if len(pts) < 2:
                continue
            pts_sorted = sorted(pts, key=lambda p: p[0])
            for i in range(len(pts_sorted) - 1):
                x1, y1 = pts_sorted[i]
                x2, y2 = pts_sorted[i + 1]
                mid_y = (y1 + y2) // 2
                # Lay horizontal wire at mid_y between x1 and x2
                for cx in range(min(x1, x2), max(x1, x2) + 1):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
                # Lay vertical wire from plant to mid_y
                for cy in range(min(y1, mid_y), max(y1, mid_y) + 1):
                    if ib(x1, cy) and bool(em[cy, x1]) and not bool(pm[cy, x1]):
                        return (Tool.WIRE, x1, cy)
                for cy in range(min(y2, mid_y), max(y2, mid_y) + 1):
                    if ib(x2, cy) and bool(em[cy, x2]) and not bool(pm[cy, x2]):
                        return (Tool.WIRE, x2, cy)

    # ---- BUILD ROAD GRID ----
    # Roads run parallel to wires but offset by 1-2 tiles
    # Create a road grid that gives access to all zones

    # Horizontal roads every 4 rows, vertical roads every 4 cols
    # This creates 3x3 zone blocks between roads
    road_interval = 4

    # Check each planned road row/col and extend roads
    # Road rows at y = 4, 8, 12, ... (multiples of road_interval)
    road_y_positions = list(range(4, WORLD_H - 3, road_interval))
    road_x_positions = list(range(4, WORLD_W - 3, road_interval))

    # Find road rows that need extension
    # First check if we have wire nearby before placing road
    # Compute wire neighborhood (power reachability)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    # Use a wider kernel for power spread
    for dy in range(-10, 11):
        for dx in range(-10, 11):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Extend horizontal roads near wire
    for ry in road_y_positions:
        if not ib(0, ry):
            continue
        # Check if this row has any wire nearby
        if not nbr_wire[ry, :].any():
            continue
        # Find existing roads in this row and extend them
        road_in_row = np.where(rm[ry, :])[0]
        if len(road_in_row) == 0:
            # Start road from a wire position in this row
            wire_in_row = np.where(wm[ry, :] | nbr_wire[ry, :])[0]
            if len(wire_in_row) > 0:
                start_x = int(wire_in_row[len(wire_in_row)//2])
                if ib(start_x, ry) and bool(em[ry, start_x]) and not bool(pm[ry, start_x]):
                    return (Tool.ROAD, start_x, ry)
        else:
            # Extend road leftward and rightward
            min_rx = int(np.min(road_in_row))
            max_rx = int(np.max(road_in_row))
            # Extend rightward
            nr = max_rx + 1
            if nr < WORLD_W - 1 and bool(em[ry, nr]) and not bool(pm[ry, nr]):
                return (Tool.ROAD, nr, ry)
            # Extend leftward
            nl = min_rx - 1
            if nl > 0 and bool(em[ry, nl]) and not bool(pm[ry, nl]):
                return (Tool.ROAD, nl, ry)

    # Extend vertical roads near wire
    for rx in road_x_positions:
        if not ib(rx, 0):
            continue
        if not nbr_wire[:, rx].any():
            continue
        road_in_col = np.where(rm[:, rx])[0]
        if len(road_in_col) == 0:
            wire_in_col = np.where(wm[:, rx] | nbr_wire[:, rx])[0]
            if len(wire_in_col) > 0:
                start_y = int(wire_in_col[len(wire_in_col)//2])
                if ib(rx, start_y) and bool(em[start_y, rx]) and not bool(pm[start_y, rx]):
                    return (Tool.ROAD, rx, start_y)
        else:
            min_ry = int(np.min(road_in_col))
            max_ry = int(np.max(road_in_col))
            nr = max_ry + 1
            if nr < WORLD_H - 1 and bool(em[nr, rx]) and not bool(pm[nr, rx]):
                return (Tool.ROAD, rx, nr)
            nl = min_ry - 1
            if nl > 0 and bool(em[nl, rx]) and not bool(pm[nl, rx]):
                return (Tool.ROAD, rx, nl)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # Want roughly 40% res, 30% com, 30% ind
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute road neighborhood for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Zone candidates: empty, near road AND near power
    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near active plant positions
        best_dist = np.full(len(cxs), 999999.0)
        for (apx, apy) in active_plants:
            d = np.abs(cxs - apx).astype(float) + np.abs(cys - apy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step to cycle through candidates for variety
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND WIRE from existing wire ----
    # Find wire endpoints and extend toward unconnected areas
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        # Find plants not yet connected to wire
        for (apx, apy) in active_plants:
            if not bool(pm[apy, apx]):
                continue
            # Check if this plant has wire adjacent
            has_wire_adj = False
            for dx in range(-2, 3):
                for dy in range(-2, 3):
                    nx, ny = apx + dx, apy + dy
                    if ib(nx, ny) and bool(wm[ny, nx]):
                        has_wire_adj = True
                        break
                if has_wire_adj:
                    break
            if not has_wire_adj:
                # Place wire adjacent to plant
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx, ny = apx + dx, apy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.WIRE, nx, ny)

        # Extend existing wire toward empty areas
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            # Look for nearby empty cells not yet powered
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Only extend if it helps reach unpowered areas
                    if not bool(nbr_wire[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- CIVIC SERVICES ----
    if pop > 500:
        # Fire stations spread across map
        fire_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                # Check if fire station not already nearby
                has_fire = False
                for dx in range(-6, 7):
                    for dy in range(-6, 7):
                        nx, ny = sx + dx, sy + dy
                        if ib(nx, ny) and 50 <= int(tm[ny, nx]) <= 60:
                            has_fire = True
                            break
                    if has_fire:
                        break
                if not has_fire:
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 1000:
        police_spots = [
            (30, 30), (70, 30), (110, 30),
            (30, 60), (70, 60), (110, 60),
            (30, 90), (70, 90), (110, 90),
            (50, 45), (90, 45), (50, 75), (90, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                has_police = False
                for dx in range(-6, 7):
                    for dy in range(-6, 7):
                        nx, ny = sx + dx, sy + dy
                        if ib(nx, ny) and 60 <= int(tm[ny, nx]) <= 70:
                            has_police = True
                            break
                    if has_police:
                        break
                if not has_police:
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 2000:
        stadium_spots = [
            (40, 15), (80, 15), (40, 85), (80, 85),
            (15, 40), (15, 70), (105, 40), (105, 70),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 5000:
        # Seaport and airport for larger cities
        if ib(10, 90) and bool(em[90, 10]):
            return (Tool.SEAPORT, 10, 90)
        if ib(100, 10) and bool(em[10, 100]):
            return (Tool.AIRPORT, 100, 10)

    # ---- FALLBACK: extend roads near existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- LAST RESORT: place wire from any wire endpoint ----
    if len(wire_xs_arr) > 0:
        step_k3 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k3 + offset * 3) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + seed roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines from center
    for x in range(50, 71):
        actions.append((Tool.WIRE, x, 50))
    for y in range(40, 61):
        actions.append((Tool.WIRE, 60, y))
    # Seed horizontal roads
    for x in range(45, 76):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    # Seed vertical roads
    for y in range(45, 56):
        actions.append((Tool.ROAD, 55, y))
        actions.append((Tool.ROAD, 65, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Power plant grid ----
    # Dense 7x6 grid of plants across whole map
    plant_positions = []
    for py in range(12, 95, 15):
        for px in range(12, 115, 18):
            plant_positions.append((px, py))

    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 8), min(WORLD_W, ppx + 9)
        y0, y1 = max(0, ppy - 8), min(WORLD_H, ppy + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network ----
    # Horizontal wire spines every 15 rows
    wire_rows = list(range(12, 95, 15))
    # Vertical wire spines every 18 cols
    wire_cols = list(range(12, 115, 18))

    # Build horizontal wires
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            if ib(60, wr) and em[wr, 60]:
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and em[wr, left-1]:
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 2 and em[wr, right+1]:
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if em[wr, x] and not pm[wr, x] and not rm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Build vertical wires
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and em[top-1, wc]:
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 2 and em[bot+1, wc]:
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if em[y, wc] and not pm[y, wc] and not rm[y, wc]:
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads offset from wire rows/cols by 5 tiles (zones fit between)
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 5)
        road_rows.append(wr + 5)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 5)
        road_cols.append(wc + 5)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    # Build horizontal roads
    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and em[rr, left-1] and not pm[rr, left-1]:
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-4 and em[rr, right+1] and not pm[rr, right+1]:
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and em[top-1, rc] and not pm[top-1, rc]:
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-4 and em[bot+1, rc] and not pm[bot+1, rc]:
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                stride = max(1, len(zxs2) // 100)
                zone_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(zxs2), stride):
                    d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
                road_ys, road_xs = np.where(rm)
                if len(road_xs) > 0:
                    rd_stride = max(1, len(road_xs) // 100)
                    road_dist = np.full(len(cxs_arr), 9999.0)
                    for i in range(0, len(road_xs), rd_stride):
                        d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                        road_dist = np.minimum(road_dist, d)
                    score = zone_dist * 0.4 + road_dist * 0.6
                else:
                    score = zone_dist
            else:
                score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)
        else:
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services (closed-loop based on pop) ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(12, 96, 12) for fx in range(12, 112, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_spots = [(px2, py2) for py2 in range(14, 92, 16) for px2 in range(14, 110, 24)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_spots = [(pkx, pky) for pky in range(16, 90, 10) for pkx in range(16, 108, 14)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 700:
        stadium_spots = [(sx, sy) for sy in range(20, 90, 25) for sx in range(20, 105, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        airport_spots = [
            (55, 8), (65, 8), (55, 91), (65, 91),
            (8, 44), (111, 44), (8, 56), (111, 56),
            (30, 8), (90, 8), (30, 91), (90, 91),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_spots = [
            (8, 50), (111, 50), (60, 5), (60, 94),
            (25, 5), (95, 5), (25, 94), (95, 94),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: wire extension from plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        # Extend wire adjacent to nearest unpowered zone or uncovered area
        unpowered = zone_tiles & ~near_power
        uzys, uzxs = np.where(unpowered)

        # Find wire candidates adjacent to power
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
            shifted = np.zeros_like(power_src)
            if dy == -1: shifted[:-1,:] = power_src[1:,:]
            elif dy == 1: shifted[1:,:] = power_src[:-1,:]
            elif dx == -1: shifted[:,:-1] = power_src[:,1:]
            elif dx == 1: shifted[:,1:] = power_src[:,:-1]
            adj_to_power |= shifted

        wire_cand = em & adj_to_power & ~zone_tiles & ~rm
        wire_cand[0:2,:] = False; wire_cand[WORLD_H-2:,:] = False
        wire_cand[:,0:2] = False; wire_cand[:,WORLD_W-2:] = False
        wys_c, wxs_c = np.where(wire_cand)

        if len(wxs_c) > 0:
            if len(uzxs) > 0:
                best_d = 1e9; best_k = 0
                stride = max(1, len(uzxs) // 30)
                for i in range(len(wxs_c)):
                    cx, cy = int(wxs_c[i]), int(wys_c[i])
                    d = min(abs(cx - uzxs[j]) + abs(cy - uzys[j]) for j in range(0, len(uzxs), stride))
                    if d < best_d:
                        best_d = d; best_k = i
                return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
            else:
                k = step % len(wxs_c)
                return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- Fallback: road near power ----
    pwr_ys2, pwr_xs2 = np.where(pm)
    if len(pwr_xs2) > 0:
        for i in range(len(pwr_xs2)):
            k = (step * 7 + i) % len(pwr_xs2)
            px2, py2 = int(pwr_xs2[k]), int(pwr_ys2[k])
            for dx2, dy2 in [(5,0),(-5,0),(0,5),(0,-5),(3,0),(-3,0),(0,3),(0,-3)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant with wire cross and road grid"""
    actions = []
    # Central coal power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines through center
    for x in range(50, 71):
        actions.append((Tool.WIRE, x, 50))
    for y in range(40, 61):
        actions.append((Tool.WIRE, 60, y))
    # Seed road grid around center
    for x in range(45, 76):
        actions.append((Tool.ROAD, x, 43))
        actions.append((Tool.ROAD, x, 57))
    for y in range(43, 58):
        actions.append((Tool.ROAD, 45, y))
        actions.append((Tool.ROAD, 75, y))
    # Add second power plant early
    actions.append((Tool.COALPOWER, 30, 30))
    for x in range(25, 36):
        actions.append((Tool.WIRE, x, 30))
    for y in range(25, 36):
        actions.append((Tool.WIRE, 30, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone ratio: 45% RES, 30% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Power plant grid: 5 columns x 5 rows for denser coverage
    plant_positions = []
    for px in [15, 35, 60, 85, 105]:
        for py in [15, 30, 50, 70, 85]:
            plant_positions.append((px, py))

    # Phase 1: ensure power plants exist
    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        found = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = ppx + dx, ppy + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            # Place plant only if we have enough funds
            if funds > 2000:
                return (Tool.COALPOWER, ppx, ppy)

    # Wire grid: dense horizontal spines every 8 rows and vertical every 8 cols
    wire_rows = list(range(8, 97, 8))
    wire_cols = list(range(8, 116, 8))

    # Extend horizontal wires across full map
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Seed near a plant if possible
            if ib(60, wr) and em[wr, 60]:
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left, right + 1):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot + 1):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # Road grid: between wire lines (offset by 4 from each wire line)
    road_rows = []
    road_cols = []
    for wr in wire_rows:
        for off in [-3, 3]:
            r = wr + off
            if 2 < r < WORLD_H - 2:
                road_rows.append(r)
    for wc in wire_cols:
        for off in [-3, 3]:
            c = wc + off
            if 2 < c < WORLD_W - 2:
                road_cols.append(c)
    road_rows = sorted(set(road_rows))
    road_cols = sorted(set(road_cols))

    # Build horizontal roads
    for rr in road_rows:
        row_road = rm[rr, :]
        if not row_road.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and ib(left - 1, rr) and em[rr, left - 1] and not pm[rr, left - 1]:
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 3 and ib(right + 1, rr) and em[rr, right + 1] and not pm[rr, right + 1]:
            return (Tool.ROAD, right + 1, rr)
        for x in range(left, right + 1):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and ib(rc, top - 1) and em[top - 1, rc] and not pm[top - 1, rc]:
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 3 and ib(rc, bot + 1) and em[bot + 1, rc] and not pm[bot + 1, rc]:
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top, bot + 1):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # Zone placement: near roads AND near wires
    # Compute "near road" mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute "near wire or plant" mask (within 4 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        """Check 3x3 area is clear (empty or existing zone tiles only)"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone locations: empty, near road, near wire, away from edges
    cand = em & nbr_road & nbr_wire
    cand[0:3, :] = False
    cand[WORLD_H - 3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score by proximity to existing zones (cluster) or toward center
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                zone_score = zone_dist
            else:
                zone_score = (np.abs(cxs_arr - 60).astype(float) +
                              np.abs(cys_arr - 50).astype(float))
        else:
            # Initially cluster near center
            zone_score = (np.abs(cxs_arr - 60).astype(float) +
                          np.abs(cys_arr - 50).astype(float))

        # As pop grows, also spread toward corners/edges
        if pop > 200:
            corners = [(15, 15), (105, 15), (15, 85), (105, 85),
                       (60, 15), (60, 85), (15, 50), (105, 50)]
            min_corner = np.full(len(cxs_arr), 999999.0)
            for cx, cy in corners:
                d = (np.abs(cxs_arr - cx).astype(float) +
                     np.abs(cys_arr - cy).astype(float))
                min_corner = np.minimum(min_corner, d)
            zone_score = zone_score * 0.3 + min_corner * 0.7

        order = np.argsort(zone_score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # Civic services based on population thresholds
    if pop > 20:
        fire_spots = [(fx, fy) for fy in range(10, 95, 10)
                      for fx in range(10, 115, 15)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_spots = [(px2, py2) for py2 in range(12, 92, 14)
                        for px2 in range(12, 112, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_spots = [(pkx, pky) for pky in range(15, 90, 12)
                      for pkx in range(15, 110, 16)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 400:
        stadium_spots = [
            (30, 25), (90, 25), (30, 75), (90, 75),
            (60, 25), (60, 75), (15, 50), (105, 50),
            (45, 40), (75, 40), (45, 60), (75, 60),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        nuclear_spots = [(20, 50), (100, 50), (60, 20), (60, 80),
                         (20, 25), (100, 25), (20, 75), (100, 75)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy):
                found = False
                for dy in range(-4, 5):
                    for dx in range(-4, 5):
                        nx2, ny2 = npx + dx, npy + dy
                        if ib(nx2, ny2) and pm[ny2, nx2]:
                            found = True
                            break
                    if found:
                        break
                if not found and bool(em[npy, npx]) and funds > 5000:
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600:
        airport_spots = [
            (55, 6), (65, 6), (55, 94), (65, 94),
            (6, 45), (114, 45), (6, 55), (114, 55),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 900:
        seaport_spots = [
            (6, 50), (114, 50), (60, 4), (60, 96),
            (20, 4), (100, 4), (20, 96), (100, 96),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend wires from plants
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend roads from existing wires
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13) % len(wxs)
        for offset in range(min(len(wxs), 80)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0, 3), (0, -3), (3, 0), (-3, 0),
                             (0, 4), (0, -4), (4, 0), (-4, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

# High-reactivity closed-loop city builder
# Strategy: 9-cluster grid (3x3) across the map, each cluster self-powered,
# with dense road networks and aggressive zone placement.

def init(obs, state):
    """Bootstrap 9 coal plants arranged in a 3x3 grid with initial wires."""
    actions = []
    # 3x3 plant grid
    plant_positions = [
        (20, 25), (60, 25), (100, 25),
        (20, 50), (60, 50), (100, 50),
        (20, 75), (60, 75), (100, 75),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Short wire stub so act() can extend
        actions.append((Tool.WIRE, px, py - 2))
        actions.append((Tool.WIRE, px, py + 2))
        # Short road stubs
        actions.append((Tool.ROAD, px - 2, py))
        actions.append((Tool.ROAD, px + 2, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # 9 cluster centers in a 3x3 grid
    ALL_CLUSTERS = [
        (20, 25), (60, 25), (100, 25),
        (20, 50), (60, 50), (100, 50),
        (20, 75), (60, 75), (100, 75),
    ]

    # Scale active clusters with population
    def num_active():
        if pop < 30:   return 1
        if pop < 100:  return 2
        if pop < 200:  return 3
        if pop < 400:  return 4
        if pop < 700:  return 6
        if pop < 1200: return 8
        return 9

    n_active = num_active()
    active_centers = ALL_CLUSTERS[:n_active]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 30% ind, 25% com, 45% res
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- ENSURE POWER PLANTS ---
    for (px, py) in active_centers:
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find nearest empty cell
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE SPINE: vertical through each cluster ---
    spine_half = min(20, 6 + pop // 20)
    for (px, py) in active_centers:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Extend downward
        for wy in range(py, spine_bot + 1):
            if ib(px, wy) and not bool(wm[wy, px]) and not bool(pm[wy, px]):
                if bool(em[wy, px]):
                    return (Tool.WIRE, px, wy)
                break
        # Extend upward
        for wy in range(py, spine_top - 1, -1):
            if ib(px, wy) and not bool(wm[wy, px]) and not bool(pm[wy, px]):
                if bool(em[wy, px]):
                    return (Tool.WIRE, px, wy)
                break

    # --- HORIZONTAL WIRE connecting clusters in same row ---
    row_ys = sorted(set(py for (px, py) in active_centers))
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl])
        for i in range(len(row_cs) - 1):
            x1c, x2c = row_cs[i][0], row_cs[i + 1][0]
            for cx in range(x1c, x2c + 1):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting cluster rows ---
    if n_active >= 4:
        col_xs = sorted(set(px for (px, py) in active_centers))
        for xc in col_xs:
            col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc])
            for i in range(len(col_cs) - 1):
                y1c, y2c = col_cs[i][1], col_cs[i + 1][1]
                for cy in range(y1c, y2c + 1):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # --- ROAD GRID: horizontal roads flanking each cluster ---
    for (px, py) in active_centers:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Left road column
        for ry in range(spine_top, spine_bot + 1):
            rx = px - 4
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)
        # Right road column
        for ry in range(spine_top, spine_bot + 1):
            rx = px + 4
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)
        # Inner left road
        for ry in range(spine_top, spine_bot + 1):
            rx = px - 2
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)
        # Inner right road
        for ry in range(spine_top, spine_bot + 1):
            rx = px + 2
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # --- HORIZONTAL CONNECTOR ROADS between clusters ---
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl])
        if len(row_cs) < 2:
            continue
        x_left = row_cs[0][0] - 5
        x_right = row_cs[-1][0] + 5
        for offset in [-3, 3, -6, 6]:
            horiz_y = yl + offset
            if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                continue
            for cx in range(x_left, x_right + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # --- BUILD NEIGHBOR MASKS for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_centers:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # --- CIVIC SERVICES ---
    if pop > 60:
        fire_spots = []
        for yl in [20, 38, 55, 72, 88]:
            for xl in [8, 35, 65, 95, 115]:
                fire_spots.append((xl, yl))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = []
        for yl in [18, 43, 60, 82]:
            for xl in [12, 40, 70, 100, 115]:
                police_spots.append((xl, yl))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (30, 10), (70, 10), (110, 10),
            (30, 90), (70, 90), (110, 90),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power upgrade
    if pop > 800:
        nuke_spots = [
            (40, 3), (80, 3), (5, 50), (115, 50),
            (40, 96), (80, 96), (5, 20), (115, 20),
            (5, 80), (115, 80), (5, 35), (115, 35),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94), (5, 5), (115, 5)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 7), (115, 7)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # Parks to boost land value
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- FALLBACK: extend wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: road near zone
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place 4 coal plants at quadrant centers + wire/road spines"""
    actions = []
    # Four power plants at quadrant centers
    for px, py in [(30, 25), (90, 25), (30, 75), (90, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spines connecting plants horizontally
    for x in range(32, 88, 2):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Wire spines connecting plants vertically
    for y in range(27, 73, 2):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Initial roads near each quadrant
    for x in range(5, 55):
        actions.append((Tool.ROAD, x, 20))
        actions.append((Tool.ROAD, x, 30))
    for x in range(65, 115):
        actions.append((Tool.ROAD, x, 20))
        actions.append((Tool.ROAD, x, 30))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Target zone mix: 50% res, 30% com, 20% ind
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plants on a dense grid (every 12 tiles, 4 quadrant focus) ----
    # Dense plant grid covering all 4 quadrants
    plant_grid = []
    for py in range(10, 95, 12):
        for px in range(10, 115, 12):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
        y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        uncovered = [(px, py) for px, py in plant_grid
                     if ib(px, py) and not bool(near_power[py, px])]
        if uncovered:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in uncovered)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire to unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs, zys))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid — denser, 4-quadrant coverage ----
    # Road grid at every 5 tiles for denser coverage
    road_grid_targets = []
    for gy in range(6, 97, 5):
        for gx in range(6, 117, 5):
            road_grid_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm
        road_cand[0:3, :] = False
        road_cand[WORLD_H-3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W-3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in uncovered_road[:20])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:5]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Dense zone placement with mix ----
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer near roads, near existing zones, spread across map
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                rd_stride = max(1, len(road_xs) // 100)
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), rd_stride):
                    d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                    road_dist = np.minimum(road_dist, d)
                score = zone_dist * 0.4 + road_dist * 1.2
            else:
                score = zone_dist
        else:
            # Start near first quadrant center
            score = (np.abs(cxs_arr - 30) + np.abs(cys_arr - 25)).astype(float)

        order = np.argsort(score)
        # Cycle through candidates to spread zones
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services (tiered by population) ----
    if pop > 50:
        # Fire stations across all 4 quadrants
        fire_grid = [(fx, fy) for fy in range(12, 92, 8) for fx in range(12, 110, 8)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_grid = [(px2, py2) for py2 in range(15, 90, 10) for px2 in range(15, 108, 10)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_grid = [(px3, py3) for py3 in range(14, 88, 7) for px3 in range(14, 108, 7)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        stadium_locs = [(25, 20), (85, 20), (25, 70), (85, 70),
                        (55, 15), (55, 85), (15, 45), (105, 45),
                        (40, 50), (80, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Nuclear plants for more power coverage at high pop
        nuke_locs = [(60, 50), (20, 50), (100, 50), (60, 15), (60, 85)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-5), min(WORLD_W, nx+6)
                y0, y1 = max(0, ny-5), min(WORLD_H, ny+6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1500:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91),
                        (8, 30), (110, 30), (8, 65), (110, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from any plant ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        for i in range(len(pwr_xs)):
            k = (step * 7 + i) % len(pwr_xs)
            px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
            for dx2, dy2 in [(4, 0), (-4, 0), (0, 4), (0, -4), (3, 3), (-3, 3)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from plant ----
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

