    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- counts ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return result
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                ny_arr = ys + dy
                nx_arr = xs + dx
                valid = (ny_arr >= 0) & (ny_arr < WORLD_H) & (nx_arr >= 0) & (nx_arr < WORLD_W)
                result[ny_arr[valid], nx_arr[valid]] = True
        return result

    # Power and road neighborhoods
    nbr_wire = expand_mask(wm | pm, 5)
    nbr_road = expand_mask(rm, 3)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Define neighborhood clusters scaled with population ---
    # Full grid: 8 cols x 6 rows = 48 clusters
    all_cols = [10, 25, 40, 57, 72, 88, 103, 115]
    all_rows = [10, 25, 40, 57, 72, 85, 95]

    def active_clusters():
        if pop < 100:
            return [(57, 50), (72, 50)]
        if pop < 400:
            return [(40, 50), (57, 50), (72, 50), (88, 50)]
        if pop < 900:
            return [(cx, cy) for cy in [40, 57] for cx in [25, 40, 57, 72, 88, 103]]
        if pop < 2000:
            return [(cx, cy) for cy in [25, 50, 72] for cx in [10, 25, 40, 57, 72, 88, 103, 115]]
        if pop < 4000:
            return [(cx, cy) for cy in [10, 25, 40, 57, 72, 85]
                    for cx in [10, 25, 40, 57, 72, 88, 103, 115]]
        return [(cx, cy) for cy in all_rows for cx in all_cols]

    clusters = active_clusters()
    active_cols_set = sorted(set(cx for cx, cy in clusters))
    active_rows_set = sorted(set(cy for cx, cy in clusters))

    # ---- 1. ENSURE POWER PLANT NEAR EACH CLUSTER ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 15), min(WORLD_W, cx + 16)
        py0, py1 = max(0, cy - 15), min(WORLD_H, cy + 16)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            # Place coal plant at cluster center if empty
            if ib(cx, cy) and bool(em[cy, cx]):
                return (Tool.COALPOWER, cx, cy)
            # Search nearby
            for r in range(1, 20):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. BUILD WIRE SPINES FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(25, 8 + pop // 20)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 16 and abs(py2 - cy) <= 16
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Horizontal wire from plant
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            # Vertical wire from plant
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- 3. CONNECT CLUSTERS WITH WIRE HORIZONTALLY ----
    for cy in active_rows_set:
        row_cls = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 16])
        for i in range(len(row_cls) - 1):
            c1, c2 = row_cls[i], row_cls[i + 1]
            # Check if gap is filled with wire or plants
            gap_ok = all(
                bool(wm[cy, x]) or bool(pm[cy, x])
                for x in range(c1, c2 + 1) if ib(x, cy)
            )
            if not gap_ok:
                for x in range(c1, c2 + 1):
                    if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]) and not bool(wm[cy, x]):
                        return (Tool.WIRE, x, cy)

    # ---- 4. CONNECT CLUSTERS WITH WIRE VERTICALLY ----
    for cx in active_cols_set:
        for i in range(len(active_rows_set) - 1):
            r1, r2 = active_rows_set[i], active_rows_set[i + 1]
            gap_ok = all(
                bool(wm[y, cx]) or bool(pm[y, cx])
                for y in range(r1, r2 + 1) if ib(cx, y)
            )
            if not gap_ok:
                for y in range(r1, r2 + 1):
                    if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]) and not bool(wm[y, cx]):
                        return (Tool.WIRE, cx, y)

    # ---- 5. BUILD ROADS AROUND EACH CLUSTER ----
    road_reach = min(20, 6 + pop // 30)
    for cx, cy in clusters:
        # Two horizontal roads flanking cluster
        for road_y in [cy - 3, cy + 3]:
            if not (0 <= road_y < WORLD_H): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if (ib(nx4, ny4) and bool(em[ny4, nx4])
                        and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4])):
                    return (Tool.ROAD, nx4, ny4)
        # Two vertical roads flanking cluster
        for road_x in [cx - 3, cx + 3]:
            if not (0 <= road_x < WORLD_W): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if (ib(nx4, ny4) and bool(em[ny4, nx4])
                        and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4])):
                    return (Tool.ROAD, nx4, ny4)

    # ---- 6. INTER-CLUSTER ROADS ----
    if pop > 80:
        for cy in active_rows_set:
            row_cls2 = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 16])
            for i in range(len(row_cls2) - 1):
                c1, c2 = row_cls2[i], row_cls2[i + 1]
                for road_y in [cy - 4, cy + 4]:
                    if not (0 <= road_y < WORLD_H): continue
                    # Check if road exists in this segment
                    has_road = any(bool(rm[road_y, x]) for x in range(c1, c2 + 1) if ib(x, road_y))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)
        for cx in active_cols_set:
            for i in range(len(active_rows_set) - 1):
                r1, r2 = active_rows_set[i], active_rows_set[i + 1]
                for road_x in [cx - 4, cx + 4]:
                    if not (0 <= road_x < WORLD_W): continue
                    has_road = any(bool(rm[y, road_x]) for y in range(r1, r2 + 1) if ib(road_x, y))
                    if not has_road:
                        for y in range(r1, r2 + 1):
                            if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                                return (Tool.ROAD, road_x, y)

    # ---- 7. ADDITIONAL DIAGONAL WIRE BRANCHES for wide coverage ----
    # Extend wire from wire tips to reach more empty areas
    if pop > 50:
        wire_ys_arr, wire_xs_arr = np.where(wm)
        if len(wire_xs_arr) > 0:
            step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
            for offset in range(min(len(wire_xs_arr), 100)):
                k = (step_k2 + offset * 7) % len(wire_xs_arr)
                wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
                for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx7, ny7 = wx3 + dx7, wy3 + dy7
                    if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                        return (Tool.WIRE, nx7, ny7)

    # ---- 8. ZONE PLACEMENT (reactive: powered + roaded empty tiles) ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- 9. CIVIC SERVICES (placed reactively based on pop) ----
    if pop > 50:
        # Fire stations distributed across map
        fire_spots = [(cx + 6, cy + 6) for cx, cy in clusters]
        for fx, fy in fire_spots:
            if ib(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        police_spots = [(cx - 6, cy - 6) for cx, cy in clusters]
        for fx, fy in police_spots:
            if ib(fx, fy) and bool(em[fy, fx]):
                return (Tool.POLICESTATION, fx, fy)

    if pop > 500:
        stadium_spots = [(57, 5), (57, 92), (10, 50), (110, 50),
                         (25, 92), (88, 92), (25, 5), (88, 5)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 10), (5, 50), (5, 90),
                      (115, 10), (115, 50), (115, 90),
                      (57, 3), (57, 96)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for ax, ay in [(60, 4), (4, 50), (115, 50), (60, 95), (30, 4), (90, 4)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sx2, sy2 in [(4, 90), (115, 90), (4, 10), (115, 10), (57, 90)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- 10. PARKS near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- 11. FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 100)):
            k = (step_k + offset * 9) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6])
                        and not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants + wire grid + initial roads"""
    actions = []
    # 4 coal plants in quadrants
    plants = [(25, 25), (90, 25), (25, 70), (90, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire corridors along y=25,70 and x=25,90
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 70))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 25, y))
        actions.append((Tool.WIRE, 90, y))
    # Initial roads flanking wire rows
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 69))
        actions.append((Tool.ROAD, x, 71))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- Define neighborhoods covering the full map ---
    # 5 columns x 4 rows = 20 neighborhoods
    nh_positions = []
    for row in range(4):
        for col in range(5):
            cx = 12 + col * 24   # 12, 36, 60, 84, 108
            cy = 13 + row * 25   # 13, 38, 63, 88
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            # center 4
            return [nh_positions[7], nh_positions[8], nh_positions[12], nh_positions[13]]
        elif pop < 400:
            return nh_positions[5:15]
        elif pop < 1000:
            return nh_positions[2:18]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # --- Wire corridor rows/cols ---
    wire_rows = [13, 25, 38, 50, 63, 75, 88]
    wire_cols = [12, 25, 36, 48, 60, 72, 84, 96, 108]

    # Dilate helper
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANTS FOR ACTIVE HOODS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 14):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE CORRIDORS ----
    # Build wire along corridor rows and columns reactively
    phase = step % 6

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            # Find existing wire in this row and extend
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    # Check if adjacent wire exists
                    if (ib(wx-1, wr) and bool(row_wire[wx-1])) or (ib(wx+1, wr) and bool(row_wire[wx+1])):
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    if (ib(wc, wy-1) and bool(col_wire[wy-1])) or (ib(wc, wy+1) and bool(col_wire[wy+1])):
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Seed new wire corridors at wire_rows (plant a wire near a plant)
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                # Find nearest plant to seed from
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    px2, py2 = int(plant_xs[best]), int(plant_ys[best])
                    # Walk from plant toward wr
                    if ib(px2, wr) and bool(em[wr, px2]):
                        return (Tool.WIRE, px2, wr)

    elif phase == 3:
        # Roads parallel to wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to wire columns
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    else:
        # Cross roads between corridors
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (c1 + c2) // 2
            if not ib(mid_x, 0):
                continue
            col_road_l = rm[:, c1+1] if ib(c1+1, 0) else np.zeros(WORLD_H, dtype=bool)
            col_road_r = rm[:, c1-1] if ib(c1-1, 0) else np.zeros(WORLD_H, dtype=bool)
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                          (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                    if adj and bool(near_power[ry, mid_x]):
                        return (Tool.ROAD, mid_x, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Exclude wire/plant corridors to avoid destroying infrastructure
    for wr in wire_rows:
        cand_mask[wr, :] = False
    for wc in wire_cols:
        cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_grid = [(20, 13), (60, 13), (100, 13),
                     (20, 38), (60, 38), (100, 38),
                     (20, 63), (60, 63), (100, 63),
                     (20, 88), (60, 88), (100, 88)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_grid = [(35, 25), (75, 25), (110, 50),
                       (10, 50), (55, 50), (95, 50),
                       (35, 75), (75, 75)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(45, 45), (75, 45), (45, 60), (75, 60),
                    (20, 50), (100, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 5), (60, 94), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(55, 5), (65, 5), (55, 94), (65, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near zones
    if pop > 150 and step % 7 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire from existing wire toward unpowered hoods ----
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            # Find closest wire to this hood
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            # Step toward target
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            # Try horizontal step first
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend road network near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: wire extension from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

