def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_budget'] = 0
        state['last_pop'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 50% RES, 25% COM, 25% IND
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Desired infrastructure: plants, wire rows/cols, road rows/cols ----
    # Plants: a grid, progressively more as pop grows
    plant_targets = [
        (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
        (60, 15), (60, 85), (15, 50), (105, 50),
        (15, 25), (105, 25), (15, 75), (105, 75),
        (45, 50), (75, 50), (60, 35), (60, 65),
    ]
    if pop > 300:
        plant_targets += [
            (30, 10), (60, 10), (90, 10),
            (30, 90), (60, 90), (90, 90),
            (10, 35), (10, 65), (110, 35), (110, 65),
        ]
    if pop > 800:
        plant_targets += [
            (20, 50), (100, 50),
            (45, 15), (75, 15), (45, 85), (75, 85),
            (5, 50), (115, 50),
        ]
    if pop > 1500:
        plant_targets += [
            (20, 10), (100, 10), (20, 90), (100, 90),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]

    # Wire grid: dense rows and columns
    wire_rows = list(range(10, 95, 10))
    wire_cols = list(range(10, 115, 10))

    if pop > 500:
        wire_rows += [5, 95]
        wire_cols += [5, 115]

    # Road grid: between wire rows
    road_rows = []
    road_cols = []
    for wr in wire_rows:
        road_rows.append(wr - 3)
        road_rows.append(wr + 3)
    for wc in wire_cols:
        road_cols.append(wc - 3)
        road_cols.append(wc + 3)
    road_rows = [r for r in road_rows if 3 <= r < WORLD_H - 3]
    road_cols = [c for c in road_cols if 3 <= c < WORLD_W - 3]

    # ---- Phase 1: Ensure power plants exist ----
    for px, py in plant_targets:
        if not ib(px, py):
            continue
        # Check if plant already nearby
        found = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and pm[ny, nx]:
                    found = True
                    break
            if found:
                break
        if not found:
            return (Tool.COALPOWER, px, py)

    # ---- Phase 2: Wire network - connect plants via wire grid ----
    # For each wire row, fill gaps
    for wr in wire_rows:
        if not ib(0, wr):
            continue
        # Find extent of existing wire/plant in this row
        row_powered = wm[wr, :] | pm[wr, :]
        if not row_powered.any():
            # No wire at all in this row - lay first wire near a plant column
            for px, py in plant_targets:
                if ib(px, wr) and em[wr, px]:
                    return (Tool.WIRE, px, wr)
            continue
        idxs = np.where(row_powered)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        # Fill gaps
        for x in range(max(0, left), min(WORLD_W, right + 1)):
            if em[wr, x]:
                return (Tool.WIRE, x, wr)
        # Extend left
        if left > 5:
            nx = left - 1
            if em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 6:
            nx = right + 1
            if em[wr, nx]:
                return (Tool.WIRE, nx, wr)

    # For each wire col, fill gaps
    for wc in wire_cols:
        if not ib(wc, 0):
            continue
        col_powered = wm[:, wc] | pm[:, wc]
        if not col_powered.any():
            for px, py in plant_targets:
                if ib(wc, py) and em[py, wc]:
                    return (Tool.WIRE, wc, py)
            continue
        idxs = np.where(col_powered)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        for y in range(max(0, top), min(WORLD_H, bot + 1)):
            if em[y, wc]:
                return (Tool.WIRE, wc, y)
        if top > 5:
            ny = top - 1
            if em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 6:
            ny = bot + 1
            if em[ny, wc]:
                return (Tool.WIRE, wc, ny)

    # ---- Phase 3: Road network ----
    # Horizontal roads
    for rr in road_rows:
        if not ib(0, rr):
            continue
        # Check wire nearby
        wire_near = False
        for dy in range(-5, 6):
            nr = rr + dy
            if 0 <= nr < WORLD_H and (wm[nr, :] | pm[nr, :]).any():
                wire_near = True
                break
        if not wire_near:
            continue
        row_road = rm[rr, :]
        if not row_road.any():
            # Start a road at a wire column intersection
            for wc in wire_cols:
                if ib(wc, rr) and em[rr, wc]:
                    return (Tool.ROAD, wc, rr)
            if ib(60, rr) and em[rr, 60]:
                return (Tool.ROAD, 60, rr)
        else:
            idxs = np.where(row_road)[0]
            left = int(idxs[0])
            right = int(idxs[-1])
            # Fill gaps
            for x in range(left, right):
                if em[rr, x] and not pm[rr, x]:
                    return (Tool.ROAD, x, rr)
            if left > 3 and em[rr, left - 1] and not pm[rr, left - 1]:
                return (Tool.ROAD, left - 1, rr)
            if right < WORLD_W - 4 and em[rr, right + 1] and not pm[rr, right + 1]:
                return (Tool.ROAD, right + 1, rr)

    # Vertical roads
    for rc in road_cols:
        if not ib(rc, 0):
            continue
        wire_near = False
        for dx in range(-5, 6):
            nc = rc + dx
            if 0 <= nc < WORLD_W and (wm[:, nc] | pm[:, nc]).any():
                wire_near = True
                break
        if not wire_near:
            continue
        col_road = rm[:, rc]
        if not col_road.any():
            for wr in wire_rows:
                if ib(rc, wr) and em[wr, rc]:
                    return (Tool.ROAD, rc, wr)
            if ib(rc, 50) and em[50, rc]:
                return (Tool.ROAD, rc, 50)
        else:
            idxs = np.where(col_road)[0]
            top = int(idxs[0])
            bot = int(idxs[-1])
            for y in range(top, bot):
                if em[y, rc] and not pm[y, rc]:
                    return (Tool.ROAD, rc, y)
            if top > 3 and em[top - 1, rc] and not pm[top - 1, rc]:
                return (Tool.ROAD, rc, top - 1)
            if bot < WORLD_H - 4 and em[bot + 1, rc] and not pm[bot + 1, rc]:
                return (Tool.ROAD, rc, bot + 1)

    # ---- Phase 4: Zone placement ----
    # Compute neighborhood masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        """Check 3x3 area is clear for zone placement"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate cells: empty, near road, near wire, away from map edge
    cand = em & nbr_road & nbr_wire
    cand[0:4, :] = False
    cand[WORLD_H - 4:, :] = False
    cand[:, 0:4] = False
    cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(cand)

    if len(cxs_arr) > 0:
        # Score: prefer close to existing zones (clustering) and close to power
        min_plant_dist = np.full(len(cxs_arr), 999999.0)
        for px2, py2 in plant_targets[:8]:
            if ib(px2, py2):
                d = (np.abs(cxs_arr - px2).astype(float) +
                     np.abs(cys_arr - py2).astype(float))
                min_plant_dist = np.minimum(min_plant_dist, d)

        zone_score = min_plant_dist.copy()

        if total_zones > 10:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 150)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                # Prefer close to existing zones but not on top
                zone_score = zone_dist * 0.4 + min_plant_dist * 0.6

        order = np.argsort(zone_score)
        # Use step-based offset for variety
        off = (step * 3 + pop) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (pick_tool(), zx2, zy2)

    # ---- Phase 5: Civic services ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(18, 95, 20) for fx in range(18, 110, 25)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(px2, py2) for py2 in range(22, 90, 25) for px2 in range(22, 105, 30)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_grid = [(pkx, pky) for pky in range(20, 90, 15) for pkx in range(20, 105, 20)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [
            (44, 30), (76, 30), (44, 70), (76, 70),
            (20, 50), (100, 50), (60, 20), (60, 80),
            (30, 40), (90, 40), (30, 60), (90, 60),
        ]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        airport_spots = [
            (55, 7), (65, 7), (55, 93), (65, 93),
            (7, 40), (113, 40), (7, 60), (113, 60),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [
            (7, 50), (113, 50), (60, 5), (60, 95),
            (20, 5), (100, 5), (20, 95), (100, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend wire from existing plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11 + pop * 7) % len(pxs)
        for offset in range(min(len(pxs), 40)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: extend road near wire ----
    wys, wxs = np.where(wm)
    if len(wxs) > 0:
        sk2 = (step * 13 + pop * 5) % len(wxs)
        for offset in range(min(len(wxs), 60)):
            k = (sk2 + offset * 5) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx3, dy3 in [(0, 2), (0, -2), (2, 0), (-2, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants along center row with wire spines and flanking roads."""
    actions = []
    # Three plants at strategic positions
    for px, py in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connectors
    for cx in range(21, 60):
        actions.append((Tool.WIRE, cx, 50))
    for cx in range(61, 100):
        actions.append((Tool.WIRE, cx, 50))
    # Horizontal roads above and below center
    for cx in range(15, 106):
        actions.append((Tool.ROAD, cx, 44))
        actions.append((Tool.ROAD, cx, 56))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    # Plant grid: 3 columns x 5 rows = 15 plants
    # Columns at x=20,60,100; rows at y=15,30,50,70,85
    all_plant_pos = [(px, py) for px in [20, 60, 100] for py in [15, 30, 50, 70, 85]]

    def num_active():
        if pop < 30:   return 3
        if pop < 100:  return 4
        if pop < 200:  return 5
        if pop < 400:  return 6
        if pop < 600:  return 8
        if pop < 1000: return 10
        if pop < 1500: return 12
        return 15

    n_active = min(num_active(), len(all_plant_pos))
    # Spread active plants evenly
    step_size = len(all_plant_pos) / max(n_active, 1)
    active_plants = [all_plant_pos[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: VERTICAL WIRE SPINES ----
    spine_half = min(45, 10 + pop // 6)
    for (px, py) in active_plants:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy in range(-6, 7):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 3: HORIZONTAL WIRE connecting plants in same row ----
    y_levels = sorted(set(py for (px, py) in active_plants))
    for yl in y_levels:
        row_plants = sorted([px for (px, py) in active_plants if py == yl])
        for i in range(len(row_plants) - 1):
            x1r, x2r = row_plants[i], row_plants[i + 1]
            for cx in range(x1r + 1, x2r):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]) and not bool(rm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- PHASE 4: VERTICAL WIRE connecting plant columns ----
    x_cols = sorted(set(px for (px, py) in active_plants))
    for xc in x_cols:
        col_plants = sorted([py for (px, py) in active_plants if px == xc])
        for i in range(len(col_plants) - 1):
            y1c, y2c = col_plants[i], col_plants[i + 1]
            for cy in range(y1c + 1, y2c):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]) and not bool(rm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- PHASE 5: FLANKING ROADS alongside wire spines ----
    for (px, py) in active_plants:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for side in [px - 1, px + 1]:
            if not (0 <= side < WORLD_W):
                continue
            wire_rows_here = [r for r in range(spine_top, spine_bot + 1)
                              if ib(px, r) and bool(wm[r, px])]
            for wr in wire_rows_here:
                if ib(side, wr) and bool(em[wr, side]) and not bool(pm[wr, side]):
                    return (Tool.ROAD, side, wr)

    # ---- PHASE 6: HORIZONTAL ROADS at each y-level (offset from plant rows) ----
    for yl in y_levels:
        row_plants = sorted([px for (px, py) in active_plants if py == yl])
        if not row_plants:
            continue
        xl = max(2, row_plants[0] - 3)
        xr = min(WORLD_W - 3, row_plants[-1] + 3)
        for horiz_y in [yl - 5, yl + 5]:
            if not (2 <= horiz_y < WORLD_H - 2):
                continue
            for cx in range(xl, xr + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- PHASE 7: VERTICAL CROSS ROADS between y levels ----
    if pop > 20 or step > 80:
        for xc in x_cols:
            for rx in [xc - 3, xc + 3]:
                if not (2 <= rx < WORLD_W - 2):
                    continue
                for i in range(len(y_levels) - 1):
                    y1v = y_levels[i]
                    y2v = y_levels[i + 1]
                    for cy in range(y1v - 5, y2v + 6):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- ADDITIONAL HORIZONTAL ROADS across full map ----
    if pop > 50 or step > 150:
        extra_road_ys = []
        for yl in y_levels:
            extra_road_ys.append(yl - 5)
            extra_road_ys.append(yl + 5)
        extra_road_ys = sorted(set(y for y in extra_road_ys if 2 <= y < WORLD_H - 2))
        for ry in extra_road_ys:
            for cx in range(5, WORLD_W - 5):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    return (Tool.ROAD, cx, ry)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    near_road = dilate(rm, 3)
    near_power = dilate(wm | pm, 5)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 8: ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Exclude wire/plant rows and columns
    for (px, py) in active_plants:
        cand_mask[py, :] = False
        cand_mask[:, px] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer near active plant anchors but spread out
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_plants:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        # Also reward being near roads
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(road_xs), stride):
                d = np.abs(cxs - road_xs[i]).astype(float) + np.abs(cys - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
            score = best_dist * 0.5 + road_dist * 0.5
        else:
            score = best_dist

        order = np.argsort(score)
        step_off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- PHASE 9: EXTEND ROADS from existing roads near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 10: WIRE extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    power_src = wm | pm
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        else: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d, best_k = 1e9, 0
        stride = max(1, len(uzxs) // 30)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d, best_k = d, i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 11: ROAD extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        else: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d, best_k = 1e9, 0
        stride = max(1, len(usxs) // 30)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d, best_k = d, i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- PHASE 12: CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(10, 95, 15) for fx in range(10, 115, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        # Parks near zones
        zone_arr_y, zone_arr_x = np.where(zone_tiles)
        if len(zone_arr_x) > 0:
            for i in range(min(len(zone_arr_x), 60)):
                k = (step * 3 + i * 17) % len(zone_arr_x)
                zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 200:
        police_spots = [(px2, py2) for py2 in range(12, 92, 18) for px2 in range(12, 112, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        stadium_spots = [(sx, sy) for sy in range(15, 90, 28) for sx in range(15, 110, 32)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuke_spots = [(8, 8), (111, 8), (8, 91), (111, 91),
                      (60, 8), (60, 91), (8, 50), (111, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (114, 50), (55, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (114, 93), (60, 97), (5, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
    if len(zone_arr_x2) > 0:
        k = (step * 19) % len(zone_arr_x2)
        zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants across the middle row with wire spines and flanking roads."""
    actions = []
    for px in [15, 45, 75, 105]:
        actions.append((Tool.COALPOWER, px, 50))
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, 50 + dy))
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, 50 + dy))
            actions.append((Tool.ROAD, px + 1, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 4 columns x 5 rows = 20 anchors
    anchors = []
    for row_y in [10, 30, 50, 70, 90]:
        for col_x in [15, 45, 75, 105]:
            anchors.append((col_x, row_y, col_x, col_x - 1, col_x + 1))

    def num_active():
        if pop < 30:   return 1
        if pop < 100:  return 2
        if pop < 250:  return 4
        if pop < 500:  return 6
        if pop < 900:  return 8
        if pop < 1500: return 12
        if pop < 2500: return 16
        if pop < 4000: return 18
        return 20

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS for each active anchor cluster ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Try placing plant
        for r in range(0, 8):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if r > 0 and abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE BUILDING (vertical) ----
    spine_half = min(25, 8 + pop // 15)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows ----
    if n_active >= 5:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                _, py1, _, _, _ = col_anchors[i]
                _, py2, _, _, _ = col_anchors[i + 1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 30:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            for horiz_y in [yl - 2, yl + 2]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.2
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (placed reactively near zones) ----
    zone_map = resm | comm | indm
    zone_ys2, zone_xs2 = np.where(zone_map)

    if pop > 80:
        fire_spots = []
        for yl in [10, 30, 50, 70, 90]:
            for xl in [10, 30, 55, 80, 105]:
                fire_spots.append((xl, yl))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = []
        for yl in [15, 35, 55, 75, 95]:
            for xl in [20, 50, 80, 110]:
                police_spots.append((xl, yl))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [
            (25, 5), (65, 5), (105, 5),
            (25, 95), (65, 95), (105, 95),
            (5, 25), (5, 50), (5, 75),
            (115, 25), (115, 50), (115, 75),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 50), (115, 50),
            (5, 95), (60, 95), (115, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 200 and len(zone_xs2) > 0:
        for i in range(min(len(zone_xs2), 25)):
            k = (step * 3 + i * 17) % len(zone_xs2)
            zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
            for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                nx2, ny2 = zx2 + dx2, zy2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    if len(zone_xs2) > 0:
        k = (step * 19) % len(zone_xs2)
        zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Dense grid of neighborhoods across the whole map
# 8 cols x 7 rows = 56 neighborhoods, spaced 14 apart
# Wire backbone connecting all plants, roads flanking wires
# Aggressive zone placement with 40/30/30 RES/COM/IND mix
# Civic services placed reactively as population grows

def init(obs, state):
    """Bootstrap: two central coal plants + wire cross + initial roads."""
    actions = []
    # Two power plants side by side near center
    actions.append((Tool.COALPOWER, 55, 50))
    actions.append((Tool.COALPOWER, 65, 50))
    # Horizontal wire connecting them and extending
    for x in range(50, 71):
        if x not in (55, 65):
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 55, y))
            actions.append((Tool.WIRE, 65, y))
    # Roads flanking spines
    for y in range(44, 57):
        actions.append((Tool.ROAD, 54, y))
        actions.append((Tool.ROAD, 56, y))
        actions.append((Tool.ROAD, 64, y))
        actions.append((Tool.ROAD, 66, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Dense 8x7 neighborhood grid covering whole map
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 22, 36, 50, 64, 78, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 5
        if pop < 500:   return 10
        if pop < 1000:  return 18
        if pop < 2000:  return 28
        if pop < 4000:  return 40
        if pop < 8000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly across the list
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS at each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
        y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find nearest empty spot
            for r in range(15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE BACKBONE - connect all plants via horizontal/vertical lines ----
    # For each hood, extend wire from plant along its row and column
    spine_range = 8
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical wire at hx from hood
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal wire at hy from hood
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS (14-tile spacing) ----
    for (hx1, hy1) in active_hoods:
        # Right neighbor
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx2 == hx1 + 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Bottom neighbor
            if hx1 == hx2 and hy2 == hy1 + 14:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines (2 roads per spine) ----
    # Build nbr_power mask efficiently
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # For current hood, place roads flanking the wire spines
    hx, hy = active_hoods[hood_idx]
    for rx in [hx - 1, hx + 1]:
        if not ib(rx, hy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]) and bool(nbr_power[ry, rx]):
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

    for ry2 in [hy - 1, hy + 1]:
        if not ib(hx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]) and bool(nbr_power[ry2, rcx]):
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build road neighbor mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (closed-loop, based on pop) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 16) for fy in range(10, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 20) for py2 in range(14, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 25), (90, 25), (30, 75), (90, 75),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (50, 50), (70, 50), (40, 40), (80, 60)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(10, 92), (110, 92), (10, 8), (110, 8),
                    (60, 96), (60, 4), (30, 96), (90, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # Nuclear upgrades for high population
    if pop > 3000 and step % 4 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (60, 20), (60, 80), (15, 50), (105, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 5000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94),
                    (6, 40), (6, 65), (114, 40), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Compact, well-powered multi-neighborhood city builder
# Key improvements over parent:
# 1. Fixed init() that actually establishes power+roads before act() runs
# 2. Simpler, more reliable zone placement logic
# 3. Better power connectivity check
# 4. More balanced R/C/I mix

def init(obs, state):
    """Bootstrap: 3 power plants with wire+road spines across the map."""
    acts = []
    # Three power plants spread horizontally
    plants = [(30, 50), (60, 50), (90, 50)]
    for (px, py) in plants:
        acts.append((Tool.COALPOWER, px, py))
        # Wire horizontally from plant
        for dx in range(-3, 4):
            if dx == 0: continue
            acts.append((Tool.WIRE, px + dx, py))
        # Wire vertically from plant
        for dy in range(-3, 4):
            if dy == 0: continue
            acts.append((Tool.WIRE, px, py + dy))
        # Roads flanking plant
        acts.append((Tool.ROAD, px - 1, py - 2))
        acts.append((Tool.ROAD, px - 1, py - 1))
        acts.append((Tool.ROAD, px - 1, py))
        acts.append((Tool.ROAD, px - 1, py + 1))
        acts.append((Tool.ROAD, px - 1, py + 2))
    return acts


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Neighborhood layout: 5 columns x 4 rows = 20 neighborhoods
    hood_xs = [20, 40, 60, 80, 100]
    hood_ys = [20, 40, 60, 80]
    all_hoods = [(hx, hy) for hy in hood_ys for hx in hood_xs]

    # Unlock more hoods as population grows
    def n_active():
        if pop < 100: return 3
        if pop < 300: return 5
        if pop < 600: return 8
        if pop < 1000: return 12
        if pop < 2000: return 15
        return len(all_hoods)

    n = n_active()
    # Spread active hoods evenly
    step_sz = max(1, len(all_hoods) // n)
    active_hoods = all_hoods[::step_sz][:n]

    # ---- PHASE 1: Ensure each active hood has a power plant ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center if empty, else search nearby
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire spines from each plant outward ----
    for (hx, hy) in active_hoods:
        # Find actual plant location near hood center
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
        if len(plant_xs) == 0:
            continue
        px = int(plant_xs[0]) + x0
        py = int(plant_ys[0]) + y0

        # Extend wire horizontally and vertically from plant
        for target_x in range(max(2, hx-12), min(WORLD_W-2, hx+13)):
            if ib(target_x, py) and not bool(pm[py, target_x]):
                if bool(em[py, target_x]) and not bool(wm[py, target_x]):
                    return (Tool.WIRE, target_x, py)

        for target_y in range(max(2, hy-12), min(WORLD_H-2, hy+13)):
            if ib(px, target_y) and not bool(pm[target_y, px]):
                if bool(em[target_y, px]) and not bool(wm[target_y, px]):
                    return (Tool.WIRE, px, target_y)

    # ---- PHASE 3: Roads flanking wire spines ----
    # Build road columns at wire column ± 1
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
        if len(plant_xs) == 0:
            continue
        px = int(plant_xs[0]) + x0
        py = int(plant_ys[0]) + y0

        # Vertical wire spine at px -> roads at px-1 and px+1
        for rx in [px-1, px+1]:
            if not ib(rx, py): continue
            wire_rows = [r for r in range(max(2, hy-12), min(WORLD_H-2, hy+13))
                        if ib(px, r) and bool(wm[r, px])]
            for wr in wire_rows[(step % 4)::(4)]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        # Horizontal wire spine at py -> roads at py-1 and py+1
        for ry in [py-1, py+1]:
            if not ib(px, ry): continue
            wire_cols = [c for c in range(max(2, hx-12), min(WORLD_W-2, hx+13))
                        if ib(c, py) and bool(wm[py, c])]
            for wc in wire_cols[((step+2) % 4)::(4)]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # ---- PHASE 4: Zone placement ----
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    def pick_zone():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_zone(), zx, zy)

    # ---- PHASE 5: Extend roads from existing network ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 60)):
            k = (sk + off*7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx+dx2, ry+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_wire[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 6: Civic services ----
    if pop > 300:
        fire_locs = [(25,25),(55,25),(85,25),(25,55),(55,55),(85,55),(25,80),(55,80),(85,80)]
        for (sx, sy) in fire_locs:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 700:
        police_locs = [(35,35),(65,35),(95,35),(35,65),(65,65),(95,65),(35,85),(65,85)]
        for (sx, sy) in police_locs:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500 and step % 3 == 0:
        stadium_locs = [(50,45),(80,45),(50,70),(80,70)]
        for (sx, sy) in stadium_locs:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        sea_locs = [(10,95),(110,95),(10,5),(110,5)]
        for (sx,sy) in sea_locs:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airport_locs = [(60,8),(60,88)]
        for (sx,sy) in airport_locs:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 500 and step % 4 == 0:
        park_cands = np.where(em & nbr_road & nbr_wire)
        if len(park_cands[0]) > 0:
            idx = (step * 19) % len(park_cands[0])
            py2, px2 = int(park_cands[0][idx]), int(park_cands[1][idx])
            if ib(px2, py2):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 40)):
            k = (sk2 + off*5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious multi-cluster city policy
# Strategy: Build 4 major clusters (NW, NE, SW, SE quadrants) each with
# coal plant, wire grid, dense road network, and mixed zones.
# Closed-loop: reacts to population, powered zones, and tile_map each step.

def init(obs, state):
    """Bootstrap: place 2 coal plants and initial wire/road seeds."""
    actions = []
    # Primary plant NW cluster
    actions.append((Tool.COALPOWER, 25, 25))
    for dy in range(-2, 3):
        actions.append((Tool.WIRE, 27, 25 + dy))
    for dy in range(-2, 3):
        actions.append((Tool.ROAD, 26, 25 + dy))
        actions.append((Tool.ROAD, 28, 25 + dy))
    # Primary plant SE cluster
    actions.append((Tool.COALPOWER, 90, 70))
    for dy in range(-2, 3):
        actions.append((Tool.WIRE, 92, 70 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    total_steps = obs.n_steps

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Four major clusters: (plant_x, plant_y, wire_col, road_left, road_right, center_y)
    clusters = [
        (25, 25, 27, 26, 28, 25),   # NW
        (90, 25, 88, 87, 89, 25),   # NE
        (25, 70, 27, 26, 28, 70),   # SW
        (90, 70, 88, 87, 89, 70),   # SE
        (57, 25, 59, 58, 60, 25),   # N center
        (57, 70, 59, 58, 60, 70),   # S center
        (25, 48, 27, 26, 28, 48),   # W mid
        (90, 48, 88, 87, 89, 48),   # E mid
    ]

    def num_active():
        if pop < 50:   return 2
        if pop < 200:  return 3
        if pop < 500:  return 4
        if pop < 1000: return 5
        if pop < 2000: return 6
        if pop < 3500: return 7
        return 8

    active = clusters[:num_active()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr, cy) in active:
        has_plant = any(
            ib(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dx in range(-4, 5) for dy in range(-4, 5)
            if ib(px + dx, py + dy)
        )
        if not has_plant:
            for r in range(8):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE per cluster ----
    pop_span = min(30, 5 + pop // 30)
    for (px, py, wc, rl, rr, cy) in active:
        if not ib(wc, py): continue
        spine_top = max(2, cy - pop_span)
        spine_bot = min(WORLD_H - 3, cy + pop_span)

        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            # Seed wire adjacent to plant
            for dy2 in range(-3, 4):
                ny = py + dy2
                if ib(wc, ny) and not bool(pm[ny, wc]) and bool(em[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connections at cluster Y levels ----
    # Connect NW-NE, SW-SE, NW-SW, NE-SE, and center connections
    h_connections = [
        (27, 88, 25),   # NW to NE top
        (27, 88, 70),   # SW to SE bottom
        (27, 59, 25),   # NW to N center
        (59, 88, 25),   # N center to NE
        (27, 59, 70),   # SW to S center
        (59, 88, 70),   # S center to SE
    ]
    if pop > 200:
        for (x1, x2, wy) in h_connections:
            for cx in range(x1, x2 + 1):
                if ib(cx, wy) and bool(em[wy, cx]) and not bool(pm[wy, cx]):
                    return (Tool.WIRE, cx, wy)

    # Vertical connections between same-column clusters
    v_connections = [
        (27, 25, 70),   # NW to SW
        (88, 25, 70),   # NE to SE
        (59, 25, 70),   # N to S center
    ]
    if pop > 400:
        for (vx, y1, y2) in v_connections:
            for cy2 in range(y1, y2 + 1):
                if ib(vx, cy2) and bool(em[cy2, vx]) and not bool(pm[cy2, vx]):
                    return (Tool.WIRE, vx, cy2)

    # ---- ROAD NETWORK ----
    # Horizontal roads at fixed Y levels connecting clusters
    road_rows = [20, 25, 30, 45, 48, 53, 65, 70, 75]
    for ry in road_rows:
        if not ib(0, ry): continue
        # Check if road needed in this row
        road_count = int(np.sum(rm[ry, :]))
        if road_count < 40:
            # Find a gap and fill it
            for cx in range(2, WORLD_W - 2):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    # Check wire nearby
                    has_wire_near = any(
                        ib(cx + ddx, ry + ddy) and (bool(wm[ry + ddy, cx + ddx]) or bool(pm[ry + ddy, cx + ddx]))
                        for ddx in range(-6, 7) for ddy in range(-6, 7)
                        if ib(cx + ddx, ry + ddy)
                    )
                    if has_wire_near:
                        return (Tool.ROAD, cx, ry)

    # Vertical roads (spines per cluster + cross-connections)
    road_cols = [22, 26, 28, 32, 55, 58, 60, 64, 84, 87, 89, 93]
    for rc in road_cols:
        if not ib(rc, 0): continue
        road_count = int(np.sum(rm[:, rc]))
        if road_count < 30:
            for ry2 in range(2, WORLD_H - 2):
                if ib(rc, ry2) and bool(em[ry2, rc]) and not bool(pm[ry2, rc]):
                    has_wire_near = any(
                        ib(rc + ddx, ry2 + ddy) and (bool(wm[ry2 + ddy, rc + ddx]) or bool(pm[ry2 + ddy, rc + ddx]))
                        for ddx in range(-6, 7) for ddy in range(-6, 7)
                        if ib(rc + ddx, ry2 + ddy)
                    )
                    if has_wire_near:
                        return (Tool.ROAD, rc, ry2)

    # Per-anchor flanking roads along wire spine
    for (px, py, wc, rl, rr, cy) in active:
        wire_rows2 = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        cycle = step % 4
        for wr in wire_rows2[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr2 = res_count / t
        # Target: 35% R, 35% C, 30% I
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road mask (within 2)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor wire/plant mask (within 6)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by proximity to active cluster wire columns
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (px, py, wc, rl, rr, cy) in active:
            d = np.abs(cxs_arr - wc).astype(float) + np.abs(cys_arr - cy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 150)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 150:
        fire_spots = [
            (40, 25), (72, 25), (40, 70), (72, 70),
            (57, 48), (25, 48), (90, 48),
            (15, 25), (105, 25), (15, 70), (105, 70),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (35, 20), (78, 20), (35, 75), (78, 75),
            (57, 38), (57, 60), (20, 38), (98, 38),
            (20, 60), (98, 60),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1200:
        stadiums = [(50, 47), (65, 47), (50, 52), (65, 52)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        # Add seaport and airport for big cities
        for (sx, sy) in [(10, 85), (100, 85)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire spines and road seeds."""
    actions = []
    # Left cluster plant at (30, 50)
    actions.append((Tool.COALPOWER, 30, 50))
    for dx in range(-6, 7):
        actions.append((Tool.WIRE, 30 + dx, 50))
    for dy in range(-6, 7):
        actions.append((Tool.WIRE, 30, 50 + dy))
    for dx in range(-6, 7):
        actions.append((Tool.ROAD, 30 + dx, 48))
        actions.append((Tool.ROAD, 30 + dx, 52))
    # Right cluster plant at (90, 50)
    actions.append((Tool.COALPOWER, 90, 50))
    for dx in range(-6, 7):
        actions.append((Tool.WIRE, 90 + dx, 50))
    for dy in range(-6, 7):
        actions.append((Tool.WIRE, 90, 50 + dy))
    for dx in range(-6, 7):
        actions.append((Tool.ROAD, 90 + dx, 48))
        actions.append((Tool.ROAD, 90 + dx, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 40% res, 35% com, 25% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return result
        # Use scipy-style dilation via loop
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Dense cluster grid: 5 columns x 4 rows covering the whole map
    cluster_cols = [15, 35, 60, 85, 105]
    cluster_rows = [15, 37, 62, 85]

    # Scale active clusters with population
    def active_clusters():
        if pop < 100:
            return [(30, 50), (90, 50)]
        if pop < 500:
            return [(30, 37), (90, 37), (30, 62), (90, 62)]
        if pop < 1500:
            return [(15, 37), (60, 37), (105, 37),
                    (15, 62), (60, 62), (105, 62)]
        if pop < 3000:
            return [(15, 15), (60, 15), (105, 15),
                    (15, 50), (60, 50), (105, 50),
                    (15, 85), (60, 85), (105, 85)]
        # Full 5x4 grid
        return [(cx, cy) for cy in cluster_rows for cx in cluster_cols]

    clusters = active_clusters()

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(15):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- EXTEND WIRE CROSSES FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(22, 6 + pop // 25)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH WIRE HORIZONTALLY ----
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        row_clusters = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 5])
        for i in range(len(row_clusters) - 1):
            c1, c2 = row_clusters[i], row_clusters[i + 1]
            for x in range(c1, c2 + 1):
                if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]) and not bool(wm[cy, x]):
                    return (Tool.WIRE, x, cy)

    # ---- CONNECT CLUSTERS WITH WIRE VERTICALLY ----
    for cx in active_cols_set:
        col_clusters = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 5])
        for i in range(len(col_clusters) - 1):
            r1, r2 = col_clusters[i], col_clusters[i + 1]
            for y in range(r1, r2 + 1):
                if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]) and not bool(wm[y, cx]):
                    return (Tool.WIRE, cx, y)

    # ---- BUILD ROAD GRID AROUND EACH CLUSTER ----
    # Use 4 road lines: cy-3, cy+3, cy-6, cy+6 for denser grid
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        road_offsets_y = [-3, 3]
        road_offsets_x = [-3, 3]
        if pop > 500:
            road_offsets_y = [-3, 3, -7, 7]
            road_offsets_x = [-3, 3, -7, 7]
        for road_y_off in road_offsets_y:
            road_y = cy + road_y_off
            if not ib(cx, road_y): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)
        for road_x_off in road_offsets_x:
            road_x = cx + road_x_off
            if not ib(road_x, cy): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    if pop > 150:
        for cy in active_rows_set:
            row_cx = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 8])
            for i in range(len(row_cx) - 1):
                c1, c2 = row_cx[i], row_cx[i + 1]
                for road_y in [cy - 4, cy + 4]:
                    if not (0 <= road_y < WORLD_H): continue
                    has_road = any(bool(rm[road_y, x]) for x in range(c1, c2 + 1) if ib(x, road_y))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    if pop > 300:
        for cx in active_cols_set:
            col_cy = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 8])
            for i in range(len(col_cy) - 1):
                r1, r2 = col_cy[i], col_cy[i + 1]
                for road_x in [cx - 4, cx + 4]:
                    if not (0 <= road_x < WORLD_W): continue
                    has_road = any(bool(rm[y, road_x]) for y in range(r1, r2 + 1) if ib(road_x, y))
                    if not has_road:
                        for y in range(r1, r2 + 1):
                            if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]):
                                return (Tool.ROAD, road_x, y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) +
                 np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(8, 96, 18) for fx in range(8, 116, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px, py) for py in range(10, 94, 20) for px in range(10, 114, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 7), (60, 7), (95, 7),
                         (25, 92), (60, 92), (95, 92)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Nuclear plants for high-pop areas
        nuke_spots = [(7, 15), (7, 50), (7, 85),
                      (113, 15), (113, 50), (113, 85),
                      (60, 7), (60, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 92), (115, 92), (5, 8), (115, 8)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 60)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

