def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: 40% res, 35% com, 25% ind (more commercial/industrial than parent)
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        # Vary by step to interleave types
        cycle = step % 20
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # PHASE 1: Dense power plant grid (every 16 tiles, tighter spacing)
    plant_grid = []
    for py in range(12, 92, 16):
        for px in range(12, 112, 16):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # PHASE 2: Wire grid — horizontal and vertical spines every 8 rows/cols
    # Connect power plants with a wire mesh
    wire_rows = list(range(12, 92, 8))
    wire_cols = list(range(12, 112, 8))

    # Lay horizontal wire spines
    for wy in wire_rows:
        for wx in range(5, 115):
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(rm[wy, wx]) and not bool(zone_tiles[wy, wx]):
                # Only if adjacent to existing power
                if bool(near_power[wy, wx]):
                    # Check if wire is needed (gap in spine)
                    if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                        return (Tool.WIRE, wx, wy)

    # Lay vertical wire spines
    for wx in wire_cols:
        for wy in range(5, 95):
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(rm[wy, wx]) and not bool(zone_tiles[wy, wx]):
                if bool(near_power[wy, wx]):
                    if not bool(wm[wy, wx]) and not bool(pm[wy, wx]):
                        return (Tool.WIRE, wx, wy)

    # PHASE 2b: Wire expansion toward uncovered plant grid points
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        uncovered = [(px, py) for px, py in plant_grid
                     if ib(px, py) and not bool(near_power[py, px])]
        if uncovered:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in uncovered)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire to unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 200)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # PHASE 3: Dense road grid every 6 tiles
    road_rows = list(range(8, 96, 6))
    road_cols = list(range(8, 115, 6))

    # Lay horizontal roads
    for ry in road_rows:
        for rx in range(5, 115):
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(wm[ry, rx]) and not bool(zone_tiles[ry, rx]):
                if bool(near_power[ry, rx]):
                    # Check adjacency to existing road
                    adj = False
                    for ddx in [-1, 1]:
                        if ib(rx+ddx, ry) and bool(rm[ry, rx+ddx]):
                            adj = True
                    for ddy in [-1, 1]:
                        if ib(rx, ry+ddy) and bool(rm[ry+ddy, rx]):
                            adj = True
                    if adj or rx == 5:
                        return (Tool.ROAD, rx, ry)

    # Lay vertical roads
    for rx in road_cols:
        for ry in range(5, 95):
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(wm[ry, rx]) and not bool(zone_tiles[ry, rx]):
                if bool(near_power[ry, rx]):
                    adj = False
                    for ddy in [-1, 1]:
                        if ib(rx, ry+ddy) and bool(rm[ry+ddy, rx]):
                            adj = True
                    for ddx in [-1, 1]:
                        if ib(rx+ddx, ry) and bool(rm[ry, rx+ddx]):
                            adj = True
                    if adj or ry == 5:
                        return (Tool.ROAD, rx, ry)

    # PHASE 3b: Road grid fallback
    road_grid_targets = []
    for gy in range(8, 95, 6):
        for gx in range(8, 114, 6):
            road_grid_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm
        road_cand[0:3, :] = False
        road_cand[WORLD_H-3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W-3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets = uncovered_road[:30]
            for i in range(min(len(rxs2), 300)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:5]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # PHASE 4: Zone placement — prefer commercial/industrial in core, residential on edges
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: distance from center (commercial in core, residential on edge)
        center_x, center_y = 60, 50
        dist_center = (np.abs(cxs_arr - center_x) + np.abs(cys_arr - center_y)).astype(float)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                rd_stride = max(1, len(road_xs) // 80)
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), rd_stride):
                    d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                    road_dist = np.minimum(road_dist, d)
                # Mixed score: place near roads, near existing zones, spread
                score = zone_dist * 0.3 + road_dist * 1.0 + dist_center * 0.05
            else:
                score = zone_dist + dist_center * 0.05
        else:
            score = dist_center

        # Pick zone type based on location: commercial near center, industrial on one side, res elsewhere
        order = np.argsort(score)
        off = (step * 17 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                # Location-based tool selection
                dx_c = abs(zx2 - center_x)
                dy_c = abs(zy2 - center_y)
                dist_c = dx_c + dy_c
                if dist_c < 20:
                    # Core: commercial
                    tool = Tool.COMMERCIAL
                elif zy2 > 65:
                    # South: industrial
                    tool = Tool.INDUSTRIAL
                else:
                    tool = pick_tool()
                return (tool, zx2, zy2)

    # PHASE 5: Civic services scaling with population
    if pop > 30:
        # Fire stations in a grid
        fire_grid = [(fx, fy) for fy in range(14, 90, 10) for fx in range(14, 110, 10)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]) and bool(near_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(16, 88, 12) for px2 in range(16, 108, 12)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]) and bool(near_road[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(px3, py3) for py3 in range(10, 92, 8) for px3 in range(10, 112, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (60, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuke_locs = [(60, 30), (20, 30), (100, 30), (60, 70), (20, 70), (100, 70)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85), (55, 10), (55, 88)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10, 50), (110, 50), (60, 10), (60, 88)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend road from plant
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        for i in range(len(pwr_xs)):
            k = (step * 7 + i) % len(pwr_xs)
            px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
            for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (4, 4), (-4, 4)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from plant
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a 2x3 grid with vertical wire spines and flanking roads."""
    actions = []
    # 3 columns x 2 rows of power plants
    for px in [20, 60, 100]:
        for py in [30, 70]:
            actions.append((Tool.COALPOWER, px, py))
            # Vertical wire spine
            for dy in range(-8, 9):
                actions.append((Tool.WIRE, px, py + dy))
            # Flanking roads
            for dy in range(-8, 9):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connections at plant rows
    for py in [30, 70]:
        for x in range(21, 60):
            actions.append((Tool.WIRE, x, py))
        for x in range(61, 100):
            actions.append((Tool.WIRE, x, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- DYNAMIC ANCHOR SYSTEM ----
    # 12 anchors in 3 cols x 4 rows, scaled by population
    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 40, 60, 80]:
            # wc=wire col, rl=road left, rr=road right
            all_anchors.append((col_x, row_y, col_x, col_x - 1, col_x + 1))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 3
        if pop < 300:   return 4
        if pop < 500:   return 6
        if pop < 800:   return 8
        if pop < 1200:  return 10
        return 12

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    spine_half = min(35, 10 + pop // 10)

    # ---- 1. ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- 2. VERTICAL WIRE SPINES ----
    for (px, py, wc, rl, rr) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            _, _, wc1, _, _ = row_anchors[i]
            _, _, wc2, _, _ = row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- 4. VERTICAL WIRE connecting anchor rows in same column ----
    wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
    for wc in wc_cols:
        col_anchors = sorted(
            [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
            key=lambda a: a[1]
        )
        for i in range(len(col_anchors) - 1):
            _, py1, _, _, _ = col_anchors[i]
            _, py2, _, _, _ = col_anchors[i + 1]
            for cy in range(py1 + 1, py2):
                if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                    return (Tool.WIRE, wc, cy)

    # ---- 5. FLANKING ROADS along wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 6. HORIZONTAL ROADS at anchor y-levels (±3 offset) ----
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[3]
        )
        if len(row_anchors) < 1:
            continue
        rl1 = row_anchors[0][3]
        rr_last = row_anchors[-1][4]
        for horiz_y in [yl - 3, yl + 3]:
            if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                continue
            for cx in range(rl1, rr_last + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- 7. VERTICAL ROADS connecting row levels ----
    if len(y_levels) >= 2:
        for col_x in [20, 60, 100]:
            for rx in [col_x - 3, col_x + 3]:
                if not ib(rx, 2) or not ib(rx, WORLD_H - 3):
                    continue
                yl_list = sorted(y_levels)
                for i in range(len(yl_list) - 1):
                    y1v = yl_list[i]
                    y2v = yl_list[i + 1]
                    for cy in range(y1v, y2v + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- 8. EXTRA HORIZONTAL ROADS between columns ----
    if pop > 100:
        for yl in y_levels:
            for horiz_y in [yl - 6, yl + 6]:
                for cx in range(3, WORLD_W - 3):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- 9. BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- 10. ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = (np.abs(cxs - wc).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)

        # Spread outward as population grows
        if pop > 300:
            corners = [(15, 15), (105, 15), (15, 85), (105, 85),
                       (60, 15), (60, 85), (15, 50), (105, 50)]
            min_corner = np.full(len(cxs), 999999.0)
            for cx2, cy2 in corners:
                d = (np.abs(cxs - cx2).astype(float) +
                     np.abs(cys - cy2).astype(float))
                min_corner = np.minimum(min_corner, d)
            spread_w = min(0.8, (pop - 300) / 2000.0)
            best_dist = best_dist * (1.0 - spread_w) + min_corner * spread_w

        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- 11. EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- 12. CIVIC SERVICES (population-gated) ----
    if pop > 60:
        fire_spots = [
            (8, 10), (35, 10), (75, 10), (108, 10),
            (8, 30), (35, 30), (75, 30), (108, 30),
            (8, 50), (35, 50), (75, 50), (108, 50),
            (8, 70), (35, 70), (75, 70), (108, 70),
            (8, 90), (35, 90), (75, 90), (108, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (22, 10), (55, 10), (88, 10),
            (22, 30), (55, 30), (88, 30),
            (22, 50), (55, 50), (88, 50),
            (22, 70), (55, 70), (88, 70),
            (22, 90), (55, 90), (88, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 500:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 50), (50, 50), (90, 50),
            (10, 90), (50, 90), (90, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800 and funds > 5000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            found = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    nx3, ny3 = nx2 + dx, ny2 + dy
                    if ib(nx3, ny3) and pm[ny3, nx3]:
                        found = True
                        break
                if found:
                    break
            if not found and ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        airport_spots = [(55, 6), (5, 50), (115, 50), (55, 94)]
        for ax, ay in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        seaport_spots = [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]
        for sx2, sy2 in seaport_spots:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- 13. FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- 14. LAST RESORT: place road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder
# Strategy: Dense grid layout with power spines, road grids, and reactive zone placement
# Uses a phase-based approach to systematically build infrastructure then zones

def init(obs, state):
    """Bootstrap 3 coal plants in a line with initial wires and roads."""
    actions = []
    # Three initial plants spread across the map
    plants = [(20, 50), (60, 50), (100, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        actions.append((Tool.WIRE, px, py - 2))
        actions.append((Tool.WIRE, px, py + 2))
        actions.append((Tool.WIRE, px - 2, py))
        actions.append((Tool.WIRE, px + 2, py))
        actions.append((Tool.ROAD, px - 4, py))
        actions.append((Tool.ROAD, px + 4, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # 15 cluster centers in a 5x3 grid covering the map well
    ALL_CLUSTERS = [
        (12, 20), (36, 20), (60, 20), (84, 20), (108, 20),
        (12, 50), (36, 50), (60, 50), (84, 50), (108, 50),
        (12, 80), (36, 80), (60, 80), (84, 80), (108, 80),
    ]

    def num_active():
        if pop < 20:   return 2
        if pop < 80:   return 3
        if pop < 200:  return 5
        if pop < 400:  return 7
        if pop < 700:  return 10
        if pop < 1200: return 12
        return 15

    n_active = num_active()
    active_centers = ALL_CLUSTERS[:n_active]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 35% ind, 25% com, 40% res
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.35:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- ENSURE POWER PLANTS at each active cluster ---
    for (px, py) in active_centers:
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(1, 10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # --- BUILD WIRE SPINES: horizontal backbone connecting all clusters in same row ---
    row_ys = sorted(set(py for (px, py) in active_centers))
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl])
        if len(row_cs) < 2:
            continue
        x_start = row_cs[0][0]
        x_end = row_cs[-1][0]
        # Lay horizontal wire backbone
        for cx in range(x_start, x_end + 1):
            if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting rows ---
    col_xs = sorted(set(px for (px, py) in active_centers))
    for xc in col_xs:
        col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc])
        if len(col_cs) < 2:
            continue
        for i in range(len(col_cs) - 1):
            y_start = col_cs[i][1]
            y_end = col_cs[i + 1][1]
            for cy in range(y_start, y_end + 1):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # --- BUILD ROAD GRID around each cluster ---
    spine_half = min(12, 4 + pop // 30)
    for (px, py) in active_centers:
        spine_top = max(3, py - spine_half)
        spine_bot = min(WORLD_H - 4, py + spine_half)
        left_spine = max(3, py - spine_half)
        right_spine = min(WORLD_H - 4, py + spine_half)

        # Left road
        for ry in range(spine_top, spine_bot + 1):
            rx = px - 6
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)
        # Right road
        for ry in range(spine_top, spine_bot + 1):
            rx = px + 6
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)
        # Inner left road
        for ry in range(spine_top, spine_bot + 1):
            rx = px - 3
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)
        # Inner right road
        for ry in range(spine_top, spine_bot + 1):
            rx = px + 3
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # --- HORIZONTAL ROADS between clusters ---
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl])
        if len(row_cs) < 2:
            continue
        x_left = max(3, row_cs[0][0] - 7)
        x_right = min(WORLD_W - 4, row_cs[-1][0] + 7)
        for offset in [-5, 5, -8, 8, -11, 11]:
            hy = yl + offset
            if not ib(x_left, hy) or not ib(x_right, hy):
                continue
            for cx in range(x_left, x_right + 1):
                if ib(cx, hy) and bool(em[hy, cx]) and not bool(pm[hy, cx]):
                    return (Tool.ROAD, cx, hy)

    # --- VERTICAL ROADS connecting row roads ---
    if n_active >= 5:
        for xc in col_xs:
            col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc])
            if len(col_cs) < 2:
                continue
            for i in range(len(col_cs) - 1):
                y_start = col_cs[i][1]
                y_end = col_cs[i + 1][1]
                for vroad_x_off in [-9, 9, -12, 12]:
                    vx = xc + vroad_x_off
                    for cy in range(y_start - 8, y_end + 8):
                        if ib(vx, cy) and bool(em[cy, vx]) and not bool(pm[cy, vx]):
                            return (Tool.ROAD, vx, cy)

    # --- BUILD NEIGHBOR MASKS for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT: near roads and wires ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_centers:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary starting position to avoid always picking same spot
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # --- CIVIC SERVICES ---
    if pop > 50:
        fire_spots = []
        for yl in [12, 25, 38, 50, 62, 75, 88]:
            for xl in [8, 24, 48, 72, 96, 114]:
                fire_spots.append((xl, yl))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = []
        for yl in [15, 35, 55, 75, 92]:
            for xl in [10, 30, 55, 80, 110]:
                police_spots.append((xl, yl))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (20, 5), (60, 5), (100, 5),
            (20, 94), (60, 94), (100, 94),
            (3, 35), (3, 65), (115, 35), (115, 65),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (3, 5), (3, 95), (117, 5), (117, 95),
            (60, 5), (60, 95), (3, 50), (117, 50),
            (30, 5), (90, 5), (30, 94), (90, 94),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for asp in [(55, 5), (5, 50), (114, 50), (55, 93), (5, 5), (114, 5), (5, 94), (114, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2000:
        for sp in [(3, 93), (116, 93), (60, 96), (3, 7), (116, 7), (60, 3)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # Parks to boost land value near zones
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (4, 0), (-4, 0), (0, 4), (0, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- EXTEND WIRE from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: road near zone
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (4, 0), (-4, 0)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Final fallback: place coal plant at most sparse active cluster
    for (px, py) in active_centers:
        for r in range(2, 8):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

