def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # 60% RES, 20% COM, 20% IND
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire grid lines (every 10 rows/cols)
    wire_rows = list(range(5, 100, 10))
    wire_cols = list(range(5, 120, 10))

    # Road grid lines (offset 5 from wire lines)
    road_rows = list(range(10, 100, 10))
    road_cols = list(range(10, 120, 10))

    # --- Phase 1: Ensure power plants at corners and sub-quadrants ---
    plant_targets = [
        (60, 50),  # center
        (20, 20), (60, 20), (100, 20),  # top row
        (20, 50), (100, 50),             # middle sides
        (20, 80), (60, 80), (100, 80),  # bottom row
        (40, 35), (80, 35), (40, 65), (80, 65),  # inner quadrants
    ]

    if funds > 3000:
        for ppx, ppy in plant_targets:
            if not ib(ppx, ppy):
                continue
            # Check if plant already exists nearby
            found = False
            for dy in range(-7, 8):
                for dx in range(-7, 8):
                    nx, ny = ppx + dx, ppy + dy
                    if ib(nx, ny) and pm[ny, nx]:
                        found = True
                        break
                if found:
                    break
            if not found:
                return (Tool.COALPOWER, ppx, ppy)

    # --- Phase 2: Wire infrastructure - extend existing wires ---
    # Build horizontal wire lines
    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            # Seed from nearest plant in same row
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                dists = np.abs(pys - wr) + np.abs(pxs - 60)
                best = np.argmin(dists)
                bx, by = int(pxs[best]), int(pys[best])
                if ib(bx, wr) and em[wr, bx]:
                    return (Tool.WIRE, bx, wr)
            continue
        indices = np.where(row_has)[0]
        # Extend leftward
        left = int(indices[0])
        if left > 1:
            nx = left - 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Extend rightward
        right = int(indices[-1])
        if right < WORLD_W - 2:
            nx = right + 1
            if ib(nx, wr) and em[wr, nx]:
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left, right + 1):
            if ib(x, wr) and em[wr, x] and not pm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Build vertical wire lines
    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        if top > 1:
            ny = top - 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        bot = int(indices[-1])
        if bot < WORLD_H - 2:
            ny = bot + 1
            if ib(wc, ny) and em[ny, wc]:
                return (Tool.WIRE, wc, ny)
        for y in range(top, bot + 1):
            if ib(wc, y) and em[y, wc] and not pm[y, wc]:
                return (Tool.WIRE, wc, y)

    # --- Phase 3: Road infrastructure ---
    # Build horizontal roads
    for rr in road_rows:
        row_road = rm[rr, :]
        if not row_road.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            # seed from center outward
            for sx in [60, 40, 80, 20, 100]:
                if ib(sx, rr) and em[rr, sx] and not pm[rr, sx]:
                    return (Tool.ROAD, sx, rr)
            continue
        indices = np.where(row_road)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2:
            nx = left - 1
            if ib(nx, rr) and em[rr, nx] and not pm[rr, nx]:
                return (Tool.ROAD, nx, rr)
        if right < WORLD_W - 3:
            nx = right + 1
            if ib(nx, rr) and em[rr, nx] and not pm[rr, nx]:
                return (Tool.ROAD, nx, rr)
        for x in range(left, right + 1):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_road = rm[:, rc]
        if not col_road.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            for sy in [50, 30, 70, 15, 85]:
                if ib(rc, sy) and em[sy, rc] and not pm[sy, rc]:
                    return (Tool.ROAD, rc, sy)
            continue
        indices = np.where(col_road)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2:
            ny = top - 1
            if ib(rc, ny) and em[ny, rc] and not pm[ny, rc]:
                return (Tool.ROAD, rc, ny)
        if bot < WORLD_H - 3:
            ny = bot + 1
            if ib(rc, ny) and em[ny, rc] and not pm[ny, rc]:
                return (Tool.ROAD, rc, ny)
        for y in range(top, bot + 1):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # --- Phase 4: Zone placement ---
    zone_tiles = resm | comm | indm

    # Compute near-road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute near-wire mask (within 3 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate cells: empty, near road, near wire, not at edges
    cand = em & nbr_road & nbr_wire
    cand[0:4, :] = False
    cand[WORLD_H - 4:, :] = False
    cand[:, 0:4] = False
    cand[:, WORLD_W - 4:] = False
    # Also exclude cells too close to power plants
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            cand[r0:r1, c0:c1] &= ~pm[sr0:sr1, sc0:sc1]

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        # Score: prefer spots near existing zones (cluster), but also spread
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 300)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                # Prefer clusters but not too tight
                score = np.where(zone_dist < 4, zone_dist + 100, zone_dist)
                score = -score  # closer is better, but not overlapping
            else:
                # Start near center
                score = -(np.abs(cxs_arr - 60).astype(float) +
                          np.abs(cys_arr - 50).astype(float))
        else:
            score = -(np.abs(cxs_arr - 60).astype(float) +
                      np.abs(cys_arr - 50).astype(float))

        # Add jitter to avoid always picking same spot
        jitter = ((cxs_arr * 7 + cys_arr * 13 + step * 3) % 7).astype(float)
        score = score - jitter * 0.5

        order = np.argsort(-score)
        tool = pick_tool()
        checked = 0
        for i in order:
            if checked > 500:
                break
            zx2, zy2 = int(cxs_arr[i]), int(cys_arr[i])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)
            checked += 1

    # --- Phase 5: Civic services based on population ---
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(15, 95, 15)
                     for fx in range(15, 115, 15)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(18, 92, 18)
                       for px2 in range(18, 112, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(8, 95, 8)
                     for pkx in range(8, 115, 8)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300 and funds > 3000:
        stadium_locs = [
            (30, 25), (90, 25), (30, 75), (90, 75),
            (60, 15), (60, 85), (15, 50), (105, 50),
            (45, 40), (75, 40), (45, 60), (75, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            found = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    nx2, ny2 = npx + dx, npy + dy
                    if ib(nx2, ny2) and pm[ny2, nx2]:
                        found = True
                        break
                if found:
                    break
            if not found and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600 and funds > 5000:
        airport_locs = [(10, 10), (110, 10), (10, 90), (110, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 800 and funds > 3000:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: wire outward from plants ---
    pys_arr, pxs_arr = np.where(pm)
    if len(pxs_arr) > 0:
        sk = (step * 11) % len(pxs_arr)
        for offset in range(min(len(pxs_arr), 40)):
            k = (sk + offset * 7) % len(pxs_arr)
            px2, py2 = int(pxs_arr[k]), int(pys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0),
                             (1, 1), (-1, 1), (1, -1), (-1, -1)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Fallback: road near wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(0, 3), (0, -3), (3, 0), (-3, 0),
                             (0, 4), (0, -4), (4, 0), (-4, 0),
                             (0, 5), (0, -5), (5, 0), (-5, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire crosses and flanking roads."""
    actions = []
    for cx, cy in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dx in range(-5, 6):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, cx + dx, cy - 1))
            actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Dense 10x8 = 80 neighborhood grid across full map
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 20, 32, 44, 56, 68, 80, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 16
        if pop < 800:   return 24
        if pop < 1500:  return 35
        if pop < 3000:  return 50
        if pop < 6000:  return 65
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (vertical + horizontal through each hood) ----
    spine_r = 11
    # Process a rotating subset each step to spread work
    n_hoods = max(len(active_hoods), 1)
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Allow roughly half hoods per step, rotating
        if (step + idx_h) % n_hoods >= (n_hoods // 2 + 2):
            continue

        # Vertical spine at column hx
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Check adjacency to power (wire or plant)
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
            # Check horizontal adjacency
            for adj_dx in [-1, 1]:
                ax = hx + adj_dx
                if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal spine at row hy
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)
            for adj_dy in [-1, 1]:
                ay = hy + adj_dy
                if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Connect horizontally to right neighbor
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Connect vertically to bottom neighbor
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 14:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Roads at hx-1 and hx+1 flanking vertical spine
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

        # Roads at hy-1 and hy+1 flanking horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (wire or plant within 7 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (16, 16), (40, 16), (64, 16), (88, 16), (112, 16),
            (16, 32), (40, 32), (64, 32), (88, 32), (112, 32),
            (16, 48), (40, 48), (64, 48), (88, 48), (112, 48),
            (16, 64), (40, 64), (64, 64), (88, 64), (112, 64),
            (16, 80), (40, 80), (64, 80), (88, 80), (112, 80),
            (8, 96), (32, 96), (56, 96), (80, 96), (104, 96),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (28, 24), (56, 24), (84, 24), (112, 24),
            (14, 44), (42, 44), (70, 44), (98, 44),
            (28, 60), (56, 60), (84, 60), (112, 60),
            (14, 76), (42, 76), (70, 76), (98, 76),
            (28, 90), (56, 90), (84, 90), (112, 90),
            (6, 8), (30, 8), (54, 8), (78, 8), (102, 8),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (70, 30), (110, 30),
            (10, 55), (50, 55), (90, 55),
            (30, 75), (70, 75), (110, 75),
            (50, 10), (90, 10), (10, 90), (110, 90),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6, 88), (114, 88), (6, 10), (114, 10), (60, 6), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (5, 48), (113, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones to boost land value ----
    if pop > 200 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder
# Strategy: Multiple power plants across the map, dense grid of zones,
# roads forming a grid network, progressive expansion based on population

def init(obs, state):
    """Bootstrap: 3 coal plants at different map locations + initial wires/roads."""
    actions = []
    # Plant 1: center
    actions.append((Tool.COALPOWER, 60, 50))
    # Plant 2: upper-left quadrant
    actions.append((Tool.COALPOWER, 25, 25))
    # Plant 3: lower-right quadrant
    actions.append((Tool.COALPOWER, 95, 75))

    # Wire from center plant
    for dx in range(-4, 5):
        if dx != 0:
            actions.append((Tool.WIRE, 60 + dx, 50))
    for dy in range(-4, 5):
        if dy != 0:
            actions.append((Tool.WIRE, 60, 50 + dy))

    # Initial roads near center plant
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 58, 50 + dy))
        actions.append((Tool.ROAD, 62, 50 + dy))
    for dx in range(-3, 4):
        actions.append((Tool.ROAD, 60 + dx, 48))
        actions.append((Tool.ROAD, 60 + dx, 52))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- NEIGHBORHOOD GRID: 6 cols x 5 rows = 30 neighborhoods ----
    # Each neighborhood has its own power plant + road grid + zones
    nh_cols = [15, 35, 55, 75, 95, 110]
    nh_rows = [12, 28, 50, 72, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Power plant locations: one near each pair of neighborhoods
    plant_targets = [
        (15, 12), (55, 12), (95, 12),
        (15, 50), (60, 50), (95, 50),
        (15, 88), (55, 88), (95, 88),
        (35, 28), (75, 28), (35, 72), (75, 72)
    ]

    def num_active():
        if pop < 100:   return 3
        if pop < 500:   return 6
        if pop < 1500:  return 10
        if pop < 3000:  return 16
        if pop < 6000:  return 22
        if pop < 10000: return 27
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = max(len(all_hoods) / max(n_active, 1), 1)
    active_hoods = [all_hoods[int(i * step_size) % len(all_hoods)] for i in range(n_active)]

    # Number of active plants scales with neighborhoods
    n_plants = min(max(n_active // 3 + 1, 1), len(plant_targets))
    active_plants = plant_targets[:n_plants]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find nearest empty spot to target
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD PROXIMITY MASKS ----
    # Power proximity (within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Road proximity (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 2: BUILD WIRE GRID connecting plants to neighborhoods ----
    # Each step, pick a plant and extend wire toward a nearby uncovered hood
    plant_ys, plant_xs = np.where(pm)

    if len(plant_xs) > 0:
        # Pick a plant based on step
        pidx = step % len(plant_xs)
        ppx, ppy = int(plant_xs[pidx]), int(plant_ys[pidx])

        # Find nearest hood without power
        best_hood = None
        best_dist = 9999
        for (hx, hy) in active_hoods:
            if not bool(nbr_power[hy, hx]):
                d = abs(hx - ppx) + abs(hy - ppy)
                if d < best_dist:
                    best_dist = d
                    best_hood = (hx, hy)

        if best_hood is None:
            # All hoods powered, extend wire toward nearest hood anyway
            best_dist = 9999
            for (hx, hy) in active_hoods:
                d = abs(hx - ppx) + abs(hy - ppy)
                if d < best_dist:
                    best_dist = d
                    best_hood = (hx, hy)

        if best_hood:
            thx, thy = best_hood
            # Route wire: first horizontal, then vertical
            # Find the current wire frontier toward hood
            # Horizontal leg
            if ppx != thx:
                wire_dir = 1 if thx > ppx else -1
                # Find furthest existing wire/plant along this path
                frontier_x = ppx
                for wx in range(ppx, thx + wire_dir, wire_dir):
                    if ib(wx, ppy) and (bool(wm[ppy, wx]) or bool(pm[ppy, wx])):
                        frontier_x = wx
                next_x = frontier_x + wire_dir
                if ib(next_x, ppy) and bool(em[ppy, next_x]) and not bool(pm[ppy, next_x]):
                    return (Tool.WIRE, next_x, ppy)

            # Vertical leg
            if ppy != thy:
                wire_dir = 1 if thy > ppy else -1
                frontier_y = ppy
                for wy in range(ppy, thy + wire_dir, wire_dir):
                    if ib(thx, wy) and (bool(wm[wy, thx]) or bool(pm[wy, thx])):
                        frontier_y = wy
                next_y = frontier_y + wire_dir
                if ib(thx, next_y) and bool(em[next_y, thx]) and not bool(pm[next_y, thx]):
                    return (Tool.WIRE, thx, next_y)

    # ---- PHASE 3: BUILD ROAD GRID ----
    # Create a road grid: horizontal roads at certain y, vertical roads at certain x
    # Road grid spaced every 6 tiles
    road_xs = list(range(9, WORLD_W - 3, 10))
    road_ys = list(range(9, WORLD_H - 3, 10))

    # Build horizontal roads in powered areas
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find roads to build near this hood: horizontal spine at hy-2, hy+2
    for ry in [hy - 2, hy + 2, hy - 4, hy + 4]:
        if not ib(hx, ry): continue
        # Build road from hx-8 to hx+8 at ry
        for rdx in range(-8, 9):
            rx = hx + rdx
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and bool(nbr_power[ry, rx]):
                # Check there's existing road adjacent or it's near a wire
                if bool(nbr_road[ry, rx]) or (abs(rdx) <= 2):
                    return (Tool.ROAD, rx, ry)

    # Vertical road spines near each hood
    hood_idx2 = (step + 7) % max(len(active_hoods), 1)
    hx2, hy2 = active_hoods[hood_idx2]
    for rx2 in [hx2 - 2, hx2 + 2, hx2 - 4, hx2 + 4]:
        if not ib(rx2, hy2): continue
        for rdy in range(-8, 9):
            ry2 = hy2 + rdy
            if not ib(rx2, ry2): continue
            if bool(em[ry2, rx2]) and bool(nbr_power[ry2, rx2]):
                if bool(nbr_road[ry2, rx2]) or (abs(rdy) <= 2):
                    return (Tool.ROAD, rx2, ry2)

    # ---- PHASE 4: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 35% RES, 35% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx3, hy3) in active_hoods:
            d = np.abs(cxs - hx3) + np.abs(cys - hy3)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary starting position based on step for diversity
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 5: EXTEND ROADS INTO POWERED AREAS ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 13) % len(road_xs_arr)
        for offset2 in range(min(len(road_xs_arr), 150)):
            k = (step_k + offset2 * 7) % len(road_xs_arr)
            rx3, ry3 = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- PHASE 6: EXTEND WIRE from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % len(wire_xs_arr)
        for offset3 in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset3 * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            # Extend toward nearest unpowered hood
            best_h = None
            best_d = 9999
            for (hx4, hy4) in active_hoods:
                if not bool(nbr_power[hy4, hx4]):
                    d = abs(hx4 - wx3) + abs(hy4 - wy3)
                    if d < best_d:
                        best_d = d
                        best_h = (hx4, hy4)
            if best_h:
                thx2, thy2 = best_h
                dx4 = 1 if thx2 > wx3 else (-1 if thx2 < wx3 else 0)
                dy4 = 1 if thy2 > wy3 else (-1 if thy2 < wy3 else 0)
                # Prefer horizontal movement first
                if dx4 != 0:
                    nx4, ny4 = wx3 + dx4, wy3
                else:
                    nx4, ny4 = wx3, wy3 + dy4
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    return (Tool.WIRE, nx4, ny4)
            else:
                # Just extend in any empty direction
                for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx4, ny4 = wx3 + dx4, wy3 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                        return (Tool.WIRE, nx4, ny4)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 20) for fy in range(15, WORLD_H, 20)]
        for i in range(len(fire_spots)):
            sx, sy = fire_spots[(step // 2 + i) % len(fire_spots)]
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px5, py5) for px5 in range(20, WORLD_W, 25) for py5 in range(20, WORLD_H, 25)]
        for i in range(len(police_spots)):
            sx, sy = police_spots[(step // 3 + i) % len(police_spots)]
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(30, 30), (90, 30), (30, 70), (90, 70), (60, 50),
                         (15, 50), (105, 50), (60, 15), (60, 85)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaport_spots = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airport_spots = [(40, 6), (80, 6), (40, 94), (80, 94), (6, 40), (6, 70), (114, 40)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR UPGRADE ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (25, 25), (95, 25), (25, 75), (95, 75),
                         (45, 50), (75, 50), (60, 30), (60, 70), (15, 50), (105, 50)]
        for (nx5, ny5) in nuclear_spots:
            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                return (Tool.NUCLEARPOWER, nx5, ny5)

    # ---- PARKS ----
    if pop > 100 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py6, px6 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px6, py6) and bool(em[py6, px6]):
                return (Tool.PARK, px6, py6)

    # ---- FALLBACK: place more coal plants near uncovered hoods ----
    for (hx6, hy6) in active_hoods:
        if not bool(nbr_power[hy6, hx6]):
            for r in range(0, 8):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r or r == 0:
                            nx6, ny6 = hx6 + dx6, hy6 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

# High-reactivity closed-loop city builder
# Strategy: Dense neighborhood grid covering full map, aggressive zone placement,
# proper power network, many civic services, adaptive growth

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + flanking roads."""
    actions = []
    cx, cy = 60, 50
    # Plant at center
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along vertical spine
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Flanking roads along horizontal spine
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions[:20]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- DENSE NEIGHBORHOOD GRID: 8 cols x 7 rows = 56 neighborhoods ----
    # Spaced 14 apart horizontally, 13 apart vertically
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 20, 33, 46, 59, 72, 85, 97]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 20
        if pop < 3000:  return 30
        if pop < 6000:  return 42
        if pop < 10000: return 52
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick hoods by striding through the list to spread coverage
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR PROXIMITY MASKS (reactive, computed from current map) ----
    # Road within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power (wire or plant) within 5 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE EACH ACTIVE HOOD HAS A POWER PLANT NEARBY ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
        y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center or nearest empty spot
            for r in range(8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (cross at each hood center) ----
    spine_range = 8
    # Only handle one hood per step (rotate by step) to stay reactive
    hood_idx = step % len(active_hoods)
    hx, hy = active_hoods[hood_idx]

    # Vertical spine at hx
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        # Only place if adjacent to existing wire/plant
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine at hy
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    # Connect horizontally and vertically adjacent hoods
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Right neighbor (14 apart)
            if hy1 == hy2 and hx2 == hx1 + 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Bottom neighbor (13 apart)
            if hx1 == hx2 and hy2 == hy1 + 13:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)
            # Handle 12-apart (bottom of different spacing)
            if hx1 == hx2 and abs(hy2 - hy1) in [12, 13, 14]:
                mid = (hy1 + hy2) // 2
                if not ib(hx1, mid): continue
                if not bool(wm[mid, hx1]) and not bool(pm[mid, hx1]) and bool(em[mid, hx1]):
                    for ady in [-1, 1]:
                        ay = mid + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, mid)

    # ---- PHASE 4: ROADS flanking wire spines ----
    hx, hy = active_hoods[hood_idx]
    # Roads flanking vertical spine at hx±1
    for rx in [hx - 1, hx + 1]:
        if not ib(rx, hy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            # Only place road if adjacent wire or plant provides power
            if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                return (Tool.ROAD, rx, ry)

    # Roads flanking horizontal spine at hy±1
    for ry2 in [hy - 1, hy + 1]:
        if not ib(hx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT (reactive to road+power availability) ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 45% RES, 30% COM, 25% IND
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Sort by distance to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS INTO POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES: fire, police, stadiums, seaports, airports ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(16, WORLD_W, 22) for py2 in range(16, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 25), (90, 25), (30, 75), (90, 75),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 45), (75, 55), (20, 20), (100, 20),
                    (20, 80), (100, 80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 5), (30, 95), (90, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94),
                    (6, 40), (6, 60), (114, 40), (114, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for large cities ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (15, 50), (105, 50), (60, 15), (60, 85)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value boost ----
    if pop > 150 and step % 4 == 0:
        park_candidates = np.where(em & nbr_road & nbr_power)
        if len(park_candidates[0]) > 0:
            idx = (step * 19) % len(park_candidates[0])
            py2, px2 = int(park_candidates[0][idx]), int(park_candidates[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from any existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place plant near unpowered active hood ----
    for (hx2, hy2) in active_hoods:
        if not bool(nbr_power[hy2, hx2]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx2 + dx, hy2 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants at center-ish locations with wire spines."""
    actions = []
    # Two central coal plants
    for px, py in [(40, 50), (80, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connecting them
    for cx in range(41, 80):
        actions.append((Tool.WIRE, cx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.18:
            return Tool.INDUSTRIAL
        if c_r < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- DYNAMIC GRID OF NEIGHBORHOODS ----
    # Scale coverage based on population
    def get_neighborhoods():
        # Each neighborhood is (center_x, center_y)
        # Start tight, expand as city grows
        base = [(40, 50), (80, 50)]
        if pop > 50:
            base += [(40, 25), (80, 25), (40, 75), (80, 75)]
        if pop > 200:
            base += [(20, 50), (60, 50), (100, 50)]
        if pop > 400:
            base += [(20, 25), (60, 25), (100, 25),
                     (20, 75), (60, 75), (100, 75)]
        if pop > 700:
            base += [(20, 10), (60, 10), (100, 10),
                     (20, 90), (60, 90), (100, 90)]
        if pop > 1000:
            base += [(10, 50), (110, 50),
                     (40, 10), (80, 10),
                     (40, 90), (80, 90)]
        if pop > 1500:
            base += [(10, 25), (110, 25), (10, 75), (110, 75),
                     (10, 10), (110, 10), (10, 90), (110, 90)]
        # Deduplicate
        seen = set()
        result = []
        for p in base:
            if p not in seen:
                seen.add(p)
                result.append(p)
        return result

    neighborhoods = get_neighborhoods()

    # ---- ENSURE POWER PLANTS near neighborhoods ----
    for (px, py) in neighborhoods:
        x0 = max(0, px - 10); x1 = min(WORLD_W, px + 11)
        y0 = max(0, py - 10); y1 = min(WORLD_H, py + 11)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty tile for plant
        for r in range(0, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if r > 0 and abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINES: extend outward from each plant ----
    # Build vertical wire spine through each neighborhood center
    spine_half = min(35, 8 + pop // 8)
    for (px, py) in neighborhoods:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check existing wire coverage
        wire_col = [r for r in range(spine_top, spine_bot + 1)
                    if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            # Bootstrap: place wire adjacent to plant
            for dy in range(-6, 7):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            max_wr = max(wire_col)
            min_wr = min(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE between neighborhoods at same y ----
    y_levels = sorted(set(py for (_, py) in neighborhoods))
    for yl in y_levels:
        row_n = sorted([(px, py) for (px, py) in neighborhoods if py == yl], key=lambda a: a[0])
        for i in range(len(row_n) - 1):
            x1 = row_n[i][0]
            x2 = row_n[i + 1][0]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE between neighborhoods at same x ----
    x_cols = sorted(set(px for (px, _) in neighborhoods))
    for xc in x_cols:
        col_n = sorted([(px, py) for (px, py) in neighborhoods if px == xc], key=lambda a: a[1])
        for i in range(len(col_n) - 1):
            y1 = col_n[i][1]
            y2 = col_n[i + 1][1]
            for cy in range(y1 + 1, y2):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- ROAD GRID: build roads flanking wire spines ----
    for idx, (px, py) in enumerate(neighborhoods):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_col = [r for r in range(spine_top, spine_bot + 1)
                    if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            continue
        # Roads on both sides of wire spine
        for offset in [1, 2]:
            for wr in wire_col[::2]:
                for side in [-offset, offset]:
                    rx = px + side
                    if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                        return (Tool.ROAD, rx, wr)

    # ---- HORIZONTAL ROADS at y offsets from each neighborhood ----
    for yl in y_levels:
        row_n = sorted([(px, py) for (px, py) in neighborhoods if py == yl], key=lambda a: a[0])
        if not row_n:
            continue
        x_min = max(2, row_n[0][0] - 3)
        x_max = min(WORLD_W - 3, row_n[-1][0] + 3)
        for horiz_y in [yl - 4, yl + 4, yl - 8, yl + 8, yl - 12, yl + 12]:
            if not (2 <= horiz_y < WORLD_H - 2):
                continue
            for cx in range(x_min, x_max + 1):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting y-rows ----
    if pop > 100:
        for xc in x_cols:
            for offset in [-2, 2]:
                xr = xc + offset
                if not (0 <= xr < WORLD_W):
                    continue
                col_n = sorted([(px, py) for (px, py) in neighborhoods if px == xc], key=lambda a: a[1])
                for i in range(len(col_n) - 1):
                    y1 = col_n[i][1]
                    y2 = col_n[i + 1][1]
                    for cy in range(y1 + 1, y2):
                        if ib(xr, cy) and bool(em[cy, xr]) and not bool(pm[cy, xr]):
                            return (Tool.ROAD, xr, cy)

    # ---- BUILD PROXIMITY MASKS ----
    # Road proximity: within 3 tiles (zones need road access)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power proximity: within 7 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in neighborhoods:
            d = (np.abs(cxs - px).astype(float) +
                 np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- DENSE INFILL: zones adjacent to existing roads ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 17) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 400)):
            k = (step_k + offset * 11) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(3, 0), (-3, 0), (0, 3), (0, -3),
                           (2, 2), (-2, 2), (2, -2), (-2, -2),
                           (4, 0), (-4, 0), (0, 4), (0, -4)]:
                zx, zy = rx + dx, ry + dy
                if ib(zx, zy) and bool(nbr_wire[zy, zx]) and zone_clear(zx, zy):
                    return (pick_tool(), zx, zy)

    # ---- EXTEND ROADS near wire ----
    if len(road_xs) > 0:
        step_k2 = (step * 13) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k2 + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- CIVIC SERVICES (reactive to pop) ----
    if pop > 80:
        fire_spots = [
            (15, 15), (50, 15), (85, 15), (115, 15),
            (15, 40), (50, 40), (85, 40), (115, 40),
            (15, 65), (50, 65), (85, 65), (115, 65),
            (15, 88), (50, 88), (85, 88), (115, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (25, 20), (55, 20), (85, 20), (110, 20),
            (25, 50), (55, 50), (85, 50), (110, 50),
            (25, 80), (55, 80), (85, 80), (110, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        # Nuclear plants for expanded power
        nuke_spots = [
            (10, 50), (110, 50), (60, 5), (60, 95),
            (10, 20), (110, 20), (10, 80), (110, 80),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx, ny) in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        for ax, ay in [(58, 5), (5, 48), (113, 48), (58, 93)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sx, sy in [(5, 93), (113, 93), (5, 5), (113, 5)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- PARKS near zones to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys, zone_xs = np.where(zone_map)
        if len(zone_xs) > 0:
            for i in range(min(len(zone_xs), 50)):
                k = (step * 3 + i * 17) % len(zone_xs)
                zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
                for dx, dy in [(2, 0), (-2, 0), (0, 2), (0, -2),
                               (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx, ny = zx2 + dx, zy2 + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.PARK, nx, ny)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k3 = (step * 11) % max(len(wire_xs), 1)
        for offset in range(min(len(wire_xs), 150)):
            k = (step_k3 + offset * 5) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Only extend toward neighborhoods
                    best_n_dist = min(abs(nx - npx) + abs(ny - npy) for (npx, npy) in neighborhoods)
                    if best_n_dist < 20:
                        return (Tool.WIRE, nx, ny)

    # ---- LAST RESORT: road near any zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 23) % len(zone_xs)
        zx, zy = int(zone_xs[k]), int(zone_ys[k])
        for dx, dy in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx, ny = zx + dx, zy + dy
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    return None

