def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Phase 1: Power plants distributed across map ---
    # Grid of coal plants every ~30 cols, ~25 rows
    plant_targets = [
        (15, 12), (45, 12), (75, 12), (105, 12),
        (15, 37), (45, 37), (75, 37), (105, 37),
        (15, 62), (45, 62), (75, 62), (105, 62),
        (15, 87), (45, 87), (75, 87), (105, 87),
    ]

    if funds > 2000:
        for ppx, ppy in plant_targets:
            if not ib(ppx, ppy):
                continue
            found = False
            for dy in range(-8, 9):
                for dx in range(-8, 9):
                    nx, ny = ppx + dx, ppy + dy
                    if ib(nx, ny) and pm[ny, nx]:
                        found = True
                        break
                if found:
                    break
            if not found:
                return (Tool.COALPOWER, ppx, ppy)

    # --- Phase 2: Wire grid every 6 cols/rows ---
    wire_rows = list(range(3, 100, 6))
    wire_cols = list(range(3, 120, 6))

    # Build horizontal wire lines fully
    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        # Fill any empty spots on this row that should be wired
        for x in range(0, WORLD_W):
            if ib(x, wr) and em[wr, x]:
                return (Tool.WIRE, x, wr)

    # Build vertical wire lines
    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        for y in range(0, WORLD_H):
            if ib(wc, y) and em[y, wc]:
                return (Tool.WIRE, wc, y)

    # --- Phase 3: Road grid offset from wire grid ---
    road_rows = list(range(6, 100, 6))
    road_cols = list(range(6, 120, 6))

    for rr in road_rows:
        for x in range(0, WORLD_W):
            if ib(x, rr) and em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        for y in range(0, WORLD_H):
            if ib(rc, y) and em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # --- Phase 4: Zone placement ---
    zone_tiles = resm | comm | indm

    # Near-road mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Near-wire/plant mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Expand near-plant buffer to prevent zoning on top of plants
    no_zone = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            no_zone[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                # Must be empty or existing zone tile
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    cand = em & nbr_road & nbr_wire & ~no_zone
    cand[0:3, :] = False
    cand[WORLD_H - 3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand)
    if len(cxs_arr) > 0:
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 500)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                # Spread out: prefer moderate distance from existing zones
                score = np.where(zone_dist < 3, -1000.0,
                        np.where(zone_dist < 10, zone_dist * 2.0,
                                 zone_dist))
            else:
                score = -(np.abs(cxs_arr - 60).astype(float) +
                          np.abs(cys_arr - 50).astype(float))
        else:
            # Start near the four quadrant centers
            score = np.zeros(len(cxs_arr), dtype=float)
            for cx, cy in [(30, 25), (90, 25), (30, 75), (90, 75)]:
                d = np.abs(cxs_arr - cx).astype(float) + np.abs(cys_arr - cy).astype(float)
                score = np.maximum(score, 50.0 - d)

        jitter = ((cxs_arr * 7 + cys_arr * 13 + step * 3) % 7).astype(float) * 0.3
        score = score - jitter

        order = np.argsort(-score)
        tool = pick_tool()
        checked = 0
        for i in order:
            if checked > 800:
                break
            zx2, zy2 = int(cxs_arr[i]), int(cys_arr[i])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)
            checked += 1

    # --- Phase 5: Civic services ---
    if pop > 30:
        fire_locs = [(fx, fy) for fy in range(12, 95, 12)
                     for fx in range(12, 115, 12)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(pm[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_locs = [(px2, py2) for py2 in range(18, 92, 18)
                       for px2 in range(18, 112, 18)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]) and not bool(pm[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150:
        park_locs = [(pkx, pky) for pky in range(9, 95, 9)
                     for pkx in range(9, 115, 9)]
        for pkx2, pky2 in park_locs:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]) and not bool(pm[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 250 and funds > 3000:
        stadium_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                        (60, 50), (15, 50), (105, 50), (60, 10), (60, 90)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 400 and funds > 5000:
        nuclear_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                        (60, 5), (60, 95)]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            found = False
            for dy in range(-7, 8):
                for dx in range(-7, 8):
                    nx2, ny2 = npx + dx, npy + dy
                    if ib(nx2, ny2) and pm[ny2, nx2]:
                        found = True
                        break
                if found:
                    break
            if not found and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600 and funds > 5000:
        airport_locs = [(10, 10), (110, 10), (10, 90), (110, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 800 and funds > 3000:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: wire from nearest plant ---
    pys_arr, pxs_arr = np.where(pm)
    if len(pxs_arr) > 0:
        sk = (step * 11) % len(pxs_arr)
        for offset in range(min(len(pxs_arr), 60)):
            k = (sk + offset * 7) % len(pxs_arr)
            px2, py2 = int(pxs_arr[k]), int(pys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Fallback: road near wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(0, 3), (0, -3), (3, 0), (-3, 0),
                             (0, 4), (0, -4), (4, 0), (-4, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a row with wire spines and flanking roads."""
    actions = []
    # Three power plants: left, center, right
    for px, py in [(20, 50), (60, 50), (100, 50)]:
