def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio: 50% res, 30% com, 20% ind — more commercial than parent
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure dense power plant grid (every 20 tiles) ---
    plant_grid_xs = list(range(10, WORLD_W - 5, 20))
    plant_grid_ys = list(range(10, WORLD_H - 5, 20))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Wire grid every 10 rows/cols ---
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            # Start from nearest plant
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest = pxs[np.argmin(np.abs(pys - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_has)[0]
        left, right = int(indices[0]), int(indices[-1])
        if left > 2 and bool(em[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top, bot = int(indices[0]), int(indices[-1])
        if top > 2 and bool(em[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # --- PHASE 3: Dense road grid every 6 rows/cols offset from wire ---
    road_rows = sorted(set(
        r for wr in wire_rows for r in [wr-4, wr+4] if 3 < r < WORLD_H - 3
    ))
    road_cols = sorted(set(
        c for wc in wire_cols for c in [wc-4, wc+4] if 3 < c < WORLD_W - 3
    ))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left, right = int(indices[0]), int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top, bot = int(indices[0]), int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # --- PHASE 4: Zone placement closed-loop ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Keep off infrastructure
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 3, 1000.0, np.where(min_zone_dist > 15, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.4
        order = np.argsort(score)
        off = (step * 11 + pop) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services based on population ---
    if pop > 30:
        fire_spots = [(fx, fy) for fy in range(6, 96, 12) for fx in range(6, 116, 12)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_spots = [(px2, py2) for py2 in range(8, 94, 14) for px2 in range(8, 114, 14)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(10, 92, 8) for pkx in range(10, 112, 8)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [(sx, sy) for sy in range(14, 88, 18) for sx in range(14, 106, 22)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuclear_spots = [(nx, ny) for ny in range(15, 88, 20) for nx in range(15, 108, 20)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-10), min(WORLD_W, npx+11)
                y0, y1 = max(0, npy-10), min(WORLD_H, npy+11)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 6), (65, 6), (55, 93), (65, 93), (6, 44), (113, 44)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [(6, 50), (113, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Wire extension toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 7: Road extension toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Fallback: place road near any plant
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6,0),(-6,0),(0,6),(0,-6),(4,0),(-4,0),(0,4),(0,-4)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in 3x3 grid with wire spines and flanking roads."""
    actions = []
    # 3 columns x 3 rows of plants at key positions
    for px in [20, 60, 100]:
        for py in [20, 50, 80]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertically from each plant
            for dy in range(-4, 5):
                actions.append((Tool.WIRE, px, py + dy))
            # Roads flanking wire
            for dy in range(-4, 5):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhood anchors covering the map
    anchors = [(px, py) for px in [20, 60, 100] for py in [20, 50, 80]]

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 300:  return 3
        if pop < 500:  return 4
        if pop < 750:  return 5
        if pop < 1000: return 6
        if pop < 1500: return 7
        if pop < 2000: return 8
        return 9

    n_active = num_active()
    if n_active >= len(anchors):
        active = anchors[:]
    else:
        step_sz = len(anchors) / n_active
        active = [anchors[int(i * step_sz)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        for r in range(0, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINES: vertical from each active anchor ----
    spine_half = min(35, 12 + pop // 8)
    for (px, py) in active:
        top = max(2, py - spine_half)
        bot = min(WORLD_H - 3, py + spine_half)
        # Check if wire exists near anchor
        wire_in_col = [r for r in range(top, bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            mn = min(wire_in_col)
            mx = max(wire_in_col)
            if mx < bot:
                nr = mx + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    if bool(em[nr, px]) or bool(wm[nr, px]):
                        return (Tool.WIRE, px, nr)
            if mn > top:
                nr = mn - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    if bool(em[nr, px]) or bool(wm[nr, px]):
                        return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same y-level ----
    y_levels = sorted(set(py for (_, py) in active))
    for yl in y_levels:
        row_a = sorted([(px, py) for (px, py) in active if py == yl], key=lambda a: a[0])
        for i in range(len(row_a) - 1):
            x1 = row_a[i][0]
            x2 = row_a[i + 1][0]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor columns ----
    x_cols = sorted(set(px for (px, _) in active))
    for xc in x_cols:
        col_a = sorted([(px, py) for (px, py) in active if px == xc], key=lambda a: a[1])
        for i in range(len(col_a) - 1):
            y1v = col_a[i][1]
            y2v = col_a[i + 1][1]
            for cy in range(y1v + 1, y2v):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- ROADS flanking wire spines ----
    for idx, (px, py) in enumerate(active):
        top = max(2, py - spine_half)
        bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(top, bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 3
        rl, rr2 = px - 1, px + 1
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr2, wr) and bool(em[wr, rr2]) and not bool(pm[wr, rr2]):
                return (Tool.ROAD, rr2, wr)

    # ---- HORIZONTAL ROADS at y-levels above and below anchors ----
    if pop > 10:
        for yl in y_levels:
            row_a = sorted([(px, py) for (px, py) in active if py == yl], key=lambda a: a[0])
            if not row_a:
                continue
            xl = row_a[0][0] - 1
            xr = row_a[-1][0] + 1
            for horiz_y in [yl - 4, yl + 4, yl - 8, yl + 8]:
                if not ib(xl, horiz_y) or not ib(xr, horiz_y):
                    continue
                for cx in range(xl, xr + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS ROADS connecting y-levels ----
    if pop > 50 and len(y_levels) >= 2:
        for xc in x_cols:
            for rx in [xc - 3, xc + 3]:
                for i in range(len(y_levels) - 1):
                    y1v = y_levels[i]
                    y2v = y_levels[i + 1]
                    for cy in range(y1v, y2v + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: distance to nearest active anchor (weighted), with jitter
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.9)
            best_dist = np.minimum(best_dist, d)

        # If zones exist, also factor in clustering
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_dist = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_dist = np.minimum(zone_dist, d2)
                # Blend: prefer near anchor but also cluster
                score = best_dist * 0.6 + zone_dist * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        jitter = ((cxs * 7 + cys * 13 + step * 3) % 7).astype(float)
        score = score + jitter * 0.3

        order = np.argsort(score)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS near wires ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 150)):
            k = (sk + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(12, 95, 15) for fx in range(12, 115, 15)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for py2 in range(18, 92, 18) for px2 in range(18, 112, 18)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150:
        zone_map = resm | comm | indm
        zys3, zxs3 = np.where(zone_map)
        if len(zxs3) > 0:
            for i in range(min(len(zxs3), 50)):
                k = (step * 3 + i * 17) % len(zxs3)
                zx2, zy2 = int(zxs3[k]), int(zys3[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 500:
        stadium_spots = [
            (10, 10), (55, 10), (100, 10),
            (10, 90), (55, 90), (100, 90),
            (10, 50), (110, 50), (55, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800 and funds > 5000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for nx2, ny2 in nuke_spots:
            if not ib(nx2, ny2):
                continue
            found = False
            for dy in range(-6, 7):
                for dx in range(-6, 7):
                    nnx, nny = nx2 + dx, ny2 + dy
                    if ib(nnx, nny) and pm[nny, nnx]:
                        found = True
                        break
                if found:
                    break
            if not found and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- FALLBACK: extend wire from existing wire ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % max(len(wxs_arr), 1)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in a 2x2 grid with wire spines and flanking roads."""
    actions = []
    # Four plants: 2 columns x 2 rows
    for px in [30, 90]:
        for py in [30, 70]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertically
            for dy in range(-8, 9):
                actions.append((Tool.WIRE, px, py + dy))
            # Roads flanking wire
            for dy in range(-8, 9):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connecting plants at same y level
    for py in [30, 70]:
        for cx in range(31, 90):
            actions.append((Tool.WIRE, cx, py))
    # Vertical wire connecting plants at same x
    for px in [30, 90]:
        for cy in range(31, 70):
            actions.append((Tool.WIRE, px, cy))
    return actions[:20]  # keep init small


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 8 anchor neighborhoods covering the map (2 cols x 4 rows + extras)
    # Scale up: 3 cols x 3 rows = 9 anchors
    anchor_xs = [20, 60, 100]
    anchor_ys = [20, 50, 80]
    anchors = [(px, py) for px in anchor_xs for py in anchor_ys]

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 3
        if pop < 500:   return 4
        if pop < 800:   return 5
        if pop < 1200:  return 6
        if pop < 2000:  return 7
        if pop < 3000:  return 8
        return 9

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        has_plant = False
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        if np.any(pm[y0:y1, x0:x1]):
            has_plant = True
        if not has_plant:
            # Try to place plant at anchor
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Spiral search
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical from anchor, adaptive length) ----
    spine_half = min(35, 10 + pop // 10)
    for (px, py) in active_anchors:
        wc = px
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Find gaps in wire column
        for wy in range(spine_top, spine_bot + 1):
            if ib(wc, wy) and not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                if bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)
                # If something blocks, skip

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    for py in anchor_ys:
        row_anchors = sorted([(px2, py2) for (px2, py2) in active_anchors if py2 == py],
                              key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1 = row_anchors[i][0]
            x2 = row_anchors[i + 1][0]
            for cx in range(x1 + 1, x2):
                if ib(cx, py) and bool(em[py, cx]) and not bool(pm[py, cx]):
                    return (Tool.WIRE, cx, py)

    # ---- VERTICAL WIRE connecting anchor rows ----
    for px in anchor_xs:
        col_anchors = sorted([(px2, py2) for (px2, py2) in active_anchors if px2 == px],
                              key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1 = col_anchors[i][1]
            y2 = col_anchors[i + 1][1]
            for cy in range(y1 + 1, y2):
                if ib(px, cy) and bool(em[cy, px]) and not bool(pm[cy, px]):
                    return (Tool.WIRE, px, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        rl = px - 1
        rr = px + 1
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check wire presence in column
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 4
        for wr in wire_in_col[cycle::4]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels +/- 3 ----
    if pop > 20:
        for py in anchor_ys:
            row_anch = sorted([(px2, py2) for (px2, py2) in active_anchors if py2 == py],
                               key=lambda a: a[0])
            if len(row_anch) < 2:
                continue
            xl = row_anch[0][0] - 1
            xr = row_anch[-1][0] + 1
            for horiz_y in [py - 3, py + 3]:
                if not (0 <= horiz_y < WORLD_H):
                    continue
                for cx in range(max(0, xl), min(WORLD_W, xr + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting anchor rows ----
    if pop > 60:
        for px in anchor_xs:
            col_anch = sorted([(px2, py2) for (px2, py2) in active_anchors if px2 == px],
                               key=lambda a: a[1])
            for i in range(len(col_anch) - 1):
                y1 = col_anch[i][1]
                y2 = col_anch[i + 1][1]
                for rx in [px - 3, px + 3]:
                    if not (0 <= rx < WORLD_W):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 10), (35, 10), (65, 10), (95, 10), (115, 10),
            (8, 35), (35, 35), (65, 35), (95, 35), (115, 35),
            (8, 60), (35, 60), (65, 60), (95, 60), (115, 60),
            (8, 85), (35, 85), (65, 85), (95, 85), (115, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 40), (45, 40), (75, 40), (105, 40),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 5), (50, 5), (90, 5), (110, 5),
            (10, 93), (50, 93), (90, 93), (110, 93),
            (5, 48), (115, 48),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Add more nuclear power plants for better coverage
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 91)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 6), (115, 6)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants spread across map with wire+road cross."""
    actions = []
    # Three power plants: left, center, right
    plants = [(25, 50), (60, 50), (95, 50)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for x in range(px - 8, px + 9):
            if 0 <= x < 120:
                actions.append((Tool.WIRE, x, py))
        # Vertical wire spine
        for y in range(py - 8, py + 9):
            if 0 <= y < 100:
                actions.append((Tool.WIRE, px, y))
        # Roads parallel to spines
        for x in range(px - 8, px + 9):
            if 0 <= x < 120:
                actions.append((Tool.ROAD, x, py - 2))
                actions.append((Tool.ROAD, x, py + 2))
        for y in range(py - 8, py + 9):
            if 0 <= y < 100:
                actions.append((Tool.ROAD, px - 2, y))
                actions.append((Tool.ROAD, px + 2, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Dense grid of neighborhood centers across whole map
    # Use 6 columns x 5 rows = 30 neighborhoods
    all_hoods = []
    for hy in range(12, 95, 16):
        for hx in range(12, 115, 16):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 10
        if pop < 1000:  return 15
        if pop < 2000:  return 20
        if pop < 4000:  return 25
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: POWER PLANTS ---
    # Each active hood should have a coal plant within 10 tiles
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(1, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: WIRE GRID ---
    for (hx, hy) in active_hoods:
        spine_top  = max(2, hy - 12)
        spine_bot  = min(WORLD_H - 3, hy + 12)
        spine_left = max(2, hx - 12)
        spine_right= min(WORLD_W - 3, hx + 12)

        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        if col_wire:
            min_wr = min(col_wire)
            max_wr = max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc = min(row_wire)
            max_wc = max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT WIRES BETWEEN ADJACENT HOODS ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 20:
                continue
            # Connect horizontally if same row
            if abs(hy1 - hy2) <= 4 and hx2 > hx1:
                for cx in range(hx1 + 1, hx2):
                    mid_y = (hy1 + hy2) // 2
                    if ib(cx, mid_y) and bool(em[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
            # Connect vertically if same col
            if abs(hx1 - hx2) <= 4 and hy2 > hy1:
                for cy in range(hy1 + 1, hy2):
                    mid_x = (hx1 + hx2) // 2
                    if ib(mid_x, cy) and bool(em[cy, mid_x]):
                        return (Tool.WIRE, mid_x, cy)

    # --- PHASE 4: ROAD GRID ---
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]

        # Roads at wire_col ± 2
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy):
                continue
            cyc = step % 7
            for wr in col_wire[cyc::7]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        # Roads at wire_row ± 2
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry):
                continue
            cyc = (step + 3) % 7
            for wc in row_wire[cyc::7]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    # More balanced zone mix: IND:COM:RES = 30:30:40
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Prioritize industrial first (jobs), then commercial, then residential
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (within 4)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES (closed-loop, based on pop) ---
    if pop > 10:
        fire_locs = [(fx, fy) for fy in range(12, 95, 16) for fx in range(12, 115, 16)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 50:
        police_locs = [(px2, py2) for py2 in range(14, 95, 18) for px2 in range(14, 115, 18)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 85), (100, 80),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 4000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 25), (85, 25), (35, 75), (85, 75),
            (35, 50), (85, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95), (5, 25), (5, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85), (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from plants ---
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: compact power + road grid to kickstart growth"""
    actions = []
    # Two coal plants near center, spaced apart
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally
    for x in range(32, 90, 1):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(43, 50):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    for y in range(51, 58):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Initial roads near plants
    for x in range(20, 50):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for x in range(70, 105):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: 40% res, 35% com, 25% ind (more commercial/industrial than parent)
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # PHASE 1: Ensure power plants on a dense grid
    # Denser grid of plants: every 10 tiles
    plant_grid = []
    for py in range(10, 95, 10):
        for px in range(10, 115, 10):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
        y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # PHASE 2: Wire expansion - connect all plants
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        uncovered = [(px, py) for px, py in plant_grid
                     if ib(px, py) and not bool(near_power[py, px])]
        if uncovered:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in uncovered)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire to unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs, zys))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # PHASE 3: Road grid - dense orthogonal grid every 4 tiles
    # This creates a much denser road network than parent
    road_grid_targets = []
    for gy in range(5, 97, 4):
        for gx in range(5, 117, 4):
            road_grid_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm
        road_cand[0:3, :] = False
        road_cand[WORLD_H-3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W-3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in uncovered_road[:20])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:5]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # PHASE 4: Zone placement with aggressive mix
    # Prefer spots near roads AND power, filling the map evenly
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()

        # Score: spread across map by dividing into quadrants
        # Use step to cycle through quadrant focus
        quadrant = (step // 50) % 9
        qx = [15, 60, 105, 15, 60, 105, 15, 60, 105][quadrant]
        qy = [17, 17, 17,  50, 50, 50,  83, 83, 83][quadrant]

        # Distance to current quadrant focus + distance to nearest road
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs_arr))

        quad_dist = (np.abs(cxs_arr - qx) + np.abs(cys_arr - qy)).astype(float)

        # Also penalize being too close to existing zones (spread out)
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 50)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer near roads, somewhat near quadrant center, not too crowded
            score = road_dist * 1.5 + quad_dist * 0.3 - zone_dist * 0.2
        else:
            score = road_dist + quad_dist * 0.5

        order = np.argsort(score)
        off = (step * 17 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services based on population - more aggressive deployment
    powered_empty = em & near_power

    if pop > 30:
        # Fire stations every 6 tiles across whole map
        fire_grid = [(fx, fy) for fy in range(10, 94, 6) for fx in range(10, 114, 6)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(powered_empty[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(12, 92, 7) for px2 in range(12, 112, 7)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(powered_empty[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(px3, py3) for py3 in range(8, 95, 5) for px3 in range(8, 115, 5)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (60, 50), (100, 50),
                        (20, 85), (60, 85), (100, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        # Switch to nuclear power for better output
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (40, 10), (80, 10), (40, 90), (80, 90), (60, 35), (60, 65)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-5), min(WORLD_W, nx+6)
                y0, y1 = max(0, ny-5), min(WORLD_H, ny+6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(55, 5), (75, 5), (55, 94), (75, 94),
                        (5, 30), (5, 60), (114, 30), (114, 60),
                        (30, 5), (90, 5)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10, 45), (110, 45), (60, 5), (60, 94),
                        (10, 20), (110, 20), (10, 80), (110, 80),
                        (35, 5), (85, 5), (35, 94), (85, 94)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend road from any plant
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        for i in range(len(pwr_xs)):
            k = (step * 7 + i) % len(pwr_xs)
            px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
            for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 4), (-4, -4)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from plant
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and initial roads."""
    actions = []
    # Primary plant at (58, 50)
    actions.append((Tool.COALPOWER, 58, 50))
    # Wire spine from plant upward and downward
    for y in range(44, 58):
        actions.append((Tool.WIRE, 60, y))
    # Road columns flanking wire
    for y in range(44, 58):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    # Second plant to the right
    actions.append((Tool.COALPOWER, 78, 50))
    # Horizontal wire bridge connecting plants
    for x in range(61, 77):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    """
    Highly reactive closed-loop policy.
    Strategy:
    - Multiple neighborhoods: left cluster (x~40), center cluster (x~60), right cluster (x~80)
    - Each neighborhood: vertical wire spine + flanking roads + balanced R/C/I zones
    - Multiple power plants connected by horizontal wires
    - Services (fire/police) placed reactively based on population
    - Expand vertically as population grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def safe_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    def safe_wire(x, y):
        return in_bounds(x, y) and bool(wm[y, x])

    def safe_road(x, y):
        return in_bounds(x, y) and bool(rm[y, x])

    def safe_plant(x, y):
        return in_bounds(x, y) and bool(pm[y, x])

    pop = obs.city_pop
    step = obs.step
    total_steps = obs.n_steps

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define 3 neighborhood columns
    # Each neighborhood: wire_col, road_left, road_right, plant_x, plant_y
    neighborhoods = [
        {'wire_col': 40, 'road_l': 39, 'road_r': 41, 'plant_x': 38, 'plant_y': 50},
        {'wire_col': 60, 'road_l': 59, 'road_r': 61, 'plant_x': 58, 'plant_y': 50},
        {'wire_col': 80, 'road_l': 79, 'road_r': 81, 'plant_x': 78, 'plant_y': 50},
    ]

    # Expand vertical extent based on population
    pop_factor = min(25, pop // 20)
    spine_top = max(5, 50 - 15 - pop_factor)
    spine_bot = min(WORLD_H - 5, 50 + 15 + pop_factor)

    # For each neighborhood, ensure plant exists
    for nb in neighborhoods:
        px, py = nb['plant_x'], nb['plant_y']
        # Check if there's a plant in 5x5 area around target
        has_plant = False
        for dy in range(-3, 4):
            for dx in range(-3, 4):
                if in_bounds(px + dx, py + dy) and bool(pm[py + dy, px + dx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if safe_empty(px, py):
                return (Tool.COALPOWER, px, py)

    # Build horizontal wire highway at y=50 connecting all plants
    for x in range(37, 83):
        if in_bounds(x, 50) and bool(em[50, x]) and not bool(pm[50, x]):
            # Check if this segment needs wire (bridges between plants)
            return (Tool.WIRE, x, 50)

    # For each neighborhood, build vertical wire spine
    for nb in neighborhoods:
        wc = nb['wire_col']
        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]

        if not wire_rows:
            # Seed wire adjacent to plant
            for dy in range(-2, 3):
                ny = 50 + dy
                if in_bounds(wc, ny) and (bool(em[ny, wc]) or bool(wm[ny, wc])) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            # Grow downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            # Grow upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # For each neighborhood, build flanking roads
    for nb in neighborhoods:
        wc = nb['wire_col']
        rl = nb['road_l']
        rr = nb['road_r']
        wire_rows = [r for r in range(WORLD_H) if in_bounds(wc, r) and bool(wm[r, wc])]

        if wire_rows:
            # Check every other step for left/right
            step_mod2 = step % 2
            rows_to_check = wire_rows[::2] if step_mod2 == 0 else wire_rows[1::2]
            for wr in rows_to_check:
                if in_bounds(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)
                if in_bounds(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                    return (Tool.ROAD, rr, wr)

    # Build proximity masks for zone placement
    # Near-road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Near-wire mask (within 6 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Place zones near roads and power
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near wire columns of all neighborhoods
        # Use combined distance to nearest wire column
        dists = np.minimum(
            np.minimum(np.abs(cxs - 40), np.abs(cxs - 60)),
            np.abs(cxs - 80)
        ) + np.abs(cys - 50) // 4
        order = np.argsort(dists)
        step_off = int(step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 120:
                break

    # Add 4th and 5th neighborhoods for large pop
    if pop > 500:
        extra_nbs = [
            {'wire_col': 20, 'road_l': 19, 'road_r': 21, 'plant_x': 18, 'plant_y': 50},
            {'wire_col': 100, 'road_l': 99, 'road_r': 101, 'plant_x': 98, 'plant_y': 50},
        ]
        for nb in extra_nbs:
            px, py2 = nb['plant_x'], nb['plant_y']
            has_plant = any(
                in_bounds(px + dx, py2 + dy) and bool(pm[py2 + dy, px + dx])
                for dy in range(-3, 4) for dx in range(-3, 4)
            )
            if not has_plant and safe_empty(px, py2):
                return (Tool.COALPOWER, px, py2)

        # Horizontal wire extension for extra neighborhoods
        for x in range(17, 42):
            if in_bounds(x, 50) and bool(em[50, x]) and not bool(pm[50, x]):
                return (Tool.WIRE, x, 50)
        for x in range(82, 101):
            if in_bounds(x, 50) and bool(em[50, x]) and not bool(pm[50, x]):
                return (Tool.WIRE, x, 50)

    # Extend roads to fill gaps near wire
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Services based on population
    if pop > 300:
        service_positions = [
            (Tool.FIRESTATION, 50, 40), (Tool.FIRESTATION, 70, 40),
            (Tool.FIRESTATION, 50, 60), (Tool.FIRESTATION, 70, 60),
        ]
        for tool, sx, sy in service_positions:
            if safe_empty(sx, sy):
                return (tool, sx, sy)

    if pop > 600:
        police_positions = [
            (Tool.POLICESTATION, 45, 45), (Tool.POLICESTATION, 75, 45),
            (Tool.POLICESTATION, 45, 55), (Tool.POLICESTATION, 75, 55),
        ]
        for tool, sx, sy in police_positions:
            if safe_empty(sx, sy):
                return (tool, sx, sy)

    if pop > 1000:
        # Stadium for big city bonus
        if safe_empty(60, 35):
            return (Tool.STADIUM, 60, 35)

    # Expand wire laterally as fallback
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in 3x3 grid with wire stubs and road stubs."""
    actions = []
    plant_positions = [
        (20, 25), (60, 25), (100, 25),
        (20, 50), (60, 50), (100, 50),
        (20, 75), (60, 75), (100, 75),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Wire stubs up and down
        for dy in [-3, -2, -1, 1, 2, 3]:
            actions.append((Tool.WIRE, px, py + dy))
        # Road stubs left and right
        for dx in [-4, -3, -2, -1, 1, 2, 3, 4]:
            actions.append((Tool.ROAD, px + dx, py - 3))
            actions.append((Tool.ROAD, px + dx, py + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # All 9 cluster centers in a 3x3 grid
    ALL_CLUSTERS = [
        (20, 25), (60, 25), (100, 25),
        (20, 50), (60, 50), (100, 50),
        (20, 75), (60, 75), (100, 75),
    ]

    def num_active():
        if pop < 30:   return 1
        if pop < 80:   return 2
        if pop < 180:  return 3
        if pop < 350:  return 4
        if pop < 600:  return 5
        if pop < 900:  return 6
        if pop < 1400: return 7
        if pop < 2000: return 8
        return 9

    n_active = num_active()
    active_centers = ALL_CLUSTERS[:n_active]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 55% res, 25% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_centers:
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place at center first
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) through each active cluster ----
    spine_half = min(22, 7 + pop // 15)
    for (px, py) in active_centers:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Extend downward from plant
        for wy in range(py, spine_bot + 1):
            if ib(px, wy) and not bool(pm[wy, px]):
                if not bool(wm[wy, px]) and bool(em[wy, px]):
                    return (Tool.WIRE, px, wy)
                elif not bool(wm[wy, px]) and not bool(em[wy, px]):
                    break
        # Extend upward from plant
        for wy in range(py, spine_top - 1, -1):
            if ib(px, wy) and not bool(pm[wy, px]):
                if not bool(wm[wy, px]) and bool(em[wy, px]):
                    return (Tool.WIRE, px, wy)
                elif not bool(wm[wy, px]) and not bool(em[wy, px]):
                    break

    # ---- HORIZONTAL WIRE connecting same-row clusters ----
    row_ys = sorted(set(py for (px, py) in active_centers))
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl])
        for i in range(len(row_cs) - 1):
            x1c, x2c = row_cs[i][0], row_cs[i + 1][0]
            for cx in range(x1c, x2c + 1):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting cluster columns ----
    if n_active >= 4:
        col_xs = sorted(set(px for (px, py) in active_centers))
        for xc in col_xs:
            col_cs = sorted([(px, py) for (px, py) in active_centers if px == xc])
            for i in range(len(col_cs) - 1):
                y1c, y2c = col_cs[i][1], col_cs[i + 1][1]
                for cy in range(y1c, y2c + 1):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # ---- ROAD COLUMNS flanking wire spines ----
    for idx, (px, py) in enumerate(active_centers):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Left and right road columns at offsets -2 and +2 (inner)
        for rx_off in [-2, 2]:
            rx = px + rx_off
            for ry in range(spine_top, spine_bot + 1):
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        # Outer roads at -4 and +4
        for rx_off in [-4, 4]:
            rx = px + rx_off
            for ry in range(spine_top, spine_bot + 1):
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- HORIZONTAL ROADS connecting clusters at same y-level ----
    for yl in row_ys:
        row_cs = sorted([(px, py) for (px, py) in active_centers if py == yl])
        if len(row_cs) < 2:
            continue
        x_left = row_cs[0][0] - 5
        x_right = row_cs[-1][0] + 5
        for offset in [-3, 3, -6, 6, -9, 9]:
            horiz_y = yl + offset
            if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                continue
            for cx in range(max(0, x_left), min(WORLD_W, x_right + 1)):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL CROSS-ROADS connecting row clusters ----
    if pop > 50 and len(row_ys) >= 2:
        for col_x in [20, 60, 100]:
            y_sorted = sorted(row_ys)
            for i in range(len(y_sorted) - 1):
                y1v = y_sorted[i]
                y2v = y_sorted[i + 1]
                for rx_off in [-3, 3, -6, 6]:
                    rx = col_x + rx_off
                    if not ib(rx, y1v) or not ib(rx, y2v):
                        continue
                    for cy in range(y1v, y2v + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_centers:
            d = (np.abs(cxs - px).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = []
        for yl in [18, 35, 55, 70, 88]:
            for xl in [8, 32, 55, 78, 108]:
                fire_spots.append((xl, yl))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = []
        for yl in [15, 38, 60, 82]:
            for xl in [10, 38, 65, 92, 115]:
                police_spots.append((xl, yl))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 8), (50, 8), (90, 8),
            (10, 90), (50, 90), (90, 90),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [
            (40, 3), (80, 3), (5, 50), (115, 50),
            (40, 96), (80, 96), (5, 20), (115, 20),
            (5, 80), (115, 80), (5, 35), (115, 35),
            (20, 3), (100, 3), (20, 96), (100, 96),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94), (5, 5), (115, 5), (30, 5), (85, 5)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 7), (115, 7)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 120:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 5 coal plants spread across map with wire spines and flanking roads."""
    actions = []
    # Five starting plants across the map
    for cx, cy in [(20, 30), (50, 50), (80, 30), (100, 70), (10, 70)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Short vertical wire spine
        for dy in [-1, 1, 2, -2]:
            actions.append((Tool.WIRE, cx, cy + dy))
        # Flanking roads
        for dy in range(-2, 3):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More neighborhoods: 10 cols x 8 rows = 80 neighborhoods for denser coverage
    nh_cols = [8, 20, 33, 46, 59, 72, 85, 98, 111, 118]
    nh_rows = [10, 22, 35, 48, 61, 74, 87, 96]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 5
        if pop < 150:   return 10
        if pop < 300:   return 18
        if pop < 600:   return 28
        if pop < 1200:  return 40
        if pop < 2500:  return 55
        if pop < 5000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood should have a plant within 10 tiles
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Find nearest empty spot for plant
        for r in range(15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE NETWORK - connect all plants with horizontal+vertical spines ----
    spine_range = 16

    # Build wire along grid lines: for each active hood, extend wire vertically and horizontally
    # Priority: extend from existing wire/plant adjacency
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Spread work across steps
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, (len(active_hoods) * 2) // 3 + 1):
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]) or bool(rm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap from plant
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]) or bool(rm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in [(hx1 + 13, hy1), (hx1 + 25, hy1), (hx1 + 11, hy1)]:
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        for (hx2, hy2) in [(hx1, hy1 + 13), (hx1, hy1 + 11)]:
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 3) % max(len(active_hoods), 1) >= max(1, (len(active_hoods) * 2) // 3 + 1):
            continue

        # Flanking vertical spine (roads at hx-1 and hx+1)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Flanking horizontal spine (roads at hy-1 and hy+1)
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road coverage mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage mask (wire or plant within 7 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    # Fire stations early and densely
    if pop > 80:
        fire_spots = []
        for fy in range(10, 100, 18):
            for fx in range(8, 120, 16):
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = []
        for py in range(18, 100, 22):
            for px in range(14, 120, 20):
                police_spots.append((px, py))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 25), (75, 25), (30, 55), (75, 55), (30, 80), (75, 80),
            (55, 10), (55, 90), (5, 45), (110, 45), (5, 70), (110, 70),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (30, 50), (90, 50), (60, 25), (60, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(8, 90), (112, 90), (8, 8), (112, 8), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 6), (70, 6), (50, 93), (70, 93), (5, 48), (113, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 150 and step % 4 == 0:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant + cross wire + roads"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross through center
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking central wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    for y in range(1, 99):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    # Additional plants at quadrant centers
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 20, 80))
    actions.append((Tool.COALPOWER, 100, 80))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Grid of plants: 4x4 evenly spaced
    plant_positions = []
    for row in range(4):
        for col in range(4):
            px = 15 + col * 30  # 15, 45, 75, 105
            py = 15 + row * 24  # 15, 39, 63, 87
            plant_positions.append((px, py))

    # Wire corridors: horizontal at every ~12 rows, vertical at every ~15 cols
    wire_rows = [9, 21, 33, 45, 57, 69, 81, 93]
    wire_cols = [9, 24, 39, 54, 69, 84, 99, 114]

    # ---- PHASE 1: ENSURE PLANTS EXIST ----
    for px, py in plant_positions:
        # Check 3x3 area around plant position
        x0, x1 = max(0, px-8), min(WORLD_W, px+9)
        y0, y1 = max(0, py-8), min(WORLD_H, py+9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find empty spot near target
            for r in range(0, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE FROM PLANTS TO CORRIDORS ----
    # Connect each plant to nearby wire corridors reactively
    phase = step % 8

    if phase == 0:
        # Extend horizontal wire corridors across full map
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_has_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_power):
                # Seed from nearby plant
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    # Walk toward wr
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
                    if ib(bpx, wr) and bool(em[wr, bpx]):
                        return (Tool.WIRE, bpx, wr)
            else:
                # Extend leftward and rightward
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_has_power[wx]):
                        if (wx > 0 and bool(row_has_power[wx-1])) or \
                           (wx < WORLD_W-1 and bool(row_has_power[wx+1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_has_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2, wc, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
                    if ib(wc, bpy2) and bool(em[bpy2, wc]):
                        return (Tool.WIRE, wc, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_has_power[wy]):
                        if (wy > 0 and bool(col_has_power[wy-1])) or \
                           (wy < WORLD_H-1 and bool(col_has_power[wy+1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors (both sides)
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors (both sides)
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross-connect roads between wire rows (vertical connectors)
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx+1]
            mid_y = (wr1 + wr2) // 2
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                        # Check adjacent road
                        adj = (ib(rcx, mid_y-1) and bool(rm[mid_y-1, rcx])) or \
                              (ib(rcx, mid_y+1) and bool(rm[mid_y+1, rcx]))
                        if adj:
                            return (Tool.ROAD, rcx, mid_y)

    elif phase == 5:
        # Cross-connect roads between wire cols (horizontal connectors)
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx+1]
            mid_x = (wc1 + wc2) // 2
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x-1, ry) and bool(rm[ry, mid_x-1])) or \
                              (ib(mid_x+1, ry) and bool(rm[ry, mid_x+1]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Wire connections: cross intersection points
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = bool(wm[wr, max(0, wc-1)]) or bool(wm[wr, min(WORLD_W-1, wc+1)])
                col_ok = bool(wm[max(0, wr-1), wc]) or bool(wm[min(WORLD_H-1, wr+1), wc])
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    else:
        # Extend road network from existing roads toward powered empty areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            # Find powered but unroaded zones to target
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H-3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W-3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                # Find nearest road tile
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                # Step toward target
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                # Try horizontal first
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Prefer areas close to existing zones (density building)
        zone_near = dilate(zone_tiles, 4)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 1.0 if bool(zone_near[y, x]) else 0.0
            # Also prefer center of map somewhat
            scores[i] += 0.3 / (1.0 + abs(x - 60)/60.0 + abs(y - 50)/50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_positions = [
            (15, 9), (45, 9), (75, 9), (105, 9),
            (15, 33), (45, 33), (75, 33), (105, 33),
            (15, 57), (45, 57), (75, 57), (105, 57),
            (15, 81), (45, 81), (75, 81), (105, 81),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_positions = [
            (30, 21), (60, 21), (90, 21),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (30, 69), (60, 69), (90, 69),
            (15, 87), (45, 87), (75, 87), (105, 87),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 33), (90, 33), (30, 69), (90, 69),
            (60, 21), (60, 81), (15, 57), (105, 57),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
            (30, 50), (90, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire toward unpowered regions ----
    # Find areas with roads but no power
    needs_power = rm & ~near_power
    npys, npxs = np.where(needs_power)
    if len(npxs) > 0:
        ti = (step * 23) % len(npxs)
        tx, ty = int(npxs[ti]), int(npys[ti])
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend roads from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
