    """Bootstrap: place 3 coal plants in a triangle with connecting wires and seed roads"""
    actions = []
    # Three power plants: left, center, right
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 30))
