def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        # Target mix: 50% residential, 25% commercial, 25% industrial
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Dense plant grid every 18 cols, 15 rows ----
    plant_grid = []
    for py in range(10, 95, 15):
        for px in range(10, 115, 18):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion to connect plants and zones ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    # Unpowered plants need wires
    unpowered_plants = [(px, py) for px, py in plant_grid
                        if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Dense road grid — horizontal every 5 rows, vertical every 8 cols ----
    road_rows = list(range(5, 97, 5))
    for ry in road_rows:
        row_road = rm[ry, :]
        if int(np.sum(row_road)) < 100:
            # Try to build road where near power
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    left_ok = rx > 0 and bool(rm[ry, rx-1])
                    right_ok = rx < WORLD_W-1 and bool(rm[ry, rx+1])
                    up_ok = ry > 0 and bool(rm[ry-1, rx])
                    down_ok = ry < WORLD_H-1 and bool(rm[ry+1, rx])
                    if left_ok or right_ok or up_ok or down_ok:
                        return (Tool.ROAD, rx, ry)
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    road_cols = list(range(8, 116, 8))
    for cx in road_cols:
        for cy in range(4, 96):
            if bool(em[cy, cx]) and bool(near_power[cy, cx]):
                adj = (cy > 0 and bool(rm[cy-1, cx])) or (cy < WORLD_H-1 and bool(rm[cy+1, cx]))
                if adj:
                    return (Tool.ROAD, cx, cy)

    # ---- PHASE 4: Zone placement with commercial/industrial emphasis near center ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    zone_cand &= ~rm & ~wm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(rm[nr, nc]) or bool(wm[nr, nc]) or bool(pm[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.ones(len(cxs_arr)) * 9999.0

        # Prefer locations near center of map for commercial, edges for industrial
        tool = pick_tool()
        center_dist = np.abs(cxs_arr - 60).astype(float) + np.abs(cys_arr - 50).astype(float)

        if tool == Tool.COMMERCIAL:
            # Commercial near city center (60, 50)
            score = road_dist + center_dist * 0.3
        elif tool == Tool.INDUSTRIAL:
            # Industrial near edges
            score = road_dist - center_dist * 0.1
        else:
            # Residential: spread out, near roads
            if total_zones > 0:
                zone_ys, zone_xs = np.where(zone_tiles)
                stride = max(1, len(zone_xs) // 200)
                zone_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(zone_xs), stride):
                    d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
                score = road_dist * 1.5 - np.clip(zone_dist, 0, 15) * 0.2
            else:
                score = road_dist + center_dist * 0.5

        order = np.argsort(score)
        for i in range(min(len(order), 1000)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled with population ----
    if pop > 50:
        # Fire stations every 15 cols, 12 rows
        fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 15)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(px2, py2) for py2 in range(10, 92, 12) for px2 in range(10, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_grid = [(pkx, pky) for pky in range(7, 95, 7) for pkx in range(7, 115, 9)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 700:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (60, 50), (100, 50),
                        (20, 85), (60, 85), (100, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        # Upgrade to nuclear power
        nuke_locs = [(60, 50), (20, 20), (100, 20), (20, 80), (100, 80),
                     (40, 10), (80, 10), (40, 90), (80, 90), (60, 5), (60, 92)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(95, 10), (95, 85), (10, 10), (10, 85), (55, 5)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from existing road ----
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k = (step * 17) % len(rxs2)
        rx2, ry2 = int(rxs2[k]), int(rys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from power ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious closed-loop city builder
# Strategy: 6 coal plants in a 2x3 grid, dense wire grid, road grid, balanced zones

def init(obs, state):
    """Bootstrap 6 coal plants with wire spines and flanking roads."""
    actions = []
    # 2 columns x 3 rows of neighborhoods
    for px in [30, 90]:
        for py in [20, 50, 80]:
            actions.append((Tool.COALPOWER, px, py))
            for dy in range(-6, 7):
                actions.append((Tool.WIRE, px, py + dy))
            for dy in range(-6, 7):
                actions.append((Tool.ROAD, px - 2, py + dy))
                actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Zone counts ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Neighborhood anchors: 6 plants in 2 cols x 3 rows ---
    # Expand to more neighborhoods as pop grows
    all_anchors = []
    for px in [30, 90]:
        for py in [20, 50, 80]:
            all_anchors.append((px, py))
    # Extra anchors at col 60 once pop grows
    extra_anchors = [(60, 20), (60, 50), (60, 80)]
    # Corner anchors for very large cities
    corner_anchors = [(15, 35), (15, 65), (105, 35), (105, 65), (15, 10), (105, 10), (15, 90), (105, 90)]

    def num_active():
        if pop < 100:   return 2
        if pop < 250:   return 4
        if pop < 500:   return 6
        if pop < 800:   return 7
        if pop < 1200:  return 8
        if pop < 1800:  return 9
        if pop < 2500:  return 11
        return 14

    n_active = num_active()
    combined = all_anchors + extra_anchors + corner_anchors
    active_anchors = combined[:n_active]

    # --- ENSURE POWER PLANTS ---
    for (px, py) in active_anchors:
        y0 = max(0, py - 10); y1 = min(WORLD_H, py + 11)
        x0 = max(0, px - 10); x1 = min(WORLD_W, px + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find nearest empty spot
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- WIRE SPINE (vertical) around each anchor ---
    spine_half = min(25, 8 + pop // 15)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check wire coverage
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy in range(-4, 5):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # --- HORIZONTAL WIRE connecting anchors at same row ---
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1 = row_anchors[i][0]
            x2 = row_anchors[i + 1][0]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and (bool(em[yl, cx]) or bool(wm[yl, cx])) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # --- VERTICAL WIRE connecting anchor columns ---
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xc in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1 = col_anchors[i][1]
            y2 = col_anchors[i + 1][1]
            for cy in range(y1 + 1, y2):
                if ib(xc, cy) and (bool(em[cy, xc]) or bool(wm[cy, xc])) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # --- ROAD GRID: flanking roads parallel to wire spines ---
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        for offset_x in [-3, 3]:
            rx = px + offset_x
            cycle = (step + idx * 5) % 3
            for wr in wire_in_col[cycle::3]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # --- HORIZONTAL ROADS connecting neighborhoods ---
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        if len(row_anchors) < 2:
            continue
        x_left = row_anchors[0][0] - 3
        x_right = row_anchors[-1][0] + 3
        for horiz_y in [yl - 5, yl + 5]:
            if not (ib(x_left, horiz_y) and ib(x_right, horiz_y)):
                continue
            for cx in range(max(2, x_left), min(WORLD_W - 2, x_right + 1)):
                if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                    return (Tool.ROAD, cx, horiz_y)

    # --- VERTICAL ROADS connecting anchor rows ---
    if pop > 80:
        for xc in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                y1 = col_anchors[i][1]
                y2 = col_anchors[i + 1][1]
                for road_x in [xc - 4, xc + 4]:
                    for cy in range(y1, y2 + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- ZONE PLACEMENT ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # --- EXTEND ROADS from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES ---
    if pop > 50:
        fire_spots = [
            (8, 12), (40, 12), (70, 12), (105, 12),
            (8, 35), (40, 35), (70, 35), (105, 35),
            (8, 58), (40, 58), (70, 58), (105, 58),
            (8, 80), (40, 80), (70, 80), (105, 80),
            (25, 5), (60, 5), (95, 5),
            (25, 95), (60, 95), (95, 95),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (12, 8), (45, 8), (75, 8), (108, 8),
            (12, 42), (45, 42), (75, 42), (108, 42),
            (12, 65), (45, 65), (75, 65), (108, 65),
            (12, 90), (45, 90), (75, 90), (108, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (18, 6), (60, 6), (100, 6),
            (18, 92), (60, 92), (100, 92),
            (5, 50), (113, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [
            (5, 5), (113, 5), (5, 93), (113, 93),
            (58, 5), (58, 93), (5, 48), (113, 48),
            (30, 3), (88, 3), (30, 95), (88, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1800:
        for asp in [(55, 5), (5, 48), (113, 48), (55, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 92), (113, 92), (5, 5), (113, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PARKS near zones ---
    if pop > 100:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- EXTEND WIRE from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near zones ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

