    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.18:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Dense power plant grid ----
    # Plants every 20 cols, 20 rows for good coverage
    plant_grid_xs = list(range(10, WORLD_W - 5, 20))
    plant_grid_ys = list(range(10, WORLD_H - 5, 20))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network - connect plants with horizontal and vertical wires ----
    # Horizontal wire rows at plant y-positions
    wire_rows = list(range(10, WORLD_H - 5, 20))
    wire_cols = list(range(10, WORLD_W - 5, 20))

    # Extend horizontal wires across entire width
    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            # Start from nearest plant
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                dists = np.abs(pys - wr)
                nearest_idx = np.argmin(dists)
                nx = int(pxs[nearest_idx])
                if ib(nx, wr) and bool(em[wr, nx]):
                    return (Tool.WIRE, nx, wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left
        if left > 1 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        # Extend right
        if right < WORLD_W - 2 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)
        # Fill gaps
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    # Extend vertical wires full height
    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Dense road network ----
    # Roads parallel to wire rows, offset by 5 tiles (both sides)
    road_rows = []
    for wr in wire_rows:
        for off in [-5, -3, 3, 5]:
            r = wr + off
            if 3 < r < WORLD_H - 3:
                road_rows.append(r)
    road_cols = []
    for wc in wire_cols:
        for off in [-5, -3, 3, 5]:
            c = wc + off
            if 3 < c < WORLD_W - 3:
                road_cols.append(c)
    road_rows = sorted(set(road_rows))
    road_cols = sorted(set(road_cols))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Start road near a wire row
            nearest_wr = min(wire_rows, key=lambda w: abs(w - rr))
            # Find where that wire row has wire
            row_has = wm[nearest_wr, :] | pm[nearest_wr, :]
            if row_has.any():
                start_x = int(np.where(row_has)[0][0])
                if ib(start_x, rr) and bool(em[rr, start_x]) and not bool(pm[rr, start_x]):
                    return (Tool.ROAD, start_x, rr)
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Avoid infrastructure
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 150)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 150)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            spread_score = zone_dist * 0.5
        else:
            spread_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Score: very close to roads, moderately close to existing zones
        score = road_dist * 2.5 + spread_score

        order = np.argsort(score)
        # Vary starting offset to spread zones across the map
        off = (step * 11 + pop // 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 10:
        # Place fire stations on a dense grid
        fire_spots = [(fx, fy) for fy in range(6, 96, 12) for fx in range(6, 116, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 50:
        police_spots = [(px2, py2) for py2 in range(8, 94, 14) for px2 in range(8, 114, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150:
        park_spots = [(pkx, pky) for pky in range(10, 92, 8) for pkx in range(10, 112, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_spots = [(sx, sy) for sy in range(14, 88, 22) for sx in range(14, 108, 28)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        airport_spots = [
            (55, 7), (65, 7), (55, 92), (65, 92),
            (7, 44), (112, 44), (7, 56), (112, 56),
            (30, 7), (90, 7), (30, 92), (90, 92),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1000:
        seaport_spots = [
            (7, 50), (112, 50), (60, 4), (60, 95),
            (24, 4), (96, 4), (24, 95), (96, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:
            shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:
            shifted[1:, :] = power_src[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1:
            shifted[:-1, :] = rm[1:, :]
        elif dy == 1:
            shifted[1:, :] = rm[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = rm[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: extend roads near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6, 0), (-6, 0), (0, 6), (0, -6), (5, 0), (-5, 0), (0, 5), (0, -5)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 5 coal plants spread across map with wire spines and flanking roads."""
    actions = []
    # Five starting plants forming a grid: corners + center
    plants = [(20, 25), (100, 25), (60, 50), (20, 75), (100, 75)]
    for cx, cy in plants:
        actions.append((Tool.COALPOWER, cx, cy))
        # Short vertical wire spine
        for dy in [-1, 1, 2, -2]:
            actions.append((Tool.WIRE, cx, cy + dy))
        # Flanking roads
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Denser neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 5
        if pop < 150:   return 10
        if pop < 300:   return 18
        if pop < 600:   return 28
        if pop < 1200:  return 40
        if pop < 2500:  return 55
        if pop < 5000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    hood_set = set(active_hoods)

    # Aim for 30% ind, 35% com, 35% res
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(12):
            placed = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if placed:
                break

    # ---- PHASE 2: WIRE SPINES ----
    spine_range = 12

    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Rotate through hoods to spread work
        phase = (step + idx_h) % max(len(active_hoods), 1)
        if phase >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap from plant neighbors
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        # Horizontal neighbors at spacing 12
        for (hx2, hy2) in [(hx1 + 12, hy1), (hx1 + 24, hy1)]:
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        # Vertical neighbors
        for (hx2, hy2) in [(hx1, hy1 + 12), (hx1, hy1 + 24)]:
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        phase = (step + idx_h * 3) % max(len(active_hoods), 1)
        if phase >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Roads at hx-1, hx+1 (flanking vertical spine)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Roads at hy-1, hy+1 (flanking horizontal spine)
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road coverage mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (wire or plant within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (scaled more aggressively) ----
    if pop > 80:
        fire_spots = [
            (8, 10), (30, 10), (52, 10), (74, 10), (96, 10), (115, 10),
            (8, 28), (30, 28), (52, 28), (74, 28), (96, 28), (115, 28),
            (8, 46), (30, 46), (52, 46), (74, 46), (96, 46), (115, 46),
            (8, 64), (30, 64), (52, 64), (74, 64), (96, 64), (115, 64),
            (8, 82), (30, 82), (52, 82), (74, 82), (96, 82), (115, 82),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (18, 18), (44, 18), (70, 18), (96, 18), (116, 18),
            (18, 40), (44, 40), (70, 40), (96, 40), (116, 40),
            (18, 60), (44, 60), (70, 60), (96, 60), (116, 60),
            (18, 80), (44, 80), (70, 80), (96, 80), (116, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (33, 33), (83, 33), (33, 63), (83, 63),
            (58, 15), (58, 85), (10, 50), (110, 50),
            (20, 5), (100, 5), (20, 92), (100, 92),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (45, 50), (75, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(8, 90), (112, 90), (8, 8), (112, 8), (60, 95), (60, 2)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 6), (70, 6), (50, 93), (70, 93), (5, 48), (113, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross of wires + seed roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(5, 115):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(5, 95):
        actions.append((Tool.WIRE, 60, y))
    # Second power plant top-left
    actions.append((Tool.COALPOWER, 20, 20))
    # Third power plant bottom-right
    actions.append((Tool.COALPOWER, 100, 80))
    # Seed roads near center
    for x in range(50, 70):
        actions.append((Tool.ROAD, x, 55))
    for x in range(50, 70):
        actions.append((Tool.ROAD, x, 45))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Track placement queue in state
    if 'phase' not in state:
        state['phase'] = 'infrastructure'
        state['infra_step'] = 0

    # Define neighborhood centers — 6 neighborhoods across the map
    neighborhoods = [
        (20, 20), (60, 20), (100, 20),
        (20, 70), (60, 70), (100, 70),
    ]

    # Power plant grid: place plants every 30 cols, 30 rows
    plant_grid_xs = list(range(15, WORLD_W - 10, 30))
    plant_grid_ys = list(range(15, WORLD_H - 10, 30))

    # --- PHASE 1: Ensure sufficient power plants ---
    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Wire grid (horizontal every 10 rows, vertical every 10 cols) ---
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 3 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # --- PHASE 3: Road grid (horizontal every 8 rows offset by 4, vertical every 8 cols) ---
    road_rows = list(range(7, WORLD_H - 4, 8))
    road_cols = list(range(7, WORLD_W - 4, 8))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Start road from a point near power
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- PHASE 4: Zone placement with balanced RCI mix ---
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        rr2 = res_count / tz
        # Target: 50% RES, 25% COM, 25% IND
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.20:
            return Tool.COMMERCIAL
        if cr < 0.30 and (step // 50) % 3 == 0:
            return Tool.COMMERCIAL
        if ir < 0.30 and (step // 50) % 3 == 1:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    zone_cand = em & near_road & near_power
    # Margins
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H - 3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W - 3:] = False
    # Avoid infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer spreading out, but not too far
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                                  np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            # Bootstrap: place near neighborhood centers
            nhood_dist = np.full(len(cxs_arr), 9999.0)
            for nx, ny in neighborhoods:
                d = np.abs(cxs_arr - nx).astype(float) + np.abs(cys_arr - ny).astype(float)
                nhood_dist = np.minimum(nhood_dist, d)
            zone_score = nhood_dist

        score = road_dist * 1.2 + zone_score * 0.5
        order = np.argsort(score)
        # Use step+pop for variety
        off = (step * 7 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 50:
        fire_ys = list(range(12, WORLD_H - 5, 10))
        fire_xs = list(range(12, WORLD_W - 5, 15))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        pol_ys = list(range(15, WORLD_H - 5, 12))
        pol_xs = list(range(15, WORLD_W - 5, 18))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_ys = list(range(10, WORLD_H - 5, 8))
        park_xs = list(range(10, WORLD_W - 5, 10))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 800:
        stad_spots = [(sx, sy) for sy in range(15, 90, 20) for sx in range(15, 110, 25)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuc_spots = [(nx, ny) for ny in range(12, 90, 20) for nx in range(12, 110, 20)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 3000:
        airport_spots = [(60, 7), (55, 92), (7, 50), (112, 50)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 5000:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Wire extension toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 7: Road extension toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx2, cy2 = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx2 - int(usxs[j])) + abs(cy2 - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Fallback: road near plant
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: dense grid of coal plants + wire backbone + road seeds"""
    actions = []
    # Place coal plants on a 20x20 grid across the map
    plant_positions = []
    for py in range(15, 95, 20):
        for px in range(15, 115, 20):
            plant_positions.append((px, py))
            actions.append((Tool.COALPOWER, px, py))

    # Horizontal wire spines every 20 rows
    for wy in range(15, 95, 20):
        for wx in range(0, 120):
            actions.append((Tool.WIRE, wx, wy))

    # Vertical wire spines every 20 cols
    for wc in range(15, 115, 20):
        for wy in range(0, 100):
            actions.append((Tool.WIRE, wc, wy))

    # Road grid: horizontal roads midway between wire rows
    for ry in range(25, 95, 20):
        for rx in range(0, 120):
