    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Track state
    if 'phase' not in state:
        state['phase'] = 0
        state['road_rows'] = [7, 9, 19, 21, 31, 33, 43, 45, 55, 57, 67, 69, 79, 81, 91, 93]
        state['road_cols'] = [7, 9, 22, 24, 37, 39, 52, 54, 67, 69, 82, 84, 97, 99, 112, 114]
        state['wire_rows'] = [8, 20, 32, 44, 56, 68, 80, 92]
        state['wire_cols'] = [8, 23, 38, 53, 68, 83, 98, 113]
        state['civic_placed'] = set()

    wire_rows = state['wire_rows']
    wire_cols = state['wire_cols']
    road_rows = state['road_rows']
    road_cols = state['road_cols']

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target ratio: 50% RES, 30% COM, 20% IND
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # ===== PHASE 1: Lay horizontal road corridors flanking wire rows =====
    # Road rows should be on both sides of each wire row
    for wr in wire_rows:
        for offset in [-1, 1]:
            ry = wr + offset
            if not (0 < ry < WORLD_H - 1):
                continue
            row_wire = wm[wr, :] | pm[wr, :]
            for rx in range(1, WORLD_W - 1):
                if not bool(rm[ry, rx]) and bool(row_wire[rx]) and not bool(pm[ry, rx]):
                    if bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # ===== PHASE 2: Lay vertical road corridors flanking wire cols =====
    for wc in wire_cols:
        for offset in [-1, 1]:
            rcx = wc + offset
            if not (0 < rcx < WORLD_W - 1):
                continue
            col_wire = wm[:, wc] | pm[:, wc]
            for ry in range(1, WORLD_H - 1):
                if not bool(rm[ry, rcx]) and bool(col_wire[ry]) and not bool(pm[ry, rcx]):
                    if bool(em[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # ===== PHASE 3: Cross-connect roads between corridors =====
    # Every 3rd step try to connect road segments
    if step % 3 == 0:
        # Find road endpoints that could be extended
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            # Find powered areas needing roads
            needs_road = near_power & ~near_road & em
            needs_road[0:4, :] = False
            needs_road[WORLD_H-4:, :] = False
            needs_road[:, 0:4] = False
            needs_road[:, WORLD_W-4:] = False
            # Exclude wire corridors
            for wr in wire_rows:
                if 0 <= wr < WORLD_H:
                    needs_road[wr, :] = False
            for wc in wire_cols:
                if 0 <= wc < WORLD_W:
                    needs_road[:, wc] = False

            nrys, nrxs = np.where(needs_road)
            if len(nrxs) > 0:
                ti = (step * 17 + pop) % len(nrxs)
                tx, ty = int(nrxs[ti]), int(nrys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        # Don't build road on wire corridors
                        on_wire = (ny2 in wire_rows) or (nx2 in wire_cols)
                        if not on_wire:
                            return (Tool.ROAD, nx2, ny2)

    # ===== PHASE 4: Wire fallback - connect unpowered road areas =====
    if step % 5 == 0:
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23 + pop) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ===== ZONE PLACEMENT - main loop =====
    # Build zones in cells between road/wire corridors
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Exclude wire corridors (+/-1) and road corridors
    for wr in wire_rows:
        for dy in range(-1, 2):
            yy = wr + dy
            if 0 <= yy < WORLD_H:
                cand_mask[yy, :] = False
    for wc in wire_cols:
        for dx in range(-1, 2):
            xx = wc + dx
            if 0 <= xx < WORLD_W:
                cand_mask[:, xx] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: prefer existing zone neighbors, prefer center
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            # Center bias (moderate)
            cx_dist = abs(x - 60) / 60.0
            cy_dist = abs(y - 50) / 50.0
            scores[i] += 1.0 / (1.0 + cx_dist + cy_dist)
            # Bonus for being in dense road area
            if bool(near_road[y, x]) and bool(near_power[y, x]):
                scores[i] += 0.5

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ===== CIVIC SERVICES (closed-loop based on pop) =====
    # Fire stations spread across map
    if pop > 30:
        fire_grid = []
        for gy in range(3, WORLD_H-3, 18):
            for gx in range(3, WORLD_W-3, 20):
                fire_grid.append((gx, gy))
        for sx, sy in fire_grid:
            key = f'fire_{sx}_{sy}'
            if key not in state['civic_placed']:
                if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                    state['civic_placed'].add(key)
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_grid = []
        for gy in range(5, WORLD_H-5, 22):
            for gx in range(5, WORLD_W-5, 25):
                police_grid.append((gx, gy))
        for sx, sy in police_grid:
            key = f'police_{sx}_{sy}'
            if key not in state['civic_placed']:
                if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                    state['civic_placed'].add(key)
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (30, 25), (80, 25), (30, 50), (80, 50),
            (30, 75), (80, 75), (55, 15), (55, 85),
            (5, 45), (110, 45),
        ]
        for sx, sy in stadium_spots:
            key = f'stadium_{sx}_{sy}'
            if key not in state['civic_placed']:
                if ib(sx, sy) and bool(em[sy, sx]) and not bool(pm[sy, sx]):
                    state['civic_placed'].add(key)
                    return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Add nuclear plants to supplement coal
        nuke_spots = [
            (25, 5), (55, 5), (85, 5), (115, 5),
            (25, 94), (55, 94), (85, 94), (115, 94),
            (5, 25), (5, 50), (5, 75),
            (115, 25), (115, 50), (115, 75),
        ]
        for nx2, ny2 in nuke_spots:
            key = f'nuke_{nx2}_{ny2}'
            if key not in state['civic_placed']:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    state['civic_placed'].add(key)
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaport_spots = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 94)]
        for sx, sy in seaport_spots:
            key = f'seaport_{sx}_{sy}'
            if key not in state['civic_placed']:
                if ib(sx, sy) and bool(em[sy, sx]):
                    state['civic_placed'].add(key)
                    return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airport_spots = [(50, 3), (70, 3), (50, 96), (70, 96), (3, 45), (116, 45)]
        for sx, sy in airport_spots:
            key = f'airport_{sx}_{sy}'
            if key not in state['civic_placed']:
                if ib(sx, sy) and bool(em[sy, sx]):
                    state['civic_placed'].add(key)
                    return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        # Near zones preferred
        pys, pxs = np.where(park_cands & dilate(zone_tiles, 3))
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            on_wire = (py2 in wire_rows) or (px2 in wire_cols)
            if not on_wire and not bool(pm[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ===== FALLBACKS =====
    # Extend roads from existing network
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    on_wire = (ny2 in wire_rows) or (nx2 in wire_cols)
                    if not on_wire and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: try placing zone anywhere powered and roaded
    cand2 = em & near_road & near_power
    c2ys, c2xs = np.where(cand2)
    if len(c2xs) > 0:
        tool = pick_tool()
        offset2 = (step * 7 + pop * 11) % len(c2xs)
        for i in range(min(len(c2xs), 200)):
            k = (offset2 + i) % len(c2xs)
            zx2, zy2 = int(c2xs[k]), int(c2ys[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    return None

def init(obs, state):
    """Bootstrap: central power plant + cross wire + road grid seed"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(5, 115):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(5, 95):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads in 4 quadrants
    for x in range(5, 55, 1):
        actions.append((Tool.ROAD, x, 35))
    for x in range(65, 115, 1):
        actions.append((Tool.ROAD, x, 35))
    for x in range(5, 55, 1):
        actions.append((Tool.ROAD, x, 65))
    for x in range(65, 115, 1):
        actions.append((Tool.ROAD, x, 65))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # --- Phase 1: Power plants on a denser grid (every 20 cols, 20 rows) ---
    # Place coal plants in a 6x5 grid covering the map
    plant_positions = []
    for py in range(12, WORLD_H - 10, 18):
        for px in range(12, WORLD_W - 10, 18):
            plant_positions.append((px, py))

    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
        y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # --- Phase 2: Wire grid - horizontal wires every 9 rows ---
    wire_rows = list(range(9, WORLD_H - 5, 9))
    wire_cols = list(range(9, WORLD_W - 5, 9))

    # Extend horizontal wires across the full map
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            # Find nearest plant row and drop a seed wire
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 2 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # --- Phase 3: Dense road grid every 6 rows/cols between wire rows ---
    # Roads at offsets +3 and +6 from wire rows to create dense coverage
    road_rows = []
    for wr in wire_rows:
        for offset in [3, 6]:
            r = wr + offset
            if 3 < r < WORLD_H - 3:
                road_rows.append(r)
    road_rows = sorted(set(road_rows))

    road_cols = []
    for wc in wire_cols:
        for offset in [3, 6]:
            c = wc + offset
            if 3 < c < WORLD_W - 3:
                road_cols.append(c)
    road_cols = sorted(set(road_cols))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- Phase 4: Reactive zone placement with smart mix ---
    tz = max(total_zones, 1)
    ir = ind_count / tz
    cr = com_count / tz
    rr_ratio = res_count / tz

    # Target: 40% RES, 30% COM, 30% IND
    if ir < 0.30:
        tool = Tool.INDUSTRIAL
    elif cr < 0.30:
        tool = Tool.COMMERCIAL
    else:
        tool = Tool.RESIDENTIAL

    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rrow in road_rows:
        if 0 <= rrow < WORLD_H:
            zone_cand[rrow, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer locations not too close or too far from existing zones
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist > 12, min_zone_dist * 0.3, 0.0))
        else:
            # Spread from center initially
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.2 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 7 + pop % 13) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- Phase 5: Civic services (reactive to population) ---
    if pop > 20:
        fire_positions = [(fx, fy) for fy in range(14, WORLD_H - 5, 10) for fx in range(14, WORLD_W - 5, 15)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(pm[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        pol_positions = [(px, py) for py in range(17, WORLD_H - 5, 12) for px in range(17, WORLD_W - 5, 18)]
        for psx, psy in pol_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and not bool(pm[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_positions = [(pkx, pky) for pky in range(11, WORLD_H - 5, 8) for pkx in range(11, WORLD_W - 5, 10)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stad_spots = [(sx, sy) for sy in range(15, 90, 20) for sx in range(15, 105, 25)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]) and not bool(pm[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        # Add nuclear plants for more power capacity
        nuc_spots = [(nx, ny) for ny in range(10, 90, 20) for nx in range(10, 110, 20)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_spots = [(55, 6), (65, 6), (55, 93), (65, 93), (6, 45), (113, 45)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_spots = [(6, 50), (113, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Phase 6: Wire extension toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx2 - int(uzxs[j])) + abs(cy2 - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- Phase 7: Road extension toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy2 == -1: shifted[:-1, :] = rm[1:, :]
        elif dy2 == 1: shifted[1:, :] = rm[:-1, :]
        elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx2 == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx3, cy3 = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx3 - int(usxs[j])) + abs(cy3 - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- Fallback: extend roads from existing plants ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx3, dy3 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx3, ny3 = px2 + dx3, py2 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

