def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'phase' not in state:
        state['phase'] = 'infrastructure'
        state['wire_done'] = False
        state['road_done'] = False
        state['zone_idx'] = 0
        # Pre-planned neighborhood centers: a 5x4 grid of clusters
        clusters = []
        for cy in range(15, 90, 20):
            for cx in range(15, 115, 20):
                clusters.append((cx, cy))
        state['clusters'] = clusters
        state['cluster_idx'] = 0

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)
    zone_tiles = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        rr = res_count / tz
        # Target mix: 40% res, 30% com, 30% ind
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Build dense wire grid ----
    # Wire every 10 rows and 10 cols
    wire_rows = list(range(5, WORLD_H - 5, 10))
    wire_cols = list(range(5, WORLD_W - 5, 10))

    # Build horizontal wires
    for wr in wire_rows:
        # Find gaps in wire/plant row
        row_has_power = wm[wr, :] | pm[wr, :]
        if not row_has_power.any():
            # Start from nearest plant
            pys2, pxs2 = np.where(pm)
            if len(pxs2) > 0:
                idx = np.argmin(np.abs(pys2 - wr))
                sx = int(pxs2[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        idxs = np.where(row_has_power)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        if left > 3 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 4 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Build vertical wires
    for wc in wire_cols:
        col_has_power = wm[:, wc] | pm[:, wc]
        if not col_has_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        idxs = np.where(col_has_power)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        if top > 3 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # ---- PHASE 2: Ensure enough power plants ----
    # One plant per ~25x25 area
    plant_positions = []
    for py_p in range(12, WORLD_H - 10, 22):
        for px_p in range(12, WORLD_W - 10, 22):
            plant_positions.append((px_p, py_p))

    for ppx, ppy in plant_positions:
        x0, x1 = max(0, ppx - 14), min(WORLD_W, ppx + 15)
        y0, y1 = max(0, ppy - 14), min(WORLD_H, ppy + 15)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place at nearest empty wire-adjacent spot
            for dx2, dy2 in [(0,0),(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
                nx2, ny2 = ppx + dx2, ppy + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.COALPOWER, nx2, ny2)

    # ---- PHASE 3: Road grid - roads between wire rows ----
    # Roads at wire_rows + 5 (midpoints) both horizontal and vertical
    road_rows = sorted(set(wr + 5 for wr in wire_rows if wr + 5 < WORLD_H - 3))
    road_cols = sorted(set(wc + 5 for wc in wire_cols if wc + 5 < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        idxs = np.where(row_rd)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        idxs = np.where(col_rd)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # ---- PHASE 4: Aggressive zone placement ----
    zone_cand = em & near_road & near_power
    # Margins
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
            if wr - 1 >= 0: zone_cand[wr - 1, :] = False
            if wr + 1 < WORLD_H: zone_cand[wr + 1, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
            if wc - 1 >= 0: zone_cand[:, wc - 1] = False
            if wc + 1 < WORLD_W: zone_cand[:, wc + 1] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                t = tm[nr, nc]
                # allow empty or existing zone tiles
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer spreading: penalize too close, reward moderate distance
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            zone_score = -(np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.1

        # Score: minimize road distance, moderate zone spread
        score = road_dist * 2.0 + zone_score * 0.5
        order = np.argsort(score)
        # Varied offset based on step and pop to avoid repetition
        off = (step * 7 + (pop % 23) * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic buildings based on population ----
    if pop > 100:
        fire_positions = [(fx, fy) for fy in range(12, 95, 15) for fx in range(12, 115, 20)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        pol_positions = [(px2, py2) for py2 in range(15, 90, 18) for px2 in range(15, 110, 22)]
        for psx, psy in pol_positions:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_positions = [(pkx, pky) for pky in range(10, 95, 12) for pkx in range(10, 115, 14)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        stad_spots = [(sx, sy) for sy in range(20, 85, 30) for sx in range(20, 100, 35)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuc_spots = [(nx2, ny2) for ny2 in range(10, 90, 20) for nx2 in range(10, 110, 20)]
        for npx, npy in nuc_spots:
            x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
            y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
            if ib(npx, npy) and bool(em[npy, npx]) and not np.any(pm[y0:y1, x0:x1]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 3000:
        airport_spots = [(58, 8), (68, 8), (58, 90), (68, 90), (8, 45), (110, 45)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 5000:
        seaport_spots = [(8, 50), (110, 50), (60, 5), (60, 93)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy3, dx3 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy3 == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy3 == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx3 == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx3 == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 30)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy4, dx4 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy4 == -1: shifted[:-1, :] = rm[1:, :]
        elif dy4 == 1: shifted[1:, :] = rm[:-1, :]
        elif dx4 == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx4 == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 30)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))
    elif len(rxs_c) > 0:
        k = step % len(rxs_c)
        return (Tool.ROAD, int(rxs_c[k]), int(rys_c[k]))

    # Fallback: road near a plant
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx5, dy5 in [(7, 0), (-7, 0), (0, 7), (0, -7), (5, 0), (-5, 0), (0, 5), (0, -5)]:
            nx2, ny2 = px2 + dx5, py2 + dy5
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder combining best of both parents
# Strategy: dense 5x4 grid of neighborhoods with coal plants, wire spines,
# flanking roads, and reactive zone placement across the whole 120x100 map

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spines and flanking roads to seed growth."""
    actions = []
    # Three initial plants at key locations
    for px, py in [(20, 50), (60, 33), (100, 67)]:
        actions.append((Tool.COALPOWER, px, py))
        for dy in range(-5, 6):
            if ib2(px, py + dy):
                actions.append((Tool.WIRE, px, py + dy))
        for dy in range(-5, 6):
            if ib2(px - 1, py + dy):
                actions.append((Tool.ROAD, px - 1, py + dy))
            if ib2(px + 1, py + dy):
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions

def ib2(x, y):
    return 0 <= x < WORLD_W and 0 <= y < WORLD_H

def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 5x4 neighborhood grid: cols at 12,32,52,72,92,112; rows at 15,35,55,75,92
    # Actually let's do cols at [15,35,55,75,95,115] rows at [15,35,55,75,92]
    nh_cols = [15, 35, 55, 75, 95, 115]
    nh_rows = [15, 35, 55, 75, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]  # 30 hoods

    def num_active():
        if pop < 30:    return 2
        if pop < 80:    return 3
        if pop < 150:   return 5
        if pop < 300:   return 7
        if pop < 500:   return 10
        if pop < 800:   return 14
        if pop < 1200:  return 18
        if pop < 2000:  return 22
        if pop < 3000:  return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick active hoods spread across the map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at hood center first, then spiral out
            for r in range(12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: VERTICAL WIRE SPINES through hood centers ----
    spine_half = min(12, 5 + pop // 30)
    for (hx, hy) in active_hoods:
        spine_top = max(2, hy - spine_half)
        spine_bot = min(WORLD_H - 3, hy + spine_half)
        # Find existing wire in this column near the hood
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(hx, r) and bool(wm[r, hx])]
        plant_rows = [r for r in range(spine_top, spine_bot + 1)
                      if ib(hx, r) and bool(pm[r, hx])]
        anchored = wire_rows + plant_rows

        if not anchored:
            # Find any wire/plant near hx column to start extending
            for dy2 in range(-5, 6):
                ny = hy + dy2
                if ib(hx, ny) and (bool(wm[ny, hx]) or bool(pm[ny, hx])):
                    anchored.append(ny)
            if not anchored:
                # Try adjacent plant
                for dx2 in [-1, 1]:
                    for dy2 in range(-3, 4):
                        ny = hy + dy2
                        nx = hx + dx2
                        if ib(nx, ny) and bool(pm[ny, nx]):
                            # Place wire adjacent to plant in our column
                            if ib(hx, ny) and bool(em[ny, hx]):
                                return (Tool.WIRE, hx, ny)
                continue

        min_wr = min(anchored)
        max_wr = max(anchored)
        # Extend downward
        if max_wr < spine_bot:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]):
                if bool(em[nr, hx]) or bool(wm[nr, hx]):
                    return (Tool.WIRE, hx, nr)
        # Extend upward
        if min_wr > spine_top:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]):
                if bool(em[nr, hx]) or bool(wm[nr, hx]):
                    return (Tool.WIRE, hx, nr)

    # ---- PHASE 3: HORIZONTAL WIRE connecting hoods in same row ----
    row_map = {}
    for (hx, hy) in active_hoods:
        if hy not in row_map:
            row_map[hy] = []
        row_map[hy].append(hx)

    for hy, hxs in row_map.items():
        hxs_sorted = sorted(hxs)
        for i in range(len(hxs_sorted) - 1):
            x1_h = hxs_sorted[i]
            x2_h = hxs_sorted[i + 1]
            # Connect wire at row hy between x1_h and x2_h
            for cx in range(x1_h + 1, x2_h):
                if not ib(cx, hy): continue
                if bool(wm[hy, cx]) or bool(pm[hy, cx]): continue
                if not bool(em[hy, cx]): continue
                # Check adjacency
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, cx, hy)

    # ---- PHASE 4: VERTICAL WIRE connecting hoods in same column ----
    col_map = {}
    for (hx, hy) in active_hoods:
        if hx not in col_map:
            col_map[hx] = []
        col_map[hx].append(hy)

    for hx, hys in col_map.items():
        hys_sorted = sorted(hys)
        for i in range(len(hys_sorted) - 1):
            y1_h = hys_sorted[i]
            y2_h = hys_sorted[i + 1]
            for cy in range(y1_h + 1, y2_h):
                if not ib(hx, cy): continue
                if bool(wm[cy, hx]) or bool(pm[cy, hx]): continue
                if not bool(em[cy, hx]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, cy)

    # ---- PHASE 5: ROAD BUILDING flanking wire spines ----
    for idx, (hx, hy) in enumerate(active_hoods):
        spine_top = max(2, hy - spine_half)
        spine_bot = min(WORLD_H - 3, hy + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1)
                     if ib(hx, r) and bool(wm[r, hx])]
        if not wire_rows:
            continue
        cycle = (step + idx * 5) % 3
        for wr in wire_rows[cycle::3]:
            for rx in [hx - 1, hx + 1]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- PHASE 6: HORIZONTAL ROADS at hood y-levels ±3 ----
    if pop > 30:
        for hy, hxs in row_map.items():
            hxs_sorted = sorted(hxs)
            if len(hxs_sorted) < 2:
                continue
            x_min = hxs_sorted[0] - 1
            x_max = hxs_sorted[-1] + 1
            for horiz_y in [hy - 3, hy + 3]:
                if not (0 <= horiz_y < WORLD_H):
                    continue
                for cx in range(max(0, x_min), min(WORLD_W, x_max + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        # Only place if near wire
                        near_wire = False
                        for dy_check in range(-4, 5):
                            if ib(cx, horiz_y + dy_check) and (bool(wm[horiz_y + dy_check, cx]) or bool(pm[horiz_y + dy_check, cx])):
                                near_wire = True
                                break
                        if near_wire:
                            return (Tool.ROAD, cx, horiz_y)

    # ---- PHASE 7: VERTICAL ROADS connecting row levels ----
    if pop > 80:
        for hx in col_map:
            for rx in [hx - 3, hx + 3]:
                if not (0 <= rx < WORLD_W):
                    continue
                hys_sorted = sorted(col_map[hx])
                for i in range(len(hys_sorted) - 1):
                    y1_h = hys_sorted[i]
                    y2_h = hys_sorted[i + 1]
                    for cy in range(y1_h - 2, y2_h + 3):
                        if not ib(rx, cy): continue
                        if bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            near_wire = False
                            for dx_check in range(-4, 5):
                                if ib(rx + dx_check, cy) and (bool(wm[cy, rx + dx_check]) or bool(pm[cy, rx + dx_check])):
                                    near_wire = True
                                    break
                            if near_wire:
                                return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 8: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float) * 0.9
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 9: EXTEND ROADS from existing roads near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 10: CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (7, 12), (30, 12), (55, 12), (80, 12), (108, 12),
            (7, 30), (30, 30), (55, 30), (80, 30), (108, 30),
            (7, 50), (30, 50), (55, 50), (80, 50), (108, 50),
            (7, 68), (30, 68), (55, 68), (80, 68), (108, 68),
            (7, 87), (30, 87), (55, 87), (80, 87), (108, 87),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (20, 8), (50, 8), (80, 8), (110, 8),
            (20, 25), (50, 25), (80, 25), (110, 25),
            (20, 45), (50, 45), (80, 45), (110, 45),
            (20, 63), (50, 63), (80, 63), (110, 63),
            (20, 82), (50, 82), (80, 82), (110, 82),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 10), (40, 10), (70, 10), (100, 10),
            (10, 45), (40, 45), (70, 45), (100, 45),
            (10, 80), (40, 80), (70, 80), (100, 80),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        # Upgrade to nuclear power for better capacity
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (15, 22), (75, 22), (15, 72), (75, 72),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(6, 90), (114, 90), (6, 8), (114, 8), (60, 6), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (5, 45), (115, 45)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 11: PARKS to boost land value near zones ----
    if pop > 100 and step % 4 == 0:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3),
                                  (4, 0), (-4, 0), (0, 4), (0, -4)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place new plant near unpowered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- ABSOLUTE FALLBACK: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious multi-cluster city policy
# Strategy: 4 power plant clusters in a grid pattern across the map,
# each with horizontal road spines and flanking zones.
# Closed-loop: reacts to population, zone counts, and tile_map state.

def init(obs, state):
    """Bootstrap: place first coal plant near center-left with wire and roads."""
    actions = []
    # Primary plant
    actions.append((Tool.COALPOWER, 20, 50))
    # Wire connecting right from plant
    for dx in range(1, 6):
        actions.append((Tool.WIRE, 20 + dx, 50))
    # Horizontal road above and below wire spine
    for dx in range(0, 6):
        actions.append((Tool.ROAD, 20 + dx, 48))
        actions.append((Tool.ROAD, 20 + dx, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # 4 main clusters arranged in a 2x2 grid
    # Each cluster: (plant_x, plant_y, wire_row, road_above, road_below)
    clusters = [
        (20, 25, 25, 23, 27),   # top-left
        (60, 25, 25, 23, 27),   # top-right
        (20, 75, 75, 73, 77),   # bottom-left
        (60, 75, 75, 73, 77),   # bottom-right
        (95, 50, 50, 48, 52),   # center-right
        (20, 50, 50, 48, 52),   # center-left
        (60, 50, 50, 48, 52),   # center
        (95, 25, 25, 23, 27),   # far-right top
        (95, 75, 75, 73, 77),   # far-right bottom
    ]

    def num_active():
        if pop < 200:   return 1
        if pop < 600:   return 2
        if pop < 1200:  return 4
        if pop < 2500:  return 6
        if pop < 4000:  return 7
        return 9

    active = clusters[:num_active()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wr, ra, rb) in active:
        has_plant = any(
            ib(px+dx, py+dy) and bool(pm[py+dy, px+dx])
            for dx in range(-4,5) for dy in range(-4,5)
            if ib(px+dx, py+dy)
        )
        if not has_plant:
            # Try exact spot, then nearby
            for r in range(8):
                for dy2 in range(-r, r+1):
                    for dx2 in range(-r, r+1):
                        nx, ny = px+dx2, py+dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- HORIZONTAL WIRE SPINES ----
    # Each cluster gets a long horizontal wire at wire_row
    for (px, py, wr, ra, rb) in active:
        if not ib(px, wr):
            continue
        # Extend wire left and right from plant column
        extend = min(50, 10 + pop // 30)
        x_min = max(2, px - extend)
        x_max = min(WORLD_W - 3, px + extend)
        # Check missing wire segments
        for x in range(x_min, x_max + 1):
            if ib(x, wr) and not bool(wm[wr, x]) and not bool(pm[wr, x]) and bool(em[wr, x]):
                return (Tool.WIRE, x, wr)

    # ---- VERTICAL WIRE CONNECTIONS between top and bottom clusters ----
    # Connect wire rows vertically to share power
    if len(active) >= 4:
        for cx in [20, 60, 95]:
            for wy in range(25, 76):
                if ib(cx, wy) and not bool(wm[wy, cx]) and not bool(pm[wy, cx]) and bool(em[wy, cx]):
                    return (Tool.WIRE, cx, wy)

    # ---- ROAD BUILDING along wire spines ----
    # Build roads above and below each horizontal wire spine
    for (px, py, wr, ra, rb) in active:
        extend = min(50, 10 + pop // 30)
        x_min = max(2, px - extend)
        x_max = min(WORLD_W - 3, px + extend)
        # Cycle through segments
        seg_len = max(1, (x_max - x_min) // 4)
        off = (step * 3) % max(1, x_max - x_min + 1)
        for i in range(x_max - x_min + 1):
            x = x_min + (off + i) % (x_max - x_min + 1)
            if not ib(x, ra) or not ib(x, rb):
                continue
            if bool(em[ra, x]) and not bool(pm[ra, x]):
                return (Tool.ROAD, x, ra)
            if bool(em[rb, x]) and not bool(pm[rb, x]):
                return (Tool.ROAD, x, rb)

    # ---- VERTICAL ROADS connecting spines ----
    if len(active) >= 2:
        for cx in [20, 40, 60, 80, 95, 110]:
            for ry in range(24, 77):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]) and not bool(wm[ry, cx]):
                    # Only build roads near existing roads to keep connectivity
                    if any(ib(cx+dx, ry+dy) and bool(rm[ry+dy, cx+dx])
                           for dx,dy in [(0,1),(0,-1),(1,0),(-1,0)]):
                        return (Tool.ROAD, cx, ry)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # Target: 40% res, 35% com, 25% ind
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor masks for road and wire proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H+dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W+dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H+dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W+dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize near active cluster wire rows
        best_dist = np.full(len(cxs), 999999, dtype=float)
        for (px, py, wr, ra, rb) in active:
            d = np.abs(cxs - px) + np.abs(cys - wr)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- CIVIC SERVICES ----
    if pop > 200:
        fire_spots = [
            (35, 25), (75, 25), (35, 50), (75, 50),
            (35, 75), (75, 75), (10, 50), (110, 50),
            (55, 38), (55, 62), (20, 38), (95, 38),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        police_spots = [
            (30, 30), (70, 30), (30, 70), (70, 70),
            (50, 20), (50, 80), (10, 25), (110, 25),
            (10, 75), (110, 75), (55, 50), (30, 50),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [(50, 10), (50, 90), (10, 50), (110, 50), (80, 10), (80, 90)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        seaports = [(10, 10), (110, 10), (10, 90), (110, 90)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spine + seed roads near center"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(50, 72):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(40, 62):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads
    for x in range(48, 74):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 54, y))
        actions.append((Tool.ROAD, 66, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---------- helper: cheap morphological dilation ----------
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---------- zone-tool selector ----------
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---------- PHASE 1: Ensure enough power plants ----------
    # Grid of plants: every ~14 cols, every ~12 rows
    plant_grid_xs = list(range(10, WORLD_W - 5, 14))
    plant_grid_ys = list(range(10, WORLD_H - 5, 12))
    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 9), min(WORLD_W, ppx + 10)
            y0, y1 = max(0, ppy - 9), min(WORLD_H, ppy + 10)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---------- PHASE 2: Grow wire network reactively ----------
    # Wire spines: horizontal every 12 rows, vertical every 14 cols
    wire_rows = list(range(10, WORLD_H - 5, 12))
    wire_cols = list(range(10, WORLD_W - 5, 14))

    # Horizontal wires: extend existing or start new
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Start one if a plant is nearby in the column
            for wc in wire_cols:
                if ib(wc, wr) and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Fill gaps first
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)
        # Extend left
        if left > 3 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        # Extend right
        if right < WORLD_W - 4 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Vertical wires
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            for wr in wire_rows:
                if ib(wc, wr) and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        # Fill gaps
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)
        if top > 3 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # ---------- PHASE 3: Road network ----------
    # Roads placed offset from wire spines so zones fit between
    road_rows = sorted(set(
        r for wr in wire_rows for r in [wr - 4, wr + 4]
        if 4 < r < WORLD_H - 4
    ))
    road_cols = sorted(set(
        c for wc in wire_cols for c in [wc - 4, wc + 4]
        if 4 < c < WORLD_W - 4
    ))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            for rc in road_cols:
                if ib(rc, rr) and bool(em[rr, rc]) and not bool(pm[rr, rc]):
                    return (Tool.ROAD, rc, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Fill gaps
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)
        if left > 4 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            for rr in road_rows:
                if ib(rc, rr) and bool(em[rr, rc]) and not bool(pm[rr, rc]):
                    return (Tool.ROAD, rc, rr)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)
        if top > 4 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # ---------- PHASE 4: Zone placement ----------
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Don't place on wire rows/cols or road rows/cols (leave those clear)
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer near roads, near existing zones (but not too close)
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        score = np.zeros(len(cxs_arr), dtype=float)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
            score += road_dist * 1.0

        if len(zone_xs) > 0:
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer compact clustering but not overlap
            score += np.clip(zone_dist, 0, 8) * 0.5
        else:
            # First zone: go near center
            score += (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        tool = pick_tool()
        order = np.argsort(score)
        # Deterministic offset based on step to avoid getting stuck
        off = (step * 13 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---------- PHASE 5: Civic services ----------
    if pop > 100:
        fire_grid = [(fx, fy) for fy in range(14, 96, 14) for fx in range(14, 112, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_grid = [(px2, py2) for py2 in range(16, 90, 18) for px2 in range(16, 110, 22)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_grid = [(pkx, pky) for pky in range(18, 88, 12) for pkx in range(18, 106, 16)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 800:
        stadium_spots = [(sx, sy) for sy in range(22, 88, 28) for sx in range(22, 102, 32)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        airport_spots = [(55, 6), (65, 6), (55, 93), (65, 93), (6, 45), (113, 45), (30, 6), (90, 6)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_spots = [(6, 50), (113, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---------- Fallback: extend wire toward unpowered zones ----------
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy2 == -1:
            shifted[:-1, :] = power_src[1:, :]
        elif dy2 == 1:
            shifted[1:, :] = power_src[:-1, :]
        elif dx2 == -1:
            shifted[:, :-1] = power_src[:, 1:]
        elif dx2 == 1:
            shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0:
        unpowered = zone_tiles & ~near_power
        uzys, uzxs = np.where(unpowered)
        if len(uzxs) > 0:
            best_d = 1e9
            best_k = 0
            stride = max(1, len(uzxs) // 30)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - uzxs[j]) + abs(cy - uzys[j]) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
        else:
            k = step % len(wxs_c)
            return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---------- Last resort: road near existing power ----------
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        for i in range(len(pwr_xs)):
            k = (step * 11 + i) % len(pwr_xs)
            px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
            for dx3, dy3 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 0), (-3, 0), (0, 3), (0, -3)]:
                nx2, ny2 = px2 + dx3, py2 + dy3
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place two coal plants with wire connections and initial roads."""
    placements = []
    # Primary plant at (58, 50)
    placements.append((Tool.COALPOWER, 58, 50))
    # Wire spine going up and down from plant
    for y in range(44, 58):
        placements.append((Tool.WIRE, 60, y))
    # Road columns flanking wire spine
    for y in range(44, 58):
        placements.append((Tool.ROAD, 59, y))
        placements.append((Tool.ROAD, 61, y))
    # Second plant far right
    placements.append((Tool.COALPOWER, 85, 50))
    # Wire connecting plants
    for x in range(61, 84):
        placements.append((Tool.WIRE, x, 50))
    return placements


def act(obs, state):
    """
    Ambitious closed-loop policy:
    - Multiple power plant clusters across the map
    - Dense grid of roads with wire spines
    - Balanced zone placement in multiple neighborhoods
    - Services placed reactively based on population
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop
    step = obs.step

    # --- Phase tracking ---
    if 'phase' not in state:
        state['phase'] = 0
    if 'plant_placed' not in state:
        state['plant_placed'] = set()

    # Helper: pick zone tool based on current ratio
    def pick_tool(zx, zy):
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # Near center prefer commercial, edges prefer industrial
        dist_center = abs(zx - 60) + abs(zy - 50)
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25 and dist_center < 30:
            return Tool.COMMERCIAL
        if r_r < 0.55:
            return Tool.RESIDENTIAL
        return Tool.RESIDENTIAL

    # --- Compute neighbor masks ---
    def dilate(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                if dx * dx + dy * dy <= radius * radius:
                    sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                    sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                    r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                    c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                    result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = dilate(rm, 2)
    nbr_power = dilate(wm | pm, 6)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # =====================================================================
    # CLUSTER DEFINITIONS: multiple neighborhoods across the map
    # Each cluster: (plant_x, plant_y, wire_col, road_l, road_r, top, bot)
    # =====================================================================
    clusters = [
        # Primary cluster (center)
        {'px': 58, 'py': 50, 'wc': 60, 'rl': 59, 'rr': 61,
         'top': 30, 'bot': 70, 'min_pop': 0},
        # Left cluster
        {'px': 25, 'py': 50, 'wc': 27, 'rl': 26, 'rr': 28,
         'top': 30, 'bot': 70, 'min_pop': 300},
        # Right cluster
        {'px': 90, 'py': 50, 'wc': 92, 'rl': 91, 'rr': 93,
         'top': 30, 'bot': 70, 'min_pop': 300},
        # Upper-center cluster
        {'px': 58, 'py': 20, 'wc': 60, 'rl': 59, 'rr': 61,
         'top': 5, 'bot': 32, 'min_pop': 600},
        # Lower-center cluster
        {'px': 58, 'py': 78, 'wc': 60, 'rl': 59, 'rr': 61,
         'top': 67, 'bot': 95, 'min_pop': 600},
        # Upper-left
        {'px': 25, 'py': 20, 'wc': 27, 'rl': 26, 'rr': 28,
         'top': 5, 'bot': 32, 'min_pop': 1000},
        # Upper-right
        {'px': 90, 'py': 20, 'wc': 92, 'rl': 91, 'rr': 93,
         'top': 5, 'bot': 32, 'min_pop': 1000},
        # Lower-left
        {'px': 25, 'py': 78, 'wc': 27, 'rl': 26, 'rr': 28,
         'top': 67, 'bot': 95, 'min_pop': 1500},
        # Lower-right
        {'px': 90, 'py': 78, 'wc': 92, 'rl': 91, 'rr': 93,
         'top': 67, 'bot': 95, 'min_pop': 1500},
    ]

    # For each active cluster, ensure plant + wire spine + flanking roads
    for ci, cl in enumerate(clusters):
        if pop < cl['min_pop']:
            continue
        cx, cy = cl['px'], cl['py']
        wc = cl['wc']
        rl, rr = cl['rl'], cl['rr']
        top, bot = cl['top'], cl['bot']

        # Place plant if not present nearby
        plant_nearby = any(
            in_bounds(cx + dx, cy + dy) and bool(pm[cy + dy, cx + dx])
            for dy in range(-4, 5) for dx in range(-4, 5)
            if in_bounds(cx + dx, cy + dy)
        )
        if not plant_nearby:
            if in_bounds(cx, cy) and bool(em[cy, cx]):
                return (Tool.COALPOWER, cx, cy)
            # Try to bulldoze if occupied by non-plant
            for dy2 in range(-1, 2):
                for dx2 in range(-1, 2):
                    if in_bounds(cx + dx2, cy + dy2) and not bool(pm[cy + dy2, cx + dx2]):
                        pass  # auto-bulldoze handles it
            return (Tool.COALPOWER, cx, cy)

        # Extend wire spine vertically
        wire_in_col = [r for r in range(WORLD_H)
                       if 0 <= wc < WORLD_W and bool(wm[r, wc])]
        # Also consider plant tiles as wire sources
        plant_in_col = [r for r in range(WORLD_H)
                        if 0 <= wc - 2 < WORLD_W and bool(pm[r, cx])]

        # Seed wire adjacent to plant if none
        if not wire_in_col:
            for dy in range(-2, 3):
                ny = cy + dy
                if in_bounds(wc, ny) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)

        if wire_in_col:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < bot:
                nr = max_wr + 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > top:
                nr = min_wr - 1
                if in_bounds(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

        # Build road columns flanking wire spine
        if wire_in_col:
            step_off = step % max(len(wire_in_col), 1)
            for i in range(min(len(wire_in_col), 5)):
                wr = wire_in_col[(step_off + i * 3) % len(wire_in_col)]
                for rc in [rl, rr]:
                    if in_bounds(rc, wr) and bool(em[wr, rc]) and not bool(pm[wr, rc]):
                        return (Tool.ROAD, rc, wr)

    # =====================================================================
    # HORIZONTAL CONNECTORS between clusters (wire bridges at row py=50)
    # =====================================================================
    # Connect primary cluster wire col (60) to left cluster wire col (27) and right (92)
    connect_bridges = [
        (28, 58, 50),   # left to primary (row 50, cols 28..58)
        (62, 89, 50),   # primary to right (row 50, cols 62..89)
        (28, 58, 20),   # upper left to upper center
        (62, 89, 20),   # upper center to upper right
        (28, 58, 78),   # lower left to lower center
        (62, 89, 78),   # lower center to lower right
    ]
    if pop > 250:
        for x1, x2, by in connect_bridges:
            for bx in range(x1, x2 + 1):
                if in_bounds(bx, by) and bool(em[by, bx]) and not bool(pm[by, bx]):
                    return (Tool.WIRE, bx, by)

    # =====================================================================
    # HORIZONTAL ROAD CONNECTORS at intermediate rows
    # =====================================================================
    if pop > 400:
        for by in [40, 45, 55, 60]:
            for x1, x2 in [(29, 57), (63, 88)]:
                for bx in range(x1, x2, 3):
                    if in_bounds(bx, by) and bool(em[by, bx]) and not bool(pm[by, bx]):
                        return (Tool.ROAD, bx, by)

    # =====================================================================
    # ZONE PLACEMENT: scan candidates near roads and power
    # =====================================================================
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize closest to any existing zone or road
        # Use step-based offset for variety
        dists = np.abs(cxs - 60) + np.abs(cys - 50) // 2
        order = np.argsort(dists)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(zx, zy), zx, zy)
            checked += 1
            if checked > 120:
                break

    # =====================================================================
    # EXTEND ROADS near wire to fill gaps
    # =====================================================================
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 30)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # =====================================================================
    # SERVICES placed reactively
    # =====================================================================
    plant_ys, plant_xs = np.where(pm)
    px0 = int(plant_xs[0]) if len(plant_xs) > 0 else 58
    py0 = int(plant_ys[0]) if len(plant_ys) > 0 else 50

    service_locs = []
    if pop > 200:
        service_locs += [(px0 - 12, py0 - 8), (px0 + 12, py0 - 8)]
    if pop > 500:
        service_locs += [(px0 - 12, py0 + 8), (px0 + 12, py0 + 8)]
    if pop > 800:
        service_locs += [(px0, py0 - 20), (px0, py0 + 20)]
    if pop > 1200:
        service_locs += [(30, 50), (90, 50)]

    for sx, sy in service_locs:
        if in_bounds(sx, sy) and bool(em[sy, sx]):
            if pop < 500:
                return (Tool.FIRESTATION, sx, sy)
            else:
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        # Stadium
        for sx, sy in [(60, 35), (60, 65), (40, 50), (80, 50)]:
            if in_bounds(sx, sy) and zone_clear(sx, sy):
                return (Tool.STADIUM, sx, sy)

    # =====================================================================
    # FALLBACK: extend wire from existing wire
    # =====================================================================
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power grid with road access"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(10, 110):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(10, 90):
        actions.append((Tool.WIRE, 60, y))
    # Main horizontal roads
    for x in range(5, 115):
        if x not in range(58, 63):
            actions.append((Tool.ROAD, x, 44))
            actions.append((Tool.ROAD, x, 56))
    # Main vertical roads
    for y in range(5, 95):
        if y not in range(48, 53):
            actions.append((Tool.ROAD, 54, y))
            actions.append((Tool.ROAD, 66, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone type: aim for 25% ind, 35% com, 40% res (more commercial/industrial than parent)
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Power plant grid (every 18 cols, 16 rows, denser than parent) ---
    plant_grid_xs = list(range(12, 115, 18))
    plant_grid_ys = list(range(12, 92, 16))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 6), min(WORLD_W, ppx + 7)
            y0, y1 = max(0, ppy - 6), min(WORLD_H, ppy + 7)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Wire grid connecting all plants ---
    # Horizontal wires along plant rows
    for ppy in plant_grid_ys:
        row_wp = wm[ppy, :] | pm[ppy, :]
        if not row_wp.any():
            if ib(60, ppy) and em[ppy, 60]:
                return (Tool.WIRE, 60, ppy)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[ppy, left-1]):
            return (Tool.WIRE, left-1, ppy)
        if right < WORLD_W - 3 and bool(em[ppy, right+1]):
            return (Tool.WIRE, right+1, ppy)
        for x in range(left+1, right):
            if bool(em[ppy, x]) and not bool(pm[ppy, x]) and not bool(rm[ppy, x]):
                return (Tool.WIRE, x, ppy)

    # Vertical wires along plant cols
    for ppx in plant_grid_xs:
        col_wp = wm[:, ppx] | pm[:, ppx]
        if not col_wp.any():
            if ib(ppx, 50) and bool(em[50, ppx]):
                return (Tool.WIRE, ppx, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top-1, ppx]):
            return (Tool.WIRE, ppx, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, ppx]):
            return (Tool.WIRE, ppx, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, ppx]) and not bool(pm[y, ppx]) and not bool(rm[y, ppx]):
                return (Tool.WIRE, ppx, y)

    # --- PHASE 3: Dense road grid (every 8 tiles) ---
    # Roads offset 5 tiles from wire rows/cols, plus intermediate roads
    road_rows = set()
    for ppy in plant_grid_ys:
        road_rows.add(ppy - 5)
        road_rows.add(ppy + 5)
        # Add midpoints between plant rows
    # Also add roads every 8 rows across the whole map
    for rr in range(8, WORLD_H - 4, 8):
        road_rows.add(rr)
    road_rows = sorted(r for r in road_rows if 3 < r < WORLD_H - 3)

    road_cols = set()
    for ppx in plant_grid_xs:
        road_cols.add(ppx - 5)
        road_cols.add(ppx + 5)
    for rc in range(8, WORLD_W - 4, 8):
        road_cols.add(rc)
    road_cols = sorted(c for c in road_cols if 3 < c < WORLD_W - 3)

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Start from center
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # --- PHASE 4: Zone placement (closed-loop) ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        # Score: prefer cells near road, with some spread
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride_r = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride_r):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)

            if total_zones > 0:
                zys2, zxs2 = np.where(zone_tiles)
                stride_z = max(1, len(zxs2) // 100)
                zone_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(zxs2), stride_z):
                    d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
                # Prefer close to existing zones but also near roads
                score = zone_dist * 0.4 + road_dist * 0.6
            else:
                score = road_dist
        else:
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services (earlier thresholds for faster city growth) ---
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(10, 92, 14) for px2 in range(10, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(6, 95, 7) for pkx in range(6, 115, 9)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 400:
        stadium_spots = [(sx, sy) for sy in range(15, 88, 18) for sx in range(15, 108, 24)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuclear_spots = [(nx, ny) for ny in range(15, 88, 20) for nx in range(15, 108, 25)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy):
                x0, x1 = max(0, npx-7), min(WORLD_W, npx+8)
                y0, y1 = max(0, npy-7), min(WORLD_H, npy+8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[npy, npx]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1200:
        seaport_spots = [(10, 50), (109, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1500:
        airport_spots = [(60, 8), (60, 91), (8, 50), (111, 50)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- Fallback: extend wire toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False; wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False; wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0:
        if len(uzxs) > 0:
            best_d = 1e9; best_k = 0
            stride = max(1, len(uzxs) // 20)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
        else:
            k = step % len(wxs_c)
            return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- Fallback: road near power plants ---
    pwr_ys2, pwr_xs2 = np.where(pm)
    if len(pwr_xs2) > 0:
        for i in range(len(pwr_xs2)):
            k = (step * 13 + i) % len(pwr_xs2)
            px2, py2 = int(pwr_xs2[k]), int(pwr_ys2[k])
            for dx2, dy2 in [(5,0),(-5,0),(0,5),(0,-5),(3,0),(-3,0),(0,3),(0,-3)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

# Compact, well-powered city builder
# Strategy: 3x3 grid of neighborhoods, each with its own coal plant
# Dense zones packed around road/wire crosses

def init(obs, state):
    """Bootstrap: place first coal plant + wire spine + roads."""
    actions = []
    # Primary plant at center
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for d in range(-3, 4):
        if d != 0:
            actions.append((Tool.WIRE, cx + d, cy))
            actions.append((Tool.WIRE, cx, cy + d))
    # Roads flanking the wire cross
    for d in range(-3, 4):
        actions.append((Tool.ROAD, cx - 1, cy + d))
        actions.append((Tool.ROAD, cx + 1, cy + d))
        actions.append((Tool.ROAD, cx + d, cy - 1))
        actions.append((Tool.ROAD, cx + d, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # 3x3 grid of neighborhood centers spread across the map
    hood_xs = [20, 60, 100]
    hood_ys = [20, 50, 80]
    all_hoods = [(x, y) for y in hood_ys for x in hood_xs]

    # Unlock hoods progressively
    def num_active():
        if pop < 100:   return 1
        if pop < 300:   return 2
        if pop < 700:   return 3
        if pop < 1500:  return 5
        if pop < 3000:  return 7
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Always include center hood first, then spread out
    active_hoods = []
    priority = [4, 1, 3, 5, 7, 0, 2, 6, 8]  # center first, then ring
    for idx in priority[:n_active]:
        if idx < len(all_hoods):
            active_hoods.append(all_hoods[idx])

    # --- 1. ENSURE POWER PLANTS ---
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at center or nearby empty spot
            for r in range(10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # --- 2. BUILD WIRE CROSS AT EACH HOOD ---
    for (hx, hy) in active_hoods:
        # Find plant position in hood area
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        psub = pm[y0:y1, x0:x1]
        pys, pxs = np.where(psub)
        if len(pys) == 0:
            continue
        px_local = int(pxs[0]) + x0
        py_local = int(pys[0]) + y0

        # Wire horizontally and vertically from plant, radius 8
        radius = 8
        # Horizontal
        for dx in range(-radius, radius + 1):
            nx = px_local + dx
            if ib(nx, py_local) and not bool(pm[py_local, nx]):
                if bool(em[py_local, nx]):
                    return (Tool.WIRE, nx, py_local)
        # Vertical
        for dy in range(-radius, radius + 1):
            ny = py_local + dy
            if ib(px_local, ny) and not bool(pm[ny, px_local]):
                if bool(em[ny, px_local]):
                    return (Tool.WIRE, px_local, ny)

    # --- 3. CONNECT WIRE SPINES BETWEEN HOODS ---
    # Build a wire bus connecting adjacent hoods
    for i, (hx1, hy1) in enumerate(active_hoods):
        for hx2, hy2 in active_hoods:
            if (hx2, hy2) <= (hx1, hy1):
                continue
            # Only connect close hoods
            dist = abs(hx2 - hx1) + abs(hy2 - hy1)
            if dist > 55:
                continue
            # Find plant positions for both
            def get_plant_pos(hx, hy):
                x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
                y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
                psub = pm[y0:y1, x0:x1]
                pys, pxs = np.where(psub)
                if len(pys) == 0:
                    return hx, hy
                return int(pxs[0]) + x0, int(pys[0]) + y0

            p1x, p1y = get_plant_pos(hx1, hy1)
            p2x, p2y = get_plant_pos(hx2, hy2)

            # Draw wire path: horizontal then vertical
            # Horizontal leg at p1y
            mn_x, mx_x = min(p1x, p2x), max(p1x, p2x)
            for cx in range(mn_x, mx_x + 1):
                if ib(cx, p1y) and bool(em[p1y, cx]) and not bool(pm[p1y, cx]):
                    return (Tool.WIRE, cx, p1y)
            # Vertical leg at p2x
            mn_y, mx_y = min(p1y, p2y), max(p1y, p2y)
            for cy in range(mn_y, mx_y + 1):
                if ib(p2x, cy) and bool(em[cy, p2x]) and not bool(pm[cy, p2x]):
                    return (Tool.WIRE, p2x, cy)

    # --- 4. BUILD ROADS FLANKING WIRE SPINES ---
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        psub = pm[y0:y1, x0:x1]
        pys, pxs = np.where(psub)
        if len(pys) == 0:
            continue
        px_local = int(pxs[0]) + x0
        py_local = int(pys[0]) + y0

        radius = 8
        # Roads parallel to horizontal wire (at py_local +/- 1)
        for road_y in [py_local - 1, py_local + 1]:
            if not ib(px_local, road_y):
                continue
            for dx in range(-radius, radius + 1):
                nx = px_local + dx
                if ib(nx, road_y) and bool(em[road_y, nx]) and not bool(pm[road_y, nx]):
                    # Check if near wire
                    if bool(wm[py_local, nx]) if ib(nx, py_local) else False:
                        return (Tool.ROAD, nx, road_y)

        # Roads parallel to vertical wire (at px_local +/- 1)
        for road_x in [px_local - 1, px_local + 1]:
            if not ib(road_x, py_local):
                continue
            for dy in range(-radius, radius + 1):
                ny = py_local + dy
                if ib(road_x, ny) and bool(em[ny, road_x]) and not bool(pm[ny, road_x]):
                    if bool(wm[ny, px_local]) if ib(px_local, ny) else False:
                        return (Tool.ROAD, road_x, ny)

    # --- 5. EXTEND ROAD NETWORK ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        k_start = (step * 11) % len(road_xs)
        for i in range(min(len(road_xs), 40)):
            k = (k_start + i * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            # Extend in all 4 directions if empty and near wire
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Check if near a wire within 2 tiles
                    near_wire = False
                    for wy_off in range(-2, 3):
                        for wx_off in range(-2, 3):
                            if ib(nx + wx_off, ny + wy_off) and bool(wm[ny + wy_off, nx + wx_off]):
                                near_wire = True
                                break
                        if near_wire:
                            break
                    if near_wire:
                        return (Tool.ROAD, nx, ny)

    # --- 6. ZONE PLACEMENT ---
    zone_tiles = resm | comm | indm

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Target: 50% residential, 30% commercial, 20% industrial
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Compute neighbor road coverage (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute neighbor power (within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hood centers
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx) + np.abs(cys2 - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- 7. CIVIC SERVICES ---
    if pop > 300:
        fire_spots = [(20, 20), (60, 20), (100, 20),
                      (20, 50), (60, 50), (100, 50),
                      (20, 80), (60, 80), (100, 80)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 800:
        police_spots = [(30, 30), (70, 30), (110, 30),
                        (30, 65), (70, 65), (110, 65),
                        (30, 90), (70, 90), (110, 90)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 2000:
        stadiums = [(40, 35), (80, 35), (40, 65), (80, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 4000:
        seaports = [(10, 90), (110, 90)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 6000:
        airports = [(55, 10), (55, 85)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- 8. PARKS near roads ---
    if pop > 500 and step % 4 == 0:
        park_cands = np.where(em & nbr_road & nbr_power)
        if len(park_cands[0]) > 0:
            idx = (step * 19) % len(park_cands[0])
            py3, px3 = int(park_cands[0][idx]), int(park_cands[1][idx])
            if ib(px3, py3) and bool(em[py3, px3]):
                return (Tool.PARK, px3, py3)

    # --- 9. FALLBACK: extend wire from existing ---
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        k2 = (step * 13) % len(wire_xs2)
        for i in range(min(len(wire_xs2), 30)):
            k = (k2 + i * 5) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants spread across map with wire and road spines."""
    actions = []
    # Place 4 power plants at strategic locations
    plants = [(20, 20), (90, 20), (20, 75), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically from plant
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # More ambitious: 16 neighborhoods in a 4x4 grid covering the whole map
    # Plant locations offset from zone centers
    all_anchors = []
    for col_x in [15, 45, 75, 105]:
        for row_y in [15, 35, 60, 82]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 4
        if pop < 250:   return 6
        if pop < 500:   return 8
        if pop < 800:   return 10
        if pop < 1200:  return 12
        if pop < 1800:  return 14
        return 16

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS near each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        for r in range(1, 14):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE: vertical from each plant toward anchor zone area ----
    spine_half = min(25, 8 + pop // 8)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting anchors in same row ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anch = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anch) - 1):
            wx1 = row_anch[i][0]
            wx2 = row_anch[i + 1][0]
            for cx in range(wx1 + 1, wx2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows in same column ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xc in x_cols:
        col_anch = sorted([(px, py) for (px, py) in active_anchors if px == xc], key=lambda a: a[1])
        for i in range(len(col_anch) - 1):
            wy1 = col_anch[i][1]
            wy2 = col_anch[i + 1][1]
            for cy in range(wy1 + 1, wy2):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    return (Tool.WIRE, xc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 3
        rl = px - 1
        rr = px + 1
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 10:
        for yl in y_levels:
            row_anch = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
            if len(row_anch) < 2:
                continue
            rl1 = row_anch[0][0] - 1
            rr_last = row_anch[-1][0] + 1
            for horiz_y in [yl - 3, yl + 3]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS ROADS connecting row levels ----
    if pop > 40 and len(y_levels) >= 2:
        for xc in x_cols:
            for road_x in [xc - 2, xc + 2]:
                for i in range(len(y_levels) - 1):
                    y1 = y_levels[i]
                    y2 = y_levels[i + 1]
                    if not ib(road_x, y1) or not ib(road_x, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (triggered by population thresholds) ----
    if pop > 40:
        fire_spots = [
            (7, 10), (37, 10), (67, 10), (97, 10),
            (7, 30), (37, 30), (67, 30), (97, 30),
            (7, 52), (37, 52), (67, 52), (97, 52),
            (7, 72), (37, 72), (67, 72), (97, 72),
            (7, 90), (37, 90), (67, 90), (97, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (12, 8), (52, 8), (82, 8), (112, 8),
            (12, 42), (52, 42), (82, 42), (112, 42),
            (12, 68), (52, 68), (82, 68), (112, 68),
            (12, 92), (52, 92), (82, 92), (112, 92),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (28, 5), (68, 5), (108, 5),
            (28, 95), (68, 95), (108, 95),
            (5, 25), (5, 55), (5, 82),
            (115, 25), (115, 55), (115, 82),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        # Add nuclear plants for more coverage
        nuke_spots = [
            (55, 5), (5, 50), (115, 50), (55, 95),
            (30, 50), (90, 50), (55, 25), (55, 75),
            (5, 10), (115, 10), (5, 90), (115, 90),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1800:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value near existing zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- EXTEND WIRE from existing wire to fill gaps ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
