def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio: 50% res, 30% com, 20% ind (more commercial focus)
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plants in grid pattern ----
    # Dense plant grid every 20 cols, 20 rows
    plant_grid_xs = list(range(10, WORLD_W - 5, 20))
    plant_grid_ys = list(range(10, WORLD_H - 5, 20))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 8), min(WORLD_W, ppx + 9)
            y0, y1 = max(0, ppy - 8), min(WORLD_H, ppy + 9)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Horizontal wire network ----
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest = pxs[np.argmin(np.abs(pys - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if bool(em[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads between wire rows
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 4)
        road_rows.append(wr + 4)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 4)
        road_cols.append(wc + 4)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement (closed-loop) ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    # Don't place on infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Prefer spots close to existing zones for density
        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 3, 1000.0, np.where(min_zone_dist > 15, min_zone_dist * 0.5, 0.0))
        else:
            # Start near center
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.1

        score = road_dist * 1.5 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 11 + pop) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 30:
        fire_spots = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 114, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_spots = [(px2, py2) for py2 in range(8, 95, 14) for px2 in range(8, 114, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_spots = [(pkx, pky) for pky in range(8, 94, 8) for pkx in range(8, 114, 10)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 500:
        stadium_spots = [(sx, sy) for sy in range(15, 88, 25) for sx in range(15, 110, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuclear_spots = [(nx, ny) for ny in range(15, 90, 20) for nx in range(15, 110, 20)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-10), min(WORLD_W, npx+11)
                y0, y1 = max(0, npy-10), min(WORLD_H, npy+11)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_spots = [(55, 7), (65, 7), (55, 92), (65, 92),
                         (7, 44), (112, 44), (7, 56), (112, 56)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: place road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(7,0),(-7,0),(0,7),(0,-7),(5,0),(-5,0),(0,5),(0,-5)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants spread across the map with wire/road spines."""
    actions = []
    # Four power plants at strategic positions
    plants = [(30, 30), (90, 30), (30, 70), (90, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        # Road flanking on both sides
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    # Horizontal wire connecting plants at same row
    for cx in range(32, 90):
        actions.append((Tool.WIRE, cx, 30))
        actions.append((Tool.WIRE, cx, 70))
    # Vertical wire connecting top/bottom plants
    for cy in range(32, 70):
        actions.append((Tool.WIRE, 30, cy))
        actions.append((Tool.WIRE, 90, cy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% residential, 30% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 12 neighborhoods across the map (4 cols x 3 rows)
    # Centers at x=20,50,80,110 and y=20,50,80
    all_anchors = []
    for col_x in [20, 50, 80, 110]:
        for row_y in [20, 50, 80]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 6
        if pop < 500:  return 8
        if pop < 800:  return 10
        if pop < 1200: return 12
        return 12

    n_active = min(num_active(), len(all_anchors))
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS near each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 10); y1 = min(WORLD_H, py + 11)
        x0 = max(0, px - 10); x1 = min(WORLD_W, px + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            # Try to place plant at anchor, else spiral out
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: vertical spine at each anchor x ----
    spine_half = min(22, 8 + pop // 15)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for wy in range(spine_top, spine_bot + 1):
            if ib(px, wy) and bool(em[wy, px]) and not bool(pm[wy, px]):
                return (Tool.WIRE, px, wy)

    # ---- WIRE GRID: horizontal connections at anchor y-levels ----
    y_levels = sorted(set(py for (px, py) in active_anchors))
    for yl in y_levels:
        row_xs = sorted([px for (px, py) in active_anchors if py == yl])
        if len(row_xs) >= 2:
            for i in range(len(row_xs) - 1):
                x1, x2 = row_xs[i], row_xs[i + 1]
                for cx in range(x1 + 1, x2):
                    if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                        return (Tool.WIRE, cx, yl)

    # ---- WIRE GRID: vertical connections between rows ----
    x_cols = sorted(set(px for (px, py) in active_anchors))
    for xc in x_cols:
        col_ys = sorted([py for (px, py) in active_anchors if px == xc])
        if len(col_ys) >= 2:
            for i in range(len(col_ys) - 1):
                y1, y2 = col_ys[i], col_ys[i + 1]
                for cy in range(y1 + 1, y2):
                    if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                        return (Tool.WIRE, xc, cy)

    # ---- ROADS: grid flanking the wire spines ----
    road_offsets = [-3, -2, 2, 3]
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        cycle = (step + idx * 5) % 4
        for roff in road_offsets:
            rx = px + roff
            if not ib(rx, py):
                continue
            for ry in range(spine_top + cycle, spine_bot + 1, 4):
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 10:
        for yl in y_levels:
            row_xs = sorted([px for (px, py) in active_anchors if py == yl])
            if len(row_xs) < 2:
                continue
            x_min = row_xs[0] - 4
            x_max = row_xs[-1] + 4
            for horiz_y in [yl - 4, yl + 4]:
                for cx in range(max(1, x_min), min(WORLD_W - 1, x_max + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS ROADS connecting y-rows ----
    if pop > 40:
        for xc in x_cols:
            y_sorted = sorted(y_levels)
            for i in range(len(y_sorted) - 1):
                y1, y2 = y_sorted[i], y_sorted[i + 1]
                for rx in [xc - 4, xc + 4]:
                    if not ib(rx, y1) or not ib(rx, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT near active anchors ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float)
                 + np.abs(cys - py).astype(float) * 0.9)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [
            (8, 10), (40, 10), (70, 10), (105, 10),
            (8, 35), (40, 35), (70, 35), (105, 35),
            (8, 60), (40, 60), (70, 60), (105, 60),
            (8, 88), (40, 88), (70, 88), (105, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 8), (45, 8), (75, 8), (108, 8),
            (15, 38), (45, 38), (75, 38), (108, 38),
            (15, 62), (45, 62), (75, 62), (108, 62),
            (15, 88), (45, 88), (75, 88), (108, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (12, 5), (55, 5), (100, 5),
            (12, 93), (55, 93), (100, 93),
            (5, 50), (114, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (35, 5), (85, 5), (35, 94), (85, 94),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a 3x2 grid with wire and road stubs."""
    actions = []
    plant_positions = [
        (20, 25), (60, 25), (100, 25),
        (20, 75), (60, 75), (100, 75),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertical
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connecting top row plants
    for cx in range(20, 101):
        actions.append((Tool.WIRE, cx, 25))
    # Horizontal wire connecting bottom row plants
    for cx in range(20, 101):
        actions.append((Tool.WIRE, cx, 75))
    # Vertical wire connecting rows at center
    for cy in range(25, 76):
        actions.append((Tool.WIRE, 60, cy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% residential, 30% commercial, 20% industrial
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 primary anchors in 3x2 grid, plus 6 secondary = 12 total
    primary_anchors = [
        (20, 25), (60, 25), (100, 25),
        (20, 75), (60, 75), (100, 75),
    ]
    secondary_anchors = [
        (40, 50), (80, 50),
        (20, 50), (100, 50),
        (60, 50),
        (40, 25), (80, 25), (40, 75), (80, 75),
    ]
    all_anchors = primary_anchors + secondary_anchors

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 6
        if pop < 600:  return 8
        if pop < 1000: return 10
        if pop < 1500: return 12
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS near each active anchor ----
    for (px, py) in active_anchors[:6]:  # Only for primary anchors
        x0 = max(0, px - 10); x1 = min(WORLD_W, px + 11)
        y0 = max(0, py - 10); y1 = min(WORLD_H, py + 11)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: horizontal at y=25, y=50, y=75; vertical at x=20,40,60,80,100 ----
    wire_rows = [25, 50, 75]
    wire_cols = [20, 40, 60, 80, 100]

    # Extend horizontal wires
    for wy in wire_rows:
        x_start, x_end = 15, 105
        for cx in range(x_start, x_end + 1):
            if ib(cx, wy) and not bool(pm[wy, cx]):
                if bool(em[wy, cx]):
                    return (Tool.WIRE, cx, wy)

    # Extend vertical wires
    for wx in wire_cols:
        y_start, y_end = 20, 80
        for cy in range(y_start, y_end + 1):
            if ib(wx, cy) and not bool(pm[cy, wx]):
                if bool(em[cy, wx]):
                    return (Tool.WIRE, wx, cy)

    # ---- ROAD NETWORK ----
    # Roads parallel to wire rows (offset by +-2)
    road_y_lines = []
    for wy in wire_rows:
        road_y_lines.extend([wy - 2, wy + 2])

    for ry in road_y_lines:
        if not ib(15, ry) or not ib(105, ry):
            continue
        for cx in range(15, 106):
            if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                return (Tool.ROAD, cx, ry)

    # Roads parallel to wire cols (offset by +-2)
    road_x_lines = []
    for wx in wire_cols:
        road_x_lines.extend([wx - 2, wx + 2])

    for rx in road_x_lines:
        if not ib(rx, 20) or not ib(rx, 80):
            continue
        for cy in range(20, 81):
            if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    # Road proximity: within 3 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power proximity: within 8 tiles
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-8, 9):
        for dx in range(-8, 9):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: dense grid between roads and wires ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) +
                 np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS near existing zones ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scale with pop) ----
    if pop > 40:
        fire_spots = [
            (10, 15), (35, 15), (65, 15), (90, 15), (110, 15),
            (10, 40), (35, 40), (65, 40), (90, 40), (110, 40),
            (10, 60), (35, 60), (65, 60), (90, 60), (110, 60),
            (10, 85), (35, 85), (65, 85), (90, 85), (110, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (15, 20), (50, 20), (85, 20), (110, 20),
            (15, 50), (50, 50), (85, 50), (110, 50),
            (15, 80), (50, 80), (85, 80), (110, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (10, 5), (55, 5), (100, 5),
            (10, 92), (55, 92), (100, 92),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (10, 50), (110, 50),
            (60, 5), (60, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 94), (115, 94), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- DENSE INFILL near roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k3 = (step * 17) % max(len(road_xs2), 1)
        checked2 = 0
        for offset in range(min(len(road_xs2), 400)):
            k = (step_k3 + offset * 11) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (2, -2), (-2, -2)]:
                zx3, zy3 = rx3 + dx3, ry3 + dy3
                if ib(zx3, zy3) and bool(nbr_wire[zy3, zx3]) and zone_clear(zx3, zy3):
                    return (pick_tool(), zx3, zy3)
            checked2 += 1
            if checked2 > 300:
                break

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Ambitious closed-loop city builder v2
# Strategy: Dense grid of neighborhoods covering the full map
# 8 cols x 6 rows = 48 neighborhoods, each with its own coal plant
# Wire mesh connects all neighborhoods, roads serve zones
# Balanced zone mix: 40% RES, 30% COM, 30% IND
# Civic services placed aggressively

def init(obs, state):
    """Bootstrap: two central coal plants + wire cross + roads."""
    actions = []
    # Two coal plants side by side for redundancy
    for cx, cy in [(55, 50), (65, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dx in range(-3, 4):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-3, 4):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
    # Connect the two plants with wire
    for x in range(56, 65):
        actions.append((Tool.WIRE, x, 50))
    # Roads flanking each spine
    for cy in [50]:
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, 54, cy + dy))
            actions.append((Tool.ROAD, 66, cy + dy))
    return actions[:20]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 8 cols x 6 rows = 48 neighborhoods ----
    # Spaced 14 apart horizontally, 15 apart vertically
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [9, 24, 39, 55, 70, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 20
        if pop < 3000:  return 28
        if pop < 6000:  return 36
        if pop < 10000: return 42
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Use first n_active hoods, prioritizing central ones
    center_order = sorted(range(len(all_hoods)),
                          key=lambda i: abs(all_hoods[i][0] - 57) + abs(all_hoods[i][1] - 47))
    active_hoods = [all_hoods[center_order[i]] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at hood center or nearby empty spot
            for r in range(10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE SPINES from each plant outward ----
    spine_range = 8
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical wire at hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal wire at hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            # Horizontal neighbors (same row, adjacent col)
            if hy1 == hy2 and abs(hx2 - hx1) == 14:
                mid_y = hy1
                x_start, x_end = min(hx1, hx2) + 1, max(hx1, hx2)
                for cx2 in range(x_start, x_end):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Vertical neighbors (same col, adjacent row)
            if hx1 == hx2 and abs(hy2 - hy1) == 15:
                mid_x = hx1
                y_start, y_end = min(hy1, hy2) + 1, max(hy1, hy2)
                for cy2 in range(y_start, y_end):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    spine_range2 = 7
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step // 2 + idx_h) % max(len(active_hoods) // 2, 1) != 0:
            continue
        # Roads at hx-1 and hx+1 (flanking vertical spine)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range2, spine_range2 + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Roads at hy-1 and hy+1 (flanking horizontal spine)
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range2, spine_range2 + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Cycle through based on step to ensure variety
        cycle = (step // 3) % 10
        if ir < 0.28 and cycle < 3:
            return Tool.INDUSTRIAL
        if cr < 0.28 and cycle < 6:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers: must be empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step-based offset to explore different candidates
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES placed aggressively ----
    # Fire stations: dense grid every 16 tiles
    if pop > 80:
        for fx in range(12, WORLD_W, 16):
            for fy in range(12, WORLD_H, 16):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 300:
        for px2 in range(16, WORLD_W, 20):
            for py2 in range(16, WORLD_H, 20):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 800:
        stadiums = [(25, 25), (95, 25), (25, 75), (95, 75),
                    (60, 10), (60, 90), (10, 50), (110, 50),
                    (40, 50), (80, 50), (60, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 8), (112, 8), (8, 92), (112, 92), (60, 5), (60, 95), (5, 50), (115, 50)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(40, 5), (80, 5), (40, 95), (80, 95), (5, 40), (5, 65), (115, 40), (115, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop cities ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(57, 47), (28, 22), (86, 22), (28, 72), (86, 72),
                         (57, 10), (57, 85), (10, 47), (110, 47)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants spread across middle row with wire+road seeds."""
    actions = []
    # Three plants at y=50, spread horizontally
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
        # Wire cross from each plant
        for d in range(-6, 7):
            actions.append((Tool.WIRE, px + d, 50))
            actions.append((Tool.WIRE, px, 50 + d))
        # Road flanking wires
        for d in range(-6, 7):
            actions.append((Tool.ROAD, px + d, 48))
            actions.append((Tool.ROAD, px + d, 52))
            actions.append((Tool.ROAD, px - 2, 50 + d))
            actions.append((Tool.ROAD, px + 2, 50 + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 7)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Define cluster grid: scales with population
    all_cluster_cols = [15, 38, 60, 82, 105]
    all_cluster_rows = [18, 40, 60, 82]

    def active_clusters():
        if pop < 50:
            return [(60, 50)]
        if pop < 200:
            return [(38, 50), (60, 50), (82, 50)]
        if pop < 600:
            return [(15, 50), (38, 50), (60, 50), (82, 50), (105, 50)]
        if pop < 1200:
            return [(15, 40), (38, 40), (60, 40), (82, 40), (105, 40),
                    (15, 60), (38, 60), (60, 60), (82, 60), (105, 60)]
        if pop < 2500:
            return [(cx, cy) for cy in [18, 50, 82]
                    for cx in [15, 38, 60, 82, 105]]
        # Full 5x4 grid
        return [(cx, cy) for cy in all_cluster_rows
                for cx in all_cluster_cols]

    clusters = active_clusters()
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        if not bool(np.any(pm[py0:py1, px0:px1])):
            for r in range(15):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- EXTEND WIRE CROSS FROM EACH PLANT ----
    spine_reach = min(22, 6 + pop // 25)
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Horizontal wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            # Vertical wire
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH HORIZONTAL WIRE ----
    for cy in active_rows_set:
        row_cx = sorted([cx for cx, c_cy in clusters if c_cy == cy])
        for i in range(len(row_cx) - 1):
            c1, c2 = row_cx[i], row_cx[i + 1]
            for x in range(c1, c2 + 1):
                if ib(x, cy) and not bool(pm[cy, x]) and not bool(wm[cy, x]) and bool(em[cy, x]):
                    return (Tool.WIRE, x, cy)

    # ---- CONNECT CLUSTERS WITH VERTICAL WIRE ----
    for cx in active_cols_set:
        col_cy = sorted([cy for c_cx, cy in clusters if c_cx == cx])
        for i in range(len(col_cy) - 1):
            r1, r2 = col_cy[i], col_cy[i + 1]
            for y in range(r1, r2 + 1):
                if ib(cx, y) and not bool(pm[y, cx]) and not bool(wm[y, cx]) and bool(em[y, cx]):
                    return (Tool.WIRE, cx, y)

    # ---- BUILD ROAD GRID AROUND EACH CLUSTER ----
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        # Horizontal roads above/below wire spine
        for road_y in [cy - 2, cy + 2]:
            if not ib(cx, road_y): continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)
        # Vertical roads left/right of wire spine
        for road_x in [cx - 2, cx + 2]:
            if not ib(road_x, cy): continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]) and not bool(rm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    if pop > 100:
        for cy in active_rows_set:
            row_cx2 = sorted([cx for cx, c_cy in clusters if c_cy == cy])
            for i in range(len(row_cx2) - 1):
                c1, c2 = row_cx2[i], row_cx2[i + 1]
                for road_y in [cy - 3, cy + 3]:
                    if not (0 <= road_y < WORLD_H): continue
                    for x in range(c1 - 2, c2 + 3):
                        if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]) and not bool(rm[road_y, x]):
                            return (Tool.ROAD, x, road_y)

    if pop > 300:
        for cx in active_cols_set:
            col_cy2 = sorted([cy for c_cx, cy in clusters if c_cx == cx])
            for i in range(len(col_cy2) - 1):
                r1, r2 = col_cy2[i], col_cy2[i + 1]
                for road_x in [cx - 3, cx + 3]:
                    if not (0 <= road_x < WORLD_W): continue
                    for y in range(r1 - 2, r2 + 3):
                        if ib(road_x, y) and bool(em[y, road_x]) and not bool(pm[y, road_x]) and not bool(rm[y, road_x]):
                            return (Tool.ROAD, road_x, y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- ADDITIONAL ROAD EXTENSION NEAR WIRE ----
    road_arr_y, road_arr_x = np.where(rm)
    if len(road_arr_x) > 0:
        step_k = (step * 11) % max(len(road_arr_x), 1)
        for offset in range(min(len(road_arr_x), 80)):
            k = (step_k + offset * 7) % len(road_arr_x)
            rx, ry = int(road_arr_x[k]), int(road_arr_y[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fy in range(10, 95, 18) for fx in range(10, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px, py) for py in range(12, 90, 20) for px in range(12, 112, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        for sx, sy in [(25, 8), (60, 8), (95, 8), (25, 92), (60, 92), (95, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(5, 18), (5, 50), (5, 82), (115, 18), (115, 50), (115, 82),
                      (38, 5), (60, 5), (82, 5), (38, 94), (60, 94), (82, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for ax, ay in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sx2, sy2 in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend wire ----
    wire_arr_y, wire_arr_x = np.where(wm)
    if len(wire_arr_x) > 0:
        step_k2 = (step * 13) % max(len(wire_arr_x), 1)
        for offset in range(min(len(wire_arr_x), 60)):
            k = (step_k2 + offset * 5) % len(wire_arr_x)
            wx3, wy3 = int(wire_arr_x[k]), int(wire_arr_y[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: multiple coal plants + dense wire grid + road grid"""
    actions = []
    # Place coal plants in a 4x4 grid pattern
    plant_xs = [15, 45, 75, 105]
    plant_ys = [12, 37, 62, 87]
    for py in plant_ys:
        for px in plant_xs:
            actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire corridors at plant rows
    for py in plant_ys:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, py))
    # Vertical wire corridors at plant cols
    for px in plant_xs:
        for y in range(1, 99):
            actions.append((Tool.WIRE, px, y))
    # Horizontal roads flanking each wire row
    for py in plant_ys:
        for x in range(1, 119):
            if py - 2 > 0:
                actions.append((Tool.ROAD, x, py - 2))
            if py + 2 < 99:
                actions.append((Tool.ROAD, x, py + 2))
    # Vertical roads flanking each wire col
    for px in plant_xs:
        for y in range(1, 99):
            if px - 2 > 0:
                actions.append((Tool.ROAD, px - 2, y))
            if px + 2 < 119:
                actions.append((Tool.ROAD, px + 2, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target zone ratios: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire corridors at plant positions
    wire_rows = [12, 37, 62, 87]
    wire_cols = [15, 45, 75, 105]

    # ---- PHASE 1: ENSURE PLANTS EXIST ----
    plant_positions = [(px, py) for py in wire_rows for px in wire_cols]
    for px, py in plant_positions:
        x0, x1 = max(0, px-6), min(WORLD_W, px+7)
        y0, y1 = max(0, py-6), min(WORLD_H, py+7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CORRIDORS ----
    phase = step % 6

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row_power[wx]):
                    adj = (wx > 0 and bool(row_power[wx-1])) or \
                          (wx < WORLD_W-1 and bool(row_power[wx+1]))
                    if adj and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(col_power[wy]):
                    adj = (wy > 0 and bool(col_power[wy-1])) or \
                          (wy < WORLD_H-1 and bool(col_power[wy+1]))
                    if adj and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking horizontal wire corridors
        for wr in wire_rows:
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                continue
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_power[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking vertical wire corridors
        for wc in wire_cols:
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                continue
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_power[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Additional mid-corridor roads between plant rows/cols for more road access
        mid_road_rows = [24, 49, 74]  # between wire rows
        mid_road_cols = [30, 60, 90]  # between wire cols
        for mry in mid_road_rows:
            if not (0 < mry < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mry, rx]) and bool(near_power[mry, rx]) and not bool(pm[mry, rx]):
                    # Check adjacent road connectivity
                    adj = (bool(rm[mry-1, rx]) if mry > 0 else False) or \
                          (bool(rm[mry+1, rx]) if mry < WORLD_H-1 else False) or \
                          (bool(rm[mry, rx-1]) if rx > 0 else False) or \
                          (bool(rm[mry, rx+1]) if rx < WORLD_W-1 else False)
                    if adj:
                        return (Tool.ROAD, rx, mry)
        for mcx in mid_road_cols:
            if not (0 < mcx < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mcx]) and bool(near_power[ry, mcx]) and not bool(pm[ry, mcx]):
                    adj = (bool(rm[ry-1, mcx]) if ry > 0 else False) or \
                          (bool(rm[ry+1, mcx]) if ry < WORLD_H-1 else False) or \
                          (bool(rm[ry, mcx-1]) if mcx > 0 else False) or \
                          (bool(rm[ry, mcx+1]) if mcx < WORLD_W-1 else False)
                    if adj:
                        return (Tool.ROAD, mcx, ry)

    else:
        # Extend roads into powered areas from existing road ends
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H-3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W-3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17 + pop * 3) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    # Zones in the "cells" between the wire corridors and roads
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid placing zones on wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            # Prefer near existing zones for density
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            # Prefer cells between wire rows (avoid corridor edges)
            min_wr_dist = min(abs(y - wr) for wr in wire_rows)
            scores[i] += min(min_wr_dist, 5) * 0.2
            min_wc_dist = min(abs(x - wc) for wc in wire_cols)
            scores[i] += min(min_wc_dist, 5) * 0.2

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES (tiered by pop) ----
    if pop > 30:
        fire_positions = [
            (28, 12), (58, 12), (88, 12),
            (28, 37), (58, 37), (88, 37),
            (28, 62), (58, 62), (88, 62),
            (28, 87), (58, 87), (88, 87),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (18, 24), (48, 24), (78, 24), (108, 24),
            (18, 49), (48, 49), (78, 49), (108, 49),
            (18, 74), (48, 74), (78, 74), (108, 74),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (33, 24), (63, 24), (93, 24),
            (33, 49), (63, 49), (93, 49),
            (33, 74), (63, 74), (93, 74),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear power at key spots
        nuke_spots = [
            (15, 12), (45, 12), (75, 12), (105, 12),
            (15, 37), (45, 37), (75, 37), (105, 37),
            (15, 62), (45, 62), (75, 62), (105, 62),
            (15, 87), (45, 87), (75, 87), (105, 87),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2):
                # Check if there's an old coal plant here, place nuclear nearby
                x0, x1 = max(0, nx2-4), min(WORLD_W, nx2+5)
                y0, y1 = max(0, ny2-4), min(WORLD_H, ny2+5)
                has_nuke = False
                for ny3 in range(y0, y1):
                    for nx3 in range(x0, x1):
                        if tm[ny3, nx3] in PLANT_TILES and tm[ny3, nx3] > 500:  # nuclear
                            has_nuke = True
                if not has_nuke and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 90), (110, 90), (5, 5), (110, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 90), (65, 90), (50, 5), (65, 5)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:2, :] = False
        park_cands[WORLD_H-2:, :] = False
        park_cands[:, 0:2] = False
        park_cands[:, WORLD_W-2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire toward unpowered roads ----
    needs_power = rm & ~near_power
    npys, npxs = np.where(needs_power)
    if len(npxs) > 0:
        ti = (step * 23) % len(npxs)
        tx, ty = int(npxs[ti]), int(npys[ti])
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs2[best_wi]), int(wire_ys2[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend roads from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants in a 3x2 grid with wire spines."""
    actions = []
    # Plants at 3 columns x 2 rows
    for px in [25, 60, 95]:
        for py in [30, 70]:
            actions.append((Tool.COALPOWER, px, py))
            # Wire spine vertical
            for dy in range(-3, 4):
                actions.append((Tool.WIRE, px, py + dy))
            # Flanking roads
            for dy in range(-3, 4):
