def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- INFRASTRUCTURE GRID DEFINITION ----
    # Power wire corridors every 12 tiles
    wire_rows = list(range(8, WORLD_H, 12))   # 8,20,32,44,56,68,80,92
    wire_cols = list(range(8, WORLD_W, 12))   # 8,20,32,44,56,68,80,92,104,116

    # Road corridors offset by 1 from wire corridors (dual parallel roads)
    road_main_rows = [r + 1 for r in wire_rows]  # 9,21,33,45,57,69,81,93
    road_main_cols = [c + 1 for c in wire_cols]  # 9,21,33,45,57,69,81,93,105,117

    # Plant positions at intersections of wire grid (every 3rd intersection)
    plant_positions = []
    for i, wr in enumerate(wire_rows):
        for j, wc in enumerate(wire_cols):
            if i % 3 == 0 and j % 3 == 0:
                plant_positions.append((wc, wr))

    # More plants for full coverage
    extra_plants = []
    for i, wr in enumerate(wire_rows):
        for j, wc in enumerate(wire_cols):
            if (i + j) % 4 == 2:
                extra_plants.append((wc, wr))

    all_plants = plant_positions + extra_plants

    # ---- PHASE SELECTION ----
    # Use step modulo to cycle through different build tasks
    phase = step % 8

    # ---- HELPER: neighbor masks ----
    def make_neighbor_mask(base_mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                if abs(dx) + abs(dy) > radius:
                    continue
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= base_mask[sr0:sr1, sc0:sc1]
        return result

    # ---- PHASE 0: ENSURE COAL PLANTS ----
    if phase == 0:
        # Check all plant positions, place missing ones
        for (px, py) in all_plants:
            if not ib(px, py):
                continue
            x0, x1 = max(0, px - 3), min(WORLD_W, px + 4)
            y0, y1 = max(0, py - 3), min(WORLD_H, py + 4)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Only place if we have funds and area is plausible
                if bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)
                # Try nearby
                for r in range(1, 5):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = px + dx, py + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 1: WIRE HORIZONTAL CORRIDORS ----
    elif phase == 1:
        # Extend wire along wire_rows, connecting to existing wire/plants
        for wr in wire_rows:
            if not ib(0, wr):
                continue
            # Find leftmost connected wire in this row
            row_has_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_wire):
                # No wire in this row yet - place near a plant
                for (px, py) in all_plants:
                    if abs(py - wr) <= 2 and ib(px, wr):
                        if bool(em[wr, px]) and not bool(pm[wr, px]):
                            return (Tool.WIRE, px, wr)
                continue
            # Extend wire rightward from existing wire
            wire_xs = np.where(row_has_wire)[0]
            rightmost = int(wire_xs[-1])
            for wx in range(rightmost + 1, WORLD_W - 1):
                if bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)
                elif bool(pm[wr, wx]):
                    break
                else:
                    break
            # Extend wire leftward
            leftmost = int(wire_xs[0])
            for wx in range(leftmost - 1, 1, -1):
                if bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)
                elif bool(pm[wr, wx]):
                    break
                else:
                    break

    # ---- PHASE 2: WIRE VERTICAL CORRIDORS ----
    elif phase == 2:
        for wc in wire_cols:
            if not ib(wc, 0):
                continue
            col_has_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_wire):
                for (px, py) in all_plants:
                    if abs(px - wc) <= 2 and ib(wc, py):
                        if bool(em[py, wc]) and not bool(pm[py, wc]):
                            return (Tool.WIRE, wc, py)
                continue
            wire_ys = np.where(col_has_wire)[0]
            bottommost = int(wire_ys[-1])
            for wy in range(bottommost + 1, WORLD_H - 1):
                if bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)
                elif bool(pm[wy, wc]):
                    break
                else:
                    break
            topmost = int(wire_ys[0])
            for wy in range(topmost - 1, 1, -1):
                if bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)
                elif bool(pm[wy, wc]):
                    break
                else:
                    break

    # ---- PHASE 3: ROAD HORIZONTAL ----
    elif phase == 3:
        for rr in road_main_rows:
            if not ib(0, rr) or rr >= WORLD_H:
                continue
            # Check if wire exists in adjacent row (for power proximity)
            wr_near = None
            for wr in wire_rows:
                if abs(wr - rr) <= 2:
                    wr_near = wr
                    break
            if wr_near is None:
                continue
            # Extend road along this row where wire exists above/below
            row_road = rm[rr, :]
            row_wire_near = wm[wr_near, :] | pm[wr_near, :]
            # Find segments of wire and build roads there
            for rx in range(2, WORLD_W - 2):
                if bool(row_wire_near[rx]) and not bool(row_road[rx]) and bool(em[rr, rx]):
                    # Check adjacency to existing road
                    adj = (rx > 0 and bool(rm[rr, rx-1])) or (rx < WORLD_W-1 and bool(rm[rr, rx+1]))
                    if adj or (wr_near == rr - 1 or wr_near == rr + 1):
                        return (Tool.ROAD, rx, rr)

    # ---- PHASE 4: ROAD VERTICAL ----
    elif phase == 4:
        for rc in road_main_cols:
            if not ib(rc, 0) or rc >= WORLD_W:
                continue
            wc_near = None
            for wc in wire_cols:
                if abs(wc - rc) <= 2:
                    wc_near = wc
                    break
            if wc_near is None:
                continue
            col_road = rm[:, rc]
            col_wire_near = wm[:, wc_near] | pm[:, wc_near]
            for ry in range(2, WORLD_H - 2):
                if bool(col_wire_near[ry]) and not bool(col_road[ry]) and bool(em[ry, rc]):
                    adj = (ry > 0 and bool(rm[ry-1, rc])) or (ry < WORLD_H-1 and bool(rm[ry+1, rc]))
                    if adj:
                        return (Tool.ROAD, rc, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    elif phase == 5 or phase == 6:
        def pick_tool():
            t = max(total_zones, 1)
            ir = ind_count / t
            cr = com_count / t
            rr_rat = res_count / t
            # Target: 40% RES, 30% COM, 30% IND
            if ir < 0.28:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

        # Build neighbor masks
        nbr_road = make_neighbor_mask(rm, 2)
        nbr_power = make_neighbor_mask(wm | pm, 4)

        zone_tiles = resm | comm | indm

        def zone_clear(zx, zy):
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    nr, nc = zy + dr, zx + dc
                    if not ib(nc, nr):
                        return False
                    if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                        return False
            return True

        # Candidate positions: empty, near road, near power
        cand = em & nbr_road & nbr_power
        # Avoid edges
        cand[0:2, :] = False
        cand[WORLD_H-2:, :] = False
        cand[:, 0:2] = False
        cand[:, WORLD_W-2:] = False

        # Score: closer to wire/road intersections = better
        # Find wire/road intersection points
        cys, cxs = np.where(cand)
        if len(cxs) > 0:
            # Prefer spots at wire grid intersections
            tool = pick_tool()
            # Use step offset for variety
            offset = (step * 17 + (1 if phase == 6 else 0)) % max(len(cxs), 1)
            # Score by distance to nearest wire corridor intersection
            scores = np.zeros(len(cxs))
            for i, (zx, zy) in enumerate(zip(cxs, cys)):
                # Distance to nearest wire row
                dr = min(abs(zy - wr) for wr in wire_rows)
                # Distance to nearest wire col
                dc = min(abs(zx - wc) for wc in wire_cols)
                # Want to be near but not ON wire lines (zones need space)
                scores[i] = -(dr + dc) + (1.0 / (1 + abs(dr - 2)) + 1.0 / (1 + abs(dc - 2)))
            order = np.argsort(-scores)
            for i in range(min(len(order), 500)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

    # ---- PHASE 7: CIVIC SERVICES + INFRASTRUCTURE GAPS ----
    else:
        # Place civic services based on pop
        if pop > 50:
            fire_spots = [
                (24, 12), (72, 12), (108, 12),
                (12, 36), (48, 36), (84, 36), (114, 36),
                (24, 60), (72, 60), (108, 60),
                (12, 84), (48, 84), (84, 84), (114, 84),
            ]
            for (sx, sy) in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 200:
            police_spots = [
                (36, 24), (84, 24),
                (12, 48), (60, 48), (108, 48),
                (36, 72), (84, 72),
                (12, 96), (60, 96), (108, 96),
            ]
            for (sx, sy) in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 600:
            stadiums = [(42, 44), (78, 44), (42, 56), (78, 56)]
            for (sx, sy) in stadiums:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 1200:
            seaports = [(10, 90), (110, 90)]
            for (sx, sy) in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2500:
            airports = [(55, 6), (65, 6)]
            for (sx, sy) in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

        # Parks for land value
        if pop > 100 and step % 10 == 7:
            nbr_road2 = make_neighbor_mask(rm, 2)
            nbr_power2 = make_neighbor_mask(wm | pm, 4)
            park_cand = em & nbr_road2 & nbr_power2
            pys, pxs = np.where(park_cand)
            if len(pxs) > 0:
                idx = (step * 31) % len(pxs)
                return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

        # Fill wire gaps: find disconnected wire/plant cells and connect them
        # Look for wire cells with empty neighbors in direction of uncovered area
        wire_cells_y, wire_cells_x = np.where(wm | pm)
        if len(wire_cells_x) > 0:
            k = (step * 19) % len(wire_cells_x)
            for i in range(min(len(wire_cells_x), 50)):
                idx = (k + i) % len(wire_cells_x)
                wx, wy = int(wire_cells_x[idx]), int(wire_cells_y[idx])
                # Extend in direction of nearest unconnected wire corridor
                # Find nearest wire row/col that has no wire
                min_d = 999
                best_dir = None
                for wr in wire_rows:
                    if abs(wr - wy) < min_d and not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                        # Check if going that direction helps
                        dy = 1 if wr > wy else -1
                        ny = wy + dy
                        if ib(wx, ny) and bool(em[ny, wx]):
                            min_d = abs(wr - wy)
                            best_dir = (0, dy)
                for wc in wire_cols:
                    if abs(wc - wx) < min_d and not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                        dx = 1 if wc > wx else -1
                        nx = wx + dx
                        if ib(nx, wy) and bool(em[wy, nx]):
                            min_d = abs(wc - wx)
                            best_dir = (dx, 0)
                if best_dir is not None:
                    dx, dy = best_dir
                    nx, ny = wx + dx, wy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.WIRE, nx, ny)

        # Fallback: extend road from existing road where power is nearby
        nbr_power3 = make_neighbor_mask(wm | pm, 5)
        road_cells_y, road_cells_x = np.where(rm)
        if len(road_cells_x) > 0:
            k = (step * 13) % len(road_cells_x)
            for i in range(min(len(road_cells_x), 80)):
                idx = (k + i * 7) % len(road_cells_x)
                rx, ry = int(road_cells_x[idx]), int(road_cells_y[idx])
                for ddx, ddy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = rx + ddx, ry + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and bool(nbr_power3[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # ---- UNIVERSAL FALLBACKS ----
    # If no action taken, try to place a wire extending from any existing wire/plant
    wire_cells_y2, wire_cells_x2 = np.where(wm | pm)
    if len(wire_cells_x2) > 0:
        k = (step * 7) % len(wire_cells_x2)
        for i in range(min(len(wire_cells_x2), 30)):
            idx = (k + i) % len(wire_cells_x2)
            wx, wy = int(wire_cells_x2[idx]), int(wire_cells_y2[idx])
            for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + ddx, wy + ddy
                if ib(nx, ny) and bool(em[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # Last resort: place a new plant
    for (px, py) in all_plants:
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)

    # Try zone placement anywhere with any road access
    nbr_road_any = make_neighbor_mask(rm, 3)
    nbr_power_any = make_neighbor_mask(wm | pm, 6)
    cand2 = em & nbr_road_any & nbr_power_any
    cand2[0:2, :] = False; cand2[WORLD_H-2:, :] = False
    cand2[:, 0:2] = False; cand2[:, WORLD_W-2:] = False
    cys2, cxs2 = np.where(cand2)
    if len(cxs2) > 0:
        k = (step * 3) % len(cxs2)
        zone_tiles2 = resm | comm | indm
        for i in range(min(len(cxs2), 100)):
            idx = (k + i) % len(cxs2)
            zx, zy = int(cxs2[idx]), int(cys2[idx])
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    nr, nc = zy + dr, zx + dc
                    if not ib(nc, nr):
                        ok = False; break
                    if not bool(em[nr, nc]) and not bool(zone_tiles2[nr, nc]):
                        ok = False; break
                if not ok:
                    break
            if ok:
                ir2 = ind_count / max(total_zones, 1)
                cr2 = com_count / max(total_zones, 1)
                if ir2 < 0.28:
                    t2 = Tool.INDUSTRIAL
                elif cr2 < 0.28:
                    t2 = Tool.COMMERCIAL
                else:
                    t2 = Tool.RESIDENTIAL
                return (t2, zx, zy)

    return None

