    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Dynamic cluster layout - scale with population
    def active_clusters():
        all_clusters = []
        for cy in [18, 35, 50, 65, 82]:
            for cx in [15, 35, 55, 75, 95, 112]:
                all_clusters.append((cx, cy))
        if pop < 100:
            return [(60, 50)]
        if pop < 400:
            return [(45, 50), (75, 50), (60, 35), (60, 65)]
        if pop < 900:
            return [(30, 50), (60, 50), (90, 50),
                    (45, 35), (75, 35), (45, 65), (75, 65)]
        if pop < 2000:
            return [(20, 50), (50, 50), (80, 50), (110, 50),
                    (35, 30), (65, 30), (95, 30),
                    (35, 70), (65, 70), (95, 70)]
        if pop < 4000:
            return [(15, 18), (45, 18), (75, 18), (105, 18),
                    (15, 50), (45, 50), (75, 50), (105, 50),
                    (15, 82), (45, 82), (75, 82), (105, 82)]
        return all_clusters

    clusters = active_clusters()

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            # Place plant as close to cluster center as possible
            for r in range(15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            tool = Tool.NUCLEARPOWER if funds > 8000 and pop > 2000 else Tool.COALPOWER
                            return (tool, nx, ny)

    # ---- PHASE 2: EXTEND WIRE FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(22, 8 + pop // 25)
        # Rotate through plants
        plant_offset = step % max(len(plant_xs), 1)
        for pi in range(len(plant_xs)):
            pidx = (plant_offset + pi) % len(plant_xs)
            px2, py2 = int(plant_xs[pidx]), int(plant_ys[pidx])
            # Check if in active cluster
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Extend wire in 4 directions
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3): break
                    if bool(pm[ny3, nx3]): break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- PHASE 3: CONNECT CLUSTERS WITH WIRE ----
    # Horizontal wire connections at cluster rows
    active_rows = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows:
        row_clusters = sorted(cx for cx, c_cy in clusters if abs(c_cy - cy) <= 8)
        for i in range(len(row_clusters) - 1):
            c1, c2 = row_clusters[i], row_clusters[i + 1]
            # Check connectivity
            connected = True
            for x in range(c1, c2 + 1):
                if ib(x, cy) and not bool(wm[cy, x]) and not bool(pm[cy, x]):
                    connected = False
                    break
            if not connected:
                for x in range(c1, c2 + 1):
                    if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]) and not bool(wm[cy, x]):
                        return (Tool.WIRE, x, cy)

    # Vertical wire connections between cluster rows
    for cx in active_cols_set:
        col_rows = sorted(cy for c_cx, cy in clusters if abs(c_cx - cx) <= 8)
        for i in range(len(col_rows) - 1):
            r1, r2 = col_rows[i], col_rows[i + 1]
            connected = True
            for y in range(r1, r2 + 1):
                if ib(cx, y) and not bool(wm[y, cx]) and not bool(pm[y, cx]):
                    connected = False
                    break
            if not connected:
                for y in range(r1, r2 + 1):
                    if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]) and not bool(wm[y, cx]):
                        return (Tool.WIRE, cx, y)

    # ---- PHASE 4: BUILD ROADS AROUND EACH CLUSTER ----
    road_reach = min(18, 5 + pop // 40)
    # Interleave clusters by step to avoid always doing the same one
    cluster_offset = step % max(len(clusters), 1)
    for ci in range(len(clusters)):
        cx, cy = clusters[(cluster_offset + ci) % len(clusters)]
        # Horizontal roads above and below wire
        for road_y in [cy - 2, cy + 2]:
            if not (0 <= road_y < WORLD_H):
                continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)
        # Vertical roads left and right of wire
        for road_x in [cx - 2, cx + 2]:
            if not (0 <= road_x < WORLD_W):
                continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)

    # ---- PHASE 5: INTER-CLUSTER ROADS ----
    if pop > 150:
        for cy in active_rows:
            row_cs = sorted(cx for cx, c_cy in clusters if abs(c_cy - cy) <= 8)
            for i in range(len(row_cs) - 1):
                c1, c2 = row_cs[i], row_cs[i + 1]
                for road_y in [cy - 3, cy + 3]:
                    if not (0 <= road_y < WORLD_H):
                        continue
                    has_road = any(ib(x, road_y) and bool(rm[road_y, x]) for x in range(c1, c2 + 1))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    # ---- PHASE 6: ADDITIONAL ROAD GRID (denser) ----
    if pop > 500:
        # Add inner road grid every 4 tiles in active area
        nbr_wire_broad = expand_mask(wm | pm, 8)
        for row in range(6, WORLD_H - 6, 4):
            row_has_wire = bool(np.any(nbr_wire_broad[row, :]))
            if not row_has_wire:
                continue
            for col in range(6, WORLD_W - 6):
                if bool(nbr_wire_broad[row, col]) and bool(em[row, col]) and not bool(pm[row, col]):
                    # Check adjacent road
                    adj = any(ib(col + dx, row) and bool(rm[row, col + dx]) for dx in [-1, 1])
                    near_wire = bool(wm[row, col])
                    if (adj or near_wire) and not bool(rm[row, col]):
                        return (Tool.ROAD, col, row)

    # ---- PHASE 7: ZONE PLACEMENT ----
    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fy in range(10, 95, 18) for fx in range(10, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px, py) for py in range(12, 90, 20) for px in range(14, 112, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(25, 8), (60, 8), (95, 8),
                         (25, 90), (60, 90), (95, 90),
                         (5, 50), (115, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(5, 18), (5, 50), (5, 82),
                      (115, 18), (115, 50), (115, 82),
                      (55, 5), (80, 5), (55, 94), (80, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # Parks to boost land value
    if pop > 200 and step % 5 == 0:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 40)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 0), (-4, 0), (0, 4), (0, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    nbr_wire_fb = expand_mask(wm | pm, 5)
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire_fb[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants in a triangle with wire connections."""
    actions = []
    # Plant 1: center-left
    actions.append((Tool.COALPOWER, 30, 50))
    for x in range(24, 37):
        actions.append((Tool.WIRE, x, 50))
    for y in range(44, 57):
        actions.append((Tool.WIRE, 30, y))
    # Plant 2: center-right
    actions.append((Tool.COALPOWER, 80, 50))
    for x in range(74, 87):
        actions.append((Tool.WIRE, x, 50))
    for y in range(44, 57):
        actions.append((Tool.WIRE, 80, y))
    # Plant 3: top-center
    actions.append((Tool.COALPOWER, 55, 25))
    for x in range(49, 62):
        actions.append((Tool.WIRE, x, 25))
    for y in range(19, 32):
        actions.append((Tool.WIRE, 55, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # --- NEIGHBORHOOD GRID: dense 5-column x 4-row layout across map ---
    # Use a tighter 12-tile spacing to fit more neighborhoods
    all_hoods = []
    for hy in range(10, 95, 12):
        for hx in range(10, 115, 12):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 700:   return 16
        if pop < 1500:  return 28
        if pop < 3000:  return 45
        if pop < 6000:  return 65
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: ENSURE POWER PLANTS ---
    if funds > 2000:
        for idx_h, (hx, hy) in enumerate(active_hoods):
            if idx_h % 5 != 0:
                continue
            x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
            y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- BUILD NEIGHBOR MASKS ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- PHASE 2: WIRE SPINES FROM PLANTS ---
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 10)
        spine_bot   = min(WORLD_H - 3, hy + 10)
        spine_left  = max(2, hx - 10)
        spine_right = min(WORLD_W - 3, hx + 10)

        # Vertical spine
        col_wire = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(wm[r, hx])]
        col_plant_tiles = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(pm[r, hx])]

        if col_plant_tiles and not col_wire:
            for pr in col_plant_tiles:
                for wr in [pr - 1, pr + 1]:
                    if ib(hx, wr) and not bool(pm[wr, hx]) and bool(em[wr, hx]):
                        return (Tool.WIRE, hx, wr)

        if col_wire:
            min_wr = min(col_wire)
            max_wr = max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine
        row_wire = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(wm[hy, c])]
        row_plant_tiles = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant_tiles and not row_wire:
            for pc in row_plant_tiles:
                for wc in [pc - 1, pc + 1]:
                    if ib(wc, hy) and not bool(pm[hy, wc]) and bool(em[hy, wc]):
                        return (Tool.WIRE, wc, hy)

        if row_wire:
            min_wc = min(row_wire)
            max_wc = max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT WIRE SPINES BETWEEN NEARBY HOODS ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 25:
                continue
            if abs(hy1 - hy2) <= 3 and hx2 > hx1:
                bridge_y = (hy1 + hy2) // 2
                for cx in range(hx1 + 1, hx2):
                    if ib(cx, bridge_y) and bool(em[bridge_y, cx]) and not bool(pm[bridge_y, cx]):
                        return (Tool.WIRE, cx, bridge_y)
            if abs(hx1 - hx2) <= 3 and hy2 > hy1:
                bridge_x = (hx1 + hx2) // 2
                for cy in range(hy1 + 1, hy2):
                    if ib(bridge_x, cy) and bool(em[cy, bridge_x]) and not bool(pm[cy, bridge_x]):
                        return (Tool.WIRE, bridge_x, cy)

    # --- PHASE 4: ROAD GRID (parallel offset ±2 from wire spines) ---
    for (hx, hy) in active_hoods:
        spine_top  = max(2, hy - 10)
        spine_bot  = min(WORLD_H - 3, hy + 10)
        spine_left = max(2, hx - 10)
        spine_right= min(WORLD_W - 3, hx + 10)

        # Road columns flanking wire spine
        col_wire = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy):
                continue
            cyc = step % 3
            for wr in col_wire[cyc::3]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        # Road rows flanking wire spine
        row_wire = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry):
                continue
            cyc = (step + 1) % 3
            for wc in row_wire[cyc::3]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT with smarter mix ---
    def pick_tool():
        # Target: 40% res, 30% com, 30% ind (more commercial/industrial than parent)
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES (scaled aggressively) ---
    if pop > 5:
        fire_grid = [(fx, fy) for fy in range(10, 95, 14) for fx in range(10, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 30:
        police_grid = [(px2, py2) for py2 in range(12, 92, 14) for px2 in range(12, 112, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 200:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 300:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(8, 8), (102, 8), (8, 87), (102, 87), (50, 8), (50, 87)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from plants ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        sk = (step * 11) % len(pxs2)
        for offset in range(min(len(pxs2), 80)):
            k = (sk + offset * 7) % len(pxs2)
            px2, py2 = int(pxs2[k]), int(pys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                              (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + seed roads + zones"""
    actions = []
    # Central power plant at (60,50)
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire horizontal spine
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertical spine
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads forming a grid near center
    for x in range(52, 70):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 52, y))
        actions.append((Tool.ROAD, 68, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---- Dilate helper ----
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure power plants are spread across map ----
    # Grid of plants every 20 cols x 18 rows
    plant_grid_xs = list(range(10, 120, 20))
    plant_grid_ys = list(range(9, 100, 18))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            # Check if there's already a plant nearby (within 8 tiles)
            x0, x1 = max(0, ppx - 9), min(WORLD_W, ppx + 10)
            y0, y1 = max(0, ppy - 9), min(WORLD_H, ppy + 10)
            if not np.any(pm[y0:y1, x0:x1]):
                # Place plant if cell is empty
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)
                # Try nearby cells
                for dy in range(-2, 3):
                    for dx in range(-2, 3):
                        nx, ny = ppx + dx, ppy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire network - connect all plants ----
    # Strategy: extend wire from existing power sources toward uncovered areas

    # Find cells adjacent to power that are empty (can become wire)
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    # Find zones not yet powered
    unpowered_zones = zone_tiles & ~near_power
    pwr_ys, pwr_xs = np.where(pm)

    # Build wire toward unpowered zones or spread power coverage
    if np.any(unpowered_zones):
        uzys, uzxs = np.where(unpowered_zones)
        wire_cand = em & adj_to_power & ~zone_tiles
        wire_cand[0:2,:] = False; wire_cand[WORLD_H-2:,:] = False
        wire_cand[:,0:2] = False; wire_cand[:,WORLD_W-2:] = False
        wys_c, wxs_c = np.where(wire_cand)

        if len(wxs_c) > 0:
            # Pick wire candidate closest to an unpowered zone
            best_d = 1e9; best_k = 0
            stride_u = max(1, len(uzxs) // 40)
            stride_w = max(1, len(wxs_c) // 200)
            for i in range(0, len(wxs_c), stride_w):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - uzxs[j]) + abs(cy - uzys[j]) 
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # Also extend wire horizontally/vertically in a grid pattern
    # Wire rows every 9 tiles
    wire_rows = list(range(9, 100, 9))
    for wr in wire_rows:
        if not ib(0, wr): continue
        row_has_power = (wm[wr,:] | pm[wr,:]).any()
        if not row_has_power:
            # Find nearest plant and wire toward it
            if len(pwr_xs) > 0:
                # Find plant closest to this row
                dists = np.abs(pwr_ys - wr)
                k = int(np.argmin(dists))
                px, py = int(pwr_xs[k]), int(pwr_ys[k])
                # Wire from plant row toward this wire row
                if ib(px, wr) and bool(em[wr, px]) and not bool(pm[wr, px]):
                    return (Tool.WIRE, px, wr)
            continue
        # Extend existing wire in this row
        indices = np.where(wm[wr,:] | pm[wr,:])[0]
        left = int(indices[0]); right = int(indices[-1])
        if left > 2 and bool(em[wr, left-1]) and not bool(pm[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W-3 and bool(em[wr, right+1]) and not bool(pm[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    # Wire cols every 20 tiles
    wire_cols = list(range(10, 120, 20))
    for wc in wire_cols:
        if not ib(wc, 0): continue
        col_has_power = (wm[:,wc] | pm[:,wc]).any()
        if not col_has_power:
            if len(pwr_ys) > 0:
                dists = np.abs(pwr_xs - wc)
                k = int(np.argmin(dists))
                px, py = int(pwr_xs[k]), int(pwr_ys[k])
                if ib(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                    return (Tool.WIRE, wc, py)
            continue
        indices = np.where(wm[:,wc] | pm[:,wc])[0]
        top = int(indices[0]); bot = int(indices[-1])
        if top > 2 and bool(em[top-1, wc]) and not bool(pm[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H-3 and bool(em[bot+1, wc]) and not bool(pm[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads on a dense grid: every 6 rows and every 8 cols
    road_rows = list(range(6, 100, 6))
    road_cols = list(range(6, 120, 8))

    # Build horizontal roads
    for rr in road_rows:
        if not ib(0, rr): continue
        row_rd = rm[rr,:]
        if not row_rd.any():
            # Start road at column 6 if near power
            if ib(6, rr) and bool(em[rr, 6]) and not bool(pm[rr, 6]):
                return (Tool.ROAD, 6, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0]); right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        # Fill gaps
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        if not ib(rc, 0): continue
        col_rd = rm[:,rc]
        if not col_rd.any():
            if ib(rc, 6) and bool(em[6, rc]) and not bool(pm[6, rc]):
                return (Tool.ROAD, rc, 6)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0]); bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Don't zone on wire rows or road rows (keep infrastructure clear)
    # Actually allow it; zone_clear will check

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()

        if total_zones > 0:
            # Score: prefer cells near roads and existing zones but not too clustered
            zys2, zxs2 = np.where(zone_tiles)
            road_ys, road_xs = np.where(rm)

            if len(road_xs) > 0:
                stride_r = max(1, len(road_xs) // 150)
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), stride_r):
                    d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                    road_dist = np.minimum(road_dist, d)
            else:
                road_dist = np.full(len(cxs_arr), 9999.0)

            if len(zxs2) > 0:
                stride_z = max(1, len(zxs2) // 150)
                zone_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(zxs2), stride_z):
                    d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
                score = road_dist * 0.5 + zone_dist * 0.5
            else:
                score = road_dist
        else:
            # First zones: near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services ----
    if pop > 30:
        fire_spots = [(fx, fy) for fy in range(9, 96, 9) for fx in range(9, 114, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(6, 94, 8) for pkx in range(6, 114, 10)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [(sx, sy) for sy in range(18, 88, 22) for sx in range(18, 106, 28)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        airport_spots = [
            (60, 8), (60, 91), (8, 50), (111, 50),
            (30, 8), (90, 8), (30, 91), (90, 91),
            (8, 25), (111, 25), (8, 75), (111, 75),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [
            (10, 50), (109, 50), (60, 5), (60, 94),
            (25, 5), (95, 5), (25, 94), (95, 94),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 2500:
        # Extra nuclear plants for more power
        nuclear_spots = [(30, 25), (90, 25), (30, 75), (90, 75), (60, 15), (60, 84)]
        for npx, npy in nuclear_spots:
            x0, x1 = max(0, npx-10), min(WORLD_W, npx+11)
            y0, y1 = max(0, npy-10), min(WORLD_H, npy+11)
            if not np.any(pm[y0:y1, x0:x1]):
                if ib(npx, npy) and bool(em[npy, npx]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    # ---- Fallback: extend road toward any powered-but-unroaded zone ----
    unroaded_zones = zone_tiles & near_power & ~near_road
    if np.any(unroaded_zones):
        uzys, uzxs = np.where(unroaded_zones)
        road_cand = em & adj_to_power
        road_cand[0:2,:] = False; road_cand[WORLD_H-2:,:] = False
        road_cand[:,0:2] = False; road_cand[:,WORLD_W-2:] = False
        rys_c, rxs_c = np.where(road_cand)
        if len(rxs_c) > 0:
            stride_u = max(1, len(uzxs) // 30)
            best_d = 1e9; best_k = 0
            for i in range(len(rxs_c)):
                cx, cy = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx - uzxs[j]) + abs(cy - uzys[j])
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: place road near existing power ----
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(4,0),(-4,0),(0,4),(0,-4),(6,0),(-6,0),(0,6),(0,-6)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Last resort: wire extension from any power source ----
    wire_cand2 = em & adj_to_power & ~zone_tiles
    wire_cand2[0:2,:] = False; wire_cand2[WORLD_H-2:,:] = False
    wire_cand2[:,0:2] = False; wire_cand2[:,WORLD_W-2:] = False
    wys2, wxs2 = np.where(wire_cand2)
    if len(wxs2) > 0:
        k = step % len(wxs2)
        return (Tool.WIRE, int(wxs2[k]), int(wys2[k]))

    return None

def init(obs, state):
