def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target ratio: 50% res, 25% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        """Check 3x3 centered at (zx, zy) is all empty or zone tiles"""
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Wire and road corridors
    wire_rows = [15, 33, 50, 67, 85]
    wire_cols = [10, 30, 50, 70, 90, 110]

    # Intermediate road rows/cols for denser coverage
    road_rows = [24, 41, 58, 76]
    road_cols = [20, 40, 60, 80, 100]

    # ---- Phase-based infrastructure maintenance ----
    phase = step % 12

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and bool(row_wire[wx - 1])
                    right = wx < WORLD_W - 1 and bool(row_wire[wx + 1])
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and bool(col_wire[wy - 1])
                    dn = wy < WORLD_H - 1 and bool(col_wire[wy + 1])
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to wire rows
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to wire cols
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add intermediate horizontal roads between wire rows
        for rr in road_rows:
            if 0 < rr < WORLD_H - 1:
                # Connect to existing road nearby
                for rx in range(1, WORLD_W - 1):
                    if ib(rx, rr) and bool(em[rr, rx]) and bool(near_power[rr, rx]):
                        # Check adjacent road for connectivity
                        adj = ((ib(rx-1, rr) and bool(rm[rr, rx-1])) or
                               (ib(rx+1, rr) and bool(rm[rr, rx+1])) or
                               (ib(rx, rr-1) and bool(rm[rr-1, rx])) or
                               (ib(rx, rr+1) and bool(rm[rr+1, rx])))
                        if adj:
                            return (Tool.ROAD, rx, rr)

    elif phase == 5:
        # Add intermediate vertical roads between wire cols
        for rc in road_cols:
            if 0 < rc < WORLD_W - 1:
                for ry in range(1, WORLD_H - 1):
                    if ib(rc, ry) and bool(em[ry, rc]) and bool(near_power[ry, rc]):
                        adj = ((ib(rc-1, ry) and bool(rm[ry, rc-1])) or
                               (ib(rc+1, ry) and bool(rm[ry, rc+1])) or
                               (ib(rc, ry-1) and bool(rm[ry-1, rc])) or
                               (ib(rc, ry+1) and bool(rm[ry+1, rc])))
                        if adj:
                            return (Tool.ROAD, rc, ry)

    elif phase == 6:
        # Add more power plants near unpowered neighborhoods
        # Grid of 6x5 neighborhoods
        for row in range(5):
            for col in range(6):
                hx = 10 + col * 20
                hy = 10 + row * 20
                x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
                y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
                has_plant = bool(np.any(pm[y0:y1, x0:x1]))
                if not has_plant:
                    # Find nearest empty spot
                    for r in range(1, 12):
                        placed = False
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx, ny = hx + dx, hy + dy
                                    if ib(nx, ny) and bool(em[ny, nx]):
                                        return (Tool.COALPOWER, nx, ny)
                    break

    elif phase == 7:
        # Cross-wire connections between corridors
        for wi, wc in enumerate(wire_cols[:-1]):
            c2 = wire_cols[wi + 1]
            for wr in wire_rows:
                # Connect with wire if gap
                for cx in range(wc + 1, c2):
                    if bool(em[wr, cx]) and bool(near_power[wr, cx]):
                        left = bool(wm[wr, cx - 1]) or bool(pm[wr, cx - 1])
                        right = bool(wm[wr, cx + 1]) or bool(pm[wr, cx + 1])
                        if left or right:
                            return (Tool.WIRE, cx, wr)

    elif phase == 8:
        # Cross-wire vertical connections
        for ri, wr in enumerate(wire_rows[:-1]):
            r2 = wire_rows[ri + 1]
            for wc in wire_cols:
                for cy in range(wr + 1, r2):
                    if bool(em[cy, wc]) and bool(near_power[cy, wc]):
                        up = bool(wm[cy - 1, wc]) or bool(pm[cy - 1, wc])
                        dn = bool(wm[cy + 1, wc]) or bool(pm[cy + 1, wc])
                        if up or dn:
                            return (Tool.WIRE, wc, cy)

    elif phase == 9:
        # Extend road network from existing roads toward unpowered zones
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            step_k = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (step_k + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                            not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2])):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 10:
        # Civic services based on population
        if pop > 50:
            fire_grid = [
                (10, 5), (30, 5), (50, 5), (70, 5), (90, 5), (110, 5),
                (10, 25), (30, 25), (50, 25), (70, 25), (90, 25), (110, 25),
                (10, 45), (30, 45), (50, 45), (70, 45), (90, 45), (110, 45),
                (10, 65), (30, 65), (50, 65), (70, 65), (90, 65), (110, 65),
                (10, 85), (30, 85), (50, 85), (70, 85), (90, 85), (110, 85),
            ]
            for (sx, sy) in fire_grid:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 300:
            police_grid = [
                (20, 10), (60, 10), (100, 10),
                (20, 35), (60, 35), (100, 35),
                (20, 60), (60, 60), (100, 60),
                (20, 88), (60, 88), (100, 88),
                (5, 50), (115, 50), (40, 50), (80, 50),
            ]
            for (sx, sy) in police_grid:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

    else:  # phase == 11
        # Upgrade to nuclear power
        if pop > 600:
            nuke_spots = [
                (5, 5), (115, 5), (5, 94), (115, 94),
                (60, 5), (60, 94), (5, 50), (115, 50),
                (30, 5), (90, 5), (30, 94), (90, 94),
                (40, 30), (80, 30), (40, 70), (80, 70),
            ]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            stadiums = [
                (45, 40), (75, 40), (45, 60), (75, 60),
                (15, 40), (105, 40), (15, 60), (105, 60),
                (60, 10), (60, 88), (30, 75), (90, 25),
            ]
            for (sx, sy) in stadiums:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 1500:
            seaports = [(10, 95), (110, 95), (10, 5), (110, 5), (60, 5), (60, 95)]
            for (sx, sy) in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2500:
            airports = [(50, 5), (70, 5), (50, 90), (70, 90),
                        (5, 40), (5, 55), (110, 40), (110, 55)]
            for (sx, sy) in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (main action) ----
    cand_mask = em & near_road & near_power
    # Margin
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    # Protect wire/road corridor rows
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False

    # Dense grid of 30 neighborhoods across the map
    nh_positions = []
    for row in range(5):
        for col in range(6):
            hx = 10 + col * 20
            hy = 10 + row * 20
            nh_positions.append((hx, hy))

    # Activate hoods progressively
    if pop < 100:
        active_hoods = nh_positions[13:17]  # center
    elif pop < 400:
        active_hoods = nh_positions[6:24]
    elif pop < 1000:
        active_hoods = nh_positions[3:27]
    else:
        active_hoods = nh_positions

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            if i > 1000:
                break

    # ---- Parks near zones ----
    if pop > 200 and step % 4 == 0:
        park_mask = em & near_road & near_power
        pys, pxs = np.where(park_mask)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- Fallback: wire extension toward unpowered hoods ----
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- Fallback: extend existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- Last resort: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place 2 coal plants with wire/road connections to kick things off"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally
    for x in range(32, 90, 1):
        actions.append((Tool.WIRE, x, 50))
    # Roads above and below wire spine
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    # Vertical roads from plants
    for y in range(10, 95):
        actions.append((Tool.ROAD, 30, y))
        actions.append((Tool.ROAD, 90, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 0: Ensure sufficient power plants across the whole map ----
    # Dense 15x12 grid of plants
    plant_grid = []
    for py in range(8, 96, 14):
        for px in range(8, 116, 18):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 1: Wire expansion - connect plants to each other ----
    # Build a wire grid at rows/cols corresponding to plants
    wire_rows = list(range(8, 96, 14))
    wire_cols = list(range(8, 116, 18))

    # Horizontal wires along plant rows
    for wy in wire_rows:
        if not ib(0, wy):
            continue
        # Find gaps in wire coverage along this row
        for wx in range(1, WORLD_W - 1):
            if bool(em[wy, wx]) and not bool(rm[wy, wx]) and not bool(zone_tiles[wy, wx]):
                # Check if adjacent to power
                adj_pow = False
                for dx in [-1, 1]:
                    nx = wx + dx
                    if ib(nx, wy) and (bool(pm[wy, nx]) or bool(wm[wy, nx])):
                        adj_pow = True
                if adj_pow:
                    return (Tool.WIRE, wx, wy)

    # Vertical wires along plant cols
    for wx2 in wire_cols:
        if not ib(wx2, 0):
            continue
        for wy2 in range(1, WORLD_H - 1):
            if bool(em[wy2, wx2]) and not bool(rm[wy2, wx2]) and not bool(zone_tiles[wy2, wx2]):
                adj_pow = False
                for dy in [-1, 1]:
                    ny = wy2 + dy
                    if ib(wx2, ny) and (bool(pm[ny, wx2]) or bool(wm[ny, wx2])):
                        adj_pow = True
                if adj_pow:
                    return (Tool.WIRE, wx2, wy2)

    # ---- PHASE 2: Road grid - dense coverage for zone access ----
    # Road grid every 6 tiles
    road_rows = list(range(6, 97, 6))
    road_cols = list(range(6, 117, 6))

    # Horizontal roads
    for ry in road_rows:
        for rx in range(3, WORLD_W - 3):
            if bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]) and not bool(wm[ry, rx]):
                # Place road if near existing road or near power
                near_r = False
                for dx in [-1, 1]:
                    nx = rx + dx
                    if ib(nx, ry) and bool(rm[ry, nx]):
                        near_r = True
                if near_r and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Vertical roads
    for rx2 in road_cols:
        for ry2 in range(3, WORLD_H - 3):
            if bool(em[ry2, rx2]) and not bool(zone_tiles[ry2, rx2]) and not bool(wm[ry2, rx2]):
                near_r = False
                for dy in [-1, 1]:
                    ny = ry2 + dy
                    if ib(rx2, ny) and bool(rm[ny, rx2]):
                        near_r = True
                if near_r and bool(near_power[ry2, rx2]):
                    return (Tool.ROAD, rx2, ry2)

    # ---- PHASE 3: Fill remaining road gaps ----
    uncovered_road = []
    for ry in road_rows:
        for rx in range(3, WORLD_W - 3):
            if bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]) and not bool(wm[ry, rx]) and bool(near_power[ry, rx]):
                uncovered_road.append((rx, ry))
    for rx2 in road_cols:
        for ry2 in range(3, WORLD_H - 3):
            if bool(em[ry2, rx2]) and not bool(zone_tiles[ry2, rx2]) and not bool(wm[ry2, rx2]) and bool(near_power[ry2, rx2]):
                uncovered_road.append((rx2, ry2))

    if uncovered_road:
        # Pick the one adjacent to existing road
        adj_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_road |= shifted

        for rx3, ry3 in uncovered_road:
            if bool(adj_road[ry3, rx3]):
                return (Tool.ROAD, rx3, ry3)
        # Just place first
        return (Tool.ROAD, uncovered_road[0][0], uncovered_road[0][1])

    # ---- PHASE 4: Zone placement ----
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Zone candidates: near road AND near power, not edge
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Avoid wire rows and road rows (keep those for infrastructure)
    for wy in wire_rows:
        if 0 <= wy < WORLD_H:
            zone_cand[wy, :] = False
    for wy in road_rows:
        if 0 <= wy < WORLD_H:
            zone_cand[wy, :] = False
    for wx in wire_cols:
        if 0 <= wx < WORLD_W:
            zone_cand[:, wx] = False
    for wx in road_cols:
        if 0 <= wx < WORLD_W:
            zone_cand[:, wx] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        # Score by distance to nearest road (closer is better) + spread
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            # Sample roads for speed
            stride = max(1, len(road_xs) // 150)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
            # Also prefer spread: penalize being close to existing zones
            if total_zones > 0:
                zone_ys, zone_xs = np.where(zone_tiles)
                stride2 = max(1, len(zone_xs) // 100)
                zone_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(zone_xs), stride2):
                    d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
                # Prefer close to road, not too close to other zones
                score = road_dist * 1.5 - zone_dist * 0.3
            else:
                score = road_dist
        else:
            score = np.abs(cxs_arr - 60).astype(float) + np.abs(cys_arr - 50).astype(float)

        order = np.argsort(score)
        # Rotate offset to avoid always picking same spot
        off = (step * 17 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled by population ----
    if pop > 100:
        fire_locs = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 12)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        for psy in range(15, 90, 12):
            for psx in range(15, 110, 14):
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_locs = [(px3, py3) for py3 in range(12, 90, 8) for px3 in range(12, 112, 9)]
        for pkx, pky in park_locs:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_power[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        stadium_locs = [(25, 20), (85, 20), (25, 75), (85, 75),
                        (55, 10), (55, 90), (10, 50), (110, 50),
                        (40, 40), (80, 40), (40, 60), (80, 60)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuke_locs = [(60, 50), (20, 20), (100, 20), (20, 80), (100, 80),
                     (60, 15), (60, 85), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 5), (75, 5), (55, 93), (75, 93),
                        (5, 30), (113, 30), (5, 65), (113, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 5), (60, 93),
                        (10, 20), (110, 20), (10, 80), (110, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend wire from any plant toward unpowered areas ----
    unpowered = ~near_power & em
    up_ys, up_xs = np.where(unpowered)
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0 and len(up_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        # Find closest unpowered area
        dists = np.abs(up_xs - px2) + np.abs(up_ys - py2)
        best = np.argmin(dists)
        tx, ty = int(up_xs[best]), int(up_ys[best])
        # Step toward it
        dx2 = np.sign(tx - px2)
        dy2 = np.sign(ty - py2)
        candidates = []
        if dx2 != 0: candidates.append((px2 + dx2, py2))
        if dy2 != 0: candidates.append((px2, py2 + dy2))
        for cx3, cy3 in candidates:
            if ib(cx3, cy3) and bool(em[cy3, cx3]):
                return (Tool.WIRE, cx3, cy3)

    # ---- Fallback: place road near plant ----
    if len(pwr_xs) > 0:
        k = (step * 7) % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (5, 0), (-5, 0), (0, 5), (0, -5)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
