        actions.append((Tool.ROAD, x, 27))
        actions.append((Tool.ROAD, x, 73))
        actions.append((Tool.ROAD, x, 77))
    # Vertical roads at x=58,62 between horizontal spines
    for y in range(23, 78):
        actions.append((Tool.ROAD, 58, y))
