def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Initialize state ---
    if 'phase' not in state:
        state['phase'] = 'infra'
        state['plant_idx'] = 0
        state['wire_row_idx'] = 0
        state['wire_col_idx'] = 0
        state['road_row_idx'] = 0
        state['road_col_idx'] = 0
        state['zone_cursor'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        rr = res_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- STEP 1: Ensure power plants distributed across map ----
    # Grid of plants every 25 cols, 25 rows
    plant_positions = [(px, py) for py in range(12, WORLD_H - 10, 22)
                       for px in range(12, WORLD_W - 10, 22)]

    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 6), min(WORLD_W, ppx + 7)
        y0, y1 = max(0, ppy - 6), min(WORLD_H, ppy + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            # Check not on road or wire
            if bool(em[ppy, ppx]) or (not bool(rm[ppy, ppx]) and not bool(zone_tiles[ppy, ppx])):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- STEP 2: Wire network - horizontal spines every 8 rows ----
    wire_rows = list(range(8, WORLD_H - 5, 8))
    wire_cols = list(range(8, WORLD_W - 5, 8))

    # Extend horizontal wires
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            # Find nearest plant to connect from
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                dists = np.abs(pys - wr) + np.abs(pxs - 60)
                k = np.argmin(dists)
                wx, wy = int(pxs[k]), int(pys[k])
                # Step toward the wire row
                ny = wy + (1 if wr > wy else -1)
                if ib(wx, ny) and not bool(zone_tiles[ny, wx]) and not bool(rm[ny, wx]):
                    return (Tool.WIRE, wx, ny)
            continue
        idxs = np.where(row_power)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        # Extend left
        if left > 3:
            nx = left - 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 4:
            nx = right + 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(zone_tiles[wr, x]):
                return (Tool.WIRE, x, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        idxs = np.where(col_power)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        if top > 3:
            ny = top - 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]):
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 4:
            ny = bot + 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]):
                return (Tool.WIRE, wc, ny)
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(zone_tiles[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- STEP 3: Road network - between wire rows/cols ----
    # Roads at wire_row +/- 3 and wire_col +/- 3
    road_rows = sorted(set(r for wr in wire_rows for r in [wr - 3, wr + 3]
                           if 4 < r < WORLD_H - 4))
    road_cols = sorted(set(c for wc in wire_cols for c in [wc - 3, wc + 3]
                           if 4 < c < WORLD_W - 4))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Start road from center
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        idxs = np.where(row_rd)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        if left > 4 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]) and not bool(wm[rr, left-1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]) and not bool(wm[rr, right+1]):
            return (Tool.ROAD, right + 1, rr)
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]) and not bool(wm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        idxs = np.where(col_rd)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        if top > 4 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]) and not bool(wm[top-1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]) and not bool(wm[bot+1, rc]):
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]) and not bool(wm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- STEP 4: Zone placement ----
    zone_cand = em & near_road & near_power
    # Buffer from edges
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W-3:] = False
    # Don't place on infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[max(0,rr-1):min(WORLD_H,rr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, max(0,wc-1):min(WORLD_W,wc+2)] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, max(0,rc-1):min(WORLD_W,rc+2)] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                t = tm[nr, nc]
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 150)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 150)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Cluster: prefer spots 4-12 away from existing zones
            zone_score = np.where(min_zone_dist < 4, 500.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.05

        score = road_dist * 2.0 + zone_score
        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- STEP 5: Civic services ----
    if pop > 20:
        fire_spots = [(fx, fy) for fy in range(6, 96, 10) for fx in range(6, 116, 16)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_spots = [(px2, py2) for py2 in range(6, 96, 12) for px2 in range(6, 116, 18)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150:
        park_spots = [(pkx, pky) for pky in range(5, 96, 7) for pkx in range(5, 116, 9)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 400:
        stadium_spots = [(sx, sy) for sy in range(12, 90, 22) for sx in range(12, 112, 28)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700 and funds > 5000:
        nuclear_spots = [(nx, ny) for ny in range(12, 92, 18) for nx in range(12, 112, 18)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 8), min(WORLD_W, npx + 9)
                y0, y1 = max(0, npy - 8), min(WORLD_H, npy + 9)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1200:
        airport_spots = [(60, 6), (60, 93), (6, 50), (113, 50),
                         (30, 6), (90, 6), (30, 93), (90, 93)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_spots = [(6, 50), (113, 50), (60, 5), (60, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- STEP 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    if len(uzxs) > 0:
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & adj_to_power & ~zone_tiles & ~rm
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H-2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W-2:] = False
        wys_c, wxs_c = np.where(wire_cand)

        if len(wxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(uzxs) // 30)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- STEP 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    if len(usxs) > 0:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
        road_cand2[0:2, :] = False
        road_cand2[WORLD_H-2:, :] = False
        road_cand2[:, 0:2] = False
        road_cand2[:, WORLD_W-2:] = False
        rys_c, rxs_c = np.where(road_cand2)

        if len(rxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(usxs) // 30)
            for i in range(len(rxs_c)):
                cx, cy = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                        for j in range(0, len(usxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: extend road from any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (8, 0), (-8, 0), (0, 8), (0, -8)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

