        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # Zone type selection: 25% ind, 35% com, 40% res
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # PHASE 1: Power plant grid - denser than parent (every 18 cols, 18 rows)
    plant_grid_xs = list(range(12, 115, 18))
    plant_grid_ys = list(range(12, 95, 18))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 6), min(WORLD_W, ppx + 7)
            y0, y1 = max(0, ppy - 6), min(WORLD_H, ppy + 7)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # PHASE 2: Wire network - horizontal rows at plant_grid_ys
    for ppy in plant_grid_ys:
        row_wp = wm[ppy, :] | pm[ppy, :]
        if not row_wp.any():
            if ib(60, ppy) and em[ppy, 60]:
                return (Tool.WIRE, 60, ppy)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and em[ppy, left-1]:
            return (Tool.WIRE, left-1, ppy)
        if right < WORLD_W - 3 and em[ppy, right+1]:
            return (Tool.WIRE, right+1, ppy)
        for x in range(left+1, right):
            if em[ppy, x] and not pm[ppy, x] and not rm[ppy, x]:
                return (Tool.WIRE, x, ppy)

    # Vertical wires at plant_grid_xs
    for ppx in plant_grid_xs:
        col_wp = wm[:, ppx] | pm[:, ppx]
        if not col_wp.any():
            if ib(ppx, 50) and em[50, ppx]:
                return (Tool.WIRE, ppx, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and em[top-1, ppx]:
            return (Tool.WIRE, ppx, top-1)
        if bot < WORLD_H - 3 and em[bot+1, ppx]:
            return (Tool.WIRE, ppx, bot+1)
        for y in range(top+1, bot):
            if em[y, ppx] and not pm[y, ppx] and not rm[y, ppx]:
                return (Tool.WIRE, ppx, y)

    # PHASE 3: Road grid - offset from wire grid
    road_rows = []
    for ppy in plant_grid_ys:
        road_rows.append(ppy - 5)
        road_rows.append(ppy + 5)
    road_cols = []
    for ppx in plant_grid_xs:
        road_cols.append(ppx - 5)
        road_cols.append(ppx + 5)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and em[rr, left-1] and not pm[rr, left-1]:
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-4 and em[rr, right+1] and not pm[rr, right+1]:
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and em[top-1, rc] and not pm[top-1, rc]:
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-4 and em[bot+1, rc] and not pm[bot+1, rc]:
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # PHASE 4: Zone placement - closed-loop, prioritize near power+road
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        if total_zones > 0:
            zys2, zxs2 = np.where(zone_tiles)
            stride_z = max(1, len(zxs2) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zxs2), stride_z):
                d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)

            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                stride_r = max(1, len(road_xs) // 100)
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), stride_r):
                    d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                    road_dist = np.minimum(road_dist, d)
                # Slightly prefer near road over clustering
                score = zone_dist * 0.25 + road_dist * 0.75
            else:
                score = zone_dist
        else:
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services (lower thresholds than parent = more services earlier)
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(10, 93, 14) for px2 in range(10, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(6, 95, 7) for pkx in range(6, 115, 9)]
        for pkx2, pky2 in park_grid:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 400:
        stadium_spots = [(sx, sy) for sy in range(15, 88, 20) for sx in range(15, 108, 25)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        nuclear_spots = [(nx, ny) for ny in range(15, 90, 22) for nx in range(15, 110, 28)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy):
                x0, x1 = max(0, npx-8), min(WORLD_W, npx+9)
                y0, y1 = max(0, npy-8), min(WORLD_H, npy+9)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[npy, npx]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1200:
        airport_spots = [(60, 8), (60, 91), (8, 50), (111, 50), (30, 8), (90, 8), (30, 91), (90, 91)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_spots = [(8, 50), (111, 50), (60, 5), (60, 94), (8, 25), (8, 75)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # PHASE 6: Fallback - extend wire toward unpowered zones
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False; wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False; wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0:
        if len(uzxs) > 0:
            best_d = 1e9; best_k = 0
            stride = max(1, len(uzxs) // 20)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
        else:
            k = step % len(wxs_c)
            return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # Final fallback: road near power plants
    pwr_ys2, pwr_xs2 = np.where(pm)
    if len(pwr_xs2) > 0:
        for i in range(len(pwr_xs2)):
            k = (step * 13 + i) % len(pwr_xs2)
            px2, py2 = int(pwr_xs2[k]), int(pwr_ys2[k])
            for dx2, dy2 in [(5,0),(-5,0),(0,5),(0,-5),(3,0),(-3,0),(0,3),(0,-3)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants spread across the map + wire grid + roads"""
    actions = []
    # 6 coal plants in a 3x2 grid pattern
    plants = [(20, 20), (60, 20), (100, 20), (20, 70), (60, 70), (100, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire corridors
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 20))
        actions.append((Tool.WIRE, x, 70))
    # Vertical wire corridors at x=20,60,100
    for y in range(1, 99):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Roads flanking horizontal wire rows
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 19))
        actions.append((Tool.ROAD, x, 21))
        actions.append((Tool.ROAD, x, 69))
        actions.append((Tool.ROAD, x, 71))
    # Roads flanking vertical wire cols
    for y in range(1, 99):
        actions.append((Tool.ROAD, 19, y))
        actions.append((Tool.ROAD, 21, y))
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
        actions.append((Tool.ROAD, 99, y))
        actions.append((Tool.ROAD, 101, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 40% residential, 30% commercial, 30% industrial
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- Wire corridors ---
    wire_rows = [20, 45, 70, 90]
    wire_cols = [20, 40, 60, 80, 100]

    # --- Neighborhoods: 6x5 grid covering map ---
    # Columns at x=10,30,50,70,90,110; rows at y=10,30,50,70,90
    nh_positions = []
    for col in range(6):
        for row in range(5):
            cx = 10 + col * 20   # 10,30,50,70,90,110
            cy = 10 + row * 20   # 10,30,50,70,90
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 200:
            # Center cluster
            return [(50, 45), (50, 50), (50, 55), (60, 45), (60, 50), (60, 55),
                    (70, 45), (70, 50), (70, 55)]
        elif pop < 600:
            return nh_positions[:15]
        elif pop < 1500:
            return nh_positions[:24]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANTS NEAR ACTIVE HOODS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CORRIDORS (reactive) ----
    phase = step % 8

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    if (ib(wx-1, wr) and bool(row_wire[wx-1])) or (ib(wx+1, wr) and bool(row_wire[wx+1])):
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    if (ib(wc, wy-1) and bool(col_wire[wy-1])) or (ib(wc, wy+1) and bool(col_wire[wy+1])):
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Seed new wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    px2 = int(plant_xs[best])
                    if ib(px2, wr) and bool(em[wr, px2]):
                        return (Tool.WIRE, px2, wr)
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    py2 = int(plant_ys[best])
                    if ib(wc, py2) and bool(em[py2, wc]):
                        return (Tool.WIRE, wc, py2)

    elif phase == 3:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Cross roads between vertical corridors (mid-columns)
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (c1 + c2) // 2
            if not ib(mid_x, 0):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                          (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                    if adj and bool(near_power[ry, mid_x]):
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Cross roads between horizontal corridors (mid-rows)
        for wr_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            mid_y = (r1 + r2) // 2
            if not ib(0, mid_y):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                          (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                    if adj and bool(near_power[mid_y, rx]):
                        return (Tool.ROAD, rx, mid_y)

    else:
        # phase == 7: Add extra wire from active hoods toward nearest wire
        for (hx, hy) in active_hoods:
            if not bool(near_power[hy, hx]):
                wire_ys_arr, wire_xs_arr = np.where(wm | pm)
                if len(wire_xs_arr) > 0:
                    dists = np.abs(wire_xs_arr - hx) + np.abs(wire_ys_arr - hy)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                    dx = 0 if hx == bwx else (1 if hx > bwx else -1)
                    dy = 0 if hy == bwy else (1 if hy > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT (main engine) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Exclude wire/plant corridors
    for wr in wire_rows:
        cand_mask[wr, :] = False
    for wc in wire_cols:
        cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_grid = [(30, 10), (70, 10), (110, 10),
                     (10, 35), (50, 35), (90, 35),
                     (30, 55), (70, 55), (110, 55),
                     (10, 80), (50, 80), (90, 80)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_grid = [(10, 10), (50, 10), (90, 10),
                       (30, 30), (70, 30), (110, 30),
                       (10, 55), (50, 55), (90, 55),
                       (30, 80), (70, 80), (110, 80)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(40, 42), (80, 42), (40, 62), (80, 62),
                    (15, 50), (105, 50), (60, 10), (60, 85)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        # Switch some coal plants to nuclear for efficiency
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 5), (60, 94), (5, 50), (115, 50),
                      (30, 50), (90, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 8), (112, 8)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(55, 5), (65, 5), (55, 90), (65, 90)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near zones to improve land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: connect unpowered hoods with wire ----
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend road network ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: wire extension ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power cluster with wire spine and roads."""
    actions = []
    # Two coal plants near center, connected by wire
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    actions.append((Tool.COALPOWER, cx + 15, cy))
    # Wire connecting them and extending out
    for x in range(cx - 8, cx + 24):
        actions.append((Tool.WIRE, x, cy))
    # Vertical wire spines
    for y in range(cy - 8, cy + 9):
        actions.append((Tool.WIRE, cx, y))
        actions.append((Tool.WIRE, cx + 15, y))
    # Roads above and below wire spine
    for x in range(cx - 8, cx + 24):
        actions.append((Tool.ROAD, x, cy - 2))
        actions.append((Tool.ROAD, x, cy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Zone ratio tracking ---
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        r = res_count / total_zones
        c = com_count / total_zones
        i = ind_count / total_zones
        if i < 0.20:
            return Tool.INDUSTRIAL
        if c < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Define a large grid of neighborhood anchors across the whole map ---
    # 6 columns x 5 rows = 30 neighborhoods, well-spread
    anchors = []
    for col_x in [10, 30, 50, 70, 90, 110]:
        for row_y in [10, 28, 50, 72, 90]:
            anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 400:   return 10
        if pop < 800:   return 16
        if pop < 1500:  return 22
        if pop < 2500:  return 26
        return 30

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # --- PHASE 1: Ensure each active anchor has a coal power plant nearby ---
    for (px, py) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant at anchor if clear, else scan outward
            for r in range(0, 12):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # --- PHASE 2: Wire cross at each anchor (connect plant to grid) ---
    spine_half = min(10, 4 + pop // 20)
    for (px, py) in active_anchors:
        # Horizontal wire
        for dx in range(-spine_half, spine_half + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        # Vertical wire
        for dy in range(-spine_half, spine_half + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # --- PHASE 3: Connect anchors with wire horizontally (same row-level) ---
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx2 in range(x1a + 1, x2a):
                if ib(cx2, yl) and bool(em[yl, cx2]) and not bool(pm[yl, cx2]):
                    return (Tool.WIRE, cx2, yl)

    # --- PHASE 4: Connect anchors with wire vertically (same column) ---
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy2 in range(y1a + 1, y2a):
                if ib(xl, cy2) and bool(em[cy2, xl]) and not bool(pm[cy2, xl]):
                    return (Tool.WIRE, xl, cy2)

    # --- PHASE 5: Roads adjacent to wire spines (above and below) ---
    for (px, py) in active_anchors:
        for road_dy in [-2, 2]:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine_half, spine_half + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        # Also roads left/right of vertical wire
        for road_dx in [-2, 2]:
            rxc = px + road_dx
            if not ib(rxc, py):
                continue
            for dy in range(-spine_half, spine_half + 1):
                ryc = py + dy
                if ib(rxc, ryc) and bool(em[ryc, rxc]) and not bool(pm[ryc, rxc]):
                    return (Tool.ROAD, rxc, ryc)

    # --- PHASE 6: Vertical road connectors between row levels ---
    if pop > 30:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1a = col_anchors[i]
                _, y2a = col_anchors[i + 1]
                # road at xl+3 and xl-3
                for road_x_off in [3, -3]:
                    road_x = xl + road_x_off
                    for cy2 in range(y1a - 2, y2a + 3):
                        if ib(road_x, cy2) and bool(em[cy2, road_x]) and not bool(pm[cy2, road_x]):
                            return (Tool.ROAD, road_x, cy2)

    # --- Build neighbor masks for zone placement ---
    # nbr_road: cells within 2 of a road
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # nbr_wire: cells within 5 of wire/plant
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- PHASE 7: Place zones near powered roads ---
    cand_mask = em & nbr_road & nbr_wire
    # Keep away from edges (zones are 3x3)
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer close to active anchors + slight variation by step
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 1200:
                break

    # --- PHASE 8: Extend roads from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 9: Civic services, reactively placed ---
    if pop > 100:
        fire_spots = []
        for fx in [8, 35, 65, 95, 115]:
            for fy in [8, 25, 50, 75, 92]:
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = []
        for px2 in [15, 45, 75, 105]:
            for py2 in [12, 40, 65, 88]:
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for sx, sy in [(20, 5), (60, 5), (100, 5), (20, 94), (60, 94), (100, 94)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        # Add nuclear plants for more power
        for nx2, ny2 in [(5, 50), (115, 50), (60, 5), (60, 94), (5, 20), (115, 20), (5, 80), (115, 80)]:
            y0 = max(0, ny2 - 5); y1 = min(WORLD_H, ny2 + 6)
            x0 = max(0, nx2 - 5); x1 = min(WORLD_W, nx2 + 6)
            if not np.any(pm[y0:y1, x0:x1]) and ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for ax, ay in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sx2, sy2 in [(5, 93), (115, 93), (60, 97)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PHASE 10: Parks to boost land value near dense zones ---
    if pop > 300:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- FALLBACK: extend wire from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: road near any zone ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in corners + center + wire grid skeleton"""
    actions = []
    # 4 corner plants + 2 center plants
    plants = [(10, 10), (108, 10), (10, 88), (108, 88), (59, 10), (59, 88)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at y=10, 33, 55, 77, 88
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 10))
        actions.append((Tool.WIRE, x, 55))
        actions.append((Tool.WIRE, x, 88))
    # Vertical wire spines at x=10, 40, 59, 80, 108
    for y in range(1, 99):
        actions.append((Tool.WIRE, 10, y))
        actions.append((Tool.WIRE, 59, y))
        actions.append((Tool.WIRE, 108, y))
    # Roads flanking horizontal wire spines
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 9))
        actions.append((Tool.ROAD, x, 11))
        actions.append((Tool.ROAD, x, 54))
        actions.append((Tool.ROAD, x, 56))
        actions.append((Tool.ROAD, x, 87))
        actions.append((Tool.ROAD, x, 89))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target ratio: 50% res, 25% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire corridors
    wire_rows = [10, 33, 55, 77, 88]
    wire_cols = [10, 30, 40, 59, 80, 90, 108]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # 7x5 = 35 neighborhoods spread across map
    nh_positions = []
    for row in range(5):
        for col in range(7):
            cx = 8 + col * 16   # 8, 24, 40, 56, 72, 88, 104
            cy = 8 + row * 22   # 8, 30, 52, 74, 96 -> clamp
            cy = min(cy, 96)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            # Start with 4 central neighborhoods
            return [nh_positions[10], nh_positions[11], nh_positions[17], nh_positions[18]]
        elif pop < 400:
            return nh_positions[7:28]
        elif pop < 1000:
            return nh_positions[3:32]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # ---- PHASE 0: Ensure power plants near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 20):
                found = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    if (ib(wx-1, wr) and bool(row_wire[wx-1])) or (ib(wx+1, wr) and bool(row_wire[wx+1])):
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    if (ib(wc, wy-1) and bool(col_wire[wy-1])) or (ib(wc, wy+1) and bool(col_wire[wy+1])):
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Add secondary horizontal wire rows at y=33 and y=77
        for wr in [33, 77]:
            row_wire = wm[wr, :] | pm[wr, :]
            # Seed from nearest vertical wire col
            if not np.any(row_wire):
                for wc in wire_cols:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_wire[wx]):
                        if (ib(wx-1, wr) and bool(row_wire[wx-1])) or (ib(wx+1, wr) and bool(row_wire[wx+1])):
                            if bool(em[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 3:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows + [33, 77]:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Add secondary vertical wire cols at x=30, 80, 90
        for wc in [30, 80, 90]:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                for wr in wire_rows:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_wire[wy]):
                        if (ib(wc, wy-1) and bool(col_wire[wy-1])) or (ib(wc, wy+1) and bool(col_wire[wy+1])):
                            if bool(em[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 6:
        # Cross-roads between vertical wire corridors at mid-row
        for wr_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            mid_y = (r1 + r2) // 2
            for wc_idx in range(len(wire_cols) - 1):
                c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
                for rx in range(c1 + 2, c2 - 1):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                              (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    elif phase == 7:
        # Cross-roads vertical
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (c1 + c2) // 2
            for wr_idx in range(len(wire_rows) - 1):
                r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
                for ry in range(r1 + 2, r2 - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                              (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 8:
        # Extend road from existing road near power
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % len(road_xs2)
            for offset in range(min(len(road_xs2), 120)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # Wire extension from existing wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False

    # Don't place zones on wire/plant corridors
    for wr in wire_rows + [33, 77]:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols + [30, 80, 90]:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_grid = [(5, 5), (30, 5), (55, 5), (80, 5), (110, 5),
                     (5, 25), (30, 25), (55, 25), (80, 25), (110, 25),
                     (5, 45), (55, 45), (110, 45),
                     (5, 65), (30, 65), (55, 65), (80, 65), (110, 65),
                     (5, 93), (30, 93), (55, 93), (80, 93), (110, 93)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_grid = [(20, 15), (70, 15), (115, 15),
                       (20, 40), (70, 40), (115, 40),
                       (20, 65), (70, 65), (115, 65),
                       (5, 80), (40, 80), (90, 80), (115, 80)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [(35, 35), (85, 35), (35, 65), (85, 65),
                    (10, 50), (110, 50), (60, 20), (60, 80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [(5, 5), (113, 5), (5, 93), (113, 93),
                      (59, 5), (59, 93), (5, 50), (113, 50),
                      (25, 5), (95, 5), (25, 93), (95, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 93), (113, 93), (5, 5), (113, 5), (59, 5), (59, 93)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [(48, 5), (72, 5), (48, 90), (72, 90),
                    (5, 43), (5, 57), (113, 43), (113, 57)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near zones for land value
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire toward unpowered hoods ----
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: wire extension from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire cross + flanking roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for dx in range(-10, 11):
        actions.append((Tool.WIRE, 60 + dx, 50))
    # Vertical wire spine
    for dy in range(-10, 11):
        actions.append((Tool.WIRE, 60, 50 + dy))
    # Flanking roads
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, 60 + dx, 48))
        actions.append((Tool.ROAD, 60 + dx, 52))
    for dy in range(-10, 11):
        actions.append((Tool.ROAD, 58, 50 + dy))
        actions.append((Tool.ROAD, 62, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Fast dilation
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 5)
    near_road = dilate(rm, 3)

    # Cluster grid: 4 cols x 4 rows across the map
    # Each cluster: power plant + wire cross + road grid + zones
    cluster_cols = [18, 42, 78, 102]
    cluster_rows = [16, 38, 62, 84]

    def active_clusters():
        if pop < 50:
            return [(60, 50)]
        if pop < 200:
            return [(42, 50), (78, 50)]
        if pop < 600:
            return [(18, 50), (60, 50), (102, 50)]
        if pop < 1200:
            return [(18, 38), (60, 38), (102, 38),
                    (18, 62), (60, 62), (102, 62)]
        if pop < 2500:
            return [(18, 16), (60, 16), (102, 16),
                    (18, 50), (60, 50), (102, 50),
                    (18, 84), (60, 84), (102, 84)]
        # Full 4x4 grid
        return [(cx, cy) for cy in cluster_rows for cx in cluster_cols]

    clusters = active_clusters()

    # ---- PHASE 1: Ensure power plants near each cluster ----
    for cx, cy in clusters:
        x0, x1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        y0, y1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find empty spot near cluster center
            for r in range(20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire grid - horizontal rows and vertical cols ----
    # Wire rows at each cluster row, wire cols at each cluster col
    active_rows = sorted(set(cy for cx, cy in clusters))
    active_cols = sorted(set(cx for cx, cy in clusters))

    # Extend wire along each active row
    for wy in active_rows:
        row_power = wm[wy, :] | pm[wy, :]
        if not row_power.any():
            # Start wire from nearest plant
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                best_i = int(np.argmin(np.abs(pys_arr - wy) + np.abs(pxs_arr - 60)))
                px0, py0 = int(pxs_arr[best_i]), int(pys_arr[best_i])
                if ib(px0, wy) and bool(em[wy, px0]):
                    return (Tool.WIRE, px0, wy)
            continue
        idxs = np.where(row_power)[0]
        left_w, right_w = int(idxs[0]), int(idxs[-1])
        # Extend left toward map edge
        target_left = 4
        if left_w > target_left:
            for x in range(left_w - 1, target_left - 1, -1):
                if ib(x, wy) and bool(em[wy, x]):
                    return (Tool.WIRE, x, wy)
        # Extend right toward map edge
        target_right = WORLD_W - 5
        if right_w < target_right:
            for x in range(right_w + 1, target_right + 1):
                if ib(x, wy) and bool(em[wy, x]):
                    return (Tool.WIRE, x, wy)
        # Fill gaps
        for x in range(left_w + 1, right_w):
            if bool(em[wy, x]) and not bool(pm[wy, x]):
                return (Tool.WIRE, x, wy)

    # Extend wire along each active column
    for wx in active_cols:
        col_power = wm[:, wx] | pm[:, wx]
        if not col_power.any():
            if ib(wx, 50) and bool(em[50, wx]):
                return (Tool.WIRE, wx, 50)
            continue
        idxs = np.where(col_power)[0]
        top_w, bot_w = int(idxs[0]), int(idxs[-1])
        target_top = 4
        if top_w > target_top:
            for y in range(top_w - 1, target_top - 1, -1):
                if ib(wx, y) and bool(em[y, wx]):
                    return (Tool.WIRE, wx, y)
        target_bot = WORLD_H - 5
        if bot_w < target_bot:
            for y in range(bot_w + 1, target_bot + 1):
                if ib(wx, y) and bool(em[y, wx]):
                    return (Tool.WIRE, wx, y)
        for y in range(top_w + 1, bot_w):
            if bool(em[y, wx]) and not bool(pm[y, wx]):
                return (Tool.WIRE, wx, y)

    # ---- PHASE 3: Road network around clusters ----
    # Two road rows per cluster (cy-3, cy+3), two road cols (cx-3, cx+3)
    road_rows_set = []
    road_cols_set = []
    for cx, cy in clusters:
        road_rows_set.extend([cy - 3, cy + 3])
        road_cols_set.extend([cx - 3, cx + 3])
    road_rows_set = sorted(set(r for r in road_rows_set if 3 < r < WORLD_H - 3))
    road_cols_set = sorted(set(c for c in road_cols_set if 3 < c < WORLD_W - 3))

    for rr in road_rows_set:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Start near a cluster
            best_cx = min(active_cols, key=lambda cx: abs(cx - 60))
            if ib(best_cx, rr) and bool(em[rr, best_cx]) and not bool(pm[rr, best_cx]):
                return (Tool.ROAD, best_cx, rr)
            continue
        idxs = np.where(row_rd)[0]
        left_r, right_r = int(idxs[0]), int(idxs[-1])
        # Extend to cover active cols range
        min_cx, max_cx = min(active_cols) - 5, max(active_cols) + 5
        min_cx = max(3, min_cx)
        max_cx = min(WORLD_W - 4, max_cx)
        if left_r > min_cx:
            for x in range(left_r - 1, min_cx - 1, -1):
                if ib(x, rr) and bool(em[rr, x]) and not bool(pm[rr, x]):
                    return (Tool.ROAD, x, rr)
        if right_r < max_cx:
            for x in range(right_r + 1, max_cx + 1):
                if ib(x, rr) and bool(em[rr, x]) and not bool(pm[rr, x]):
                    return (Tool.ROAD, x, rr)
        for x in range(left_r + 1, right_r):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols_set:
        col_rd = rm[:, rc]
        if not col_rd.any():
            best_cy = min(active_rows, key=lambda cy: abs(cy - 50))
            if ib(rc, best_cy) and bool(em[best_cy, rc]) and not bool(pm[best_cy, rc]):
                return (Tool.ROAD, rc, best_cy)
            continue
        idxs = np.where(col_rd)[0]
        top_r, bot_r = int(idxs[0]), int(idxs[-1])
        min_cy, max_cy = min(active_rows) - 5, max(active_rows) + 5
        min_cy = max(3, min_cy)
        max_cy = min(WORLD_H - 4, max_cy)
        if top_r > min_cy:
            for y in range(top_r - 1, min_cy - 1, -1):
                if ib(rc, y) and bool(em[y, rc]) and not bool(pm[y, rc]):
                    return (Tool.ROAD, rc, y)
        if bot_r < max_cy:
            for y in range(bot_r + 1, max_cy + 1):
                if ib(rc, y) and bool(em[y, rc]) and not bool(pm[y, rc]):
                    return (Tool.ROAD, rc, y)
        for y in range(top_r + 1, bot_r):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    # Exclude infrastructure rows/cols from zone placement
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Don't place on wire rows/cols or road rows/cols
    for wy in active_rows:
        if 0 <= wy < WORLD_H:
            zone_cand[wy, :] = False
    for wx in active_cols:
        if 0 <= wx < WORLD_W:
            zone_cand[:, wx] = False
    for rr in road_rows_set:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for rc in road_cols_set:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer close to clusters, close to roads
        best_dist = np.full(len(cxs_arr), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs_arr - cx).astype(float) +
                 np.abs(cys_arr - cy).astype(float))
            best_dist = np.minimum(best_dist, d)

        # Also score by road proximity
        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            stride = max(1, len(road_xs_arr) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs_arr), stride):
                d = (np.abs(cxs_arr - road_xs_arr[i]).astype(float) +
                     np.abs(cys_arr - road_ys_arr[i]).astype(float))
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = best_dist.copy()

        score = best_dist * 0.5 + road_dist * 1.5
        order = np.argsort(score)
        off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 5: Civic services ----
    if pop > 60:
        fire_spots = [(fx, fy) for fy in range(8, 95, 14) for fx in range(8, 114, 16)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_spots = [(px, py) for py in range(10, 92, 16) for px in range(10, 112, 18)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(10, 92, 8) for pkx in range(10, 112, 9)]
        for pkx, pky in park_spots:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        stadium_spots = [(sx, sy) for sy in range(12, 90, 22) for sx in range(12, 110, 24)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Upgrade to nuclear power
        nuclear_spots = [(nx, ny) for ny in range(10, 92, 18) for nx in range(10, 112, 18)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 10), min(WORLD_W, npx + 11)
                y0, y1 = max(0, npy - 10), min(WORLD_H, npy + 11)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 6), (65, 6), (6, 44), (113, 44),
                         (55, 93), (65, 93), (6, 56), (113, 56)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [(6, 50), (113, 50), (60, 4), (60, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    if len(uzxs) > 0:
        # Find wire tiles adjacent to power that can extend toward unpowered zones
        adj_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy == -1: shifted[:-1, :] = power_src[1:, :]
            elif dy == 1: shifted[1:, :] = power_src[:-1, :]
            elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
            else: shifted[:, 1:] = power_src[:, :-1]
            adj_power |= shifted
        wire_cand = em & adj_power & ~zone_tiles & ~rm
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False
        wys_c, wxs_c = np.where(wire_cand)
        if len(wxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(uzxs) // 20)
            for i in range(len(wxs_c)):
                cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx2 - int(uzxs[j])) + abs(cy2 - int(uzys[j]))
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    if len(usxs) > 0:
        adj_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            else: shifted[:, 1:] = rm[:, :-1]
            adj_road |= shifted
        road_cand2 = em & adj_road & ~zone_tiles & ~pm
        road_cand2[0:2, :] = False
        road_cand2[WORLD_H - 2:, :] = False
        road_cand2[:, 0:2] = False
        road_cand2[:, WORLD_W - 2:] = False
        rys_c, rxs_c = np.where(road_cand2)
        if len(rxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(usxs) // 20)
            for i in range(len(rxs_c)):
                cx2, cy2 = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx2 - int(usxs[j])) + abs(cy2 - int(usys[j]))
                        for j in range(0, len(usxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: extend road from existing roads near wire ----
    road_ys_fb, road_xs_fb = np.where(rm)
    if len(road_xs_fb) > 0:
        sk = (step * 11) % len(road_xs_fb)
        for off in range(min(len(road_xs_fb), 60)):
            k = (sk + off * 7) % len(road_xs_fb)
            rx, ry = int(road_xs_fb[k]), int(road_ys_fb[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if (ib(nx, ny) and bool(em[ny, nx]) and
                        not bool(pm[ny, nx]) and bool(near_power[ny, nx])):
                    return (Tool.ROAD, nx, ny)

    # ---- Fallback: extend wire from existing wire ----
    wire_ys_fb, wire_xs_fb = np.where(wm)
    if len(wire_xs_fb) > 0:
        sk = (step * 13) % len(wire_xs_fb)
        for off in range(min(len(wire_xs_fb), 50)):
            k = (sk + off * 5) % len(wire_xs_fb)
            wx, wy = int(wire_xs_fb[k]), int(wire_ys_fb[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire spine + seed roads for quick start"""
    actions = []
    # Place 3 coal plants at strategic locations
    for px, py in [(60, 50), (30, 25), (90, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spine at y=50
    for x in range(55, 115, 3):
        actions.append((Tool.WIRE, x, 50))
    for x in range(5, 60, 3):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine at x=60
    for y in range(5, 95, 3):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads near center
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(5, 95):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Compute derived maps ----
    zone_tiles = resm | comm | indm
    power_src = wm | pm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Infrastructure grid parameters ----
    # Wire rows every 10, roads at wire_row +/- 4
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))
    road_rows = sorted(set(r for wr in wire_rows for r in [wr - 4, wr + 4]
                           if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for wc in wire_cols for c in [wc - 4, wc + 4]
                           if 3 < c < WORLD_W - 3))

    # ---- STEP 1: Ensure power plants distributed across map ----
    # Grid of plants every 20 cols, 20 rows (denser than parent)
    plant_positions = [(px, py) for py in range(10, WORLD_H - 8, 20)
                       for px in range(10, WORLD_W - 8, 20)]

    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 5), min(WORLD_W, ppx + 6)
        y0, y1 = max(0, ppy - 5), min(WORLD_H, ppy + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place if not on zone or road
            if not bool(zone_tiles[ppy, ppx]) and not bool(rm[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- STEP 2: Wire network - connect plants and extend horizontal spines ----
    for wr in wire_rows:
        # Check if wire row already fully covered
        row_infra = wm[wr, :] | pm[wr, :]
        if not row_infra.any():
            # Find nearest plant and step wire toward this row
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                dists = np.abs(pys - wr)
                k = np.argmin(dists)
                wx, wy = int(pxs[k]), int(pys[k])
                ny = wy + (1 if wr > wy else -1)
                if ib(wx, ny) and not bool(zone_tiles[ny, wx]) and not bool(rm[ny, wx]):
                    return (Tool.WIRE, wx, ny)
            continue
        idxs = np.where(row_infra)[0]
        left, right = int(idxs[0]), int(idxs[-1])
        if left > 3:
            nx = left - 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)
        if right < WORLD_W - 4:
            nx = right + 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Fill gaps
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(zone_tiles[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    # Vertical wire spines
    for wc in wire_cols:
        col_infra = wm[:, wc] | pm[:, wc]
        if not col_infra.any():
            if ib(wc, 50) and bool(em[50, wc]) and not bool(rm[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        idxs = np.where(col_infra)[0]
        top, bot = int(idxs[0]), int(idxs[-1])
        if top > 3:
            ny = top - 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 4:
            ny = bot + 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(zone_tiles[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- STEP 3: Road network ----
    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        idxs = np.where(row_rd)[0]
        left, right = int(idxs[0]), int(idxs[-1])
        if left > 4 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]) and not bool(wm[rr, left-1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]) and not bool(wm[rr, right+1]):
            return (Tool.ROAD, right + 1, rr)
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]) and not bool(wm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        idxs = np.where(col_rd)[0]
        top, bot = int(idxs[0]), int(idxs[-1])
        if top > 4 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]) and not bool(wm[top-1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]) and not bool(wm[bot+1, rc]):
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]) and not bool(wm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- STEP 4: Wire extension toward unpowered zones (reactive) ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    if len(uzxs) > 0:
        # Find empty tiles adjacent to existing power
        adj_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dy == -1: adj_power[:-1, :] |= power_src[1:, :]
            elif dy == 1: adj_power[1:, :] |= power_src[:-1, :]
            elif dx == -1: adj_power[:, :-1] |= power_src[:, 1:]
            elif dx == 1: adj_power[:, 1:] |= power_src[:, :-1]

        wire_cand = em & adj_power & ~zone_tiles & ~rm
        wire_cand[:2, :] = False; wire_cand[WORLD_H-2:, :] = False
        wire_cand[:, :2] = False; wire_cand[:, WORLD_W-2:] = False
        wys_c, wxs_c = np.where(wire_cand)
        if len(wxs_c) > 0:
            best_d, best_k = 1e9, 0
            stride_u = max(1, len(uzxs) // 30)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- STEP 5: Road extension toward unserved zones (reactive) ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    if len(usxs) > 0:
        adj_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dy == -1: adj_road[:-1, :] |= rm[1:, :]
            elif dy == 1: adj_road[1:, :] |= rm[:-1, :]
            elif dx == -1: adj_road[:, :-1] |= rm[:, 1:]
            elif dx == 1: adj_road[:, 1:] |= rm[:, :-1]

        road_cand2 = em & adj_road & ~zone_tiles & ~pm & ~wm
        road_cand2[:2, :] = False; road_cand2[WORLD_H-2:, :] = False
        road_cand2[:, :2] = False; road_cand2[:, WORLD_W-2:] = False
        rys_c, rxs_c = np.where(road_cand2)
        if len(rxs_c) > 0:
            best_d, best_k = 1e9, 0
            stride_u = max(1, len(usxs) // 30)
            for i in range(len(rxs_c)):
                cx, cy = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                        for j in range(0, len(usxs), stride_u))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- STEP 6: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[:3, :] = False; zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, :3] = False; zone_cand[:, WORLD_W-3:] = False
    # Protect infrastructure rows/cols
    for wr in wire_rows:
        zone_cand[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for rr in road_rows:
        zone_cand[max(0, rr-1):min(WORLD_H, rr+2), :] = False
    for wc in wire_cols:
        zone_cand[:, max(0, wc-1):min(WORLD_W, wc+2)] = False
    for rc in road_cols:
        zone_cand[:, max(0, rc-1):min(WORLD_W, rc+2)] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 200)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Slightly prefer moderate spacing from existing zones
            zone_score = np.where(min_zone_dist < 3, 400.0,
                         np.where(min_zone_dist > 18, min_zone_dist * 0.4, 0.0))
        else:
            zone_score = np.abs(cxs_arr - 60).astype(float) * 0.01

        score = road_dist * 1.5 + zone_score
        order = np.argsort(score)
        # Vary starting offset by step to spread across map
        off = (step * 11 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- STEP 7: Civic services (reactive to population) ----
    if pop > 15:
        fire_spots = [(fx, fy) for fy in range(6, 96, 10) for fx in range(6, 116, 14)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(wm[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_spots = [(px2, py2) for py2 in range(7, 96, 12) for px2 in range(7, 116, 16)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]) and not bool(wm[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 120:
        park_spots = [(pkx, pky) for pky in range(5, 96, 8) for pkx in range(5, 116, 10)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 350:
        stadium_spots = [(sx, sy) for sy in range(15, 88, 25) for sx in range(15, 110, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 5000:
        nuclear_spots = [(nx, ny) for ny in range(12, 90, 18) for nx in range(12, 112, 18)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 7), min(WORLD_W, npx + 8)
                y0, y1 = max(0, npy - 7), min(WORLD_H, npy + 8)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1000:
        airport_spots = [(60, 6), (60, 93), (6, 50), (113, 50),
                         (30, 6), (90, 6), (30, 93), (90, 93)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [(6, 50), (113, 50), (60, 5), (60, 93)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: lay road outward from nearest plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(4, 0), (-4, 0), (0, 4), (0, -4), (7, 0), (-7, 0), (0, 7), (0, -7)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 5 coal plants spread across map with wire spines and flanking roads."""
    actions = []
    # Five starting plants: far-left, mid-left, center, mid-right, far-right
    for cx, cy in [(12, 50), (35, 50), (60, 50), (85, 50), (108, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Vertical wire spine above and below
        for dy in [-1, 1, -2, 2, -3, 3]:
            actions.append((Tool.WIRE, cx, cy + dy))
        # Flanking roads
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense neighborhood grid: 8 cols x 7 rows = 56 neighborhoods
    # Spaced to cover the whole 120x100 map effectively
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [10, 24, 38, 52, 66, 80, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 5
        if pop < 150:   return 10
        if pop < 300:   return 16
        if pop < 600:   return 24
        if pop < 1200:  return 34
        if pop < 2500:  return 44
        if pop < 5000:  return 54
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Spread evenly across all neighborhoods
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    hood_set = set(map(tuple, active_hoods))

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Find nearest empty spot for power plant
        for r in range(12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (vertical + horizontal cross pattern) ----
    spine_range = 12

    # Rotate which hoods we process to avoid bottleneck
    n_proc = max(1, len(active_hoods) // 2 + 1)
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods), 1) >= n_proc:
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap: start wire from plant neighbor
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        # Horizontal neighbors
        for dhx in [15, 25]:
            hx2, hy2 = hx1 + dhx, hy1
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        # Vertical neighbors
        for dhy in [14, 15]:
            hx2, hy2 = hx1, hy1 + dhy
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    n_road_proc = max(1, len(active_hoods) // 2 + 1)
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 3) % max(len(active_hoods), 1) >= n_road_proc:
            continue

        # Flanking vertical spine roads at hx-1, hx+1
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Flanking horizontal spine roads at hy-1, hy+1
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (wire or plant within 7 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS FROM EXISTING ROADS INTO POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (8, 10), (28, 10), (48, 10), (68, 10), (88, 10), (108, 10),
            (8, 28), (28, 28), (48, 28), (68, 28), (88, 28), (108, 28),
            (8, 46), (28, 46), (48, 46), (68, 46), (88, 46), (108, 46),
            (8, 64), (28, 64), (48, 64), (68, 64), (88, 64), (108, 64),
            (8, 82), (28, 82), (48, 82), (68, 82), (88, 82), (108, 82),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (18, 18), (48, 18), (78, 18), (108, 18),
            (18, 36), (48, 36), (78, 36), (108, 36),
            (18, 54), (48, 54), (78, 54), (108, 54),
            (18, 72), (48, 72), (78, 72), (108, 72),
            (18, 90), (48, 90), (78, 90), (108, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (33, 33), (83, 33), (33, 63), (83, 63),
            (58, 15), (58, 85), (8, 50), (112, 50),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (5, 30), (115, 30), (5, 70), (115, 70),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(8, 90), (112, 90), (8, 8), (112, 8), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 6), (70, 6), (50, 93), (70, 93), (5, 48), (113, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones to boost land value ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire connections and seed roads"""
    actions = []
    # Three core power plants
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 20))
