def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID: 6 cols x 5 rows = 30 neighborhoods ----
    nh_cols = [10, 30, 50, 70, 90, 110]
    nh_rows = [10, 28, 50, 72, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 12
        if pop < 1000:  return 18
        if pop < 2000:  return 24
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread evenly
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- DILATE HELPER ----
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]) and not bool(rm[ny, nx]) and not bool(wm[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES connecting plants to hood centers ----
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 16), min(WORLD_W, hx + 17)
    y0, y1 = max(0, hy - 16), min(WORLD_H, hy + 17)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0

        # Wire from plant toward hood (vertical first)
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if bool(rm[wy, px_local]): continue
                if bool(zone_tiles[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if bool(rm[hy, wx]): continue
                if bool(zone_tiles[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            # Horizontal neighbors (same row)
            if hy1 == hy2 and abs(hx2 - hx1) <= 30:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx, mxx + 1):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if bool(rm[hy1, cx2]) or bool(zone_tiles[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical neighbors (same col)
            if hx1 == hx2 and abs(hy2 - hy1) <= 30:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny, mxy + 1):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if bool(rm[cy2, hx1]) or bool(zone_tiles[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines near active hoods ----
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]
    spine_range = 16

    # Vertical roads on both sides of horizontal wire spine
    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]): continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    # Horizontal roads on both sides of vertical wire spine
    for ry2 in [hy3 - 1, hy3 + 1]:
        if not ib(hx3, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]): continue
            if bool(pm[ry2, rcx]) or bool(wm[ry2, rcx]): continue
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 4b: CROSS-ROAD GRID between hoods ----
    # Add connecting roads between same-row hoods
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 28:
                for cy2 in [hy1 - 1, hy1 + 1]:
                    if not ib(hx1, cy2): continue
                    mnx2, mxx2 = min(hx1, hx2), max(hx1, hx2)
                    for cx3 in range(mnx2, mxx2 + 1):
                        if not ib(cx3, cy2): continue
                        if not bool(em[cy2, cx3]): continue
                        if bool(pm[cy2, cx3]) or bool(wm[cy2, cx3]): continue
                        has_adj = False
                        for ax2, ay2 in [(cx3-1,cy2),(cx3+1,cy2),(cx3,cy2-1),(cx3,cy2+1)]:
                            if ib(ax2, ay2) and bool(rm[ay2, ax2]):
                                has_adj = True
                                break
                        if has_adj:
                            return (Tool.ROAD, cx3, cy2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 33% com, 27% ind
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: close to active hoods but spread out
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Also prefer spots near existing roads
        road_dist = np.full(len(cxs), 9999.0)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            for i in range(0, len(road_xs), rd_stride):
                d2 = np.abs(cxs - road_xs[i]) + np.abs(cys - road_ys[i])
                road_dist = np.minimum(road_dist, d2.astype(float))

        score = best_dist * 0.5 + road_dist * 2.0
        order = np.argsort(score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]) and not bool(wm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: FIX UNPOWERED ZONES with wire extension ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    if len(uzxs) > 0:
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            else:           shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & adj_to_power & ~zone_tiles & ~rm
        wys_c, wxs_c = np.where(wire_cand)
        if len(wxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(uzxs) // 20)
            for i in range(len(wxs_c)):
                cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx2 - int(uzxs[j])) + abs(cy2 - int(uzys[j]))
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 8: FIX UNSERVED ZONES with road extension ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    if len(usxs) > 0:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
            else:           shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
        rys_c, rxs_c = np.where(road_cand2)
        if len(rxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(usxs) // 20)
            for i in range(len(rxs_c)):
                cx2, cy2 = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx2 - int(usxs[j])) + abs(cy2 - int(usys[j]))
                        for j in range(0, len(usxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- PHASE 9: CIVIC SERVICES (reactive) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fy in range(8, WORLD_H, 18) for fx in range(8, WORLD_W, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_spots = [(px2, py2) for py2 in range(10, WORLD_H, 20) for px2 in range(10, WORLD_W, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 3 == 0:
        park_cands = em & near_road & near_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 800:
        stadium_spots = [(sx, sy) for sy in range(15, WORLD_H-10, 25) for sx in range(15, WORLD_W-10, 28)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # ---- PHASE 10: NUCLEAR UPGRADES for mature cities ----
    if pop > 1500 and step % 2 == 0:
        nuclear_spots = [(nx2, ny2) for ny2 in range(10, WORLD_H-8, 18) for nx2 in range(10, WORLD_W-8, 20)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 8), min(WORLD_W, npx + 9)
                y0, y1 = max(0, npy - 8), min(WORLD_H, npy + 9)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        seaport_spots = [(6, 50), (113, 50), (60, 5), (60, 94), (6, 25), (6, 75), (113, 25), (113, 75)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 3000:
        airport_spots = [(40, 6), (80, 6), (40, 93), (80, 93), (6, 40), (6, 60), (113, 40), (113, 60)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and not bool(rm[ny3, nx3]) and not bool(zone_tiles[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]) and not bool(rm[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in a diamond layout with wire connections."""
    actions = []
    # 4 power plants at cardinal positions
    plants = [(30, 20), (90, 20), (30, 75), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spines in both directions
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
    # Connect plants horizontally at y=20 and y=75
    for cx in range(30, 91):
        actions.append((Tool.WIRE, cx, 20))
        actions.append((Tool.WIRE, cx, 75))
    # Connect plants vertically at x=30 and x=90
    for cy in range(20, 76):
        actions.append((Tool.WIRE, 30, cy))
        actions.append((Tool.WIRE, 90, cy))
    return actions[:60]  # Keep init small


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 45% res, 30% com, 25% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 4 main neighborhoods in a 2x2 grid, each with its own power plant
    # Neighborhoods are at (30,20), (90,20), (30,75), (90,75)
    # Plus extra neighborhoods as pop grows
    base_anchors = [
        (30, 20),   # top-left
        (90, 20),   # top-right
        (30, 75),   # bottom-left
        (90, 75),   # bottom-right
    ]
    extra_anchors = [
        (60, 47),   # center
        (10, 47),   # far left
        (110, 47),  # far right
        (60, 10),   # top center
        (60, 90),   # bottom center
    ]

    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 3
        if pop < 600:   return 4
        if pop < 1000:  return 5
        if pop < 1500:  return 6
        if pop < 2000:  return 7
        if pop < 2500:  return 8
        return 9

    n_active = num_active()
    all_anchors = base_anchors + extra_anchors
    active_anchors = all_anchors[:min(n_active, len(all_anchors))]

    # Road offsets relative to wire spine (per anchor)
    def get_road_cols(ax):
        return (ax - 2, ax + 2)

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearby empty spot
        found = False
        for r in range(0, 10):
            if found:
                break
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: build a connected wire mesh ----
    # Horizontal wire rows at anchor y-levels
    wire_ys = sorted(set(py for (px, py) in active_anchors))
    wire_xs = sorted(set(px for (px, py) in active_anchors))

    # Add cross wire rows/cols for center connectivity
    extra_wire_rows = []
    extra_wire_cols = []
    if n_active >= 5:
        extra_wire_rows = [47]
        extra_wire_cols = [60]

    all_wire_rows = sorted(set(wire_ys + extra_wire_rows))
    all_wire_cols = sorted(set(wire_xs + extra_wire_cols))

    # Build horizontal wire rows
    for wy in all_wire_rows:
        # Span the full width between leftmost and rightmost anchor x
        x_start = max(2, min(wire_xs) - 5)
        x_end = min(WORLD_W - 3, max(wire_xs) + 5)
        for cx in range(x_start, x_end + 1):
            if ib(cx, wy) and bool(em[wy, cx]) and not bool(pm[wy, cx]):
                return (Tool.WIRE, cx, wy)

    # Build vertical wire columns
    for wx in all_wire_cols:
        y_start = max(2, min(wire_ys) - 5)
        y_end = min(WORLD_H - 3, max(wire_ys) + 5)
        for cy in range(y_start, y_end + 1):
            if ib(wx, cy) and bool(em[cy, wx]) and not bool(pm[cy, wx]):
                return (Tool.WIRE, wx, cy)

    # ---- ROAD NETWORK: roads flanking wire columns ----
    spine_half = min(35, 12 + pop // 8)

    for (px, py) in active_anchors:
        rl, rr = get_road_cols(px)
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check if wire spine exists
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        # Place roads on both sides of wire
        for wr in wire_in_col:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels (connecting neighborhoods) ----
    for wy in all_wire_rows:
        for road_y_off in [-3, 3]:
            ry = wy + road_y_off
            if not ib(0, ry):
                continue
            x_start = max(2, min(wire_xs) - 6)
            x_end = min(WORLD_W - 3, max(wire_xs) + 6)
            for cx in range(x_start, x_end + 1):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    return (Tool.ROAD, cx, ry)

    # ---- CROSS ROADS connecting wire rows ----
    if pop > 80:
        for wx in all_wire_cols:
            for dx_off in [-3, 3]:
                rx = wx + dx_off
                if not ib(rx, 0):
                    continue
                sorted_rows = sorted(all_wire_rows)
                for i in range(len(sorted_rows) - 1):
                    y1 = sorted_rows[i]
                    y2 = sorted_rows[i + 1]
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.9
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (placed near roads, scaled with pop) ----
    # Fire stations: dense grid
    if pop > 50:
        fire_spots = []
        for fy in range(10, 95, 20):
            for fx in range(8, 115, 25):
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = []
        for py2 in range(15, 90, 25):
            for px2 in range(12, 112, 30):
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (15, 8), (60, 8), (105, 8),
            (15, 92), (60, 92), (105, 92),
            (5, 47), (115, 47),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Nuclear power for extra capacity
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 50), (90, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power cluster + cross roads/wires."""
    actions = []
    # Place 3 coal plants in a triangle for reliable power coverage
    plants = [(58, 48), (38, 68), (78, 68)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spines from center outward
    for x in range(35, 82):
        actions.append((Tool.WIRE, x, 58))
    for y in range(45, 72):
        actions.append((Tool.WIRE, 58, y))
    # Initial road grid near center
    for x in range(30, 90):
        actions.append((Tool.ROAD, x, 55))
        actions.append((Tool.ROAD, x, 62))
    for y in range(42, 78):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 66, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Counters
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        if rr < 0.55:
            return Tool.RESIDENTIAL
        return Tool.RESIDENTIAL

    # Build neighbor masks efficiently
    power_src = wm | pm

    # 5-cell power neighborhood
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # 3-cell road neighborhood
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Define a dense grid of neighborhoods across the whole map
    all_hoods = []
    for hy in range(10, 95, 12):
        for hx in range(10, 115, 12):
            all_hoods.append((hx, hy))

    # Scale active hoods with population
    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 600:   return 16
        if pop < 1000:  return 25
        if pop < 2000:  return 40
        if pop < 4000:  return 60
        if pop < 8000:  return 80
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick hoods near center first
    cx, cy = 60, 50
    hood_dists = sorted(all_hoods, key=lambda h: abs(h[0]-cx)+abs(h[1]-cy))
    active_hoods = hood_dists[:n_active]

    # ---- PHASE 1: Ensure each active hood has a power plant nearby ----
    plant_ys, plant_xs = np.where(pm)
    plant_locs = list(zip(plant_xs.tolist(), plant_ys.tolist()))

    for hx, hy in active_hoods:
        x0, x1 = max(0, hx-13), min(WORLD_W, hx+14)
        y0, y1 = max(0, hy-13), min(WORLD_H, hy+14)
        if not bool(np.any(pm[y0:y1, x0:x1])) and funds > 800:
            # Find nearest empty spot
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx)==r or abs(dy)==r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire from each plant toward nearest unpowered hood ----
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    if not bool(nbr_power[hy, hx]):
        # Find nearest plant
        if plant_locs:
            best_p = min(plant_locs, key=lambda p: abs(p[0]-hx)+abs(p[1]-hy))
            px, py = best_p
            # Wire L-path: horizontal then vertical
            # Step along x first
            if px != hx:
                step_x = 1 if hx > px else -1
                cur_x = px + step_x
                while cur_x != hx + step_x:
                    if ib(cur_x, py) and bool(em[py, cur_x]) and not bool(pm[py, cur_x]) and not bool(wm[py, cur_x]):
                        return (Tool.WIRE, cur_x, py)
                    cur_x += step_x
            if py != hy:
                step_y = 1 if hy > py else -1
                cur_y = py + step_y
                while cur_y != hy + step_y:
                    if ib(hx, cur_y) and bool(em[cur_y, hx]) and not bool(pm[cur_y, hx]) and not bool(wm[cur_y, hx]):
                        return (Tool.WIRE, hx, cur_y)
                    cur_y += step_y

    # ---- PHASE 3: Expand wire network from existing wire/plants ----
    # Find frontier: wire/plant tiles with empty neighbors not yet wired
    # Only run occasionally to save steps for zoning
    if step % 3 == 0:
        frontier_y, frontier_x = np.where(wm)
        if len(frontier_x) > 0:
            sk = (step * 7) % len(frontier_x)
            for off in range(min(len(frontier_x), 50)):
                k = (sk + off * 3) % len(frontier_x)
                wx, wy = int(frontier_x[k]), int(frontier_y[k])
                # Extend toward nearest unpowered hood
                best_h = None
                best_d = 9999
                for ahx, ahy in active_hoods:
                    if not bool(nbr_power[ahy, ahx]):
                        d = abs(wx-ahx)+abs(wy-ahy)
                        if d < best_d:
                            best_d = d
                            best_h = (ahx, ahy)
                if best_h:
                    thx, thy = best_h
                    # Move one step toward target
                    dx_w = 0 if thx==wx else (1 if thx>wx else -1)
                    dy_w = 0 if thy==wy else (1 if thy>wy else -1)
                    # Try x direction first
                    if dx_w != 0:
                        nx, ny = wx+dx_w, wy
                        if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                            return (Tool.WIRE, nx, ny)
                    if dy_w != 0:
                        nx, ny = wx, wy+dy_w
                        if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                            return (Tool.WIRE, nx, ny)

    # ---- PHASE 4: Build road grid ----
    # Horizontal roads every 8 rows, vertical roads every 8 cols
    road_rows = list(range(8, 95, 8))
    road_cols = list(range(8, 115, 8))

    # Try to seed or extend horizontal roads near powered areas
    for rr in road_rows:
        row_r = rm[rr, :]
        if row_r.any():
            idxs = np.where(row_r)[0]
            left = int(idxs[0]); right = int(idxs[-1])
            # Extend left
            if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]) and bool(nbr_power[rr, left-1]):
                return (Tool.ROAD, left-1, rr)
            # Extend right
            if right < WORLD_W-4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]) and bool(nbr_power[rr, right+1]):
                return (Tool.ROAD, right+1, rr)
        elif bool(nbr_power[rr, 60]) and bool(em[rr, 60]):
            return (Tool.ROAD, 60, rr)

    for rc in road_cols:
        col_r = rm[:, rc]
        if col_r.any():
            idxs = np.where(col_r)[0]
            top = int(idxs[0]); bot = int(idxs[-1])
            if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]) and bool(nbr_power[top-1, rc]):
                return (Tool.ROAD, rc, top-1)
            if bot < WORLD_H-4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]) and bool(nbr_power[bot+1, rc]):
                return (Tool.ROAD, rc, bot+1)
        elif bool(nbr_power[50, rc]) and bool(em[50, rc]):
            return (Tool.ROAD, rc, 50)

    # ---- PHASE 5: Place zones ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer close to active hoods and close to existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for ahx, ahy in active_hoods:
            d = np.abs(cxs - ahx) + np.abs(cys - ahy)
            best_dist = np.minimum(best_dist, d.astype(float))

        zone_prox = np.full(len(cxs), 999999.0)
        zys2, zxs2 = np.where(zone_tiles)
        if len(zxs2) > 0:
            stride = max(1, len(zxs2)//80)
            for i in range(0, len(zxs2), stride):
                d2 = np.abs(cxs-zxs2[i]).astype(float)+np.abs(cys-zys2[i]).astype(float)
                zone_prox = np.minimum(zone_prox, d2)
            score = best_dist*0.5 + zone_prox*0.5
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step*7 + pop*3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off+i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: Civic services ----
    if pop > 30 and funds > 500:
        fire_grid = [(fx, fy) for fy in range(15, 90, 16) for fx in range(15, 110, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(nbr_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 120 and funds > 500:
        police_grid = [(px2, py2) for py2 in range(18, 90, 18) for px2 in range(18, 110, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 4 == 0:
        park_y, park_x = np.where(em & nbr_road & nbr_power)
        if len(park_x) > 0:
            idx = (step*13) % len(park_x)
            return (Tool.PARK, int(park_x[idx]), int(park_y[idx]))

    if pop > 350 and funds > 3000:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx-6), min(WORLD_W, npx+7)
            y0b, y1b = max(0, npy-6), min(WORLD_H, npy+7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400 and funds > 2000:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 700 and funds > 3000:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- PHASE 7: Add more coal plants where no power coverage ----
    if funds > 1000:
        for ahy in range(15, 90, 15):
            for ahx in range(15, 110, 15):
                if not bool(nbr_power[ahy, ahx]):
                    # Place plant here if empty
                    if ib(ahx, ahy) and bool(em[ahy, ahx]):
                        return (Tool.COALPOWER, ahx, ahy)
                    # Try adjacent
                    for r in range(1, 8):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx)==r or abs(dy)==r:
                                    nx, ny = ahx+dx, ahy+dy
                                    if ib(nx, ny) and bool(em[ny, nx]):
                                        return (Tool.COALPOWER, nx, ny)

    # ---- FALLBACK: extend road from existing network ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step*11) % len(road_xs2)
        for off in range(min(len(road_xs2), 80)):
            k = (sk + off*7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step*13) % len(wxs_arr)
        for off in range(min(len(wxs_arr), 60)):
            k = (sk2 + off*5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place coal plant near map center ----
    if funds > 800:
        for r in range(1, 30):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx)==r or abs(dy)==r:
                        nx, ny = 60+dx, 50+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

# High-reactivity closed-loop city builder
# Strategy: 6x5 grid of 30 neighborhoods, each with dedicated power plant
# Dense road grid, balanced zoning, reactive civic services
# Key improvements over parent:
# - More neighborhoods (30 vs 20)
# - Denser road grid (roads every 4 tiles instead of flanking)
# - Better zone placement prioritization
# - Earlier civic services
# - Faster infrastructure expansion

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + initial roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross in both directions
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads on both sides of horizontal wire
    for dx in range(-9, 10):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- 6 columns x 5 rows = 30 neighborhoods ----
    nh_cols = [10, 30, 50, 70, 90, 110]
    nh_rows = [10, 28, 50, 72, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 10
        if pop < 1000:  return 15
        if pop < 2000:  return 20
        if pop < 4000:  return 25
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread evenly
    step_size = len(all_hoods) / n_active
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS (vectorized) ----
    power_src = wm | pm
    # Fast approximation using cumsum for power neighbor check (radius 8)
    def dilate(mask, radius):
        result = mask.copy().astype(np.float32)
        # Horizontal
        padded = np.pad(result, ((0,0),(radius,radius)), mode='constant')
        cs = np.cumsum(padded, axis=1)
        result = (cs[:, 2*radius:WORLD_W+2*radius] - cs[:, 0:WORLD_W]) > 0
        # Vertical
        padded2 = np.pad(result.astype(np.float32), ((radius,radius),(0,0)), mode='constant')
        cs2 = np.cumsum(padded2, axis=0)
        result = (cs2[2*radius:WORLD_H+2*radius, :] - cs2[0:WORLD_H, :]) > 0
        return result

    nbr_power = dilate(power_src, 7)
    nbr_road = dilate(rm, 3)

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from plant toward hood center ----
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine_range = 14

    x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
    y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0

        # Draw wire from plant to hood center (vertical then horizontal)
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

        # Extend vertical wire spine
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Extend horizontal wire spine
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: INTER-HOOD WIRE CONNECTIONS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 22:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx + 1, mxx):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and abs(hy2 - hy1) <= 24:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny + 1, mxy):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: DENSE ROAD GRID ----
    # Place roads along wire spines (offset by 1) AND perpendicular roads
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    # Road flanking horizontal wire (both sides)
    for ry_off in [-1, 1, -2, 2]:
        ry = hy3 + ry_off
        if not ib(hx3, ry): continue
        for dx in range(-spine_range, spine_range + 1):
            rx = hx3 + dx
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            # Only if the wire spine or road already exists nearby
            if bool(wm[ry3, rx]) if (ry3 := hy3) else False: continue
            if bool(wm[hy3, rx]) or bool(pm[hy3, rx]):
                return (Tool.ROAD, rx, ry)

    # Road flanking vertical wire (both sides)
    for rx_off in [-1, 1, -2, 2]:
        rx2 = hx3 + rx_off
        if not ib(rx2, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry2 = hy3 + dy
            if not ib(rx2, ry2): continue
            if not bool(em[ry2, rx2]) or bool(pm[ry2, rx2]): continue
            if bool(wm[ry2, hx3]) or bool(pm[ry2, hx3]):
                return (Tool.ROAD, rx2, ry2)

    # ---- PHASE 5: CROSS-ROADS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 22:
                mnx2, mxx2 = min(hx1, hx2), max(hx1, hx2)
                for roff in [-1, 1]:
                    cy2 = hy1 + roff
                    if not ib(hx1, cy2): continue
                    for cx3 in range(mnx2, mxx2 + 1):
                        if not ib(cx3, cy2): continue
                        if not bool(em[cy2, cx3]) and not bool(rm[cy2, cx3]): continue
                        if bool(pm[cy2, cx3]): continue
                        has_adj = any(ib(ax2, cy2) and bool(rm[cy2, ax2])
                                      for ax2 in [cx3-1, cx3+1]) or \
                                  any(ib(cx3, ay2) and bool(rm[ay2, cx3])
                                      for ay2 in [cy2-1, cy2+1])
                        if has_adj and bool(em[cy2, cx3]):
                            return (Tool.ROAD, cx3, cy2)

    # ---- PHASE 6: ZONE PLACEMENT (dense, close to infrastructure) ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 35% com, 25% ind (more res for population)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS INTO POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: CIVIC SERVICES (reactive, lower thresholds) ----
    # Fire stations early and dense
    if pop > 50:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 16) for fy in range(12, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    # Police stations
    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 20) for py2 in range(15, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # Stadiums
    if pop > 500:
        stadiums = [(20, 20), (100, 20), (20, 80), (100, 80),
                    (60, 10), (60, 90), (10, 50), (110, 50),
                    (40, 50), (80, 50), (60, 35), (60, 65),
                    (30, 35), (90, 35), (30, 65), (90, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Seaports
    if pop > 1000:
        seaports = [(6, 94), (114, 94), (6, 6), (114, 6), (60, 97), (60, 3),
                    (30, 97), (90, 97), (30, 3), (90, 3)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # Airports
    if pop > 2000:
        airports = [(35, 5), (85, 5), (35, 94), (85, 94),
                    (5, 35), (5, 65), (114, 35), (114, 65),
                    (60, 5), (60, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR UPGRADE ----
    if pop > 1500 and step % 2 == 0:
        nuclear_spots = [(60, 50), (12, 12), (108, 12), (12, 88), (108, 88),
                         (35, 28), (85, 28), (35, 72), (85, 72),
                         (10, 28), (110, 28), (10, 72), (110, 72),
                         (60, 20), (60, 80), (20, 50), (100, 50),
                         (50, 10), (70, 10), (50, 90), (70, 90)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 100 and step % 3 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 31) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants at corners + center with wire grid and roads."""
    actions = []
    # Place coal plants at strategic positions
    plant_positions = [
        (20, 20), (60, 20), (100, 20),
        (20, 50), (60, 50), (100, 50),
        (20, 80), (60, 80), (100, 80),
    ]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Wire north-south spine
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Wire east-west connector
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
        # Flanking roads
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target: 40% res, 35% com, 25% ind - more commercial than parent
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhoods arranged in 3x3 grid covering more of the map
    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 50, 80]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 30:    return 1
        if pop < 100:   return 2
        if pop < 200:   return 3
        if pop < 400:   return 4
        if pop < 700:   return 5
        if pop < 1000:  return 6
        if pop < 1500:  return 7
        if pop < 2500:  return 8
        return 9

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE CROSS PATTERN (both horizontal and vertical spines) ----
    spine_half = min(25, 8 + pop // 8)
    for (px, py) in active_anchors:
        # Vertical spine
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        for wy in range(spine_top, spine_bot + 1):
            if ib(px, wy) and not bool(pm[wy, px]) and not bool(rm[wy, px]) and not bool(wm[wy, px]) and bool(em[wy, px]):
                return (Tool.WIRE, px, wy)
        # Horizontal spine
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        for wx in range(spine_left, spine_right + 1):
            if ib(wx, py) and not bool(pm[py, wx]) and not bool(rm[py, wx]) and not bool(wm[py, wx]) and bool(em[py, wx]):
                return (Tool.WIRE, wx, py)

    # ---- HORIZONTAL WIRE connecting anchors in same row ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1 = row_anchors[i][0]
            x2 = row_anchors[i + 1][0]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor columns ----
    x_levels = sorted(set(px for (px, _) in active_anchors))
    for xl in x_levels:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1 = col_anchors[i][1]
            y2 = col_anchors[i + 1][1]
            for cy in range(y1 + 1, y2):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: 4 roads flanking each spine (±2 and ±3 from wire) ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)

        # Roads flanking vertical spine
        cycle = (step + idx * 5) % 2
        for road_x in [px - 2, px + 2]:
            for wy in range(spine_top + cycle, spine_bot + 1, 2):
                if ib(road_x, wy) and bool(em[wy, road_x]) and not bool(pm[wy, road_x]):
                    return (Tool.ROAD, road_x, wy)

        # Roads flanking horizontal spine
        for road_y in [py - 2, py + 2]:
            for wx in range(spine_left + cycle, spine_right + 1, 2):
                if ib(wx, road_y) and bool(em[road_y, wx]) and not bool(pm[road_y, wx]):
                    return (Tool.ROAD, wx, road_y)

    # ---- HORIZONTAL ROADS connecting neighborhoods ----
    if pop > 10:
        for yl in y_levels:
            row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
            if len(row_anchors) < 2:
                continue
            x_start = row_anchors[0][0] - spine_half
            x_end = row_anchors[-1][0] + spine_half
            for horiz_y in [yl - 3, yl + 3]:
                if not (0 <= horiz_y < WORLD_H):
                    continue
                for cx in range(max(2, x_start), min(WORLD_W - 2, x_end + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting row levels ----
    if pop > 30:
        for xl in x_levels:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            if len(col_anchors) < 2:
                continue
            for road_x in [xl - 3, xl + 3]:
                y_start = col_anchors[0][1] - spine_half
                y_end = col_anchors[-1][1] + spine_half
                for cy in range(max(2, y_start), min(WORLD_H - 2, y_end + 1)):
                    if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT - prioritize near wire AND road ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 11) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (earlier thresholds than parent) ----
    if pop > 40:
        fire_spots = [
            (5, 10), (30, 10), (60, 10), (90, 10), (115, 10),
            (5, 35), (30, 35), (60, 35), (90, 35), (115, 35),
            (5, 60), (30, 60), (60, 60), (90, 60), (115, 60),
            (5, 85), (30, 85), (60, 85), (90, 85), (115, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (10, 20), (40, 20), (70, 20), (105, 20),
            (10, 50), (40, 50), (70, 50), (105, 50),
            (10, 80), (40, 80), (70, 80), (105, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (8, 8), (55, 8), (110, 8),
            (8, 92), (55, 92), (110, 92),
            (8, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (4, 4), (116, 4), (4, 96), (116, 96),
            (60, 4), (60, 96), (4, 50), (116, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 5), (5, 48), (115, 48), (55, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(4, 92), (116, 92), (60, 96)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3), (3, -3), (-3, 3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 23) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: dense grid of coal plants + wire backbone + road grid"""
    actions = []
    # 9 coal plants in 3x3 grid pattern
    plants = [
        (20, 15), (60, 15), (100, 15),
        (20, 50), (60, 50), (100, 50),
        (20, 85), (60, 85), (100, 85),
    ]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Three horizontal wire corridors
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 15))
        actions.append((Tool.WIRE, x, 50))
        actions.append((Tool.WIRE, x, 85))
    # Three vertical wire corridors
    for y in range(1, 99):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Roads flanking all wire corridors
    for x in range(1, 119):
        for wy in [15, 50, 85]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    # Roads flanking vertical wire corridors
    for y in range(1, 99):
        for wc in [20, 60, 100]:
            actions.append((Tool.ROAD, wc - 1, y))
            actions.append((Tool.ROAD, wc + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Wire/road corridors
    wire_rows = [15, 50, 85]
    wire_cols = [20, 60, 100]

    # Extra cross roads at midpoints
    cross_rows = [32, 67]  # between wire rows
    cross_cols = [40, 80]  # between wire cols

    def pick_tool():
        # More balanced: 40% res, 30% com, 30% ind - shift toward com/ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            # Early: mostly residential to boost pop
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.20:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 500:
            if ir < 0.28:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # Balanced with slight com/ind lean
            if ir < 0.32:
                return Tool.INDUSTRIAL
            if cr < 0.32:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # 16 neighborhoods (4x4 grid) covering the full map
    nh_positions = []
    for row in range(4):
        for col in range(4):
            cx = 15 + col * 30   # 15, 45, 75, 105
            cy = 12 + row * 25   # 12, 37, 62, 87
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            # Center 4 hoods
            return [nh_positions[5], nh_positions[6], nh_positions[9], nh_positions[10]]
        elif pop < 400:
            # 8 central hoods
            return nh_positions[4:12]
        elif pop < 1000:
            # 12 hoods
            return nh_positions[2:14]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # ---- PHASE 0: Ensure power plants near ALL active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    if (ib(wx-1, wr) and bool(row_wire[wx-1])) or (ib(wx+1, wr) and bool(row_wire[wx+1])):
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    if (ib(wc, wy-1) and bool(col_wire[wy-1])) or (ib(wc, wy+1) and bool(col_wire[wy+1])):
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add cross-roads connecting neighborhoods horizontally
        for cr in cross_rows:
            for rx in range(1, WORLD_W - 1):
                if ib(rx, cr) and bool(em[cr, rx]) and not bool(pm[cr, rx]) and bool(near_power[cr, rx]):
                    adj = (ib(rx-1, cr) and bool(rm[cr, rx-1])) or (ib(rx+1, cr) and bool(rm[cr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, cr)

    elif phase == 5:
        # Add cross-roads connecting neighborhoods vertically
        for cc in cross_cols:
            for ry in range(1, WORLD_H - 1):
                if ib(cc, ry) and bool(em[ry, cc]) and not bool(pm[ry, cc]) and bool(near_power[ry, cc]):
                    adj = (ib(cc, ry-1) and bool(rm[ry-1, cc])) or (ib(cc, ry+1) and bool(rm[ry+1, cc]))
                    if adj:
                        return (Tool.ROAD, cc, ry)

    elif phase == 6:
        # Extend wire to cross_rows using diagonals from nearest wire
        for cr in cross_rows:
            row_wire = wm[cr, :]
            if not np.any(row_wire):
                # Build from nearest vertical corridor
                for wc in wire_cols:
                    if ib(wc, cr) and bool(em[cr, wc]):
                        return (Tool.WIRE, wc, cr)

    elif phase == 7:
        # More road extensions - extend roads near zones
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            step_k = (step * 17) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (step_k + offset * 11) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Wire from plants toward unpowered hoods
        unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
        if unpowered_hoods:
            wire_ys_arr, wire_xs_arr = np.where(wm | pm)
            if len(wire_xs_arr) > 0:
                target_hx, target_hy = unpowered_hoods[0]
                dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
                dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    else:
        # phase 9: plant additional coal plants where needed
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
            y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
            # Count powered zones in hood area
            powered_here = bool(np.any(near_power[y0:y1, x0:x1]))
            if not powered_here:
                if ib(hx, hy) and bool(em[hy, hx]):
                    return (Tool.COALPOWER, hx, hy)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Don't place zones on wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-2):wr+3, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-2):wc+3] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- CIVIC SERVICES (scaled up) ----
    if pop > 30:
        fire_grid = [
            (10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
            (10, 25), (35, 25), (60, 25), (85, 25), (110, 25),
            (10, 45), (35, 45), (60, 45), (85, 45), (110, 45),
            (10, 65), (35, 65), (60, 65), (85, 65), (110, 65),
            (10, 90), (35, 90), (60, 90), (85, 90), (110, 90),
        ]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_grid = [
            (25, 12), (75, 12), (115, 12),
            (10, 37), (50, 37), (90, 37),
            (25, 62), (75, 62), (115, 62),
            (10, 87), (50, 87), (90, 87),
        ]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadiums = [
            (45, 30), (75, 30), (15, 55), (105, 55),
            (45, 70), (75, 70), (30, 10), (90, 10),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        # Upgrade to nuclear power plants
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (40, 5), (80, 5), (40, 95), (80, 95),
            (5, 48), (115, 48),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(10, 95), (110, 95), (60, 95), (10, 4), (110, 4)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(48, 4), (72, 4), (48, 92), (72, 92), (4, 42), (4, 55)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        # Prefer parks near zones
        zone_dilate = dilate(zone_tiles, 3)
        park_cands &= zone_dilate
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire extension ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place two coal plants with wire connections and road seeds."""
    actions = []
    # Primary plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire horizontal and vertical from center plant
    for x in range(48, 73):
