    # Roads adjacent to wire cols (both sides)
    for y in range(1, 99):
        for wc in [15, 60, 105]:
            actions.append((Tool.ROAD, wc - 1, y))
            actions.append((Tool.ROAD, wc + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Wire backbones and road offsets
    wire_rows = [15, 50, 85]
    wire_cols = [15, 60, 105]
    # Additional cross roads at midpoints
    mid_rows = [30, 67]
    mid_cols = [37, 82]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 35% res, 30% com, 35% ind
        if ir < 0.35:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Define dense 6x5 = 30 neighborhood centers
    nh_positions = []
    for row in range(5):
        for col in range(6):
            cx = 8 + col * 21   # 8, 29, 50, 71, 92, 113
            cy = 8 + row * 21   # 8, 29, 50, 71, 92
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 300:
            # Start with inner 9
            return [nh_positions[7], nh_positions[8], nh_positions[13], nh_positions[14],
                    nh_positions[9], nh_positions[19], nh_positions[20], nh_positions[6], nh_positions[12]]
        elif pop < 800:
            return nh_positions[6:24]
        elif pop < 2000:
            return nh_positions[3:27]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # ---- PHASE 0: Ensure power plants near active neighborhoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left = ib(wx-1, wr) and bool(row_wire[wx-1])
                    right = ib(wx+1, wr) and bool(row_wire[wx+1])
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up = ib(wc, wy-1) and bool(col_wire[wy-1])
                    down = ib(wc, wy+1) and bool(col_wire[wy+1])
                    if (up or down) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads adjacent to wire rows
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads adjacent to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Build mid-row cross roads (horizontal connectors between wire cols)
        for mr in mid_rows:
            for wc_idx in range(len(wire_cols) - 1):
                c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
                for rx in range(c1 + 2, c2 - 1):
                    if ib(rx, mr) and bool(em[mr, rx]) and not bool(pm[mr, rx]):
                        adj = (ib(rx-1, mr) and bool(rm[mr, rx-1])) or \
                              (ib(rx+1, mr) and bool(rm[mr, rx+1]))
                        if adj or bool(near_power[mr, rx]):
                            return (Tool.ROAD, rx, mr)

    elif phase == 5:
        # Build mid-col cross roads (vertical connectors between wire rows)
        for mc in mid_cols:
            for wr_idx in range(len(wire_rows) - 1):
                r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
                for ry in range(r1 + 2, r2 - 1):
                    if ib(mc, ry) and bool(em[ry, mc]) and not bool(pm[ry, mc]):
                        adj = (ib(mc, ry-1) and bool(rm[ry-1, mc])) or \
                              (ib(mc, ry+1) and bool(rm[ry+1, mc]))
                        if adj or bool(near_power[ry, mc]):
                            return (Tool.ROAD, mc, ry)

    elif phase == 6:
        # Extend roads from existing roads toward unpowered areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            step_k = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (step_k + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire extension from existing wire toward unpowered hoods
        unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
        if unpowered:
            wire_ys_arr, wire_xs_arr = np.where(wm | pm)
            if len(wire_xs_arr) > 0:
                thx, thy = unpowered[0]
                dists = np.abs(wire_xs_arr - thx) + np.abs(wire_ys_arr - thy)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                dx = 0 if thx == bwx else (1 if thx > bwx else -1)
                dy = 0 if thy == bwy else (1 if thy > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Add additional cross roads in mid-map areas with power but no road
        midmap_y, midmap_x = np.where(near_power & ~near_road & em)
        if len(midmap_x) > 0:
            # Find one near an existing road to expand road network
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                for i in range(min(len(midmap_x), 50)):
                    k = (step * 17 + i * 13) % len(midmap_x)
                    cx, cy = int(midmap_x[k]), int(midmap_y[k])
                    # Check adjacency to road
                    for dx, dy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
                        nx2, ny2 = cx + dx, cy + dy
                        if ib(nx2, ny2) and bool(rm[ny2, nx2]) and not bool(pm[cy, cx]):
                            return (Tool.ROAD, cx, cy)

    else:
        # phase == 9: wire from existing wire to spread coverage
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            step_k2 = (step * 13) % len(wire_xs3)
            for offset in range(min(len(wire_xs3), 80)):
                k = (step_k2 + offset * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT ----
    # Build candidate mask: empty, near road, near power, not on corridors
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Protect wire/plant corridors from zone placement
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by distance to nearest active hood
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_locs = [
            (8, 5), (29, 5), (50, 5), (71, 5), (92, 5), (113, 5),
            (8, 26), (29, 26), (50, 26), (71, 26), (92, 26), (113, 26),
            (8, 47), (50, 47), (113, 47),
            (8, 68), (29, 68), (50, 68), (71, 68), (92, 68), (113, 68),
            (8, 90), (29, 90), (50, 90), (71, 90), (92, 90), (113, 90),
        ]
        for (sx, sy) in fire_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_locs = [
            (20, 10), (60, 10), (100, 10),
            (20, 40), (60, 40), (100, 40),
            (20, 70), (60, 70), (100, 70),
            (20, 93), (60, 93), (100, 93),
            (8, 55), (113, 55),
        ]
        for (sx, sy) in police_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_locs = [
            (37, 30), (82, 30),
            (37, 67), (82, 67),
            (15, 50), (105, 50),
            (60, 8), (60, 90),
            (37, 50), (82, 50),
        ]
        for (sx, sy) in stadium_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_locs = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (37, 5), (82, 5), (37, 94), (82, 94),
            (5, 30), (115, 30), (5, 67), (115, 67),
        ]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaport_locs = [
            (8, 94), (60, 94), (112, 94),
            (8, 5), (60, 5), (112, 5),
        ]
        for (sx, sy) in seaport_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airport_locs = [
            (45, 5), (75, 5), (45, 90), (75, 90),
            (5, 40), (5, 58), (113, 40), (113, 58),
        ]
        for (sx, sy) in airport_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend road from zone
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
