def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def is_empty(x, y):
        return in_bounds(x, y) and bool(em[y, x])

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Define clusters spread across the entire map - 4 quadrants + center
    clusters = [
        (60, 50),   # center
        (30, 30),   # upper-left
        (90, 30),   # upper-right
        (30, 70),   # lower-left
        (90, 70),   # lower-right
        (60, 20),   # top-center
        (60, 80),   # bottom-center
        (15, 50),   # far-left
        (105, 50),  # far-right
        (15, 20),   # far upper-left
        (105, 20),  # far upper-right
        (15, 80),   # far lower-left
        (105, 80),  # far lower-right
    ]

    # Number of active clusters scales with population
    num_clusters = max(1, min(len(clusters), 1 + pop // 150 + total_zones // 10))
    num_clusters = min(num_clusters, len(clusters))

    def pick_zone_tool():
        t = max(total_zones, 1)
        # Want roughly 50% RES, 25% COM, 25% IND
        if ind_count < 2 or ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count < 2 or com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 0: Ensure each active cluster has a power plant ---
    for i in range(num_clusters):
        cx, cy = clusters[i]
        plant_near = False
        r_check = 8
        x0 = max(0, cx - r_check); x1 = min(WORLD_W, cx + r_check + 1)
        y0 = max(0, cy - r_check); y1 = min(WORLD_H, cy + r_check + 1)
        if np.any(pm[y0:y1, x0:x1]):
            plant_near = True
        if not plant_near:
            # Find a clear spot near cluster for plant
            for r in range(0, 12):
                placed = False
                for dx in range(-r, r+1):
                    for dy in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        px, py = cx + dx, cy + dy
                        if not in_bounds(px, py):
                            continue
                        # Check 3x3 area
                        clear = True
                        for ddy in range(-1, 2):
                            for ddx in range(-1, 2):
                                nx2, ny2 = px+ddx, py+ddy
                                if not in_bounds(nx2, ny2) or not bool(em[ny2, nx2]):
                                    clear = False
                                    break
                            if not clear:
                                break
                        if clear:
                            return (Tool.COALPOWER, px, py)
                if placed:
                    break

    # --- PHASE 1: Wire network - connect all plants and clusters ---
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        return (Tool.COALPOWER, 60, 50)

    # For each active cluster, check if it's wired; if not, extend wire toward it
    for i in range(num_clusters):
        cx, cy = clusters[i]
        # Check if wire/plant is near this cluster
        r_w = 5
        x0 = max(0, cx - r_w); x1 = min(WORLD_W, cx + r_w + 1)
        y0 = max(0, cy - r_w); y1 = min(WORLD_H, cy + r_w + 1)
        if np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1]):
            continue
        # Not wired - find closest powered cell and extend toward cx, cy
        powered = wm | pm
        pow_ys, pow_xs = np.where(powered)
        if len(pow_xs) == 0:
            continue
        dists = np.abs(pow_xs - cx) + np.abs(pow_ys - cy)
        idx = int(np.argmin(dists))
        bx, by = int(pow_xs[idx]), int(pow_ys[idx])
        ddx = cx - bx
        ddy = cy - by
        if abs(ddx) >= abs(ddy):
            nx2, ny2 = bx + (1 if ddx > 0 else -1), by
        else:
            nx2, ny2 = bx, by + (1 if ddy > 0 else -1)
        if in_bounds(nx2, ny2) and not bool(pm[ny2, nx2]) and (bool(em[ny2, nx2]) or bool(wm[ny2, nx2])):
            return (Tool.WIRE, nx2, ny2)

    # Extend wire spines from each plant toward cluster edges
    for i in range(num_clusters):
        cx, cy = clusters[i]
        # Find plant nearest this cluster
        dists2 = np.abs(plant_xs - cx) + np.abs(plant_ys - cy)
        idx2 = int(np.argmin(dists2))
        px2, py2 = int(plant_xs[idx2]), int(plant_ys[idx2])

        # Wire vertical spine above and below plant
        extent = min(20, 6 + pop // 80)
        for wy in range(py2 - extent, py2 + extent + 1):
            if in_bounds(px2, wy) and bool(em[wy, px2]) and not bool(pm[wy, px2]):
                return (Tool.WIRE, px2, wy)

        # Wire horizontal spine left and right
        for wx2 in range(px2 - extent, px2 + extent + 1):
            if in_bounds(wx2, py2) and bool(em[py2, wx2]) and not bool(pm[py2, wx2]):
                return (Tool.WIRE, wx2, py2)

    # --- PHASE 2: Road grid ---
    # Build a grid of roads: horizontal roads every 4 rows, vertical every 4 cols
    # around each active cluster
    for i in range(num_clusters):
        cx, cy = clusters[i]
        extent = min(18, 6 + pop // 60 + i)

        # Find plant near cluster
        dists3 = np.abs(plant_xs - cx) + np.abs(plant_ys - cy)
        idx3 = int(np.argmin(dists3))
        px3, py3 = int(plant_xs[idx3]), int(plant_ys[idx3])

        # Horizontal roads every 4 rows
        for row_off in range(-extent, extent + 1, 4):
            hry = cy + row_off
            if not in_bounds(0, hry):
                continue
            # Check if any wire/plant is nearby (within 8 cols of cluster center)
            powered_row = False
            for hx in range(max(2, cx - extent), min(WORLD_W - 2, cx + extent)):
                if in_bounds(hx, hry) and (bool(wm[hry, hx]) or bool(pm[hry, hx])):
                    powered_row = True
                    break
            if not powered_row:
                continue
            for hx in range(max(2, cx - extent), min(WORLD_W - 2, cx + extent + 1)):
                if in_bounds(hx, hry) and bool(em[hry, hx]) and not bool(pm[hry, hx]):
                    return (Tool.ROAD, hx, hry)

        # Vertical roads every 4 cols
        for col_off in range(-extent, extent + 1, 4):
            hcx = cx + col_off
            if not in_bounds(hcx, 0):
                continue
            powered_col = False
            for hy in range(max(2, cy - extent), min(WORLD_H - 2, cy + extent)):
                if in_bounds(hcx, hy) and (bool(wm[hy, hcx]) or bool(pm[hy, hcx])):
                    powered_col = True
                    break
            if not powered_col:
                continue
            for hy in range(max(2, cy - extent), min(WORLD_H - 2, cy + extent + 1)):
                if in_bounds(hcx, hy) and bool(em[hy, hcx]) and not bool(pm[hy, hcx]):
                    return (Tool.ROAD, hcx, hy)

    # --- PHASE 3: Place zones near roads and power ---
    # Build neighbor masks efficiently
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            r0s = max(0, -dy); r1s = min(WORLD_H, WORLD_H - dy)
            c0s = max(0, -dx); c1s = min(WORLD_W, WORLD_W - dx)
            r0d = max(0, dy); r1d = min(WORLD_H, WORLD_H + dy)
            c0d = max(0, dx); c1d = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0d:r1d, c0d:c1d] |= rm[r0s:r1s, c0s:c1s]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            r0s = max(0, -dy); r1s = min(WORLD_H, WORLD_H - dy)
            c0s = max(0, -dx); c1s = min(WORLD_W, WORLD_W - dx)
            r0d = max(0, dy); r1d = min(WORLD_H, WORLD_H + dy)
            c0d = max(0, dx); c1d = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0d:r1d, c0d:c1d] |= wm[r0s:r1s, c0s:c1s]
            nbr_wire[r0d:r1d, c0d:c1d] |= pm[r0s:r1s, c0s:c1s]

    zone_tiles = resm | comm | indm
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by distance to nearest active cluster
        scores = np.full(len(cxs_arr), 999999.0)
        for i in range(num_clusters):
            cx2, cy2 = clusters[i]
            d = np.abs(cxs_arr - cx2) + np.abs(cys_arr - cy2)
            scores = np.minimum(scores, d.astype(float))
        order = np.argsort(scores)
        step_off = (step * 7) % max(len(order), 1)
        tool = pick_zone_tool()

        def zone_clear(zx, zy):
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    nr, nc = zy + dr, zx + dc
                    if not in_bounds(nc, nr):
                        return False
                    if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                        return False
            return True

        for i in range(min(len(order), 150)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 4: Extend wire network ---
    powered_mask = wm | pm
    pow_ys2, pow_xs2 = np.where(powered_mask)
    if len(pow_xs2) > 0:
        step_k = (step * 11) % max(len(pow_xs2), 1)
        for offset in range(min(len(pow_xs2), 30)):
            k = (step_k + offset * 7) % len(pow_xs2)
            wx2, wy2 = int(pow_xs2[k]), int(pow_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- PHASE 5: Extend roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k2 = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k2 + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 6: Services scaled to population ---
    if pop > 200:
        fire_spots = [(55, 35), (65, 35), (35, 55), (85, 55),
                      (35, 35), (85, 35), (55, 65), (65, 65),
                      (20, 50), (100, 50), (60, 15), (60, 85)]
        for fsx, fsy in fire_spots:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                x0 = max(0, fsx - 5); x1 = min(WORLD_W, fsx + 6)
                y0 = max(0, fsy - 5); y1 = min(WORLD_H, fsy + 6)
                if np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 500:
        police_spots = [(58, 38), (62, 62), (38, 38), (82, 62),
                        (38, 62), (82, 38), (20, 30), (100, 70)]
        for psx, psy in police_spots:
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                x0 = max(0, psx - 5); x1 = min(WORLD_W, psx + 6)
                y0 = max(0, psy - 5); y1 = min(WORLD_H, psy + 6)
                if np.any(wm[y0:y1, x0:x1]) or np.any(pm[y0:y1, x0:x1]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 800:
        stadium_spots = [(90, 50), (30, 50), (60, 20), (60, 80),
                         (15, 30), (105, 30), (15, 70), (105, 70)]
        for ssx, ssy in stadium_spots:
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    if pop > 1200 and funds > 8000:
        nuke_spots = [(100, 20), (20, 20), (100, 80), (20, 80),
                      (60, 50), (40, 50), (80, 20), (40, 80)]
        for nsx, nsy in nuke_spots:
            if in_bounds(nsx, nsy) and bool(em[nsy, nsx]):
                x0 = max(0, nsx - 6); x1 = min(WORLD_W, nsx + 7)
                y0 = max(0, nsy - 6); y1 = min(WORLD_H, nsy + 7)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nsx, nsy)

    # Seaport for commerce boost when large
    if pop > 2000 and funds > 5000:
        for spx, spy in [(110, 90), (10, 90), (110, 10), (10, 10)]:
            if in_bounds(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    return None

