    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))

    # Horizontal wire corridors at y=15,50,83
    for wr in [15, 50, 83]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wr))

    # Vertical wire corridors at x=15,58,102
    for wc in [15, 58, 102]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wc, y))

    # Roads flanking horizontal wire rows (above and below)
    for wr in [15, 50, 83]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wr - 1))
            actions.append((Tool.ROAD, x, wr + 1))

    # Roads flanking vertical wire cols (left and right)
    for wc in [15, 58, 102]:
        for y in range(1, 99):
