            actions.append((Tool.ROAD, wc + 1, y))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Wire corridors and road layout
    wire_rows = [15, 50, 83]
    wire_cols = [15, 58, 102]
    # Additional mid roads between corridors
    mid_roads_h = [32, 66]  # midpoints between wire rows
    mid_roads_v = [36, 80]  # midpoints between wire cols

    def pick_tool():
        # Target: 40% res, 30% com, 30% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # 9 neighborhood centers in 3x3 grid
    nh_positions = []
    for row in range(3):
        for col in range(3):
            cx = 36 + col * 24   # 36, 60, 84
            cy = 25 + row * 25   # 25, 50, 75
            nh_positions.append((cx, cy))

    # Add extra neighborhoods in corners and edges
    extra_hoods = [
        (8, 8), (58, 8), (110, 8),
        (8, 32), (110, 32),
        (8, 65), (110, 65),
        (8, 90), (58, 90), (110, 90),
    ]
    all_hoods = nh_positions + extra_hoods

    def get_active_hoods():
        if pop < 100:
            return [nh_positions[4]]  # center
        elif pop < 400:
            return nh_positions
        elif pop < 1000:
            return nh_positions + extra_hoods[:6]
        else:
            return all_hoods

    active_hoods = get_active_hoods()

    # PHASE: ensure power plants near active hoods
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place a coal plant nearby
            for r in range(1, 20):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = hx + dx, hy + dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)
                if placed:
                    break

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                cell = wm[wr, wx] | pm[wr, wx]
                if not bool(cell):
                    left = bool(wm[wr, wx-1] | pm[wr, wx-1]) if wx > 0 else False
                    right = bool(wm[wr, wx+1] | pm[wr, wx+1]) if wx < WORLD_W-1 else False
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                cell = wm[wy, wc] | pm[wy, wc]
                if not bool(cell):
                    up = bool(wm[wy-1, wc] | pm[wy-1, wc]) if wy > 0 else False
                    down = bool(wm[wy+1, wc] | pm[wy+1, wc]) if wy < WORLD_H-1 else False
                    if (up or down) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add mid horizontal roads between corridors
        for mry in mid_roads_h:
            if not (0 < mry < WORLD_H - 1):
                continue
            # Find a seed: connect from nearest vertical road
            for wc in wire_cols:
                for off in [-1, 1]:
                    sx = wc + off
                    if ib(sx, mry) and bool(rm[mry, sx]):
                        # extend left/right from this seed
                        for rx in range(1, WORLD_W - 1):
                            if bool(em[mry, rx]) and not bool(pm[mry, rx]) and bool(near_power[mry, rx]):
                                adj = (ib(rx-1, mry) and bool(rm[mry, rx-1])) or \
                                      (ib(rx+1, mry) and bool(rm[mry, rx+1]))
                                if adj:
                                    return (Tool.ROAD, rx, mry)

    elif phase == 5:
        # Add mid vertical roads between corridors
        for mcx in mid_roads_v:
            if not (0 < mcx < WORLD_W - 1):
                continue
            for wr in wire_rows:
                for off in [-1, 1]:
                    sy = wr + off
                    if ib(mcx, sy) and bool(rm[sy, mcx]):
                        for ry in range(1, WORLD_H - 1):
                            if bool(em[ry, mcx]) and not bool(pm[ry, mcx]) and bool(near_power[ry, mcx]):
                                adj = (ib(mcx, ry-1) and bool(rm[ry-1, mcx])) or \
                                      (ib(mcx, ry+1) and bool(rm[ry+1, mcx]))
                                if adj:
                                    return (Tool.ROAD, mcx, ry)

    elif phase == 6:
        # Add cross-roads in neighborhoods
        for (hx, hy) in active_hoods:
            # Add horizontal road through neighborhood
            for ry in [hy - 3, hy, hy + 3]:
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(max(1, hx - 10), min(WORLD_W - 1, hx + 11)):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]) and bool(near_power[ry, rx]):
                        adj = (ib(rx-1, ry) and bool(rm[ry, rx-1])) or \
                              (ib(rx+1, ry) and bool(rm[ry, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, ry)

    elif phase == 7:
        # Extend roads from existing roads near power
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % len(road_xs2)
            for offset in range(min(len(road_xs2), 150)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Add wires toward unpowered regions
        unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
        if unpowered_hoods:
            wire_ys_arr, wire_xs_arr = np.where(wm | pm)
            if len(wire_xs_arr) > 0:
                target_hx, target_hy = unpowered_hoods[0]
                dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
                dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
                for nwx, nwy in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nwx, nwy) and bool(em[nwy, nwx]) and not bool(pm[nwy, nwx]):
                        return (Tool.WIRE, nwx, nwy)

    else:  # phase == 9
        # Wire extension from existing wire into empty areas
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            step_k2 = (step * 13) % len(wire_xs3)
            for offset in range(min(len(wire_xs3), 80)):
                k = (step_k2 + offset * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Don't place zones on wire/plant corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step + pop to vary which candidate we pick each step
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- CIVIC SERVICES (placed reactively based on pop) ----
    if pop > 30:
        fire_grid = [
            (8, 8), (36, 8), (58, 8), (80, 8), (110, 8),
            (8, 32), (36, 32), (80, 32), (110, 32),
            (8, 50), (36, 50), (80, 50), (110, 50),
            (8, 66), (36, 66), (80, 66), (110, 66),
            (8, 90), (36, 90), (58, 90), (80, 90), (110, 90),
        ]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_grid = [
            (24, 24), (72, 24), (100, 24),
            (12, 50), (48, 50), (95, 50),
            (24, 72), (72, 72), (100, 72),
            (48, 10), (48, 90), (110, 50),
        ]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (42, 40), (78, 40), (42, 62), (78, 62),
            (10, 40), (108, 40), (10, 62), (108, 62),
            (58, 25), (58, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5, 5), (112, 5), (5, 93), (112, 93),
            (58, 5), (58, 93), (5, 50), (112, 50),
            (28, 5), (90, 5), (28, 93), (90, 93),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [
            (10, 93), (110, 93), (10, 5), (110, 5),
            (58, 5), (58, 93), (30, 93), (88, 93),
        ]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [
            (50, 5), (70, 5), (50, 90), (70, 90),
            (5, 40), (5, 55), (112, 40), (112, 55),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near zones for land value boost
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire toward unpowered hoods ----
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nwx, nwy in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nwx, nwy) and bool(em[nwy, nwx]) and not bool(pm[nwy, nwx]):
                    return (Tool.WIRE, nwx, nwy)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
