def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 45% res, 30% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    wire_rows = [15, 35, 50, 65, 85]
    wire_cols = [15, 35, 59, 83, 103]

    # Dense grid of neighborhoods across the map
    nh_positions = []
    for row in range(6):
        for col in range(8):
            cx = 7 + col * 15
            cy = 7 + row * 16
            cy = min(cy, 95)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 50:
            # Start central
            center = [(59, 50), (44, 50), (74, 50), (59, 35), (59, 65)]
            return center
        elif pop < 200:
            return nh_positions[12:36]
        elif pop < 600:
            return nh_positions[6:42]
        elif pop < 1500:
            return nh_positions[3:45]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                cell_empty = bool(em[nr, nc])
                cell_zone = bool(zone_tiles[nr, nc])
                if not cell_empty and not cell_zone:
                    return False
        return True

    # Phase-based infrastructure building
    phase = step % 12

    # Ensure power plants near active neighborhoods
    if step % 5 == 0:
        for (hx, hy) in active_hoods[:8]:
            x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
            y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(2, 25):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    powered_here = bool(wm[wr, rx]) or bool(pm[wr, rx])
                    if powered_here and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    powered_here = bool(wm[ry, wc]) or bool(pm[ry, wc])
                    if powered_here and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add cross-streets between wire cols at midpoints between wire rows
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire rows
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend road from existing road
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 150)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase in (8, 9, 10, 11):
        # Civic services based on population
        if pop > 20:
            fire_spots = [(5,5),(25,5),(50,5),(75,5),(105,5),
                          (5,25),(25,25),(50,25),(75,25),(105,25),
                          (5,45),(25,45),(75,45),(105,45),
                          (5,68),(25,68),(50,68),(75,68),(105,68),
                          (5,92),(25,92),(50,92),(75,92),(105,92)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 100:
            police_spots = [(18,12),(60,12),(100,12),
                            (18,38),(60,38),(100,38),
                            (18,62),(60,62),(100,62),
                            (18,88),(60,88),(100,88)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 500:
            stadium_spots = [(30,28),(88,28),(30,72),(88,72),(59,50)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [(5,50),(113,50),(59,5),(59,93),(5,5),(113,5),(5,93),(113,93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1200:
            seaports = [(5,93),(113,93),(5,5),(113,5)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2000:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(113,43)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (main closed-loop action) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders and wire/road corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # Parks for land value
    if pop > 50 and step % 3 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx,bwy),(bwx,bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants arranged in a cross pattern with wire spines."""
    actions = []
    # Place 4 power plants at cardinal positions
    plant_positions = [(30, 20), (90, 20), (30, 80), (90, 80)]
    for px, py in plant_positions:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking horizontal wire
        for dx in range(-4, 5):
            actions.append((Tool.ROAD, px + dx, py - 1))
            actions.append((Tool.ROAD, px + dx, py + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More balanced zone mix: 45% res, 30% com, 25% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 12 neighborhoods in a 4x3 grid covering the full map
    anchors = []
    for col_x in [15, 45, 75, 105]:
        for row_y in [20, 50, 80]:
            anchors.append((col_x, row_y))

    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 3
        if pop < 200:   return 5
        if pop < 400:   return 7
        if pop < 700:   return 9
        if pop < 1100:  return 11
        return 12

    n_active = num_active()
    active_anchors = anchors[:n_active]

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 10); y1 = min(WORLD_H, py + 11)
        x0 = max(0, px - 10); x1 = min(WORLD_W, px + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find empty spot near anchor for plant
            for r in range(0, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE GRID: horizontal + vertical spines at each anchor ----
    spine_half = min(18, 5 + pop // 15)
    for (px, py) in active_anchors:
        # Horizontal wire spine
        for dx in range(-spine_half, spine_half + 1):
            wx = px + dx
            if ib(wx, py) and bool(em[py, wx]) and not bool(pm[py, wx]):
                return (Tool.WIRE, wx, py)
        # Vertical wire spine
        for dy in range(-spine_half, spine_half + 1):
            wy = py + dy
            if ib(px, wy) and bool(em[wy, px]) and not bool(pm[wy, px]):
                return (Tool.WIRE, px, wy)

    # ---- CONNECT WIRES BETWEEN ANCHORS HORIZONTALLY ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            px1 = row_anchors[i][0]
            px2 = row_anchors[i + 1][0]
            for cx in range(px1 + 1, px2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- CONNECT WIRES BETWEEN ANCHOR ROWS VERTICALLY ----
    x_levels = sorted(set(px for (px, _) in active_anchors))
    for xl in x_levels:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            py1 = col_anchors[i][1]
            py2 = col_anchors[i + 1][1]
            for cy in range(py1 + 1, py2):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: roads flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        # Horizontal roads above and below wire
        for dx in range(-spine_half, spine_half + 1):
            wx = px + dx
            for ry in [py - 1, py + 1]:
                if ib(wx, ry) and bool(em[ry, wx]) and not bool(pm[ry, wx]):
                    return (Tool.ROAD, wx, ry)
        # Vertical roads left and right of vertical wire
        for dy in range(-spine_half, spine_half + 1):
            wy = py + dy
            for rx in [px - 1, px + 1]:
                if ib(rx, wy) and bool(em[wy, rx]) and not bool(pm[wy, rx]):
                    return (Tool.ROAD, rx, wy)

    # ---- HORIZONTAL ROADS connecting row anchors ----
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        if len(row_anchors) < 2:
            continue
        x_start = row_anchors[0][0] - spine_half
        x_end = row_anchors[-1][0] + spine_half
        for road_y in [yl - 2, yl + 2]:
            for cx in range(max(1, x_start), min(WORLD_W - 1, x_end + 1)):
                if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    return (Tool.ROAD, cx, road_y)

    # ---- VERTICAL ROADS connecting column anchors ----
    for xl in x_levels:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        if len(col_anchors) < 2:
            continue
        y_start = col_anchors[0][1] - spine_half
        y_end = col_anchors[-1][1] + spine_half
        for road_x in [xl - 2, xl + 2]:
            for cy in range(max(1, y_start), min(WORLD_H - 1, y_end + 1)):
                if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [
            (8, 10), (30, 10), (55, 10), (80, 10), (108, 10),
            (8, 35), (30, 35), (55, 35), (80, 35), (108, 35),
            (8, 60), (30, 60), (55, 60), (80, 60), (108, 60),
            (8, 88), (30, 88), (55, 88), (80, 88), (108, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (20, 6), (60, 6), (100, 6),
            (20, 44), (60, 44), (100, 44),
            (20, 74), (60, 74), (100, 74),
            (20, 94), (60, 94), (100, 94),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (40, 6), (80, 6), (20, 94), (60, 94), (100, 94),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near any existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID ----
    # Dense grid of neighborhood anchors across the full map
    all_hoods = []
    for hy in range(10, 95, 14):
        for hx in range(10, 115, 14):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 22
        if pop < 3000:  return 32
        if pop < 5000:  return 45
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    stride = max(1, len(all_hoods) // max(n_active, 1))
    active_hoods = all_hoods[::stride][:n_active]

    # ---- POWER MASKS ----
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # ---- ROAD NEIGHBOR MASK ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Place a coal plant near each active hood that lacks nearby power
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
            y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Find empty spot near hood
                for r in range(1, 14):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    # For each active hood, build wire spines connecting plant to hood
    spine = 16
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant for this hood
    x0p, x1p = max(0, hx - 14), min(WORLD_W, hx + 15)
    y0p, y1p = max(0, hy - 14), min(WORLD_H, hy + 15)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        px_l = int(plant_xs[0]) + x0p
        py_l = int(plant_ys[0]) + y0p

        # Wire vertically from plant toward hood
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        # Wire horizontally from plant toward hood
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical wire spine at hx
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    col_plant_r = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                   if ib(hx, r) and bool(pm[r, hx])]

    if col_plant_r and not col_wire:
        py2 = col_plant_r[0]
        for wy in [py2 - 1, py2 + 1]:
            if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                return (Tool.WIRE, hx, wy)

    if col_wire:
        min_wr = min(col_wire)
        max_wr = max(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    # Extend horizontal wire spine at hy
    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    row_plant_c = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                   if ib(c, hy) and bool(pm[hy, c])]

    if row_plant_c and not row_wire:
        px2 = row_plant_c[0]
        for wx in [px2 - 1, px2 + 1]:
            if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                return (Tool.WIRE, wx, hy)

    if row_wire:
        min_wc = min(row_wire)
        max_wc = max(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i: continue
            # Horizontal connection (same row, close y)
            if abs(hy1 - hy2) <= 3 and abs(hx1 - hx2) <= 20:
                mid_y = (hy1 + hy2) // 2
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                        if not bool(wm[mid_y, cx2]):
                            has_left = any(bool(wm[mid_y, c]) or bool(pm[mid_y, c])
                                           for c in range(max(0, cx2 - 4), cx2))
                            has_right = any(bool(wm[mid_y, c]) or bool(pm[mid_y, c])
                                            for c in range(cx2 + 1, min(WORLD_W, cx2 + 5)))
                            if has_left or has_right:
                                return (Tool.WIRE, cx2, mid_y)
            # Vertical connection (same col, close x)
            if abs(hx1 - hx2) <= 3 and abs(hy1 - hy2) <= 20:
                mid_x = (hx1 + hx2) // 2
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mid_x, cy2) and bool(em[cy2, mid_x]) and not bool(pm[cy2, mid_x]):
                        if not bool(wm[cy2, mid_x]):
                            has_top = any(bool(wm[r, mid_x]) or bool(pm[r, mid_x])
                                          for r in range(max(0, cy2 - 4), cy2))
                            has_bot = any(bool(wm[r, mid_x]) or bool(pm[r, mid_x])
                                          for r in range(cy2 + 1, min(WORLD_H, cy2 + 5)))
                            if has_top or has_bot:
                                return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 4
    for rx in [hx3 - 2, hx3 + 2]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::4]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 2, hy3 + 2]:
        if not ib(hx3, ry): continue
        cyc2 = (step + 2) % 4
        for wc2 in row_wire3[cyc2::4]:
            if ib(wc2, ry) and bool(em[ry, wc2]) and not bool(pm[ry, wc2]):
                return (Tool.ROAD, wc2, ry)

    # Flanking roads at ±1
    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy2 in range(-spine, spine + 1):
            ry2 = hy3 + dy2
            if not ib(rx, ry2): continue
            if not bool(em[ry2, rx]) or bool(pm[ry2, rx]): continue
            if bool(wm[ry2, hx3]) or bool(pm[ry2, hx3]):
                return (Tool.ROAD, rx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Clustering bonus
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride2 = max(1, len(zxs2) // 80)
                for i2 in range(0, len(zxs2), stride2):
                    d2 = (np.abs(cxs - zxs2[i2]).astype(float) +
                          np.abs(cys - zys2[i2]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.55 + zone_prox * 0.45
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(12, 95, 14)
                     for fx in range(12, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_grid = [(px2, py2) for py2 in range(14, 90, 16)
                       for px2 in range(14, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py3, px3 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px3, py3) and bool(em[py3, px3]):
                return (Tool.PARK, px3, py3)

    if pop > 400:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (55, 50), (25, 50), (95, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 30), (60, 70),
            (40, 10), (80, 10), (40, 90), (80, 90),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 8), min(WORLD_W, npx + 9)
            y0b, y1b = max(0, npy - 8), min(WORLD_H, npy + 9)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75),
                        (30, 5), (90, 5), (30, 95), (90, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 900:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 93), (5, 45), (113, 45),
                        (50, 50), (20, 30), (100, 30)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- PHASE 8: NUCLEAR UPGRADE for mature cities ----
    if pop > 1500 and step % 3 == 0 and funds > 7000:
        nuc_spots = [
            (20, 20), (100, 20), (20, 80), (100, 80),
            (40, 35), (80, 35), (40, 65), (80, 65),
            (60, 20), (60, 80), (20, 50), (100, 50),
            (12, 12), (108, 12), (12, 88), (108, 88),
            (50, 12), (70, 12), (50, 88), (70, 88),
        ]
        for nx2, ny2 in nuc_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- FALLBACK: extend wire from plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % max(len(pxs), 1)
        for offset in range(min(len(pxs), 80)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: extend wire from existing wire ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % max(len(wxs_arr), 1)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant for uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Ambitious multi-neighborhood city builder
# Strategy: 4 coal plants spread across map, dense road grid, balanced R/C/I mix
# Closed-loop: reacts to population, powered zones, and actual tile state

def init(obs, state):
    """Bootstrap: place 4 power plants + initial wire/road spines."""
    actions = []
    # 4 plants at quadrant centers
    plants = [(30, 25), (90, 25), (30, 75), (90, 75)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Short wire cross from each plant
        for d in range(1, 5):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px - d, py))
            actions.append((Tool.WIRE, px, py + d))
            actions.append((Tool.WIRE, px, py - d))
    # Central connecting wire along row 50
    for x in range(25, 96, 2):
        actions.append((Tool.WIRE, x, 50))
    # Central connecting wire along col 60
    for y in range(20, 81, 2):
        actions.append((Tool.WIRE, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))
    plant_count = int(np.sum(pm))

    # ── PHASE 0: ENSURE ENOUGH POWER PLANTS ──
    # Target: 1 plant per ~50 zones, minimum 4
    target_plants = max(4, total_zones // 40)
    if plant_count < target_plants:
        # Candidate plant locations spread across map
        plant_candidates = [
            (30, 25), (90, 25), (30, 75), (90, 75),
            (60, 15), (60, 85), (15, 50), (105, 50),
            (45, 40), (75, 40), (45, 60), (75, 60),
            (20, 15), (100, 15), (20, 85), (100, 85),
            (60, 50), (35, 50), (85, 50),
        ]
        for (px, py) in plant_candidates:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ── PHASE 1: WIRE BACKBONE ──
    # Build a grid of wires connecting all plants
    # Horizontal wires at rows 25, 50, 75
    # Vertical wires at cols 15, 30, 45, 60, 75, 90, 105
    wire_rows = [10, 25, 40, 50, 60, 75, 90]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 110]

    # Extend horizontal wire spines
    for wr in wire_rows:
        for wx in range(5, WORLD_W - 5):
            if ib(wx, wr) and not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                # Only lay wire if adjacent cell has wire or plant
                has_neighbor = (
                    (ib(wx-1, wr) and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))) or
                    (ib(wx+1, wr) and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                )
                if has_neighbor and bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)

    # Extend vertical wire spines
    for wc in wire_cols:
        for wy in range(5, WORLD_H - 5):
            if ib(wc, wy) and not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                has_neighbor = (
                    (ib(wc, wy-1) and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or
                    (ib(wc, wy+1) and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                )
                if has_neighbor and bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)

    # ── PHASE 2: ROAD NETWORK ──
    # Build roads 1 tile away from wire spines (parallel roads)
    # Road rows offset from wire rows
    road_h_rows = []
    for wr in wire_rows:
        for off in [-2, 2]:
            rr = wr + off
            if 3 <= rr < WORLD_H - 3:
                road_h_rows.append(rr)

    road_v_cols = []
    for wc in wire_cols:
        for off in [-2, 2]:
            rc = wc + off
            if 3 <= rc < WORLD_W - 3:
                road_v_cols.append(rc)

    # Build horizontal roads
    for rr in road_h_rows:
        # Only build road segments near wire coverage
        for rx in range(4, WORLD_W - 4):
            if ib(rx, rr) and bool(em[rr, rx]) and not bool(pm[rr, rx]):
                # Check wire within 3 rows
                near_wire = False
                for ddy in range(-3, 4):
                    ny2 = rr + ddy
                    if ib(rx, ny2) and (bool(wm[ny2, rx]) or bool(pm[ny2, rx])):
                        near_wire = True
                        break
                if near_wire:
                    # Check road continuity
                    has_road_nbr = (
                        (ib(rx-1, rr) and bool(rm[rr, rx-1])) or
                        (ib(rx+1, rr) and bool(rm[rr, rx+1]))
                    )
                    if has_road_nbr or (rx == 4):
                        return (Tool.ROAD, rx, rr)

    # Build vertical roads
    for rc in road_v_cols:
        for ry in range(4, WORLD_H - 4):
            if ib(rc, ry) and bool(em[ry, rc]) and not bool(pm[ry, rc]):
                near_wire = False
                for ddx in range(-3, 4):
                    nx2 = rc + ddx
                    if ib(nx2, ry) and (bool(wm[ry, nx2]) or bool(pm[ry, nx2])):
                        near_wire = True
                        break
                if near_wire:
                    has_road_nbr = (
                        (ib(rc, ry-1) and bool(rm[ry-1, rc])) or
                        (ib(rc, ry+1) and bool(rm[ry+1, rc]))
                    )
                    if has_road_nbr or (ry == 4):
                        return (Tool.ROAD, rc, ry)

    # ── PHASE 3: ZONE PLACEMENT ──
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr2 = res_count / t
        # Target: 45% res, 30% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # Build proximity masks efficiently
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-2, 3):
        for ddx in range(-2, 3):
            sy0 = max(0, -ddy); sy1 = min(WORLD_H, WORLD_H - ddy)
            sx0 = max(0, -ddx); sx1 = min(WORLD_W, WORLD_W - ddx)
            dy0 = max(0, ddy); dy1 = min(WORLD_H, WORLD_H + ddy)
            dx0 = max(0, ddx); dx1 = min(WORLD_W, WORLD_W + ddx)
            nbr_road[dy0:dy1, dx0:dx1] |= rm[sy0:sy1, sx0:sx1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-3, 4):
        for ddx in range(-3, 4):
            sy0 = max(0, -ddy); sy1 = min(WORLD_H, WORLD_H - ddy)
            sx0 = max(0, -ddx); sx1 = min(WORLD_W, WORLD_W - ddx)
            dy0 = max(0, ddy); dy1 = min(WORLD_H, WORLD_H + ddy)
            dx0 = max(0, ddx); dx1 = min(WORLD_W, WORLD_W + ddx)
            nbr_power[dy0:dy1, dx0:dx1] |= wm[sy0:sy1, sx0:sx1]
            nbr_power[dy0:dy1, dx0:dx1] |= pm[sy0:sy1, sx0:sx1]

    cand_mask = em & nbr_road & nbr_power
    # Border margin
    cand_mask[:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, :3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer positions equidistant from roads AND power
        # Use a cycling offset for variety each step
        offset = (step * 7) % max(len(cxs), 1)
        tried = 0
        for i in range(min(len(cxs), 300)):
            k = (offset + i) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            tried += 1
            if tried > 100:
                break

    # ── PHASE 4: FILL ROAD GAPS ──
    # Extend roads from existing road ends
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11 + 3) % len(road_xs)
        for off in range(min(len(road_xs), 60)):
            k = (sk + off * 3) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2])
                        and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ── PHASE 5: FILL WIRE GAPS ──
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        sk2 = (step * 13 + 5) % len(wire_xs)
        for off in range(min(len(wire_xs), 40)):
            k = (sk2 + off * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ── PHASE 6: CIVIC SERVICES (closed-loop: based on actual pop) ──
    if pop > 100:
        fire_grid = [(x, y) for x in range(20, 110, 25) for y in range(20, 90, 25)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_grid = [(x, y) for x in range(22, 108, 28) for y in range(22, 88, 28)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        for (sx, sy) in [(40, 45), (80, 45), (40, 60), (80, 60), (60, 35), (60, 65)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for (sx, sy) in [(15, 80), (105, 80), (15, 20), (105, 20)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for (sx, sy) in [(55, 5), (55, 92), (5, 48), (112, 48)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ── PHASE 7: PARKS for land value ──
    if pop > 200 and step % 5 == 0:
        pk_cands = np.where(em & nbr_road & nbr_power)
        if len(pk_cands[0]) > 0:
            idx = (step * 23) % len(pk_cands[0])
            py2, px2 = int(pk_cands[0][idx]), int(pk_cands[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ── PHASE 8: ADD MORE COAL PLANTS aggressively ──
    if pop > 500 and plant_count < 8:
        extra_plants = [
            (50, 15), (70, 15), (50, 85), (70, 85),
            (15, 35), (105, 35), (15, 65), (105, 65),
            (40, 50), (80, 50), (60, 30), (60, 70),
        ]
        for (px, py) in extra_plants:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 2000 and plant_count < 12:
        more_plants = [
            (20, 20), (100, 20), (20, 80), (100, 80),
            (60, 10), (60, 90), (10, 50), (110, 50),
        ]
        for (px, py) in more_plants:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    return None

# Ambitious closed-loop city builder combining best of both parents
# Key improvements:
# - Denser hood grid covering full map (8x7=56 hoods)
# - Multiple plants per hood cluster
# - Reactive wire/road extension from existing infrastructure
# - Smart zone placement with balanced R/C/I
# - Progressive civic services (fire, police, stadium, nuclear, airport)

def init(obs, state):
    """Bootstrap: 4 coal plants spread across map with wire+road cross."""
    actions = []
    starts = [(20, 30), (60, 30), (100, 30), (20, 70), (60, 70), (100, 70)]
    for cx, cy in starts[:4]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dy in range(-3, 4):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Full-map hood grid: 8 cols x 7 rows = 56 neighborhoods
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [10, 22, 34, 50, 62, 74, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 350:   return 14
        if pop < 700:   return 22
        if pop < 1500:  return 32
        if pop < 3000:  return 44
        if pop < 6000:  return 52
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    spine_range = 12

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from each active hood ----
    # Rotate hoods each step so we make progress on all of them
    hood_offset = step % max(len(active_hoods), 1)
    rotated_hoods = active_hoods[hood_offset:] + active_hoods[:hood_offset]

    for idx_h, (hx, hy) in enumerate(rotated_hoods):
        # Only process a subset each step for efficiency
        if idx_h >= max(len(active_hoods) // 3 + 2, 6):
            break

        # Find plant near this hood
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        sub_pm = pm[y0:y1, x0:x1]
        plant_locs = list(zip(*np.where(sub_pm)))
        if not plant_locs:
            continue
        pr, pc = plant_locs[0]
        px_abs = x0 + pc
        py_abs = y0 + pr

        # Vertical wire spine at hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy) or bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            # Must connect to existing wire/plant
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap if column empty
            col_has = any(bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1) if ib(hx, hy + d2))
            if not col_has:
                for d2 in [-1, 1]:
                    ay2 = py_abs + d2
                    if ib(hx, ay2) and bool(em[ay2, hx]) and not bool(pm[ay2, hx]):
                        return (Tool.WIRE, hx, ay2)

        # Horizontal wire spine at hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy) or bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Horizontal neighbors
        for gap in [15, 25]:
            hx2, hy2 = hx1 + gap, hy1
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        # Vertical neighbors
        for gap in [12, 15]:
            hx2, hy2 = hx1, hy1 + gap
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    road_offset = (step * 3) % max(len(active_hoods), 1)
    rotated_hoods2 = active_hoods[road_offset:] + active_hoods[:road_offset]

    for idx_h, (hx, hy) in enumerate(rotated_hoods2):
        if idx_h >= max(len(active_hoods) // 3 + 2, 6):
            break

        # Roads flanking vertical wire spine at hx
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if ib(hx, ry) and (bool(wm[ry, hx]) or bool(pm[ry, hx])):
                        # Check road connectivity
                        has_adj_road = False
                        for ady in [-1, 1]:
                            if ib(rx, ry + ady) and bool(rm[ry + ady, rx]):
                                has_adj_road = True
                                break
                        if has_adj_road or abs(dy) <= 1:
                            return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal wire spine at hy
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if ib(rcx, hy) and (bool(wm[hy, rcx]) or bool(pm[hy, rcx])):
                        has_adj_road = False
                        for adx in [-1, 1]:
                            if ib(rcx + adx, ry2) and bool(rm[ry2, rcx + adx]):
                                has_adj_road = True
                                break
                        if has_adj_road or abs(dx) <= 1:
                            return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road proximity mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power proximity mask (within 6 tiles of wire or plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset_z = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset_z + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (8, 10), (30, 10), (52, 10), (74, 10), (96, 10), (115, 10),
            (8, 28), (30, 28), (52, 28), (74, 28), (96, 28), (115, 28),
            (8, 46), (30, 46), (52, 46), (74, 46), (96, 46), (115, 46),
            (8, 64), (30, 64), (52, 64), (74, 64), (96, 64), (115, 64),
            (8, 82), (30, 82), (52, 82), (74, 82), (96, 82), (115, 82),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [
            (18, 18), (48, 18), (78, 18), (108, 18),
            (18, 40), (48, 40), (78, 40), (108, 40),
            (18, 58), (48, 58), (78, 58), (108, 58),
            (18, 76), (48, 76), (78, 76), (108, 76),
            (18, 92), (48, 92), (78, 92), (108, 92),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 900:
        stadiums = [
            (30, 30), (80, 30), (30, 60), (80, 60),
            (55, 15), (55, 80), (5, 50), (110, 50),
            (30, 85), (80, 85),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 94), (90, 94),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2800:
        seaports = [(8, 92), (112, 92), (8, 6), (112, 6), (60, 94), (60, 4)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(48, 5), (72, 5), (48, 93), (72, 93), (4, 45), (114, 45)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 150 and step % 3 == 0:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_arr2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_arr2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire cross + roads."""
    actions = []
