def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        rr = res_count / tz
        # Target: 25% industrial, 30% commercial, 45% residential
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Distributed power plant grid ----
    # Cover map with plants every 20 cols, 18 rows
    plant_positions = []
    for py in range(10, 95, 18):
        for px in range(10, 115, 20):
            plant_positions.append((px, py))

    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 9), min(WORLD_W, ppx + 10)
        y0, y1 = max(0, ppy - 9), min(WORLD_H, ppy + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network (horizontal spines every 18 rows, vertical every 20 cols) ----
    wire_rows = list(range(10, 95, 18))
    wire_cols = list(range(10, 115, 20))

    # Build horizontal wires across full width
    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            if ib(60, wr) and em[wr, 60]:
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and em[wr, left-1] and not rm[wr, left-1]:
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and em[wr, right+1] and not rm[wr, right+1]:
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if em[wr, x] and not pm[wr, x] and not rm[wr, x]:
                return (Tool.WIRE, x, wr)

    # Build vertical wires full height
    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and em[top-1, wc] and not rm[top-1, wc]:
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and em[bot+1, wc] and not rm[bot+1, wc]:
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if em[y, wc] and not pm[y, wc] and not rm[y, wc]:
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Dense road grid ----
    # Roads at wire_row +/- 4 and wire_col +/- 4 (zones fit between)
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 4)
        road_rows.append(wr + 4)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 4)
        road_cols.append(wc + 4)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    # Build horizontal roads full width
    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and em[rr, left-1] and not pm[rr, left-1]:
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and em[rr, right+1] and not pm[rr, right+1]:
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if em[rr, x] and not pm[rr, x]:
                return (Tool.ROAD, x, rr)

    # Build vertical roads full height
    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and em[top-1, rc] and not pm[top-1, rc]:
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and em[bot+1, rc] and not pm[bot+1, rc]:
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if em[y, rc] and not pm[y, rc]:
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement (closed-loop: densify near existing zones first) ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Don't place zones on wire rows or road rows
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        if total_zones > 0:
            # Prefer locations near existing zones (densification) and roads
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                stride = max(1, len(zxs2) // 80)
                zone_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(zxs2), stride):
                    d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
                road_ys, road_xs = np.where(rm)
                if len(road_xs) > 0:
                    rd_stride = max(1, len(road_xs) // 80)
                    road_dist = np.full(len(cxs_arr), 9999.0)
                    for i in range(0, len(road_xs), rd_stride):
                        d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                        road_dist = np.minimum(road_dist, d)
                    score = zone_dist * 0.5 + road_dist * 0.5
                else:
                    score = zone_dist
            else:
                score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)
        else:
            # First zones: start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        # Small offset to avoid always picking the same spot
        off = (step * 3 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services (closed-loop based on pop) ----
    if pop > 100:
        fire_spots = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_spots = [(px2, py2) for py2 in range(12, 92, 14) for px2 in range(12, 112, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_spots = [(pkx, pky) for pky in range(15, 90, 9) for pkx in range(15, 110, 13)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 800:
        stadium_spots = [(sx, sy) for sy in range(18, 88, 22) for sx in range(18, 108, 28)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        airport_spots = [
            (58, 7), (62, 7), (58, 92), (62, 92),
            (7, 48), (112, 48), (7, 52), (112, 52),
            (28, 7), (92, 7), (28, 92), (92, 92),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_spots = [
            (7, 50), (112, 50), (60, 4), (60, 95),
            (24, 4), (96, 4), (24, 95), (96, 95),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 3000:
        # Extra nuclear plants for large cities
        nuke_spots = [(55, 50), (65, 50), (55, 25), (65, 25), (55, 75), (65, 75)]
        for nx, ny in nuke_spots:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    # ---- Fallback: wire extension toward unpowered zones ----
    power_src2 = wm | pm
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src2)
        if dy == -1: shifted[:-1,:] = power_src2[1:,:]
        elif dy == 1: shifted[1:,:] = power_src2[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src2[:,1:]
        elif dx == 1: shifted[:,1:] = power_src2[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False; wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False; wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0:
        unpowered = zone_tiles & ~near_power
        uzys, uzxs = np.where(unpowered)
        if len(uzxs) > 0:
            best_d = 1e9; best_k = 0
            stride = max(1, len(uzxs) // 30)
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - uzxs[j]) + abs(cy - uzys[j]) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
        else:
            k = step % len(wxs_c)
            return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- Fallback: road near power ----
    pwr_ys2, pwr_xs2 = np.where(pm)
    if len(pwr_xs2) > 0:
        for i in range(len(pwr_xs2)):
            k = (step * 11 + i) % len(pwr_xs2)
            px2, py2 = int(pwr_xs2[k]), int(pwr_ys2[k])
            for dx2, dy2 in [(4,0),(-4,0),(0,4),(0,-4),(2,0),(-2,0),(0,2),(0,-2)]:
                nx2, ny2 = px2+dx2, py2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not pm[ny2, nx2]:
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + seed roads + zones"""
    actions = []
    # Central power plant at (60, 50)
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines from center
    for x in range(50, 71):
        actions.append((Tool.WIRE, x, 50))
    for y in range(40, 61):
        actions.append((Tool.WIRE, 60, y))
    # Seed horizontal roads
    for x in range(45, 76):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    # Seed vertical roads
    for y in range(45, 56):
        actions.append((Tool.ROAD, 55, y))
        actions.append((Tool.ROAD, 65, y))
    # Seed a few zones near the center
    actions.append((Tool.RESIDENTIAL, 58, 47))
    actions.append((Tool.INDUSTRIAL, 62, 47))
    actions.append((Tool.COMMERCIAL, 58, 53))
    actions.append((Tool.RESIDENTIAL, 62, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # Track phase in state for sequencing
    if 'phase' not in state:
        state['phase'] = 0
    if 'next_plant_idx' not in state:
        state['next_plant_idx'] = 0
    if 'next_wire_spine_h' not in state:
        state['next_wire_spine_h'] = 0
    if 'next_wire_spine_v' not in state:
        state['next_wire_spine_v'] = 0
    if 'next_road_h' not in state:
        state['next_road_h'] = 0
    if 'next_road_v' not in state:
        state['next_road_v'] = 0

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- Grid layout parameters ----
    # Plants at every 20 cols, 18 rows
    # Wires on rows/cols with plants
    # Roads offset by 7 from wire rows
    plant_row_spacing = 18
    plant_col_spacing = 20
    plant_rows = list(range(10, WORLD_H - 5, plant_row_spacing))  # ~5 rows
    plant_cols = list(range(10, WORLD_W - 5, plant_col_spacing))  # ~6 cols

    # ---- PHASE 1: Ensure power plants ----
    # Place a plant at each grid intersection if not already powered nearby
    plant_positions = [(px, py) for py in plant_rows for px in plant_cols]
    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        # Check if there's already a plant within 8 tiles
        x0, x1 = max(0, ppx - 8), min(WORLD_W, ppx + 9)
        y0, y1 = max(0, ppy - 8), min(WORLD_H, ppy + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire horizontal spines (along plant rows) ----
    for wr in plant_rows:
        if not ib(0, wr):
            continue
        # Find existing wire/plant in this row
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            # Start from center
            cx = 60
            if ib(cx, wr) and bool(em[wr, cx]):
                return (Tool.WIRE, cx, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        # Extend left
        if left > 2 and bool(em[wr, left - 1]) and not bool(pm[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        # Extend right
        if right < WORLD_W - 3 and bool(em[wr, right + 1]) and not bool(pm[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)
        # Fill gaps
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    # ---- PHASE 2b: Wire vertical spines (along plant cols) ----
    for wc in plant_cols:
        if not ib(wc, 0):
            continue
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            cy = 50
            if ib(wc, cy) and bool(em[cy, wc]):
                return (Tool.WIRE, wc, cy)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top - 1, wc]) and not bool(pm[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 3 and bool(em[bot + 1, wc]) and not bool(pm[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads placed 7 tiles offset from wire rows (above and below)
    # and 7 tiles offset from wire cols (left and right)
    road_rows = []
    for wr in plant_rows:
        r1 = wr - 7
        r2 = wr + 7
        if 5 < r1 < WORLD_H - 5:
            road_rows.append(r1)
        if 5 < r2 < WORLD_H - 5:
            road_rows.append(r2)
    road_cols = []
    for wc in plant_cols:
        c1 = wc - 7
        c2 = wc + 7
        if 5 < c1 < WORLD_W - 5:
            road_cols.append(c1)
        if 5 < c2 < WORLD_W - 5:
            road_cols.append(c2)
    road_rows = sorted(set(road_rows))
    road_cols = sorted(set(road_cols))

    # Build horizontal roads
    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            cx = 60
            if ib(cx, rr) and bool(em[rr, cx]) and not bool(pm[rr, cx]):
                return (Tool.ROAD, cx, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 4 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]) and not bool(wm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]) and not bool(wm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]) and not bool(wm[rr, x]):
                return (Tool.ROAD, x, rr)

    # Build vertical roads
    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            cy = 50
            if ib(rc, cy) and bool(em[cy, rc]) and not bool(pm[cy, rc]):
                return (Tool.ROAD, rc, cy)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 4 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]) and not bool(wm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]) and not bool(wm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]) and not bool(wm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    # Find candidate cells: empty, near road, near power
    zone_cand = em & near_road & near_power
    # Buffer from edges
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Don't place on wire rows or plant cols
    for wr in plant_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for wc in plant_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False

    def zone_clear(zx, zy):
        # Check 3x3 area around center is clear of obstructions
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                tile = tm[nr, nc]
                # Allow empty or existing zone tiles
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        # Score candidates: prefer close to existing roads and zones
        if total_zones > 0:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                stride_z = max(1, len(zxs2) // 80)
                zone_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(zxs2), stride_z):
                    d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                    zone_dist = np.minimum(zone_dist, d)
            else:
                zone_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)
        else:
            zone_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
            score = zone_dist * 0.3 + road_dist * 0.7
        else:
            score = zone_dist

        order = np.argsort(score)
        # Offset to try different candidates each step for variety
        off = (step * 3 + pop * 2) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on pop ----
    if pop > 100:
        fire_spots = [(fx, fy) for fy in range(10, 96, 10) for fx in range(10, 112, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_spots = [(px2, py2) for py2 in range(12, 92, 14) for px2 in range(12, 110, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_spots = [(pkx, pky) for pky in range(14, 90, 8) for pkx in range(14, 108, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 800:
        stadium_spots = [(sx, sy) for sy in range(18, 90, 22) for sx in range(18, 105, 28)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        airport_spots = [
            (55, 8), (65, 8), (55, 91), (65, 91),
            (8, 44), (111, 44), (8, 56), (111, 56),
        ]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_spots = [
            (8, 50), (111, 50), (60, 5), (60, 94),
        ]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend wire toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy2 == -1:
            shifted[:-1, :] = power_src[1:, :]
        elif dy2 == 1:
            shifted[1:, :] = power_src[:-1, :]
        elif dx2 == -1:
            shifted[:, :-1] = power_src[:, 1:]
        elif dx2 == 1:
            shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0:
        if len(uzxs) > 0:
            best_d = 1e9
            best_k = 0
            stride = max(1, len(uzxs) // 20)
            for i in range(len(wxs_c)):
                cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx2 - uzxs[j]) + abs(cy2 - uzys[j]) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
        else:
            k = step % len(wxs_c)
            return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- Fallback: road near existing roads ----
    pwr_ys2, pwr_xs2 = np.where(pm)
    if len(pwr_xs2) > 0:
        for i in range(len(pwr_xs2)):
            k = (step * 7 + i) % len(pwr_xs2)
            px3, py3 = int(pwr_xs2[k]), int(pwr_ys2[k])
            for dx3, dy3 in [(6, 0), (-6, 0), (0, 6), (0, -6), (4, 0), (-4, 0), (0, 4), (0, -4)]:
                nx3, ny3 = px3 + dx3, py3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    return None

# Compact, dense city builder with systematic infrastructure
# Strategy: Build a grid of power plants, connect with wires, add roads, zone densely

def init(obs, state):
    """Bootstrap: 5 coal plants with wire connections across the map."""
    actions = []
    # Place coal plants in a cross pattern
    plants = [(20, 20), (100, 20), (60, 50), (20, 80), (100, 80)]
    for (px, py) in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire in 4 directions
        for d in range(1, 4):
            for dx, dy in [(d,0),(-d,0),(0,d),(0,-d)]:
                nx, ny = px+dx, py+dy
                if 0<=nx<WORLD_W and 0<=ny<WORLD_H:
                    actions.append((Tool.WIRE, nx, ny))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Store phase state in state dict
    if 'phase' not in state:
        state['phase'] = 0
        state['plant_idx'] = 0
        state['wire_queue'] = []
        state['road_queue'] = []
        state['zone_cursor'] = 0

    # Build a dense grid of neighborhoods
    # 8 cols x 7 rows = 56 neighborhoods, 14-tile spacing
    nh_cols = list(range(8, 120, 14))  # 8,22,36,50,64,78,92,106 -> 8 cols
    nh_rows = list(range(8, 100, 14))  # 8,22,36,50,64,78,92 -> 7 rows
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Scale number of active hoods with population
    def num_active():
        if pop < 50:    return 8
        if pop < 200:   return 16
        if pop < 500:   return 24
        if pop < 1000:  return 32
        if pop < 2000:  return 42
        if pop < 4000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick evenly spaced hoods
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # --- PHASE 1: ENSURE POWER PLANTS near each active hood ---
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx-9), min(WORLD_W, hx+10)
        y0, y1 = max(0, hy-9), min(WORLD_H, hy+10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            nearby = int(np.sum(zone_tiles[y0:y1, x0:x1]))
            use_nuclear = nearby > 15 and funds > 8000 and pop > 500
            tool_p = Tool.NUCLEARPOWER if use_nuclear else Tool.COALPOWER
            # Find nearest empty spot
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (tool_p, nx, ny)

    # --- PHASE 2: WIRE SPINES connecting all active hoods ---
    # Build vertical wire spine at each hood's x, horizontal at each hood's y
    # Also connect between neighboring hoods
    for (hx, hy) in active_hoods:
        spine_r = 6
        # Vertical spine at hx
        for dy in range(-spine_r, spine_r+1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Only place if adjacent to existing wire/plant
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal spine at hy
        for dx in range(-spine_r, spine_r+1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # --- PHASE 3: CONNECT WIRE between neighboring hoods ---
    # Build wire grid - horizontal connections
    row_to_hoods = {}
    col_to_hoods = {}
    for (hx, hy) in active_hoods:
        row_to_hoods.setdefault(hy, []).append(hx)
        col_to_hoods.setdefault(hx, []).append(hy)

    for hy, hxs in row_to_hoods.items():
        hxs_s = sorted(hxs)
        for i in range(len(hxs_s)-1):
            hx1, hx2 = hxs_s[i], hxs_s[i+1]
            for cx in range(hx1+1, hx2):
                if not ib(cx, hy): continue
                if bool(wm[hy, cx]) or bool(pm[hy, cx]): continue
                if not bool(em[hy, cx]): continue
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, cx, hy)

    for hx, hys in col_to_hoods.items():
        hys_s = sorted(hys)
        for i in range(len(hys_s)-1):
            hy1, hy2 = hys_s[i], hys_s[i+1]
            for cy in range(hy1+1, hy2):
                if not ib(hx, cy): continue
                if bool(wm[cy, hx]) or bool(pm[cy, hx]): continue
                if not bool(em[cy, hx]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, cy)

    # --- PHASE 4: ROADS flanking wire spines ---
    spine_r = 6
    for (hx, hy) in active_hoods:
        # Roads at hx±1 (flanking vertical spine)
        for rx in [hx-1, hx+1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r+1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]): continue
                if bool(pm[ry, rx]): continue
                # Place only if there's a wire nearby to power
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    # Check neighbors for existing road (connectivity)
                    for adj in [-1, 1]:
                        ar = ry + adj
                        if ib(rx, ar) and bool(rm[ar, rx]):
                            return (Tool.ROAD, rx, ry)
        # Roads at hy±1 (flanking horizontal spine)
        for ry2 in [hy-1, hy+1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r+1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]): continue
                if bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    for adj in [-1, 1]:
                        ac = rcx + adj
                        if ib(ac, ry2) and bool(rm[ry2, ac]):
                            return (Tool.ROAD, rcx, ry2)

    # --- PHASE 5: ZONE PLACEMENT with better balance ---
    # Target: 50% RES, 25% COM, 25% IND
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # rr = res_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0,-dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0,-dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0  = max(0, dy2); r1  = min(WORLD_H, WORLD_H+dy2)
            c0  = max(0, dx2); c1  = min(WORLD_W, WORLD_W+dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (wire or plant within 4 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0,-dy2); sr1 = min(WORLD_H, WORLD_H-dy2)
            sc0 = max(0,-dx2); sc1 = min(WORLD_W, WORLD_W-dx2)
            r0  = max(0, dy2); r1  = min(WORLD_H, WORLD_H+dy2)
            c0  = max(0, dx2); c1  = min(WORLD_W, WORLD_W+dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False; cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False; cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES ---
    if pop > 30:
        fire_grid = [(x, y) for y in range(15, 100, 20) for x in range(10, 120, 20)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_grid = [(x, y) for y in range(25, 100, 25) for x in range(15, 120, 25)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [(30,30),(90,30),(30,70),(90,70),(60,50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        seaports = [(5,90),(115,90),(5,5),(115,5),(60,5),(60,95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(45,5),(75,5),(45,93),(75,93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- PHASE 8: PARKS ---
    if pop > 100 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 37) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # --- FALLBACK: extend wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- FALLBACK: new plant at unpowered active hood ---
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Ambitious closed-loop city builder v2
# Strategy: Dense grid of neighborhoods across the full map
# Better wire connectivity, more aggressive zone placement, smarter civic services
# Key changes: more neighborhoods (8x6=48), tighter spacing (14 apart),
# explicit wire backbone connecting all plants, faster zone placement

def init(obs, state):
    """Bootstrap: central coal plant + cross of wires + roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for d in range(1, 6):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Roads flanking the vertical wire
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 8 cols x 6 rows = 48 neighborhoods ----
    # Spacing 14 horizontally, 16 vertically - tighter than parent
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 24, 40, 56, 72, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 700:   return 14
        if pop < 1500:  return 22
        if pop < 3000:  return 32
        if pop < 6000:  return 40
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Select hoods distributed across the map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each neighborhood needs a power plant within 10 tiles
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant near hood center
            for r in range(15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE BACKBONE - connect all plants ----
    # Build horizontal wire rows at each nh_row level
    # and vertical wire columns at each nh_col level
    for (hx, hy) in active_hoods:
        if step % max(len(active_hoods), 1) != all_hoods.index((hx, hy)) % max(len(active_hoods), 1):
            continue
        # Extend wire vertically from this hood
        for dy in range(-7, 8):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Check if adjacent tile has wire/plant
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Extend wire horizontally
        for dx in range(-7, 8):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT NEIGHBORHOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            # Horizontal neighbors (same row, adjacent col)
            if hy1 == hy2 and hx2 == hx1 + 14:
                mid_y = hy1
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Vertical neighbors (same col, adjacent row)
            if hx1 == hx2 and hy2 == hy1 + 16:
                mid_x = hx1
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    spine_range = 7
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods), 2) not in range(max(1, len(active_hoods) // 3)):
            continue
        # Roads flanking vertical spine
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 45% RES, 30% COM, 25% IND
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 2 tiles - tighter requirement)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers - must have road AND power nearby
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step-based offset to vary placement
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    # Fire stations grid - denser than parent
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 16) for fy in range(12, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 20) for py2 in range(14, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50), (15, 25), (105, 25),
                    (15, 75), (105, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 5), (30, 95), (90, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94),
                    (6, 45), (6, 65), (114, 45), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear power for high-pop - replace coal plants
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (8, 50), (112, 50), (60, 8), (60, 92),
            (20, 50), (100, 50), (50, 20), (70, 20),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value boost
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two power plants with wire spines and road seeds."""
    actions = []
    # Left cluster plant at (30, 50)
    actions.append((Tool.COALPOWER, 30, 50))
    # Right cluster plant at (90, 50)
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire horizontal spines from each plant
    for dx in range(-10, 11):
        actions.append((Tool.WIRE, 30 + dx, 50))
        actions.append((Tool.WIRE, 90 + dx, 50))
    # Wire vertical spines
    for dy in range(-10, 11):
        actions.append((Tool.WIRE, 30, 50 + dy))
        actions.append((Tool.WIRE, 90, 50 + dy))
    # Seed roads flanking horizontal wires
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, 30 + dx, 48))
        actions.append((Tool.ROAD, 30 + dx, 52))
        actions.append((Tool.ROAD, 90 + dx, 48))
        actions.append((Tool.ROAD, 90 + dx, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More industrial and commercial bias: 35% res, 35% com, 30% ind
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        ys, xs = np.where(mask)
        if len(xs) == 0:
            return result
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                ny_arr = ys + dy
                nx_arr = xs + dx
                valid = (nx_arr >= 0) & (nx_arr < WORLD_W) & (ny_arr >= 0) & (ny_arr < WORLD_H)
                result[ny_arr[valid], nx_arr[valid]] = True
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 6)
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # More clusters: 5 columns x 4 rows
    cluster_cols = [12, 35, 60, 85, 108]
    cluster_rows = [15, 38, 62, 85]

    def active_clusters():
        if pop < 50:
            return [(30, 50), (90, 50)]
        if pop < 300:
            return [(30, 38), (90, 38), (30, 62), (90, 62)]
        if pop < 800:
            return [(12, 38), (60, 38), (108, 38),
                    (12, 62), (60, 62), (108, 62)]
        if pop < 2000:
            return [(12, 15), (60, 15), (108, 15),
                    (12, 50), (60, 50), (108, 50),
                    (12, 85), (60, 85), (108, 85)]
        # Full 5x4 grid
        return [(cx, cy) for cy in cluster_rows for cx in cluster_cols]

    clusters = active_clusters()

    # ---- ENSURE POWER PLANTS ----
    for cx, cy in clusters:
        px0, px1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        py0, py1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[py0:py1, px0:px1]))
        if not has_plant:
            for r in range(15):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        if r > 0 and abs(dx2) != r and abs(dy2) != r:
                            continue
                        nx, ny = cx + dx2, cy + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- EXTEND WIRE FROM EACH PLANT ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        spine_reach = min(20, 8 + pop // 20)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            in_cluster = any(abs(px2 - cx) <= 14 and abs(py2 - cy) <= 14
                             for cx, cy in clusters)
            if not in_cluster:
                continue
            # Extend wire in all 4 directions
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2 + sign * dist, py2
                    if not ib(nx3, ny3):
                        break
                    if bool(pm[ny3, nx3]):
                        break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)
            for sign in [-1, 1]:
                for dist in range(1, spine_reach + 1):
                    nx3, ny3 = px2, py2 + sign * dist
                    if not ib(nx3, ny3):
                        break
                    if bool(pm[ny3, nx3]):
                        break
                    if bool(em[ny3, nx3]) and not bool(wm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CONNECT CLUSTERS WITH WIRE HORIZONTALLY ----
    active_rows_set = sorted(set(cy for cx, cy in clusters))
    active_cols_set = sorted(set(cx for cx, cy in clusters))

    for cy in active_rows_set:
        row_clusters_sorted = sorted([cx for cx, c_cy in clusters if abs(c_cy - cy) <= 12])
        for i in range(len(row_clusters_sorted) - 1):
            c1, c2 = row_clusters_sorted[i], row_clusters_sorted[i + 1]
            row_wire = [bool(wm[cy, x] or pm[cy, x]) for x in range(c1, c2 + 1) if ib(x, cy)]
            if not all(row_wire):
                for x in range(c1, c2 + 1):
                    if ib(x, cy) and not bool(pm[cy, x]) and bool(em[cy, x]) and not bool(wm[cy, x]):
                        return (Tool.WIRE, x, cy)

    # ---- CONNECT CLUSTERS WITH WIRE VERTICALLY ----
    for cx in active_cols_set:
        col_clusters_sorted = sorted([cy for c_cx, cy in clusters if abs(c_cx - cx) <= 12])
        for i in range(len(col_clusters_sorted) - 1):
            r1, r2 = col_clusters_sorted[i], col_clusters_sorted[i + 1]
            col_wire = [bool(wm[y, cx] or pm[y, cx]) for y in range(r1, r2 + 1) if ib(cx, y)]
            if not all(col_wire):
                for y in range(r1, r2 + 1):
                    if ib(cx, y) and not bool(pm[y, cx]) and bool(em[y, cx]) and not bool(wm[y, cx]):
                        return (Tool.WIRE, cx, y)

    # ---- BUILD ROAD GRID: 4 roads around each cluster (not just 2) ----
    road_reach = min(18, 5 + pop // 40)
    for cx, cy in clusters:
        # 4 parallel road lanes: cy-3, cy-1, cy+1, cy+3
        for road_y in [cy - 3, cy - 1, cy + 1, cy + 3]:
            if not ib(cx, road_y):
                continue
            for dx in range(-road_reach, road_reach + 1):
                nx4, ny4 = cx + dx, road_y
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)
        # 4 vertical road lanes
        for road_x in [cx - 3, cx - 1, cx + 1, cx + 3]:
            if not ib(road_x, cy):
                continue
            for dy in range(-road_reach, road_reach + 1):
                nx4, ny4 = road_x, cy + dy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    if not bool(rm[ny4, nx4]):
                        return (Tool.ROAD, nx4, ny4)

    # ---- INTER-CLUSTER ROADS ----
    if pop > 100:
        for cy in active_rows_set:
            sorted_cx2 = active_cols_set
            for i in range(len(sorted_cx2) - 1):
                c1, c2 = sorted_cx2[i], sorted_cx2[i + 1]
                for road_y in [cy - 4, cy + 4]:
                    if not (0 <= road_y < WORLD_H):
                        continue
                    has_road = any(bool(rm[road_y, x]) for x in range(c1, c2 + 1) if ib(x, road_y))
                    if not has_road:
                        for x in range(c1, c2 + 1):
                            if ib(x, road_y) and bool(em[road_y, x]) and not bool(pm[road_y, x]):
                                return (Tool.ROAD, x, road_y)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for cx, cy in clusters:
            d = (np.abs(cxs2 - cx).astype(float) +
                 np.abs(cys2 - cy).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [(fx, fy) for fy in range(8, 98, 15) for fx in range(8, 118, 18)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px, py) for py in range(10, 95, 18) for px in range(10, 115, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 5), (60, 5), (95, 5),
                         (25, 93), (60, 93), (95, 93)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear power
        nuke_spots = [(5, 15), (115, 15), (5, 50), (115, 50),
                      (5, 85), (115, 85), (60, 5), (60, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(60, 5), (5, 50), (115, 50), (60, 93)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 50)):
                k = (step * 5 + i * 13) % len(zone_xs3)
                zx3, zy3 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx5, dy5 in [(3, 0), (-3, 0), (0, 3), (0, -3),
                                  (4, 4), (-4, 4), (4, -4), (-4, -4)]:
                    nx5, ny5 = zx3 + dx5, zy3 + dy5
                    if ib(nx5, ny5) and bool(em[ny5, nx5]):
                        return (Tool.PARK, nx5, ny5)

    # ---- FALLBACK: extend roads near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 80)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx6, dy6 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx6, ny6 = rx + dx6, ry + dy6
                if (ib(nx6, ny6) and bool(em[ny6, nx6]) and
                        not bool(pm[ny6, nx6]) and bool(nbr_wire[ny6, nx6])):
                    return (Tool.ROAD, nx6, ny6)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx3, wy3 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx7, dy7 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx7, ny7 = wx3 + dx7, wy3 + dy7
                if ib(nx7, ny7) and bool(em[ny7, nx7]) and not bool(pm[ny7, nx7]):
                    return (Tool.WIRE, nx7, ny7)

    return None

# High-reactivity closed-loop city builder
# Strategy: Dense compact clusters with coal plants, wire grids, road grids
# Scan map each step to decide what's needed most

def init(obs, state):
    """Bootstrap: 2 coal plants near center + wire + roads"""
    actions = []
    # Two plants near center
    actions.append((Tool.COALPOWER, 55, 45))
    actions.append((Tool.COALPOWER, 65, 55))
    # Wire connecting them
    for x in range(56, 65):
        actions.append((Tool.WIRE, x, 45))
    for y in range(46, 55):
        actions.append((Tool.WIRE, 65, y))
    # Horizontal roads
    for x in range(50, 72):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Vertical roads
    for y in range(44, 58):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- CLUSTER DEFINITIONS ---
    # 6x5 grid of clusters covering the map
    # Each cluster is ~20x20 tiles with a coal plant
    cluster_centers = []
    for row in range(5):
        for col in range(6):
            cx = 10 + col * 20
            cy = 10 + row * 20
            cluster_centers.append((cx, cy))

    # Determine active clusters based on population
    def get_active_clusters():
        if pop < 100:
            # Start with 4 center clusters
            return [(50, 30), (70, 30), (50, 50), (70, 50)]
        elif pop < 500:
            # 9 clusters in center region
            return [(cx, cy) for (cx, cy) in cluster_centers
                    if 30 <= cx <= 90 and 10 <= cy <= 70]
        elif pop < 1500:
            # All but edge clusters
            return [(cx, cy) for (cx, cy) in cluster_centers
                    if 10 <= cx <= 110 and 10 <= cy <= 90]
        else:
            return cluster_centers

    active_clusters = get_active_clusters()

    # --- POWER COVERAGE CHECK ---
    # Build a dilation of wire+plant mask (power reaches ~3 tiles)
    power_base = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_base[sr0:sr1, sc0:sc1]

    # --- ROAD COVERAGE ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # --- PHASE: determine what to do this step ---
    # Round-robin through tasks to balance infrastructure vs zoning
    phase = step % 8

    # ---- TASK 1: Ensure each active cluster has a power plant ----
    for (cx, cy) in active_clusters:
        x0 = max(0, cx - 10); x1 = min(WORLD_W, cx + 11)
        y0 = max(0, cy - 10); y1 = min(WORLD_H, cy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at cluster center if empty, else nearby
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- TASK 2: Wire from each cluster plant outward to connect to main grid ----
    # Wire corridors: horizontal at y=10,30,50,70,90; vertical at x=10,30,50,70,90,110
    wire_rows = [10, 30, 50, 70, 90]
    wire_cols = [10, 30, 50, 70, 90, 110]

    if phase in (0, 1):
        # Extend wire corridors
        # First find any plant/wire and grow outward along corridors
        for wr in wire_rows:
            if not ib(0, wr):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    # Check if adjacent to wire/plant
                    left_ok = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    if left_ok and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)
        for wc in wire_cols:
            if not ib(wc, 0):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    above_ok = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    if above_ok and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    if phase in (2, 3):
        # Build roads parallel to wire corridors (offset by +-1)
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not ib(0, ry):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if ib(rx, ry) and bool(em[ry, rx]):
                        # Only if wire exists nearby
                        if bool(nbr_power[ry, rx]):
                            left_ok = rx > 0 and bool(rm[ry, rx-1])
                            if left_ok:
                                return (Tool.ROAD, rx, ry)
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not ib(rcx, 0):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if ib(rcx, ry) and bool(em[ry, rcx]):
                        if bool(nbr_power[ry, rcx]):
                            above_ok = ry > 0 and bool(rm[ry-1, rcx])
                            if above_ok:
                                return (Tool.ROAD, rcx, ry)

    # ---- WIRE SPURS: connect cluster plants to nearest corridor wire ----
    if phase == 4:
        # For each active cluster with a plant, wire spur toward main grid
        for (cx, cy) in active_clusters:
            x0 = max(0, cx - 12); x1 = min(WORLD_W, cx + 13)
            y0 = max(0, cy - 12); y1 = min(WORLD_H, cy + 13)
            # Find plant location in cluster
            pys, pxs = np.where(pm[y0:y1, x0:x1])
            if len(pxs) == 0:
                continue
            plant_x = int(pxs[0]) + x0
            plant_y = int(pys[0]) + y0
            # Find nearest wire tile not in this cluster
            best_d = 999
            best_pos = None
            wy_all, wx_all = np.where(wm | pm)
            if len(wx_all) > 0:
                dists = np.abs(wx_all - plant_x) + np.abs(wy_all - plant_y)
                far = dists > 3  # exclude self
                if np.any(far):
                    idx = np.argmin(dists + (~far) * 10000)
                    best_pos = (int(wx_all[idx]), int(wy_all[idx]))
                    best_d = int(dists[idx])
            if best_pos is not None and best_d > 3:
                bx, by = best_pos
                # Step from plant_x,plant_y toward bx,by
                dx = 0 if bx == plant_x else (1 if bx > plant_x else -1)
                dy = 0 if by == plant_y else (1 if by > plant_y else -1)
                # Try horizontal first
                if dx != 0:
                    nx, ny = plant_x + dx, plant_y
                else:
                    nx, ny = plant_x, plant_y + dy
                if ib(nx, ny) and bool(em[ny, nx]):
                    return (Tool.WIRE, nx, ny)
                # Try vertical
                if dy != 0:
                    nx, ny = plant_x, plant_y + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- CROSS STREETS every ~6 tiles between wire cols ----
    if phase == 5:
        for col_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[col_idx], wire_cols[col_idx + 1]
            for mid_x in range(c1 + 6, c2, 6):
                if not ib(mid_x, 0):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]):
                        if bool(nbr_power[ry, mid_x]):
                            adj_road = False
                            for ady in [-1, 1]:
                                ay = ry + ady
                                if ib(mid_x, ay) and bool(rm[ay, mid_x]):
                                    adj_road = True
                                    break
                            if adj_road:
                                return (Tool.ROAD, mid_x, ry)
        # Also horizontal cross streets
        for row_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[row_idx], wire_rows[row_idx + 1]
            for mid_y in range(r1 + 6, r2, 6):
                if not ib(0, mid_y):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]):
                        if bool(nbr_power[mid_y, rx]):
                            adj_road = False
                            for adx in [-1, 1]:
                                ax = rx + adx
                                if ib(ax, mid_y) and bool(rm[mid_y, ax]):
                                    adj_road = True
                                    break
                            if adj_road:
                                return (Tool.ROAD, rx, mid_y)

    # ---- ZONE PLACEMENT ----
    # Balanced: 40% RES, 35% COM, 25% IND (more commercial for revenue)
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Candidate: empty, near road AND near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to active cluster centers
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_clusters:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 200:
        fire_positions = [
            (20, 10), (50, 10), (80, 10), (110, 10),
            (10, 30), (40, 30), (70, 30), (100, 30),
            (20, 50), (60, 50), (90, 50), (110, 50),
            (10, 70), (40, 70), (70, 70), (100, 70),
            (20, 90), (50, 90), (80, 90), (110, 90),
        ]
        for (sx, sy) in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_positions = [
            (30, 20), (70, 20), (110, 20),
            (10, 45), (50, 45), (90, 45),
            (30, 65), (70, 65), (110, 65),
            (20, 85), (60, 85), (100, 85),
        ]
        for (sx, sy) in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(40, 40), (80, 40), (40, 60), (80, 60),
                    (60, 20), (60, 80), (20, 50), (100, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(55, 5), (65, 5), (55, 94), (65, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks boost land value
    if pop > 300 and step % 6 == 0:
        pys2, pxs2 = np.where(em & nbr_road & nbr_power)
        if len(pxs2) > 0:
            idx = (step * 17) % len(pxs2)
            return (Tool.PARK, int(pxs2[idx]), int(pys2[idx]))

    # ---- FALLBACK: Extend roads from existing road ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k = (step * 11) % len(road_xs2)
        for i in range(min(len(road_xs2), 80)):
            idx = (k + i * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[idx]), int(road_ys2[idx])
            for dx2, dy2 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: Extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        k2 = (step * 13) % len(wire_xs_arr)
        for i in range(min(len(wire_xs_arr), 60)):
            idx = (k2 + i * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[idx]), int(wire_ys_arr[idx])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: New plant near uncovered active cluster ----
    for (cx, cy) in active_clusters:
        if not bool(nbr_power[cy, cx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 power plants + wire spine + seed roads"""
    actions = []
    # Three coal plants
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Horizontal wire spine
    for x in range(18, 103):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(30, 70):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Seed horizontal roads near each plant
    for x in range(10, 115):
        if x % 10 != 0:  # skip plant cols
            actions.append((Tool.ROAD, x, 44))
            actions.append((Tool.ROAD, x, 56))
    # Seed vertical roads
    for y in range(36, 65):
        actions.append((Tool.ROAD, 30, y))
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        # 50% res, 25% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plants cover the map ----
    # Dense grid: plant every 20 cols x 20 rows
    plant_spacing = 20
    for ppy in range(10, WORLD_H - 5, plant_spacing):
        for ppx in range(10, WORLD_W - 5, plant_spacing):
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network - horizontal spine rows ----
    # Wire every 10 rows
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    # Extend horizontal wire rows across full width
    for wr in wire_rows:
        # Scan for gaps in this row
        row_src = wm[wr, :] | pm[wr, :]
        for x in range(2, WORLD_W - 2):
            if not bool(row_src[x]) and bool(em[wr, x]) and not bool(rm[wr, x]) and not bool(zone_tiles[wr, x]):
                # Check neighbors to extend existing wire
                left_has = x > 0 and (bool(wm[wr, x-1]) or bool(pm[wr, x-1]))
                right_has = x < WORLD_W-1 and (bool(wm[wr, x+1]) or bool(pm[wr, x+1]))
                up_has = wr > 0 and (bool(wm[wr-1, x]) or bool(pm[wr-1, x]))
                down_has = wr < WORLD_H-1 and (bool(wm[wr+1, x]) or bool(pm[wr+1, x]))
                if left_has or right_has or up_has or down_has:
                    return (Tool.WIRE, x, wr)

    # Extend vertical wire cols
    for wc in wire_cols:
        col_src = wm[:, wc] | pm[:, wc]
        for y in range(2, WORLD_H - 2):
            if not bool(col_src[y]) and bool(em[y, wc]) and not bool(rm[y, wc]) and not bool(zone_tiles[y, wc]):
                up_has = y > 0 and (bool(wm[y-1, wc]) or bool(pm[y-1, wc]))
                down_has = y < WORLD_H-1 and (bool(wm[y+1, wc]) or bool(pm[y+1, wc]))
                left_has = wc > 0 and (bool(wm[y, wc-1]) or bool(pm[y, wc-1]))
                right_has = wc < WORLD_W-1 and (bool(wm[y, wc+1]) or bool(pm[y, wc+1]))
                if up_has or down_has or left_has or right_has:
                    return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads at offset +/-4 from wire rows/cols, covering full width/height
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 4)
        road_rows.append(wr + 4)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 4)
        road_cols.append(wc + 4)
    road_rows = sorted(set(r for r in road_rows if 2 < r < WORLD_H - 2))
    road_cols = sorted(set(c for c in road_cols if 2 < c < WORLD_W - 2))

    for rr in road_rows:
        for x in range(2, WORLD_W - 2):
            if bool(em[rr, x]) and not bool(pm[rr, x]) and not bool(zone_tiles[rr, x]):
                left_has = x > 0 and bool(rm[rr, x-1])
                right_has = x < WORLD_W-1 and bool(rm[rr, x+1])
                up_has = rr > 0 and bool(rm[rr-1, x])
                down_has = rr < WORLD_H-1 and bool(rm[rr+1, x])
                if left_has or right_has or up_has or down_has:
                    return (Tool.ROAD, x, rr)
                # Start a road row if none exists
                if not rm[rr, :].any():
                    # Find nearest wire and seed road next to it
                    pys, pxs = np.where(pm)
                    if len(pxs) > 0:
                        idx = np.argmin(np.abs(pys - rr))
                        sx = int(pxs[idx]) + 4
                        if ib(sx, rr) and bool(em[rr, sx]) and not bool(pm[rr, sx]):
                            return (Tool.ROAD, sx, rr)

    for rc in road_cols:
        for y in range(2, WORLD_H - 2):
            if bool(em[y, rc]) and not bool(pm[y, rc]) and not bool(zone_tiles[y, rc]):
                up_has = y > 0 and bool(rm[y-1, rc])
                down_has = y < WORLD_H-1 and bool(rm[y+1, rc])
                left_has = rc > 0 and bool(rm[y, rc-1])
                right_has = rc < WORLD_W-1 and bool(rm[y, rc+1])
                if up_has or down_has or left_has or right_has:
                    return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W-3:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 200)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 4, 500.0, np.where(min_zone_dist > 30, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 3 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services ----
    if pop > 100:
        fire_spots = [(fx, fy) for fy in range(6, WORLD_H-6, 12) for fx in range(6, WORLD_W-6, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_spots = [(px2, py2) for py2 in range(8, WORLD_H-8, 14) for px2 in range(8, WORLD_W-8, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_spots = [(pkx, pky) for pky in range(8, WORLD_H-4, 10) for pkx in range(8, WORLD_W-4, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 1000:
        stadium_spots = [(sx, sy) for sy in range(15, WORLD_H-15, 25) for sx in range(15, WORLD_W-15, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 2000:
        nuclear_spots = [(nx, ny) for ny in range(15, WORLD_H-5, 25) for nx in range(15, WORLD_W-5, 25)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-14), min(WORLD_W, npx+15)
                y0, y1 = max(0, npy-14), min(WORLD_H, npy+15)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 4000:
        airport_spots = [(55, 8), (65, 8), (55, 90), (65, 90), (8, 48), (110, 48)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 6000:
        seaport_spots = [(8, 50), (110, 50), (60, 5), (60, 93)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 30)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 30)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: extend road or wire from any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6,0),(-6,0),(0,6),(0,-6),(4,0),(-4,0),(0,4),(0,-4),(8,0),(-8,0)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant + cross wire + seed roads for a compact core."""
    actions = []
    # Two coal plants as anchors
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 30, 25))
    actions.append((Tool.COALPOWER, 90, 25))
    actions.append((Tool.COALPOWER, 30, 75))
    actions.append((Tool.COALPOWER, 90, 75))
    # Wire from center plant outward in a cross
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads around center
    for x in range(50, 72):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(47, 54):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone type selection: balanced mix RES:COM:IND ~ 5:3:2
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dense neighborhood grid across whole map, 10-tile spacing
    all_hoods = []
    for hy in range(10, 95, 10):
        for hx in range(10, 115, 10):
            all_hoods.append((hx, hy))

    # Scale active hoods with population
    def num_active():
        if pop < 50:    return 5
        if pop < 200:   return 15
        if pop < 500:   return 30
        if pop < 1000:  return 50
        if pop < 3000:  return 80
        if pop < 6000:  return 110
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick hoods spread across the map
    stride = max(1, len(all_hoods) // n_active)
    active_hoods = all_hoods[::stride][:n_active]

    power_src = wm | pm

    # Neighbor power mask (radius 6)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Neighbor road mask (radius 3)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: Place power plants for uncovered hoods ===
    if funds > 500:
        for (hx, hy) in active_hoods:
            if not bool(nbr_power[hy, hx]):
                # Find empty spot near hood for plant
                for r in range(1, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: Wire grid - connect plants to hoods ===
    # Build a wire grid on rows/cols at every 10 tiles
    wire_rows = list(range(10, 95, 10))
    wire_cols = list(range(10, 115, 10))

    # Extend wire along target rows from existing power sources
    cyc = step % max(len(wire_rows), 1)
    for i in range(len(wire_rows)):
        wr = wire_rows[(cyc + i) % len(wire_rows)]
        row_has_power = any(bool(power_src[wr, c]) for c in range(0, WORLD_W, 5))
        if not row_has_power:
            continue
        # Extend wire leftward and rightward
        row_wire = np.where(wm[wr, :])[0]
        row_plant = np.where(pm[wr, :])[0]
        all_pow = sorted(set(list(row_wire)) | set(list(row_plant)))
        if all_pow:
            lx = all_pow[0]; rx = all_pow[-1]
            if lx > 5 and ib(lx - 1, wr) and bool(em[wr, lx - 1]) and not bool(pm[wr, lx - 1]):
                return (Tool.WIRE, lx - 1, wr)
            if rx < WORLD_W - 5 and ib(rx + 1, wr) and bool(em[wr, rx + 1]) and not bool(pm[wr, rx + 1]):
                return (Tool.WIRE, rx + 1, wr)

    cyc2 = (step + 3) % max(len(wire_cols), 1)
    for i in range(len(wire_cols)):
        wc = wire_cols[(cyc2 + i) % len(wire_cols)]
        col_has_power = any(bool(power_src[r, wc]) for r in range(0, WORLD_H, 5))
        if not col_has_power:
            continue
        col_wire = np.where(wm[:, wc])[0]
        col_plant = np.where(pm[:, wc])[0]
        all_pow_c = sorted(set(list(col_wire)) | set(list(col_plant)))
        if all_pow_c:
            ty = all_pow_c[0]; by = all_pow_c[-1]
            if ty > 5 and ib(wc, ty - 1) and bool(em[ty - 1, wc]) and not bool(pm[ty - 1, wc]):
                return (Tool.WIRE, wc, ty - 1)
            if by < WORLD_H - 5 and ib(wc, by + 1) and bool(em[by + 1, wc]) and not bool(pm[by + 1, wc]):
                return (Tool.WIRE, wc, by + 1)

    # Seed wire at target grid intersections near plants
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    # Find nearest plant
    pys_all, pxs_all = np.where(pm)
    if len(pxs_all) > 0:
        dists = np.abs(pxs_all - hx) + np.abs(pys_all - hy)
        nearest = int(np.argmin(dists))
        px_near = int(pxs_all[nearest])
        py_near = int(pys_all[nearest])
        # Wire from plant toward hood
        if abs(px_near - hx) + abs(py_near - hy) > 2:
            # Vertical first
            if py_near != hy:
                sdir = 1 if hy > py_near else -1
                for wy in range(py_near + sdir, hy + sdir, sdir):
                    if not ib(px_near, wy): break
                    if bool(pm[wy, px_near]): continue
                    if bool(wm[wy, px_near]): continue
                    if bool(em[wy, px_near]):
                        return (Tool.WIRE, px_near, wy)
                    break
            # Horizontal
            if px_near != hx:
                sdir = 1 if hx > px_near else -1
                for wx in range(px_near + sdir, hx + sdir, sdir):
                    if not ib(wx, hy): break
                    if bool(pm[hy, wx]): continue
                    if bool(wm[hy, wx]): continue
                    if bool(em[hy, wx]):
                        return (Tool.WIRE, wx, hy)
                    break

    # === PHASE 3: Road grid - rows and cols offset from wire grid ===
    # Road rows at offsets +2/-2 from wire rows (so zones between wire and road)
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr + 2)
        road_rows.append(wr - 2)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc + 2)
        road_cols.append(wc - 2)

    # Extend road rows near powered areas
    rcyc = (step + 1) % max(len(road_rows), 1)
    for i in range(min(len(road_rows), 5)):
        rr = road_rows[(rcyc + i) % len(road_rows)]
        if not ib(0, rr): continue
        if not bool(nbr_power[rr, 60]): continue
        row_road = np.where(rm[rr, :])[0]
        if len(row_road) > 0:
            lx2 = int(row_road[0]); rx2 = int(row_road[-1])
            if lx2 > 3 and ib(lx2 - 1, rr) and bool(em[rr, lx2 - 1]) and not bool(pm[rr, lx2 - 1]):
                return (Tool.ROAD, lx2 - 1, rr)
            if rx2 < WORLD_W - 3 and ib(rx2 + 1, rr) and bool(em[rr, rx2 + 1]) and not bool(pm[rr, rx2 + 1]):
                return (Tool.ROAD, rx2 + 1, rr)
        else:
            # Seed road at center if powered
            cx = 60
            if ib(cx, rr) and bool(em[rr, cx]) and not bool(pm[rr, cx]) and bool(nbr_power[rr, cx]):
                return (Tool.ROAD, cx, rr)

    rccyc = (step + 2) % max(len(road_cols), 1)
    for i in range(min(len(road_cols), 5)):
        rc = road_cols[(rccyc + i) % len(road_cols)]
        if not ib(rc, 0): continue
        if not bool(nbr_power[50, rc]): continue
        col_road = np.where(rm[:, rc])[0]
        if len(col_road) > 0:
            ty2 = int(col_road[0]); by2 = int(col_road[-1])
            if ty2 > 3 and ib(rc, ty2 - 1) and bool(em[ty2 - 1, rc]) and not bool(pm[ty2 - 1, rc]):
                return (Tool.ROAD, rc, ty2 - 1)
            if by2 < WORLD_H - 3 and ib(rc, by2 + 1) and bool(em[by2 + 1, rc]) and not bool(pm[by2 + 1, rc]):
                return (Tool.ROAD, rc, by2 + 1)
        else:
            cy = 50
            if ib(rc, cy) and bool(em[cy, rc]) and not bool(pm[cy, rc]) and bool(nbr_power[cy, rc]):
                return (Tool.ROAD, rc, cy)

    # === PHASE 4: Zone placement ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Also prefer clustering near existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride_z = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride_z):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: Extend roads from existing network into powered areas ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 6: Civic services ===
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(12, 95, 16) for fx in range(12, 115, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(nbr_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(15, 90, 18) for px2 in range(15, 112, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(nbr_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 4 == 0:
        park_y, park_x = np.where(em & nbr_road & nbr_power)
        if len(park_x) > 0:
            idx = (step * 19) % len(park_x)
            return (Tool.PARK, int(park_x[idx]), int(park_y[idx]))

    if pop > 200 and funds > 2000:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (40, 50), (80, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 30), (85, 30), (35, 70), (85, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 300 and funds > 1000:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600 and funds > 5000:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 7: Fallback wire extension from any power source ===
    pys_f, pxs_f = np.where(pm)
    if len(pxs_f) > 0:
        sk = (step * 11) % len(pxs_f)
        for offset in range(min(len(pxs_f), 60)):
            k = (sk + offset * 7) % len(pxs_f)
            px3, py3 = int(pxs_f[k]), int(pys_f[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    wys_f, wxs_f = np.where(wm)
    if len(wxs_f) > 0:
        sk2 = (step * 13) % len(wxs_f)
        for offset in range(min(len(wxs_f), 60)):
            k = (sk2 + offset * 5) % len(wxs_f)
            wx2, wy2 = int(wxs_f[k]), int(wys_f[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === PHASE 8: Plant for uncovered hood ===
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]) and funds > 500:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx3 + dx, hy3 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants + wire spines + flanking roads."""
    actions = []
    # Three coal plants along center row
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from plants
    for px in [20, 60, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, px, y))
    # Roads flanking horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID: 10 cols x 7 rows = 70 neighborhoods ----
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]
    nh_rows = [8, 20, 33, 46, 59, 72, 85]
    # Clamp to valid range
    nh_cols = [min(c, WORLD_W - 2) for c in nh_cols]
    nh_rows = [min(r, WORLD_H - 2) for r in nh_rows]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 6
        if pop < 400:  return 12
        if pop < 800:  return 20
        if pop < 1500: return 30
        if pop < 3000: return 45
        if pop < 6000: return 60
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS ----
    # Power within 6 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Road within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT NEAR EACH ACTIVE HOOD ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE BACKBONE - vertical and horizontal spines per hood ----
    # Each hood gets a vertical spine (column) and horizontal spine (row)
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Extend vertical wire spine at hx from hy-8 to hy+8
    for dy in range(-8, 9):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for ady in [-1, 1]:
            ay = wy + ady
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Extend horizontal wire spine at hy from hx-8 to hx+8
    for dx in range(-8, 9):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adx in [-1, 1]:
            ax = wx + adx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT NEIGHBORHOODS ----
    # Horizontal wire connections between same-row adjacent cols (spacing=12)
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 14:
                # Fill gap horizontally
                mid_y = hy1
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Vertical connections
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 16:
                mid_x = hx1
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    spine_range = 8
    # Stagger road building across hoods
    road_hood_idx = (step // 2) % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_hood_idx]

    # Roads flanking vertical spine
    for rx in [rhx - 1, rhx + 1]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)

    # Roads flanking horizontal spine
    for ry2 in [rhy - 1, rhy + 1]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: CROSS-ROADS between neighborhood rows ----
    # Add horizontal roads at midpoints between nh_rows
    for ri in range(len(nh_rows) - 1):
        r1, r2 = nh_rows[ri], nh_rows[ri + 1]
        mid_y = (r1 + r2) // 2
        for x in range(1, WORLD_W - 1):
            if bool(em[mid_y, x]) and bool(nbr_power[mid_y, x]) and not bool(pm[mid_y, x]):
                adj = ((x > 0 and bool(rm[mid_y, x - 1])) or
                       (x < WORLD_W - 1 and bool(rm[mid_y, x + 1])))
                if adj:
                    return (Tool.ROAD, x, mid_y)

    # ---- EXTEND ROADS from existing road network ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    # Avoid wire/plant columns and rows
    for (hx2, hy2) in active_hoods:
        cand_mask[max(0, hy2 - 1):hy2 + 2, hx2] = False
        cand_mask[hy2, max(0, hx2 - 1):hx2 + 2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2).astype(float) + np.abs(cys - hy2).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 14) for fy in range(10, WORLD_H, 14)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(12, WORLD_W, 18) for py2 in range(12, WORLD_H, 18)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 45), (75, 45), (45, 55), (75, 55)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 4), (30, 95), (90, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000 and step % 3 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (10, 50), (110, 50), (60, 10), (60, 90),
                         (20, 50), (100, 50), (50, 20), (70, 20)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 4000:
        airports = [(45, 5), (75, 5), (45, 94), (75, 94),
                    (5, 40), (5, 60), (114, 40), (114, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17 + pop) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire toward unpowered hoods ----
    unpowered_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if not bool(nbr_power[hy2, hx2])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new coal plant near uncovered hood ----
    for (hx2, hy2) in active_hoods:
        if not bool(nbr_power[hy2, hx2]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx2 + dx, hy2 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for d in range(1, 8):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID: 10 cols x 8 rows = 80 neighborhoods ----
    # Dense coverage across full 120x100 map
    nh_cols = [6, 19, 32, 45, 58, 71, 84, 97, 110, 117]
    nh_rows = [6, 18, 30, 44, 56, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 20:    return 3
        if pop < 80:    return 6
        if pop < 200:   return 10
        if pop < 500:   return 16
        if pop < 1000:  return 24
        if pop < 2000:  return 35
        if pop < 4000:  return 50
        if pop < 7000:  return 65
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: POWER PLANTS ----
    # Place coal plants on a coarse grid so all hoods have nearby power
    plant_grid = []
    for py in range(12, 95, 22):
        for px in range(12, 112, 22):
            plant_grid.append((px, py))

    if funds > 1000:
        for (ppx, ppy) in plant_grid:
            x0, x1 = max(0, ppx - 9), min(WORLD_W, ppx + 10)
            y0, y1 = max(0, ppy - 9), min(WORLD_H, ppy + 10)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE BACKBONE ----
    # Build vertical and horizontal wire spines through each hood
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Vertical spine at hx
        spine_top = max(1, hy - 12)
        spine_bot = min(WORLD_H - 2, hy + 12)
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        if col_wire:
            min_wr, max_wr = min(col_wire), max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine at hy
        spine_left = max(1, hx - 12)
        spine_right = min(WORLD_W - 2, hx + 12)
        row_wire = [c for c in range(spine_left, spine_right + 1)
                    if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc, max_wc = min(row_wire), max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: CONNECT ADJACENT HOODS WITH WIRES ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 32:
                continue
            # Horizontal connection
            if abs(hy1 - hy2) <= 3:
                mid_y = (hy1 + hy2) // 2
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, mid_y):
                        continue
                    if bool(pm[mid_y, cx2]):
                        continue
                    if bool(em[mid_y, cx2]):
                        # Check adjacency
                        for adx in [-1, 1]:
                            ax = cx2 + adx
                            if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                                return (Tool.WIRE, cx2, mid_y)
            # Vertical connection
            if abs(hx1 - hx2) <= 3:
                mid_x = (hx1 + hx2) // 2
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(mid_x, cy2):
                        continue
                    if bool(pm[cy2, mid_x]):
                        continue
                    if bool(em[cy2, mid_x]):
                        for ady in [-1, 1]:
                            ay = cy2 + ady
                            if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                                return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Only process a subset each step for efficiency
        if (step + idx_h) % max(1, len(active_hoods) // 4) != 0:
            continue

        col_wire = [r for r in range(max(0, hy - 12), min(WORLD_H, hy + 13))
                    if ib(hx, r) and bool(wm[r, hx])]
        # Roads at ±1 and ±3 from vertical spine
        for rx_off in [-1, 1, -3, 3]:
            rx = hx + rx_off
            if not ib(rx, hy):
                continue
            cyc = (step + rx_off) % 5
            for wr in col_wire[cyc::5]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(max(0, hx - 12), min(WORLD_W, hx + 13))
                    if ib(c, hy) and bool(wm[hy, c])]
        # Roads at ±1 and ±3 from horizontal spine
        for ry_off in [-1, 1, -3, 3]:
            ry = hy + ry_off
            if not ib(hx, ry):
                continue
            cyc = (step + ry_off + 2) % 5
            for wc in row_wire[cyc::5]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = total_zones
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 45% RES, 30% COM, 25% IND
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        if rr < 0.44:
            return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (wire or plant within 4 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Bonus: cluster near existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS INTO POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    # Fire stations - dense grid
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(10, WORLD_H, 15)
                      for fx in range(10, WORLD_W, 15)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(12, WORLD_H, 18)
                        for px2 in range(12, WORLD_W, 18)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # Parks for land value
    if pop > 100 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 500:
        stadiums = [
            (30, 25), (60, 15), (90, 25),
            (20, 50), (60, 50), (100, 50),
            (30, 75), (60, 85), (90, 75),
            (15, 15), (105, 15), (15, 85), (105, 85),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        seaports = [(5, 50), (115, 50), (60, 5), (60, 95),
                    (5, 25), (5, 75), (115, 25), (115, 75),
                    (30, 5), (90, 5), (30, 95), (90, 95)]
        for (spx, spy) in seaports:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Nuclear power upgrade when rich
    if pop > 1000 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (35, 25), (85, 25), (35, 75), (85, 75),
            (20, 50), (100, 50), (60, 30), (60, 70),
            (35, 50), (85, 50),
        ]
        for (npx, npy) in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 7), min(WORLD_W, npx + 8)
            y0b, y1b = max(0, npy - 7), min(WORLD_H, npy + 8)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airports = [(10, 10), (100, 10), (10, 85), (100, 85),
                    (55, 5), (55, 92), (5, 45), (5, 65),
                    (110, 45), (110, 65)]
        for (apx, apy) in airports:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Ambitious closed-loop city builder
# Strategy: 6x5 grid of 30 neighborhoods, each self-powered
# Dense road grid, balanced zones, civic services, reactive expansion

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-9, 10):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-9, 10):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # 6 columns x 5 rows = 30 neighborhoods
    nh_cols = [10, 30, 50, 70, 90, 110]
    nh_rows = [10, 28, 50, 72, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on pop
    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 6
        if pop < 400:   return 10
        if pop < 800:   return 16
        if pop < 1500:  return 22
        if pop < 3000:  return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread evenly
    step_size = len(all_hoods) / n_active
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Build neighbor power mask (zones within 7 of wire/plant)
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Build neighbor road mask (zones within 3 of road)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: Ensure power plant near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire from each plant to its hood center ----
    spine_range = 16
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 16), min(WORLD_W, hx + 17)
    y0, y1 = max(0, hy - 16), min(WORLD_H, hy + 17)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0

        # Vertical wire toward hood
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        # Horizontal wire toward hood
        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

        # Extend vertical wire spine from hood
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Extend horizontal wire spine from hood
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: Inter-hood wire connections ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 22:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx + 1, mxx):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and abs(hy2 - hy1) <= 24:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny + 1, mxy):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: Dense road grid around each hood ----
    # Place roads at multiple offsets around each hood to create a grid
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    road_offsets = [-2, -1, 1, 2]  # Multiple road lanes
    for roff in road_offsets:
        # Vertical roads flanking wire spine (horizontal offsets)
        rx = hx3 + roff
        if ib(rx, hy3):
            for dy in range(-spine_range, spine_range + 1):
                ry = hy3 + dy
                if not ib(rx, ry): continue
                if bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                # Place if near wire or near existing road
                if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                    return (Tool.ROAD, rx, ry)
                # Or if adjacent to an existing road
                for ax2, ay2 in [(rx-1,ry),(rx+1,ry),(rx,ry-1),(rx,ry+1)]:
                    if ib(ax2, ay2) and bool(rm[ay2, ax2]) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    for roff in road_offsets:
        # Horizontal roads flanking vertical wire spine
        ry2 = hy3 + roff
        if ib(hx3, ry2):
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx3 + dx
                if not ib(rcx, ry2): continue
                if bool(pm[ry2, rcx]): continue
                if not bool(em[ry2, rcx]): continue
                if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                    return (Tool.ROAD, rcx, ry2)
                for ax2, ay2 in [(rcx-1,ry2),(rcx+1,ry2),(rcx,ry2-1),(rcx,ry2+1)]:
                    if ib(ax2, ay2) and bool(rm[ay2, ax2]) and bool(em[ry2, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: Cross-roads between hoods (inter-hood road connectors) ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 22:
                # Connect with horizontal road segments at hy1-1 and hy1+1
                for cy2 in [hy1 - 1, hy1 + 1, hy1 - 2, hy1 + 2]:
                    if not ib(hx1, cy2): continue
                    mnx2, mxx2 = min(hx1, hx2), max(hx1, hx2)
                    for cx3 in range(mnx2, mxx2 + 1):
                        if not ib(cx3, cy2): continue
                        if not bool(em[cy2, cx3]): continue
                        if bool(pm[cy2, cx3]): continue
                        has_adj = False
                        for ax2, ay2 in [(cx3-1,cy2),(cx3+1,cy2),(cx3,cy2-1),(cx3,cy2+1)]:
                            if ib(ax2, ay2) and bool(rm[ay2, ax2]):
                                has_adj = True
                                break
                        if has_adj:
                            return (Tool.ROAD, cx3, cy2)
            if hx1 == hx2 and abs(hy2 - hy1) <= 24:
                for cx2 in [hx1 - 1, hx1 + 1, hx1 - 2, hx1 + 2]:
                    if not ib(cx2, hy1): continue
                    mny2, mxy2 = min(hy1, hy2), max(hy1, hy2)
                    for cy3 in range(mny2, mxy2 + 1):
                        if not ib(cx2, cy3): continue
                        if not bool(em[cy3, cx2]): continue
                        if bool(pm[cy3, cx2]): continue
                        has_adj = False
                        for ax2, ay2 in [(cx2-1,cy3),(cx2+1,cy3),(cx2,cy3-1),(cx2,cy3+1)]:
                            if ib(ax2, ay2) and bool(rm[ay2, ax2]):
                                has_adj = True
                                break
                        if has_adj:
                            return (Tool.ROAD, cx2, cy3)

    # ---- PHASE 6: Zone placement (balanced R/C/I) ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 32% com, 28% ind
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: Extend roads into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: Civic services reactive to population ----
    # Fire stations every 18 tiles
    if pop > 80:
        for fx in range(12, WORLD_W, 18):
            for fy in range(12, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    # Police stations
    if pop > 300:
        for px2 in range(15, WORLD_W, 22):
            for py2 in range(15, WORLD_H, 22):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    # Stadiums
    if pop > 800:
        stadiums = [(20,20),(60,20),(100,20),(20,50),(60,50),(100,50),(20,80),(60,80),(100,80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Seaports
    if pop > 1500:
        seaports = [(6,94),(114,94),(6,6),(114,6),(60,97),(60,3),(30,97),(90,97),(30,3),(90,3)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # Airports
    if pop > 3000:
        airports = [(40,5),(80,5),(40,94),(80,94),(5,40),(5,70),(114,40),(114,70),(5,50),(114,50)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrades for mature city
    if pop > 2000 and step % 2 == 0:
        nuclear_spots = [(60,50),(10,10),(110,10),(10,90),(110,90),
                         (30,28),(70,28),(30,72),(70,72),(50,50),
                         (60,28),(60,72),(30,50),(90,50),(10,50),(110,50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 200 and step % 3 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- Fallback: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- Fallback: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: place two coal plants with wire connections and initial roads."""
    actions = []
    # Primary plant at (58, 50)
    actions.append((Tool.COALPOWER, 58, 50))
    # Wire spine from plant upward and downward
    for y in range(44, 58):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking wire spine
    for y in range(44, 58):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    # Second plant to the right
    actions.append((Tool.COALPOWER, 78, 50))
    # Wire bridge connecting plants
    for x in range(61, 77):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    """
    Highly reactive closed-loop policy.
    Strategy: Build multiple neighborhoods around power spines.
    - Read current map state each step
    - Extend infrastructure where needed
    - Place zones densely near power+roads
    - Add more plants/services as city grows
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step

    # Count existing zones
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Ensure primary power plant exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, 58, 50)

    plant_ys, plant_xs = np.where(pm)
    num_plants = len(plant_xs) // 9  # approximate (3x3 tiles per plant)

    # --- Add more power plants as city grows ---
    # Plant locations: primary=58,50; secondary=78,50; tertiary=38,50; quaternary=58,30; quinary=58,70
    plant_targets = [
        (58, 50), (78, 50), (38, 50),
        (58, 30), (58, 70),
        (90, 30), (30, 30),
        (90, 70), (30, 70),
    ]
    # Check which plants are missing
    for (ptx, pty) in plant_targets:
        if not in_bounds(ptx, pty):
            continue
        nearby = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = ptx + dx, pty + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    nearby = True
                    break
            if nearby:
                break
        if not nearby:
            # Only place if we have enough pop or it's early plants
            plant_idx = plant_targets.index((ptx, pty))
            pop_threshold = plant_idx * 150
            if pop >= pop_threshold or plant_idx < 2:
                # Check if tile is empty
                if bool(em[pty, ptx]):
                    return (Tool.COALPOWER, ptx, pty)

    # --- Wire infrastructure: connect all plants with horizontal/vertical spines ---
    # Vertical spines at x=60, x=80, x=40 (right of each plant column)
    # Horizontal spines at y=50, y=32, y=68
    spine_cols = [60, 80, 40, 92, 32]
    spine_rows = [50, 32, 68, 20, 80]

    # Determine extent based on population
    extent = min(35, 10 + pop // 30)
    cy = 50  # center y

    # Build vertical wire spines
    for sc in spine_cols:
        if not in_bounds(sc, cy):
            continue
        spine_top = max(3, cy - extent)
        spine_bot = min(WORLD_H - 4, cy + extent)
        # Check if this spine needs extension
        col_wires = [r for r in range(WORLD_H) if bool(wm[r, sc])]
        col_plants = [r for r in range(WORLD_H) if bool(pm[r, sc])]
        existing = col_wires + col_plants
        if not existing:
            # Seed from center
            for dy in range(-2, 3):
                ny = cy + dy
                if in_bounds(sc, ny) and bool(em[ny, sc]):
                    return (Tool.WIRE, sc, ny)
        else:
            min_r = min(existing)
            max_r = max(existing)
            # Grow downward
            if max_r < spine_bot:
                nr = max_r + 1
                if in_bounds(sc, nr) and bool(em[nr, sc]) and not bool(pm[nr, sc]):
                    return (Tool.WIRE, sc, nr)
            # Grow upward
            if min_r > spine_top:
                nr = min_r - 1
                if in_bounds(sc, nr) and bool(em[nr, sc]) and not bool(pm[nr, sc]):
                    return (Tool.WIRE, sc, nr)

    # Build horizontal wire spines connecting vertical spines
    for sr in spine_rows:
        if not in_bounds(0, sr):
            continue
        row_wires = [c for c in range(WORLD_W) if bool(wm[sr, c])]
        row_plants = [c for c in range(WORLD_W) if bool(pm[sr, c])]
        existing_c = row_wires + row_plants
        if not existing_c:
            continue
        min_c = min(existing_c)
        max_c = max(existing_c)
        # Find leftmost and rightmost spine cols that exist with wire
        target_left = max(3, 32 - extent // 2)
        target_right = min(WORLD_W - 4, 92 + extent // 2)
        if max_c < target_right:
            nc = max_c + 1
            if in_bounds(nc, sr) and bool(em[sr, nc]) and not bool(pm[sr, nc]):
                return (Tool.WIRE, nc, sr)
        if min_c > target_left:
            nc = min_c - 1
            if in_bounds(nc, sr) and bool(em[sr, nc]) and not bool(pm[sr, nc]):
                return (Tool.WIRE, nc, sr)

    # --- Build road grid: roads parallel to wire spines ---
    # Road columns flank each wire spine col
    road_spine_pairs = [(sc - 1, sc + 1) for sc in spine_cols]
    road_row_pairs = [(sr - 1, sr + 1) for sr in spine_rows]

    # For each wire spine, build flanking roads
    for sc in spine_cols:
        for road_col in [sc - 1, sc + 1]:
            if not in_bounds(road_col, cy):
                continue
            # Check wires in the spine col
            col_wires = [r for r in range(WORLD_H) if bool(wm[r, sc])]
            if not col_wires:
                continue
            spine_top = min(col_wires)
            spine_bot = max(col_wires)
            for wr in range(spine_top, spine_bot + 1):
                if in_bounds(road_col, wr) and bool(em[wr, road_col]) and not bool(pm[wr, road_col]):
                    return (Tool.ROAD, road_col, wr)

    # For each wire row spine, build flanking roads
    for sr in spine_rows:
        for road_row in [sr - 1, sr + 1]:
            if not in_bounds(60, road_row):
                continue
            row_wires = [c for c in range(WORLD_W) if bool(wm[sr, c])]
            if not row_wires:
                continue
            spine_left = min(row_wires)
            spine_right = max(row_wires)
            for wc in range(spine_left, spine_right + 1):
                if in_bounds(wc, road_row) and bool(em[road_row, wc]) and not bool(pm[road_row, wc]):
                    return (Tool.ROAD, wc, road_row)

    # --- Place zones near power and roads ---
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                t = tm[nr2, nc2]
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    # Allow placement on roads/wires only if they're not plants
                    if bool(pm[nr2, nc2]):
                        return False
                    # Road/wire under zone is handled by auto-bulldoze
                    # but don't place zone on existing zone tiles
                    if bool(zone_tiles[nr2, nc2]):
                        return False
        return True

    # Candidate zone positions: near both road and wire, away from edges
    cand_mask = nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    # Must be empty
    cand_mask &= em
    # Not near plants
    plant_nbr = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            plant_nbr[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]
    cand_mask &= ~plant_nbr

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Find candidates with clear 3x3 area
        # Sort by distance from map center to favor dense core
        cx_center, cy_center = 60, 50
        dists = np.abs(cxs_arr - cx_center) + np.abs(cys_arr - cy_center)
        # Add some step-based offset for variety
        order = np.argsort(dists)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 120:
                break

    # --- Extend roads near existing roads ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Services based on population ---
    service_locs = [
        (pop > 200, Tool.FIRESTATION, [(50, 42), (70, 42), (50, 58), (70, 58)]),
        (pop > 400, Tool.POLICESTATION, [(46, 46), (74, 46), (46, 54), (74, 54)]),
        (pop > 600, Tool.FIRESTATION, [(40, 32), (80, 32), (40, 68), (80, 68)]),
        (pop > 800, Tool.POLICESTATION, [(36, 50), (84, 50), (60, 25), (60, 75)]),
        (pop > 1000, Tool.STADIUM, [(60, 40), (60, 60)]),
    ]
    for condition, tool, locs in service_locs:
        if condition:
            for (sx, sy) in locs:
                if in_bounds(sx, sy) and bool(em[sy, sx]):
                    return (tool, sx, sy)

    # --- Extend wire laterally as fallback ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
