        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        for wr in all_wire_rows:
            if 0 <= wr < WORLD_H:
                park_cands[max(0, wr-1):min(WORLD_H, wr+2), :] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (primary closed-loop action) ----
    # Exclude wire/road corridors from zoning
    all_excl_rows = wire_rows + [14, 15, 16, 17, 24, 25, 26, 27, 37, 38, 39, 40,
                                  47, 48, 49, 53, 54, 55, 60, 61, 62, 63,
                                  70, 71, 72, 73, 80, 81, 82, 83, 94, 95, 96, 97]
    all_excl_cols = wire_cols + [5, 6, 15, 16, 17, 18, 30, 31, 32, 33,
                                  45, 46, 47, 48, 60, 61, 62, 63,
                                  75, 76, 77, 78, 90, 91, 92, 93,
                                  107, 108, 109, 110, 111]

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in all_excl_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in all_excl_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scale active centers based on population
        if pop < 50:
            active_centers = [
                (60, 50), (50, 50), (70, 50),
                (60, 42), (60, 58), (50, 42), (70, 42), (50, 58), (70, 58),
                (40, 50), (80, 50), (60, 35), (60, 65),
            ]
        elif pop < 200:
            active_centers = []
            for row in range(4):
                for col in range(6):
                    cx = 15 + col * 18
                    cy = 15 + row * 22
                    active_centers.append((cx, cy))
        elif pop < 600:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 10 + col * 14
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 7 + col * 11
                    cy = 7 + row * 11
                    active_centers.append((cx, cy))
        else:
            # Full map dense coverage
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 1200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Ambitious city builder: multiple power plants, grid infrastructure, dense zones
# Combines Parent A's multi-plant grid with Parent B's closed-loop spine approach
# Strategy: 3 horizontal bands of zones, each with power + road grid

def init(obs, state):
    """Bootstrap: 3 coal plants + initial wire spines + flanking roads."""
    actions = []
    # Three power plants at different vertical bands
    # Center-left, center, center-right for coverage
    for px, py in [(30, 30), (60, 50), (90, 70)]:
        actions.append((Tool.COALPOWER, px, py))
    # Short wire spines seeded from each plant
    for px, py in [(30, 30), (60, 50), (90, 70)]:
        for dy in range(-3, 4):
            actions.append((Tool.WIRE, px + 2, py + dy))
        # Road flanking
        actions.append((Tool.ROAD, px + 1, py))
        actions.append((Tool.ROAD, px + 3, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)
    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.26:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # --- Power plant network ---
    # We want plants spread across the map to power all zones
    # Scale number of plants with population
    if pop < 100:
        target_plants = 3
    elif pop < 500:
        target_plants = 5
    elif pop < 1500:
        target_plants = 8
    elif pop < 3000:
        target_plants = 12
    else:
        target_plants = 16

    # Plant positions distributed across map
    plant_positions = [
        (30, 30), (60, 50), (90, 70),
        (90, 30), (30, 70), (60, 15), (60, 85),
        (15, 50), (105, 50), (15, 15), (105, 15),
        (15, 85), (105, 85), (45, 50), (75, 50), (60, 35)
    ]

    plant_ys, plant_xs = np.where(pm)
    existing_plants = list(zip(plant_xs.tolist(), plant_ys.tolist()))
    n_plants = len(plant_xs)

    # Place missing plants if needed
    if n_plants < target_plants:
        for ppx, ppy in plant_positions[:target_plants]:
            # Check if there's already a plant nearby
            already = any(abs(ex - ppx) < 8 and abs(ey - ppy) < 8 for ex, ey in existing_plants)
            if not already:
                if ib(ppx, ppy) and bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)
                # Try nearby empty spot
                for r in range(1, 10):
                    placed = False
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = ppx+dx, ppy+dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # --- Wire spine network: 3 main vertical spines + horizontal connectors ---
    # Vertical spines at x=30, 60, 90 (near each plant column)
    # Horizontal connectors every 15 rows
    spine_xs = [30, 60, 90]
    horiz_ys = [15, 30, 45, 60, 75, 90]

    # Determine spine extents based on population
    if pop < 100:
        y_top, y_bot = 25, 55
    elif pop < 300:
        y_top, y_bot = 15, 65
    elif pop < 800:
        y_top, y_bot = 8, 80
    else:
        y_top, y_bot = 3, 96

    # Build vertical wire spines
    if step % 6 in (0, 1):
        for sx in spine_xs:
            wire_col = sx + 2  # offset from plant
            for wy in range(y_top, y_bot + 1):
                if ib(wire_col, wy) and not bool(wm[wy, wire_col]) and not bool(pm[wy, wire_col]):
                    # Check adjacency to existing wire/plant
                    adj = False
                    for dy2 in [-1, 1]:
                        ny2 = wy + dy2
                        if ib(wire_col, ny2) and (bool(wm[ny2, wire_col]) or bool(pm[ny2, wire_col])):
                            adj = True
                    if adj or wy == y_top or wy == y_bot:
                        if bool(em[wy, wire_col]):
                            return (Tool.WIRE, wire_col, wy)

    # Build horizontal wire connectors between spines
    if step % 6 in (2, 3):
        for hy in horiz_ys:
            if hy < y_top or hy > y_bot:
                continue
            for wx in range(min(spine_xs) + 2, max(spine_xs) + 3):
                if ib(wx, hy) and not bool(wm[hy, wx]) and not bool(pm[hy, wx]):
                    left_ok = wx > 0 and (bool(wm[hy, wx-1]) or bool(pm[hy, wx-1]))
                    right_ok = wx < WORLD_W-1 and (bool(wm[hy, wx+1]) or bool(pm[hy, wx+1]))
                    if (left_ok or right_ok) and bool(em[hy, wx]):
                        return (Tool.WIRE, wx, hy)

    # Build roads flanking wire spines
    if step % 6 == 4:
        for sx in spine_xs:
            wire_col = sx + 2
            for road_col in [wire_col - 1, wire_col + 1]:
                if not ib(road_col, 0):
                    continue
                for wy in range(y_top, y_bot + 1):
                    if ib(road_col, wy) and bool(em[wy, road_col]) and not bool(pm[wy, road_col]):
                        # Only place if wire exists in this row
                        if bool(wm[wy, wire_col]) or bool(pm[wy, wire_col]):
                            return (Tool.ROAD, road_col, wy)

    # Build horizontal roads between spines
    if step % 6 == 5:
        for hy in horiz_ys:
            if hy < y_top - 2 or hy > y_bot + 2:
                continue
            for road_y in [hy - 1, hy + 1]:
                if not (0 < road_y < WORLD_H - 1):
                    continue
                for rx in range(min(spine_xs), max(spine_xs) + 5):
                    if ib(rx, road_y) and bool(em[road_y, rx]) and not bool(pm[road_y, rx]):
                        if bool(wm[hy, rx]) or bool(pm[hy, rx]):
                            return (Tool.ROAD, rx, road_y)

    # --- Civic services scaled with population ---
    if pop > 80:
        fire_locs = [(20, 20), (70, 20), (20, 60), (70, 60), (45, 40), (95, 40), (45, 80), (95, 80)]
        for fx, fy in fire_locs:
            if ib(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if pop > 300:
        police_locs = [(15, 35), (65, 35), (15, 75), (65, 75), (40, 55), (90, 55), (40, 15), (90, 15)]
        for plx, ply in police_locs:
            if ib(plx, ply) and bool(em[ply, plx]):
                return (Tool.POLICESTATION, plx, ply)

    if pop > 700:
        for stx, sty in [(25, 45), (75, 45), (50, 25), (100, 65), (50, 75)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(5, 5), (113, 5), (5, 93), (113, 93), (5, 50), (113, 50), (57, 5), (57, 93)]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for spx, spy in [(5, 90), (110, 90), (5, 10), (110, 10)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 3500:
        for apx, apy in [(45, 5), (45, 92), (5, 40), (110, 40)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- Zone placement: dense grid approach ---
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Candidate zones: near road AND near power, avoiding infrastructure
    cand = em & near_road & near_power
    # Keep away from borders
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False
    # Keep away from wire spines (avoid bulldozing infrastructure)
    for sx in spine_xs:
        wc = sx + 2
        cand[:, max(0, wc-1):wc+2] = False
    for hy in horiz_ys:
        cand[max(0, hy-1):hy+2, :] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Prioritize positions near power and road
        # Use multiple "neighborhood centers" spread across map
        centers = [(sx + 2 + offset*6, y)
                   for sx in spine_xs
                   for offset in [-3, -1, 1, 3]
                   for y in [20, 35, 50, 65, 80]
                   if ib(sx + 2 + offset*6, y)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy2) in centers:
            d = (np.abs(cxs - hx) + np.abs(cys - hy2)).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Slight randomization to avoid getting stuck
        offset_seed = (step * 7 + pop * 3 + step // 100) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset_seed + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # --- Parks for land value when zones are dense ---
    if pop > 200 and step % 3 == 0:
        park_cand = em & near_road & near_power
        pys2, pxs2 = np.where(park_cand)
        if len(pxs2) > 0:
            idx = (step * 31 + pop * 7) % len(pxs2)
            return (Tool.PARK, int(pxs2[idx]), int(pys2[idx]))

    # --- Extend roads from existing roads into powered areas ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11 + pop) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Extend wire network to unpowered areas ---
    # Find areas near roads but without power
    needs_power = near_road & ~near_power & ~em.__class__(em)  # areas with road but no power
    needs_power = near_road & ~near_power
    wneed_ys, wneed_xs = np.where(needs_power)
    if len(wneed_xs) > 0:
        # Find nearest wire/plant to bridge
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            idx2 = (step * 17) % len(wneed_xs)
            tx, ty = int(wneed_xs[idx2]), int(wneed_ys[idx2])
            dists2 = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
            best2 = np.argmin(dists2)
            bwx, bwy = int(wire_xs2[best2]), int(wire_ys2[best2])
            dx3 = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy3 = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nwx, nwy in [(bwx+dx3, bwy), (bwx, bwy+dy3)]:
                if ib(nwx, nwy) and bool(em[nwy, nwx]) and not bool(pm[nwy, nwx]):
                    return (Tool.WIRE, nwx, nwy)

    # --- Fallback: extend any wire ---
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13 + pop) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx4, ny4 = wx2+dx4, wy2+dy4
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    return (Tool.WIRE, nx4, ny4)

    # --- Last resort: place coal plant near any road without power ---
    if len(wneed_xs) > 0:
        idx3 = (step * 19) % len(wneed_xs)
        tx2, ty2 = int(wneed_xs[idx3]), int(wneed_ys[idx3])
        for r in range(1, 12):
            for dy5 in range(-r, r+1):
                for dx5 in range(-r, r+1):
                    if abs(dx5) == r or abs(dy5) == r:
                        nx5, ny5 = tx2+dx5, ty2+dy5
                        if ib(nx5, ny5) and bool(em[ny5, nx5]):
                            return (Tool.COALPOWER, nx5, ny5)

    return None

