                    cx, cy = gx + 10, gy + 10
                    for r in range(0, 12):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = cx + dx, cy + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # --- STEP 2: Extend wire grid reactively ---
    # Find wire rows that have gaps and fill them
    if step % 8 == 1:
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_has_wire = bool(np.any(wm[wr, :] | pm[wr, :]))
            if not row_has_wire:
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    if step % 8 == 2:
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_has_wire = bool(np.any(wm[:, wc] | pm[:, wc]))
            if not col_has_wire:
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # --- STEP 3: Extend road grid reactively ---
    if step % 8 == 3:
        for rr in road_rows:
            if rr >= WORLD_H or rr < 0:
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    adj = (rx > 0 and bool(rm[rr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or \
                          (rr > 0 and bool(rm[rr-1, rx])) or \
                          (rr < WORLD_H-1 and bool(rm[rr+1, rx]))
                    if adj or rx == 1:
                        return (Tool.ROAD, rx, rr)

    if step % 8 == 4:
        for rc in road_cols:
            if rc >= WORLD_W or rc < 0:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    adj = (ry > 0 and bool(rm[ry-1, rc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or \
                          (rc > 0 and bool(rm[ry, rc-1])) or \
                          (rc < WORLD_W-1 and bool(rm[ry, rc+1]))
                    if adj or ry == 1:
                        return (Tool.ROAD, rc, ry)

    # --- Wire unpowered zones ---
    if step % 8 == 5:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- Civic services ---
    # Fire stations: every ~20 tiles
    if pop > 10 and step % 8 == 6:
        for gy in range(5, 100, 18):
            for gx in range(5, 120, 18):
                x0, x1 = max(0, gx-9), min(120, gx+9)
                y0, y1 = max(0, gy-9), min(100, gy+9)
                has_fire = False
                # Check for fire station (use tile range heuristic via em)
                # We don't have a fire mask, just place if area seems empty of services
                # Use state to track placed fire stations
                if 'fire_placed' not in state:
                    state['fire_placed'] = set()
                key = (gx // 18, gy // 18)
                if key not in state['fire_placed']:
                    if bool(em[gy, gx]):
                        state['fire_placed'].add(key)
                        return (Tool.FIRESTATION, gx, gy)

    if pop > 50 and step % 8 == 7:
        for gy in range(8, 100, 22):
            for gx in range(8, 120, 22):
                if 'police_placed' not in state:
                    state['police_placed'] = set()
                key = (gx // 22, gy // 22)
                if key not in state['police_placed']:
                    if ib(gx, gy) and bool(em[gy, gx]):
                        state['police_placed'].add(key)
                        return (Tool.POLICESTATION, gx, gy)

    if pop > 200:
        stadium_spots = [
            (25, 15), (75, 15), (25, 45), (75, 45),
            (25, 75), (75, 75), (50, 30), (100, 30),
            (50, 60), (100, 60), (50, 85), (10, 50), (110, 50),
        ]
        if 'stadium_placed' not in state:
            state['stadium_placed'] = set()
        for sx, sy in stadium_spots:
            key = (sx, sy)
            if key not in state['stadium_placed'] and ib(sx, sy) and bool(em[sy, sx]):
                state['stadium_placed'].add(key)
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 20), (115, 20), (5, 80), (115, 80),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        if 'nuke_placed' not in state:
            state['nuke_placed'] = set()
        for nx2, ny2 in nuke_spots:
            key = (nx2, ny2)
            if key not in state['nuke_placed'] and ib(nx2, ny2) and bool(em[ny2, nx2]):
                state['nuke_placed'].add(key)
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 90), (115, 90), (5, 8), (115, 8)]
        if 'sea_placed' not in state:
            state['sea_placed'] = set()
        for sx, sy in seaports:
            if (sx, sy) not in state['sea_placed'] and ib(sx, sy) and bool(em[sy, sx]):
                state['sea_placed'].add((sx, sy))
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        if 'air_placed' not in state:
            state['air_placed'] = set()
        for ax, ay in airports:
            if (ax, ay) not in state['air_placed'] and ib(ax, ay) and bool(em[ay, ax]):
                state['air_placed'].add((ax, ay))
                return (Tool.AIRPORT, ax, ay)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- PRIMARY: Zone placement ---
    # Build candidate mask: empty, near road, near power
    cand_mask = em & near_road & near_power
    # Exclude borders
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    # Exclude wire/road rows (infrastructure corridors)
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            cand_mask[max(0, rr-1):min(WORLD_H, rr+2), :] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            cand_mask[:, max(0, rc-1):min(WORLD_W, rc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Reactively pick center of gravity near existing zones to grow outward
        # or spread evenly across powered+roaded areas
        if res_count + com_count + ind_count == 0:
            # No zones yet: start at center
            target_x, target_y = 60.0, 50.0
        else:
            # Find centroid of existing zones and spread outward
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                centroid_x = float(np.mean(zone_xs))
                centroid_y = float(np.mean(zone_ys))
                # Bias toward less-zoned areas: pick candidate far from centroid
                # but still close to infrastructure
                dists_from_center = np.abs(cxs - centroid_x) + np.abs(cys - centroid_y)
                # Mix: prefer moderate distance (spreading, not too far)
                target_dist = min(pop / 3.0 + 10.0, 60.0)
                score = -np.abs(dists_from_center - target_dist)
            else:
                score = np.zeros(len(cxs))
            order = np.argsort(-score)
            tool = pick_tool()
            offset = (step * 7 + pop * 3) % max(len(order), 1)
            for i in range(min(len(order), 500)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

        # Simple closest-to-target fallback
        tool = pick_tool()
        dists = np.abs(cxs - target_x) + np.abs(cys - target_y)
        order = np.argsort(dists)
        offset = (step * 7 + pop) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 5 coal plants spread across map with wire spines and flanking roads."""
    actions = []
    # Five starting plants: far-left, left-center, center, right-center, far-right
    for cx, cy in [(12, 50), (35, 50), (60, 50), (85, 50), (108, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Vertical wire spine
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Flanking roads
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Denser neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    nh_cols = [8, 20, 33, 46, 59, 72, 85, 98, 111, 118]
    nh_rows = [10, 22, 35, 48, 61, 74, 87, 97]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 5
        if pop < 150:   return 10
        if pop < 300:   return 18
        if pop < 600:   return 28
        if pop < 1200:  return 40
        if pop < 2500:  return 55
        if pop < 5000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood should have a plant within 10 tiles
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Find nearest empty spot for plant
        for r in range(15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (both vertical and horizontal) ----
    spine_range = 12

    # Prioritize hoods based on step rotation
    hood_order = [(idx_h, hx, hy) for idx_h, (hx, hy) in enumerate(active_hoods)]

    for idx_h, hx, hy in hood_order:
        if (step // 2 + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) * 2 // 3 + 1):
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap from plant neighbors
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Connect horizontal neighbors (multiple spacing options)
        for gap in [13, 15, 25]:
            hx2, hy2 = hx1 + gap, hy1
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        # Connect vertical neighbors
        for gap in [13, 15, 25]:
            hx2, hy2 = hx1, hy1 + gap
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step // 2 + idx_h * 3) % max(len(active_hoods), 1) >= max(1, len(active_hoods) * 2 // 3 + 1):
            continue

        # Flanking vertical spine (roads at hx-1 and hx+1)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Flanking horizontal spine (roads at hy-1 and hy+1)
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (more aggressive thresholds) ----
    if pop > 80:
        fire_spots = [
