def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Wire and road infrastructure columns/rows
    wire_cols = [30, 60, 90]
    wire_rows = [10, 30, 50, 70, 90]
    road_offset = 1  # roads are 1 away from wire

    # ---- INFRASTRUCTURE BUILDING ----
    phase = step % 10

    if phase == 0:
        # Ensure horizontal wire spines exist
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    # Check if adjacent to existing wire/plant
                    if (ib(wx-1, wr) and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))) or \
                       (ib(wx+1, wr) and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))):
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Ensure vertical wire spines exist
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    if (ib(wc, wy-1) and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or \
                       (ib(wc, wy+1) and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))):
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking horizontal wire rows
        for wr in wire_rows:
            for off in [-1, 1]:
                ry = wr + off
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Only place road if there's wire above/below
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking vertical wire cols
        for wc in wire_cols:
            for off in [-1, 1]:
                rcx = wc + off
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross roads at row bands between wire cols
        row_mids = [20, 40, 60, 80]
        for ry in row_mids:
            for rx in range(1, WORLD_W - 1):
                if ib(rx, ry) and bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    adj_road = (ib(rx-1, ry) and bool(rm[ry, rx-1])) or \
                               (ib(rx+1, ry) and bool(rm[ry, rx+1]))
                    if adj_road:
                        return (Tool.ROAD, rx, ry)

    elif phase == 5:
        # Add more power plants if population is growing and funds allow
        if pop > 500 and funds > 5000:
            # Check for unpowered zones
            unpowered = zone_tiles & ~near_power
            if np.any(unpowered):
                uys, uxs = np.where(unpowered)
                if len(uxs) > 0:
                    idx = step % len(uxs)
                    tx, ty = int(uxs[idx]), int(uys[idx])
                    # Place coal plant nearby
                    for r in range(5, 30):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx2, ny2 = tx + dx, ty + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        # Don't place on wire rows
                                        if ny2 not in wire_rows and nx2 not in wire_cols:
                                            return (Tool.COALPOWER, nx2, ny2)

    elif phase == 6:
        # Extend road network from existing roads
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (sk + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) \
                       and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase in (7, 8):
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT (closed-loop, every step) ----
    cand_mask = em & near_road & near_power
    # Avoid wire/road corridors and edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Prefer positions close to center of map (denser cluster)
        cx_center, cy_center = 60, 50
        dist_to_center = np.abs(cxs2 - cx_center).astype(float) + np.abs(cys2 - cy_center).astype(float)
        # Also prefer near existing zones (agglomeration)
        near_zones = dilate(zone_tiles, 4)
        zone_bonus = near_zones[cys2, cxs2].astype(float) * 10
        score = dist_to_center - zone_bonus
        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES (closed-loop based on pop) ----
    if pop > 100:
        fire_spots = [(15, 20), (55, 20), (95, 20), (15, 60), (55, 60), (95, 60),
                      (15, 80), (55, 80), (95, 80), (35, 40), (75, 40)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(20, 25), (60, 25), (100, 25), (20, 65), (60, 65), (100, 65),
                        (20, 85), (60, 85), (100, 85)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(45, 20), (75, 20), (45, 75), (75, 75)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [(5, 50), (113, 50), (5, 15), (113, 15), (5, 85), (113, 85)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(5, 5), (113, 5), (5, 93), (113, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 5), (70, 5), (50, 93), (70, 93)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 200 and step % 7 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: place a wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 11) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (sk2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

