def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.18:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- CLOSED-LOOP: find frontier tiles adjacent to wire/road/plant ---
    # Expand wire toward unpowered areas
    # Expand roads near wire
    # Place zones near roads+wire

    # Precompute neighbor masks
    def neighbor_mask(src, radius=1):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                if dx == 0 and dy == 0:
                    continue
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= src[sr0:sr1, sc0:sc1]
        return result

    power_src = wm | pm
    near_power = neighbor_mask(power_src, 1)
    near_road = neighbor_mask(rm, 2)
    near_power5 = neighbor_mask(power_src, 5)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Phase 1: Ensure enough power plants as city grows
    plant_count = int(np.sum(pm)) // 9  # approx (plants are 3x3)
    plant_count = max(1, int(np.sum(pm)) // 6)
    target_plants = 1 + pop // 80

    if plant_count < target_plants:
        # Place a new coal plant far from existing plants
        plant_ys, plant_xs = np.where(pm)
        # Try candidate locations spread across map
        candidates = [
            (20, 20), (100, 20), (20, 80), (100, 80),
            (60, 20), (60, 80), (20, 50), (100, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
            (30, 10), (90, 10), (30, 90), (90, 90),
        ]
        for (px, py) in candidates:
            if not ib(px, py):
                continue
            # Check distance from existing plants
            too_close = False
            for k in range(len(plant_xs)):
                dist = abs(plant_xs[k] - px) + abs(plant_ys[k] - py)
                if dist < 15:
                    too_close = True
                    break
            if not too_close and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # Phase 2: Extend wire from power sources to reach more area
    # Find empty cells adjacent to wire/plant that are not yet wired
    wire_frontier = em & near_power & ~pm
    wire_ys, wire_xs = np.where(wire_frontier)

    if len(wire_xs) > 0:
        # Prioritize extending toward areas with no power
        # Score: distance from nearest existing wire (prefer longer reach)
        # Use a subset for speed
        n = min(len(wire_xs), 500)
        step_k = (step * 7) % max(len(wire_xs), 1)
        indices = [(step_k + i * 3) % len(wire_xs) for i in range(n)]

        # Find wire locations not near road (we want to build roads there)
        # Prioritize wires that go toward unpowered zones
        best_wire = None
        best_score = -1

        # Check plant locations to extend wire toward them
        plant_ys_arr, plant_xs_arr = np.where(pm)

        for idx in indices[:200]:
            wx, wy = int(wire_xs[idx]), int(wire_ys[idx])
            # Score: how far is this from existing wires? (prefer extending)
            # Check all 4 dirs
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Extend wire if it leads somewhere useful
                    # Check if far corner has no wire
                    nx2, ny2 = nx+dx, ny+dy
                    if ib(nx2, ny2) and not bool(power_src[ny2, nx2]):
                        score = 1
                        if best_wire is None or score > best_score:
                            best_wire = (Tool.WIRE, nx, ny)
                            best_score = score

        # If no good extension found, just extend in any direction
        # to connect power plants
        if best_wire is None:
            # Connect plants to each other via wire
            if len(plant_xs_arr) >= 2:
                for i in range(len(plant_xs_arr)):
                    for j in range(i+1, len(plant_xs_arr)):
                        px1, py1 = int(plant_xs_arr[i]), int(plant_ys_arr[i])
                        px2, py2 = int(plant_xs_arr[j]), int(plant_ys_arr[j])
                        # Try to wire them together
                        # Walk from px1,py1 toward px2,py2
                        cx_w = px1
                        cy_w = py1
                        dx_w = 1 if px2 > px1 else -1
                        dy_w = 1 if py2 > py1 else -1
                        if px2 != px1:
                            step_to = cx_w + dx_w
                            if ib(step_to, cy_w) and bool(em[cy_w, step_to]) and not bool(pm[cy_w, step_to]):
                                return (Tool.WIRE, step_to, cy_w)
                        elif py2 != py1:
                            step_to = cy_w + dy_w
                            if ib(cx_w, step_to) and bool(em[step_to, cx_w]) and not bool(pm[step_to, cx_w]):
                                return (Tool.WIRE, cx_w, step_to)

    # Phase 3: Build roads near wire (roads parallel, 2 tiles away)
    # Find wire tiles and place roads 2 tiles away if empty
    wire_ys_arr, wire_xs_arr = np.where(wm)

    if len(wire_xs_arr) > 0:
        step_k2 = (step * 11) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 300)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            # Roads 2 tiles away perpendicularly
            for road_offset in [(-2, 0), (2, 0), (0, -2), (0, 2)]:
                rx, ry = wx + road_offset[0], wy + road_offset[1]
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Phase 4: Place zones near roads + wire
    cand_mask = em & near_road & near_power5
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        step_off = (step * 13) % max(len(cxs), 1)
        checked = 0
        for i in range(len(cxs)):
            k = (step_off + i) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # Phase 5: Extend roads from existing roads
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k3 = (step * 17) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 200)):
            k = (step_k3 + offset * 11) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = rx+dx, ry+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(near_power5[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # Phase 6: Civic buildings
    if pop > 50:
        fire_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 50), (50, 50), (90, 50),
            (10, 88), (50, 88), (90, 88),
            (30, 30), (70, 30), (30, 70), (70, 70),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (15, 15), (55, 15), (95, 15),
            (15, 55), (55, 55), (95, 55),
            (15, 85), (55, 85), (95, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for sx, sy in [(25, 6), (65, 6), (105, 6), (25, 93), (65, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        for nx2, ny2 in [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Phase 7: Parks near zones
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 5 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
                    nx2, ny2 = zx2+dx2, zy2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # Fallback: extend wire from any wire tile
    if len(wire_xs_arr) > 0:
        step_k4 = (step * 19) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k4 + offset * 7) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire+road grid to kick things off."""
    actions = []
    # Two plants: left-center and right-center
    for cx, cy in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Vertical wire spine
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Horizontal wire
        for dx in range(-5, 6):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        # Flanking roads
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 2, cy + dy))
            actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Denser grid of neighborhoods: more columns, different rows
    # 10 cols x 7 rows = 70 neighborhoods
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [10, 22, 35, 50, 65, 78, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 300:   return 14
        if pop < 600:   return 22
        if pop < 1200:  return 32
        if pop < 2500:  return 45
        if pop < 5000:  return 58
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        # More aggressive commercial/industrial ratio for city growth
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 25% industrial, 35% commercial, 40% residential
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS per neighborhood cluster ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(14):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: CROSS-SHAPED WIRE SPINES (vertical + horizontal) ----
    spine_range = 10

    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Rotate to spread work
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap wire from plant
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Horizontal neighbors at spacing 12
        for (hx2, hy2) in [(hx1 + 12, hy1), (hx1 + 12, hy1)]:
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        # Vertical neighbors
        for (hx2, hy2) in [(hx1, hy1 + 13), (hx1, hy1 + 15)]:
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS - grid pattern around each hood ----
    # Place roads at offsets -3,-2,+2,+3 from wire spine (both axes)
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 2) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Vertical roads flanking wire spine at hx
        for rx in [hx - 2, hx + 2, hx - 4, hx + 4]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only if there's wire/plant nearby (powered area)
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Horizontal roads flanking wire spine at hy
        for ry2 in [hy - 2, hy + 2, hy - 4, hy + 4]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT with road+power proximity ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road coverage mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary offset to spread placement
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (earlier thresholds for better city services) ----
    if pop > 80:
        fire_spots = [
            (8, 10), (28, 10), (50, 10), (72, 10), (94, 10), (114, 10),
            (8, 30), (28, 30), (50, 30), (72, 30), (94, 30), (114, 30),
            (8, 50), (28, 50), (50, 50), (72, 50), (94, 50), (114, 50),
            (8, 70), (28, 70), (50, 70), (72, 70), (94, 70), (114, 70),
            (8, 90), (28, 90), (50, 90), (72, 90), (94, 90), (114, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (15, 18), (45, 18), (75, 18), (105, 18),
            (15, 42), (45, 42), (75, 42), (105, 42),
            (15, 62), (45, 62), (75, 62), (105, 62),
            (15, 82), (45, 82), (75, 82), (105, 82),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (80, 30), (30, 65), (80, 65),
            (55, 10), (55, 88), (5, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (58, 5), (58, 95), (5, 50), (115, 50),
            (28, 5), (88, 5), (28, 95), (88, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(8, 92), (112, 92), (8, 6), (112, 6), (58, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(48, 5), (70, 5), (48, 92), (70, 92), (5, 46), (113, 46)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones for land value boost ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 5 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (2, 2), (-2, 2), (2, -2), (-2, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 23) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + cross wire + road grid"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [15, 40, 65, 90, 110]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows (above and below)
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
            actions.append((Tool.ROAD, x, wy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    WIRE_ROWS = [25, 50, 75]
    WIRE_COLS = [15, 40, 65, 90, 110]
    ROAD_OFFSETS = [-2, 2]

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.22:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.38:
                return Tool.COMMERCIAL
            if rr < 0.42:
                return Tool.RESIDENTIAL
            return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- 1. Fix missing wire on key rows (close gaps reactively) ---
    if step % 6 == 0:
        for wr in WIRE_ROWS:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = (wx > 0) and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = (wx < WORLD_W-1) and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # --- 2. Fix missing wire on key cols ---
    if step % 6 == 1:
        for wc in WIRE_COLS:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = (wy2 > 0) and (bool(wm[wy2-1, wc]) or bool(pm[wy2-1, wc]))
                    dn = (wy2 < WORLD_H-1) and (bool(wm[wy2+1, wc]) or bool(pm[wy2+1, wc]))
                    if up or dn:
                        if bool(em[wy2, wc]):
                            return (Tool.WIRE, wc, wy2)

    # --- 3. Fix roads flanking wire rows ---
    if step % 6 == 2:
        for wr in WIRE_ROWS:
            for offset in ROAD_OFFSETS:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                               (ry > 0 and bool(rm[ry-1, rx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                        if adj or rx <= 2:
                            return (Tool.ROAD, rx, ry)

    # --- 4. Fix roads flanking wire cols ---
    if step % 6 == 3:
        for wc in WIRE_COLS:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                               bool(rm[ry, max(0, rcx-1)]) or
                               bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                        if adj or ry <= 2:
                            return (Tool.ROAD, rcx, ry)

    # --- 5. Reactively wire unpowered zones ---
    if step % 6 == 4:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 60)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # --- 6. Reactively road unroaded zones ---
    if step % 6 == 5:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- Reactive power plant placement if region lacks coverage ---
    if step % 10 == 7:
        plant_targets = []
        for py in range(12, WORLD_H - 5, 20):
            for px in range(12, WORLD_W - 5, 22):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 11), min(WORLD_W, px + 12)
            y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # --- Civic services (pop-gated) ---
    if pop > 20:
        fire_spots = [
            (8, 8), (38, 8), (68, 8), (98, 8), (112, 8),
            (8, 35), (112, 35), (8, 60), (112, 60),
            (8, 85), (38, 85), (68, 85), (98, 85), (112, 85),
            (40, 50), (70, 50), (25, 25), (55, 25), (85, 25),
            (25, 75), (55, 75), (85, 75), (100, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (22, 15), (52, 15), (82, 15), (108, 15),
            (22, 38), (52, 38), (82, 38), (108, 38),
            (22, 62), (52, 62), (82, 62), (108, 62),
            (22, 85), (52, 85), (82, 85), (108, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (30, 15), (90, 15), (30, 85), (90, 85),
            (60, 50), (15, 50), (105, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (8, 50), (112, 50), (60, 5), (60, 95),
            (8, 20), (112, 20), (8, 80), (112, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 93), (70, 93)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 60 and step % 9 == 3:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- Zone placement: find candidates near power and road ---
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire infrastructure rows/cols (tight margin)
    for wr in WIRE_ROWS:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in WIRE_COLS:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Choose active centers based on population phase
        if pop < 200:
            active_centers = [
                (52, 35), (52, 62), (28, 35), (28, 62),
                (78, 35), (78, 62), (52, 50), (30, 50), (75, 50),
                (52, 15), (52, 85), (15, 50), (100, 50),
            ]
        elif pop < 800:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 12 + col * 16
                    cy = 10 + row * 18
                    active_centers.append((cx, cy))
        else:
            # Dense saturation
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 7 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary starting position to avoid always retrying the same spot
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road toward powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

