def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        arr = result.copy()
        for d in range(1, r + 1):
            result[d:, :] |= arr[:-d, :]
            result[:-d, :] |= arr[d:, :]
            result[:, d:] |= arr[:, :-d]
            result[:, :-d] |= arr[:, d:]
        return result

    # Power and road reach
    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Wire and road corridors
    wire_rows = [20, 50, 78]
    wire_cols = [30, 88]

    def zone_clear(zx, zy):
        """Check 3x3 centered at zx,zy is clear (only empty or zone tiles)"""
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # --- STEP 1: Ensure power plants are well distributed ---
    # If any region far from power, add a coal plant
    if step % 20 == 1:
        # Check for large unpowered areas
        unpow_ys, unpow_xs = np.where(~near_power & em)
        if len(unpow_xs) > 50:
            # Find centroid of unpowered region
            cx = int(np.median(unpow_xs))
            cy = int(np.median(unpow_ys))
            # Find empty spot near centroid
            for r in range(2, 20):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = cx+dx, cy+dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)

    # --- STEP 2: Extend wire network reactively ---
    # Find wire endpoints (wire tiles with fewer than 2 wire neighbors)
    # and extend toward unpowered zones
    if step % 4 in (0, 1):
        # Find unpowered empty tiles that have road access
        need_power = (~near_power) & em & near_road
        npys, npxs = np.where(need_power)
        if len(npxs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(npxs)
                tx, ty = int(npxs[idx]), int(npys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                # Try to step closer
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- STEP 3: Extend road network reactively ---
    if step % 4 == 2:
        # Find powered empty tiles without road access - extend road toward them
        need_road = near_power & em & (~near_road)
        nrys, nrxs = np.where(need_road)
        if len(nrxs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 13) % len(nrxs)
                tx, ty = int(nrxs[idx]), int(nrys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- STEP 4: Extend road from existing roads into powered area ---
    if step % 4 == 3:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (sk + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- ZONE PLACEMENT: scan for best zone location ---
    cand_mask = em & near_road & near_power
    # Avoid placing zones on wire/road corridors
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    # Keep corridors free (wire rows/cols ±1)
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        tool = pick_tool()
        # Try to place near existing zones (cluster building)
        if res_count + com_count + ind_count > 0:
            zone_ys_a, zone_xs_a = np.where(zone_tiles)
            best_dist = np.full(len(cxs2), 999999.0)
            # Sample some zone tiles to compute distance from
            sample_n = min(20, len(zone_xs_a))
            sample_idx = np.linspace(0, len(zone_xs_a)-1, sample_n, dtype=int)
            for si in sample_idx:
                zxa, zya = int(zone_xs_a[si]), int(zone_ys_a[si])
                d = np.abs(cxs2 - zxa).astype(float) + np.abs(cys2 - zya).astype(float)
                best_dist = np.minimum(best_dist, d)
            order = np.argsort(best_dist)
        else:
            # Start near center
            d = np.abs(cxs2 - 59).astype(float) + np.abs(cys2 - 50).astype(float)
            order = np.argsort(d)

        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(len(order)):
            k = order[(i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- CIVIC SERVICES (reactive, only when useful) ---
    if pop > 100:
        fire_spots = [(10, 15), (58, 10), (108, 15),
                      (10, 40), (58, 40), (108, 40),
                      (10, 65), (58, 65), (108, 65),
                      (10, 88), (58, 88), (108, 88)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(15, 25), (58, 25), (100, 25),
                        (15, 60), (58, 60), (100, 60),
                        (15, 85), (58, 85), (100, 85)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(45, 35), (75, 35), (45, 65), (75, 65)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [(59, 5), (5, 50), (113, 50), (59, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(5, 5), (113, 5), (5, 93), (113, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 200 and step % 7 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend wire from existing wire toward center of map
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (sk2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Absolute fallback: road near any zone
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Dense grid layout with alternating road/wire columns and rows
# Zones placed in blocks between road grid, progressive expansion
# Focus on compact, well-connected neighborhoods with strong commercial presence

def init(obs, state):
    """Bootstrap: two coal plants + wire connections + initial road grid."""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire connecting them horizontally
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Seed roads at y=49, y=51
    for x in range(35, 85, 4):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Grid-based city layout:
    # Road columns at x = 10, 18, 26, 34, 42, 50, 58, 66, 74, 82, 90, 98, 106
    # Wire columns at x = 14, 22, 30, 38, 46, 54, 62, 70, 78, 86, 94, 102, 110
    # Road rows at y = 10, 18, 26, 34, 42, 50, 58, 66, 74, 82, 90
    # Zones fill 3x3 cells between roads

    road_cols = list(range(10, 115, 8))   # ~13 road columns
    wire_cols = [c + 4 for c in road_cols if c + 4 < WORLD_W]  # wire between roads
    road_rows = list(range(10, 95, 8))   # ~11 road rows

    # Progressive unlock based on population
    def active_region():
        if pop < 100:
            # Central region only
            return (32, 64, 34, 66)  # xmin, xmax, ymin, ymax
        elif pop < 300:
            return (24, 72, 26, 74)
        elif pop < 600:
            return (16, 88, 18, 82)
        elif pop < 1200:
            return (10, 96, 10, 90)
        else:
            return (10, 110, 10, 90)

    xmin, xmax, ymin, ymax = active_region()

    # ---- PHASE 1: ENSURE POWER PLANTS are placed ----
    # We want plants at regular intervals within active region
    plant_xs = [int(x) for x in np.arange(max(xmin, 40), min(xmax, 90), 25)]
    plant_ys = [50]
    if pop > 400:
        plant_ys = [30, 50, 70]
    if pop > 1000:
        plant_xs = [int(x) for x in np.arange(max(xmin, 20), min(xmax, 105), 20)]

    for py in plant_ys:
        for px in plant_xs:
            if not ib(px, py):
                continue
            # Check if there's a plant nearby
            x0 = max(0, px - 12); x1 = min(WORLD_W, px + 13)
            y0 = max(0, py - 12); y1 = min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                if bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: WIRE GRID ----
    # Wire along wire_cols within active region
    for wc in wire_cols:
        if wc < xmin or wc > xmax:
            continue
        # Vertical wire from ymin to ymax
        for wy in range(ymin, ymax + 1):
            if not ib(wc, wy):
                continue
            if bool(pm[wy, wc]):
                continue
            if bool(wm[wy, wc]):
                continue
            if not bool(em[wy, wc]):
                continue
            # Check if adjacent wire or plant exists to connect to
            has_adj = False
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                    has_adj = True
            if has_adj:
                return (Tool.WIRE, wc, wy)

    # Wire horizontally connecting plants to wire columns at plant y-levels
    for py in plant_ys:
        if py < ymin or py > ymax:
            continue
        for wx in range(xmin, xmax + 1):
            if not ib(wx, py):
                continue
            if bool(pm[py, wx]):
                continue
            if bool(wm[py, wx]):
                continue
            if not bool(em[py, wx]):
                continue
            has_adj = False
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, py) and (bool(wm[py, ax]) or bool(pm[py, ax])):
                    has_adj = True
            if has_adj:
                return (Tool.WIRE, wx, py)

    # ---- PHASE 3: ROAD GRID ----
    active_road_cols = [c for c in road_cols if xmin <= c <= xmax]
    active_road_rows = [r for r in road_rows if ymin <= r <= ymax]

    # Build road columns
    for rc in active_road_cols:
        for ry in range(ymin, ymax + 1):
            if not ib(rc, ry):
                continue
            if bool(rm[ry, rc]):
                continue
            if bool(pm[ry, rc]) or bool(wm[ry, rc]):
                continue
            if not bool(em[ry, rc]):
                continue
            # Place road if there's adjacent road
            has_adj = False
            for adj in [-1, 1]:
                ay = ry + adj
                if ib(rc, ay) and bool(rm[ay, rc]):
                    has_adj = True
            # Or if it's at a row intersection
            if ry in active_road_rows:
                has_adj = True
            if has_adj:
                return (Tool.ROAD, rc, ry)

    # Build road rows
    for rr in active_road_rows:
        for rx in range(xmin, xmax + 1):
            if not ib(rx, rr):
                continue
            if bool(rm[rr, rx]):
                continue
            if bool(pm[rr, rx]) or bool(wm[rr, rx]):
                continue
            if not bool(em[rr, rx]):
                continue
            has_adj = False
            for adj in [-1, 1]:
                ax = rx + adj
                if ib(ax, rr) and bool(rm[rr, ax]):
                    has_adj = True
            if has_adj:
                return (Tool.ROAD, rx, rr)

    # ---- COMPUTE NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 4: ZONE PLACEMENT ----
    # Target mix: 35% RES, 35% COM, 30% IND (more commercial than parent)
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Zone candidates: empty, near road, near power, within active region
    cand_mask = em & nbr_road & nbr_power
    cand_mask[:ymin, :] = False
    cand_mask[ymax:, :] = False
    cand_mask[:, :xmin] = False
    cand_mask[:, xmax:] = False
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    # Avoid placing on road columns/rows
    for rc in road_cols:
        if ib(rc, 0):
            cand_mask[:, rc] = False
    for rr in road_rows:
        cand_mask[rr, :] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize center of map for compact growth
        cx_center = (xmin + xmax) / 2
        cy_center = (ymin + ymax) / 2
        dist_center = np.abs(cxs - cx_center) + np.abs(cys - cy_center)
        order = np.argsort(dist_center)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        for fx in range(20, WORLD_W, 25):
            for fy in range(20, WORLD_H, 25):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 400:
        for px2 in range(22, WORLD_W, 28):
            for py2 in range(22, WORLD_H, 28):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 800:
        for sx in [30, 60, 90]:
            for sy in [25, 50, 75]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuclear_spots = [(20, 20), (100, 20), (20, 80), (100, 80), (60, 15), (60, 85)]
        for (nx, ny) in nuclear_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 6), (70, 6), (50, 93), (70, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 13) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: extend roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross outward
    for d in range(1, 10):
        for dx, dy in [(d,0),(-d,0),(0,d),(0,-d)]:
            nx, ny = cx+dx, cy+dy
            if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                actions.append((Tool.WIRE, nx, ny))
    # Roads flanking the vertical spine
    for dy in range(-8, 9):
        for rdx in [-1, 1]:
            actions.append((Tool.ROAD, cx+rdx, cy+dy))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Neighborhood grid: 10 cols x 8 rows
    nh_cols = list(range(8, 115, 11))
    nh_rows = list(range(8, 95, 11))
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 6
        if pop < 200:  return 15
        if pop < 500:  return 28
        if pop < 1000: return 45
        if pop < 2000: return 60
        if pop < 4000: return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # --- Build power and road neighbor masks ---
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            if abs(dx) + abs(dy) > 6: continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # --- PHASE 1: Ensure each active hood has power plant or wire connection ---
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx-10), min(WORLD_W, hx+11)
        y0, y1 = max(0, hy-10), min(WORLD_H, hy+11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            nearby_z = int(np.sum(zone_tiles[y0:y1, x0:x1]))
                            use_nuke = nearby_z > 20 and funds > 10000
                            tool_p = Tool.NUCLEARPOWER if use_nuke else Tool.COALPOWER
                            return (tool_p, nx, ny)

    spine_r = 9

    # --- PHASE 2: Wire spines from each hood center (extend adjacent to existing wire/plant) ---
    for (hx, hy) in active_hoods:
        # Vertical spine
        for dy in range(-spine_r, spine_r+1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal spine
        for dx in range(-spine_r, spine_r+1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adx in [-1, 1]:
                ax = wx + adx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # --- PHASE 3: Connect neighboring hoods with wire ---
    row_to_hoods = {}
    col_to_hoods = {}
    for (hx, hy) in active_hoods:
        row_to_hoods.setdefault(hy, []).append(hx)
        col_to_hoods.setdefault(hx, []).append(hy)

    for hy, hxs in row_to_hoods.items():
        for i in range(len(sorted(hxs)) - 1):
            hx1, hx2 = sorted(hxs)[i], sorted(hxs)[i+1]
            for cx in range(hx1+1, hx2):
                if not ib(cx, hy): continue
                if bool(wm[hy, cx]) or bool(pm[hy, cx]): continue
                if not bool(em[hy, cx]): continue
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, cx, hy)

    for hx, hys in col_to_hoods.items():
        for i in range(len(sorted(hys)) - 1):
            hy1, hy2 = sorted(hys)[i], sorted(hys)[i+1]
            for cy in range(hy1+1, hy2):
                if not ib(hx, cy): continue
                if bool(wm[cy, hx]) or bool(pm[cy, hx]): continue
                if not bool(em[cy, hx]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, cy)

    # --- PHASE 4: Roads flanking wire spines ---
    for (hx, hy) in active_hoods:
        # Roads parallel to vertical spine
        for rx in [hx-1, hx+1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r+1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]): continue
                if bool(pm[ry, rx]): continue
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)
        # Roads parallel to horizontal spine
        for ry2 in [hy-1, hy+1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r+1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]): continue
                if bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # --- PHASE 5: Zone placement ---
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: Extend roads into powered empty areas ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: Civic services ---
    if pop > 40:
        fire_spots = [
            (20,20),(50,20),(80,20),(110,20),
            (20,45),(50,45),(80,45),(110,45),
            (20,70),(50,70),(80,70),(110,70),
            (20,90),(50,90),(80,90),(110,90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (30,15),(65,15),(100,15),
            (15,40),(50,40),(85,40),(115,40),
            (30,65),(65,65),(100,65),
            (15,85),(50,85),(85,85),(115,85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(30,30),(70,30),(110,30),(30,60),(70,60),(110,60),(30,85),(70,85)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        for (sx, sy) in [(5,90),(115,90),(5,5),(115,5),(60,5),(60,95)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        for (sx, sy) in [(40,5),(80,5),(40,94),(80,94)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- Parks for land value boost ---
    if pop > 80 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 37 + pop) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # --- Fallback: extend wire from existing wire ---
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % len(wire_xs)
        for offset in range(min(len(wire_xs), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- Fallback: place plant near uncovered active hood ---
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire grid + initial roads."""
    actions = []
    # Two plants for redundancy
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire connecting the two plants horizontally
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for d in range(1, 8):
        actions.append((Tool.WIRE, 40, 50 + d))
        actions.append((Tool.WIRE, 40, 50 - d))
        actions.append((Tool.WIRE, 80, 50 + d))
        actions.append((Tool.WIRE, 80, 50 - d))
    # Initial roads flanking the plants
    for d in range(-6, 7):
        actions.append((Tool.ROAD, 39, 50 + d))
        actions.append((Tool.ROAD, 41, 50 + d))
        actions.append((Tool.ROAD, 79, 50 + d))
        actions.append((Tool.ROAD, 81, 50 + d))
    return actions[:20]  # keep init small


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    pz = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- Dynamic neighborhood grid based on current map state ---
    # Start with a moderate grid, expand as population grows
    if pop < 200:
        hood_cols = [40, 80]
        hood_rows = [50]
    elif pop < 600:
        hood_cols = [25, 55, 85]
        hood_rows = [35, 65]
    elif pop < 1500:
        hood_cols = [20, 45, 70, 95]
        hood_rows = [25, 50, 75]
    elif pop < 3000:
        hood_cols = [15, 35, 55, 75, 95]
        hood_rows = [20, 40, 60, 80]
    else:
        hood_cols = [12, 28, 44, 60, 76, 92, 108]
        hood_rows = [12, 28, 44, 60, 76, 90]

    all_hoods = [(cx, cy) for cx in hood_cols for cy in hood_rows]

    # --- PHASE 1: ENSURE EACH ACTIVE HOOD HAS A PLANT ---
    for (hx, hy) in all_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try placing plant at hood center or nearby empty spot
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: EXTEND WIRE FROM EXISTING PLANTS/WIRES ---
    # Find all plant cells and extend wires toward hood centers
    plant_ys, plant_xs = np.where(pm)

    for (hx, hy) in all_hoods:
        # Find nearest plant to this hood
        if len(plant_xs) == 0:
            break
        dists = np.abs(plant_xs - hx) + np.abs(plant_ys - hy)
        best_idx = np.argmin(dists)
        px_abs = int(plant_xs[best_idx])
        py_abs = int(plant_ys[best_idx])

        # Extend wire from plant toward hood center (if far)
        # Also extend wire in 4 cardinal directions from plant
        reach = 16
        for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            ddx, ddy = direction
            for dist in range(1, reach + 1):
                wx = px_abs + ddx * dist
                wy = py_abs + ddy * dist
                if not ib(wx, wy):
                    break
                if bool(pm[wy, wx]):
                    break  # another plant, stop
                if not bool(wm[wy, wx]):
                    if bool(em[wy, wx]):
                        return (Tool.WIRE, wx, wy)
                    elif bool(rm[wy, wx]):
                        return (Tool.WIRE, wx, wy)
                    else:
                        break  # blocked

    # --- PHASE 3: CONNECT WIRE BETWEEN HOODS (horizontal then vertical) ---
    # Scan for gaps in horizontal wire connections between adjacent hoods
    for i in range(len(all_hoods)):
        hx1, hy1 = all_hoods[i]
        for j in range(len(all_hoods)):
            hx2, hy2 = all_hoods[j]
            if hx2 <= hx1 or abs(hy1 - hy2) > 5:
                continue
            # Try to bridge wire at the shared row
            bridge_y = (hy1 + hy2) // 2
            # Find rightmost wire left of midpoint and leftmost wire right
            mid = (hx1 + hx2) // 2
            # Scan for wire gap
            for bx in range(hx1, hx2 + 1):
                if ib(bx, bridge_y) and not bool(wm[bridge_y, bx]) and not bool(pm[bridge_y, bx]):
                    if bool(em[bridge_y, bx]):
                        # Check if adjacent to existing wire or plant
                        adj_powered = False
                        for adx in [-1, 1, 0, 0]:
                            ady = 0 if adx != 0 else -1
                            if adx == 0 and ady == 0:
                                ady = 1
                            ax, ay = bx + adx, bridge_y + ady
                            if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                                adj_powered = True
                                break
                        if adj_powered:
                            return (Tool.WIRE, bx, bridge_y)

    # Vertical connections
    for i in range(len(all_hoods)):
        hx1, hy1 = all_hoods[i]
        for j in range(len(all_hoods)):
            hx2, hy2 = all_hoods[j]
            if hy2 <= hy1 or abs(hx1 - hx2) > 5:
                continue
            bridge_x = (hx1 + hx2) // 2
            for by in range(hy1, hy2 + 1):
                if ib(bridge_x, by) and not bool(wm[by, bridge_x]) and not bool(pm[by, bridge_x]):
                    if bool(em[by, bridge_x]):
                        adj_powered = False
                        for ady in [-1, 1]:
                            ay = by + ady
                            if ib(bridge_x, ay) and (bool(wm[ay, bridge_x]) or bool(pm[ay, bridge_x])):
                                adj_powered = True
                                break
                        if adj_powered:
                            return (Tool.WIRE, bridge_x, by)

    # --- PHASE 4: BUILD ROAD NETWORK ADJACENT TO WIRE ---
    # Build "near wire" mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-1, 2):
        for ddx in range(-1, 2):
            r0s = max(0, -ddy); r1s = min(WORLD_H, WORLD_H - ddy)
            c0s = max(0, -ddx); c1s = min(WORLD_W, WORLD_W - ddx)
            r0d = max(0, ddy); r1d = min(WORLD_H, WORLD_H + ddy)
            c0d = max(0, ddx); c1d = min(WORLD_W, WORLD_W + ddx)
            nbr_wire[r0d:r1d, c0d:c1d] |= wm[r0s:r1s, c0s:c1s]
            nbr_wire[r0d:r1d, c0d:c1d] |= pm[r0s:r1s, c0s:c1s]

    # Build "near road" mask (within 2)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-2, 3):
        for ddx in range(-2, 3):
            r0s = max(0, -ddy); r1s = min(WORLD_H, WORLD_H - ddy)
            c0s = max(0, -ddx); c1s = min(WORLD_W, WORLD_W - ddx)
            r0d = max(0, ddy); r1d = min(WORLD_H, WORLD_H + ddy)
            c0d = max(0, ddx); c1d = min(WORLD_W, WORLD_W + ddx)
            nbr_road[r0d:r1d, c0d:c1d] |= rm[r0s:r1s, c0s:c1s]

    # Build "near power" mask (within 3)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-3, 4):
        for ddx in range(-3, 4):
            r0s = max(0, -ddy); r1s = min(WORLD_H, WORLD_H - ddy)
            c0s = max(0, -ddx); c1s = min(WORLD_W, WORLD_W - ddx)
            r0d = max(0, ddy); r1d = min(WORLD_H, WORLD_H + ddy)
            c0d = max(0, ddx); c1d = min(WORLD_W, WORLD_W + ddx)
            nbr_power[r0d:r1d, c0d:c1d] |= wm[r0s:r1s, c0s:c1s]
            nbr_power[r0d:r1d, c0d:c1d] |= pm[r0s:r1s, c0s:c1s]

    # For each hood, build roads flanking the wire axis
    for (hx, hy) in all_hoods:
        # Find the plant near this hood
        if len(plant_xs) == 0:
            break
        dists = np.abs(plant_xs - hx) + np.abs(plant_ys - hy)
        best_idx = np.argmin(dists)
        px_abs = int(plant_xs[best_idx])
        py_abs = int(plant_ys[best_idx])

        reach = 16
        # Roads flanking vertical wire from plant (px_abs ± 1)
        for rx_off in [-1, 1]:
            rx = px_abs + rx_off
            if not ib(rx, py_abs):
                continue
            for dist in range(-reach, reach + 1):
                ry = py_abs + dist
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only if there's wire at the spine position
                    if ib(px_abs, ry) and (bool(wm[ry, px_abs]) or bool(pm[ry, px_abs])):
                        return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal wire from plant (py_abs ± 1)
        for ry_off in [-1, 1]:
            ry = py_abs + ry_off
            if not ib(hx, ry):
                continue
            for dist in range(-reach, reach + 1):
                rxc = px_abs + dist
                if not ib(rxc, ry):
                    continue
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    if ib(rxc, py_abs) and (bool(wm[py_abs, rxc]) or bool(pm[py_abs, rxc])):
                        return (Tool.ROAD, rxc, ry)

    # --- PHASE 5: EXTEND ROADS from existing road network ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 60)):
            k = (sk + off * 3) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2])
                        and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 6: ZONE PLACEMENT ---
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 45% res, 30% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                # Allow empty or existing zone tiles
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in all_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset_base = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(offset_base + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- PHASE 7: CIVIC SERVICES (reactive to pop thresholds) ---
    if pop > 100:
        fire_spots = [(20, 20), (60, 20), (100, 20),
                      (20, 50), (60, 50), (100, 50),
                      (20, 80), (60, 80), (100, 80),
                      (40, 35), (80, 35), (40, 65), (80, 65)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [(30, 30), (70, 30), (30, 70), (70, 70),
                        (50, 20), (50, 80), (10, 50), (110, 50)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(30, 45), (70, 45), (30, 65), (70, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(55, 5), (55, 90), (5, 50)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- PHASE 8: PARKS (improve land value) ---
    if pop > 200 and step % 5 == 0:
        pk_cands = np.where(em & nbr_road & nbr_power)
        if len(pk_cands[0]) > 0:
            idx = (step * 17) % len(pk_cands[0])
            py2, px2 = int(pk_cands[0][idx]), int(pk_cands[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- PHASE 9: EXTEND WIRE from existing wire to fill gaps ---
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        sk2 = (step * 13) % len(wire_xs)
        for off in range(min(len(wire_xs), 50)):
            k = (sk2 + off * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    # Only extend toward a hood
                    if any(abs(nx3 - hx) + abs(ny3 - hy) < 20 for hx, hy in all_hoods):
                        return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants centered, wire cross, initial roads"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Horizontal wire at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire at x=40 and x=80
    for y in range(1, 99):
        actions.append((Tool.WIRE, 40, y))
        actions.append((Tool.WIRE, 80, y))
    # Roads flanking main wire row
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Wire grid: horizontal rows and vertical columns
    # Different from parent: denser vertical wires, fewer horizontal
    wire_rows = [15, 30, 45, 60, 75, 90]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    def pick_tool():
        # Target: 40% res, 30% com, 30% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if pop < 100:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.28:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # More commercial late game
            if cr < 0.35:
                return Tool.COMMERCIAL
            if ir < 0.25:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # INFRASTRUCTURE: wire rows
    if step % 8 == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    if step % 8 == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ROADS flanking wire rows (above and below)
    if step % 8 == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  (ry > 0 and bool(rm[ry-1, rx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # ROADS flanking wire cols (left and right)
    if step % 8 == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # POWER PLANTS: reactive placement
    if step % 8 == 4:
        plant_targets = []
        for py in range(10, WORLD_H - 5, 20):
            for px in range(10, WORLD_W - 5, 20):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # WIRE to unpowered zones
    if step % 8 == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ROAD to unroaded zones
    if step % 8 == 6:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bwy else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # CIVIC SERVICES (pop-gated, reactive)
    if pop > 20:
        fire_spots = [
            (10, 10), (60, 10), (110, 10),
            (10, 35), (60, 35), (110, 35),
            (10, 60), (60, 60), (110, 60),
            (10, 85), (60, 85), (110, 85),
            (35, 22), (85, 22), (35, 72), (85, 72),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (112, 15),
            (25, 40), (55, 40), (85, 40), (112, 40),
            (25, 65), (55, 65), (85, 65), (112, 65),
            (25, 88), (55, 88), (85, 88), (112, 88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (20, 22), (65, 22), (100, 22),
            (20, 65), (65, 65), (100, 65),
            (42, 42), (42, 82), (88, 42), (88, 82),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        # Nuclear plants for more power
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 20), (115, 20), (5, 80), (115, 80),
            (30, 10), (90, 10), (30, 90), (90, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks occasionally for land value
    if pop > 80 and step % 11 == 5:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ZONE PLACEMENT (closed-loop, reacts to pop)
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Use a neighborhood grid that expands with population
        if pop < 150:
            # Start with 3 compact neighborhoods around the center
            active_centers = [
                (60, 50), (45, 40), (75, 40),
                (45, 60), (75, 60), (60, 30), (60, 70),
                (30, 50), (90, 50),
            ]
        elif pop < 600:
            # Expand to fill more of the map
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 8 + col * 15
                    cy = 8 + row * 16
                    active_centers.append((cx, cy))
        else:
            # Dense full-map coverage
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 6 + col * 10
                    cy = 6 + row * 10
                    active_centers.append((cx, cy))

        # Score candidates by distance to nearest active center
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants at x=20,60,100, y=50 with wire spines and flanking roads."""
    actions = []
    for px in [20, 60, 100]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Active anchor columns and rows - scale with population
    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 8
        if pop < 1500:  return 10
        return 12

    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 40, 60, 80]:
            all_anchors.append((col_x, row_y))

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- CLOSED-LOOP: Find nearest wire frontier and extend it ----
    # Check each anchor: does it have a power plant nearby?
    for (px, py) in active_anchors:
        y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
        x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            # No plant near this anchor — find nearest empty spot
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- CLOSED-LOOP WIRE: Extend wire from existing wire toward anchor targets ----
    # Build a set of wire target positions (vertical spines at anchor x, full coverage)
    spine_half = min(35, 10 + pop // 10)

    # For each active anchor, check if wire spine is complete; if not, extend it
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check for gaps in wire spine at column px
        for wy in range(spine_top, spine_bot + 1):
            if ib(px, wy) and not bool(wm[wy, px]) and not bool(pm[wy, px]) and bool(em[wy, px]):
                # Check if adjacent to existing wire or plant
                has_adj_power = False
                for ddy in [-1, 1]:
                    ny2 = wy + ddy
                    if ib(px, ny2) and (bool(wm[ny2, px]) or bool(pm[ny2, px])):
                        has_adj_power = True
                if has_adj_power:
                    return (Tool.WIRE, px, wy)

        # If no adjacent wire found, seed from plant
        plant_ys, plant_xs = np.where(pm[max(0,py-8):min(WORLD_H,py+9), max(0,px-8):min(WORLD_W,px+9)])
        if len(plant_xs) > 0:
            for i in range(len(plant_xs)):
                plx = int(plant_xs[i]) + max(0, px - 8)
                ply = int(plant_ys[i]) + max(0, py - 8)
                # Place wire adjacent to plant toward spine
                if ib(px, ply) and bool(em[ply, px]) and not bool(pm[ply, px]):
                    return (Tool.WIRE, px, ply)
                for ddy in [-1, 0, 1]:
                    for ddx in [-1, 0, 1]:
                        nwx, nwy = plx + ddx, ply + ddy
                        if ib(nwx, nwy) and bool(em[nwy, nwx]) and not bool(pm[nwy, nwx]):
                            return (Tool.WIRE, nwx, nwy)

    # ---- HORIZONTAL WIRE connecting same-row anchors ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_xs = sorted([px for (px, py) in active_anchors if py == yl])
        for i in range(len(row_xs) - 1):
            x1, x2 = row_xs[i], row_xs[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    # Only place if adjacent to existing wire
                    has_adj = False
                    for ddx in [-1, 1]:
                        if ib(cx + ddx, yl) and bool(wm[yl, cx + ddx]):
                            has_adj = True
                    if has_adj:
                        return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows in same column ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xc in x_cols:
        col_ys = sorted([py for (px, py) in active_anchors if px == xc])
        for i in range(len(col_ys) - 1):
            y1v, y2v = col_ys[i], col_ys[i + 1]
            for cy in range(y1v + 1, y2v):
                if ib(xc, cy) and bool(em[cy, xc]) and not bool(pm[cy, xc]):
                    has_adj = False
                    for ddy in [-1, 1]:
                        if ib(xc, cy + ddy) and bool(wm[cy + ddy, xc]):
                            has_adj = True
                    if has_adj:
                        return (Tool.WIRE, xc, cy)

    # ---- CLOSED-LOOP ROAD: Extend roads adjacent to existing roads, near wire ----
    # Build neighbor-wire mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Roads flank wire spines at px-1, px+1 for each active anchor
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_rows = [r for r in range(spine_top, spine_bot + 1) if ib(px, r) and bool(wm[r, px])]
        if not wire_rows:
            continue
        cycle = (step + px) % 2
        for rl, rr in [(px - 1, px + 1)]:
            for wr in wire_rows[cycle::2]:
                if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                    return (Tool.ROAD, rl, wr)
                if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                    return (Tool.ROAD, rr, wr)

    # Horizontal roads at anchor y-levels +/- 2 (zone access roads)
    if pop > 15:
        for yl in y_levels:
            row_xs = sorted([px for (px, py) in active_anchors if py == yl])
            if len(row_xs) < 1:
                continue
            x_left = row_xs[0] - 1
            x_right = row_xs[-1] + 1
            for horiz_y in [yl - 2, yl + 2]:
                if not ib(x_left, horiz_y) or not ib(x_right, horiz_y):
                    continue
                for cx in range(x_left, x_right + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]) and bool(nbr_wire[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # Vertical roads connecting y-levels
    if pop > 50 and len(y_levels) >= 2:
        for xc in x_cols:
            for rx in [xc - 2, xc + 2]:
                if not ib(rx, 2):
                    continue
                yl_sorted = sorted(y_levels)
                for i in range(len(yl_sorted) - 1):
                    y1v2, y2v2 = yl_sorted[i], yl_sorted[i + 1]
                    for cy in range(y1v2, y2v2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]) and bool(nbr_wire[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # Extend roads from existing roads that are near wire
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 100)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            if not bool(nbr_wire[ry2, rx2]):
                continue
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- BUILD ZONE NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: prefer near roads AND near wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES (closed-loop: only place if empty) ----
    if pop > 80:
        fire_spots = [
            (8, 15), (35, 15), (75, 15), (108, 15),
            (8, 40), (35, 40), (75, 40), (108, 40),
            (8, 60), (35, 60), (75, 60), (108, 60),
            (8, 85), (35, 85), (75, 85), (108, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (22, 10), (55, 10), (88, 10),
            (22, 30), (55, 30), (88, 30),
            (22, 50), (55, 50), (88, 50),
            (22, 70), (55, 70), (88, 70),
            (22, 90), (55, 90), (88, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(15, 10), (55, 10), (95, 10),
                         (15, 50), (55, 50), (95, 50),
                         (15, 90), (55, 90), (95, 90)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(5, 5), (115, 5), (5, 95), (115, 95),
                      (60, 5), (60, 95), (5, 50), (115, 50)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # Parks near zones
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # Fallback: extend wire from nearest wire to empty
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: road near zone
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + seed roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from plant
    for x in range(50, 71):
        actions.append((Tool.WIRE, x, 50))
    for y in range(40, 61):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads parallel to wire spines
    for x in range(50, 71):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(40, 61):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- NEIGHBORHOOD GRID ---
    all_hoods = []
    for hy in range(15, 95, 16):
        for hx in range(15, 115, 16):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:   return 2
        if pop < 200:  return 5
        if pop < 500:  return 9
        if pop < 1000: return 14
        if pop < 2000: return 20
        if pop < 4000: return 28
        if pop < 7000: return 38
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: ENSURE POWER PLANTS near active hoods ---
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
            y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: WIRE SPINES for each active hood ---
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 12)
        spine_bot   = min(WORLD_H - 3, hy + 12)
        spine_left  = max(2, hx - 12)
        spine_right = min(WORLD_W - 3, hx + 12)

        # Vertical spine at hx
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        col_plant_rows = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        # Connect plant to wire if needed
        if col_plant_rows and not col_wire:
            pr = col_plant_rows[0]
            for wy in [pr - 1, pr + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        if col_wire:
            min_wr, max_wr = min(col_wire), max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine at hy
        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        row_plant_cols = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant_cols and not row_wire:
            pc = row_plant_cols[0]
            for wx in [pc - 1, pc + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc, max_wc = min(row_wire), max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT WIRE SPINES BETWEEN ADJACENT HOODS ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            # Connect horizontally adjacent hoods
            if abs(hy1 - hy2) <= 4 and abs(hx1 - hx2) <= 20:
                mid_y = (hy1 + hy2) // 2
                for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
            # Connect vertically adjacent hoods
            if abs(hx1 - hx2) <= 4 and abs(hy1 - hy2) <= 20:
                mid_x = (hx1 + hx2) // 2
                for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                        return (Tool.WIRE, mid_x, cy)

    # --- PHASE 4: ROAD GRID (parallel to wire spines, offset ±2) ---
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy):
                continue
            if not col_wire:
                continue
            cyc = step % 4
            for wr in col_wire[cyc::4]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry):
                continue
            if not row_wire:
                continue
            cyc = (step + 2) % 4
            for wc in row_wire[cyc::4]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- Build neighbor masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # --- PHASE 5: ZONE PLACEMENT ---
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus: reward proximity to existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS from existing network into powered areas ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES ---
    if pop > 10:
        fire_grid = [(fx, fy) for fy in range(15, 95, 20) for fx in range(15, 115, 20)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(20, 90, 22) for px2 in range(20, 110, 22)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 5 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17 + pop) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1000:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from plants ---
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire cross + road grid seed"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines outward from center
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Two more plants on the wire spine
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    actions.append((Tool.COALPOWER, 60, 15))
    actions.append((Tool.COALPOWER, 60, 85))
    # Seed horizontal roads near center
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 53))
        actions.append((Tool.ROAD, x, 47))
    # Seed vertical roads
    for y in range(1, 99):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- CLOSED LOOP PHASE LOGIC ---
    # Each step, react to what's on the map

    # 1. If any area lacks power coverage, extend wire from nearest wire/plant toward it
    # 2. If any powered area lacks road, extend road
    # 3. Otherwise, place zones in powered+roaded empty cells

    # Check power coverage across the map
    power_coverage = dilate(wm | pm, 5)
    uncovered = ~power_coverage
    uncovered[0, :] = False; uncovered[WORLD_H-1, :] = False
    uncovered[:, 0] = False; uncovered[:, WORLD_W-1] = False

    # Priority 1: Extend wire grid to cover more area
    # Target: wire every 10 rows and cols
    wire_target_rows = list(range(5, 100, 8))
    wire_target_cols = list(range(5, 120, 8))

    # Phase based on step mod to cycle through tasks
    phase = step % 10

    # Phase 0-1: Extend horizontal wire rows
    if phase in (0, 1):
        rows_to_try = wire_target_rows[::2] if phase == 0 else wire_target_rows[1::2]
        for wr in rows_to_try:
            if wr >= WORLD_H:
                continue
            row_has_wire = bool(np.any(wm[wr, :] | pm[wr, :]))
            if not row_has_wire:
                # Find nearest row with wire/plant
                best_y = -1
                best_d = 999
                for yy in range(max(0, wr-15), min(WORLD_H, wr+16)):
                    if bool(np.any(wm[yy, :] | pm[yy, :])):
                        if abs(yy - wr) < best_d:
                            best_d = abs(yy - wr)
                            best_y = yy
                if best_y >= 0:
                    # Place wire stepping from best_y toward wr
                    step_y = best_y + (1 if wr > best_y else -1)
                    if ib(60, step_y) and bool(em[step_y, 60]):
                        return (Tool.WIRE, 60, step_y)
            # Extend wire along this row
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Phase 2-3: Extend vertical wire cols
    if phase in (2, 3):
        cols_to_try = wire_target_cols[::2] if phase == 2 else wire_target_cols[1::2]
        for wc in cols_to_try:
            if wc >= WORLD_W:
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # Phase 4: Add coal plants where power coverage is thin
    if phase == 4:
        # Find region without plant nearby
        plant_near = dilate(pm, 20)
        for py in range(10, 95, 20):
            for px in range(10, 115, 20):
                if not bool(plant_near[py, px]):
                    # Place plant on wire if possible, else find empty near wire
                    if bool(wm[py, px]) and bool(em[py, px]):
                        return (Tool.COALPOWER, px, py)
                    for r in range(1, 8):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx2, ny2 = px+dx, py+dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # Phase 5-6: Build road grid reactively
    # Roads run parallel to wire rows, offset by 3
    road_rows = []
    for wr in wire_target_rows:
        road_rows.append(wr + 3)
        road_rows.append(wr - 3)
    road_cols = []
    for wc in wire_target_cols:
        road_cols.append(wc + 3)
        road_cols.append(wc - 3)

    if phase == 5:
        # Extend horizontal roads, only in powered areas
        for rr in sorted(set(r for r in road_rows if 0 < r < WORLD_H)):
            if not bool(np.any(near_power[rr, :])):
                continue
            for rx in range(1, WORLD_W - 1):
                if not bool(near_power[rr, rx]):
                    continue
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    adj = (rx > 0 and bool(rm[rr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or \
                          (rr > 0 and bool(rm[rr-1, rx])) or \
                          (rr < WORLD_H-1 and bool(rm[rr+1, rx]))
                    if adj or (rx == 1):
                        return (Tool.ROAD, rx, rr)

    if phase == 6:
        for rc in sorted(set(c for c in road_cols if 0 < c < WORLD_W)):
            if not bool(np.any(near_power[:, rc])):
                continue
            for ry in range(1, WORLD_H - 1):
                if not bool(near_power[ry, rc]):
                    continue
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    adj = (ry > 0 and bool(rm[ry-1, rc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or \
                          (rc > 0 and bool(rm[ry, rc-1])) or \
                          (rc < WORLD_W-1 and bool(rm[ry, rc+1]))
                    if adj or (ry == 1):
                        return (Tool.ROAD, rc, ry)

    # Phase 7: Wire unpowered zones
    if phase == 7:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Civic services
    if phase == 8:
        if pop > 10:
            fire_spots = [(x, y) for x in range(15, 115, 25) for y in range(10, 95, 20)]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 100:
            police_spots = [(x, y) for x in range(20, 110, 30) for y in range(15, 90, 25)]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadium_spots = [(30, 25), (90, 25), (30, 75), (90, 75), (60, 50)]
            for sx, sy in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [(15, 50), (105, 50), (60, 12), (60, 88), (30, 25), (90, 75)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
            for sx, sy in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 3000:
            airports = [(45, 8), (75, 8), (45, 90), (75, 90)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # Phase 9: Parks in powered+roaded area
    if phase == 9 and pop > 200:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- PRIMARY: Place zones in powered+roaded cells ----
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    # Don't zone wire/road corridors
    for wr in wire_target_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_target_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()

        # Prefer cells closer to existing zones (denser city)
        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                # Sample a few zone positions and find nearest
                sample_sz = min(len(zone_xs), 30)
                sample_idx = np.linspace(0, len(zone_xs)-1, sample_sz, dtype=int)
                best_dist = np.full(len(cxs), 999999.0)
                for si in sample_idx:
                    zx_s, zy_s = int(zone_xs[si]), int(zone_ys[si])
                    d = np.abs(cxs - zx_s).astype(float) + np.abs(cys - zy_s).astype(float)
                    best_dist = np.minimum(best_dist, d)
                order = np.argsort(best_dist)
            else:
                order = np.arange(len(cxs))
        else:
            # Start near center
            d = np.abs(cxs - 60).astype(float) + np.abs(cys - 50).astype(float)
            order = np.argsort(d)

        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and a central road grid."""
    actions = []
    # Two power plants: left cluster and right cluster
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire from left plant outward
    for d in range(1, 6):
        for dx, dy in [(d,0),(-d,0),(0,d),(0,-d)]:
            nx, ny = 30+dx, 50+dy
            if 0<=nx<WORLD_W and 0<=ny<WORLD_H:
                actions.append((Tool.WIRE, nx, ny))
    # Wire from right plant outward
    for d in range(1, 6):
        for dx, dy in [(d,0),(-d,0),(0,d),(0,-d)]:
            nx, ny = 90+dx, 50+dy
            if 0<=nx<WORLD_W and 0<=ny<WORLD_H:
                actions.append((Tool.WIRE, nx, ny))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # Two clusters: left centered at (30,50), right at (90,50)
    # Each cluster has a grid of neighborhoods
    # Left cluster neighborhoods
    left_hoods = [(x, y) for y in range(20, 85, 12) for x in range(10, 55, 12)]
    # Right cluster neighborhoods  
    right_hoods = [(x, y) for y in range(20, 85, 12) for x in range(65, 115, 12)]
    all_hoods = left_hoods + right_hoods

    # Scale active hoods with population
    def num_active():
        if pop < 50:    return 6
        if pop < 200:   return 14
        if pop < 500:   return 25
        if pop < 1000:  return 40
        if pop < 2000:  return 55
        if pop < 4000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Build neighbor masks
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            if abs(dx) + abs(dy) > 6: continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # PHASE 1: Ensure power plants near active hoods
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx-9), min(WORLD_W, hx+10)
        y0, y1 = max(0, hy-9), min(WORLD_H, hy+10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            nearby_z = int(np.sum(zone_tiles[y0:y1, x0:x1]))
                            tool_p = Tool.NUCLEARPOWER if nearby_z > 15 and funds > 10000 else Tool.COALPOWER
                            return (tool_p, nx, ny)

    # PHASE 2: Wire spines - horizontal AND vertical through each hood
    spine_r = 9
    for (hx, hy) in active_hoods:
        # Vertical spine along hx
        for dy in range(-spine_r, spine_r+1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal spine along hy
        for dx in range(-spine_r, spine_r+1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adx in [-1, 1]:
                ax = wx + adx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # PHASE 3: Connect neighboring hoods with wire
    row_to_hoods = {}
    col_to_hoods = {}
    for (hx, hy) in active_hoods:
        row_to_hoods.setdefault(hy, []).append(hx)
        col_to_hoods.setdefault(hx, []).append(hy)

    for hy, hxs in row_to_hoods.items():
        shxs = sorted(hxs)
        for i in range(len(shxs) - 1):
            hx1, hx2 = shxs[i], shxs[i+1]
            for cx in range(hx1+1, hx2):
                if not ib(cx, hy): continue
                if bool(wm[hy, cx]) or bool(pm[hy, cx]): continue
                if not bool(em[hy, cx]): continue
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, cx, hy)

    for hx, hys in col_to_hoods.items():
        shys = sorted(hys)
        for i in range(len(shys) - 1):
            hy1, hy2 = shys[i], shys[i+1]
            for cy in range(hy1+1, hy2):
                if not ib(hx, cy): continue
                if bool(wm[cy, hx]) or bool(pm[cy, hx]): continue
                if not bool(em[cy, hx]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, cy)

    # PHASE 4: Roads - grid pattern around each hood (both sides of wire spine)
    for (hx, hy) in active_hoods:
        # Roads parallel to vertical spine
        for rx in [hx-1, hx+1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r+1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]): continue
                if bool(pm[ry, rx]): continue
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)
        # Roads parallel to horizontal spine
        for ry2 in [hy-1, hy+1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r+1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]): continue
                if bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # PHASE 5: Zone placement with balanced mix (more commercial/industrial bias)
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 35% ind, 35% com, 30% res for higher density
        if ir < 0.35:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 6: Extend roads into powered empty areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # PHASE 7: Civic services
    if pop > 30:
        fire_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,40),(45,40),(75,40),(105,40),
            (15,65),(45,65),(75,65),(105,65),
            (15,88),(45,88),(75,88),(105,88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (25,10),(60,10),(95,10),
            (10,35),(40,35),(70,35),(100,35),
            (25,60),(60,60),(95,60),
            (10,82),(40,82),(70,82),(100,82),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 350:
        for (sx, sy) in [(20,25),(60,25),(100,25),(20,55),(60,55),(100,55),(20,80),(60,80),(100,80)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        for (sx, sy) in [(5,95),(115,95),(5,5),(115,5),(60,5),(60,94)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        for (sx, sy) in [(35,5),(75,5),(35,93),(75,93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # PHASE 8: Parks near roads for land value
    if pop > 60 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 41) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # FALLBACK: extend wire
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % len(wire_xs)
        for offset in range(min(len(wire_xs), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # FALLBACK: place plant
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + initial road grid"""
    actions = []
    # Two coal plants: left and right of center
    plants = [(25, 50), (95, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire horizontally across the map at y=50
    for x in range(26, 95):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically at x=60 from y=20 to y=80
    for y in range(20, 50):
        actions.append((Tool.WIRE, 60, y))
    for y in range(51, 80):
        actions.append((Tool.WIRE, 60, y))
    # Roads above and below the wire spine
    for x in range(20, 100):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Vertical roads
    for y in range(20, 80):
        actions.append((Tool.ROAD, 40, y))
        actions.append((Tool.ROAD, 80, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- CLOSED-LOOP POWER EXTENSION ----
    # Find frontier: empty tiles adjacent to wire or plant
    # Prioritize extending wire toward empty areas far from power

    # Build power coverage map (wire or plant)
    power_map = wm | pm

    # Find tiles that need wire (empty, adjacent to wire/plant, not already powered)
    # We extend wire outward from existing power network
    def extend_wire():
        """Find best empty tile adjacent to power network to add wire"""
        power_ys, power_xs = np.where(power_map)
        if len(power_xs) == 0:
            return None
        # Sample from power frontier
        candidates = []
        step_k = (step * 7) % max(len(power_xs), 1)
        checked = 0
        for i in range(len(power_xs)):
            idx = (step_k + i * 3) % len(power_xs)
            wx, wy = int(power_xs[idx]), int(power_ys[idx])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]):
                    candidates.append((nx, ny))
                    checked += 1
                    if checked > 20:
                        break
            if checked > 20:
                break
        if candidates:
            # Pick candidate that extends toward underserved area
            cx, cy = candidates[(step * 11) % len(candidates)]
            return (Tool.WIRE, cx, cy)
        return None

    # ---- CLOSED-LOOP ROAD EXTENSION ----
    def extend_road():
        """Extend road network from existing roads toward powered empty areas"""
        road_ys, road_xs = np.where(rm)
        if len(road_xs) == 0:
            return None
        step_k = (step * 13) % max(len(road_xs), 1)
        for i in range(min(len(road_xs), 80)):
            idx = (step_k + i * 5) % len(road_xs)
            rx, ry = int(road_xs[idx]), int(road_ys[idx])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Only extend into powered area or toward it
                    near_power = False
                    for pdx in range(-3, 4):
                        for pdy in range(-3, 4):
                            px2, py2 = nx + pdx, ny + pdy
                            if ib(px2, py2) and bool(power_map[py2, px2]):
                                near_power = True
                                break
                        if near_power:
                            break
                    if near_power:
                        return (Tool.ROAD, nx, ny)
        return None

    # ---- NEIGHBOR MASKS ----
    # Power reachability (within 3 tiles of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_map[sr0:sr1, sc0:sc1]

    # Road reachability (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # 40% RES, 30% COM, 30% IND
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- STRATEGY: decide what to do this step ----
    # Phase based on what the map actually shows

    powered_zones = obs.powered_zones
    wire_count = int(np.sum(wm))
    road_count = int(np.sum(rm))
    plant_count = int(np.sum(pm))

    # How well-powered are we?
    powered_fraction = min(powered_zones / max(total_zones, 1), 1.0)

    # Candidate zone positions: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    n_cand = int(np.sum(cand_mask))

    # Decision logic based on observed state
    # Priority 1: If very few wires, extend wire network
    if wire_count < 50:
        r = extend_wire()
        if r:
            return r

    # Priority 2: If very few roads, extend roads
    if road_count < 30:
        r = extend_road()
        if r:
            return r

    # Priority 3: Place zones if we have good coverage
    if n_cand > 5:
        cys, cxs = np.where(cand_mask)
        # Find zone center closest to map center (60,50) that is clear
        dists = np.abs(cxs - 60) + np.abs(cys - 50)
        order = np.argsort(dists)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Priority 4: Extend wire to cover more area
    # Target: wire should reach all road corridors
    # Find road tiles not near power and extend wire toward them
    road_no_power = rm & ~nbr_power
    rny, rnx = np.where(road_no_power)
    if len(rnx) > 0:
        # Find closest road-without-power to existing wire
        power_pos = np.array(np.where(power_map)).T  # shape (N,2)
        if len(power_pos) > 0:
            # Pick a target road tile
            t_idx = (step * 11) % len(rnx)
            tx, ty = int(rnx[t_idx]), int(rny[t_idx])
            # Find closest power tile
            dists = np.abs(power_pos[:, 1] - tx) + np.abs(power_pos[:, 0] - ty)
            pidx = int(np.argmin(dists))
            py_c, px_c = int(power_pos[pidx, 0]), int(power_pos[pidx, 1])
            # Step from closest power tile toward target
            dx = 0 if tx == px_c else (1 if tx > px_c else -1)
            dy = 0 if ty == py_c else (1 if ty > py_c else -1)
            # Try horizontal then vertical
            candidates_w = []
            if dx != 0:
                nx, ny = px_c + dx, py_c
                if ib(nx, ny) and bool(em[ny, nx]):
                    candidates_w.append((nx, ny))
            if dy != 0:
                nx, ny = px_c, py_c + dy
                if ib(nx, ny) and bool(em[ny, nx]):
                    candidates_w.append((nx, ny))
            for nx, ny in candidates_w:
                return (Tool.WIRE, nx, ny)

    # Priority 5: Extend road network into powered empty areas
    r = extend_road()
    if r:
        return r

    # Priority 6: Extend wire network
    r = extend_wire()
    if r:
        return r

    # Priority 7: Add more power plants if we have many unpowered zones
    if total_zones > 0 and powered_fraction < 0.5 and plant_count < 8:
        # Place plant near unpowered zones
        unpowered = (resm | comm | indm) & ~nbr_power
        upy, upx = np.where(unpowered)
        if len(upx) > 0:
            t_idx = (step * 3) % len(upx)
            tx, ty = int(upx[t_idx]), int(upy[t_idx])
            # Find empty spot near unpowered zone
            for r2 in range(2, 15):
                for dy in range(-r2, r2+1):
                    for dx in range(-r2, r2+1):
                        if abs(dx) == r2 or abs(dy) == r2:
                            nx, ny = tx + dx, ty + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # Priority 8: Civic services
    if pop > 200:
        fire_spots = [(20, 20), (60, 20), (100, 20),
                      (20, 50), (100, 50),
                      (20, 80), (60, 80), (100, 80)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [(40, 30), (80, 30), (30, 60), (90, 60), (60, 70)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(50, 40), (70, 40), (50, 60), (70, 60)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(10, 85), (110, 85)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(55, 10), (55, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Priority 9: Parks for land value
    if pop > 300 and n_cand > 0:
        cys2, cxs2 = np.where(cand_mask)
        if len(cxs2) > 0:
            idx = (step * 17) % len(cxs2)
            return (Tool.PARK, int(cxs2[idx]), int(cys2[idx]))

    # Final fallback: extend wire
    r = extend_wire()
    if r:
        return r

    return None

