def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 45% res, 30% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- REACTIVE POWER EXTENSION ----
    # Find zones/roads without power and wire them up
    unpowered = (zone_tiles | rm) & ~near_power
    if bool(np.any(unpowered)):
        up_ys, up_xs = np.where(unpowered)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0 and len(up_xs) > 0:
            # Pick a random unpowered tile
            idx = (step * 17 + pop) % len(up_xs)
            tx, ty = int(up_xs[idx]), int(up_ys[idx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best_i = np.argmin(dists)
            bwx, bwy = int(wire_xs[best_i]), int(wire_ys[best_i])
            # Step one tile toward target
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            # Try horizontal first, then vertical
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and not bool(pm[ny2, nx2]):
                    if bool(em[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- REACTIVE ROAD EXTENSION ----
    # Find powered empty areas without roads and extend roads there
    powered_no_road = near_power & em & ~near_road
    powered_no_road[0:3, :] = False
    powered_no_road[WORLD_H-3:, :] = False
    powered_no_road[:, 0:3] = False
    powered_no_road[:, WORLD_W-3:] = False
    if bool(np.any(powered_no_road)):
        pnr_ys, pnr_xs = np.where(powered_no_road)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0 and len(pnr_xs) > 0:
            idx = (step * 13 + pop * 2) % len(pnr_xs)
            tx, ty = int(pnr_xs[idx]), int(pnr_ys[idx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best_i = np.argmin(dists)
            brx, bry = int(road_xs[best_i]), int(road_ys[best_i])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- ADD POWER PLANT IF COVERAGE POOR ----
    powered_fraction = float(np.sum(near_power)) / (WORLD_W * WORLD_H)
    if powered_fraction < 0.6 and step % 20 == 0:
        # Find densest unpowered region
        unpow_em = em & ~near_power
        unpow_em[0:5, :] = False
        unpow_em[WORLD_H-5:, :] = False
        unpow_em[:, 0:5] = False
        unpow_em[:, WORLD_W-5:] = False
        if bool(np.any(unpow_em)):
            up_ys2, up_xs2 = np.where(unpow_em)
            idx = (step * 7) % len(up_xs2)
            return (Tool.COALPOWER, int(up_xs2[idx]), int(up_ys2[idx]))

    # ---- CIVIC SERVICES ----
    if pop > 20:
        fire_spots = [
            (5,5),(55,5),(110,5),(5,50),(110,50),(5,95),(55,95),(110,95),
            (30,25),(80,25),(30,75),(80,75),(55,50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (15,15),(65,15),(105,15),(15,50),(105,50),(15,85),(65,85),(105,85),
            (40,35),(90,35),(40,65),(90,65),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (30,20),(80,20),(30,70),(80,70),(55,45),(55,55),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (10,10),(110,10),(10,90),(110,90),(60,10),(60,90),(10,50),(110,50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5,92),(115,92),(5,8),(115,8)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50,5),(70,5),(50,92),(70,92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 200 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (main action) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Pick centers based on population growth stage
        if pop < 100:
            centers = [(60, 50), (57, 50), (63, 50), (60, 44), (60, 56)]
        elif pop < 500:
            centers = []
            for row in range(6):
                for col in range(8):
                    centers.append((15 + col * 13, 15 + row * 14))
        else:
            centers = []
            for row in range(9):
                for col in range(11):
                    centers.append((7 + col * 10, 7 + row * 10))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- FALLBACK: extend road from existing road ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 200)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

