        if pop > 150:
            police_spots = [(18,12),(60,12),(100,12),
                            (18,40),(60,40),(100,40),
                            (18,62),(60,62),(100,62),
                            (18,88),(60,88),(100,88)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 500:
            stadium_spots = [(30,15),(88,15),(30,62),(88,62),(59,38),(59,75)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [(5,50),(113,50),(59,5),(59,93),(5,5),(113,5),(5,93),(113,93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1200:
            seaports = [(5,93),(113,93),(5,5),(113,5)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2000:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(113,43)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # --- REACTIVE ZONE PLACEMENT ---
    # Build candidate mask: empty, near road, near power, away from borders/corridors
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score candidates: prioritize those closer to existing zones or roads
        # (reactive to current map state)
        existing_road_ys, existing_road_xs = np.where(rm)
        if len(existing_road_xs) > 0:
            # Score by proximity to road network (reactive)
            # Sample a subset of road tiles for efficiency
            sample_size = min(50, len(existing_road_xs))
            step_hash = (step * 31 + pop * 7) % max(len(existing_road_xs), 1)
            indices = [(step_hash + i * 13) % len(existing_road_xs) for i in range(sample_size)]
            rsx = existing_road_xs[indices]
            rsy = existing_road_ys[indices]
            # For each candidate, min dist to sampled roads
            best_dist = np.full(len(cxs2), 999999.0)
            for i in range(len(rsx)):
                d = np.abs(cxs2 - rsx[i]).astype(float) + np.abs(cys2 - rsy[i]).astype(float)
                best_dist = np.minimum(best_dist, d)
            order = np.argsort(best_dist)
        else:
            # No roads yet, just pick first candidates
            order = np.arange(len(cxs2))

        tool = pick_tool()
        # Add randomness via pop+step to avoid always picking same spot
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks for land value
    if pop > 100 and step % 3 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend wire toward unpowered area
    unpowered_hood = []
    for hx in range(10, 110, 20):
        for hy in range(10, 90, 20):
            if not bool(near_power[hy, hx]):
                unpowered_hood.append((hx, hy))
    if unpowered_hood:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered_hood[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx,bwy),(bwx,bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Final fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13 + pop) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire/road cross"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(55, 75):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Initial roads near center
    for x in range(50, 72):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 56, y))
        actions.append((Tool.ROAD, 64, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    zone_tiles = resm | comm | indm

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # --- STEP 1: Ensure power plants distributed ---
    # Place coal plants on a grid so wires can reach zones
    plant_grid = [(px, py) for py in range(15, WORLD_H - 10, 20)
                  for px in range(15, WORLD_W - 10, 20)]
    for ppx, ppy in plant_grid:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 7), min(WORLD_W, ppx + 8)
        y0, y1 = max(0, ppy - 7), min(WORLD_H, ppy + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            # Only place if not on a road/zone
            if not bool(rm[ppy, ppx]) and not bool(zone_tiles[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # --- STEP 2: Extend wire network from existing power sources ---
    # Wire spines: horizontal every 10 rows, vertical every 10 cols
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    for wr in wire_rows:
        row_pw = wm[wr, :] | pm[wr, :]
        if not row_pw.any():
            # Try to start from a plant above/below
            pys_a, pxs_a = np.where(pm)
            if len(pxs_a) > 0:
                dists = np.abs(pys_a - wr)
                k = np.argmin(dists)
                wx, wy = int(pxs_a[k]), int(pys_a[k])
                step_y = 1 if wr > wy else -1
                ny = wy + step_y
                if ib(wx, ny) and not bool(zone_tiles[ny, wx]) and not bool(rm[ny, wx]):
                    return (Tool.WIRE, wx, ny)
            continue
        idxs = np.where(row_pw)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        # Fill gaps first
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(zone_tiles[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)
        # Extend left
        if left > 3:
            nx = left - 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Extend right
        if right < WORLD_W - 4:
            nx = right + 1
            if bool(em[wr, nx]) and not bool(zone_tiles[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)

    for wc in wire_cols:
        col_pw = wm[:, wc] | pm[:, wc]
        if not col_pw.any():
            if ib(wc, 50) and bool(em[50, wc]) and not bool(zone_tiles[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        idxs = np.where(col_pw)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(zone_tiles[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)
        if top > 3:
            ny = top - 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)
        if bot < WORLD_H - 4:
            ny = bot + 1
            if bool(em[ny, wc]) and not bool(zone_tiles[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)

    # --- STEP 3: Road network between wire rows/cols ---
    # Roads at offsets +4 from wire rows/cols (zone-friendly spacing)
    road_rows = sorted(set(r for wr in wire_rows for r in [wr + 4, wr - 4]
                           if 4 < r < WORLD_H - 4))
    road_cols = sorted(set(c for wc in wire_cols for c in [wc + 4, wc - 4]
                           if 4 < c < WORLD_W - 4))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        idxs = np.where(row_rd)[0]
        left = int(idxs[0])
        right = int(idxs[-1])
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)
        if left > 4 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        idxs = np.where(col_rd)[0]
        top = int(idxs[0])
        bot = int(idxs[-1])
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)
        if top > 4 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- STEP 4: Zone placement (closed-loop reactive) ---
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Candidate: empty, near road, near power, away from edges
    zone_cand = em & near_road & near_power
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W-3:] = False
    # Avoid infrastructure rows/cols
    for wr in wire_rows:
        zone_cand[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for rr in road_rows:
        zone_cand[max(0,rr-1):min(WORLD_H,rr+2), :] = False
    for wc in wire_cols:
        zone_cand[:, max(0,wc-1):min(WORLD_W,wc+2)] = False
    for rc in road_cols:
        zone_cand[:, max(0,rc-1):min(WORLD_W,rc+2)] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer spots close to roads but cluster with existing zones
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer spots 4-14 tiles from existing zones (natural clustering)
            zone_score = np.where(min_zone_dist < 4, 800.0,
                         np.where(min_zone_dist > 18, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.1

        score = road_dist * 2.5 + zone_score
        order = np.argsort(score)
        off = (step * 11 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- STEP 5: Civic services based on population ---
    if pop > 15:
        fire_spots = [(fx, fy) for fy in range(8, 96, 12) for fx in range(8, 116, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_spots = [(px2, py2) for py2 in range(8, 96, 14) for px2 in range(8, 116, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 120:
        park_spots = [(pkx, pky) for pky in range(5, 96, 8) for pkx in range(5, 116, 10)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 300:
        stadium_spots = [(sx, sy) for sy in range(14, 90, 24) for sx in range(14, 112, 30)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 5000:
        nuclear_spots = [(nx2, ny2) for ny2 in range(12, 92, 20) for nx2 in range(12, 112, 20)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and not bool(rm[npy, npx]) and not bool(zone_tiles[npy, npx]):
                x0, x1 = max(0, npx - 8), min(WORLD_W, npx + 9)
                y0, y1 = max(0, npy - 8), min(WORLD_H, npy + 9)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1000:
        airport_spots = [(60, 8), (60, 91), (8, 50), (111, 50)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [(8, 50), (111, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- STEP 6: Wire toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    if len(uzxs) > 0:
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted
        wire_cand = em & adj_to_power & ~zone_tiles & ~rm
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H-2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W-2:] = False
        wys_c, wxs_c = np.where(wire_cand)
        if len(wxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(uzxs) // 30)
            for i in range(len(wxs_c)):
                cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx2 - int(uzxs[j])) + abs(cy2 - int(uzys[j]))
                        for j in range(0, len(uzxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # --- STEP 7: Road toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    if len(usxs) > 0:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted
        road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
        road_cand2[0:2, :] = False
        road_cand2[WORLD_H-2:, :] = False
        road_cand2[:, 0:2] = False
        road_cand2[:, WORLD_W-2:] = False
        rys_c, rxs_c = np.where(road_cand2)
        if len(rxs_c) > 0:
            best_d = 1e9
            best_k = 0
            stride_u = max(1, len(usxs) // 30)
            for i in range(len(rxs_c)):
                cx2, cy2 = int(rxs_c[i]), int(rys_c[i])
                d = min(abs(cx2 - int(usxs[j])) + abs(cy2 - int(usys[j]))
                        for j in range(0, len(usxs), stride_u))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- Fallback: road from plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle with wire spines and roads."""
    actions = []
    plants = [(30, 35), (90, 35), (60, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        for dx in range(-8, 9):
            if px + dx >= 0 and px + dx < WORLD_W:
                actions.append((Tool.WIRE, px + dx, py))
        for dy in range(-8, 9):
            if py + dy >= 0 and py + dy < WORLD_H:
                actions.append((Tool.WIRE, px, py + dy))
    # Horizontal roads near plants
    for px, py in plants:
        for dx in range(-8, 9):
            if px + dx >= 0 and px + dx < WORLD_W:
                actions.append((Tool.ROAD, px + dx, py - 3))
                actions.append((Tool.ROAD, px + dx, py + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Aim for 40% RES, 30% COM, 30% IND
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of anchors - 6 columns, 5 rows for dense coverage
    all_anchors = []
    for ax in [15, 35, 55, 75, 95, 110]:
        for ay in [15, 30, 50, 68, 85]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 6
        if pop < 300:  return 9
        if pop < 500:  return 12
        if pop < 800:  return 18
        if pop < 1200: return 22
        if pop < 2000: return 26
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 14):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE EXPANSION along spines ----
    wire_half = min(18, 5 + pop // 10)
    vert_half = min(12, 4 + pop // 15)

    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- INTER-ANCHOR WIRE CONNECTIONS ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING along spines ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        # Roads at ay-3 and ay+3 (flanking wire at ay)
        for road_y_off in [-3, 3]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx+ddx, road_y) and bool(rm[road_y, cx+ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y-1) and bool(wm[road_y-1, cx])) or \
                               (ib(cx, road_y+1) and bool(wm[road_y+1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-3, 3]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy+ddy) and bool(rm[cy+ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x-1, cy) and bool(wm[cy, road_x-1])) or \
                               (ib(road_x+1, cy) and bool(wm[cy, road_x+1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_spots = [
            (8, 8), (32, 8), (56, 8), (80, 8), (104, 8),
            (8, 28), (32, 28), (56, 28), (80, 28), (104, 28),
            (8, 48), (32, 48), (56, 48), (80, 48), (104, 48),
            (8, 68), (32, 68), (56, 68), (80, 68), (104, 68),
            (8, 88), (32, 88), (56, 88), (80, 88), (104, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (12, 3), (38, 3), (62, 3), (88, 3), (112, 3),
            (12, 23), (38, 23), (62, 23), (88, 23), (112, 23),
            (12, 43), (38, 43), (62, 43), (88, 43), (112, 43),
            (12, 63), (38, 63), (62, 63), (88, 63), (112, 63),
            (12, 83), (38, 83), (62, 83), (88, 83), (112, 83),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(22, 3), (60, 3), (98, 3), (22, 95), (60, 95), (98, 95)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        for (nx2, ny2) in [(4, 4), (116, 4), (4, 95), (116, 95), (60, 4), (60, 95)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for (ax2, ay2) in [(55, 5), (5, 50), (114, 50), (55, 93)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for (sx2, sy2) in [(5, 93), (114, 93), (60, 96), (5, 4), (114, 4)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 80:
        zone_map2 = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map2)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in a 3x3 grid with wire spines and flanking roads."""
    actions = []
    for px in [20, 60, 100]:
        for py in [25, 50, 75]:
            actions.append((Tool.COALPOWER, px, py))
            for dy in range(-6, 7):
                actions.append((Tool.WIRE, px, py + dy))
            for dy in range(-6, 7):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target: 50% res, 30% com, 20% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhoods in a 3x3 grid: (anchor_x, anchor_y, wire_col, road_left, road_right)
    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [25, 50, 75]:
            all_anchors.append((col_x, row_y, col_x, col_x - 1, col_x + 1))

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 300:  return 3
        if pop < 500:  return 4
        if pop < 750:  return 5
        if pop < 1000: return 6
        if pop < 1500: return 7
        if pop < 2000: return 8
        return 9

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- 1. ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- 2. VERTICAL WIRE SPINE ----
    spine_half = min(35, 12 + pop // 8)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            wc1 = row_anchors[i][2]
            wc2 = row_anchors[i + 1][2]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- 4. VERTICAL WIRE connecting anchor rows in same column ----
    if n_active >= 3:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                py1 = col_anchors[i][1]
                py2 = col_anchors[i + 1][1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- 5. ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 3
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 6. HORIZONTAL ROADS at anchor y-levels ----
    if pop > 20:
        for yl in y_levels:
            row_anchors = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][3]
            rr_last = row_anchors[-1][4]
            for horiz_y in [yl - 5, yl + 5]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- 7. CROSS ROADS connecting row levels ----
    if pop > 60 and len(y_levels) >= 2:
        for col_x in [20, 60, 100]:
            for rx in [col_x - 3, col_x + 3]:
                for i in range(len(y_levels) - 1):
                    y1 = y_levels[i]
                    y2 = y_levels[i + 1]
                    if not ib(rx, y1) or not ib(rx, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- 8. BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- 9. ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- 10. EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- 11. CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 15), (35, 15), (65, 15), (95, 15), (115, 15),
            (8, 40), (35, 40), (65, 40), (95, 40), (115, 40),
            (8, 60), (35, 60), (65, 60), (95, 60), (115, 60),
            (8, 85), (35, 85), (65, 85), (95, 85), (115, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (12, 25), (45, 25), (75, 25), (108, 25),
            (12, 50), (45, 50), (75, 50), (108, 50),
            (12, 75), (45, 75), (75, 75), (108, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (10, 10), (55, 10), (100, 10),
            (10, 90), (55, 90), (100, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (30, 6), (90, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- 12. PARKS to boost land value ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- 13. FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- 14. LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants at center-left and center-right with wire and roads."""
    actions = []
    # Two plants: left cluster and right cluster
    for cx, cy in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Vertical wire spine
        for dy in [-1, 1, -2, 2, -3, 3]:
            actions.append((Tool.WIRE, cx, cy + dy))
        # Horizontal wire
        for dx in [-1, 1, -2, 2, -3, 3]:
            actions.append((Tool.WIRE, cx + dx, cy))
        # Flanking roads
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid of neighborhoods: 7 cols x 5 rows = 35 neighborhoods
    # Denser in the center, covering more of the map
    nh_cols = [12, 28, 44, 60, 76, 92, 108]
    nh_rows = [15, 30, 50, 70, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 300:   return 12
        if pop < 600:   return 18
        if pop < 1200:  return 24
        if pop < 2500:  return 30
        if pop < 5000:  return 35
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Pick evenly spread hoods
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        # Target: 25% ind, 35% com, 40% res
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CROSS-SHAPED SPINES ----
    spine_range = 12

    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = any(
                ib(hx, wy + ady) and (bool(wm[wy + ady, hx]) or bool(pm[wy + ady, hx]))
                for ady in [-1, 1]
            ) or any(
                ib(hx + adx, wy) and (bool(wm[wy, hx + adx]) or bool(pm[wy, hx + adx]))
                for adx in [-1, 1]
            )
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap from plant neighbors
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = any(
                ib(wx + adx, hy) and (bool(wm[hy, wx + adx]) or bool(pm[hy, wx + adx]))
                for adx in [-1, 1]
            ) or any(
                ib(wx, hy + ady) and (bool(wm[hy + ady, wx]) or bool(pm[hy + ady, wx]))
                for ady in [-1, 1]
            )
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in [(hx1 + 16, hy1), (hx1 + 14, hy1)]:
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1) or bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        for (hx2, hy2) in [(hx1, hy1 + 15), (hx1, hy1 + 20)]:
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines + perpendicular roads ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 3) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Flanking roads for vertical spine
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Flanking roads for horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2):
                    continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

        # Perpendicular roads at intervals to create grid
        for lane_dy in [-6, 6]:
            lane_y = hy + lane_dy
            if not ib(hx, lane_y):
                continue
            for dx in range(-spine_range, spine_range + 1):
                rx2 = hx + dx
                if not ib(rx2, lane_y):
                    continue
                if bool(em[lane_y, rx2]) and not bool(pm[lane_y, rx2]):
                    if bool(rm[lane_y, rx2 - 1] if rx2 > 0 else False) or \
                       bool(rm[lane_y, rx2 + 1] if rx2 < WORLD_W - 1 else False):
                        return (Tool.ROAD, rx2, lane_y)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 7 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-7, 8):
        for dx2 in range(-7, 8):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary zone placement pattern by step to spread different zone types
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (10, 10), (35, 10), (60, 10), (85, 10), (110, 10),
            (10, 35), (35, 35), (60, 35), (85, 35), (110, 35),
            (10, 55), (35, 55), (60, 55), (85, 55), (110, 55),
            (10, 75), (35, 75), (60, 75), (85, 75), (110, 75),
            (10, 93), (35, 93), (60, 93), (85, 93), (110, 93),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (20, 22), (50, 22), (80, 22), (110, 22),
            (20, 48), (50, 48), (80, 48), (110, 48),
            (20, 68), (50, 68), (80, 68), (110, 68),
            (20, 88), (50, 88), (80, 88), (110, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (80, 30), (30, 65), (80, 65),
            (55, 15), (55, 85), (5, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(8, 90), (112, 90), (8, 8), (112, 8), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 6), (70, 6), (50, 93), (70, 93), (5, 48), (113, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + initial road grid"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Horizontal wire spine connecting them
    for x in range(42, 80):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spurs from spine
    for y in range(44, 57):
        actions.append((Tool.WIRE, 40, y))
        actions.append((Tool.WIRE, 80, y))
    # Horizontal wire arms
    for x in range(30, 40):
        actions.append((Tool.WIRE, x, 50))
    for x in range(80, 90):
        actions.append((Tool.WIRE, x, 50))
    # Initial road grid near center
    for x in range(35, 86):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 35, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 85, y))
    return actions[:20]  # keep small


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- PRIORITY 1: Ensure enough coal plants ----
    # Count plants; add one per ~200 pop or if fewer than 2
    plant_ys, plant_xs = np.where(pm)
    n_plants = len(plant_xs)
    needed_plants = max(2, 2 + pop // 300)

    if n_plants < needed_plants:
        # Place plant far from existing ones, in empty area
        # Try candidate positions in a grid pattern
        best_x, best_y, best_score = None, None, -1
        for gy in range(10, 95, 20):
            for gx in range(10, 115, 25):
                if not ib(gx, gy):
                    continue
                if not bool(em[gy, gx]):
                    continue
                # Check 3x3 clear
                clear = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        nx, ny = gx+dx, gy+dy
                        if not ib(nx, ny) or not bool(em[ny, nx]):
                            clear = False
                            break
                    if not clear:
                        break
                if not clear:
                    continue
                # Score: prefer far from existing plants
                min_d = 9999
                for i in range(len(plant_xs)):
                    d = abs(gx - int(plant_xs[i])) + abs(gy - int(plant_ys[i]))
                    min_d = min(min_d, d)
                if min_d > best_score:
                    best_score = min_d
                    best_x, best_y = gx, gy
        if best_x is not None:
            return (Tool.COALPOWER, best_x, best_y)

    # ---- BUILD WIRE NETWORK ----
    # Strategy: grow wires outward from existing wire/plant network
    # to cover the whole map with corridors

    # Define wire corridor targets: horizontal rows and vertical columns
    wire_rows = [10, 25, 40, 55, 70, 85]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 115]

    # Phase alternation for wire vs road vs zone
    phase = step % 6

    if phase in (0, 1):
        # Extend wire corridors
        if phase == 0:
            # Horizontal corridors
            for wr in wire_rows:
                # Find leftmost gap in corridor
                connected_to_power = False
                for wx in range(0, WORLD_W):
                    if bool(wm[wr, wx]) or bool(pm[wr, wx]):
                        connected_to_power = True
                # Scan for a gap next to existing wire/plant
                for wx in range(0, WORLD_W):
                    if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                        # Check if adjacent tile has wire or plant
                        adj = False
                        for adx in [-1, 1]:
                            ax = wx + adx
                            if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                                adj = True
                                break
                        if adj:
                            return (Tool.WIRE, wx, wr)
        else:
            # Vertical corridors
            for wc in wire_cols:
                for wy in range(0, WORLD_H):
                    if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                        adj = False
                        for ady in [-1, 1]:
                            ay = wy + ady
                            if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                                adj = True
                                break
                        if adj:
                            return (Tool.WIRE, wc, wy)

        # Connect corridors: if a wire row doesn't have wire yet, try to add one
        # near a plant
        for px_i in range(len(plant_xs)):
            px, py = int(plant_xs[px_i]), int(plant_ys[px_i])
            # Extend wire toward nearest wire row
            best_wr, best_dist = None, 999
            for wr in wire_rows:
                d = abs(py - wr)
                if d < best_dist:
                    best_dist = d
                    best_wr = wr
            if best_wr is not None and best_dist > 0:
                dy = 1 if best_wr > py else -1
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]):
                    return (Tool.WIRE, px, ny)
            # Extend wire toward nearest wire col
            best_wc, best_dist = None, 999
            for wc in wire_cols:
                d = abs(px - wc)
                if d < best_dist:
                    best_dist = d
                    best_wc = wc
            if best_wc is not None and best_dist > 0:
                dx = 1 if best_wc > px else -1
                nx = px + dx
                if ib(nx, py) and bool(em[py, nx]):
                    return (Tool.WIRE, nx, py)

    elif phase in (2, 3):
        # Build road network
        # Roads parallel to wire corridors (offset by 1)
        # and cross streets

        if phase == 2:
            # Roads adjacent to wire rows (above and below)
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not ib(0, ry):
                        continue
                    # Find segment adjacent to existing road
                    for rx in range(0, WORLD_W):
                        if not ib(rx, ry):
                            continue
                        if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                            # Check: wire exists at wr,rx (so road is powered-adjacent)
                            if not (bool(wm[wr, rx]) or bool(pm[wr, rx])):
                                continue
                            # Check adjacent to existing road
                            adj = False
                            for adx in [-1, 1]:
                                ax = rx + adx
                                if ib(ax, ry) and bool(rm[ry, ax]):
                                    adj = True
                                    break
                            # Also check if start of corridor (near plant or wire col)
                            for wc in wire_cols:
                                if abs(rx - wc) <= 1:
                                    adj = True
                            if adj:
                                return (Tool.ROAD, rx, ry)
        else:
            # Roads adjacent to wire columns
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not ib(rcx, 0):
                        continue
                    for ry in range(0, WORLD_H):
                        if not ib(rcx, ry):
                            continue
                        if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                            if not (bool(wm[ry, wc]) or bool(pm[ry, wc])):
                                continue
                            adj = False
                            for ady in [-1, 1]:
                                ay = ry + ady
                                if ib(rcx, ay) and bool(rm[ay, rcx]):
                                    adj = True
                                    break
                            for wr in wire_rows:
                                if abs(ry - wr) <= 1:
                                    adj = True
                            if adj:
                                return (Tool.ROAD, rcx, ry)

        # Cross streets between wire corridors
        for row_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[row_idx], wire_rows[row_idx + 1]
            mid_y = (r1 + r2) // 2
            for wc in wire_cols:
                for offset in [-1, 1]:
                    cx = wc + offset
                    if not ib(cx, mid_y):
                        continue
                    if bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        adj = False
                        for ady in [-1, 1]:
                            ay = mid_y + ady
                            if ib(cx, ay) and bool(rm[ay, cx]):
                                adj = True
                        if adj:
                            return (Tool.ROAD, cx, mid_y)

    else:
        # Phase 4,5: Zone placement
        # Compute neighbor road (within 2) and power (within 5) masks
        nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2 in range(-2, 3):
            for dx2 in range(-2, 3):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2 in range(-5, 6):
            for dx2 in range(-5, 6):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
                nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        # Civic services
        if pop > 150:
            fire_positions = [
                (20, 20), (60, 20), (100, 20),
                (20, 50), (60, 50), (100, 50),
                (20, 80), (60, 80), (100, 80),
            ]
            for (sx, sy) in fire_positions:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 400:
            police_positions = [
                (35, 30), (75, 30), (35, 70), (75, 70),
                (15, 50), (105, 50),
            ]
            for (sx, sy) in police_positions:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        # Determine zone type needed
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.28:
            tool = Tool.INDUSTRIAL
        elif cr < 0.28:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.RESIDENTIAL

        # Zone clear check
        zone_tiles = resm | comm | indm

        def zone_clear(zx, zy):
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    nr, nc = zy + dr, zx + dc
                    if not ib(nc, nr):
                        return False
                    if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                        return False
            return True

        # Candidate zone centers: empty, near road, near power
        cand_mask = em & nbr_road & nbr_power
        # Margin
        cand_mask[0:2, :] = False
        cand_mask[WORLD_H-2:, :] = False
        cand_mask[:, 0:2] = False
        cand_mask[:, WORLD_W-2:] = False

        cys, cxs = np.where(cand_mask)
        if len(cxs) > 0:
            # Score: prefer near center of map but spread out
            cx_center = WORLD_W // 2
            cy_center = WORLD_H // 2
            # Use a rotating offset to spread placements
            offset = (step * 17) % max(len(cxs), 1)
            # Score by road proximity (lower=better) + distance from center (lower=better)
            road_ys_arr, road_xs_arr = np.where(rm)
            for i in range(min(len(cxs), 500)):
                k = (offset + i) % len(cxs)
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

    # ---- FALLBACK: extend road from existing ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        nbr_power2 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2 in range(-5, 6):
            for dx2 in range(-5, 6):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
                nbr_power2[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power2[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power2[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plants and initial road/wire skeleton"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally through center
    for x in range(33, 88, 1):
        actions.append((Tool.WIRE, x, 50))
    # Main horizontal roads at key rows
    for x in range(3, 118):
        actions.append((Tool.ROAD, x, 43))
        actions.append((Tool.ROAD, x, 57))
    # Vertical spine roads
    for y in range(3, 98):
        actions.append((Tool.ROAD, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # Fast dilate using slice operations
    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        # Target ratio: 50% res, 30% com, 20% ind
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure coal plants spread across map ----
    # Grid of plants every 20 cols, 20 rows
    plant_grid = []
    for py in range(10, 95, 20):
        for px in range(10, 115, 20):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion — connect power to unpowered areas ----
    # Find tiles adjacent to existing power sources
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    # Wire candidate: empty, adjacent to power, not on road or zone
    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    # Check for unpowered plants
    unpowered_plants = [(px, py) for px, py in plant_grid
                        if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Wire toward unpowered zones
    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            sample = min(50, len(zxs))
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(sample))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid — horizontal roads every 6 rows ----
    road_rows = list(range(6, 97, 6))
    for ry in road_rows:
        row_road = rm[ry, :]
        if int(np.sum(row_road)) < 110:
            # Find first gap near power, adjacent to existing road
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    left_ok = rx > 0 and bool(rm[ry, rx-1])
                    right_ok = rx < WORLD_W-1 and bool(rm[ry, rx+1])
                    up_ok = ry > 0 and bool(rm[ry-1, rx])
                    down_ok = ry < WORLD_H-1 and bool(rm[ry+1, rx])
                    if left_ok or right_ok or up_ok or down_ok:
                        return (Tool.ROAD, rx, ry)
            # Fallback: start near power
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Vertical connector roads every 10 cols
    road_cols = list(range(10, 116, 10))
    for cx in road_cols:
        col_road = rm[:, cx]
        if int(np.sum(col_road)) < 90:
            for cy in range(4, 96):
                if bool(em[cy, cx]) and bool(near_power[cy, cx]):
                    adj = ((cy > 0 and bool(rm[cy-1, cx])) or
                           (cy < WORLD_H-1 and bool(rm[cy+1, cx])) or
                           (cx > 0 and bool(rm[cy, cx-1])) or
                           (cx < WORLD_W-1 and bool(rm[cy, cx+1])))
                    if adj:
                        return (Tool.ROAD, cx, cy)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    zone_cand &= ~rm & ~wm & ~pm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(rm[nr, nc]) or bool(wm[nr, nc]) or bool(pm[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 300)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.ones(len(cxs_arr)) * 9999.0

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 300)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer close to roads, moderate spread from existing zones
            score = road_dist * 2.0 - np.clip(zone_dist, 0, 30) * 0.5
        else:
            # Start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) + road_dist

        order = np.argsort(score)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(px2, py2) for py2 in range(10, 92, 14) for px2 in range(10, 112, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_grid = [(pkx, pky) for pky in range(6, 95, 8) for pkx in range(6, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 700:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (60, 50), (100, 50),
                        (20, 85), (60, 85), (100, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (40, 10), (80, 10), (40, 90), (80, 90)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(95, 10), (10, 10), (95, 85), (10, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from existing road ----
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k = (step * 13) % len(rxs2)
        rx2, ry2 = int(rxs2[k]), int(rys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from power ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire spines + road grid"""
    actions = []
    # Central coal plant
