def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 45% res, 30% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Infrastructure layout: roads every 8 rows/cols, wires offset by 4
    # Two neighborhoods: left (x=5..55) and right (x=65..115)
    # Wire rows and cols
    wire_rows = list(range(8, 100, 8))   # 8,16,24,...,96
    wire_cols = [30, 90]                  # main vertical wire spines
    road_rows = list(range(12, 100, 8))  # 12,20,28,...,92 (between wire rows)
    road_cols = [20, 40, 70, 100]        # vertical roads in each neighborhood

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure enough coal plants spread across map
    if phase == 0:
        plant_targets = [
            (30, 20), (90, 20), (30, 80), (90, 80),
            (10, 50), (110, 50), (60, 15), (60, 85),
            (15, 35), (105, 35), (15, 65), (105, 65),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1-2: Build horizontal wire rows
    if phase in (1, 2):
        target_rows = wire_rows[::2] if phase == 1 else wire_rows[1::2]
        for wr in target_rows:
            if wr >= WORLD_H:
                continue
            for wx in range(2, WORLD_W - 2):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Phase 3-4: Build vertical wire spines
    if phase in (3, 4):
        target_cols = wire_cols + [10, 50, 70, 110] if phase == 3 else [20, 40, 60, 80, 100]
        for wc in target_cols:
            if wc >= WORLD_W:
                continue
            for wy in range(2, WORLD_H - 2):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # Phase 5-6: Build horizontal roads
    if phase == 5:
        for rr in road_rows:
            if rr >= WORLD_H:
                continue
            for rx in range(2, WORLD_W - 2):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]) and not bool(wm[rr, rx]):
                    adj = (rx > 0 and bool(rm[rr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or \
                          (rr > 0 and bool(rm[rr-1, rx])) or \
                          (rr < WORLD_H-1 and bool(rm[rr+1, rx]))
                    if adj or rx == 2:
                        return (Tool.ROAD, rx, rr)

    # Phase 6: Build vertical roads
    if phase == 6:
        for rc in road_cols:
            if rc >= WORLD_W:
                continue
            for ry in range(2, WORLD_H - 2):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]) and not bool(wm[ry, rc]):
                    adj = (ry > 0 and bool(rm[ry-1, rc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or \
                          (rc > 0 and bool(rm[ry, rc-1])) or \
                          (rc < WORLD_W-1 and bool(rm[ry, rc+1]))
                    if adj or ry == 2:
                        return (Tool.ROAD, rc, ry)

    # Phase 7: Wire unpowered zones toward nearest wire/plant
    if phase == 7:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Extra roads near unpowered zones to give road access
    if phase == 8:
        zoned_no_road = zone_tiles & ~near_road
        zr_ys, zr_xs = np.where(zoned_no_road)
        if len(zr_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 23) % len(zr_xs)
                tx, ty = int(zr_xs[idx]), int(zr_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Civic services based on population
    if pop > 10:
        # Fire stations at strategic points
        fire_spots = [
            (15, 25), (45, 25), (75, 25), (105, 25),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 75), (45, 75), (75, 75), (105, 75),
            (30, 10), (90, 10), (30, 90), (90, 90),
            (5, 40), (115, 40), (5, 60), (115, 60),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (25, 30), (55, 30), (85, 30), (115, 30),
            (25, 55), (55, 55), (85, 55), (115, 55),
            (25, 80), (55, 80), (85, 80), (115, 80),
            (10, 15), (110, 15), (10, 85), (110, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 250:
        stadium_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 60), (60, 60), (100, 60),
            (20, 85), (60, 85), (100, 85),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 400:
        nuke_spots = [
            (5, 10), (115, 10), (5, 90), (115, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5, 95), (115, 5), (5, 5), (115, 95), (60, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (110, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost when population growing
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        # Keep parks away from wire rows
        for wr in wire_rows:
            if 0 <= wr < WORLD_H:
                park_cands[max(0, wr-1):min(WORLD_H, wr+2), :] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (closed-loop primary action) ----
    # Two-neighborhood layout: left cluster (x~5-55) and right cluster (x~65-115)
    # Avoid wire rows/cols to keep infrastructure intact
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Exclude wire infrastructure rows
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    # Exclude wire spine cols
    for wc in [30, 90, 10, 50, 70, 110]:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False
    # Exclude road cols
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            cand_mask[:, max(0, rc-1):min(WORLD_W, rc+2)] = False
    # Exclude road rows
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            cand_mask[max(0, rr-1):min(WORLD_H, rr+2), :] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Grow in two neighborhoods simultaneously
        if pop < 80:
            # Start with dense center of each neighborhood
            active_centers = [
                (30, 50), (90, 50),
                (25, 42), (35, 42), (85, 42), (95, 42),
                (25, 58), (35, 58), (85, 58), (95, 58),
            ]
        elif pop < 300:
            # Expand neighborhoods outward
            active_centers = []
            for col in range(5):
                for row in range(6):
                    cx = 10 + col * 10
                    cy = 15 + row * 12
                    active_centers.append((cx, cy))
            for col in range(5):
                for row in range(6):
                    cx = 70 + col * 10
                    cy = 15 + row * 12
                    active_centers.append((cx, cy))
        elif pop < 800:
            # Fill both halves densely
            active_centers = []
            for col in range(6):
                for row in range(9):
                    cx = 7 + col * 9
                    cy = 7 + row * 10
                    active_centers.append((cx, cy))
            for col in range(6):
                for row in range(9):
                    cx = 65 + col * 9
                    cy = 7 + row * 10
                    active_centers.append((cx, cy))
        else:
            # Full map coverage
            active_centers = []
            for col in range(12):
                for row in range(10):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
