def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target ratio: 50% res, 25% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire/road corridor definitions matching init
    wire_rows = [30, 50, 70]
    wire_cols = [30, 60, 90]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 8)
    near_road = dilate(rm, 2)

    # ---- PHASE 0: Ensure power plants are present near active areas ----
    # Check if any area lacks a plant within 20 tiles
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) == 0:
        # No plant at all - emergency place one
        return (Tool.COALPOWER, 60, 50)

    # Dynamic neighborhood coverage based on population
    if pop < 300:
        active_zone_xs = [30, 60, 90]
        active_zone_ys = [30, 50, 70]
    elif pop < 1000:
        active_zone_xs = [15, 30, 45, 60, 75, 90, 105]
        active_zone_ys = [15, 30, 50, 70, 85]
    else:
        active_zone_xs = list(range(10, 120, 20))
        active_zone_ys = list(range(10, 100, 15))

    # ---- CLOSED-LOOP: Read current state and decide ----

    # Priority 1: If powered zones are few relative to zones, add more power infrastructure
    zone_count = res_count + com_count + ind_count
    power_deficit = zone_count > 0 and powered < zone_count * 0.5

    # Priority 2: Extend wires to cover unpowered regions
    if power_deficit or step % 12 < 2:
        # Find empty tiles adjacent to existing wire/plant that need power extension
        wire_or_plant = wm | pm
        # Expand wire toward any empty tile not yet powered
        unpowered_empty = em & ~near_power
        if np.any(unpowered_empty):
            # Find closest wire to unpowered area
            wp_ys, wp_xs = np.where(wire_or_plant)
            up_ys, up_xs = np.where(unpowered_empty)
            if len(wp_xs) > 0 and len(up_xs) > 0:
                # Pick a random unpowered spot to target
                target_idx = (step * 17) % len(up_xs)
                tx, ty = int(up_xs[target_idx]), int(up_ys[target_idx])
                # Find nearest wire
                dists = np.abs(wp_xs - tx) + np.abs(wp_ys - ty)
                best = np.argmin(dists)
                bwx, bwy = int(wp_xs[best]), int(wp_ys[best])
                # Step toward target
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                # Prefer to move in primary direction
                candidates = []
                if dx != 0:
                    candidates.append((bwx + dx, bwy))
                if dy != 0:
                    candidates.append((bwx, bwy + dy))
                for nx, ny in candidates:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # Priority 3: Extend roads to cover areas near power
    if step % 12 < 4:
        # Extend roads adjacent to existing roads into powered territory
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            # Find road tiles that have empty powered neighbors
            step_k = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 200)):
                k = (step_k + offset * 7) % len(road_xs)
                rx, ry = int(road_xs[k]), int(road_ys[k])
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = rx + dx, ry + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(near_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # Priority 4: Add additional coal plants in areas with zones but no nearby power
    if zone_count > 10 and step % 15 == 0:
        zone_ys_arr, zone_xs_arr = np.where(zone_tiles)
        if len(zone_xs_arr) > 0:
            # Find unpowered zones
            unpowered_zone_mask = zone_tiles & ~near_power
            if np.any(unpowered_zone_mask):
                uz_ys, uz_xs = np.where(unpowered_zone_mask)
                # Place a coal plant near the most unpowered cluster
                cx = int(np.mean(uz_xs))
                cy = int(np.mean(uz_ys))
                # Find empty spot near center
                for r in range(1, 20):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = cx + dx, cy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- ZONE PLACEMENT (main action) ----
    cand_mask = em & near_road & near_power
    # Keep away from edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Avoid placing on wire corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates by distance to active neighborhoods
        best_dist = np.full(len(cxs), 999999.0)
        for ax in active_zone_xs:
            for ay in active_zone_ys:
                d = np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float)
                best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_grid = [(15, 10), (45, 10), (75, 10), (105, 10),
                     (15, 40), (45, 40), (75, 40), (105, 40),
                     (15, 60), (60, 60), (105, 60),
                     (15, 85), (45, 85), (75, 85), (105, 85)]
        for sx, sy in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_grid = [(30, 15), (75, 15), (50, 45), (100, 45),
                       (20, 60), (70, 60), (15, 88), (55, 88), (95, 88)]
        for sx, sy in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(48, 48), (72, 48), (48, 68), (72, 68),
                    (20, 48), (100, 48), (20, 68), (100, 68)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(10, 10), (110, 10), (10, 90), (110, 90),
                      (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 10), (70, 10), (50, 88), (70, 88)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near zones for land value boost
    if pop > 150 and step % 6 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: Extend wire from existing wire toward untouched area ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys2, zone_xs2 = np.where(zone_tiles)
    if len(zone_xs2) > 0:
        k = (step * 19) % len(zone_xs2)
        zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with wire cross and road grid."""
    actions = []
    cx, cy = 60, 50
    # Central power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending outward
    for d in range(1, 15):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Two horizontal roads flanking the wire
    for dx in range(-12, 13):
        actions.append((Tool.ROAD, cx + dx, cy - 3))
        actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% RES, 30% COM, 20% IND
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood anchors in a 3x3 grid (9 neighborhoods), expanding with pop
    # Each has a coal plant and road/wire around it
    all_anchors = [
        (30, 25), (60, 25), (90, 25),
        (30, 50), (60, 50), (90, 50),
        (30, 75), (60, 75), (90, 75),
    ]

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 3
        if pop < 500:   return 5
        if pop < 900:   return 7
        return 9

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
        x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 8):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE CROSS at each anchor ----
    spine = min(10, 5 + pop // 50)
    for (px, py) in active_anchors:
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- CONNECT POWER BETWEEN ANCHORS horizontally ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx in range(x1a + 1, x2a):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- CONNECT POWER vertically ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy in range(y1a + 1, y2a):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: horizontal roads above and below each wire row ----
    for (px, py) in active_anchors:
        for road_dy in [-3, 3]:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- VERTICAL ROADS connecting rows ----
    if pop > 30:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1a = col_anchors[i]
                _, y2a = col_anchors[i + 1]
                for road_x in [xl + 4, xl - 4]:
                    for cy in range(y1a, y2a + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD ZONE CANDIDATE MASK ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled to pop ----
    if pop > 100:
        fire_spots = [
            (15, 20), (50, 20), (85, 20), (115, 20),
            (15, 50), (50, 50), (85, 50), (115, 50),
            (15, 80), (50, 80), (85, 80), (115, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (20, 15), (60, 15), (100, 15),
            (20, 55), (60, 55), (100, 55),
            (20, 85), (60, 85), (100, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for sp in [(10, 5), (60, 5), (110, 5), (10, 94), (60, 94), (110, 94)]:
            sx, sy = sp
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        for np2 in [(5, 5), (115, 5), (5, 94), (115, 94)]:
            nx2, ny2 = np2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        for ap in [(55, 6), (5, 50), (115, 50)]:
            ax, ay = ap
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 300:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

