def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # --- DYNAMIC PLANT PLACEMENT ---
    # Add more plants as population grows, spread across map
    plant_targets = [(40, 50), (80, 50)]
    if pop > 500:
        plant_targets += [(20, 25), (60, 25), (100, 25)]
    if pop > 1500:
        plant_targets += [(20, 75), (60, 75), (100, 75)]
    if pop > 3000:
        plant_targets += [(40, 10), (80, 10), (40, 90), (80, 90)]

    for (px, py) in plant_targets:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 4), min(WORLD_W, px + 5)
        y0, y1 = max(0, py - 4), min(WORLD_H, py + 5)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Try nearby
            for r in range(1, 5):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- REACTIVE WIRE EXTENSION ---
    # Find all plant tiles and extend wire outward reactively
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # For each plant, check if wire extends far enough in each direction
        for i in range(len(plant_xs)):
            px_abs = int(plant_xs[i])
            py_abs = int(plant_ys[i])
            for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                ddx, ddy = direction
                # Walk from plant outward, find first gap in wire
                for dist in range(1, 25):
                    wx = px_abs + ddx * dist
                    wy = py_abs + ddy * dist
                    if not ib(wx, wy):
                        break
                    if bool(pm[wy, wx]):
                        break
                    if bool(wm[wy, wx]):
                        continue  # wire already here, keep going
                    # Gap found - fill it if empty or road
                    if bool(em[wy, wx]) or bool(rm[wy, wx]):
                        return (Tool.WIRE, wx, wy)
                    else:
                        break  # blocked by something solid

    # --- CONNECT WIRE SEGMENTS ---
    # Find wire endpoints and extend toward nearest other wire
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        # Sample some wire tiles and try to extend
        sk = (step * 17) % len(wire_xs)
        for off in range(min(len(wire_xs), 60)):
            k = (sk + off * 7) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            # Prefer extending toward a plant we know about
            best_dir = None
            best_score = -1
            for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2 + ddx, wy2 + ddy
                if not ib(nx, ny):
                    continue
                if bool(wm[ny, nx]) or bool(pm[ny, nx]):
                    continue
                if bool(em[ny, nx]) or bool(rm[ny, nx]):
                    # Score by proximity to nearest plant
                    if len(plant_xs) > 0:
                        dists = np.abs(plant_xs - nx) + np.abs(plant_ys - ny)
                        score = -float(np.min(dists))
                    else:
                        score = 0
                    if score > best_score:
                        best_score = score
                        best_dir = (nx, ny)
            # Also extend toward areas without wire coverage
            if best_dir is not None and best_score < -5:
                # Only extend if it would cover new territory
                nx, ny = best_dir
                return (Tool.WIRE, nx, ny)

    # --- ROAD NETWORK: REACTIVE ---
    # Build roads adjacent to existing roads, preferring wire-covered areas
    # Build "near wire or plant" mask
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-2, 3):
        for ddx in range(-2, 3):
            r0s = max(0, -ddy); r1s = min(WORLD_H, WORLD_H - ddy)
            c0s = max(0, -ddx); c1s = min(WORLD_W, WORLD_W - ddx)
            r0d = max(0, ddy); r1d = min(WORLD_H, WORLD_H + ddy)
            c0d = max(0, ddx); c1d = min(WORLD_W, WORLD_W + ddx)
            nbr_power[r0d:r1d, c0d:c1d] |= wm[r0s:r1s, c0s:c1s]
            nbr_power[r0d:r1d, c0d:c1d] |= pm[r0s:r1s, c0s:c1s]

    # Build roads flanking wire spines
    # Scan wire tiles and place roads next to them if empty
    if len(wire_xs) > 0:
        sk2 = (step * 3) % len(wire_xs)
        for off in range(min(len(wire_xs), 100)):
            k = (sk2 + off * 11) % len(wire_xs)
            wx3, wy3 = int(wire_xs[k]), int(wire_ys[k])
            # Try perpendicular placement (road beside wire)
            # For horizontal wire, try up/down; for vertical, try left/right
            # Check which directions the wire runs
            h_wire = (ib(wx3 - 1, wy3) and bool(wm[wy3, wx3 - 1])) or \
                     (ib(wx3 + 1, wy3) and bool(wm[wy3, wx3 + 1]))
            v_wire = (ib(wx3, wy3 - 1) and bool(wm[wy3 - 1, wx3])) or \
                     (ib(wx3, wy3 + 1) and bool(wm[wy3 + 1, wx3]))

            if h_wire:
                for ry in [wy3 - 1, wy3 + 1]:
                    if ib(wx3, ry) and bool(em[ry, wx3]) and not bool(pm[ry, wx3]):
                        return (Tool.ROAD, wx3, ry)
            if v_wire:
                for rx in [wx3 - 1, wx3 + 1]:
                    if ib(rx, wy3) and bool(em[wy3, rx]) and not bool(pm[wy3, rx]):
                        return (Tool.ROAD, rx, wy3)

    # Extend existing roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk3 = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 80)):
            k = (sk3 + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for ddx, ddy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + ddx, ry2 + ddy
                if (ib(nx2, ny2) and bool(em[ny2, nx2])
                        and not bool(pm[ny2, nx2])
                        and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- ZONE PLACEMENT: REACTIVE ---
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% res, 35% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build "near road" mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for ddy in range(-2, 3):
        for ddx in range(-2, 3):
            r0s = max(0, -ddy); r1s = min(WORLD_H, WORLD_H - ddy)
            c0s = max(0, -ddx); c1s = min(WORLD_W, WORLD_W - ddx)
            r0d = max(0, ddy); r1d = min(WORLD_H, WORLD_H + ddy)
            c0d = max(0, ddx); c1d = min(WORLD_W, WORLD_W + ddx)
            nbr_road[r0d:r1d, c0d:c1d] |= rm[r0s:r1s, c0s:c1s]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer candidates near existing zones (density) and near plants
        # Also use step-based offset for variety
        if len(plant_xs) > 0:
            best_plant_dist = np.full(len(cxs), 999999.0)
            for i in range(len(plant_xs)):
                d = np.abs(cxs - int(plant_xs[i])) + np.abs(cys - int(plant_ys[i]))
                best_plant_dist = np.minimum(best_plant_dist, d)
        else:
            best_plant_dist = np.zeros(len(cxs))

        # Also score by proximity to existing zones (cluster building)
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            best_zone_dist = np.full(len(cxs), 999999.0)
            # Sample zones for performance
            sample_size = min(len(zone_xs), 50)
            sidx = np.linspace(0, len(zone_xs) - 1, sample_size, dtype=int)
            for i in sidx:
                d = np.abs(cxs - int(zone_xs[i])) + np.abs(cys - int(zone_ys[i]))
                best_zone_dist = np.minimum(best_zone_dist, d)
            # Combined score: close to plant but also cluster
            score = best_plant_dist * 0.5 + best_zone_dist * 0.3
        else:
            score = best_plant_dist

        order = np.argsort(score)
        offset_base = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(offset_base + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- CIVIC SERVICES (reactive to population) ---
    if pop > 100:
        fire_spots = [(20, 20), (60, 20), (100, 20),
                      (20, 50), (60, 50), (100, 50),
                      (20, 80), (60, 80), (100, 80),
                      (40, 35), (80, 35), (40, 65), (80, 65)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [(30, 30), (70, 30), (110, 30),
                        (30, 60), (70, 60), (110, 60),
                        (30, 85), (70, 85), (110, 85)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(35, 40), (75, 40), (35, 70), (75, 70)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(55, 5), (55, 90), (5, 50)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- PARKS for happiness ---
    if pop > 200 and step % 5 == 0:
        pk_cands = np.where(em & nbr_road & nbr_power)
        if len(pk_cands[0]) > 0:
            idx = (step * 23) % len(pk_cands[0])
            py2, px2 = int(pk_cands[0][idx]), int(pk_cands[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- FALLBACK: extend wire anywhere empty ---
    if len(wire_xs) > 0:
        sk4 = (step * 19) % len(wire_xs)
        for off in range(min(len(wire_xs), 40)):
            k = (sk4 + off * 11) % len(wire_xs)
            wx4, wy4 = int(wire_xs[k]), int(wire_ys[k])
            for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx4, ny4 = wx4 + ddx, wy4 + ddy
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    return (Tool.WIRE, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spine + road grid starter"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire connecting them through center
    for x in range(28, 93):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from plants
    for y in range(10, 90):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Horizontal road spines
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 60))
    # Vertical road spines
    for y in range(1, 99):
        actions.append((Tool.ROAD, 20, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 40% res, 35% com, 25% ind
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Infrastructure definitions - different from parent
    # Fewer, more evenly spaced power plants
    # Wire runs at rows: 15, 30, 50, 70, 85
    # Wire runs at cols: 10, 30, 50, 70, 90, 110
    wire_rows = [15, 30, 50, 70, 85]
    wire_cols = [10, 30, 50, 70, 90, 110]
    # Roads between wire lines
    road_rows = [20, 25, 35, 44, 55, 60, 76, 80]
    road_cols = [5, 15, 18, 38, 42, 58, 62, 78, 82, 98, 102, 115]

    phase = step % 12

    # Phase 0: Add more coal plants if needed
    if phase == 0:
        plant_targets = []
        for py in [15, 50, 85]:
            for px in [10, 30, 60, 90, 110]:
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 18), min(WORLD_W, px + 19)
            y0, y1 = max(0, py - 18), min(WORLD_H, py + 19)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill wire rows
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    if bool(em[wr, wx]):
                        left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                        right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                        if left or right or wx <= 2:
                            return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire cols
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    if bool(em[wy, wc]):
                        up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                        dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                        if up or dn or wy <= 2:
                            return (Tool.WIRE, wc, wy)

    # Phase 3: Horizontal roads
    if phase == 3:
        for rr in road_rows:
            if not (0 < rr < WORLD_H):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    left = rx > 0 and bool(rm[rr, rx-1])
                    right = rx < WORLD_W-1 and bool(rm[rr, rx+1])
                    up = rr > 0 and bool(rm[rr-1, rx])
                    dn = rr < WORLD_H-1 and bool(rm[rr+1, rx])
                    if left or right or up or dn or rx == 1:
                        return (Tool.ROAD, rx, rr)

    # Phase 4: Vertical roads
    if phase == 4:
        for rc in road_cols:
            if not (0 < rc < WORLD_W):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    up = ry > 0 and bool(rm[ry-1, rc])
                    dn = ry < WORLD_H-1 and bool(rm[ry+1, rc])
                    left = rc > 0 and bool(rm[ry, rc-1])
                    right = rc < WORLD_W-1 and bool(rm[ry, rc+1])
                    if up or dn or left or right or ry == 1:
                        return (Tool.ROAD, rc, ry)

    # Phase 5: Connect unpowered zones with wire
    if phase == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                bi = np.argmin(dists)
                bwx, bwy = int(wire_xs[bi]), int(wire_ys[bi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 6: Connect unroaded zones with road
    if phase == 6:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                bi = np.argmin(dists)
                brx, bry = int(road_xs[bi]), int(road_ys[bi])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (closed-loop) ----
    if pop > 10:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 50), (115, 50),
            (5, 95), (60, 95), (115, 95),
            (25, 25), (95, 25), (25, 75), (95, 75),
            (40, 40), (80, 40), (40, 65), (80, 65),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 50:
        police_spots = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 90), (45, 90), (75, 90), (105, 90),
            (5, 40), (115, 40), (5, 60), (115, 60),
            (35, 50), (65, 50), (95, 50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (20, 20), (70, 20), (20, 75), (70, 75),
            (50, 45), (100, 45),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 400:
        # Upgrade to nuclear for more power
        nuke_spots = [
            (10, 50), (110, 50), (60, 10), (60, 90),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5, 90), (115, 90), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        for wr in wire_rows:
            if 0 <= wr < WORLD_H:
                park_cands[max(0, wr-1):min(WORLD_H, wr+2), :] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT ----
    # Exclude infrastructure corridors
    excl_rows = set(wire_rows)
    for r in road_rows:
        excl_rows.add(r)
    excl_cols = set(wire_cols)
    for c in road_cols:
        excl_cols.add(c)

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in excl_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-2):min(WORLD_H, wr+3), :] = False
    for wc in excl_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-2):min(WORLD_W, wc+3)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Three-neighborhood approach: left, center, right clusters
        if pop < 100:
            active_centers = [
                (30, 50), (60, 50), (90, 50),
                (30, 40), (60, 40), (90, 40),
                (30, 60), (60, 60), (90, 60),
            ]
        elif pop < 400:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 12 + col * 16
                    cy = 12 + row * 18
                    active_centers.append((cx, cy))
        elif pop < 1000:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 8 + col * 13
                    cy = 8 + row * 13
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a row with wire and road spines."""
    actions = []
    # Three power plants horizontally spread
    plants = [(30, 50), (60, 50), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-8, 9):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
    # Initial roads along two horizontal corridors
    for cx in range(10, 110):
        actions.append((Tool.ROAD, cx, 45))
        actions.append((Tool.ROAD, cx, 55))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 40% RES, 35% COM, 25% IND
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of anchor points — denser than parent
    all_anchors = []
    for ax in [15, 30, 45, 60, 75, 90, 105]:
        for ay in [15, 28, 41, 50, 59, 72, 85]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 6
        if pop < 300:  return 10
        if pop < 500:  return 14
        if pop < 800:  return 20
        if pop < 1500: return 28
        if pop < 2500: return 35
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE EXPANSION ----
    wire_half = min(22, 8 + pop // 10)
    vert_half = min(16, 5 + pop // 15)

    # Horizontal wire spines
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    # Vertical wire spines
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- WIRE CONNECTIONS between anchors in same column ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    # Wire connections in same row
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: roads at offset ±3 from wire spines (wider spacing) ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-3, 3]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx + ddx, road_y) and bool(rm[road_y, cx + ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y - 1) and bool(wm[road_y - 1, cx])) or \
                               (ib(cx, road_y + 1) and bool(wm[road_y + 1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # Vertical roads flanking vertical wire spines
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-3, 3]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy + ddy) and bool(rm[cy + ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x - 1, cy) and bool(wm[cy, road_x - 1])) or \
                               (ib(road_x + 1, cy) and bool(wm[cy, road_x + 1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive) ----
    if pop > 30:
        fire_spots = [
            (7, 7), (25, 7), (45, 7), (65, 7), (85, 7), (105, 7),
            (7, 25), (25, 25), (45, 25), (65, 25), (85, 25), (105, 25),
            (7, 45), (25, 45), (45, 45), (65, 45), (85, 45), (105, 45),
            (7, 65), (25, 65), (45, 65), (65, 65), (85, 65), (105, 65),
            (7, 85), (25, 85), (45, 85), (65, 85), (85, 85), (105, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (12, 3), (37, 3), (62, 3), (87, 3), (112, 3),
            (12, 20), (37, 20), (62, 20), (87, 20), (112, 20),
            (12, 40), (37, 40), (62, 40), (87, 40), (112, 40),
            (12, 60), (37, 60), (62, 60), (87, 60), (112, 60),
            (12, 80), (37, 80), (62, 80), (87, 80), (112, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(20, 3), (60, 3), (100, 3), (20, 94), (60, 94), (100, 94)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        for (nx2, ny2) in [(5, 3), (115, 3), (5, 94), (115, 94), (60, 3), (60, 94)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for (ax2, ay2) in [(55, 4), (5, 50), (115, 50), (55, 94)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for (sx2, sy2) in [(5, 92), (115, 92), (60, 96), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 6 coal plants + wire grid + initial roads"""
    actions = []
    # 6 coal plants in 2 rows of 3
