    # Vertical wire corridors connecting the two horizontal corridors
    for wc in [20, 60, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wc, y))
    # Roads flanking wire corridors
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 19))
