def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire/road corridor definitions - 5x5 grid of neighborhoods
    wire_rows = [20, 40, 55, 75, 90]
    wire_cols = [20, 40, 60, 80, 100]

    # 25 neighborhoods on a 5x5 grid
    nh_positions = []
    for row in range(5):
        for col in range(5):
            cx = 10 + col * 25   # 10, 35, 60, 85, 110
            cy = 10 + row * 20   # 10, 30, 50, 70, 90
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 200:
            return [nh_positions[6], nh_positions[7], nh_positions[11], nh_positions[12]]
        elif pop < 600:
            return nh_positions[5:20]
        elif pop < 1500:
            return nh_positions[2:23]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # Efficient dilation using numpy slicing
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- PHASE 0: Ensure power plants near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 8

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left = wx > 0 and bool(row_wire[wx - 1])
                    right = wx < WORLD_W - 1 and bool(row_wire[wx + 1])
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up = wy > 0 and bool(col_wire[wy - 1])
                    down = wy < WORLD_H - 1 and bool(col_wire[wy + 1])
                    if (up or down) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Seed wire corridors near plants if empty
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    px2, py2 = int(plant_xs[best]), int(plant_ys[best])
                    if ib(px2, wr) and bool(em[wr, px2]):
                        return (Tool.WIRE, px2, wr)

    elif phase == 3:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Cross streets every ~6 tiles between wire col corridors
        for col_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[col_idx], wire_cols[col_idx + 1]
            for mid_x in range(c1 + 6, c2, 6):
                for ry in range(1, WORLD_H - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                        adj_road = (ib(mid_x, ry - 1) and bool(rm[ry - 1, mid_x])) or \
                                   (ib(mid_x, ry + 1) and bool(rm[ry + 1, mid_x]))
                        if adj_road and bool(near_power[ry, mid_x]):
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Vertical cross roads between corridor intersections
        for wr_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            for wc_idx in range(len(wire_cols) - 1):
                c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
                mid_x = (c1 + c2) // 2
                for ry in range(r1 + 2, r2 - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                        adj = (ib(mid_x, ry - 1) and bool(rm[ry - 1, mid_x])) or \
                              (ib(mid_x, ry + 1) and bool(rm[ry + 1, mid_x]))
                        if adj and bool(near_power[ry, mid_x]):
                            return (Tool.ROAD, mid_x, ry)

    else:
        # Extend road from existing road near power
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % len(road_xs2)
            for offset in range(min(len(road_xs2), 100)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    # Don't place zones on wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_grid = [
            (10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
            (10, 30), (35, 30), (60, 30), (85, 30), (110, 30),
            (10, 50), (60, 50), (110, 50),
            (10, 70), (35, 70), (60, 70), (85, 70), (110, 70),
            (10, 92), (35, 92), (60, 92), (85, 92), (110, 92),
        ]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_grid = [
            (25, 15), (75, 15), (50, 40), (100, 40),
            (25, 60), (75, 60), (10, 85), (50, 85), (90, 85),
            (115, 25), (5, 45), (115, 65),
        ]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (45, 45), (75, 45), (45, 65), (75, 65),
            (15, 45), (105, 45), (15, 65), (105, 65),
            (60, 10), (60, 88),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [
            (50, 5), (70, 5), (50, 90), (70, 90),
            (5, 45), (5, 55), (110, 45), (110, 55),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire toward unpowered hoods ----
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: wire extension from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire connections + initial road grid"""
    actions = []
    # Two power plants: left cluster and right cluster
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire spine connecting both plants horizontally
    for x in range(32, 88):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for y in range(20, 48):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    for y in range(52, 80):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Horizontal roads at y=35, y=50 (skip plant area), y=65
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 35))
        actions.append((Tool.ROAD, x, 65))
    # Vertical roads at x=15, 45, 75, 105
    for y in range(28, 75):
        actions.append((Tool.ROAD, 15, y))
        actions.append((Tool.ROAD, 45, y))
        actions.append((Tool.ROAD, 75, y))
        actions.append((Tool.ROAD, 105, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Denser power plant grid - every 20 tiles in both dimensions
    plant_positions = []
    for py in range(15, 90, 20):
        for px in range(15, 110, 20):
            plant_positions.append((px, py))

    # PHASE 1: Place power plants where needed
    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # PHASE 2: Wire extension toward unpowered areas
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and not bool(near_power[py, px])]

    if len(wxs) > 0:
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:15])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0 and total_zones < 300:
            rng_idx = list(range(min(60, len(upxs))))
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in rng_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # PHASE 3: Denser road grid - every 5 tiles
    road_grid = []
    for gy in range(5, 97, 5):
        for gx in range(5, 115, 5):
            road_grid.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:50]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:15]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # PHASE 4: Zone placement with better COM/IND ratio
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        score = road_dist * 1.0 + np.maximum(0, 8 - zone_dist) * 3.0
        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # More balanced zone mix: RES 50%, COM 30%, IND 20%
        # React dynamically to current ratios
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        if ir < 0.20:
            tool = Tool.INDUSTRIAL
        elif cr < 0.30:
            tool = Tool.COMMERCIAL
        else:
            # Cycle: heavy residential with periodic COM/IND
            step_mod = step % 10
            if step_mod < 5:
                tool = Tool.RESIDENTIAL
            elif step_mod < 8:
                tool = Tool.COMMERCIAL
            else:
                tool = Tool.INDUSTRIAL

        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services scaled to population
    if pop > 40:
        fire_grid = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 115, 8)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 10)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_grid = [(pkx, pky) for pky in range(7, 95, 7) for pkx in range(7, 115, 7)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (60, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        nuke_locs = [(25, 25), (95, 25), (25, 75), (95, 75),
                     (60, 15), (60, 85), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 6), min(WORLD_W, nx + 7)
                y0, y1 = max(0, ny - 6), min(WORLD_H, ny + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 88), (100, 88)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend roads or wires near plants
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, -2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire grid + roads for early coverage."""
    actions = []
    # Plant 1: left cluster
    actions.append((Tool.COALPOWER, 30, 50))
    # Plant 2: right cluster
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, 30, 50 + dy))
            actions.append((Tool.WIRE, 90, 50 + dy))
    # Roads flanking left plant spine
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, 29, 50 + dy))
        actions.append((Tool.ROAD, 31, 50 + dy))
    # Roads flanking right plant spine
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, 89, 50 + dy))
        actions.append((Tool.ROAD, 91, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Two main cluster centers
    # Left cluster at x=30, right cluster at x=90
    # Multiple row neighborhoods
    left_rows  = [20, 35, 50, 65, 80]
    right_rows = [20, 35, 50, 65, 80]
    mid_rows   = [20, 35, 50, 65, 80]

    # Build neighborhood grid: (cx, cy) pairs
    nh_cols = [15, 30, 45, 60, 75, 90, 105]
    nh_rows = [15, 28, 41, 54, 67, 80, 93]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 700:   return 16
        if pop < 1500:  return 28
        if pop < 3000:  return 40
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Prioritize hoods near existing infrastructure (around x=30 and x=90)
    active_hoods = all_hoods[:n_active]

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # PHASE 1: Ensure each active hood has a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Grow wire toward uncovered hoods
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            for (tx, ty) in uncovered:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # PHASE 3: Road grid around each hood
    # For each active hood, place roads in a cross pattern at offsets ±4
    hood_cycle = step % max(len(active_hoods), 1)
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Horizontal road at hy-4, hy+4
        for ry in [hy - 4, hy + 4]:
            if not ib(hx, ry): continue
            for sign in [1, -1]:
                for dist in range(0, 7):
                    rx = hx + sign * dist
                    if not ib(rx, ry): continue
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]) and bool(nbr_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)
        # Vertical road at hx-4, hx+4
        for rx in [hx - 4, hx + 4]:
            if not ib(rx, hy): continue
            for sign in [1, -1]:
                for dist in range(0, 7):
                    ry = hy + sign * dist
                    if not ib(rx, ry): continue
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]) and bool(nbr_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # PHASE 4: Wire spine for each hood (cross at hood center)
    spine_range = 6
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                # Vertical
                wy2 = hy + sign * dist
                if ib(hx, wy2) and bool(em[wy2, hx]) and not bool(pm[wy2, hx]):
                    for ay in [wy2 - 1, wy2 + 1]:
                        if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                            return (Tool.WIRE, hx, wy2)
                # Horizontal
                wx2 = hx + sign * dist
                if ib(wx2, hy) and bool(em[hy, wx2]) and not bool(pm[hy, wx2]):
                    for ax in [wx2 - 1, wx2 + 1]:
                        if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                            return (Tool.WIRE, wx2, hy)

    # PHASE 5: Connect wire between adjacent hoods
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and 10 <= abs(hx2 - hx1) <= 16:
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 10 <= abs(hy2 - hy1) <= 16:
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # PHASE 6: Zone placement with balanced mix
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% RES, 35% COM, 25% IND
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 7: Extend roads into powered empty areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # CIVIC SERVICES
    if pop > 150:
        for fx in range(10, WORLD_W, 20):
            for fy in range(10, WORLD_H, 20):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 400:
        for px2 in range(15, WORLD_W, 25):
            for py2 in range(15, WORLD_H, 25):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 1000:
        for sx in range(20, WORLD_W, 35):
            for sy in range(20, WORLD_H, 35):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    # Nuclear power for growing cities
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(30, 50), (90, 50), (60, 25), (60, 75),
                         (15, 25), (105, 25), (15, 75), (105, 75)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 8), (75, 8), (45, 92), (75, 92)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new coal plant near uncovered hood
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire connections and initial roads."""
    actions = []
    # Three power plants in a triangle
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 60, 70))
    # Horizontal wire at y=20 connecting left and right plants
    for x in range(18, 103):
        actions.append((Tool.WIRE, x, 20))
    # Vertical wire from y=20 down to y=70 at x=60
    for y in range(20, 72):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads near each plant
    for x in range(14, 30):
        actions.append((Tool.ROAD, x, 27))
    for x in range(94, 110):
        actions.append((Tool.ROAD, x, 27))
    for x in range(54, 70):
        actions.append((Tool.ROAD, x, 63))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # --- Dilate helper (closed-loop, computed from current map) ---
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # Adjacency to power (1 tile)
    adj_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        if dy == -1: adj_power[:-1,:] |= power_src[1:,:]
        elif dy == 1: adj_power[1:,:] |= power_src[:-1,:]
        elif dx == -1: adj_power[:,:-1] |= power_src[:,1:]
        elif dx == 1: adj_power[:,1:] |= power_src[:,:-1]

    adj_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        if dy == -1: adj_road[:-1,:] |= rm[1:,:]
        elif dy == 1: adj_road[1:,:] |= rm[:-1,:]
        elif dx == -1: adj_road[:,:-1] |= rm[:,1:]
        elif dx == 1: adj_road[:,1:] |= rm[:,:-1]

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure power plants on a dense grid (~every 20 tiles) ---
    plant_xs = list(range(10, WORLD_W - 5, 20))
    plant_ys = list(range(10, WORLD_H - 5, 20))
    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                # Find nearest empty cell
                for r in range(0, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx+dx, ppy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Extend wire grid ---
    # Wire rows every 10 rows, wire cols every 10 cols
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    # Horizontal wire extension
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            # Connect from nearest power source
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left-1]) and not bool(pm[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W-2 and bool(em[wr, right+1]) and not bool(pm[wr, right+1]):
            return (Tool.WIRE, right+1, wr)

    # Vertical wire extension
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top-1, wc]) and not bool(pm[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H-2 and bool(em[bot+1, wc]) and not bool(pm[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)

    # --- PHASE 3: Road grid (midway between wire rows/cols) ---
    road_rows = sorted(set(wr+5 for wr in wire_rows if 3 < wr+5 < WORLD_H-3))
    road_cols = sorted(set(wc+5 for wc in wire_cols if 3 < wc+5 < WORLD_W-3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)

    # --- PHASE 4: Zone placement (reactive, from current map) ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Block wire and road rows/cols from zones
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist > 15, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.4
        order = np.argsort(score)
        off = (step * 11 + pop % 17) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Wire toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    wire_cand = em & adj_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 6: Road toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    road_cand2 = em & adj_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H-2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- PHASE 7: Civic services (reactive to population) ---
    if pop > 30:
        fire_ys = list(range(15, WORLD_H-5, 12))
        fire_xs = list(range(15, WORLD_W-5, 18))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        pol_ys = list(range(18, WORLD_H-5, 14))
        pol_xs = list(range(18, WORLD_W-5, 20))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_ys = list(range(12, WORLD_H-5, 10))
        park_xs = list(range(12, WORLD_W-5, 12))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 600:
        for sty in range(20, 85, 25):
            for stx in range(20, 100, 30):
                if ib(stx, sty) and bool(em[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        for npy in range(15, 90, 25):
            for npx in range(15, 110, 25):
                if ib(npx, npy) and bool(em[npy, npx]):
                    x0, x1 = max(0, npx-14), min(WORLD_W, npx+15)
                    y0, y1 = max(0, npy-14), min(WORLD_H, npy+15)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        for apx, apy in [(55,7),(65,7),(55,92),(65,92),(7,45),(112,45)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        for spx, spy in [(7,50),(112,50),(60,4),(60,95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: road near plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6,0),(-6,0),(0,6),(0,-6),(4,0),(-4,0),(0,4),(0,-4)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant cluster + wire/road grid skeleton"""
    actions = []
    # Coal plants at key positions
    for px, py in [(20, 50), (59, 50), (99, 50), (59, 20), (59, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for x in range(1, 119):
        for wy in [20, 40, 50, 60, 80]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for y in range(1, 99):
        for wx in [20, 40, 59, 79, 99]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines (skip row 50 - has plant)
    for x in range(1, 119):
        for wy in [20, 40, 60, 80]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [20, 40, 59, 79, 99]

    # Neighborhood grid for zone targeting
    nh_positions = []
    for row in range(7):
        for col in range(8):
            cx = min(7 + col * 15, 116)
            cy = min(7 + row * 13, 94)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 50:
            return [nh_positions[i] for i in [18, 19, 26, 27, 17, 20]]
        elif pop < 200:
            return nh_positions[12:40]
        elif pop < 600:
            return nh_positions[6:50]
        elif pop < 1500:
            return nh_positions[3:53]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- REACTIVE POWER PLANT PLACEMENT ---
    # Only check a few hoods per step to stay reactive
    check_hoods = active_hoods[:6]
    for (hx, hy) in check_hoods:
        x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
        y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(2, 20):
                found = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = hx + dx, hy + dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)
                if found:
                    break

    phase = step % 14

    if phase == 0:
        # Extend horizontal wire corridors reactively
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left = bool(row_wire[wx-1]) if wx > 0 else False
                    right = bool(row_wire[wx+1]) if wx < WORLD_W-1 else False
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors reactively
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up = bool(col_wire[wy-1]) if wy > 0 else False
                    down = bool(col_wire[wy+1]) if wy < WORLD_H-1 else False
                    if (up or down) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking horizontal wire spines
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Secondary wire rows (reactive: only if not already wired)
        for wr in [30, 70, 10, 90]:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                for wc in wire_cols:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_wire[wx]):
                        left = bool(row_wire[wx-1]) if wx > 0 else False
                        right = bool(row_wire[wx+1]) if wx < WORLD_W-1 else False
                        if (left or right) and bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 5:
        # Secondary vertical wire cols
        for wc in [10, 30, 70, 90, 110]:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                for wr in wire_rows:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_wire[wy]):
                        up = bool(col_wire[wy-1]) if wy > 0 else False
                        down = bool(col_wire[wy+1]) if wy < WORLD_H-1 else False
                        if (up or down) and bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 6:
        # Cross-street horizontal roads
        all_wire_rows = sorted([20, 40, 50, 60, 80, 30, 70, 10, 90])
        for wr_idx in range(len(all_wire_rows) - 1):
            r1, r2 = all_wire_rows[wr_idx], all_wire_rows[wr_idx + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(2, WORLD_W - 2):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                    adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                          (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 7:
        # Cross-street vertical roads
        all_wire_cols = sorted([20, 40, 59, 79, 99, 10, 30, 70, 90, 110])
        for wc_idx in range(len(all_wire_cols) - 1):
            c1, c2 = all_wire_cols[wc_idx], all_wire_cols[wc_idx + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(2, WORLD_H - 2):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                    adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                          (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 8:
        # Extend road from existing road near power (reactive)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 150)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 9:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 10:
        # Wire toward unpowered hoods
        unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
        if unpowered:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                tx, ty = unpowered[0]
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best = np.argmin(dists)
                bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 11:
        # Civic services based on current observed population
        if pop > 20:
            fire_spots = [(5,5),(35,5),(65,5),(95,5),(115,5),
                          (5,25),(35,25),(65,25),(95,25),(115,25),
                          (5,50),(65,50),(115,50),
                          (5,70),(35,70),(65,70),(95,70),(115,70),
                          (5,93),(35,93),(65,93),(95,93),(115,93)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 100:
            police_spots = [(15,15),(45,15),(75,15),(105,15),
                            (15,45),(45,45),(75,45),(105,45),
                            (15,75),(45,75),(75,75),(105,75)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

    elif phase == 12:
        if pop > 300:
            stadium_spots = [(35,35),(85,35),(35,65),(85,65),
                             (10,50),(110,50),(60,20),(60,80)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 500:
            nuke_spots = [(5,5),(113,5),(5,93),(113,93),
                          (59,5),(59,93),(5,50),(113,50),
                          (40,50),(79,50),(59,30),(59,70)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    elif phase == 13:
        if pop > 800:
            seaports = [(5,93),(113,93),(5,5),(113,5),(59,5),(59,93),(30,93),(90,93)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1500:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(5,57),(113,43),(113,57)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (main closed-loop action) ----
    avoid_rows = [20, 40, 50, 60, 80, 30, 70, 10, 90]
    avoid_cols = [20, 40, 59, 79, 99, 10, 30, 70, 90, 110]

    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    for wr in avoid_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in avoid_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # Parks for land value
    if pop > 50 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: extend road from zones
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: three coal plants arranged in a triangle, with wire + road grids."""
    actions = []
    # Three plants: top-center, bottom-left, bottom-right
    plants = [(60, 20), (25, 75), (95, 75)]
    for (cx, cy) in plants:
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire cross from plant
        for dx in range(-8, 9):
            if dx != 0:
                nx = cx + dx
                if 0 <= nx < WORLD_W:
                    actions.append((Tool.WIRE, nx, cy))
        for dy in range(-8, 9):
            if dy != 0:
                ny = cy + dy
                if 0 <= ny < WORLD_H:
                    actions.append((Tool.WIRE, cx, ny))
        # Roads flanking the wire cross
        for offset in [-3, 3]:
            for dy in range(-7, 8):
                ny = cy + dy
                nx = cx + offset
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    actions.append((Tool.ROAD, nx, ny))
            for dx in range(-7, 8):
                nx = cx + dx
                ny = cy + offset
                if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                    actions.append((Tool.ROAD, nx, ny))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Neighborhood grid: 6 columns x 5 rows = 30 hoods
    all_hoods = []
    for hy in range(12, 95, 18):
        for hx in range(12, 115, 18):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:   return 4
        if pop < 200:  return 8
        if pop < 500:  return 14
        if pop < 1000: return 20
        if pop < 2000: return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # Build neighbor masks for power and road access
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # PHASE 1: Ensure power plant near each active hood
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
            y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Wire from nearest plant to hood center
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 14

    x0p, x1p = max(0, hx - 18), min(WORLD_W, hx + 19)
    y0p, y1p = max(0, hy - 18), min(WORLD_H, hy + 19)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0; best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d; best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical wire spine at hx
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        min_wr, max_wr = min(col_wire), max(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    # Extend horizontal wire spine at hy
    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        min_wc, max_wc = min(row_wire), max(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # PHASE 3: Roads flanking wire spines (offset 2 and 4 for denser coverage)
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    # Roads at -2 and +2 from wire (tighter spacing = more zone coverage)
    cyc = step % 2
    for rx in [hx3 - 2, hx3 + 2]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::2]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 2, hy3 + 2]:
        if not ib(hx3, ry): continue
        cyc2 = (step + 1) % 2
        for wc in row_wire3[cyc2::2]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # Also add roads at -4 and +4 for extra coverage
    cyc3 = step % 3
    for rx in [hx3 - 4, hx3 + 4]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc3::3]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 4, hy3 + 4]:
        if not ib(hx3, ry): continue
        for wc in row_wire3[cyc3::3]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # PHASE 4: Connect hoods with roads
    if step % 4 < 3:
        for i, (hx1, hy1) in enumerate(active_hoods):
            for (hx2, hy2) in active_hoods[i+1:]:
                dist = abs(hx1-hx2) + abs(hy1-hy2)
                if dist > 30: continue
                if abs(hy1 - hy2) <= 3:
                    mid_y = (hy1 + hy2) // 2
                    step_conn = step % max(abs(hx2-hx1), 1)
                    cx2 = min(hx1, hx2) + step_conn
                    if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                        if not bool(rm[mid_y, cx2]):
                            return (Tool.ROAD, cx2, mid_y)
                if abs(hx1 - hx2) <= 3:
                    mid_x = (hx1 + hx2) // 2
                    step_conn = step % max(abs(hy2-hy1), 1)
                    cy2 = min(hy1, hy2) + step_conn
                    if ib(mid_x, cy2) and bool(em[cy2, mid_x]) and not bool(pm[cy2, mid_x]):
                        if not bool(rm[cy2, mid_x]):
                            return (Tool.ROAD, mid_x, cy2)

    # PHASE 5: Zone placement — targeting 45% res, 30% com, 25% ind
    # This differs from parent's 40/30/30 to boost residential population
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4) + np.abs(cys - hy4)
            best_dist = np.minimum(best_dist, d)

        # Clustering bonus: prefer near existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # Weight clustering more heavily than parent (0.4 vs 0.6 instead of 0.5/0.5)
                score = best_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        # Vary selection offset by step+pop for diversity
        off = (step * 5 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 6: Extend roads from existing network
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # PHASE 7: Civic services — fire stations denser grid
    if pop > 15:
        fire_grid = [(fx, fy) for fy in range(10, 95, 12)
                     for fx in range(10, 115, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_grid = [(px2, py2) for py2 in range(14, 92, 14)
                       for px2 in range(14, 112, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 19) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Stadiums — more aggressive placement
    if pop > 200:
        stadium_locs = [
            (30, 15), (60, 12), (90, 15),
            (15, 45), (60, 50), (105, 45),
            (30, 85), (60, 88), (90, 85),
            (15, 20), (105, 20), (15, 80), (105, 80),
            (40, 30), (80, 30), (40, 70), (80, 70),
            (25, 55), (95, 55), (60, 35), (60, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power for mature cities
    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 15), (85, 15), (35, 85), (85, 85),
            (20, 45), (100, 45), (60, 25), (60, 75),
            (15, 30), (105, 30), (15, 70), (105, 70),
            (45, 5), (75, 5), (45, 95), (75, 95),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 93), (5, 45), (113, 45)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # PHASE 8: Wire connections between nearby hoods
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hx1-hx2) + abs(hy1-hy2) > 40: continue
            if abs(hy1 - hy2) <= 3:
                mid_y = (hy1 + hy2) // 2
                for cx3 in range(min(hx1,hx2)+1, max(hx1,hx2)):
                    if ib(cx3, mid_y) and bool(em[mid_y, cx3]) and not bool(pm[mid_y, cx3]):
                        if not bool(wm[mid_y, cx3]):
                            return (Tool.WIRE, cx3, mid_y)
            if abs(hx1 - hx2) <= 3:
                mid_x = (hx1 + hx2) // 2
                for cy3 in range(min(hy1,hy2)+1, max(hy1,hy2)):
                    if ib(mid_x, cy3) and bool(em[cy3, mid_x]) and not bool(pm[cy3, mid_x]):
                        if not bool(wm[cy3, mid_x]):
                            return (Tool.WIRE, mid_x, cy3)

    # Fallback: extend wire from plants
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: extend wire from existing wire
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new plant for uncovered hood
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    # Late-game nuclear upgrade
    if pop > 1000 and step % 3 == 0 and funds > 5000:
        nuc_spots = [(30, 30), (90, 30), (30, 70), (90, 70),
                     (60, 50), (15, 15), (105, 15), (15, 85), (105, 85)]
        for nx6, ny6 in nuc_spots:
            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                return (Tool.NUCLEARPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire + road grid."""
    actions = []
    # Two power plants side by side
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire connecting them horizontally
    for x in range(33, 88):
        if x not in (40, 80):
            actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(35, 66):
        if y != 50:
            actions.append((Tool.WIRE, 40, y))
            actions.append((Tool.WIRE, 80, y))
    # Initial roads (horizontal, 3 rows above/below wire spine)
    for x in range(30, 91):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    zone_tiles = resm | comm | indm

    # Dense neighborhood grid: 8 cols x 7 rows = 56 neighborhoods
    # Tighter spacing to pack zones closer together
    all_hoods = []
    for hy in range(10, 95, 13):
        for hx in range(10, 115, 15):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 14
        if pop < 800:   return 20
        if pop < 1500:  return 28
        if pop < 3000:  return 38
        if pop < 6000:  return 48
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: POWER PLANTS ---
    # Denser plant grid than parent
    if funds > 1000:
        plant_positions = []
        for py in range(15, 90, 25):
            for px in range(15, 110, 25):
                plant_positions.append((px, py))

        for (ppx, ppy) in plant_positions:
            x0, x1 = max(0, ppx - 7), min(WORLD_W, ppx + 8)
            y0, y1 = max(0, ppy - 7), min(WORLD_H, ppy + 8)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(7):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: WIRE GRID (diagonal cross pattern per hood) ---
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 12)
        spine_bot   = min(WORLD_H - 3, hy + 12)
        spine_left  = max(2, hx - 12)
        spine_right = min(WORLD_W - 3, hx + 12)

        # Vertical spine
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        if col_wire:
            min_wr, max_wr = min(col_wire), max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine
        row_wire = [c for c in range(spine_left, spine_right + 1)
                    if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc, max_wc = min(row_wire), max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT HOODS WITH WIRES ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 30:
                continue
            if abs(hy1 - hy2) <= 3:
                mid_y = (hy1 + hy2) // 2
                for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
            if abs(hx1 - hx2) <= 3:
                mid_x = (hx1 + hx2) // 2
                for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                        return (Tool.WIRE, mid_x, cy)

    # --- PHASE 4: ROAD GRID (2 offsets for denser road coverage) ---
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        # Two road columns per wire spine (±2 and ±4)
        for rx in [hx - 2, hx + 2, hx - 4, hx + 4]:
            if not ib(rx, hy) or not col_wire:
                continue
            cyc = step % 5
            for wr in col_wire[cyc::5]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2, hy - 4, hy + 4]:
            if not ib(hx, ry) or not row_wire:
                continue
            cyc = (step + 2) % 5
            for wc in row_wire[cyc::5]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    # Zone mix: 35% RES, 35% COM, 30% IND (more commercial than parent)
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.33:
            return Tool.COMMERCIAL
        if r_r < 0.38:
            return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (within 3 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Stronger zone clustering bonus
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # Weight clustering more heavily to create dense districts
                score = best_dist * 0.3 + zone_prox * 0.7
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        # Use a smaller offset to prefer best candidates
        off = (step * 3 + pop) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES (placed earlier than parent) ---
    # Fire stations
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(15, 95, 18)
                     for fx in range(15, 110, 20)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    # Police stations
    if pop > 60:
        police_grid = [(px2, py2) for py2 in range(18, 90, 20)
                       for px2 in range(18, 108, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # Stadiums (earlier than parent)
    if pop > 300:
        stadium_locs = [
            (25, 20), (60, 15), (95, 20),
            (15, 50), (60, 50), (105, 50),
            (25, 80), (60, 85), (95, 80),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Parks
    if pop > 150 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Nuclear power
    if pop > 800 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-6), min(WORLD_W, npx+7)
            y0b, y1b = max(0, npy-6), min(WORLD_H, npy+7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    # Seaports
    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Airports
    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from plants ---
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + connecting wire + initial roads"""
    actions = []
    # Primary coal plant at (40, 50)
    actions.append((Tool.COALPOWER, 40, 50))
    # Wire spine going right from plant
    for x in range(43, 80):
        actions.append((Tool.WIRE, x, 50))
    # Secondary coal plant at (78, 50)
    actions.append((Tool.COALPOWER, 78, 50))
    # Wire from secondary going down
    for y in range(47, 70):
        actions.append((Tool.WIRE, 78, y))
    # Wire from primary going up
    for y in range(35, 50):
        actions.append((Tool.WIRE, 40, y))
    # Initial roads flanking primary plant area
    for y in range(35, 65):
        actions.append((Tool.ROAD, 37, y))
        actions.append((Tool.ROAD, 43, y))
    return actions


def act(obs, state):
    """
    Dual-cluster city with horizontal wire backbone.
    Cluster A: around (40, 50), Cluster B: around (78, 50)
    Heavy industrial base + commercial + residential mix
    Reacts to city growth to expand, add services, second ring of zones.
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        """Balanced: 40% industrial, 30% commercial, 30% residential"""
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.35:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Check if plants exist
    plant_ys, plant_xs = np.where(pm)
    n_plants = len(plant_xs)

    # Ensure primary plant exists
    if n_plants == 0:
        return (Tool.COALPOWER, 40, 50)

    # Ensure secondary plant exists
    if n_plants < 6:  # plant is 3x3 = 9 tiles but we check roughly
        # Check if secondary plant area is free
        p2x, p2y = 78, 50
        area_has_plant = False
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                nx, ny = p2x + dx, p2y + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    area_has_plant = True
                    break
        if not area_has_plant and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)

    # Third plant when population high enough
    if pop > 800 and n_plants < 15:
        p3x, p3y = 60, 70
        area_has_plant = False
        for dy in range(-5, 6):
            for dx in range(-5, 6):
                nx, ny = p3x + dx, p3y + dy
                if in_bounds(nx, ny) and bool(pm[ny, nx]):
                    area_has_plant = True
                    break
        if not area_has_plant and bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)

    # Define wire backbone: horizontal at y=50 from x=43 to x=75
    # and vertical spines at x=40 (y=35..65) and x=78 (y=35..70)

    # Build horizontal wire backbone
    backbone_y = 50
    for x in range(43, 77):
        if in_bounds(x, backbone_y) and not bool(wm[backbone_y, x]) and not bool(pm[backbone_y, x]):
            if bool(em[backbone_y, x]):
                return (Tool.WIRE, x, backbone_y)

    # Build vertical wire spine A at x=40
    spine_ax = 40
    spine_a_top = max(3, 35 - min(15, pop // 50))
    spine_a_bot = min(WORLD_H - 4, 65 + min(15, pop // 50))
    for y in range(spine_a_top, spine_a_bot + 1):
        if in_bounds(spine_ax, y) and not bool(wm[y, spine_ax]) and not bool(pm[y, spine_ax]):
            if bool(em[y, spine_ax]):
                return (Tool.WIRE, spine_ax, y)

    # Build vertical wire spine B at x=78
    spine_bx = 78
    spine_b_top = max(3, 35 - min(15, pop // 50))
    spine_b_bot = min(WORLD_H - 4, 70 + min(15, pop // 50))
    for y in range(spine_b_top, spine_b_bot + 1):
        if in_bounds(spine_bx, y) and not bool(wm[y, spine_bx]) and not bool(pm[y, spine_bx]):
            if bool(em[y, spine_bx]):
                return (Tool.WIRE, spine_bx, y)

    # Build road columns flanking cluster A (x=37 and x=43)
    road_cols_a = [37, 43]
    road_cols_b = [75, 81]

    wire_ys_a = [y for y in range(WORLD_H) if in_bounds(spine_ax, y) and bool(wm[y, spine_ax])]
    wire_ys_b = [y for y in range(WORLD_H) if in_bounds(spine_bx, y) and bool(wm[y, spine_bx])]

    # Build roads alongside spine A
    if wire_ys_a:
        for wy in wire_ys_a[::2] if step % 2 == 0 else wire_ys_a[1::2]:
            for rc in road_cols_a:
                if in_bounds(rc, wy) and bool(em[wy, rc]) and not bool(pm[wy, rc]):
                    return (Tool.ROAD, rc, wy)

    # Build roads alongside spine B
    if wire_ys_b:
        for wy in wire_ys_b[::2] if step % 2 == 0 else wire_ys_b[1::2]:
            for rc in road_cols_b:
                if in_bounds(rc, wy) and bool(em[wy, rc]) and not bool(pm[wy, rc]):
                    return (Tool.ROAD, rc, wy)

    # Add horizontal connector roads for better connectivity
    if pop > 100 or total_zones > 5:
        # Horizontal road at y=45 and y=55 connecting both clusters
        for connector_y in [45, 55]:
            for x in range(36, 84):
                if in_bounds(x, connector_y) and bool(em[connector_y, x]) and not bool(pm[connector_y, x]):
                    # Only place if near wire
                    near_wire = False
                    for dy in range(-3, 4):
                        for dx in range(-3, 4):
                            nx, ny = x + dx, connector_y + dy
                            if in_bounds(nx, ny) and (bool(wm[ny, nx]) or bool(pm[ny, nx])):
                                near_wire = True
                                break
                    if near_wire:
                        return (Tool.ROAD, x, connector_y)

    # Build proximity masks for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone positions: near road AND near wire
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize based on distance to either cluster center
        center1 = np.array([40, 50])
        center2 = np.array([78, 50])
        coords = np.stack([cxs, cys], axis=1)
        d1 = np.abs(coords[:, 0] - center1[0]) + np.abs(coords[:, 1] - center1[1])
        d2 = np.abs(coords[:, 0] - center2[0]) + np.abs(coords[:, 1] - center2[1])
        dists = np.minimum(d1, d2)
        order = np.argsort(dists)
        step_off = int(step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # Extend roads near wire to fill gaps
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 20)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Services based on population
    if pop > 200:
        for spos in [(35, 40), (83, 40), (35, 60), (83, 60)]:
            sx, sy = spos
            if in_bounds(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        for ppos in [(35, 45), (83, 45), (35, 55), (83, 55)]:
            px2, py2 = ppos
            if in_bounds(px2, py2) and bool(em[py2, px2]):
                return (Tool.POLICESTATION, px2, py2)

    if pop > 1000:
        # Stadium boosts population significantly
        for stpos in [(59, 40), (59, 62)]:
            stx, sty = stpos
            all_clear = True
            for dy in range(-1, 2):
                for dx in range(-1, 2):
                    nx, ny = stx + dx, sty + dy
                    if not in_bounds(nx, ny) or not bool(em[ny, nx]):
                        all_clear = False
            if all_clear:
                return (Tool.STADIUM, stx, sty)

    # Expand wire laterally when stuck
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from center
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along wire spines
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-7, 8):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: ~40% RES, ~30% COM, ~30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === NEIGHBORHOOD GRID ===
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 20, 33, 46, 59, 72, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 400:   return 10
        if pop < 800:   return 16
        if pop < 1500:  return 24
        if pop < 3000:  return 36
        if pop < 6000:  return 48
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # === BUILD NEIGHBOR MASKS ===
    power_src = wm | pm

    # Fast dilation for power (radius 5 Manhattan)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            if abs(dx2) + abs(dy2) > 5:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Fast dilation for road (radius 3 Manhattan)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            if abs(dx2) + abs(dy2) > 3:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: POWER PLANTS for active hoods ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE SPINES ===
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant for this hood
    x0p, x1p = max(0, hx - 16), min(WORLD_W, hx + 17)
    y0p, y1p = max(0, hy - 16), min(WORLD_H, hy + 17)
    plant_ys_l, plant_xs_l = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs_l) > 0:
        px_l = int(plant_xs_l[0]) + x0p
        py_l = int(plant_ys_l[0]) + y0p
        # Wire vertical from plant to hood center
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        # Wire horizontal from plant/wire to hood center
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical/horizontal wire spines at hood
    for dy3 in range(-spine_range, spine_range + 1):
        wy = hy + dy3
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    for dx3 in range(-spine_range, spine_range + 1):
        wx = hx + dx3
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # === PHASE 3: CONNECT WIRE BETWEEN HOODS ===
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    for i_h in range(min(len(active_hoods), 8)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist == 0 or dist > 30:
                continue
            # Horizontal bridge
            if abs(hy1 - hy2) <= 3:
                mid_y2 = (hy1 + hy2) // 2
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, mid_y2): continue
                    if not bool(em[mid_y2, cx2]) or bool(pm[mid_y2, cx2]) or bool(wm[mid_y2, cx2]):
                        continue
                    has_l = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                for c in range(max(0, cx2 - 4), cx2))
                    has_r = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                for c in range(cx2 + 1, min(WORLD_W, cx2 + 5)))
                    if has_l or has_r:
                        return (Tool.WIRE, cx2, mid_y2)
            # Vertical bridge
            if abs(hx1 - hx2) <= 3:
                mid_x2 = (hx1 + hx2) // 2
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(mid_x2, cy2): continue
                    if not bool(em[cy2, mid_x2]) or bool(pm[cy2, mid_x2]) or bool(wm[cy2, mid_x2]):
                        continue
                    has_t = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2])
                                for r in range(max(0, cy2 - 4), cy2))
                    has_b = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2])
                                for r in range(cy2 + 1, min(WORLD_H, cy2 + 5)))
                    if has_t or has_b:
                        return (Tool.WIRE, mid_x2, cy2)

    # === PHASE 4: ROADS FLANKING WIRE SPINES ===
    road_idx = step % max(len(active_hoods), 1)
    hx_r, hy_r = active_hoods[road_idx]

    for rx in [hx_r - 1, hx_r + 1, hx_r - 2, hx_r + 2]:
        if not ib(rx, hy_r): continue
        for dy4 in range(-spine_range, spine_range + 1):
            ry = hy_r + dy4
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(wm[ry, hx_r]) or bool(pm[ry, hx_r]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy_r - 1, hy_r + 1, hy_r - 2, hy_r + 2]:
        if not ib(hx_r, ry2): continue
        for dx4 in range(-spine_range, spine_range + 1):
            rcx = hx_r + dx4
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
            if bool(wm[hy_r, rcx]) or bool(pm[hy_r, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # === PHASE 5: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Add zone clustering bonus when enough zones exist
        if total_zones > 10:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: EXTEND ROADS INTO POWERED EMPTY AREAS ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx5, dy5 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx5, ry2 + dy5
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # === CIVIC SERVICES (population-gated) ===
    if pop > 80:
        for fx in range(12, WORLD_W, 16):
            for fy in range(12, WORLD_H, 16):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        for px2 in range(14, WORLD_W, 18):
            for py2 in range(14, WORLD_H, 18):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 150 and step % 4 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 17) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 3000:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (5, 75), (115, 25), (115, 75),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 500 and funds > 3500:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 900:
        airport_locs = [
            (10, 10), (100, 10), (10, 85), (100, 85),
            (55, 5), (55, 93), (5, 45), (113, 45),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: EXTEND WIRE FROM EXISTING WIRE/PLANTS ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx6, dy6 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx6, wy2 + dy6
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: NEW PLANT FOR UNCOVERED HOOD ===
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 14):
                for dy7 in range(-r2, r2 + 1):
                    for dx7 in range(-r2, r2 + 1):
                        if abs(dx7) == r2 or abs(dy7) == r2:
                            nx4, ny4 = hx3 + dx7, hy3 + dy7
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire spine and initial roads"""
    actions = []
    # Two power plants near center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at plant columns
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Horizontal wire at y=25 and y=75
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Roads flanking the center spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 35% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- REACTIVE CLOSED-LOOP INFRASTRUCTURE ----
    # Check current state and extend infrastructure from what exists

    # 1. If there are zones without power, extend wire toward them
    unpowered_zones = zone_tiles & ~near_power
    uz_ys, uz_xs = np.where(unpowered_zones)
    if len(uz_xs) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # 2. If there are zones without road access, extend roads toward them
    unroaded_zones = zone_tiles & ~near_road
    uz_ys2, uz_xs2 = np.where(unroaded_zones)
    if len(uz_xs2) > 0:
        road_ys_a, road_xs_a = np.where(rm)
        if len(road_xs_a) > 0:
            idx = (step * 19) % len(uz_xs2)
            tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
            dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # 3. Check if we need more power plants (< 1 plant per 30x30 region)
    # Reactively place plants where there's no nearby plant
    if step % 7 == 3:
        for py in range(15, WORLD_H - 5, 25):
            for px in range(15, WORLD_W - 5, 25):
                x0, x1 = max(0, px - 14), min(WORLD_W, px + 15)
                y0, y1 = max(0, py - 14), min(WORLD_H, py + 15)
                has_plant = bool(np.any(pm[y0:y1, x0:x1]))
                if not has_plant:
                    # Find empty spot near target, prefer near existing wire
                    for r in range(0, 8):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # 4. Extend road network reactively - find frontier of road and extend into powered area
    if step % 5 == 1:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 5. Extend wire network reactively - connect disconnected regions
    if step % 5 == 2:
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            sk2 = (step * 13) % len(wire_xs3)
            for off in range(min(len(wire_xs3), 100)):
                k = (sk2 + off * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        # Only extend into areas that need power
                        if not bool(near_power[ny3, nx3]):
                            return (Tool.WIRE, nx3, ny3)

    # ---- CIVIC SERVICES (reactive to pop) ----
    if pop > 20:
        fire_spots = [
            (5, 5), (30, 5), (60, 5), (90, 5), (115, 5),
            (5, 25), (30, 25), (60, 25), (90, 25), (115, 25),
            (5, 45), (115, 45), (5, 55), (115, 55),
            (5, 75), (30, 75), (60, 75), (90, 75), (115, 75),
            (5, 95), (30, 95), (60, 95), (90, 95), (115, 95),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 35), (45, 35), (75, 35), (105, 35),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 85), (45, 85), (75, 85), (105, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(35, 20), (85, 20), (35, 80), (85, 80), (60, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 20), (115, 20), (5, 80), (115, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (closed-loop: place where power+road already exist) ----
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Build active centers that spread across the map as pop grows
        if pop < 300:
            # Focus near center where infrastructure is
            active_centers = [(60, 50), (45, 50), (75, 50), (60, 38), (60, 62),
                               (30, 50), (90, 50)]
        elif pop < 1000:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 17
                    cy = 12 + row * 19
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 6 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use step and pop for deterministic but varied placement
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Parks to boost land value when pop is decent
    if pop > 50 and step % 6 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: build roads adjacent to existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Different strategy: linear spine city with denser zone coverage
# Use a horizontal road/wire backbone with zones on both sides
# Focus on getting early zones powered quickly, then expand outward

def init(obs, state):
    """Bootstrap: two coal plants + horizontal wire backbone + vertical roads."""
    actions = []
    # Two coal plants on the central horizontal spine
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine connecting them
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical roads through center
    for y in range(44, 57):
        actions.append((Tool.ROAD, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- SPINE-BASED LAYOUT ----
    # Main horizontal wire spine at y=50
    # Vertical branch roads at regular intervals
    # Zones placed in strips above and below the spine

    # Branch road x-positions (vertical roads crossing the spine)
    branch_xs = list(range(10, WORLD_W, 8))  # every 8 tiles

    # ---- PHASE 1: ENSURE SPINE WIRE IS CONTINUOUS ----
    # Check and fill gaps in the horizontal wire spine
    spine_y = 50
    for x in range(5, 115):
        if not ib(x, spine_y): continue
        if bool(pm[spine_y, x]): continue  # skip power plants
        if bool(wm[spine_y, x]): continue  # already wired
        # Check if there's a wire neighbor
        has_neighbor = False
        for dx in [-1, 1]:
            nx = x + dx
            if ib(nx, spine_y) and (bool(wm[spine_y, nx]) or bool(pm[spine_y, nx])):
                has_neighbor = True
                break
        if has_neighbor and bool(em[spine_y, x]):
            return (Tool.WIRE, x, spine_y)

    # ---- PHASE 2: EXTEND SPINE VERTICALLY (wire branches up and down) ----
    # Create vertical wire branches at branch positions to power zones
    branch_depth = 12  # how far up/down wire extends
    for bx in branch_xs:
        if not ib(bx, spine_y): continue
        # Check spine has power at this x
        if not (bool(wm[spine_y, bx]) or bool(pm[spine_y, bx])):
            continue
        # Extend wire up
        for dy in range(1, branch_depth + 1):
            wy = spine_y - dy
            if not ib(bx, wy): continue
            if bool(pm[wy, bx]): break
            if bool(wm[wy, bx]): continue
            if not bool(em[wy, bx]): break
            # Check adjacent wire exists
            adj_wire = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(bx, ay) and (bool(wm[ay, bx]) or bool(pm[ay, bx])):
                    adj_wire = True
            if adj_wire:
                if step % 2 == 0:
                    return (Tool.WIRE, bx, wy)
        # Extend wire down
        for dy in range(1, branch_depth + 1):
            wy = spine_y + dy
            if not ib(bx, wy): continue
            if bool(pm[wy, bx]): break
            if bool(wm[wy, bx]): continue
            if not bool(em[wy, bx]): break
            adj_wire = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(bx, ay) and (bool(wm[ay, bx]) or bool(pm[ay, bx])):
                    adj_wire = True
            if adj_wire:
                if step % 2 == 1:
                    return (Tool.WIRE, bx, wy)

    # ---- PHASE 3: ROAD GRID ----
    # Horizontal roads above and below spine (for zone access)
    road_offsets = [-4, -8, -12, 4, 8, 12]  # y offsets from spine
    for y_off in road_offsets:
        ry = spine_y + y_off
        if not ib(0, ry): continue
        for x in range(5, 115):
            if not ib(x, ry): continue
            if bool(rm[ry, x]) or bool(pm[ry, x]): continue
            if not bool(em[ry, x]): continue
            # Check for road neighbor
            has_rneighbor = False
            for dx in [-1, 1]:
                nx = x + dx
                if ib(nx, ry) and bool(rm[ry, nx]):
                    has_rneighbor = True
                    break
            # Also connect vertical roads
            for dy in [-1, 1]:
                ny = ry + dy
                if ib(x, ny) and bool(rm[ny, x]):
                    has_rneighbor = True
                    break
            if has_rneighbor:
                if (step // 3) % 2 == 0:
                    return (Tool.ROAD, x, ry)

    # Vertical roads at branch positions
    for bx in branch_xs:
        for y in range(spine_y - branch_depth, spine_y + branch_depth + 1):
            if not ib(bx, y): continue
            if bool(rm[y, bx]) or bool(pm[y, bx]) or bool(wm[y, bx]): continue
            if not bool(em[y, bx]): continue
            has_rneighbor = False
            for dy in [-1, 1]:
                ny = y + dy
                if ib(bx, ny) and bool(rm[ny, bx]):
                    has_rneighbor = True
                    break
            for dx in [-1, 1]:
                nx = bx + dx
                if ib(nx, y) and bool(rm[y, nx]):
                    has_rneighbor = True
                    break
            if has_rneighbor and step % 4 == 0:
                return (Tool.ROAD, bx, y)

    # ---- COMPUTE COVERAGE MAPS ----
    # Road coverage within 3 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage within 5 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 4: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 35% RES, 35% COM, 30% IND - more commercial focus
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Zone candidates: empty, road nearby, power nearby, safe from edge
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize by distance to spine
        dist_to_spine = np.abs(cys - spine_y)
        # Also prefer near branch roads
        dist_to_branch = np.full(len(cxs), 999.0)
        for bx in branch_xs:
            d = np.abs(cxs - bx)
            dist_to_branch = np.minimum(dist_to_branch, d)
        score = dist_to_spine * 0.5 + dist_to_branch * 0.5
        order = np.argsort(score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 5: ADD MORE POWER PLANTS as city grows ----
    powered_frac = obs.powered_zones / max(total_zones, 1)
    if pop > 200 and powered_frac < 0.7:
        # Place new coal plants every 25 tiles along spine
        for px in range(10, WORLD_W - 10, 25):
            # Check if there's a plant nearby
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, spine_y - 12), min(WORLD_H, spine_y + 13)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find empty spot near spine
                for dy in range(0, 8):
                    for dx in range(0, 8):
                        for sy in [spine_y - dy, spine_y + dy]:
                            for sx in [px - dx, px + dx]:
                                if ib(sx, sy) and bool(em[sy, sx]):
                                    return (Tool.COALPOWER, sx, sy)

    # ---- EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (scaled with population) ----
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [(px2, py2) for px2 in range(16, WORLD_W, 20) for py2 in range(16, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(25, 25), (60, 25), (95, 25), (25, 75), (60, 75), (95, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 88), (112, 88), (8, 12), (112, 12), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 93), (75, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for density ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(20, 20), (60, 20), (100, 20), (20, 80), (60, 80), (100, 80), (20, 50), (100, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 300 and step % 6 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant if no power near empty zone areas ----
    if not bool(np.any(pm)):
        return (Tool.COALPOWER, 60, 50)

    uncovered = cand_mask & ~nbr_power
    ucy, ucx = np.where(uncovered & em)
    if len(ucx) > 0:
        idx = (step * 3) % len(ucx)
        return (Tool.COALPOWER, int(ucx[idx]), int(ucy[idx]))

    return None

