    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    zone_tiles = resm | comm | indm

    # --- STEP 1: Ensure we have enough power plants ---
    # Target one plant per ~200 population, spread across the map
    plant_ys, plant_xs = np.where(pm)
    plant_count = len(plant_xs)

    target_plants = 1 + pop // 150
    if funds > 3000 and plant_count < target_plants and plant_count < 12:
        # Place plants on a grid, pick first spot without nearby plant
        plant_grid = []
        for py in range(15, 90, 25):
            for px in range(15, 110, 25):
                plant_grid.append((px, py))

        for (ppx, ppy) in plant_grid:
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find empty spot near target
                for r in range(6):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- STEP 2: Extend wires from existing power infrastructure ---
    # Find all wire+plant tiles, expand outward toward uncovered zones
    # Build wire neighbor expansion - prioritize reaching zones without power

    # Compute where power currently reaches (adjacent to wire or plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-1, 2):
        for dx in range(-1, 2):
            if dx == 0 and dy == 0:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Extended power reach (3 tiles) for zone placement scoring
    nbr_power3 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power3[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power3[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Extended road reach (2 tiles)
    nbr_road2 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road2[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Determine how many neighborhoods to activate based on population
    all_hoods = []
    for hy in range(10, 95, 14):
        for hx in range(10, 115, 14):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 14
        if pop < 1000:  return 20
        if pop < 2000:  return 28
        if pop < 4000:  return 40
        return len(all_hoods)

    n_active = num_active_hoods()
    # Pick evenly spaced hoods
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- STEP 3: Wire extension toward active neighborhoods ---
    # For each hood, check if vertical/horizontal wire spines reach it
    # If not, extend wires toward the hood from nearest wire

    # Find frontier wire tiles (wire adjacent to empty)
    wire_ys, wire_xs = np.where(wm)

    for (hx, hy) in active_hoods:
        spine_r = 12  # spine radius
        spine_top   = max(2, hy - spine_r)
        spine_bot   = min(WORLD_H - 3, hy + spine_r)
        spine_left  = max(2, hx - spine_r)
        spine_right = min(WORLD_W - 3, hx + spine_r)

        # Check if vertical spine exists
        col_has_wire = bool(np.any(wm[spine_top:spine_bot+1, hx]))
        col_has_plant = bool(np.any(pm[spine_top:spine_bot+1, hx]))

        if not col_has_wire and not col_has_plant:
            # Try to extend wire toward hx from nearest wire column
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - hx) + np.abs(wire_ys - hy)
                nearest_idx = np.argmin(dists)
                wx, wy = int(wire_xs[nearest_idx]), int(wire_ys[nearest_idx])
                # Step from (wx,wy) toward (hx,hy)
                if abs(wx - hx) > abs(wy - hy):
                    # Move horizontally
                    step_x = 1 if hx > wx else -1
                    nx, ny = wx + step_x, wy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
                else:
                    # Move vertically
                    step_y = 1 if hy > wy else -1
                    nx, ny = wx, wy + step_y
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
        else:
            # Spine column exists, extend it vertically
            col_wire_rows = [r for r in range(spine_top, spine_bot + 1)
                             if ib(hx, r) and bool(wm[r, hx])]
            if col_wire_rows:
                min_wr, max_wr = min(col_wire_rows), max(col_wire_rows)
                # Extend down
                if max_wr < spine_bot:
                    nr = max_wr + 1
                    if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                        return (Tool.WIRE, hx, nr)
                # Extend up
                if min_wr > spine_top:
                    nr = min_wr - 1
                    if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                        return (Tool.WIRE, hx, nr)

        # Horizontal spine
        row_has_wire = bool(np.any(wm[hy, spine_left:spine_right+1]))
        row_has_plant = bool(np.any(pm[hy, spine_left:spine_right+1]))

        if not row_has_wire and not row_has_plant:
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - hx) + np.abs(wire_ys - hy)
                nearest_idx = np.argmin(dists)
                wx, wy = int(wire_xs[nearest_idx]), int(wire_ys[nearest_idx])
                if abs(wx - hx) > abs(wy - hy):
                    step_x = 1 if hx > wx else -1
                    nx, ny = wx + step_x, wy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
                else:
                    step_y = 1 if hy > wy else -1
                    nx, ny = wx, wy + step_y
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
        else:
            row_wire_cols = [c for c in range(spine_left, spine_right + 1)
                             if ib(c, hy) and bool(wm[hy, c])]
            if row_wire_cols:
                min_wc, max_wc = min(row_wire_cols), max(row_wire_cols)
                if max_wc < spine_right:
                    nc = max_wc + 1
                    if ib(nc, hy) and bool(em[hy, nc]) and not bool(pm[hy, nc]):
                        return (Tool.WIRE, nc, hy)
                if min_wc > spine_left:
                    nc = min_wc - 1
                    if ib(nc, hy) and bool(em[hy, nc]) and not bool(pm[hy, nc]):
                        return (Tool.WIRE, nc, hy)

    # --- STEP 4: Roads parallel to wire spines ---
    for (hx, hy) in active_hoods:
        # Vertical roads at ±3 from wire spine column
        col_wire_rows = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 3, hx + 3]:
            if not ib(rx, hy) or not col_wire_rows:
                continue
            cyc = step % 9
            for wr in col_wire_rows[cyc::9]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        # Horizontal roads at ±3 from wire spine row
        row_wire_cols = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 3, hy + 3]:
            if not ib(hx, ry) or not row_wire_cols:
                continue
            cyc = (step + 5) % 9
            for wc in row_wire_cols[cyc::9]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- STEP 5: ZONE PLACEMENT (reactive to current road+power coverage) ---
    def pick_tool():
        """Dynamic mix based on current zone ratios."""
        if total_zones < 3:
            return Tool.RESIDENTIAL
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        # Prioritize underrepresented types
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        if r_r < 0.45:
            return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        """Check 3x3 area is placeable."""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Zone candidates: empty + near road + near power
    cand_mask = em & nbr_road2 & nbr_power3
    # Border buffer
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods and existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Bonus: cluster near existing zones
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 60)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        # Use step+pop offset for variety
        off = (step * 11 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- STEP 6: Civic services (reactive to population) ---
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(16, 92, 18)
                     for fx in range(16, 110, 20)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(20, 88, 20)
                       for px2 in range(20, 106, 22)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road2 & nbr_power3)
        if len(park_cands_x) > 0:
            idx = (step * 17 + pop) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 600:
        stadium_locs = [
            (28, 22), (60, 12), (92, 22),
            (18, 50), (60, 50), (102, 50),
            (28, 78), (60, 88), (92, 78),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power when population large enough
    if pop > 800 and funds > 5000:
        nuke_locs = [
            (8, 8), (112, 8), (8, 92), (112, 92),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuke_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 8), min(WORLD_W, npx + 9)
            y0b, y1b = max(0, npy - 8), min(WORLD_H, npy + 9)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(4, 50), (116, 50), (60, 4), (60, 96),
                        (4, 25), (4, 75), (116, 25), (116, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 2000:
        airport_locs = [(8, 8), (102, 8), (8, 88), (102, 88)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: Extend roads from existing network into powered areas ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power3[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- FALLBACK: Extend wire from any wire tile ---
    if len(wire_xs) > 0:
        sk2 = (step * 17) % len(wire_xs)
        for offset in range(min(len(wire_xs), 60)):
            k = (sk2 + offset * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    # --- FALLBACK: Extend wire from plants ---
    if len(plant_xs) > 0:
        sk = (step * 11) % len(plant_xs)
        for offset in range(min(len(plant_xs), 40)):
            k = (sk + offset * 7) % len(plant_xs)
            ppx2, ppy2 = int(plant_xs[k]), int(plant_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = ppx2 + dx2, ppy2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + initial road grid"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Roads flanking the horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PHASE 1: Ensure power plants exist in each region ===
    # Check a grid of plant positions every ~20 tiles
    if step % 6 == 0:
        plant_positions = []
        for py in range(15, WORLD_H - 5, 20):
            for px in range(15, WORLD_W - 5, 20):
                plant_positions.append((px, py))
        for px, py in plant_positions:
            x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
            y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                # Find nearest empty spot
                for r in range(0, 6):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if placed:
                        break

    # === PHASE 2: Extend wire toward unpowered zones ===
    if step % 6 == 1:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            # Find wire/plant positions
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                # Pick closest unpowered zone to existing power
                best_dist = 999999
                best_zone = None
                sample = min(len(uz_xs), 30)
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # === PHASE 3: Extend wire to unpowered regions ===
    if step % 6 == 2:
        # Find empty unpowered areas and extend wire toward them
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False

        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            # Look for empty unpowered area
            unpowered_empty = em & ~near_power & ~zone_tiles
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                best_dist = 1e9
                best_k = 0
                sample_indices = np.linspace(0, len(upxs) - 1, min(30, len(upxs)), dtype=int)
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_indices)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # === PHASE 4: Extend road network ===
    if step % 6 == 3:
        # Connect unpowered zones to road
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

        # Extend road grid: roads every 6 tiles in powered areas
        road_grid_targets = []
        for gy in range(6, 97, 6):
            for gx in range(6, 115, 6):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        if road_grid_targets:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted

            road_cand = em & adj_to_road & near_power & ~zone_tiles
            road_cand[0:2, :] = False
            road_cand[WORLD_H - 2:, :] = False
            road_cand[:, 0:2] = False
            road_cand[:, WORLD_W - 2:] = False

            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                best_dist = 1e9
                best_k = 0
                targets_sample = road_grid_targets[:30]
                for i in range(min(len(rxs2), 400)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
            else:
                for gx, gy in road_grid_targets[:10]:
                    if bool(em[gy, gx]):
                        return (Tool.ROAD, gx, gy)

    # === PHASE 5: Civic services ===
    if step % 6 == 4:
        if pop > 25:
            fire_grid = [(fx, fy) for fy in range(10, 95, 15) for fx in range(10, 115, 15)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        if pop > 150:
            police_grid = [(px2, py2) for py2 in range(15, 90, 18) for px2 in range(15, 110, 18)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        if pop > 300 and step % 8 == 4:
            park_cands = em & near_road & near_power
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 31 + pop) % len(pxs3)
                px2, py2 = int(pxs3[idx]), int(pys3[idx])
                if not bool(zone_tiles[py2, px2]):
                    return (Tool.PARK, px2, py2)

        if pop > 500:
            stadium_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                            (60, 50), (15, 50), (105, 50), (60, 15), (60, 85)]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        if pop > 800:
            nuke_locs = [(10, 25), (110, 25), (10, 75), (110, 75),
                         (60, 10), (60, 90), (10, 50), (110, 50),
                         (35, 15), (85, 15), (35, 85), (85, 85)]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                    y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            airport_locs = [(10, 10), (100, 10), (10, 88), (100, 88)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        if pop > 2000:
            seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # === PHASE 6: Zone placement ===
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        # Score: close to road, spread away from existing zones
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Prefer close to road, spread from existing zones
        score = road_dist * 1.0 + np.maximum(0, 8 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spines and flanking roads."""
    actions = []
    # Three power columns at x=20, 60, 100; centered at y=50
    for px in [20, 60, 100]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood grid: columns at 20,40,60,80,100; rows at 20,35,50,65,80
    nh_cols = [20, 40, 60, 80, 100]
    nh_rows = [20, 35, 50, 65, 80]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 3
        if pop < 350:   return 6
        if pop < 700:   return 10
        if pop < 1200:  return 15
        if pop < 2000:  return 18
        if pop < 3500:  return 22
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    # ---- BUILD PROXIMITY MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS NEAR ACTIVE HOODS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: EXTEND WIRE TOWARD UNCOVERED HOODS ----
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            for (tx, ty) in uncovered:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: EXTEND WIRE SPINES FOR ACTIVE HOODS ----
    spine_half = min(20, 8 + pop // 20)
    hood_cycle = step % max(len(active_hoods), 1)
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Vertical spine
        spine_top = max(2, hy - spine_half)
        spine_bot = min(WORLD_H - 3, hy + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(hx, r) and bool(wm[r, hx])]
        if not wire_in_col:
            for dy2 in range(-5, 6):
                ny = hy + dy2
                if ib(hx, ny) and bool(em[ny, hx]) and not bool(pm[ny, hx]):
                    return (Tool.WIRE, hx, ny)
        else:
            max_wr = max(wire_in_col)
            min_wr = min(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)

    # ---- PHASE 4: HORIZONTAL WIRE CONNECTING HOODS AT SAME ROW ----
    row_levels = sorted(set(hy for (hx, hy) in active_hoods))
    for yl in row_levels:
        row_hood_xs = sorted([hx for (hx, hy) in active_hoods if hy == yl])
        for i in range(len(row_hood_xs) - 1):
            x1, x2 = row_hood_xs[i], row_hood_xs[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]) and not bool(wm[yl, cx]):
                    # Only connect if adjacent cell has wire
                    if bool(wm[yl, cx - 1]) or bool(wm[yl, cx + 1]) or bool(pm[yl, cx - 1]) or bool(pm[yl, cx + 1]):
                        return (Tool.WIRE, cx, yl)

    # ---- PHASE 5: VERTICAL WIRE CONNECTING HOODS IN SAME COLUMN ----
    col_levels = sorted(set(hx for (hx, hy) in active_hoods))
    for xl in col_levels:
        col_hood_ys = sorted([hy for (hx, hy) in active_hoods if hx == xl])
        for i in range(len(col_hood_ys) - 1):
            y1, y2 = col_hood_ys[i], col_hood_ys[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]) and not bool(wm[cy, xl]):
                    if bool(wm[cy - 1, xl]) or bool(wm[cy + 1, xl]) or bool(pm[cy - 1, xl]) or bool(pm[cy + 1, xl]):
                        return (Tool.WIRE, xl, cy)

    # ---- PHASE 6: ROADS FLANKING WIRE SPINES ----
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        spine_top = max(2, hy - spine_half)
        spine_bot = min(WORLD_H - 3, hy + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(hx, r) and bool(wm[r, hx])]
        cycle = (step + idx_h * 7) % 3
        for wr in wire_in_col[cycle::3]:
            for rx in [hx - 1, hx + 1]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- PHASE 7: HORIZONTAL ROADS AT HOOD ROW LEVELS ----
    if pop > 30:
        for yl in row_levels:
            row_hood_xs = sorted([hx for (hx, hy) in active_hoods if hy == yl])
            if len(row_hood_xs) < 2:
                continue
            x_min = row_hood_xs[0] - 1
            x_max = row_hood_xs[-1] + 1
            for horiz_y in [yl - 3, yl + 3]:
                for cx in range(x_min, x_max + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- PHASE 8: CROSS ROADS CONNECTING ROW LEVELS ----
    if pop > 80 and len(row_levels) >= 2:
        for xl in col_levels:
            for rx in [xl - 2, xl + 2]:
                col_hood_ys_sorted = sorted([hy for (hx, hy) in active_hoods if hx == xl])
                for i in range(len(col_hood_ys_sorted) - 1):
                    y1, y2 = col_hood_ys_sorted[i], col_hood_ys_sorted[i + 1]
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- PHASE 9: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx).astype(float) + np.abs(cys_arr - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 10: EXTEND ROADS FROM EXISTING ROADS IN POWERED AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive) ----
    if pop > 60:
        fire_grid = [(fx, fy) for fx in range(10, WORLD_W, 20) for fy in range(10, WORLD_H, 20)]
        for (fx, fy) in fire_grid:
            if ib(fx, fy) and bool(em[fy, fx]):
                return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        police_grid = [(px2, py2) for px2 in range(15, WORLD_W, 25) for py2 in range(15, WORLD_H, 25)]
        for (px2, py2) in police_grid:
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        stadium_spots = [(10, 10), (55, 10), (100, 10), (10, 90), (55, 90), (100, 90), (10, 50), (110, 50)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000 and step % 3 == 0:
        nuke_spots = [(5, 5), (115, 5), (5, 95), (115, 95), (60, 5), (60, 95), (5, 50), (115, 50),
                      (30, 5), (90, 5), (30, 95), (90, 95)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        airport_spots = [(55, 6), (5, 50), (115, 50), (55, 94), (30, 6), (90, 6)]
        for (ax, ay) in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        seaport_spots = [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]
        for (sx2, sy2) in seaport_spots:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS for land value ----
    if pop > 150 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: new coal plant near uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
