def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio: 45% res, 30% com, 25% ind
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plants ----
    # Dense plant grid every 25 cols, 25 rows
    plant_grid_xs = list(range(15, WORLD_W - 5, 25))
    plant_grid_ys = list(range(15, WORLD_H - 5, 25))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network - connect plants together ----
    # Wire rows at y=25,50,75
    wire_rows = [25, 50, 75]
    # Wire cols at x=30,60,90
    wire_cols = [30, 60, 90]

    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest = pxs[np.argmin(np.abs(pys - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if bool(em[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network ----
    # Roads at y=20,30,40,60,70,80 and x=10,20,40,50,70,80,100,110
    road_rows_target = [20, 30, 40, 60, 70, 80]
    road_cols_target = [10, 20, 40, 50, 70, 80, 100, 110]

    for rr in road_rows_target:
        row_rd = rm[rr, :]
        if not row_rd.any():
            for rx in range(5, WORLD_W - 5):
                if ib(rx, rr) and bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    return (Tool.ROAD, rx, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 5 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 6 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols_target:
        col_rd = rm[:, rc]
        if not col_rd.any():
            for ry in range(5, WORLD_H - 5):
                if ib(rc, ry) and bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    return (Tool.ROAD, rc, ry)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 5 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 6 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement (closed-loop) ----
    zone_cand = em & near_road & near_power
    # Keep safe margins
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    # Don't overwrite infrastructure
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rr in road_rows_target:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for rc in road_cols_target:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer spots adjacent to existing zones but not too close (avoid overlap)
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                         np.where(min_zone_dist < 8, 0.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.8, 0.0)))
        else:
            # Start near center
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.1

        score = road_dist * 2.0 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 7 + pop) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(10, 90, 15) for fx in range(10, 110, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(10, 90, 18) for px2 in range(10, 110, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(8, 92, 10) for pkx in range(8, 112, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [(sx, sy) for sy in range(15, 85, 30) for sx in range(15, 105, 35)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Upgrade to nuclear power
        nuclear_spots = [(nx, ny) for ny in range(15, 90, 25) for nx in range(15, 110, 25)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-12), min(WORLD_W, npx+13)
                y0, y1 = max(0, npy-12), min(WORLD_H, npy+13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(58, 8), (62, 8), (58, 91), (62, 91), (8, 48), (111, 48)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [(8, 50), (111, 50), (60, 5), (60, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire extension toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: place road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(8,0),(-8,0),(0,8),(0,-8),(5,0),(-5,0),(0,5),(0,-5)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire cross + road grid seed"""
    actions = []
    # Central coal plants
    for px, py in [(30, 25), (90, 25), (30, 75), (90, 75), (60, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines connecting plants
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Seed roads adjacent to wire spines
    for rx in [28, 32, 58, 62, 88, 92]:
        for y in range(2, 98, 4):
            actions.append((Tool.ROAD, rx, y))
    for ry in [23, 27, 48, 52, 73, 77]:
        for x in range(2, 118, 4):
            actions.append((Tool.ROAD, x, ry))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # --- CLOSED LOOP: React to what's on the map ---

    # 1) If there are unpowered zones, extend wire toward them
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        uz_ys, uz_xs = np.where(unpowered_zones)
        power_ys, power_xs = np.where(wm | pm)
        if len(power_xs) > 0:
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            dists = np.abs(power_xs - tx) + np.abs(power_ys - ty)
            best = np.argmin(dists)
            bx, by = int(power_xs[best]), int(power_ys[best])
            # Step toward unpowered zone
            dx = 0 if tx == bx else (1 if tx > bx else -1)
            dy = 0 if ty == by else (1 if ty > by else -1)
            for nx, ny in [(bx+dx, by), (bx, by+dy), (bx+dx, by+dy)]:
                if ib(nx, ny) and bool(em[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # 2) If there are zones with road access but no road near them, extend road
    zone_no_road = zone_tiles & ~near_road
    if np.any(zone_no_road):
        znr_ys, znr_xs = np.where(zone_no_road)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            idx = (step * 13) % len(znr_xs)
            tx, ty = int(znr_xs[idx]), int(znr_ys[idx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best = np.argmin(dists)
            bx, by = int(road_xs[best]), int(road_ys[best])
            dx = 0 if tx == bx else (1 if tx > bx else -1)
            dy = 0 if ty == by else (1 if ty > by else -1)
            for nx, ny in [(bx+dx, by), (bx, by+dy)]:
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # 3) Check if power coverage is sparse — add coal plants in uncovered areas
    # Find large empty areas far from power
    if step % 20 == 0:
        # Sample grid points, find one far from power
        best_dist = -1
        best_pos = None
        for py in range(10, 95, 15):
            for px in range(10, 115, 15):
                if not bool(near_power[py, px]) and bool(em[py, px]):
                    d = 1
                    for dy in range(-8, 9):
                        for dx in range(-8, 9):
                            nx, ny = px+dx, py+dy
                            if ib(nx, ny) and (bool(wm[ny, nx]) or bool(pm[ny, nx])):
                                d = 0
                                break
                        if d == 0:
                            break
                    if d > best_dist:
                        best_dist = d
                        best_pos = (px, py)
        if best_pos and best_dist > 0:
            return (Tool.COALPOWER, best_pos[0], best_pos[1])

    # 4) Extend wire grid: find wire endpoints and extend them
    if step % 8 in (1, 2, 3):
        # Find wire tiles that have fewer than 2 wire/plant neighbors — these are endpoints
        wm_int = wm.astype(np.int16) + pm.astype(np.int16)
        # neighbor count
        neigh = (np.roll(wm_int, 1, 0) + np.roll(wm_int, -1, 0) +
                 np.roll(wm_int, 1, 1) + np.roll(wm_int, -1, 1))
        endpoints = wm & (neigh <= 1)
        ep_ys, ep_xs = np.where(endpoints)
        if len(ep_xs) > 0:
            # Find endpoint farthest from wire coverage centroid
            # Just extend in a direction toward empty near-power areas
            idx = (step * 7) % len(ep_xs)
            ex, ey = int(ep_xs[idx]), int(ep_ys[idx])
            # Try to extend toward largest empty region
            best_dir = None
            best_empty = -1
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = ex+dx, ey+dy
                if ib(nx, ny) and bool(em[ny, nx]):
                    # Count empty tiles further in this direction
                    cnt = 0
                    for k in range(1, 10):
                        nx2, ny2 = ex+dx*k, ey+dy*k
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            cnt += 1
                        else:
                            break
                    if cnt > best_empty:
                        best_empty = cnt
                        best_dir = (nx, ny)
            if best_dir:
                return (Tool.WIRE, best_dir[0], best_dir[1])

    # 5) Extend road grid: grow roads from endpoints into powered areas
    if step % 8 in (4, 5):
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx, ry = int(road_xs[k]), int(road_ys[k])
                for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx, ny = rx+dx, ry+dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        if bool(near_power[ny, nx]):
                            return (Tool.ROAD, nx, ny)

    # 6) Civic services based on population
    if pop > 20 and step % 15 == 0:
        # Place fire station in area with zones but no fire station nearby
        fire_ys, fire_xs = np.where(zone_tiles)
        if len(fire_xs) > 0:
            idx = (step * 19) % len(fire_xs)
            tx, ty = int(fire_xs[idx]), int(fire_ys[idx])
            # Find empty spot near this zone
            for r in range(3, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = tx+dx, ty+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.FIRESTATION, nx, ny)

    if pop > 100 and step % 20 == 0:
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            idx = (step * 23) % len(zone_xs)
            tx, ty = int(zone_xs[idx]), int(zone_ys[idx])
            for r in range(3, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = tx+dx, ty+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.POLICESTATION, nx, ny)

    if pop > 500 and step % 30 == 0:
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            idx = (step * 29) % len(zone_xs)
            tx, ty = int(zone_xs[idx]), int(zone_ys[idx])
            for r in range(3, 15):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = tx+dx, ty+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.STADIUM, nx, ny)

    if pop > 1000 and step % 25 == 0:
        # Add nuclear power for more capacity
        for py in range(5, 95, 20):
            for px in range(5, 115, 20):
                if ib(px, py) and bool(em[py, px]):
                    return (Tool.NUCLEARPOWER, px, py)

    # 7) Parks to boost land value near zones
    if pop > 100 and step % 5 == 0:
        park_cand = em & near_road & near_power
        park_cand[0:2, :] = False
        park_cand[WORLD_H-2:, :] = False
        park_cand[:, 0:2] = False
        park_cand[:, WORLD_W-2:] = False
        p_ys, p_xs = np.where(park_cand)
        if len(p_xs) > 0:
            # Pick park near zones
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zidx = (step * 31) % len(zone_xs)
                ztx, zty = int(zone_xs[zidx]), int(zone_ys[zidx])
                dists = np.abs(p_xs - ztx) + np.abs(p_ys - zty)
                best = np.argmin(dists)
                if dists[best] < 15:
                    return (Tool.PARK, int(p_xs[best]), int(p_ys[best]))

    # 8) PRIMARY: Place zones in powered+road areas
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()

        # Find cluster centroid of existing zones to prefer nearby placement
        if total_zones > 3:
            zone_ys, zone_xs = np.where(zone_tiles)
            # Use centroid of zones as attraction point
            cx = int(np.mean(zone_xs))
            cy = int(np.mean(zone_ys))
            dists = np.abs(cxs - cx).astype(float) + np.abs(cys - cy).astype(float)
            # Also attract toward empty areas (spread out a bit with pop)
            spread_factor = min(pop / 200.0, 1.0)
            # Mix: prefer near centroid early, spread later
            order = np.argsort(dists * (1.0 - spread_factor * 0.5))
        else:
            # No zones yet, pick central candidates
            dists = np.abs(cxs - 60).astype(float) + np.abs(cys - 50).astype(float)
            order = np.argsort(dists)

        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # 9) Fallback: extend road into powered empty area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = rx+dx, ry+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # 10) Fallback: extend wire
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        sk = (step * 13) % len(wire_xs)
        for off in range(min(len(wire_xs), 150)):
            k = (sk + off * 5) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    actions.append((Tool.COALPOWER, 60, 50))
    for d in range(-4, 5):
        if d != 0:
            actions.append((Tool.WIRE, 60 + d, 50))
            actions.append((Tool.WIRE, 60, 50 + d))
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD ANCHORS ----
    nh_xs = [15, 35, 60, 85, 105]
    nh_ys = [15, 38, 62, 85]
    all_hoods = [(x, y) for y in nh_ys for x in nh_xs]  # 20 total

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 9
        if pop < 2000:  return 12
        if pop < 4000:  return 16
        if pop < 6000:  return 18
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    spine_range = 16

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (vertical at hx, horizontal at hy) ----
    # Only process one hood per step to keep it fast, cycle through them
    hood_idx = step % len(active_hoods)
    hx, hy = active_hoods[hood_idx]

    # Vertical spine at hx
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj in [-1, 1]:
            ay = wy + adj
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine at hy
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj in [-1, 1]:
            ax = wx + adj
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: WIRE CONNECTIONS between adjacent hoods ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i: continue
            # Horizontal connections (same row)
            if hy1 == hy2 and abs(hx2 - hx1) <= 35:
                for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx, hy1): continue
                    if bool(wm[hy1, cx]) or bool(pm[hy1, cx]): continue
                    if not bool(em[hy1, cx]): continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
            # Vertical connections (same col)
            if hx1 == hx2 and abs(hy2 - hy1) <= 35:
                for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(hx1, cy): continue
                    if bool(wm[cy, hx1]) or bool(pm[cy, hx1]): continue
                    if not bool(em[cy, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy)

    # ---- PHASE 4: ROADS flanking wire spines ----
    # Cycle through hoods
    road_hood_idx = (step // 2) % len(active_hoods)
    rhx, rhy = active_hoods[road_hood_idx]

    for rx in [rhx - 1, rhx + 1]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            # Only place road if wire is present at spine
            if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [rhy - 1, rhy + 1]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PRECOMPUTE COVERAGE MASKS ----
    zone_tiles = resm | comm | indm

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target mix: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ahx, ahy) in active_hoods:
            d = np.abs(cxs - ahx) + np.abs(cys - ahy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 20) for fy in range(10, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 22) for py2 in range(15, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadiums = [
            (25, 25), (60, 25), (95, 25),
            (25, 50), (60, 50), (95, 50),
            (25, 75), (60, 75), (95, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(45, 6), (75, 6), (45, 93), (75, 93), (6, 45), (6, 65), (113, 45), (113, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop areas ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [
            (15, 15), (60, 15), (105, 15),
            (15, 50), (105, 50),
            (15, 85), (60, 85), (105, 85),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 250 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new coal plant near unpowered active hood ----
    for (ahx, ahy) in active_hoods:
        if not bool(nbr_power[ahy, ahx]):
            if ib(ahx, ahy) and bool(em[ahy, ahx]):
                return (Tool.COALPOWER, ahx, ahy)
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = ahx + dx, ahy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire spines and flanking roads."""
    actions = []
    # Place 2 plants at strategic positions
    for px in [30, 90]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Compute neighbor masks efficiently ---
    power_src = wm | pm

    # Dilate power source by 6
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Dilate road by 3
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Define a denser grid of neighborhoods
    nh_cols = [15, 30, 45, 60, 75, 90, 105]
    nh_rows = [15, 30, 45, 60, 75, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 14
        if pop < 800:   return 20
        if pop < 1500:  return 28
        if pop < 3000:  return 35
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly across the full list
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # --- PHASE 1: Ensure power plant near each active hood ---
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            # Spiral search for empty spot
            for r in range(0, 16):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # --- PHASE 2: Wire from plant toward uncovered hoods ---
    # Find all plants, extend wire toward hoods that lack power
    plant_ys, plant_xs = np.where(pm)
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            # Find nearest plant
            if len(plant_xs) > 0:
                dists = np.abs(plant_xs - hx) + np.abs(plant_ys - hy)
                k = int(np.argmin(dists))
                px_p, py_p = int(plant_xs[k]), int(plant_ys[k])
                # Walk wire toward hood from plant
                # Move in the direction of larger distance first
                wx, wy = px_p, py_p
                dx_h = hx - px_p
                dy_h = hy - py_p
                if abs(dx_h) >= abs(dy_h):
                    step_x = 1 if dx_h > 0 else -1
                    nx, ny = wx + step_x, wy
                else:
                    step_y = 1 if dy_h > 0 else -1
                    nx, ny = wx, wy + step_y
                if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                    if not bool(wm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
                # Also try extending existing wire toward hood
                for col in range(min(px_p, hx), max(px_p, hx) + 1):
                    if ib(col, py_p) and not bool(pm[py_p, col]) and not bool(wm[py_p, col]) and bool(em[py_p, col]):
                        # Check it's on path
                        if (px_p <= col <= hx) or (hx <= col <= px_p):
                            return (Tool.WIRE, col, py_p)
                for row in range(min(py_p, hy), max(py_p, hy) + 1):
                    if ib(px_p, row) and not bool(pm[row, px_p]) and not bool(wm[row, px_p]) and bool(em[row, px_p]):
                        if (py_p <= row <= hy) or (hy <= row <= py_p):
                            return (Tool.WIRE, px_p, row)

    # --- PHASE 3: Extend wire network reactively ---
    # Find wire frontier (wire cells with empty neighbors) and extend toward unpowered hoods
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        # Find hoods that need power
        unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
        if unpowered_hoods:
            # Pick a random unpowered hood (deterministically)
            uh_idx = step % len(unpowered_hoods)
            thx, thy = unpowered_hoods[uh_idx]
            # Find closest wire to this hood
            dists = np.abs(wire_xs - thx) + np.abs(wire_ys - thy)
            k = int(np.argmin(dists))
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            # Step wire toward hood
            ddx = thx - wx2
            ddy = thy - wy2
            if abs(ddx) >= abs(ddy) and ddx != 0:
                nx2, ny2 = wx2 + (1 if ddx > 0 else -1), wy2
            elif ddy != 0:
                nx2, ny2 = wx2, wy2 + (1 if ddy > 0 else -1)
            else:
                nx2, ny2 = wx2, wy2
            if ib(nx2, ny2) and not bool(pm[ny2, nx2]) and bool(em[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    # --- PHASE 4: Build roads near powered areas ---
    # Extend roads from existing road cells toward powered but un-roaded areas
    road_ys, road_xs = np.where(rm)

    # Find powered but road-less areas near active hoods
    need_road = nbr_power & ~nbr_road & ~rm & em
    need_road[0:3, :] = False
    need_road[WORLD_H-3:, :] = False
    need_road[:, 0:3] = False
    need_road[:, WORLD_W-3:] = False

    nr_ys, nr_xs = np.where(need_road)
    if len(nr_xs) > 0 and len(road_xs) > 0:
        # Find a need-road cell near an active hood
        best_dist = np.full(len(nr_xs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(nr_xs - hx).astype(float) + np.abs(nr_ys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        k = int(np.argmin(best_dist))
        trx, try_ = int(nr_xs[k]), int(nr_ys[k])
        # Find closest road and step toward target
        rdists = np.abs(road_xs - trx) + np.abs(road_ys - try_)
        rk = int(np.argmin(rdists))
        rx_near, ry_near = int(road_xs[rk]), int(road_ys[rk])
        ddx = trx - rx_near
        ddy = try_ - ry_near
        if abs(ddx) >= abs(ddy) and ddx != 0:
            nx3, ny3 = rx_near + (1 if ddx > 0 else -1), ry_near
        elif ddy != 0:
            nx3, ny3 = rx_near, ry_near + (1 if ddy > 0 else -1)
        else:
            nx3, ny3 = rx_near, ry_near
        if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
            return (Tool.ROAD, nx3, ny3)

    # Also extend roads from existing roads into powered empty areas
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_power[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # --- PHASE 5: Zone placement ---
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary starting point by step to avoid always placing in same spot
        offset = (step * 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: Civic services based on population ---
    if pop > 60:
        fire_spots = [(fx, fy)
                      for fx in range(12, WORLD_W, 20)
                      for fy in range(12, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2)
                        for px2 in range(18, WORLD_W, 24)
                        for py2 in range(18, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (25, 10), (60, 10), (95, 10),
            (25, 90), (60, 90), (95, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (8, 8), (112, 8), (8, 92), (112, 92),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (35, 8), (85, 8), (35, 92), (85, 92),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [
            (40, 5), (80, 5), (40, 94), (80, 94),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- PHASE 7: Parks for land value boost ---
    if pop > 150 and step % 6 == 0:
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 3 + i * 19) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # --- Fallback: extend wire from any existing wire ---
    if len(wire_xs) > 0:
        step_k2 = (step * 17) % max(len(wire_xs), 1)
        for offset in range(min(len(wire_xs), 150)):
            k = (step_k2 + offset * 7) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # --- Fallback: new plant near unpowered hood ---
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spines and flanking roads."""
    actions = []
    # Three power plants at columns 20, 60, 100, row 50
    for px in [20, 60, 100]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Power plant anchor columns, rows expand with population
    plant_cols = [20, 60, 100]
    plant_rows = [50]
    if pop > 200:
        plant_rows = [33, 67]
    if pop > 600:
        plant_rows = [20, 50, 80]

    # ---- ENSURE POWER PLANTS EXIST ----
    # For each desired plant location, check if a plant is nearby
    for px in plant_cols:
        for py in plant_rows:
            y0 = max(0, py - 5); y1 = min(WORLD_H, py + 6)
            x0 = max(0, px - 5); x1 = min(WORLD_W, px + 6)
            if np.any(pm[y0:y1, x0:x1]):
                continue
            # Need a plant here - find nearest empty spot
            for r in range(0, 8):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE EXTENSION: grow wire from existing wire toward nearby empty cells ----
    # Strategy: find wire cells, extend them toward zones/areas that need power
    # First, build a "needs power" map - areas near roads but far from wire

    # Compute neighbor of wire (power reach)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- EXTEND WIRE from plant outward reactively ----
    # Find plant cells and extend wire from them if nearby cells lack wire
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # For each plant, check if wire extends far enough
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            # Check vertical spine
            for direction in [1, -1]:
                for dist in range(1, 20):
                    ny = py2 + direction * dist
                    if not ib(px2, ny):
                        break
                    if bool(pm[ny, px2]):
                        break
                    if bool(wm[ny, px2]):
                        continue
                    if bool(em[ny, px2]):
                        return (Tool.WIRE, px2, ny)
                    break

    # ---- EXTEND WIRE HORIZONTALLY to connect plants ----
    # Connect wire between plant columns at the same row
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        # Find columns with wire
        wire_cols_set = set(int(x) for x in wire_xs2)
        # For each pair of plant cols, try to connect them
        for i in range(len(plant_cols) - 1):
            c1_col = plant_cols[i]
            c2_col = plant_cols[i + 1]
            # Find common y levels where both have wire
            for py_level in plant_rows:
                # Check if wire spans from c1 to c2 at py_level
                # Extend from existing wire endpoints
                # Find rightmost wire in c1's column near py_level
                best_x = c1_col
                for cx in range(c1_col, c2_col):
                    if ib(cx, py_level) and bool(wm[py_level, cx]):
                        best_x = cx
                # Extend one step right
                nx2 = best_x + 1
                if nx2 < c2_col and ib(nx2, py_level) and bool(em[py_level, nx2]) and not bool(pm[py_level, nx2]):
                    return (Tool.WIRE, nx2, py_level)

    # ---- ROAD BUILDING: extend roads reactively ----
    # Find road endpoints and extend them toward areas with wire but no road
    road_ys2, road_xs2 = np.where(rm)

    # Build vertical roads along wire spines
    for px in plant_cols:
        for py in plant_rows:
            spine_top = max(2, py - 15)
            spine_bot = min(WORLD_H - 3, py + 15)
            # Left flank road
            for road_x in [px - 1, px + 1]:
                if not ib(road_x, py):
                    continue
                # Find missing road segments along spine
                for ry in range(spine_top, spine_bot + 1):
                    if ib(road_x, ry) and bool(em[ry, road_x]) and not bool(pm[ry, road_x]) and bool(wm[ry, px] if ib(px, ry) else False):
                        return (Tool.ROAD, road_x, ry)

    # ---- EXTEND ROADS from existing roads ----
    # Reactively: find road cells near wire, extend toward more wire coverage
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) 
                        and not bool(pm[ny2, nx2]) 
                        and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- HORIZONTAL ROADS between plant columns ----
    for py in plant_rows:
        for road_y_off in [-3, 3]:
            horiz_y = py + road_y_off
            if not ib(0, horiz_y):
                continue
            for col_i in range(len(plant_cols) - 1):
                c1 = plant_cols[col_i]
                c2 = plant_cols[col_i + 1]
                for cx in range(c1 - 1, c2 + 2):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- ZONE PLACEMENT (closed-loop, reactive) ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate: empty, near road, near wire
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest plant
        best_dist = np.full(len(cxs), 999999.0)
        for px in plant_cols:
            for py in plant_rows:
                d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
                best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- CIVIC SERVICES (reactive, based on pop thresholds) ----
    if pop > 80:
        fire_spots = [
            (8, 15), (35, 15), (75, 15), (108, 15),
            (8, 50), (35, 50), (75, 50), (108, 50),
            (8, 85), (35, 85), (75, 85), (108, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (22, 25), (55, 25), (88, 25),
            (22, 60), (55, 60), (88, 60),
            (22, 90), (55, 90), (88, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 50), (50, 50), (90, 50),
            (10, 90), (50, 90), (90, 90),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        # Add nuclear plants reactively when coal is insufficient
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PARKS to boost land value near zones ----
    if pop > 150:
        zone_map = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 20)):
                k = (step * 3 + i * 17) % len(zone_xs3)
                zx2, zy2 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle with wire+road spines."""
    actions = []
    # Three power plants spread across the map
    plants = [(30, 40), (70, 40), (50, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-8, 9):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire (above and below)
        for dx in range(-8, 9):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
        # Roads flanking vertical wire (left and right)
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target: 50% RES, 25% COM, 25% IND
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of anchors covering the map better
    all_anchors = []
    for ax in [15, 30, 50, 70, 90, 105]:
        for ay in [15, 30, 45, 60, 75, 88]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 6
        if pop < 300:  return 9
        if pop < 500:  return 12
        if pop < 800:  return 18
        if pop < 1200: return 24
        if pop < 2000: return 30
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE EXPANSION ----
    wire_half = min(22, 7 + pop // 10)
    vert_half = min(16, 5 + pop // 15)

    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- WIRE CONNECTIONS between anchors in same column ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    # ---- WIRE CONNECTIONS between anchors in same row ----
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: roads flanking horizontal wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-2, 2]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = False
                    for ddx in [-1, 1]:
                        if ib(cx + ddx, road_y) and bool(rm[road_y, cx + ddx]):
                            adj_road = True
                    adj_wire = (ib(cx, road_y - 1) and bool(wm[road_y - 1, cx])) or \
                               (ib(cx, road_y + 1) and bool(wm[road_y + 1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # ---- VERTICAL ROADS flanking vertical wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-2, 2]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = False
                    for ddy in [-1, 1]:
                        if ib(road_x, cy + ddy) and bool(rm[cy + ddy, road_x]):
                            adj_road = True
                    adj_wire = (ib(road_x - 1, cy) and bool(wm[cy, road_x - 1])) or \
                               (ib(road_x + 1, cy) and bool(wm[cy, road_x + 1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: near roads and wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_spots = [
            (8, 8), (30, 8), (55, 8), (80, 8), (108, 8),
            (8, 28), (30, 28), (55, 28), (80, 28), (108, 28),
            (8, 48), (30, 48), (55, 48), (80, 48), (108, 48),
            (8, 68), (30, 68), (55, 68), (80, 68), (108, 68),
            (8, 88), (30, 88), (55, 88), (80, 88), (108, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (12, 5), (37, 5), (62, 5), (87, 5), (112, 5),
            (12, 25), (37, 25), (62, 25), (87, 25), (112, 25),
            (12, 45), (37, 45), (62, 45), (87, 45), (112, 45),
            (12, 65), (37, 65), (62, 65), (87, 65), (112, 65),
            (12, 85), (37, 85), (62, 85), (87, 85), (112, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(22, 5), (62, 5), (102, 5), (22, 92), (62, 92), (102, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        # Nuclear plants for more power
        for (nx2, ny2) in [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5), (60, 94), (5, 50), (115, 50)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for (ax2, ay2) in [(55, 6), (5, 50), (115, 50), (55, 92), (20, 5), (95, 5)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for (sx2, sy2) in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5), (60, 2)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones for land value boost ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: single coal plant + initial wire/road cross"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire arms from plant
    for x in range(55, 60):
        actions.append((Tool.WIRE, x, 50))
    for x in range(61, 67):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 50):
        actions.append((Tool.WIRE, 60, y))
    for y in range(51, 56):
        actions.append((Tool.WIRE, 60, y))
    # Initial roads near plant
    for x in range(50, 72):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    for y in range(45, 56):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 71, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Add more coal plants if coverage is insufficient ----
    # Check power coverage — place new plants reactively where needed
    plant_locs = [
        (30, 25), (90, 25), (30, 75), (90, 75),
        (60, 15), (60, 85), (15, 50), (105, 50),
        (45, 50), (75, 50), (30, 50), (90, 50),
        (60, 30), (60, 70), (20, 30), (100, 30),
        (20, 70), (100, 70),
    ]
    for px, py in plant_locs:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion — connect unpowered areas ----
    # Find tiles adjacent to power that are empty (not road, not zone)
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0:
        # Prioritize: reach unpowered plant_locs
        unpowered_plants = [(px, py) for px, py in plant_locs
                            if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Also wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 200)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unconnected plant_locs (not yet placed but planned)
        unconnected = [(px, py) for px, py in plant_locs
                       if ib(px, py) and not bool(near_power[py, px])]
        if unconnected:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in unconnected)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid — reactive, extend from existing roads ----
    # Build roads on a 6-tile grid, preferring powered areas
    road_targets = []
    for gy in range(8, 95, 6):
        for gx in range(8, 115, 6):
            road_targets.append((gx, gy))

    # Find road targets that are unpaved and near power
    unpaved = [(gx, gy) for gx, gy in road_targets
               if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if unpaved:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:3, :] = False
        road_cand[WORLD_H-3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W-3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_subset = unpaved[:30]
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_subset)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Directly place at unpaved target if empty
            for gx, gy in unpaved[:10]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement with reactive mix ----
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer near roads, but spread across map
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs_arr))

        # Spread score: distance from nearest existing zone (want spread)
        if total_zones > 0:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride2 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride2):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Want zones near roads, slightly spread from each other
            score = road_dist * 1.5 - zone_dist * 0.3
        else:
            # Bootstrap near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        tool = pick_tool()
        # Cycle with some variation per step
        off = (step * 17 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services (reactive to population) ----
    if pop > 100:
        fire_locs = [(fx, fy) for fy in range(15, 90, 10) for fx in range(15, 110, 10)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_locs = [(px2, py2) for py2 in range(18, 88, 12) for px2 in range(18, 108, 12)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_locs = [(px3, py3) for py3 in range(14, 88, 8) for px3 in range(14, 108, 8)]
        for pkx, pky in park_locs:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        stadium_locs = [(25, 20), (95, 20), (25, 78), (95, 78),
                        (60, 12), (60, 88), (12, 50), (108, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(60, 50), (20, 50), (100, 50), (60, 20), (60, 80),
                     (40, 35), (80, 35), (40, 65), (80, 65)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-5), min(WORLD_W, nx+6)
                y0, y1 = max(0, ny-5), min(WORLD_H, ny+6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (75, 8), (55, 90), (75, 90),
                        (8, 35), (110, 35), (8, 65), (110, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from any plant ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = (step * 7) % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (4, 4), (-4, 4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from plant ----
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads around center
    for d in range(-6, 7):
        actions.append((Tool.ROAD, cx - 1, cy + d))
        actions.append((Tool.ROAD, cx + 1, cy + d))
        actions.append((Tool.ROAD, cx + d, cy - 1))
        actions.append((Tool.ROAD, cx + d, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID ----
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 20, 33, 46, 59, 72, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 6
        if pop < 400:   return 10
        if pop < 800:   return 16
        if pop < 1500:  return 24
        if pop < 3000:  return 35
        if pop < 6000:  return 45
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- POWER/ROAD COVERAGE MAPS ----
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    nbr_power = dilate(wm | pm, 6)
    nbr_road = dilate(rm, 3)
    zone_tiles = resm | comm | indm

    # ---- TOOL SELECTION ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- ZONE CLEAR CHECK ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: POWER PLANTS for active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES for active hoods ----
    spine_range = 9
    hood_idx = step % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_idx + i_h) % len(active_hoods)]

        # Vertical wire spine at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal wire spine at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)
        break  # One hood per step

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            # Horizontal connection (same row, adjacent cols)
            if hy1 == hy2 and abs(hx2 - hx1) == 14 and hx2 > hx1:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical connection (same col, adjacent rows)
            if hx1 == hx2 and abs(hy2 - hy1) == 13 and hy2 > hy1:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)
        break

    # ---- PHASE 4: ROADS along wire spines ----
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx]

    # Roads flanking vertical spine
    for rx in [hx - 1, hx + 1]:
        if not ib(rx, hy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                return (Tool.ROAD, rx, ry)

    # Roads flanking horizontal spine
    for ry2 in [hy - 1, hy + 1]:
        if not ib(hx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 6: EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        for fx in range(10, WORLD_W, 15):
            for fy in range(10, WORLD_H, 15):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        for px2 in range(15, WORLD_W, 18):
            for py2 in range(15, WORLD_H, 18):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for sx in range(20, WORLD_W, 25):
            for sy in range(20, WORLD_H, 25):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaport_spots = [(8, 90), (112, 90), (8, 10), (112, 10),
                         (60, 95), (60, 5), (30, 95), (90, 95)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        nuke_spots = [(20, 25), (100, 25), (20, 75), (100, 75),
                      (60, 10), (60, 90), (5, 50), (115, 50)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        airport_spots = [(20, 6), (50, 6), (80, 6), (20, 94), (50, 94), (80, 94)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks
    if pop > 100 and step % 4 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 19 + pop) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 12):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + initial road grid"""
    actions = []
    # Two coal plants near center-left and center-right
    plants = [(28, 50), (92, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire horizontally connecting both plants through center
    for x in range(29, 92):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spurs from center horizontal
    for y in range(44, 57):
        actions.append((Tool.WIRE, 60, y))
    # Initial road grid near center
    for x in range(50, 72):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(46, 55):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 71, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- Desired zone ratio picker ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Check if a 3x3 area is clear for zone placement ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- Compute neighbor masks efficiently ----
    # Road neighbor within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Wire/power neighbor within 5 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- STEP 1: Ensure coal plants exist in each quadrant ----
    quadrants = [
        (30, 25), (90, 25),
        (30, 75), (90, 75),
        (60, 50),  # center
    ]
    for (qx, qy) in quadrants:
        x0, x1 = max(0, qx - 12), min(WORLD_W, qx + 13)
        y0, y1 = max(0, qy - 12), min(WORLD_H, qy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at or near quadrant center
            for r in range(0, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = qx + dx, qy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- STEP 2: Extend wire from existing wire/plant to unconnected regions ----
    # Find frontiers: empty tiles adjacent to wire/plant
    wire_or_plant = wm | pm
    # Expand wire frontiers - grow wire outward prioritizing direction toward
    # areas lacking power
    wire_ys, wire_xs = np.where(wire_or_plant)
    if len(wire_xs) > 0:
        # Find largest cluster of empty tiles without power
        unpowered_empty = em & ~nbr_power
        unp_ys, unp_xs = np.where(unpowered_empty)
        if len(unp_xs) > 0:
            # Find centroid of unpowered area
            target_x = int(np.mean(unp_xs))
            target_y = int(np.mean(unp_ys))
            # Find wire tile closest to target
            dists = np.abs(wire_xs - target_x) + np.abs(wire_ys - target_y)
            best_idx = np.argmin(dists)
            wx, wy = int(wire_xs[best_idx]), int(wire_ys[best_idx])
            # Step toward target
            dx = 0 if target_x == wx else (1 if target_x > wx else -1)
            dy = 0 if target_y == wy else (1 if target_y > wy else -1)
            # Try horizontal then vertical
            for ddx, ddy in [(dx, 0), (0, dy), (dx, dy)]:
                if ddx == 0 and ddy == 0:
                    continue
                nx, ny = wx + ddx, wy + ddy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- STEP 3: Extend road network from existing roads ----
    # Goal: roads should cover all powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        # Find powered areas without nearby roads
        needs_road = nbr_power & ~nbr_road & em
        needs_ys, needs_xs = np.where(needs_road)
        if len(needs_xs) > 0:
            target_rx = int(np.mean(needs_xs))
            target_ry = int(np.mean(needs_ys))
            # Find road tile closest to target
            dists = np.abs(road_xs - target_rx) + np.abs(road_ys - target_ry)
            best_idx = np.argmin(dists)
            rox, roy = int(road_xs[best_idx]), int(road_ys[best_idx])
            dx = 0 if target_rx == rox else (1 if target_rx > rox else -1)
            dy = 0 if target_ry == roy else (1 if target_ry > roy else -1)
            for ddx, ddy in [(dx, 0), (0, dy)]:
                if ddx == 0 and ddy == 0:
                    continue
                nx, ny = rox + ddx, roy + ddy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)
        # Also extend roads along corridors
        # Build road grid: horizontal every 6 rows, vertical every 8 cols
        road_rows = list(range(10, WORLD_H - 5, 8))
        road_cols = list(range(10, WORLD_W - 5, 8))
        # Pick a road row that has power but incomplete road coverage
        for rr in road_rows:
            if not bool(np.any(nbr_power[rr, :])):
                continue
            # Find gaps in this row
            for cx in range(2, WORLD_W - 2):
                if bool(em[rr, cx]) and bool(nbr_power[rr, cx]) and not bool(rm[rr, cx]):
                    # Check adjacent road exists
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, rr) and bool(rm[rr, ax]):
                            return (Tool.ROAD, cx, rr)
        for rc in road_cols:
            if not bool(np.any(nbr_power[:, rc])):
                continue
            for cy in range(2, WORLD_H - 2):
                if bool(em[cy, rc]) and bool(nbr_power[cy, rc]) and not bool(rm[cy, rc]):
                    for ady in [-1, 1]:
                        ay = cy + ady
                        if ib(rc, ay) and bool(rm[ay, rc]):
                            return (Tool.ROAD, rc, cy)

    # ---- STEP 4: Place zones where powered + road-adjacent ----
    cand_mask = em & nbr_road & nbr_power
    # Buffer from edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()
        # Score by: close to roads + close to power + dense clustering
        # Compute density: number of zones in 9x9 neighborhood (sparse = prefer)
        zone_tiles_mask = resm | comm | indm
        zone_density = np.zeros((WORLD_H, WORLD_W), dtype=np.float32)
        for dy in range(-4, 5):
            for dx in range(-4, 5):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                zone_density[r0:r1, c0:c1] += zone_tiles_mask[sr0:sr1, sc0:sc1].astype(np.float32)

        cand_density = zone_density[cys, cxs]
        # Prefer areas with some existing zones (clustering) but not overcrowded
        # Score: prefer moderate density (2-8 neighbors)
        scores = -np.abs(cand_density - 5.0)
        order = np.argsort(-scores)  # higher score first

        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- STEP 5: Civic services based on population ----
    if pop > 80:
        fire_locs = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for (sx, sy) in fire_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_locs = [
            (40, 35), (80, 35),
            (20, 60), (60, 60), (100, 60),
            (40, 85), (80, 85),
        ]
        for (sx, sy) in police_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600 and step % 7 == 0:
        park_ys2, park_xs2 = np.where(em & nbr_road & nbr_power)
        if len(park_xs2) > 0:
            idx = (step * 31) % len(park_xs2)
            return (Tool.PARK, int(park_xs2[idx]), int(park_ys2[idx]))

    if pop > 1200:
        stadiums = [(45, 45), (75, 45), (45, 65), (75, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2500:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(55, 8), (65, 8), (55, 92), (65, 92)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- FALLBACK: grow wire outward from any wire tile ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        k = (step * 13) % len(wire_xs2)
        for i in range(min(len(wire_xs2), 60)):
            idx = (k + i) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[idx]), int(wire_ys2[idx])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2 + dx, wy2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- FALLBACK: grow road from existing road ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k = (step * 11) % len(road_xs2)
        for i in range(min(len(road_xs2), 60)):
            idx = (k + i * 3) % len(road_xs2)
            rx2, ry2 = int(road_xs2[idx]), int(road_ys2[idx])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_power[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    return None

