def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% residential, 25% commercial, 25% industrial
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.astype(bool).copy()
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # ---- PHASE 1: Reactive wire extension ----
    # Extend wire grid from existing wires/plants outward
    # Wire rows and cols (every 10 tiles for sparser but cleaner grid)
    wire_rows = list(range(20, 90, 10))
    wire_cols = list(range(15, 110, 10))

    # Find any existing wire/plant cells and grow outward
    # Strategy: on even steps, try to extend wires along wire_rows
    # on odd steps, extend along wire_cols
    if step % 4 in (0, 1):
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            # Find leftmost gap adjacent to power on this row
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    lp = bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])
                    rp = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    # Also check vertical adjacency
                    up = wr > 0 and (bool(wm[wr-1, wx]) or bool(pm[wr-1, wx]))
                    dn = wr < WORLD_H-1 and (bool(wm[wr+1, wx]) or bool(pm[wr+1, wx]))
                    if lp or rp or up or dn:
                        return (Tool.WIRE, wx, wr)

    if step % 4 in (2, 3):
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = bool(wm[wy-1, wc]) or bool(pm[wy-1, wc])
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    lp = wc > 0 and (bool(wm[wy, wc-1]) or bool(pm[wy, wc-1]))
                    rp = wc < WORLD_W-1 and (bool(wm[wy, wc+1]) or bool(pm[wy, wc+1]))
                    if up or dn or lp or rp:
                        return (Tool.WIRE, wc, wy)

    # ---- PHASE 2: Reactive road extension ----
    # Roads run parallel to wire rows/cols (offset +1)
    road_rows = [wr + 1 for wr in wire_rows]
    road_cols = [wc + 1 for wc in wire_cols]

    # Extend roads along road_rows wherever there's adjacent power
    if step % 6 in (0, 2, 4):
        for rr in road_rows:
            if rr >= WORLD_H - 1:
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    adj_road = ((rx > 0 and bool(rm[rr, rx-1])) or
                                (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or
                                (bool(rm[rr-1, rx]) if rr > 0 else False) or
                                (bool(rm[rr+1, rx]) if rr < WORLD_H-1 else False))
                    if adj_road and bool(near_power[rr, rx]):
                        return (Tool.ROAD, rx, rr)

    if step % 6 in (1, 3, 5):
        for rc in road_cols:
            if rc >= WORLD_W - 1:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    adj_road = ((ry > 0 and bool(rm[ry-1, rc])) or
                                (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or
                                (bool(rm[ry, rc-1]) if rc > 0 else False) or
                                (bool(rm[ry, rc+1]) if rc < WORLD_W-1 else False))
                    if adj_road and bool(near_power[ry, rc]):
                        return (Tool.ROAD, rc, ry)

    # ---- PHASE 3: New power plants for expanding grid ----
    # If large areas have roads but no power, add coal plants
    unpowered_road = rm & ~near_power
    if np.any(unpowered_road):
        uys, uxs = np.where(unpowered_road)
        if len(uxs) > 0:
            # Pick centroid of unpowered road area
            cx = int(np.mean(uxs))
            cy = int(np.mean(uys))
            # Find nearest empty spot for a plant
            for r in range(1, 25):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 4: Civic buildings ----
    if pop > 100 and step % 15 == 3:
        for sy in range(12, 90, 18):
            for sx in range(12, 110, 22):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 300 and step % 17 == 5:
        for sy in range(15, 90, 20):
            for sx in range(15, 110, 25):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 600 and step % 20 == 7:
        for sx, sy in [(35, 35), (85, 35), (35, 65), (85, 65), (60, 50), (20, 50), (100, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000 and step % 25 == 9:
        for nx2, ny2 in [(10, 50), (110, 50), (60, 10), (60, 90), (10, 10), (110, 90)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000 and step % 30 == 11:
        for sx, sy in [(5, 90), (110, 90), (5, 10), (110, 10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000 and step % 40 == 13:
        for sx, sy in [(45, 5), (75, 5), (45, 92), (75, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 5: Zone placement (closed-loop) ----
    # Build candidate mask: must be empty, near road, near power
    # Exclude wire row/col corridors to avoid blocking infrastructure
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False
    for rr in road_rows:
        cand_mask[max(0, rr-1):min(WORLD_H, rr+2), :] = False
    for rc in road_cols:
        cand_mask[:, max(0, rc-1):min(WORLD_W, rc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()
        # Sort by distance from center of existing zones (reactive to actual city shape)
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            cz_x = float(np.mean(zone_xs))
            cz_y = float(np.mean(zone_ys))
        else:
            cz_x, cz_y = 60.0, 50.0
        # Prefer spots near existing zones but with some spread
        dists = np.abs(cxs - cz_x).astype(float) + np.abs(cys - cz_y).astype(float)
        # Add slight randomization using step+pop as seed to avoid always same spot
        noise = ((cxs * 7 + cys * 13 + step * 3) % 20).astype(float)
        score = dists + noise * 0.5
        order = np.argsort(score)
        for i in range(min(len(order), 600)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: Extend roads from any existing road into powered empty areas ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        sk = (step * 17 + pop * 3) % len(road_xs_arr)
        for off in range(min(len(road_xs_arr), 400)):
            k = (sk + off * 11) % len(road_xs_arr)
            rx2, ry2 = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: Extend any existing wire outward ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        sk2 = (step * 23 + pop * 5) % len(wire_xs_arr)
        for off in range(min(len(wire_xs_arr), 200)):
            k = (sk2 + off * 9) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- Fallback: place a new coal plant somewhere empty ----
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        # Far from existing plants
        px0, py0 = int(plant_xs[0]), int(plant_ys[0])
        for r in range(20, 60, 5):
            for dy in [-r, r]:
                for dx in range(-r, r+1):
                    nx, ny = px0 + dx, py0 + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            for dx in [-r, r]:
                for dy in range(-r, r+1):
                    nx, ny = px0 + dx, py0 + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # Parks as last resort for land value
    if step % 3 == 0:
        park_ys, park_xs = np.where(em & near_road)
        if len(park_xs) > 0:
            idx = (step * 41) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    return None

