            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (closed-loop primary action) ----
    # Candidate: empty, near road, near power
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    # Exclude infrastructure corridors
    all_infra_rows = wire_rows + road_rows
    all_infra_cols = wire_cols + road_cols
    for wr in all_infra_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr - 1):min(WORLD_H, wr + 2), :] = False
    for wc in all_infra_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc - 1):min(WORLD_W, wc + 2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Two neighborhood approach: west cluster and east cluster
        # Grow them based on population
        if pop < 100:
            # Start: two small neighborhoods
            active_centers = [
                (25, 50), (95, 50),
                (25, 40), (25, 60), (95, 40), (95, 60),
            ]
        elif pop < 400:
            # Medium: expand both neighborhoods
            active_centers = []
            for row in range(5):
                for col in range(3):
                    cx = 15 + col * 12
                    cy = 30 + row * 10
                    active_centers.append((cx, cy))
            for row in range(5):
                for col in range(3):
                    cx = 85 + col * 12
                    cy = 30 + row * 10
                    active_centers.append((cx, cy))
        elif pop < 1000:
            # Large: 3 neighborhoods including center
            active_centers = []
            for row in range(7):
                for col in range(4):
                    cx = 12 + col * 10
                    cy = 15 + row * 11
                    active_centers.append((cx, cy))
            for row in range(7):
                for col in range(3):
                    cx = 50 + col * 10
                    cy = 15 + row * 11
                    active_centers.append((cx, cy))
            for row in range(7):
                for col in range(4):
                    cx = 85 + col * 10
                    cy = 15 + row * 11
                    active_centers.append((cx, cy))
        else:
            # Full coverage
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 1000)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road near power
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plant, wire spine, and initial roads."""
    placements = []
    # Primary plant at center
    placements.append((Tool.COALPOWER, 60, 50))
    # Wire spine going left and right from plant
    for x in range(55, 60):
        placements.append((Tool.WIRE, x, 50))
    for x in range(61, 66):
        placements.append((Tool.WIRE, x, 50))
    # Initial roads above and below
    placements.append((Tool.ROAD, 60, 47))
    placements.append((Tool.ROAD, 60, 53))
    placements.append((Tool.ROAD, 57, 50))
    placements.append((Tool.ROAD, 63, 50))
    return placements[:20]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    powered_map = wm | pm

    # Dilate road map (radius 3)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            if abs(dx) + abs(dy) > 4:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Dilate power map (radius 6)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            if abs(dx) + abs(dy) > 8:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= powered_map[sr0:sr1, sc0:sc1]

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    plant_count = int(np.sum(pm))
    zone_tiles = resm | comm | indm

    # Cluster grid: 6x5 covering the map densely
    clusters = []
    for cx in [15, 32, 49, 66, 83, 100]:
        for cy in [12, 28, 44, 60, 76, 92]:
            clusters.append((cx, cy))

    # Activate more clusters as city grows
    num_active = max(1, min(len(clusters), 1 + pop // 100 + total_zones // 6))
    num_active = min(num_active, len(clusters))
    # Prioritize clusters near existing infrastructure
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        cx_plant = int(np.mean(plant_xs))
        cy_plant = int(np.mean(plant_ys))
        clusters.sort(key=lambda c: abs(c[0]-cx_plant) + abs(c[1]-cy_plant))
    active_clusters = clusters[:num_active]

    def pick_zone_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Need industrial base first for commercial demand
        if ind_count < 4 or ir < 0.18:
            return Tool.INDUSTRIAL
        if com_count < 4 or cr < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === STEP 1: Ensure each active cluster has a power plant nearby ===
    for cx, cy in active_clusters:
        x0 = max(0, cx - 8); x1 = min(WORLD_W, cx + 9)
        y0 = max(0, cy - 8); y1 = min(WORLD_H, cy + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 12):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        px, py = cx + dx, cy + dy
                        if not in_bounds(px, py):
                            continue
                        ok = True
                        for ddy in range(-1, 2):
                            for ddx in range(-1, 2):
                                tx, ty = px + ddx, py + ddy
                                if not in_bounds(tx, ty):
                                    ok = False; break
                                if not bool(em[ty, tx]) and not bool(wm[ty, tx]) and not bool(rm[ty, tx]):
                                    ok = False; break
                            if not ok:
                                break
                        if ok:
                            return (Tool.COALPOWER, px, py)
                if placed:
                    break

    if len(plant_xs) == 0:
        return (Tool.COALPOWER, 60, 50)

    # === STEP 2: Connect power via wire from nearest powered cell ===
    for cx, cy in active_clusters:
        x0 = max(0, cx - 5); x1 = min(WORLD_W, cx + 6)
        y0 = max(0, cy - 5); y1 = min(WORLD_H, cy + 6)
        if not np.any(powered_map[y0:y1, x0:x1]):
            all_py, all_px = np.where(powered_map)
            if len(all_px) == 0:
                continue
            dists = np.abs(all_px - cx) + np.abs(all_py - cy)
            idx = int(np.argmin(dists))
            wx, wy = int(all_px[idx]), int(all_py[idx])
            dx = cx - wx; dy = cy - wy
            # Walk horizontally first, then vertically
            if abs(dx) >= abs(dy):
                nx, ny = wx + (1 if dx > 0 else -1), wy
            else:
                nx, ny = wx, wy + (1 if dy > 0 else -1)
            if in_bounds(nx, ny) and not bool(pm[ny, nx]):
                if bool(em[ny, nx]) or bool(wm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # === STEP 3: Build road grid reactively ===
    # Roads run perpendicular to wire; extend existing roads outward
    for ci, (cx, cy) in enumerate(active_clusters):
        extent = min(20, 5 + pop // 60 + ci // 2)
        top = max(2, cy - extent)
        bot = min(WORLD_H - 3, cy + extent)
        left = max(2, cx - extent)
        right = min(WORLD_W - 3, cx + extent)

        # Horizontal road rows every 4 rows
        for row_off in range(-extent, extent + 1, 4):
            hry = cy + row_off
            if not (0 <= hry < WORLD_H):
                continue
            # Extend existing road segments or start new ones near power
            for hx in range(left, right + 1):
                if bool(em[hry, hx]) and not bool(pm[hry, hx]) and bool(nbr_power[hry, hx]):
                    # Check if adjacent to existing road
                    adj_road = False
                    for ddx in [-1, 1]:
                        nx2 = hx + ddx
                        if in_bounds(nx2, hry) and bool(rm[hry, nx2]):
                            adj_road = True; break
                    if adj_road or (hx == cx and bool(nbr_power[hry, hx])):
                        return (Tool.ROAD, hx, hry)

        # Vertical road columns every 4 cols
        for col_off in range(-extent, extent + 1, 4):
            hcx = cx + col_off
            if not (0 <= hcx < WORLD_W):
                continue
            for ry in range(top, bot + 1):
                if bool(em[ry, hcx]) and not bool(pm[ry, hcx]) and bool(nbr_power[ry, hcx]):
                    adj_road = False
                    for ddy in [-1, 1]:
                        ny2 = ry + ddy
                        if in_bounds(hcx, ny2) and bool(rm[ny2, hcx]):
                            adj_road = True; break
                    if adj_road or (ry == cy and bool(nbr_power[ry, hcx])):
                        return (Tool.ROAD, hcx, ry)

    # === STEP 4: Place zones near roads and power ===
    def zone_clear(zx, zy):
        x0 = max(0, zx - 1); x1 = min(WORLD_W, zx + 2)
        y0 = max(0, zy - 1); y1 = min(WORLD_H, zy + 2)
        if x1 - x0 < 3 or y1 - y0 < 3:
            return False
        patch = em[y0:y1, x0:x1] | zone_tiles[y0:y1, x0:x1]
        return bool(np.all(patch))

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        scores = np.full(len(cxs_arr), 999999.0)
        for cx2, cy2 in active_clusters:
            d = np.abs(cxs_arr - cx2) + np.abs(cys_arr - cy2)
            scores = np.minimum(scores, d.astype(float))
        order = np.argsort(scores)
        tool = pick_zone_tool()
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 100)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === STEP 5: Extend wire from existing powered cells ===
    wire_ys2, wire_xs2 = np.where(powered_map)
    if len(wire_xs2) > 0:
        # Try to reach unserved clusters first
        for cx2, cy2 in active_clusters:
            x0 = max(0, cx2 - 5); x1 = min(WORLD_W, cx2 + 6)
            y0 = max(0, cy2 - 5); y1 = min(WORLD_H, cy2 + 6)
            if np.any(powered_map[y0:y1, x0:x1]):
                continue
            dists2 = np.abs(wire_xs2 - cx2) + np.abs(wire_ys2 - cy2)
            idx2 = int(np.argmin(dists2))
            wx2, wy2 = int(wire_xs2[idx2]), int(wire_ys2[idx2])
            ddx = cx2 - wx2; ddy = cy2 - wy2
            if abs(ddx) >= abs(ddy):
                nnx, nny = wx2 + (1 if ddx > 0 else -1), wy2
            else:
                nnx, nny = wx2, wy2 + (1 if ddy > 0 else -1)
            if in_bounds(nnx, nny) and not bool(pm[nny, nnx]):
                if bool(em[nny, nnx]) or bool(wm[nny, nnx]):
                    return (Tool.WIRE, nnx, nny)

        # General wire extension
        step_k = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 40)):
            k = (step_k + offset * 7) % len(wire_xs2)
            wx3, wy3 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === STEP 6: Extend roads from existing roads near power ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k2 = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k2 + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === STEP 7: Civic services ===
    if pop > 150:
        fire_positions = [
            (60, 44), (60, 56), (54, 50), (66, 50),
            (50, 38), (70, 38), (50, 62), (70, 62),
            (40, 50), (80, 50), (60, 30), (60, 70),
            (35, 35), (85, 35), (35, 65), (85, 65),
        ]
        for fsx, fsy in fire_positions:
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]) and bool(nbr_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        police_positions = [
            (55, 44), (65, 56), (75, 45), (45, 55),
            (55, 63), (65, 37), (88, 35), (32, 65),
            (22, 45), (98, 55), (60, 22), (60, 78),
        ]
        for psx, psy in police_positions:
            if in_bounds(psx, psy) and bool(em[psy, psx]) and bool(nbr_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 800:
        for ssx, ssy in [(90, 50), (30, 50), (60, 18), (60, 82), (90, 25), (30, 75)]:
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    if pop > 1200:
        for spx, spy in [(110, 50), (10, 50), (60, 5), (60, 94)]:
            if in_bounds(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Additional coal plants as needed
    if plant_count < 2 + pop // 500:
        candidate_plants = [
            (80, 50), (40, 50), (60, 30), (60, 70),
            (80, 30), (40, 30), (80, 70), (40, 70),
            (100, 50), (20, 50), (60, 15), (60, 85),
        ]
        for cp_x, cp_y in candidate_plants:
            if not in_bounds(cp_x, cp_y):
                continue
            x0 = max(0, cp_x - 9); x1 = min(WORLD_W, cp_x + 10)
            y0 = max(0, cp_y - 9); y1 = min(WORLD_H, cp_y + 10)
            if not np.any(pm[y0:y1, x0:x1]) and bool(em[cp_y, cp_x]):
                return (Tool.COALPOWER, cp_x, cp_y)

    if pop > 600 and funds > 6000:
        nuclear_positions = [
            (100, 20), (20, 20), (100, 80), (20, 80),
            (60, 8), (60, 92), (110, 50), (10, 50)
        ]
        for nsx, nsy in nuclear_positions:
            if not in_bounds(nsx, nsy):
                continue
            x0 = max(0, nsx - 9); x1 = min(WORLD_W, nsx + 10)
            y0 = max(0, nsy - 9); y1 = min(WORLD_H, nsy + 10)
            if not np.any(pm[y0:y1, x0:x1]) and bool(em[nsy, nsx]):
                return (Tool.NUCLEARPOWER, nsx, nsy)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + initial roads."""
    actions = []
    # Central power plant at (60, 50)
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(48, 73):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(43, 58):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking wire spines
    for x in range(48, 73):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(43, 58):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood grid - denser than parent for more coverage
    all_hoods = []
    for hy in range(12, 98, 12):
        for hx in range(12, 118, 12):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 14
        if pop < 1000:  return 22
        if pop < 2000:  return 35
        if pop < 4000:  return 50
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANTS near active hoods ----
    # Place coal plant if no plant nearby; prefer nuclear when funded
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find nearest empty spot to center
                for r in range(10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                # Prefer nuclear at pop > 600
                                tool = Tool.NUCLEARPOWER if (pop > 600 and funds > 5000) else Tool.COALPOWER
                                return (tool, nx, ny)

    # ---- PHASE 2: EXTEND WIRE SPINES reactively ----
    # For each active hood, grow wire toward it from nearest wire/plant
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 10)
        spine_bot   = min(WORLD_H - 3, hy + 10)
        spine_left  = max(2, hx - 10)
        spine_right = min(WORLD_W - 3, hx + 10)

        # Vertical wire spine at hx
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]
        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)
        if col_wire:
            min_wr, max_wr = min(col_wire), max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal wire spine at hy
        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]
        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)
        if row_wire:
            min_wc, max_wc = min(row_wire), max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: CONNECT WIRE SPINES between hoods ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 20:
                continue
            if abs(hy1 - hy2) <= 3 and hx2 > hx1:
                mid_y = (hy1 + hy2) // 2
                for cx in range(hx1 + 1, hx2):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
            if abs(hx1 - hx2) <= 3 and hy2 > hy1:
                mid_x = (hx1 + hx2) // 2
                for cy in range(hy1 + 1, hy2):
                    if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                        return (Tool.WIRE, mid_x, cy)

    # ---- PHASE 4: ROAD GRID - build roads adjacent to wire spines ----
    # Key change: build roads at offset +/-3 from wire spine (wider separation)
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 3, hx + 3]:
            if not ib(rx, hy) or not col_wire:
                continue
            cyc = step % 5
            for wr in col_wire[cyc::5]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)
        # Also connect roads horizontally
        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 3, hy + 3]:
            if not ib(hx, ry) or not row_wire:
                continue
            cyc = (step + 2) % 5
            for wc in row_wire[cyc::5]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus: prefer spots near existing zones
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                # Stronger cluster bias than parent
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 11 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS from existing network into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(10, 98, 14)
                     for fx in range(10, 118, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(15, 95, 15)
                       for px2 in range(15, 115, 15)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & near_road & near_power)
        if len(park_cands_x) > 0:
            idx = (step * 19) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 4), min(WORLD_W, npx + 5)
            y0b, y1b = max(0, npy - 4), min(WORLD_H, npy + 5)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- WIRE UNPOWERED ZONES ----
    unpowered_zones = zone_tiles & ~near_power
    uz_ys, uz_xs = np.where(unpowered_zones)
    if len(uz_xs) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = int(np.argmin(dists))
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy), (bwx + dx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants at center-left and center-right with wire+road spines."""
    actions = []
    # Two plants: left cluster and right cluster
    for cx, cy in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Vertical wire spine
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Horizontal wire arm
        for dx in range(-5, 6):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        # Roads flanking the vertical spine
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 2, cy + dy))
            actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid of neighborhoods: denser than parent, 2 columns of 6 clusters each
    # Left cluster centered at x=30, right at x=90, rows at y=15,30,45,60,75,90
    # Plus middle column at x=60
    nh_cols = [15, 30, 45, 60, 75, 90, 105]
    nh_rows = [15, 30, 45, 60, 75, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 300:   return 14
        if pop < 600:   return 20
        if pop < 1200:  return 28
        if pop < 2500:  return 36
        if pop < 5000:  return 42
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        # Shifted mix: more commercial and industrial
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(14):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    spine_range = 12

    # ---- PHASE 2: WIRE SPINES (cross pattern: vertical + horizontal) ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in [(hx1 + 15, hy1), (hx1, hy1 + 15)]:
            if (hx2, hy2) in hood_set:
                if hx2 == hx1:
                    for cy2 in range(hy1 + 1, hy2):
                        if not ib(hx1, cy2): continue
                        if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]): continue
                        for ady in [-1, 1]:
                            ay = cy2 + ady
                            if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                                return (Tool.WIRE, hx1, cy2)
                else:
                    for cx2 in range(hx1 + 1, hx2):
                        if not ib(cx2, hy1): continue
                        if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]) or not bool(em[hy1, cx2]): continue
                        for adx in [-1, 1]:
                            ax = cx2 + adx
                            if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                                return (Tool.WIRE, cx2, hy1)

    # ---- PHASE 4: ROADS flanking wire spines (both sides of vertical + horizontal) ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 3) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Roads flanking vertical spine
        for rx in [hx - 2, hx + 2]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal spine
        for ry2 in [hy - 2, hy + 2]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 2)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (wire or plant within 6)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 6: EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES based on population ----
    if pop > 80:
        fire_spots = [
            (10, 15), (35, 15), (60, 15), (85, 15), (110, 15),
            (10, 40), (35, 40), (60, 40), (85, 40), (110, 40),
            (10, 65), (35, 65), (60, 65), (85, 65), (110, 65),
            (10, 88), (35, 88), (60, 88), (85, 88), (110, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (20, 22), (50, 22), (80, 22), (110, 22),
            (20, 50), (50, 50), (80, 50), (110, 50),
            (20, 75), (50, 75), (80, 75), (110, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (90, 30), (30, 70), (90, 70),
            (60, 10), (60, 88), (10, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (55, 5), (65, 95), (5, 48), (115, 52),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(48, 5), (72, 5), (48, 94), (72, 94), (5, 46), (114, 54)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant near uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: coal plant + initial wire spine seed + road seeds"""
    placements = []
    # Primary coal plant at center-ish
    placements.append((Tool.COALPOWER, 58, 50))
    # Wire spine going up and down from plant
    for dy in range(-3, 4):
        placements.append((Tool.WIRE, 60, 50 + dy))
    # Seed roads on both sides
    for dy in range(-3, 4):
        placements.append((Tool.ROAD, 59, 50 + dy))
        placements.append((Tool.ROAD, 61, 50 + dy))
    return placements


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Phase tracking in state ----
    if 'phase' not in state:
        state['phase'] = 'power'
        state['second_plant_done'] = False
        state['third_plant_done'] = False

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Find existing plants ----
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0
    px = int(plant_xs[0]) if has_plant else 58
    py = int(plant_ys[0]) if has_plant else 50

    # ---- Ensure primary plant exists ----
    if not has_plant:
        return (Tool.COALPOWER, 58, 50)

    # ---- Second power plant ----
    if not state['second_plant_done'] and (total_zones > 6 or obs.city_pop > 150):
        p2x, p2y = px + 22, py
        if in_bounds(p2x, p2y):
            nearby = any(
                in_bounds(p2x+dx, p2y+dy) and bool(pm[p2y+dy, p2x+dx])
                for dy in range(-6,7) for dx in range(-6,7) if in_bounds(p2x+dx, p2y+dy)
            )
            if not nearby:
                if bool(em[p2y, p2x]):
                    state['second_plant_done'] = True
                    return (Tool.COALPOWER, p2x, p2y)
                # Wire bridge to second plant location
                for wc in range(px+3, p2x):
                    if in_bounds(wc, py) and (bool(em[py, wc]) or bool(wm[py, wc])) and not bool(pm[py, wc]):
                        return (Tool.WIRE, wc, py)

    # ---- Third power plant ----
    if state['second_plant_done'] and not state['third_plant_done'] and (total_zones > 20 or obs.city_pop > 600):
        p3x, p3y = px + 44, py
        if in_bounds(p3x, p3y):
            nearby = any(
                in_bounds(p3x+dx, p3y+dy) and bool(pm[p3y+dy, p3x+dx])
                for dy in range(-6,7) for dx in range(-6,7) if in_bounds(p3x+dx, p3y+dy)
            )
            if not nearby:
                if bool(em[p3y, p3x]):
                    state['third_plant_done'] = True
                    return (Tool.COALPOWER, p3x, p3y)
                for wc in range(px+3, p3x):
                    if in_bounds(wc, py) and (bool(em[py, wc]) or bool(wm[py, wc])) and not bool(pm[py, wc]):
                        return (Tool.WIRE, wc, py)

    # ---- Dynamic wire spine: grow wire from existing wire toward needed coverage ----
    # Compute how far we want the spine to extend based on population
    pop_factor = min(35, obs.city_pop // 12)
    spine_top = max(3, py - 16 - pop_factor)
    spine_bot = min(WORLD_H - 4, py + 16 + pop_factor)

    # Build vertical wire spines near each plant
    all_plant_xs = list(plant_xs)
    all_plant_ys = list(plant_ys)

    for i in range(len(all_plant_xs)):
        ppx = int(all_plant_xs[i])
        ppy = int(all_plant_ys[i])
        wire_col = ppx + 2

        # Gather existing wire in this column
        wire_in_col = [r for r in range(WORLD_H)
                       if in_bounds(wire_col, r) and bool(wm[r, wire_col])]

        if not wire_in_col:
            # Seed wire adjacent to plant
            for dy in range(-2, 3):
                ny = ppy + dy
                if in_bounds(wire_col, ny) and (bool(em[ny, wire_col]) or bool(wm[ny, wire_col])) and not bool(pm[ny, wire_col]):
                    return (Tool.WIRE, wire_col, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)

        # Roads flanking this wire spine
        road_col_l = wire_col - 1
        road_col_r = wire_col + 1
        if wire_in_col:
            # Alternate which rows we fill roads on each step
            stride_rows = wire_in_col[::1]
            offset = (obs.step * 3 + i * 17) % max(len(stride_rows), 1)
            for idx in range(min(len(stride_rows), 5)):
                wr = stride_rows[(offset + idx) % len(stride_rows)]
                if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]) and not bool(pm[wr, road_col_l]):
                    return (Tool.ROAD, road_col_l, wr)
                if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]) and not bool(pm[wr, road_col_r]):
                    return (Tool.ROAD, road_col_r, wr)

    # ---- Proximity masks for zone placement ----
    # Road neighbors (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbors (within 6 tiles of wire or plant)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # ---- Place zones near roads and power ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Distance from primary plant wire spine, prefer closer
        wire_col_primary = px + 2
        dists = np.abs(cxs - wire_col_primary) + np.abs(cys - py) // 2
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # ---- Extend roads near wire to reach more areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 25)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- Services at population thresholds ----
    if obs.city_pop > 200:
        for fpos in [(px - 12, py - 10), (px + 12, py - 10), (px + 12, py + 10), (px - 12, py + 10)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 400:
        for ppos in [(px - 8, py + 12), (px + 8, py + 12), (px + 8, py - 12), (px - 8, py - 12)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 800:
        for spos in [(px + 30, py + 15), (px - 30, py + 15)]:
            ssx, ssy = spos
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    # ---- Expand wire laterally from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a row + wire grid + initial roads"""
    actions = []
    # 3 plants spread horizontally at mid-height
    plants = [(20, 50), (60, 50), (100, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire at y=50 connecting all plants
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires at plant columns
    for y in range(1, 99):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 100, y))
    # Roads flanking horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire corridors (5 horizontal rows + 5 vertical cols)
    wire_rows = [15, 30, 50, 68, 84]
    wire_cols = [15, 35, 60, 85, 105]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 3)

    # Neighborhood anchors: 5x5 grid
    nh_positions = []
    for row in range(5):
        for col in range(5):
            cx = 15 + col * 22   # 15, 37, 59, 81, 103
            cy = 12 + row * 19   # 12, 31, 50, 69, 88
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            return [nh_positions[12]]  # center
        elif pop < 300:
            return [nh_positions[6], nh_positions[7], nh_positions[11], nh_positions[12], nh_positions[13]]
        elif pop < 700:
            return nh_positions[5:20]
        elif pop < 1500:
            return nh_positions[2:23]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # ---- PHASE 0: Ensure power plants near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 9

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left_ok = ib(wx-1, wr) and bool(row_wire[wx-1])
                    right_ok = ib(wx+1, wr) and bool(row_wire[wx+1])
                    if (left_ok or right_ok) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up_ok = ib(wc, wy-1) and bool(col_wire[wy-1])
                    dn_ok = ib(wc, wy+1) and bool(col_wire[wy+1])
                    if (up_ok or dn_ok) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Seed wire corridors near plants if empty
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    px2, py2 = int(plant_xs[best]), int(plant_ys[best])
                    if ib(px2, wr) and bool(em[wr, px2]):
                        return (Tool.WIRE, px2, wr)
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    px2, py2 = int(plant_xs[best]), int(plant_ys[best])
                    if ib(wc, py2) and bool(em[py2, wc]):
                        return (Tool.WIRE, wc, py2)

    elif phase == 3:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Cross roads between corridor intersections (horizontal)
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            for wr_idx in range(len(wire_rows) - 1):
                r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
                mid_y = (r1 + r2) // 2
                for rx in range(c1 + 2, c2 - 1):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                              (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    elif phase == 6:
        # Cross roads between corridor intersections (vertical)
        for wr_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            for wc_idx in range(len(wire_cols) - 1):
                c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
                mid_x = (c1 + c2) // 2
                for ry in range(r1 + 2, r2 - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                              (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 7:
        # Extend road from existing road near power
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % len(road_xs2)
            for offset in range(min(len(road_xs2), 120)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # Wire spine extension toward active hoods
        for (hx, hy) in active_hoods:
            if not bool(near_power[hy, hx]):
                # extend wire toward this hood
                wire_ys_arr, wire_xs_arr = np.where(wm | pm)
                if len(wire_xs_arr) > 0:
                    dists = np.abs(wire_xs_arr - hx) + np.abs(wire_ys_arr - hy)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                    dx = 0 if hx == bwx else (1 if hx > bwx else -1)
                    dy = 0 if hy == bwy else (1 if hy > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Protect wire/plant corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_grid = [(10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
                     (10, 25), (35, 25), (85, 25), (110, 25),
                     (10, 50), (110, 50),
                     (10, 72), (35, 72), (60, 72), (85, 72), (110, 72),
                     (10, 93), (35, 93), (60, 93), (85, 93), (110, 93)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_grid = [(25, 15), (75, 15), (50, 40), (100, 40),
                       (25, 60), (75, 60), (10, 85), (50, 85), (90, 85),
                       (115, 25), (5, 45), (115, 65), (5, 70)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(45, 44), (75, 44), (45, 64), (75, 64),
                    (15, 44), (105, 44), (15, 64), (105, 64),
                    (60, 10), (60, 88)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 5), (115, 5), (5, 93), (115, 93),
                      (60, 5), (60, 93), (5, 50), (115, 50),
                      (30, 5), (90, 5), (30, 93), (90, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5), (60, 5), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90),
                    (5, 44), (5, 55), (110, 44), (110, 55)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire toward unpowered hoods ----
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: wire extension from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along vertical spine
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Flanking roads along horizontal spine
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- POWER COVERAGE: build adjacency map ----
    # nbr_power: any tile within 3 of wire or plant
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # nbr_road: any tile within 2 of road
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- NEIGHBORHOOD GRID ----
    nh_cols = [15, 32, 49, 60, 71, 88, 105]
    nh_rows = [12, 27, 42, 58, 73, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 3
        if pop < 300:  return 5
        if pop < 600:  return 9
        if pop < 1000: return 14
        if pop < 2000: return 20
        if pop < 4000: return 28
        if pop < 7000: return 36
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS near each hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: GROW WIRE from existing wire/plant toward uncovered hoods ----
    # For each active hood not yet near power, find closest wire tile and extend toward hood
    for (hx, hy) in active_hoods:
        if bool(nbr_power[hy, hx]):
            continue
        # Find wire tiles and extend the closest one toward this hood
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) == 0:
            continue
        dists = np.abs(wire_xs - hx) + np.abs(wire_ys - hy)
        closest = np.argmin(dists)
        wx, wy = int(wire_xs[closest]), int(wire_ys[closest])
        # Step toward hood
        dx = hx - wx
        dy = hy - wy
        if abs(dx) >= abs(dy):
            step_x = 1 if dx > 0 else -1
            nx, ny = wx + step_x, wy
        else:
            step_y = 1 if dy > 0 else -1
            nx, ny = wx, wy + step_y
        if ib(nx, ny) and bool(em[ny, nx]):
            return (Tool.WIRE, nx, ny)
        # Try alternate direction
        if abs(dx) < abs(dy) or not ib(nx, ny) or not bool(em[ny, nx]):
            if dx != 0:
                step_x = 1 if dx > 0 else -1
                nx2, ny2 = wx + step_x, wy
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)
            if dy != 0:
                step_y = 1 if dy > 0 else -1
                nx2, ny2 = wx, wy + step_y
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 3: EXTEND WIRE to fill spine near each hood ----
    spine_range = 10
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical spine at hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal spine at hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 4: GROW ROADS from existing roads toward uncovered hoods ----
    for (hx, hy) in active_hoods:
        if bool(nbr_road[hy, hx]):
            continue
        road_ys, road_xs = np.where(rm)
        if len(road_xs) == 0:
            continue
        dists = np.abs(road_xs - hx) + np.abs(road_ys - hy)
        closest = np.argmin(dists)
        rx, ry = int(road_xs[closest]), int(road_ys[closest])
        dx = hx - rx
        dy = hy - ry
        if abs(dx) >= abs(dy):
            step_x = 1 if dx > 0 else -1
            nx, ny = rx + step_x, ry
        else:
            step_y = 1 if dy > 0 else -1
            nx, ny = rx, ry + step_y
        if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
            return (Tool.ROAD, nx, ny)

    # ---- PHASE 5: FLANKING ROADS alongside wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods) // 2 + 1, 1) != 0:
            continue
        for rx_off in [hx - 1, hx + 1]:
            if not ib(rx_off, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx_off, ry): continue
                if bool(em[ry, rx_off]) and not bool(pm[ry, rx_off]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx_off, ry)
        for ry_off in [hy - 1, hy + 1]:
            if not ib(hx, ry_off): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry_off): continue
                if bool(em[ry_off, rcx]) and not bool(pm[ry_off, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry_off)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power, not at edge
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Distance to nearest active hood
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive: check existing counts) ----
    fire_count = 0
    police_count = 0
    # Count existing service buildings via tile ranges (approximate by checking near hoods)
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 20) for fy in range(15, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W, 24) for py2 in range(20, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (60, 30), (90, 30),
            (30, 60), (60, 60), (90, 60),
            (30, 80), (60, 80), (90, 80),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 45), (6, 65), (114, 45), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop ----
    if pop > 2000 and step % 3 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (10, 50), (110, 50), (60, 10), (60, 90),
            (20, 10), (100, 10), (20, 90), (100, 90)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire crosses and flanking roads."""
    actions = []
    # Two plants at different positions for good initial coverage
    for cx, cy in [(40, 50), (80, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for d in range(1, 7):
            actions.append((Tool.WIRE, cx + d, cy))
            actions.append((Tool.WIRE, cx - d, cy))
            actions.append((Tool.WIRE, cx, cy + d))
            actions.append((Tool.WIRE, cx, cy - d))
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 2, cy + dy))
            actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood grid - 8 cols x 6 rows
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 26, 42, 58, 74, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 22
        if pop < 3000:  return 32
        if pop < 6000:  return 40
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANT near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINE - extend from plant/wire toward hood center ----
    for (hx, hy) in active_hoods:
        # Vertical spine
        for dy in range(-8, 9):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal spine
        for dx in range(-8, 9):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            # Same row, horizontally adjacent
            if hy1 == hy2 and abs(hx2 - hx1) <= 16:
                lx, rx = min(hx1, hx2), max(hx1, hx2)
                for cx in range(lx + 1, rx):
                    if not ib(cx, hy1): continue
                    if bool(wm[hy1, cx]) or bool(pm[hy1, cx]): continue
                    if not bool(em[hy1, cx]): continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
            # Same col, vertically adjacent
            if hx1 == hx2 and abs(hy2 - hy1) <= 18:
                ty, by = min(hy1, hy2), max(hy1, hy2)
                for cy in range(ty + 1, by):
                    if not ib(hx1, cy): continue
                    if bool(wm[cy, hx1]) or bool(pm[cy, hx1]): continue
                    if not bool(em[cy, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy)

    # ---- PHASE 4: ROADS flanking wire spines ----
    spine_range = 8
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Roads flanking vertical spine (hx col)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal spine (hy row)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]): return False
        return True

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 18) for fy in range(10, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(12, WORLD_W, 22) for py2 in range(12, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000 and step % 3 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (8, 50), (112, 50), (60, 8), (60, 92)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94),
                    (6, 45), (6, 65), (114, 45), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 120 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx2 = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx2]), int(park_xs[idx2])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spine + flanking roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        if x != 60:
            actions.append((Tool.WIRE, x, 50))
    # Two flanking roads at y=47 and y=53
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    # Vertical wire at x=60
    for y in range(1, 99):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Keep balanced ratios: IND ~25%, COM ~25%, RES ~50%
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Grid: wire rows/cols define the power skeleton
    # Denser grid than parent for better coverage
    wire_rows = [8, 16, 24, 32, 40, 50, 60, 68, 76, 84, 92]
    wire_cols = [8, 16, 24, 32, 40, 50, 60, 68, 76, 84, 92, 100, 108]
    road_offsets = [-3, 3]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 0: Place coal plants if area lacks power (every 5 steps) ----
    if step % 5 == 0:
        # Check a grid of potential plant locations; place where no plant nearby
        plant_targets = []
        for py in range(10, 100, 20):
            for px in range(10, 120, 20):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Find nearest empty tile
                for r in range(12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # ---- PHASE 1: Extend wire rows (connected to existing wire/plant) ----
    if step % 6 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]):
                    continue
                if not bool(em[wr, wx]):
                    continue
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    return (Tool.WIRE, wx, wr)

    # ---- PHASE 2: Extend wire cols ----
    if step % 6 == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if bool(wm[wy, wc]) or bool(pm[wy, wc]):
                    continue
                if not bool(em[wy, wc]):
                    continue
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: Roads flanking wire rows ----
    if step % 6 == 3:
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  bool(rm[max(0,ry-1), rx]) or bool(rm[min(WORLD_H-1,ry+1), rx])
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Roads flanking wire cols ----
    if step % 6 == 4:
        for wc in wire_cols:
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

    # ---- PHASE 5: Wire toward unpowered zones ----
    if step % 6 == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- CIVIC SERVICES (reactive: place when pop threshold met and spot empty) ----
    if pop > 10:
        # Spread fire stations across map
        fire_spots = [
            (5,5),(35,5),(65,5),(95,5),(115,5),
            (5,18),(115,18),(5,33),(115,33),
            (5,48),(115,48),(5,62),(115,62),
            (5,77),(115,77),(5,92),(35,92),(65,92),(95,92),(115,92),
            (28,25),(55,25),(83,25),(28,75),(55,75),(83,75),
            (40,50),(80,50),(20,50),(100,50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 50:
        police_spots = [
            (15,12),(45,12),(75,12),(105,12),
            (15,37),(45,37),(75,37),(105,37),
            (15,62),(45,62),(75,62),(105,62),
            (15,87),(45,87),(75,87),(105,87),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (30,15),(70,15),(110,15),
            (30,40),(70,40),(110,40),
            (30,60),(70,60),(110,60),
            (30,85),(70,85),(110,85),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Upgrade to nuclear when pop is high enough
    if pop > 300:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
            (30,5),(90,5),(30,95),(90,95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 600:
        seaports = [(5,90),(115,90),(5,10),(115,10),(60,5),(60,95),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45),(5,55),(110,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near road and power - scatter across map
    if pop > 80 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT ----
    # Reactive: scan for powered+roaded empty tiles, place zones
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Avoid wire corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Active neighborhoods: denser grid than parent for higher pop
        if pop < 100:
            active_centers = [(cx, cy) for cy in [44, 47, 53, 56]
                              for cx in [15, 30, 45, 60, 75, 90, 105]]
        elif pop < 300:
            active_centers = [(cx, cy) for cy in [21, 28, 35, 42, 58, 65, 72, 79]
                              for cx in [10, 20, 35, 50, 65, 80, 95, 110]]
        elif pop < 800:
            active_centers = [(cx, cy) for cy in range(11, 100, 8)
                              for cx in range(8, 120, 8)]
        else:
            active_centers = [(cx, cy) for cy in range(7, 100, 6)
                              for cx in range(5, 120, 6)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary offset with both step and pop for higher reactivity
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- FALLBACK: extend road from existing road into powered area ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant near unpowered area ----
    all_hoods = [(cx, cy) for cy in range(8, 100, 9) for cx in range(5, 120, 9)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

