def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Aim for ~40% RES, 30% COM, 30% IND for a balanced city
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 8)
    near_road = dilate(rm, 2)

    # Dense wire grid: horizontal every 10 rows, vertical every 15 cols
    wire_rows = list(range(10, 100, 10))  # 10,20,30,...,90
    wire_cols = list(range(10, 120, 15))  # 10,25,40,55,70,85,100,115

    # Road grid: one row above/below each wire row, one col left/right each wire col
    # Additional plants at key intersections
    plant_positions = [
        (30, 50), (90, 50),   # center plants (already in init)
        (15, 15), (60, 15), (105, 15),
        (15, 85), (60, 85), (105, 85),
        (15, 50), (60, 50), (105, 50),
    ]

    # ---- PHASE 1: ENSURE PLANTS EXIST ----
    for px, py in plant_positions:
        x0, x1 = max(0, px-6), min(WORLD_W, px+7)
        y0, y1 = max(0, py-6), min(WORLD_H, py+7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Lay horizontal wire corridors
        for wr in wire_rows:
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
                    if ib(bpx, wr) and bool(em[wr, bpx]):
                        return (Tool.WIRE, bpx, wr)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        if (wx > 0 and bool(row_power[wx-1])) or \
                           (wx < WORLD_W-1 and bool(row_power[wx+1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Lay vertical wire corridors
        for wc in wire_cols:
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2, wc, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
                    if ib(wc, bpy2) and bool(em[bpy2, wc]):
                        return (Tool.WIRE, wc, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        if (wy > 0 and bool(col_power[wy-1])) or \
                           (wy < WORLD_H-1 and bool(col_power[wy+1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add cross-roads between wire rows to improve connectivity
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx+1]
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    for ry in range(wr1+2, wr2-1):
                        if ib(rcx, ry) and bool(em[ry, rcx]) and bool(near_power[ry, rcx]):
                            adj = (ib(rcx, ry-1) and bool(rm[ry-1, rcx])) or \
                                  (ib(rcx, ry+1) and bool(rm[ry+1, rcx]))
                            if adj:
                                return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Add cross-roads between wire cols
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx+1]
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    for rx in range(wc1+2, wc2-1):
                        if ib(rx, ry) and bool(em[ry, rx]) and bool(near_power[ry, rx]):
                            adj = (ib(rx-1, ry) and bool(rm[ry, rx-1])) or \
                                  (ib(rx+1, ry) and bool(rm[ry, rx+1]))
                            if adj:
                                return (Tool.ROAD, rx, ry)

    elif phase == 6:
        # Wire intersection crossings
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc-1])) or (wc < WORLD_W-1 and bool(wm[wr, wc+1]))
                col_ok = (wr > 0 and bool(wm[wr-1, wc])) or (wr < WORLD_H-1 and bool(wm[wr+1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 7:
        # Extend roads toward powered but unroaded areas
        target_mask = near_power & ~near_road & em
        target_mask[0:3, :] = False
        target_mask[WORLD_H-3:, :] = False
        target_mask[:, 0:3] = False
        target_mask[:, WORLD_W-3:] = False
        tys, txs = np.where(target_mask)
        road_ys, road_xs = np.where(rm)
        if len(txs) > 0 and len(road_xs) > 0:
            ti = (step * 17) % len(txs)
            tx, ty = int(txs[ti]), int(tys[ti])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Wire toward unpowered roads
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(npxs) > 0 and len(wire_xs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # else phase == 9: fall through to zone placement

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        # Score candidates: prefer near existing zones + near roads
        scores = np.zeros(len(cxs2), dtype=float)
        road_near4 = dilate(rm, 4)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 1.0 if bool(road_near4[y, x]) else 0.0
            # Spread across map — prefer areas that aren't too central
            # to avoid overcrowding the center
            dist_center = abs(x - 60) / 60.0 + abs(y - 50) / 50.0
            scores[i] += 0.5 * dist_center

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_positions = [
            (20, 10), (60, 10), (100, 10),
            (20, 40), (60, 40), (100, 40),
            (20, 60), (60, 60), (100, 60),
            (20, 88), (60, 88), (100, 88),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_positions = [
            (35, 25), (75, 25),
            (15, 55), (55, 55), (95, 55),
            (35, 75), (75, 75),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [
            (45, 35), (75, 35), (45, 65), (75, 65),
            (20, 50), (100, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(48, 5), (72, 5), (48, 92), (72, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value near zones
    if pop > 150 and step % 4 == 0:
        park_cands = em & near_road & near_power & dilate(zone_tiles, 3)
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 29 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend roads from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants, wire spine, seed roads"""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire connecting them at y=50
    for x in range(28, 93):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires spreading power up and down from center
    for y in range(44, 20, -1):
        actions.append((Tool.WIRE, 60, y))
    for y in range(56, 80):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads parallel to wire spine
    for x in range(20, 110):
        actions.append((Tool.ROAD, x, 44))
    for x in range(20, 110):
        actions.append((Tool.ROAD, x, 56))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        rr = res_count / tz
        # Aim for ~50% res, 25% com, 25% ind
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure enough power plants (one per ~20x20 region) ---
    # Grid of plant anchor points
    plant_xs = list(range(15, WORLD_W - 10, 25))
    plant_ys = list(range(15, WORLD_H - 10, 25))
    for ppy in plant_ys:
        for ppx in plant_xs:
            x0, x1 = max(0, ppx - 15), min(WORLD_W, ppx + 16)
            y0, y1 = max(0, ppy - 15), min(WORLD_H, ppy + 16)
            if not np.any(pm[y0:y1, x0:x1]):
                if ib(ppx, ppy) and bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Extend wire network reactively ---
    # Find all power sources; extend wire toward areas lacking power
    # Strategy: grow wires in a grid pattern every 8 rows/cols
    wire_rows = list(range(8, WORLD_H - 4, 8))
    wire_cols = list(range(8, WORLD_W - 4, 8))

    # Horizontal wire extension
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            # Find nearest plant and start wire there
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                sy = int(pys_arr[idx])
                # Wire from plant toward wire row
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Vertical wire extension
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 3 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # --- PHASE 3: Road grid reactively ---
    # Roads between wire rows (at midpoints)
    road_rows = sorted(set(wr + 4 for wr in wire_rows if 4 < wr + 4 < WORLD_H - 4))
    road_cols = sorted(set(wc + 4 for wc in wire_cols if 4 < wc + 4 < WORLD_W - 4))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(15, rr) and bool(em[rr, 15]) and not bool(pm[rr, 15]):
                return (Tool.ROAD, 15, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 4 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 15) and bool(em[15, rc]) and not bool(pm[15, rc]):
                return (Tool.ROAD, rc, 15)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 4 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- PHASE 4: Zone placement (closed-loop, reactive) ---
    zone_cand = em & near_road & near_power
    # Margins
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H - 3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W - 3:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        zone_cand[max(0, wr-1):wr+2, :] = False
    for rr in road_rows:
        zone_cand[max(0, rr-1):rr+2, :] = False
    for wc in wire_cols:
        zone_cand[:, max(0, wc-1):wc+2] = False
    for rc in road_cols:
        zone_cand[:, max(0, rc-1):rc+2] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                t = tm[nr, nc]
                # Allow empty or zone tiles
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            stride_r = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride_r):
                d = (np.abs(cxs_arr - road_xs[i]).astype(float) +
                     np.abs(cys_arr - road_ys[i]).astype(float))
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            stride_z = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride_z):
                d = (np.abs(cxs_arr - zone_xs[i]).astype(float) +
                     np.abs(cys_arr - zone_ys[i]).astype(float))
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Penalize too-close (overlapping), reward moderate distance
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Prefer near roads
        score = road_dist * 2.0 + zone_score * 0.5
        order = np.argsort(score)
        tool = pick_tool()
        off = (step * 7 + pop % 13) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services reactive to population ---
    if pop > 20:
        fire_ys = list(range(12, WORLD_H - 5, 15))
        fire_xs = list(range(12, WORLD_W - 5, 20))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        pol_ys = list(range(14, WORLD_H - 5, 16))
        pol_xs = list(range(14, WORLD_W - 5, 22))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_ys = list(range(10, WORLD_H - 5, 10))
        park_xs = list(range(10, WORLD_W - 5, 12))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 500:
        stad_spots = [(sx, sy) for sy in range(15, 85, 30) for sx in range(15, 105, 35)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuc_spots = [(nx, ny) for ny in range(12, 88, 22) for nx in range(12, 108, 22)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 14), min(WORLD_W, npx + 15)
                y0, y1 = max(0, npy - 14), min(WORLD_H, npy + 15)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 7), (65, 7), (55, 92), (65, 92)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Wire extension toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                    for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 7: Road extension toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                    for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- Fallback: road near existing plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 0), (-3, 0)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + cross-wire grid + initial roads"""
    actions = []
    # Two central coal plants, offset from parent
    actions.append((Tool.COALPOWER, 25, 45))
    actions.append((Tool.COALPOWER, 95, 45))
    # Horizontal wire spines at y=45 and y=65
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 45))
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 65))
    # Vertical wire spines at x=25, x=60, x=95
    for y in range(1, 99):
        actions.append((Tool.WIRE, 25, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 95, y))
    # Roads along wire spines (offset by 1)
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 66))
    for y in range(1, 99):
        actions.append((Tool.ROAD, 26, y))
        actions.append((Tool.ROAD, 61, y))
        actions.append((Tool.ROAD, 96, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        # More balanced mix skewed toward RES+COM for higher pop
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            # Bootstrap: need industry for jobs
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 500:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 2000:
            # Shift heavily to residential + commercial
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.50:
                return Tool.RESIDENTIAL
            if ir < 0.15:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            if rr < 0.55:
                return Tool.RESIDENTIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PHASE 1: Ensure power plants spread across map ===
    if step % 7 == 0:
        # Grid of coverage checks every 25 tiles
        for py in range(12, WORLD_H - 12, 22):
            for px in range(12, WORLD_W - 12, 22):
                x0, x1 = max(0, px - 11), min(WORLD_W, px + 12)
                y0, y1 = max(0, py - 11), min(WORLD_H, py + 12)
                if not np.any(pm[y0:y1, x0:x1]):
                    for r in range(0, 8):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 2: Extend wire toward unpowered zones ===
    if step % 7 == 1:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                best_dist = 999999
                best_zone = None
                sample = min(len(uz_xs), 40)
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # === PHASE 3: Extend wire into unpowered empty areas ===
    if step % 7 == 2:
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False

        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            unpowered_empty = em & ~near_power & ~zone_tiles
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                best_dist = 1e9
                best_k = 0
                sample_indices = np.linspace(0, len(upxs) - 1, min(30, len(upxs)), dtype=int)
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_indices)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # === PHASE 4: Extend road network ===
    if step % 7 == 3:
        # Connect unroaded zones to road first
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

        # Road grid: denser than parent (every 5 tiles) in powered areas
        road_grid_targets = []
        for gy in range(5, 98, 5):
            for gx in range(5, 118, 5):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        if road_grid_targets:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted

            road_cand = em & adj_to_road & near_power & ~zone_tiles
            road_cand[0:2, :] = False
            road_cand[WORLD_H - 2:, :] = False
            road_cand[:, 0:2] = False
            road_cand[:, WORLD_W - 2:] = False

            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                best_dist = 1e9
                best_k = 0
                targets_sample = road_grid_targets[:40]
                for i in range(min(len(rxs2), 500)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
            else:
                for gx, gy in road_grid_targets[:10]:
                    if bool(em[gy, gx]):
                        return (Tool.ROAD, gx, gy)

    # === PHASE 5: Civic services ===
    if step % 7 == 5:
        if pop > 20:
            fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 12)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        if pop > 100:
            police_grid = [(px2, py2) for py2 in range(12, 90, 14) for px2 in range(12, 110, 14)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        if pop > 400 and step % 7 == 5:
            park_cands = em & near_road & near_power
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 31 + pop) % len(pxs3)
                px2, py2 = int(pxs3[idx]), int(pys3[idx])
                if not bool(zone_tiles[py2, px2]):
                    return (Tool.PARK, px2, py2)

        if pop > 600:
            stadium_locs = [(25, 20), (95, 20), (25, 75), (95, 75),
                            (60, 48), (10, 48), (110, 48), (60, 12), (60, 88)]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        if pop > 1000:
            nuke_locs = [(8, 20), (112, 20), (8, 75), (112, 75),
                         (60, 8), (60, 92), (8, 48), (112, 48),
                         (35, 12), (85, 12), (35, 88), (85, 88)]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                    y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 2000:
            airport_locs = [(8, 8), (102, 8), (8, 90), (102, 90)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        if pop > 3000:
            seaport_locs = [(4, 48), (116, 48), (60, 4), (60, 95)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # === PHASE 6: Zone placement — core of the policy ===
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Favor close to road, spread from existing zones, prefer center regions
        cx_center = np.abs(cxs_arr - 60).astype(float) / 60.0
        cy_center = np.abs(cys_arr - 50).astype(float) / 50.0
        center_penalty = (cx_center + cy_center) * 3.0

        score = road_dist * 1.0 + np.maximum(0, 6 - zone_dist) * 2.5 + center_penalty

        order = np.argsort(score)
        # Use pop-dependent offset to explore different areas
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    # Central coal plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for x in range(max(0, cx-10), min(WORLD_W, cx+11)):
        if x != cx:
            actions.append((Tool.WIRE, x, cy))
    # Vertical wire spine
    for y in range(max(0, cy-10), min(WORLD_H, cy+11)):
        if y != cy:
            actions.append((Tool.WIRE, cx, y))
    # Roads flanking horizontal spine
    for x in range(max(0, cx-10), min(WORLD_W, cx+11)):
        for off in [-1, 1]:
            ry = cy + off
            if 0 <= ry < WORLD_H:
                actions.append((Tool.ROAD, x, ry))
    # Roads flanking vertical spine
    for y in range(max(0, cy-10), min(WORLD_H, cy+11)):
        for off in [-1, 1]:
            rx = cx + off
            if 0 <= rx < WORLD_W:
                actions.append((Tool.ROAD, rx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire/road grid layout: 5 vertical wire cols, 5 horizontal wire rows
    wire_cols = [20, 40, 60, 80, 100]
    wire_rows = [10, 27, 50, 72, 90]

    # Neighborhoods between wire spines
    nh_positions = []
    col_bands = [(2, 18), (22, 38), (42, 58), (62, 78), (82, 98), (102, 118)]
    row_bands = [(12, 25), (29, 48), (52, 70), (74, 88)]
    for (ry0, ry1) in row_bands:
        for (cx0, cx1) in col_bands:
            nh_positions.append(((cx0+cx1)//2, (ry0+ry1)//2))

    def get_active_hoods():
        if pop < 100:
            return nh_positions[9:15]
        elif pop < 400:
            return nh_positions[6:18]
        elif pop < 1000:
            return nh_positions[3:21]
        elif pop < 3000:
            return nh_positions
        return nh_positions

    active_hoods = get_active_hoods()

    # Dilate helper using numpy shifts
    def dilate(mask, r):
        result = mask.astype(bool).copy()
        for d in range(1, r+1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: Ensure power plants near active hoods ----
    if step % 10 == 0:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx-20), min(WORLD_W, hx+21)
            y0, y1 = max(0, hy-20), min(WORLD_H, hy+21)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(2, 20):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx+dx, hy+dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase in (0, 1):
        # Extend horizontal wire spines
        for wr in wire_rows:
            row_power = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W-1):
                if not bool(row_power[wx]) and bool(em[wr, wx]):
                    left = ib(wx-1, wr) and bool(row_power[wx-1])
                    right = ib(wx+1, wr) and bool(row_power[wx+1])
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    elif phase in (2, 3):
        # Extend vertical wire spines
        for wc in wire_cols:
            col_power = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H-1):
                if not bool(col_power[wy]) and bool(em[wy, wc]):
                    up = ib(wc, wy-1) and bool(col_power[wy-1])
                    down = ib(wc, wy+1) and bool(col_power[wy+1])
                    if up or down:
                        return (Tool.WIRE, wc, wy)

    elif phase == 4:
        # Roads flanking horizontal wire rows
        for wr in wire_rows:
            row_power = wm[wr, :] | pm[wr, :]
            for off in [-1, 1]:
                ry = wr + off
                if not (0 < ry < WORLD_H-1):
                    continue
                for rx in range(1, WORLD_W-1):
                    if bool(row_power[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 5:
        # Roads flanking vertical wire cols
        for wc in wire_cols:
            col_power = wm[:, wc] | pm[:, wc]
            for off in [-1, 1]:
                rcx = wc + off
                if not (0 < rcx < WORLD_W-1):
                    continue
                for ry in range(1, WORLD_H-1):
                    if bool(col_power[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 6:
        # Cross-roads between wire cols at row band midpoints
        for (ry0, ry1) in row_bands:
            mid_y = (ry0 + ry1) // 2
            for cx0, cx1 in zip(wire_cols[:-1], wire_cols[1:]):
                for rx in range(cx0+2, cx1-1):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = ((ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or
                               (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1])))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    elif phase == 7:
        # Cross-roads between wire rows at col band midpoints
        for (cx0, cx1) in col_bands:
            mid_x = (cx0 + cx1) // 2
            for ry0, ry1 in zip(wire_rows[:-1], wire_rows[1:]):
                for ry in range(ry0+2, ry1-1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = ((ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or
                               (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x])))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 8:
        # Extend roads from existing road network into powered areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (sk + offset*7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 9:
        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpowered_zones)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step*17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire spine corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step*7 + pop*3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset+i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 2000:
                break

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [(10,15),(30,15),(50,15),(70,15),(90,15),(110,15),
                      (10,40),(50,40),(90,40),(110,40),
                      (10,65),(50,65),(90,65),(110,65),
                      (10,85),(50,85),(90,85),(110,85)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(20,20),(55,20),(95,20),
                        (20,55),(55,55),(95,55),
                        (20,80),(55,80),(95,80)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30,35),(80,35),(30,65),(80,65),(55,15),(55,85)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [(5,50),(113,50),(5,10),(113,10),(5,90),(113,90)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(5,90),(113,90),(5,5),(113,5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45,5),(75,5),(45,92),(75,92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 200 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step*31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered hoods
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_a - target_hx) + np.abs(wire_ys_a - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step*13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (sk2 + offset*5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: road near zone
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step*19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plants + wire/road spines"""
    actions = []
    # Coal plants at key positions
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 20))
        actions.append((Tool.COALPOWER, px, 80))
    # Horizontal wire spines
    for x in range(1, 119):
        for wy in [20, 40, 50, 60, 80]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for y in range(1, 99):
        for wx in [20, 40, 60, 80, 100]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows
    for x in range(1, 119):
        for wy in [20, 40, 50, 60, 80]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def pick_tool():
        # Target: 40% res, 35% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 14

    # --- REACTIVE INFRASTRUCTURE PHASES ---

    # Phase 0: Check for unpowered zones and wire toward them
    if phase == 0:
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 1: Extend horizontal wire corridors reactively
    elif phase == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Extend vertical wire corridors reactively
    elif phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads above/below wire rows
    elif phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # Phase 4: Roads left/right of wire cols
    elif phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # Phase 5: Detect areas with road but no power and add wire
    elif phase == 5:
        road_no_power = rm & ~near_power
        rys, rxs = np.where(road_no_power)
        if len(rxs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 11) % len(rxs)
                tx, ty = int(rxs[idx]), int(rys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 6: Cross-roads between wire cols
    elif phase == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 7: Vertical roads between wire cols
    elif phase == 7:
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Phase 8: Extend road from existing road (reactive growth)
    elif phase == 8:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 150)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 9: Add power plant if large areas have road but no nearby plant
    elif phase == 9:
        # Find area farthest from any plant
        road_ys, road_xs = np.where(rm & ~near_power)
        if len(road_xs) > 0:
            plant_ys, plant_xs = np.where(pm)
            if len(plant_xs) > 0:
                # pick road tile farthest from plants
                idx = (step * 13) % len(road_xs)
                for off in range(min(len(road_xs), 50)):
                    k = (idx + off * 3) % len(road_xs)
                    tx, ty = int(road_xs[k]), int(road_ys[k])
                    # Find empty spot near this road tile for a plant
                    for r in range(3, 20):
                        placed = False
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx2, ny2 = tx + dx, ty + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)
                        if placed:
                            break

    # Phases 10-13: Civic services based on population
    elif phase in (10, 11, 12, 13):
        if pop > 20:
            fire_spots = [(5,5),(25,5),(55,5),(85,5),(110,5),
                          (5,25),(25,25),(55,25),(85,25),(110,25),
                          (5,45),(25,45),(85,45),(110,45),
                          (5,68),(25,68),(55,68),(85,68),(110,68),
                          (5,92),(25,92),(55,92),(85,92),(110,92)]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 100:
            police_spots = [(18,12),(60,12),(100,12),
                            (18,38),(60,38),(100,38),
                            (18,62),(60,62),(100,62),
                            (18,88),(60,88),(100,88)]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 500:
            stadium_spots = [(30,28),(88,28),(30,72),(88,72),(60,50)]
            for sx, sy in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [(5,50),(113,50),(60,5),(60,93),(5,5),(113,5),(5,93),(113,93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1200:
            seaports = [(5,93),(113,93),(5,5),(113,5)]
            for sx, sy in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2000:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(113,43)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- MAIN ZONE PLACEMENT (closed-loop, every step) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders and wire/road corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: prefer spots near existing zones (clustering) and roads
        # Use distance to nearest existing zone to encourage compact growth
        near_zone = dilate(zone_tiles, 4)
        # Priority: near zones AND near roads AND near power
        priority_mask = cand_mask & near_zone
        pys, pxs = np.where(priority_mask)
        if len(pxs) > 0:
            # Among priority candidates, pick deterministically
            offset = (step * 7 + pop * 3) % len(pxs)
            tool = pick_tool()
            checked = 0
            for i in range(len(pxs)):
                k = (offset + i) % len(pxs)
                zx, zy = int(pxs[k]), int(pys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)
                checked += 1
                if checked > 300:
                    break
        # Fallback: any candidate
        offset = (step * 7 + pop * 3) % len(cxs2)
        tool = pick_tool()
        checked = 0
        for i in range(len(cxs2)):
            k = (offset + i) % len(cxs2)
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # Parks for land value when nothing else to place
    if pop > 50 and step % 3 == 0:
        park_cands = em & near_road & near_power
        pys2, pxs2 = np.where(park_cands)
        if len(pxs2) > 0:
            idx = (step * 31 + pop) % len(pxs2)
            return (Tool.PARK, int(pxs2[idx]), int(pys2[idx]))

    # Fallback: wire toward unpowered road areas
    road_no_power2 = rm & ~near_power
    rys2, rxs2 = np.where(road_no_power2)
    if len(rxs2) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 13) % len(rxs2)
            tx, ty = int(rxs2[idx]), int(rys2[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place central coal plant + wire cross + initial roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross extending from plant
    for x in range(52, 70):
        if x not in range(58, 63):  # avoid overwriting plant tiles
            actions.append((Tool.WIRE, x, 50))
    for y in range(42, 59):
        if y not in range(48, 53):
            actions.append((Tool.WIRE, 60, y))
    # Roads parallel to wire spines (offset by 2)
    for x in range(52, 70):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(42, 59):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- REACTIVE NEIGHBORHOOD SYSTEM ----
    # Neighborhoods expand based on current population (closed-loop)
    def num_active_hoods():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 7
        if pop < 1000:  return 11
        if pop < 2000:  return 16
        if pop < 4000:  return 22
        if pop < 7000:  return 30
        return 36

    all_hoods = []
    for hy in range(12, 95, 16):
        for hx in range(12, 115, 16):
            all_hoods.append((hx, hy))

    n_active = num_active_hoods()
    # Select hoods closest to center first (spiral outward as pop grows)
    cx, cy = WORLD_W // 2, WORLD_H // 2
    all_hoods_sorted = sorted(all_hoods, key=lambda p: abs(p[0]-cx) + abs(p[1]-cy))
    active_hoods = all_hoods_sorted[:n_active]

    # ---- PHASE 1: POWER PLANTS ----
    # Each active hood needs a power plant nearby — check map reactively
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
            y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find empty spot near hood center
                for r in range(12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE INFRASTRUCTURE ----
    # Reactively extend wires from plants and existing wire networks
    # For each hood, build wire cross connecting to power
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 12)
        spine_bot   = min(WORLD_H - 3, hy + 12)
        spine_left  = max(2, hx - 12)
        spine_right = min(WORLD_W - 3, hx + 12)

        # Check if vertical spine exists at hx
        col_wire = [r for r in range(spine_top, spine_bot + 1) if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        # If plant in column but no adjacent wire, seed wire
        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1, py_l - 2, py_l + 2]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        # Extend vertical spine (reactive: extend from current wire boundary)
        if col_wire:
            min_wr, max_wr = min(col_wire), max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Check horizontal spine at hy
        row_wire  = [c for c in range(spine_left, spine_right + 1) if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1, px_l - 2, px_l + 2]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc, max_wc = min(row_wire), max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: CONNECT WIRE SPINES BETWEEN ADJACENT HOODS ----
    # Reactively bridge gaps between neighborhoods
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hx2 - hx1) > 20 or abs(hy1 - hy2) > 4:
                continue
            mid_y = (hy1 + hy2) // 2
            for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                    return (Tool.WIRE, cx2, mid_y)

    # ---- BUILD NEIGHBOR ROAD MASK (reactive, from current map) ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 4: ROAD GRID (reactive, follows wire placement) ----
    for (hx, hy) in active_hoods:
        # Roads parallel to wires, offset by 2 (reactive: only where wire exists)
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy) or not col_wire:
                continue
            cyc = step % 4
            for wr in col_wire[cyc::4]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry) or not row_wire:
                continue
            cyc = (step + 2) % 4
            for wc in row_wire[cyc::4]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # ---- PHASE 5: ZONE PLACEMENT (reactive, reads current map) ----
    def pick_tool():
        # Maintain balance: 25% ind, 25% com, rest res
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates: prefer close to active hoods AND existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (reactively placed when thresholds met) ----
    if pop > 10:
        for fsy in range(16, 96, 16):
            for fsx in range(16, 116, 16):
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        for psy in range(24, 88, 20):
            for psx in range(24, 100, 20):
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        for sty in [20, 50, 80]:
            for stx in [20, 60, 100]:
                if ib(stx, sty) and bool(em[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

    if pop > 800 and funds > 5000:
        for npy in [10, 90]:
            for npx in [10, 110, 60]:
                if not ib(npx, npy):
                    continue
                x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
                y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
                if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1000:
        for apx, apy in [(10, 10), (100, 10), (10, 85), (100, 85)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plant ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0), (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Improved city builder: denser grid, better zone ratios, faster infrastructure
# Key changes: 
# - Smaller neighborhood spacing (10 instead of 12) for denser coverage
# - More aggressive zone placement with better RCI balance
# - Nuclear power for higher capacity areas
# - Roads first strategy before zones
# - Better civic service placement timing

def init(obs, state):
    """Bootstrap: two coal plants + wire network + initial roads."""
    actions = []
    # Two central power plants to bootstrap faster
    cx1, cy1 = 40, 50
    cx2, cy2 = 80, 50
    actions.append((Tool.COALPOWER, cx1, cy1))
    actions.append((Tool.COALPOWER, cx2, cy2))
    # Wire connecting them
    for x in range(42, 79):
        actions.append((Tool.WIRE, x, cy1))
    # Vertical wires from each plant
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, cx1, cy1 + dy))
            actions.append((Tool.WIRE, cx2, cy2 + dy))
    # Roads flanking plant 1
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx1 - 1, cy1 + dy))
        actions.append((Tool.ROAD, cx1 + 1, cy1 + dy))
    # Roads flanking plant 2
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx2 - 1, cy2 + dy))
        actions.append((Tool.ROAD, cx2 + 1, cy2 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Denser neighborhood grid: 11 cols x 9 rows = 99 neighborhoods
    # Spaced 10 apart for denser coverage
    nh_cols = [6, 16, 26, 36, 46, 56, 66, 76, 86, 96, 106]
    nh_rows = [6, 17, 28, 39, 50, 61, 72, 83, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 10
        if pop < 700:   return 20
        if pop < 1500:  return 35
        if pop < 3000:  return 55
        if pop < 6000:  return 75
        if pop < 10000: return 90
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm
    spine_r = 8

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            # Use nuclear for later hoods when funded
                            if pop > 5000 and funds > 10000:
                                return (Tool.NUCLEARPOWER, nx, ny)
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Vertical spine at hx
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal spine at hy
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 14:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for (hx, hy) in active_hoods:
        # Roads at hx±1 (flanking vertical wire spine)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

        # Roads at hy±1 (flanking horizontal wire spine)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT with better RCI balance ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% residential, 30% commercial, 30% industrial
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers: need road access AND power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Try multiple candidates to find a clear spot
        for i in range(min(len(order), 400)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (16, 16), (36, 16), (56, 16), (76, 16), (96, 16), (116, 16),
            (16, 33), (36, 33), (56, 33), (76, 33), (96, 33), (116, 33),
            (16, 50), (36, 50), (56, 50), (76, 50), (96, 50), (116, 50),
            (16, 67), (36, 67), (56, 67), (76, 67), (96, 67), (116, 67),
            (16, 84), (36, 84), (56, 84), (76, 84), (96, 84), (116, 84),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (26, 24), (46, 24), (66, 24), (86, 24), (106, 24),
            (16, 42), (36, 42), (56, 42), (76, 42), (96, 42), (116, 42),
            (26, 60), (46, 60), (66, 60), (86, 60), (106, 60),
            (16, 78), (36, 78), (56, 78), (76, 78), (96, 78), (116, 78),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (25, 25), (55, 25), (85, 25), (115, 25),
            (10, 50), (40, 50), (70, 50), (100, 50),
            (25, 75), (55, 75), (85, 75), (115, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10), (60, 5), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 5), (70, 5), (40, 95), (70, 95)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: PARKS to boost land value ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

