def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        rr = res_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure enough power plants (dense grid every 16 tiles) ----
    plant_grid = []
    for py in range(10, WORLD_H - 5, 16):
        for px in range(10, WORLD_W - 5, 16):
            plant_grid.append((px, py))

    for ppx, ppy in plant_grid:
        if not ib(ppx, ppy):
            continue
        x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
        y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire network - extend toward unpowered areas ----
    # Compute tiles adjacent to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0:
        # Find unpowered plants first
        unpowered_plants = [(ppx, ppy) for ppx, ppy in plant_grid
                            if ib(ppx, ppy) and bool(pm[ppy, ppx]) and not bool(near_power[ppy, ppx])]
        if unpowered_plants:
            best_d, best_k = 1e9, 0
            for i in range(min(len(wxs_c), 500)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

        # Extend wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        uzys, uzxs = np.where(unpowered_zones)
        if len(uzxs) > 0:
            best_d, best_k = 1e9, 0
            stride = max(1, len(uzxs) // 20)
            for i in range(min(len(wxs_c), 500)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                        for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

        # Extend wire toward unpowered empty areas (frontier expansion)
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0 and len(wxs_c) > 0:
            sample_idx = np.random.choice(len(upxs), min(50, len(upxs)), replace=False)
            best_d, best_k = 1e9, 0
            for i in range(min(len(wxs_c), 300)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 3: Road network - dense grid every 5 tiles in powered areas ----
    road_grid = []
    for gy in range(5, WORLD_H - 3, 5):
        for gx in range(5, WORLD_W - 3, 5):
            road_grid.append((gx, gy))

    uncovered_roads = [(gx, gy) for gx, gy in road_grid
                       if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_roads:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles & ~pm
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False
        rys2, rxs2 = np.where(road_cand)

        if len(rxs2) > 0:
            targets_sample = uncovered_roads[:40]
            best_d, best_k = 1e9, 0
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_roads[:10]:
                if bool(em[gy, gx]) and not bool(pm[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # Also extend roads toward unserved zones
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    if len(usxs) > 0:
        adj_to_road2 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road2 |= shifted
        road_cand2 = em & adj_to_road2 & ~zone_tiles & ~pm
        road_cand2[0:2, :] = False
        road_cand2[WORLD_H-2:, :] = False
        road_cand2[:, 0:2] = False
        road_cand2[:, WORLD_W-2:] = False
        rys3, rxs3 = np.where(road_cand2)
        if len(rxs3) > 0:
            stride = max(1, len(usxs) // 20)
            best_d, best_k = 1e9, 0
            for i in range(min(len(rxs3), 400)):
                cx, cy = int(rxs3[i]), int(rys3[i])
                d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                        for j in range(0, len(usxs), stride))
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs3[best_k]), int(rys3[best_k]))

    # ---- PHASE 4: Zone placement (closed-loop, mixed) ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist > 20, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Use step-modulo for variety plus ratio override
        step_mod = step % 10
        if step_mod < 5:
            tool = Tool.RESIDENTIAL
        elif step_mod < 7:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL
        tz = max(total_zones, 1)
        if ind_count / tz < 0.20 or com_count / tz < 0.20:
            tool = pick_tool()

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled to population ----
    if pop > 50:
        for fy in range(8, 95, 10):
            for fx in range(8, 115, 14):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(near_road[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        for py2 in range(10, 92, 12):
            for px2 in range(10, 112, 16):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(near_road[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 400:
        for pky in range(12, 90, 8):
            for pkx in range(12, 110, 10):
                if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 700:
        stadium_locs = [(25, 20), (85, 20), (25, 75), (85, 75),
                        (55, 15), (55, 85), (15, 50), (105, 50),
                        (45, 35), (75, 65), (45, 65), (75, 35)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuclear_spots = [(nx, ny) for ny in range(12, 90, 20) for nx in range(12, 110, 20)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 10), min(WORLD_W, npx + 11)
                y0, y1 = max(0, npy - 10), min(WORLD_H, npy + 11)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_locs = [(55, 7), (65, 7), (55, 92), (65, 92),
                        (7, 44), (112, 44), (7, 56), (112, 56)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(7, 50), (112, 50), (60, 4), (60, 95),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: place road/wire near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5),
                         (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire connections and seed roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from central plant
    for x in range(50, 71):
        actions.append((Tool.WIRE, x, 50))
    for y in range(40, 61):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads offset from wire spines
    for x in range(50, 71):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(40, 61):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    # Left plant
    actions.append((Tool.COALPOWER, 25, 50))
    for x in range(19, 32):
        actions.append((Tool.WIRE, x, 50))
    for y in range(44, 57):
        actions.append((Tool.WIRE, 25, y))
    # Right plant
    actions.append((Tool.COALPOWER, 95, 50))
    for x in range(89, 102):
        actions.append((Tool.WIRE, x, 50))
    for y in range(44, 57):
        actions.append((Tool.WIRE, 95, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # --- PHASE 1: ENSURE POWER PLANTS ---
    # Reactively check: if any neighborhood lacks a nearby plant, place one
    all_hoods = []
    for hy in range(10, 100, 12):
        for hx in range(10, 120, 12):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:   return 4
        if pop < 200:  return 10
        if pop < 500:  return 20
        if pop < 1000: return 35
        if pop < 2000: return 55
        if pop < 4000: return 75
        if pop < 7000: return 92
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    if funds > 3000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Place plant at nearest empty spot
                for r in range(15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                use_nuclear = (funds > 15000 and pop > 2000)
                                tool = Tool.NUCLEARPOWER if use_nuclear else Tool.COALPOWER
                                return (tool, nx, ny)

    # --- PHASE 2: WIRE CONNECTIVITY ---
    # Grow wires from existing plants/wires toward uncovered areas
    # Build a proximity mask: where is power already?
    power_src = wm | pm
    pys_arr, pxs_arr = np.where(power_src)

    # For each active hood, check if it has wire coverage, if not extend wires
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_wire = bool(np.any(wm[y0:y1, x0:x1])) or bool(np.any(pm[y0:y1, x0:x1]))
        if not has_wire:
            # Find nearest existing wire/plant and extend toward hood
            if len(pxs_arr) > 0:
                dists = np.abs(pxs_arr - hx) + np.abs(pys_arr - hy)
                nearest_k = np.argmin(dists)
                wx, wy = int(pxs_arr[nearest_k]), int(pys_arr[nearest_k])
                # Step one tile toward hood
                dx = np.sign(hx - wx)
                dy = np.sign(hy - wy)
                # Try x direction first, then y
                cands = []
                if dx != 0:
                    cands.append((wx + dx, wy))
                if dy != 0:
                    cands.append((wx, wy + dy))
                for (nx, ny) in cands:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

        # Extend wire spines for each hood
        # Vertical spine at hx
        spine_top = max(2, hy - 8)
        spine_bot = min(WORLD_H - 3, hy + 8)
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(hx, r) and (bool(wm[r, hx]) or bool(pm[r, hx]))]
        col_empty = [r for r in range(spine_top, spine_bot + 1)
                     if ib(hx, r) and bool(em[r, hx]) and not bool(pm[r, hx])]
        if col_wire and col_empty:
            min_wr = min(col_wire)
            max_wr = max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine at hy
        spine_left = max(2, hx - 8)
        spine_right = min(WORLD_W - 3, hx + 8)
        row_wire = [c for c in range(spine_left, spine_right + 1)
                    if ib(c, hy) and (bool(wm[hy, c]) or bool(pm[hy, c]))]
        if row_wire:
            min_wc = min(row_wire)
            max_wc = max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and bool(em[hy, nc]) and not bool(pm[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and bool(em[hy, nc]) and not bool(pm[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: ROAD GRID ---
    # Roads offset ±2 from wire spines
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for road_x in [hx - 2, hx + 2]:
            if not ib(road_x, hy):
                continue
            if not col_wire:
                continue
            cyc = step % 3
            for wr in col_wire[cyc::3]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for road_y in [hy - 2, hy + 2]:
            if not ib(hx, road_y):
                continue
            if not row_wire:
                continue
            cyc = (step + 1) % 3
            for wc in row_wire[cyc::3]:
                if ib(wc, road_y) and bool(em[road_y, wc]) and not bool(pm[road_y, wc]):
                    return (Tool.ROAD, wc, road_y)

    # --- PHASE 4: ZONE PLACEMENT ---
    def pick_tool():
        # Maintain roughly 40% res, 30% com, 30% ind
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (within 4 tiles of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Cluster near existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # Weight: 35% hood distance, 65% zone proximity (more clustering)
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        # Vary offset reactively based on pop changes
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 5: EXTEND ROADS REACTIVELY ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 6: CIVIC SERVICES ---
    if pop > 10:
        fire_grid = [(fx, fy) for fy in range(15, 95, 18)
                     for fx in range(15, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(15, 95, 18)
                       for px2 in range(15, 115, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 25), (60, 75),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 30), (5, 70), (115, 30), (115, 70)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from any plant/wire ---
    if len(pxs_arr) > 0:
        sk = (step * 11) % len(pxs_arr)
        for offset in range(min(len(pxs_arr), 80)):
            k = (sk + offset * 7) % len(pxs_arr)
            px2, py2 = int(pxs_arr[k]), int(pys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: single central coal plant with wire cross and initial roads."""
    actions = []
    # Central power plant
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending outward
    for dx in range(-12, 13):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-12, 13):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Two horizontal roads flanking the central wire at y=47 and y=53
    for x in range(48, 73):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    # Two vertical roads flanking the central wire at x=57 and x=63
    for y in range(38, 63):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Build neighborhoods in a grid around the center
    # Tighter spacing: 14 units apart to allow dense development
    all_hoods = []
    for hy in range(14, 96, 14):
        for hx in range(14, 116, 14):
            all_hoods.append((hx, hy))

    # Scale active neighborhoods based on population
    def num_active():
        if pop < 50:   return 6
        if pop < 150:  return 12
        if pop < 400:  return 20
        if pop < 800:  return 30
        if pop < 1500: return 45
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick hoods spread across the map, centered around (60,50)
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        # Sort by distance from center, pick closest n_active
        center_x, center_y = 60, 50
        sorted_hoods = sorted(all_hoods,
                              key=lambda h: abs(h[0]-center_x) + abs(h[1]-center_y))
        active_hoods = sorted_hoods[:n_active]

    # === PROXIMITY MASKS ===
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: Ensure power plant near each active hood ===
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 16), min(WORLD_W, hx + 17)
            y0, y1 = max(0, hy - 16), min(WORLD_H, hy + 17)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                tool_p = Tool.NUCLEARPOWER if (pop > 500 and funds > 6000) else Tool.COALPOWER
                # Find empty spot near hood
                for r in range(2, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (tool_p, nx, ny)

    # === PHASE 2: Wire from nearest plant toward active hood ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        dists = np.abs(pxs - hx) + np.abs(pys - hy)
        best_pi = int(np.argmin(dists))
        px_l = int(pxs[best_pi])
        py_l = int(pys[best_pi])

        # Wire horizontally first, then vertically (L-shaped routing)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, py_l): continue
                if bool(pm[py_l, wx]) or bool(wm[py_l, wx]): continue
                if not bool(em[py_l, wx]): continue
                return (Tool.WIRE, wx, py_l)
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(hx, wy): continue
                if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
                if not bool(em[wy, hx]): continue
                return (Tool.WIRE, hx, wy)

    # === PHASE 3: Roads in a grid pattern around each hood ===
    # Place roads at offsets ±3 from the hood center (crossing wires)
    hood_idx3 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx3]

    road_offsets = [-3, 3]
    # Vertical roads flanking horizontal wire
    for rx in [hx3 + road_offsets[0], hx3 + road_offsets[1]]:
        if not ib(rx, hy3): continue
        for wr in range(max(0, hy3 - 6), min(WORLD_H, hy3 + 7)):
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    # Horizontal roads flanking vertical wire
    for ry in [hy3 + road_offsets[0], hy3 + road_offsets[1]]:
        if not ib(hx3, ry): continue
        for wc in range(max(0, hx3 - 6), min(WORLD_W, hx3 + 7)):
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # === PHASE 4: Connect neighborhoods with roads ===
    if step % 3 < 2:
        for i, (hx1, hy1) in enumerate(active_hoods[:-1]):
            hx2, hy2 = active_hoods[i + 1]
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 25: continue
            # Horizontal connection
            if abs(hy1 - hy2) <= 5:
                mid_y = (hy1 + hy2) // 2
                for cx3 in range(min(hx1, hx2), max(hx1, hx2) + 1):
                    if ib(cx3, mid_y) and bool(em[mid_y, cx3]) and not bool(pm[mid_y, cx3]):
                        if not bool(rm[mid_y, cx3]):
                            return (Tool.ROAD, cx3, mid_y)
            # Vertical connection
            if abs(hx1 - hx2) <= 5:
                mid_x = (hx1 + hx2) // 2
                for cy3 in range(min(hy1, hy2), max(hy1, hy2) + 1):
                    if ib(mid_x, cy3) and bool(em[cy3, mid_x]) and not bool(pm[cy3, mid_x]):
                        if not bool(rm[cy3, mid_x]):
                            return (Tool.ROAD, mid_x, cy3)

    # === PHASE 5: Zone placement with balanced RES/COM/IND ===
    def pick_tool():
        # Target: 40% RES, 35% COM, 25% IND
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: proximity to hoods + proximity to existing zones
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs2 - hx4).astype(float) + np.abs(cys2 - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)

        score = best_dist.copy()
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs2), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs2 - zxs2[i]).astype(float) +
                          np.abs(cys2 - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: Extend roads from existing network into powered areas ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 17) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 11) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 7: Civic services ===
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(12, 96, 16)
                     for fx in range(12, 116, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 80:
        police_grid = [(px2, py2) for py2 in range(16, 92, 18)
                       for px2 in range(16, 112, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 250:
        stadium_locs = [(30, 20), (90, 20), (30, 80), (90, 80),
                        (60, 20), (60, 80), (20, 50), (100, 50),
                        (45, 45), (75, 45), (45, 55), (75, 55)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 400 and funds > 4000:
        nuclear_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                        (60, 5), (60, 95), (5, 50), (115, 50),
                        (35, 25), (85, 25), (35, 75), (85, 75)]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 700:
        airport_locs = [(8, 8), (102, 8), (8, 84), (102, 84)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 8: Wire connections between hoods ===
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hx1-hx2) + abs(hy1-hy2) > 20: continue
            if abs(hy1 - hy2) <= 2:
                mid_y2 = (hy1 + hy2) // 2
                for cx4 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx4, mid_y2) and bool(em[mid_y2, cx4]) and not bool(pm[mid_y2, cx4]):
                        if not bool(wm[mid_y2, cx4]):
                            return (Tool.WIRE, cx4, mid_y2)
            if abs(hx1 - hx2) <= 2:
                mid_x2 = (hx1 + hx2) // 2
                for cy4 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mid_x2, cy4) and bool(em[cy4, mid_x2]) and not bool(pm[cy4, mid_x2]):
                        if not bool(wm[cy4, mid_x2]):
                            return (Tool.WIRE, mid_x2, cy4)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 19) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 7) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for unpowered hood ===
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 15):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire backbone and seed roads."""
    actions = []
    # Three power plants forming a triangle
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 60, 70))
    # Horizontal wire at y=20 connecting plants
    for x in range(18, 103):
        actions.append((Tool.WIRE, x, 20))
    # Vertical wire from y=20 to y=70 at x=60
    for y in range(20, 72):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads near each plant
    for x in range(14, 30):
        actions.append((Tool.ROAD, x, 27))
    for x in range(94, 110):
        actions.append((Tool.ROAD, x, 27))
    for x in range(54, 70):
        actions.append((Tool.ROAD, x, 63))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # --- Dilate helper ---
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 5)
    near_road = dilate(rm, 3)

    # Adjacency masks (1 tile)
    adj_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        s_y0 = max(0, -dy); s_y1 = min(WORLD_H, WORLD_H-dy)
        d_y0 = max(0, dy);  d_y1 = min(WORLD_H, WORLD_H+dy)
        s_x0 = max(0, -dx); s_x1 = min(WORLD_W, WORLD_W-dx)
        d_x0 = max(0, dx);  d_x1 = min(WORLD_W, WORLD_W+dx)
        adj_power[d_y0:d_y1, d_x0:d_x1] |= power_src[s_y0:s_y1, s_x0:s_x1]

    adj_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        s_y0 = max(0, -dy); s_y1 = min(WORLD_H, WORLD_H-dy)
        d_y0 = max(0, dy);  d_y1 = min(WORLD_H, WORLD_H+dy)
        s_x0 = max(0, -dx); s_x1 = min(WORLD_W, WORLD_W-dx)
        d_x0 = max(0, dx);  d_x1 = min(WORLD_W, WORLD_W+dx)
        adj_road[d_y0:d_y1, d_x0:d_x1] |= rm[s_y0:s_y1, s_x0:s_x1]

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Dense plant grid (~every 20 tiles) ---
    plant_xs = list(range(10, WORLD_W - 5, 20))
    plant_ys = list(range(10, WORLD_H - 5, 20))
    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                for r in range(0, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx+dx, ppy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Wire grid (rows every 10, cols every 10) ---
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = int(np.argmin(np.abs(pys_arr - wr)))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(60, wr) and bool(em[wr, 60]):
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left-1]) and not bool(pm[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W-2 and bool(em[wr, right+1]) and not bool(pm[wr, right+1]):
            return (Tool.WIRE, right+1, wr)

    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top-1, wc]) and not bool(pm[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H-2 and bool(em[bot+1, wc]) and not bool(pm[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)

    # --- PHASE 3: Road grid (midway between wire rows/cols) ---
    road_rows = sorted(set(wr+5 for wr in wire_rows if 3 < wr+5 < WORLD_H-3))
    road_cols = sorted(set(wc+5 for wc in wire_cols if 3 < wc+5 < WORLD_W-3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(10, rr) and bool(em[rr, 10]) and not bool(pm[rr, 10]):
                return (Tool.ROAD, 10, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)

    # --- PHASE 4: Zone placement ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    # Don't place zones on wire/road rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist > 15, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.4
        order = np.argsort(score)
        off = (step * 11 + pop % 17) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Wire toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    wire_cand = em & adj_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 6: Road toward unserved zones ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    road_cand2 = em & adj_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H-2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- PHASE 7: Civic services (reactive to population) ---
    if pop > 30:
        fire_ys = list(range(15, WORLD_H-5, 12))
        fire_xs = list(range(15, WORLD_W-5, 18))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        pol_ys = list(range(18, WORLD_H-5, 14))
        pol_xs = list(range(18, WORLD_W-5, 20))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_ys = list(range(12, WORLD_H-5, 10))
        park_xs = list(range(12, WORLD_W-5, 12))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 600:
        for sty in range(20, 85, 25):
            for stx in range(20, 100, 30):
                if ib(stx, sty) and bool(em[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        # Upgrade to nuclear in dense areas
        for npy in range(15, 90, 25):
            for npx in range(15, 110, 25):
                if ib(npx, npy) and bool(em[npy, npx]):
                    x0, x1 = max(0, npx-14), min(WORLD_W, npx+15)
                    y0, y1 = max(0, npy-14), min(WORLD_H, npy+15)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        for apx, apy in [(55,7),(65,7),(55,92),(65,92),(7,45),(112,45)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        for spx, spy in [(7,50),(112,50),(60,4),(60,95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: road near plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6,0),(-6,0),(0,6),(0,-6),(4,0),(-4,0),(0,4),(0,-4)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants in corners + center, with wire and road spines."""
    actions = []
    # Plant positions: corners and center
    plants = [(20, 20), (100, 20), (60, 50), (20, 80), (100, 80)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine horizontally from plant
        for dx in range(-4, 5):
            actions.append((Tool.WIRE, px + dx, py))
        # Wire spine vertically from plant
        for dy in range(-4, 5):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire horizontally
        for dx in range(-4, 5):
            actions.append((Tool.ROAD, px + dx, py - 1))
            actions.append((Tool.ROAD, px + dx, py + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target: 40% res, 35% com, 25% ind — more commercial/industrial than parent
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 5 neighborhoods at different positions than parent
    # Using a diamond/cross pattern instead of 3x3 grid
    all_anchors = [
        (20, 20),   # top-left
        (100, 20),  # top-right
        (60, 50),   # center
        (20, 80),   # bottom-left
        (100, 80),  # bottom-right
    ]

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 2
        if pop < 400:   return 3
        if pop < 700:   return 4
        return 5

    n_active = num_active()
    # Start with center, then spread outward
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: horizontal + vertical from each anchor ----
    spine_half = min(25, 8 + pop // 15)
    for (px, py) in active_anchors:
        # Horizontal wire spine
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, py) and bool(wm[py, c])]
        if not wire_in_row:
            for dx in range(-4, 5):
                nx = px + dx
                if ib(nx, py) and bool(em[py, nx]) and not bool(pm[py, nx]):
                    return (Tool.WIRE, nx, py)
        else:
            max_wc = max(wire_in_row)
            min_wc = min(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, py) and not bool(pm[py, nc]):
                    return (Tool.WIRE, nc, py)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, py) and not bool(pm[py, nc]):
                    return (Tool.WIRE, nc, py)

        # Vertical wire spine
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy in range(-4, 5):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            max_wr = max(wire_in_col)
            min_wr = min(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- CONNECT ANCHORS WITH WIRE ----
    if n_active >= 2:
        for i in range(len(active_anchors)):
            for j in range(i + 1, len(active_anchors)):
                ax1, ay1 = active_anchors[i]
                ax2, ay2 = active_anchors[j]
                # Connect horizontally at ay1 level
                if ay1 == ay2:
                    for cx in range(min(ax1, ax2), max(ax1, ax2) + 1):
                        if ib(cx, ay1) and bool(em[ay1, cx]) and not bool(pm[ay1, cx]):
                            return (Tool.WIRE, cx, ay1)
                else:
                    # Connect via midpoint
                    mid_x = (ax1 + ax2) // 2
                    for cy in range(min(ay1, ay2), max(ay1, ay2) + 1):
                        if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                            return (Tool.WIRE, mid_x, cy)

    # ---- ROAD BUILDING: horizontal roads flanking each anchor ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_left = max(2, px - spine_half)
        spine_right = min(WORLD_W - 3, px + spine_half)
        # Horizontal roads above and below each anchor
        for road_y_off in [-2, 2]:
            ry = py + road_y_off
            if not ib(px, ry):
                continue
            for cx in range(spine_left, spine_right + 1):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    return (Tool.ROAD, cx, ry)

    # ---- VERTICAL ROADS flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        cycle = (step + idx * 7) % 3
        for wr in range(spine_top + cycle, spine_bot + 1, 3):
            for rx in [px - 2, px + 2]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- CONNECTING ROADS BETWEEN ANCHORS ----
    if pop > 30:
        for i in range(len(active_anchors)):
            for j in range(i + 1, len(active_anchors)):
                ax1, ay1 = active_anchors[i]
                ax2, ay2 = active_anchors[j]
                # Road at midpoint vertical connector
                mid_x = (ax1 + ax2) // 2
                for road_off in [-1, 1]:
                    for cy in range(min(ay1, ay2), max(ay1, ay2) + 1):
                        if ib(mid_x + road_off, cy) and bool(em[cy, mid_x + road_off]) and not bool(pm[cy, mid_x + road_off]):
                            return (Tool.ROAD, mid_x + road_off, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [
            (10, 10), (55, 10), (105, 10),
            (10, 50), (55, 50), (105, 50),
            (10, 90), (55, 90), (105, 90),
            (30, 30), (80, 30), (30, 70), (80, 70),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 35), (60, 35), (105, 35),
            (15, 65), (60, 65), (105, 65),
            (35, 10), (85, 10), (35, 90), (85, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 5), (60, 5), (110, 5),
            (10, 95), (60, 95), (110, 95),
            (5, 50), (115, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Compact grid-based city with strong infrastructure first
# Key differences from parent:
# 1. More balanced zone mix (more commercial/industrial)
# 2. Denser road network with cross-streets
# 3. Nuclear power for later game
# 4. Prioritize powered zones over expansion
# 5. Better wire connectivity ensuring all zones get power

def init(obs, state):
    """Bootstrap: two coal plants flanking center, wire grid, starter roads."""
    actions = []
    # Two power plants for better coverage
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire connecting them horizontally
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Vertical spines from each plant
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 40, y))
            actions.append((Tool.WIRE, 80, y))
    # Roads flanking the wire spines
    for y in range(44, 57):
        actions.append((Tool.ROAD, 39, y))
        actions.append((Tool.ROAD, 41, y))
        actions.append((Tool.ROAD, 79, y))
        actions.append((Tool.ROAD, 81, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Neighborhood grid: staggered layout with 12-tile spacing
    # Columns at 10, 22, 34, 46, 58, 70, 82, 94, 106
    # Rows at 10, 22, 34, 46, 58, 70, 82, 94
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 700:   return 15
        if pop < 1500:  return 25
        if pop < 3000:  return 40
        if pop < 6000:  return 55
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread hoods across the map evenly
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # Build nbr_road and nbr_power masks upfront
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place coal plant near hood center
            for r in range(1, 10):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE SPINES (cross pattern through hood center) ----
    spine_r = 9
    # Process one hood per step to spread work
    hood_idx = step % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_idx + i_h) % len(active_hoods)]

        # Vertical wire spine at hx
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Check if adjacent to existing wire/plant
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal wire spine at hy
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Horizontal connections
            if hy1 == hy2 and 0 < hx2 - hx1 <= 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical connections
            if hx1 == hx2 and 0 < hy2 - hy1 <= 14:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS (grid around wire spines) ----
    for i_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_idx + i_h) % len(active_hoods)]

        # Roads flanking vertical wire spine (hx-1, hx+1)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(pm[ry, rx]): continue
                if bool(rm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                # Only lay road if wire spine is present at hx
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal wire spine (hy-1, hy+1)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(pm[ry2, rcx]): continue
                if bool(rm[ry2, rcx]): continue
                if not bool(em[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

        # Cross-streets every 4 tiles to form grid (connect parallel roads)
        for cross_offset in range(-spine_r, spine_r + 1, 4):
            # Horizontal cross at hy + cross_offset connecting hx-1 to hx+1
            cross_y = hy + cross_offset
            for rx in [hx - 1, hx + 1]:
                if not ib(rx, cross_y): continue
                # Road from hx+1 outward
                for ext in range(1, 5):
                    ex = rx + (1 if rx > hx else -1) * ext
                    if not ib(ex, cross_y): break
                    if bool(pm[cross_y, ex]): break
                    if bool(rm[cross_y, ex]): continue
                    if not bool(em[cross_y, ex]): break
                    return (Tool.ROAD, ex, cross_y)

    # ---- PHASE 5: ZONE PLACEMENT ----
    # Zone mix: 40% res, 30% com, 30% ind
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (reactive to pop) ----
    if pop > 200:
        fire_spots = [
            (18, 18), (42, 18), (66, 18), (90, 18), (114, 18),
            (18, 38), (42, 38), (66, 38), (90, 38), (114, 38),
            (18, 58), (42, 58), (66, 58), (90, 58), (114, 58),
            (18, 78), (42, 78), (66, 78), (90, 78), (114, 78),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (30, 28), (54, 28), (78, 28), (102, 28),
            (18, 48), (42, 48), (66, 48), (90, 48), (114, 48),
            (30, 68), (54, 68), (78, 68), (102, 68),
            (18, 88), (42, 88), (66, 88), (90, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [
            (25, 25), (60, 25), (95, 25),
            (12, 55), (47, 55), (82, 55), (110, 55),
            (25, 80), (60, 80), (95, 80),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        seaports = [(6, 90), (114, 90), (6, 8), (114, 8), (60, 5), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # Switch to nuclear for high pop (cleaner/more powerful)
    if pop > 5000 and funds > 10000:
        nuclear_spots = [(20, 50), (60, 20), (100, 50), (60, 80)]
        for (sx, sy) in nuclear_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.NUCLEARPOWER, sx, sy)

    if pop > 8000:
        airports = [(46, 5), (76, 5), (46, 95), (76, 95)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: PARKS for land value boost ----
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new power plant ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
