def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Helper: dilate a mask by radius r (Manhattan) ---
    def dilate(mask, r):
        result = mask.astype(bool).copy()
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # --- Wire grid: horizontal lines every 6 rows, vertical every 6 cols ---
    wire_rows = list(range(14, 92, 6))
    wire_cols = list(range(12, 112, 6))

    # --- Phase logic based on step mod ---
    phase = step % 4

    # Phase 0: Extend horizontal wires reactively (gap-fill adjacent to existing power)
    if phase == 0:
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            for wx in range(1, WORLD_W - 1):
                if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                    left = bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])
                    right = bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    # Phase 1: Extend vertical wires reactively
    if phase == 1:
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            for wy in range(1, WORLD_H - 1):
                if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                    up = bool(wm[wy-1, wc]) or bool(pm[wy-1, wc])
                    dn = bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # Phase 2: Roads along wire rows (offset +1 and -1)
    if phase == 2:
        for wr in wire_rows:
            for offset in [1, -1, 2, -2]:
                ry = wr + offset
                if not (1 <= ry < WORLD_H - 1):
                    continue
                for rx in range(2, WORLD_W - 2):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        near_w = bool(wm[wr, rx]) if 0 <= wr < WORLD_H else False
                        adj_r = ((rx > 0 and bool(rm[ry, rx-1])) or
                                 (rx < WORLD_W-1 and bool(rm[ry, rx+1])))
                        if near_w or adj_r:
                            return (Tool.ROAD, rx, ry)

    # Phase 3: Roads along wire cols (offset +1 and -1)
    if phase == 3:
        for wc in wire_cols:
            for offset in [1, -1, 2, -2]:
                rcx = wc + offset
                if not (1 <= rcx < WORLD_W - 1):
                    continue
                for ry in range(2, WORLD_H - 2):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        near_w = bool(wm[ry, wc]) if 0 <= wc < WORLD_W else False
                        adj_r = ((ry > 0 and bool(rm[ry-1, rcx])) or
                                 (ry < WORLD_H-1 and bool(rm[ry+1, rcx])))
                        if near_w or adj_r:
                            return (Tool.ROAD, rcx, ry)

    # --- Ensure power plant coverage: if any active hub lacks nearby plant, place one ---
    hubs = [
        (60, 50), (25, 25), (95, 25), (25, 75), (95, 75),
        (60, 20), (60, 80), (20, 50), (100, 50),
        (40, 40), (80, 40), (40, 60), (80, 60),
    ]
    # Activate hubs progressively
    if pop < 150:
        active_hubs = hubs[:1]
    elif pop < 400:
        active_hubs = hubs[:3]
    elif pop < 800:
        active_hubs = hubs[:5]
    elif pop < 1500:
        active_hubs = hubs[:7]
    elif pop < 2500:
        active_hubs = hubs[:10]
    else:
        active_hubs = hubs

    for (hx, hy) in active_hubs:
        x0, x1 = max(0, hx - 18), min(WORLD_W, hx + 19)
        y0, y1 = max(0, hy - 18), min(WORLD_H, hy + 19)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place coal plant near hub
            for r in range(1, 20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- Civic services ---
    if pop > 60:
        fire_spots = [(x, y) for y in range(12, 92, 18) for x in range(12, 112, 22)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(x, y) for y in range(15, 92, 20) for x in range(15, 112, 25)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(30, 35), (90, 35), (30, 65), (90, 65), (60, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [(10, 50), (110, 50), (60, 10), (60, 90),
                      (10, 10), (110, 90), (10, 90), (110, 10),
                      (35, 50), (85, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 90), (110, 90), (5, 10), (110, 10)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(45, 5), (75, 5), (45, 92), (5, 45), (112, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- Zone placement: find empty tiles near road AND power ---
    cand_mask = em & near_road & near_power
    # Exclude border
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/road corridors themselves
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Prioritize candidates closest to an active hub
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hubs:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use step+pop offset to vary starting search point for reactivity
        offset = (step * 13 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- Parks for land value in populated areas ---
    if pop > 80 and step % 4 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 11) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- Extend roads from existing road tiles into powered areas ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 17 + pop * 3) % len(road_xs)
        for off in range(min(len(road_xs), 400)):
            k = (sk + off * 11) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Extend wires from existing wire tiles ---
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 23 + pop * 5) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 200)):
            k = (sk2 + off * 9) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- Wire unpowered hubs ---
    unpowered = [(hx, hy) for (hx, hy) in active_hubs if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- Last resort: coal plant near first hub ---
    hx, hy = active_hubs[0]
    for r in range(1, 20):
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                if abs(dx) == r or abs(dy) == r:
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + parallel roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines from center
    for x in range(45, 76):
        if x != 60:
            actions.append((Tool.WIRE, x, 50))
    for y in range(35, 66):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    # Roads parallel to wire spines (offset ±3)
    for x in range(45, 76):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(35, 66):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # --- Dilation helpers ---
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    nbr_power = dilate(wm | pm, 3)
    nbr_road = dilate(rm, 2)

    # --- Zone tool picker ---
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        if rr < 0.44:
            return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- Neighborhood grid (reactive: active hoods scale with pop) ---
    all_hoods = []
    for hy in range(12, 92, 16):
        for hx in range(12, 115, 18):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 30:    return 3
        if pop < 100:   return 6
        if pop < 300:   return 10
        if pop < 700:   return 16
        if pop < 1500:  return 22
        if pop < 3000:  return 28
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # === PHASE 1: POWER PLANTS ===
    if funds > 1500:
        for py in range(20, 92, 28):
            for px in range(20, 112, 28):
                x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
                y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    for r in range(9):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) != r and abs(dy) != r:
                                    continue
                                nx, ny = px + dx, py + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE SPINES (reactive: extend toward uncovered hoods) ===
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 13)
        spine_bot   = min(WORLD_H - 3, hy + 13)
        spine_left  = max(2, hx - 13)
        spine_right = min(WORLD_W - 3, hx + 13)

        # Vertical spine at hx
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        if col_wire:
            min_wr, max_wr = min(col_wire), max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine at hy
        row_wire = [c for c in range(spine_left, spine_right + 1)
                    if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc, max_wc = min(row_wire), max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # === PHASE 3: CONNECT ADJACENT HOODS WITH WIRES ===
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 40:
                continue
            if abs(hy1 - hy2) <= 4:
                mid_y = (hy1 + hy2) // 2
                for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
            if abs(hx1 - hx2) <= 4:
                mid_x = (hx1 + hx2) // 2
                for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                        return (Tool.WIRE, mid_x, cy)

    # === PHASE 4: ROAD GRID (parallel to wire spines, ±3 tiles) ===
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 3, hx + 3]:
            if not ib(rx, hy) or not col_wire:
                continue
            cyc = step % 7
            for wr in col_wire[cyc::7]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 3, hy + 3]:
            if not ib(hx, ry) or not row_wire:
                continue
            cyc = (step + 3) % 7
            for wc in row_wire[cyc::7]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # === PHASE 5: ZONE PLACEMENT (primary growth action) ===
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Boost clustering near existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: CIVIC SERVICES (reactive to pop) ===
    if pop > 30:
        fire_grid = [(fx, fy) for fy in range(18, 95, 22)
                     for fx in range(18, 112, 24)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(22, 90, 24)
                       for px2 in range(22, 110, 24)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 19 + pop) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 500:
        stadium_locs = [
            (30, 25), (60, 15), (90, 25),
            (20, 50), (60, 50), (100, 50),
            (30, 75), (60, 85), (90, 75),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1000 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (40, 25), (80, 25), (40, 75), (80, 75),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1500:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: extend road into powered area ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === FALLBACK: extend wire from existing wires ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
