    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    plant_count = int(np.sum(pm))

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(resm[nr, nc]) or
                        bool(comm[nr, nc]) or bool(indm[nr, nc])):
                    return False
        return True

    # === PHASE 1: Ensure power plants cover the map ===
    # Check quadrants every ~10 steps
    if step % 10 == 0:
        # Grid of target positions for plants
        plant_targets = []
        for py in range(15, 95, 20):
            for px in range(15, 115, 20):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Place plant near this target
                for r in range(15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 2: Extend wire network from power sources ===
    if step % 5 in (1, 2):
        frontier_ys, frontier_xs = np.where(power_src)
        if len(frontier_xs) > 0:
            # Find wire frontier cells and extend toward unpowered areas
            candidates = []
            n_sample = min(len(frontier_xs), 100)
            sh = (step * 37) % max(len(frontier_xs), 1)
            for i in range(n_sample):
                k = (sh + i * 13) % len(frontier_xs)
                fx, fy = int(frontier_xs[k]), int(frontier_ys[k])
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx2, ny2 = fx + dx, fy + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(near_power[ny2, nx2]):
                        candidates.append((nx2, ny2))
            if candidates:
                # Pick candidate furthest from power centroid (expands coverage)
                pm_ys, pm_xs = np.where(power_src)
                cx_p = float(np.mean(pm_xs)) if len(pm_xs) > 0 else 60.0
                cy_p = float(np.mean(pm_ys)) if len(pm_ys) > 0 else 50.0
                best, best_score = None, -1.0
                for (cx2, cy2) in candidates[:40]:
                    score = abs(cx2 - cx_p) + abs(cy2 - cy_p)
                    if score > best_score:
                        best_score = score
                        best = (cx2, cy2)
                if best:
                    return (Tool.WIRE, best[0], best[1])

    # === PHASE 3: Connect wire to unpowered roads ===
    if step % 9 == 5:
        unpowered_roads = rm & ~near_power
        ur_ys, ur_xs = np.where(unpowered_roads)
        if len(ur_xs) > 0:
            wire_ys, wire_xs = np.where(power_src)
            if len(wire_xs) > 0:
                idx = (step * 23) % len(ur_xs)
                tx, ty = int(ur_xs[idx]), int(ur_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # === PHASE 4: Extend road network into powered areas ===
    if step % 7 in (3, 4):
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            n_sample = min(len(road_xs), 120)
            sk = (step * 17) % len(road_xs)
            for i in range(n_sample):
                k = (sk + i * 11) % len(road_xs)
                rx, ry = int(road_xs[k]), int(road_ys[k])
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx2, ny2 = rx + dx, ry + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        if bool(near_power[ny2, nx2]):
                            return (Tool.ROAD, nx2, ny2)
        else:
            # No roads yet — seed one near center
            for dx in range(-6, 7):
                for dy in range(-6, 7):
                    nx2, ny2 = 60 + dx, 50 + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # === CIVIC SERVICES ===
    if pop > 20:
        fire_spots = [
            (5, 5), (30, 5), (60, 5), (90, 5), (115, 5),
            (5, 25), (115, 25), (5, 50), (115, 50),
            (5, 75), (115, 75), (5, 95), (30, 95), (60, 95), (90, 95),
            (20, 20), (45, 20), (75, 20), (100, 20),
            (20, 50), (45, 50), (75, 50), (100, 50),
            (20, 80), (45, 80), (75, 80), (100, 80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (15, 12), (40, 12), (65, 12), (90, 12), (112, 12),
            (15, 35), (40, 35), (65, 35), (90, 35), (112, 35),
            (15, 60), (40, 60), (65, 60), (90, 60), (112, 60),
            (15, 85), (40, 85), (65, 85), (90, 85), (112, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for sx, sy in [(25, 15), (75, 15), (25, 45), (75, 45),
                       (25, 75), (75, 75), (50, 30), (100, 30),
                       (50, 70), (100, 70)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        for nx2, ny2 in [(10, 50), (110, 50), (60, 10), (60, 90),
                         (30, 10), (90, 10), (30, 90), (90, 90)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for sx, sy in [(5, 92), (115, 92), (5, 8), (115, 8)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        for sx, sy in [(50, 5), (70, 5), (50, 92), (70, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # === ZONE PLACEMENT ===
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False
    cand_mask &= ~(wm | rm | pm)

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        if pop < 150:
            cx_t, cy_t = 60, 50
            dists = np.abs(cxs - cx_t).astype(float) + np.abs(cys - cy_t).astype(float)
        elif pop < 600:
            ring_r = 15 + pop // 25
            dists = np.abs(np.abs(cxs - 60).astype(float) + np.abs(cys - 50).astype(float) - ring_r)
        else:
            q_counts = [
                int(np.sum(resm[:50, :60])) + int(np.sum(comm[:50, :60])) + int(np.sum(indm[:50, :60])),
                int(np.sum(resm[:50, 60:])) + int(np.sum(comm[:50, 60:])) + int(np.sum(indm[:50, 60:])),
                int(np.sum(resm[50:, :60])) + int(np.sum(comm[50:, :60])) + int(np.sum(indm[50:, :60])),
                int(np.sum(resm[50:, 60:])) + int(np.sum(comm[50:, 60:])) + int(np.sum(indm[50:, 60:])),
            ]
            min_q = int(np.argmin(q_counts))
            cx_t = 30 if min_q in (0, 2) else 90
            cy_t = 25 if min_q in (0, 1) else 75
            dists = np.abs(cxs - cx_t).astype(float) + np.abs(cys - cy_t).astype(float)

        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 7 + pop) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === FALLBACK: extend road near existing power ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 200)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire ===
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % max(len(wire_xs2), 1)
        for off in range(min(len(wire_xs2), 100)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: place road near center if nothing else works ===
    for r in range(1, 20):
        for dx in range(-r, r + 1):
            for dy in range(-r, r + 1):
                if abs(dx) == r or abs(dy) == r:
                    nx2, ny2 = 60 + dx, 50 + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants + wire spine + flanking roads"""
    actions = []
    # Three coal plants at center row
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(1, 99):
        for px in [20, 60, 100]:
            actions.append((Tool.WIRE, px, y))
    # Flanking roads
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 3)

    # Wire rows and cols for infrastructure grid
    wire_rows = [15, 30, 50, 70, 85]
    wire_cols = [10, 25, 40, 60, 80, 95, 110]

    phase = step % 10

    # ---- PHASE: Ensure power plants cover all areas ----
    if step % 6 == 0:
        grid_xs = list(range(10, WORLD_W - 5, 20))
        grid_ys = list(range(10, WORLD_H - 5, 20))
        for ppy in grid_ys:
            for ppx in grid_xs:
                if not ib(ppx, ppy):
                    continue
                x0, x1 = max(0, ppx - 15), min(WORLD_W, ppx + 16)
                y0, y1 = max(0, ppy - 15), min(WORLD_H, ppy + 16)
                if not np.any(pm[y0:y1, x0:x1]):
                    if bool(em[ppy, ppx]):
                        return (Tool.COALPOWER, ppx, ppy)

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]) and (bool(wm[wr, rx]) or bool(pm[wr, rx])):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]) and (bool(wm[ry, wc]) or bool(pm[ry, wc])):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross streets between wire rows at midpoints
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire cols at midpoints
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend roads from existing roads toward unpowered/unserved areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 100)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Civic services
        if pop > 30:
            fire_spots = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 114, 15)]
            for fsx, fsy in fire_spots:
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        if pop > 150:
            police_spots = [(px2, py2) for py2 in range(10, 92, 15) for px2 in range(10, 112, 18)]
            for psx, psy in police_spots:
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        if pop > 500:
            stadium_spots = [(30,25),(88,25),(30,75),(88,75),(60,50),(15,50),(105,50)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [(5,5),(113,5),(5,93),(113,93),(5,50),(113,50),(60,5),(60,93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            seaports = [(5,93),(113,93),(5,5),(113,5),(60,3),(60,96)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2500:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(113,43)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (main closed-loop, every step) ----
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep zones off infrastructure rows/cols
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: close to roads, cluster with existing zones
        road_ys_arr, road_xs_arr = np.where(rm)
        zone_ys_arr, zone_xs_arr = np.where(zone_tiles)

        if len(road_xs_arr) > 0:
            stride = max(1, len(road_xs_arr) // 80)
            road_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(road_xs_arr), stride):
                d = np.abs(cxs2 - road_xs_arr[i]).astype(float) + np.abs(cys2 - road_ys_arr[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.abs(cxs2 - 60).astype(float) + np.abs(cys2 - 50).astype(float)

        if len(zone_xs_arr) > 0:
            stride2 = max(1, len(zone_xs_arr) // 80)
            zone_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(zone_xs_arr), stride2):
                d = np.abs(cxs2 - zone_xs_arr[i]).astype(float) + np.abs(cys2 - zone_ys_arr[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            zone_score = np.where(zone_dist < 3, 1000.0, np.where(zone_dist > 25, zone_dist * 0.5, 0.0))
        else:
            # Prefer center of map to start
            zone_score = np.abs(cxs2 - 60).astype(float) + np.abs(cys2 - 50).astype(float)

        score = road_dist * 2.0 + zone_score * 0.4
        order = np.argsort(score)
        tool = pick_tool()
        off = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 400:
                break

    # Parks for land value boost
    if pop > 80 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & near_road & near_power)
        if len(park_cands_x) > 0:
            idx = (step * 31 + pop) % len(park_cands_x)
            return (Tool.PARK, int(park_cands_x[idx]), int(park_cands_y[idx]))

    # Fallback: extend wire toward unpowered neighborhoods
    unpow_ys, unpow_xs = np.where(zone_tiles & ~near_power)
    if len(unpow_xs) > 0:
        wire_ys_fb, wire_xs_fb = np.where(wm | pm)
        if len(wire_xs_fb) > 0:
            idx = (step * 13) % len(unpow_xs)
            tx, ty = int(unpow_xs[idx]), int(unpow_ys[idx])
            dists = np.abs(wire_xs_fb - tx) + np.abs(wire_ys_fb - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_fb[best_wi]), int(wire_ys_fb[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 60)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire spine + roads so act() has a powered base."""
    actions = []
    # Three coal plants along horizontal center
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at each plant column
    for wx in [20, 60, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking the wire spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire grid rows/cols for power backbone
    wire_rows = [10, 25, 40, 50, 60, 75, 90]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 115]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 10

    # Phase 0: Ensure power plants exist in all quadrants
    if phase == 0:
        plant_targets = []
        for py in [10, 30, 50, 70, 90]:
            for px in [20, 60, 100]:
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill gaps in horizontal wire rows
    if phase == 1:
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill gaps in vertical wire cols
    if phase == 2:
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads above/below wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  (ry > 0 and bool(rm[ry-1, rx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # Phase 4: Roads left/right of wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

    # Phase 5: Cross streets between wire rows
    if phase == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            for frac in [0.33, 0.5, 0.67]:
                mid_y = int(r1 + (r2 - r1) * frac)
                if not (0 < mid_y < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                              (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])) or \
                              (mid_y > 0 and bool(rm[mid_y-1, rx])) or \
                              (mid_y < WORLD_H-1 and bool(rm[mid_y+1, rx]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # Phase 6: Cross streets between wire cols
    if phase == 6:
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = int(c1 + (c2 - c1) * 0.5)
            if not (0 < mid_x < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ry > 0 and bool(rm[ry-1, mid_x])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])) or \
                          (mid_x > 0 and bool(rm[ry, mid_x-1])) or \
                          (mid_x < WORLD_W-1 and bool(rm[ry, mid_x+1]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Phase 7: Wire unpowered zones reactively
    if phase == 7:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Extend road from existing roads into powered areas
    if phase == 8:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled to population ----
    if pop > 30:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,25),(115,25),(5,50),(115,50),
            (5,75),(115,75),(5,95),(30,95),(60,95),(90,95),(115,95),
            (20,20),(50,20),(80,20),(110,20),
            (20,45),(50,45),(80,45),(110,45),
            (20,70),(50,70),(80,70),(110,70),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 120:
        police_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,35),(45,35),(75,35),(105,35),
            (15,65),(45,65),(75,65),(105,65),
            (15,85),(45,85),(75,85),(105,85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(35,20),(85,20),(35,80),(85,80),(60,50),(10,50),(110,50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,20),(115,20),(5,80),(115,80),
            (30,5),(90,5),(30,95),(90,95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5,95),(115,95),(5,5),(115,5),(60,5),(60,95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3,:] = False
        park_cands[WORLD_H-3:,:] = False
        park_cands[:,0:3] = False
        park_cands[:,WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep zones off wire/road corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Active centers grow outward as population increases
        if pop < 100:
            active_centers = [(60,50),(45,50),(75,50),(60,42),(60,58)]
        elif pop < 400:
            active_centers = [(60,50),(30,50),(90,50),
                              (60,30),(60,70),(30,30),(90,30),(30,70),(90,70)]
        elif pop < 1000:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 10 + col * 15
                    cy = 10 + row * 16
                    active_centers.append((cx, cy))
        elif pop < 2500:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 8 + col * 12
                    cy = 8 + row * 12
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend wire from existing wire network
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plant and initial wire/road spine at center."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from plant
    for dx in range(-3, 4):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-3, 4):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the vertical wire spine
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD CENTERS ----
    # Compact grid of neighborhoods
    hood_cols = [20, 40, 60, 80, 100]
    hood_rows = [20, 40, 60, 80]
    all_hoods = [(c, r) for r in hood_rows for c in hood_cols]

    # Unlock hoods progressively
    def n_active():
        if pop < 50:   return 1
        if pop < 200:  return 3
        if pop < 500:  return 5
        if pop < 1000: return 8
        if pop < 2000: return 12
        if pop < 4000: return 15
        return len(all_hoods)

    na = n_active()
    if na >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_s = max(1, len(all_hoods) // na)
        active_hoods = all_hoods[::step_s][:na]

    # ---- POWER PLANTS ----
    # For each active hood, ensure a plant exists within 6 tiles
    for (hx, hy) in active_hoods:
        x0 = max(0, hx - 6); x1 = min(WORLD_W, hx + 7)
        y0 = max(0, hy - 6); y1 = min(WORLD_H, hy + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place plant at hood center if empty, else search outward
            for r in range(1, 8):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE SPINES ----
    # Extend wire from each plant outward to cover the hood
    for (hx, hy) in active_hoods:
        # Find nearest plant to this hood
        x0 = max(0, hx - 10); x1 = min(WORLD_W, hx + 11)
        y0 = max(0, hy - 10); y1 = min(WORLD_H, hy + 11)
        pys, pxs = np.where(pm[y0:y1, x0:x1])
        if len(pxs) == 0:
            continue
        # Use the first plant found
        py_loc = int(pys[0]) + y0
        px_loc = int(pxs[0]) + x0

        # Extend vertical wire from plant
        col_wires = [r for r in range(WORLD_H) if ib(px_loc, r) and (bool(wm[r, px_loc]) or bool(pm[r, px_loc]))]
        if col_wires:
            min_wr = min(col_wires)
            max_wr = max(col_wires)
            top_target = max(2, hy - 10)
            bot_target = min(WORLD_H - 3, hy + 10)
            if max_wr < bot_target:
                ny2 = max_wr + 1
                if ib(px_loc, ny2) and bool(em[ny2, px_loc]):
                    return (Tool.WIRE, px_loc, ny2)
            if min_wr > top_target:
                ny2 = min_wr - 1
                if ib(px_loc, ny2) and bool(em[ny2, px_loc]):
                    return (Tool.WIRE, px_loc, ny2)

        # Extend horizontal wire from plant
        row_wires = [c for c in range(WORLD_W) if ib(c, py_loc) and (bool(wm[py_loc, c]) or bool(pm[py_loc, c]))]
        if row_wires:
            min_wc = min(row_wires)
            max_wc = max(row_wires)
            left_target = max(2, hx - 10)
            right_target = min(WORLD_W - 3, hx + 10)
            if max_wc < right_target:
                nx2 = max_wc + 1
                if ib(nx2, py_loc) and bool(em[py_loc, nx2]):
                    return (Tool.WIRE, nx2, py_loc)
            if min_wc > left_target:
                nx2 = min_wc - 1
                if ib(nx2, py_loc) and bool(em[py_loc, nx2]):
                    return (Tool.WIRE, nx2, py_loc)

    # ---- CROSS-CONNECT WIRE BETWEEN HOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hy1 - hy2) > 3 and abs(hx1 - hx2) > 3:
                continue
            # Connect horizontally if same row
            if abs(hy1 - hy2) <= 3:
                mid_y = (hy1 + hy2) // 2
                x_lo, x_hi = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(x_lo, x_hi + 1):
                    if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                        return (Tool.WIRE, cx2, mid_y)
            # Connect vertically if same col
            if abs(hx1 - hx2) <= 3:
                mid_x = (hx1 + hx2) // 2
                y_lo, y_hi = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(y_lo, y_hi + 1):
                    if ib(mid_x, cy2) and bool(em[cy2, mid_x]) and not bool(pm[cy2, mid_x]):
                        return (Tool.WIRE, mid_x, cy2)

    # ---- ROAD NETWORK ----
    # Build roads flanking wire columns (at hx-1 and hx+1)
    for (hx, hy) in active_hoods:
        col_wires = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy):
                continue
            # Build road along wire extent
            offset = step % max(len(col_wires), 1) if col_wires else 0
            for i, wr in enumerate(col_wires):
                if i % 2 != offset % 2:
                    continue
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        # Roads flanking horizontal wire rows (at hy-1 and hy+1)
        row_wires = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 1, hy + 1]:
            if not ib(hx, ry):
                continue
            offset2 = (step + 1) % max(len(row_wires), 1) if row_wires else 0
            for i, wc in enumerate(row_wires):
                if i % 2 != offset2 % 2:
                    continue
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        # 3x3 zone must be empty or existing zone tiles
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute neighbor road coverage (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute neighbor wire/power coverage (within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone positions: empty, near road, near power, not border
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H - 2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Score by proximity to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- EXTEND ROADS from existing road ends ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 300:
        fire_spots = [(25, 25), (75, 25), (25, 75), (75, 75), (50, 50),
                      (100, 25), (100, 75), (50, 15), (50, 85)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 800:
        police_spots = [(30, 30), (70, 30), (30, 70), (70, 70), (50, 50),
                        (90, 50), (10, 50)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 2000:
        stadiums = [(40, 40), (80, 40), (40, 70), (80, 70)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 4000:
        for (sx, sy) in [(10, 90), (110, 90)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 6000:
        for (sx, sy) in [(55, 10), (55, 88)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS to boost land value ----
    if pop > 500 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from center
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along wire spines
    for dy in range(-9, 10):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-9, 10):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: ~45% RES, ~30% COM, ~25% IND
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === NEIGHBORHOOD GRID - denser than parent ===
    # Use tighter spacing for more zones
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106]
    nh_rows = [10, 21, 32, 43, 54, 65, 76, 87]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 14
        if pop < 800:   return 22
        if pop < 1500:  return 32
        if pop < 3000:  return 45
        if pop < 6000:  return 56
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # === BUILD NEIGHBOR MASKS ===
    power_src = wm | pm

    # Power dilation radius 5
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            if abs(dx2) + abs(dy2) > 5:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Road dilation radius 3
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            if abs(dx2) + abs(dy2) > 3:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === REACTIVE: Check powered zones ratio ===
    powered_ratio = obs.powered_zones / max(total_zones, 1)

    # === PHASE 1: POWER PLANTS for active hoods ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
        y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            # Place plant near hood center
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE SPINES - connect plants to hoods ===
    spine_range = 12
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0p, x1p = max(0, hx - 18), min(WORLD_W, hx + 19)
    y0p, y1p = max(0, hy - 18), min(WORLD_H, hy + 19)
    plant_ys_l, plant_xs_l = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs_l) > 0:
        px_l = int(plant_xs_l[0]) + x0p
        py_l = int(plant_ys_l[0]) + y0p
        # Wire vertical from plant to hood
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        # Wire horizontal from plant to hood
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spines at hood
    for dy3 in range(-spine_range, spine_range + 1):
        wy = hy + dy3
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    for dx3 in range(-spine_range, spine_range + 1):
        wx = hx + dx3
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # === PHASE 3: CONNECT WIRE BETWEEN HOODS ===
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    for i_h in range(min(len(active_hoods), 8)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist == 0 or dist > 35:
                continue
            if abs(hy1 - hy2) <= 3:
                mid_y2 = (hy1 + hy2) // 2
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, mid_y2): continue
                    if not bool(em[mid_y2, cx2]) or bool(pm[mid_y2, cx2]) or bool(wm[mid_y2, cx2]):
                        continue
                    has_l = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                for c in range(max(0, cx2 - 4), cx2))
                    has_r = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                for c in range(cx2 + 1, min(WORLD_W, cx2 + 5)))
                    if has_l or has_r:
                        return (Tool.WIRE, cx2, mid_y2)
            if abs(hx1 - hx2) <= 3:
                mid_x2 = (hx1 + hx2) // 2
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(mid_x2, cy2): continue
                    if not bool(em[cy2, mid_x2]) or bool(pm[cy2, mid_x2]) or bool(wm[cy2, mid_x2]):
                        continue
                    has_t = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2])
                                for r in range(max(0, cy2 - 4), cy2))
                    has_b = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2])
                                for r in range(cy2 + 1, min(WORLD_H, cy2 + 5)))
                    if has_t or has_b:
                        return (Tool.WIRE, mid_x2, cy2)

    # === PHASE 4: ROADS FLANKING WIRE SPINES ===
    # REACTIVE: if powered_ratio is low, prioritize roads to fix power delivery
    road_idx = step % max(len(active_hoods), 1)
    hx_r, hy_r = active_hoods[road_idx]

    # Build roads flanking the wire spines (both sides)
    for offset in [1, 2]:
        for rx in [hx_r - offset, hx_r + offset]:
            if not ib(rx, hy_r): continue
            for dy4 in range(-spine_range, spine_range + 1):
                ry = hy_r + dy4
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]): continue
                if bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
                if bool(wm[ry, hx_r]) or bool(pm[ry, hx_r]):
                    return (Tool.ROAD, rx, ry)

    for offset in [1, 2]:
        for ry2 in [hy_r - offset, hy_r + offset]:
            if not ib(hx_r, ry2): continue
            for dx4 in range(-spine_range, spine_range + 1):
                rcx = hx_r + dx4
                if not ib(rcx, ry2): continue
                if bool(rm[ry2, rcx]): continue
                if bool(pm[ry2, rcx]): continue
                if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
                if bool(wm[hy_r, rcx]) or bool(pm[hy_r, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # === PHASE 5: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Zone clustering bonus
        if total_zones > 8:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        # Vary offset by pop too so city doesn't get stuck
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: EXTEND ROADS INTO POWERED EMPTY AREAS ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx5, dy5 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx5, ry2 + dy5
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # === CIVIC SERVICES (population-gated) ===
    if pop > 60:
        for fx in range(12, WORLD_W, 14):
            for fy in range(12, WORLD_H, 14):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 150:
        for px2 in range(14, WORLD_W, 16):
            for py2 in range(14, WORLD_H, 16):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 100 and step % 4 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 17) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 2500:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (5, 75), (115, 25), (115, 75),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 700:
        airport_locs = [
            (10, 10), (100, 10), (10, 85), (100, 85),
            (55, 5), (55, 93),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: EXTEND WIRE FROM EXISTING WIRE/PLANTS ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx6, dy6 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx6, wy2 + dy6
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: NEW PLANT FOR UNCOVERED HOOD ===
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 16):
                for dy7 in range(-r2, r2 + 1):
                    for dx7 in range(-r2, r2 + 1):
                        if abs(dx7) == r2 or abs(dy7) == r2:
                            nx4, ny4 = hx3 + dx7, hy3 + dy7
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + initial roads"""
    actions = []
    # Two coal plants: left-center and right-center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines connecting both plants
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from both plants
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Cross wire at y=25, y=75
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Roads flanking horizontal wire spines
    for x in range(1, 119):
        for wy in [25, 50, 75]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target ratio: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Primary wire spines (horizontal: y=25,50,75; vertical: x=30,90 + secondaries)
    wire_rows = [25, 50, 75]
    wire_cols = [30, 90, 10, 50, 70, 110]
    road_rows = [24, 26, 49, 51, 74, 76]

    # Neighborhoods arranged in a 3-band layout
    # Band 1: y~12-18, Band 2: y~35-45, Band 3: y~57-67, Band 4: y~82-92
    nh_positions = []
    for col in range(9):
        cx = 6 + col * 13
        cx = min(cx, 114)
        for ry, ry_center in [(12, 12), (37, 37), (62, 62), (87, 87)]:
            nh_positions.append((cx, ry_center))

    def get_active_hoods():
        if pop < 100:
            return [(cx, cy) for (cx, cy) in nh_positions if 30 <= cx <= 90 and 30 <= cy <= 70]
        elif pop < 500:
            return [(cx, cy) for (cx, cy) in nh_positions if 10 <= cx <= 110]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # Phase-based infrastructure actions
    phase = step % 10

    # Phase 0: Ensure power coverage near active hoods
    if phase == 0:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
            y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Add coal plant near hood
                for r in range(2, 20):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    elif phase == 1:
        # Extend horizontal wire rows
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left = ib(wx-1, wr) and bool(row_wire[wx-1])
                    right = ib(wx+1, wr) and bool(row_wire[wx+1])
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 2:
        # Extend vertical wire columns
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up = ib(wc, wy-1) and bool(col_wire[wy-1])
                    down = ib(wc, wy+1) and bool(col_wire[wy+1])
                    if (up or down) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 3:
        # Roads flanking wire rows
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (1 <= ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Add vertical roads flanking wire columns
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (1 <= rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Connect unpowered hoods with wire
        unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
        if unpowered:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                tx, ty = unpowered[0]
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best = np.argmin(dists)
                bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 6:
        # Add mid-band horizontal roads for cross-connectivity
        mid_roads = [12, 37, 62, 87]
        for mr in mid_roads:
            if not (1 <= mr < WORLD_H - 1):
                continue
            row_road = rm[mr, :]
            row_wire_near = near_power[mr, :]
            for rx in range(2, WORLD_W - 2):
                if bool(em[mr, rx]) and bool(row_wire_near[rx]) and not bool(pm[mr, rx]):
                    adj = (ib(rx-1, mr) and bool(rm[mr, rx-1])) or \
                          (ib(rx+1, mr) and bool(rm[mr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mr)

    elif phase == 7:
        # Extend road from existing road near power
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            step_k = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 80)):
                k = (step_k + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) \
                       and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpowered_zones)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    else:
        # Add secondary wire for mid-band rows
        for wr in [12, 37, 62, 87]:
            row_wire = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left = ib(wx-1, wr) and bool(row_wire[wx-1])
                    right = ib(wx+1, wr) and bool(row_wire[wx+1])
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # ---- ZONE PLACEMENT (closed-loop, driven by obs) ----
    avoid_rows = [25, 50, 75, 24, 26, 49, 51, 74, 76, 12, 37, 62, 87]
    avoid_cols = [30, 90, 10, 50, 70, 110, 29, 31, 89, 91]

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    for wr in avoid_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in avoid_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 2000:
                break

    # ---- CIVIC SERVICES (closed-loop based on pop) ----
    if pop > 30:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 35), (60, 35), (115, 35),
            (5, 62), (60, 62), (115, 62),
            (5, 90), (60, 90), (115, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (15, 15), (55, 15), (95, 15),
            (15, 50), (95, 50),
            (15, 80), (55, 80), (95, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (40, 20), (80, 20),
            (40, 80), (80, 80),
            (20, 50), (100, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        # Upgrade to nuclear
        nuke_spots = [
            (5, 5), (113, 5), (5, 93), (113, 93),
            (5, 50), (113, 50), (59, 5), (59, 93),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 93), (113, 93), (5, 5), (113, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [
            (48, 5), (72, 5), (48, 90), (72, 90),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 29 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend road from zone tiles
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: compact central cluster with power + road grid"""
    actions = []
    # Two coal power plants
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 95, 50))
    # Horizontal wire spine
    for x in range(18, 98):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire from each plant
    for y in range(34, 67):
        actions.append((Tool.WIRE, 20, y))
        actions.append((Tool.WIRE, 95, y))
    # Cross-wire at center
    for y in range(34, 67):
        actions.append((Tool.WIRE, 57, y))
    # Seed roads: horizontal grid lines
    for x in range(10, 112):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
        actions.append((Tool.ROAD, x, 60))
    # Vertical connector roads
    for y in range(38, 63):
        actions.append((Tool.ROAD, 15, y))
        actions.append((Tool.ROAD, 35, y))
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 79, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone mix: 50% res, 30% com, 20% ind — more commercial than parent
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plants cover the map ----
    # Grid every 18 cols, 18 rows
    plant_grid_xs = list(range(10, WORLD_W - 5, 18))
    plant_grid_ys = list(range(10, WORLD_H - 5, 18))

    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            if not ib(ppx, ppy):
                continue
            x0 = max(0, ppx - 12)
            x1 = min(WORLD_W, ppx + 13)
            y0 = max(0, ppy - 12)
            y1 = min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Wire grid — horizontal rows every 18, vertical cols every 18 ----
    wire_rows = list(range(10, WORLD_H - 5, 18))
    wire_cols = list(range(10, WORLD_W - 5, 18))

    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not row_has.any():
            pys, pxs = np.where(pm)
            if len(pxs) > 0:
                nearest = pxs[np.argmin(np.abs(pys - wr))]
                if ib(int(nearest), wr) and bool(em[wr, int(nearest)]):
                    return (Tool.WIRE, int(nearest), wr)
            if ib(57, wr) and bool(em[wr, 57]):
                return (Tool.WIRE, 57, wr)
            continue
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left-1]):
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right+1]):
            return (Tool.WIRE, right+1, wr)
        for x in range(left+1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]) and not bool(rm[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not col_has.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top-1, wc]):
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and bool(em[bot+1, wc]):
            return (Tool.WIRE, wc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]) and not bool(rm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Dense road grid — rows and cols between wire lines ----
    # Road rows at offset +6 from each wire row
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 6)
        road_rows.append(wr + 6)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 6)
        road_cols.append(wc + 6)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(57, rr) and bool(em[rr, 57]) and not bool(pm[rr, 57]):
                return (Tool.ROAD, 57, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        for x in range(left+1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        for y in range(top+1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement (closed-loop) ----
    zone_cand = em & near_road & near_power
    # Buffer from edges
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H-3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W-3:] = False
    # Don't place on wire rows/cols or road rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
            if wr-1 >= 0: zone_cand[wr-1, :] = False
            if wr+1 < WORLD_H: zone_cand[wr+1, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
            if wc-1 >= 0: zone_cand[:, wc-1] = False
            if wc+1 < WORLD_W: zone_cand[:, wc+1] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 57) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Cluster zones together: penalize being too far from existing zones
            zone_score = np.where(min_zone_dist < 3, 500.0,
                         np.where(min_zone_dist > 25, min_zone_dist * 0.5, 0.0))
        else:
            zone_score = np.zeros(len(cxs_arr))

        # Prefer near roads, cluster with existing zones
        score = road_dist * 1.5 + zone_score * 0.5

        order = np.argsort(score)
        # Vary starting point with step + pop for diversity
        off = (step * 11 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 5: Civic services based on population ----
    if pop > 100:
        fire_spots = [(fx, fy) for fy in range(12, 92, 12) for fx in range(12, 110, 16)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_spots = [(px2, py2) for py2 in range(14, 90, 14) for px2 in range(14, 108, 18)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_spots = [(pkx, pky) for pky in range(16, 88, 10) for pkx in range(16, 106, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 1000:
        stadium_spots = [(sx, sy) for sy in range(18, 86, 22) for sx in range(18, 102, 26)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuclear_spots = [(nx, ny) for ny in range(14, 88, 22) for nx in range(14, 108, 22)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0 = max(0, npx - 13)
                x1 = min(WORLD_W, npx + 14)
                y0 = max(0, npy - 13)
                y1 = min(WORLD_H, npy + 14)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 3000:
        airport_spots = [(57, 8), (57, 91), (8, 50), (111, 50)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 4000:
        seaport_spots = [(8, 50), (111, 50), (57, 5), (57, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Extend wire toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Extend road toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2,:] = False
    road_cand2[WORLD_H-2:,:] = False
    road_cand2[:,0:2] = False
    road_cand2[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(8,0),(-8,0),(0,8),(0,-8),(6,0),(-6,0),(0,6),(0,-6)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Compact grid layout with strong road network first,
# then balanced RCI zoning, civic services early, multiple power plants
# Key differences from parent:
# - Use a cross/grid road pattern instead of spine wires
# - Place roads FIRST then wire alongside them
# - More commercial/industrial bias early for tax revenue
# - Civic services placed proactively based on zone count not just pop
# - Tighter neighborhood spacing for denser coverage

def init(obs, state):
    """Bootstrap: central coal plant + cross roads + connecting wires."""
    actions = []
    cx, cy = 60, 50
    # Central coal plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire ring around plant
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads parallel to wire (for zone access)
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, cx + dx, cy - 2))
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Grid of neighborhoods with 12-unit spacing
    # Offset from edges to leave room for 3x3 zones
    nh_xs = list(range(10, 115, 12))  # ~9 cols
    nh_ys = list(range(10, 95, 12))   # ~8 rows
    all_hoods = [(x, y) for y in nh_ys for x in nh_xs]

    # Scale active neighborhoods with population
    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 8
        if pop < 500:   return 16
        if pop < 1000:  return 28
        if pop < 2000:  return 45
        if pop < 5000:  return 60
        if pop < 10000: return 72
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick evenly spaced hoods
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS near each neighborhood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find nearest empty tile for plant
            for r in range(1, 12):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            if pop > 8000 and funds > 15000:
                                return (Tool.NUCLEARPOWER, nx, ny)
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # Build road grid: horizontal roads every 6 rows, vertical roads every 6 cols
    # centered on hood positions
    # ---- PHASE 2: ROAD GRID ----
    # For each active hood, lay horizontal road at hy and vertical at hx
    road_radius = 10
    for (hx, hy) in active_hoods:
        # Horizontal road at hy
        for dx in range(-road_radius, road_radius + 1):
            rx, ry = hx + dx, hy
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]): continue
            if not bool(rm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)

        # Vertical road at hx
        for dy in range(-road_radius, road_radius + 1):
            rx, ry = hx, hy + dy
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]): continue
            if not bool(rm[ry, rx]) and not bool(wm[ry, rx]):
                if bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- PHASE 3: WIRE alongside roads for power distribution ----
    wire_radius = 10
    for (hx, hy) in active_hoods:
        # Wire at hy-1 (parallel to horizontal road at hy)
        for wry in [hy - 1, hy + 1]:
            if not ib(hx, wry): continue
            for dx in range(-wire_radius, wire_radius + 1):
                wx, wy = hx + dx, wry
                if not ib(wx, wy): continue
                if bool(pm[wy, wx]): continue
                if bool(wm[wy, wx]): continue
                if not bool(em[wy, wx]): continue
                # Only place wire if adjacent to existing wire or plant
                has_adj = False
                for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = wx+adx, wy+ady
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        has_adj = True
                        break
                if has_adj:
                    return (Tool.WIRE, wx, wy)

        # Wire at hx-1 or hx+1 (parallel to vertical road at hx)
        for wrx in [hx - 1, hx + 1]:
            if not ib(wrx, hy): continue
            for dy in range(-wire_radius, wire_radius + 1):
                wx, wy = wrx, hy + dy
                if not ib(wx, wy): continue
                if bool(pm[wy, wx]): continue
                if bool(wm[wy, wx]): continue
                if not bool(em[wy, wx]): continue
                has_adj = False
                for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = wx+adx, wy+ady
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        has_adj = True
                        break
                if has_adj:
                    return (Tool.WIRE, wx, wy)

    # ---- PHASE 4: CONNECT WIRE BETWEEN NEIGHBORHOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            # Connect horizontally adjacent hoods
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1 - 1): continue
                    if bool(wm[hy1-1, cx2]) or bool(pm[hy1-1, cx2]): continue
                    if not bool(em[hy1-1, cx2]): continue
                    has_adj = False
                    for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ax, ay = cx2+adx, hy1-1+ady
                        if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                            has_adj = True; break
                    if has_adj:
                        return (Tool.WIRE, cx2, hy1 - 1)
            # Connect vertically adjacent hoods
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 14:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1 - 1, cy2): continue
                    if bool(wm[cy2, hx1-1]) or bool(pm[cy2, hx1-1]): continue
                    if not bool(em[cy2, hx1-1]): continue
                    has_adj = False
                    for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                        ax, ay = hx1-1+adx, cy2+ady
                        if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                            has_adj = True; break
                    if has_adj:
                        return (Tool.WIRE, hx1 - 1, cy2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 35% res, 35% com, 30% ind - more commercial than parent
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Precompute road neighbor mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Precompute power neighbor mask
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: CIVIC SERVICES - place early based on zone count ----
    # Fire stations every ~20 zones
    if total_zones > 5 or pop > 50:
        fire_grid_xs = list(range(15, 115, 20))
        fire_grid_ys = list(range(15, 95, 20))
        for fy in fire_grid_ys:
            for fx in fire_grid_xs:
                if ib(fx, fy) and bool(em[fy, fx]) and not bool(pm[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if total_zones > 20 or pop > 200:
        police_grid_xs = list(range(20, 115, 25))
        police_grid_ys = list(range(20, 95, 25))
        for py in police_grid_ys:
            for px in police_grid_xs:
                if ib(px, py) and bool(em[py, px]) and not bool(pm[py, px]):
                    return (Tool.POLICESTATION, px, py)

    if pop > 500 or total_zones > 50:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70), (60, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(5, 85), (115, 85), (5, 15), (115, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 5), (75, 5), (45, 92), (75, 92)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 7: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: PARKS ----
    if pop > 100 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 13) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place plant for uncovered hoods ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant cluster + wire cross + road access"""
    actions = []
    # Place coal plants in a ring around center
    centers = [
        (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
        (10, 50), (110, 50), (60, 15), (60, 85),
    ]
    for px, py in centers:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [15, 25, 35, 50, 65, 75, 85]:
        for x in range(2, 118):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [15, 30, 45, 60, 75, 90, 105]:
        for y in range(2, 98):
            actions.append((Tool.WIRE, wx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 40% res, 35% com, 25% ind (more commercial than parent)
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Road grid: denser spacing between wire spines
    wire_rows = [15, 25, 35, 50, 65, 75, 85]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]
    road_rows = [19, 22, 29, 32, 39, 42, 46, 53, 57, 61, 68, 71, 79, 82, 89, 93]
    road_cols = [5, 8, 20, 23, 37, 40, 52, 55, 67, 70, 83, 86, 98, 101, 112, 115]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure power plants exist in sparse regions
    if phase == 0:
        plant_targets = []
        for py in range(10, 95, 20):
            for px in range(10, 115, 20):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1-2: Fill wire row gaps
    if phase in (1, 2):
        target_rows = wire_rows if phase == 1 else [20, 30, 42, 57, 70, 80, 90]
        for wr in target_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 3-4: Fill wire col gaps
    if phase in (3, 4):
        target_cols = wire_cols if phase == 3 else [22, 37, 52, 67, 82, 97, 112]
        for wc in target_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 5: Horizontal roads
    if phase == 5:
        for rr in road_rows:
            if not (0 < rr < WORLD_H):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]) and not bool(wm[rr, rx]):
                    adj = (rx > 0 and bool(rm[rr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or \
                          (rr > 0 and bool(rm[rr-1, rx])) or \
                          (rr < WORLD_H-1 and bool(rm[rr+1, rx]))
                    if adj or rx == 1:
                        return (Tool.ROAD, rx, rr)

    # Phase 6: Vertical roads
    if phase == 6:
        for rc in road_cols:
            if not (0 < rc < WORLD_W):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]) and not bool(wm[ry, rc]):
                    adj = (ry > 0 and bool(rm[ry-1, rc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or \
                          (rc > 0 and bool(rm[ry, rc-1])) or \
                          (rc < WORLD_W-1 and bool(rm[ry, rc+1]))
                    if adj or ry == 1:
                        return (Tool.ROAD, rc, ry)

    # Phase 7: Wire unpowered roads toward power
    if phase == 7:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Wire unpowered zones
    if phase == 8:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 9: Road to unroaded zones
    if phase == 9:
        unroaded_zones = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded_zones)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled to pop ----
    if pop > 10:
        fire_spots = [
            (8,8),(58,8),(110,8),(8,50),(110,50),(8,92),(58,92),(110,92),
            (33,25),(83,25),(33,75),(83,75),(58,50),
            (20,40),(95,40),(20,60),(95,60),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (15,12),(45,12),(75,12),(105,12),
            (15,37),(45,37),(75,37),(105,37),
            (15,62),(45,62),(75,62),(105,62),
            (15,87),(45,87),(75,87),(105,87),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 250:
        stadium_spots = [
            (28,18),(78,18),(28,48),(78,48),
            (28,72),(78,72),(28,92),(78,92),
            (53,30),(103,30),(53,70),(103,70),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 400:
        # Upgrade some coal to nuclear
        nuke_spots = [
            (60,50),(30,25),(90,25),(30,75),(90,75),
            (10,50),(110,50),(60,15),(60,85),
            (5,5),(115,5),(5,95),(115,95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5,90),(115,90),(5,10),(115,10),(60,5),(60,95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45),(5,55),(110,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value near high-density zones
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        # Exclude wire/road corridor rows
        for wr in wire_rows + road_rows:
            if 0 <= wr < WORLD_H:
                park_cands[max(0, wr-1):min(WORLD_H, wr+2), :] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (closed-loop, reacts to pop) ----
    all_excl_rows = wire_rows + road_rows
    all_excl_cols = wire_cols + road_cols

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in all_excl_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in all_excl_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Use multiple neighborhoods, expanding as pop grows
        if pop < 80:
            # Start with 3 distinct neighborhoods: center, NW, SE
            active_centers = [
                (60, 50), (55, 45), (65, 45), (55, 55), (65, 55),
                (50, 50), (70, 50), (60, 42), (60, 58),
                (25, 20), (35, 20), (25, 30), (35, 30),
                (85, 70), (95, 70), (85, 80), (95, 80),
            ]
        elif pop < 300:
            # Expand to 5 neighborhoods
            active_centers = []
            for (cx, cy) in [(30, 25), (90, 25), (60, 50), (30, 75), (90, 75)]:
                for dy in range(-12, 13, 6):
                    for dx in range(-12, 13, 6):
                        active_centers.append((cx+dx, cy+dy))
        elif pop < 800:
            # Grid of neighborhoods
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 12 + col * 14
                    cy = 12 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 2000:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 8 + col * 11
                    cy = 8 + row * 11
                    active_centers.append((cx, cy))
        else:
            # Full dense coverage
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 1500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along vertical wire
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Flanking roads along horizontal wire
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: denser, more coverage ----
    # 8 cols x 7 rows = 56 neighborhoods
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [10, 24, 38, 52, 66, 80, 92]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 8
        if pop < 600:   return 14
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 42
        if pop < 7000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MAPS (reactive, based on current tile_map) ----
    # Road coverage within 3 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage within 6 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: EXTEND WIRE FROM EXISTING WIRE/PLANT ----
    # Reactively extend wire toward uncovered hoods
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if not bool(nbr_power[hy, hx]):
            # Find nearest wire/plant and extend toward this hood
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) == 0:
                continue
            dists = np.abs(wire_xs - hx) + np.abs(wire_ys - hy)
            nearest_idx = int(np.argmin(dists))
            wx, wy = int(wire_xs[nearest_idx]), int(wire_ys[nearest_idx])
            # Step toward hood
            step_dx = int(np.sign(hx - wx))
            step_dy = int(np.sign(hy - wy))
            # Try horizontal then vertical
            candidates = []
            if step_dx != 0:
                candidates.append((wx + step_dx, wy))
            if step_dy != 0:
                candidates.append((wx, wy + step_dy))
            for (nx, ny) in candidates:
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: WIRE SPINES for each hood ----
    spine_range = 10
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical wire spine at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal wire spine at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 4: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and hx2 > hx1 and hx2 - hx1 <= 22:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and hy2 > hy1 and hy2 - hy1 <= 22:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 5: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods) // 2 + 1, 1) != 0:
            continue
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 45% RES, 27% COM, 28% IND
        if ir < 0.26:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to pop level) ----
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 16) for fy in range(12, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 20) for py2 in range(15, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadiums = [
            (30, 30), (60, 30), (90, 30),
            (30, 55), (60, 55), (90, 55),
            (30, 75), (60, 75), (90, 75),
            (15, 15), (105, 15), (15, 85), (105, 85)
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94), (6, 45), (6, 65), (114, 45), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop cities ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (10, 50), (110, 50), (60, 10), (60, 90),
            (20, 10), (100, 10), (20, 90), (100, 90),
            (45, 40), (75, 40), (45, 60), (75, 60)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value (reactive: only in powered+road areas) ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire spines + flanking roads"""
    actions = []
    # Four power plants at strategic quadrant positions
    for px, py in [(20, 25), (80, 25), (20, 75), (80, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 60, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire spines (horizontal)
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 50:
            if ir < 0.35:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 500:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.25:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Infrastructure corridors
    wire_rows = [10, 25, 40, 55, 70, 85, 95]
    wire_cols = [12, 24, 36, 48, 60, 72, 84, 96, 108]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- REACTIVE INFRASTRUCTURE ---
    # Fix missing wire on horizontal spines
    if step % 6 == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Fix missing wire on vertical spines
    if step % 6 == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Fix missing roads flanking wire rows
    if step % 6 == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                                   (ry > 0 and bool(rm[ry-1, rx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # Fix missing vertical roads flanking wire cols
    if step % 6 == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                                   bool(rm[ry, max(0, rcx-1)]) or
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # Place coal plants reactively where coverage is missing
    if step % 6 == 4:
        plant_targets = []
        for py in range(12, WORLD_H - 5, 18):
            for px in range(12, WORLD_W - 5, 20):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
            y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 6):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Wire unpowered zones reactively
    if step % 6 == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Road to unroaded zones reactively
    if step % 9 == 7:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES (pop-gated, reactive to empty spots) ---
    if pop > 30:
        fire_spots = [
            (6,6),(35,6),(65,6),(95,6),(113,6),
            (6,30),(113,30),(6,50),(113,50),
            (6,70),(113,70),(6,93),(35,93),(65,93),(95,93),(113,93),
            (35,50),(65,50),(95,50),(50,20),(80,20),(50,80),(80,80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (20,15),(50,15),(80,15),(110,15),
            (20,35),(50,35),(80,35),(110,35),
            (20,55),(50,55),(80,55),(110,55),
            (20,75),(50,75),(80,75),(110,75),
            (10,50),(60,20),(60,80),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(30,20),(90,20),(30,80),(90,80),(60,50),(15,50),(105,50),(60,10),(60,90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (10,50),(110,50),(60,5),(60,95),
            (10,20),(110,20),(10,80),(110,80),
            (35,10),(85,10),(35,90),(85,90),
            (35,50),(85,50),(60,30),(60,70),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5,95),(115,95),(5,5),(115,5),(60,95),(60,5),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45),(5,55),(115,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 7 == 3:
        park_cands_mask = em & near_road & near_power
        pys, pxs = np.where(park_cands_mask)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- REACTIVE ZONE PLACEMENT ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road infrastructure corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active zone centers scale with population
        if pop < 100:
            active_centers = [
                (60,50),(45,50),(75,50),(60,38),(60,62),
                (30,50),(90,50),(60,25),(60,75),
                (45,38),(75,38),(45,62),(75,62),
            ]
        elif pop < 500:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 12 + row * 19
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 8 + col * 13
                    cy = 8 + row * 12
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 6 + col * 11
                    cy = 6 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area from existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spines and flanking roads."""
    actions = []
    # 3 coal plants at cols 20, 60, 100; row 50
    for px in [20, 60, 100]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Power plant anchor positions: 3x4 grid
    plant_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [20, 40, 60, 80]:
            plant_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 4
        if pop < 300:  return 6
        if pop < 600:  return 8
        if pop < 1000: return 10
        return 12

    n_active = num_active()
    active_anchors = plant_anchors[:n_active]

    # ---- ENSURE POWER PLANTS at active anchors ----
    for (px, py) in active_anchors:
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Find nearest empty spot
        for r in range(0, 10):
            found = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r and r != 0:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
                if found:
                    break

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # ---- WIRE SPINES: vertical at each anchor column ----
    spine_half = min(35, 10 + pop // 10)
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        # Check coverage
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy in range(-5, 6):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            mx_wr = max(wire_in_col)
            mn_wr = min(wire_in_col)
            if mx_wr < spine_bot:
                nr = mx_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if mn_wr > spine_top:
                nr = mn_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row level ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([px for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            wc1, wc2 = row_anchors[i], row_anchors[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting row levels in same column ----
    for col_x in sorted(set(px for (px, _) in active_anchors)):
        col_rows = sorted([py for (px, py) in active_anchors if px == col_x])
        for i in range(len(col_rows) - 1):
            py1, py2 = col_rows[i], col_rows[i + 1]
            for cy in range(py1 + 1, py2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    return (Tool.WIRE, col_x, cy)

    # ---- ROAD BUILDING: flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        for side_dx in [-1, 1]:
            rx = px + side_dx
            if not ib(rx, py):
                continue
            cycle = (step + idx * 7) % 4
            for wr in wire_in_col[cycle::4]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

    # ---- HORIZONTAL ROADS at y-levels ----
    if pop > 10:
        for yl in y_levels:
            row_pxs = sorted([px for (px, py) in active_anchors if py == yl])
            if len(row_pxs) < 2:
                continue
            x_left = row_pxs[0] - 1
            x_right = row_pxs[-1] + 1
            for horiz_y in [yl - 3, yl + 3]:
                if not (0 < horiz_y < WORLD_H - 1):
                    continue
                for cx in range(x_left, x_right + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- VERTICAL ROADS connecting y-levels ----
    if pop > 50 and len(y_levels) >= 2:
        for col_x in sorted(set(px for (px, _) in active_anchors)):
            for rx in [col_x - 3, col_x + 3]:
                if not ib(rx, 2):
                    continue
                yl_list = sorted(y_levels)
                for i in range(len(yl_list) - 1):
                    y1v, y2v = yl_list[i], yl_list[i + 1]
                    for cy in range(y1v, y2v + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Neighbor masks
    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(wm | pm, 5)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) * 1.0
                 + np.abs(cys - py).astype(float) * 0.8)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing road into powered area ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 15), (35, 15), (75, 15), (108, 15),
            (8, 35), (35, 35), (75, 35), (108, 35),
            (8, 55), (35, 55), (75, 55), (108, 55),
            (8, 75), (35, 75), (75, 75), (108, 75),
            (8, 92), (35, 92), (75, 92), (108, 92),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (22, 10), (55, 10), (88, 10),
            (22, 30), (55, 30), (88, 30),
            (22, 50), (55, 50), (88, 50),
            (22, 70), (55, 70), (88, 70),
            (22, 90), (55, 90), (88, 90),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 10), (50, 10), (90, 10),
            (10, 50), (50, 50), (90, 50),
            (10, 90), (50, 90), (90, 90),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]
        for sx2, sy2 in seaports:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (110, 45)]
        for ax, ay in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PARKS to boost land value ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % max(len(wire_xs3), 1)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire connections + initial roads"""
    actions = []
    # Primary plant at (55, 50)
    actions.append((Tool.COALPOWER, 55, 50))
    # Wire spine going up and down from plant
    for y in range(47, 35, -1):
        actions.append((Tool.WIRE, 57, y))
    for y in range(53, 65):
        actions.append((Tool.WIRE, 57, y))
    # Horizontal wire to connect second plant
    for x in range(58, 75):
        actions.append((Tool.WIRE, x, 50))
    # Second plant at (75, 50)
    actions.append((Tool.COALPOWER, 75, 50))
    # Initial roads flanking left wire spine
    for y in range(38, 62):
        actions.append((Tool.ROAD, 56, y))
        actions.append((Tool.ROAD, 58, y))
    return actions


def act(obs, state):
    """
    Dual-neighborhood city:
    - Left cluster around x=55 (wire spine at x=57, roads at x=56 and x=58)
    - Right cluster around x=75 (wire spine at x=77, roads at x=76 and x=78)
    - Balanced R/C/I zoning
    - Reactive: reads tile_map each step
    """
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Ensure primary power plant exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, 55, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs)) if len(plant_xs) > 0 else 55
    py = int(np.mean(plant_ys)) if len(plant_ys) > 0 else 50

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Zone type picker: aim for ~30% industrial, ~30% commercial, ~40% residential
    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        if i_r < 0.28:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Two wire spines
    left_wire_col = 57
    right_wire_col = 77

    # Two pairs of road columns
    left_road_l = 56
    left_road_r = 58
    right_road_l = 76
    right_road_r = 78

    # Extent of spines based on population
    pop_factor = min(25, obs.city_pop // 20)
    spine_top = max(3, 50 - 12 - pop_factor)
    spine_bot = min(WORLD_H - 4, 50 + 12 + pop_factor)

    def grow_wire_spine(wcol, top, bot):
        """Try to grow the wire spine at wcol between top and bot. Return action or None."""
        rows_with_wire = [r for r in range(WORLD_H) if in_bounds(wcol, r) and bool(wm[r, wcol])]
        if not rows_with_wire:
            # Seed wire near plant row
            seed_y = 50
            if in_bounds(wcol, seed_y) and not bool(pm[seed_y, wcol]):
                return (Tool.WIRE, wcol, seed_y)
            return None
        min_wr = min(rows_with_wire)
        max_wr = max(rows_with_wire)
        if max_wr < bot:
            nr = max_wr + 1
            if in_bounds(wcol, nr) and (bool(em[nr, wcol]) or bool(wm[nr, wcol])) and not bool(pm[nr, wcol]):
                return (Tool.WIRE, wcol, nr)
        if min_wr > top:
            nr = min_wr - 1
            if in_bounds(wcol, nr) and (bool(em[nr, wcol]) or bool(wm[nr, wcol])) and not bool(pm[nr, wcol]):
                return (Tool.WIRE, wcol, nr)
        return None

    # Step-based priority switching
    step = obs.step
    phase = step % 6

    if phase < 2:
        # Grow left wire spine
        act_result = grow_wire_spine(left_wire_col, spine_top, spine_bot)
        if act_result:
            return act_result
    elif phase < 4:
        # Grow right wire spine
        act_result = grow_wire_spine(right_wire_col, spine_top, spine_bot)
        if act_result:
            return act_result
    else:
        # Build roads flanking both spines
        for wcol, rl, rr in [(left_wire_col, left_road_l, left_road_r),
                              (right_wire_col, right_road_l, right_road_r)]:
            wire_rows = [r for r in range(WORLD_H) if in_bounds(wcol, r) and bool(wm[r, wcol])]
            if wire_rows:
                step_k = (step * 7) % max(len(wire_rows), 1)
                for i in range(min(len(wire_rows), 30)):
                    wr = wire_rows[(step_k + i) % len(wire_rows)]
                    if in_bounds(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                        return (Tool.ROAD, rl, wr)
                    if in_bounds(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                        return (Tool.ROAD, rr, wr)

    # Also try growing both spines as fallback
    for wcol in [left_wire_col, right_wire_col]:
        act_result = grow_wire_spine(wcol, spine_top, spine_bot)
        if act_result:
            return act_result

    # --- Horizontal wire bridge connecting two spines ---
    bridge_y = 50
    for x in range(left_wire_col, right_wire_col + 1):
        if in_bounds(x, bridge_y) and bool(em[bridge_y, x]) and not bool(pm[bridge_y, x]):
            return (Tool.WIRE, x, bridge_y)

    # --- Third cluster if population growing ---
    if obs.city_pop > 500:
        # Add third wire spine further right
        third_wire_col = 97
        third_road_l = 96
        third_road_r = 98
        act_result = grow_wire_spine(third_wire_col, spine_top, spine_bot)
        if act_result:
            return act_result
        # Wire from right plant to third spine
        for x in range(right_wire_col + 3, third_wire_col):
            if in_bounds(x, bridge_y) and bool(em[bridge_y, x]) and not bool(pm[bridge_y, x]):
                return (Tool.WIRE, x, bridge_y)
        # Roads for third spine
        wire_rows_3 = [r for r in range(WORLD_H) if in_bounds(third_wire_col, r) and bool(wm[r, third_wire_col])]
        if wire_rows_3:
            for wr in wire_rows_3:
                if in_bounds(third_road_l, wr) and bool(em[wr, third_road_l]):
                    return (Tool.ROAD, third_road_l, wr)
                if in_bounds(third_road_r, wr) and bool(em[wr, third_road_r]):
                    return (Tool.ROAD, third_road_r, wr)

    # --- Build proximity masks for zone placement ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Place zones near roads and power ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near both wire spines
        dists_left = np.abs(cxs - left_wire_col) + np.abs(cys - 50) // 3
        dists_right = np.abs(cxs - right_wire_col) + np.abs(cys - 50) // 3
        dists = np.minimum(dists_left, dists_right)
        order = np.argsort(dists)
        step_off = int(step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Extend roads near wire to fill gaps ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 25)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Services at appropriate thresholds ---
    if obs.city_pop > 200:
        for fpos in [(45, 40), (65, 40), (85, 40)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 400:
        for ppos in [(45, 60), (65, 60), (85, 60)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 800:
        # Add stadium for commercial growth
        for spos in [(60, 35), (80, 35)]:
            ssx, ssy = spos
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    # --- Expand wire laterally as fallback ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
