def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure enough power plants distributed across map ----
    # Grid of plants every 20 tiles, offset to avoid roads
    plant_positions = []
    for py in range(12, 95, 20):
        for px in range(12, 115, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire from power sources toward unpowered areas ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and not bool(near_power[py, px])]

    if len(wxs) > 0:
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:15])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0 and total_zones < 300:
            rng_idx = list(range(min(60, len(upxs))))
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in rng_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Dense road grid every 5 tiles ----
    road_grid_h = list(range(8, 97, 5))   # horizontal road rows
    road_grid_v = list(range(8, 115, 5))  # vertical road cols

    # Build roads adjacent to existing roads, prioritizing near-power areas
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1:   shifted[:-1, :] = rm[1:, :]
        elif dy == 1:  shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    # Find missing road grid positions with power
    uncovered_road = []
    for gy in road_grid_h:
        for gx in road_grid_v:
            if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]):
                uncovered_road.append((gx, gy))

    if uncovered_road:
        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:50]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:15]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement with better commercial/industrial balance ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        score = road_dist * 1.0 + np.maximum(0, 12 - zone_dist) * 2.0

        order = np.argsort(score)
        # Vary offset based on step to spread zones
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Tool selection: 50% res, 25% com, 25% ind
        # React to current ratios
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        step_mod = step % 4
        if ir < 0.20:
            tool = Tool.INDUSTRIAL
        elif cr < 0.25:
            tool = Tool.COMMERCIAL
        elif step_mod < 2:
            tool = Tool.RESIDENTIAL
        elif step_mod == 2:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

        # If commercial districts are needed near city center, place them there
        if total_zones > 50 and cr < 0.30 and step_mod >= 2:
            tool = Tool.COMMERCIAL
        if total_zones > 50 and ir < 0.20:
            tool = Tool.INDUSTRIAL

        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled to population ----
    if pop > 40:
        fire_grid = [(fx, fy) for fy in range(10, 95, 8) for fx in range(10, 115, 8)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 10)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(7, 95, 7) for pkx in range(7, 115, 7)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(25, 25), (65, 25), (100, 25),
                        (25, 50), (65, 50), (100, 50),
                        (25, 75), (65, 75), (100, 75)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        nuke_locs = [(25, 20), (95, 20), (25, 80), (95, 80),
                     (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 6), min(WORLD_W, nx + 7)
                y0, y1 = max(0, ny - 6), min(WORLD_H, ny + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(8, 8), (100, 8), (8, 88), (100, 88), (55, 8)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(8, 50), (112, 50), (60, 8), (60, 92)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend roads near power ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, -2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with wire cross and road grid."""
    actions = []
    # Two power plants for better coverage
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire horizontal spine connecting both plants
    for x in range(30, 91):
        if not (x in (40, 80)):
            actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(38, 63):
        if y != 50:
            actions.append((Tool.WIRE, 40, y))
            actions.append((Tool.WIRE, 80, y))
    # Roads parallel to wire spines
    for x in range(30, 91):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(38, 63):
        actions.append((Tool.ROAD, 36, y))
        actions.append((Tool.ROAD, 44, y))
        actions.append((Tool.ROAD, 76, y))
        actions.append((Tool.ROAD, 84, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # --- NEIGHBORHOOD GRID: denser, more spread out ---
    # 3 rows x 7 cols = 21 hoods, wider spacing on x
    all_hoods = []
    for hy in range(15, 90, 25):
        for hx in range(15, 115, 16):
            all_hoods.append((hx, hy))
    # Add inner ring for density
    for hy in range(30, 75, 20):
        for hx in range(22, 100, 20):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:    return 4
        if pop < 150:   return 7
        if pop < 400:   return 12
        if pop < 800:   return 18
        if pop < 1500:  return 25
        if pop < 3000:  return 32
        return len(all_hoods)

    n_active = num_active_hoods()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: POWER PLANTS (coarser grid, place when needed) ---
    if funds > 2000:
        plant_positions = []
        for py in range(18, 92, 28):
            for px in range(18, 110, 28):
                plant_positions.append((px, py))

        for (ppx, ppy) in plant_positions:
            x0, x1 = max(0, ppx - 9), min(WORLD_W, ppx + 10)
            y0, y1 = max(0, ppy - 9), min(WORLD_H, ppy + 10)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(9):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: WIRE GRID (connect plants to neighborhoods) ---
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 12)
        spine_bot   = min(WORLD_H - 3, hy + 12)
        spine_left  = max(2, hx - 12)
        spine_right = min(WORLD_W - 3, hx + 12)

        # Vertical spine at hx
        col_wire = [r for r in range(spine_top, spine_bot + 1)
                    if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        if col_wire:
            min_wr, max_wr = min(col_wire), max(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal spine at hy
        row_wire = [c for c in range(spine_left, spine_right + 1)
                    if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wire:
            min_wc, max_wc = min(row_wire), max(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT ADJACENT HOODS WITH WIRES ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if j <= i:
                continue
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist > 32:
                continue
            if abs(hy1 - hy2) <= 3:
                mid_y = (hy1 + hy2) // 2
                for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
            if abs(hx1 - hx2) <= 3:
                mid_x = (hx1 + hx2) // 2
                for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                        return (Tool.WIRE, mid_x, cy)

    # --- PHASE 4: ROAD GRID (closer to wire spines for denser coverage) ---
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        # Roads at ±2 and ±5 from vertical spine for wider coverage
        for rx in [hx - 2, hx + 2, hx - 5, hx + 5]:
            if not ib(rx, hy) or not col_wire:
                continue
            cyc = step % 5
            for wr in col_wire[cyc::5]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2, hy - 5, hy + 5]:
            if not ib(hx, ry) or not row_wire:
                continue
            cyc = (step + 2) % 5
            for wc in row_wire[cyc::5]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT with aggressive commercial/industrial mix ---
    def pick_tool():
        """Aggressive commercial + industrial: 30% RES, 35% COM, 35% IND."""
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        # Prioritize commercial early for tax revenue
        if pop < 200:
            if c_r < 0.35: return Tool.COMMERCIAL
            if i_r < 0.33: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        # Balance at higher pop
        if i_r < 0.32: return Tool.INDUSTRIAL
        if c_r < 0.33: return Tool.COMMERCIAL
        if r_r < 0.35: return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (within 3 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # Slightly prefer clustering zones together
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 11 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES (earlier than parent) ---
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(15, 95, 18)
                     for fx in range(15, 112, 20)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 50:
        police_grid = [(px2, py2) for py2 in range(18, 90, 20)
                       for px2 in range(18, 108, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        stadium_locs = [
            (25, 20), (60, 15), (95, 20),
            (15, 50), (60, 50), (105, 50),
            (25, 80), (60, 85), (95, 80),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power upgrade when affordable
    if pop > 800 and funds > 5000:
        nuclear_locs = [
            (8, 8), (112, 8), (8, 92), (112, 92),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-6), min(WORLD_W, npx+7)
            y0b, y1b = max(0, npy-6), min(WORLD_H, npy+7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 30), (5, 70), (115, 30), (115, 70)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1200:
        airport_locs = [(8, 8), (102, 8), (8, 85), (102, 85), (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from plants ---
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants at center-left and center-right, wire spine, roads"""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires up and down from each plant
    for y in range(43, 50):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    for y in range(51, 58):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Horizontal roads above and below the power line
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 42))
        actions.append((Tool.ROAD, x, 58))
    # Vertical roads
    for y in range(38, 63):
        actions.append((Tool.ROAD, 30, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 90, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Target zone mix: 50% res, 30% com, 20% ind
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Place coal plants in a denser grid ---
    # Use a 20-tile spacing to cover the map
    plant_positions = []
    for py in range(15, 95, 20):
        for px in range(15, 115, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire expansion toward unpowered areas ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Look for unpowered plant locations first
        unpowered_plants = [(px, py) for px, py in plant_positions
                            if ib(px, py) and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Then wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Road grid at spacing 6 (denser than parent's 5, covers map differently) ---
    road_targets = []
    # Horizontal roads every 6 rows
    for gy in range(6, 98, 6):
        for gx in range(3, 118):
            road_targets.append((gx, gy))
    # Vertical roads every 8 cols
    for gx in range(8, 116, 8):
        for gy in range(3, 98):
            road_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        # Find road tile adjacent to existing road and within powered area
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:60]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement with closed-loop mix ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Prefer close to road, prefer spreading from existing zones (bigger spread than parent)
        score = road_dist * 2.0 + np.maximum(0, 6 - zone_dist) * 1.5

        order = np.argsort(score)

        # Closed-loop tool selection: vary based on actual ratios read from obs
        tool = pick_tool()

        # Secondary override: cycle through types to ensure variety
        if total_zones > 0:
            step_cycle = step % 15
            if step_cycle < 7:
                candidate = Tool.RESIDENTIAL
            elif step_cycle < 11:
                candidate = Tool.COMMERCIAL
            else:
                candidate = Tool.INDUSTRIAL
            # Only use cycle if ratio not too off
            ir = ind_count / max(total_zones, 1)
            cr = com_count / max(total_zones, 1)
            if ir >= 0.15 and cr >= 0.25:
                tool = candidate

        off = (step * 17 + pop * 11) % max(len(order), 1)
        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population (closed-loop on pop) ---
    if pop > 60:
        fire_positions = [(fx, fy) for fy in range(9, 95, 9) for fx in range(9, 115, 9)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_positions = [(px2, py2) for py2 in range(12, 92, 12) for px2 in range(12, 112, 12)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_positions = [(pkx, pky) for pky in range(6, 96, 6) for pkx in range(6, 116, 6)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 80), (60, 80), (100, 80),
                        (20, 50), (100, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        # Upgrade some coal to nuclear
        nuke_locs = [(30, 50), (90, 50), (60, 25), (60, 75),
                     (15, 25), (105, 25), (15, 75), (105, 75)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(50, 8), (70, 8), (50, 91), (70, 91),
                        (8, 25), (111, 25), (8, 70), (111, 70)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(8, 50), (111, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: lay roads near power plants ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

# Different strategy: denser grid, 3-zone mix from start, horizontal wire backbone,
# roads before zones, more aggressive civic services at lower thresholds

def init(obs, state):
    """Bootstrap: 2 coal plants with horizontal wire backbone and flanking roads."""
    actions = []
    # 2 plants at y=50, x=30 and x=90
    for px in [30, 90]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine through center
        for dx in range(-20, 21):
            if dx != 0:
                actions.append((Tool.WIRE, px + dx, py))
        # Vertical roads flanking each plant
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 columns x 5 rows = 30 neighborhoods (denser than parent's 5x4)
    nh_cols = [15, 33, 55, 75, 95, 112]
    nh_rows = [15, 32, 50, 68, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 20
        if pop < 3000:  return 25
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Precompute power proximity (wire or plant within 5 cells)
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Road proximity (within 3)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: HORIZONTAL WIRE BACKBONE across all rows ----
    # Primary strategy: horizontal wires at each hood row
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        if len(row_hoods) < 2:
            continue
        row_hoods.sort(key=lambda h: h[0])
        xl = row_hoods[0][0]
        xr = row_hoods[-1][0]
        # Find plant near this row to anchor wire
        x0b, x1b = max(0, xl - 15), min(WORLD_W, xr + 16)
        y0b, y1b = max(0, hy_row - 15), min(WORLD_H, hy_row + 16)
        plant_ys, plant_xs = np.where(pm[y0b:y1b, x0b:x1b])
        if len(plant_xs) > 0:
            px_loc = int(plant_xs[0]) + x0b
            py_loc = int(plant_ys[0]) + y0b
            # Wire vertically from plant to hood row
            if py_loc != hy_row:
                sd = 1 if hy_row > py_loc else -1
                for wy in range(py_loc + sd, hy_row + sd, sd):
                    if not ib(px_loc, wy): continue
                    if bool(pm[wy, px_loc]) or bool(wm[wy, px_loc]): continue
                    if not bool(em[wy, px_loc]): continue
                    return (Tool.WIRE, px_loc, wy)
        # Horizontal wire across the row
        for cx2 in range(max(2, xl), min(WORLD_W - 2, xr + 1)):
            if ib(cx2, hy_row) and bool(em[hy_row, cx2]) and not bool(pm[hy_row, cx2]) and not bool(wm[hy_row, cx2]):
                return (Tool.WIRE, cx2, hy_row)

    # ---- PHASE 3: VERTICAL WIRE connecting rows at each column ----
    if n_active >= 4:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for cy2 in range(hy1 + 1, hy2):
                    if ib(hx_col, cy2) and bool(em[cy2, hx_col]) and not bool(pm[cy2, hx_col]) and not bool(wm[cy2, hx_col]):
                        return (Tool.WIRE, hx_col, cy2)

    # ---- PHASE 4: ROADS — horizontal at +/-3 from hood rows ----
    # Build roads eagerly (before zones) to ensure access
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        if not row_hoods:
            continue
        row_hoods.sort(key=lambda h: h[0])
        xl = row_hoods[0][0] - 2
        xr = row_hoods[-1][0] + 2
        for horiz_y in [hy_row - 3, hy_row + 3]:
            if not ib(0, horiz_y):
                continue
            for cx3 in range(max(2, xl), min(WORLD_W - 2, xr + 1)):
                if ib(cx3, horiz_y) and bool(em[horiz_y, cx3]) and not bool(pm[horiz_y, cx3]) and not bool(rm[horiz_y, cx3]):
                    return (Tool.ROAD, cx3, horiz_y)

    # ---- PHASE 5: VERTICAL ROADS at ±3 from hood columns ----
    for hx_col in nh_cols:
        col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
        if not col_hoods:
            continue
        col_hoods.sort(key=lambda h: h[1])
        yt = col_hoods[0][1] - 2
        yb = col_hoods[-1][1] + 2
        for vert_x in [hx_col - 3, hx_col + 3]:
            if not ib(vert_x, 0):
                continue
            for cy3 in range(max(2, yt), min(WORLD_H - 2, yb + 1)):
                if ib(vert_x, cy3) and bool(em[cy3, vert_x]) and not bool(pm[cy3, vert_x]) and not bool(rm[cy3, vert_x]):
                    return (Tool.ROAD, vert_x, cy3)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use different offset pattern than parent
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: CIVIC SERVICES at lower thresholds ----
    if pop > 50:
        fire_spots = [(fx, fy)
                      for fx in range(12, WORLD_W, 20)
                      for fy in range(12, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2)
                        for px2 in range(16, WORLD_W, 22)
                        for py2 in range(16, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (18, 7), (60, 7), (100, 7),
            (18, 93), (60, 93), (100, 93),
            (7, 50), (113, 50),
            (38, 50), (82, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (28, 5), (92, 5), (28, 95), (92, 95),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 98)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [
            (38, 5), (82, 5), (38, 95), (82, 95),
            (5, 35), (5, 65), (115, 35), (115, 65),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value boost ----
    if pop > 150 and step % 4 == 0:
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 5 + i * 13) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # ---- EXTEND ROADS near powered+wired areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 7) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 11) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # ---- FALLBACK: new plant near unpowered active hood ----
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire spine and road grid"""
    actions = []
    # Two power plants at strategic positions
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire at plant columns
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Main horizontal roads (avoid wire row)
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Different zone mix: 40% res, 30% com, 30% ind (more commercial/industrial than parent)
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Different grid layout: denser rows, more vertical wires
    wire_rows = [15, 30, 45, 50, 55, 70, 85]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Track what infrastructure we've already built
    if 'infra_done' not in state:
        state['infra_done'] = set()

    # Priority 1: Fill wire rows
    if step % 10 == 0:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    has_neighbor = (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))) or \
                                   (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    if has_neighbor and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Priority 2: Fill wire cols
    if step % 10 == 1:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    has_neighbor = (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or \
                                   (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    if has_neighbor and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Priority 3: Roads parallel to wire rows
    if step % 10 == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  (ry > 0 and bool(rm[ry-1, rx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # Priority 4: Roads parallel to wire cols
    if step % 10 == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

    # Priority 5: Power plants distributed across map
    if step % 10 == 4:
        plant_targets = [
            (30, 15), (90, 15), (60, 15),
            (30, 50), (90, 50), (60, 50),
            (30, 85), (90, 85), (60, 85),
            (15, 35), (105, 35),
            (15, 65), (105, 65),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Priority 6: Cross roads between wire rows
    if step % 10 == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            for frac in [0.5]:
                mid_y = int(r1 + (r2 - r1) * frac)
                for rx in range(1, WORLD_W - 1):
                    if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                              (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # Priority 7: Wire unpowered zones
    if step % 10 == 6:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Priority 8: Civic services scaled by population
    if step % 10 == 7:
        if pop > 20:
            fire_spots = [
                (5,5),(60,5),(115,5),
                (5,25),(115,25),
                (5,50),(115,50),
                (5,75),(115,75),
                (5,95),(60,95),(115,95),
                (30,20),(90,20),(30,80),(90,80),
            ]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 100:
            police_spots = [
                (20,10),(50,10),(80,10),(110,10),
                (20,40),(50,40),(80,40),(110,40),
                (20,60),(50,60),(80,60),(110,60),
                (20,90),(50,90),(80,90),(110,90),
            ]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadium_spots = [(40,25),(80,25),(40,75),(80,75),(60,50)]
            for sx, sy in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 700:
            nuke_spots = [
                (5, 50), (115, 50), (60, 5), (60, 95),
                (5, 15), (115, 15), (5, 85), (115, 85),
                (30, 5), (90, 5), (30, 95), (90, 95),
            ]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1200:
            seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
            for sx, sy in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2000:
            airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # Priority 9: Parks for land value
    if step % 10 == 8 and pop > 50:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (closed-loop, reacts to pop) ----
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Grow outward from multiple neighborhood centers based on population
        if pop < 80:
            # Start with two clusters: left and right of center
            active_centers = [(35, 50), (85, 50), (60, 35), (60, 65)]
        elif pop < 300:
            # Expand to 9 centers
            active_centers = [
                (20, 25), (60, 25), (100, 25),
                (20, 50), (60, 50), (100, 50),
                (20, 75), (60, 75), (100, 75),
            ]
        elif pop < 1000:
            # Full grid coverage
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 8 + col * 14
                    cy = 8 + row * 14
                    active_centers.append((cx, cy))
        else:
            # Dense full-map
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 5 + col * 10
                    cy = 5 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

