    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Key wire/road corridors
    wire_rows = [50, 30, 70, 15, 85]
    wire_cols = [30, 90, 60, 10, 110]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- STEP 1: Ensure power grid is extended ---
    # Find any gap in horizontal wire spines and fix it
    for wr in wire_rows:
        row_has_wire = wm[wr, :] | pm[wr, :]
        # Extend wire connected to existing wire
        for wx in range(1, WORLD_W - 1):
            if not bool(row_has_wire[wx]):
                left = bool(row_has_wire[wx-1]) if wx > 0 else False
                right = bool(row_has_wire[wx+1]) if wx < WORLD_W-1 else False
                if (left or right) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                    return (Tool.WIRE, wx, wr)

    for wc in wire_cols:
        col_has_wire = wm[:, wc] | pm[:, wc]
        for wy in range(1, WORLD_H - 1):
            if not bool(col_has_wire[wy]):
                up = bool(col_has_wire[wy-1]) if wy > 0 else False
                down = bool(col_has_wire[wy+1]) if wy < WORLD_H-1 else False
                if (up or down) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                    return (Tool.WIRE, wc, wy)

    # --- STEP 2: Extend road network adjacent to wire ---
    road_offsets = [-1, 1]
    for wr in wire_rows:
        row_wire = wm[wr, :] | pm[wr, :]
        for offset in road_offsets:
            ry = wr + offset
            if not ib(30, ry):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    for wc in wire_cols:
        col_wire = wm[:, wc] | pm[:, wc]
        for offset in road_offsets:
            rcx = wc + offset
            if not (0 < rcx < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                    return (Tool.ROAD, rcx, ry)

    # --- STEP 3: Reactive road extension from existing roads ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 100)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- STEP 4: Wire toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    zone_ys_u, zone_xs_u = np.where(unpowered_zones)
    if len(zone_xs_u) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 17) % len(zone_xs_u)
            tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- STEP 5: Add more power plants if coverage is thin ---
    total_wire = int(np.sum(wm | pm))
    total_plant = int(np.sum(pm))
    if total_plant < 6 and step % 20 == 0:
        # Find area far from existing plants
        plant_ys, plant_xs = np.where(pm)
        candidates = [(x, y) for x in range(5, WORLD_W-5, 15)
                      for y in range(5, WORLD_H-5, 15)
                      if bool(em[y, x])]
        if candidates and len(plant_xs) > 0:
            best_c = None
            best_d = -1
            for (cx, cy) in candidates:
                d = float(np.min(np.abs(plant_xs - cx) + np.abs(plant_ys - cy)))
                if d > best_d:
                    best_d = d
                    best_c = (cx, cy)
            if best_c:
                return (Tool.COALPOWER, best_c[0], best_c[1])

    # --- STEP 6: Civic services ---
    if pop > 50 and step % 30 == 5:
        fire_spots = [(5,5),(60,5),(115,5),(5,50),(115,50),(5,93),(60,93),(115,93),
                      (30,25),(90,25),(30,75),(90,75)]
        for sx, sy in fire_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150 and step % 30 == 10:
        police_spots = [(20,20),(60,20),(100,20),(20,60),(60,60),(100,60),
                        (20,80),(60,80),(100,80)]
        for sx, sy in police_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500 and step % 50 == 15:
        nuclear_spots = [(15,15),(105,15),(15,85),(105,85),(60,5),(60,93)]
        for nx2, ny2 in nuclear_spots:
            if ib(nx2,ny2) and bool(em[ny2,nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800 and step % 50 == 20:
        stadium_spots = [(40,35),(80,35),(40,65),(80,65)]
        for sx, sy in stadium_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500 and step % 50 == 25:
        seaports = [(5,93),(113,93)]
        for sx, sy in seaports:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.SEAPORT, sx, sy)

    # --- STEP 7: Zone placement (main loop) ---
    avoid_rows = wire_rows + [15, 85]
    avoid_cols = wire_cols

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in avoid_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in avoid_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Prioritize zones near center and near existing zones
        center_x, center_y = WORLD_W // 2, WORLD_H // 2
        dist_center = np.abs(cxs2 - center_x).astype(float) + np.abs(cys2 - center_y).astype(float)

        # Also reward proximity to existing zones
        if int(np.sum(zone_tiles)) > 0:
            zone_ys_e, zone_xs_e = np.where(zone_tiles)
            # Rough proximity: nearest zone distance
            sample_k = min(len(zone_xs_e), 50)
            idx_s = np.linspace(0, len(zone_xs_e)-1, sample_k, dtype=int)
            dist_zones = np.full(len(cxs2), 9999.0)
            for zi in idx_s:
                d = np.abs(cxs2 - zone_xs_e[zi]).astype(float) + np.abs(cys2 - zone_ys_e[zi]).astype(float)
                dist_zones = np.minimum(dist_zones, d)
            score = dist_center + 0.3 * dist_zones
        else:
            score = dist_center

        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7 + pop) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks to improve land value
    if pop > 30 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend wire network
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 60)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire and road spines."""
    actions = []
    # Two central power plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-8, 9):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire - closer to wire for better zone access
        for dx in range(-8, 9):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
        # Vertical roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        # Balanced mix: 40% res, 30% com, 30% ind
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Active anchors - denser grid for more coverage
    all_anchors = []
    for ax in [20, 40, 60, 80, 100]:
        for ay in [20, 35, 50, 65, 80]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 6
        if pop < 500:  return 9
        if pop < 800:  return 12
        if pop < 1200: return 16
        if pop < 2000: return 20
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE EXPANSION: extend wire from existing wire/plant toward anchor goals ----
    wire_half = min(22, 8 + pop // 10)
    vert_half = min(16, 5 + pop // 15)

    for (ax, ay) in active_anchors:
        # Horizontal spine
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    for (ax, ay) in active_anchors:
        # Vertical spine
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- WIRE CONNECTIONS between anchors ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: roads flanking wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        # Roads at ay-2 and ay+2
        for road_y_off in [-2, 2]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = False
                    for ddx in [-1, 1]:
                        if ib(cx + ddx, road_y) and bool(rm[road_y, cx + ddx]):
                            adj_road = True
                    adj_wire = (ib(cx, road_y - 1) and bool(wm[road_y - 1, cx])) or \
                               (ib(cx, road_y + 1) and bool(wm[road_y + 1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # ---- VERTICAL ROADS flanking vertical wire spines ----
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-2, 2]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = False
                    for ddy in [-1, 1]:
                        if ib(road_x, cy + ddy) and bool(rm[cy + ddy, road_x]):
                            adj_road = True
                    adj_wire = (ib(road_x - 1, cy) and bool(wm[cy, road_x - 1])) or \
                               (ib(road_x + 1, cy) and bool(wm[cy, road_x + 1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: near roads and wire ----
    # KEY CHANGE: Use step-based cycling to spread placements across the map
    # rather than always picking the single closest point
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)

        # Score = closeness to anchors + diversity boost
        # Add a small random-ish rotation based on step to avoid always picking same spot
        order = np.argsort(best_dist)

        # Try from different offsets to spread placements
        step_off = (step * 3) % max(len(order), 1)
        # First try closest candidates (within top 30%)
        n_top = max(1, len(order) // 3)
        checked = 0
        for i in range(len(order)):
            # Alternate between close candidates and step-offset candidates
            if i < n_top:
                k = order[i]
            else:
                k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive) ----
    # Place fire stations early and spread them across active anchors
    if pop > 30:
        fire_spots = []
        for (ax, ay) in active_anchors:
            fire_spots.append((ax - 5, ay - 5))
            fire_spots.append((ax + 5, ay + 5))
        fire_spots += [
            (7, 10), (30, 10), (55, 10), (80, 10), (105, 10),
            (7, 50), (30, 50), (55, 50), (80, 50), (105, 50),
            (7, 88), (30, 88), (55, 88), (80, 88), (105, 88),
        ]
        for (sx, sy) in fire_spots:
            sx, sy = int(sx), int(sy)
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = []
        for (ax, ay) in active_anchors:
            police_spots.append((ax + 5, ay - 5))
            police_spots.append((ax - 5, ay + 5))
        police_spots += [
            (10, 25), (35, 25), (60, 25), (85, 25), (110, 25),
            (10, 65), (35, 65), (60, 65), (85, 65), (110, 65),
        ]
        for (sx, sy) in police_spots:
            sx, sy = int(sx), int(sy)
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(20, 5), (60, 5), (100, 5), (20, 92), (60, 92), (100, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear plants for late-game power boost
    if pop > 600:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5), (60, 94), (5, 50), (115, 50)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for (ax2, ay2) in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for (sx2, sy2) in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones for land value ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 9 coal plants in 3x3 grid with wire spines and flanking roads."""
    actions = []
    for px in [20, 60, 100]:
        for py in [25, 50, 75]:
            actions.append((Tool.COALPOWER, px, py))
            for dy in range(-6, 7):
                actions.append((Tool.WIRE, px, py + dy))
            for dy in range(-6, 7):
                actions.append((Tool.ROAD, px - 1, py + dy))
                actions.append((Tool.ROAD, px + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target: 45% res, 30% com, 25% ind
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 anchors in 3x3 grid
    all_anchors = []
    for col_x in [20, 60, 100]:
        for row_y in [25, 50, 75]:
            all_anchors.append((col_x, row_y))

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 300:  return 3
        if pop < 500:  return 4
        if pop < 750:  return 5
        if pop < 1000: return 6
        if pop < 1500: return 7
        if pop < 2000: return 8
        return 9

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    spine_half = min(35, 8 + pop // 8)

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 7); y1 = min(WORLD_H, py + 8)
        x0 = max(0, px - 7); x1 = min(WORLD_W, px + 8)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) ----
    for (px, py) in active_anchors:
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and (bool(em[nr, px]) or bool(wm[nr, px])) and not bool(pm[nr, px]):
                    return (Tool.WIRE, px, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            px1 = row_anchors[i][0]
            px2 = row_anchors[i + 1][0]
            for cx in range(px1 + 1, px2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows in same column ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for wc in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == wc], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            py1 = col_anchors[i][1]
            py2 = col_anchors[i + 1][1]
            for cy in range(py1 + 1, py2):
                if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                    return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(px, r) and bool(wm[r, px])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 3
        for wr in wire_in_col[cycle::3]:
            rl, rr = px - 1, px + 1
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS at anchor y-levels ----
    if pop > 20:
        for yl in y_levels:
            row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl], key=lambda a: a[0])
            if len(row_anchors) < 2:
                continue
            rl1 = row_anchors[0][0] - 1
            rr_last = row_anchors[-1][0] + 1
            for horiz_y in [yl - 5, yl + 5]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS ROADS connecting row levels ----
    if pop > 60 and len(y_levels) >= 2:
        for col_x in x_cols:
            for rx in [col_x - 3, col_x + 3]:
                for i in range(len(y_levels) - 1):
                    y1 = y_levels[i]
                    y2 = y_levels[i + 1]
                    if not ib(rx, y1) or not ib(rx, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 700:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [
            (8, 15), (35, 15), (65, 15), (95, 15), (112, 15),
            (8, 40), (35, 40), (65, 40), (95, 40), (112, 40),
            (8, 62), (35, 62), (65, 62), (95, 62), (112, 62),
            (8, 85), (35, 85), (65, 85), (95, 85), (112, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [
            (12, 25), (45, 25), (75, 25), (108, 25),
            (12, 50), (45, 50), (75, 50), (108, 50),
            (12, 75), (45, 75), (75, 75), (108, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (10, 10), (55, 10), (100, 10),
            (10, 90), (55, 90), (100, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94), (30, 6), (90, 6)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: new plant at uncovered anchor ----
    for (px, py) in active_anchors:
        if not bool(nbr_wire[py, px]):
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + cross wire grid + road grid"""
    actions = []
    # Two central coal plants
    plants = [(40, 50), (79, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at y=10,30,50,70,90
    wire_rows = [10, 30, 50, 70, 90]
    wire_cols = [20, 40, 59, 79, 98]
    for wy in wire_rows:
        for x in range(0, 120):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wc in wire_cols:
        for y in range(0, 100):
            actions.append((Tool.WIRE, wc, y))
    # Roads flanking horizontal wires
    for wy in wire_rows:
        for x in range(0, 120):
            for off in [-1, 1]:
                ry = wy + off
                if 0 <= ry < 100:
                    actions.append((Tool.ROAD, x, ry))
    # Roads flanking vertical wires
    for wc in wire_cols:
        for y in range(0, 100):
            for off in [-1, 1]:
                rx = wc + off
                if 0 <= rx < 120:
                    actions.append((Tool.ROAD, rx, y))
    return actions


def act(obs, state):
