    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    wire_rows = [10, 30, 50, 70, 90]
    wire_cols = [20, 40, 59, 79, 98]

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # 50% res, 25% com, 25% ind
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    # Power reach: wires+plants dilated by 1 (adjacency)
    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- REACTIVE: check where wire spine is missing and fill it ---
    phase = step % 8

    if phase in (0, 1):
        # Fill missing horizontal wire spine tiles
        for wr in wire_rows:
            for wx in range(0, WORLD_W):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    # Check if adjacent wire/plant exists (connectivity)
                    adj = False
                    for ddx in [-1, 1]:
                        nx2 = wx + ddx
                        if ib(nx2, wr) and (bool(wm[wr, nx2]) or bool(pm[wr, nx2])):
                            adj = True
                    if adj or wx == 0:
                        return (Tool.WIRE, wx, wr)

    elif phase in (2, 3):
        # Fill missing vertical wire spine tiles
        for wc in wire_cols:
            for wy in range(0, WORLD_H):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    adj = False
                    for ddy in [-1, 1]:
                        ny2 = wy + ddy
                        if ib(wc, ny2) and (bool(wm[ny2, wc]) or bool(pm[ny2, wc])):
                            adj = True
                    if adj or wy == 0:
                        return (Tool.WIRE, wc, wy)

    elif phase == 4:
        # Fill missing road tiles adjacent to horizontal wires
        for wr in wire_rows:
            for off in [-1, 1]:
                ry = wr + off
                if not (0 <= ry < WORLD_H):
                    continue
                for rx in range(0, WORLD_W):
                    if bool(em[ry, rx]) and (bool(wm[wr, rx]) or bool(pm[wr, rx])):
                        return (Tool.ROAD, rx, ry)

    elif phase == 5:
        # Fill missing road tiles adjacent to vertical wires
        for wc in wire_cols:
            for off in [-1, 1]:
                rcx = wc + off
                if not (0 <= rcx < WORLD_W):
                    continue
                for ry in range(0, WORLD_H):
                    if bool(em[ry, rcx]) and (bool(wm[ry, wc]) or bool(pm[ry, wc])):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 6:
        # Extend roads from existing road network into powered empty areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11 + pop * 3) % len(road_xs)
            for offset in range(min(len(road_xs), 300)):
                k = (sk + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- REACTIVE ZONE PLACEMENT ---
    # Candidate: empty, near road, near power, not on spine corridors
    cand_mask = em & near_road & near_power
    # Protect spine corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False
    # Protect borders
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Pick position closest to existing zones (reactive: grow from current city core)
        if total_zones > 1:
            zone_ys_arr, zone_xs_arr = np.where(zone_tiles)
            # Compute mean zone position
            mzx = float(np.mean(zone_xs_arr))
            mzy = float(np.mean(zone_ys_arr))
            # Score: closer to mean zone + some spread
            dists = np.abs(cxs2 - mzx).astype(float) + np.abs(cys2 - mzy).astype(float)
        else:
            # Start near center
            dists = np.abs(cxs2 - 60).astype(float) + np.abs(cys2 - 50).astype(float)

        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 3 + pop * 7) % max(len(order), 1)
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- CIVIC SERVICES (reactive on pop) ---
    if pop > 200:
        fire_spots = [(10, 20), (50, 20), (90, 20), (110, 20),
                      (10, 45), (50, 45), (90, 45), (110, 45),
                      (10, 65), (50, 65), (90, 65), (110, 65),
                      (10, 85), (50, 85), (90, 85)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [(15, 25), (55, 25), (95, 25),
                        (15, 60), (55, 60), (95, 60),
                        (15, 82), (55, 82), (95, 82)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(30, 20), (80, 20), (30, 75), (80, 75)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        # Add nuclear plants reactively near unpowered areas
        nuke_spots = [(5, 50), (113, 50), (59, 5), (59, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        seaports = [(5, 92), (113, 92)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(45, 5), (75, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value near zones
    if pop > 300 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: add more coal plants if not enough power
    powered_z = obs.powered_zones
    total_z = total_zones
    if total_z > 0 and powered_z < total_z * 0.7:
        # Find empty spot near center to place coal plant
        for r in range(2, 30):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx2, ny2 = 60 + dx, 50 + dy
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            return (Tool.COALPOWER, nx2, ny2)

    # Fallback: extend road from existing road
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk2 = (step * 19) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (sk2 + offset * 11) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: wire extension
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk3 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 100)):
            k = (sk3 + offset * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire grid + flanking roads for initial power/road coverage."""
    actions = []
    # Coal plants at quadrant positions
    for px, py in [(20, 25), (80, 25), (20, 75), (80, 75), (50, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 50, 80]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Infrastructure grid definitions
    wire_rows = [10, 25, 40, 50, 60, 75, 90]
    wire_cols = [12, 24, 36, 48, 60, 72, 84, 96, 108]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 10

    # Phase 0: Ensure power plants distributed across map
    if phase == 0:
        plant_targets = []
        for py in [12, 30, 50, 70, 88]:
            for px in [15, 40, 60, 85, 110]:
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 18), min(WORLD_W, px + 19)
            y0, y1 = max(0, py - 18), min(WORLD_H, py + 19)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill gaps in horizontal wire rows
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill gaps in vertical wire cols
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads above/below horizontal wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                                   (ry > 0 and bool(rm[ry-1, rx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # Phase 4: Roads left/right of vertical wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                                   bool(rm[ry, max(0, rcx-1)]) or
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # Phase 5: Cross streets between wire rows (improve connectivity)
    if phase == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            for frac in [0.33, 0.5, 0.67]:
                mid_y = int(r1 + (r2 - r1) * frac)
                if not (0 < mid_y < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])) or
                               (mid_y > 0 and bool(rm[mid_y-1, rx])) or
                               (mid_y < WORLD_H-1 and bool(rm[mid_y+1, rx])))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # Phase 6: Cross streets between wire cols
    if phase == 6:
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = int(c1 + (c2 - c1) * 0.5)
            if not (0 < mid_x < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])) or
                           (mid_x > 0 and bool(rm[ry, mid_x-1])) or
                           (mid_x < WORLD_W-1 and bool(rm[ry, mid_x+1])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Phase 7: Wire unpowered zones reactively
    if phase == 7:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Road to unroaded zones reactively
    if phase == 8:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 9: Extend road from existing roads into powered areas
    if phase == 9:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled to population ----
    if pop > 30:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,25),(115,25),(5,50),(115,50),
            (5,75),(115,75),(5,95),(30,95),(60,95),(90,95),(115,95),
            (35,50),(65,50),(95,50),(50,20),(80,20),(50,80),(80,80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 120:
        police_spots = [
            (20,15),(50,15),(80,15),(110,15),
            (20,35),(50,35),(80,35),(110,35),
            (20,55),(50,55),(80,55),(110,55),
            (20,75),(50,75),(80,75),(110,75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(30,20),(90,20),(30,80),(90,80),(60,50),(15,50),(105,50),(60,10),(60,90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,20),(115,20),(5,80),(115,80),
            (30,5),(90,5),(30,95),(90,95),
            (35,50),(85,50),(60,30),(60,70),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5,95),(115,95),(5,5),(115,5),(60,95),(60,5),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45),(5,55),(115,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 6 == 3:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep zones off wire/road infrastructure corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active centers expand outward as population increases
        if pop < 100:
            active_centers = [
                (60,50),(45,50),(75,50),(60,38),(60,62),
                (30,50),(90,50),(60,25),(60,75),
            ]
        elif pop < 500:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 12 + row * 19
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 8 + col * 13
                    cy = 8 + row * 12
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 6 + col * 11
                    cy = 6 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area from existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire network
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: one coal plant at center, wires out, seed roads."""
    actions = []
    # Central power plant
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire horizontally from plant
    for x in range(55, 10, -1):
        actions.append((Tool.WIRE, x, cy))
    for x in range(65, 110):
        actions.append((Tool.WIRE, x, cy))
    # Wire vertically
    for y in range(45, 10, -1):
        actions.append((Tool.WIRE, cx, y))
    for y in range(55, 90):
        actions.append((Tool.WIRE, cx, y))
    # Seed roads on either side of center wire row
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 44))
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 56))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def adj_mask(mask):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        result[:-1, :] |= mask[1:, :]
        result[1:, :] |= mask[:-1, :]
        result[:, :-1] |= mask[:, 1:]
        result[:, 1:] |= mask[:, :-1]
        return result

    adj_power = adj_mask(power_src)
    adj_road = adj_mask(rm)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure enough power plants ---
    # One plant per ~25x25 region
    plant_xs = list(range(12, WORLD_W - 6, 25))
    plant_ys = list(range(12, WORLD_H - 6, 25))
    for ppy in plant_ys:
        for ppx in plant_xs:
            x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                # Place near desired spot, on empty tile
                for r in range(0, 7):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # --- PHASE 2: Grow wire grid connecting plants ---
    # Wire rows at y=10,20,...,90 - connect via horizontal wires
    wire_rows = list(range(10, WORLD_H - 5, 10))
    wire_cols = list(range(10, WORLD_W - 5, 10))

    # Extend horizontal wires
    for wr in wire_rows:
        row_pw = wm[wr, :] | pm[wr, :]
        if not row_pw.any():
            # Find nearest plant and start wire toward this row
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr) + np.abs(pxs_arr - 60))
                sx, sy = int(pxs_arr[idx]), int(pys_arr[idx])
                # Walk toward wr
                if sy != wr:
                    step_y = 1 if wr > sy else -1
                    ny2 = sy + step_y
                    if ib(sx, ny2) and bool(em[ny2, sx]) and not bool(pm[ny2, sx]):
                        return (Tool.WIRE, sx, ny2)
            continue
        indices = np.where(row_pw)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left - 1]) and not bool(pm[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 3 and bool(em[wr, right + 1]) and not bool(pm[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_pw = wm[:, wc] | pm[:, wc]
        if not col_pw.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_pw)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top - 1, wc]) and not bool(pm[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 3 and bool(em[bot + 1, wc]) and not bool(pm[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # --- PHASE 3: Road grid between wire rows ---
    road_rows = [wr + 5 for wr in wire_rows if 3 < wr + 5 < WORLD_H - 3]
    road_cols = [wc + 5 for wc in wire_cols if 3 < wc + 5 < WORLD_W - 3]

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(12, rr) and bool(em[rr, 12]) and not bool(pm[rr, 12]):
                return (Tool.ROAD, 12, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 12) and bool(em[12, rc]) and not bool(pm[12, rc]):
                return (Tool.ROAD, rc, 12)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # --- PHASE 4: Zone placement ---
    zone_cand = em & near_road & near_power
    # Exclude edges and wire/road corridors
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 60)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 60)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer zones near but not too near existing zones (3-15 tiles)
            zone_score = np.where(min_zone_dist < 4, 800.0,
                                  np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            zone_score = -(np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Score: prefer close to road, moderate distance from existing zones
        score = road_dist * 2.0 + zone_score
        order = np.argsort(score)
        # Use step offset to vary selection and avoid repetition
        off = (step * 7 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Wire toward unpowered zones (reactive) ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    wire_cand = em & adj_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx2 - int(uzxs[j])) + abs(cy2 - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # --- PHASE 6: Road toward unserved zones (reactive) ---
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    road_cand2 = em & adj_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx2, cy2 = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx2 - int(usxs[j])) + abs(cy2 - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- PHASE 7: Civic services (pop-reactive) ---
    if pop > 50:
        for fsy in range(13, WORLD_H - 5, 15):
            for fsx in range(13, WORLD_W - 5, 20):
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        for psy in range(16, WORLD_H - 5, 18):
            for psx in range(16, WORLD_W - 5, 22):
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        for pky in range(11, WORLD_H - 5, 12):
            for pkx in range(11, WORLD_W - 5, 14):
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 800:
        for sty in range(22, 85, 30):
            for stx in range(22, 100, 35):
                if ib(stx, sty) and bool(em[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        for npy in range(18, 90, 30):
            for npx in range(18, 110, 30):
                if ib(npx, npy) and bool(em[npy, npx]):
                    x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                    y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 3000:
        for apx, apy in [(55, 7), (65, 7), (55, 92), (65, 92), (7, 45), (112, 45)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 5000:
        for spx, spy in [(7, 50), (112, 50), (60, 4), (60, 95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend road near any plant ---
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire grid + road grid"""
    actions = []
    # Place coal plants at strategic locations
    for px, py in [(20, 20), (80, 20), (20, 75), (80, 75), (50, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at key rows
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 50, 80, 110]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 60, 80]
    wire_cols = [20, 50, 80, 110]
    road_offsets = [-1, 1]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            if ir < 0.30: return Tool.INDUSTRIAL
            if cr < 0.25: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.25: return Tool.INDUSTRIAL
            if cr < 0.28: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35: return Tool.COMMERCIAL
            if rr < 0.45: return Tool.RESIDENTIAL
            if ir < 0.20: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === REACTIVE INFRASTRUCTURE REPAIR ===

    # 1. Wire unpowered zones
    if step % 5 == 0:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 50)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # 2. Road unroaded zones
    if step % 5 == 1:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 3. Repair horizontal wire rows
    if step % 5 == 2:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1): continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])))
                    right = (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # 4. Repair vertical wire cols
    if step % 5 == 3:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1): continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = (wy2 > 0 and (bool(wm[wy2-1, wc]) or bool(pm[wy2-1, wc])))
                    dn = (wy2 < WORLD_H-1 and (bool(wm[wy2+1, wc]) or bool(pm[wy2+1, wc])))
                    if (up or dn) and bool(em[wy2, wc]):
                        return (Tool.WIRE, wc, wy2)

    # 5. Power plant coverage check
    if step % 5 == 4:
        plant_targets = []
        for py in range(15, WORLD_H - 5, 20):
            for px in range(15, WORLD_W - 5, 25):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px-12), min(WORLD_W, px+13)
            y0, y1 = max(0, py-10), min(WORLD_H, py+11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px+dx, py+dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    if pop > 5000 and funds > 15000:
                                        return (Tool.NUCLEARPOWER, nx2, ny2)
                                    return (Tool.COALPOWER, nx2, ny2)

    # Fix roads flanking wire rows
    if step % 7 == 5:
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1): continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                                   (ry > 0 and bool(rm[ry-1, rx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # Fix roads flanking wire cols
    if step % 7 == 6:
        for wc in wire_cols:
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1): continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                                   bool(rm[ry, max(0, rcx-1)]) or
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # === CIVIC SERVICES (pop-gated) ===
    if pop > 25:
        fire_spots = [
            (6, 6), (35, 6), (65, 6), (95, 6), (113, 6),
            (6, 30), (113, 30), (6, 50), (113, 50),
            (6, 70), (113, 70), (6, 93), (35, 93), (65, 93), (95, 93),
            (35, 50), (65, 50), (95, 50), (50, 20), (80, 20),
            (50, 80), (80, 80), (20, 50), (100, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 120:
        police_spots = [
            (20, 15), (50, 15), (80, 15), (110, 15),
            (20, 35), (50, 35), (80, 35), (110, 35),
            (20, 55), (50, 55), (80, 55), (110, 55),
            (20, 75), (50, 75), (80, 75), (110, 75),
            (10, 50), (60, 20), (60, 80), (35, 25), (85, 25),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (30, 20), (90, 20), (30, 80), (90, 80),
            (60, 50), (15, 50), (105, 50), (60, 10), (60, 90),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (10, 50), (110, 50), (60, 5), (60, 95),
            (10, 20), (110, 20), (10, 80), (110, 80),
            (35, 10), (85, 10), (35, 90), (85, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 80 and step % 8 == 4:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === ZONE PLACEMENT ===
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road infrastructure corridors (but leave flanking roads usable)
    for wr in wire_rows:
        cand_mask[max(0, wr):min(WORLD_H, wr+1), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc):min(WORLD_W, wc+1)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Adaptive neighborhood centers based on population
        if pop < 150:
            active_centers = [
                (50, 50), (35, 50), (65, 50), (50, 33), (50, 67),
                (20, 50), (80, 50), (50, 15), (50, 85),
                (35, 33), (65, 33), (35, 67), (65, 67),
            ]
        elif pop < 600:
            active_centers = []
            for row in range(4):
                for col in range(6):
                    cx = 15 + col * 18
                    cy = 15 + row * 22
                    active_centers.append((cx, cy))
        else:
            # Dense grid for high pop
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 6 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road toward powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and initial road grid."""
    actions = []
    # Two power plants side by side for redundancy
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire connecting them horizontally
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Wire spines extending up/down from each plant
    for d in range(1, 12):
        actions.append((Tool.WIRE, 40, 50 + d))
        actions.append((Tool.WIRE, 40, 50 - d))
        actions.append((Tool.WIRE, 80, 50 + d))
        actions.append((Tool.WIRE, 80, 50 - d))
    # Horizontal roads above and below the wire spine
    for x in range(28, 95):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood anchors expanding with population
    all_anchors = [
        (40, 50), (80, 50),
        (40, 25), (80, 25),
        (40, 75), (80, 75),
        (20, 50), (100, 50),
        (60, 25), (60, 75),
        (20, 25), (100, 25),
        (20, 75), (100, 75),
        (60, 50),
    ]

    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 8
        if pop < 1500:  return 10
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS near each anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find nearest empty tile to place plant
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE: connect power grid reactively ----
    # For each anchor, extend wire cross if not already present
    spine = min(12, 4 + pop // 60)
    for (px, py) in active_anchors:
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- CONNECT WIRES between adjacent anchors ----
    # Horizontal connections
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1a = row_anchors[i][0]
            x2a = row_anchors[i + 1][0]
            for cx in range(x1a + 1, x2a):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # Vertical connections
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1a = col_anchors[i][1]
            y2a = col_anchors[i + 1][1]
            for cy in range(y1a + 1, y2a):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROADS: build grid around each anchor ----
    for (px, py) in active_anchors:
        for road_dy in [-3, 3]:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        # Also add vertical roads at ±4 from anchor
        for road_dx in [-4, 4]:
            rx = px + road_dx
            for dy in range(-spine, spine + 1):
                ry = py + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- VERTICAL ROADS connecting between anchor rows ----
    if pop > 50:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                y1a = col_anchors[i][1]
                y2a = col_anchors[i + 1][1]
                for road_x in [xl + 4, xl - 4]:
                    for cy in range(y1a - 3, y2a + 4):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD ZONES: near roads AND wire ----
    # Compute proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step to vary which candidate we pick (reactivity)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing road ends near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 150:
        fire_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [
            (25, 15), (65, 15), (105, 15),
            (25, 55), (65, 55), (105, 55),
            (25, 85), (65, 85), (105, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        for sp in [(15, 8), (60, 8), (105, 8), (15, 92), (60, 92), (105, 92)]:
            sx, sy = sp
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for np2 in [(5, 5), (115, 5), (5, 94), (115, 94)]:
            nx2, ny2 = np2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 4000:
        for ap in [(55, 6), (5, 50), (115, 50)]:
            ax, ay = ap
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 5000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 400:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Different strategy: radial/spoke layout from center, mixed zones, reactive growth
# Key changes:
# 1. Compact central hub with radial roads/wires
# 2. Better zone mix (more balanced R/C/I)
# 3. Reactive to actual power/road coverage
# 4. Multiple coal plants placed reactively near unpowered areas

def init(obs, state):
    """Bootstrap: central coal plant + cross wire spines + perimeter plants."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Cross wire spines from center
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Additional plants at cardinal extremes
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    actions.append((Tool.COALPOWER, 60, 20))
    actions.append((Tool.COALPOWER, 60, 80))
    # Roads flanking horizontal spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    # Roads flanking vertical spine
    for y in range(1, 99):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone mix: 50% residential, 25% commercial, 25% industrial
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Grid of neighborhoods in concentric rings from center
    # Ring 0: center cluster
    # Ring 1: inner ring
    # Ring 2: outer ring
    center = (60, 50)

    def make_hoods():
        hoods = []
        # Dense grid, 8 columns x 7 rows, spaced 14x13
        for col in range(8):
            for row in range(7):
                cx = 8 + col * 15
                cy = 8 + row * 13
                hoods.append((cx, cy))
        return hoods

    all_hoods = make_hoods()

    # Sort hoods by distance from center
    all_hoods.sort(key=lambda h: abs(h[0]-60) + abs(h[1]-50))

    def get_active_hoods():
        if pop < 50:
            return all_hoods[:5]
        elif pop < 150:
            return all_hoods[:12]
        elif pop < 400:
            return all_hoods[:22]
        elif pop < 800:
            return all_hoods[:35]
        elif pop < 1500:
            return all_hoods[:45]
        elif pop < 3000:
            return all_hoods[:50]
        else:
            return all_hoods

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Wire corridors: horizontal at rows, vertical at cols
    wire_rows = [14, 27, 40, 50, 63, 76, 89]
    wire_cols = [8, 23, 38, 53, 68, 83, 98, 113]

    # Phase 1: Ensure power plants near active hoods
    if step % 10 < 3:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
            y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(2, 18):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # Phase 2: Extend horizontal wire corridors
    if step % 8 in (0, 1):
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 3: Extend vertical wire corridors
    if step % 8 in (2, 3):
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 4: Roads along wire rows (flanking above and below)
    if step % 8 == 4:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Road if adjacent wire/plant exists
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    # Phase 5: Roads along wire cols (flanking left and right)
    if step % 8 == 5:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    # Phase 6: Cross streets between wire rows
    if step % 8 == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj and bool(near_power[mid_y, rx]):
                        return (Tool.ROAD, rx, mid_y)

    # Phase 7: Vertical cross-streets between wire cols
    if step % 8 == 7:
        for wci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wci], wire_cols[wci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj and bool(near_power[ry, mid_x]):
                        return (Tool.ROAD, mid_x, ry)

    # Civic services - placed reactively based on population
    if pop > 50:
        fire_spots = [(x, y) for y in range(10, 100, 20) for x in range(10, 120, 25)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 180:
        police_spots = [(x, y) for y in range(15, 100, 24) for x in range(15, 120, 28)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(30, 30), (90, 30), (30, 70), (90, 70), (60, 50), (15, 50), (105, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 50), (113, 50), (60, 5), (60, 93), (5, 5), (113, 5), (5, 93), (113, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 93), (113, 93), (5, 5), (113, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(48, 5), (72, 5), (48, 90), (72, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Zone placement - main closed-loop action
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors themselves
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active neighborhood centers
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary offset to avoid getting stuck
        offset = (step * 11 + pop * 5) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # Parks for land value improvement
    if pop > 100 and step % 5 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend road from existing roads into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Wire toward unpowered active hoods
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Extend any wire to expand power coverage
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: new coal plant near unpowered active hood
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants at center-left and center-right, connected by wire, with initial roads"""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally through center
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from plants up and down
    for y in range(42, 50):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    for y in range(51, 59):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Horizontal roads above and below the wire spine
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 43))
        actions.append((Tool.ROAD, x, 57))
    # Vertical roads forming columns
    for y in range(38, 63):
        actions.append((Tool.ROAD, 30, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 90, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: ~40% res, 35% com, 25% ind — more commercial than parent
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Place coal plants in a grid, every 20 tiles ---
    plant_positions = []
    for py in range(10, 95, 20):
        for px in range(10, 115, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Extend wire to connect plants and reach zones ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Prioritize wiring toward unpowered plants first
        unpowered_plants = [(px, py) for px, py in plant_positions
                            if ib(px, py) and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered empty areas
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            best_dist = 1e9
            best_k = 0
            sample_idx = np.random.choice(len(upxs), min(50, len(upxs)), replace=False)
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Build a denser road grid (every 4 tiles) ---
    road_targets = []
    # Horizontal roads every 4 rows, vertical roads every 4 cols
    for gy in range(4, 97, 4):
        for gx in range(4, 117, 4):
            road_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:40]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Place zones with a stronger commercial/industrial bias ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Prefer close to road, spread from existing zones
        score = road_dist * 1.5 + np.maximum(0, 8 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 17 + pop * 11) % max(len(order), 1)

        # Alternate zone types: 4 res, 3 com, 3 ind per 10-step cycle
        step_mod = step % 10
        if step_mod < 4:
            tool = Tool.RESIDENTIAL
        elif step_mod < 7:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL
        # Override with ratio-based pick if ratio very off
        tool = pick_tool() if (ind_count / max(total_zones, 1) < 0.15 or
                                com_count / max(total_zones, 1) < 0.25) else tool

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 60:
        fire_positions = [(fx, fy) for fy in range(6, 95, 6) for fx in range(6, 115, 6)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_positions = [(px2, py2) for py2 in range(8, 92, 8) for px2 in range(8, 112, 8)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_positions = [(pkx, pky) for pky in range(6, 95, 6) for pkx in range(6, 115, 6)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (60, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80),
                        (40, 35), (80, 35), (40, 65), (80, 65)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        # Upgrade to nuclear power for more capacity
        nuke_locs = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50),
                     (15, 15), (105, 15), (15, 85), (105, 85)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(50, 8), (70, 8), (50, 91), (70, 91),
                        (8, 25), (110, 25), (8, 70), (110, 70)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: roads/wires near power plants ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (4, 0), (0, 4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire and roads for quick start."""
    actions = []
    # Two power plants: left and right clusters
    for px, py in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spine vertically
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 1, py + dy))
            actions.append((Tool.ROAD, px + 1, py + dy))
    # Horizontal wire connecting the two plants
    for cx in range(31, 90):
        actions.append((Tool.WIRE, cx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target ratio: 40% res, 35% com, 25% ind (more commercial than parent)
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 cluster anchors: 2 columns x 3 rows
    # Each anchor: (plant_x, plant_y, wire_col, road_left, road_right)
    all_anchors = []
    for col_x in [30, 90]:
        for row_y in [25, 50, 75]:
            all_anchors.append((col_x, row_y, col_x, col_x - 1, col_x + 1))

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 2
        if pop < 400:   return 3
        if pop < 700:   return 4
        if pop < 1000:  return 5
        return 6

    n_active = num_active()
    if n_active >= len(all_anchors):
        active_anchors = all_anchors
    else:
        step_size = len(all_anchors) / n_active
        active_anchors = [all_anchors[int(i * step_size)] for i in range(n_active)]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)
        for r in range(1, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- WIRE SPINE (vertical) ----
    spine_half = min(35, 12 + pop // 8)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            for dy2 in range(-5, 6):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connecting anchors at same row ----
    y_levels = sorted(set(py for (_, py, _, _, _) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted(
            [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
            key=lambda a: a[2]
        )
        for i in range(len(row_anchors) - 1):
            wc1 = row_anchors[i][2]
            wc2 = row_anchors[i + 1][2]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- VERTICAL WIRE connecting anchor rows in same column ----
    if n_active >= 3:
        wc_cols = sorted(set(wc for (_, _, wc, _, _) in active_anchors))
        for wc in wc_cols:
            col_anchors = sorted(
                [(px, py, wc2, rl, rr) for (px, py, wc2, rl, rr) in active_anchors if wc2 == wc],
                key=lambda a: a[1]
            )
            for i in range(len(col_anchors) - 1):
                py1 = col_anchors[i][1]
                py2 = col_anchors[i + 1][1]
                for cy in range(py1 + 1, py2):
                    if ib(wc, cy) and bool(em[cy, wc]) and not bool(pm[cy, wc]):
                        return (Tool.WIRE, wc, cy)

    # ---- ROAD BUILDING flanking wire spines ----
    for idx, (px, py, wc, rl, rr) in enumerate(active_anchors):
        spine_top = max(2, py - spine_half)
        spine_bot = min(WORLD_H - 3, py + spine_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 7) % 3
        for wr in wire_in_col[cycle::3]:
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS connecting the two columns at each y-level ----
    # Place roads at offsets from wire to create grid for zone access
    if pop > 10:
        for yl in y_levels:
            row_anchors_sorted = sorted(
                [(px, py, wc, rl, rr) for (px, py, wc, rl, rr) in active_anchors if py == yl],
                key=lambda a: a[3]
            )
            if len(row_anchors_sorted) < 2:
                continue
            rl1 = row_anchors_sorted[0][3]
            rr_last = row_anchors_sorted[-1][4]
            for horiz_y in [yl - 5, yl + 5, yl - 10, yl + 10]:
                if not ib(rl1, horiz_y) or not ib(rr_last, horiz_y):
                    continue
                for cx in range(rl1, rr_last + 1):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # ---- CROSS ROADS connecting the row levels ----
    if pop > 40 and len(y_levels) >= 2:
        for col_x in [30, 90]:
            for rx in [col_x - 4, col_x + 4]:
                for i in range(len(y_levels) - 1):
                    y1 = y_levels[i]
                    y2 = y_levels[i + 1]
                    if not ib(rx, y1) or not ib(rx, y2):
                        continue
                    for cy in range(y1, y2 + 1):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            return (Tool.ROAD, rx, cy)

    # ---- ADD EXTRA HORIZONTAL ROADS for wider coverage ----
    if pop > 100:
        # Mid-column roads for central connectivity
        for col_x in [30, 90]:
            for rx in [col_x - 7, col_x + 7]:
                for yl in y_levels:
                    for i in range(len(y_levels) - 1):
                        y1 = y_levels[i]
                        y2 = y_levels[i + 1]
                        if not ib(rx, y1) or not ib(rx, y2):
                            continue
                        for cy in range(y1, y2 + 1):
                            if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                                return (Tool.ROAD, rx, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc).astype(float) + np.abs(cys - py).astype(float) * 0.8
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (more aggressive placement) ----
    if pop > 40:
        fire_spots = [
            (8, 15), (50, 15), (110, 15),
            (8, 40), (50, 40), (110, 40),
            (8, 65), (50, 65), (110, 65),
            (8, 90), (50, 90), (110, 90),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 25), (55, 25), (105, 25),
            (15, 50), (55, 50), (105, 50),
            (15, 75), (55, 75), (105, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (10, 10), (60, 10), (110, 10),
            (10, 90), (60, 90), (110, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1800:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 94)]:
            ax, ay = asp
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS to boost land value ----
    if pop > 120:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire spines and roads for two clusters."""
    actions = []
    # Left cluster center
    lx, ly = 35, 50
    # Right cluster center
    rx, ry = 85, 50

    # Two power plants
    actions.append((Tool.COALPOWER, lx, ly))
    actions.append((Tool.COALPOWER, rx, ry))

    # Wire connecting them horizontally
    for x in range(lx + 2, rx - 1):
        actions.append((Tool.WIRE, x, ly))

    # Wire spines vertical for each cluster
    for d in range(1, 18):
        actions.append((Tool.WIRE, lx, ly + d))
        actions.append((Tool.WIRE, lx, ly - d))
        actions.append((Tool.WIRE, rx, ry + d))
        actions.append((Tool.WIRE, rx, ry - d))

    # Roads around each cluster
    for dx in range(-12, 13):
        actions.append((Tool.ROAD, lx + dx, ly - 4))
        actions.append((Tool.ROAD, lx + dx, ly + 4))
        actions.append((Tool.ROAD, rx + dx, ry - 4))
        actions.append((Tool.ROAD, rx + dx, ry + 4))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target zone mix: 45% RES, 30% COM, 25% IND
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 6 neighborhood anchors in 2 columns x 3 rows
    all_anchors = [
        (35, 25), (85, 25),
        (35, 50), (85, 50),
        (35, 75), (85, 75),
    ]
    # Extra anchors for large pop
    extra_anchors = [
        (60, 15), (60, 85),
        (10, 50), (110, 50),
        (10, 25), (110, 25),
        (10, 75), (110, 75),
    ]

    def get_active_anchors():
        if pop < 100:   return all_anchors[:2]
        if pop < 300:   return all_anchors[:4]
        if pop < 600:   return all_anchors[:6]
        if pop < 1000:  return all_anchors + extra_anchors[:2]
        if pop < 2000:  return all_anchors + extra_anchors[:4]
        return all_anchors + extra_anchors

    active_anchors = get_active_anchors()

    # ---- ENSURE POWER PLANTS ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    spine = min(14, 4 + pop // 40)

    # ---- WIRE CROSS at each anchor ----
    for (px, py) in active_anchors:
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- CONNECT POWER horizontally between anchors at same y ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx in range(x1a + 1, x2a):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- CONNECT POWER vertically between anchors ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy in range(y1a + 1, y2a):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: multiple roads around each anchor ----
    # Use offsets -5, -3, 3, 5 for denser road network
    road_offsets = [-5, -3, 3, 5]
    for (px, py) in active_anchors:
        for road_dy in road_offsets:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        # Also vertical roads
        for road_dx in road_offsets:
            rx = px + road_dx
            if not ib(rx, py):
                continue
            for dy in range(-spine, spine + 1):
                ry = py + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- CONNECT ROADS between row anchors ----
    if pop > 20:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1a = col_anchors[i]
                _, y2a = col_anchors[i + 1]
                for road_x_off in [-5, -3, 3, 5]:
                    road_x = xl + road_x_off
                    for cy in range(y1a, y2a + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD ZONE CANDIDATE MASK ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (20, 20), (55, 20), (90, 20),
            (20, 50), (55, 50), (90, 50),
            (20, 80), (55, 80), (90, 80),
            (110, 50), (10, 50),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (25, 15), (65, 15), (100, 15),
            (25, 55), (65, 55), (100, 55),
            (25, 85), (65, 85), (100, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        for sp in [(15, 5), (60, 5), (105, 5), (15, 94), (60, 94), (105, 94)]:
            sx, sy = sp
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        for np2 in [(5, 5), (115, 5), (5, 94), (115, 94), (60, 50)]:
            nx2, ny2 = np2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for ap in [(55, 6), (5, 50), (115, 50), (55, 93)]:
            ax, ay = ap
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3500:
        for sp in [(5, 93), (115, 93), (60, 97), (5, 6), (115, 6)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + initial road grid"""
    actions = []
    # Two central coal plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire connecting the two plants horizontally
    for x in range(42, 80):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for py_off in range(1, 20):
        actions.append((Tool.WIRE, 40, 50 - py_off))
        actions.append((Tool.WIRE, 40, 50 + py_off))
        actions.append((Tool.WIRE, 80, 50 - py_off))
        actions.append((Tool.WIRE, 80, 50 + py_off))
    # Initial roads near center
    for x in range(35, 86):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(43, 58):
        actions.append((Tool.ROAD, 38, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 82, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- PRIORITY 1: Ensure enough coal plants for coverage ----
    # Count plants, add more if population growing but power limited
    plant_count = int(np.sum(pm)) // 9  # rough estimate (plants are 3x3 area)
    needed_plants = max(2, 2 + pop // 300)

    if plant_count < needed_plants:
        # Find empty spots far from existing plants for new plants
        plant_ys, plant_xs = np.where(pm)
        # Try candidate locations on a grid
        candidates = []
        for py in range(10, WORLD_H - 10, 20):
            for px in range(10, WORLD_W - 10, 20):
                if bool(em[py, px]):
                    # distance to nearest plant
                    if len(plant_xs) > 0:
                        min_d = int(np.min(np.abs(plant_xs - px) + np.abs(plant_ys - py)))
                        if min_d > 15:
                            candidates.append((px, py))
                    else:
                        candidates.append((px, py))
        if candidates:
            # Pick candidate closest to center
            best = min(candidates, key=lambda c: abs(c[0] - 60) + abs(c[1] - 50))
            return (Tool.COALPOWER, best[0], best[1])

    # ---- PRIORITY 2: Extend wire network from existing power ----
    # Wire frontier: cells adjacent to wire/plant that are empty
    # Use BFS-inspired approach: find wire frontier cells
    power_src = wm | pm

    # Dilate power_src by 1 to find frontier
    wire_frontier = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
        sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
        r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
        c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
        wire_frontier[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    wire_frontier = wire_frontier & em & ~power_src

    # Build power coverage map (areas within range of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Build road neighbor map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Determine which step modulo we're on for round-robin
    phase = step % 6

    # ---- PRIORITY 3: Zone placement when conditions are good ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Good zone spots: near road AND power, not on boundary
    cand = em & nbr_road & nbr_power
    cand[0:2, :] = False
    cand[WORLD_H - 2:, :] = False
    cand[:, 0:2] = False
    cand[:, WORLD_W - 2:] = False

    # On zone phases, try to place a zone
    if phase in (0, 1, 2):
        cys, cxs = np.where(cand)
        if len(cxs) > 0:
            # Score: prefer locations closer to existing zones (clustering) and center
            if total_zones > 0:
                zone_y, zone_x = np.where(zone_tiles)
                # Use center of mass of existing zones as attractor
                center_x = int(np.mean(zone_x))
                center_y = int(np.mean(zone_y))
            else:
                center_x, center_y = 60, 50

            scores = np.abs(cxs - center_x) + np.abs(cys - center_y)
            order = np.argsort(scores)
            offset = (step * 7) % max(len(order), 1)
            tool = pick_tool()
            for i in range(min(len(order), 200)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

    # ---- PRIORITY 4: Extend roads toward unpowered/unroaded empty areas ----
    if phase == 3:
        # Find road frontier: cells adjacent to roads that are empty and powered
        road_frontier = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            road_frontier[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

        road_frontier = road_frontier & em & nbr_power & ~rm

        # Extend roads toward areas that have power but no road access
        # and no zones yet
        needs_road = nbr_power & ~nbr_road & em
        needs_road[0:2, :] = False
        needs_road[WORLD_H - 2:, :] = False
        needs_road[:, 0:2] = False
        needs_road[:, WORLD_W - 2:] = False

        if bool(np.any(road_frontier & needs_road)):
            target_mask = road_frontier & needs_road
        elif bool(np.any(road_frontier)):
            target_mask = road_frontier
        else:
            target_mask = None

        if target_mask is not None:
            rys, rxs = np.where(target_mask)
            if len(rxs) > 0:
                idx = (step * 11) % len(rxs)
                return (Tool.ROAD, int(rxs[idx]), int(rys[idx]))

    # ---- PRIORITY 5: Extend wire toward uncovered empty areas ----
    if phase == 4:
        # Find areas that are empty but not powered, extend wire toward them
        unpowered_empty = em & ~nbr_power
        unpowered_empty[0:2, :] = False
        unpowered_empty[WORLD_H - 2:, :] = False
        unpowered_empty[:, 0:2] = False
        unpowered_empty[:, WORLD_W - 2:] = False

        if bool(np.any(wire_frontier)) and bool(np.any(unpowered_empty)):
            # Find wire frontier cell closest to unpowered area
            uys, uxs = np.where(unpowered_empty)
            wfy, wfx = np.where(wire_frontier)

            if len(wfx) > 0 and len(uxs) > 0:
                # Pick target unpowered cell
                target_idx = (step * 17) % len(uxs)
                tx, ty = int(uxs[target_idx]), int(uys[target_idx])

                # Find wire frontier cell closest to target
                dists = np.abs(wfx - tx) + np.abs(wfy - ty)
                best_wf = np.argmin(dists)
                return (Tool.WIRE, int(wfx[best_wf]), int(wfy[best_wf]))

        elif bool(np.any(wire_frontier)):
            wfy, wfx = np.where(wire_frontier)
            if len(wfx) > 0:
                idx = (step * 13) % len(wfx)
                return (Tool.WIRE, int(wfx[idx]), int(wfy[idx]))

    # ---- PRIORITY 6: Civic services ----
    if phase == 5:
        if pop > 150:
            fire_spots = [
                (25, 20), (60, 20), (95, 20),
                (25, 50), (95, 50),
                (25, 80), (60, 80), (95, 80),
            ]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 400:
            police_spots = [
                (40, 30), (80, 30),
                (20, 55), (60, 55), (100, 55),
                (40, 75), (80, 75),
            ]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 1000:
            for sx, sy in [(50, 45), (70, 45), (50, 60), (70, 60)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 2000:
            for sx, sy in [(10, 85), (110, 85), (10, 15), (110, 15)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 4000:
            for sx, sy in [(55, 5), (65, 5)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- FALLBACK: any zone placement near existing infrastructure ----
    cys2, cxs2 = np.where(cand)
    if len(cxs2) > 0:
        tool = pick_tool()
        for i in range(min(len(cxs2), 300)):
            idx = (step * 7 + i * 3) % len(cxs2)
            zx, zy = int(cxs2[idx]), int(cys2[idx])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- FALLBACK: extend road anywhere from existing road ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        for i in range(min(len(road_xs), 80)):
            k = (step * 11 + i * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- FALLBACK: extend wire ----
    wfy2, wfx2 = np.where(wire_frontier)
    if len(wfx2) > 0:
        idx = step % len(wfx2)
        return (Tool.WIRE, int(wfx2[idx]), int(wfy2[idx]))

    # ---- LAST RESORT: place coal plant somewhere empty ----
    eys, exs = np.where(em)
    if len(exs) > 0:
        idx = (step * 17) % len(exs)
        return (Tool.COALPOWER, int(exs[idx]), int(eys[idx]))

    return None

# Strategy: Denser grid with 4 coal plants, horizontal wire backbone,
# roads perpendicular to wire, aggressive zone filling with 50% res / 25% com / 25% ind mix
# Uses a grid of neighborhoods reacting to population growth dynamically

def init(obs, state):
    actions = []
    # 4 plants at corners of a central rectangle, connected via horizontal wires
    plants = [(25, 35), (95, 35), (25, 65), (95, 65)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire backbones at y=35 and y=65 connecting plants
    for wx in range(25, 96):
        actions.append((Tool.WIRE, wx, 35))
        actions.append((Tool.WIRE, wx, 65))
    # Vertical wire connecting the two backbones at x=25, x=60, x=95
    for wy in range(36, 65):
        actions.append((Tool.WIRE, 25, wy))
        actions.append((Tool.WIRE, 60, wy))
        actions.append((Tool.WIRE, 95, wy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood grid: 6 cols x 5 rows = 30 neighborhoods
    nh_cols = [15, 32, 50, 70, 88, 105]
    nh_rows = [15, 30, 50, 70, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 6
        if pop < 400:   return 10
        if pop < 800:   return 16
        if pop < 1500:  return 22
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    power_src = wm | pm

    # Build neighbor power mask (shift-based dilation)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Build neighbor road mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # PHASE 1: Ensure power plant near each active hood
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Horizontal wire backbone connecting hoods in same row
    for hy_row in nh_rows:
        row_hoods = sorted([(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row], key=lambda h: h[0])
        if len(row_hoods) < 2:
            continue
        xl = row_hoods[0][0]
        xr = row_hoods[-1][0]
        for cx in range(xl, xr + 1):
            if ib(cx, hy_row) and not bool(pm[hy_row, cx]) and not bool(wm[hy_row, cx]) and bool(em[hy_row, cx]):
                return (Tool.WIRE, cx, hy_row)

    # PHASE 3: Vertical wire connecting same-column hoods
    for hx_col in nh_cols:
        col_hoods = sorted([(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col], key=lambda h: h[1])
        if len(col_hoods) < 2:
            continue
        yt = col_hoods[0][1]
        yb = col_hoods[-1][1]
        for cy in range(yt, yb + 1):
            if ib(hx_col, cy) and not bool(pm[cy, hx_col]) and not bool(wm[cy, hx_col]) and bool(em[cy, hx_col]):
                return (Tool.WIRE, hx_col, cy)

    # PHASE 4: Roads perpendicular to wire (horizontal roads above/below wire rows)
    road_offsets = [-2, 2]
    hood_idx = step % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx]

    # Place horizontal roads flanking the wire backbone rows
    for hy_row in nh_rows:
        row_hoods = sorted([(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row], key=lambda h: h[0])
        if not row_hoods:
            continue
        xl = max(2, row_hoods[0][0] - 2)
        xr = min(WORLD_W - 3, row_hoods[-1][0] + 2)
        for roff in road_offsets:
            road_y = hy_row + roff
            if not (0 < road_y < WORLD_H - 1):
                continue
            for cx in range(xl, xr + 1):
                if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    return (Tool.ROAD, cx, road_y)

    # PHASE 5: Vertical roads connecting hood rows at each column
    if pop > 40:
        for hx_col in nh_cols:
            col_hoods = sorted([(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col], key=lambda h: h[1])
            if len(col_hoods) < 2:
                continue
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for rx_off in [-2, 2]:
                    rx = hx_col + rx_off
                    if not ib(rx, hy1):
                        continue
                    for cy in range(hy1 + road_offsets[1], hy2 + road_offsets[0]):
                        if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                            adj_road = any(ib(rx+dx, cy+dy) and bool(rm[cy+dy, rx+dx])
                                          for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)])
                            if adj_road or cy == hy1 + road_offsets[1]:
                                return (Tool.ROAD, rx, cy)

    # PHASE 6: Zone placement - fill cells near roads and power
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 7: Extend roads near powered zones
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # PHASE 8: Civic services
    if pop > 60:
        fire_spots = [(fx, fy)
                      for fx in range(8, WORLD_W, 20)
                      for fy in range(8, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2)
                        for px2 in range(12, WORLD_W, 24)
                        for py2 in range(12, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (25, 8), (60, 8), (95, 8),
            (25, 92), (60, 92), (95, 92),
            (8, 50), (112, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (6, 6), (114, 6), (6, 94), (114, 94),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (30, 10), (90, 10), (30, 90), (90, 90),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2000:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [
            (40, 5), (80, 5), (40, 94), (80, 94),
            (5, 35), (5, 65), (115, 35), (115, 65),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value near zones
    if pop > 150 and step % 4 == 0:
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 3 + i * 17) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # Fallback: extend wire from existing wires
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # Fallback: place new plant near unpowered active hood
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 14):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

# Simplified, more reliable city builder
# Key changes from parent:
# 1. Fixed init to actually bootstrap power+roads properly
# 2. Simpler, more reliable zone placement logic
# 3. Linear street grid instead of spine approach
# 4. More balanced zone mix from the start
# 5. Reactive to obs state throughout

def init(obs, state):
    """Bootstrap: two coal plants with wire + road grid."""
    actions = []
    # Plant 1 at center-left
    actions.append((Tool.COALPOWER, 20, 50))
    # Wire right from plant 1
    for x in range(21, 30):
        actions.append((Tool.WIRE, x, 50))
    # Plant 2 at center-right
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire left from plant 2
    for x in range(71, 80):
        actions.append((Tool.WIRE, x, 50))
    # Horizontal road along y=52 (below wire spine)
    for x in range(15, 95):
        actions.append((Tool.ROAD, x, 52))
    # Vertical roads
    for y in range(44, 58):
        actions.append((Tool.ROAD, 30, y))
        actions.append((Tool.ROAD, 60, y))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Grid of neighborhood centers - 10 cols x 8 rows = 80 hoods
    # Spaced 11 apart to give 3x3 zone + roads room
    nh_cols = list(range(8, 115, 11))   # ~10 cols
    nh_rows = list(range(8, 95, 11))    # ~8 rows
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Scale active hoods with population
    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 10
        if pop < 500:   return 20
        if pop < 1000:  return 35
        if pop < 2000:  return 55
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick hoods spread across map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find nearest empty spot for plant
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID connecting plants to hoods ----
    # Build horizontal wire rows at each nh_row
    for hy in nh_rows:
        if not any(hy == ah[1] for ah in active_hoods):
            continue
        # Find plant column in this row's vicinity
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        if not bool(np.any(pm[y0:y1, :])):
            continue
        # Lay wire across the row at hy connecting power
        for hx in nh_cols:
            if not any((hx, hy) in active_hoods or (c, hy) in active_hoods for c in nh_cols):
                continue
            # Wire from hx-5 to hx+5
            for dx in range(-6, 7):
                wx, wy = hx + dx, hy
                if not ib(wx, wy): continue
                if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
                    continue
                if not bool(em[wy, wx]):
                    continue
                # Only place if adjacent to existing wire/plant
                for adx, ady in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ax, ay = wx+adx, wy+ady
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        return (Tool.WIRE, wx, wy)

    # Vertical wire columns at each nh_col connecting rows
    for hx in nh_cols:
        if not any(hx == ah[0] for ah in active_hoods):
            continue
        x0, x1 = max(0, hx - 2), min(WORLD_W, hx + 3)
        if not bool(np.any(pm[:, x0:x1])):
            continue
        for hy in nh_rows:
            for dy in range(-6, 7):
                wx, wy = hx, hy + dy
                if not ib(wx, wy): continue
                if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]):
                    continue
                if not bool(em[wy, wx]):
                    continue
                for adx, ady in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ax, ay = wx+adx, wy+ady
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        return (Tool.WIRE, wx, wy)

    # ---- PHASE 3: ROAD GRID ----
    # Roads at hy+1 and hy-1 for each active hood row (flanking wire)
    for (hx, hy) in active_hoods:
        for ry in [hy - 1, hy + 1]:
            if not ib(hx, ry): continue
            for dx in range(-5, 6):
                rx, rrow = hx + dx, ry
                if not ib(rx, rrow): continue
                if bool(rm[rrow, rx]): continue
                if bool(pm[rrow, rx]): continue
                if not bool(em[rrow, rx]): continue
                # Only if adjacent to road or near wire
                for adx, ady in [(-1,0),(1,0)]:
                    ax2 = rx + adx
                    if ib(ax2, rrow) and bool(rm[rrow, ax2]):
                        return (Tool.ROAD, rx, rrow)
        # Roads at hx+1 and hx-1 (flanking vertical wire)
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-5, 6):
                rcx, rcy = rx, hy + dy
                if not ib(rcx, rcy): continue
                if bool(rm[rcy, rcx]): continue
                if bool(pm[rcy, rcx]): continue
                if not bool(em[rcy, rcx]): continue
                for ady2 in [-1, 1]:
                    ay2 = rcy + ady2
                    if ib(rcx, ay2) and bool(rm[ay2, rcx]):
                        return (Tool.ROAD, rcx, rcy)

    # ---- PHASE 4: EXTEND ROADS from existing into powered areas ----
    # Build nbr_power mask
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 80)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        # Target: 35% RES, 35% COM, 30% IND
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,45),(45,45),(75,45),(105,45),
            (15,75),(45,75),(75,75),(105,75),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (30,10),(60,10),(90,10),
            (10,35),(40,35),(70,35),(100,35),
            (30,60),(60,60),(90,60),
            (10,85),(40,85),(70,85),(100,85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (25,25),(65,25),(105,25),
            (25,65),(65,65),(105,65),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(5,90),(60,90),(114,90),(5,5),(60,5),(114,5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40,5),(80,5),(40,93),(80,93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 7: PARKS ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 37) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        sk2 = (step * 13) % len(wire_xs_arr)
        for off in range(min(len(wire_xs_arr), 80)):
            k = (sk2 + off * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Strategy: Dense grid city with alternating R/C/I zones, multiple power plants,
# grid road network, reactive zone placement based on actual coverage.
# Key differences from parent:
# 1. True grid road layout (horizontal + vertical every 6 tiles)
# 2. More balanced zone mix (R/C/I in 2:1:1 ratio)
# 3. Power plants placed at grid intersections early
# 4. Zones placed in checkerboard between roads
# 5. Civic buildings placed proactively

def init(obs, state):
    """Bootstrap: 3 coal plants along center + horizontal/vertical road+wire spines."""
    actions = []
    # Three coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine at x=30, 60, 90
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Horizontal roads flanking wire at y=50
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Vertical roads flanking plants
    for y in range(1, 99):
        actions.append((Tool.ROAD, 28, y))
        actions.append((Tool.ROAD, 32, y))
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
        actions.append((Tool.ROAD, 88, y))
        actions.append((Tool.ROAD, 92, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone mix: 50% R, 25% C, 25% I
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Grid: roads every 7 columns, 7 rows
    # Leaves 5-tile zones between roads
    road_cols = list(range(7, WORLD_W, 7))   # 7,14,21,...,112
    road_rows = list(range(7, WORLD_H, 7))   # 7,14,21,...,98
    wire_cols = list(range(14, WORLD_W, 14)) # 14,28,42,...
    wire_rows = list(range(14, WORLD_H, 14)) # 14,28,42,...

    # Scale active region with population
    def get_region():
        if pop < 100:
            return (20, 80, 35, 65)  # x0,x1,y0,y1
        elif pop < 300:
            return (10, 110, 25, 75)
        elif pop < 700:
            return (5, 115, 15, 85)
        else:
            return (2, 118, 2, 98)

    rx0, rx1, ry0, ry1 = get_region()

    # Step-based phases for balanced infrastructure vs zoning
    phase = step % 12

    # Phase 0-1: Build road grid
    if phase in (0, 1):
        for rc in road_cols:
            if not (rx0 <= rc <= rx1):
                continue
            for ry in range(ry0, ry1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    # Only extend if adjacent road exists or close to wire
                    adj = ((ry > 0 and bool(rm[ry-1, rc])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or
                           bool(near_power[ry, rc]))
                    if adj:
                        return (Tool.ROAD, rc, ry)
        for rr in road_rows:
            if not (ry0 <= rr <= ry1):
                continue
            for rx in range(rx0, rx1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    adj = ((rx > 0 and bool(rm[rr, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or
                           bool(near_power[rr, rx]))
                    if adj:
                        return (Tool.ROAD, rx, rr)

    # Phase 2-3: Extend wire grid
    if phase in (2, 3):
        for wc in wire_cols:
            if not (rx0 <= wc <= rx1):
                continue
            for wy in range(ry0, ry1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    adj = ((wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or
                           (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))))
                    if adj:
                        return (Tool.WIRE, wc, wy)
        for wr2 in wire_rows:
            if not (ry0 <= wr2 <= ry1):
                continue
            for wx2 in range(rx0, rx1):
                if not bool(wm[wr2, wx2]) and not bool(pm[wr2, wx2]) and bool(em[wr2, wx2]):
                    adj = ((wx2 > 0 and (bool(wm[wr2, wx2-1]) or bool(pm[wr2, wx2-1]))) or
                           (wx2 < WORLD_W-1 and (bool(wm[wr2, wx2+1]) or bool(pm[wr2, wx2+1]))))
                    if adj:
                        return (Tool.WIRE, wx2, wr2)

    # Phase 4: Place coal plants reactively at wire grid intersections if unpowered
    if phase == 4:
        for wc in wire_cols:
            for wr2 in wire_rows:
                # Check if this intersection area is powered
                if not (rx0 <= wc <= rx1 and ry0 <= wr2 <= ry1):
                    continue
                y0p, y1p = max(0, wr2-15), min(WORLD_H, wr2+16)
                x0p, x1p = max(0, wc-15), min(WORLD_W, wc+16)
                if not bool(np.any(pm[y0p:y1p, x0p:x1p])):
                    # Place plant nearby
                    for r in range(1, 10):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx, ny = wc+dx, wr2+dy
                                    if ib(nx, ny) and bool(em[ny, nx]):
                                        return (Tool.COALPOWER, nx, ny)

    # Phase 5: Connect wire from plants to grid
    if phase == 5:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            # Find cell near a wire_col/wire_row that isn't powered
            for wc in wire_cols:
                for wr2 in wire_rows:
                    if not (rx0 <= wc <= rx1 and ry0 <= wr2 <= ry1):
                        continue
                    if not bool(wm[wr2, wc]) and not bool(pm[wr2, wc]):
                        dists = np.abs(wire_xs - wc) + np.abs(wire_ys - wr2)
                        bi = np.argmin(dists)
                        bx, by = int(wire_xs[bi]), int(wire_ys[bi])
                        dx = 0 if bx == wc else (1 if wc > bx else -1)
                        dy = 0 if by == wr2 else (1 if wr2 > by else -1)
                        for nx, ny in [(bx+dx, by), (bx, by+dy)]:
                            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                                return (Tool.WIRE, nx, ny)

    # Phase 6-8: Zone placement - main growth engine
    if phase in (6, 7, 8, 9):
        zone_clear_cache = {}
        def zone_clear(zx, zy):
            if (zx, zy) in zone_clear_cache:
                return zone_clear_cache[(zx, zy)]
            ok = True
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    nr, nc = zy + dr, zx + dc
                    if not ib(nc, nr):
                        ok = False
                        break
                    if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                        ok = False
                        break
                if not ok:
                    break
            zone_clear_cache[(zx, zy)] = ok
            return ok

        # Candidate: empty, near road, near power, within active region
        cand = em & near_road & near_power
        cand[:ry0, :] = False
        cand[ry1:, :] = False
        cand[:, :rx0] = False
        cand[:, rx1:] = False
        # Don't place on road cols/rows
        for rc in road_cols:
            cand[:, max(0, rc-1):rc+2] = False
        for rr in road_rows:
            cand[max(0, rr-1):rr+2, :] = False
        # Don't place on wire cols/rows
        for wc in wire_cols:
            cand[:, max(0, wc-1):wc+2] = False
        for wr2 in wire_rows:
            cand[max(0, wr2-1):wr2+2, :] = False

        cys, cxs = np.where(cand)
        if len(cxs) > 0:
            # Sort by distance from city center (60,50), biased toward active region center
            cx_center = (rx0 + rx1) // 2
            cy_center = (ry0 + ry1) // 2
            dists = (np.abs(cxs - cx_center).astype(float) +
                     np.abs(cys - cy_center).astype(float))
            order = np.argsort(dists)
            tool = pick_tool()
            offset = (step * 13 + pop * 7) % max(len(order), 1)
            for i in range(min(len(order), 600)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

    # Phase 10-11: Civic services
    if phase == 10:
        if pop > 80:
            # Fire stations at road intersections
            for rc in road_cols[::3]:
                for rr in road_rows[::3]:
                    if ib(rc+1, rr+1) and bool(em[rr+1, rc+1]):
                        return (Tool.FIRESTATION, rc+1, rr+1)
        if pop > 250:
            for rc in road_cols[1::4]:
                for rr in road_rows[1::4]:
                    if ib(rc+1, rr+1) and bool(em[rr+1, rc+1]):
                        return (Tool.POLICESTATION, rc+1, rr+1)

    if phase == 11:
        if pop > 600:
            for sx, sy in [(40, 25), (80, 25), (40, 75), (80, 75), (60, 50)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)
        if pop > 1200:
            for nx2, ny2 in [(5, 5), (113, 5), (5, 93), (113, 93), (5, 50), (113, 50)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)
        if pop > 2000:
            for sx, sy in [(5, 93), (113, 5)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 3000:
            for sx, sy in [(50, 5), (70, 5), (50, 90), (70, 90)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # Fallback: extend roads greedily from existing roads
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 17) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 11) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2+dx, ry2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if bool(near_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 19) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2+dx, wy2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: coal plant + wire spine + flanking roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine horizontally from plant
    for x in range(55, 70):
        actions.append((Tool.WIRE, x, 50))
    # Roads flanking the wire spine
    for x in range(55, 70):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions[:20]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 3)

    # Infrastructure grid: wire rows and cols
    wire_rows = [15, 25, 35, 45, 55, 65, 75, 85]
    wire_cols = [10, 22, 34, 46, 58, 70, 82, 94, 108]

    # Cluster centers for zone placement
    clusters = [
        (60, 50), (40, 50), (80, 50), (60, 30), (60, 70),
        (80, 30), (40, 30), (80, 70), (40, 70), (100, 50),
        (20, 50), (60, 15), (60, 85), (100, 30), (20, 30),
        (100, 70), (20, 70), (110, 50), (10, 50),
    ]

    num_clusters = max(1, min(len(clusters), 1 + pop // 150 + total_zones // 10))

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 150:
            if ir < 0.28:
                return Tool.INDUSTRIAL
            if cr < 0.24:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.22:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.18:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 10

    # Phase 0: Place power plants near each active cluster
    if phase == 0:
        for i in range(num_clusters):
            cx, cy = clusters[i]
            plant_near = False
            for dy in range(-7, 8):
                for dx in range(-7, 8):
                    nx, ny = cx + dx, cy + dy
                    if ib(nx, ny) and bool(pm[ny, nx]):
                        plant_near = True
                        break
                if plant_near:
                    break
            if not plant_near:
                for r in range(0, 10):
                    for dx in range(-r, r + 1):
                        for dy in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                px, py = cx + dx, cy + dy
                                if ib(px, py) and bool(em[py, px]):
                                    clear = True
                                    for ddy in range(-1, 2):
                                        for ddx in range(-1, 2):
                                            if not ib(px + ddx, py + ddy) or \
                                               (not bool(em[py + ddy, px + ddx]) and
                                                not bool(wm[py + ddy, px + ddx])):
                                                clear = False
                                    if clear:
                                        return (Tool.COALPOWER, px, py)

    # Phase 1: Fill wire row gaps
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]))
                    right = wx < WORLD_W - 1 and (bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy - 1, wc]) or bool(pm[wy - 1, wc]))
                    dn = wy < WORLD_H - 1 and (bool(wm[wy + 1, wc]) or bool(pm[wy + 1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads above/below wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx - 1])) or \
                                  (rx < WORLD_W - 1 and bool(rm[ry, rx + 1])) or \
                                  (ry > 0 and bool(rm[ry - 1, rx])) or \
                                  (ry < WORLD_H - 1 and bool(rm[ry + 1, rx]))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # Phase 4: Roads flanking wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry - 1, rcx])) or \
                                  (ry < WORLD_H - 1 and bool(rm[ry + 1, rcx])) or \
                                  bool(rm[ry, max(0, rcx - 1)]) or \
                                  bool(rm[ry, min(WORLD_W - 1, rcx + 1)])
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # Phase 5: Extend wire toward unreached clusters
    if phase == 5:
        for i in range(num_clusters):
            cx, cy = clusters[i]
            reached = False
            for dy in range(-4, 5):
                for dx in range(-4, 5):
                    nx, ny = cx + dx, cy + dy
                    if ib(nx, ny) and (bool(wm[ny, nx]) or bool(pm[ny, nx])):
                        reached = True
                        break
                if reached:
                    break
            if not reached:
                all_powered_y, all_powered_x = np.where(wm | pm)
                if len(all_powered_x) > 0:
                    dists = np.abs(all_powered_x - cx) + np.abs(all_powered_y - cy)
                    idx = np.argmin(dists)
                    bwx, bwy = int(all_powered_x[idx]), int(all_powered_y[idx])
                    dx = cx - bwx
                    dy = cy - bwy
                    if abs(dx) >= abs(dy):
                        nx, ny = bwx + (1 if dx > 0 else -1), bwy
                    else:
                        nx, ny = bwx, bwy + (1 if dy > 0 else -1)
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # Phase 6: Cross streets between wire rows
    if phase == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            if not (0 < mid_y < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx - 1])) or \
                          (rx < WORLD_W - 1 and bool(rm[mid_y, rx + 1])) or \
                          (mid_y > 0 and bool(rm[mid_y - 1, rx])) or \
                          (mid_y < WORLD_H - 1 and bool(rm[mid_y + 1, rx]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 7: Reactively wire unpowered zones
    if phase == 7:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy), (bwx + dx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Reactively road unroaded zones
    if phase == 8:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 9: Extend roads into powered areas
    if phase == 9:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # === Civic services scaled to population ===
    if pop > 30:
        fire_spots = [
            (5, 5), (30, 5), (60, 5), (90, 5), (115, 5),
            (5, 25), (115, 25), (5, 50), (115, 50),
            (5, 75), (115, 75), (5, 95), (30, 95), (60, 95), (90, 95), (115, 95),
            (35, 50), (65, 50), (50, 20), (80, 20), (50, 80), (80, 80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (20, 15), (50, 15), (80, 15), (110, 15),
            (20, 35), (50, 35), (80, 35), (110, 35),
            (20, 55), (50, 55), (80, 55), (110, 55),
            (20, 75), (50, 75), (80, 75), (110, 75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(30, 20), (90, 20), (30, 80), (90, 80), (60, 50), (15, 50), (105, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 20), (115, 20), (5, 80), (115, 80),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value occasionally
    if pop > 100 and step % 7 == 4:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === Zone placement: closed-loop, reactive ===
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Keep zones off wire/road infrastructure corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr - 1):min(WORLD_H, wr + 2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc - 1):min(WORLD_W, wc + 2)] = False

    cys_arr, cxs_arr = np.where(cand_mask)

    if len(cxs_arr) > 0:
        scores = np.full(len(cxs_arr), 999999.0)
        for i in range(min(num_clusters, len(clusters))):
            cx2, cy2 = clusters[i]
            d = np.abs(cxs_arr - cx2).astype(float) + np.abs(cys_arr - cy2).astype(float)
            scores = np.minimum(scores, d)
        order = np.argsort(scores)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing roads into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire network
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire corridors + flanking roads."""
    actions = []
    # Two central coal plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire at y=50
    for x in range(1, 119):
        if x not in (40, 80):
            actions.append((Tool.WIRE, x, 50))
    # Vertical wires at x=40 and x=80
    for y in range(1, 99):
        if y != 50:
            actions.append((Tool.WIRE, 40, y))
        if y != 50:
            actions.append((Tool.WIRE, 80, y))
    # Roads flanking horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire corridors: horizontal rows and vertical cols
    wire_rows = [15, 30, 50, 65, 82]
    wire_cols = [20, 40, 60, 80, 100]

    # Dilate helper using numpy shifts
    def dilate(mask, r):
        result = mask.astype(bool).copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Neighborhood grid
    nh_positions = []
    for row in range(5):
        for col in range(6):
            cx = 10 + col * 20
            cy = 10 + row * 20
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            return [nh_positions[7], nh_positions[8], nh_positions[13], nh_positions[14]]
        elif pop < 400:
            return nh_positions[4:20]
        elif pop < 1000:
            return nh_positions[2:26]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # ---- PHASE 0: Ensure power plants near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 9

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left_ok = ib(wx-1, wr) and bool(row_wire[wx-1])
                    right_ok = ib(wx+1, wr) and bool(row_wire[wx+1])
                    if (left_ok or right_ok) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up_ok = ib(wc, wy-1) and bool(col_wire[wy-1])
                    dn_ok = ib(wc, wy+1) and bool(col_wire[wy+1])
                    if (up_ok or dn_ok) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Seed wire at corridor rows from nearest plant
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    px2, py2 = int(plant_xs[best]), int(plant_ys[best])
                    if ib(px2, wr) and bool(em[wr, px2]):
                        return (Tool.WIRE, px2, wr)
        # Seed wire at corridor cols from nearest plant
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    px2, py2 = int(plant_xs[best]), int(plant_ys[best])
                    if ib(wc, py2) and bool(em[py2, wc]):
                        return (Tool.WIRE, wc, py2)

    elif phase == 3:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Cross roads between corridor intersections (horizontal)
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            for wr_idx in range(len(wire_rows) - 1):
                r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
                mid_y = (r1 + r2) // 2
                for rx in range(c1 + 2, c2 - 1):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                              (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    elif phase == 6:
        # Cross roads between corridor intersections (vertical)
        for wr_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            for wc_idx in range(len(wire_cols) - 1):
                c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
                mid_x = (c1 + c2) // 2
                for ry in range(r1 + 2, r2 - 1):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                              (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 7:
        # Extend road from existing road in powered areas
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % len(road_xs2)
            for offset in range(min(len(road_xs2), 120)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # Wire extension from existing wire toward unpowered hoods
        unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
        if unpowered:
            wire_ys_arr, wire_xs_arr = np.where(wm | pm)
            if len(wire_xs_arr) > 0:
                target_hx, target_hy = unpowered[0]
                dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
                dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
                dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT (every step after infra phases) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Don't place zones directly on wire corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_grid = [(10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
                     (10, 25), (35, 25), (60, 25), (85, 25), (110, 25),
                     (10, 45), (60, 45), (110, 45),
                     (10, 65), (35, 65), (60, 65), (85, 65), (110, 65),
                     (10, 90), (35, 90), (60, 90), (85, 90), (110, 90)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_grid = [(25, 15), (75, 15), (50, 38), (100, 38),
                       (25, 58), (75, 58), (10, 82), (50, 82), (90, 82),
                       (115, 22), (5, 42), (115, 62)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(45, 42), (75, 42), (45, 62), (75, 62),
                    (15, 42), (105, 42), (15, 62), (105, 62),
                    (60, 10), (60, 88)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 3), (60, 96), (3, 50), (116, 50),
                      (30, 5), (90, 5), (30, 94), (90, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5), (60, 5), (60, 94)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92),
                    (5, 44), (5, 56), (112, 44), (112, 56)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Variation: Compact ring-road neighborhoods with better power distribution
# Key changes: 
# - Ring roads around each hood center (better road access for all zones)
# - More aggressive zone placement ratio (50% RES, 25% COM, 25% IND)
# - Multiple power plants distributed early
# - Denser neighborhoods spaced closer together
# - Horizontal wire backbone connecting all hoods

def init(obs, state):
    """Bootstrap: two coal plants + wire backbone + initial roads."""
    actions = []
    # Two plants for redundant power
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire backbone at y=50
    for x in range(5, 115):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at key columns
    for y in range(35, 66):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 90, y))
    # Initial roads near first plant
    for y in range(44, 57):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
    for x in range(24, 37):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 6 cols x 5 rows = 30 neighborhoods ----
    # Spaced 18 apart horizontally, 18 apart vertically
    nh_cols = [12, 30, 48, 66, 84, 102]
    nh_rows = [12, 28, 46, 64, 82]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 4
        if pop < 300:   return 6
        if pop < 700:   return 10
        if pop < 1500:  return 16
        if pop < 3000:  return 22
        if pop < 6000:  return 28
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- POWER COVERAGE MAP ----
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            if abs(dx2) + abs(dy2) > 4:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # ---- ROAD COVERAGE MAP ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            if abs(dx2) + abs(dy2) > 2:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANT for each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(2, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE BACKBONE - horizontal lines through hoods ----
    # Each hood row gets a horizontal wire backbone
    hood_idx = step % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_idx + i_h) % len(active_hoods)]

        # Horizontal wire at hy
        for dx in range(-7, 8):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            # Only extend if adjacent to wire/plant
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

        # Vertical wire at hx
        for dy in range(-7, 8):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        break

    # ---- PHASE 3: RING ROADS around each hood ----
    # Each hood gets a ring road at radius 6 (offset ±6 from center)
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx]
    ring_r = 6

    # Build the ring: top/bottom horizontal roads
    for dx in range(-ring_r, ring_r + 1):
        for sign in [-1, 1]:
            rx, ry = hx + dx, hy + sign * ring_r
            if ib(rx, ry) and not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
                if bool(nbr_power[ry, rx]) or bool(pm[hy, hx + dx]):
                    return (Tool.ROAD, rx, ry)

    # Left/right vertical roads
    for dy in range(-ring_r, ring_r + 1):
        for sign in [-1, 1]:
            rx, ry = hx + sign * ring_r, hy + dy
            if ib(rx, ry) and not bool(rm[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: CROSS ROADS through hood center ----
    # Horizontal road through hood
    for dx in range(-ring_r, ring_r + 1):
        rx, ry = hx + dx, hy
        if ib(rx, ry) and not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and bool(em[ry, rx]):
            if bool(nbr_power[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # Vertical road through hood
    for dy in range(-ring_r, ring_r + 1):
        rx, ry = hx, hy + dy
        if ib(rx, ry) and not bool(rm[ry, rx]) and not bool(pm[ry, rx]) and bool(em[ry, rx]):
            return (Tool.ROAD, rx, ry)

    # ---- PHASE 5: CONNECT HOODS with wire ----
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            if hy1 == hy2 and abs(hx2 - hx1) == 18 and hx2 > hx1:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and abs(hy2 - hy1) == 18 and hy2 > hy1:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)
        break

    # ---- PHASE 6: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 50% RES, 25% COM, 25% IND
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        for fx in range(9, WORLD_W, 18):
            for fy in range(9, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for px2 in range(14, WORLD_W, 22):
            for py2 in range(14, WORLD_H, 22):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for sx in range(18, WORLD_W, 30):
            for sy in range(18, WORLD_H, 30):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaport_spots = [(10, 92), (110, 92), (10, 8), (110, 8), (60, 95), (60, 5)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airport_spots = [(20, 6), (55, 6), (90, 6), (20, 94), (55, 94), (90, 94)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrade for high pop
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(30, 50), (90, 50), (60, 20), (60, 80),
                         (15, 20), (105, 20), (15, 80), (105, 80)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value boost
    if pop > 120 and step % 5 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 17) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: plant at uncovered hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 14):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spine + initial roads."""
    actions = []
    # Two plants: left cluster and right cluster
    # Left plant at (30, 50), Right plant at (80, 50)
    for cx, cy in [(30, 50), (80, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire cross from each plant
        for dx in range(-3, 4):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-3, 4):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking wire column
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Wire connecting the two plants horizontally
    for x in range(34, 80):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Anchors: two columns of neighborhoods
    # Left column: x=30, Right column: x=80, rows: 20,35,50,65,80
    anchors = []
    for col_i, cx in enumerate([20, 40, 60, 80, 100]):
        for row_i, cy in enumerate([20, 35, 50, 65, 80]):
            anchors.append((cx, cy, col_i * 5 + row_i))

    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 600:   return 6
        if pop < 1000:  return 9
        if pop < 1500:  return 12
        if pop < 2500:  return 16
        return 25

    active = anchors[:num_active()]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active anchor ----
    for (px, py, idx) in active:
        has_plant = any(
            ib(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dx in range(-8, 9) for dy in range(-8, 9)
        )
        if not has_plant:
            # Place plant at anchor or nearby empty spot
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: EXTEND WIRE from existing wire/plant toward active anchors ----
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0:
        for (px, py, idx) in active:
            dists = np.abs(wire_xs.astype(float) - px) + np.abs(wire_ys.astype(float) - py)
            min_dist = float(np.min(dists))
            if min_dist > 3:
                closest_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[closest_k]), int(wire_ys[closest_k])
                dx = 1 if px > wx else (-1 if px < wx else 0)
                dy = 1 if py > wy else (-1 if py < wy else 0)
                for (ddx, ddy) in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: BUILD WIRE SPINES (vertical) for each anchor column ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            for dy in range(-5, 6):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            ext = min(20, 6 + pop // 100)
            spine_top = max(2, py - ext)
            spine_bot = min(WORLD_H - 3, py + ext)
            max_wr = max(wire_col)
            min_wr = min(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 4: HORIZONTAL WIRE between anchors in same row ----
    row_groups = {}
    for (px, py, idx) in active:
        row_groups.setdefault(py, []).append(px)
    for row_y, group in row_groups.items():
        group_sorted = sorted(group)
        for i in range(len(group_sorted) - 1):
            x1, x2 = group_sorted[i], group_sorted[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- PHASE 5: BUILD ROADS flanking wire spines ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            continue
        # Roads on both sides of wire column
        cycle_off = (step + idx * 7) % max(len(wire_col), 1)
        for k in range(min(len(wire_col), 12)):
            wr = wire_col[(cycle_off + k) % len(wire_col)]
            for side in [px - 1, px + 1]:
                if ib(side, wr) and bool(em[wr, side]) and not bool(pm[wr, side]):
                    return (Tool.ROAD, side, wr)

    # ---- PHASE 6: HORIZONTAL ROADS connecting neighborhoods ----
    for (px, py, idx) in active:
        for dx in range(-10, 11):
            rx = px + dx
            if not ib(rx, py):
                continue
            if bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near = any(
                    ib(rx + d, py) and (bool(rm[py, rx + d]) or bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near:
                    return (Tool.ROAD, rx, py)

    # ---- PHASE 7: ZONE PLACEMENT (closed-loop, reactive) ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target mix: 50% res, 25% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # More aggressive commercial/industrial balance
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks: road within 2, wire/plant within 6
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, idx) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 8: EXTEND ROADS from existing roads near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 7) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 9) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 100:
        firestations = [
            (25, 25), (55, 25), (85, 25), (110, 25),
            (25, 45), (55, 45), (85, 45), (110, 45),
            (25, 65), (55, 65), (85, 65), (110, 65),
            (25, 85), (55, 85), (85, 85), (110, 85),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        polices = [
            (35, 30), (65, 30), (95, 30),
            (35, 55), (65, 55), (95, 55),
            (35, 75), (65, 75), (95, 75),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (15, 15), (60, 15), (105, 15),
            (15, 85), (60, 85), (105, 85),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 90), (110, 10), (10, 10), (110, 90)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- PHASE 10: ADD NUCLEAR PLANT for high pop ----
    if pop > 2000:
        # Add nuclear plants near high-density anchors
        for (px, py, idx) in active:
            for r in range(3, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.NUCLEARPOWER, nx, ny)

    # ---- FALLBACK: extend wire from any wire tile ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 50)):
            k = (step_k2 + offset * 7) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
