def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure enough power plants ----
    # Place plants on a grid, ~1 per 20x20 area
    plant_positions = []
    for py in range(10, 95, 20):
        for px in range(10, 115, 22):
            plant_positions.append((px, py))

    for ppx, ppy in plant_positions:
        if not ib(ppx, ppy):
            continue
        # Check if there's already a plant nearby
        x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
        y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Extend wire network reactively ----
    # Find zones that are not powered and try to extend wire toward them
    unpowered_zones = zone_tiles & ~near_power
    uz_ys, uz_xs = np.where(unpowered_zones)

    # Find locations adjacent to existing power that are empty
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles
    wire_cand[0:2,:] = False; wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False; wire_cand[:,WORLD_W-2:] = False

    if len(uz_xs) > 0 and np.any(wire_cand):
        wys_c, wxs_c = np.where(wire_cand)
        # Find wire candidate closest to an unpowered zone
        best_d = 1e9; best_k = -1
        stride_u = max(1, len(uz_xs) // 20)
        stride_w = max(1, len(wxs_c) // 200)
        for i in range(0, len(wxs_c), stride_w):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - uz_xs[j]) + abs(cy - uz_ys[j])
                    for j in range(0, len(uz_xs), stride_u))
            if d < best_d:
                best_d = d; best_k = i
        if best_k >= 0:
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # Also extend wires along grid rows/cols for coverage
    wire_rows = list(range(10, 95, 20))
    wire_cols = list(range(10, 115, 22))

    for wr in wire_rows:
        row_wp = wm[wr, :] | pm[wr, :]
        if not row_wp.any():
            if ib(60, wr) and em[wr, 60]:
                return (Tool.WIRE, 60, wr)
            continue
        indices = np.where(row_wp)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and em[wr, left-1] and not rm[wr, left-1]:
            return (Tool.WIRE, left-1, wr)
        if right < WORLD_W - 3 and em[wr, right+1] and not rm[wr, right+1]:
            return (Tool.WIRE, right+1, wr)

    for wc in wire_cols:
        col_wp = wm[:, wc] | pm[:, wc]
        if not col_wp.any():
            if ib(wc, 50) and em[50, wc]:
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_wp)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and em[top-1, wc] and not rm[top-1, wc]:
            return (Tool.WIRE, wc, top-1)
        if bot < WORLD_H - 3 and em[bot+1, wc] and not rm[bot+1, wc]:
            return (Tool.WIRE, wc, bot+1)

    # ---- PHASE 3: Road network ----
    # Roads offset from wire rows/cols by 4 tiles
    road_rows = []
    for wr in wire_rows:
        road_rows.append(wr - 4)
        road_rows.append(wr + 4)
    road_cols = []
    for wc in wire_cols:
        road_cols.append(wc - 4)
        road_cols.append(wc + 4)
    road_rows = sorted(set(r for r in road_rows if 3 < r < WORLD_H - 3))
    road_cols = sorted(set(c for c in road_cols if 3 < c < WORLD_W - 3))

    # Find zones near power but not near road - extend roads toward them
    needs_road = zone_tiles & near_power & ~near_road
    nr_ys, nr_xs = np.where(needs_road)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand = em & adj_to_road & ~zone_tiles & ~wm & ~pm
    road_cand[0:2,:] = False; road_cand[WORLD_H-2:,:] = False
    road_cand[:,0:2] = False; road_cand[:,WORLD_W-2:] = False

    if len(nr_xs) > 0 and np.any(road_cand):
        rys_c, rxs_c = np.where(road_cand)
        best_d = 1e9; best_k = -1
        stride_nr = max(1, len(nr_xs) // 20)
        stride_r = max(1, len(rxs_c) // 200)
        for i in range(0, len(rxs_c), stride_r):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - nr_xs[j]) + abs(cy - nr_ys[j])
                    for j in range(0, len(nr_xs), stride_nr))
            if d < best_d:
                best_d = d; best_k = i
        if best_k >= 0:
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Extend road grid
    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            if ib(60, rr) and em[rr, 60] and not pm[rr, 60] and not wm[rr, 60]:
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 3 and em[rr, left-1] and not pm[rr, left-1] and not wm[rr, left-1]:
            return (Tool.ROAD, left-1, rr)
        if right < WORLD_W-4 and em[rr, right+1] and not pm[rr, right+1] and not wm[rr, right+1]:
            return (Tool.ROAD, right+1, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and em[50, rc] and not pm[50, rc] and not wm[50, rc]:
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 3 and em[top-1, rc] and not pm[top-1, rc] and not wm[top-1, rc]:
            return (Tool.ROAD, rc, top-1)
        if bot < WORLD_H-4 and em[bot+1, rc] and not pm[bot+1, rc] and not wm[bot+1, rc]:
            return (Tool.ROAD, rc, bot+1)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        # Score: prefer spots close to road and to existing zones
        if total_zones > 0:
            zys2, zxs2 = np.where(zone_tiles)
            road_ys, road_xs = np.where(rm)
            stride_z = max(1, len(zxs2) // 80)
            stride_rd = max(1, len(road_xs) // 80) if len(road_xs) > 0 else 1

            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zxs2), stride_z):
                d = np.abs(cxs_arr - zxs2[i]).astype(float) + np.abs(cys_arr - zys2[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)

            if len(road_xs) > 0:
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), stride_rd):
                    d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                    road_dist = np.minimum(road_dist, d)
                score = zone_dist * 0.3 + road_dist * 0.7
            else:
                score = zone_dist
        else:
            score = (np.abs(cxs_arr - 45) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 11 + pop * 5) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on pop ----
    if pop > 80:
        fire_spots = [(fx, fy) for fy in range(10, 96, 15) for fx in range(10, 112, 22)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 250:
        police_spots = [(px2, py2) for py2 in range(12, 92, 18) for px2 in range(12, 110, 26)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_spots = [(pkx, pky) for pky in range(14, 90, 12) for pkx in range(14, 108, 16)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 800:
        stadium_spots = [(sx, sy) for sy in range(18, 88, 28) for sx in range(18, 104, 32)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        airport_spots = [(55, 8), (65, 8), (55, 91), (65, 91),
                         (8, 44), (111, 44), (8, 56), (111, 56)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_spots = [(8, 50), (111, 50), (60, 5), (60, 94)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: place wire adjacent to power
    if np.any(wire_cand):
        wys_c, wxs_c = np.where(wire_cand)
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    return None

