def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Wire corridors: denser grid
    wire_rows = [10, 22, 34, 46, 50, 54, 66, 78, 90]
    wire_cols = [10, 22, 30, 42, 60, 78, 90, 98, 110]

    # ---- PHASE 0: ENSURE PLANTS ----
    plant_positions = [
        (30, 25), (90, 25), (30, 75), (90, 75),
        (60, 10), (60, 90), (5, 50), (115, 50),
        (15, 15), (105, 15), (15, 85), (105, 85),
    ]
    for px, py in plant_positions:
        x0, x1 = max(0, px-8), min(WORLD_W, px+9)
        y0, y1 = max(0, py-8), min(WORLD_H, py+9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if np.any(row_power):
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        left = wx > 0 and bool(row_power[wx-1])
                        right = wx < WORLD_W-1 and bool(row_power[wx+1])
                        if (left or right) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                            return (Tool.WIRE, wx, wr)
            else:
                # Seed from nearest plant
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)

    elif phase == 1:
        # Vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if np.any(col_power):
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        up = wy > 0 and bool(col_power[wy-1])
                        down = wy < WORLD_H-1 and bool(col_power[wy+1])
                        if (up or down) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                            return (Tool.WIRE, wc, wy)
            else:
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx else -1
                    for nx in range(bpx, wc, step_x):
                        if ib(nx, bpy) and bool(em[bpy, nx]):
                            return (Tool.WIRE, nx, bpy)

    elif phase == 2:
        # Roads adjacent to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads adjacent to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Extra horizontal roads between wire rows (mid-block access)
        for i in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[i], wire_rows[i+1]
            if wr2 - wr1 < 4:
                continue
            mid = (wr1 + wr2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(near_power[mid, rx]) and bool(em[mid, rx]) and not bool(pm[mid, rx]):
                    # Adjacent existing road?
                    adj = (ib(rx-1, mid) and bool(rm[mid, rx-1])) or \
                          (ib(rx+1, mid) and bool(rm[mid, rx+1])) or \
                          (ib(rx, mid-1) and bool(rm[mid-1, rx])) or \
                          (ib(rx, mid+1) and bool(rm[mid+1, rx]))
                    if adj:
                        return (Tool.ROAD, rx, mid)

    elif phase == 5:
        # Extra vertical roads between wire cols
        for i in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[i], wire_cols[i+1]
            if wc2 - wc1 < 4:
                continue
            mid = (wc1 + wc2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(near_power[ry, mid]) and bool(em[ry, mid]) and not bool(pm[ry, mid]):
                    adj = (ib(mid-1, ry) and bool(rm[ry, mid-1])) or \
                          (ib(mid+1, ry) and bool(rm[ry, mid+1])) or \
                          (ib(mid, ry-1) and bool(rm[ry-1, mid])) or \
                          (ib(mid, ry+1) and bool(rm[ry+1, mid]))
                    if adj:
                        return (Tool.ROAD, mid, ry)

    elif phase == 6:
        # Wire intersection reinforcement
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc-1])) or (wc < WORLD_W-1 and bool(wm[wr, wc+1]))
                col_ok = (wr > 0 and bool(wm[wr-1, wc])) or (wr < WORLD_H-1 and bool(wm[wr+1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 7:
        # Power unpowered roads
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Extend road to reach powered empty areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H-3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W-3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # phase 9: extend wire from existing wire
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            step_k2 = (step * 13) % len(wire_xs3)
            for offset in range(min(len(wire_xs3), 60)):
                k = (step_k2 + offset * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2+dx3, wy2+dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT (closed-loop, dominant action) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            # Prefer building clusters in two "neighborhoods": left (x<60) and right (x>60)
            dist_center_x = min(abs(x - 30), abs(x - 90))
            scores[i] += 1.0 / (1.0 + dist_center_x / 30.0)
            scores[i] += 0.5 / (1.0 + abs(y - 50) / 50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_positions = [
            (20, 10), (60, 10), (100, 10),
            (20, 35), (60, 35), (100, 35),
            (20, 60), (60, 60), (100, 60),
            (20, 85), (60, 85), (100, 85),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (10, 22), (50, 22), (70, 22), (110, 22),
            (10, 45), (50, 45), (70, 45), (110, 45),
            (10, 68), (50, 68), (70, 68), (110, 68),
            (10, 87), (50, 87), (70, 87), (110, 87),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (20, 25), (100, 25), (20, 75), (100, 75),
            (60, 25), (60, 75), (40, 50), (80, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 92), (115, 92), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 200 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:2, :] = False
        park_cands[WORLD_H-2:, :] = False
        park_cands[:, 0:2] = False
        park_cands[:, WORLD_W-2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: place road adjacent to existing road in powered area
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Radial city design with central power hub, mixed zones, and reactive growth
# Key differences from parent:
# 1. Radial road layout from center instead of grid
# 2. More aggressive commercial/industrial mix (different zone ratios)
# 3. Compact cluster expansion that reacts to actual powered/road coverage
# 4. Multiple smaller power plants spread proactively
# 5. Uses actual tile state to decide what's needed next

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + initial roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Second power plant
    actions.append((Tool.COALPOWER, 30, 25))
    actions.append((Tool.COALPOWER, 90, 25))
    actions.append((Tool.COALPOWER, 30, 75))
    actions.append((Tool.COALPOWER, 90, 75))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Roads along the spines (offset by 1)
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    for y in range(1, 99):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # More aggressive commercial and industrial ratios
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 30% industrial, 35% commercial, 35% residential
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire corridors - cross pattern plus diagonals
    wire_rows = [25, 37, 50, 63, 75]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    # Neighborhood centers in rings around center (60, 50)
    # Ring 1: close in
    # Ring 2: medium distance
    # Ring 3: far out
    def get_all_hoods():
        hoods = []
        # Center
        hoods.append((60, 50))
        # Ring 1 (distance ~12)
        for angle_idx in range(8):
            angle = angle_idx * math.pi / 4
            rx = int(60 + 12 * math.cos(angle))
            ry = int(50 + 12 * math.sin(angle))
            rx = max(5, min(WORLD_W-5, rx))
            ry = max(5, min(WORLD_H-5, ry))
            hoods.append((rx, ry))
        # Ring 2 (distance ~25)
        for angle_idx in range(12):
            angle = angle_idx * math.pi / 6
            rx = int(60 + 25 * math.cos(angle))
            ry = int(50 + 25 * math.sin(angle))
            rx = max(5, min(WORLD_W-5, rx))
            ry = max(5, min(WORLD_H-5, ry))
            hoods.append((rx, ry))
        # Ring 3 (distance ~40)
        for angle_idx in range(16):
            angle = angle_idx * math.pi / 8
            rx = int(60 + 40 * math.cos(angle))
            ry = int(50 + 40 * math.sin(angle))
            rx = max(5, min(WORLD_W-5, rx))
            ry = max(5, min(WORLD_H-5, ry))
            hoods.append((rx, ry))
        # Grid fill for very high pop
        for gx in range(10, 115, 15):
            for gy in range(10, 95, 15):
                hoods.append((gx, gy))
        return hoods

    all_hoods = get_all_hoods()

    def get_active_hoods():
        if pop < 100:
            return all_hoods[:5]
        elif pop < 300:
            return all_hoods[:12]
        elif pop < 700:
            return all_hoods[:22]
        elif pop < 1500:
            return all_hoods[:35]
        elif pop < 3000:
            return all_hoods[:50]
        else:
            return all_hoods

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Phase 1: Ensure power plants near active hoods
    # Place plant if no power within 20 tiles of active hood
    if step % 5 == 0:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
            y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find empty spot near hood
                for r in range(2, 15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # Phase 2: Extend wire corridors from power sources
    if step % 6 in (0, 1):
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    if step % 6 in (2, 3):
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads along wire corridors
    if step % 6 == 4:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    if step % 6 == 5:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # Civic services - placed reactively based on population
    if pop > 50:
        # Fire stations every 20 tiles
        fire_spots = [(x, y) for y in range(10, 95, 20) for x in range(10, 115, 20)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [(x, y) for y in range(15, 95, 22) for x in range(15, 115, 25)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50),
                         (45, 40), (75, 60), (20, 50), (100, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Switch some coal to nuclear for higher power capacity
        nuke_spots = [(5, 50), (115, 50), (60, 5), (60, 95),
                      (5, 25), (115, 25), (5, 75), (115, 75)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 90), (110, 90), (5, 10), (110, 10), (60, 90)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(45, 5), (75, 5), (45, 92), (75, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Zone placement - main loop, reactive to actual powered+roaded tiles
    cand_mask = em & near_road & near_power
    # Buffer from edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors themselves
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary starting offset to avoid always picking same spot
        offset = (step * 13 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # Parks for land value boost
    if pop > 100 and step % 5 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 11) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend roads from existing roads into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 17) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 11) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Wire toward unpowered active hoods
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Extend any wire to cover more area
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 19) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: place coal plant near unpowered hood
    for (hx, hy) in unpowered_hoods:
        for r in range(2, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

# Strategy: Dense compact neighborhoods with proper power+road+zone grids
# Key changes from parent:
# 1. Fixed neighborhood layout with explicit zone grid patterns
# 2. Better zone ratio (more residential, balanced com/ind)
# 3. Direct wire connections from plant to zones
# 4. Road grid pattern instead of spine-flanking approach
# 5. Simpler, more reliable build sequence

def init(obs, state):
    """Bootstrap: two coal plants with wire connections."""
    actions = []
    # Plant 1: center-left
    actions.append((Tool.COALPOWER, 30, 50))
    # Wire from plant rightward
    for dx in range(1, 6):
        actions.append((Tool.WIRE, 30 + dx, 50))
    # Wire upward
    for dy in range(1, 6):
        actions.append((Tool.WIRE, 30, 50 - dy))
    # Road grid seed
    actions.append((Tool.ROAD, 33, 47))
    actions.append((Tool.ROAD, 33, 48))
    actions.append((Tool.ROAD, 33, 49))
    actions.append((Tool.ROAD, 34, 47))
    actions.append((Tool.ROAD, 35, 47))
    # Plant 2: center-right
    actions.append((Tool.COALPOWER, 80, 50))
    for dx in range(1, 6):
        actions.append((Tool.WIRE, 80 - dx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 2 <= x < WORLD_W - 2 and 2 <= y < WORLD_H - 2

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Neighborhood centers - spread across map
    # Each neighborhood has a coal plant as anchor
    hoods = [
        (30, 30), (60, 30), (90, 30),
        (30, 55), (60, 55), (90, 55),
        (30, 80), (60, 80), (90, 80),
        (15, 15), (105, 15), (15, 85), (105, 85),
    ]

    # How many hoods to activate based on pop
    def n_active():
        if pop < 100:   return 2
        if pop < 500:   return 4
        if pop < 1500:  return 6
        if pop < 3000:  return 9
        return len(hoods)

    active_hoods = hoods[:n_active()]

    # --- STEP 1: Ensure each active hood has a power plant ---
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 6), min(WORLD_W, hx + 7)
        y0, y1 = max(0, hy - 6), min(WORLD_H, hy + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try to place plant at hood center, search outward
            for r in range(10):
                placed = False
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break
            return (Tool.COALPOWER, hx, hy)

    # --- STEP 2: Build wire network ---
    # For each hood, find its plant and extend wires in a cross pattern
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)

        # Find plant location in this hood
        plant_locs = []
        for py in range(y0, y1):
            for px in range(x0, x1):
                if bool(pm[py, px]):
                    plant_locs.append((px, py))

        if not plant_locs:
            continue

        plx, ply = plant_locs[0]

        # Wire cross: horizontal and vertical from plant
        # Horizontal wire: 12 tiles each direction
        for dx in [-1, 1]:
            for dist in range(1, 16):
                wx, wy = plx + dx * dist, ply
                if not ib(wx, wy):
                    break
                if bool(pm[wy, wx]):
                    break
                if not bool(wm[wy, wx]) and bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)

        # Vertical wire
        for dy in [-1, 1]:
            for dist in range(1, 16):
                wx, wy = plx, ply + dy * dist
                if not ib(wx, wy):
                    break
                if bool(pm[wy, wx]):
                    break
                if not bool(wm[wy, wx]) and bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)

    # --- STEP 3: Connect hoods with wire backbone ---
    # Horizontal connections between hoods in same row
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods:
            if hx2 <= hx1 or abs(hy1 - hy2) > 10:
                continue
            # Wire along shared Y
            shared_y = (hy1 + hy2) // 2
            # Find nearest wire on each side
            left_wire = None
            right_wire = None
            for cx in range(hx1, hx2 + 1):
                if ib(cx, shared_y) and bool(wm[shared_y, cx]):
                    if left_wire is None:
                        left_wire = cx
                    right_wire = cx

            # Fill gap
            if left_wire is not None and right_wire is not None:
                for cx in range(left_wire + 1, right_wire):
                    if ib(cx, shared_y) and bool(em[shared_y, cx]) and not bool(pm[shared_y, cx]):
                        return (Tool.WIRE, cx, shared_y)
            elif left_wire is not None:
                cx = left_wire + 1
                if ib(cx, shared_y) and bool(em[shared_y, cx]) and not bool(pm[shared_y, cx]):
                    return (Tool.WIRE, cx, shared_y)

    # --- STEP 4: Build road grid around each hood ---
    # Road pattern: grid every 4 tiles, centered on hood
    for (hx, hy) in active_hoods:
        # Road grid: 3 horizontal roads and 3 vertical roads
        road_offsets = [-4, 0, 4]
        extent = 12

        # Vertical roads (constant x, varying y)
        for ox in road_offsets:
            rx = hx + ox
            if not ib(rx, hy):
                continue
            for ry in range(hy - extent, hy + extent + 1):
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Check if adjacent wire (powered area)
                    has_power_nearby = False
                    for dx2 in range(-8, 9):
                        for dy2 in range(-8, 9):
                            nx, ny = rx + dx2, ry + dy2
                            if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                                if bool(wm[ny, nx]) or bool(pm[ny, nx]):
                                    has_power_nearby = True
                                    break
                        if has_power_nearby:
                            break
                    if has_power_nearby:
                        return (Tool.ROAD, rx, ry)

        # Horizontal roads
        for oy in road_offsets:
            ry = hy + oy
            if not ib(hx, ry):
                continue
            for rx in range(hx - extent, hx + extent + 1):
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    has_power_nearby = False
                    for dx2 in range(-8, 9):
                        for dy2 in range(-8, 9):
                            nx, ny = rx + dx2, ry + dy2
                            if 0 <= nx < WORLD_W and 0 <= ny < WORLD_H:
                                if bool(wm[ny, nx]) or bool(pm[ny, nx]):
                                    has_power_nearby = True
                                    break
                        if has_power_nearby:
                            break
                    if has_power_nearby:
                        return (Tool.ROAD, rx, ry)

    # --- STEP 5: Place zones in road+power coverage ---
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not (0 <= nc < WORLD_W and 0 <= nr < WORLD_H):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Target: 60% res, 20% com, 20% ind
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Build power proximity mask (within 10 tiles of wire or plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    wire_ys, wire_xs = np.where(wm | pm)
    for i in range(len(wire_xs)):
        wx, wy = int(wire_xs[i]), int(wire_ys[i])
        y0 = max(0, wy - 10); y1 = min(WORLD_H, wy + 11)
        x0 = max(0, wx - 10); x1 = min(WORLD_W, wx + 11)
        nbr_power[y0:y1, x0:x1] = True

    # Build road proximity mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    road_ys, road_xs = np.where(rm)
    for i in range(len(road_xs)):
        rx, ry = int(road_xs[i]), int(road_ys[i])
        y0 = max(0, ry - 3); y1 = min(WORLD_H, ry + 4)
        x0 = max(0, rx - 3); x1 = min(WORLD_W, rx + 4)
        nbr_road[y0:y1, x0:x1] = True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cand_ys, cand_xs = np.where(cand_mask)
    if len(cand_xs) > 0:
        # Score by distance to nearest active hood
        best_dist = np.full(len(cand_xs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cand_xs - hx) + np.abs(cand_ys - hy)
            best_dist = np.minimum(best_dist, d)

        # Prefer candidates close to hoods
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)

        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cand_xs[k]), int(cand_ys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # --- STEP 6: Extend roads from existing road network ---
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if bool(nbr_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # --- STEP 7: Civic services based on population ---
    if pop > 300:
        fire_spots = [(25, 25), (55, 25), (85, 25), (25, 55), (55, 55), 
                      (85, 55), (25, 80), (55, 80), (85, 80)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 800:
        police_spots = [(35, 35), (65, 35), (95, 35), (35, 65), 
                        (65, 65), (95, 65), (35, 85), (65, 85)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 2000:
        for (sx, sy) in [(45, 45), (75, 45), (45, 70), (75, 70)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 4000:
        for (sx, sy) in [(10, 90), (110, 90)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # --- STEP 8: Parks near roads to boost land value ---
    if pop > 500 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py, px = int(park_ys[idx]), int(park_xs[idx])
            if ib(px, py) and bool(em[py, px]):
                return (Tool.PARK, px, py)

    # --- FALLBACK: extend wire ---
    if len(wire_xs) > 0:
        step_k2 = (step * 13) % len(wire_xs)
        for offset in range(min(len(wire_xs), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire spine and initial roads."""
    actions = []
    # Three power plants along the horizontal center
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire spine at y=50
    for x in range(18, 103, 2):
        actions.append((Tool.WIRE, x, 50))
    # Roads flanking the spine
    for x in range(1, 119, 3):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions[:20]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 50% res, 25% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire/road grid backbone
    wire_rows = [10, 25, 40, 50, 60, 75, 90]
    wire_cols = [10, 25, 40, 55, 65, 80, 95, 110]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- STEP 1: Ensure plants exist in each quadrant ----
    plant_targets = [
        (20, 50), (60, 50), (100, 50),
        (20, 25), (60, 25), (100, 25),
        (20, 75), (60, 75), (100, 75),
        (20, 10), (60, 10), (100, 10),
        (20, 90), (60, 90), (100, 90),
    ]
    if step % 7 == 0:
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 8):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if placed:
                        break

    # ---- STEP 2: Wire rows - fill gaps ----
    if step % 7 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # ---- STEP 3: Wire cols - fill gaps ----
    if step % 7 == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ---- STEP 4: Roads along wire rows ----
    if step % 7 == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                       (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                       (ry > 0 and bool(rm[ry-1, rx])) or \
                                       (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                            if adj_road or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # ---- STEP 5: Roads along wire cols ----
    if step % 7 == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry2 in range(1, WORLD_H - 1):
                    if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                        if bool(wm[ry2, wc]) or bool(pm[ry2, wc]):
                            adj_road = (ry2 > 0 and bool(rm[ry2-1, rcx])) or \
                                       (ry2 < WORLD_H-1 and bool(rm[ry2+1, rcx])) or \
                                       bool(rm[ry2, max(0, rcx-1)]) or \
                                       bool(rm[ry2, min(WORLD_W-1, rcx+1)])
                            if adj_road or ry2 == 1:
                                return (Tool.ROAD, rcx, ry2)

    # ---- STEP 6: Wire unpowered zones reactively ----
    if step % 7 == 5:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- STEP 7: Cross streets ----
    if step % 7 == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # ---- CIVIC SERVICES reactive to population ----
    if pop > 30:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,25),(115,25),(5,50),(115,50),
            (5,75),(115,75),(5,95),(30,95),(60,95),(90,95),(115,95),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,35),(105,35),(15,65),(105,65),
            (15,85),(45,85),(75,85),(105,85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(35,20),(85,20),(35,80),(85,80),(60,50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 20), (115, 20), (5, 80), (115, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (primary closed-loop action) ----
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors themselves
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Active neighborhood centers scale with population
        if pop < 100:
            active_centers = [(60, 50), (45, 50), (75, 50), (60, 35), (60, 65)]
        elif pop < 500:
            active_centers = [(60, 50), (30, 50), (90, 50),
                               (60, 30), (60, 70), (30, 30), (90, 30), (30, 70), (90, 70)]
        elif pop < 2000:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 10 + row * 20
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 6 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire spine and flanking roads."""
    actions = []
    # Two plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        if x not in [30, 90]:
            actions.append((Tool.WIRE, x, 50))
    # Flanking roads
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Wire/road grid layout - denser than parent
    wire_rows = [8, 18, 28, 38, 48, 58, 68, 78, 88, 98]
    wire_cols = [8, 18, 28, 38, 48, 58, 68, 78, 88, 98, 108, 118]
    road_rows = [r + 2 for r in wire_rows if r + 2 < WORLD_H] + [r - 2 for r in wire_rows if r - 2 >= 0]
    road_cols = [c + 2 for c in wire_cols if c + 2 < WORLD_W] + [c - 2 for c in wire_cols if c - 2 >= 0]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 0: Ensure power plants spread across map ----
    # More plants at a denser grid
    plant_targets = [(px, py) for py in [15, 35, 50, 65, 85] for px in [15, 35, 55, 75, 95, 115]]
    if step % 6 == 0:
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # ---- REACTIVE: find unpowered zones and wire toward them ----
    if step % 7 == 1:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy), (bwx + dx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 1: Build wire rows by extending existing wire ----
    if step % 7 == 2:
        for wr in wire_rows:
            # Scan for gaps in wire rows - fill adjacently
            for wx in range(1, WORLD_W - 1):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]) or bool(rm[wr, wx]):
                    continue
                if not bool(em[wr, wx]):
                    continue
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    return (Tool.WIRE, wx, wr)

    # ---- PHASE 2: Build wire cols by extending ----
    if step % 7 == 3:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if bool(wm[wy, wc]) or bool(pm[wy, wc]) or bool(rm[wy, wc]):
                    continue
                if not bool(em[wy, wc]):
                    continue
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: Roads flanking wire rows ----
    if step % 7 == 4:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        near_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        if near_wire:
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  (ry > 0 and bool(rm[ry-1, rx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Roads flanking wire cols ----
    if step % 7 == 5:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        near_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        if near_wire:
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

    # ---- REACTIVE: extend road toward unpowered area or zone gap ----
    if step % 7 == 6:
        # Find powered area with no road and extend road from nearest road
        powered_no_road = near_power & ~rm & em
        pnr_ys, pnr_xs = np.where(powered_no_road)
        if len(pnr_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(pnr_xs)
                tx, ty = int(pnr_xs[idx]), int(pnr_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 20:
        fire_spots = [
            (5,5),(35,5),(65,5),(95,5),(115,5),
            (5,20),(115,20),(5,40),(115,40),
            (5,60),(115,60),(5,80),(115,80),
            (5,95),(35,95),(65,95),(95,95),(115,95),
            (25,50),(55,50),(85,50),(110,50),
            (40,25),(80,25),(40,75),(80,75),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (15,12),(45,12),(75,12),(105,12),
            (15,38),(45,38),(75,38),(105,38),
            (15,62),(45,62),(75,62),(105,62),
            (15,87),(45,87),(75,87),(105,87),
            (30,25),(60,25),(90,25),
            (30,75),(60,75),(90,75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (25,15),(65,15),(105,15),
            (25,40),(65,40),(105,40),
            (25,60),(65,60),(105,60),
            (25,85),(65,85),(105,85),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
            (30,5),(90,5),(30,95),(90,95),
            (50,50),(70,50),(60,30),(60,70),
            (10,10),(110,10),(10,90),(110,90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5,90),(115,90),(5,10),(115,10),(60,5),(60,95),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45),(5,55),(110,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value reactively
    if pop > 150 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        for wr in wire_rows:
            park_cands[max(0,wr-1):wr+3, :] = False
        for wc in wire_cols:
            park_cands[:, max(0,wc-1):wc+3] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (primary reactive loop) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Active neighborhood centers scale with pop - more neighborhoods as city grows
        if pop < 100:
            active_centers = [(cx, cy) for cy in [50] for cx in [20, 40, 60, 80, 100]]
        elif pop < 400:
            active_centers = [(cx, cy) for cy in [35, 50, 65] for cx in [15, 35, 55, 75, 95, 115]]
        elif pop < 1000:
            active_centers = [(cx, cy) for cy in [15, 30, 50, 65, 80]
                              for cx in [10, 25, 45, 65, 80, 100, 115]]
        else:
            active_centers = [(cx, cy) for cy in range(10, 100, 10)
                              for cx in range(8, 120, 10)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- FALLBACK: extend road from existing road into powered area ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new coal plant near area without power ----
    all_hoods = [(cx, cy) for cy in range(8, 100, 10) for cx in range(8, 120, 10)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
