def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm
    powered_src = wm | pm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(powered_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure enough power plants (one per ~20x20 area) ---
    # Place plants on a grid, skip if one nearby
    plant_grid_step_x = 20
    plant_grid_step_y = 18
    for py in range(10, WORLD_H - 10, plant_grid_step_y):
        for px in range(10, WORLD_W - 10, plant_grid_step_x):
            x0 = max(0, px - 9); x1 = min(WORLD_W, px + 10)
            y0 = max(0, py - 9); y1 = min(WORLD_H, py + 10)
            if not np.any(pm[y0:y1, x0:x1]):
                # Find nearest empty cell to (px, py)
                for r in range(0, 6):
                    placed = False
                    for dx in range(-r, r+1):
                        for dy in range(-r, r+1):
                            nx, ny = px+dx, py+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Extend wire network from existing power sources ---
    # For each plant, ensure wire extends outward toward road grid
    # Wire rows at every 9 rows (between road pairs)
    wire_rows = list(range(9, WORLD_H - 9, 9))
    wire_cols = list(range(9, WORLD_W - 9, 9))

    # Extend horizontal wires on wire_rows
    for wr in wire_rows:
        row_has_power = bool((wm[wr, :] | pm[wr, :]).any())
        if not row_has_power:
            # Check if there's a plant in nearby rows, connect via vertical wire
            continue
        # Extend left and right
        indices = np.where(wm[wr, :] | pm[wr, :])[0]
        if len(indices) == 0:
            continue
        left = int(indices[0])
        right = int(indices[-1])
        # Extend right if not at edge
        if right < WORLD_W - 3:
            nx = right + 1
            if bool(em[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)
        # Extend left
        if left > 2:
            nx = left - 1
            if bool(em[wr, nx]) and not bool(rm[wr, nx]):
                return (Tool.WIRE, nx, wr)

    # Extend vertical wires on wire_cols to connect horizontal rows
    for wc in wire_cols:
        col_has_power = bool((wm[:, wc] | pm[:, wc]).any())
        if not col_has_power:
            # Seed from nearest plant column
            pwr_ys, pwr_xs = np.where(pm)
            if len(pwr_xs) > 0:
                dists = np.abs(pwr_xs - wc)
                k = int(np.argmin(dists))
                px_near, py_near = int(pwr_xs[k]), int(pwr_ys[k])
                # Place wire at wc toward py_near
                if ib(wc, py_near) and bool(em[py_near, wc]):
                    return (Tool.WIRE, wc, py_near)
            continue
        indices = np.where(wm[:, wc] | pm[:, wc])[0]
        if len(indices) == 0:
            continue
        top = int(indices[0])
        bot = int(indices[-1])
        if bot < WORLD_H - 3:
            ny = bot + 1
            if bool(em[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)
        if top > 2:
            ny = top - 1
            if bool(em[ny, wc]) and not bool(rm[ny, wc]):
                return (Tool.WIRE, wc, ny)

    # --- PHASE 3: Road network ---
    # Roads 4 tiles offset from wire rows/cols
    road_rows = sorted(set(
        r for wr in wire_rows for r in [wr - 4, wr + 4]
        if 4 < r < WORLD_H - 4
    ))
    road_cols = sorted(set(
        c for wc in wire_cols for c in [wc - 4, wc + 4]
        if 4 < c < WORLD_W - 4
    ))

    # Extend horizontal roads
    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Seed near center
            if ib(60, rr) and bool(em[rr, 60]) and not bool(pm[rr, 60]):
                return (Tool.ROAD, 60, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0]); right = int(indices[-1])
        if right < WORLD_W - 4 and bool(em[rr, right+1]) and not bool(pm[rr, right+1]):
            return (Tool.ROAD, right+1, rr)
        if left > 3 and bool(em[rr, left-1]) and not bool(pm[rr, left-1]):
            return (Tool.ROAD, left-1, rr)

    # Extend vertical roads
    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 50) and bool(em[50, rc]) and not bool(pm[50, rc]):
                return (Tool.ROAD, rc, 50)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0]); bot = int(indices[-1])
        if bot < WORLD_H - 4 and bool(em[bot+1, rc]) and not bool(pm[bot+1, rc]):
            return (Tool.ROAD, rc, bot+1)
        if top > 3 and bool(em[top-1, rc]) and not bool(pm[top-1, rc]):
            return (Tool.ROAD, rc, top-1)

    # --- PHASE 4: Zone placement ---
    # Place zones adjacent to roads and within power reach
    zone_cand = em & near_road & near_power
    # Keep border clear
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        tool = pick_tool()
        # Score: prefer close to existing zones and roads
        road_ys, road_xs = np.where(rm)
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            # Sample for speed
            stride_z = max(1, len(zone_xs) // 80)
            stride_r = max(1, len(road_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride_z):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            road_dist = np.full(len(cxs_arr), 9999.0)
            if len(road_xs) > 0:
                for i in range(0, len(road_xs), stride_r):
                    d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                    road_dist = np.minimum(road_dist, d)
            score = road_dist * 0.7 + zone_dist * 0.3
        else:
            # First zones: near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        # Small offset by step to explore different candidates
        off = (step * 3) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services based on population ---
    if pop > 60:
        for fy in range(15, WORLD_H - 5, 15):
            for fx in range(15, WORLD_W - 5, 22):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for py2 in range(18, WORLD_H - 5, 18):
            for px2 in range(18, WORLD_W - 5, 25):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 500:
        for pky in range(12, WORLD_H - 4, 12):
            for pkx in range(12, WORLD_W - 4, 12):
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 800:
        for sy in range(25, WORLD_H - 5, 30):
            for sx in range(25, WORLD_W - 5, 35):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        for apy in [8, 90]:
            for apx in [30, 60, 90]:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        for spy in [5, 94]:
            for spx in [20, 60, 100]:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend wire toward unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        # Find wire candidates adjacent to existing power
        adj_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
            shifted = np.zeros_like(powered_src)
            if dy == -1: shifted[:-1,:] = powered_src[1:,:]
            elif dy == 1: shifted[1:,:] = powered_src[:-1,:]
            elif dx == -1: shifted[:,:-1] = powered_src[:,1:]
            else: shifted[:,1:] = powered_src[:,:-1]
            adj_power |= shifted
        wire_cand = em & adj_power & ~zone_tiles & ~rm
        wire_cand[0:2,:] = False; wire_cand[WORLD_H-2:,:] = False
        wire_cand[:,0:2] = False; wire_cand[:,WORLD_W-2:] = False
        wys_c, wxs_c = np.where(wire_cand)
        if len(wxs_c) > 0:
            uzys, uzxs = np.where(unpowered_zones)
            stride = max(1, len(uzxs) // 20)
            best_d = 1e9; best_k = 0
            for i in range(len(wxs_c)):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx - uzxs[j]) + abs(cy - uzys[j]) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # --- Fallback: road near powered empty area ---
    road_cand = em & near_power & ~zone_tiles
    road_cand[0:3,:] = False; road_cand[WORLD_H-3:,:] = False
    road_cand[:,0:3] = False; road_cand[:,WORLD_W-3:] = False
    rcs_y, rcs_x = np.where(road_cand)
    if len(rcs_x) > 0:
        k = step % len(rcs_x)
        return (Tool.ROAD, int(rcs_x[k]), int(rcs_y[k]))

    return None

