def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        # Target mix: 50% residential, 25% commercial, 25% industrial
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure enough power plants spread across map ----
    # Dense plant grid: every 18 cols, every 14 rows
    plant_grid = []
    for py in range(10, 95, 14):
        for px in range(10, 115, 18):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire expansion — connect plants and zones ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    # Check for unpowered plants or zones
    unpowered_plants = [(px, py) for px, py in plant_grid
                        if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid — denser horizontal roads every 5 rows ----
    # Use two distinct neighborhoods: upper (rows 10-45) and lower (rows 55-90)
    road_rows_upper = list(range(10, 45, 5))
    road_rows_lower = list(range(55, 95, 5))
    road_rows = road_rows_upper + road_rows_lower

    for ry in road_rows:
        row_road = rm[ry, :]
        if int(np.sum(row_road)) < 100:
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    left_ok = rx > 0 and bool(rm[ry, rx-1])
                    right_ok = rx < WORLD_W-1 and bool(rm[ry, rx+1])
                    up_ok = ry > 0 and bool(rm[ry-1, rx])
                    down_ok = ry < WORLD_H-1 and bool(rm[ry+1, rx])
                    if left_ok or right_ok or up_ok or down_ok:
                        return (Tool.ROAD, rx, ry)
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Vertical connector roads every 10 cols
    road_cols = list(range(10, 116, 10))
    for cx in road_cols:
        for cy in range(4, 96):
            if bool(em[cy, cx]) and bool(near_power[cy, cx]):
                adj = ((cy > 0 and bool(rm[cy-1, cx])) or
                       (cy < WORLD_H-1 and bool(rm[cy+1, cx])))
                if adj:
                    return (Tool.ROAD, cx, cy)

    # ---- PHASE 4: Zone placement with balanced zone mix ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    zone_cand &= ~rm & ~wm & ~pm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(rm[nr, nc]) or bool(wm[nr, nc]) or bool(pm[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.ones(len(cxs_arr)) * 9999.0

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 200)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer close to roads, spread from existing zones
            score = road_dist * 2.0 - np.clip(zone_dist, 0, 15) * 0.5
        else:
            # Start near power/road intersections
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 44)).astype(float) + road_dist

        order = np.argsort(score)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 80:
        fire_grid = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 115, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 15)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_grid = [(pkx, pky) for pky in range(6, 95, 6) for pkx in range(6, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 600:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        # Upgrade to nuclear for more power capacity
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (40, 10), (80, 10), (40, 90), (80, 90)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(95, 8), (95, 88), (8, 8), (8, 88)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(8, 50), (110, 50), (60, 6), (60, 92)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road from any existing road ----
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k = (step * 13) % len(rxs2)
        rx2, ry2 = int(rxs2[k]), int(rys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # ---- Fallback: extend wire from power ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads + quadrant plants."""
    actions = []
    cx, cy = 60, 50
    # Central plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from center
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads around center
    for d in range(-8, 9):
        actions.append((Tool.ROAD, cx - 1, cy + d))
        actions.append((Tool.ROAD, cx + 1, cy + d))
        actions.append((Tool.ROAD, cx + d, cy - 1))
        actions.append((Tool.ROAD, cx + d, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    nbr_power = dilate(power_src, 4)
    nbr_road = dilate(rm, 3)

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- Neighborhood grid: spread across full map ----
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 22, 35, 48, 61, 74, 87]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 14
        if pop < 800:   return 20
        if pop < 1500:  return 30
        if pop < 3000:  return 42
        if pop < 6000:  return 52
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: Power plants for active neighborhoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire spines connecting neighborhoods ----
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)

    for i_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_idx + i_h) % len(active_hoods)]

        # Vertical wire spine at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal wire spine at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)
        break

    # ---- PHASE 3: Connect wires between adjacent hoods ----
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            if hy1 == hy2 and 10 <= abs(hx2 - hx1) <= 16 and hx2 > hx1:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 10 <= abs(hy2 - hy1) <= 16 and hy2 > hy1:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)
        break

    # ---- PHASE 4: Roads flanking wire spines ----
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx]

    for rx in [hx - 1, hx + 1]:
        if not ib(rx, hy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy - 1, hy + 1]:
        if not ib(hx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: Zone placement ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Also score near roads
        road_ys, road_xs = np.where(rm)
        road_dist = np.full(len(cxs), 9999.0)
        if len(road_xs) > 0:
            stride = max(1, len(road_xs) // 80)
            for i in range(0, len(road_xs), stride):
                d = (np.abs(cxs - road_xs[i]) + np.abs(cys - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)

        score = best_dist * 0.7 + road_dist * 0.5
        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: Extend roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (tiered by population) ----
    if pop > 60:
        for fx in range(12, WORLD_W - 2, 12):
            for fy in range(12, WORLD_H - 2, 12):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(nbr_power[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 180:
        for px2 in range(15, WORLD_W - 2, 15):
            for py2 in range(15, WORLD_H - 2, 15):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(nbr_power[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 100 and step % 5 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 19 + pop) % len(park_xs2)
            py3, px3 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px3, py3) and bool(em[py3, px3]):
                return (Tool.PARK, px3, py3)

    if pop > 500:
        stadium_locs = [(25, 20), (85, 20), (25, 70), (85, 70),
                        (55, 15), (55, 85), (15, 45), (105, 45), (60, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 900:
        seaport_spots = [(8, 90), (112, 90), (8, 10), (112, 10),
                         (60, 95), (60, 5), (30, 95), (90, 95)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        nuke_locs = [(20, 25), (100, 25), (20, 75), (100, 75),
                     (60, 10), (60, 90), (5, 50), (115, 50),
                     (60, 50), (40, 50), (80, 50)]
        for (nx2, ny2) in nuke_locs:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0b, x1b = max(0, nx2-5), min(WORLD_W, nx2+6)
                y0b, y1b = max(0, ny2-5), min(WORLD_H, ny2+6)
                if not np.any(pm[y0b:y1b, x0b:x1b]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        airport_spots = [(20, 6), (50, 6), (80, 6), (20, 94), (50, 94), (80, 94)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 14):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire connections + initial road grid"""
    actions = []
    # Two coal plants near center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire spine connecting them horizontally
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for y in range(20, 80):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Horizontal wire at top and bottom of coverage
    for x in range(30, 91):
        actions.append((Tool.WIRE, x, 20))
        actions.append((Tool.WIRE, x, 80))
    # Main roads
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 35))
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
        actions.append((Tool.ROAD, x, 65))
    for y in range(5, 95):
        actions.append((Tool.ROAD, 20, y))
        actions.append((Tool.ROAD, 45, y))
        actions.append((Tool.ROAD, 60, y))
        actions.append((Tool.ROAD, 75, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Pick zone type: 50% res, 25% com, 25% ind
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure sufficient power plants ----
    # Place plants on a grid, check if region is already covered
    plant_positions = []
    for py in range(15, WORLD_H - 10, 25):
        for px in range(15, WORLD_W - 10, 25):
            plant_positions.append((px, py))

    for ppx, ppy in plant_positions:
        x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
        y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
        if not np.any(pm[y0:y1, x0:x1]):
            # No plant nearby — try to place one
            # Find an empty spot near ppx, ppy
            for dx in range(-2, 3):
                for dy in range(-2, 3):
                    nx, ny = ppx + dx, ppy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire extension — connect power to all areas ----
    # Find cells adjacent to existing power that are empty and not zones or roads
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    # Identify zones without power
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    # Also identify large empty areas without power coverage for proactive wiring
    uncovered = ~near_power
    uncovered[0:3,:] = False
    uncovered[WORLD_H-3:,:] = False
    uncovered[:,0:3] = False
    uncovered[:,WORLD_W-3:] = False

    # Wire toward unpowered zones or uncovered areas
    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2,:] = False
    wire_cand[WORLD_H-2:,:] = False
    wire_cand[:,0:2] = False
    wire_cand[:,WORLD_W-2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        # Wire toward unpowered zones
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) 
                    for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # Proactive: extend wire into uncovered empty areas
    if len(wxs_c) > 0:
        # Pick wire candidate that is most distant from power center (expand coverage)
        uncov_wire = wire_cand & uncovered
        uwy, uwx = np.where(uncov_wire)
        if len(uwx) > 0:
            # pick one that extends coverage most (farthest from existing power centroid)
            k = step % len(uwx)
            return (Tool.WIRE, int(uwx[k]), int(uwy[k]))
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 3: Road extension toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand = em & adj_to_road & ~zone_tiles & ~pm
    road_cand[0:2,:] = False
    road_cand[WORLD_H-2:,:] = False
    road_cand[:,0:2] = False
    road_cand[:,WORLD_W-2:] = False
    rys_c, rxs_c = np.where(road_cand)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                    for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Proactive road: extend into uncovered areas
    if len(rxs_c) > 0:
        unserved_area = road_cand & ~near_road
        uray, urax = np.where(unserved_area)
        if len(urax) > 0:
            k = step % len(urax)
            return (Tool.ROAD, int(urax[k]), int(uray[k]))

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]).astype(float) +
                     np.abs(cys_arr - road_ys[i]).astype(float))
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Prefer spots close to existing zones for density, but not too close
        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]).astype(float) +
                     np.abs(cys_arr - zone_ys[i]).astype(float))
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Too close (<3): bad (overlap). Too far (>20): also bad (isolation)
            zone_score = np.where(min_zone_dist < 3, 5000.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.1

        score = road_dist * 1.5 + zone_score
        order = np.argsort(score)

        tool = pick_tool()
        # Vary starting offset by step to avoid always picking same spot
        off = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(8, 95, 15) for fx in range(8, 114, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(8, 95, 18) for px2 in range(8, 114, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(8, 94, 10) for pkx in range(8, 114, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [(sx, sy) for sy in range(15, 88, 30) for sx in range(15, 110, 35)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuclear_spots = [(nx, ny) for ny in range(15, 90, 25) for nx in range(15, 110, 25)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-12), min(WORLD_W, npx+13)
                y0, y1 = max(0, npy-12), min(WORLD_H, npy+13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 7), (65, 7), (55, 92), (65, 92),
                         (7, 44), (112, 44)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: place road near any plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(5,0),(-5,0),(0,5),(0,-5),(8,0),(-8,0),(0,8),(0,-8)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + roads for two neighborhoods."""
    actions = []
    # Two power plants at different locations
    # Left cluster center: (35, 50), Right cluster center: (85, 50)
    for cx, cy in [(35, 50), (85, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire spines from each plant
        for dx in range(-6, 7):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-6, 7):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking the vertical wire spine
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
        # Roads flanking the horizontal wire spine
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, cx + dx, cy - 1))
            actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: ~35% RES, ~35% COM, ~30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Two main cluster centers + satellite neighborhoods
    # Left cluster: 35,50; Right cluster: 85,50
    # Plus additional neighborhoods in a grid pattern
    nh_cols = [12, 25, 38, 51, 64, 77, 90, 103, 116]
    nh_rows = [12, 25, 38, 51, 64, 77, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 400:   return 14
        if pop < 800:   return 22
        if pop < 1500:  return 32
        if pop < 3000:  return 45
        if pop < 6000:  return 56
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    power_src = wm | pm

    # Dilation for power (radius 5 Manhattan)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            if abs(dx2) + abs(dy2) > 5:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Dilation for road (radius 3 Manhattan)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            if abs(dx2) + abs(dy2) > 3:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: POWER PLANTS for active hoods ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
        y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE SPINES — connect plant to hood ===
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0p, x1p = max(0, hx - 18), min(WORLD_W, hx + 19)
    y0p, y1p = max(0, hy - 18), min(WORLD_H, hy + 19)
    plant_ys_l, plant_xs_l = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs_l) > 0:
        px_l = int(plant_xs_l[0]) + x0p
        py_l = int(plant_ys_l[0]) + y0p
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spine at hood
    for dy3 in range(-spine_range, spine_range + 1):
        wy = hy + dy3
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    for dx3 in range(-spine_range, spine_range + 1):
        wx = hx + dx3
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # === PHASE 3: INTER-HOOD WIRE CONNECTIONS ===
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    for i_h in range(min(len(active_hoods), 8)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            dist = abs(hx1 - hx2) + abs(hy1 - hy2)
            if dist == 0 or dist > 35:
                continue
            if abs(hy1 - hy2) <= 3:
                mid_y2 = (hy1 + hy2) // 2
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, mid_y2): continue
                    if not bool(em[mid_y2, cx2]) or bool(pm[mid_y2, cx2]) or bool(wm[mid_y2, cx2]):
                        continue
                    has_l = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                for c in range(max(0, cx2 - 4), cx2))
                    has_r = any(bool(wm[mid_y2, c]) or bool(pm[mid_y2, c])
                                for c in range(cx2 + 1, min(WORLD_W, cx2 + 5)))
                    if has_l or has_r:
                        return (Tool.WIRE, cx2, mid_y2)
            if abs(hx1 - hx2) <= 3:
                mid_x2 = (hx1 + hx2) // 2
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(mid_x2, cy2): continue
                    if not bool(em[cy2, mid_x2]) or bool(pm[cy2, mid_x2]) or bool(wm[cy2, mid_x2]):
                        continue
                    has_t = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2])
                                for r in range(max(0, cy2 - 4), cy2))
                    has_b = any(bool(wm[r, mid_x2]) or bool(pm[r, mid_x2])
                                for r in range(cy2 + 1, min(WORLD_H, cy2 + 5)))
                    if has_t or has_b:
                        return (Tool.WIRE, mid_x2, cy2)

    # === PHASE 4: ROADS FLANKING WIRE SPINES ===
    road_idx = step % max(len(active_hoods), 1)
    hx_r, hy_r = active_hoods[road_idx]

    # Place roads at offsets +/-1 and +/-2 from wire spine
    for rx in [hx_r - 1, hx_r + 1, hx_r - 2, hx_r + 2]:
        if not ib(rx, hy_r): continue
        for dy4 in range(-spine_range, spine_range + 1):
            ry = hy_r + dy4
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(wm[ry, hx_r]) or bool(pm[ry, hx_r]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy_r - 1, hy_r + 1, hy_r - 2, hy_r + 2]:
        if not ib(hx_r, ry2): continue
        for dx4 in range(-spine_range, spine_range + 1):
            rcx = hx_r + dx4
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
            if bool(wm[hy_r, rcx]) or bool(pm[hy_r, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # === PHASE 5: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 10:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: EXTEND ROADS INTO POWERED EMPTY AREAS ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx5, dy5 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx5, ry2 + dy5
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # === CIVIC SERVICES (population-gated) ===
    if pop > 60:
        for fx in range(10, WORLD_W, 14):
            for fy in range(10, WORLD_H, 14):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 150:
        for px2 in range(12, WORLD_W, 16):
            for py2 in range(12, WORLD_H, 16):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 120 and step % 3 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 17) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
            (30, 50), (90, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 2500:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (5, 75), (115, 25), (115, 75),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 700:
        airport_locs = [
            (10, 10), (100, 10), (10, 85), (100, 85),
            (55, 5), (55, 93),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: EXTEND WIRE ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx6, dy6 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx6, wy2 + dy6
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: NEW PLANT FOR UNCOVERED HOOD ===
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 16):
                for dy7 in range(-r2, r2 + 1):
                    for dx7 in range(-r2, r2 + 1):
                        if abs(dx7) == r2 or abs(dy7) == r2:
                            nx4, ny4 = hx3 + dx7, hy3 + dy7
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire connections and initial roads."""
    actions = []
    # Two starting plants: left-center and right-center
    for cx, cy in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Vertical wire spine from plant
        for dy in [-1, 1, -2, 2, -3, 3]:
            actions.append((Tool.WIRE, cx, cy + dy))
        # Horizontal wire spine from plant
        for dx in [-1, 1, -2, 2, -3, 3]:
            actions.append((Tool.WIRE, cx + dx, cy))
        # Flanking roads
        for dy in range(-3, 4):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid of neighborhoods - denser than parent, different layout
    # 9 cols x 7 rows = 63 neighborhoods
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104]
    nh_rows = [10, 22, 34, 46, 58, 70, 82]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 9
        if pop < 300:   return 15
        if pop < 600:   return 22
        if pop < 1200:  return 32
        if pop < 2500:  return 45
        if pop < 5000:  return 55
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Spread active hoods evenly
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Different zone mix than parent: target 30% ind, 35% com, 35% res
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS near active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        # Place plant at nearest empty spot
        for r in range(15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: HORIZONTAL wire spines (different from parent's vertical) ----
    spine_range = 12

    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Rotate through hoods
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Horizontal wire at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx in [-1, 1]:
                ax = wx + adx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    adj = True
                    break
            if not adj:
                for ady in [-1, 1]:
                    ay = hy + ady
                    if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)
            # Bootstrap horizontal if no wire yet
            row_has_wire = any(
                bool(wm[hy, hx + d2]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx + d2, hy)
            )
            if not row_has_wire:
                for d2 in [-1, 1]:
                    ax = hx + d2
                    if ib(ax, hy) and bool(em[hy, ax]) and not bool(pm[hy, ax]):
                        return (Tool.WIRE, ax, hy)

        # Vertical wire at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        # Horizontal neighbors (spacing 12)
        for dhx in [12, 24]:
            hx2, hy2 = hx1 + dhx, hy1
            if (hx2, hy2) in hood_set:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1) or bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]) or not bool(em[hy1, cx2]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
        # Vertical neighbors (spacing 12)
        for dhy in [12, 24]:
            hx2, hy2 = hx1, hy1 + dhy
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2) or bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS - grid pattern around hoods ----
    # Place roads above AND below horizontal wire spines, plus left/right of vertical spines
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 2) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 2 + 2):
            continue

        # Roads flanking horizontal wire spine (above and below)
        for ry in [hy - 1, hy + 1]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry):
                    continue
                if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry)

        # Roads flanking vertical wire spine (left and right)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road proximity mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power proximity mask (wire or plant within 6 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary offset by step to avoid always placing same zone type in same spot
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (earlier than parent) ----
    if pop > 80:
        fire_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 38), (45, 38), (75, 38), (105, 38),
            (15, 58), (45, 58), (75, 58), (105, 58),
            (15, 78), (45, 78), (75, 78), (105, 78),
            (15, 95), (45, 95), (75, 95), (105, 95),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (25, 25), (55, 25), (85, 25), (115, 25),
            (25, 50), (55, 50), (85, 50), (115, 50),
            (25, 70), (55, 70), (85, 70), (115, 70),
            (25, 90), (55, 90), (85, 90), (115, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (40, 40), (80, 40), (40, 65), (80, 65),
            (60, 20), (60, 80), (10, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (6, 6), (114, 6), (6, 94), (114, 94),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (35, 6), (85, 6), (35, 94), (85, 94),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(10, 92), (110, 92), (10, 8), (110, 8), (60, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(48, 5), (72, 5), (48, 94), (72, 94), (5, 46), (114, 46)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near zones ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 5 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 0), (-3, 0), (0, 3), (0, -3),
                                  (2, 2), (-2, 2), (2, -2), (-2, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 23) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
