def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Build neighbor masks efficiently
    def expand_mask(src, radius):
        result = src.copy()
        for dy in range(-radius, radius+1):
            for dx in range(-radius, radius+1):
                if dx == 0 and dy == 0:
                    continue
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H+dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W+dx)
                result[r0:r1, c0:c1] |= src[sr0:sr1, sc0:sc1]
        return result

    power_src = wm | pm
    nbr_power = expand_mask(power_src, 3)
    nbr_road = expand_mask(rm, 2)

    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr):
                    return False
                cell = tm[nr, nc]
                # Must be empty or zone (not road/wire/plant)
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # ---- PHASE 1: Ensure enough power plants ----
    # One plant per ~15x15 neighborhood across map
    plant_ys, plant_xs = np.where(pm)
    n_plants = len(plant_xs)
    # Scale needed plants with map usage
    needed_plants = max(2, 1 + total_zones // 20)
    if n_plants < needed_plants:
        # Place plant at a spot with power neighbor or near road
        # Try systematic grid positions
        plant_grid_x = [20, 40, 60, 80, 100]
        plant_grid_y = [20, 40, 50, 60, 80]
        for py in plant_grid_y:
            for px in plant_grid_x:
                if not ib(px, py): continue
                # Check if already has plant nearby
                x0,x1 = max(0,px-8), min(WORLD_W,px+9)
                y0,y1 = max(0,py-8), min(WORLD_H,py+9)
                if bool(np.any(pm[y0:y1, x0:x1])):
                    continue
                # Find empty spot near this grid point
                for r in range(0, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = px+dx, py+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Extend wires from plants to reach roads/zones ----
    # Find frontier wire cells (wire adjacent to empty)
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        # Look for empty cells adjacent to wire that are not yet powered
        # and would help extend power toward unserved zones
        sk = (step * 7) % len(wire_xs)
        for off in range(min(len(wire_xs), 50)):
            k = (sk + off * 3) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if not ib(nx, ny): continue
                if not bool(em[ny, nx]): continue
                if bool(pm[ny, nx]): continue
                # Extend wire toward road areas or unserved zones
                # Prefer extending toward roads without power
                score = 0
                for ddx in range(-3,4):
                    for ddy in range(-3,4):
                        nnx, nny = nx+ddx, ny+ddy
                        if ib(nnx, nny):
                            if bool(rm[nny, nnx]) and not bool(nbr_power[nny, nnx]):
                                score += 3
                            if bool(zone_tiles[nny, nnx]) and not bool(nbr_power[nny, nnx]):
                                score += 5
                if score > 0:
                    return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: Extend roads from existing road network ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        sk = (step * 11) % len(road_xs_arr)
        for off in range(min(len(road_xs_arr), 80)):
            k = (sk + off * 7) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = rx+dx, ry+dy
                if not ib(nx, ny): continue
                if not bool(em[ny, nx]): continue
                if bool(pm[ny, nx]): continue
                # Extend into powered areas
                if bool(nbr_power[ny, nx]):
                    # Check if this direction has unzoned powered empty land
                    score = 0
                    for ddx in range(-3,4):
                        for ddy in range(-3,4):
                            nnx, nny = nx+ddx, ny+ddy
                            if ib(nnx, nny):
                                if bool(em[nny, nnx]) and bool(nbr_power[nny, nnx]):
                                    score += 1
                    if score > 2:
                        return (Tool.ROAD, nx, ny)

    # ---- PHASE 4: Place zones adjacent to roads and power ----
    cand_mask = em & nbr_road & nbr_power
    # Keep away from edges (zones are 3x3)
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by: near road AND near power AND clear 3x3
        # Use step offset for variety
        offset = (step * 13) % max(len(cxs), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(cxs)):
            k = (offset + i) % len(cxs)
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- PHASE 5: Civic services ----
    if pop > 100:
        fire_grid = [(x, y) for y in range(15, 90, 25) for x in range(15, 110, 30)]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_grid = [(x, y) for y in range(10, 95, 30) for x in range(10, 115, 35)]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(30,25),(70,25),(110,25),(30,65),(70,65),(110,65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(5,90),(60,90),(114,90),(5,5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(40,5),(80,5),(40,93),(80,93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 6: Parks near existing zones ----
    if pop > 150 and step % 4 == 0:
        park_mask = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_mask)
        if len(park_xs) > 0:
            idx = (step * 41) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: lay wire extending from any plant ----
    plant_ys_arr, plant_xs_arr = np.where(pm)
    for i in range(len(plant_xs_arr)):
        px, py = int(plant_xs_arr[i]), int(plant_ys_arr[i])
        for dx, dy in [(1,0),(-1,0),(0,1),(0,-1),(2,0),(-2,0),(0,2),(0,-2)]:
            nx, ny = px+dx, py+dy
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # ---- FALLBACK: new plant at random empty spot ----
    empty_ys, empty_xs = np.where(em)
    if len(empty_xs) > 0:
        idx = (step * 17) % len(empty_xs)
        return (Tool.COALPOWER, int(empty_xs[idx]), int(empty_ys[idx]))

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire spines and flanking roads."""
    actions = []
    # 2 plants at center-left and center-right
    for px in [30, 90]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # vertical wire spine
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # flanking roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood grid: 4 cols x 4 rows = 16 neighborhoods
    nh_cols = [20, 47, 73, 100]
    nh_rows = [18, 40, 62, 84]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 6
        if pop < 800:   return 9
        if pop < 1500:  return 12
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Build proximity masks using dilation
    power_src = wm | pm

    # nbr_power: any cell within 5 of a wire/plant
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # nbr_road: any cell within 3 of a road
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINE - grow wire FROM existing plants/wires toward hoods ----
    # For the current hood (based on step), extend wire connectivity
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) > 0:
        dists = np.abs(plant_xs - hx) + np.abs(plant_ys - hy)
        closest = np.argmin(dists)
        px_loc = int(plant_xs[closest])
        py_loc = int(plant_ys[closest])

        # Grow wire vertically from plant toward hood y
        if py_loc != hy:
            sd = 1 if hy > py_loc else -1
            cy = py_loc + sd
            while ib(px_loc, cy):
                if bool(pm[cy, px_loc]):
                    break
                if bool(wm[cy, px_loc]):
                    cy += sd
                    continue
                if bool(em[cy, px_loc]):
                    return (Tool.WIRE, px_loc, cy)
                break

        # Grow wire horizontally from plant toward hood x
        if px_loc != hx:
            sd = 1 if hx > px_loc else -1
            cx = px_loc + sd
            # Use hood y row for horizontal wire
            if bool(wm[py_loc, px_loc]) or bool(pm[py_loc, px_loc]):
                # Start horizontal wire from plant level
                for cx2 in range(px_loc + sd, hx + sd, sd):
                    if not ib(cx2, py_loc): break
                    if bool(pm[py_loc, cx2]): break
                    if bool(wm[py_loc, cx2]): continue
                    if bool(em[py_loc, cx2]):
                        return (Tool.WIRE, cx2, py_loc)
                    break

    # ---- PHASE 3: HORIZONTAL WIRE connecting same-row hoods ----
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        row_hoods.sort(key=lambda h: h[0])
        for i in range(len(row_hoods) - 1):
            hx1 = row_hoods[i][0]
            hx2 = row_hoods[i + 1][0]
            # Check if wire already connects them
            already = all(bool(wm[hy_row, cx2]) or bool(pm[hy_row, cx2])
                         for cx2 in range(hx1, hx2 + 1))
            if not already:
                for cx2 in range(hx1, hx2 + 1):
                    if ib(cx2, hy_row) and bool(em[hy_row, cx2]) and not bool(pm[hy_row, cx2]):
                        return (Tool.WIRE, cx2, hy_row)

    # ---- PHASE 4: VERTICAL WIRE connecting same-column hoods ----
    if n_active >= 4:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for cy2 in range(hy1, hy2 + 1):
                    if ib(hx_col, cy2) and bool(em[cy2, hx_col]) and not bool(pm[cy2, hx_col]) and not bool(wm[cy2, hx_col]):
                        return (Tool.WIRE, hx_col, cy2)

    # ---- PHASE 5: ROADS flanking wire spines ----
    # Place roads adjacent to wire columns at each active hood
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]
    spine_half = min(12, 4 + pop // 50)
    spine_top3 = max(2, hy3 - spine_half)
    spine_bot3 = min(WORLD_H - 3, hy3 + spine_half)

    # Road columns at hx3-2 and hx3+2 (flanking with gap for zones)
    cycle = step % 6
    for wr in range(spine_top3 + cycle, spine_bot3 + 1, 6):
        for rx in [hx3 - 2, hx3 + 2]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    # ---- PHASE 6: HORIZONTAL ROADS connecting hoods ----
    if pop > 20:
        for hy_row in nh_rows:
            row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
            if len(row_hoods) < 2:
                continue
            row_hoods.sort(key=lambda h: h[0])
            xl = row_hoods[0][0] - 3
            xr = row_hoods[-1][0] + 3
            for horiz_y in [hy_row - 4, hy_row + 4]:
                if not ib(max(2, xl), horiz_y):
                    continue
                # Check if road already exists
                for cx3 in range(max(2, xl), min(WORLD_W - 2, xr + 1)):
                    if ib(cx3, horiz_y) and bool(em[horiz_y, cx3]) and not bool(pm[horiz_y, cx3]):
                        return (Tool.ROAD, cx3, horiz_y)

    # ---- PHASE 7: VERTICAL ROADS connecting hood rows ----
    if pop > 60 and len(nh_rows) >= 2:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for rx2 in [hx_col - 4, hx_col + 4]:
                    for cy3 in range(hy1, hy2 + 1):
                        if ib(rx2, cy3) and bool(em[cy3, rx2]) and not bool(pm[cy3, rx2]):
                            adj_road = any(
                                ib(ax, ay) and bool(rm[ay, ax])
                                for ax, ay in [(rx2-1,cy3),(rx2+1,cy3),(rx2,cy3-1),(rx2,cy3+1)]
                            )
                            if adj_road or cy3 == hy1 or cy3 == hy2:
                                return (Tool.ROAD, rx2, cy3)

    # ---- PHASE 8: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                # Allow existing zones but not roads/wires/plants
                cell_ok = bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])
                if not cell_ok:
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 9: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- PHASE 10: CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [(fx, fy)
                      for fx in range(12, WORLD_W, 25)
                      for fy in range(12, WORLD_H, 25)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [(px2, py2)
                        for px2 in range(16, WORLD_W, 28)
                        for py2 in range(16, WORLD_H, 28)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [
            (25, 9), (60, 9), (95, 9),
            (25, 91), (60, 91), (95, 91),
            (9, 50), (111, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (7, 7), (113, 7), (7, 93), (113, 93),
            (60, 7), (60, 93),
            (32, 7), (88, 7),
            (7, 30), (7, 70), (113, 30), (113, 70),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2500:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3500:
        airports = [
            (42, 5), (78, 5), (42, 94), (78, 94),
            (5, 38), (5, 62), (115, 38), (115, 62),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 150 and step % 8 == 0:
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 3 + i * 17) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # ---- FALLBACK: new plant near uncovered hood ----
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + initial roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines
    for x in range(52, 69):
        if x not in (59, 60, 61):
            actions.append((Tool.WIRE, x, 50))
    for y in range(42, 59):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    # Roads parallel to wire spines
    for x in range(52, 69):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for y in range(42, 59):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # --- DYNAMIC NEIGHBORHOOD GRID ---
    # Use a denser grid as population grows
    if pop < 100:
        spacing = 20
    elif pop < 500:
        spacing = 18
    elif pop < 2000:
        spacing = 16
    else:
        spacing = 14

    all_hoods = []
    for hy in range(spacing // 2, WORLD_H, spacing):
        for hx in range(spacing // 2, WORLD_W, spacing):
            all_hoods.append((hx, hy))

    def num_active_hoods():
        if pop < 50:   return 2
        if pop < 200:  return 4
        if pop < 500:  return 8
        if pop < 1000: return 14
        if pop < 2000: return 20
        if pop < 4000: return 28
        return len(all_hoods)

    n_active = num_active_hoods()
    n_active = min(n_active, len(all_hoods))
    # Pick hoods spread across map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # --- PHASE 1: POWER PLANTS ---
    # Each active hood needs a plant nearby; place one if missing
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
            y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find nearest empty tile near hood center
                for r in range(1, 12):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if found:
                        break

    # --- PHASE 2: WIRE SPINES (closed-loop extension) ---
    # For each hood, extend wires from any existing wire/plant toward hood extent
    for (hx, hy) in active_hoods:
        extent = spacing // 2 + 2
        spine_top   = max(2, hy - extent)
        spine_bot   = min(WORLD_H - 3, hy + extent)
        spine_left  = max(2, hx - extent)
        spine_right = min(WORLD_W - 3, hx + extent)

        # Check existing wires in this column
        col_wires = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        col_plants = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]

        # Wire adjacent to plant if no wire yet
        if col_plants and not col_wires:
            py_loc = col_plants[0]
            for wy in [py_loc - 1, py_loc + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)

        # Extend vertical spine
        if col_wires:
            min_wr = min(col_wires)
            max_wr = max(col_wires)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Check existing wires in this row
        row_wires = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        row_plants = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]

        if row_plants and not row_wires:
            px_loc = row_plants[0]
            for wx in [px_loc - 1, px_loc + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)

        if row_wires:
            min_wc = min(row_wires)
            max_wc = max(row_wires)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: INTER-HOOD WIRE CONNECTIONS ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hy1 - hy2) > 4 and abs(hx1 - hx2) > 4:
                continue
            # Connect horizontally if same row-ish
            if abs(hy1 - hy2) <= 4 and hx2 > hx1:
                mid_y = (hy1 + hy2) // 2
                for cx in range(hx1 + 1, hx2):
                    if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                        return (Tool.WIRE, cx, mid_y)
            # Connect vertically if same col-ish
            if abs(hx1 - hx2) <= 4 and hy2 > hy1:
                mid_x = (hx1 + hx2) // 2
                for cy in range(hy1 + 1, hy2):
                    if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                        return (Tool.WIRE, mid_x, cy)

    # --- PHASE 4: ROAD GRID (parallel to wire spines) ---
    # Roads at ±2 from wire spine, following wire extent reactively
    road_offsets = [-2, 2, -3, 3]
    for (hx, hy) in active_hoods:
        col_wires = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx_off in road_offsets:
            rx = hx + rx_off
            if not ib(rx, hy):
                continue
            if not col_wires:
                continue
            cyc = step % 4
            for wr in col_wires[cyc::4]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)

        row_wires = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry_off in road_offsets:
            ry = hy + ry_off
            if not ib(hx, ry):
                continue
            if not row_wires:
                continue
            cyc = (step + 1) % 4
            for wc in row_wires[cyc::4]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (within 3 tiles of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    # Keep border clear
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods + existing zone clustering
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus: reward being near existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        # Vary starting offset slightly to avoid always picking same spot
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS REACTIVELY ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES (reactive to population) ---
    # Fire stations
    if pop > 50:
        fire_spacing = max(10, 20 - pop // 500)
        for fy in range(fire_spacing, WORLD_H - 5, fire_spacing):
            for fx in range(fire_spacing, WORLD_W - 5, fire_spacing):
                x0f, x1f = max(0, fx-4), min(WORLD_W, fx+5)
                y0f, y1f = max(0, fy-4), min(WORLD_H, fy+5)
                has_fire = bool(np.any(tm[y0f:y1f, x0f:x1f] == 18))  # fire station tile
                if not has_fire and ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 100:
        police_spacing = max(12, 25 - pop // 400)
        for py2 in range(police_spacing, WORLD_H - 5, police_spacing):
            for px2 in range(police_spacing, WORLD_W - 5, police_spacing):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 200 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17 + pop) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 500:
        for stx, sty in [(20, 20), (95, 20), (20, 78), (95, 78), (57, 20), (57, 78)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000 and funds > 5000:
        nuclear_locs = [(10, 10), (108, 10), (10, 88), (108, 88),
                        (60, 5), (60, 93), (5, 50), (113, 50)]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 700:
        for spx, spy in [(5, 50), (113, 50), (60, 5), (60, 93)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1200:
        for apx, apy in [(8, 8), (100, 8), (8, 88), (100, 88)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from plants/wires ---
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire grid + road network."""
    actions = []
    # Plant 1: left cluster center
    cx1, cy1 = 35, 45
    actions.append((Tool.COALPOWER, cx1, cy1))
    # Plant 2: right cluster center
    cx2, cy2 = 85, 55
    actions.append((Tool.COALPOWER, cx2, cy2))

    # Horizontal wire spine left plant
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx1 + dx, cy1))
    # Vertical wire spine left plant
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx1, cy1 + dy))

    # Horizontal wire spine right plant
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx2 + dx, cy2))
    # Vertical wire spine right plant
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx2, cy2 + dy))

    # Roads flanking left plant spines
    for d in range(-8, 9):
        actions.append((Tool.ROAD, cx1 - 1, cy1 + d))
        actions.append((Tool.ROAD, cx1 + 1, cy1 + d))

    # Roads flanking right plant spines
    for d in range(-8, 9):
        actions.append((Tool.ROAD, cx2 - 1, cy2 + d))
        actions.append((Tool.ROAD, cx2 + 1, cy2 + d))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Two clusters: left (residential-heavy) and right (industrial+commercial)
    # More neighborhoods arranged in a tighter grid
    left_cols  = [12, 22, 32, 42, 52]
    left_rows  = [15, 27, 39, 51, 63, 75]
    right_cols = [62, 72, 82, 92, 102, 112]
    right_rows = [15, 27, 39, 51, 63, 75, 87]

    all_hoods = [(c, r) for r in left_rows for c in left_cols] + \
                [(c, r) for r in right_rows for c in right_cols]

    def num_active():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 700:   return 16
        if pop < 1500:  return 28
        if pop < 3000:  return 42
        if pop < 6000:  return 55
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    nbr_power = dilate(wm | pm, 6)
    nbr_road = dilate(rm, 3)
    zone_tiles = resm | comm | indm

    def pick_tool(hx, hy):
        # Right side: more industrial and commercial
        if hx >= 60:
            t = max(total_zones, 1)
            ir = ind_count / t
            cr = com_count / t
            if ir < 0.35:
                return Tool.INDUSTRIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # Left side: residential focus with some commercial
            t = max(total_zones, 1)
            cr = com_count / t
            ir = ind_count / t
            if cr < 0.22:
                return Tool.COMMERCIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # PHASE 1: Ensure each active hood has a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Wire spines for active hoods
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_idx + i_h) % len(active_hoods)]

        # Vertical wire spine
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal wire spine
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)
        break

    # PHASE 3: Connect wire between hoods in same row/col
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            if hy1 == hy2 and 5 < abs(hx2 - hx1) <= 20 and hx2 > hx1:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 5 < abs(hy2 - hy1) <= 20 and hy2 > hy1:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)
        break

    # PHASE 4: Roads along wire spines (both sides of spine)
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx]

    for rx in [hx - 1, hx + 1]:
        if not ib(rx, hy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy - 1, hy + 1]:
        if not ib(hx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # PHASE 5: Zone placement - prefer compact clusters near hoods
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                tool = pick_tool(zx, zy)
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # PHASE 6: Extend roads into powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # CIVIC SERVICES - placed more aggressively
    if pop > 60:
        for fx in range(8, WORLD_W, 18):
            for fy in range(8, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 150:
        for px2 in range(12, WORLD_W, 20):
            for py2 in range(12, WORLD_H, 20):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 500:
        for sx in range(20, WORLD_W, 30):
            for sy in range(20, WORLD_H, 30):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 800:
        seaport_spots = [(8, 90), (112, 90), (8, 10), (112, 10),
                         (60, 95), (60, 5)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        nuke_spots = [(20, 20), (100, 20), (20, 80), (100, 80),
                      (60, 10), (60, 90)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        airport_spots = [(20, 6), (50, 6), (80, 6), (20, 94), (50, 94), (80, 94)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 80 and step % 5 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 17 + pop) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new plant at uncovered hood
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 15):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with wire cross and ring road."""
    actions = []
    # Single central plant at (60, 50)
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending out 10 tiles
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Ring roads at offset +-4 from center
    for d in range(-9, 10):
        actions.append((Tool.ROAD, cx - 4, cy + d))
        actions.append((Tool.ROAD, cx + 4, cy + d))
        actions.append((Tool.ROAD, cx + d, cy - 4))
        actions.append((Tool.ROAD, cx + d, cy + 4))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # === NEIGHBORHOOD GRID: concentric expansion from center ===
    # Start with center, expand outward as population grows
    center_x, center_y = 60, 50

    # Hoods arranged in rings around center
    ring0 = [(60, 50)]
    ring1 = [(40, 30), (60, 30), (80, 30),
             (40, 50), (80, 50),
             (40, 70), (60, 70), (80, 70)]
    ring2 = [(20, 15), (60, 15), (100, 15),
             (20, 50), (100, 50),
             (20, 85), (60, 85), (100, 85),
             (35, 30), (85, 30), (35, 70), (85, 70)]
    ring3 = [(10, 10), (35, 10), (60, 10), (85, 10), (110, 10),
             (10, 50), (110, 50),
             (10, 90), (35, 90), (60, 90), (85, 90), (110, 90),
             (25, 30), (95, 30), (25, 70), (95, 70)]

    all_hoods = ring0 + ring1 + ring2 + ring3

    def num_active():
        if pop < 100:   return 1
        if pop < 300:   return 4
        if pop < 600:   return 9
        if pop < 1000:  return 13
        if pop < 2000:  return 20
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    # === NEIGHBOR MASKS ===
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: ENSURE POWER PLANTS near every active hood ===
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
            y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 16):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)
                    if found:
                        break

    # === PHASE 2: WIRE INFRASTRUCTURE from plants to hoods ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 14

    x0p, x1p = max(0, hx - 20), min(WORLD_W, hx + 21)
    y0p, y1p = max(0, hy - 20), min(WORLD_H, hy + 21)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0
        best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d
                best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        # Wire from plant toward hood - vertical first
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spine at current hood
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        min_wr, max_wr = min(col_wire), max(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        min_wc, max_wc = min(row_wire), max(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: ROADS flanking wire at offset 3 ===
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 3
    for rx in [hx3 - 3, hx3 + 3]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::3]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 3, hy3 + 3]:
        if not ib(hx3, ry): continue
        cyc2 = (step + 1) % 3
        for wc in row_wire3[cyc2::3]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # === PHASE 4: ZONE PLACEMENT - varied mix based on ratios ===
    def pick_tool():
        # Target: 50% residential, 25% commercial, 25% industrial
        # Industrial and commercial create jobs -> residential grows
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4) + np.abs(cys - hy4)
            best_dist = np.minimum(best_dist, d)

        # Prefer spots near center for early game, spread later
        center_d = np.abs(cxs - center_x) + np.abs(cys - center_y)
        center_weight = max(0.0, 1.0 - pop / 2000.0)
        score = best_dist + center_d * center_weight * 0.3

        # Clustering bonus near existing zones
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = score * 0.6 + zone_prox * 0.4

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: EXTEND ROAD NETWORK ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 6: CIVIC SERVICES ===
    if pop > 30:
        # Fire stations in a denser grid (every 12 tiles)
        fire_grid = [(fx, fy) for fy in range(10, 95, 12)
                     for fx in range(10, 115, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(14, 92, 14)
                       for px2 in range(14, 112, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Stadiums: placed near active hoods
    if pop > 300:
        stadium_locs = [
            (55, 45), (65, 45), (55, 55), (65, 55),
            (35, 25), (85, 25), (35, 75), (85, 75),
            (20, 20), (100, 20), (20, 80), (100, 80),
            (60, 20), (60, 80), (20, 50), (100, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power - more aggressive placement
    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (20, 20), (100, 20), (20, 80), (100, 80),
            (60, 10), (60, 90), (10, 50), (110, 50),
            (40, 15), (80, 15), (40, 85), (80, 85),
            (15, 35), (105, 35), (15, 65), (105, 65),
            (35, 50), (85, 50), (60, 35), (60, 65),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (50, 40), (70, 40), (50, 60), (70, 60)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 7: WIRE CONNECTIONS between hoods ===
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hx1-hx2) + abs(hy1-hy2) > 45: continue
            if abs(hy1 - hy2) <= 3:
                mid_y = (hy1 + hy2) // 2
                for cx3 in range(min(hx1,hx2)+1, max(hx1,hx2)):
                    if ib(cx3, mid_y) and bool(em[mid_y, cx3]) and not bool(pm[mid_y, cx3]):
                        if not bool(wm[mid_y, cx3]):
                            return (Tool.WIRE, cx3, mid_y)
            if abs(hx1 - hx2) <= 3:
                mid_x = (hx1 + hx2) // 2
                for cy3 in range(min(hy1,hy2)+1, max(hy1,hy2)):
                    if ib(mid_x, cy3) and bool(em[cy3, mid_x]) and not bool(pm[cy3, mid_x]):
                        if not bool(wm[cy3, mid_x]):
                            return (Tool.WIRE, mid_x, cy3)

    # === FALLBACK: extend wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants + wire spines + flanking roads."""
    actions = []
    # Three coal plants spread horizontally at mid-height
    for px, py in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at rows 25, 50, 75
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at cols 20, 60, 100
    for wx in [20, 60, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire and road infrastructure definitions
    wire_rows = [10, 25, 40, 50, 60, 75, 90]
    wire_cols = [12, 20, 36, 48, 60, 72, 84, 96, 108]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    phase = step % 12

    # Phase 0: Ensure power plants distributed across map quadrants
    if phase == 0:
        plant_targets = []
        for py2 in [12, 30, 50, 70, 88]:
            for px2 in [15, 35, 60, 85, 105]:
                plant_targets.append((px2, py2))
        for px2, py2 in plant_targets:
            x0, x1 = max(0, px2 - 20), min(WORLD_W, px2 + 21)
            y0, y1 = max(0, py2 - 20), min(WORLD_H, py2 + 21)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px2 + dx, py2 + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill gaps in horizontal wire rows
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill gaps in vertical wire cols
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]) and not bool(rm[wy2, wc]):
                    up = wy2 > 0 and (bool(wm[wy2-1, wc]) or bool(pm[wy2-1, wc]))
                    dn = wy2 < WORLD_H-1 and (bool(wm[wy2+1, wc]) or bool(pm[wy2+1, wc]))
                    if (up or dn) and bool(em[wy2, wc]):
                        return (Tool.WIRE, wc, wy2)

    # Phase 3: Roads above/below horizontal wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                                   (ry > 0 and bool(rm[ry-1, rx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # Phase 4: Roads left/right of vertical wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                                   bool(rm[ry, max(0, rcx-1)]) or
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # Phase 5: Cross streets between wire rows
    if phase == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            for frac in [0.33, 0.5, 0.67]:
                mid_y = int(r1 + (r2 - r1) * frac)
                if not (0 < mid_y < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])) or
                               (mid_y > 0 and bool(rm[mid_y-1, rx])) or
                               (mid_y < WORLD_H-1 and bool(rm[mid_y+1, rx])))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # Phase 6: Wire unpowered zones reactively
    if phase == 6:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 7: Road to unroaded zones reactively
    if phase == 7:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 8: Extend road from existing roads into powered areas
    if phase == 8:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 9: Extend wire from existing wire network
    if phase == 9:
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            sk2 = (step * 13) % len(wire_xs3)
            for off in range(min(len(wire_xs3), 150)):
                k = (sk2 + off * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2+dx3, wy2+dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CIVIC SERVICES scaled to population ----
    if pop > 30:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,25),(115,25),(5,50),(115,50),
            (5,75),(115,75),(5,95),(30,95),(60,95),(90,95),(115,95),
            (35,50),(65,50),(95,50),(50,20),(80,20),(50,80),(80,80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 120:
        police_spots = [
            (20,15),(50,15),(80,15),(110,15),
            (20,35),(50,35),(80,35),(110,35),
            (20,55),(50,55),(80,55),(110,55),
            (20,75),(50,75),(80,75),(110,75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(30,20),(90,20),(30,80),(90,80),(60,50),(15,50),(105,50),(60,10),(60,90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,20),(115,20),(5,80),(115,80),
            (30,5),(90,5),(30,95),(90,95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5,95),(115,95),(5,5),(115,5),(60,95),(60,5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 7 == 3:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Protect infrastructure corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active expansion centers scale with population
        if pop < 200:
            active_centers = [
                (60,50),(40,50),(80,50),(60,35),(60,65),
                (25,50),(95,50),(60,25),(60,75),(60,15),(60,85),
            ]
        elif pop < 600:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 10 + col * 15
                    cy = 10 + row * 16
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 7 + col * 11
                    cy = 7 + row * 11
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

