def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Dilate helper
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # --- Wire corridor definitions (reactive) ---
    # We use multiple horizontal and vertical wires
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    # PHASE based on step mod
    phase = step % 8

    # --- PHASE 0: Ensure each active wire row has wire seeded ---
    if phase == 0:
        for wr in wire_rows:
            row_has_power = bool(np.any(wm[wr, :] | pm[wr, :]))
            if not row_has_power:
                # Seed from nearest plant
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    px2 = int(plant_xs[best])
                    if ib(px2, wr) and bool(em[wr, px2]):
                        return (Tool.WIRE, px2, wr)
            else:
                # Extend wire across the row
                for wx in range(1, WORLD_W - 1):
                    if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                        has_adj = (ib(wx-1, wr) and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))) or \
                                  (ib(wx+1, wr) and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                        if has_adj and bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # --- PHASE 1: Extend vertical wire corridors ---
    elif phase == 1:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    has_adj = (ib(wc, wy-1) and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or \
                              (ib(wc, wy+1) and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    if has_adj and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # --- PHASE 2: Roads parallel to wire rows ---
    elif phase == 2:
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # --- PHASE 3: Roads parallel to wire columns ---
    elif phase == 3:
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # --- PHASE 4: Connect wire rows to cols (cross-wires) ---
    elif phase == 4:
        for wc in wire_cols:
            for wr in wire_rows:
                if bool(em[wr, wc]) and not bool(pm[wr, wc]):
                    # Check if either has wire nearby
                    row_has = bool(np.any(wm[wr, :] | pm[wr, :]))
                    col_has = bool(np.any(wm[:, wc] | pm[:, wc]))
                    if row_has or col_has:
                        return (Tool.WIRE, wc, wr)

    # --- PHASE 5: ENSURE NEW POWER PLANTS if coverage needed ---
    elif phase == 5:
        # Check if there are large unpowered regions
        unpowered_empty = em & ~near_power
        if np.sum(unpowered_empty) > 200:
            # Find centroid of unpowered area
            uy, ux = np.where(unpowered_empty)
            if len(ux) > 0:
                mid_x = int(np.median(ux))
                mid_y = int(np.median(uy))
                # Place coal plant nearby if funds allow
                for r in range(1, 12):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = mid_x + dx, mid_y + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # --- PHASE 6: Civic services reactively ---
    elif phase == 6:
        if pop > 100:
            fire_spots = [(20, 20), (60, 20), (100, 20),
                          (20, 50), (60, 50), (100, 50),
                          (20, 80), (60, 80), (100, 80)]
            for (sx, sy) in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)
        if pop > 300:
            police_spots = [(35, 35), (75, 35), (35, 65), (75, 65),
                            (10, 50), (110, 50)]
            for (sx, sy) in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)
        if pop > 700:
            stadium_spots = [(50, 40), (70, 40), (50, 60), (70, 60)]
            for (sx, sy) in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)
        if pop > 1500:
            nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5)]
            for (nx2, ny2) in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)
        if pop > 2000:
            seaports = [(10, 94), (110, 94)]
            for (sx, sy) in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 4000:
            airports = [(55, 5), (65, 5)]
            for (sx, sy) in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # --- PHASE 7: Cross roads between corridors ---
    elif phase == 7:
        for wc_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                          (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                    if adj and bool(near_power[ry, mid_x]):
                        return (Tool.ROAD, mid_x, ry)

    # ---- ZONE PLACEMENT (always try after phase logic) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/plant corridors
    for wr in wire_rows:
        cand_mask[wr, :] = False
    for wc in wire_cols:
        cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Pick based on step offset for variety
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(cxs2), 1)
        checked = 0
        for i in range(len(cxs2)):
            k = (offset + i) % len(cxs2)
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- FALLBACK: extend wire toward unpowered hoods ----
    active_hoods = []
    for wr in wire_rows:
        for wc in wire_cols:
            active_hoods.append((wc, wr))
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend road near power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: wire extension ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Parks for city score
    if pop > 200 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    return None

def init(obs, state):
    """Bootstrap: coal plants at corners + center, wire + road spines"""
    actions = []
    # Five power plants spread across map
    for px, py in [(20, 20), (100, 20), (20, 80), (100, 80), (60, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire at key rows
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire at key cols
    for wx in [20, 50, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if pop < 100:
            if ir < 0.35: return Tool.INDUSTRIAL
            if cr < 0.25: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if ir < 0.25: return Tool.INDUSTRIAL
            if cr < 0.25: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30: return Tool.COMMERCIAL
            if ind_count / total_zones < 0.20: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Key infrastructure rows/cols
    wire_rows = [20, 40, 60, 80]
    wire_cols = [20, 50, 80, 100]
    road_offsets = [-1, 1]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]): return False
        return True

    # --- REACTIVE: Fix missing wires on key rows ---
    if step % 8 == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H): continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    neighbors_wired = (
                        (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))) or
                        (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    )
                    if neighbors_wired and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # --- REACTIVE: Fix missing wires on key cols ---
    if step % 8 == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W): continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    neighbors_wired = (
                        (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or
                        (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    )
                    if neighbors_wired and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # --- REACTIVE: Roads flanking wire rows ---
    if step % 8 == 2:
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1): continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire_above = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        if has_wire_above:
                            adj_road = (
                                (rx > 0 and bool(rm[ry, rx-1])) or
                                (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                                rx == 1
                            )
                            if adj_road:
                                return (Tool.ROAD, rx, ry)

    # --- REACTIVE: Roads flanking wire cols ---
    if step % 8 == 3:
        for wc in wire_cols:
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1): continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        if has_wire:
                            adj_road = (
                                (ry > 0 and bool(rm[ry-1, rcx])) or
                                (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                                ry == 1
                            )
                            if adj_road:
                                return (Tool.ROAD, rcx, ry)

    # --- REACTIVE: Power plant coverage check ---
    if step % 8 == 4:
        # Find areas with zones but no plant within range 15
        plant_near = dilate(pm, 15)
        unplanted_zones = zone_tiles & ~plant_near
        if np.any(unplanted_zones):
            uz_ys, uz_xs = np.where(unplanted_zones)
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            # Find empty spot near this zone
            for r in range(1, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = tx+dx, ty+dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)
        # Also check grid targets
        for py2 in range(15, WORLD_H-5, 20):
            for px2 in range(15, WORLD_W-5, 20):
                x0, x1 = max(0, px2-10), min(WORLD_W, px2+11)
                y0, y1 = max(0, py2-10), min(WORLD_H, py2+11)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    for r in range(0, 6):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx)==r or abs(dy)==r or r==0:
                                    nx2, ny2 = px2+dx, py2+dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # --- REACTIVE: Wire toward unpowered zones ---
    if step % 8 == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 13) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- REACTIVE: Road toward unroaded zones ---
    if step % 8 == 6:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bwy else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES (reactive to pop) ---
    if pop > 30:
        fire_spots = [
            (6,6),(35,6),(65,6),(95,6),(113,6),
            (6,30),(113,30),(6,50),(113,50),
            (6,70),(113,70),(6,93),(35,93),(65,93),(95,93),(113,93),
            (35,50),(65,50),(95,50),(50,20),(80,20),(50,80),(80,80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (20,15),(50,15),(80,15),(110,15),
            (20,35),(50,35),(80,35),(110,35),
            (20,55),(50,55),(80,55),(110,55),
            (20,75),(50,75),(80,75),(110,75),
            (10,50),(60,20),(60,80),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(30,20),(90,20),(30,80),(90,80),(60,50),(15,50),(105,50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (10,50),(110,50),(60,5),(60,95),
            (10,20),(110,20),(10,80),(110,80),
            (35,10),(85,10),(35,90),(85,90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for sx, sy in [(5,95),(115,95),(5,5),(115,5),(60,95),(60,5)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        for sx, sy in [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 9 == 4:
        park_mask = em & near_road & near_power
        pys, pxs = np.where(park_mask)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- ZONE PLACEMENT: reactive to current power+road coverage ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Protect wire rows and cols
    for wr in wire_rows:
        cand_mask[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):min(WORLD_W,wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Dynamic centers based on pop
        if pop < 150:
            active_centers = [
                (60,50),(45,50),(75,50),(60,38),(60,62),
                (30,50),(90,50),(60,25),(60,75),
            ]
        elif pop < 600:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 12 + row * 18
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 7 + col * 11
                    cy = 7 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plant + initial wire cross + flanking roads."""
    actions = []
    cx, cy = 58, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking wire column
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Horizontal roads at center row
    for dx in range(-6, 7):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Neighborhood anchors in a denser grid
    # 6 columns x 5 rows = 30 neighborhoods
    anchors = []
    for col_i, cx in enumerate([15, 33, 51, 69, 87, 105]):
        for row_i, cy in enumerate([15, 30, 50, 70, 85]):
            anchors.append((cx, cy, col_i * 5 + row_i))

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 3
        if pop < 500:   return 6
        if pop < 900:   return 10
        if pop < 1500:  return 15
        if pop < 2500:  return 20
        if pop < 4000:  return 25
        return 30

    active = anchors[:num_active()]
    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE POWER PLANTS near each active anchor ----
    for (px, py, idx) in active:
        has_plant = False
        for dx in range(-7, 8):
            for dy in range(-7, 8):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place plant at anchor or nearby
            for r in range(0, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                # Check 3x3 clearance
                                clear = all(
                                    ib(nx + ddx, ny + ddy) and (bool(em[ny + ddy, nx + ddx]) or bool(wm[ny + ddy, nx + ddx]))
                                    for ddx in [-1, 0, 1] for ddy in [-1, 0, 1]
                                )
                                if clear:
                                    return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: CONNECT WIRE from existing wire/plant toward uncovered anchors ----
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0:
        for (px, py, idx) in active:
            dists = np.abs(wire_xs.astype(float) - px) + np.abs(wire_ys.astype(float) - py)
            min_dist = float(np.min(dists))
            if min_dist > 5:
                closest_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[closest_k]), int(wire_ys[closest_k])
                dx = 1 if px > wx else (-1 if px < wx else 0)
                dy = 1 if py > wy else (-1 if py < wy else 0)
                for (ddx, ddy) in [(dx, 0), (0, dy), (dx, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: EXTEND WIRE SPINES vertically at anchor columns ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        ext = min(25, 10 + pop // 60)
        spine_top = max(2, py - ext)
        spine_bot = min(WORLD_H - 3, py + ext)
        if wire_col:
            min_wr = min(wire_col)
            max_wr = max(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
        else:
            for dy in range(-8, 9):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)

    # ---- PHASE 4: HORIZONTAL WIRE between adjacent anchors ----
    row_groups = {}
    for (px, py, idx) in active:
        key = py
        if key not in row_groups:
            row_groups[key] = []
        row_groups[key].append(px)

    for row_y, group in row_groups.items():
        group_sorted = sorted(group)
        for i in range(len(group_sorted) - 1):
            x1, x2 = group_sorted[i], group_sorted[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and (bool(em[row_y, cx]) or bool(wm[row_y, cx])) and not bool(pm[row_y, cx]):
                    if not bool(wm[row_y, cx]):
                        return (Tool.WIRE, cx, row_y)

    # ---- PHASE 5: ROADS flanking wire spines ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            continue
        cycle_off = (step + idx * 13) % max(len(wire_col), 1)
        for k in range(min(len(wire_col), 12)):
            wr = wire_col[(cycle_off + k) % len(wire_col)]
            for side in [px - 1, px + 1]:
                if ib(side, wr) and bool(em[wr, side]) and not bool(pm[wr, side]):
                    return (Tool.ROAD, side, wr)

    # ---- PHASE 6: HORIZONTAL ROADS at anchor rows ----
    for (px, py, idx) in active:
        for sign in [-1, 1]:
            for road_y in [py - 1, py + 1]:
                if not ib(px, road_y):
                    continue
                for dx in range(0, 12):
                    rx = px + sign * dx
                    if not ib(rx, road_y):
                        break
                    if bool(em[road_y, rx]) and not bool(pm[road_y, rx]) and not bool(wm[road_y, rx]):
                        near = any(
                            ib(rx + d, road_y) and (bool(rm[road_y, rx + d]) or bool(wm[road_y, rx + d]) or bool(pm[road_y, rx + d]))
                            for d in [-1, 1]
                        ) or any(
                            ib(rx, road_y + d) and (bool(rm[road_y + d, rx]) or bool(wm[road_y + d, rx]) or bool(pm[road_y + d, rx]))
                            for d in [-1, 1]
                        )
                        if near:
                            return (Tool.ROAD, rx, road_y)

    # ---- PHASE 7: ZONE PLACEMENT ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Balanced ratio: 20% ind, 20% com, 60% res
        if ir < 0.18:
            return Tool.INDUSTRIAL
        if cr < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    # Keep border safe
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, idx) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 8: EXTEND ROADS from existing roads ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 7) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 9) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 100:
        firestations = [
            (25, 15), (45, 15), (65, 15), (85, 15), (105, 15),
            (25, 35), (45, 35), (65, 35), (85, 35), (105, 35),
            (25, 55), (45, 55), (65, 55), (85, 55), (105, 55),
            (25, 75), (45, 75), (65, 75), (85, 75), (105, 75),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        polices = [
            (35, 25), (55, 25), (75, 25), (95, 25),
            (35, 45), (55, 45), (75, 45), (95, 45),
            (35, 65), (55, 65), (75, 65), (95, 65),
            (35, 85), (55, 85), (75, 85), (95, 85),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (20, 10), (60, 10), (100, 10),
            (20, 50), (60, 50), (100, 50),
            (20, 90), (60, 90), (100, 90),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- PHASE 10: NUCLEAR PLANTS for high pop ----
    if pop > 2000:
        for (px, py, idx) in active:
            for r in range(2, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                clear = all(
                                    ib(nx + ddx, ny + ddy) and bool(em[ny + ddy, nx + ddx])
                                    for ddx in [-1, 0, 1] for ddy in [-1, 0, 1]
                                )
                                if clear:
                                    return (Tool.NUCLEARPOWER, nx, ny)

    # ---- FALLBACK: Extend wire from wire frontier ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 40)):
            k = (step_k2 + offset * 7) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: coal plant + cross wires + flanking roads."""
    actions = []
    cx, cy = 55, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking wire column
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- NEIGHBORHOOD ANCHORS: 5 cols x 5 rows = 25 ----
    anchors = []
    for col_i, cx in enumerate([15, 35, 55, 75, 95]):
        for row_i, cy in enumerate([15, 30, 50, 70, 85]):
            anchors.append((cx, cy, col_i * 5 + row_i))

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 2
        if pop < 400:   return 4
        if pop < 800:   return 6
        if pop < 1500:  return 9
        if pop < 2500:  return 13
        if pop < 4000:  return 18
        return 25

    active = anchors[:num_active()]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active anchor ----
    for (px, py, idx) in active:
        has_plant = False
        for dx in range(-6, 7):
            for dy in range(-6, 7):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: EXTEND WIRE toward uncovered anchors ----
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0:
        for (px, py, idx) in active:
            dists = np.abs(wire_xs.astype(float) - px) + np.abs(wire_ys.astype(float) - py)
            min_dist = float(dists.min())
            if min_dist > 4:
                closest_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[closest_k]), int(wire_ys[closest_k])
                dx = 1 if px > wx else (-1 if px < wx else 0)
                dy = 1 if py > wy else (-1 if py < wy else 0)
                for (ddx, ddy) in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: VERTICAL WIRE SPINES per anchor column ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            for dy in range(-6, 7):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_col)
            max_wr = max(wire_col)
            ext = min(25, 10 + pop // 60)
            spine_top = max(2, py - ext)
            spine_bot = min(WORLD_H - 3, py + ext)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 4: HORIZONTAL WIRE between adjacent anchors in same row ----
    row_groups = {}
    for (px, py, idx) in active:
        key = py
        if key not in row_groups:
            row_groups[key] = []
        row_groups[key].append(px)

    for row_y, group in row_groups.items():
        group_sorted = sorted(group)
        for i in range(len(group_sorted) - 1):
            x1, x2 = group_sorted[i], group_sorted[i + 1]
            for cx2 in range(x1 + 1, x2):
                if ib(cx2, row_y) and bool(em[row_y, cx2]) and not bool(pm[row_y, cx2]):
                    return (Tool.WIRE, cx2, row_y)

    # ---- PHASE 5: ROADS flanking wire spines ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            continue
        rl, rr = px - 1, px + 1
        cycle_off = (step + idx * 11) % max(len(wire_col), 1)
        for k in range(min(len(wire_col), 12)):
            wr = wire_col[(cycle_off + k) % len(wire_col)]
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- PHASE 6: HORIZONTAL ROADS connecting neighborhoods ----
    for (px, py, idx) in active:
        for dx in range(-12, 13):
            rx = px + dx
            if not ib(rx, py):
                continue
            if bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near = any(
                    ib(rx + d, py) and (bool(rm[py, rx + d]) or bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near:
                    return (Tool.ROAD, rx, py)

    # ---- PHASE 7: ZONE PLACEMENT ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # More industrial early, more residential late
        if pop < 300 and ir < 0.20:
            return Tool.INDUSTRIAL
        if ir < 0.15:
            return Tool.INDUSTRIAL
        if cr < 0.18:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks: road within 2, wire/plant within 6
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, idx) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 8: EXTEND ROADS near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 7) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 9) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 100:
        firestations = [
            (25, 15), (45, 15), (65, 15), (85, 15),
            (25, 30), (45, 30), (65, 30), (85, 30),
            (25, 50), (45, 50), (65, 50), (85, 50),
            (25, 70), (45, 70), (65, 70), (85, 70),
            (25, 85), (45, 85), (65, 85), (85, 85),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        polices = [
            (35, 22), (55, 22), (75, 22), (95, 22),
            (35, 42), (55, 42), (75, 42), (95, 42),
            (35, 62), (55, 62), (75, 62), (95, 62),
            (35, 82), (55, 82), (75, 82), (95, 82),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (20, 8), (60, 8), (100, 8),
            (20, 92), (60, 92), (100, 92),
            (8, 45), (112, 45),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- PHASE 10: NUCLEAR PLANTS for high pop ----
    if pop > 2000:
        nuke_spots = [
            (20, 50), (90, 50), (55, 20), (55, 80),
            (20, 20), (90, 20), (20, 80), (90, 80),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- FALLBACK: Extend wire from any wire tile ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 50)):
            k = (step_k2 + offset * 7) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + road grid"""
    actions = []
    # Two coal plants: left-center and right-center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines at y=25, 50, 75
    for x in range(1, 119):
        for wy in [25, 50, 75]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at x=15, 30, 60, 90, 105
    for y in range(1, 99):
        for wx in [15, 30, 60, 90, 105]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for x in range(1, 119):
        for wy in [25, 50, 75]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # 50% res, 25% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire spine rows/cols
    wire_rows = [25, 50, 75]
    wire_cols = [15, 30, 60, 90, 105]
    road_offset_rows = [24, 26, 49, 51, 74, 76]

    # ---- CLOSED-LOOP: check what's missing and fix it ----

    # 1. If fewer than 2 power plants, place one near center
    plant_ys, plant_xs = np.where(pm)
    if len(plant_xs) < 2:
        for px, py in [(30, 50), (90, 50), (60, 25), (60, 75)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # 2. Ensure wire spines are complete (scan and fill gaps)
    # Check horizontal wire spines
    for wr in wire_rows:
        for wx in range(1, WORLD_W - 1):
            if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                # Check if adjacent wire/plant exists
                left = (wx > 0) and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = (wx < WORLD_W-1) and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if (left or right) and bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)

    # Check vertical wire spines
    for wc in wire_cols:
        for wy in range(1, WORLD_H - 1):
            if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                up = (wy > 0) and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                down = (wy < WORLD_H-1) and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if (up or down) and bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)

    # 3. Ensure roads along wire spines
    for wr in wire_rows:
        for offset in [-1, 1]:
            ry = wr + offset
            if not (0 < ry < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # 4. Vertical roads along wire cols (connecting the horizontal bands)
    for wc in wire_cols:
        for offset in [-1, 1]:
            rcx = wc + offset
            if not (0 < rcx < WORLD_W - 1):
                continue
            # Only fill between wire rows
            for ry in range(1, WORLD_H - 1):
                wr = ry
                if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # 5. Reactive zone placement
    # Find cells with both road and power access
    cand_mask = em & near_road & near_power
    # Keep away from edges and infrastructure rows/cols
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire spines
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-2):wc+3] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Pick nearest candidate to center of map (60,50) weighted by distance
        # Also weight by road proximity for dense building
        center_x, center_y = 60, 50
        # Score: closer to center + has road very nearby
        road_near2 = dilate(rm, 1)
        scores = (np.abs(cxs - center_x) + np.abs(cys - center_y)).astype(float)
        # Bonus for very close road
        road_bonus = road_near2[cys, cxs].astype(float) * (-3.0)
        scores += road_bonus
        order = np.argsort(scores)
        tool = pick_tool()
        for i in range(min(len(order), 2000)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # 6. If no zones placeable, extend road from existing road near power
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 200)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # 7. Extend wire toward unpowered zones
    unpowered_zones = zone_tiles & ~near_power
    zone_ys_u, zone_xs_u = np.where(unpowered_zones)
    if len(zone_xs_u) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 17) % len(zone_xs_u)
            tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # 8. Civic services (reactive to population)
    if pop > 20:
        fire_spots = [
            (5, 5), (55, 5), (115, 5),
            (5, 35), (55, 35), (115, 35),
            (5, 65), (55, 65), (115, 65),
            (5, 93), (55, 93), (115, 93),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (20, 12), (60, 12), (100, 12),
            (20, 62), (60, 62), (100, 62),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadiums = [(40, 38), (80, 38), (40, 62), (80, 62)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        # Add nuclear power
        nuke_spots = [(5, 5), (113, 5), (5, 93), (113, 93), (60, 5), (60, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5, 93), (113, 93), (59, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(48, 5), (72, 5), (48, 90), (72, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 50 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Add extra coal plants reactively if needed
    if obs.powered_zones < total_zones - 5 and pop > 50:
        # Find a powered empty spot for another plant
        powered_empty = em & near_power
        peys, pexs = np.where(powered_empty)
        if len(pexs) > 0:
            idx = (step * 23) % len(pexs)
            px2, py2 = int(pexs[idx]), int(peys[idx])
            if ib(px2, py2):
                return (Tool.COALPOWER, px2, py2)

    # Fallback: extend road from zones
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
