def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- BUILD NEIGHBOR MASKS (vectorized) ----
    # Road within 3 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power (wire or plant) within 3 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- CLOSED-LOOP: GROW WIRE FROM EXISTING WIRE/PLANT ----
    # Priority: extend wire toward uncovered areas that have road access
    # This is purely reactive to current tile_map

    # Find wire frontier: wire tiles adjacent to empty tiles
    wire_ys, wire_xs = np.where(wm | pm)

    # Strategy: extend wire to cover the map in a systematic sweep
    # Use step to determine direction bias
    if len(wire_xs) > 0:
        # Find empty tiles adjacent to wire that are not yet powered
        # and prioritize those near roads (for future zone placement)
        best_score = -1
        best_action = None

        # Sample a subset of wire tiles to check neighbors
        num_sample = min(len(wire_xs), 100)
        indices = np.linspace(0, len(wire_xs)-1, num_sample, dtype=int)

        for k in indices:
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if not ib(nx, ny): continue
                if not bool(em[ny, nx]): continue
                if bool(pm[ny, nx]): continue
                # Score: prefer extending toward map edges + toward roads
                road_bonus = 3 if bool(nbr_road[ny, nx]) else 0
                # Prefer directions that expand coverage
                dist_center = abs(nx - 60) + abs(ny - 50)
                score = road_bonus + dist_center * 0.01
                if score > best_score:
                    best_score = score
                    best_action = (Tool.WIRE, nx, ny)

        # Only extend wire if we need more coverage (not too many wires)
        wire_count = len(wire_xs)
        if wire_count < 400 and best_action is not None and (step % 3 == 0):
            return best_action

    # ---- PHASE: ENSURE POWER PLANTS near active neighborhoods ----
    nh_cols = [10, 28, 46, 60, 74, 92, 110]
    nh_rows = [10, 25, 40, 58, 73, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 7
        if pop < 600:   return 12
        if pop < 1000:  return 18
        if pop < 2000:  return 26
        if pop < 4000:  return 36
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Check each active hood for power plant
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center or nearby empty spot
            for r in range(0, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r: continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- REACTIVE ROAD EXTENSION ----
    # Extend roads adjacent to existing roads into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        # Find road tiles and try to extend them
        num_r = min(len(road_xs), 150)
        offset_r = (step * 11) % max(len(road_xs), 1)
        for i in range(num_r):
            k = (offset_r + i * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = rx+dx, ry+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if bool(nbr_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # ---- CONNECT WIRE BETWEEN HOODS (reactive bridging) ----
    # Find pairs of hoods that are close but not wire-connected
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            dist = abs(hx1-hx2) + abs(hy1-hy2)
            if dist > 25: continue
            # Check if area between them lacks wire
            mid_x = (hx1 + hx2) // 2
            mid_y = (hy1 + hy2) // 2
            if not bool(wm[mid_y, mid_x]) and not bool(pm[mid_y, mid_x]):
                # Lay wire along the path between hoods
                if hy1 == hy2:
                    for cx in range(min(hx1,hx2)+1, max(hx1,hx2)):
                        if ib(cx, hy1) and bool(em[hy1, cx]):
                            for ax in [cx-1, cx+1]:
                                if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                                    return (Tool.WIRE, cx, hy1)
                elif hx1 == hx2:
                    for cy in range(min(hy1,hy2)+1, max(hy1,hy2)):
                        if ib(hx1, cy) and bool(em[cy, hx1]):
                            for ay in [cy-1, cy+1]:
                                if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                                    return (Tool.WIRE, hx1, cy)

    # ---- ZONE PLACEMENT (reactive to current power+road coverage) ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 35% RES, 35% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power, not on border
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates: prefer near active hoods and near existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)

        # Also give bonus to spots near existing zones (cluster effect)
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            zone_bonus = np.zeros(len(cxs))
            # Vectorized: count zone neighbors within 5 tiles
            for i in range(min(len(cxs), 500)):
                zd = np.abs(zone_xs - cxs[i]) + np.abs(zone_ys - cys[i])
                zone_bonus[i] = np.sum(zd <= 5) * 2
            best_dist = best_dist - zone_bonus

        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- WIRE EXTENSION (fallback: grow wire from any wire tile) ----
    if len(wire_xs) > 0:
        step_k = (step * 13) % max(len(wire_xs), 1)
        for offset in range(min(len(wire_xs), 80)):
            k = (step_k + offset * 5) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx+dx, wy+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- CIVIC SERVICES (reactive to population thresholds) ----
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 20) for fy in range(12, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px, py) for px in range(18, WORLD_W, 24) for py in range(18, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadiums = [(30, 30),(60, 30),(90, 30),(30, 70),(60, 70),(90, 70),
                    (15, 50),(105, 50),(60, 15),(60, 85)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90),(112, 90),(8, 10),(112, 10),(60, 95),(60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(45, 6),(75, 6),(45, 94),(75, 94),(6, 45),(114, 45)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high pop ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60,50),(30,25),(90,25),(30,75),(90,75),
                         (10,50),(110,50),(60,10),(60,90)]
        for (nx, ny) in nuclear_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    # ---- PARKS for land value ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py, px = int(park_ys[idx]), int(park_xs[idx])
            if ib(px, py) and bool(em[py, px]):
                return (Tool.PARK, px, py)

    # ---- FALLBACK: place new coal plant near uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(0, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r: continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants + wire connections + initial roads near center"""
    actions = []
    # Place 4 coal plants in a cross pattern
    plants = [(30, 30), (90, 30), (30, 70), (90, 70)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire from each plant toward center (60,50)
    for px, py in plants:
        cx, cy = 60, 50
        step_x = 1 if cx > px else -1
        for x in range(px + step_x, cx, step_x):
            actions.append((Tool.WIRE, x, py))
        step_y = 1 if cy > py else -1
        for y in range(py, cy + step_y, step_y):
            actions.append((Tool.WIRE, cx, y))
    # Initial roads near center
    for x in range(52, 69):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(44, 57):
        actions.append((Tool.ROAD, 52, y))
        actions.append((Tool.ROAD, 68, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID ----
    # 4x4 grid of neighborhoods
    nh_positions = []
    for row in range(4):
        for col in range(4):
            cx = 15 + col * 30   # 15, 45, 75, 105
            cy = 12 + row * 26   # 12, 38, 64, 90
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 50:
            return nh_positions[5:7] + nh_positions[9:11]
        elif pop < 200:
            return nh_positions[4:8] + nh_positions[8:12]
        elif pop < 600:
            return nh_positions[1:15]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # ---- DILATION HELPER ----
    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    nbr_power = dilate(power_src, 6)
    nbr_road = dilate(rm, 2)

    # ---- ZONE CLEAR CHECK ----
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                # Allow empty or existing zone tiles only
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: ENSURE POWER PLANTS PER HOOD ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE NETWORK ----
    # Wire corridors along major axes matching hood positions
    wire_rows = [12, 38, 64, 90]
    wire_cols = [15, 45, 75, 105]

    wire_phase = step % 4

    if wire_phase == 0:
        # Horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if ib(wx, wr) and not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    adj = False
                    for adx in [-1, 1]:
                        ax = wx + adx
                        if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                            adj = True
                            break
                    if adj:
                        return (Tool.WIRE, wx, wr)

    elif wire_phase == 1:
        # Vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if ib(wc, wy) and not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    adj = False
                    for ady in [-1, 1]:
                        ay = wy + ady
                        if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                            adj = True
                            break
                    if adj:
                        return (Tool.WIRE, wc, wy)

    elif wire_phase == 2:
        # Extend wire spurs to hoods not yet powered
        for (hx, hy) in active_hoods:
            if not bool(nbr_power[hy, hx]):
                # Find nearest wire/plant
                best = None
                best_d = 999
                for wy_r in range(max(0, hy - 20), min(WORLD_H, hy + 21)):
                    for wy_c in range(max(0, hx - 20), min(WORLD_W, hx + 21)):
                        if bool(wm[wy_r, wy_c]) or bool(pm[wy_r, wy_c]):
                            d = abs(wy_r - hy) + abs(wy_c - hx)
                            if d < best_d:
                                best_d = d
                                best = (wy_c, wy_r)
                if best is not None:
                    bx, by = best
                    # Step from wire toward hood
                    dx = 0 if bx == hx else (1 if hx > bx else -1)
                    dy = 0 if by == hy else (1 if hy > by else -1)
                    # Move from wire side toward hood
                    nx, ny = bx + dx, by + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    else:
        # Fill wire gaps - extend from any wire/plant into empty space
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            k = (step * 7) % len(wire_xs)
            for i in range(min(len(wire_xs), 40)):
                idx = (k + i) % len(wire_xs)
                wx2, wy2 = int(wire_xs[idx]), int(wire_ys[idx])
                for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx2, ny2 = wx2 + dx2, wy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        # Only extend toward unpowered hoods
                        hood_unpowered = any(
                            not bool(nbr_power[hy, hx]) and
                            abs(nx2 - hx) + abs(ny2 - hy) < abs(wx2 - hx) + abs(wy2 - hy)
                            for hx, hy in active_hoods
                        )
                        if hood_unpowered:
                            return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 3: ROAD NETWORK ----
    # Roads parallel to wire corridors (offset by ±1 so zones can sit between)
    road_phase = step % 3

    if road_phase == 0:
        # Roads parallel to wire rows
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not ib(0, ry):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Only if wire exists nearby in that column
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    elif road_phase == 1:
        # Roads parallel to wire columns
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not ib(rcx, 0):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if ib(rcx, ry) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    else:
        # Cross streets between wire corridors
        for col_idx in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[col_idx], wire_cols[col_idx + 1]
            for mid_x in range(c1 + 6, c2, 6):
                if not ib(mid_x, 0):
                    continue
                for ry in range(2, WORLD_H - 2):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                        adj_road = any(
                            ib(mid_x, ry + ady) and bool(rm[ry + ady, mid_x])
                            for ady in [-1, 1]
                        )
                        if adj_road and bool(nbr_power[ry, mid_x]):
                            return (Tool.ROAD, mid_x, ry)

        # Also horizontal cross streets between wire rows
        for row_idx in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[row_idx], wire_rows[row_idx + 1]
            for mid_y in range(r1 + 6, r2, 6):
                for rx in range(2, WORLD_W - 2):
                    if ib(rx, mid_y) and bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        adj_road = any(
                            ib(rx + adx, mid_y) and bool(rm[mid_y, rx + adx])
                            for adx in [-1, 1]
                        )
                        if adj_road and bool(nbr_power[mid_y, rx]):
                            return (Tool.ROAD, rx, mid_y)

    # ---- PHASE 4: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Candidate zone centers: near road and power, not on infrastructure
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    cand_mask &= ~rm & ~wm

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer close to active hood centers and close to roads
        best_hood_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_hood_dist = np.minimum(best_hood_dist, d)

        # Road proximity bonus
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 300)
            road_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs - road_xs[i]) + np.abs(cys - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.ones(len(cxs)) * 9999.0

        score = best_hood_dist * 0.5 + road_dist * 2.0
        order = np.argsort(score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_grid = [
            (20, 12), (60, 12), (100, 12),
            (20, 38), (60, 38), (100, 38),
            (20, 64), (60, 64), (100, 64),
            (20, 90), (60, 90), (100, 90),
        ]
        for (sx, sy) in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_grid = [
            (35, 25), (75, 25),
            (15, 51), (55, 51), (95, 51),
            (35, 77), (75, 77),
        ]
        for (sx, sy) in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            return (Tool.PARK, px2, py2)

    if pop > 700:
        stadiums = [(45, 50), (75, 50), (45, 25), (75, 75), (15, 50), (105, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_power[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1000:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 7), min(WORLD_W, nx + 8)
                y0, y1 = max(0, ny - 7), min(WORLD_H, ny + 8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3000:
        airports = [(55, 5), (55, 93)]
        for (apx, apy) in airports:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend road from existing road ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant if no power near unpowered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with wire cross and flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending outward
    for d in range(1, 12):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Two horizontal roads flanking the wire spine
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 3))
        actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target zone mix: 50% RES, 30% COM, 20% IND
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 9 neighborhood anchors in a 3x3 grid, expanding with population
    all_anchors = [
        (30, 25), (60, 25), (90, 25),
        (30, 50), (60, 50), (90, 50),
        (30, 75), (60, 75), (90, 75),
    ]

    def num_active():
        if pop < 50:   return 1
        if pop < 200:  return 3
        if pop < 500:  return 5
        if pop < 900:  return 7
        return 9

    active_anchors = all_anchors[:num_active()]

    # --- Build neighbor masks (reactive, based on current map) ---
    # Power neighbor: wire or plant within 6 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            if abs(dx) + abs(dy) > 6:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Road neighbor: road within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # --- PHASE 1: Ensure each active anchor has a nearby power plant ---
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            # If already near wire from another plant, skip planting here
            if bool(nbr_power[py, px]):
                continue
            for r in range(0, 9):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            nearby_z = int(np.sum(zone_tiles[y0:y1, x0:x1]))
                            tool_p = Tool.NUCLEARPOWER if nearby_z > 20 and funds > 8000 else Tool.COALPOWER
                            return (tool_p, nx, ny)

    # --- PHASE 2: Wire cross at each anchor (reactively extend adjacent to existing wire/plant) ---
    spine = min(12, 6 + pop // 80)
    for (px, py) in active_anchors:
        # Horizontal spine
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if not ib(wx, wy): continue
            if not bool(em[wy, wx]) or bool(pm[wy, wx]): continue
            # Only place if adjacent to existing wire or plant
            for adx in [-1, 1]:
                ax = wx + adx
                if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                    return (Tool.WIRE, wx, wy)
        # Vertical spine
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if not ib(wx, wy): continue
            if not bool(em[wy, wx]) or bool(pm[wy, wx]): continue
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                    return (Tool.WIRE, wx, wy)

    # --- PHASE 3: Connect anchors horizontally with wire ---
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1a = row_anchors[i][0]
            x2a = row_anchors[i + 1][0]
            for cx in range(x1a + 1, x2a):
                if not ib(cx, yl): continue
                if not bool(em[yl, cx]) or bool(pm[yl, cx]): continue
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, yl) and (bool(wm[yl, ax]) or bool(pm[yl, ax])):
                        return (Tool.WIRE, cx, yl)

    # --- PHASE 4: Connect anchors vertically with wire ---
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1a = col_anchors[i][1]
            y2a = col_anchors[i + 1][1]
            for cy in range(y1a + 1, y2a):
                if not ib(xl, cy): continue
                if not bool(em[cy, xl]) or bool(pm[cy, xl]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(xl, ay) and (bool(wm[ay, xl]) or bool(pm[ay, xl])):
                        return (Tool.WIRE, xl, cy)

    # --- PHASE 5: Roads flanking wire spines (reactive: only where spine wire exists) ---
    for (px, py) in active_anchors:
        for road_dy in [-3, 3]:
            ry = py + road_dy
            if not ib(px, ry): continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                # Only lay road if there's wire on the spine row
                if bool(wm[ry - road_dy, rx]) if ib(rx, ry - road_dy) else False:
                    return (Tool.ROAD, rx, ry)
                # Also lay if adjacent road exists
                for adx in [-1, 1]:
                    ax = rx + adx
                    if ib(ax, ry) and bool(rm[ry, ax]):
                        return (Tool.ROAD, rx, ry)

    # --- PHASE 6: Vertical roads connecting rows ---
    if pop > 30:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                y1a = col_anchors[i][1]
                y2a = col_anchors[i + 1][1]
                for road_x in [xl + 4, xl - 4]:
                    for cy in range(y1a, y2a + 1):
                        if not ib(road_x, cy): continue
                        if not bool(em[cy, road_x]) or bool(pm[cy, road_x]): continue
                        # Only place if adjacent to existing road
                        for ady in [-1, 1]:
                            ay = cy + ady
                            if ib(road_x, ay) and bool(rm[ay, road_x]):
                                return (Tool.ROAD, road_x, cy)

    # --- PHASE 7: Zone placement (reactive: near existing road+power) ---
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # --- PHASE 8: Extend roads into powered empty areas from existing roads ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 9: Civic services scaled to population ---
    if pop > 80:
        fire_spots = [
            (15, 20), (50, 20), (85, 20), (115, 20),
            (15, 50), (85, 50), (115, 50),
            (15, 80), (50, 80), (85, 80), (115, 80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (20, 15), (60, 15), (100, 15),
            (20, 50), (100, 50),
            (20, 85), (60, 85), (100, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        for sp in [(10, 5), (60, 5), (110, 5), (10, 94), (60, 94), (110, 94)]:
            sx, sy = sp
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        for np2 in [(5, 5), (115, 5), (5, 94), (115, 94)]:
            nx2, ny2 = np2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for ap in [(55, 6), (5, 50), (115, 50)]:
            ax, ay = ap
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # --- PHASE 10: Parks to boost land value near zones ---
    if pop > 200 and step % 4 == 0:
        zone_ys2, zone_xs2 = np.where(zone_tiles)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # --- FALLBACK: extend wire from existing wire/plant ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 120)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- LAST RESORT: place coal plant near any unpowered anchor ---
    for (px, py) in active_anchors:
        if not bool(nbr_power[py, px]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants connected by wire grid, plus initial road spine"""
    actions = []
    # Two power plants: left and right of center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at x=30 and x=90
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Initial road grid skeleton
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(resm[nr, nc]) or
                        bool(comm[nr, nc]) or bool(indm[nr, nc])):
                    return False
        return True

    # === Periodic road grid expansion ===
    # Build horizontal roads every 8 rows (grid pattern)
    if step % 11 == 0:
        road_rows = list(range(10, 90, 8))
        for ry in road_rows:
            # Check if this row has road coverage
            row_road_count = int(np.sum(rm[ry, :]))
            if row_road_count < 50:
                # Find a gap and extend
                for rx in range(2, 118):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    if step % 11 == 1:
        # Build vertical roads every 8 cols
        road_cols = list(range(10, 115, 8))
        for cx in road_cols:
            col_road_count = int(np.sum(rm[:, cx]))
            if col_road_count < 40:
                for cy in range(2, 98):
                    if bool(em[cy, cx]) and not bool(pm[cy, cx]):
                        return (Tool.ROAD, cx, cy)

    # === Power plant placement for underserved regions ===
    if step % 25 == 5:
        # Check 20x20 blocks for power
        for py in range(10, 90, 20):
            for px in range(10, 110, 20):
                x0, x1 = max(0, px-10), min(WORLD_W, px+10)
                y0, y1 = max(0, py-10), min(WORLD_H, py+10)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    # Place plant
                    for r in range(15):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px+dx, py+dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # === Wire extension toward unpowered road areas ===
    if step % 7 in (2, 3):
        unpowered_roads = rm & ~near_power
        ur_ys, ur_xs = np.where(unpowered_roads)
        if len(ur_xs) > 0:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                idx = (step * 23 + pop) % len(ur_xs)
                tx, ty = int(ur_xs[idx]), int(ur_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # === Extend wires from power frontier outward ===
    if step % 7 in (4, 5):
        power_src = wm | pm
        frontier_ys, frontier_xs = np.where(power_src)
        if len(frontier_xs) > 0:
            candidates = []
            n_sample = min(len(frontier_xs), 100)
            sk = (step * 37 + pop) % len(frontier_xs)
            for i in range(n_sample):
                k = (sk + i * 13) % len(frontier_xs)
                fx, fy = int(frontier_xs[k]), int(frontier_ys[k])
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx2, ny2 = fx+dx, fy+dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(near_power[ny2, nx2]):
                        candidates.append((nx2, ny2))
            if candidates:
                pm_ys, pm_xs = np.where(power_src)
                cx_p = float(np.mean(pm_xs)) if len(pm_xs) > 0 else 60
                cy_p = float(np.mean(pm_ys)) if len(pm_ys) > 0 else 50
                best = max(candidates[:40], key=lambda c: abs(c[0]-cx_p)+abs(c[1]-cy_p))
                return (Tool.WIRE, best[0], best[1])

    # === Civic services ===
    if pop > 5:
        fire_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,40),(45,40),(75,40),(105,40),
            (15,65),(45,65),(75,65),(105,65),
            (15,85),(45,85),(75,85),(105,85),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 40:
        police_spots = [
            (25,25),(55,25),(85,25),(110,25),
            (25,55),(55,55),(85,55),(110,55),
            (25,80),(55,80),(85,80),(110,80),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        for sx, sy in [(20,20),(70,20),(20,70),(70,70),(45,45),(95,45),(45,75),(95,75)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        # Upgrade to nuclear
        for nx2, ny2 in [(30,50),(90,50),(60,20),(60,80),(15,30),(105,30),(15,70),(105,70)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for sx, sy in [(5,90),(115,90),(5,10),(115,10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        for sx, sy in [(50,5),(70,5),(50,93),(70,93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for happiness
    if pop > 80 and step % 8 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:2, :] = False
        park_cands[WORLD_H-2:, :] = False
        park_cands[:, 0:2] = False
        park_cands[:, WORLD_W-2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # === Zone placement: grid-aware, react to power+road coverage ===
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    cand_mask &= ~(wm | rm | pm)

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()

        # Strategy based on population phase
        if pop < 200:
            # Build in two clusters: left (x~30) and right (x~90)
            # alternating between them based on step
            if step % 2 == 0:
                cx_target, cy_target = 30, 50
            else:
                cx_target, cy_target = 90, 50
            dists = (np.abs(cxs - cx_target).astype(float) +
                     np.abs(cys - cy_target).astype(float))
        elif pop < 800:
            # Expand in rings from both clusters
            # Pick least-dense band
            q_counts = [
                int(np.sum(resm[:, :60])) + int(np.sum(comm[:, :60])) + int(np.sum(indm[:, :60])),
                int(np.sum(resm[:, 60:])) + int(np.sum(comm[:, 60:])) + int(np.sum(indm[:, 60:])),
            ]
            cx_target = 30 if q_counts[0] <= q_counts[1] else 90
            cy_target = 50
            ring_r = 15 + pop // 30
            dists = np.abs(np.abs(cxs - cx_target).astype(float) +
                           np.abs(cys - cy_target).astype(float) - ring_r)
        else:
            # Fill entire map, prefer least-occupied quadrant
            q_counts = [
                int(np.sum(resm[:50, :60])) + int(np.sum(comm[:50, :60])) + int(np.sum(indm[:50, :60])),
                int(np.sum(resm[:50, 60:])) + int(np.sum(comm[:50, 60:])) + int(np.sum(indm[:50, 60:])),
                int(np.sum(resm[50:, :60])) + int(np.sum(comm[50:, :60])) + int(np.sum(indm[50:, :60])),
                int(np.sum(resm[50:, 60:])) + int(np.sum(comm[50:, 60:])) + int(np.sum(indm[50:, 60:])),
            ]
            min_q = int(np.argmin(q_counts))
            cx_target = 30 if min_q in (0, 2) else 90
            cy_target = 25 if min_q in (0, 1) else 75
            dists = (np.abs(cxs - cx_target).astype(float) +
                     np.abs(cys - cy_target).astype(float))

        order = np.argsort(dists)
        offset = (step * 11 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === Fallback: extend road toward powered areas ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 17 + pop) % len(road_xs2)
        for off in range(min(len(road_xs2), 150)):
            k = (sk + off * 9) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)
    else:
        # Bootstrap: place road near center
        for dx in range(-3, 4):
            for dy in range(-3, 4):
                nx2, ny2 = 60+dx, 50+dy
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === Fallback: extend wire ===
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        sk2 = (step * 19 + pop) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 80)):
            k = (sk2 + off * 7) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire and road crosses."""
    actions = []
    for (cx, cy) in [(35, 30), (85, 70)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dx in range(-5, 6):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, cx - 3, cy + dy))
            actions.append((Tool.ROAD, cx + 3, cy + dy))
        for dx in range(-4, 5):
            actions.append((Tool.ROAD, cx + dx, cy - 3))
            actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # === NEIGHBORHOOD GRID: spread across map ===
    all_hoods = []
    for hy in range(12, 95, 18):
        for hx in range(12, 115, 18):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 100:  return 4
        if pop < 300:  return 8
        if pop < 600:  return 14
        if pop < 1000: return 20
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # === COMPUTE NEIGHBOR MASKS (CLOSED-LOOP: read from current map) ===
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: ENSURE POWER PLANTS near every active hood ===
    if funds > 2500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE - connect from nearest plant to current hood ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 10

    x0p, x1p = max(0, hx - 18), min(WORLD_W, hx + 19)
    y0p, y1p = max(0, hy - 18), min(WORLD_H, hy + 19)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0
        best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d
                best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        # Wire vertically from plant to hood
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        # Wire horizontally from plant to hood
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend vertical wire spine at hx
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        min_wr, max_wr = min(col_wire), max(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    # Extend horizontal wire spine at hy
    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        min_wc, max_wc = min(row_wire), max(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: ROADS flanking wire spines ===
    # CHANGE: use offset ±2 (tighter than parent's ±3) for denser zone packing
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 2
    for rx in [hx3 - 2, hx3 + 2]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::2]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 2, hy3 + 2]:
        if not ib(hx3, ry): continue
        cyc2 = (step + 1) % 2
        for wc in row_wire3[cyc2::2]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # === PHASE 4: CONNECT HOODS WITH ROADS ===
    if step % 5 < 3:
        for i, (hx1, hy1) in enumerate(active_hoods):
            for (hx2, hy2) in active_hoods[i+1:]:
                dist = abs(hx1-hx2) + abs(hy1-hy2)
                if dist > 30: continue
                if abs(hy1 - hy2) <= 3:
                    mid_y = (hy1 + hy2) // 2
                    step_conn = step % max(abs(hx2-hx1), 1)
                    cx2 = min(hx1, hx2) + step_conn
                    if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                        if not bool(rm[mid_y, cx2]):
                            return (Tool.ROAD, cx2, mid_y)
                if abs(hx1 - hx2) <= 3:
                    mid_x = (hx1 + hx2) // 2
                    step_conn = step % max(abs(hy2-hy1), 1)
                    cy2 = min(hy1, hy2) + step_conn
                    if ib(mid_x, cy2) and bool(em[cy2, mid_x]) and not bool(pm[cy2, mid_x]):
                        if not bool(rm[cy2, mid_x]):
                            return (Tool.ROAD, mid_x, cy2)

    # === PHASE 5: ZONE PLACEMENT ===
    # CHANGE: different ratio target: 50% RES, 25% COM, 25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4) + np.abs(cys - hy4)
            best_dist = np.minimum(best_dist, d)

        # CHANGE: stronger clustering bias toward existing zones
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # More weight on zone proximity (0.3 hood + 0.7 zone cluster)
                score = best_dist * 0.3 + zone_prox * 0.7
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 7: CIVIC SERVICES ===
    if pop > 30:
        fire_grid = [(fx, fy) for fy in range(10, 95, 15)
                     for fx in range(10, 115, 15)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(14, 92, 18)
                       for px2 in range(14, 112, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (25, 20), (60, 15), (95, 20),
            (25, 80), (60, 85), (95, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power - CHANGE: lower threshold, more locations
    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 30), (60, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 93)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 8: WIRE CONNECTIONS between hoods ===
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hx1-hx2) + abs(hy1-hy2) > 35: continue
            if abs(hy1 - hy2) <= 3:
                mid_y = (hy1 + hy2) // 2
                for cx3 in range(min(hx1,hx2)+1, max(hx1,hx2)):
                    if ib(cx3, mid_y) and bool(em[mid_y, cx3]) and not bool(pm[mid_y, cx3]):
                        if not bool(wm[mid_y, cx3]):
                            return (Tool.WIRE, cx3, mid_y)
            if abs(hx1 - hx2) <= 3:
                mid_x = (hx1 + hx2) // 2
                for cy3 in range(min(hy1,hy2)+1, max(hy1,hy2)):
                    if ib(mid_x, cy3) and bool(em[cy3, mid_x]) and not bool(pm[cy3, mid_x]):
                        if not bool(wm[cy3, mid_x]):
                            return (Tool.WIRE, mid_x, cy3)

    # === FALLBACK: extend wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    # === UPGRADE: nuclear for dense mature city ===
    if pop > 1000 and step % 3 == 0 and funds > 5000:
        nuc_spots = [(30, 30), (90, 30), (30, 70), (90, 70),
                     (60, 50), (15, 15), (105, 15), (15, 85), (105, 85)]
        for nx6, ny6 in nuc_spots:
            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                return (Tool.NUCLEARPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + initial wires + roads for quick start."""
    actions = []
    # Two main power plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire horizontally from each plant
    for px, py in plants:
        for dx in range(-10, 11):
            if dx == 0: continue
            wx = px + dx
            if 0 <= wx < 120:
                actions.append((Tool.WIRE, wx, py))
        # Wire vertically
        for dy in range(-8, 9):
            if dy == 0: continue
            wy = py + dy
            if 0 <= wy < 100:
                actions.append((Tool.WIRE, px, wy))
    # Roads parallel to wire spines
    for px, py in plants:
        for dx in range(-10, 11):
            wx = px + dx
            if 2 <= wx < 118:
                actions.append((Tool.ROAD, wx, py+2))
                actions.append((Tool.ROAD, wx, py-2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.astype(bool).copy()
        m = mask.astype(bool)
        for d in range(1, r+1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone tool selection: 50% res, 25% com, 25% ind
    def pick_tool():
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 3)

    # --- Phase counter in state for cycling actions ---
    if 'phase' not in state:
        state['phase'] = 0
    phase = state['phase']

    # Check if any zone exists
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Count powered zones
    powered = obs.powered_zones

    # --- STEP 1: Ensure we have enough power plants ---
    # Add more plants as population grows
    desired_plants = 2
    if pop > 500: desired_plants = 3
    if pop > 1500: desired_plants = 5
    if pop > 3000: desired_plants = 7
    if pop > 5000: desired_plants = 9

    plant_ys, plant_xs = np.where(pm)
    current_plants = len(plant_xs)

    if current_plants < desired_plants:
        # Place a new plant in an uncrowded area far from existing plants
        plant_targets = [
            (40, 50), (80, 50), (60, 25), (60, 75),
            (20, 25), (100, 25), (20, 75), (100, 75),
            (20, 50), (100, 50), (60, 10), (60, 88),
        ]
        for tx, ty in plant_targets:
            if ib(tx, ty) and bool(em[ty, tx]):
                # Check not too close to existing plants
                if current_plants == 0:
                    return (Tool.COALPOWER, tx, ty)
                dists = np.sqrt((plant_xs - tx)**2 + (plant_ys - ty)**2)
                if np.min(dists) > 15:
                    return (Tool.COALPOWER, tx, ty)

    # --- STEP 2: Extend wires from existing power sources ---
    # Find cells adjacent to existing wire/plant that are empty and not yet wired
    power_src = wm | pm
    power_ys, power_xs = np.where(power_src)

    if step % 4 in (0, 1) and len(power_xs) > 0:
        # Find nearest un-powered zone or road endpoint to wire toward
        # Priority: extend wires toward areas with roads but no power
        road_no_power = rm & ~near_power
        rny, rnx = np.where(road_no_power)
        if len(rnx) > 0:
            # Pick closest road-no-power to nearest wire
            # Sample subset for speed
            sample_n = min(len(rnx), 50)
            idxs = np.linspace(0, len(rnx)-1, sample_n, dtype=int)
            best_wdist = 1e9
            best_target = None
            for i in idxs:
                tx, ty = int(rnx[i]), int(rny[i])
                dists = np.abs(power_xs - tx) + np.abs(power_ys - ty)
                d = np.min(dists)
                if d < best_wdist:
                    best_wdist = d
                    wi = np.argmin(dists)
                    best_target = (tx, ty, int(power_xs[wi]), int(power_ys[wi]))

            if best_target:
                tx, ty, wx, wy = best_target
                # Step toward target
                dx = 0 if tx == wx else (1 if tx > wx else -1)
                dy = 0 if ty == wy else (1 if ty > wy else -1)
                # Try x-step first, then y-step
                for nx2, ny2 in [(wx+dx, wy), (wx, wy+dy), (wx+dx, wy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

        # Extend wire outward from existing wire in sparse directions
        # Pick a random wire tile and extend outward
        sk = (step * 17 + pop * 3) % max(len(power_xs), 1)
        for off in range(min(len(power_xs), 100)):
            k = (sk + off * 7) % len(power_xs)
            wx2, wy2 = int(power_xs[k]), int(power_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = wx2+dx2, wy2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    # Check this direction extends coverage
                    if not bool(near_power[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- STEP 3: Extend roads into powered areas ---
    if step % 4 == 2:
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            sk = (step * 13 + pop * 5) % len(road_xs2)
            for off in range(min(len(road_xs2), 200)):
                k = (sk + off * 11) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        # Prefer extending into powered area
                        if bool(near_power[ny2, nx2]):
                            return (Tool.ROAD, nx2, ny2)

        # Also: add roads near wires that lack road coverage
        wire_no_road = wm & ~near_road
        wny, wnx = np.where(wire_no_road)
        if len(wnx) > 0:
            sk2 = (step * 7 + pop * 11) % len(wnx)
            for off in range(min(len(wnx), 50)):
                k = (sk2 + off * 3) % len(wnx)
                wx3, wy3 = int(wnx[k]), int(wny[k])
                for dx2, dy2 in [(0,2),(0,-2),(2,0),(-2,0)]:
                    nx2, ny2 = wx3+dx2, wy3+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- STEP 4: Civic buildings (reactive to pop) ---
    if pop > 60:
        fire_candidates = [(x, y) for y in range(8, 100, 18) for x in range(8, 120, 22)]
        for sx, sy in fire_candidates:
            if ib(sx, sy) and bool(em[sy, sx]):
                near_zone = dilate(zone_tiles, 10)
                if bool(near_zone[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_candidates = [(x, y) for y in range(12, 100, 22) for x in range(12, 120, 26)]
        for sx, sy in police_candidates:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        for sx, sy in [(25,25),(95,25),(25,75),(95,75),(60,50),(60,15),(60,85)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        for nx2, ny2 in [(10,50),(110,50),(60,10),(60,88),(10,10),(110,10),(10,88),(110,88)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for sx, sy in [(10,88),(110,88),(10,10),(110,10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for sx, sy in [(50,10),(70,10),(50,88),(70,88)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # --- STEP 5: Zone placement (main action) ---
    # Find candidates: empty, near power, near road, not edge
    cand = em & near_power & near_road
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False
    # Don't place on plant tiles
    cand &= ~pm

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        tool = pick_tool()
        # Sort by distance to nearest road (prefer closer to road for growth)
        road_ys3, road_xs3 = np.where(rm)

        if len(road_xs3) > 0:
            # Score each candidate by road proximity
            # Vectorized: min dist to any road tile
            best_score = np.full(len(cxs), 9999.0)
            # Sample roads for speed
            nr = min(len(road_xs3), 200)
            ridx = np.linspace(0, len(road_xs3)-1, nr, dtype=int)
            for ri in ridx:
                rx3, ry3 = int(road_xs3[ri]), int(road_ys3[ri])
                d = np.abs(cxs - rx3).astype(float) + np.abs(cys - ry3).astype(float)
                best_score = np.minimum(best_score, d)

            order = np.argsort(best_score)
            # Slight randomization to avoid always picking same cell
            offset = (step * 7 + pop * 3) % max(1, min(20, len(order)))
            checked = 0
            for i in range(len(order)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)
                checked += 1
                if checked > 300:
                    break
        else:
            # No roads yet, place first zone near a wire
            for i in range(min(len(cxs), 100)):
                k = (step * 11 + i) % len(cxs)
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

    # --- STEP 6: Wire extension fallback toward empty powered-adjacent spots ---
    if len(power_xs) > 0:
        sk3 = (step * 19) % max(len(power_xs), 1)
        for off in range(min(len(power_xs), 150)):
            k = (sk3 + off * 5) % len(power_xs)
            wx4, wy4 = int(power_xs[k]), int(power_ys[k])
            for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = wx4+dx2, wy4+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- STEP 7: Parks for land value ---
    if pop > 80 and step % 7 == 0:
        park_cand = em & near_road & near_power
        pys2, pxs2 = np.where(park_cand)
        if len(pxs2) > 0:
            idx = (step * 31 + pop * 13) % len(pxs2)
            return (Tool.PARK, int(pxs2[idx]), int(pys2[idx]))

    # Update phase
    state['phase'] = (phase + 1) % 12
    return None

# Strategy: Compact star-shaped neighborhoods with dedicated power rings,
# horizontal road grid, better zone ratios (50%R/25%C/25%I),
# and reactive civic placement based on actual population thresholds.

def init(obs, state):
    """Bootstrap: two coal plants + wire connections + seed roads."""
    actions = []
    # Plant 1: center-left
    cx1, cy1 = 35, 50
    actions.append((Tool.COALPOWER, cx1, cy1))
    # Plant 2: center-right
    cx2, cy2 = 85, 50
    actions.append((Tool.COALPOWER, cx2, cy2))
    # Wire horizontal spine connecting both plants
    for x in range(36, 85):
        actions.append((Tool.WIRE, x, cy1))
    # Wire vertical arms from each plant
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx1, cy1 + dy))
            actions.append((Tool.WIRE, cx2, cy2 + dy))
    # Seed roads flanking plant 1
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx1 - 2, cy1 + dy))
        actions.append((Tool.ROAD, cx1 + 2, cy1 + dy))
    # Seed roads flanking plant 2
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx2 - 2, cy2 + dy))
        actions.append((Tool.ROAD, cx2 + 2, cy2 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- NEIGHBORHOOD DEFINITIONS ----
    # 8 cols x 5 rows = 40 neighborhoods, denser layout
    nh_cols = [15, 32, 49, 62, 75, 88, 101, 114]
    nh_rows = [15, 30, 50, 70, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock
    def num_active():
        if pop < 30:    return 1
        if pop < 100:   return 2
        if pop < 250:   return 4
        if pop < 500:   return 7
        if pop < 1000:  return 12
        if pop < 2000:  return 20
        if pop < 4000:  return 28
        if pop < 6000:  return 36
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (cross pattern at each hood center) ----
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx % len(active_hoods)]

    # Vertical spine
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for ady in [-1, 1]:
            ay = wy + ady
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adx in [-1, 1]:
            ax = wx + adx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRES BETWEEN NEIGHBORING HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and 0 < hx2 - hx1 <= 22:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 0 < hy2 - hy1 <= 22:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS — horizontal grid lines at fixed row offsets ----
    # Roads at hy-2 and hy+2 (wider flanking to fit more zones between them)
    road_offsets = [-2, 2, -5, 5]
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods) // 3 + 1, 1) != 0:
            continue
        for ro in road_offsets:
            ry = hy + ro
            if not ib(hx, ry): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry): continue
                if not bool(em[ry, rcx]) or bool(pm[ry, rcx]): continue
                # Only build road if near power
                has_near_wire = False
                for dy_check in range(-7, 8):
                    cy_check = ry + dy_check
                    if ib(hx, cy_check) and (bool(wm[cy_check, hx]) or bool(pm[cy_check, hx])):
                        has_near_wire = True
                        break
                if has_near_wire:
                    return (Tool.ROAD, rcx, ry)

        # Also roads at hx-2 and hx+2 (vertical flanking)
        for co in [-2, 2]:
            rx = hx + co
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                rcy = hy + dy
                if not ib(rx, rcy): continue
                if not bool(em[rcy, rx]) or bool(pm[rcy, rx]): continue
                has_near_wire = False
                for dx_check in range(-7, 8):
                    cx_check = rx + dx_check
                    if ib(cx_check, hy) and (bool(wm[hy, cx_check]) or bool(pm[hy, cx_check])):
                        has_near_wire = True
                        break
                if has_near_wire:
                    return (Tool.ROAD, rx, rcy)

    # ---- PHASE 5: ZONE PLACEMENT with 50/25/25 R/C/I ratio ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 50% RES, 25% COM, 25% IND
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.23:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor road coverage mask (within 2 tiles — tighter for density)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 16) for fy in range(10, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 20) for py2 in range(14, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [
            (25, 25), (60, 25), (95, 25),
            (25, 50), (60, 50), (95, 50),
            (25, 75), (60, 75), (95, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(6, 85), (113, 85), (6, 15), (113, 15), (60, 93), (60, 6)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(40, 6), (80, 6), (40, 93), (80, 93), (6, 40), (6, 60), (113, 40), (113, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop cities ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [
            (60, 50), (25, 25), (95, 25), (25, 75), (95, 75),
            (8, 50), (112, 50), (60, 8), (60, 92),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value in dense areas ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire and road spines to seed growth."""
    actions = []
    # Two central power plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-8, 9):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire (above and below)
        for dx in range(-8, 9):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
    # Connect the two plants with horizontal wire at y=50
    for x in range(40, 81):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dilate helper
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # --- Active anchors scale with population ---
    all_anchors = []
    for ax in [20, 40, 60, 80, 100]:
        for ay in [20, 35, 50, 65, 80]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 6
        if pop < 500:  return 9
        if pop < 800:  return 12
        if pop < 1200: return 16
        if pop < 2000: return 20
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # --- PHASE 1: Ensure coal plant near each active anchor ---
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            # Find empty spot near anchor
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Wire expansion - extend wire from existing wire/plant toward anchors ---
    wire_half = min(22, 7 + pop // 10)
    vert_half = min(16, 5 + pop // 15)

    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # --- Connect anchors in same column via wire ---
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy in range(y1a + 1, y2a):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = ((ib(col_x, cy - 1) and (bool(wm[cy - 1, col_x]) or bool(pm[cy - 1, col_x]))) or
                           (ib(col_x, cy + 1) and (bool(wm[cy + 1, col_x]) or bool(pm[cy + 1, col_x]))))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    # Connect anchors in same row via wire
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx in range(x1a + 1, x2a):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = ((ib(cx - 1, row_y) and (bool(wm[row_y, cx - 1]) or bool(pm[row_y, cx - 1]))) or
                           (ib(cx + 1, row_y) and (bool(wm[row_y, cx + 1]) or bool(pm[row_y, cx + 1]))))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # --- PHASE 3: Road building flanking wire spines ---
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-2, 2]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx + ddx, road_y) and bool(rm[road_y, cx + ddx]) for ddx in [-1, 1])
                    adj_wire = ((ib(cx, road_y - 1) and bool(wm[road_y - 1, cx])) or
                                (ib(cx, road_y + 1) and bool(wm[road_y + 1, cx])))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-2, 2]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy + ddy) and bool(rm[cy + ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = ((ib(road_x - 1, cy) and bool(wm[cy, road_x - 1])) or
                                (ib(road_x + 1, cy) and bool(wm[cy, road_x + 1])))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # --- PHASE 4: Zone placement ---
    # Zones need road AND power access
    zone_cand = em & near_road & near_power
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H - 3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W - 3:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cys, cxs = np.where(zone_cand)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 500:
                break

    # --- PHASE 5: Wire toward unpowered zones (reactive) ---
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    if len(uzxs) > 0:
        # Find wire candidates adjacent to existing power
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if dy2 == -1: adj_to_power[:-1, :] |= power_src[1:, :]
            elif dy2 == 1: adj_to_power[1:, :] |= power_src[:-1, :]
            elif dx2 == -1: adj_to_power[:, :-1] |= power_src[:, 1:]
            elif dx2 == 1: adj_to_power[:, 1:] |= power_src[:, :-1]
        wire_cand = em & adj_to_power & ~zone_tiles & ~rm
        wire_cand[0:2, :] = False; wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False; wire_cand[:, WORLD_W - 2:] = False
        wys_c, wxs_c = np.where(wire_cand)
        if len(wxs_c) > 0:
            best_d = 1e9; best_k = 0
            stride = max(1, len(uzxs) // 20)
            for i in range(len(wxs_c)):
                cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx2 - int(uzxs[j])) + abs(cy2 - int(uzys[j])) for j in range(0, len(uzxs), stride))
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # --- PHASE 6: Road extension from existing roads near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: Civic services (reactive to population) ---
    if pop > 40:
        fire_spots = [(sx, sy) for sy in range(12, WORLD_H - 5, 15) for sx in range(12, WORLD_W - 5, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        pol_spots = [(sx, sy) for sy in range(15, WORLD_H - 5, 18) for sx in range(15, WORLD_W - 5, 22)]
        for (sx, sy) in pol_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 500:
        for (sx, sy) in [(20, 5), (60, 5), (100, 5), (20, 93), (60, 93), (100, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuc_spots = [(nx2, ny2) for ny2 in range(10, 90, 25) for nx2 in range(10, 115, 25)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 14), min(WORLD_W, npx + 15)
                y0, y1 = max(0, npy - 14), min(WORLD_H, npy + 15)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        for (apx, apy) in [(55, 7), (65, 7), (55, 92), (65, 92), (7, 45), (112, 45)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        for (spx, spy) in [(7, 50), (112, 50), (60, 4), (60, 95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend wire from any wire toward center ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- Last resort: road near zones ---
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + flanking roads + corner plants."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        if x != 60:
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(1, 99):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    # Roads flanking horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Roads flanking vertical wire
    for y in range(1, 99):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    # Corner plants for coverage
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 20, 80))
    actions.append((Tool.COALPOWER, 100, 80))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.astype(bool).copy()
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(pm[nr, nc]):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Wire grid rows/cols (like Parent B)
    wire_rows = [9, 21, 33, 45, 57, 69, 81, 93]
    wire_cols = [9, 24, 39, 54, 69, 84, 99, 114]

    # Progressive hub activation (like Parent A)
    all_hubs = [
        (60, 50), (30, 50), (90, 50), (60, 25), (60, 75),
        (30, 25), (90, 25), (30, 75), (90, 75),
        (15, 50), (105, 50), (60, 8), (60, 90),
        (15, 25), (105, 25), (15, 75), (105, 75),
        (45, 50), (75, 50), (60, 40), (60, 62),
    ]

    def get_active_hubs():
        if pop < 100:
            return all_hubs[:3]
        elif pop < 300:
            return all_hubs[:5]
        elif pop < 700:
            return all_hubs[:9]
        elif pop < 1500:
            return all_hubs[:13]
        elif pop < 3000:
            return all_hubs[:17]
        else:
            return all_hubs

    active_hubs = get_active_hubs()

    # Plant positions for coverage (from Parent B + hub positions)
    plant_positions = []
    for row in range(4):
        for col in range(4):
            px = 15 + col * 30
            py = 15 + row * 24
            plant_positions.append((px, py))
    for extra in [(5, 50), (115, 50), (60, 5), (60, 95),
                  (30, 50), (90, 50), (60, 25), (60, 75)]:
        plant_positions.append(extra)

    # ---- PHASE 0: Ensure plants exist near positions ----
    for px, py in plant_positions:
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 8

    # ---- PHASE 1: Extend horizontal wire corridors ----
    if phase == 0:
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = int(np.argmin(dists))
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        left = wx > 0 and bool(row_power[wx - 1])
                        right = wx < WORLD_W - 1 and bool(row_power[wx + 1])
                        if (left or right) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # ---- PHASE 2: Extend vertical wire corridors ----
    elif phase == 1:
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = int(np.argmin(dists))
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2 + step_x, wc + step_x, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        up = wy > 0 and bool(col_power[wy - 1])
                        dn = wy < WORLD_H - 1 and bool(col_power[wy + 1])
                        if (up or dn) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: Roads parallel to horizontal wire corridors ----
    elif phase == 2:
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Roads parallel to vertical wire corridors ----
    elif phase == 3:
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # ---- PHASE 5: Wire intersection connectors ----
    elif phase == 4:
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc - 1])) or \
                         (wc < WORLD_W - 1 and bool(wm[wr, wc + 1]))
                col_ok = (wr > 0 and bool(wm[wr - 1, wc])) or \
                         (wr < WORLD_H - 1 and bool(wm[wr + 1, wc]))
                if (row_ok or col_ok) and bool(em[wr, wc]) and not bool(pm[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    # ---- PHASE 6: Radial wire spokes from active hubs ----
    elif phase == 5:
        directions = [(1, 0), (-1, 0), (0, 1), (0, -1)]
        for (hx, hy) in active_hubs:
            if not (bool(pm[hy, hx]) or bool(wm[hy, hx])):
                continue
            for dx, dy in directions:
                for r in range(1, 20):
                    wx, wy = hx + dx * r, hy + dy * r
                    if not ib(wx, wy):
                        break
                    if bool(pm[wy, wx]):
                        break
                    if not bool(wm[wy, wx]) and bool(em[wy, wx]):
                        return (Tool.WIRE, wx, wy)
                    elif bool(wm[wy, wx]):
                        continue
                    else:
                        break

    # ---- PHASE 7: Extend roads toward powered unroaded areas ----
    elif phase == 6:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H - 3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W - 3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: Wire toward unpowered roads ----
    else:  # phase == 7
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to pop) ----
    if pop > 50:
        fire_positions = [
            (15, 9), (45, 9), (75, 9), (105, 9),
            (15, 33), (45, 33), (75, 33), (105, 33),
            (15, 57), (45, 57), (75, 57), (105, 57),
            (15, 81), (45, 81), (75, 81), (105, 81),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_positions = [
            (30, 21), (60, 21), (90, 21),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (30, 69), (60, 69), (90, 69),
            (15, 87), (45, 87), (75, 87), (105, 87),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 33), (90, 33), (30, 69), (90, 69),
            (60, 21), (60, 81), (15, 57), (105, 57),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
            (30, 50), (90, 50), (60, 30), (60, 70),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 5), (60, 94)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (110, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (primary closed-loop) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Avoid wire corridors and hub rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 4)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.5 / (1.0 + abs(x - 60) / 60.0 + abs(y - 50) / 50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- FALLBACK: extend road from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: wire toward unpowered active hub ----
    unpowered_hubs = [(hx, hy) for (hx, hy) in active_hubs if not bool(near_power[hy, hx])]
    if unpowered_hubs:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered_hubs[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)
        # Place new plant near unpowered hub
        for (hx, hy) in unpowered_hubs:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire+road spines in central area."""
    actions = []
    # Two central power plants
    plants = [(40, 45), (80, 45)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-6, 7):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-6, 7):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire spine (above and below)
        for dx in range(-6, 7):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
        # Roads flanking vertical spine (left and right)
        for dy in range(-6, 7):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    # Connect the two plants with wire along y=45
    for cx in range(43, 78):
        actions.append((Tool.WIRE, cx, 45))
    # Road connecting them
    for cx in range(43, 78):
        actions.append((Tool.ROAD, cx, 43))
        actions.append((Tool.ROAD, cx, 47))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Aim for ~50% res, 30% com, 20% ind
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure power plants near active fronts ----
    # Scan for areas with roads but no nearby power plant
    # Use a grid of candidate plant locations
    plant_needed_spots = []
    check_spacing = 25
    for px in range(10, WORLD_W - 10, check_spacing):
        for py in range(10, WORLD_H - 10, check_spacing):
            y0 = max(0, py - 12); y1 = min(WORLD_H, py + 13)
            x0 = max(0, px - 12); x1 = min(WORLD_W, px + 13)
            has_plant = np.any(pm[y0:y1, x0:x1])
            has_road = np.any(rm[y0:y1, x0:x1])
            if not has_plant and has_road:
                plant_needed_spots.append((px, py))

    for (px, py) in plant_needed_spots:
        # Place plant at nearest empty spot
        for r in range(0, 12):
            placed = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if placed:
                break

    # ---- PHASE 2: Extend wire from existing plants/wires ----
    # Find the frontier of the wire network and extend it toward roads
    # Compute wire neighbor mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-1, 2):
        for dx in range(-1, 2):
            if dx == 0 and dy == 0:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Build extended wire neighborhood (5-cell radius)
    nbr_wire_ext = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire_ext[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire_ext[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Build road neighbor mask
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- CLOSED-LOOP WIRE EXTENSION ----
    # Find roads that don't have nearby wire and extend wire toward them
    road_no_wire = rm & ~nbr_wire_ext
    r_ys, r_xs = np.where(road_no_wire)
    if len(r_xs) > 0:
        # Find wire cells adjacent to empty cells that point toward unwired roads
        wire_cells = np.argwhere(wm | pm)
        if len(wire_cells) > 0:
            # Pick a target road cell
            target_idx = (step * 7) % len(r_xs)
            tx, ty = int(r_xs[target_idx]), int(r_ys[target_idx])
            # Find closest wire cell to this target
            dists = np.abs(wire_cells[:, 1] - tx) + np.abs(wire_cells[:, 0] - ty)
            closest_idx = np.argmin(dists)
            wy, wx = int(wire_cells[closest_idx, 0]), int(wire_cells[closest_idx, 1])
            # Step toward target from wire
            step_x = np.sign(tx - wx)
            step_y = np.sign(ty - wy)
            # Try horizontal then vertical
            for (nx, ny) in [(wx + step_x, wy), (wx, wy + step_y), (wx + step_x, wy + step_y)]:
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- CLOSED-LOOP ROAD EXTENSION ----
    # Find wire cells without nearby roads and build roads near them
    wire_no_road = (wm | pm) & ~nbr_road
    w_ys, w_xs = np.where(wire_no_road)
    if len(w_xs) > 0:
        idx = (step * 11) % len(w_xs)
        wx2, wy2 = int(w_xs[idx]), int(w_ys[idx])
        # Try to place road at offset 2 from wire (so zones can sit between)
        for dy2 in [-2, 2, -1, 1]:
            for dx2 in [-2, 2, -1, 1]:
                nx2, ny2 = wx2 + dx2, wy2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Good zone spots: near road AND near wire, and empty
    cand_mask = em & nbr_road & nbr_wire_ext
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize spots near existing zones (denser growth)
        zone_ys2, zone_xs2 = np.where(zone_tiles)
        if len(zone_xs2) > 0:
            # Score each candidate by proximity to existing zones and wire
            best = None
            best_score = 1e9
            step_off = (step * 13) % max(len(cxs), 1)
            for i in range(min(len(cxs), 600)):
                k = (step_off + i) % len(cxs)
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    # Score: min distance to any existing zone
                    dz = float(np.min(np.abs(zone_xs2 - zx) + np.abs(zone_ys2 - zy)))
                    # Also bonus for being near wire
                    score = dz
                    if score < best_score:
                        best_score = score
                        best = (zx, zy)
                if i > 200 and best is not None:
                    break
            if best is not None:
                return (pick_tool(), best[0], best[1])
        else:
            # No zones yet, place first zone near center
            step_off = (step * 13) % max(len(cxs), 1)
            for i in range(min(len(cxs), 400)):
                k = (step_off + i) % len(cxs)
                zx, zy = int(cxs[k]), int(cys[k])
                if zone_clear(zx, zy):
                    return (pick_tool(), zx, zy)

    # ---- EXTEND ROADS from existing roads toward wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 17) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_wire_ext[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 78), (60, 78), (100, 78),
            (7, 10), (110, 10), (7, 90), (110, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 15), (65, 15), (105, 15),
            (15, 55), (65, 55), (105, 55),
            (15, 85), (65, 85), (105, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 8), (65, 8), (105, 8), (25, 88), (65, 88), (105, 88)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5), (60, 94)]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for asp in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2500:
        for sp in [(5, 93), (115, 93), (60, 97)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 100:
        zone_map2 = resm | comm | indm
        zone_ys3, zone_xs3 = np.where(zone_map2)
        if len(zone_xs3) > 0:
            for i in range(min(len(zone_xs3), 40)):
                k = (step * 3 + i * 17) % len(zone_xs3)
                zx2, zy2 = int(zone_xs3[k]), int(zone_ys3[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire cell ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road next to any zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

