def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Phase tracking ---
    if 'phase' not in state:
        state['phase'] = 0
        state['scan_idx'] = 0
        state['wire_extend_count'] = 0

    res_count = int(np.sum(resm)) // 9
    com_count = int(np.sum(comm)) // 9
    ind_count = int(np.sum(indm)) // 9
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Ensure power plant exists ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    px = int(np.mean(plant_xs))
    py = int(np.mean(plant_ys))

    # --- Wire spine: grow it reactively based on current wire extent ---
    wire_col = px + 2
    pop_factor = min(35, obs.city_pop // 10)
    spine_top = max(3, py - 18 - pop_factor)
    spine_bot = min(WORLD_H - 4, py + 18 + pop_factor)

    wire_rows = [r for r in range(WORLD_H)
                 if in_bounds(wire_col, r) and bool(wm[r, wire_col])]

    if not wire_rows:
        # Seed wire adjacent to plant
        for dy in range(-2, 3):
            ny = py + dy
            if in_bounds(wire_col, ny) and not bool(pm[ny, wire_col]):
                return (Tool.WIRE, wire_col, ny)
    else:
        min_wr = min(wire_rows)
        max_wr = max(wire_rows)
        # Extend downward
        if max_wr < spine_bot:
            nr = max_wr + 1
            if in_bounds(wire_col, nr) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)
        # Extend upward
        if min_wr > spine_top:
            nr = min_wr - 1
            if in_bounds(wire_col, nr) and not bool(pm[nr, wire_col]):
                return (Tool.WIRE, wire_col, nr)

    # --- Build road columns flanking wire spine reactively ---
    road_col_l = wire_col - 2
    road_col_r = wire_col + 2

    if wire_rows:
        # Check which road positions are missing and fill them
        for wr in wire_rows:
            if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]) and not bool(pm[wr, road_col_l]):
                return (Tool.ROAD, road_col_l, wr)
            if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]) and not bool(pm[wr, road_col_r]):
                return (Tool.ROAD, road_col_r, wr)

    # --- Second power plant when population grows ---
    if obs.city_pop > 100 or total_zones > 6:
        p2x = px + 22
        p2y = py
        nearby_plant = any(
            in_bounds(p2x + dx, p2y + dy) and bool(pm[p2y + dy, p2x + dx])
            for dy in range(-6, 7) for dx in range(-6, 7)
            if in_bounds(p2x + dx, p2y + dy)
        )
        if not nearby_plant:
            if in_bounds(p2x, p2y) and bool(em[p2y, p2x]):
                return (Tool.COALPOWER, p2x, p2y)
            # Wire bridge to second plant location
            for wc in range(wire_col + 1, p2x):
                if in_bounds(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]):
                    return (Tool.WIRE, wc, py)

    # Third power plant for large cities
    if obs.city_pop > 500:
        p3x = px + 22
        p3y = py + 22
        nearby_plant3 = any(
            in_bounds(p3x + dx, p3y + dy) and bool(pm[p3y + dy, p3x + dx])
            for dy in range(-6, 7) for dx in range(-6, 7)
            if in_bounds(p3x + dx, p3y + dy)
        )
        if not nearby_plant3:
            if in_bounds(p3x, p3y) and bool(em[p3y, p3x]):
                return (Tool.COALPOWER, p3x, p3y)

    # --- Compute neighbor masks reactively ---
    # Proximity to road (within 2 cells)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Proximity to wire or plant (within 5 cells)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Zone placement: reactively find best candidate ---
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: close to wire spine, spread vertically
        dists = (np.abs(cxs - wire_col) * 2 + np.abs(cys - py) // 4)
        order = np.argsort(dists)
        # Use step-based offset for variety but still reactive
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 100:
                break

    # --- Extend roads along wire spine to reach more areas ---
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 25)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx2, ry2 = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Horizontal road cross-streets for better connectivity ---
    if wire_rows and obs.city_pop > 50:
        # Add horizontal cross roads every 6 rows
        for wr in wire_rows[::6]:
            for cx_off in range(-8, 9):
                cx = wire_col + cx_off
                if in_bounds(cx, wr) and bool(em[wr, cx]) and not bool(pm[wr, cx]):
                    return (Tool.ROAD, cx, wr)

    # --- Services ---
    if obs.city_pop > 200:
        for fpos in [(px - 12, py - 12), (px + 12, py - 12), (px - 12, py + 12)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if obs.city_pop > 400:
        for ppos in [(px + 12, py + 12), (px - 6, py + 14)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if obs.city_pop > 800:
        for spos in [(px + 5, py + 20), (px - 5, py - 20)]:
            ssx, ssy = spos
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    # --- Expand wire laterally as fallback ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 15)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

