    # Vertical wire spines
    for wx in [10, 30, 50, 70, 90, 110]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows (above and below)
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
