def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [10, 30, 50, 70, 90, 110]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target mix: 35% industrial, 30% commercial, 35% residential
        if pop < 300:
            if ir < 0.35:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if ir < 0.25:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    phase = step % 10

    # Phase 0: Ensure power plants spread across map
    if phase == 0:
        plant_targets = [(15,20),(50,20),(85,20),(15,50),(50,50),(85,50),(15,80),(50,80),(85,80)]
        for px2, py2 in plant_targets:
            x0, x1 = max(0,px2-15), min(WORLD_W,px2+16)
            y0, y1 = max(0,py2-15), min(WORLD_H,py2+16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(12):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx)==r or abs(dy)==r or r==0:
                                nx2, ny2 = px2+dx, py2+dy
                                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill horizontal wire row gaps
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W-1):
                if not bool(wm[wr,wx]) and not bool(pm[wr,wx]) and not bool(rm[wr,wx]):
                    left = wx>0 and (bool(wm[wr,wx-1]) or bool(pm[wr,wx-1]))
                    right = wx<WORLD_W-1 and (bool(wm[wr,wx+1]) or bool(pm[wr,wx+1]))
                    if (left or right) and bool(em[wr,wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill vertical wire col gaps
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy2 in range(1, WORLD_H-1):
                if not bool(wm[wy2,wc]) and not bool(pm[wy2,wc]) and not bool(rm[wy2,wc]):
                    up = wy2>0 and (bool(wm[wy2-1,wc]) or bool(pm[wy2-1,wc]))
                    dn = wy2<WORLD_H-1 and (bool(wm[wy2+1,wc]) or bool(pm[wy2+1,wc]))
                    if (up or dn) and bool(em[wy2,wc]):
                        return (Tool.WIRE, wc, wy2)

    # Phase 3: Roads flanking wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H-1):
                    continue
                for rx in range(1, WORLD_W-1):
                    if bool(em[ry,rx]) and not bool(pm[ry,rx]):
                        if bool(wm[wr,rx]) or bool(pm[wr,rx]):
                            adj = ((rx>0 and bool(rm[ry,rx-1])) or
                                   (rx<WORLD_W-1 and bool(rm[ry,rx+1])) or
                                   (ry>0 and bool(rm[ry-1,rx])) or
                                   (ry<WORLD_H-1 and bool(rm[ry+1,rx])))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # Phase 4: Roads flanking wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W-1):
                    continue
                for ry in range(1, WORLD_H-1):
                    if bool(em[ry,rcx]) and not bool(pm[ry,rcx]):
                        if bool(wm[ry,wc]) or bool(pm[ry,wc]):
                            adj = ((ry>0 and bool(rm[ry-1,rcx])) or
                                   (ry<WORLD_H-1 and bool(rm[ry+1,rcx])) or
                                   bool(rm[ry,max(0,rcx-1)]) or
                                   bool(rm[ry,min(WORLD_W-1,rcx+1)]))
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # Phase 5: Cross roads between wire rows
    if phase == 5:
        for wi in range(len(wire_rows)-1):
            r1, r2 = wire_rows[wi], wire_rows[wi+1]
            for frac in [0.25, 0.5, 0.75]:
                mid_y = int(r1 + (r2-r1)*frac)
                if not (0 < mid_y < WORLD_H-1):
                    continue
                for rx in range(1, WORLD_W-1):
                    if bool(em[mid_y,rx]) and bool(near_power[mid_y,rx]) and not bool(pm[mid_y,rx]):
                        adj = ((rx>0 and bool(rm[mid_y,rx-1])) or
                               (rx<WORLD_W-1 and bool(rm[mid_y,rx+1])) or
                               (mid_y>0 and bool(rm[mid_y-1,rx])) or
                               (mid_y<WORLD_H-1 and bool(rm[mid_y+1,rx])))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # Phase 6: Wire unpowered zones
    if phase == 6:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx==bwx else (1 if tx>bwx else -1)
                dy = 0 if ty==bwy else (1 if ty>bwy else -1)
                for nx2, ny2 in [(bwx+dx,bwy),(bwx,bwy+dy),(bwx+dx,bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 7: Road to unroaded zones
    if phase == 7:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx==brx else (1 if tx>brx else -1)
                dy = 0 if ty==bry else (1 if ty>bry else -1)
                for nx2, ny2 in [(brx+dx,bry),(brx,bry+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 8: Extend road into powered empty areas
    if phase == 8:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off*7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 9: Extend wire network
    if phase == 9:
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            sk2 = (step*13) % len(wire_xs3)
            for off in range(min(len(wire_xs3),150)):
                k = (sk2+off*5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx3, ny3 = wx2+dx3, wy2+dy3
                    if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- CIVIC SERVICES scaled to population ----
    if pop > 50:
        fire_spots = [
            (5,5),(35,5),(65,5),(95,5),(115,5),
            (5,30),(115,30),(5,50),(115,50),
            (5,70),(115,70),(5,95),(35,95),(65,95),(95,95),(115,95),
            (35,30),(65,30),(95,30),(35,70),(65,70),(95,70),
        ]
        for sx, sy in fire_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (20,10),(50,10),(80,10),(110,10),
            (20,30),(50,30),(80,30),(110,30),
            (20,50),(50,50),(80,50),(110,50),
            (20,70),(50,70),(80,70),(110,70),
            (20,90),(50,90),(80,90),(110,90),
        ]
        for sx, sy in police_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25,15),(75,15),(25,50),(75,50),(25,85),(75,85),(50,30),(100,30),(50,70),(100,70)]
        for sx, sy in stadium_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2,ny2) and bool(em[ny2,nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5,95),(115,95),(5,5),(115,5),(60,95),(60,5)]
        for sx, sy in seaports:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45)]
        for sx, sy in airports:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value near roads and power
    if pop > 100 and step % 5 == 4:
        park_cands = em & near_road & near_power
        park_cands[0:3,:] = False
        park_cands[WORLD_H-3:,:] = False
        park_cands[:,0:3] = False
        park_cands[:,WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step*31 + pop*3) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2,px2]):
                return (Tool.PARK, px2, py2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3,:] = False
    cand_mask[WORLD_H-3:,:] = False
    cand_mask[:,0:3] = False
    cand_mask[:,WORLD_W-3:] = False
    # Protect wire/road infrastructure corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0,wr-2):min(WORLD_H,wr+3),:] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:,max(0,wc-2):min(WORLD_W,wc+3)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Dense grid of expansion centers covering the whole map
        if pop < 300:
            active_centers = []
            for row in range(5):
                for col in range(6):
                    cx = 15 + col*18
                    cy = 15 + row*17
                    active_centers.append((cx,cy))
        elif pop < 800:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 8 + col*13
                    cy = 8 + row*13
                    active_centers.append((cx,cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col*10
                    cy = 5 + row*9
                    active_centers.append((cx,cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx,hy) in active_centers:
            d = np.abs(cxs-hx).astype(float) + np.abs(cys-hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step*7 + pop*3) % max(len(order),1)

        for i in range(min(len(order),800)):
            k = order[(offset+i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step*11) % len(road_xs)
        for off in range(min(len(road_xs),200)):
            k = (sk+off*7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step*13) % len(wire_xs3)
        for off in range(min(len(wire_xs3),150)):
            k = (sk2+off*5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from plant
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along vertical spine
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 3, cy + dy))
        actions.append((Tool.ROAD, cx + 3, cy + dy))
    # Flanking roads along horizontal spine
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, cx + dx, cy - 3))
        actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID ----
    # 7 cols x 6 rows = 42 hoods spread across map
    nh_cols = [12, 30, 48, 63, 78, 96, 108]
    nh_rows = [12, 28, 44, 58, 72, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 7
        if pop < 600:  return 12
        if pop < 1000: return 18
        if pop < 2000: return 26
        if pop < 4000: return 34
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Each active hood should have a plant within ~10 tiles
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and funds > 500:
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from plants ----
    # Grow wires outward from each plant toward active hoods
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        # For each hood, check if it has wire coverage; if not, extend wire
        for (hx, hy) in active_hoods:
            # Check wire coverage near hood
            wx0, wx1 = max(0, hx - 3), min(WORLD_W, hx + 4)
            wy0, wy1 = max(0, hy - 3), min(WORLD_H, hy + 4)
            has_wire = bool(np.any(wm[wy0:wy1, wx0:wx1])) or bool(np.any(pm[wy0:wy1, wx0:wx1]))
            if has_wire:
                continue
            # Find nearest wire/plant and extend toward hood
            # Look along spine columns/rows
            # Vertical spine at hx: find wire extent
            col_tiles = [r for r in range(WORLD_H) if ib(hx, r) and (bool(wm[r, hx]) or bool(pm[r, hx]))]
            if col_tiles:
                # Extend toward hood row
                if hy > max(col_tiles):
                    nr = max(col_tiles) + 1
                    if ib(hx, nr) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)
                elif hy < min(col_tiles):
                    nr = min(col_tiles) - 1
                    if ib(hx, nr) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)
            # Horizontal spine at hy
            row_tiles = [c for c in range(WORLD_W) if ib(c, hy) and (bool(wm[hy, c]) or bool(pm[hy, c]))]
            if row_tiles:
                if hx > max(row_tiles):
                    nc = max(row_tiles) + 1
                    if ib(nc, hy) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)
                elif hx < min(row_tiles):
                    nc = min(row_tiles) - 1
                    if ib(nc, hy) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: EXTEND WIRE SPINES from existing wires ----
    spine_range = 14
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical spine at hx for this hood
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine at hy for this hood
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 4: CONNECT ADJACENT HOODS WITH WIRES ----
    for i_h, (hx1, hy1) in enumerate(active_hoods):
        for j_h, (hx2, hy2) in enumerate(active_hoods):
            if j_h <= i_h: continue
            # Horizontal neighbors
            if hy1 == hy2 and 0 < hx2 - hx1 <= 22:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical neighbors
            if hx1 == hx2 and 0 < hy2 - hy1 <= 22:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 5: ROADS flanking wire spines ----
    # Roads at hx±3 (flanking vertical spine) and hy±3 (flanking horizontal)
    road_hood_idx = (step + len(active_hoods) // 2) % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_hood_idx]

    for rx in [rhx - 3, rhx + 3]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                # Only place road if there's wire on the spine column
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)

    for ry2 in [rhy - 3, rhy + 3]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28: return Tool.INDUSTRIAL
        if cr < 0.28: return Tool.COMMERCIAL
        if rr < 0.44: return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (within 4 tiles of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx_a, hy_a) in active_hoods:
            d = np.abs(cxs - hx_a) + np.abs(cys - hy_a)
            best_dist = np.minimum(best_dist, d)

        # Zone clustering bonus
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(14, WORLD_W - 4, 20)
                      for fy in range(14, WORLD_H - 4, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W - 4, 24)
                        for py2 in range(20, WORLD_H - 4, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(30, 25), (60, 15), (90, 25),
                    (20, 50), (100, 50),
                    (30, 75), (60, 85), (90, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 300 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 1000 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (40, 25), (80, 25), (40, 75), (80, 75),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 700:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1500:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        sk = (step * 11) % len(pxs2)
        for offset in range(min(len(pxs2), 60)):
            k = (sk + offset * 7) % len(pxs2)
            px2, py2 = int(pxs2[k]), int(pys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire + road spines."""
    actions = []
    for cx, cy in [(20, 50), (60, 50), (100, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 2, cy + dy))
            actions.append((Tool.ROAD, cx + 2, cy + dy))
    # Horizontal wire connecting plants
    for wx in range(22, 58):
        actions.append((Tool.WIRE, wx, 50))
    for wx in range(62, 98):
        actions.append((Tool.WIRE, wx, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # --- Neighborhood grid: denser than parent ---
    nh_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 4
        if pop < 150:  return 8
        if pop < 300:  return 14
        if pop < 600:  return 20
        if pop < 1200: return 30
        if pop < 2500: return 45
        if pop < 5000: return 60
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === PHASE 1: ENSURE POWER PLANTS near active hoods ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE PROPAGATION — connect power to active hoods ===
    # Build power reachability: tiles adjacent to wire or plant
    # Strategy: extend wire toward hoods that lack nearby power
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Find hoods needing wire extension
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if not bool(nbr_power[hy, hx]):
            # Find nearest powered tile and walk toward hood
            best_dist = 9999
            best_wx, best_wy = -1, -1
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - hx) + np.abs(wire_ys - hy)
                ki = int(np.argmin(dists))
                best_wx, best_wy = int(wire_xs[ki]), int(wire_ys[ki])
                best_dist = int(dists[ki])
            if best_wx >= 0 and best_dist > 1:
                # Step from best_wx,best_wy toward hx,hy
                dx = hx - best_wx; dy = hy - best_wy
                if abs(dx) >= abs(dy):
                    nx = best_wx + (1 if dx > 0 else -1)
                    ny = best_wy
                else:
                    nx = best_wx
                    ny = best_wy + (1 if dy > 0 else -1)
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # === PHASE 3: VERTICAL+HORIZONTAL WIRE SPINES at active hoods ===
    spine_range = 12
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Only process subset each step for variety
        if (step + idx_h) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 3 + 2):
            continue

        # Vertical spine
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True; break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True; break
            if adj:
                return (Tool.WIRE, hx, wy)
            # bootstrap: start near plant
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal spine
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True; break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True; break
            if adj:
                return (Tool.WIRE, wx, hy)

    # === PHASE 4: ROADS — flanking wire spines + extending existing roads ===
    # Build road neighbor mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 2) % max(len(active_hoods), 1) >= max(1, len(active_hoods) // 3 + 2):
            continue

        # Roads flanking vertical wire spine at hx
        for rx in [hx - 2, hx + 2]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Roads flanking horizontal wire spine at hy
        for ry2 in [hy - 2, hy + 2]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # Extend roads into powered empty areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 150)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 5: ZONE PLACEMENT — reactive to power+road coverage ===
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]): return False
        return True

    # Power coverage within 6 tiles (tighter than parent's 7)
    nbr_power6 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power6[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power6[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone tiles: empty, near road (within 3), near power (within 6)
    cand_mask = em & nbr_road & nbr_power6
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: proximity to active hoods + proximity to existing zones (clustering)
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Also reward being close to existing zones for clustering effect
        zone_bonus = np.zeros(len(cxs), dtype=float)
        zone_ys2, zone_xs2 = np.where(zone_tiles)
        if len(zone_xs2) > 0:
            # Approximate: count zones within 8 tiles using vectorized ops
            for i in range(min(len(zone_xs2), 200)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                dz = np.abs(cxs - zx2).astype(float) + np.abs(cys - zy2).astype(float)
                zone_bonus += np.maximum(0, 8.0 - dz)

        score = best_dist - zone_bonus * 0.5
        order = np.argsort(score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # === PHASE 6: CIVIC SERVICES ===
    if pop > 80:
        fire_spots = [
            (8, 10), (30, 10), (52, 10), (74, 10), (96, 10), (115, 10),
            (8, 30), (30, 30), (52, 30), (74, 30), (96, 30), (115, 30),
            (8, 50), (30, 50), (52, 50), (74, 50), (96, 50), (115, 50),
            (8, 70), (30, 70), (52, 70), (74, 70), (96, 70), (115, 70),
            (8, 90), (30, 90), (52, 90), (74, 90), (96, 90), (115, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (18, 20), (48, 20), (78, 20), (108, 20),
            (18, 45), (48, 45), (78, 45), (108, 45),
            (18, 65), (48, 65), (78, 65), (108, 65),
            (18, 85), (48, 85), (78, 85), (108, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (33, 33), (83, 33), (33, 63), (83, 63),
            (58, 15), (58, 85), (8, 50), (112, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        seaports = [(8, 90), (112, 90), (8, 8), (112, 8), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(50, 6), (70, 6), (50, 93), (70, 93), (5, 48), (113, 48)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # === PHASE 7: PARKS near dense zone clusters ===
    if pop > 150 and step % 2 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: plant for uncovered hood ===
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # === LAST RESORT: road near existing zone ===
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Two-neighborhood city with grid roads, balanced R/C/I zones
# Key changes from parent:
# 1. Two separate clusters (left ~x=35, right ~x=85) with their own power
# 2. Regular grid roads (every 4 rows, every 4 cols) for denser coverage
# 3. Wire backbone connecting both clusters
# 4. More aggressive zone placement closer to roads
# 5. Earlier civic services

def init(obs, state):
    """Bootstrap: coal plant at each cluster center, wire backbone"""
    actions = []
    # Left cluster power
    actions.append((Tool.COALPOWER, 35, 50))
    # Right cluster power
    actions.append((Tool.COALPOWER, 85, 50))
    # Wire backbone connecting them horizontally
    for x in range(36, 85):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines for each cluster
    for y in range(38, 63):
        actions.append((Tool.WIRE, 35, y))
        actions.append((Tool.WIRE, 85, y))
    # Initial roads around left cluster
    for x in range(28, 45):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(46, 55):
        actions.append((Tool.ROAD, 28, y))
        actions.append((Tool.ROAD, 44, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Two cluster centers
    cl = (35, 50)  # left cluster
    cr = (85, 50)  # right cluster

    # Active expansion radius based on population
    if pop < 200:
        max_radius = 18
    elif pop < 800:
        max_radius = 28
    elif pop < 2000:
        max_radius = 40
    else:
        max_radius = 55

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr2 = com_count / t
        rr = res_count / t
        # Want roughly 35% R, 35% C, 30% I
        if pop < 300 and ir < 0.28:
            return Tool.INDUSTRIAL
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr2 < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    plant_count = int(np.sum(pm))

    # Add more power plants as city grows
    if pop > 400 and plant_count < 4:
        for px, py in [(35, 25), (85, 25), (35, 75), (85, 75)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 1500 and plant_count < 6:
        for px, py in [(60, 20), (60, 80), (10, 50), (110, 50)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    if pop > 3000 and plant_count < 8:
        for px, py in [(20, 30), (100, 30), (20, 70), (100, 70)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    # Build neighbor maps
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Distance map: min dist to either cluster center
    ys_arr = np.arange(WORLD_H).reshape(-1, 1)
    xs_arr = np.arange(WORLD_W).reshape(1, -1)
    dist_l = np.abs(ys_arr - cl[1]) + np.abs(xs_arr - cl[0])
    dist_r = np.abs(ys_arr - cr[1]) + np.abs(xs_arr - cr[0])
    dist_min = np.minimum(dist_l, dist_r)

    # === PHASE: Wire network ===
    # Build wire grid to power zones in both clusters
    if step % 5 == 0:
        # Wire along horizontal backbone and vertical spines
        wire_lines = [
            [(x, 50) for x in range(2, WORLD_W - 2)],  # main horizontal
            [(35, y) for y in range(2, WORLD_H - 2)],   # left vertical
            [(85, y) for y in range(2, WORLD_H - 2)],   # right vertical
            [(x, 25) for x in range(2, WORLD_W - 2)],   # upper horizontal
            [(x, 75) for x in range(2, WORLD_W - 2)],   # lower horizontal
            [(60, y) for y in range(2, WORLD_H - 2)],   # middle vertical
        ]
        for line in wire_lines:
            for (wx, wy) in line:
                if not ib(wx, wy):
                    continue
                if bool(pm[wy, wx]) or bool(wm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    dist = int(dist_min[wy, wx])
                    if dist <= max_radius + 15:
                        # Only place wire if adjacent to existing wire/plant
                        adj_power = False
                        for adx, ady in [(-1,0),(1,0),(0,-1),(0,1)]:
                            ax, ay = wx+adx, wy+ady
                            if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                                adj_power = True
                        if adj_power:
                            return (Tool.WIRE, wx, wy)

    # === PHASE: Road grid ===
    # Grid roads every 4 rows/cols in both clusters
    if step % 5 == 1:
        # Horizontal roads every 4 rows
        road_ys = list(range(26, 75, 4))
        for ry in road_ys:
            if int(dist_min[ry, 35]) > max_radius + 5 and int(dist_min[ry, 85]) > max_radius + 5:
                continue
            for rx in range(10, WORLD_W - 10):
                d = int(dist_min[ry, rx])
                if d > max_radius:
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Connect to existing road
                    adj = any(ib(rx+adx, ry) and bool(rm[ry, rx+adx]) for adx in [-1,1])
                    if adj or rx in [35, 85]:
                        return (Tool.ROAD, rx, ry)

    elif step % 5 == 2:
        # Vertical roads every 4 cols
        road_xs = list(range(15, 106, 4))
        for rxc in road_xs:
            if int(dist_min[50, rxc]) > max_radius + 5:
                continue
            for ry in range(20, WORLD_H - 20):
                d = int(dist_min[ry, rxc])
                if d > max_radius:
                    continue
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    adj = any(ib(rxc, ry+ady) and bool(rm[ry+ady, rxc]) for ady in [-1,1])
                    if adj or ry == 50:
                        return (Tool.ROAD, rxc, ry)

    # === PHASE: Zone placement ===
    cand_mask = em & nbr_road & nbr_power & (dist_min <= max_radius)
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        dists = dist_min[cys_arr, cxs_arr]
        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === CIVIC SERVICES ===
    if pop > 100:
        fire_spots = [
            (25, 40), (45, 40), (25, 60), (45, 60),
            (75, 40), (95, 40), (75, 60), (95, 60),
            (35, 30), (85, 30), (35, 70), (85, 70),
            (60, 40), (60, 60),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (30, 45), (40, 45), (30, 55), (40, 55),
            (80, 45), (90, 45), (80, 55), (90, 55),
            (55, 45), (65, 45), (55, 55), (65, 55),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for (sx, sy) in [(33, 48), (83, 48), (33, 52), (83, 52)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for (sx, sy) in [(10, 90), (110, 90), (10, 10), (110, 10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for (sx, sy) in [(15, 50), (105, 50), (60, 10), (60, 90)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 200 and step % 9 == 0:
        park_ys2, park_xs2 = np.where(em & nbr_road & nbr_power & (dist_min <= max_radius))
        if len(park_xs2) > 0:
            idx = (step * 19) % len(park_xs2)
            return (Tool.PARK, int(park_xs2[idx]), int(park_ys2[idx]))

    # === FALLBACK: Extend roads from existing ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 13) % len(road_xs2)
        for off in range(min(len(road_xs2), 100)):
            k = (sk + off * 9) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            if int(dist_min[ry2, rx2]) > max_radius + 3:
                continue
            for dx2, dy2 in [(0,1),(1,0),(0,-1),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Extend wire
    if step % 5 == 3:
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            sk2 = (step * 17) % len(wire_xs2)
            for off in range(min(len(wire_xs2), 80)):
                k = (sk2 + off * 7) % len(wire_xs2)
                wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
                for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx3, ny3 = wx2+dx3, wy2+dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        if int(dist_min[ny3, nx3]) <= max_radius + 15:
                            return (Tool.WIRE, nx3, ny3)

    # Last resort: ensure power near both cluster centers
    for cen in [cl, cr]:
        cx2, cy2 = cen
        if not bool(nbr_power[cy2, cx2]):
            for r in range(1, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx2+dx, cy2+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + cross wire grid + road grid"""
    actions = []
    # Two coal plants near center
    for px, py in [(30, 30), (90, 30), (30, 70), (90, 70)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [30, 50, 70]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows (above and below)
    for wy in [30, 50, 70]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
            actions.append((Tool.ROAD, x, wy + 2))
    # Roads flanking wire cols
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, wx - 2, y))
            actions.append((Tool.ROAD, wx + 2, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    wire_rows = [30, 50, 70]
    wire_cols = [30, 60, 90]

    # Zone mix: aim for 30% ind, 30% com, 40% res
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.32:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.38:
                return Tool.COMMERCIAL
            if rr < 0.42:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # 1. Fix unpowered zones - wire them
    if step % 6 == 0:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 50)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # 2. Fix zones without road access
    if step % 6 == 1:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 3. Repair missing wire on key rows
    if step % 6 == 2:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]) if wx > 0 else False
                    right = bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]) if wx < WORLD_W - 1 else False
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # 4. Repair/extend vertical wire on key cols
    if step % 6 == 3:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = bool(wm[wy2 - 1, wc]) or bool(pm[wy2 - 1, wc]) if wy2 > 0 else False
                    dn = bool(wm[wy2 + 1, wc]) or bool(pm[wy2 + 1, wc]) if wy2 < WORLD_H - 1 else False
                    if up or dn:
                        if bool(em[wy2, wc]):
                            return (Tool.WIRE, wc, wy2)

    # 5. Power plant coverage check - add coal/nuclear as needed
    if step % 6 == 4:
        plant_targets = []
        for py in range(15, WORLD_H - 5, 25):
            for px in range(15, WORLD_W - 5, 30):
                plant_targets.append((px, py))
        for ppx, ppy in plant_targets:
            x0, x1 = max(0, ppx - 15), min(WORLD_W, ppx + 16)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = ppx + dx, ppy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    tool_choice = Tool.NUCLEARPOWER if pop > 500 else Tool.COALPOWER
                                    return (tool_choice, nx2, ny2)

    # 6. Fix roads flanking wire rows (reactive)
    if step % 8 == 5:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx - 1])) or \
                                  (rx < WORLD_W - 1 and bool(rm[ry, rx + 1])) or \
                                  (ry > 0 and bool(rm[ry - 1, rx])) or \
                                  (ry < WORLD_H - 1 and bool(rm[ry + 1, rx]))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # 7. Fix roads flanking wire cols
    if step % 8 == 6:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry - 1, rcx])) or \
                                  (ry < WORLD_H - 1 and bool(rm[ry + 1, rcx])) or \
                                  bool(rm[ry, max(0, rcx - 1)]) or \
                                  bool(rm[ry, min(WORLD_W - 1, rcx + 1)])
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # === CIVIC SERVICES (pop-gated) ===
    if pop > 20:
        fire_spots = [
            (10, 10), (40, 10), (70, 10), (100, 10),
            (10, 40), (100, 40), (10, 60), (100, 60),
            (10, 90), (40, 90), (70, 90), (100, 90),
            (40, 50), (70, 50), (55, 25), (55, 75),
            (25, 50), (85, 50), (55, 45), (55, 55),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 45), (55, 45), (85, 45), (115, 45),
            (25, 65), (55, 65), (85, 65), (115, 65),
            (25, 85), (55, 85), (85, 85), (10, 50),
            (45, 25), (75, 25), (45, 75), (75, 75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (20, 15), (80, 15), (20, 85), (80, 85),
            (50, 50), (10, 50), (110, 50), (50, 10), (50, 90),
            (35, 35), (65, 35), (35, 65), (65, 65),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (15, 20), (105, 20), (15, 80), (105, 80),
            (40, 10), (80, 10), (40, 90), (80, 90),
            (15, 50), (105, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95), (60, 5), (5, 50), (115, 50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 60 and step % 9 == 4:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === ZONE PLACEMENT: dense cluster-based, reactive ===
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False
    # Avoid wire rows/cols themselves (not the flanking roads)
    for wr in wire_rows:
        cand_mask[wr:wr + 1, :] = False
    for wc in wire_cols:
        cand_mask[:, wc:wc + 1] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Dense neighborhood centers between the wires
        # Cells between wire rows/cols form natural blocks
        if pop < 100:
            active_centers = [
                (45, 40), (45, 60), (75, 40), (75, 60),
                (15, 40), (15, 60), (105, 40), (105, 60),
                (45, 15), (75, 15), (45, 85), (75, 85),
            ]
        elif pop < 500:
            active_centers = []
            # Fill blocks between wire rows and cols
            block_xs = [15, 45, 75, 105]
            block_ys = [15, 40, 60, 85]
            for bx in block_xs:
                for by in block_ys:
                    active_centers.append((bx, by))
            # Add mid-row centers
            for bx in [5, 22, 38, 52, 68, 82, 98, 112]:
                for by in [20, 40, 60, 80]:
                    active_centers.append((bx, by))
        else:
            # Full map with fine grid
            active_centers = []
            for row in range(9):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road toward powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Improved closed-loop policy with better reactivity and denser zone placement
# Key changes from parent:
# 1. Simpler anchor system focused on 3 horizontal bands
# 2. Horizontal road spines instead of just vertical wire
# 3. More aggressive zone placement near existing infrastructure
# 4. Better power connectivity checking

def init(obs, state):
    """Bootstrap: primary coal plant + wire spine + roads."""
    actions = []
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine leftward and rightward from plant
    for dx in range(1, 6):
        actions.append((Tool.WIRE, 60 + dx, 50))
        actions.append((Tool.WIRE, 60 - dx, 50))
    # Roads above and below wire spine
    for dx in range(-4, 6):
        actions.append((Tool.ROAD, 60 + dx, 49))
        actions.append((Tool.ROAD, 60 + dx, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Active neighborhood bands based on population
    # Each anchor: (plant_x, plant_y, wire_row, road_row_above, road_row_below)
    all_anchors = [
        # Center band
        (60, 50, 50, 49, 51),
        # Upper band
        (60, 25, 25, 24, 26),
        # Lower band
        (60, 75, 75, 74, 76),
        # Left extensions center
        (30, 50, 50, 49, 51),
        # Right extensions center
        (90, 50, 50, 49, 51),
        # Left extensions upper
        (30, 25, 25, 24, 26),
        # Right extensions upper
        (90, 25, 25, 24, 26),
        # Left extensions lower
        (30, 75, 75, 74, 76),
        # Right extensions lower
        (90, 75, 75, 74, 76),
    ]

    def num_active():
        if pop < 200: return 1
        elif pop < 600: return 3
        elif pop < 1500: return 5
        elif pop < 3000: return 7
        else: return 9

    active_anchors = all_anchors[:num_active()]

    # ---- ENSURE POWER PLANTS ----
    for (px, py, wr, ra, rb) in active_anchors:
        has_plant = any(
            ib(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dx in range(-4, 5) for dy in range(-4, 5)
            if ib(px + dx, py + dy)
        )
        if not has_plant:
            # Place plant at anchor or nearby empty
            for r in range(8):
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- HORIZONTAL WIRE SPINE along anchor rows ----
    for (px, py, wr, ra, rb) in active_anchors:
        # Extend wire horizontally from plant position
        wire_in_row = [c for c in range(WORLD_W) if ib(c, wr) and bool(wm[wr, c])]
        plant_in_region = [
            c for c in range(max(0, px - 10), min(WORLD_W, px + 11))
            if bool(pm[wr, c]) or (wr > 0 and bool(pm[wr - 1, c])) or bool(pm[min(WORLD_H - 1, wr + 1), c])
        ]

        target_left = max(2, px - 20)
        target_right = min(WORLD_W - 3, px + 20)

        if not wire_in_row:
            # Seed wire near plant
            for dx2 in range(-2, 3):
                nx = px + dx2
                if ib(nx, wr) and (bool(em[wr, nx]) or bool(wm[wr, nx])) and not bool(pm[wr, nx]):
                    return (Tool.WIRE, nx, wr)
        else:
            min_wc = min(wire_in_row)
            max_wc = max(wire_in_row)
            if min_wc > target_left:
                nx = min_wc - 1
                if ib(nx, wr) and not bool(pm[wr, nx]):
                    return (Tool.WIRE, nx, wr)
            if max_wc < target_right:
                nx = max_wc + 1
                if ib(nx, wr) and not bool(pm[wr, nx]):
                    return (Tool.WIRE, nx, wr)

    # ---- VERTICAL WIRE CONNECTIONS between anchor rows ----
    for i in range(len(active_anchors) - 1):
        px1, py1, wr1, _, _ = active_anchors[i]
        px2, py2, wr2, _, _ = active_anchors[i + 1]
        if abs(px1 - px2) < 5:  # Same column anchors
            col = px1 + 2  # Wire column
            min_row = min(wr1, wr2)
            max_row = max(wr1, wr2)
            for row in range(min_row, max_row + 1):
                if ib(col, row) and bool(em[row, col]) and not bool(pm[row, col]):
                    return (Tool.WIRE, col, row)

    # ---- ROAD BUILDING along anchor rows ----
    for (px, py, wr, ra, rb) in active_anchors:
        wire_in_row = [c for c in range(WORLD_W) if ib(c, wr) and bool(wm[wr, c])]
        if not wire_in_row:
            continue
        target_left = max(2, min(wire_in_row) - 1)
        target_right = min(WORLD_W - 3, max(wire_in_row) + 1)

        # Build roads above wire row (ra)
        for cx in range(target_left, target_right + 1):
            if ib(cx, ra) and bool(em[ra, cx]) and not bool(pm[ra, cx]):
                return (Tool.ROAD, cx, ra)
        # Build roads below wire row (rb)
        for cx in range(target_left, target_right + 1):
            if ib(cx, rb) and bool(em[rb, cx]) and not bool(pm[rb, cx]):
                return (Tool.ROAD, cx, rb)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.20:
            return Tool.INDUSTRIAL
        if com_count / t < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute neighbor road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute neighbor wire/plant proximity (within 6 tiles)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near anchor wire rows
        best_dist = np.full(len(cxs), 999999, dtype=float)
        for (px, py, wr, ra, rb) in active_anchors:
            d = np.abs(cxs - px) + np.abs(cys - wr) * 2
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 200:
        svc_spots = [
            (55, 50), (65, 50), (55, 25), (65, 25),
            (55, 75), (65, 75), (35, 50), (85, 50),
            (35, 25), (85, 25), (35, 75), (85, 75),
        ]
        for (sx, sy) in svc_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        pstations = [
            (50, 50), (70, 50), (50, 25), (70, 25),
            (50, 75), (70, 75), (25, 50), (95, 50),
        ]
        for (sx, sy) in pstations:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [(60, 38), (60, 62), (30, 38), (90, 38), (30, 62), (90, 62)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire grid + roads."""
    actions = []
    # Two plants: left-center and right-center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally
    for x in range(31, 90):
        if x % 3 == 0:
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, 30, 50 + dy))
            actions.append((Tool.WIRE, 90, 50 + dy))
    # Roads flanking each spine
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, 29, 50 + dy))
        actions.append((Tool.ROAD, 31, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- NEIGHBORHOOD GRID ----
    nh_xs = [15, 30, 45, 60, 75, 90, 105]
    nh_ys = [15, 30, 45, 60, 75, 85]
    all_hoods = [(x, y) for y in nh_ys for x in nh_xs]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 6
        if pop < 600:  return 10
        if pop < 1000: return 14
        if pop < 2000: return 20
        if pop < 4000: return 30
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    # Check if any active hood lacks nearby power
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place coal plant nearby
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- BUILD POWER COVERAGE MAP ----
    # BFS/dilation: which tiles are near wire or plant?
    nbr_power = pm.copy().astype(bool) | wm.copy().astype(bool)
    # Dilate by 3 tiles (zone adjacency)
    for _ in range(3):
        shifted = np.zeros_like(nbr_power)
        shifted[1:, :] |= nbr_power[:-1, :]
        shifted[:-1, :] |= nbr_power[1:, :]
        shifted[:, 1:] |= nbr_power[:, :-1]
        shifted[:, :-1] |= nbr_power[:, 1:]
        nbr_power |= shifted

    # ---- PHASE 2: WIRE EXTENSION — grow wire from existing wire/plant toward unpowered hoods ----
    # For each active hood that's not yet powered, extend wire toward it
    for (hx, hy) in active_hoods:
        if bool(nbr_power[hy, hx]):
            continue
        # Find nearest wire/plant tile and extend wire one step toward hood
        # Search in decreasing radius from hood
        best_src = None
        best_dist = 9999
        wys, wxs = np.where(wm | pm)
        if len(wxs) > 0:
            dists = np.abs(wxs - hx) + np.abs(wys - hy)
            idx = np.argmin(dists)
            best_src = (int(wxs[idx]), int(wys[idx]))
            best_dist = int(dists[idx])

        if best_src is not None:
            sx, sy = best_src
            # Step from src toward hood
            dx = hx - sx
            dy = hy - sy
            if abs(dx) >= abs(dy):
                nx, ny = sx + (1 if dx > 0 else -1), sy
            else:
                nx, ny = sx, sy + (1 if dy > 0 else -1)
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: WIRE SPINES around each active hood ----
    spine_r = 10
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical spine
        for dy in range(-spine_r, spine_r + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal spine
        for dx in range(-spine_r, spine_r + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 4: ROADS — extend from existing roads into powered areas ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # For each hood, ensure flanking roads along wire spine
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods) // 2 + 1, 1) != 0:
            continue
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                # Only place if adjacent wire exists
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)
        # Horizontal spine roads
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 40% RES, 30% COM, 30% IND
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidates: near road AND near power, not edge
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Cycle through candidates based on step to add variety
        offset = (step * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 20) for py2 in range(14, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(25, 25), (60, 25), (95, 25),
                    (25, 50), (60, 50), (95, 50),
                    (25, 75), (60, 75), (95, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(45, 6), (75, 6), (45, 93), (75, 93), (6, 45), (6, 65), (113, 45), (113, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop ----
    if pop > 1200 and step % 3 == 0:
        nuclear_spots = [
            (15, 15), (60, 15), (105, 15),
            (15, 50), (105, 50),
            (15, 85), (60, 85), (105, 85),
            (35, 35), (85, 35), (35, 65), (85, 65),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value boost ----
    if pop > 200 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: plant near uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants with wire crosses and seed roads."""
    actions = []
    # Three coal plants: left, center, right
    for px, py in [(30, 50), (60, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross from each plant
        for x in range(px - 8, px + 9):
            if 0 <= x < 120:
                actions.append((Tool.WIRE, x, py))
        for y in range(py - 8, py + 9):
            if 0 <= y < 100:
                actions.append((Tool.WIRE, px, y))
        # Roads parallel to wire spines
        for x in range(px - 8, px + 9):
            if 0 <= x < 120:
                actions.append((Tool.ROAD, x, py - 2))
                actions.append((Tool.ROAD, x, py + 2))
        for y in range(py - 8, py + 9):
            if 0 <= y < 100:
                actions.append((Tool.ROAD, px - 2, y))
                actions.append((Tool.ROAD, px + 2, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Neighborhood grid: 10 cols x 8 rows = 80 neighborhoods
    all_hoods = []
    for hy in range(10, 100, 12):
        for hx in range(10, 120, 11):
            all_hoods.append((hx, hy))

    # Scale active neighborhoods with population
    def num_active():
        if pop < 50:   return 4
        if pop < 200:  return 10
        if pop < 500:  return 20
        if pop < 1000: return 35
        if pop < 2000: return 55
        if pop < 4000: return 75
        return len(all_hoods)

    n_active = num_active()
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighbor masks for power and road proximity
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :]  |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:]  |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    nbr_power = dilate(wm | pm, 4)
    nbr_road  = dilate(rm, 2)

    # --- PHASE 1: ENSURE POWER PLANTS near each active hood ---
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
            y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Find nearest empty cell
                for r in range(1, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                tool = (Tool.NUCLEARPOWER
                                        if funds > 10000 and pop > 1000
                                        else Tool.COALPOWER)
                                return (tool, nx, ny)

    # --- PHASE 2: WIRE SPINES from each hood's plant ---
    for (hx, hy) in active_hoods:
        spine_top   = max(2, hy - 10)
        spine_bot   = min(WORLD_H - 3, hy + 10)
        spine_left  = max(2, hx - 10)
        spine_right = min(WORLD_W - 3, hx + 10)

        # Vertical wire spine along hx
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        col_plant = [r for r in range(WORLD_H) if ib(hx, r) and bool(pm[r, hx])]
        if col_plant and not col_wire:
            py_l = col_plant[0]
            for wy in [py_l - 1, py_l + 1]:
                if ib(hx, wy) and not bool(pm[wy, hx]) and bool(em[wy, hx]):
                    return (Tool.WIRE, hx, wy)
        if col_wire:
            max_wr = max(col_wire)
            min_wr = min(col_wire)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                    return (Tool.WIRE, hx, nr)

        # Horizontal wire spine along hy
        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        row_plant = [c for c in range(WORLD_W) if ib(c, hy) and bool(pm[hy, c])]
        if row_plant and not row_wire:
            px_l = row_plant[0]
            for wx in [px_l - 1, px_l + 1]:
                if ib(wx, hy) and not bool(pm[hy, wx]) and bool(em[hy, wx]):
                    return (Tool.WIRE, wx, hy)
        if row_wire:
            max_wc = max(row_wire)
            min_wc = min(row_wire)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                    return (Tool.WIRE, nc, hy)

    # --- PHASE 3: CONNECT WIRE SPINES BETWEEN ADJACENT HOODS ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for hx2, hy2 in active_hoods:
            if hx2 <= hx1 or abs(hy1 - hy2) > 3:
                continue
            mid_y = (hy1 + hy2) // 2
            for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                if ib(cx, mid_y) and bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                    return (Tool.WIRE, cx, mid_y)
    for (hx1, hy1) in active_hoods:
        for hx2, hy2 in active_hoods:
            if hy2 <= hy1 or abs(hx1 - hx2) > 3:
                continue
            mid_x = (hx1 + hx2) // 2
            for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                if ib(mid_x, cy) and bool(em[cy, mid_x]) and not bool(pm[cy, mid_x]):
                    return (Tool.WIRE, mid_x, cy)

    # --- PHASE 4: ROAD GRID parallel to wire spines ---
    for (hx, hy) in active_hoods:
        col_wire = [r for r in range(WORLD_H) if ib(hx, r) and bool(wm[r, hx])]
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy) or not col_wire:
                continue
            cyc = step % 4
            for wr in col_wire[cyc::4]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)
        row_wire = [c for c in range(WORLD_W) if ib(c, hy) and bool(wm[hy, c])]
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry) or not row_wire:
                continue
            cyc = (step + 2) % 4
            for wc in row_wire[cyc::4]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # --- PHASE 5: ZONE PLACEMENT ---
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: proximity to active hoods + clustering with existing zones
        best_hood_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_hood_dist = np.minimum(best_hood_dist, d.astype(float))

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 150)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_hood_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_hood_dist
        else:
            score = best_hood_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- PHASE 6: EXTEND ROADS from existing network ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: CIVIC SERVICES (reactive) ---
    if pop > 10:
        fire_grid = [(fx, fy) for fy in range(15, 95, 15) for fx in range(15, 115, 15)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_grid = [(px2, py2) for py2 in range(15, 95, 15) for px2 in range(15, 115, 15)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [(20, 20), (60, 15), (100, 20),
                        (20, 80), (60, 85), (100, 80),
                        (15, 50), (105, 50),
                        (40, 40), (80, 40), (40, 60), (80, 60)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 5000:
        nuclear_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                        (60, 5), (60, 95), (5, 50), (115, 50),
                        (35, 20), (85, 20), (35, 80), (85, 80),
                        (20, 50), (100, 50)]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 30), (5, 70), (115, 30), (115, 70)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- FALLBACK: extend wire from any plant ---
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend wire from existing wires ---
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plant + wire spine + road seeds in a compact grid"""
    placements = []
    # Primary coal plant
    placements.append((Tool.COALPOWER, 60, 50))
    # Wire spine vertically from plant
    for dy in range(-4, 5):
        placements.append((Tool.WIRE, 62, 50 + dy))
    # Horizontal wire to seed coverage
    for dx in range(-4, 5):
        placements.append((Tool.WIRE, 60 + dx, 50))
    return placements


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- State init ---
    if 'phase' not in state:
        state['phase'] = 0
        state['road_cursor'] = 0
        state['zone_cursor'] = 0
        state['n_plants'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Plant management ---
    plant_ys, plant_xs = np.where(pm)
    n_plants = len(plant_xs)

    # Need primary plant
    if n_plants == 0:
        return (Tool.COALPOWER, 60, 50)

    # Find all plant centers (use first plant as anchor)
    ppx = int(plant_xs[0])
    ppy = int(plant_ys[0])

    # Add more plants as city grows
    plant_thresholds = [
        (8, (ppx + 24, ppy)),
        (25, (ppx + 48, ppy)),
        (60, (ppx + 24, ppy + 24)),
        (100, (ppx + 48, ppy + 24)),
    ]
    for i, (thresh, (p2x, p2y)) in enumerate(plant_thresholds):
        if total_zones >= thresh and n_plants <= i:
            if in_bounds(p2x, p2y):
                # Check no plant nearby
                nearby = False
                for dy in range(-5, 6):
                    for dx in range(-5, 6):
                        nx, ny = p2x + dx, p2y + dy
                        if in_bounds(nx, ny) and pm[ny, nx]:
                            nearby = True
                            break
                    if nearby:
                        break
                if not nearby:
                    # Wire bridge first
                    for wc in range(ppx + 3, p2x - 1):
                        if in_bounds(wc, ppy) and not pm[ppy, wc] and (em[ppy, wc] or wm[ppy, wc]):
                            return (Tool.WIRE, wc, ppy)
                    for wr in range(ppy + 3, p2y - 1):
                        if in_bounds(p2x, wr) and not pm[wr, p2x] and (em[wr, p2x] or wm[wr, p2x]):
                            return (Tool.WIRE, p2x, wr)
                    if in_bounds(p2x, p2y) and (em[p2y, p2x] or not pm[p2y, p2x]):
                        return (Tool.COALPOWER, p2x, p2y)

    # --- Build wire network reactively ---
    # Compute frontier: empty cells adjacent to existing wire/plant
    # We want to grow wire toward areas that need coverage
    wire_or_plant = wm | pm

    # Desired wire coverage area: rectangle around all plants
    all_px = list(plant_xs)
    all_py = list(plant_ys)
    cx = int(np.mean(all_px)) if all_px else 60
    cy = int(np.mean(all_py)) if all_py else 50

    pop_radius = min(30, 8 + obs.city_pop // 30)

    # Find wire frontier cells (adjacent to wire/plant, empty)
    wire_frontier = []
    wys, wxs = np.where(wire_or_plant)
    if len(wxs) > 0:
        for dy in range(-1, 2):
            for dx in range(-1, 2):
                if abs(dx) + abs(dy) != 1:
                    continue
                nr = np.clip(wys + dy, 0, WORLD_H - 1)
                nc = np.clip(wxs + dx, 0, WORLD_W - 1)
                valid = (
                    (nr >= 0) & (nr < WORLD_H) &
                    (nc >= 0) & (nc < WORLD_W) &
                    em[nr, nc]
                )
                for k in range(len(wxs)):
                    if valid[k]:
                        wnx, wny = int(nc[k]), int(nr[k])
                        dist_center = abs(wnx - cx) + abs(wny - cy)
                        if dist_center <= pop_radius:
                            wire_frontier.append((dist_center, wnx, wny))

    wire_frontier.sort(key=lambda t: t[0])

    # --- Build road grid reactively ---
    # Roads: we want a grid of roads every 4 tiles within wire coverage
    # First compute which cells have wire nearby
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wire_or_plant[sr0:sr1, sc0:sc1]

    # Road grid: every 4 columns and rows within coverage
    # Priority: extend roads adjacent to existing roads (or wire, near plant)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Desired road positions: grid lines every 4 tiles in covered area
    def wants_road(x, y):
        # Road on columns/rows that are multiples of 4 offset from center
        cx_mod = (x - cx) % 4
        cy_mod = (y - cy) % 4
        return cx_mod == 0 or cy_mod == 0

    # Candidate road cells: want road, empty, near wire, near existing road
    road_candidates = []
    rys2, rxs2 = np.where(rm)
    step_k = int(obs.step * 13) % max(len(rxs2), 1) if len(rxs2) > 0 else 0
    for offset in range(min(len(rxs2), 30)):
        k = (step_k + offset * 7) % len(rxs2)
        rx2, ry2 = int(rxs2[k]), int(rys2[k])
        for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if in_bounds(nx2, ny2) and em[ny2, nx2] and not pm[ny2, nx2] and nbr_wire[ny2, nx2]:
                dist_c = abs(nx2 - cx) + abs(ny2 - cy)
                if dist_c <= pop_radius:
                    road_candidates.append((dist_c, nx2, ny2))

    road_candidates.sort(key=lambda t: t[0])

    # --- Zone placement ---
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if pm[nr2, nc2]:
                    return False
                if rm[nr2, nc2]:
                    return False
                if wm[nr2, nc2]:
                    return False
                if not (em[nr2, nc2] or zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    zone_candidates = []
    for k in range(len(cxs)):
        zx, zy = int(cxs[k]), int(cys[k])
        dist_c = abs(zx - cx) + abs(zy - cy)
        zone_candidates.append((dist_c, zx, zy))
    zone_candidates.sort(key=lambda t: t[0])

    # --- Decision logic: balance wire/road/zone ---
    # Count how many wires, roads, zones exist
    n_wires = int(np.sum(wm))
    n_roads = int(np.sum(rm))

    # Strategy: ensure power first, then roads, then zones, interleaved
    # We want roughly: 1 wire per 2 zones, 1 road per 2 zones

    wire_deficit = total_zones * 2 - n_wires
    road_deficit = total_zones * 2 - n_roads

    # Place wire if wire is lagging
    if wire_deficit > road_deficit and wire_deficit > 0 and len(wire_frontier) > 0:
        _, wx3, wy3 = wire_frontier[0]
        return (Tool.WIRE, wx3, wy3)

    # Place road if road is lagging
    if road_deficit > 0 and len(road_candidates) > 0:
        _, rx3, ry3 = road_candidates[0]
        return (Tool.ROAD, rx3, ry3)

    # Place zone if we have coverage
    step_z = int(obs.step * 7) % max(len(zone_candidates), 1) if zone_candidates else 0
    for offset in range(min(len(zone_candidates), 80)):
        k = (step_z + offset) % len(zone_candidates)
        _, zx, zy = zone_candidates[k]
        if zone_clear(zx, zy):
            return (pick_tool(), zx, zy)

    # Fallback: extend wire
    if len(wire_frontier) > 0:
        _, wx4, wy4 = wire_frontier[0]
        return (Tool.WIRE, wx4, wy4)

    # Extend roads along existing roads into wire-covered areas
    for offset in range(len(road_candidates)):
        _, rx4, ry4 = road_candidates[offset]
        if em[ry4, rx4] and not pm[ry4, rx4]:
            return (Tool.ROAD, rx4, ry4)

    # --- Services ---
    if obs.city_pop > 300:
        for fpos in [(cx - 14, cy - 10), (cx + 14, cy - 10),
                     (cx + 14, cy + 10), (cx - 14, cy + 10)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and em[fsy, fsx] and nbr_road[fsy, fsx]:
                return (Tool.FIRESTATION, fsx, fsy)

    if obs.city_pop > 600:
        for ppos in [(cx - 10, cy + 14), (cx + 10, cy + 14),
                     (cx + 10, cy - 14), (cx - 10, cy - 14)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and em[psy, psx] and nbr_road[psy, psx]:
                return (Tool.POLICESTATION, psx, psy)

    if obs.city_pop > 1200:
        for spos in [(cx + 30, cy + 18), (cx - 30, cy + 18)]:
            ssx, ssy = spos
            if in_bounds(ssx, ssy) and em[ssy, ssx]:
                return (Tool.STADIUM, ssx, ssy)

    return None

