def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target mix: 50% residential, 25% commercial, 25% industrial
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(resm[nr, nc]) or bool(comm[nr, nc]) or bool(indm[nr, nc])):
                    return False
        return True

    # Build roads in a grid pattern - every 6 tiles both horizontally and vertically
    # This creates a denser road network for better access
    road_rows = list(range(8, 95, 6))   # y positions of horizontal roads
    road_cols = list(range(8, 115, 6))  # x positions of vertical roads

    # Phase 1: Build road grid (first ~300 steps)
    if step < 300:
        # Lay horizontal roads
        target_row_idx = step % len(road_rows)
        ry = road_rows[target_row_idx]
        # Find a stretch of empty tiles in this row
        for rx in range(3, WORLD_W - 3):
            if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                return (Tool.ROAD, rx, ry)

    # Phase 2: Extend road grid (next steps)
    if step < 600 and step % 3 == 0:
        # Lay vertical roads
        target_col_idx = (step // 3) % len(road_cols)
        cx = road_cols[target_col_idx]
        for cy in range(3, WORLD_H - 3):
            if ib(cx, cy) and bool(em[cy, cx]) and not bool(pm[cy, cx]):
                return (Tool.ROAD, cx, cy)

    # Power plants: add more as city grows
    if step % 50 == 10:
        # Check if any region lacks power, add plant if so
        for py in range(15, 90, 20):
            for px in range(15, 110, 20):
                x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
                y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    for r in range(10):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # Wire extension: connect unpowered areas
    if step % 5 in (1, 2):
        power_src = wm | pm
        unpowered_empty = em & ~near_power
        ue_ys, ue_xs = np.where(unpowered_empty)
        if len(ue_xs) > 0:
            # Find wire/plant nearest to an unpowered empty area
            wire_ys, wire_xs = np.where(power_src)
            if len(wire_xs) > 0:
                idx = (step * 31) % len(ue_xs)
                tx, ty = int(ue_xs[idx]), int(ue_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                # Step toward target
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Road extension: extend roads into powered areas
    if step % 7 in (3, 4):
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            n_sample = min(len(road_xs), 150)
            sk = (step * 17) % len(road_xs)
            for i in range(n_sample):
                k = (sk + i * 11) % len(road_xs)
                rx, ry = int(road_xs[k]), int(road_ys[k])
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx2, ny2 = rx + dx, ry + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        if bool(near_power[ny2, nx2]):
                            return (Tool.ROAD, nx2, ny2)

    # Civic services based on population
    if pop > 5:
        fire_spots = [
            (10, 10), (35, 10), (65, 10), (95, 10), (112, 10),
            (10, 35), (112, 35), (10, 65), (112, 65),
            (10, 90), (35, 90), (65, 90), (95, 90), (112, 90),
            (25, 25), (55, 25), (85, 25),
            (25, 50), (55, 50), (85, 50),
            (25, 75), (55, 75), (85, 75),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 50:
        police_spots = [
            (18, 18), (48, 18), (78, 18), (108, 18),
            (18, 48), (48, 48), (78, 48), (108, 48),
            (18, 78), (48, 78), (78, 78), (108, 78),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        for sx, sy in [(20, 20), (60, 20), (100, 20), (20, 60), (60, 60), (100, 60),
                       (20, 80), (60, 80), (100, 80), (40, 40), (80, 40), (40, 70), (80, 70)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        for nx2, ny2 in [(15, 50), (105, 50), (60, 15), (60, 85),
                         (15, 25), (105, 25), (15, 75), (105, 75)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for sx, sy in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        for sx, sy in [(45, 5), (75, 5), (45, 92), (75, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks
    if pop > 80 and step % 8 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 13) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Zone placement: place zones in powered+roaded areas
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False
    cand_mask &= ~(wm | rm | pm)

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Use multiple neighborhood centers for denser, more distributed growth
        if pop < 200:
            # Build two neighborhoods simultaneously
            centers = [(30, 30), (90, 70)]
            cx_t = centers[step % 2][0]
            cy_t = centers[step % 2][1]
            dists = np.abs(cxs - cx_t).astype(float) + np.abs(cys - cy_t).astype(float)
        elif pop < 800:
            # Expand to 4 neighborhoods
            centers = [(25, 25), (95, 25), (25, 75), (95, 75)]
            ci = step % 4
            cx_t, cy_t = centers[ci]
            dists = np.abs(cxs - cx_t).astype(float) + np.abs(cys - cy_t).astype(float)
        else:
            # Fill entire map - prefer least-filled areas
            # Divide into 3x3 grid of sectors
            sector_counts = np.zeros((3, 3))
            for si in range(3):
                for sj in range(3):
                    y0, y1 = si * 33, min(100, (si + 1) * 33)
                    x0, x1 = sj * 40, min(120, (sj + 1) * 40)
                    sector_counts[si, sj] = (
                        int(np.sum(resm[y0:y1, x0:x1])) +
                        int(np.sum(comm[y0:y1, x0:x1])) +
                        int(np.sum(indm[y0:y1, x0:x1]))
                    )
            min_idx = np.argmin(sector_counts)
            si, sj = divmod(int(min_idx), 3)
            cx_t = sj * 40 + 20
            cy_t = si * 33 + 16
            dists = np.abs(cxs - cx_t).astype(float) + np.abs(cys - cy_t).astype(float)

        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 200)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 100)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

