    # Roads flanking horizontal wire spines
    for x in range(0, 120):
        for wy in [20, 50, 80]:
            for off in [-1, 1]:
                ry = wy + off
                if 0 <= ry < 100:
                    actions.append((Tool.ROAD, x, ry))
    # Roads flanking vertical wire spines
    for y in range(0, 100):
        for wx in [30, 60, 90]:
            for off in [-1, 1]:
                rx = wx + off
                if 0 <= rx < 120:
                    actions.append((Tool.ROAD, rx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [20, 50, 80]
    wire_cols = [30, 60, 90]

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind - more residential bias for population
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if pop < 500:
            # Early: more industrial for jobs, then balance
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # Late: maximize residential
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.20:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Neighborhood positions: cells between wire spines
    # row bands between y=20,50,80: [3..18], [22..48], [52..78], [82..97]
    # col bands between x=30,60,90: [3..28], [32..58], [62..88], [92..117]
    row_bands = [(3, 18), (22, 48), (52, 78), (82, 97)]
    col_bands = [(3, 28), (32, 58), (62, 88), (92, 117)]
    nh_positions = []
    for (ry0, ry1) in row_bands:
        for (cx0, cx1) in col_bands:
            cy = (ry0 + ry1) // 2
            cx = (cx0 + cx1) // 2
            nh_positions.append((cx, cy))

    def get_active_hoods():
        # Expand coverage as population grows
        if pop < 100:
            return nh_positions[4:8]  # Central row
        elif pop < 500:
            return nh_positions[0:12]
        elif pop < 2000:
            return nh_positions
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    # Phase-based infrastructure
    phase = step % 10

    if phase in (0, 1):
        # Ensure power plants near each active hood region
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 25), min(WORLD_W, hx + 26)
            y0, y1 = max(0, hy - 25), min(WORLD_H, hy + 26)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(2, 30):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if found:
                        break

    elif phase == 2:
        # Extend wire horizontally
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    if bool(em[wr, wx]):
                        left = ib(wx-1, wr) and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                        right = ib(wx+1, wr) and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                        if left or right:
                            return (Tool.WIRE, wx, wr)

    elif phase == 3:
        # Extend wire vertically
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    if bool(em[wy, wc]):
                        up = ib(wc, wy-1) and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                        down = ib(wc, wy+1) and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                        if up or down:
                            return (Tool.WIRE, wc, wy)

    elif phase == 4:
        # Fill horizontal roads flanking wire rows
        for wr in wire_rows:
            for off in [-1, 1]:
                ry = wr + off
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 5:
        # Fill vertical roads flanking wire cols
        for wc in wire_cols:
            for off in [-1, 1]:
                rcx = wc + off
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 6:
        # Add cross-roads through neighborhoods (horizontal)
        for (ry0, ry1) in row_bands:
            mid_y = (ry0 + ry1) // 2
            for rx in range(3, WORLD_W - 3):
                if ib(rx, mid_y) and bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                    adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                          (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 7:
        # Add cross-roads through neighborhoods (vertical)
        for (cx0, cx1) in col_bands:
            mid_x = (cx0 + cx1) // 2
            for ry in range(3, WORLD_H - 3):
                if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                    adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                          (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 8:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 9:
        # Extend road from existing road near power
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 150)):
                k = (sk + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT (main closed-loop decision) ----
    cand_mask = em & near_road & near_power
    # Avoid wire/road corridors and boundaries
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 3000:
                break

    # ---- CIVIC SERVICES (closed-loop: only place when pop warrants) ----
    if pop > 30:
        fire_spots = [(10, 10), (55, 10), (110, 10),
                      (10, 40), (55, 40), (110, 40),
                      (10, 65), (55, 65), (110, 65),
                      (10, 90), (55, 90), (110, 90)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [(20, 10), (60, 10), (100, 10),
                        (20, 40), (60, 40), (100, 40),
                        (20, 70), (60, 70), (100, 70),
                        (20, 90), (60, 90), (100, 90)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [(45, 10), (75, 10), (45, 90), (75, 90),
                    (15, 50), (105, 50)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Add nuclear power plants at strategic locations
        nuke_spots = [(15, 10), (105, 10), (15, 90), (105, 90),
                      (60, 35), (60, 65)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 5), (113, 5), (5, 93), (113, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(45, 5), (75, 5), (45, 93), (75, 93)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 50 and step % 8 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered neighborhoods
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            target_hx, target_hy = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - target_hx) + np.abs(wire_ys_arr - target_hy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_hx == bwx else (1 if target_hx > bwx else -1)
            dy = 0 if target_hy == bwy else (1 if target_hy > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (sk2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: road near zone
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + initial wire + road grid."""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire horizontally between them
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically from each plant
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 40, y))
            actions.append((Tool.WIRE, 80, y))
    # Roads parallel to wire spine
    for x in range(38, 83):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.astype(bool).copy()
        m = mask.astype(bool)
        for d in range(1, r+1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    # Proximity masks
    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% res, 25% com, 25% ind
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # === CLOSED-LOOP STRATEGY ===
    # Priority 1: If we have very few power sources, add a coal plant near center
    plant_count = int(np.any(pm))
    plant_ys, plant_xs = np.where(pm)
    num_plants = len(plant_xs)

    # Need more plants as city grows
    plants_needed = 1 + pop // 300
    if num_plants < plants_needed:
        # Find empty spot near map center, away from existing infra
        cx, cy = WORLD_W // 2, WORLD_H // 2
        # Try to place near existing wire network to connect easily
        wire_ys, wire_xs = np.where(wm)
        if len(wire_xs) > 0:
            # Find a wire-adjacent empty spot far from existing plants
            # Score: near wire but far from existing plants
            cands = []
            step_sample = max(1, len(wire_xs) // 50)
            for i in range(0, len(wire_xs), step_sample):
                wx, wy = int(wire_xs[i]), int(wire_ys[i])
                # Try 5 tiles away from wire in various directions
                for dx, dy in [(6,0),(-6,0),(0,6),(0,-6),(6,6),(-6,6),(6,-6),(-6,-6)]:
                    nx, ny = wx+dx, wy+dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        # Check 3x3 clearance
                        clear = all(ib(nx+ddc, ny+ddr) and bool(em[ny+ddr, nx+ddc])
                                    for ddr in range(-1, 2) for ddc in range(-1, 2))
                        if clear:
                            min_pd = min(abs(px-nx)+abs(py-ny) for px, py in zip(plant_xs, plant_ys)) if len(plant_xs) > 0 else 999
                            if min_pd > 15:
                                cands.append((min_pd, nx, ny))
            if cands:
                cands.sort(reverse=True)
                _, px2, py2 = cands[0]
                return (Tool.COALPOWER, px2, py2)
        else:
            # No wires yet, place near center
            for r in range(0, 30):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = cx+dx, cy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # Priority 2: Extend wire network from plants/existing wires toward unpowered areas
    # Find tiles that are near road but not near power
    needs_power = rm & ~near_power & ~pm
    need_ys, need_xs = np.where(needs_power)
    if len(need_xs) > 0 and step % 4 in (0, 1):
        # Find nearest wire/plant to each needy road tile
        wire_src = wm | pm
        src_ys, src_xs = np.where(wire_src)
        if len(src_xs) > 0:
            # Pick the needy road tile closest to wire network
            idx = (step * 17) % len(need_xs)
            for off in range(min(len(need_xs), 100)):
                k = (idx + off) % len(need_xs)
                tx, ty = int(need_xs[k]), int(need_ys[k])
                # Find nearest wire source
                dists = np.abs(src_xs - tx) + np.abs(src_ys - ty)
                bi = int(np.argmin(dists))
                sx, sy = int(src_xs[bi]), int(src_ys[bi])
                # Step from source toward target
                dx = 0 if tx == sx else (1 if tx > sx else -1)
                dy = 0 if ty == sy else (1 if ty > sy else -1)
                # Try to move in x first, then y
                for nx, ny in [(sx+dx, sy), (sx, sy+dy), (sx+dx, sy+dy)]:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # Priority 3: Extend wire from existing wire to cover more area
    if step % 4 == 2:
        # Find wire frontier: wire tiles with empty neighbors far from other wires
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            # Prefer extending toward areas with roads
            road_ys2, road_xs2 = np.where(rm)
            if len(road_xs2) > 0:
                # Find road tile farthest from power
                power_dist = np.full((WORLD_H, WORLD_W), 9999.0)
                for px, py in zip(wire_xs2, wire_ys2):
                    ys_idx = np.arange(WORLD_H)
                    xs_idx = np.arange(WORLD_W)
                    d = np.abs(xs_idx[np.newaxis, :] - px) + np.abs(ys_idx[:, np.newaxis] - py)
                    power_dist = np.minimum(power_dist, d)
                # Pick road tile with highest power dist
                road_power_dists = power_dist[road_ys2, road_xs2]
                if len(road_power_dists) > 0:
                    bi = int(np.argmax(road_power_dists))
                    tx, ty = int(road_xs2[bi]), int(road_ys2[bi])
                    if road_power_dists[bi] > 5:
                        # Walk wire toward that target
                        w_dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
                        wi = int(np.argmin(w_dists))
                        sx, sy = int(wire_xs2[wi]), int(wire_ys2[wi])
                        dx = 0 if tx == sx else (1 if tx > sx else -1)
                        dy = 0 if ty == sy else (1 if ty > sy else -1)
                        for nx, ny in [(sx+dx, sy), (sx, sy+dy)]:
                            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                                return (Tool.WIRE, nx, ny)

    # Priority 4: Extend roads into powered but road-less areas
    if step % 4 == 3:
        powered_empty = em & near_power & ~near_road
        pe_ys, pe_xs = np.where(powered_empty)
        if len(pe_xs) > 0:
            # Find road tile nearest to these powered-empty tiles
            road_ys3, road_xs3 = np.where(rm)
            if len(road_xs3) > 0:
                # Pick powered-empty tile closest to existing road
                idx = (step * 19) % len(pe_xs)
                for off in range(min(len(pe_xs), 150)):
                    k = (idx + off) % len(pe_xs)
                    tx, ty = int(pe_xs[k]), int(pe_ys[k])
                    dists = np.abs(road_xs3 - tx) + np.abs(road_ys3 - ty)
                    bi = int(np.argmin(dists))
                    sx, sy = int(road_xs3[bi]), int(road_ys3[bi])
                    if abs(sx-tx) + abs(sy-ty) > 20:
                        continue
                    dx = 0 if tx == sx else (1 if tx > sx else -1)
                    dy = 0 if ty == sy else (1 if ty > sy else -1)
                    for nx, ny in [(sx+dx, sy), (sx, sy+dy)]:
                        if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                            return (Tool.ROAD, nx, ny)

    # Civic services (reactive)
    if pop > 100:
        fire_spots = [(x, y) for y in range(12, 100, 22) for x in range(12, 120, 28)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                # Check not destroying infrastructure
                clear3 = all(ib(sx+dc, sy+dr) and (bool(em[sy+dr, sx+dc]) or bool(zone_tiles[sy+dr, sx+dc]))
                             for dr in range(-1,2) for dc in range(-1,2))
                if clear3:
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(x, y) for y in range(18, 100, 28) for x in range(18, 120, 32)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                clear3 = all(ib(sx+dc, sy+dr) and (bool(em[sy+dr, sx+dc]) or bool(zone_tiles[sy+dr, sx+dc]))
                             for dr in range(-1,2) for dc in range(-1,2))
                if clear3:
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for sx, sy in [(25,25),(95,25),(25,75),(95,75),(60,50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [(10,50),(110,50),(60,10),(60,90),(10,20),(110,20),(10,80),(110,80)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                clear3 = all(ib(nx2+dc, ny2+dr) and bool(em[ny2+dr, nx2+dc])
                             for dr in range(-1,2) for dc in range(-1,2))
                if clear3:
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2500:
        for sx, sy in [(10,90),(110,90),(10,10),(110,10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for sx, sy in [(50,10),(70,10),(50,88),(70,88)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Priority 5: Place zones on tiles that are both powered and road-accessible
    cand_mask = em & near_road & near_power
    # Avoid map edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Don't place on wires or road rows (protect infrastructure)
    cand_mask[rm | wm] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        tool = pick_tool()
        # Prefer spots near existing zones (cluster for density bonus)
        if int(np.sum(zone_tiles)) > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            # Score each candidate by proximity to existing zones
            scores = np.zeros(len(cxs2))
            sample = max(1, len(zone_xs) // 30)
            for i in range(0, len(zone_xs), sample):
                d = np.abs(cxs2 - zone_xs[i]) + np.abs(cys2 - zone_ys[i])
                scores += 1.0 / (d + 1)
            order = np.argsort(-scores)
        else:
            # No zones yet, pick near center
            cx, cy = WORLD_W // 2, WORLD_H // 2
            dists = np.abs(cxs2 - cx) + np.abs(cys2 - cy)
            order = np.argsort(dists)

        # Offset by step for variety
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # Fallback: place parks near roads to boost land value
    if pop > 50 and step % 3 == 0:
        park_mask = em & near_road & near_power
        pys, pxs = np.where(park_mask)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 11) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend roads from existing road network
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 13) % len(road_xs4)
        for off in range(min(len(road_xs4), 300)):
            k = (sk + off * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Last resort: extend wire from existing wire
    wire_ys5, wire_xs5 = np.where(wm | pm)
    if len(wire_xs5) > 0:
        sk = (step * 11) % len(wire_xs5)
        for off in range(min(len(wire_xs5), 200)):
            k = (sk + off * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = wx2+dx2, wy2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + flanking roads."""
    actions = []
    # Central power plant
