def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire/road grid definitions
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [10, 22, 35, 47, 60, 72, 85, 97, 110]
    road_rows = [5, 15, 25, 35, 45, 55, 65, 75, 85, 95]
    road_cols = [4, 16, 28, 41, 53, 66, 78, 91, 103, 116]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure power plants cover all regions
    if phase == 0:
        plant_targets = []
        for py in range(10, 95, 20):
            for px in range(10, 115, 25):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 14), min(WORLD_W, px + 15)
            y0, y1 = max(0, py - 14), min(WORLD_H, py + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1-2: Fill wire row gaps
    if phase in (1, 2):
        target_rows = wire_rows if phase == 1 else [5, 15, 25, 45, 55, 65, 75, 85, 95]
        for wr in target_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]) and bool(em[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    # Phase 3-4: Fill wire col gaps
    if phase in (3, 4):
        target_cols = wire_cols if phase == 3 else [4, 16, 28, 41, 53, 66, 78, 91, 103, 116]
        for wc in target_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]) and bool(em[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # Phase 5: Build horizontal road grid
    if phase == 5:
        for rr in road_rows:
            if not (0 < rr < WORLD_H):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    adj = ((rx > 0 and bool(rm[rr, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or
                           (rr > 0 and bool(rm[rr-1, rx])) or
                           (rr < WORLD_H-1 and bool(rm[rr+1, rx])))
                    if adj or rx == 1:
                        return (Tool.ROAD, rx, rr)

    # Phase 6: Build vertical road grid
    if phase == 6:
        for rc in road_cols:
            if not (0 < rc < WORLD_W):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    adj = ((ry > 0 and bool(rm[ry-1, rc])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or
                           (rc > 0 and bool(rm[ry, rc-1])) or
                           (rc < WORLD_W-1 and bool(rm[ry, rc+1])))
                    if adj or ry == 1:
                        return (Tool.ROAD, rc, ry)

    # Phase 7: Wire unpowered road segments toward power
    if phase == 7:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Wire unpowered zones
    if phase == 8:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 9: Road toward unroaded zones
    if phase == 9:
        unroaded_zones = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded_zones)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (closed-loop, scaled to pop) ----
    if pop > 15:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,25),(115,25),(5,48),(115,48),
            (5,68),(115,68),(5,88),(115,88),
            (30,95),(60,95),(90,95),
            (20,20),(45,20),(70,20),(95,20),
            (20,50),(45,50),(70,50),(95,50),
            (20,75),(45,75),(70,75),(95,75),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (12,8),(37,8),(62,8),(87,8),(112,8),
            (12,22),(37,22),(62,22),(87,22),(112,22),
            (12,38),(37,38),(62,38),(87,38),(112,38),
            (12,55),(37,55),(62,55),(87,55),(112,55),
            (12,72),(37,72),(62,72),(87,72),(112,72),
            (12,88),(37,88),(62,88),(87,88),(112,88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (25,12),(75,12),(25,38),(75,38),
            (25,62),(75,62),(25,88),(75,88),
            (50,25),(100,25),(50,75),(100,75),
            (10,50),(110,50),(60,50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,20),(115,20),(5,80),(115,80),
            (30,5),(90,5),(30,95),(90,95),
            (5,35),(115,35),(5,65),(115,65),
            (50,50),(70,50),(40,50),(80,50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5,92),(115,92),(5,8),(115,8),(60,5),(60,95),(30,95),(90,95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45),(5,55),(110,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 150 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (primary closed-loop action) ----
    # Exclude wire/road corridors from zoning
    all_excl_rows = wire_rows + road_rows
    all_excl_cols = wire_cols + road_cols

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in all_excl_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in all_excl_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scale active centers based on population
        if pop < 50:
            active_centers = [
                (60, 50), (50, 50), (70, 50),
                (60, 42), (60, 58), (50, 42), (70, 42),
                (40, 50), (80, 50), (60, 35), (60, 65),
                (45, 55), (75, 45),
            ]
        elif pop < 200:
            active_centers = []
            for row in range(4):
                for col in range(6):
                    cx = 12 + col * 18
                    cy = 12 + row * 22
                    active_centers.append((cx, cy))
        elif pop < 600:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 8 + col * 14
                    cy = 8 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 6 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 1200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: place a new coal plant near unpowered area
    unpowered_road = rm & ~near_power
    up_ys, up_xs = np.where(unpowered_road)
    if len(up_xs) > 0:
        idx = (step * 29) % len(up_xs)
        tx, ty = int(up_xs[idx]), int(up_ys[idx])
        for r in range(1, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx2, ny2 = tx + dx, ty + dy
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            return (Tool.COALPOWER, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + extra plants at compass points."""
    actions = []
    # Central plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(20, 100):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(15, 90):
        actions.append((Tool.WIRE, 60, y))
    # Corner plants to power the whole map faster
    for px, py in [(20, 20), (100, 20), (20, 80), (100, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Initial roads flanking center plant
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, 58, 50 + dy))
        actions.append((Tool.ROAD, 62, 50 + dy))
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, 60 + dx, 48))
        actions.append((Tool.ROAD, 60 + dx, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(resm[nr, nc]) or
                        bool(comm[nr, nc]) or bool(indm[nr, nc])):
                    return False
        return True

    # Active neighborhood centers — dense grid
    hood_cols = [12, 28, 44, 60, 76, 92, 108]
    hood_rows = [12, 28, 44, 60, 76, 90]
    all_hoods = [(cx, cy) for cx in hood_cols for cy in hood_rows]

    def n_active():
        if pop < 100:   return 3
        if pop < 300:   return 6
        if pop < 700:   return 10
        if pop < 1500:  return 16
        if pop < 3000:  return 22
        if pop < 6000:  return 28
        return len(all_hoods)

    na = n_active()
    if na >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        step_sz = len(all_hoods) / na
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(na)]

    # === PHASE 1: Ensure each active hood has a power plant ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx2, ny2 = hx + dx, hy + dy
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 2: Extend wires from power plants to cover map ===
    # Every ~20 steps, check for uncovered regions and add a plant
    if step % 20 == 0:
        for py2 in range(10, 95, 18):
            for px2 in range(10, 115, 18):
                x0, x1 = max(0, px2 - 10), min(WORLD_W, px2 + 11)
                y0, y1 = max(0, py2 - 10), min(WORLD_H, py2 + 11)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    for r in range(0, 12):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px2 + dx, py2 + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 3: Wire spines from each plant outward ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        sub_pm = pm[y0:y1, x0:x1]
        plant_locs = list(zip(*np.where(sub_pm)))
        if not plant_locs:
            continue
        pr, pc = plant_locs[0]
        px_abs = x0 + pc
        py_abs = y0 + pr

        reach = 16
        for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            ddx, ddy = direction
            for dist in range(1, reach + 1):
                wx = px_abs + ddx * dist
                wy = py_abs + ddy * dist
                if not ib(wx, wy):
                    break
                if bool(pm[wy, wx]):
                    break
                if not bool(wm[wy, wx]):
                    if bool(em[wy, wx]) or bool(rm[wy, wx]):
                        return (Tool.WIRE, wx, wy)
                    else:
                        break

    # === PHASE 4: Connect wire between nearby hoods (horizontal) ===
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods:
            if hx2 <= hx1 or abs(hy1 - hy2) > 10:
                continue
            ty = (hy1 + hy2) // 2
            row_wire_cols = [c for c in range(min(hx1, hx2), max(hx1, hx2) + 1)
                             if ib(c, ty) and bool(wm[ty, c])]
            if not row_wire_cols:
                mid = (hx1 + hx2) // 2
                if ib(mid, ty) and bool(em[ty, mid]):
                    return (Tool.WIRE, mid, ty)
                continue
            max_c = max(row_wire_cols)
            min_c = min(row_wire_cols)
            if max_c < max(hx1, hx2) - 2:
                nc = max_c + 1
                if ib(nc, ty) and not bool(pm[ty, nc]) and (bool(em[ty, nc]) or bool(wm[ty, nc])):
                    return (Tool.WIRE, nc, ty)
            if min_c > min(hx1, hx2) + 2:
                nc = min_c - 1
                if ib(nc, ty) and not bool(pm[ty, nc]) and (bool(em[ty, nc]) or bool(wm[ty, nc])):
                    return (Tool.WIRE, nc, ty)

    # === PHASE 5: Connect wire between nearby hoods (vertical) ===
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy2 <= hy1 or abs(hx1 - hx2) > 10:
                continue
            tx = (hx1 + hx2) // 2
            col_wire_rows = [r for r in range(min(hy1, hy2), max(hy1, hy2) + 1)
                             if ib(tx, r) and bool(wm[r, tx])]
            if not col_wire_rows:
                mid = (hy1 + hy2) // 2
                if ib(tx, mid) and bool(em[mid, tx]):
                    return (Tool.WIRE, tx, mid)
                continue
            max_r = max(col_wire_rows)
            min_r = min(col_wire_rows)
            if max_r < max(hy1, hy2) - 2:
                nr = max_r + 1
                if ib(tx, nr) and not bool(pm[nr, tx]) and (bool(em[nr, tx]) or bool(wm[nr, tx])):
                    return (Tool.WIRE, tx, nr)
            if min_r > min(hy1, hy2) + 2:
                nr = min_r - 1
                if ib(tx, nr) and not bool(pm[nr, tx]) and (bool(em[nr, tx]) or bool(wm[nr, tx])):
                    return (Tool.WIRE, tx, nr)

    # === PHASE 6: Build roads along wire spines ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 7), min(WORLD_W, hx + 8)
        y0, y1 = max(0, hy - 7), min(WORLD_H, hy + 8)
        sub_pm = pm[y0:y1, x0:x1]
        plant_locs = list(zip(*np.where(sub_pm)))
        if not plant_locs:
            continue
        pr, pc = plant_locs[0]
        px_abs = x0 + pc
        py_abs = y0 + pr

        reach = 15
        # Roads on either side of vertical wire
        for rx in [px_abs - 1, px_abs + 1]:
            if not ib(rx, py_abs):
                continue
            for dist in range(-reach, reach + 1):
                ry = py_abs + dist
                if not ib(rx, ry):
                    continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if ib(px_abs, ry) and bool(wm[ry, px_abs]):
                        return (Tool.ROAD, rx, ry)

        # Roads on either side of horizontal wire
        for ry in [py_abs - 1, py_abs + 1]:
            if not ib(px_abs, ry):
                continue
            for dist in range(-reach, reach + 1):
                rxc = px_abs + dist
                if not ib(rxc, ry):
                    continue
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    if ib(rxc, py_abs) and bool(wm[py_abs, rxc]):
                        return (Tool.ROAD, rxc, ry)

    # === PHASE 7: Extend roads from existing network into powered areas ===
    if step % 3 in (0, 1):
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 17) % len(road_xs)
            for i in range(min(len(road_xs), 120)):
                k = (sk + i * 11) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if (ib(nx2, ny2) and bool(em[ny2, nx2])
                            and not bool(pm[ny2, nx2])
                            and bool(near_power[ny2, nx2])):
                        return (Tool.ROAD, nx2, ny2)

    # === PHASE 8: ZONE PLACEMENT ===
    cand_mask = em & near_road & near_power
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False
    cand_mask &= ~(wm | rm | pm)

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates by proximity to active hoods
        if pop < 500:
            # Focus near center hoods
            cx_t, cy_t = 60, 50
            dists = (np.abs(cxs - cx_t) + np.abs(cys - cy_t)).astype(float)
        elif pop < 2000:
            # Spread outward in rings
            ring_r = 20 + pop // 25
            dists = np.abs((np.abs(cxs - 60) + np.abs(cys - 50)).astype(float) - ring_r)
        else:
            # Fill least-dense quadrant
            q_counts = [
                int(np.sum(resm[:50, :60])) + int(np.sum(comm[:50, :60])) + int(np.sum(indm[:50, :60])),
                int(np.sum(resm[:50, 60:])) + int(np.sum(comm[:50, 60:])) + int(np.sum(indm[:50, 60:])),
                int(np.sum(resm[50:, :60])) + int(np.sum(comm[50:, :60])) + int(np.sum(indm[50:, :60])),
                int(np.sum(resm[50:, 60:])) + int(np.sum(comm[50:, 60:])) + int(np.sum(indm[50:, 60:])),
            ]
            min_q = int(np.argmin(q_counts))
            cx_t = 30 if min_q in (0, 2) else 90
            cy_t = 25 if min_q in (0, 1) else 75
            dists = (np.abs(cxs - cx_t) + np.abs(cys - cy_t)).astype(float)

        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 7 + pop) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === CIVIC SERVICES ===
    if pop > 20:
        fire_spots = [
            (20, 10), (60, 10), (100, 10),
            (10, 30), (50, 30), (80, 30), (110, 30),
            (20, 50), (100, 50),
            (10, 70), (50, 70), (80, 70), (110, 70),
            (20, 90), (60, 90), (100, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 40), (45, 40), (75, 40), (105, 40),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 88), (45, 88), (75, 88), (105, 88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        for sx, sy in [(35, 35), (85, 35), (35, 65), (85, 65),
                       (55, 20), (55, 80), (10, 50), (110, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        for nx2, ny2 in [(30, 15), (90, 15), (30, 85), (90, 85),
                         (10, 50), (110, 50)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for sx, sy in [(5, 93), (115, 93), (5, 7), (115, 7)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for sx, sy in [(48, 5), (72, 5), (48, 93), (72, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near dense zones
    if pop > 200 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[:2, :] = False
        park_cands[WORLD_H - 2:, :] = False
        park_cands[:, :2] = False
        park_cands[:, WORLD_W - 2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # === FALLBACK: extend wire from existing wire ===
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 80)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + cross wire spines + road grid"""
    actions = []
    # Two coal plants on opposite sides
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at x=20, x=60, x=100
    for y in range(1, 99):
        actions.append((Tool.WIRE, 20, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 100, y))
    # Roads parallel to wire spine (for zone access)
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Horizontal roads crossing vertical wire spines
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 30))
        actions.append((Tool.ROAD, x, 70))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio strategy: aim for ~40% RES, ~35% COM, ~25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            # Bootstrap: balanced start
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 500:
            if ir < 0.22:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 2000:
            # More commercial helps growth
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            # At high pop, focus on residential + commercial
            if cr < 0.38:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.17:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PHASE 1: Add more power plants to underserved regions ===
    if step % 8 == 0:
        # Check a tighter grid of positions every ~15 tiles
        for py in range(10, WORLD_H - 5, 15):
            for px in range(10, WORLD_W - 5, 15):
                x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
                y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
                if not np.any(pm[y0:y1, x0:x1]):
                    for r in range(0, 5):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 2: Extend wire toward unpowered zones ===
    if step % 8 == 1:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                best_dist = 999999
                best_zone = None
                sample = min(len(uz_xs), 20)
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # === PHASE 3: Extend wire into empty unpowered regions ===
    if step % 8 == 2:
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False

        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            unpowered_empty = em & ~near_power & ~zone_tiles
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                best_dist = 1e9
                best_k = 0
                sample_indices = np.linspace(0, len(upxs) - 1, min(20, len(upxs)), dtype=int)
                for i in range(min(len(wxs), 200)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_indices)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # === PHASE 4: Build road grid (denser, every 4-5 tiles) ===
    if step % 8 == 3:
        # Connect unroaded zones first
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

        # Dense road grid: every 5 tiles horizontally and vertically
        road_grid_targets = []
        for gy in range(5, 97, 5):
            for gx in range(5, 115, 5):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        if road_grid_targets:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted

            road_cand = em & adj_to_road & near_power & ~zone_tiles
            road_cand[0:2, :] = False
            road_cand[WORLD_H - 2:, :] = False
            road_cand[:, 0:2] = False
            road_cand[:, WORLD_W - 2:] = False

            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                best_dist = 1e9
                best_k = 0
                targets_sample = road_grid_targets[:30]
                for i in range(min(len(rxs2), 300)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
            else:
                for gx, gy in road_grid_targets[:10]:
                    if bool(em[gy, gx]):
                        return (Tool.ROAD, gx, gy)

    # === PHASE 5: Civic services — scale with population ===
    if step % 8 == 4:
        # Fire stations every 12 tiles
        if pop > 20:
            fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 12)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        # Police stations every 14 tiles
        if pop > 100:
            police_grid = [(px2, py2) for py2 in range(12, 90, 14) for px2 in range(12, 110, 14)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if step % 8 == 5:
        # Stadiums boost residential zones significantly
        if pop > 400:
            stadium_locs = [
                (25, 20), (60, 20), (95, 20),
                (25, 50), (60, 50), (95, 50),
                (25, 80), (60, 80), (95, 80),
            ]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        # Nuclear power for denser power coverage
        if pop > 600:
            nuke_locs = [
                (10, 10), (60, 10), (110, 10),
                (10, 50), (110, 50),
                (10, 90), (60, 90), (110, 90),
                (35, 30), (85, 30), (35, 70), (85, 70),
            ]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 5), min(WORLD_W, nx2 + 6)
                    y0, y1 = max(0, ny2 - 5), min(WORLD_H, ny2 + 6)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        # Parks spread along the road network
        if pop > 300 and step % 12 == 5:
            park_cands = em & near_road & near_power
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 29 + pop * 11) % len(pxs3)
                px2, py2 = int(pxs3[idx]), int(pys3[idx])
                if not bool(zone_tiles[py2, px2]):
                    return (Tool.PARK, px2, py2)

        if pop > 1200:
            airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        if pop > 1800:
            seaport_locs = [(5, 45), (5, 55), (115, 45), (115, 55), (60, 5), (60, 95)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # === PHASE 6: Zone placement — fill map with well-served zones ===
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Prefer spots close to road and spread from existing zones
        score = road_dist * 1.5 + np.maximum(0, 6 - zone_dist) * 1.5

        order = np.argsort(score)
        # Vary starting offset per step and population to cover different spots
        off = (step * 11 + pop * 5) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Compact grid city: 6x6 neighborhoods with coal plants, wire grid, and road network
# Key differences from parent:
# 1. Simpler, more reliable wire routing (Manhattan path between plants)
# 2. Zone mix: 50% RES, 25% COM, 25% IND
# 3. Neighborhoods on a 18-tile grid for better spacing
# 4. Direct wire connections between all plants first
# 5. Roads as a proper grid, not just flanking wires

def init(obs, state):
    """Bootstrap: two coal plants with cross wires and starter roads."""
    acts = []
    # Two central plants
    acts.append((Tool.COALPOWER, 40, 45))
    acts.append((Tool.COALPOWER, 78, 45))
    # Wire between them along row 45
    for x in range(41, 78):
        acts.append((Tool.WIRE, x, 45))
    # Roads flanking the wire spine
    for x in range(38, 82):
        acts.append((Tool.ROAD, x, 44))
        acts.append((Tool.ROAD, x, 46))
    return acts[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count + 1

    # Grid of neighborhoods: 6 cols x 5 rows, spaced 18 tiles apart
    nh_cols = list(range(12, 115, 18))  # 12,30,48,66,84,102 -> 6 cols
    nh_rows = list(range(12, 95, 18))   # 12,30,48,66,84 -> 5 rows
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Scale active hoods with population
    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 14
        if pop < 1000:  return 20
        if pop < 2000:  return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick hoods spread across map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE EACH ACTIVE HOOD HAS A NEARBY PLANT ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            nearby = int(np.sum(zone_tiles[y0:y1, x0:x1]))
            tool_p = Tool.NUCLEARPOWER if (nearby > 15 and funds > 8000) else Tool.COALPOWER
            # Try to place plant at hood center or nearby empty
            for r in range(0, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r and r > 0:
                            continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (tool_p, nx, ny)

    # ---- PHASE 2: WIRE SPINES - vertical and horizontal through each hood ----
    spine_r = 8
    # Build wire cross through each hood, extending from existing powered tiles
    for (hx, hy) in active_hoods:
        # Vertical arm
        for dy in range(-spine_r, spine_r+1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Check if adjacent tile is powered
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal arm
        for dx in range(-spine_r, spine_r+1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adx in [-1, 1]:
                ax = wx + adx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT HOODS WITH WIRE (horizontal then vertical) ----
    # Horizontal connections along shared rows
    row_to_hx = {}
    for (hx, hy) in active_hoods:
        row_to_hx.setdefault(hy, []).append(hx)
    for hy, hxs in row_to_hx.items():
        for i in range(len(hxs)-1):
            hx1, hx2 = sorted(hxs)[i], sorted(hxs)[i+1]
            for cx in range(hx1+1, hx2):
                if not ib(cx, hy): continue
                if bool(wm[hy, cx]) or bool(pm[hy, cx]): continue
                if not bool(em[hy, cx]): continue
                for adx in [-1, 1]:
                    ax = cx + adx
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, cx, hy)

    # Vertical connections along shared cols
    col_to_hy = {}
    for (hx, hy) in active_hoods:
        col_to_hy.setdefault(hx, []).append(hy)
    for hx, hys in col_to_hy.items():
        for i in range(len(hys)-1):
            hy1, hy2 = sorted(hys)[i], sorted(hys)[i+1]
            for cy in range(hy1+1, hy2):
                if not ib(hx, cy): continue
                if bool(wm[cy, hx]) or bool(pm[cy, hx]): continue
                if not bool(em[cy, hx]): continue
                for ady in [-1, 1]:
                    ay = cy + ady
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, cy)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    # Road at hx-1 and hx+1 (vertical corridors), hy-1 and hy+1 (horizontal)
    for (hx, hy) in active_hoods:
        for rx in [hx-1, hx+1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_r, spine_r+1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]): continue
                if bool(pm[ry, rx]): continue
                # Only place road if wire spine exists nearby
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)
        for ry2 in [hy-1, hy+1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_r, spine_r+1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]): continue
                if bool(pm[ry2, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0=max(0,-dy2); sr1=min(WORLD_H,WORLD_H-dy2)
            sc0=max(0,-dx2); sc1=min(WORLD_W,WORLD_W-dx2)
            r0=max(0,dy2);   r1=min(WORLD_H,WORLD_H+dy2)
            c0=max(0,dx2);   c1=min(WORLD_W,WORLD_W+dx2)
            nbr_road[r0:r1,c0:c1] |= rm[sr0:sr1,sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0=max(0,-dy2); sr1=min(WORLD_H,WORLD_H-dy2)
            sc0=max(0,-dx2); sc1=min(WORLD_W,WORLD_W-dx2)
            r0=max(0,dy2);   r1=min(WORLD_H,WORLD_H+dy2)
            c0=max(0,dx2);   c1=min(WORLD_W,WORLD_W+dx2)
            nbr_power[r0:r1,c0:c1] |= wm[sr0:sr1,sc0:sc1]
            nbr_power[r0:r1,c0:c1] |= pm[sr0:sr1,sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    # Keep margin from edges
    cand_mask[0:2,:]=False; cand_mask[WORLD_H-2:,:]=False
    cand_mask[:,0:2]=False; cand_mask[:,WORLD_W-2:]=False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset*7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(nbr_power[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [
            (20,20),(50,20),(80,20),(110,20),
            (20,50),(50,50),(80,50),(110,50),
            (20,80),(50,80),(80,80),(110,80),
        ]
        for (sx,sy) in fire_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (30,15),(60,15),(90,15),
            (15,40),(45,40),(75,40),(105,40),
            (30,65),(60,65),(90,65),
            (15,88),(45,88),(75,88),(105,88),
        ]
        for (sx,sy) in police_spots:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (25,25),(65,25),(105,25),
            (25,60),(65,60),(105,60),
            (25,90),(65,90),(105,90),
        ]
        for (sx,sy) in stadiums:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(5,90),(115,90),(5,5),(115,5)]
        for (sx,sy) in seaports:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40,5),(80,5),(40,93),(80,93)]
        for (sx,sy) in airports:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: PARKS ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 29) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: extend wire ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        sk = (step * 13) % len(wire_xs)
        for offset in range(min(len(wire_xs), 100)):
            k = (sk + offset*5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3,dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3,ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant near uncovered hood ----
    for (hx,hy) in active_hoods:
        if not bool(nbr_power[hy,hx]):
            for r in range(1,10):
                for dy in range(-r,r+1):
                    for dx in range(-r,r+1):
                        if abs(dx)==r or abs(dy)==r:
                            nx,ny = hx+dx, hy+dy
                            if ib(nx,ny) and bool(em[ny,nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spines + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the wire spines
    for dy in range(-9, 10):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-9, 10):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Neighborhood centers - 5 cols x 4 rows = 20 hoods
    nh_cols = [12, 35, 60, 85, 108]
    nh_rows = [12, 38, 62, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 100:   return 4
        if pop < 400:   return 8
        if pop < 1000:  return 12
        if pop < 2000:  return 16
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / n_active
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Build neighbor masks for power and road proximity
    power_src = wm | pm

    def dilate(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2 in range(-radius, radius + 1):
            for dx2 in range(-radius, radius + 1):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_power = dilate(power_src, 6)
    nbr_road = dilate(rm, 3)

    # PHASE 1: Ensure each active hood has a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Wire from plants toward hood centers (reactive: read plant positions)
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine_range = 14

    x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
    y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0

        # Wire from plant toward hood (vertical leg)
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        # Wire from plant toward hood (horizontal leg)
        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

        # Extend vertical spine from hood
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Extend horizontal spine from hood
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # PHASE 3: Roads flanking wire spines (reactive: check wire positions)
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    # Roads flanking vertical wire at hx3
    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    # Roads flanking horizontal wire at hy3
    for ry2 in [hy3 - 1, hy3 + 1]:
        if not ib(hx3, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # PHASE 4: Connect hoods with wires
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 30:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx + 1, mxx):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and abs(hy2 - hy1) <= 30:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny + 1, mxy):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # PHASE 5: Zone placement (reactive to road+power availability)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 30% com, 30% ind
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 6: Extend roads into powered areas (reactive)
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # PHASE 7: Civic services (reactive to population)
    if pop > 150:
        fire_spots = [(fx, fy) for fx in range(14, WORLD_W, 18) for fy in range(14, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(18, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(24, 25), (96, 25), (24, 75), (96, 75),
                    (60, 15), (60, 85), (12, 50), (108, 50),
                    (48, 50), (72, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6, 94), (114, 94), (6, 6), (114, 6), (60, 97), (60, 3)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 5), (80, 5), (40, 94), (80, 94),
                    (5, 40), (5, 70), (114, 40), (114, 70)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrade for mature cities
    if pop > 2500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (12, 12), (108, 12), (12, 88), (108, 88),
                         (35, 38), (85, 38), (35, 62), (85, 62),
                         (60, 25), (60, 75), (25, 50), (95, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value (reactive: place where road+power exists)
    if pop > 300 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire from existing wire/plant
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new plant at uncovered hood
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending from plant
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads around center (offset by 2 from wire spine)
    for d in range(-8, 9):
        actions.append((Tool.ROAD, cx - 2, cy + d))
        actions.append((Tool.ROAD, cx + 2, cy + d))
        actions.append((Tool.ROAD, cx + d, cy - 2))
        actions.append((Tool.ROAD, cx + d, cy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID ----
    # Dense grid of hood centers; unlock more as population grows
    all_hoods = []
    for hy in range(12, 95, 14):
        for hx in range(12, 115, 14):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 42
        if pop < 7000:  return 56
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # ---- POWER/ROAD COVERAGE MAPS (efficient dilation) ----
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        src = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= src[:-d, :]
            result[:-d, :] |= src[d:, :]
            result[:, d:] |= src[:, :-d]
            result[:, :-d] |= src[:, d:]
        return result

    nbr_power = dilate(wm | pm, 5)
    nbr_road = dilate(rm, 2)

    # ---- TOOL SELECTION ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- ZONE CLEAR CHECK ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: POWER PLANTS for active hoods ----
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 12):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # ---- PHASE 2: WIRE SPINES for active hoods ----
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical wire spine at column hx
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy):
            continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]):
            continue
        if not bool(em[wy, hx]):
            continue
        # Check if adjacent to existing wire/plant
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal wire spine at row hy
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy):
            continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]):
            continue
        if not bool(em[hy, wx]):
            continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for i_h in range(min(len(active_hoods), 8)):
        hx1, hy1 = active_hoods[(hood_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            # Horizontal connection (same approximate row)
            if abs(hy2 - hy1) <= 2 and 4 <= abs(hx2 - hx1) <= 20 and hx2 > hx1:
                mid_y = (hy1 + hy2) // 2
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y):
                        continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]):
                        continue
                    if not bool(em[mid_y, cx2]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Vertical connection (same approximate col)
            if abs(hx2 - hx1) <= 2 and 4 <= abs(hy2 - hy1) <= 18 and hy2 > hy1:
                mid_x = (hx1 + hx2) // 2
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2):
                        continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]):
                        continue
                    if not bool(em[cy2, mid_x]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx]

    # Roads flanking vertical spine (offset ±2)
    for rx in [hx - 2, hx + 2]:
        if not ib(rx, hy):
            continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry):
                continue
            if bool(rm[ry, rx]):
                continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]):
                continue
            if bool(pm[ry, rx]):
                continue
            if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                return (Tool.ROAD, rx, ry)

    # Roads flanking horizontal spine (offset ±2)
    for ry2 in [hy - 2, hy + 2]:
        if not ib(hx, ry2):
            continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2):
                continue
            if bool(rm[ry2, rcx]):
                continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]):
                continue
            if bool(pm[ry2, rcx]):
                continue
            if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus: proximity to existing zones
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(12, 95, 16)
                     for fx in range(12, 115, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_grid = [(px2, py2) for py2 in range(14, 90, 18)
                       for px2 in range(14, 110, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 4 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 19 + pop) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700 and funds > 4000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1000:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (50, 6), (80, 6), (50, 93), (80, 93)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plant ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new plant near unpowered active hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 12):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

