def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    cx, cy = 60, 50

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Adaptive radius
    if pop < 200:
        max_radius = 20
    elif pop < 800:
        max_radius = 35
    elif pop < 2000:
        max_radius = 55
    else:
        max_radius = 75

    # --- Precompute neighbor masks ---
    # Road neighbor within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor within 5 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Distance from center
    ys_arr = np.arange(WORLD_H).reshape(-1, 1)
    xs_arr = np.arange(WORLD_W).reshape(1, -1)
    dist_arr = np.abs(ys_arr - cy) + np.abs(xs_arr - cx)

    # Zone type selection - balanced with early industry push
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Need industry early for jobs/demand
        if pop < 300 and ir < 0.35:
            return Tool.INDUSTRIAL
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PHASE 1: Power plants ===
    plant_count = int(np.sum(pm))

    # Place extra coal plants as population grows
    if pop > 300 and plant_count < 2:
        candidates = [(45, 50), (75, 35), (45, 65), (75, 65)]
        for px, py in candidates:
            if ib(px, py) and bool(em[py, px]):
                # Check area is mostly clear
                clear = all(
                    ib(px+dx, py+dy) and bool(em[py+dy, px+dx])
                    for dx in range(-1,2) for dy in range(-1,2)
                )
                if clear:
                    return (Tool.COALPOWER, px, py)

    if pop > 800 and plant_count < 3:
        for px, py in [(40, 35), (80, 35), (40, 65), (80, 65), (30, 50), (90, 50)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    if pop > 2000 and plant_count < 5:
        for px, py in [(20, 25), (100, 25), (20, 75), (100, 75)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # === PHASE 2: Wire extension (reactive - extend from existing wire/plant) ===
    # Find frontier: empty cells adjacent to existing wire/plant within radius
    if step % 3 == 0:
        # Wire grid corridors: horizontal every 8 rows, vertical every 8 cols
        # Prioritize extending existing wire connectivity
        wire_ys, wire_xs = np.where((wm | pm) & (dist_arr <= max_radius + 10))
        if len(wire_xs) > 0:
            # Look for empty neighbors to extend wire toward zones
            best = None
            best_dist = 1e9
            sk = (step * 7) % len(wire_xs)
            for i in range(min(len(wire_xs), 100)):
                k = (sk + i) % len(wire_xs)
                wx, wy = int(wire_xs[k]), int(wire_ys[k])
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx, ny = wx+dx, wy+dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        d = int(dist_arr[ny, nx])
                        if d <= max_radius + 15 and d < best_dist:
                            best_dist = d
                            best = (Tool.WIRE, nx, ny)
            if best:
                return best

    # === PHASE 3: Road network (reactive - extend from existing roads) ===
    # Build a grid: horizontal roads every 4 rows, vertical every 6 cols
    if step % 3 == 1:
        # Prioritize road placement near wire/power for zone access
        # Horizontal roads at regular intervals
        road_ys_list = list(range(28, 73, 4))
        for ry in road_ys_list:
            if abs(ry - cy) > max_radius:
                continue
            x_range = min(max_radius, WORLD_W // 2)
            for rx in range(max(2, cx - x_range), min(WORLD_W - 2, cx + x_range)):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Extend from existing road
                    adj = (ib(rx-1, ry) and bool(rm[ry, rx-1])) or (ib(rx+1, ry) and bool(rm[ry, rx+1]))
                    if adj and bool(nbr_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif step % 3 == 2:
        # Vertical roads
        road_xs_list = list(range(36, 85, 6))
        for rxc in road_xs_list:
            if abs(rxc - cx) > max_radius:
                continue
            y_range = min(max_radius, WORLD_H // 2)
            for ry in range(max(2, cy - y_range), min(WORLD_H - 2, cy + y_range)):
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    adj = (ib(rxc, ry-1) and bool(rm[ry-1, rxc])) or (ib(rxc, ry+1) and bool(rm[ry+1, rxc]))
                    if adj and bool(nbr_power[ry, rxc]):
                        return (Tool.ROAD, rxc, ry)

    # === PHASE 4: Zone placement (primary action) ===
    cand_mask = em & nbr_road & nbr_power & (dist_arr <= max_radius)
    # Keep safe margins
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr2, cxs_arr2 = np.where(cand_mask)
    if len(cxs_arr2) > 0:
        dists = dist_arr[cys_arr2, cxs_arr2]
        order = np.argsort(dists)
        tool = pick_tool()
        # Use step-based offset for variety but still prefer compact
        offset = (step * 5) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr2[k]), int(cys_arr2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === CIVIC SERVICES (reactive to population) ===
    if pop > 100:
        fire_spots = [
            (48, 38), (72, 38), (48, 62), (72, 62),
            (60, 34), (60, 66), (36, 50), (84, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (52, 42), (68, 42), (52, 58), (68, 58),
            (44, 50), (76, 50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for sx, sy in [(58, 44), (62, 44), (58, 56), (62, 56)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for sx, sy in [(10, 85), (110, 85), (10, 15), (110, 15)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        for sx, sy in [(15, 50), (105, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 200 and step % 9 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power & (dist_arr <= max_radius))
        if len(park_xs) > 0:
            idx = (step * 13) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # === FALLBACKS ===
    # Extend roads from existing road network toward powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 60)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            if int(dist_arr[ry2, rx2]) > max_radius + 5:
                continue
            for dx, dy in [(0,1),(1,0),(0,-1),(-1,0)]:
                nx, ny = rx2+dx, ry2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if bool(nbr_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # Extend wire from existing wire/plant
    wire_ys2, wire_xs2 = np.where(wm | pm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 60)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx2+dx, wy2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if int(dist_arr[ny, nx]) <= max_radius + 15:
                        return (Tool.WIRE, nx, ny)

    # Emergency: place coal plant near center if no power
    if not bool(nbr_power[cy, cx]):
        for r in range(1, 10):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = cx+dx, cy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

