def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 6

    # === PHASE 0: Ensure power plants across map ===
    if phase == 0:
        # Place coal plants on a grid every 20 tiles if none nearby
        plant_positions = []
        for py in range(15, WORLD_H - 5, 20):
            for px in range(15, WORLD_W - 5, 20):
                plant_positions.append((px, py))
        for px, py in plant_positions:
            x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
            y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 1: Extend wire toward unpowered zones ===
    if phase == 1:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                best_dist = 999999
                best_zone = None
                sample = min(len(uz_xs), 30)
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

        # Extend wire toward unpowered empty regions
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False

        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            unpowered_empty = em & ~near_power & ~zone_tiles
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                best_dist2 = 1e9
                best_k = 0
                sample_indices = np.linspace(0, len(upxs) - 1, min(30, len(upxs)), dtype=int)
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_indices)
                    if d < best_dist2:
                        best_dist2 = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # === PHASE 2: Build road grid and connect zones to roads ===
    if phase == 2:
        # Connect unroaded zones to road
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

        # Extend road grid every 6 tiles in powered areas
        road_grid_targets = []
        for gy in range(6, 97, 6):
            for gx in range(6, 115, 6):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        if road_grid_targets:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted

            road_cand = em & adj_to_road & near_power & ~zone_tiles
            road_cand[0:2, :] = False
            road_cand[WORLD_H - 2:, :] = False
            road_cand[:, 0:2] = False
            road_cand[:, WORLD_W - 2:] = False

            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                best_dist3 = 1e9
                best_k3 = 0
                targets_sample = road_grid_targets[:30]
                for i in range(min(len(rxs2), 400)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist3:
                        best_dist3 = d
                        best_k3 = i
                return (Tool.ROAD, int(rxs2[best_k3]), int(rys2[best_k3]))
            else:
                for gx, gy in road_grid_targets[:10]:
                    if bool(em[gy, gx]):
                        return (Tool.ROAD, gx, gy)

    # === PHASE 3: Civic services ===
    if phase == 3:
        if pop > 25:
            fire_grid = [(fx, fy) for fy in range(10, 95, 15) for fx in range(10, 115, 15)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        if pop > 150:
            police_grid = [(px2, py2) for py2 in range(15, 90, 18) for px2 in range(15, 110, 18)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        if pop > 300 and step % 8 == 3:
            park_cands = em & near_road & near_power & ~zone_tiles
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 31 + pop) % len(pxs3)
                return (Tool.PARK, int(pxs3[idx]), int(pys3[idx]))

        if pop > 500:
            stadium_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                            (60, 50), (15, 50), (105, 50), (60, 15), (60, 85)]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        if pop > 800:
            nuke_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                         (60, 10), (60, 90), (10, 50), (110, 50),
                         (35, 15), (85, 15), (35, 85), (85, 85)]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                    y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        if pop > 2000:
            seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 94)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # === PHASE 4 & 5: Zone placement (main loop) ===
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        # Score candidates: close to road, spread away from existing zones
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Prefer close to road, prefer spreading out from existing zones
        score = road_dist * 1.0 + np.maximum(0, 8 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Compact, well-powered city builder with a different strategy:
# - Two coal plants connected by a wire backbone
# - Dense road grid (every 4 tiles) for maximum zone coverage
# - Balanced zone mix: ~50% residential, ~25% commercial, ~25% industrial
# - Civic services placed proactively
# - Fully closed-loop: reads tile_map every step

def init(obs, state):
    """Bootstrap: two coal plants + wire backbone + seed roads."""
    actions = []
    # Plant 1: left-center
    actions.append((Tool.COALPOWER, 30, 50))
    # Plant 2: right-center
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire backbone connecting both plants at y=50
    for x in range(28, 93):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire at x=30 and x=90
    for y in range(45, 56):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Seed roads parallel to backbone
    for x in range(28, 93, 4):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- DETERMINE ACTIVE BUILD AREA based on population ----
    # Expand outward from center as pop grows
    if pop < 100:
        x_min, x_max, y_min, y_max = 20, 100, 35, 65
    elif pop < 500:
        x_min, x_max, y_min, y_max = 10, 110, 25, 75
    elif pop < 2000:
        x_min, x_max, y_min, y_max = 5, 115, 15, 85
    else:
        x_min, x_max, y_min, y_max = 3, 117, 5, 95

    # ---- ENSURE WIRE BACKBONE covers build area ----
    # Horizontal wire spine at y=50 from x_min to x_max
    spine_y = 50
    for bx in range(x_min, x_max + 1):
        if ib(bx, spine_y) and not bool(pm[spine_y, bx]) and not bool(wm[spine_y, bx]) and not bool(rm[spine_y, bx]):
            if bool(em[spine_y, bx]):
                return (Tool.WIRE, bx, spine_y)

    # Vertical wire spines at x=30, x=60, x=90
    for vx in [30, 60, 90]:
        if not ib(vx, spine_y):
            continue
        for vy in range(y_min, y_max + 1):
            if ib(vx, vy) and not bool(pm[vy, vx]) and not bool(wm[vy, vx]) and bool(em[vy, vx]):
                return (Tool.WIRE, vx, vy)

    # ---- ENSURE ADDITIONAL COAL PLANTS as city grows ----
    plant_positions = []
    if pop > 1000:
        plant_positions = [(30, 25), (90, 25), (30, 75), (90, 75), (60, 50)]
    elif pop > 300:
        plant_positions = [(30, 50), (90, 50), (60, 50)]
    else:
        plant_positions = [(30, 50), (90, 50)]

    for (px, py) in plant_positions:
        if ib(px, py):
            x0, x1 = max(0, px - 3), min(WORLD_W, px + 4)
            y0, y1 = max(0, py - 3), min(WORLD_H, py + 4)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                if bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)

    # ---- BUILD ROAD GRID every 4 tiles ----
    # Horizontal roads at y = y_min, y_min+4, ...
    # Vertical roads at x = x_min, x_min+4, ...
    road_ys = list(range(y_min, y_max + 1, 4))
    road_xs = list(range(x_min, x_max + 1, 4))

    # Stagger road building with step
    road_step = step % max(len(road_ys) + len(road_xs), 1)

    # Build horizontal roads
    for i, ry in enumerate(road_ys):
        if (i + step) % 2 == 0:
            for rx in range(x_min, x_max + 1):
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Build vertical roads
    for i, rx in enumerate(road_xs):
        if (i + step) % 2 == 1:
            for ry in range(y_min, y_max + 1):
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Power proximity: near wire or plant
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Road proximity
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in [-2, -1, 0, 1, 2]:
        for dx2 in [-2, -1, 0, 1, 2]:
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Candidate zone spots: empty, near road, near power, inside bounds
    cand = em & nbr_road & nbr_power
    cand[:3, :] = False; cand[WORLD_H-3:, :] = False
    cand[:, :3] = False; cand[:, WORLD_W-3:] = False
    # Only in active area
    mask = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    mask[y_min:y_max+1, x_min:x_max+1] = True
    cand &= mask

    cys, cxs = np.where(cand)
    if len(cxs) > 0:
        # Pick candidate closest to a road-grid intersection for density
        # Score = proximity to nearest road_xs x road_ys intersection
        gx = np.array(road_xs)
        gy = np.array(road_ys)
        min_dist = np.full(len(cxs), 999999.0)
        for gxi in gx:
            for gyi in gy:
                d = np.abs(cxs - gxi) + np.abs(cys - gyi)
                min_dist = np.minimum(min_dist, d)

        # Between zones 2 and 6 apart from each other = avoid clustering
        # Use step offset to vary pick
        order = np.argsort(min_dist)
        step_off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 200)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 150:
        fire_spots = [(25, 30), (60, 30), (95, 30), (25, 55), (60, 55), (95, 55),
                      (25, 75), (60, 75), (95, 75)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [(35, 40), (70, 40), (35, 65), (70, 65), (50, 20), (80, 80)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 2000:
        stadiums = [(45, 35), (75, 35), (45, 65), (75, 65)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 4000:
        for (sx, sy) in [(10, 90), (110, 10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 6000:
        for (sx, sy) in [(55, 10), (55, 88)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS near populated zones ----
    if pop > 300 and step % 4 == 0:
        park_cand = np.where(em & nbr_road & nbr_power & mask)
        if len(park_cand[0]) > 0:
            idx = (step * 13) % len(park_cand[0])
            py2, px2 = int(park_cand[0][idx]), int(park_cand[1][idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend roads from existing network ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 20)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plants at key positions, wire grid, flanking roads."""
    actions = []
    # Coal plants at strategic positions
    for px, py in [(20, 25), (80, 25), (50, 50), (20, 75), (80, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 50, 80]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines (above and below)
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Infrastructure grid
    wire_rows = [10, 25, 40, 50, 60, 75, 90]
    wire_cols = [12, 24, 36, 48, 60, 72, 84, 96, 108]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 10

    # Phase 0: Ensure power plants distributed across map
    if phase == 0:
        plant_targets = [(px, py) for py in [12, 30, 50, 70, 88]
                         for px in [15, 40, 60, 85, 110]]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 18), min(WORLD_W, px + 19)
            y0, y1 = max(0, py - 18), min(WORLD_H, py + 19)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill gaps in horizontal wire rows
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill gaps in vertical wire cols
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads above/below horizontal wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                                   (ry > 0 and bool(rm[ry-1, rx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # Phase 4: Roads left/right of vertical wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                                   bool(rm[ry, max(0, rcx-1)]) or
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # Phase 5: Cross streets between wire rows
    if phase == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            for frac in [0.33, 0.5, 0.67]:
                mid_y = int(r1 + (r2 - r1) * frac)
                if not (0 < mid_y < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])) or
                               (mid_y > 0 and bool(rm[mid_y-1, rx])) or
                               (mid_y < WORLD_H-1 and bool(rm[mid_y+1, rx])))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # Phase 6: Cross streets between wire cols
    if phase == 6:
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = int(c1 + (c2 - c1) * 0.5)
            if not (0 < mid_x < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])) or
                           (mid_x > 0 and bool(rm[ry, mid_x-1])) or
                           (mid_x < WORLD_W-1 and bool(rm[ry, mid_x+1])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Phase 7: Wire unpowered zones reactively
    if phase == 7:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Road to unroaded zones reactively
    if phase == 8:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 9: Extend road from existing roads into powered areas
    if phase == 9:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled to population ----
    if pop > 30:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,25),(115,25),(5,50),(115,50),
            (5,75),(115,75),(5,95),(30,95),(60,95),(90,95),(115,95),
            (35,50),(65,50),(95,50),(50,20),(80,20),(50,80),(80,80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 120:
        police_spots = [
            (20,15),(50,15),(80,15),(110,15),
            (20,35),(50,35),(80,35),(110,35),
            (20,55),(50,55),(80,55),(110,55),
            (20,75),(50,75),(80,75),(110,75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(30,20),(90,20),(30,80),(90,80),(60,50),(15,50),(105,50),(60,10),(60,90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,20),(115,20),(5,80),(115,80),
            (30,5),(90,5),(30,95),(90,95),
            (35,50),(85,50),(60,30),(60,70),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5,95),(115,95),(5,5),(115,5),(60,95),(60,5),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45),(5,55),(115,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 6 == 3:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep zones off wire/road infrastructure corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active centers expand outward as population increases
        if pop < 100:
            active_centers = [
                (60,50),(45,50),(75,50),(60,38),(60,62),
                (30,50),(90,50),(60,25),(60,75),
            ]
        elif pop < 500:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 12 + row * 19
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 8 + col * 13
                    cy = 8 + row * 12
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 6 + col * 11
                    cy = 6 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area from existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire network
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: compact central power cluster."""
    actions = []
    # Two coal plants at center-left and center-right
    plants = [(38, 50), (78, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire spines in 4 directions
        for d in range(1, 10):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px - d, py))
            actions.append((Tool.WIRE, px, py + d))
            actions.append((Tool.WIRE, px, py - d))
        # Roads along y±3 flanking horizontal wire
        for d in range(-8, 9):
            actions.append((Tool.ROAD, px + d, py - 3))
            actions.append((Tool.ROAD, px + d, py + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Want ~40% res, ~30% com, ~30% ind
        if ind_count / total_zones < 0.28:
            return Tool.INDUSTRIAL
        if com_count / total_zones < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Anchor grid - more anchors as city grows
    all_anchors = []
    for ax in [20, 40, 60, 80, 100]:
        for ay in [20, 38, 56, 74, 88]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 2
        if pop < 200:  return 4
        if pop < 400:  return 6
        if pop < 700:  return 10
        if pop < 1200: return 15
        if pop < 2000: return 20
        return len(all_anchors)

    active_anchors = all_anchors[:num_active()]

    # ---- POWER PLANT near each anchor if missing ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 14); y1 = min(WORLD_H, ay + 15)
        x0 = max(0, ax - 14); x1 = min(WORLD_W, ax + 15)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find nearest empty cell for a coal plant
            for r in range(2, 15):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE: extend from existing wire/plant toward anchors ----
    # Build horizontal wire spine through each anchor row
    for (ax, ay) in active_anchors:
        hw = min(20, 6 + pop // 20)
        for cx in range(max(2, ax - hw), min(WORLD_W-2, ax + hw + 1)):
            if not ib(cx, ay): continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]): continue
            # Only extend if adjacent to existing wire/plant
            adj = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj = True; break
            if adj and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    # Vertical wire spines
    for (ax, ay) in active_anchors:
        vw = min(15, 5 + pop // 25)
        for cy in range(max(2, ay - vw), min(WORLD_H-2, ay + vw + 1)):
            if not ib(ax, cy): continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]): continue
            adj = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj = True; break
            if adj and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # Connect wire spines vertically between anchors in same column
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i+1]
            for cy in range(y1+1, y2):
                if not ib(col_x, cy): continue
                if bool(wm[cy, col_x]) or bool(pm[cy, col_x]): continue
                adj = ((ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or
                       (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x]))))
                if adj and bool(em[cy, col_x]):
                    return (Tool.WIRE, col_x, cy)

    # ---- ROAD BUILDING: roads flanking wire spines at offset ±3 ----
    for (ax, ay) in active_anchors:
        hw = min(20, 6 + pop // 20)
        for road_off in [-3, 3]:
            road_y = ay + road_off
            if not ib(ax, road_y): continue
            for cx in range(max(2, ax - hw), min(WORLD_W-2, ax + hw + 1)):
                if not ib(cx, road_y): continue
                if not bool(em[road_y, cx]) or bool(pm[road_y, cx]): continue
                adj_road = any(ib(cx+ddx, road_y) and bool(rm[road_y, cx+ddx]) for ddx in [-1, 1])
                near_wire = (ib(cx, road_y-1) and (bool(wm[road_y-1, cx]) or bool(pm[road_y-1, cx]))) or \
                            (ib(cx, road_y+1) and (bool(wm[road_y+1, cx]) or bool(pm[road_y+1, cx])))
                if adj_road or near_wire:
                    return (Tool.ROAD, cx, road_y)

    # Vertical roads flanking vertical wire
    for (ax, ay) in active_anchors:
        vw = min(15, 5 + pop // 25)
        for road_off in [-3, 3]:
            road_x = ax + road_off
            if not ib(road_x, ay): continue
            for cy in range(max(2, ay - vw), min(WORLD_H-2, ay + vw + 1)):
                if not ib(road_x, cy): continue
                if not bool(em[cy, road_x]) or bool(pm[cy, road_x]): continue
                adj_road = any(ib(road_x, cy+ddy) and bool(rm[cy+ddy, road_x]) for ddy in [-1, 1])
                near_wire = (ib(road_x-1, cy) and (bool(wm[cy, road_x-1]) or bool(pm[cy, road_x-1]))) or \
                            (ib(road_x+1, cy) and (bool(wm[cy, road_x+1]) or bool(pm[cy, road_x+1])))
                if adj_road or near_wire:
                    return (Tool.ROAD, road_x, cy)

    # ---- ZONE PLACEMENT ----
    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy+dr, zx+dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]): return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Cycle through candidates using step to avoid repetition
        n_top = max(1, len(order) // 4)
        step_off = (step * 5) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            if i < n_top:
                k = order[i]
            else:
                k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = []
        for (ax, ay) in active_anchors:
            fire_spots.append((ax - 6, ay - 6))
            fire_spots.append((ax + 6, ay + 6))
        fire_spots += [(8, 10), (30, 10), (55, 10), (80, 10), (105, 10),
                       (8, 50), (55, 50), (105, 50),
                       (8, 88), (30, 88), (55, 88), (80, 88), (105, 88)]
        for (sx, sy) in fire_spots:
            sx, sy = int(sx), int(sy)
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = []
        for (ax, ay) in active_anchors:
            police_spots.append((ax + 6, ay - 6))
            police_spots.append((ax - 6, ay + 6))
        police_spots += [(12, 25), (38, 25), (62, 25), (88, 25), (112, 25),
                         (12, 65), (38, 65), (62, 65), (88, 65), (112, 65)]
        for (sx, sy) in police_spots:
            sx, sy = int(sx), int(sy)
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        for (sx, sy) in [(20, 5), (60, 5), (100, 5), (20, 93), (60, 93), (100, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        for (nx2, ny2) in [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5), (60, 94)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for (ax2, ay2) in [(55, 6), (5, 50), (115, 50), (55, 93)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2500:
        for (sx2, sy2) in [(5, 93), (115, 93), (60, 97)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 100:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 40)):
                k = (step * 7 + i * 13) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2+dx2, zy2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near wire ----
    wire_ys3, wire_xs3 = np.where(wm | pm)
    if len(wire_xs3) > 0:
        k = (step * 23) % max(len(wire_xs3), 1)
        wx3, wy3 = int(wire_xs3[k]), int(wire_ys3[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx3, ny3 = wx3+dx3, wy3+dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

# Simplified, focused city builder
# Key differences from parent:
# 1. Single dense cluster instead of spreading thin
# 2. Build wire/road grid FIRST, then fill zones
# 3. More balanced zone mix (50% res, 25% com, 25% ind)
# 4. React to actual powered_zones count before adding more zones
# 5. Simpler, more reliable infrastructure

def init(obs, state):
    """Bootstrap: two coal plants with basic wire + road network."""
    actions = []
    # Two coal plants side by side
    actions.append((Tool.COALPOWER, 40, 45))
    actions.append((Tool.COALPOWER, 70, 45))
    # Wire connecting them horizontally
    for x in range(41, 70):
        actions.append((Tool.WIRE, x, 45))
    # Wire extending up and down from left plant
    for dy in range(1, 8):
        actions.append((Tool.WIRE, 40, 45 - dy))
        actions.append((Tool.WIRE, 40, 45 + dy))
    # Wire extending up and down from right plant
    for dy in range(1, 8):
        actions.append((Tool.WIRE, 70, 45 - dy))
        actions.append((Tool.WIRE, 70, 45 + dy))
    # Main road at y=47 (below plants)
    for x in range(35, 80):
        actions.append((Tool.ROAD, x, 47))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    road_count = int(np.sum(rm))
    wire_count = int(np.sum(wm))
    plant_count = int(np.sum(pm))

    # Store build phase in state
    if 'phase' not in state:
        state['phase'] = 0
        state['grid_built'] = False
        state['wire_progress'] = 0
        state['road_progress'] = 0

    # ---- DEFINE CITY LAYOUT ----
    # Central dense cluster: 50x40 region centered at (60, 50)
    CX, CY = 60, 50
    # Wire backbone: vertical at x=40,55,70,85; horizontal at y=35,45,55,65
    wire_verts = [38, 52, 68, 82]  # vertical wire columns
    wire_horiz = [33, 43, 53, 63, 73]  # horizontal wire rows
    # Road flanking each wire: roads at wire_vert ± 1
    road_verts = []
    for wv in wire_verts:
        road_verts.extend([wv - 1, wv + 1])
    road_horiz = []
    for wh in wire_horiz:
        road_horiz.extend([wh - 1, wh + 1])

    # ---- PHASE 0: Ensure enough power plants ----
    # Need 1 plant per ~15 zones
    needed_plants = max(2, total_zones // 12 + 1)
    if plant_count < needed_plants and funds > 3000:
        # Try to place plant near cluster
        plant_spots = [
            (38, 25), (68, 25), (38, 75), (68, 75),
            (20, 50), (100, 50), (38, 85), (68, 85),
            (20, 30), (100, 30), (20, 70), (100, 70),
        ]
        for (px, py) in plant_spots:
            if ib(px, py) and bool(em[py, px]):
                # Check no overlap with important infrastructure
                clear = True
                for dy in range(-1, 2):
                    for dx in range(-1, 2):
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and (bool(rm[ny, nx]) or bool(wm[ny, nx])):
                            clear = False
                            break
                if clear:
                    return (Tool.COALPOWER, px, py)

    # ---- PHASE 1: Build wire grid ----
    # Wire vertical spines
    for wx in wire_verts:
        for wy in range(28, 80):
            if not ib(wx, wy): continue
            if bool(pm[wy, wx]): continue  # don't overwrite plants
            if not bool(wm[wy, wx]):
                # Only place if adjacent to existing wire or plant
                adj_powered = False
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = wx+dx, wy+dy
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        adj_powered = True
                        break
                if adj_powered and bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)

    # Wire horizontal spines
    for wy in wire_horiz:
        for wx in range(32, 90):
            if not ib(wx, wy): continue
            if bool(pm[wy, wx]): continue
            if not bool(wm[wy, wx]):
                adj_powered = False
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = wx+dx, wy+dy
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        adj_powered = True
                        break
                if adj_powered and bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)

    # ---- PHASE 2: Build road grid ----
    # Vertical roads flanking wire spines
    road_verts_actual = []
    for wv in wire_verts:
        road_verts_actual.extend([wv - 1, wv + 1])
    for rx in road_verts_actual:
        for ry in range(30, 78):
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]): continue
            if not bool(rm[ry, rx]) and bool(em[ry, rx]):
                # Only extend from existing road
                adj_road = False
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = rx+dx, ry+dy
                    if ib(ax, ay) and bool(rm[ay, ax]):
                        adj_road = True
                        break
                if adj_road:
                    return (Tool.ROAD, rx, ry)

    # Horizontal roads flanking wire rows
    road_horiz_actual = []
    for wh in wire_horiz:
        road_horiz_actual.extend([wh - 1, wh + 1])
    for ry in road_horiz_actual:
        for rx in range(30, 88):
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]) or bool(wm[ry, rx]): continue
            if not bool(rm[ry, rx]) and bool(em[ry, rx]):
                adj_road = False
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = rx+dx, ry+dy
                    if ib(ax, ay) and bool(rm[ay, ax]):
                        adj_road = True
                        break
                if adj_road:
                    return (Tool.ROAD, rx, ry)

    # ---- PHASE 3: ZONE PLACEMENT ----
    def pick_zone_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                # Allow empty or already a zone tile (same zone expanding)
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Zone candidate: empty, near road, near power, safe margins
    cand = em & nbr_road & nbr_power
    cand[0:3, :] = False
    cand[WORLD_H-3:, :] = False
    cand[:, 0:3] = False
    cand[:, WORLD_W-3:] = False
    # Prefer central region
    cand_inner = cand.copy()
    cand_inner[:28, :] = False
    cand_inner[79:, :] = False
    cand_inner[:, :30] = False
    cand_inner[:, 90:] = False

    # Pick candidates, prioritize inner
    for use_mask in [cand_inner, cand]:
        cys, cxs = np.where(use_mask)
        if len(cxs) == 0:
            continue
        # Sort by distance to center
        dist = np.abs(cxs - CX) + np.abs(cys - CY)
        order = np.argsort(dist)
        offset = (step * 3) % max(len(order), 1)
        tool = pick_zone_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 4: CIVIC SERVICES ----
    if pop > 30:
        fire_spots = [(45, 38), (65, 38), (45, 62), (65, 62),
                      (30, 50), (90, 50), (55, 28), (65, 72)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [(50, 35), (70, 35), (50, 65), (70, 65),
                        (35, 50), (85, 50), (60, 30), (60, 70)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500 and funds > 5000:
        stadiums = [(55, 35), (65, 65), (35, 45), (85, 45)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000 and funds > 3000:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000 and funds > 10000:
        airports = [(15, 15), (95, 15), (15, 80), (95, 80)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 5: Extend wire to uncovered areas ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k = (step * 7) % len(wire_xs)
        for offset in range(min(len(wire_xs), 80)):
            k = (step_k + offset * 5) % len(wire_xs)
            wx2, wy2 = int(wire_xs[k]), int(wire_ys[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- PHASE 6: Extend roads into powered empty areas ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 80)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 50 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: place plant near unpowered zone area ----
    if funds > 2000:
        for (hx, hy) in [(55, 50), (65, 50), (55, 40), (65, 40)]:
            if not bool(nbr_power[hy, hx]):
                for r in range(1, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx+dx, hy+dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + flanking roads"""
    actions = []
    # Two central coal plants
    plants = [(30, 50), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for x in range(0, 120):
        for wy in [10, 30, 50, 70, 90]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for y in range(0, 100):
        for wx in [15, 35, 55, 75, 95]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wires
    for x in range(0, 120):
        for wy in [10, 30, 50, 70, 90]:
            for off in [-1, 1]:
                ry = wy + off
                if 0 <= ry < 100:
                    actions.append((Tool.ROAD, x, ry))
    # Roads flanking vertical wires
    for y in range(0, 100):
        for wx in [15, 35, 55, 75, 95]:
            for off in [-1, 1]:
                rx = wx + off
                if 0 <= rx < 120:
                    actions.append((Tool.ROAD, rx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Wire/power spines
    wire_rows = [10, 30, 50, 70, 90]
    wire_cols = [15, 35, 55, 75, 95]

    # Zone tracking
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- CLOSED-LOOP: Reactively repair power grid ----
    # Check if wires are broken on the spines; fix them first
    if step % 8 == 0:
        for wr in wire_rows:
            row = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row[wx]):
                    # Check neighbors for connectivity
                    left = bool(row[max(0, wx-1)])
                    right = bool(row[min(WORLD_W-1, wx+1)])
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    if step % 8 == 1:
        for wc in wire_cols:
            col = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(col[wy]):
                    up = bool(col[max(0, wy-1)])
                    down = bool(col[min(WORLD_H-1, wy+1)])
                    if up or down:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ---- CLOSED-LOOP: Reactively repair road grid ----
    if step % 8 == 2:
        for wr in wire_rows:
            spine = wm[wr, :] | pm[wr, :]
            for off in [-1, 1]:
                ry = wr + off
                if not (0 <= ry < WORLD_H):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(spine[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    if step % 8 == 3:
        for wc in wire_cols:
            spine = wm[:, wc] | pm[:, wc]
            for off in [-1, 1]:
                rcx = wc + off
                if not (0 <= rcx < WORLD_W):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(spine[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # ---- CLOSED-LOOP: Extend road network toward unpowered/unroaded areas ----
    if step % 8 == 4:
        # Find unpowered zones and wire toward them
        unpowered = zone_tiles & ~near_power
        uys, uxs = np.where(unpowered)
        if len(uxs) > 0:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                idx = (step * 17) % len(uxs)
                tx, ty = int(uxs[idx]), int(uys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    if step % 8 == 5:
        # Extend road from existing road tiles near power
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 300)):
                k = (sk + offset * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CLOSED-LOOP: Add coal plants if power coverage is sparse ----
    if step % 8 == 6 and pop < 5000:
        # Find large empty areas far from existing power
        not_powered = em & ~near_power
        nys, nxs = np.where(not_powered)
        if len(nxs) > 100:
            # Pick a random far-from-power spot
            idx = (step * 23) % len(nxs)
            cx, cy = int(nxs[idx]), int(nys[idx])
            # Check if a plant would help
            plant_ys, plant_xs = np.where(pm)
            if len(plant_xs) == 0 or float(np.min(np.abs(plant_xs - cx) + np.abs(plant_ys - cy))) > 30:
                if ib(cx, cy):
                    return (Tool.COALPOWER, cx, cy)

    # ---- ZONE PLACEMENT (main closed-loop decision) ----
    # Candidate tiles: empty, near road, near power
    cand_mask = em & near_road & near_power
    # Protect wire/road spines
    for wr in wire_rows:
        lo, hi = max(0, wr - 1), min(WORLD_H, wr + 2)
        cand_mask[lo:hi, :] = False
    for wc in wire_cols:
        lo, hi = max(0, wc - 1), min(WORLD_W, wc + 2)
        cand_mask[:, lo:hi] = False
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates: prefer near existing zones (for density) and near roads
        # Reactively pick based on current map state
        tool = pick_tool()

        # Score: near existing zones (density bonus) + near power
        near_zone = dilate(zone_tiles, 4)
        # Pick candidates in zone-dense areas first (closed-loop: density-driven)
        scored = np.zeros(len(cxs))
        for i in range(len(cxs)):
            x, y = int(cxs[i]), int(cys[i])
            zone_nearby = bool(near_zone[y, x])
            scored[i] = 1.0 if zone_nearby else 0.0

        # Mix: half the time go dense, half go to uncovered areas
        if step % 2 == 0:
            # Dense placement
            dense_idx = np.where(scored > 0)[0]
            candidates = dense_idx if len(dense_idx) > 0 else np.arange(len(cxs))
        else:
            # Sparse placement (grow frontier)
            sparse_idx = np.where(scored == 0)[0]
            candidates = sparse_idx if len(sparse_idx) > 0 else np.arange(len(cxs))

        offset = (step * 7 + pop * 3) % max(len(candidates), 1)
        checked = 0
        for i in range(len(candidates)):
            k = candidates[(offset + i) % len(candidates)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1500:
                break

    # ---- CIVIC SERVICES (closed-loop: place when pop threshold crossed) ----
    if pop > 100:
        fire_spots = [(12, 20), (45, 20), (80, 20), (110, 20),
                      (12, 60), (45, 60), (80, 60), (110, 60),
                      (12, 85), (45, 85), (80, 85), (110, 85)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(20, 40), (60, 40), (100, 40),
                        (20, 75), (60, 75), (100, 75)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(25, 20), (85, 20), (25, 78), (85, 78)]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuke_spots = [(5, 50), (113, 50), (5, 15), (113, 15), (5, 85), (113, 85)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        seaports = [(5, 93), (110, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 200 and step % 4 == 0:
        park_cand = em & near_road & near_power
        pys, pxs = np.where(park_cand)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire from nearest wire toward center of map if nothing else
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 100)):
            k = (sk2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire backbone + initial roads."""
    actions = []
    # Left cluster power plant at (30, 50)
    actions.append((Tool.COALPOWER, 30, 50))
    # Right cluster power plant at (90, 50)
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire horizontal backbone connecting them
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Wire verticals from each plant
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, 30, 50 + dy))
            actions.append((Tool.WIRE, 90, 50 + dy))
    # Roads flanking left plant spine
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, 29, 50 + dy))
        actions.append((Tool.ROAD, 31, 50 + dy))
    # Roads flanking right plant spine
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, 89, 50 + dy))
        actions.append((Tool.ROAD, 91, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Two neighborhood clusters: left around x=30, right around x=90
    # Each cluster has multiple hood centers spread vertically and horizontally
    left_hoods = [(c, r) for r in [20, 35, 50, 65, 80] for c in [15, 30, 45]]
    right_hoods = [(c, r) for r in [20, 35, 50, 65, 80] for c in [75, 90, 105]]
    all_hoods = left_hoods + right_hoods

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 6
        if pop < 500:   return 10
        if pop < 1000:  return 16
        if pop < 2000:  return 22
        if pop < 4000:  return 30
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT NEAR ACTIVE HOODS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: GROW WIRE TOWARD UNCOVERED HOODS ----
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            for (tx, ty) in uncovered:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy), (dx, dy)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: WIRE SPINES FOR EACH ACTIVE HOOD ----
    spine_range = 10
    hood_cycle = step % max(len(active_hoods), 1)
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Vertical spine
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wy2 = hy + sign * dist
                if not ib(hx, wy2): continue
                if bool(wm[wy2, hx]) or bool(pm[wy2, hx]): continue
                if not bool(em[wy2, hx]): continue
                for ay in [wy2 - 1, wy2 + 1]:
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, wy2)
        # Horizontal spine
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wx2 = hx + sign * dist
                if not ib(wx2, hy): continue
                if bool(wm[hy, wx2]) or bool(pm[hy, wx2]): continue
                if not bool(em[hy, wx2]): continue
                for ax in [wx2 - 1, wx2 + 1]:
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, wx2, hy)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Roads flanking vertical spine
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    ry = hy + sign * dist
                    if not ib(rx, ry): continue
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                            return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    rcx = hx + sign * dist
                    if not ib(rcx, ry2): continue
                    if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                        if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                            return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT (closed-loop ratio targeting) ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target ratios: 40% RES, 35% COM, 25% IND
        # More commercial than parent to differentiate
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS INTO POWERED EMPTY AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive) ----
    if pop > 100:
        for fx in range(10, WORLD_W, 20):
            for fy in range(10, WORLD_H, 20):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 300:
        for px2 in range(15, WORLD_W, 25):
            for py2 in range(15, WORLD_H, 25):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 700:
        for sx in range(20, WORLD_W, 35):
            for sy in range(20, WORLD_H, 35):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(35, 8), (85, 8), (35, 92), (85, 92)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrade when population is high
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(30, 50), (90, 50), (60, 25), (60, 75),
                         (15, 25), (15, 75), (105, 25), (105, 75)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire from existing
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new coal plant near uncovered hood
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Strategy: Dense compact grid city
# Key differences from parent:
# 1. Single central nuclear power plant + extensive wire network
# 2. Grid-based road layout with regular spacing (every 6 tiles)
# 3. More aggressive zone placement targeting road intersections
# 4. Better ratio tracking: 50% RES, 25% COM, 25% IND
# 5. Civic services placed proactively at lower pop thresholds
# 6. Focus on a single large dense cluster rather than 16 neighborhoods

def init(obs, state):
    """Bootstrap: nuclear plant at center + cross wire + initial road grid"""
    actions = []
    # Nuclear plant at center
    actions.append((Tool.NUCLEARPOWER, 60, 50))
    # Wire cross from plant outward
    for x in range(10, 110):
        if x != 60:
            actions.append((Tool.WIRE, x, 50))
    for y in range(5, 95):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    # Main road grid - horizontal roads
    for ry in [44, 56]:
        for rx in range(20, 100):
            actions.append((Tool.ROAD, rx, ry))
    # Main road grid - vertical roads
    for rx in [54, 66]:
        for ry in range(35, 65):
            actions.append((Tool.ROAD, rx, ry))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- ZONE TOOL SELECTION ----
    # Target: 50% RES, 25% COM, 25% IND
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- ENSURE POWER COVERAGE ----
    # Add more coal/nuclear plants if needed based on powered zones
    powered = obs.powered_zones
    if total_zones > 0 and powered < total_zones * 0.6 and step % 5 == 0:
        # Place a coal plant near unpowered zones
        zone_mask = resm | comm | indm
        zone_ys, zone_xs = np.where(zone_mask)
        if len(zone_xs) > 0:
            # Find zone far from power
            for i in range(min(len(zone_xs), 50)):
                k = (step * 7 + i * 3) % len(zone_xs)
                zx, zy = int(zone_xs[k]), int(zone_ys[k])
                # Check if near wire/plant
                x0, x1 = max(0, zx-5), min(WORLD_W, zx+6)
                y0, y1 = max(0, zy-5), min(WORLD_H, zy+6)
                has_power = bool(np.any(wm[y0:y1, x0:x1])) or bool(np.any(pm[y0:y1, x0:x1]))
                if not has_power:
                    # Place coal plant nearby
                    for r in range(2, 8):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx)==r or abs(dy)==r:
                                    nx, ny = zx+dx, zy+dy
                                    if ib(nx, ny) and bool(em[ny, nx]):
                                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE: EXPAND WIRE NETWORK ----
    # Build wire grid: horizontal lines every 6 rows, vertical lines every 6 cols
    # This ensures power reaches all zones

    # Define wire grid lines
    wire_row_spacing = 6
    wire_col_spacing = 6
    wire_rows_set = list(range(8, WORLD_H-8, wire_row_spacing))
    wire_cols_set = list(range(8, WORLD_W-8, wire_col_spacing))

    if step % 4 == 0:
        # Expand horizontal wire grid
        for wr in wire_rows_set:
            for wx in range(2, WORLD_W-2):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    # Check adjacency to existing wire or plant
                    adj = False
                    for adx in [-1, 1]:
                        ax = wx + adx
                        if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                            adj = True
                            break
                    # Also check vertical wire at this col
                    for ady in [-1, 1]:
                        ay = wr + ady
                        if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                            adj = True
                            break
                    if adj and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif step % 4 == 1:
        # Expand vertical wire grid
        for wc in wire_cols_set:
            for wy in range(2, WORLD_H-2):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    adj = False
                    for ady in [-1, 1]:
                        ay = wy + ady
                        if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                            adj = True
                            break
                    for adx in [-1, 1]:
                        ax = wc + adx
                        if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                            adj = True
                            break
                    if adj and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # ---- PHASE: BUILD ROAD NETWORK ----
    # Roads placed 1 row/col offset from wire lines to avoid conflict
    # Road rows at wire_rows + 1 (zone access rows)
    # Road cols at wire_cols + 1

    road_rows = [wr + 1 for wr in wire_rows_set if wr + 1 < WORLD_H - 1]
    road_cols = [wc + 1 for wc in wire_cols_set if wc + 1 < WORLD_W - 1]

    if step % 4 == 2:
        # Build horizontal roads
        for road_y in road_rows:
            for road_x in range(2, WORLD_W-2):
                if bool(em[road_y, road_x]) and not bool(pm[road_y, road_x]):
                    # Only build if adjacent to existing road or at start
                    adj_road = False
                    for adx in [-1, 1]:
                        ax = road_x + adx
                        if ib(ax, road_y) and bool(rm[road_y, ax]):
                            adj_road = True
                            break
                    # Also start road from wire intersections
                    adj_wire = False
                    if bool(wm[road_y-1, road_x]) or bool(pm[road_y-1, road_x]):
                        adj_wire = True
                    if (adj_road or adj_wire) and bool(em[road_y, road_x]):
                        return (Tool.ROAD, road_x, road_y)

    elif step % 4 == 3:
        # Build vertical roads
        for road_x in road_cols:
            for road_y in range(2, WORLD_H-2):
                if bool(em[road_y, road_x]) and not bool(pm[road_y, road_x]):
                    adj_road = False
                    for ady in [-1, 1]:
                        ay = road_y + ady
                        if ib(road_x, ay) and bool(rm[ay, road_x]):
                            adj_road = True
                            break
                    adj_wire = False
                    if ib(road_x-1, road_y) and (bool(wm[road_y, road_x-1]) or bool(pm[road_y, road_x-1])):
                        adj_wire = True
                    if (adj_road or adj_wire) and bool(em[road_y, road_x]):
                        return (Tool.ROAD, road_x, road_y)

    # ---- PHASE: ZONE PLACEMENT ----
    # Build neighbor road mask (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Build neighbor power mask (wire or plant within 4 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to center (prefer denser central city)
        cx_map, cy_map = 60.0, 50.0
        dist_to_center = np.abs(cxs - cx_map) + np.abs(cys - cy_map)
        # Also prefer spots near existing zones (cluster density)
        zone_nbr = np.zeros((WORLD_H, WORLD_W), dtype=np.float32)
        for dy2 in range(-6, 7):
            for dx2 in range(-6, 7):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
                zone_nbr[r0:r1, c0:c1] += zone_tiles[sr0:sr1, sc0:sc1].astype(np.float32)

        zone_bonus = zone_nbr[cys, cxs]
        # Score: prefer center and clustered zones
        score = dist_to_center - zone_bonus * 3.0
        order = np.argsort(score)

        tool = pick_tool()
        # Try top candidates
        offset = (step * 3) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    # Fire stations early (every 20 tiles coverage)
    fire_stations = [
        (20, 20), (50, 20), (80, 20), (110, 20),
        (20, 50), (50, 50), (80, 50), (110, 50),
        (20, 80), (50, 80), (80, 80), (110, 80),
    ]
    if pop > 50:
        for (sx, sy) in fire_stations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_stations = [
            (30, 30), (60, 30), (90, 30),
            (30, 60), (60, 60), (90, 60),
            (30, 90), (60, 90), (90, 90),
        ]
        for (sx, sy) in police_stations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(40, 40), (80, 40), (40, 70), (80, 70)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(10, 85), (105, 85), (10, 15), (105, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(55, 8), (65, 8), (55, 92), (65, 92)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value boost ----
    if pop > 300 and step % 7 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend road from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset2 in range(min(len(road_xs2), 80)):
            k = (step_k + offset2 * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset2 in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset2 * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: add another power plant if we have funds ----
    if funds > 5000 and step % 20 == 0:
        # Place coal plant where there are no nearby plants
        for cy2 in range(10, WORLD_H-10, 20):
            for cx2 in range(10, WORLD_W-10, 20):
                x0, x1 = max(0, cx2-15), min(WORLD_W, cx2+16)
                y0, y1 = max(0, cy2-15), min(WORLD_H, cy2+16)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    if ib(cx2, cy2) and bool(em[cy2, cx2]):
                        return (Tool.COALPOWER, cx2, cy2)

    return None

# Improved city builder: denser grid, better power distribution, balanced zoning
# Key changes from parent:
# - Compact 3x3 neighborhood grid (9 neighborhoods instead of 16)
# - Nuclear plants for more power coverage
# - Stricter R/C/I balance (40% RES, 35% COM, 25% IND)
# - Earlier civic services
# - Better wire connectivity using direct paths between plants

def init(obs, state):
    """Bootstrap: 2 coal plants + central wire cross + initial road grid"""
    actions = []
    # Two coal plants flanking center
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire corridor connecting them through center
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spurs from center
    for y in range(44, 50):
        actions.append((Tool.WIRE, 60, y))
    for y in range(51, 57):
        actions.append((Tool.WIRE, 60, y))
    # Initial road grid around center
    for x in range(50, 71):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(46, 55):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Neighborhood grid: 3x3 arrangement, well-spaced
    # Centers at x=25,60,95 and y=20,50,80
    nh_positions = []
    for row_idx, cy in enumerate([20, 50, 80]):
        for col_idx, cx in enumerate([25, 60, 95]):
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            return [nh_positions[4]]  # center only
        elif pop < 300:
            return nh_positions[3:6]  # center row
        elif pop < 800:
            return nh_positions[1:8]  # 7 hoods
        else:
            return nh_positions  # all 9

    active_hoods = get_active_hoods()

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: ENSURE POWER PLANTS NEAR ACTIVE HOODS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place nuclear plant for larger hoods, coal for initial
            plant_tool = Tool.NUCLEARPOWER if pop > 500 else Tool.COALPOWER
            for r in range(1, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (plant_tool, nx, ny)
                if placed:
                    break

    # ---- PHASE 2: WIRE NETWORK ----
    # Main wire corridors: horizontal at y=20,50,80 and vertical at x=25,60,95
    wire_rows_list = [20, 50, 80]
    wire_cols_list = [25, 60, 95]

    wire_phase = step % 4

    if wire_phase == 0:
        # Build horizontal wire corridors
        for wr in wire_rows_list:
            for wx in range(2, WORLD_W - 2):
                if ib(wx, wr) and not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    adj = False
                    for adx in [-1, 1]:
                        ax = wx + adx
                        if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                            adj = True
                            break
                    if adj:
                        return (Tool.WIRE, wx, wr)

    elif wire_phase == 1:
        # Build vertical wire corridors
        for wc in wire_cols_list:
            for wy in range(2, WORLD_H - 2):
                if ib(wc, wy) and not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    adj = False
                    for ady in [-1, 1]:
                        ay = wy + ady
                        if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                            adj = True
                            break
                    if adj:
                        return (Tool.WIRE, wc, wy)

    elif wire_phase == 2:
        # Connect plants to wire corridors
        plant_ys, plant_xs = np.where(pm)
        for i in range(len(plant_xs)):
            px2, py2 = int(plant_xs[i]), int(plant_ys[i])
            # Find nearest wire corridor row/col
            # Connect to nearest wire row
            for wr in sorted(wire_rows_list, key=lambda r: abs(r - py2)):
                if abs(wr - py2) < 20:
                    step_y = 1 if wr > py2 else -1
                    for ny in range(py2 + step_y, wr + step_y, step_y):
                        nx = px2
                        if ib(nx, ny) and not bool(wm[ny, nx]) and not bool(pm[ny, nx]) and bool(em[ny, nx]):
                            return (Tool.WIRE, nx, ny)
                    break

    else:
        # Fill wire gaps to uncovered hoods
        for (hx, hy) in active_hoods:
            if not bool(wm[hy, hx]) and not bool(pm[hy, hx]):
                # Find nearest wire
                nearby = []
                for r in range(1, 20):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and (bool(wm[ny, nx]) or bool(pm[ny, nx])):
                                    nearby.append((nx, ny))
                    if nearby:
                        break
                if nearby:
                    bx, by = nearby[0]
                    dx = 0 if bx == hx else (1 if bx > hx else -1)
                    dy = 0 if by == hy else (1 if by > hy else -1)
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: ROAD NETWORK ----
    # Roads parallel to wire corridors (+/-2 offset for zone access)
    road_phase = step % 3

    if road_phase == 0:
        for wr in wire_rows_list:
            for offset in [-2, 2, -4, 4]:
                ry = wr + offset
                if not ib(0, ry):
                    continue
                for rx in range(2, WORLD_W - 2):
                    if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    elif road_phase == 1:
        for wc in wire_cols_list:
            for offset in [-2, 2, -4, 4]:
                rcx = wc + offset
                if not ib(rcx, 0):
                    continue
                for ry in range(2, WORLD_H - 2):
                    if ib(rcx, ry) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    else:
        # Cross streets every 8 tiles between wire cols
        for col_idx in range(len(wire_cols_list) - 1):
            c1, c2 = wire_cols_list[col_idx], wire_cols_list[col_idx + 1]
            for mid_x in range(c1 + 8, c2, 8):
                for ry in range(2, WORLD_H - 2):
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                        adj_road = False
                        for ady in [-1, 1]:
                            ay = ry + ady
                            if ib(mid_x, ay) and bool(rm[ay, mid_x]):
                                adj_road = True
                                break
                        if adj_road:
                            return (Tool.ROAD, mid_x, ry)

    # ---- PHASE 4: ZONE PLACEMENT ----
    # Target: 40% RES, 35% COM, 25% IND
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighbor road mask (within 3 tiles for better coverage)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (wire or plant within 8 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-8, 9):
        for dx2 in range(-8, 9):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use step-based offset to vary placements
        offset = (step * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    # Fire stations early and densely
    if pop > 50:
        fire_locs = [
            (25, 20), (60, 20), (95, 20),
            (25, 50), (60, 50), (95, 50),
            (25, 80), (60, 80), (95, 80),
            (42, 35), (78, 35), (42, 65), (78, 65),
        ]
        for (sx, sy) in fire_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_locs = [
            (25, 35), (60, 35), (95, 35),
            (25, 65), (60, 65), (95, 65),
            (42, 20), (78, 20), (42, 80), (78, 80),
        ]
        for (sx, sy) in police_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        for (sx, sy) in [(45, 50), (75, 50), (45, 25), (75, 75), (25, 50), (95, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        for (sx, sy) in [(10, 85), (110, 85), (10, 15), (110, 15)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        for (sx, sy) in [(55, 5), (65, 5), (55, 95), (65, 95)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # ---- FALLBACK: extend road near existing roads with power ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant for uncovered hoods ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            plant_tool = Tool.NUCLEARPOWER if pop > 300 else Tool.COALPOWER
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (plant_tool, nx, ny)

    return None

def init(obs, state):
