                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Fill road row gaps
    if phase == 3:
        for rr2 in road_rows:
            if not (0 < rr2 < WORLD_H):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr2, rx]) and not bool(pm[rr2, rx]):
                    adj = (rx > 0 and bool(rm[rr2, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr2, rx+1])) or \
                          (rr2 > 0 and bool(rm[rr2-1, rx])) or \
                          (rr2 < WORLD_H-1 and bool(rm[rr2+1, rx]))
                    if adj or rx == 1:
                        return (Tool.ROAD, rx, rr2)

    # Phase 4: Fill road col gaps
    if phase == 4:
        for rc2 in road_cols:
            if not (0 < rc2 < WORLD_W):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc2]) and not bool(pm[ry, rc2]):
                    adj = (ry > 0 and bool(rm[ry-1, rc2])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc2])) or \
                          (rc2 > 0 and bool(rm[ry, rc2-1])) or \
                          (rc2 < WORLD_W-1 and bool(rm[ry, rc2+1]))
                    if adj or ry == 1:
                        return (Tool.ROAD, rc2, ry)

    # Phase 5: Extend roads toward unroaded zones
    if phase == 5:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 6: Wire unpowered zones
    if phase == 6:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys2, uz_xs2 = np.where(unpowered_zones)
        if len(uz_xs2) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 7: Civic services - fire stations
    if phase == 7 and pop > 15:
        fire_grid = [(fx, fy) for fy in range(8, 95, 18) for fx in range(8, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    # Phase 8: Police stations
    if phase == 8 and pop > 80:
        police_grid = [(px2, py2) for py2 in range(12, 92, 20) for px2 in range(12, 112, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # Phase 9: Stadiums
    if phase == 9 and pop > 350:
        stadium_spots = [
            (25, 15), (75, 15), (25, 45), (75, 45),
            (25, 65), (75, 65), (25, 85), (75, 85),
            (50, 30), (100, 30), (50, 70), (100, 70),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Phase 10: Nuclear power
    if phase == 10 and pop > 500:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
            (30, 5), (90, 5), (30, 95), (90, 95),
            (50, 50), (70, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2-5), min(WORLD_W, nx2+6)
                y0, y1 = max(0, ny2-5), min(WORLD_H, ny2+6)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    # Phase 11: Seaports & airports
    if phase == 11:
        if pop > 1000:
            for sx, sy in [(5, 92), (115, 92), (5, 8), (115, 8)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 2000:
            for ax, ay in [(50, 5), (70, 5), (50, 92), (70, 92)]:
                if ib(ax, ay) and bool(em[ay, ax]):
                    return (Tool.AIRPORT, ax, ay)

    # Phase 12: Parks
    if phase == 12 and pop > 200 and step % 3 == 0:
        park_cands = em & near_road & near_power & ~zone_tiles
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys3, pxs3 = np.where(park_cands)
        if len(pxs3) > 0:
            idx = (step * 29 + pop * 11) % len(pxs3)
            return (Tool.PARK, int(pxs3[idx]), int(pys3[idx]))

    # Main zone placement
    # Build exclusion zones around wires/roads
    all_excl_rows = wire_rows + road_rows
    all_excl_cols = wire_cols + road_cols

    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    for wr in all_excl_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in all_excl_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active centers scale with population
        if pop < 100:
            active_centers = [
                (60, 50), (50, 50), (70, 50), (55, 45), (65, 55),
                (45, 45), (75, 55), (55, 35), (65, 65),
            ]
        elif pop < 400:
            active_centers = [(10 + c * 15, 10 + r * 18) for r in range(5) for c in range(8)]
        elif pop < 1000:
            active_centers = [(8 + c * 13, 8 + r * 14) for r in range(7) for c in range(9)]
        elif pop < 2500:
            active_centers = [(6 + c * 11, 6 + r * 11) for r in range(9) for c in range(11)]
        else:
            active_centers = [(5 + c * 9, 5 + r * 9) for r in range(11) for c in range(13)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Also factor in proximity to roads (reward being close to roads)
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride = max(1, len(road_xs3) // 100)
            road_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(road_xs3), stride):
                d = (np.abs(cxs - road_xs3[i]) + np.abs(cys - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs))

        score = best_dist * 1.0 + road_dist * 2.0
        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off in range(min(len(road_xs4), 200)):
            k = (sk + off * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off in range(min(len(wire_xs5), 100)):
            k = (sk2 + off * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the vertical wire spine
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Roads flanking the horizontal wire spine
    for dx in range(-7, 8):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID ----
    # Denser spacing to pack more zones
    nh_cols = [12, 24, 36, 48, 60, 72, 84, 96, 108]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 4000:  return 45
        if pop < 8000:  return 55
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    # ---- BUILD NEIGHBOR MASKS ----
    # Road proximity (3x3 neighborhood)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power proximity (larger neighborhood)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT NEAR EACH ACTIVE HOOD ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: GROW WIRE FROM EXISTING WIRE/PLANT TOWARD UNCOVERED HOODS ----
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(power_src)
        if len(wire_xs) > 0:
            for (tx, ty) in uncovered:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: WIRE SPINES THROUGH HOODS ----
    hood_cycle = step % max(len(active_hoods), 1)
    spine_range = 10
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Vertical spine at hx
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wy2 = hy + sign * dist
                if not ib(hx, wy2): continue
                if bool(power_src[wy2, hx]): continue
                if not bool(em[wy2, hx]): continue
                # Check adjacent wire exists
                for ay in [wy2 - 1, wy2 + 1]:
                    if ib(hx, ay) and bool(power_src[ay, hx]):
                        return (Tool.WIRE, hx, wy2)
        # Horizontal spine at hy
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wx2 = hx + sign * dist
                if not ib(wx2, hy): continue
                if bool(power_src[hy, wx2]): continue
                if not bool(em[hy, wx2]): continue
                for ax in [wx2 - 1, wx2 + 1]:
                    if ib(ax, hy) and bool(power_src[hy, ax]):
                        return (Tool.WIRE, wx2, hy)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Roads flanking vertical spine
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    ry = hy + sign * dist
                    if not ib(rx, ry): continue
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(power_src[ry, hx]) if ib(hx, ry) else False:
                            return (Tool.ROAD, rx, ry)
        # Roads flanking horizontal spine
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    rcx = hx + sign * dist
                    if not ib(rcx, ry2): continue
                    if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                        if bool(power_src[hy, rcx]) if ib(rcx, hy) else False:
                            return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: CONNECT HOODS WITH WIRE (horizontal & vertical neighbors) ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and 10 <= abs(hx2 - hx1) <= 14:
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, hy1): continue
                    if bool(power_src[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and bool(power_src[hy1, ax]):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 10 <= abs(hy2 - hy1) <= 14:
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(hx1, cy2): continue
                    if bool(power_src[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and bool(power_src[ay, hx1]):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 50% RES, 28% COM, 22% IND
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.26:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS INTO POWERED EMPTY AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        for fx in range(12, WORLD_W, 16):
            for fy in range(12, WORLD_H, 16):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for px2 in range(16, WORLD_W, 20):
            for py2 in range(16, WORLD_H, 20):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for sx in range(20, WORLD_W, 28):
            for sy in range(20, WORLD_H, 28):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 85), (112, 85), (8, 15), (112, 15), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(30, 6), (80, 6), (30, 93), (80, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high population ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(30, 25), (90, 25), (30, 75), (90, 75),
                         (60, 15), (60, 85), (15, 50), (105, 50),
                         (45, 50), (75, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 120 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(power_src)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant near uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire backbone + initial road grid"""
    actions = []
    # Two power plants for better coverage
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Wire spines going up and down from center
    for y in range(5, 48):
        actions.append((Tool.WIRE, 60, y))
    for y in range(52, 95):
        actions.append((Tool.WIRE, 60, y))
    # Wire from left plant up/down
    for y in range(38, 48):
        actions.append((Tool.WIRE, 30, y))
    for y in range(52, 62):
        actions.append((Tool.WIRE, 30, y))
    # Wire from right plant up/down
    for y in range(38, 48):
        actions.append((Tool.WIRE, 90, y))
    for y in range(52, 62):
        actions.append((Tool.WIRE, 90, y))
    # Horizontal roads at multiple y values for denser coverage
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 50))
        actions.append((Tool.ROAD, x, 60))
    # Vertical roads
    for y in range(35, 65):
        actions.append((Tool.ROAD, 20, y))
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
        actions.append((Tool.ROAD, 100, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure enough power plants scattered across map ----
    # Grid of plants every 20 tiles
    plant_positions = []
    for py in range(15, 90, 20):
        for px in range(15, 110, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire extension toward unpowered plants/zones ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and np.any(pm[max(0,py-2):min(WORLD_H,py+3), max(0,px-2):min(WORLD_W,px+3)])
                        and not bool(near_power[py, px])]

    if len(wxs) > 0:
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire into unpowered empty areas (to enable future zones)
        if total_zones < 300:
            unpowered_empty = em & ~near_power
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                rng_idx = np.arange(0, len(upxs), max(1, len(upxs)//60))[:60]
                best_dist = 1e9
                best_k = 0
                for i in range(min(len(wxs), 400)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in rng_idx)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Dense road grid every 5 tiles ----
    road_grid = []
    for gy in range(5, 97, 5):
        for gx in range(5, 116, 5):
            road_grid.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:50]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:15]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement with better R/C/I balance ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        score = road_dist * 1.0 + np.maximum(0, 8 - zone_dist) * 3.0
        order = np.argsort(score)

        # Improved zone ratio: target 50% RES, 30% COM, 20% IND
        # Use step-based cycling with ratio correction
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        # Determine tool based on current ratios
        if ir < 0.18:
            tool = Tool.INDUSTRIAL
        elif cr < 0.28:
            tool = Tool.COMMERCIAL
        elif rr < 0.45:
            tool = Tool.RESIDENTIAL
        else:
            # Cycle: 5 res, 3 com, 2 ind
            step_mod = step % 10
            if step_mod < 5:
                tool = Tool.RESIDENTIAL
            elif step_mod < 8:
                tool = Tool.COMMERCIAL
            else:
                tool = Tool.INDUSTRIAL

        # Use offset to vary placements
        off = (step * 13 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 1000)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled to population ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(10, 92, 14) for px2 in range(10, 112, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_grid = [(pkx, pky) for pky in range(7, 95, 8) for pkx in range(7, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (60, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        nuke_locs = [(25, 25), (95, 25), (25, 75), (95, 75),
                     (60, 15), (60, 85), (15, 50), (105, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 7), min(WORLD_W, nx + 8)
                y0, y1 = max(0, ny - 7), min(WORLD_H, ny + 8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 88), (100, 88), (55, 10), (55, 88)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91), (10, 30), (110, 70)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend road/wire from plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (4, 0), (0, 4), (5, 0), (0, 5)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = (step + 3) % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2), (-2, 0), (0, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

# Different approach: denser neighborhoods, mixed zoning ratios, radial wire layout
# Key changes: smaller neighborhood spacing (14 tiles), more neighborhoods,
# different zone mix (50% RES, 25% COM, 25% IND), radial wire from plants,
# earlier civic services, nuclear power sooner

def init(obs, state):
    """Bootstrap: central coal plant + cross wires + initial roads."""
    actions = []
    cx, cy = 60, 50
    # Two coal plants for early power coverage
    actions.append((Tool.COALPOWER, cx, cy))
    actions.append((Tool.COALPOWER, cx - 20, cy))
    # Horizontal wire spine
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Initial roads flanking center
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Denser neighborhood grid: 7 cols x 6 rows = 42 neighborhoods, spacing 16
    nh_cols = [10, 26, 42, 58, 74, 90, 106]
    nh_rows = [10, 24, 40, 56, 72, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 4
        if pop < 500:   return 8
        if pop < 1000:  return 14
        if pop < 2000:  return 20
        if pop < 4000:  return 28
        if pop < 8000:  return 36
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick evenly spread active hoods (not just the first N)
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 9), min(WORLD_W, hx + 10)
        y0, y1 = max(0, hy - 9), min(WORLD_H, hy + 10)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at hood center if empty, else spiral out
            for r in range(10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: RADIAL WIRE from each plant outward ----
    spine_range = 8
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Build wire cross at hood center
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            # Connect horizontal neighbors (16 apart)
            if hy1 == hy2 and hx2 == hx1 + 16:
                mid_y = hy1
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            # Connect vertical neighbors
            if hx1 == hx2 and hy2 == hy1 + 16:
                mid_x = hx1
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Roads at hx-2, hx+2 (wider flanking - leaves space for zones)
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        # Horizontal roads at hy-2, hy+2
        for ry2 in [hy - 2, hy + 2]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- COMPUTE NEIGHBOR MASKS ----
    zone_tiles = resm | comm | indm

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Different mix: 50% RES, 25% COM, 25% IND
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (earlier than parent) ----
    if pop > 80:
        fire_spots = []
        for fx in range(12, WORLD_W, 18):
            for fy in range(12, WORLD_H, 18):
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = []
        for px2 in range(16, WORLD_W, 22):
            for py2 in range(16, WORLD_H, 22):
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # Nuclear power earlier (pop > 500 instead of 3000)
    if pop > 500 and step % 4 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (15, 50), (105, 50), (60, 15), (60, 85),
            (45, 40), (75, 40), (45, 60), (75, 60)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (10, 50), (110, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value boost ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 13) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant near uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Different strategy: 
# - Single central nuclear plant (more power), dense compact grid
# - Two main neighborhoods, one focused R/C, one focused I
# - Road-first then wire approach
# - More aggressive zone packing with civic services earlier
# - Different zone ratio: 50% RES, 25% COM, 25% IND initially, then shift

def init(obs, state):
    """Bootstrap: nuclear plant + wire cross + initial road grid"""
    actions = []
    # Central nuclear power plant
    actions.append((Tool.NUCLEARPOWER, 60, 50))
    # Wire cross from plant outward
    for x in range(20, 100):
        if x != 60:
            actions.append((Tool.WIRE, x, 50))
    for y in range(15, 85):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    # Two coal plants to supplement
    actions.append((Tool.COALPOWER, 25, 25))
    actions.append((Tool.COALPOWER, 95, 75))
    # Initial road grid - two neighborhoods
    # Neighborhood 1: x=30-55, y=30-45
    for x in range(28, 58, 4):
        for y in range(28, 48):
            actions.append((Tool.ROAD, x, y))
    for y in range(28, 48, 4):
        for x in range(28, 58):
            actions.append((Tool.ROAD, x, y))
    # Neighborhood 2: x=65-95, y=55-75
    for x in range(63, 98, 4):
        for y in range(53, 78):
            actions.append((Tool.ROAD, x, y))
    for y in range(53, 78, 4):
        for x in range(63, 98):
            actions.append((Tool.ROAD, x, y))
    return actions[:40]  # limit bootstrap size


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # State tracking for sequential building
    if 'phase' not in state:
        state['phase'] = 'wire'
        state['wire_idx'] = 0
        state['road_idx'] = 0
        state['zone_idx'] = 0

    # ---- NEIGHBORHOOD DEFINITIONS ----
    # Two main clusters + expansion zones
    # Cluster A: residential/commercial focus, top-left quadrant area
    # Cluster B: industrial focus, bottom-right area  
    # Cluster C/D/E/F: expansion

    clusters = [
        # (cx, cy, primary_tool)
        (35, 35, Tool.RESIDENTIAL),
        (80, 65, Tool.INDUSTRIAL),
        (35, 65, Tool.COMMERCIAL),
        (80, 35, Tool.RESIDENTIAL),
        (55, 50, Tool.COMMERCIAL),  # center
        (20, 50, Tool.RESIDENTIAL),
        (100, 50, Tool.INDUSTRIAL),
        (60, 20, Tool.RESIDENTIAL),
        (60, 80, Tool.COMMERCIAL),
        (20, 20, Tool.INDUSTRIAL),
        (100, 20, Tool.RESIDENTIAL),
        (20, 80, Tool.RESIDENTIAL),
        (100, 80, Tool.COMMERCIAL),
    ]

    # Active clusters based on population
    if pop < 100:
        active = clusters[:2]
    elif pop < 300:
        active = clusters[:4]
    elif pop < 600:
        active = clusters[:6]
    elif pop < 1000:
        active = clusters[:9]
    else:
        active = clusters

    # ---- POWER PLANT CHECK ----
    # Ensure each active cluster has power nearby
    for (cx, cy, _) in active:
        x0, x1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        y0, y1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_power = bool(np.any(pm[y0:y1, x0:x1])) or bool(np.any(wm[y0:y1, x0:x1]))
        if not has_power:
            # Place coal plant nearby
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- WIRE NETWORK ----
    # Build wire corridors connecting plants to all clusters
    # Main wire spine: horizontal at y=20,35,50,65,80 and vertical at x=20,35,50,65,80,95
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [20, 35, 50, 65, 80, 95]

    phase_mod = step % 6

    if phase_mod < 2:
        # Horizontal wire corridors
        for wr in wire_rows:
            for wx in range(2, WORLD_W - 2):
                if not ib(wx, wr):
                    continue
                if bool(pm[wr, wx]):
                    continue
                if not bool(wm[wr, wx]) and bool(em[wr, wx]):
                    # Check if adjacent to existing wire/plant
                    for adx in [-1, 1]:
                        ax = wx + adx
                        if ib(ax, wr) and (bool(wm[wr, ax]) or bool(pm[wr, ax])):
                            return (Tool.WIRE, wx, wr)

    elif phase_mod < 4:
        # Vertical wire corridors
        for wc in wire_cols:
            for wy in range(2, WORLD_H - 2):
                if not ib(wc, wy):
                    continue
                if bool(pm[wy, wc]):
                    continue
                if not bool(wm[wy, wc]) and bool(em[wy, wc]):
                    for ady in [-1, 1]:
                        ay = wy + ady
                        if ib(wc, ay) and (bool(wm[ay, wc]) or bool(pm[ay, wc])):
                            return (Tool.WIRE, wc, wy)

    else:
        # Connect cluster centers to wire grid
        for (cx, cy, _) in active:
            if not bool(wm[cy, cx]) and not bool(pm[cy, cx]):
                # Find nearest wire/plant
                best_d = 9999
                best_pos = None
                for wy_r in range(max(0, cy - 20), min(WORLD_H, cy + 21)):
                    for wy_c in range(max(0, cx - 20), min(WORLD_W, cx + 21)):
                        if bool(wm[wy_r, wy_c]) or bool(pm[wy_r, wy_c]):
                            d = abs(wy_r - cy) + abs(wy_c - cx)
                            if d < best_d:
                                best_d = d
                                best_pos = (wy_c, wy_r)
                if best_pos:
                    bx, by = best_pos
                    # Step toward cluster from wire
                    mx = cx + (1 if bx < cx else -1 if bx > cx else 0)
                    my = cy + (1 if by < cy else -1 if by > cy else 0)
                    if ib(mx, my) and bool(em[my, mx]):
                        return (Tool.WIRE, mx, my)

    # ---- ROAD NETWORK ----
    # Grid roads near wire corridors (offset by 1) and cross-streets
    road_phase = step % 4

    if road_phase == 0:
        # Roads parallel to wire rows (y+1 and y-1)
        for wr in wire_rows:
            for offset in [2, -2, 3, -3]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(2, WORLD_W - 2):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Near wire
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            # Adjacent to existing road?
                            for adx in [-1, 1]:
                                if ib(rx + adx, ry) and bool(rm[ry, rx + adx]):
                                    return (Tool.ROAD, rx, ry)
                            # Or start fresh near intersection
                            for wc in wire_cols:
                                if abs(rx - wc) <= 2:
                                    return (Tool.ROAD, rx, ry)

    elif road_phase == 1:
        # Roads parallel to wire cols
        for wc in wire_cols:
            for offset in [2, -2, 3, -3]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(2, WORLD_H - 2):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            for ady in [-1, 1]:
                                if ib(rcx, ry + ady) and bool(rm[ry + ady, rcx]):
                                    return (Tool.ROAD, rcx, ry)
                            for wr in wire_rows:
                                if abs(ry - wr) <= 2:
                                    return (Tool.ROAD, rcx, ry)

    elif road_phase == 2:
        # Extend existing roads in all directions
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            k = (step * 17) % len(road_xs)
            for i in range(min(len(road_xs), 50)):
                idx = (k + i * 3) % len(road_xs)
                rx2, ry2 = int(road_xs[idx]), int(road_ys[idx])
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = rx2 + dx, ry2 + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        # Extend if near wire/power
                        for wdy in range(-4, 5):
                            for wdx in range(-4, 5):
                                wx2, wy2 = nx + wdx, ny + wdy
                                if ib(wx2, wy2) and (bool(wm[wy2, wx2]) or bool(pm[wy2, wx2])):
                                    return (Tool.ROAD, nx, ny)

    else:
        # Build roads FROM cluster centers outward in a grid pattern
        for (cx, cy, _) in active:
            for gx in range(cx - 9, cx + 10, 3):
                for gy in [cy - 3, cy + 3]:
                    if ib(gx, gy) and bool(em[gy, gx]) and not bool(pm[gy, gx]):
                        adj_r = any(
                            ib(gx + adx, gy + ady) and bool(rm[gy + ady, gx + adx])
                            for adx, ady in [(1, 0), (-1, 0), (0, 1), (0, -1)]
                        )
                        if adj_r:
                            return (Tool.ROAD, gx, gy)
            for gy in range(cy - 9, cy + 10, 3):
                for gx in [cx - 3, cx + 3]:
                    if ib(gx, gy) and bool(em[gy, gx]) and not bool(pm[gy, gx]):
                        adj_r = any(
                            ib(gx + adx, gy + ady) and bool(rm[gy + ady, gx + adx])
                            for adx, ady in [(1, 0), (-1, 0), (0, 1), (0, -1)]
                        )
                        if adj_r:
                            return (Tool.ROAD, gx, gy)

    # ---- ZONE PLACEMENT ----
    # Dynamic ratio based on population
    def pick_tool_for_cluster(cx, cy, primary):
        # Near each cluster, favor its primary tool, but balance
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Global balance targets that shift with pop
        if pop < 200:
            # Early game: mostly residential
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.15:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            # Mid game: more balanced
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # Late game: heavy commercial/industrial for tax base
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.INDUSTRIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by proximity to active clusters
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (cx, cy, _) in active:
            d = np.abs(cxs_arr - cx) + np.abs(cys_arr - cy)
            best_dist = np.minimum(best_dist, d)

        # Sort by distance (closest first)
        order = np.argsort(best_dist)
        offset = (step * 11) % max(len(order), 1)

        # Find primary cluster for closest candidates
        for i in range(min(len(order), 200)):
            k_idx = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k_idx]), int(cys_arr[k_idx])
            if zone_clear(zx, zy):
                # Find nearest cluster to pick tool
                nearest_cx, nearest_cy, nearest_primary = active[0]
                nearest_d = abs(zx - nearest_cx) + abs(zy - nearest_cy)
                for (cx, cy, prim) in active:
                    d = abs(zx - cx) + abs(zy - cy)
                    if d < nearest_d:
                        nearest_d = d
                        nearest_cx, nearest_cy, nearest_primary = cx, cy, prim
                tool = pick_tool_for_cluster(nearest_cx, nearest_cy, nearest_primary)
                return (tool, zx, zy)

    # ---- CIVIC SERVICES ----
    # Place early and spread across the map
    if pop > 50:
        fire_locs = [
            (30, 30), (70, 30), (110, 30),
            (10, 50), (50, 50), (90, 50),
            (30, 70), (70, 70), (110, 70),
            (50, 15), (50, 85),
        ]
        for (sx, sy) in fire_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_locs = [
            (20, 20), (60, 20), (100, 20),
            (20, 60), (60, 60), (100, 60),
            (40, 40), (80, 40), (40, 80), (80, 80),
        ]
        for (sx, sy) in police_locs:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(40, 50), (80, 50), (60, 30), (60, 70)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 93), (70, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value when pop is decent ----
    if pop > 300 and step % 7 == 0:
        park_ys2, park_xs2 = np.where(em & nbr_road & nbr_power)
        if len(park_xs2) > 0:
            idx = (step * 31) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            return (Tool.PARK, px2, py2)

    # ---- FALLBACK: more wire to cover gaps ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        k = (step * 19) % len(wire_xs_arr)
        for i in range(min(len(wire_xs_arr), 50)):
            idx = (k + i * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[idx]), int(wire_ys_arr[idx])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2 + dx, wy2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- FALLBACK: extend roads from existing ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        k = (step * 23) % len(road_xs2)
        for i in range(min(len(road_xs2), 60)):
            idx = (k + i * 11) % len(road_xs2)
            rx2, ry2 = int(road_xs2[idx]), int(road_ys2[idx])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_power[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    return None

