def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 5)
    near_road = dilate(rm, 3)

    # Wire corridor definitions (reactive: check what's actually there)
    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    # ---- PHASE 0: Ensure power plants exist near active regions ----
    # Check every 30x25 cell for plant coverage
    for gy in range(12, WORLD_H - 10, 25):
        for gx in range(15, WORLD_W - 10, 30):
            x0, x1 = max(0, gx - 15), min(WORLD_W, gx + 16)
            y0, y1 = max(0, gy - 12), min(WORLD_H, gy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Find empty spot near this grid cell
                for r in range(1, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = gx + dx, gy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 1: Extend horizontal wire corridors (closed-loop) ----
    for wr in wire_rows:
        row_has = wm[wr, :] | pm[wr, :]
        if not np.any(row_has):
            # Seed from nearest plant
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                dists = np.abs(pys_arr - wr)
                best = np.argmin(dists)
                px2, py2 = int(pxs_arr[best]), int(pys_arr[best])
                if ib(px2, wr) and bool(em[wr, px2]):
                    return (Tool.WIRE, px2, wr)
            continue
        # Extend left and right
        indices = np.where(row_has)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 1 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 2 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)
        # Fill gaps
        for x in range(left + 1, right):
            if bool(em[wr, x]) and not bool(pm[wr, x]):
                return (Tool.WIRE, x, wr)

    # ---- PHASE 2: Extend vertical wire corridors (closed-loop) ----
    for wc in wire_cols:
        col_has = wm[:, wc] | pm[:, wc]
        if not np.any(col_has):
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                dists = np.abs(pxs_arr - wc)
                best = np.argmin(dists)
                px2, py2 = int(pxs_arr[best]), int(pys_arr[best])
                if ib(wc, py2) and bool(em[py2, wc]):
                    return (Tool.WIRE, wc, py2)
            continue
        indices = np.where(col_has)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 1 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, wc]) and not bool(pm[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Roads flanking wire corridors (closed-loop) ----
    for wr in wire_rows:
        row_wire = wm[wr, :] | pm[wr, :]
        for offset in [-1, 1]:
            ry = wr + offset
            if not (1 <= ry <= WORLD_H - 2):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    for wc in wire_cols:
        col_wire = wm[:, wc] | pm[:, wc]
        for offset in [-1, 1]:
            rcx = wc + offset
            if not (1 <= rcx <= WORLD_W - 2):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                    return (Tool.ROAD, rcx, ry)

    # ---- PHASE 4: Cross roads between corridors ----
    cross_road_rows = [12, 37, 62, 87]  # midpoints between wire rows
    cross_road_cols = [15, 45, 75, 105]
    for cry in cross_road_rows:
        row_rd = rm[cry, :]
        if not np.any(row_rd):
            # Try to start from nearby road
            if ib(60, cry) and bool(em[cry, 60]) and not bool(pm[cry, 60]) and bool(near_power[cry, 60]):
                return (Tool.ROAD, 60, cry)
        else:
            indices = np.where(row_rd)[0]
            left = int(indices[0])
            right = int(indices[-1])
            if left > 2 and bool(em[cry, left - 1]) and not bool(pm[cry, left - 1]) and bool(near_power[cry, left - 1]):
                return (Tool.ROAD, left - 1, cry)
            if right < WORLD_W - 3 and bool(em[cry, right + 1]) and not bool(pm[cry, right + 1]) and bool(near_power[cry, right + 1]):
                return (Tool.ROAD, right + 1, cry)

    for crc in cross_road_cols:
        col_rd = rm[:, crc]
        if not np.any(col_rd):
            if ib(crc, 50) and bool(em[50, crc]) and not bool(pm[50, crc]) and bool(near_power[50, crc]):
                return (Tool.ROAD, crc, 50)
        else:
            indices = np.where(col_rd)[0]
            top = int(indices[0])
            bot = int(indices[-1])
            if top > 2 and bool(em[top - 1, crc]) and not bool(pm[top - 1, crc]) and bool(near_power[top - 1, crc]):
                return (Tool.ROAD, crc, top - 1)
            if bot < WORLD_H - 3 and bool(em[bot + 1, crc]) and not bool(pm[bot + 1, crc]) and bool(near_power[bot + 1, crc]):
                return (Tool.ROAD, crc, bot + 1)

    # ---- ZONE PLACEMENT (closed-loop, reactive) ----
    cand_mask = em & near_road & near_power
    # Exclude borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Don't place on wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: prefer spots close to roads and not too far from existing zones
        road_ys_arr, road_xs_arr = np.where(rm)
        zone_ys_arr, zone_xs_arr = np.where(zone_tiles)

        if len(road_xs_arr) > 0:
            stride_r = max(1, len(road_xs_arr) // 80)
            road_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(road_xs_arr), stride_r):
                d = np.abs(cxs2 - road_xs_arr[i]).astype(float) + np.abs(cys2 - road_ys_arr[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float)

        if len(zone_xs_arr) > 0:
            stride_z = max(1, len(zone_xs_arr) // 80)
            zone_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(zone_xs_arr), stride_z):
                d = np.abs(cxs2 - zone_xs_arr[i]).astype(float) + np.abs(cys2 - zone_ys_arr[i]).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            zone_score = np.where(zone_dist < 3, 5000.0, np.where(zone_dist > 25, zone_dist * 0.5, 0.0))
        else:
            zone_score = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float)

        score = road_dist * 2.0 + zone_score
        order = np.argsort(score)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 40:
        fire_spots = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 114, 18)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(10, 92, 15) for px2 in range(10, 112, 20)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_cands = em & near_road & near_power
        pys_p, pxs_p = np.where(park_cands)
        if len(pxs_p) > 0:
            idx = (step * 31 + pop) % len(pxs_p)
            return (Tool.PARK, int(pxs_p[idx]), int(pys_p[idx]))

    if pop > 600:
        stadium_spots = [(45, 45), (75, 45), (45, 65), (75, 65),
                         (15, 40), (105, 40), (15, 60), (105, 60),
                         (60, 10), (60, 88)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 5), (60, 94), (5, 48), (115, 48),
                      (32, 5), (88, 5), (32, 94), (88, 94)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2 - 8), min(WORLD_W, nx2 + 9)
                y0, y1 = max(0, ny2 - 8), min(WORLD_H, ny2 + 9)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5), (60, 5), (60, 94)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90),
                    (5, 44), (5, 55), (110, 44), (110, 55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- FALLBACK: Wire toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    if len(uzxs) > 0:
        # Find wire tile closest to an unpowered zone, extend toward it
        wire_ys_arr, wire_xs_arr = np.where(power_src)
        if len(wire_xs_arr) > 0:
            target_x, target_y = int(uzxs[0]), int(uzys[0])
            dists = np.abs(wire_xs_arr - target_x) + np.abs(wire_ys_arr - target_y)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if target_x == bwx else (1 if target_x > bwx else -1)
            dy = 0 if target_y == bwy else (1 if target_y > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: Extend road toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)
    if len(usxs) > 0:
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            target_x, target_y = int(usxs[0]), int(usys[0])
            dists = np.abs(road_xs2 - target_x) + np.abs(road_ys2 - target_y)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs2[best_ri]), int(road_ys2[best_ri])
            dx = 0 if target_x == brx else (1 if target_x > brx else -1)
            dy = 0 if target_y == bry else (1 if target_y > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: Extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: Road near zone ----
    zone_ys_f, zone_xs_f = np.where(zone_tiles)
    if len(zone_xs_f) > 0:
        k = (step * 19) % len(zone_xs_f)
        zx2, zy2 = int(zone_xs_f[k]), int(zone_ys_f[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants + wire spines + flanking roads."""
    actions = []
    # 3 coal plants along central horizontal spine
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Roads flanking the spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
