def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Near power: tiles adjacent to wire or plant
    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire rows and cols for structured expansion
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 115]

    # --- REACTIVE: Find frontiers where power/road exist but zones don't ---

    def zone_clear(zx, zy):
        """Check 3x3 zone area is clear (empty or existing zone tiles)."""
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Step 1: Reactively extend power (wire) toward unpowered areas near roads
    # Find road tiles that are not near power — bridge the gap
    road_no_power = rm & ~near_power
    rys, rxs = np.where(road_no_power)
    if len(rxs) > 0:
        # Find nearest wire/plant to each unpowered road tile, extend wire
        wire_or_plant = wm | pm
        wyp, wxp = np.where(wire_or_plant)
        if len(wxp) > 0:
            # Pick a random unpowered road tile
            idx = (step * 17 + pop * 3) % len(rxs)
            tx, ty = int(rxs[idx]), int(rys[idx])
            dists = np.abs(wxp - tx) + np.abs(wyp - ty)
            bi = np.argmin(dists)
            bwx, bwy = int(wxp[bi]), int(wyp[bi])
            # Step toward target
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            # Try horizontal then vertical
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Step 2: Reactively extend wire rows across the map
    if step % 6 in (0, 1):
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Step 3: Extend vertical wire corridors
    if step % 6 in (2, 3):
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Step 4: Roads flanking wire rows
    if step % 6 == 4:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # Step 5: Roads flanking wire cols (vertical roads)
    if step % 6 == 5:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # Step 6: Extend roads from existing roads into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11 + pop) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Step 7: Add coal plants where power doesn't reach near roads
    # Check if we have adequate power coverage
    powered_road_frac = float(np.sum(rm & near_power)) / max(float(np.sum(rm)), 1)
    if powered_road_frac < 0.7:
        # Place a new coal plant near unpowered road cluster
        rys2, rxs2 = np.where(rm & ~near_power)
        if len(rxs2) > 0:
            idx = (step * 23) % len(rxs2)
            tx, ty = int(rxs2[idx]), int(rys2[idx])
            for r in range(2, 20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = tx + dx, ty + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # Civic services based on population
    if pop > 80:
        fire_spots = [(x, y) for y in range(10, 100, 20) for x in range(10, 120, 25)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(x, y) for y in range(15, 100, 25) for x in range(15, 120, 28)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [(30, 25), (90, 25), (30, 75), (90, 75), (60, 50), (15, 50), (105, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(5, 50), (113, 50), (60, 5), (60, 93), (5, 5), (113, 5), (5, 93), (113, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1800:
        seaports = [(5, 93), (113, 93), (5, 5), (113, 5), (60, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(48, 5), (72, 5), (48, 90), (72, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Main zone placement - reactively place zones where power AND road exist
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors and plant area
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Sort by proximity to roads (prefer tiles that are closest to roads)
        # Use a reactive metric: how many road tiles are adjacent?
        road_proximity = dilate(rm, 1).astype(np.float32)
        # Score candidates: closer to road = higher priority
        scores = road_proximity[cys2, cxs2]
        # Add small perturbation for variety
        order = np.argsort(-scores)

        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # Parks for land value near roads
    if pop > 100 and step % 5 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Wire toward any empty area that has road but no power
    unpow_road_ys, unpow_road_xs = np.where(rm & ~near_power)
    if len(unpow_road_xs) > 0:
        wyp2, wxp2 = np.where(wm | pm)
        if len(wxp2) > 0:
            idx = (step * 19) % len(unpow_road_xs)
            tx, ty = int(unpow_road_xs[idx]), int(unpow_road_ys[idx])
            dists = np.abs(wxp2 - tx) + np.abs(wyp2 - ty)
            bi = np.argmin(dists)
            bwx, bwy = int(wxp2[bi]), int(wyp2[bi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Extend any wire as fallback
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place first coal plant and seed wires/roads."""
    actions = []
    # Primary plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Seed wire in both directions
    for dy in range(-3, 4):
        actions.append((Tool.WIRE, 62, 50 + dy))
    # Seed roads flanking wire
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 61, 50 + dy))
        actions.append((Tool.ROAD, 63, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    pop = obs.city_pop
    step = obs.step

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Anchors: multiple neighborhoods spread across the map
    # Each: (plant_x, plant_y, wire_col, road_l, road_r)
    anchors = [
        (60, 50, 62, 61, 63),   # center
        (30, 50, 32, 31, 33),   # left-center
        (90, 50, 92, 91, 93),   # right-center
        (60, 25, 62, 61, 63),   # center-top
        (30, 25, 32, 31, 33),   # left-top
        (90, 25, 92, 91, 93),   # right-top
        (60, 75, 62, 61, 63),   # center-bottom
        (30, 75, 32, 31, 33),   # left-bottom
        (90, 75, 92, 91, 93),   # right-bottom
    ]

    def num_active_anchors():
        if pop < 200:
            return 1
        elif pop < 600:
            return 3
        elif pop < 1200:
            return 5
        elif pop < 2500:
            return 7
        else:
            return 9

    active_anchors = anchors[:num_active_anchors()]

    # ---- ENSURE POWER PLANTS for each active anchor ----
    for (px, py, wc, rl, rr) in active_anchors:
        has_plant = any(
            ib(px + dx, py + dy) and bool(pm[py + dy, px + dx])
            for dx in range(-4, 5) for dy in range(-4, 5)
            if ib(px + dx, py + dy)
        )
        if not has_plant:
            # Try placing at anchor location
            for r in range(0, 8):
                placed = False
                for dy2 in range(-r, r + 1):
                    for dx2 in range(-r, r + 1):
                        nx, ny = px + dx2, py + dy2
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- WIRE SPINE: extend vertically from each anchor ----
    pop_factor = min(40, pop // 8)
    for (px, py, wc, rl, rr) in active_anchors:
        if not ib(wc, py):
            continue
        spine_top = max(2, py - 18 - pop_factor)
        spine_bot = min(WORLD_H - 3, py + 18 + pop_factor)

        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_in_col:
            # Seed wire near plant
            for dy2 in range(-4, 5):
                ny = py + dy2
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- HORIZONTAL WIRE connections between same-row anchors ----
    for i in range(len(active_anchors) - 1):
        px1, py1, wc1, _, _ = active_anchors[i]
        px2, py2, wc2, _, _ = active_anchors[i + 1]
        if py1 == py2:
            min_wc = min(wc1, wc2)
            max_wc = max(wc1, wc2)
            for cx in range(min_wc, max_wc + 1):
                if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                    return (Tool.WIRE, cx, py1)

    # ---- ROAD BUILDING flanking wire spines ----
    # Use step cycling to spread out road building
    for (px, py, wc, rl, rr) in active_anchors:
        wire_in_col = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_in_col:
            continue
        cycle = step % 2
        for idx, wr in enumerate(wire_in_col):
            if idx % 2 != cycle:
                continue
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- HORIZONTAL ROADS connecting anchor road columns ----
    # Add horizontal roads to improve connectivity between clusters
    for i in range(len(active_anchors) - 1):
        px1, py1, wc1, rl1, rr1 = active_anchors[i]
        px2, py2, wc2, rl2, rr2 = active_anchors[i + 1]
        if py1 == py2:
            # Connect right road of anchor i to left road of anchor i+1
            min_x = min(rr1, rl2)
            max_x = max(rr1, rl2)
            for cx in range(min_x, max_x + 1):
                if ib(cx, py1) and bool(em[py1, cx]) and not bool(pm[py1, cx]):
                    return (Tool.ROAD, cx, py1)

    # ---- ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        # Balance: ~20% industrial, ~25% commercial, rest residential
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Compute neighbor road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute neighbor wire/plant proximity (within 6 tiles for power)
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prioritize candidates near active anchor wire columns
        best_dist = np.full(len(cxs), 999999, dtype=float)
        for (px, py, wc, rl, rr) in active_anchors:
            d = np.abs(cxs - wc) * 0.5 + np.abs(cys - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 150:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 200:
        svc_spots = [
            (45, 50), (75, 50), (45, 25), (75, 25),
            (45, 75), (75, 75), (20, 50), (100, 50),
            (55, 38), (55, 62), (20, 38), (100, 38),
        ]
        for (sx, sy) in svc_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        pstations = [
            (45, 38), (75, 38), (45, 62), (75, 62),
            (20, 35), (100, 35), (20, 65), (100, 65),
            (55, 15), (55, 85),
        ]
        for (sx, sy) in pstations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1500:
        stadiums = [(55, 15), (55, 85), (20, 50), (100, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # ---- FALLBACK: extend wire laterally ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: single central coal plant + cross roads + wires"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center outward
    for x in range(55, 90, 1):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 55, 1):
        actions.append((Tool.WIRE, 60, y))
    # Main roads: horizontal at y=40,50,60 and vertical at x=50,60,70
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 60))
    for y in range(35, 65):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: 40% res, 35% com, 25% ind — more commercial than parent
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure enough power plants across the map ---
    # Grid of plants every 15 tiles, offset to avoid road overlap
    plant_grid = []
    for py in range(12, 95, 15):
        for px in range(12, 115, 15):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire from power to uncovered areas ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H - 3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W - 3:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Find plant grid points that are not yet near power
        uncovered = [(px, py) for px, py in plant_grid
                     if ib(px, py) and not bool(near_power[py, px])]
        if uncovered:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in uncovered)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys2, zxs2 = np.where(unpowered_zones)
        if len(zxs2) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs2, zys2))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Dense road grid every 6 tiles ---
    road_grid_targets = []
    # Horizontal roads at every 6 rows, vertical at every 6 cols
    for gy in range(5, 98, 6):
        for gx in range(5, 118, 1):
            road_grid_targets.append((gx, gy))
    for gx in range(5, 118, 6):
        for gy in range(5, 98, 1):
            road_grid_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm
        road_cand[0:3, :] = False
        road_cand[WORLD_H - 3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W - 3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:30]
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:5]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement with 40/35/25 mix ---
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H - 5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W - 5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                # Allow zone tiles but not roads/wires/plants blocking the footprint
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                rd_stride = max(1, len(road_xs) // 80)
                road_dist = np.full(len(cxs_arr), 9999.0)
                for i in range(0, len(road_xs), rd_stride):
                    d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                    road_dist = np.minimum(road_dist, d)
                # Balance spread (zone_dist) with road proximity (road_dist)
                score = zone_dist * 0.5 + road_dist * 1.0
            else:
                score = zone_dist
        else:
            # Start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 17 + pop * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services tiered by population ---
    if pop > 30:
        # Fire stations grid
        fire_grid = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 112, 10)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(13, 92, 12) for px2 in range(13, 110, 12)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_grid = [(px3, py3) for py3 in range(11, 90, 8) for px3 in range(11, 111, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                        (60, 50), (15, 50), (105, 50), (60, 15), (60, 85)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 800:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75), (60, 15), (60, 85)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 5), min(WORLD_W, nx + 6)
                y0, y1 = max(0, ny - 5), min(WORLD_H, ny + 6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91),
                        (8, 35), (110, 35), (8, 65), (110, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91),
                        (15, 20), (105, 20), (15, 80), (105, 80)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: road from power plant ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        for i in range(len(pwr_xs)):
            k = (step * 7 + i) % len(pwr_xs)
            px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
            for dx2, dy2 in [(5, 0), (-5, 0), (0, 5), (0, -5), (4, 3), (-4, 3)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire ---
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place 2 coal plants with wire connections and seed roads"""
    actions = []
    # Two power plants positioned to cover left and right halves
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire between them
    for x in range(33, 88):
        actions.append((Tool.WIRE, x, 50))
    # Horizontal roads at key y positions
    for x in range(4, 116):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 60))
    # Vertical connectors
    for y in range(38, 63):
        actions.append((Tool.ROAD, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: aim for 50% RES, 25% COM, 25% IND
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # PHASE 1: Ensure power plants on a grid (every 25 cols, 20 rows)
    plant_grid = []
    for py in range(10, 95, 20):
        for px in range(10, 115, 25):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # PHASE 2: Wire expansion toward unpowered areas
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    # Find unpowered plants and wire toward them
    unpowered_plants = [(px, py) for px, py in plant_grid
                        if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Wire toward unpowered zones
    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # PHASE 3: Road grid — horizontal every 8 rows, verticals every 10 cols
    road_rows = list(range(8, 95, 8))
    for ry in road_rows:
        row_road_count = int(np.sum(rm[ry, :]))
        if row_road_count < 100:
            for rx in range(4, 116):
                if bool(em[ry, rx]):
                    left_ok = rx > 0 and bool(rm[ry, rx-1])
                    right_ok = rx < WORLD_W-1 and bool(rm[ry, rx+1])
                    up_ok = ry > 0 and bool(rm[ry-1, rx])
                    down_ok = ry < WORLD_H-1 and bool(rm[ry+1, rx])
                    if (left_ok or right_ok or up_ok or down_ok) and bool(near_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)
            # Start road near a plant if none adjacent
            for rx in range(4, 116):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    road_cols = list(range(10, 116, 10))
    for cx in road_cols:
        for cy in range(4, 96):
            if bool(em[cy, cx]) and bool(near_power[cy, cx]):
                adj = (cy > 0 and bool(rm[cy-1, cx])) or (cy < WORLD_H-1 and bool(rm[cy+1, cx]))
                if adj:
                    return (Tool.ROAD, cx, cy)

    # PHASE 4: Zone placement — balanced mix, clustered near roads and power
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False
    zone_cand &= ~rm & ~wm & ~pm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(rm[nr, nc]) or bool(wm[nr, nc]) or bool(pm[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score candidates: prefer near roads, spread from existing zones
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.ones(len(cxs_arr)) * 9999.0

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 200)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Spread zones: penalize being too close, reward being near roads
            score = road_dist * 1.5 - np.clip(zone_dist, 4, 30) * 0.5
        else:
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) + road_dist

        order = np.argsort(score)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic buildings based on population thresholds
    if pop > 200:
        fire_grid = [(fx, fy) for fy in range(12, 95, 12) for fx in range(12, 112, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        for py2 in range(14, 90, 14):
            for px2 in range(14, 110, 20):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(near_power[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for pky in range(10, 95, 10):
            for pkx in range(10, 115, 12):
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 1000:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (60, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 2000:
        nuke_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                     (60, 10), (60, 90), (15, 50), (105, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3000:
        airport_locs = [(95, 10), (95, 85), (10, 10), (10, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 4000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend road from existing roads
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k = (step * 13) % len(rxs2)
        rx2, ry2 = int(rxs2[k]), int(rys2[k])
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from power
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

# Strategy: Compact grid neighborhoods with horizontal road spines
# Key changes from parent:
# 1. Road-first layout: horizontal roads at fixed Y intervals, zones cluster around roads
# 2. Better zone mix: more industrial early, balanced later
# 3. Cross-connected wire grid instead of vertical spines only
# 4. Denser zone placement in a tighter core area

def init(obs, state):
    """Bootstrap: place coal plant + wire cross + road spine at center."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-5, 6):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Road above and below wire spine
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, cx + dx, cy - 2))
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- CLUSTER LAYOUT ----
    # Use horizontal road spines at Y = 20, 35, 50, 65, 80
    # Wire columns at X = 15, 30, 45, 60, 75, 90, 105
    # Plants at intersections of wire cols and road spines

    road_ys = [20, 35, 50, 65, 80]
    wire_xs = [15, 30, 45, 60, 75, 90, 105]

    # Plants at every other wire column, center road
    plant_positions = [
        (15, 50), (45, 50), (75, 50), (105, 50),
        (30, 35), (60, 35), (90, 35),
        (30, 65), (60, 65), (90, 65),
    ]

    # How many plants/wire-cols to activate based on pop
    def num_active_plants():
        if pop < 100:   return 1
        if pop < 300:   return 2
        if pop < 600:   return 4
        if pop < 1000:  return 6
        if pop < 1800:  return 8
        return 10

    active_plants = plant_positions[:num_active_plants()]

    def num_active_wire_cols():
        if pop < 100:   return 1
        if pop < 300:   return 2
        if pop < 600:   return 4
        if pop < 1000:  return 5
        if pop < 1800:  return 7
        return 7

    active_wire_cols = wire_xs[:num_active_wire_cols()]

    def num_active_roads():
        if pop < 100:   return 1
        if pop < 300:   return 2
        if pop < 600:   return 3
        if pop < 1000:  return 4
        return 5

    active_road_ys = road_ys[:num_active_roads()]

    # ---- 1. ENSURE POWER PLANTS ----
    for (px, py) in active_plants:
        has_plant = False
        for dx in range(-4, 5):
            for dy in range(-4, 5):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. BUILD HORIZONTAL WIRE SPINES at road_ys ----
    # Wire runs along each active road_y, connecting all active wire columns
    for ry in active_road_ys:
        for wx in active_wire_cols:
            # Build horizontal wire at ry from wx-range
            x_min = min(active_wire_cols)
            x_max = max(active_wire_cols)
            for cx in range(x_min, x_max + 1):
                if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                    return (Tool.WIRE, cx, ry)

    # ---- 3. BUILD VERTICAL WIRE COLUMNS ----
    # Wire runs along each active wire_col, connecting all active road_ys
    for wx in active_wire_cols:
        y_min = min(active_road_ys) if active_road_ys else 20
        y_max = max(active_road_ys) if active_road_ys else 80
        for cy_val in range(y_min, y_max + 1):
            if ib(wx, cy_val) and bool(em[cy_val, wx]) and not bool(pm[cy_val, wx]):
                return (Tool.WIRE, wx, cy_val)

    # ---- 4. BUILD HORIZONTAL ROADS ----
    # Roads 1 tile above and below each wire spine (to allow zone access)
    for ry in active_road_ys:
        x_min = min(active_wire_cols) if active_wire_cols else 15
        x_max = max(active_wire_cols) if active_wire_cols else 105
        for offset in [-1, 1]:
            road_y = ry + offset
            if not ib(0, road_y):
                continue
            for rx in range(x_min - 1, x_max + 2):
                if ib(rx, road_y) and bool(em[road_y, rx]) and not bool(pm[road_y, rx]) and not bool(wm[road_y, rx]):
                    return (Tool.ROAD, rx, road_y)

    # ---- 5. BUILD VERTICAL ROADS along wire columns (access roads) ----
    for wx in active_wire_cols:
        road_col = wx + 2  # road 2 tiles right of wire col
        if not ib(road_col, 0):
            continue
        y_min = min(active_road_ys) - 2 if active_road_ys else 18
        y_max = max(active_road_ys) + 2 if active_road_ys else 82
        for ry in range(y_min, y_max + 1):
            if ib(road_col, ry) and bool(em[ry, road_col]) and not bool(pm[ry, road_col]) and not bool(wm[ry, road_col]):
                return (Tool.ROAD, road_col, ry)

    # ---- 6. ZONE PLACEMENT (closed-loop: balanced mix) ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr_val = res_count / t
        # Heavy industrial early (power demand), then balance
        if pop < 200:
            if ir < 0.35:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score: prefer near active wire columns and road ys
        best_dist = np.full(len(cxs_arr), 999999.0)
        for wx in active_wire_cols:
            for ry in active_road_ys:
                d = np.abs(cxs_arr.astype(float) - wx) + np.abs(cys_arr.astype(float) - ry)
                best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- 7. EXTEND ROADS near wire ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 50)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx, ry_val = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry_val + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- 8. CIVIC SERVICES ----
    if pop > 150:
        firestations = [
            (22, 27), (52, 27), (82, 27),
            (22, 57), (52, 57), (82, 57),
            (22, 72), (52, 72), (82, 72),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        polices = [
            (37, 42), (67, 42), (97, 42),
            (37, 72), (67, 72), (97, 72),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(35, 10), (75, 10), (35, 90), (75, 90)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        # Add nuclear plants near active plant locations
        for (px, py) in active_plants[:4]:
            for dx in range(-6, 7):
                for dy in range(-6, 7):
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(wm[ny, nx]):
                        return (Tool.NUCLEARPOWER, nx, ny)

    # ---- 9. FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx_val, wy_val = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx_val + dx, wy_val + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross from plant
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along vertical spine
    for dy in range(-10, 11):
        actions.append((Tool.ROAD, cx - 4, cy + dy))
        actions.append((Tool.ROAD, cx + 4, cy + dy))
    # Flanking roads along horizontal spine
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 4))
        actions.append((Tool.ROAD, cx + dx, cy + 4))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Denser hood grid: 8 cols x 7 rows
    nh_cols = [12, 26, 40, 55, 70, 84, 98, 110]
    nh_rows = [12, 24, 36, 50, 62, 76, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 6
        if pop < 300:  return 10
        if pop < 600:  return 16
        if pop < 1000: return 24
        if pop < 2000: return 36
        if pop < 4000: return 48
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and funds > 500:
            for r in range(0, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from plants toward hoods ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        for (hx, hy) in active_hoods:
            wx0, wx1 = max(0, hx - 4), min(WORLD_W, hx + 5)
            wy0, wy1 = max(0, hy - 4), min(WORLD_H, hy + 5)
            has_wire = bool(np.any(wm[wy0:wy1, wx0:wx1])) or bool(np.any(pm[wy0:wy1, wx0:wx1]))
            if has_wire:
                continue
            # Extend along vertical spine at hx
            col_tiles = [r for r in range(WORLD_H) if ib(hx, r) and (bool(wm[r, hx]) or bool(pm[r, hx]))]
            if col_tiles:
                if hy > max(col_tiles):
                    nr = max(col_tiles) + 1
                    if ib(hx, nr) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)
                elif hy < min(col_tiles):
                    nr = min(col_tiles) - 1
                    if ib(hx, nr) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)
            # Extend along horizontal spine at hy
            row_tiles = [c for c in range(WORLD_W) if ib(c, hy) and (bool(wm[hy, c]) or bool(pm[hy, c]))]
            if row_tiles:
                if hx > max(row_tiles):
                    nc = max(row_tiles) + 1
                    if ib(nc, hy) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)
                elif hx < min(row_tiles):
                    nc = min(row_tiles) - 1
                    if ib(nc, hy) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: EXTEND WIRE SPINES from existing wires ----
    spine_range = 16
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 4: CONNECT ADJACENT HOODS WITH WIRES ----
    for i_h, (hx1, hy1) in enumerate(active_hoods):
        for j_h, (hx2, hy2) in enumerate(active_hoods):
            if j_h <= i_h: continue
            if hy1 == hy2 and 0 < hx2 - hx1 <= 20:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 0 < hy2 - hy1 <= 20:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 5: ROADS flanking wire spines ----
    # Roads at hx±4 and hy±4 (slightly wider than parent's ±3)
    road_hood_idx = (step + len(active_hoods) // 2) % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_hood_idx]

    for rx in [rhx - 4, rhx + 4]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)

    for ry2 in [rhy - 4, rhy + 4]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # Also add roads at ±8 offset for extra density
    for rx in [rhx - 8, rhx + 8]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)

    for ry2 in [rhy - 8, rhy + 8]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Balanced: 30% ind, 30% com, 40% res
        if ir < 0.30: return Tool.INDUSTRIAL
        if cr < 0.30: return Tool.COMMERCIAL
        if rr < 0.40: return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (within 5 tiles of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx_a, hy_a) in active_hoods:
            d = np.abs(cxs - hx_a) + np.abs(cys - hy_a)
            best_dist = np.minimum(best_dist, d)

        # Zone clustering bonus (stronger weight)
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(14, WORLD_W - 4, 18)
                      for fy in range(14, WORLD_H - 4, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W - 4, 22)
                        for py2 in range(18, WORLD_H - 4, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [(30, 25), (60, 15), (90, 25),
                    (20, 50), (100, 50),
                    (30, 75), (60, 85), (90, 75),
                    (45, 40), (75, 40), (45, 62), (75, 62)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 200 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 800 and funds > 4000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (35, 20), (85, 20), (35, 78), (85, 78),
            (20, 35), (100, 35), (20, 65), (100, 65),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        sk = (step * 11) % len(pxs2)
        for offset in range(min(len(pxs2), 60)):
            k = (sk + offset * 7) % len(pxs2)
            px2, py2 = int(pxs2[k]), int(pys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
