def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Wire corridors: 8 horizontal rows, 8 vertical cols
    wire_rows = [9, 21, 33, 45, 57, 69, 81, 93]
    wire_cols = [9, 24, 39, 54, 69, 84, 99, 114]

    # Plant grid positions: 4x4 spread
    plant_positions = [
        (15, 15), (45, 15), (75, 15), (105, 15),
        (15, 39), (45, 39), (75, 39), (105, 39),
        (15, 63), (45, 63), (75, 63), (105, 63),
        (15, 87), (45, 87), (75, 87), (105, 87),
    ]

    # ---- PHASE 1: Ensure plants exist at grid positions ----
    for px, py in plant_positions:
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_has_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_has_power[wx]):
                        if (wx > 0 and bool(row_has_power[wx - 1])) or \
                           (wx < WORLD_W - 1 and bool(row_has_power[wx + 1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_has_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2 + step_x, wc + step_x, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_has_power[wy]):
                        if (wy > 0 and bool(col_has_power[wy - 1])) or \
                           (wy < WORLD_H - 1 and bool(col_has_power[wy + 1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire corridors
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire corridors
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Wire cross-connections at intersections
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc - 1])) or (wc < WORLD_W - 1 and bool(wm[wr, wc + 1]))
                col_ok = (wr > 0 and bool(wm[wr - 1, wc])) or (wr < WORLD_H - 1 and bool(wm[wr + 1, wc]))
                if (row_ok or col_ok) and bool(em[wr, wc]) and not bool(pm[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 5:
        # Cross-connect roads between wire rows
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            mid_y = (wr1 + wr2) // 2
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                        adj = (ib(rcx, mid_y - 1) and bool(rm[mid_y - 1, rcx])) or \
                              (ib(rcx, mid_y + 1) and bool(rm[mid_y + 1, rcx]))
                        if adj:
                            return (Tool.ROAD, rcx, mid_y)

    elif phase == 6:
        # Cross-connect roads between wire cols
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            mid_x = (wc1 + wc2) // 2
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x - 1, ry) and bool(rm[ry, mid_x - 1])) or \
                              (ib(mid_x + 1, ry) and bool(rm[ry, mid_x + 1]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 7:
        # Extend roads toward powered-but-unroaded areas
        target_mask = near_power & ~near_road & em
        target_mask[0:3, :] = False
        target_mask[WORLD_H - 3:, :] = False
        target_mask[:, 0:3] = False
        target_mask[:, WORLD_W - 3:] = False
        tys, txs = np.where(target_mask)
        road_ys, road_xs = np.where(rm)
        if len(txs) > 0 and len(road_xs) > 0:
            ti = (step * 17) % len(txs)
            tx, ty = int(txs[ti]), int(tys[ti])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Wire toward unpowered road areas
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(npxs) > 0 and len(wire_xs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    else:
        # Extend wire from existing wire network
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            step_k2 = (step * 13) % len(wire_xs3)
            for offset in range(min(len(wire_xs3), 80)):
                k = (step_k2 + offset * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 4)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 1.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.3 / (1.0 + abs(x - 60) / 60.0 + abs(y - 50) / 50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 50:
        fire_positions = [
            (15, 9), (45, 9), (75, 9), (105, 9),
            (15, 33), (45, 33), (75, 33), (105, 33),
            (15, 57), (45, 57), (75, 57), (105, 57),
            (15, 81), (45, 81), (75, 81), (105, 81),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_positions = [
            (30, 21), (60, 21), (90, 21),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (30, 69), (60, 69), (90, 69),
            (15, 87), (45, 87), (75, 87), (105, 87),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 33), (90, 33), (30, 69), (90, 69),
            (60, 21), (60, 81), (15, 57), (105, 57),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
            (30, 50), (90, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value reactively
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend road from existing roads near power
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Last resort: road near zones
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Compact grid city with dedicated power corridors
# Key differences from parent:
# - Denser neighborhood grid (6x5 = 30 neighborhoods)
# - Horizontal wire highway along fixed rows, roads run perpendicular
# - Heavier commercial/industrial weighting (40% res, 30% com, 30% ind)
# - Power distributed via horizontal "wire highways" + vertical feeders
# - Civic services placed more aggressively

def init(obs, state):
    """Bootstrap: two coal plants + wire highway + perpendicular roads."""
    actions = []
    # Two plants for better coverage
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire highway at y=50
    for x in range(5, 115):
        if x not in (30, 90):  # skip plant tiles
            actions.append((Tool.WIRE, x, 50))
    # Vertical wires up/down from center
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # 6 columns x 5 rows = 30 neighborhoods
    nh_cols = [10, 30, 50, 70, 90, 110]
    nh_rows = [10, 28, 50, 72, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 14
        if pop < 1000:  return 20
        if pop < 2000:  return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly
    step_size = len(all_hoods) / n_active
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Build neighbor masks for power and road
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # PHASE 1: Ensure each active hood has a nearby power plant
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Wire horizontal highways at each neighborhood row
    # Wire runs at the exact hood row y, connecting across columns
    hood_idx = step % max(len(active_hoods), 1)
    hx_cur, hy_cur = active_hoods[hood_idx]

    # Find plant near this hood
    x0, x1 = max(0, hx_cur - 15), min(WORLD_W, hx_cur + 16)
    y0, y1 = max(0, hy_cur - 15), min(WORLD_H, hy_cur + 16)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])

    if len(plant_xs) > 0:
        px_l = int(plant_xs[0]) + x0
        py_l = int(plant_ys[0]) + y0

        # Route wire: vertical segment from plant to hood row
        if py_l != hy_cur:
            sd = 1 if hy_cur > py_l else -1
            for wy in range(py_l + sd, hy_cur + sd, sd):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        # Route wire: horizontal segment from plant column to hood column
        if px_l != hx_cur:
            sd = 1 if hx_cur > px_l else -1
            for wx in range(px_l + sd, hx_cur + sd, sd):
                if not ib(wx, hy_cur): continue
                if bool(pm[hy_cur, wx]) or bool(wm[hy_cur, wx]): continue
                if not bool(em[hy_cur, wx]): continue
                return (Tool.WIRE, wx, hy_cur)

    # PHASE 3: Horizontal wire highways connecting hoods in same row
    # For each pair of same-row hoods, fill wire between them
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 25:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx, mxx + 1):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    # Only if adjacent to power
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)

    # PHASE 4: Vertical wire feeders connecting row highways
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hx1 == hx2 and abs(hy2 - hy1) <= 25:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny, mxy + 1):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # PHASE 5: Roads parallel to wire highways (one tile above and below)
    spine_range = 12
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    # Roads above and below horizontal wire spine
    for ry_offset in [-1, 1]:
        ry = hy3 + ry_offset
        if not ib(hx3, ry): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry): continue
            if not bool(em[ry, rcx]) and not bool(rm[ry, rcx]): continue
            if bool(pm[ry, rcx]): continue
            # Place road if adjacent to wire spine or existing road
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]) or bool(rm[ry, rcx]):
                if bool(em[ry, rcx]):
                    return (Tool.ROAD, rcx, ry)

    # Vertical roads flanking vertical wire feeders
    for rx_offset in [-1, 1]:
        rx = hx3 + rx_offset
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry2 = hy3 + dy
            if not ib(rx, ry2): continue
            if not bool(em[ry2, rx]) and not bool(rm[ry2, rx]): continue
            if bool(pm[ry2, rx]): continue
            if bool(wm[ry2, hx3]) or bool(pm[ry2, hx3]) or bool(rm[ry2, rx]):
                if bool(em[ry2, rx]):
                    return (Tool.ROAD, rx, ry2)

    # PHASE 6: Cross roads between adjacent hoods
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 25:
                for cy2 in [hy1 - 1, hy1 + 1]:
                    if not ib(hx1, cy2): continue
                    mnx2, mxx2 = min(hx1, hx2), max(hx1, hx2)
                    for cx3 in range(mnx2, mxx2 + 1):
                        if not ib(cx3, cy2): continue
                        if bool(pm[cy2, cx3]): continue
                        if not bool(em[cy2, cx3]): continue
                        # Require adjacency to existing road
                        for ax2, ay2 in [(cx3-1,cy2),(cx3+1,cy2),(cx3,cy2-1),(cx3,cy2+1)]:
                            if ib(ax2, ay2) and bool(rm[ay2, ax2]):
                                return (Tool.ROAD, cx3, cy2)

    # PHASE 7: Zone placement with heavier commercial/industrial mix
    zone_tiles = resm | comm | indm

    def pick_tool():
        # 35% res, 33% com, 32% ind — shift commercial/industrial heavier
        if total_zones < 10:
            return Tool.RESIDENTIAL
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # target: 35% res, 33% com, 32% ind
        if ir < 0.32:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 8: Extend roads into powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(nbr_power[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # PHASE 9: Civic services — more aggressive placement
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(16, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(24,24),(96,24),(24,76),(96,76),(60,14),(60,86),(12,50),(108,50),(48,50),(72,50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(6,94),(114,94),(6,6),(114,6),(60,97),(60,3)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40,5),(80,5),(40,94),(80,94),(5,40),(5,70),(114,40),(114,70)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrade for mature cities
    if pop > 2500 and step % 3 == 0:
        nuclear_spots = [(60,50),(12,12),(108,12),(12,88),(108,88),
                         (35,38),(85,38),(35,62),(85,62),
                         (60,25),(60,75),(25,50),(95,50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 150 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire from existing wire/plant
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new plant at uncovered hood
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

