def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    def pick_tool():
        t = max(total_zones, 1)
        if ind_count / t < 0.22:
            return Tool.INDUSTRIAL
        if com_count / t < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Ensure at least one plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    # Primary plant
    px0 = int(plant_xs[0])
    py0 = int(plant_ys[0])

    # Compute nbr_road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Compute nbr_power mask (wire or plant within 7 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-7, 8):
        for dx in range(-7, 8):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # --- Multi-spine layout ---
    # Determine number of active spines based on pop
    if pop < 200:
        n_spines = 1
    elif pop < 800:
        n_spines = 2
    elif pop < 2000:
        n_spines = 4
    elif pop < 5000:
        n_spines = 6
    else:
        n_spines = 8

    # Spine wire columns spaced 14 apart, centered at 60
    spine_cols = []
    for i in range(n_spines):
        col = 60 + (i - n_spines // 2) * 14
        if 5 <= col < WORLD_W - 5:
            spine_cols.append(col)

    # Spine vertical extent grows with pop
    pop_factor = min(35, pop // 20)
    spine_top = max(3, 50 - 18 - pop_factor)
    spine_bot = min(WORLD_H - 4, 50 + 18 + pop_factor)

    # --- For each spine: ensure plant, build wire spine, flanking roads ---
    for sci, wcol in enumerate(spine_cols):
        plant_near = bool(np.any(pm[max(0, 47):min(WORLD_H, 54), max(0, wcol - 4):min(WORLD_W, wcol + 5)]))

        # Ensure plant near this spine
        if not plant_near:
            # Try to place plant at (wcol+2, 50) or find empty spot
            for attempt_x in [wcol + 2, wcol - 2, wcol]:
                for attempt_y in [50, 48, 52]:
                    if ib(attempt_x, attempt_y) and bool(em[attempt_y, attempt_x]):
                        # Don't overwrite existing wire
                        if not bool(wm[attempt_y, attempt_x]):
                            return (Tool.COALPOWER, attempt_x, attempt_y)

        # Build wire spine in this column
        wire_in_col = [r for r in range(WORLD_H) if ib(wcol, r) and bool(wm[r, wcol])]

        if not wire_in_col:
            # Seed wire near plant center
            for dy in range(-2, 3):
                ny = 50 + dy
                if ib(wcol, ny) and bool(em[ny, wcol]) and not bool(pm[ny, wcol]):
                    return (Tool.WIRE, wcol, ny)
        else:
            min_wr = min(wire_in_col)
            max_wr = max(wire_in_col)
            # Grow downward
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wcol, nr) and (bool(em[nr, wcol])) and not bool(pm[nr, wcol]):
                    return (Tool.WIRE, wcol, nr)
            # Grow upward
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wcol, nr) and (bool(em[nr, wcol])) and not bool(pm[nr, wcol]):
                    return (Tool.WIRE, wcol, nr)

        # Build flanking roads
        road_l = wcol - 1
        road_r = wcol + 1
        wire_in_col2 = [r for r in range(WORLD_H) if ib(wcol, r) and bool(wm[r, wcol])]
        if wire_in_col2:
            # Every step check a subset of rows
            rows_sub = wire_in_col2[step % 2::2]
            for wr in rows_sub:
                if ib(road_l, wr) and bool(em[wr, road_l]) and not bool(pm[wr, road_l]):
                    return (Tool.ROAD, road_l, wr)
                if ib(road_r, wr) and bool(em[wr, road_r]) and not bool(pm[wr, road_r]):
                    return (Tool.ROAD, road_r, wr)

    # --- Connect spines horizontally with wire at mid-height ---
    if len(spine_cols) > 1:
        mid_y = 50
        for i in range(len(spine_cols) - 1):
            c1, c2 = spine_cols[i], spine_cols[i + 1]
            # Check if there's a wire gap between them at mid_y
            for cx2 in range(c1 + 1, c2):
                if ib(cx2, mid_y) and not bool(wm[mid_y, cx2]) and not bool(pm[mid_y, cx2]) and bool(em[mid_y, cx2]):
                    # Need adjacency to wire
                    adj = False
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            adj = True
                    for ady in [-1, 1]:
                        ay = mid_y + ady
                        if ib(cx2, ay) and (bool(wm[ay, cx2]) or bool(pm[ay, cx2])):
                            adj = True
                    if adj:
                        return (Tool.WIRE, cx2, mid_y)
            # Also connect horizontal roads between spines at mid_y±1
            for ry_h in [mid_y - 1, mid_y + 1]:
                for cx2 in range(c1 + 1, c2):
                    if ib(cx2, ry_h) and bool(em[ry_h, cx2]) and not bool(pm[ry_h, cx2]) and bool(nbr_power[ry_h, cx2]):
                        # Check if adjacent road exists
                        for adx in [-1, 1]:
                            ax = cx2 + adx
                            if ib(ax, ry_h) and bool(rm[ry_h, ax]):
                                return (Tool.ROAD, cx2, ry_h)

    # --- Place zones near powered roads ---
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to nearest spine
        best_dist = np.full(len(cxs), 999999.0)
        for wcol in spine_cols:
            d = np.abs(cxs - wcol) + np.abs(cys - 50) * 0.3
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 120)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- Extend roads from existing network into powered areas ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 40)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Civic services ---
    if pop > 150:
        fire_spots = [
            (45, 35), (75, 35), (45, 65), (75, 65),
            (30, 50), (90, 50), (60, 30), (60, 70),
            (20, 30), (100, 30), (20, 70), (100, 70),
        ]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 400:
        police_spots = [
            (40, 40), (80, 40), (40, 60), (80, 60),
            (25, 50), (95, 50), (60, 25), (60, 75),
        ]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 1500:
        stadiums = [(35, 35), (85, 35), (35, 65), (85, 65), (60, 15), (60, 85)]
        for ssx, ssy in stadiums:
            if ib(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    if pop > 3000:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15)]
        for spx, spy in seaports:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 6000:
        airports = [(50, 10), (70, 10), (50, 90), (70, 90)]
        for apx, apy in airports:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- Parks to boost land value ---
    if pop > 400 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            ppx, ppy = int(park_xs[idx]), int(park_ys[idx])
            if ib(ppx, ppy) and bool(em[ppy, ppx]):
                return (Tool.PARK, ppx, ppy)

    # --- Fallback: extend wire from existing wire ---
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 30)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- Fallback: place plant at unpowered active area ---
    for wcol in spine_cols:
        if not bool(nbr_power[50, wcol]):
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = wcol + dx, 50 + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

