    # Primary plant at left-center
    placements.append((Tool.COALPOWER, 28, 50))
    # Wire spine from plant
    for dy in range(-3, 4):
        placements.append((Tool.WIRE, 30, 50 + dy))
    # Roads flanking wire
    for dy in range(-3, 4):
        placements.append((Tool.ROAD, 29, 50 + dy))
