def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Track state for sequential neighborhood building
    if 'phase' not in state:
        state['phase'] = 'power'
        state['neighborhood_idx'] = 0
        state['road_progress'] = 0

    # Define neighborhoods in a grid pattern
    neighborhoods = []
    for ny in range(15, 90, 25):
        for nx in range(15, 110, 25):
            neighborhoods.append((nx, ny))

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Pick zone tool based on ratios - aim for 35% res, 35% com, 30% ind
    def pick_tool(step_offset=0):
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        if rr < 0.33:
            return Tool.RESIDENTIAL
        # Cycle: 3 com, 3 res, 2 ind
        cycle = (step + step_offset) % 8
        if cycle < 3:
            return Tool.COMMERCIAL
        elif cycle < 6:
            return Tool.RESIDENTIAL
        else:
            return Tool.INDUSTRIAL

    # PHASE 1: Ensure power plants exist across the map
    # Place plants on a coarser grid than parent (every 24 tiles)
    plant_grid = []
    for py in range(12, 95, 24):
        for px in range(12, 110, 24):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # PHASE 2: Wire expansion - connect plants and extend power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0:
        # Find unpowered plants
        unpowered_plants = [(px, py) for px, py in plant_grid
                            if ib(px, py) and np.any(pm[max(0,py-1):py+2, max(0,px-1):px+2])
                            and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 600)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward areas without power - focus on road cells first
        unpowered_roads = rm & ~near_power
        urys, urxs = np.where(unpowered_roads)
        if len(urxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(urxs[j])) + abs(cy - int(urys[j])) for j in range(min(20, len(urxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # PHASE 3: Road grid - denser 5-tile grid horizontal/vertical
    # Horizontal roads at every 5 rows, vertical every 5 cols
    road_rows = list(range(5, 98, 5))
    road_cols = list(range(5, 118, 5))

    # Find powered areas without road
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    # Identify missing road grid cells that are powered
    missing_roads = []
    for ry in road_rows:
        for rx in road_cols:
            if ib(rx, ry) and not bool(rm[ry, rx]) and bool(near_power[ry, rx]):
                missing_roads.append((rx, ry))

    if missing_roads:
        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets = missing_roads[:50]
            for i in range(min(len(rxs2), 600)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in missing_roads[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # PHASE 4: Zone placement - prefer spots near intersections of road grid
    # Focus commercial near center, industrial on outskirts, residential everywhere
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Distance from center (60, 50)
        cx_center = 60
        cy_center = 50
        dist_center = (np.abs(cxs_arr - cx_center) + np.abs(cys_arr - cy_center)).astype(float)

        # Distance from nearest road
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Distance from existing zones (prefer some spread)
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Score: prefer close to roads, moderate spread, not too far from center
        score = road_dist * 2.0 + np.maximum(0, 6 - zone_dist) * 1.5 + dist_center * 0.05

        order = np.argsort(score)

        # Determine tool based on location and ratios
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        for i in range(min(len(order), 600)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if not zone_clear(zx2, zy2):
                continue
            # Zone type based on location: commercial near center, industrial far, res elsewhere
            d_c = abs(zx2 - cx_center) + abs(zy2 - cy_center)
            if ir < 0.28:
                tool = Tool.INDUSTRIAL
            elif cr < 0.33:
                tool = Tool.COMMERCIAL
            elif rr < 0.33:
                tool = Tool.RESIDENTIAL
            else:
                # Location-based assignment
                if d_c < 20:
                    tool = Tool.COMMERCIAL
                elif d_c > 50:
                    tool = Tool.INDUSTRIAL
                else:
                    cycle = step % 6
                    if cycle < 2:
                        tool = Tool.COMMERCIAL
                    elif cycle < 4:
                        tool = Tool.RESIDENTIAL
                    else:
                        tool = Tool.INDUSTRIAL
            return (tool, zx2, zy2)

    # PHASE 5: Civic buildings scaled to pop
    if pop > 80:
        for fsy in range(8, 95, 8):
            for fsx in range(8, 115, 8):
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        for psy in range(10, 92, 10):
            for psx in range(10, 112, 10):
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        for pky in range(7, 95, 7):
            for pkx in range(7, 115, 7):
                if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 700:
        nuke_locs = [(60, 50), (20, 20), (100, 20), (20, 80), (100, 80),
                     (60, 20), (60, 80), (20, 50), (100, 50),
                     (40, 35), (80, 35), (40, 65), (80, 65)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-7), min(WORLD_W, nx+8)
                y0, y1 = max(0, ny-7), min(WORLD_H, ny+8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 600:
        stadium_locs = [(20, 15), (60, 15), (100, 15),
                        (20, 50), (100, 50),
                        (20, 85), (60, 85), (100, 85),
                        (40, 35), (80, 35), (40, 65), (80, 65)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        airport_locs = [(45, 7), (75, 7), (45, 92), (75, 92),
                        (7, 30), (112, 30), (7, 70), (112, 70)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2000:
        seaport_locs = [(8, 50), (112, 50), (60, 7), (60, 92)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # Fallback: extend roads near plants
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 0), (0, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

