def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            if ir < 0.35:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.25:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PRIORITY 1: Wire toward unpowered zones ===
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        uz_ys, uz_xs = np.where(unpowered_zones)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0 and len(uz_xs) > 0:
            tidx = (step * 7) % len(uz_xs)
            tx, ty = int(uz_xs[tidx]), int(uz_ys[tidx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best = np.argmin(dists)
            bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === PRIORITY 2: Road toward zones without road access ===
    zones_no_road = zone_tiles & ~near_road
    if np.any(zones_no_road):
        zr_ys, zr_xs = np.where(zones_no_road)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0 and len(zr_xs) > 0:
            tidx = (step * 11) % len(zr_xs)
            tx, ty = int(zr_xs[tidx]), int(zr_ys[tidx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best = np.argmin(dists)
            brx, bry = int(road_xs[best]), int(road_ys[best])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bwy else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PRIORITY 3: Maintain wire grid (closed-loop repair) ===
    phase = step % 8

    if phase == 0:
        # Repair/extend horizontal wire rows
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])))
                    right = (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Repair/extend vertical wire columns
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc])))
                    dn = (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Extend roads adjacent to wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Extend roads adjacent to wire columns
        for wc in wire_cols:
            for offset in [-1, 1]:
                cx = wc + offset
                if not (0 < cx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, cx]):
                        return (Tool.ROAD, cx, ry)

    elif phase == 4:
        # Add extra wire rows for denser coverage
        extra_rows = [12, 37, 62, 87]
        for wr in extra_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])))
                    right = (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    if left or right:
                        return (Tool.WIRE, wx, wr)
        # Check if we need more power plants
        # Find large empty powered area without a plant
        plant_targets = [(15, 12), (45, 12), (75, 12), (105, 12),
                         (15, 37), (45, 37), (75, 37), (105, 37),
                         (15, 62), (45, 62), (75, 62), (105, 62),
                         (15, 87), (45, 87), (75, 87), (105, 87)]
        for ppx, ppy in plant_targets:
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = ppx + dx, ppy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    elif phase == 5:
        # Roads along extra rows
        extra_rows = [12, 37, 62, 87]
        for wr in extra_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 6:
        # Extra vertical wire columns for density
        extra_cols = [15, 45, 75, 105]
        for wc in extra_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc])))
                    dn = (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    elif phase == 7:
        # Roads along extra columns
        extra_cols = [15, 45, 75, 105]
        for wc in extra_cols:
            for offset in [-1, 1]:
                cx = wc + offset
                if not (0 < cx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, cx]):
                        return (Tool.ROAD, cx, ry)

    # === CIVIC SERVICES (pop-gated) ===
    if pop > 30:
        fire_spots = [
            (6, 6), (35, 6), (65, 6), (95, 6), (113, 6),
            (6, 30), (113, 30), (6, 50), (113, 50),
            (6, 70), (113, 70), (6, 93), (35, 93), (65, 93), (95, 93),
            (35, 50), (65, 50), (95, 50), (50, 20), (80, 20), (50, 80), (80, 80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (20, 15), (50, 15), (80, 15), (110, 15),
            (20, 38), (50, 38), (80, 38), (110, 38),
            (20, 62), (50, 62), (80, 62), (110, 62),
            (20, 85), (50, 85), (80, 85), (110, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(30, 20), (90, 20), (30, 80), (90, 80),
                         (60, 50), (15, 50), (105, 50), (60, 10), (60, 90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (10, 50), (110, 50), (60, 5), (60, 95),
            (10, 20), (110, 20), (10, 80), (110, 80),
            (35, 10), (85, 10), (35, 90), (85, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 94), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92),
                    (5, 45), (115, 45), (5, 55), (115, 55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 7 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # === ZONE PLACEMENT ===
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors (all wire rows and cols)
    all_wire_rows = [12, 25, 37, 50, 62, 75, 87]
    all_wire_cols = [15, 30, 45, 60, 75, 90, 105]
    for wr in all_wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in all_wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score candidates: cluster near existing zones, but spread across map
        if np.any(zone_tiles):
            zone_ys_arr, zone_xs_arr = np.where(zone_tiles)
            zone_cx = float(np.mean(zone_xs_arr))
            zone_cy = float(np.mean(zone_ys_arr))
            dist_to_center = np.abs(cxs2 - zone_cx) + np.abs(cys2 - zone_cy)
            # Prefer moderate distance for expansion
            score = dist_to_center
            order = np.argsort(score)
        else:
            # No zones yet: pick near map center
            dist_center = np.abs(cxs2 - 60) + np.abs(cys2 - 50)
            order = np.argsort(dist_center)

        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # === FALLBACK: extend wire toward unpowered empty area ===
    no_power_em = em & ~near_power
    if np.any(no_power_em):
        np_ys, np_xs = np.where(no_power_em)
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0 and len(np_xs) > 0:
            tidx = (step * 13) % len(np_xs)
            tx, ty = int(np_xs[tidx]), int(np_ys[tidx])
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best]), int(wire_ys_arr[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + cross wire spine + initial roads."""
    actions = []
    # Two plants for better coverage
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
