    for wy in [20, 40, 50, 60, 80]:
        for x in range(0, 120, 2):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at key cols
    for wx in [20, 40, 60, 80, 100]:
        for y in range(0, 100, 2):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire spines
    for wy in [20, 40, 50, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def pick_tool():
        # 40% res, 30% com, 30% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- CLOSED-LOOP: react to current map state ----

    # 1) If any zone lacks power, extend wire toward it
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        uzy, uzx = np.where(unpowered_zones)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            idx = int((step * 17) % len(uzx))
            tx, ty = int(uzx[idx]), int(uzy[idx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            bi = np.argmin(dists)
            bwx, bwy = int(wire_xs[bi]), int(wire_ys[bi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # 2) If any zone lacks road access, extend road toward it
    roadless_zones = zone_tiles & ~near_road
    if np.any(roadless_zones):
        rzy, rzx = np.where(roadless_zones)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            idx = int((step * 13) % len(rzx))
            tx, ty = int(rzx[idx]), int(rzy[idx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            bi = np.argmin(dists)
            brx, bry = int(road_xs[bi]), int(road_ys[bi])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # 3) Ensure power coverage: place plant if large region has no power
    phase = step % 10

    if phase == 0:
        # Check if unpowered empty regions exist — place a plant
        unpowered_empty = em & ~near_power
        if np.any(unpowered_empty):
            uey, uex = np.where(unpowered_empty)
            if len(uex) > 0:
                # Place near center of unpowered cluster
                cx = int(np.median(uex))
                cy = int(np.median(uey))
                # Find closest empty cell to centroid
                dists = np.abs(uex - cx) + np.abs(uey - cy)
                bi = np.argmin(dists)
                px, py = int(uex[bi]), int(uey[bi])
                if ib(px, py) and bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)

    elif phase == 1:
        # Extend horizontal wire corridors reactively
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]))
                    right = wx < WORLD_W - 1 and (bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    elif phase == 2:
        # Extend vertical wire corridors reactively
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = wy > 0 and (bool(wm[wy - 1, wc]) or bool(pm[wy - 1, wc]))
                    dn = wy < WORLD_H - 1 and (bool(wm[wy + 1, wc]) or bool(pm[wy + 1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    elif phase == 3:
        # Roads flanking horizontal wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        powered_adj = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        if powered_adj:
                            return (Tool.ROAD, rx, ry)

    elif phase == 4:
        # Roads flanking vertical wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        powered_adj = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        if powered_adj:
                            return (Tool.ROAD, rcx, ry)

    elif phase == 5:
        # Extend roads from existing roads reactively
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            sk = (step * 11) % len(road_xs2)
            for off in range(min(len(road_xs2), 100)):
                k = (sk + off * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 6:
        # Cross-streets between wire rows
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx - 1])) or
                           (rx < WORLD_W - 1 and bool(rm[mid_y, rx + 1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 7:
        # Civic services based on population
        if pop > 30:
            fire_spots = [(5, 5), (30, 5), (60, 5), (90, 5), (115, 5),
                          (5, 30), (30, 30), (60, 30), (90, 30), (115, 30),
                          (5, 50), (115, 50),
                          (5, 70), (30, 70), (60, 70), (90, 70), (115, 70),
                          (5, 95), (30, 95), (60, 95), (90, 95), (115, 95)]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 150:
            police_spots = [(15, 15), (60, 15), (105, 15),
                            (15, 45), (60, 45), (105, 45),
                            (15, 75), (60, 75), (105, 75)]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 500:
            stadium_spots = [(35, 25), (85, 25), (35, 75), (85, 75)]
            for sx, sy in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 1000:
            nuke_spots = [(5, 50), (115, 50), (60, 5), (60, 95)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 2000:
            airports = [(50, 5), (70, 5), (50, 90), (70, 90)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (main closed-loop zone action) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Keep away from wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score candidates by proximity to existing zones (cluster-building)
        # and by proximity to map center
        cx_map, cy_map = WORLD_W // 2, WORLD_H // 2

        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            # Find zone centroid
            zc_x = float(np.mean(zone_xs))
            zc_y = float(np.mean(zone_ys))
            # Score: distance to zone centroid (prefer clustering)
            dist_to_cluster = np.abs(cxs2 - zc_x) + np.abs(cys2 - zc_y)
            # Also consider distance from map center (don't drift too far)
            dist_from_center = np.abs(cxs2 - cx_map) + np.abs(cys2 - cy_map)
            score = dist_to_cluster + dist_from_center * 0.3
        else:
            # No zones yet: start near center
            score = np.abs(cxs2 - cx_map) + np.abs(cys2 - cy_map)

        order = np.argsort(score)
        tool = pick_tool()
        # Use small random offset to avoid getting stuck
        offset = int((step * 7 + pop * 3) % max(len(order), 1))
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # Parks for land value near existing zones
    if pop > 50 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend wire toward map center from nearest wire
    wire_ys3, wire_xs3 = np.where(wm | pm)
    if len(wire_xs3) > 0:
        # Find cell nearest center that has no power
        unpow_empty = em & ~near_power
        if np.any(unpow_empty):
            uey2, uex2 = np.where(unpow_empty)
            cx2, cy2 = WORLD_W // 2, WORLD_H // 2
            dists2 = np.abs(uex2 - cx2) + np.abs(uey2 - cy2)
            bi2 = np.argmin(dists2)
            tx2, ty2 = int(uex2[bi2]), int(uey2[bi2])
            d2 = np.abs(wire_xs3 - tx2) + np.abs(wire_ys3 - ty2)
            bwi = np.argmin(d2)
            bwx2, bwy2 = int(wire_xs3[bwi]), int(wire_ys3[bwi])
            ddx = 0 if tx2 == bwx2 else (1 if tx2 > bwx2 else -1)
            ddy = 0 if ty2 == bwy2 else (1 if ty2 > bwy2 else -1)
            for nx3, ny3 in [(bwx2 + ddx, bwy2), (bwx2, bwy2 + ddy)]:
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire/road spine in center"""
    actions = []
    # Two coal plants near center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire connecting them
    for x in range(28, 93):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(10, 90):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Cross wires
    for x in range(10, 115):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Roads adjacent to wire spines
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    # Vertical roads
    for y in range(5, 95):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
        actions.append((Tool.ROAD, 89, y))
        actions.append((Tool.ROAD, 91, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 45% res, 30% com, 25% ind — more commercial than parent
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire grid lines
    wire_rows = [10, 25, 40, 50, 60, 75, 90]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure coal plants distributed across map
    if phase == 0:
        plant_targets = [
            (30, 10), (90, 10), (10, 50), (60, 15), (110, 15),
            (30, 90), (90, 90), (10, 75), (60, 85), (110, 85),
            (10, 25), (110, 25), (10, 75), (110, 75),
            (60, 50),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill wire row gaps
    if phase == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # Phase 3: Build roads adjacent to wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        if has_wire and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Build roads adjacent to wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                   bool(rm[ry, max(0, rcx-1)]) or \
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if has_wire and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # Phase 5: Add additional coal plants when population demands more power
    if phase == 5 and pop > 100:
        extra_plants = [
            (5, 10), (115, 10), (5, 90), (115, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 30), (90, 30), (30, 70), (90, 70),
        ]
        for px, py in extra_plants:
            x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
            y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                if ib(px, py) and bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)

    # Phase 6: Wire unpowered zones
    if phase == 6:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 7: Extend road network into unpowered but wired areas
    if phase == 7:
        powered_no_road = near_power & ~near_road & em
        powered_no_road[0:3, :] = False
        powered_no_road[WORLD_H-3:, :] = False
        powered_no_road[:, 0:3] = False
        powered_no_road[:, WORLD_W-3:] = False
        pr_ys, pr_xs = np.where(powered_no_road)
        if len(pr_xs) > 0:
            road_ys2, road_xs2 = np.where(rm)
            if len(road_xs2) > 0:
                idx = (step * 19) % len(pr_xs)
                tx, ty = int(pr_xs[idx]), int(pr_ys[idx])
                dists = np.abs(road_xs2 - tx) + np.abs(road_ys2 - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs2[best_ri]), int(road_ys2[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Civic services — fire stations first, scaled to population
    if pop > 10:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 33), (115, 33),
            (5, 50), (60, 50), (115, 50),
            (5, 66), (115, 66),
            (5, 95), (60, 95), (115, 95),
            (30, 18), (90, 18), (30, 82), (90, 82),
            (20, 50), (100, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (20, 8), (50, 8), (80, 8), (110, 8),
            (20, 33), (50, 33), (80, 33), (110, 33),
            (20, 50), (50, 50), (80, 50), (110, 50),
            (20, 66), (50, 66), (80, 66), (110, 66),
            (20, 90), (50, 90), (80, 90), (110, 90),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 250:
        stadium_spots = [
            (20, 15), (80, 15), (20, 85), (80, 85),
            (50, 40), (70, 40), (50, 60), (70, 60),
            (10, 50), (110, 50), (60, 20), (60, 80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power when population is high enough
    if pop > 400:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5, 92), (115, 92), (5, 8), (115, 8)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: primary closed-loop action ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridor rows/cols
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Build in clusters radiating from center, expand as pop grows
        if pop < 50:
            # Start near center
            active_centers = [
                (60, 50), (45, 50), (75, 50),
                (60, 38), (60, 62),
                (45, 38), (75, 38), (45, 62), (75, 62),
            ]
        elif pop < 150:
            active_centers = []
            for row in range(4):
                for col in range(6):
                    cx = 20 + col * 16
                    cy = 20 + row * 20
                    active_centers.append((cx, cy))
        elif pop < 400:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 12 + col * 13
                    cy = 12 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 1000:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 8 + col * 11
                    cy = 8 + row * 11
                    active_centers.append((cx, cy))
        else:
            # Full coverage
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 1000)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
