def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    # ---- NEIGHBORHOOD ANCHORS ----
    anchors = []
    for cx in [15, 45, 75, 105]:
        for cy in [12, 37, 62, 87]:
            anchors.append((cx, cy))

    def num_active():
        if pop < 50:   return 2
        if pop < 200:  return 4
        if pop < 500:  return 8
        if pop < 1000: return 12
        if pop < 2000: return 16
        return len(anchors)

    n_active = min(num_active(), len(anchors))
    active = anchors[:n_active]

    # ---- PHASE 1: Ensure each active anchor has a nearby power plant ----
    for (hx, hy) in active:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and not bool(near_power[hy, hx]):
            # Place coal plant nearby
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Connect unpowered zones with wire ----
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        uz_ys, uz_xs = np.where(unpowered_zones)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            target_idx = (step * 7) % len(uz_xs)
            tx, ty = int(uz_xs[target_idx]), int(uz_ys[target_idx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best = int(np.argmin(dists))
            bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 3: Give road access to zones that lack it ----
    zones_no_road = zone_tiles & ~near_road
    if np.any(zones_no_road):
        zr_ys, zr_xs = np.where(zones_no_road)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_idx = (step * 11) % len(zr_xs)
            tx, ty = int(zr_xs[target_idx]), int(zr_ys[target_idx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best = int(np.argmin(dists))
            brx, bry = int(road_xs[best]), int(road_ys[best])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 4: Extend wire grid (closed-loop) ----
    phase = step % 6

    if phase == 0:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    down = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or down:
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                cx = wc + offset
                if not (0 < cx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, cx]):
                        return (Tool.ROAD, cx, ry)

    elif phase == 4:
        # Extend wire toward uncovered anchors
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            for (hx, hy) in active:
                if not bool(near_power[hy, hx]):
                    dists = np.abs(wire_xs2.astype(float) - hx) + np.abs(wire_ys2.astype(float) - hy)
                    closest_k = int(np.argmin(dists))
                    wx, wy = int(wire_xs2[closest_k]), int(wire_ys2[closest_k])
                    dx = 1 if hx > wx else (-1 if hx < wx else 0)
                    dy = 1 if hy > wy else (-1 if hy < wy else 0)
                    for (ddx, ddy) in [(dx, 0), (0, dy)]:
                        if ddx == 0 and ddy == 0:
                            continue
                        nx, ny = wx + ddx, wy + ddy
                        if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                            return (Tool.WIRE, nx, ny)

    else:
        # Cross-roads between corridor intersections
        cross_ys = [37, 62]
        cross_xs = [45, 75]
        for cy in cross_ys:
            for cx in cross_xs:
                for rx in range(max(1, cx-15), min(WORLD_W-1, cx+16)):
                    if ib(rx, cy) and bool(em[cy, rx]) and bool(near_power[cy, rx]):
                        adj = (rx > 0 and bool(rm[cy, rx-1])) or (rx < WORLD_W-1 and bool(rm[cy, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, cy)
                for ry in range(max(1, cy-15), min(WORLD_H-1, cy+16)):
                    if ib(cx, ry) and bool(em[ry, cx]) and bool(near_power[ry, cx]):
                        adj = (ry > 0 and bool(rm[ry-1, cx])) or (ry < WORLD_H-1 and bool(rm[ry+1, cx]))
                        if adj:
                            return (Tool.ROAD, cx, ry)

    # ---- PHASE 5: Zone placement ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        if np.any(zone_tiles):
            zone_ys_arr, zone_xs_arr = np.where(zone_tiles)
            zone_cx = float(np.mean(zone_xs_arr))
            zone_cy = float(np.mean(zone_ys_arr))
            dist_to_center = np.abs(cxs2 - zone_cx) + np.abs(cys2 - zone_cy)
            order = np.argsort(dist_to_center)
        else:
            # Score by proximity to active anchors
            best_dist = np.full(len(cxs2), 999999.0)
            for (hx, hy) in active:
                d = np.abs(cxs2.astype(float) - hx) + np.abs(cys2.astype(float) - hy)
                best_dist = np.minimum(best_dist, d)
            order = np.argsort(best_dist)

        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [(10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
                      (10, 30), (35, 30), (60, 30), (85, 30), (110, 30),
                      (10, 50), (60, 50), (110, 50),
                      (10, 70), (35, 70), (60, 70), (85, 70), (110, 70),
                      (10, 92), (35, 92), (60, 92), (85, 92), (110, 92)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(25, 15), (75, 15), (50, 40), (100, 40),
                        (25, 60), (75, 60), (10, 85), (50, 85), (90, 85)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(45, 45), (75, 45), (45, 65), (75, 65),
                    (15, 45), (105, 45), (60, 10), (60, 88)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 5), (60, 94), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 7 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire toward unpowered empty areas ----
    no_power_em = em & ~near_power
    if np.any(no_power_em):
        np_ys, np_xs = np.where(no_power_em)
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tidx = (step * 13) % len(np_xs)
            tx, ty = int(np_xs[tidx]), int(np_ys[tidx])
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best = int(np.argmin(dists))
            bwx, bwy = int(wire_xs_arr[best]), int(wire_ys_arr[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend road from existing road into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

