            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    wire_rows = [20, 38, 50, 62, 80]
    wire_cols = [20, 40, 60, 80, 100]

    # Dense grid of neighborhoods covering the map more evenly
    nh_positions = []
    for row in range(8):
        for col in range(8):
            cx = 8 + col * 15
            cy = 8 + row * 12
            cy = min(cy, 93)
            nh_positions.append((cx, cy))

    def get_active_hoods():
