                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Additional cross-streets midway between wire rows
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire cols midpoints
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend roads from existing roads near active hoods
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 19) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase in (8, 9):
        # Fire stations — spread widely for land value
        fire_spots = [
            (10,10),(35,10),(60,10),(85,10),(110,10),
            (10,30),(35,30),(85,30),(110,30),
            (10,50),(60,50),(110,50),
            (10,70),(35,70),(85,70),(110,70),
            (10,90),(35,90),(60,90),(85,90),(110,90),
            (50,44),(70,44),(50,56),(70,56)
        ]
        if pop > 5:
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

    elif phase == 10:
        # Police stations
        police_spots = [
            (20,20),(50,20),(80,20),(110,20),
            (20,44),(50,44),(80,44),(110,44),
            (20,56),(50,56),(80,56),(110,56),
            (20,80),(50,80),(80,80),(110,80)
        ]
        if pop > 50:
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

    elif phase == 11:
        # Stadiums earlier
        if pop > 300:
            for sx, sy in [(30,30),(90,30),(30,70),(90,70),(60,50)]:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)
        # Nuclear power for high pop
        if pop > 500:
            for nx2, ny2 in [(5,50),(115,50),(60,5),(60,95),(5,5),(115,5),(5,95),(115,95),(30,50),(90,50)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    elif phase == 12:
        if pop > 800:
            for sx, sy in [(5,95),(115,95),(5,5),(115,5)]:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 1500:
            for sx, sy in [(50,5),(70,5),(50,92),(70,92)]:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase == 13:
        # Parks for land value boost near dense zones
        if pop > 20:
            park_cands = em & near_road & near_power
            pys, pxs = np.where(park_cands)
            if len(pxs) > 0:
                idx = (step * 37 + pop * 5) % len(pxs)
                return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    elif phase == 14:
        # Extra wire to cover edges
        for wr in wire_rows:
            for wx in [1, WORLD_W-2]:
                if ib(wx, wr) and not bool(wm[wr, wx]) and bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)

    elif phase == 15:
        # Extra cross roads for coverage near population centers
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0 and pop > 100:
            for (hx, hy) in active_hoods[:6]:
                # Try to extend road toward each active hood
                dists = np.abs(road_xs - hx) + np.abs(road_ys - hy)
                best_k = np.argmin(dists)
                rx2, ry2 = int(road_xs[best_k]), int(road_ys[best_k])
                dx = 0 if hx == rx2 else (1 if hx > rx2 else -1)
                dy = 0 if hy == ry2 else (1 if hy > ry2 else -1)
                for nx2, ny2 in [(rx2+dx, ry2), (rx2, ry2+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT (main closed-loop) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors themselves
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx,bwy),(bwx,bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Closed-loop city builder: reactive placement based on observed map state
# Key improvements over parent:
# - True closed-loop: every decision based on current tile_map observation
# - Compact cluster strategy: build outward from power plants
# - Better wire connectivity: flood-fill from plants rather than grid spines
# - Prioritize road+wire adjacency for zone placement

def init(obs, state):
    """Bootstrap: two coal plants + connecting wire + initial road grid."""
    actions = []
    # Central power plant cluster
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire radiating from plant
    for dx in range(1, 8):
        actions.append((Tool.WIRE, cx + dx, cy))
        actions.append((Tool.WIRE, cx - dx, cy))
    for dy in range(1, 6):
        actions.append((Tool.WIRE, cx, cy + dy))
        actions.append((Tool.WIRE, cx, cy - dy))
    # Roads flanking wire (zones need road access)
    for dx in range(-6, 8):
        actions.append((Tool.ROAD, cx + dx, cy + 1))
        actions.append((Tool.ROAD, cx + dx, cy - 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- BUILD ADJACENCY MASKS ----
    # Wire-or-plant neighbor mask (power reachable within 1 tile)
    powered_src = wm | pm
    # Power neighbor: any tile adjacent to wire or plant
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
        sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
        r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
        c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
        nbr_wire[r0:r1, c0:c1] |= powered_src[sr0:sr1, sc0:sc1]

    # Road neighbor mask (within 2 tiles for zone access)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Extended power mask (wire/plant within 5 tiles for zone placement)
    nbr_power5 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power5[r0:r1, c0:c1] |= powered_src[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    # ---- PHASE 1: ENSURE AT LEAST ONE POWER PLANT ----
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # ---- PHASE 2: ENSURE ROAD GRID EXISTS ----
    # Count roads; if very few, build roads adjacent to existing wire
    road_count = int(np.sum(rm))
    wire_count = int(np.sum(wm))

    if road_count < 20 and wire_count > 0:
        # Find wire tiles and place roads adjacent to them
        wys, wxs = np.where(wm)
        for i in range(len(wxs)):
            wx, wy = int(wxs[i]), int(wys[i])
            for dx, dy in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 3: EXTEND WIRE FROM EXISTING WIRE/PLANT ----
    # Find frontier: empty tiles adjacent to wire/plant
    # Strategy: extend wire toward uncovered areas
    # Count coverage
    powered_area = int(np.sum(nbr_power5))
    road_area = int(np.sum(nbr_road))

    # Decide if we need more wire or more roads
    need_wire = powered_area < (WORLD_W * WORLD_H * 0.3)

    if need_wire and wire_count < 300:
        # Find empty tiles adjacent to wire, prioritize those far from center
        wire_frontier = em & nbr_wire & ~pm
        wfy, wfx = np.where(wire_frontier)
        if len(wfx) > 0:
            # Pick based on step to spread coverage
            cx_map, cy_map = 60, 50
            # Extend in all 4 cardinal directions from wire endpoints
            # Find wire tiles at the "frontier" (adjacent to empty)
            wys2, wxs2 = np.where(wm)
            if len(wxs2) > 0:
                # Use step to cycle through wire tiles
                k = (step * 7) % len(wxs2)
                for offset in range(min(len(wxs2), 50)):
                    idx = (k + offset) % len(wxs2)
                    wx, wy = int(wxs2[idx]), int(wys2[idx])
                    # Try to extend in direction away from center
                    dirs = [(1,0),(-1,0),(0,1),(0,-1)]
                    # Sort directions: prefer those going away from center
                    for dx, dy in dirs:
                        nx, ny = wx + dx, wy + dy
                        if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                            # Check this direction makes sense (not into water/blocked)
                            return (Tool.WIRE, nx, ny)

    # ---- PHASE 4: ADD MORE POWER PLANTS IF NEEDED ----
    plant_count = int(np.sum(pm))
    # Add plants when population grows and we need more power
    if pop > 200 * plant_count and funds > 3000:
        # Find empty location not too close to existing plants
        best_x, best_y = -1, -1
        pys, pxs = np.where(pm)
        # Try locations around active zone clusters
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0:
            for i in range(min(len(zone_xs), 30)):
                idx = (step * 3 + i * 7) % len(zone_xs)
                zx, zy = int(zone_xs[idx]), int(zone_ys[idx])
                # Look for empty spot nearby for a plant
                for r in range(3, 12):
                    placed = False
                    for angle_i in range(8):
                        dx2 = int(r * math.cos(angle_i * math.pi / 4))
                        dy2 = int(r * math.sin(angle_i * math.pi / 4))
                        nx, ny = zx + dx2, zy + dy2
                        if not ib(nx, ny): continue
                        if not bool(em[ny, nx]): continue
                        # Check not too close to existing plant
                        min_d = 999
                        for pi in range(len(pxs)):
                            d = abs(int(pxs[pi]) - nx) + abs(int(pys[pi]) - ny)
                            min_d = min(min_d, d)
                        if min_d > 8:
                            return (Tool.COALPOWER, nx, ny)
                    if placed: break

    # ---- PHASE 5: ROAD EXTENSION ----
    # Extend roads into powered areas that lack road access
    road_needed = em & nbr_power5 & ~nbr_road & ~pm
    rny, rnx = np.where(road_needed)
    if len(rnx) > 0 and road_count > 0:
        # Find road tile closest to a powered-but-unroaded area
        rys2, rxs2 = np.where(rm)
        if len(rxs2) > 0:
            # Pick a random road tile and extend toward unroaded powered area
            k = (step * 11) % len(rxs2)
            rx, ry = int(rxs2[k]), int(rys2[k])
            # Find nearest unroaded powered location
            dists = np.abs(rnx - rx) + np.abs(rny - ry)
            nearest = np.argmin(dists)
            tx, ty = int(rnx[nearest]), int(rny[nearest])
            # Move one step toward target
            dx = 1 if tx > rx else (-1 if tx < rx else 0)
            dy = 1 if ty > ry else (-1 if ty < ry else 0)
            # Try primary direction first, then secondary
            for ddx, ddy in [(dx, 0), (0, dy), (dx, dy)]:
                if ddx == 0 and ddy == 0: continue
                nx, ny = rx + ddx, ry + ddy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 6: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% res, 30% com, 30% ind
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: powered AND road-adjacent AND not at edge
    cand_mask = em & nbr_road & nbr_power5
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates: prefer those close to existing zones (cluster growth)
        # but also near roads and power
        if total_zones > 0:
            # Find zone center of mass
            zys_all, zxs_all = np.where(zone_tiles)
            zone_cx = float(np.mean(zxs_all))
            zone_cy = float(np.mean(zys_all))
            # Prefer candidates close to cluster but with room to expand
            dists = np.abs(cxs - zone_cx) + np.abs(cys - zone_cy)
            # Prefer medium distance (not too close, not too far)
            score = dists
            order = np.argsort(score)
        else:
            # No zones yet: place near center of map
            dists = np.abs(cxs - 60) + np.abs(cys - 50)
            order = np.argsort(dists)

        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: ROAD EXTENSION along existing roads ----
    rys3, rxs3 = np.where(rm)
    if len(rxs3) > 0:
        step_k = (step * 13) % len(rxs3)
        for offset in range(min(len(rxs3), 80)):
            k = (step_k + offset * 7) % len(rxs3)
            rx2, ry2 = int(rxs3[k]), int(rys3[k])
            for dx2, dy2 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    # Only extend if near power
                    if bool(nbr_power5[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: CIVIC SERVICES based on population ----
    if pop > 100:
        # Fire stations
        fire_spots = [
            (20,20),(40,20),(60,20),(80,20),(100,20),
            (20,40),(40,40),(60,40),(80,40),(100,40),
            (20,60),(40,60),(60,60),(80,60),(100,60),
            (20,80),(40,80),(60,80),(80,80),(100,80),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (30,30),(50,30),(70,30),(90,30),
            (30,50),(50,50),(70,50),(90,50),
            (30,70),(50,70),(70,70),(90,70),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(30,25),(60,25),(90,25),(30,75),(60,75),(90,75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(5,90),(115,90),(5,10),(115,10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(40,5),(70,5),(40,95),(70,95)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 9: PARKS for land value ----
    if pop > 200 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power5)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from any wire tile ----
    wys4, wxs4 = np.where(wm)
    if len(wxs4) > 0:
        k2 = (step * 17) % len(wxs4)
        for offset in range(min(len(wxs4), 60)):
            k = (k2 + offset * 3) % len(wxs4)
            wx2, wy2 = int(wxs4[k]), int(wys4[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST FALLBACK: new coal plant ----
    for r in range(1, 15):
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                if abs(dx) == r or abs(dy) == r:
                    nx, ny = 60 + dx, 50 + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire + road grid."""
    actions = []
    # Two plants at strategic positions
    for (cx, cy) in [(35, 30), (85, 70)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire cross from plant
        for dx in range(-8, 9):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking wire at offset ±4
        for dy in range(-7, 8):
            actions.append((Tool.ROAD, cx - 4, cy + dy))
            actions.append((Tool.ROAD, cx + 4, cy + dy))
        for dx in range(-7, 8):
            actions.append((Tool.ROAD, cx + dx, cy - 4))
            actions.append((Tool.ROAD, cx + dx, cy + 4))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ── BUILD neighbor-power and neighbor-road masks ONCE ──
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0  = max(0,  dy2); r1  = min(WORLD_H, WORLD_H + dy2)
            c0  = max(0,  dx2); c1  = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0  = max(0,  dy2); r1  = min(WORLD_H, WORLD_H + dy2)
            c0  = max(0,  dx2); c1  = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ── REACTIVE NEIGHBOURHOOD GRID: scaled by pop ──
    all_hoods = [(hx, hy) for hy in range(15, 95, 18)
                           for hx in range(15, 115, 18)]

    def num_active():
        if pop < 50:   return 3
        if pop < 200:  return 6
        if pop < 500:  return 10
        if pop < 1000: return 16
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # ── PHASE 1: ENSURE EACH ACTIVE HOOD HAS A NEARBY PLANT ──
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
            y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ── PHASE 2: WIRE — greedily extend from nearest plant toward hood ──
    # Pick hood based on step rotation
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 14

    x0p, x1p = max(0, hx - 16), min(WORLD_W, hx + 17)
    y0p, y1p = max(0, hy - 16), min(WORLD_H, hy + 17)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0; best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d; best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        # Wire path: vertical first then horizontal
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # ── PHASE 3: EXTEND WIRE SPINES OUTWARD ──
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        min_wr, max_wr = min(col_wire), max(col_wire)
        bot_t = min(WORLD_H - 3, hy + spine)
        top_t = max(2, hy - spine)
        if max_wr < bot_t:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_t:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        min_wc, max_wc = min(row_wire), max(row_wire)
        right_t = min(WORLD_W - 3, hx + spine)
        left_t  = max(2, hx - spine)
        if max_wc < right_t:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_t:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # ── PHASE 4: ROADS adjacent to wire spines (offset ±4 for denser packing) ──
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 4
    for rx in [hx3 - 4, hx3 + 4]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::4]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 4, hy3 + 4]:
        if not ib(hx3, ry): continue
        cyc2 = (step + 1) % 4
        for wc in row_wire3[cyc2::4]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # ── PHASE 5: ZONE PLACEMENT (closed-loop: scan powered+road cells) ──
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 35% ind, 30% com, 35% res
        if ir < 0.35: return Tool.INDUSTRIAL
        if cr < 0.30: return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: proximity to active hoods + proximity to existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4) + np.abs(cys - hy4)
            best_dist = np.minimum(best_dist, d)

        score = best_dist.copy()
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.4 + zone_prox * 0.6

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ── PHASE 6: EXTEND ROAD NETWORK FROM EXISTING ROADS ──
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ── PHASE 7: CIVIC SERVICES (reactive: place only if map shows need) ──
    if pop > 20:
        for fy in range(10, 95, 16):
            for fx in range(10, 115, 16):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 80:
        for py2 in range(14, 92, 18):
            for px2 in range(14, 112, 18):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 150 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 200:
        stadium_locs = [
            (25, 20), (60, 15), (95, 20),
            (25, 80), (60, 85), (95, 80),
            (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear plants for mature cities — reactively check funds + pop
    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5),  (60, 95), (5, 50),  (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50),(60, 30), (60, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        for spx, spy in [(5,50),(115,50),(60,5),(60,95),(5,25),(5,75),(115,25),(115,75)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        for apx, apy in [(10,10),(100,10),(10,85),(100,85),(55,5),(55,93),(5,45),(113,45)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ── FALLBACK: wire from existing plant ──
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ── FALLBACK: extend wire from existing wire ──
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ── FALLBACK: new plant for unpowered hood ──
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy5 in range(-r, r+1):
                    for dx5 in range(-r, r+1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5+dx5, hy5+dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire connections + seed roads in center"""
    actions = []
    # Two coal plants side by side for redundancy
    actions.append((Tool.COALPOWER, 55, 50))
    actions.append((Tool.COALPOWER, 65, 50))
    # Wire horizontally from plants outward
    for x in range(20, 100):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically from center
    for y in range(15, 85):
        actions.append((Tool.WIRE, 55, y))
        actions.append((Tool.WIRE, 65, y))
    # Seed roads parallel to wire
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 44))
        actions.append((Tool.ROAD, x, 56))
    for y in range(10, 90):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # --- PHASE 1: Ensure we have enough power plants ---
    # One plant per ~50 zones, minimum 2
    needed_plants = max(2, total_zones // 50 + 1)
    plant_count = int(np.sum(pm)) // 9  # approx
    pys_arr, pxs_arr = np.where(pm)
    actual_plant_count = len(pxs_arr)

    if actual_plant_count == 0 or (pop > 500 and actual_plant_count < needed_plants):
        # Find empty spot for new plant, away from existing ones
        candidates = [
            (55, 50), (65, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (55, 20), (65, 80), (20, 50), (100, 50)
        ]
        for px, py in candidates:
            if not ib(px, py):
                continue
            x0, x1 = max(0, px-8), min(WORLD_W, px+9)
            y0, y1 = max(0, py-8), min(WORLD_H, py+9)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Extend wire network reactively ---
    # Find frontier: empty cells adjacent to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1,:] = power_src[1:,:]
        elif dy == 1: shifted[1:,:] = power_src[:-1,:]
        elif dx == -1: shifted[:,:-1] = power_src[:,1:]
        elif dx == 1: shifted[:,1:] = power_src[:,:-1]
        adj_to_power |= shifted

    # Identify unpowered zones and zones without road access
    unpowered_zones = zone_tiles & ~near_power
    unserved_zones = zone_tiles & ~near_road
    uzys, uzxs = np.where(unpowered_zones)
    usys, usxs = np.where(unserved_zones)

    # Wire candidate cells: empty, adjacent to power, not on zone or road
    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:3,:] = False; wire_cand[WORLD_H-3:,:] = False
    wire_cand[:,0:3] = False; wire_cand[:,WORLD_W-3:] = False

    # If there are unpowered zones, extend wire toward them
    wys_c, wxs_c = np.where(wire_cand)
    if len(wxs_c) > 0 and len(uzxs) > 0:
        # Find wire candidate closest to any unpowered zone
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 30)
        for i in range(min(len(wxs_c), 300)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                    for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        if best_d < 50:  # Only extend if reasonably close
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # --- PHASE 3: Extend road network toward unserved zones ---
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1,:] = rm[1:,:]
        elif dy == 1: shifted[1:,:] = rm[:-1,:]
        elif dx == -1: shifted[:,:-1] = rm[:,1:]
        elif dx == 1: shifted[:,1:] = rm[:,:-1]
        adj_to_road |= shifted

    road_cand = em & adj_to_road & ~zone_tiles & ~pm
    road_cand[0:3,:] = False; road_cand[WORLD_H-3:,:] = False
    road_cand[:,0:3] = False; road_cand[:,WORLD_W-3:] = False

    rys_c, rxs_c = np.where(road_cand)
    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 30)
        for i in range(min(len(rxs_c), 300)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                    for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        if best_d < 50:
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # --- PHASE 4: Zone placement (closed-loop, reactive) ---
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Zone candidates: empty, near power AND near road
    zone_cand = em & near_road & near_power
    zone_cand[0:4,:] = False; zone_cand[WORLD_H-4:,:] = False
    zone_cand[:,0:4] = False; zone_cand[:,WORLD_W-4:] = False
    # Don't place zones on wire rows or road rows used as infrastructure
    for row in [44, 50, 56]:
        if 0 <= row < WORLD_H:
            zone_cand[row,:] = False
    for col in [50, 55, 65, 70]:
        if 0 <= col < WORLD_W:
            zone_cand[:,col] = False

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer spots close to existing zones (density) but not too close
        zone_ys, zone_xs = np.where(zone_tiles)
        road_ys2, road_xs2 = np.where(rm)

        # Distance to nearest road
        if len(road_xs2) > 0:
            stride = max(1, len(road_xs2) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs2), stride):
                d = (np.abs(cxs_arr - road_xs2[i]).astype(float) +
                     np.abs(cys_arr - road_ys2[i]).astype(float))
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Distance to nearest zone (prefer some clustering but not overcrowding)
        if len(zone_xs) > 0:
            stride2 = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride2):
                d = (np.abs(cxs_arr - zone_xs[i]).astype(float) +
                     np.abs(cys_arr - zone_ys[i]).astype(float))
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Penalize too close (<3) or too far (>20)
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                         np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            # Start near center
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.2

        score = road_dist * 2.0 + zone_score
        order = np.argsort(score)

        # Use step-based offset for variety
        off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services based on population ---
    if pop > 200:
        fire_spots = [(fx, fy) for fy in range(10, 90, 15) for fx in range(10, 110, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(pm[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 500:
        police_spots = [(px2, py2) for py2 in range(12, 88, 18) for px2 in range(12, 108, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]) and not bool(pm[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 800:
        stadium_spots = [(sx, sy) for sy in range(20, 85, 30) for sx in range(20, 105, 35)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]) and not bool(pm[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(8, 94, 10) for pkx in range(8, 114, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]) and not bool(pm[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 1000:
        nuclear_spots = [(nx, ny) for ny in range(20, 85, 25) for nx in range(20, 105, 25)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx-10), min(WORLD_W, npx+11)
                y0, y1 = max(0, npy-10), min(WORLD_H, npy+11)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 7), (65, 7), (7, 44), (112, 44)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- PHASE 6: Extend infrastructure proactively ---
    # Extend road network outward from existing roads
    if len(rxs_c) > 0:
        # Extend toward map center if road doesn't cover center
        cx_map, cy_map = 60, 50
        best_d = 1e9
        best_k = 0
        for i in range(min(len(rxs_c), 200)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = abs(cx - cx_map) + abs(cy - cy_map)
            if d < best_d:
                best_d = d
                best_k = i
        if best_d > 5:
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Extend wire network outward
    if len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # Fallback: place road near any plant
    if len(pxs_arr) > 0:
        k = step % len(pxs_arr)
        px2, py2 = int(pxs_arr[k]), int(pys_arr[k])
        for dx2, dy2 in [(5,0),(-5,0),(0,5),(0,-5),(8,0),(-8,0),(0,8),(0,-8)]:
            nx2, ny2 = px2+dx2, py2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire spines and flanking roads."""
    actions = []
    # Two anchor plants
    actions.append((Tool.COALPOWER, 38, 50))
    actions.append((Tool.COALPOWER, 78, 50))
    # Horizontal wire spine
    for x in range(5, 115):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire at both plant columns
    for y in range(5, 95):
        actions.append((Tool.WIRE, 38, y))
        actions.append((Tool.WIRE, 78, y))
    # Roads flanking vertical spines
    for y in range(5, 95):
        actions.append((Tool.ROAD, 37, y))
        actions.append((Tool.ROAD, 39, y))
        actions.append((Tool.ROAD, 77, y))
        actions.append((Tool.ROAD, 79, y))
    # Roads above/below horizontal spine
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Active neighborhood anchors based on population
    all_anchors = []
    for col_i, cx in enumerate([18, 38, 58, 78, 98]):
        for row_i, cy in enumerate([18, 38, 58, 78]):
            all_anchors.append((cx, cy))

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 350:  return 4
        if pop < 700:  return 6
        if pop < 1200: return 9
        if pop < 2000: return 13
        return 20

    active = all_anchors[:num_active()]

    # Wire spine columns and rows
    wire_cols = [18, 38, 58, 78, 98]
    wire_rows = [18, 38, 50, 58, 78]

    # ---- PHASE 1: Ensure each active anchor has a nearby power plant ----
    for (px, py) in active:
        has_plant = bool(np.any(pm[max(0, py-6):min(WORLD_H, py+7),
                                    max(0, px-6):min(WORLD_W, px+7)]))
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Extend wire toward uncovered active anchors ----
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0:
        for (px, py) in active:
            dists = np.abs(wire_xs.astype(float) - px) + np.abs(wire_ys.astype(float) - py)
            min_dist = float(dists.min())
            if min_dist > 4:
                closest_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[closest_k]), int(wire_ys[closest_k])
                dx = 1 if px > wx else (-1 if px < wx else 0)
                dy = 1 if py > wy else (-1 if py < wy else 0)
                for (ddx, ddy) in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: Vertical wire spines for each active anchor ----
    for (px, py) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        ext = min(25, 10 + pop // 60)
        spine_top = max(3, py - ext)
        spine_bot = min(WORLD_H - 4, py + ext)
        if wire_col:
            max_wr = max(wire_col)
            min_wr = min(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and bool(em[nr, px]):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and bool(em[nr, px]):
                    return (Tool.WIRE, px, nr)
        else:
            for dy2 in range(-6, 7):
                ny = py + dy2
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)

    # ---- PHASE 4: Horizontal wire connections between same-row anchors ----
    row_groups = {}
    for (px, py) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append(px)

    for row_y, group in row_groups.items():
        group_sorted = sorted(group)
        for i in range(len(group_sorted) - 1):
            x1, x2 = group_sorted[i], group_sorted[i + 1]
            for cx2 in range(x1 + 1, x2):
                if ib(cx2, row_y) and bool(em[row_y, cx2]) and not bool(pm[row_y, cx2]):
                    return (Tool.WIRE, cx2, row_y)

    # ---- PHASE 5: Roads flanking vertical wire spines ----
    for (px, py) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_col:
            continue
        cycle_off = (step + px) % max(len(wire_col), 1)
        for k in range(min(len(wire_col), 15)):
            wr = wire_col[(cycle_off + k) % len(wire_col)]
            for road_x in [px - 1, px + 1]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- PHASE 6: Horizontal roads at anchor rows ----
    for (px, py) in active:
        for dx in range(-10, 11):
            rx = px + dx
            if not ib(rx, py):
                continue
            if bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near = any(
                    ib(rx + d, py) and (bool(rm[py, rx + d]) or bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near:
                    return (Tool.ROAD, rx, py)

    # ---- PHASE 7: Add cross-roads to increase connectivity ----
    # Horizontal roads between vertical spines at mid-points
    step_mod = step % 8
    if step_mod == 0:
        for ri in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[ri], wire_rows[ri + 1]
            for frac in [0.33, 0.67]:
                mid_y = int(r1 + (r2 - r1) * frac)
                for rx in range(2, WORLD_W - 2):
                    if bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]) and bool(near_power[mid_y, rx]):
                        adj = ((rx > 0 and bool(rm[mid_y, rx - 1])) or
                               (rx < WORLD_W - 1 and bool(rm[mid_y, rx + 1])))
                        if adj:
                            return (Tool.ROAD, rx, mid_y)

    # ---- PHASE 8: Zone placement (closed-loop, reactive) ----
    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(wm | pm, 5)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Avoid wire spine tiles themselves
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 3 + pop * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 9: Civic services ----
    if pop > 100:
        fire_spots = [
            (8, 8), (28, 8), (48, 8), (68, 8), (88, 8), (108, 8),
            (8, 30), (108, 30),
            (8, 50), (108, 50),
            (8, 70), (108, 70),
            (8, 90), (28, 90), (48, 90), (68, 90), (88, 90), (108, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (28, 28), (48, 28), (68, 28), (88, 28),
            (28, 48), (88, 48),
            (28, 68), (48, 68), (68, 68), (88, 68),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 900:
        stadiums = [
            (15, 10), (55, 10), (95, 10),
            (15, 90), (55, 90), (95, 90),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 88), (108, 88), (10, 10), (108, 10)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        nuke_spots = [
            (5, 50), (113, 50), (58, 5), (58, 93),
            (20, 20), (96, 20), (20, 78), (96, 78),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        airports = [(50, 5), (60, 5), (70, 5), (50, 92), (60, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- FALLBACK: Extend road from existing road into powered area ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 100)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: Extend wire from existing wire ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        sk2 = (step * 17) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 60)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: Park for land value ----
    if pop > 200 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    return None

def init(obs, state):
