    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Efficient dilation using numpy slicing
    def dilate(mask, r):
        result = mask.astype(bool).copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 35% res, 30% com, 35% ind initially, more res as city grows
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood grid: 5 cols x 5 rows = 25 hoods
    nh_cols = [12, 35, 60, 85, 108]
    nh_rows = [10, 28, 50, 72, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 7
        if pop < 800:   return 12
        if pop < 1500:  return 17
        if pop < 3000:  return 20
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_sz = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    # Power and road proximity
    power_src = wm | pm
    nbr_power = dilate(power_src, 6)
    nbr_road = dilate(rm, 3)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: Ensure power plant near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
        y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Wire spine from plant toward hood ----
    spine_half = min(20, 8 + pop // 40)
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
    y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_loc = int(plant_xs[0]) + x0
        py_loc = int(plant_ys[0]) + y0

        # Wire vertically from plant toward hood center
        if py_loc != hy:
            sd = 1 if hy > py_loc else -1
            for wy in range(py_loc + sd, hy + sd, sd):
                if not ib(px_loc, wy): continue
                if bool(pm[wy, px_loc]) or bool(wm[wy, px_loc]): continue
                if not bool(em[wy, px_loc]): continue
                return (Tool.WIRE, px_loc, wy)

        # Extend vertical spine up and down
        spine_top = max(2, hy - spine_half)
        spine_bot = min(WORLD_H - 3, hy + spine_half)
        wire_col = [r for r in range(spine_top, spine_bot + 1)
                    if ib(hx, r) and bool(wm[r, hx])]
        if not wire_col:
            for dy in range(-4, 5):
                ny = hy + dy
                if ib(hx, ny) and bool(em[ny, hx]) and not bool(pm[ny, hx]):
                    return (Tool.WIRE, hx, ny)
        else:
            max_wr = max(wire_col)
            min_wr = min(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)

    # ---- PHASE 3: Horizontal wire connecting same-row hoods ----
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        row_hoods.sort(key=lambda h: h[0])
        for i in range(len(row_hoods) - 1):
            hx1 = row_hoods[i][0]
            hx2 = row_hoods[i + 1][0]
            for cx2 in range(hx1, hx2 + 1):
                if ib(cx2, hy_row) and bool(em[hy_row, cx2]) and not bool(pm[hy_row, cx2]) and not bool(wm[hy_row, cx2]):
                    return (Tool.WIRE, cx2, hy_row)

    # ---- PHASE 4: Vertical wire connecting same-col hoods ----
    if n_active >= 3:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for cy2 in range(hy1, hy2 + 1):
                    if ib(hx_col, cy2) and bool(em[cy2, hx_col]) and not bool(pm[cy2, hx_col]) and not bool(wm[cy2, hx_col]):
                        return (Tool.WIRE, hx_col, cy2)

    # ---- PHASE 5: Roads flanking wire spines ----
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]
    spine_top3 = max(2, hy3 - spine_half)
    spine_bot3 = min(WORLD_H - 3, hy3 + spine_half)
    wire_col3 = [r for r in range(spine_top3, spine_bot3 + 1)
                 if ib(hx3, r) and (bool(wm[r, hx3]) or bool(pm[r, hx3]))]
    cycle = step % 4
    for wr in wire_col3[cycle::4]:
        for rx in [hx3 - 2, hx3 + 2]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    # ---- PHASE 6: Horizontal roads at ±3 from hood rows ----
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        if len(row_hoods) < 1: continue
        row_hoods.sort(key=lambda h: h[0])
        xl = row_hoods[0][0] - 2
        xr = row_hoods[-1][0] + 2
        for horiz_y in [hy_row - 3, hy_row + 3]:
            if not (0 < horiz_y < WORLD_H - 1): continue
            for cx3 in range(max(2, xl), min(WORLD_W - 2, xr + 1)):
                if ib(cx3, horiz_y) and bool(em[horiz_y, cx3]) and not bool(pm[horiz_y, cx3]):
                    # Only place if adjacent road exists or it's near a wire hood
                    near_wire = bool(wm[horiz_y, cx3]) or any(
                        ib(cx3+ddx, horiz_y+ddy) and (bool(wm[horiz_y+ddy, cx3+ddx]) or bool(pm[horiz_y+ddy, cx3+ddx]))
                        for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]
                    )
                    adj_road = any(
                        ib(cx3+ddx, horiz_y+ddy) and bool(rm[horiz_y+ddy, cx3+ddx])
                        for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]
                    )
                    if near_wire or adj_road:
                        return (Tool.ROAD, cx3, horiz_y)

    # ---- PHASE 7: Vertical roads between hood rows ----
    if pop > 60 and len(nh_rows) >= 2:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for rx2 in [hx_col - 3, hx_col + 3]:
                    for cy3 in range(hy1, hy2 + 1):
                        if ib(rx2, cy3) and bool(em[cy3, rx2]) and not bool(pm[cy3, rx2]):
                            adj_road = any(
                                ib(rx2+ax, cy3+ay) and bool(rm[cy3+ay, rx2+ax])
                                for ax, ay in [(-1,0),(1,0),(0,-1),(0,1)]
                            )
                            if adj_road or cy3 == hy1 or cy3 == hy2:
                                return (Tool.ROAD, rx2, cy3)

    # ---- PHASE 8: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 9: Extend roads near powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy)
                      for fx in range(10, WORLD_W, 20)
                      for fy in range(10, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2)
                        for px2 in range(14, WORLD_W, 25)
                        for py2 in range(14, WORLD_H, 25)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (20, 8), (60, 8), (100, 8),
            (20, 92), (60, 92), (100, 92),
            (8, 50), (112, 50), (40, 50), (80, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (6, 6), (114, 6), (6, 94), (114, 94),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (30, 6), (90, 6), (30, 94), (90, 94),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2000:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [
            (40, 5), (80, 5), (40, 94), (80, 94),
            (5, 35), (5, 65), (115, 35), (115, 65),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 150 and step % 6 == 0:
        zone_ys2, zone_xs2 = np.where(zone_tiles)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # ---- FALLBACK: new plant near uncovered hood ----
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 15):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with road+wire grid skeleton"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire outward from plant in 4 directions
    for x in range(62, 100):
        actions.append((Tool.WIRE, x, 50))
    for x in range(20, 59):
        actions.append((Tool.WIRE, x, 50))
    for y in range(30, 49):
        actions.append((Tool.WIRE, 60, y))
    for y in range(51, 70):
        actions.append((Tool.WIRE, 60, y))
    # Road grid: horizontal roads every 6 rows
    for ry in [32, 38, 44, 56, 62, 68]:
        for rx in range(5, 115):
            actions.append((Tool.ROAD, rx, ry))
    # Road grid: vertical roads every 8 cols
    for rx in [20, 28, 36, 44, 52, 60, 68, 76, 84, 92, 100]:
        for ry in range(28, 73):
            actions.append((Tool.ROAD, rx, ry))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Zone mix: 35% res, 40% com, 25% ind — more commercial bias
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.40:
            return Tool.COMMERCIAL
        if rr < 0.35:
            return Tool.RESIDENTIAL
        return Tool.COMMERCIAL

    # --- PHASE 1: Place coal plants in a tighter grid ---
    plant_positions = []
    for py in range(15, 90, 25):
        for px in range(15, 110, 25):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Extend wire toward unpowered areas ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Wire toward unpowered plants
        unpowered_plants = [(ppx, ppy) for ppx, ppy in plant_positions
                            if ib(ppx, ppy) and not bool(near_power[ppy, ppx])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Build denser road grid (every 6 tiles, columns every 8) ---
    road_rows = list(range(6, 95, 6))
    road_cols = list(range(8, 113, 8))

    # Build horizontal roads first
    for gy in road_rows:
        for gx in range(4, 117):
            if ib(gx, gy) and bool(near_power[gy, gx]) and bool(em[gy, gx]) and not bool(rm[gy, gx]):
                return (Tool.ROAD, gx, gy)

    # Build vertical roads
    for gx in road_cols:
        for gy in range(4, 97):
            if ib(gx, gy) and bool(near_power[gy, gx]) and bool(em[gy, gx]) and not bool(rm[gy, gx]):
                return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Place zones with commercial focus ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Close to road, spread from zones, prefer clusters
        score = road_dist * 1.2 + np.maximum(0, 6 - zone_dist) * 1.5

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Zone type: heavy commercial/industrial rotation
        # 3 com, 2 res, 2 ind per 7-step cycle
        step_mod = step % 7
        if step_mod < 3:
            tool = Tool.COMMERCIAL
        elif step_mod < 5:
            tool = Tool.RESIDENTIAL
        else:
            tool = Tool.INDUSTRIAL
        # Override with ratio check
        tool = pick_tool() if (ind_count / max(total_zones, 1) < 0.15 or
                                com_count / max(total_zones, 1) < 0.30 or
                                res_count / max(total_zones, 1) < 0.25) else tool

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 50:
        for fsy in range(9, 95, 9):
            for fsx in range(9, 112, 9):
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
