def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target ratio: 40% RES, 30% COM, 30% IND — more commercial/industrial than parent
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Grid of wire columns and rows — denser grid than parent
    wire_cols = [12, 24, 36, 48, 60, 72, 84, 96, 108]
    wire_rows = [12, 24, 36, 48, 60, 72, 84]
    road_offsets = [-3, 3]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 0: Place coal plants where area lacks power ----
    if step % 6 == 0:
        plant_targets = [(px, py) for py in [12, 25, 50, 75, 88]
                         for px in [12, 36, 60, 84, 108]]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 20), min(WORLD_W, px + 21)
            y0, y1 = max(0, py - 20), min(WORLD_H, py + 21)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(20):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # ---- PHASE 1: Extend wire rows ----
    if step % 7 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]):
                    continue
                if not bool(em[wr, wx]):
                    continue
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    return (Tool.WIRE, wx, wr)

    # ---- PHASE 2: Extend wire cols ----
    if step % 7 == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if bool(wm[wy, wc]) or bool(pm[wy, wc]):
                    continue
                if not bool(em[wy, wc]):
                    continue
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: Roads flanking wire rows ----
    if step % 7 == 3:
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  bool(rm[max(0,ry-1), rx]) or bool(rm[min(WORLD_H-1,ry+1), rx])
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Roads flanking wire cols ----
    if step % 7 == 4:
        for wc in wire_cols:
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

    # ---- PHASE 5: Wire toward unpowered zones ----
    if step % 7 == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 6: Road toward unserved powered areas ----
    if step % 7 == 6:
        powered_no_road = near_power & ~near_road & em
        pnr_ys, pnr_xs = np.where(powered_no_road)
        if len(pnr_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(pnr_xs)
                tx, ty = int(pnr_xs[idx]), int(pnr_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES — placed more aggressively ----
    if pop > 5:
        fire_spots = [
            (6, 6), (30, 6), (60, 6), (90, 6), (114, 6),
            (6, 30), (114, 30),
            (6, 50), (114, 50),
            (6, 70), (114, 70),
            (6, 93), (30, 93), (60, 93), (90, 93), (114, 93),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (20, 50), (50, 50), (70, 50), (100, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 20:
        police_spots = [
            (18, 18), (42, 18), (66, 18), (90, 18), (114, 18),
            (18, 42), (42, 42), (66, 42), (90, 42), (114, 42),
            (18, 66), (42, 66), (66, 66), (90, 66), (114, 66),
            (18, 90), (42, 90), (66, 90), (90, 90), (114, 90),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 100:
        stadium_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 200:
        nuke_spots = [
            (6, 50), (114, 50), (60, 6), (60, 93),
            (6, 25), (114, 25), (6, 75), (114, 75),
            (30, 6), (90, 6), (30, 93), (90, 93),
            (6, 12), (6, 88), (114, 12), (114, 88),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 400:
        seaports = [(6, 90), (114, 90), (6, 10), (114, 10),
                    (60, 6), (60, 93), (6, 50), (114, 50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 800:
        airports = [(50, 6), (70, 6), (50, 92), (70, 92),
                    (6, 44), (110, 44), (6, 56), (110, 56)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near road and power to boost land value
    if pop > 30 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Avoid wire corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scale active placement centers with population growth
        # Use a grid of centers that grows as population grows
        if pop < 80:
            # Start from center cluster
            active_centers = [(cx, cy) for cy in [43, 46, 54, 57]
                              for cx in [24, 36, 48, 60, 72, 84, 96]]
        elif pop < 250:
            active_centers = [(cx, cy) for cy in [15, 21, 27, 33, 39, 43, 46, 54, 57, 61, 67, 73, 79, 85]
                              for cx in [15, 25, 36, 45, 55, 65, 75, 85, 95, 105]]
        else:
            # Full map coverage with denser grid
            active_centers = [(cx, cy) for cy in range(6, 100, 6)
                              for cx in range(6, 120, 6)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- FALLBACK: extend road into powered area ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant near unpowered area ----
    all_hoods = [(cx, cy) for cy in range(8, 100, 8) for cx in range(6, 120, 8)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# New city builder: compact radial neighborhoods, better zone mix, reactive growth
# Key differences from parent:
# 1. Radial layout centered at map center with 6 satellite neighborhoods
# 2. More aggressive commercial/industrial ratio (2:1:1 RES:COM:IND)
# 3. Nuclear plants added earlier for better coverage
# 4. Denser road grid with cross-streets, not just flanking wires
# 5. Civic buildings placed more aggressively

def init(obs, state):
    """Bootstrap: 3 coal plants + wire cross + flanking roads."""
    actions = []
    # 3 coal plants: center and two flanks
    for px, py in [(60, 50), (25, 25), (95, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Wire spines from center plants
    for x in range(5, 115):
        actions.append((Tool.WIRE, x, 50))
    for y in range(5, 95):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking main wire spine
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    for y in range(5, 95):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Target ratio: 50% res, 30% com, 20% ind
    def pick_tool():
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 3)
    zone_tiles = resm | comm | indm

    # Neighborhood centers: center + ring of 6 + outer ring
    # Reactive: expand neighborhoods as population grows
    core_hoods = [(60, 50)]
    ring1 = [(60, 25), (60, 75), (35, 38), (85, 38), (35, 62), (85, 62)]
    ring2 = [(15, 15), (60, 10), (105, 15), (15, 50), (105, 50),
             (15, 85), (60, 90), (105, 85), (35, 15), (85, 15),
             (35, 85), (85, 85), (10, 35), (110, 35), (10, 65), (110, 65)]
    ring3 = [(40, 25), (80, 25), (40, 75), (80, 75),
             (20, 50), (100, 50), (60, 35), (60, 65)]

    def get_active_hoods():
        if pop < 30:
            return core_hoods
        elif pop < 100:
            return core_hoods + ring1[:3]
        elif pop < 250:
            return core_hoods + ring1
        elif pop < 500:
            return core_hoods + ring1 + ring3[:4]
        elif pop < 900:
            return core_hoods + ring1 + ring3
        elif pop < 1500:
            return core_hoods + ring1 + ring3 + ring2[:8]
        else:
            return core_hoods + ring1 + ring3 + ring2

    active_hoods = get_active_hoods()

    # Wire corridors: main cross + diagonals
    wire_rows = [10, 25, 38, 50, 62, 75, 90]
    wire_cols = [10, 25, 40, 60, 80, 95, 110]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Phase 1: Ensure power coverage for active hoods
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
        y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find nearest empty cell to place plant
            for r in range(1, 18):
                found = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx + dx, hy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if found:
                    break

    # Phase 2: Wire horizontal corridors
    if step % 10 in (0, 1):
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left_ok = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right_ok = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left_ok or right_ok) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 3: Wire vertical corridors
    if step % 10 in (2, 3):
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up_ok = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn_ok = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up_ok or dn_ok) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 4: Roads alongside wire rows (both sides)
    if step % 10 == 4:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    # Phase 5: Roads alongside wire cols
    if step % 10 == 5:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    # Phase 6: Cross-streets between wire rows (midpoint roads)
    if step % 10 == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            if not (0 < mid_y < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]) and bool(near_power[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 7: Cross-streets between wire cols
    if step % 10 == 7:
        for wci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wci], wire_cols[wci + 1]
            mid_x = (c1 + c2) // 2
            if not (0 < mid_x < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]) and bool(near_power[ry, mid_x]):
                    adj = (ry > 0 and bool(rm[ry-1, mid_x])) or (ry < WORLD_H-1 and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Civic services — placed more aggressively
    if pop > 40:
        fire_spots = [(x, y) for y in range(10, 95, 15) for x in range(10, 115, 18)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 120:
        police_spots = [(x, y) for y in range(15, 95, 18) for x in range(15, 115, 20)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # Nuclear power for extra coverage once pop warrants
    if pop > 300:
        nuke_spots = [(5, 5), (113, 5), (5, 93), (113, 93),
                      (5, 50), (113, 50), (60, 5), (60, 93),
                      (30, 5), (90, 5), (30, 93), (90, 93)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 500:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50), (10, 50), (110, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        seaports = [(5, 90), (113, 90), (5, 10), (113, 10), (60, 90)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(45, 5), (75, 5), (45, 92), (75, 92), (5, 40), (113, 40)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Zone placement: find best candidates near active neighborhoods
    cand_mask = em & near_road & near_power
    # Buffer from edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep away from wire corridors to preserve connectivity
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 5) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # Parks for land value boost
    if pop > 60 and step % 5 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend roads into powered empty areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 9) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Wire toward unpowered hoods
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Extend existing wires
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: coal plant near unpowered hood
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire grid + flanking roads."""
    actions = []
    # Two central coal plants
    plants = [(30, 50), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire at y=50
    for x in range(1, 119):
        if x not in [30, 90]:
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(1, 99):
        for wc in [30, 60, 90]:
            actions.append((Tool.WIRE, wc, y))
    # Roads flanking horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Wire/road grid parameters
    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]
    road_offsets = [-1, 1]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PRIORITY 1: Fix unpowered zones — wire toward them ===
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        uz_ys, uz_xs = np.where(unpowered_zones)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            target_idx = (step * 7) % len(uz_xs)
            tx, ty = int(uz_xs[target_idx]), int(uz_ys[target_idx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best = int(np.argmin(dists))
            bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === PRIORITY 2: Fix zones without road access ===
    zones_no_road = zone_tiles & ~near_road
    if np.any(zones_no_road):
        zr_ys, zr_xs = np.where(zones_no_road)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_idx = (step * 11) % len(zr_xs)
            tx, ty = int(zr_xs[target_idx]), int(zr_ys[target_idx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best = int(np.argmin(dists))
            brx, bry = int(road_xs[best]), int(road_ys[best])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PRIORITY 3: Ensure power plants spread across map ===
    plant_targets = [(px, py) for py in [20, 50, 80] for px in [15, 45, 75, 105]]
    if step % 6 == 0:
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # === PHASE-BASED GRID EXTENSION ===
    phase = step % 6

    if phase == 0:
        # Extend horizontal wire rows
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]):
                    continue
                if not bool(em[wr, wx]):
                    continue
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire columns
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if bool(wm[wy, wc]) or bool(pm[wy, wc]):
                    continue
                if not bool(em[wy, wc]):
                    continue
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Extend roads flanking horizontal wire rows
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Extend roads flanking vertical wire columns
        for wc in wire_cols:
            for offset in road_offsets:
                cx2 = wc + offset
                if not (0 < cx2 < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, cx2]):
                        return (Tool.ROAD, cx2, ry)

    elif phase == 4:
        # Add cross-roads between corridors
        cross_ys = [37, 62]
        cross_xs = [45, 75]
        for cy2 in cross_ys:
            for cx2 in cross_xs:
                for rx in range(max(1, cx2 - 15), min(WORLD_W - 1, cx2 + 16)):
                    if ib(rx, cy2) and bool(em[cy2, rx]) and bool(near_power[cy2, rx]):
                        adj = (rx > 0 and bool(rm[cy2, rx-1])) or (rx < WORLD_W-1 and bool(rm[cy2, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, cy2)

    else:
        # Vertical cross-roads
        cross_ys = [37, 62]
        cross_xs = [45, 75]
        for cy2 in cross_ys:
            for cx2 in cross_xs:
                for ry in range(max(1, cy2 - 15), min(WORLD_H - 1, cy2 + 16)):
                    if ib(cx2, ry) and bool(em[ry, cx2]) and bool(near_power[ry, cx2]):
                        adj = (ry > 0 and bool(rm[ry-1, cx2])) or (ry < WORLD_H-1 and bool(rm[ry+1, cx2]))
                        if adj:
                            return (Tool.ROAD, cx2, ry)

    # === CIVIC SERVICES ===
    if pop > 30:
        fire_spots = [
            (10, 5), (35, 5), (60, 5), (85, 5), (110, 5),
            (10, 30), (35, 30), (60, 30), (85, 30), (110, 30),
            (10, 50), (60, 50), (110, 50),
            (10, 70), (35, 70), (60, 70), (85, 70), (110, 70),
            (10, 92), (35, 92), (60, 92), (85, 92), (110, 92),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (25, 15), (75, 15), (50, 40), (100, 40),
            (25, 60), (75, 60), (10, 85), (50, 85), (90, 85),
            (15, 12), (45, 12), (75, 12), (105, 12),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (45, 45), (75, 45), (45, 65), (75, 65),
            (15, 45), (105, 45), (60, 10), (60, 88),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5), (5, 50), (115, 50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 80 and step % 7 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # === ZONE PLACEMENT ===
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        if np.any(zone_tiles):
            zone_ys_arr, zone_xs_arr = np.where(zone_tiles)
            zone_cx = float(np.mean(zone_xs_arr))
            zone_cy = float(np.mean(zone_ys_arr))
            dist_to_center = np.abs(cxs2 - zone_cx) + np.abs(cys2 - zone_cy)
            order = np.argsort(dist_to_center)
        else:
            dist_center = np.abs(cxs2 - 60) + np.abs(cys2 - 50)
            order = np.argsort(dist_center)

        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # === FALLBACK: extend wire toward unpowered empty areas ===
    no_power_em = em & ~near_power
    if np.any(no_power_em):
        np_ys, np_xs = np.where(no_power_em)
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tidx = (step * 13) % len(np_xs)
            tx, ty = int(np_xs[tidx]), int(np_ys[tidx])
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best = int(np.argmin(dists))
            bwx, bwy = int(wire_xs_arr[best]), int(wire_ys_arr[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: place coal plant near area lacking power ===
    all_hoods = [(cx2, cy2) for cy2 in range(10, 100, 15) for cx2 in range(10, 120, 15)]
    for hx, hy in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = hx + dx, hy + dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along vertical wire
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Horizontal roads flanking horizontal wire
    for dx in range(-7, 8):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID ---- denser than parent
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 19, 30, 41, 52, 63, 74, 85, 96]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 35
        if pop < 4000:  return 50
        if pop < 8000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE EACH ACTIVE HOOD HAS A POWER PLANT NEARBY ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 18):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: GROW WIRE TOWARD UNCOVERED HOODS ----
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            for (tx, ty) in uncovered:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy), (dx, dy)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: BUILD ROAD GRID CONNECTING HOODS ----
    # For each active hood, build roads in a cross pattern
    hood_cycle = step % max(len(active_hoods), 1)
    spine_range = 6

    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Build roads adjacent to wire at each hood
        # Horizontal road above/below wire row
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    rcx = hx + sign * dist
                    if not ib(rcx, ry2): continue
                    if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                        if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                            return (Tool.ROAD, rcx, ry2)
        # Vertical road left/right of wire column
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    rcy = hy + sign * dist
                    if not ib(rx, rcy): continue
                    if bool(em[rcy, rx]) and not bool(pm[rcy, rx]):
                        if bool(wm[rcy, hx]) or bool(pm[rcy, hx]):
                            return (Tool.ROAD, rx, rcy)

    # ---- PHASE 4: EXTEND WIRE SPINES ----
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wy = hy + sign * dist
                if not ib(hx, wy): continue
                if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
                if not bool(em[wy, hx]): continue
                for ay in [wy - 1, wy + 1]:
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, wy)
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wx = hx + sign * dist
                if not ib(wx, hy): continue
                if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                for ax in [wx - 1, wx + 1]:
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, wx, hy)

    # ---- PHASE 5: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and 10 <= abs(hx2 - hx1) <= 14:
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 10 <= abs(hy2 - hy1) <= 14:
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 50% RES, 30% COM, 20% IND
        if ir < 0.18:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS INTO POWERED EMPTY AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        for fx in range(10, WORLD_W, 15):
            for fy in range(10, WORLD_H, 15):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for px2 in range(15, WORLD_W, 20):
            for py2 in range(15, WORLD_H, 20):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for sx in range(20, WORLD_W, 25):
            for sy in range(20, WORLD_H, 25):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 85), (112, 85), (8, 15), (112, 15), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(40, 6), (80, 6), (40, 94), (80, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high pop ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (25, 20), (95, 20), (25, 80), (95, 80),
                         (60, 10), (60, 90), (10, 50), (110, 50),
                         (40, 35), (80, 35), (40, 65), (80, 65)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS ----
    if pop > 100 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: coal near uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + dense wire/road grid in central area"""
    actions = []
    # Two coal plants near center
    actions.append((Tool.COALPOWER, 30, 45))
    actions.append((Tool.COALPOWER, 85, 45))
    # Horizontal wire spines
    for wy in [25, 45, 65, 85]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines connecting horizontal
    for wx in [15, 40, 65, 90, 110]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows (above and below)
    for wy in [25, 45, 65, 85]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    # Roads flanking vertical wire spines
    for wx in [15, 40, 65, 90, 110]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, wx - 1, y))
            actions.append((Tool.ROAD, wx + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Wire/road infrastructure layout
    wire_rows = [25, 45, 65, 85]
    wire_cols = [15, 40, 65, 90, 110]

    def pick_tool():
        """Balanced mix: ~40% RES, ~35% COM, ~25% IND at mature city"""
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            # Bootstrap: need industry and commerce early
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # Dense city: more commercial drives pop
            if cr < 0.40:
                return Tool.COMMERCIAL
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === REACTIVE INFRASTRUCTURE REPAIR ===

    # 1. Fix unpowered zones by extending wire
    if step % 6 == 0:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 50)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # 2. Fix zones without road access
    if step % 6 == 1:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 3. Repair horizontal wire spines
    if step % 6 == 2:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]) if wx > 0 else False
                    right = bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]) if wx < WORLD_W - 1 else False
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # 4. Repair vertical wire spines
    if step % 6 == 3:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = bool(wm[wy2 - 1, wc]) or bool(pm[wy2 - 1, wc]) if wy2 > 0 else False
                    dn = bool(wm[wy2 + 1, wc]) or bool(pm[wy2 + 1, wc]) if wy2 < WORLD_H - 1 else False
                    if up or dn:
                        if bool(em[wy2, wc]):
                            return (Tool.WIRE, wc, wy2)

    # 5. Reactive power plant placement - add plants where coverage is missing
    if step % 6 == 4:
        # Grid of plant coverage targets - denser than parent
        plant_targets = []
        for py in range(12, WORLD_H - 5, 18):
            for px in range(10, WORLD_W - 5, 22):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 11), min(WORLD_W, px + 12)
            y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Only place if there are zones in this region
                has_zones = bool(np.any(zone_tiles[y0:y1, x0:x1]))
                if has_zones or pop < 100:
                    for r in range(0, 6):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # 6. Repair roads flanking wire rows
    if step % 8 == 5:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and (bool(wm[wr, rx]) or bool(pm[wr, rx])):
                        adj = (rx > 0 and bool(rm[ry, rx - 1])) or \
                              (rx < WORLD_W - 1 and bool(rm[ry, rx + 1])) or \
                              (ry > 0 and bool(rm[ry - 1, rx])) or \
                              (ry < WORLD_H - 1 and bool(rm[ry + 1, rx]))
                        if adj or rx <= 2:
                            return (Tool.ROAD, rx, ry)

    # 7. Repair roads flanking wire cols
    if step % 8 == 6:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and (bool(wm[ry, wc]) or bool(pm[ry, wc])):
                        adj = (ry > 0 and bool(rm[ry - 1, rcx])) or \
                              (ry < WORLD_H - 1 and bool(rm[ry + 1, rcx])) or \
                              bool(rm[ry, max(0, rcx - 1)]) or \
                              bool(rm[ry, min(WORLD_W - 1, rcx + 1)])
                        if adj or ry <= 2:
                            return (Tool.ROAD, rcx, ry)

    # === CIVIC SERVICES (pop-gated) ===
    if pop > 30:
        fire_spots = [
            (8, 8), (38, 8), (68, 8), (98, 8),
            (8, 35), (113, 35), (8, 55), (113, 55),
            (8, 75), (113, 75), (8, 93), (38, 93), (68, 93), (98, 93),
            (38, 55), (68, 55), (53, 30), (83, 30),
            (53, 75), (83, 75), (25, 55), (100, 55),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (22, 18), (52, 18), (82, 18), (108, 18),
            (22, 38), (52, 38), (82, 38), (108, 38),
            (22, 58), (52, 58), (82, 58), (108, 58),
            (22, 78), (52, 78), (82, 78), (108, 78),
            (12, 50), (62, 25), (62, 78),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (32, 22), (92, 22), (32, 78), (92, 78),
            (62, 50), (17, 50), (107, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear for larger power coverage
        nuke_spots = [
            (10, 50), (110, 50), (60, 5), (60, 95),
            (10, 22), (110, 22), (10, 78), (110, 78),
            (37, 12), (87, 12), (37, 88), (87, 88),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 10 == 7:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === ZONE PLACEMENT (closed-loop: react to current state) ===
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Avoid infrastructure corridors (wire rows/cols and their road flanks)
    for wr in wire_rows:
        cand_mask[max(0, wr - 2):min(WORLD_H, wr + 3), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 2):min(WORLD_W, wc + 3)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Neighborhood centers - more distributed than parent, fill 5x4 grid
        if pop < 200:
            # Focus on central cluster first
            active_centers = [
                (52, 50), (38, 50), (66, 50), (52, 35), (52, 65),
                (25, 50), (80, 50), (52, 20), (52, 80),
                (38, 35), (66, 35), (38, 65), (66, 65),
                (25, 35), (80, 35), (25, 65), (80, 65),
            ]
        elif pop < 800:
            # Expand to fill map in a grid
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 10 + row * 20
                    active_centers.append((cx, cy))
        else:
            # Full saturation
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 6 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road toward powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire connections + seed roads"""
    actions = []
    # Two power plants: left and right side
    actions.append((Tool.COALPOWER, 30, 50))
