def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio: 50% res, 25% com, 25% ind
    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: Ensure adequate power plants ----
    # Check density of plants; add more if zone count growing
    pys_arr, pxs_arr = np.where(pm)
    num_plants = len(pxs_arr)
    needed_plants = max(2, total_zones // 30)

    if num_plants < needed_plants:
        # Find a good location: near center of zones or spread out
        # Try positions on a grid spaced ~20 apart, away from existing plants
        for ppx in range(15, WORLD_W - 15, 20):
            for ppy in range(15, WORLD_H - 15, 20):
                x0, x1 = max(0, ppx - 10), min(WORLD_W, ppx + 11)
                y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
                if not np.any(pm[y0:y1, x0:x1]):
                    # Check it's not on a road or zone
                    if ib(ppx, ppy) and bool(em[ppy, ppx]):
                        return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Extend wire network reactively ----
    # Find zones not near power and extend wire toward them
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    if len(uzxs) > 0:
        # Find wire/plant tiles adjacent to empty tiles, closest to unpowered zones
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy == -1:
                shifted[:-1, :] = power_src[1:, :]
            elif dy == 1:
                shifted[1:, :] = power_src[:-1, :]
            elif dx == -1:
                shifted[:, :-1] = power_src[:, 1:]
            elif dx == 1:
                shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & adj_to_power & ~zone_tiles & ~rm
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False
        wys_c, wxs_c = np.where(wire_cand)

        if len(wxs_c) > 0:
            # Pick wire position closest to an unpowered zone
            stride_u = max(1, len(uzxs) // 30)
            stride_w = max(1, len(wxs_c) // 200)
            best_d = 1e9
            best_k = 0
            for i in range(0, len(wxs_c), stride_w):
                cx, cy = int(wxs_c[i]), int(wys_c[i])
                d = min(
                    abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j]))
                    for j in range(0, len(uzxs), stride_u)
                )
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))

    # ---- PHASE 3: Extend road network reactively ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    if len(usxs) > 0:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:
                shifted[:-1, :] = rm[1:, :]
            elif dy == 1:
                shifted[1:, :] = rm[:-1, :]
            elif dx == -1:
                shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:
                shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & ~zone_tiles & ~pm
        road_cand[0:2, :] = False
        road_cand[WORLD_H - 2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W - 2:] = False
        rys_c, rxs_c = np.where(road_cand)

        if len(rxs_c) > 0:
            stride_u = max(1, len(usxs) // 30)
            stride_r = max(1, len(rxs_c) // 200)
            best_d = 1e9
            best_k = 0
            for i in range(0, len(rxs_c), stride_r):
                cx, cy = int(rxs_c[i]), int(rys_c[i])
                d = min(
                    abs(cx - int(usxs[j])) + abs(cy - int(usys[j]))
                    for j in range(0, len(usxs), stride_u)
                )
                if d < best_d:
                    best_d = d
                    best_k = i
            return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Don't place on infrastructure
    zone_cand &= ~pm
    zone_cand &= ~wm
    zone_cand &= ~rm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        # Score: prefer close to roads, cluster with existing zones
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]).astype(float) +
                     np.abs(cys_arr - road_ys[i]).astype(float))
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs_arr - zone_xs[i]).astype(float) +
                     np.abs(cys_arr - zone_ys[i]).astype(float))
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Penalize too-close (overlap risk) and too-far
            zone_score = np.where(
                min_zone_dist < 3, 500.0,
                np.where(min_zone_dist > 20, min_zone_dist * 0.3, min_zone_dist * 0.1)
            )
        else:
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float) * 0.05

        score = road_dist * 1.2 + zone_score * 0.8
        order = np.argsort(score)
        # Use step+pop offset for diversity
        off = (step * 7 + pop) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 50:
        fire_spots = [(fx, fy) for fy in range(10, 92, 15) for fx in range(10, 112, 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        police_spots = [(px2, py2) for py2 in range(10, 92, 18) for px2 in range(10, 112, 22)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        park_spots = [(pkx, pky) for pky in range(8, 93, 10) for pkx in range(8, 112, 12)]
        for pkx2, pky2 in park_spots:
            if ib(pkx2, pky2) and bool(em[pky2, pkx2]):
                return (Tool.PARK, pkx2, pky2)

    if pop > 600:
        stadium_spots = [(sx, sy) for sy in range(15, 88, 30) for sx in range(15, 108, 35)]
        for stx, sty in stadium_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuclear_spots = [(nx, ny) for ny in range(15, 90, 25) for nx in range(15, 108, 25)]
        for npx, npy in nuclear_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        airport_spots = [(55, 7), (65, 7), (55, 92), (65, 92),
                         (7, 44), (112, 44), (7, 56), (112, 56)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_spots = [(7, 50), (112, 50), (60, 4), (60, 95)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Extend wire from existing power reactively ----
    adj_to_power2 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:
            shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:
            shifted[1:, :] = power_src[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = power_src[:, :-1]
        adj_to_power2 |= shifted

    wire_cand2 = em & adj_to_power2 & ~zone_tiles & ~rm
    wire_cand2[0:2, :] = False
    wire_cand2[WORLD_H - 2:, :] = False
    wire_cand2[:, 0:2] = False
    wire_cand2[:, WORLD_W - 2:] = False
    wys2, wxs2 = np.where(wire_cand2)

    if len(wxs2) > 0:
        k = step % len(wxs2)
        return (Tool.WIRE, int(wxs2[k]), int(wys2[k]))

    # ---- PHASE 7: Extend road network ----
    adj_to_road2 = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1:
            shifted[:-1, :] = rm[1:, :]
        elif dy == 1:
            shifted[1:, :] = rm[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = rm[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = rm[:, :-1]
        adj_to_road2 |= shifted

    road_cand2 = em & adj_to_road2 & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys2, rxs2 = np.where(road_cand2)

    if len(rxs2) > 0:
        # Extend road toward center if sparse
        cx_target, cy_target = 60, 50
        dists = np.abs(rxs2 - cx_target).astype(float) + np.abs(rys2 - cy_target).astype(float)
        k = int(np.argmin(dists))
        return (Tool.ROAD, int(rxs2[k]), int(rys2[k]))

    # ---- Fallback: place power plant near center ----
    for ppx in range(40, 80, 10):
        for ppy in range(40, 60, 10):
            if ib(ppx, ppy) and bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending further
    for dx in range(-15, 16):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-15, 16):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads
    for dy in range(-14, 15):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    for dx in range(-14, 15):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID ----
    # Denser grid for more coverage
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [8, 19, 30, 41, 52, 63, 74, 85, 96]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 10
        if pop < 500:   return 20
        if pop < 1000:  return 35
        if pop < 2000:  return 55
        if pop < 4000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Sort hoods by distance from center to expand outward
    cx0, cy0 = 60, 50
    all_hoods_sorted = sorted(all_hoods, key=lambda h: abs(h[0]-cx0) + abs(h[1]-cy0))
    active_hoods = all_hoods_sorted[:n_active]

    # ---- BUILD NEIGHBOR MASKS ----
    def dilate_mask(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    nbr_road = dilate_mask(rm, 2)
    nbr_power = dilate_mask(wm | pm, 6)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: ~50% RES, ~30% COM, ~20% IND
        if ir < 0.18:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 1: ENSURE EACH ACTIVE HOOD HAS A POWER PLANT NEARBY ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: GROW WIRE TOWARD UNCOVERED HOODS ----
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            # Pick the closest uncovered hood
            best_hood = None
            best_dist_h = 999999
            wire_cx = float(np.mean(wire_xs))
            wire_cy = float(np.mean(wire_ys))
            for (tx, ty) in uncovered:
                d = abs(tx - wire_cx) + abs(ty - wire_cy)
                if d < best_dist_h:
                    best_dist_h = d
                    best_hood = (tx, ty)
            if best_hood:
                tx, ty = best_hood
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy), (dx, dy)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: BUILD ROAD GRID CONNECTING HOODS ----
    hood_cycle = step % max(len(active_hoods), 1)
    spine_range = 8

    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Horizontal road above/below wire row
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    rcx = hx + sign * dist
                    if not ib(rcx, ry2): continue
                    if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                        if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                            return (Tool.ROAD, rcx, ry2)
        # Vertical road left/right of wire column
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for sign in [1, -1]:
                for dist in range(0, spine_range + 1):
                    rcy = hy + sign * dist
                    if not ib(rx, rcy): continue
                    if bool(em[rcy, rx]) and not bool(pm[rcy, rx]):
                        if bool(wm[rcy, hx]) or bool(pm[rcy, hx]):
                            return (Tool.ROAD, rx, rcy)

    # ---- PHASE 4: EXTEND WIRE SPINES ----
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wy2 = hy + sign * dist
                if not ib(hx, wy2): continue
                if bool(wm[wy2, hx]) or bool(pm[wy2, hx]): continue
                if not bool(em[wy2, hx]): continue
                for ay in [wy2 - 1, wy2 + 1]:
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, wy2)
        for sign in [1, -1]:
            for dist in range(1, spine_range + 1):
                wx2 = hx + sign * dist
                if not ib(wx2, hy): continue
                if bool(wm[hy, wx2]) or bool(pm[hy, wx2]): continue
                if not bool(em[hy, wx2]): continue
                for ax in [wx2 - 1, wx2 + 1]:
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, wx2, hy)

    # ---- PHASE 5: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and 8 <= abs(hx2 - hx1) <= 16:
                for cx2 in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 8 <= abs(hy2 - hy1) <= 16:
                for cy2 in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx).astype(float) + np.abs(cys_arr - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- PHASE 7: EXTEND ROADS INTO POWERED EMPTY AREAS ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (closed-loop, pop-gated) ----
    if pop > 60:
        for fx in range(10, WORLD_W, 18):
            for fy in range(10, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        for px2 in range(15, WORLD_W, 22):
            for py2 in range(15, WORLD_H, 22):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 500:
        for sx in range(20, WORLD_W, 28):
            for sy in range(20, WORLD_H, 28):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 85), (112, 85), (8, 15), (112, 15), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(40, 6), (80, 6), (40, 94), (80, 94)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high pop ----
    if pop > 1000:
        nuclear_spots = [(25, 20), (95, 20), (25, 80), (95, 80),
                         (60, 10), (60, 90), (10, 50), (110, 50),
                         (40, 35), (80, 35), (40, 65), (80, 65),
                         (20, 50), (100, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS ----
    if pop > 80 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19 + pop) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: wire toward unpowered zones ----
    zone_ys_u, zone_xs_u = np.where(zone_tiles & ~nbr_power)
    if len(zone_xs_u) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 17) % len(zone_xs_u)
            tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: coal near uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire cross + road ring."""
    actions = []
    # Single central coal plant at (60, 50)
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending outward
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the wire cross
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 3, cy + dy))
        actions.append((Tool.ROAD, cx + 3, cy + dy))
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, cx + dx, cy - 3))
        actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # === NEIGHBORHOOD GRID: ring layout around center ===
    # Different from parent: use a ring + center layout
    all_hoods = [
        (60, 50),  # center
        (40, 30), (60, 25), (80, 30),  # top row
        (30, 50), (90, 50),            # sides
        (40, 70), (60, 75), (80, 70),  # bottom row
        (20, 20), (100, 20), (20, 80), (100, 80),  # corners
        (50, 45), (70, 45), (50, 55), (70, 55),    # inner ring
        (35, 35), (85, 35), (35, 65), (85, 65),    # mid ring
        (15, 50), (105, 50), (60, 15), (60, 85),   # edge centers
    ]

    def num_active():
        if pop < 50:   return 4
        if pop < 200:  return 7
        if pop < 500:  return 12
        if pop < 1000: return 17
        if pop < 2000: return 20
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    # === NEIGHBOR MASKS ===
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: ENSURE POWER PLANTS near every active hood ===
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
            y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 16):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)
                    if found:
                        break

    # === PHASE 2: WIRE INFRASTRUCTURE ===
    # Wire from nearest plant to current hood, rotating through hoods
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 14

    x0p, x1p = max(0, hx - 18), min(WORLD_W, hx + 19)
    y0p, y1p = max(0, hy - 18), min(WORLD_H, hy + 19)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0; best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d; best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        # Wire vertically first, then horizontally (L-shaped path)
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spine vertically at hx
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        min_wr, max_wr = min(col_wire), max(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    # Extend wire spine horizontally at hy
    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        min_wc, max_wc = min(row_wire), max(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: ROAD GRID - parallel roads on BOTH sides of wire ===
    # Use offsets 2 and 4 for denser road coverage
    hood_idx2 = (step + 2) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 4
    # Four parallel roads flanking vertical wire (at -4,-2,+2,+4)
    for rx in [hx3 - 4, hx3 - 2, hx3 + 2, hx3 + 4]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::4]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 4, hy3 - 2, hy3 + 2, hy3 + 4]:
        if not ib(hx3, ry): continue
        for wc in row_wire3[cyc::4]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # === PHASE 4: ZONE PLACEMENT with different mix: 50% RES, 30% COM, 20% IND ===
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Heavier commercial bias vs parent
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        if rr < 0.45:
            return Tool.RESIDENTIAL
        # Cycle through in 5:3:2 ratio based on step
        cycle = step % 10
        if cycle < 5:
            return Tool.RESIDENTIAL
        elif cycle < 8:
            return Tool.COMMERCIAL
        else:
            return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs_arr - hx4) + np.abs(cys_arr - hy4)
            best_dist = np.minimum(best_dist, d)

        # Prefer spots near existing zones (clustering)
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs_arr - zxs2[i]).astype(float) +
                          np.abs(cys_arr - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # Balance: cluster zones but also spread to new hoods
                spread_w = max(0.3, min(0.7, pop / 2000.0))
                score = best_dist * spread_w + zone_prox * (1.0 - spread_w)
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 11 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: CONNECT HOODS WITH ROADS ===
    if step % 4 < 2:
        for i, (hx1, hy1) in enumerate(active_hoods):
            for (hx2, hy2) in active_hoods[i+1:i+4]:
                dist = abs(hx1-hx2) + abs(hy1-hy2)
                if dist > 40: continue
                if abs(hy1 - hy2) <= 4:
                    mid_y = (hy1 + hy2) // 2
                    step_conn = step % max(abs(hx2-hx1), 1)
                    cx2 = min(hx1, hx2) + step_conn
                    if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                        if not bool(rm[mid_y, cx2]):
                            return (Tool.ROAD, cx2, mid_y)
                if abs(hx1 - hx2) <= 4:
                    mid_x = (hx1 + hx2) // 2
                    step_conn = step % max(abs(hy2-hy1), 1)
                    cy2 = min(hy1, hy2) + step_conn
                    if ib(mid_x, cy2) and bool(em[cy2, mid_x]) and not bool(pm[cy2, mid_x]):
                        if not bool(rm[cy2, mid_x]):
                            return (Tool.ROAD, mid_x, cy2)

    # === PHASE 6: EXTEND ROAD NETWORK ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 7: CIVIC SERVICES ===
    # Fire stations first (needed for low crime/fire)
    if pop > 15:
        fire_grid = [(fx, fy) for fy in range(12, 95, 15)
                     for fx in range(12, 115, 15)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_grid = [(px2, py2) for py2 in range(14, 92, 16)
                       for px2 in range(14, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    # Parks near zones for land value
    if pop > 100 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 19) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Stadiums for commercial demand
    if pop > 200:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50), (60, 50),
            (38, 38), (82, 38), (38, 62), (82, 62),
            (25, 30), (95, 30), (25, 70), (95, 70),
            (50, 20), (70, 20), (50, 80), (70, 80),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power for mid-late game
    if pop > 400 and funds > 2500:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5),  (60, 95),  (5, 50),  (115, 50),
            (30, 20), (90, 20),  (30, 80), (90, 80),
            (15, 35), (105, 35), (15, 65), (105, 65),
            (45, 10), (75, 10),  (45, 90), (75, 90),
            (20, 50), (100, 50), (60, 30), (60, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 92), (5, 45), (113, 45)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 8: WIRE CONNECTIONS BETWEEN HOODS ===
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:i+3]:
            if abs(hx1-hx2) + abs(hy1-hy2) > 45: continue
            if abs(hy1 - hy2) <= 4:
                mid_y = (hy1 + hy2) // 2
                for cx3 in range(min(hx1,hx2)+1, max(hx1,hx2)):
                    if ib(cx3, mid_y) and bool(em[mid_y, cx3]) and not bool(pm[mid_y, cx3]):
                        if not bool(wm[mid_y, cx3]):
                            return (Tool.WIRE, cx3, mid_y)
            if abs(hx1 - hx2) <= 4:
                mid_x = (hx1 + hx2) // 2
                for cy3 in range(min(hy1,hy2)+1, max(hy1,hy2)):
                    if ib(mid_x, cy3) and bool(em[cy3, mid_x]) and not bool(pm[cy3, mid_x]):
                        if not bool(wm[cy3, mid_x]):
                            return (Tool.WIRE, mid_x, cy3)

    # === FALLBACK: wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 18):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    # === LATE GAME: upgrade to nuclear ===
    if pop > 1000 and step % 4 == 0 and funds > 4000:
        nuc_spots = [(25, 25), (95, 25), (25, 75), (95, 75),
                     (60, 50), (10, 10), (110, 10), (10, 90), (110, 90),
                     (45, 15), (75, 15), (45, 85), (75, 85),
                     (15, 45), (105, 45), (15, 55), (105, 55)]
        for nx6, ny6 in nuc_spots:
            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                return (Tool.NUCLEARPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants + wire spines + flanking roads"""
    actions = []
    # Four power plants spread across the map
    for px, py in [(20, 50), (60, 25), (60, 75), (100, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for y in [25, 50, 75]:
        for x in range(2, 118):
            actions.append((Tool.WIRE, x, y))
    # Vertical wire spines
    for x in [20, 60, 100]:
        for y in range(2, 98):
            actions.append((Tool.WIRE, x, y))
    # Roads flanking horizontal wires
    for y in [25, 50, 75]:
        for x in range(2, 118):
            actions.append((Tool.ROAD, x, y - 1))
            actions.append((Tool.ROAD, x, y + 1))
    # Roads flanking vertical wires
    for x in [20, 60, 100]:
        for y in range(2, 98):
            actions.append((Tool.ROAD, x - 1, y))
            actions.append((Tool.ROAD, x + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- Helper: dilate a mask by radius r (Manhattan) ----
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    # ---- Current infrastructure state ----
    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)
    zone_tiles = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    wire_rows = [25, 50, 75]
    wire_cols = [20, 60, 100]

    # ---- Zone tool selection: target 45% res, 30% com, 25% ind ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- Zone placement validity (3x3 footprint) ----
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- REACTIVE PHASE LOGIC ----
    # Phase is now computed from step but we REACT to the map, not replay
    phase = step % 16

    # --- Phase 0-1: Repair/extend horizontal wire spines reactively ---
    if phase == 0:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # --- Phase 2-3: Repair/extend roads flanking wire spines ---
    elif phase == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # --- Phase 4: Add cross-roads between wire rows (reactive: only where empty + near power) ---
    elif phase == 4:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # --- Phase 5: Vertical cross-roads between wire cols ---
    elif phase == 5:
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # --- Phase 6: Extend road from existing road endpoints (reactive) ---
    elif phase == 6:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13 + pop * 3) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- Phase 7: Wire toward unpowered zones ---
    elif phase == 7:
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 19 + pop) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- Phase 8: Add power plant near unpowered/underpowered zone clusters ---
    elif phase == 8:
        # Find zones that are NOT near power - add a plant near them
        unp_ys, unp_xs = np.where(zone_tiles & ~near_power)
        if len(unp_xs) > 0:
            cx = int(np.mean(unp_xs))
            cy = int(np.mean(unp_ys))
            # Search spiral for empty spot to place plant
            for r in range(2, 20):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = cx+dx, cy+dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)
        # Also add plant if total powered_zones is low relative to total zones
        elif obs.powered_zones < total_zones * 0.6 and total_zones > 10:
            pm_ys, pm_xs = np.where(pm)
            if len(pm_xs) > 0:
                # Place near existing plant to extend power network
                pidx = (step * 7) % len(pm_xs)
                bpx, bpy = int(pm_xs[pidx]), int(pm_ys[pidx])
                for r in range(3, 25):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = bpx+dx, bpy+dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # --- Phase 9: Fire stations (reactive: only where empty + near road) ---
    elif phase == 9:
        fire_spots = [
            (10,10),(35,10),(65,10),(90,10),(110,10),
            (10,30),(110,30),
            (10,50),(110,50),
            (10,70),(110,70),
            (10,90),(35,90),(65,90),(90,90),(110,90),
            (40,40),(80,40),(40,60),(80,60),(60,50)
        ]
        if pop > 5:
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]) and bool(near_road[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

    # --- Phase 10: Police stations ---
    elif phase == 10:
        police_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,40),(45,40),(75,40),(105,40),
            (15,60),(45,60),(75,60),(105,60),
            (15,85),(45,85),(75,85),(105,85)
        ]
        if pop > 50:
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]) and bool(near_road[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

    # --- Phase 11: Stadiums + nuclear power ---
    elif phase == 11:
        if pop > 500:
            for sx, sy in [(30,35),(90,35),(30,65),(90,65),(60,50)]:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)
        if pop > 800:
            for nx2, ny2 in [(5,50),(115,50),(60,5),(60,95),(5,5),(115,5)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    # --- Phase 12: Seaport + airport ---
    elif phase == 12:
        if pop > 1200:
            for sx, sy in [(5,95),(115,95),(5,5),(115,5)]:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 2000:
            for sx, sy in [(50,5),(70,5),(50,92),(70,92)]:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # --- Phase 13: Parks for land value ---
    elif phase == 13:
        if pop > 50:
            park_cands = em & near_road & near_power
            pys, pxs = np.where(park_cands)
            if len(pxs) > 0:
                idx = (step * 37 + pop * 5) % len(pxs)
                return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- Phase 14-15: Additional wire/road extension to underserved areas ---
    elif phase == 14:
        # Wire from nearest wire to zones that lack power - step toward them
        zone_mask_any = zone_tiles.copy().astype(bool)
        unserved_ys, unserved_xs = np.where(zone_mask_any & ~near_power)
        if len(unserved_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                # Pick the closest zone to any wire
                best_i, best_j, best_d = 0, 0, 999999
                for i in range(min(len(unserved_xs), 50)):
                    tx, ty = int(unserved_xs[i]), int(unserved_ys[i])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    j = int(np.argmin(dists))
                    if dists[j] < best_d:
                        best_d = dists[j]
                        best_i = i
                        best_j = j
                tx, ty = int(unserved_xs[best_i]), int(unserved_ys[best_i])
                bwx, bwy = int(wire_xs_a[best_j]), int(wire_ys_a[best_j])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 15:
        # Road toward zones with power but no road access
        need_road_ys, need_road_xs = np.where(zone_tiles & near_power & ~near_road)
        if len(need_road_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 23) % len(need_road_xs)
                tx, ty = int(need_road_xs[idx]), int(need_road_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- MAIN ZONE PLACEMENT (closed-loop, every step) ----
    # Build candidate mask: empty tiles near roads AND near power, away from edges
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road spine rows/cols (don't zone on top of infrastructure)
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Reactively choose neighborhood centers based on current population
        # The more population, the further out we build
        if pop < 200:
            focus_x, focus_y = 60, 50  # start central
            weights = np.exp(-((cxs2 - focus_x)**2 + (cys2 - focus_y)**2) / (30.0**2))
        elif pop < 600:
            # Expand to mid-ring
            weights = np.ones(len(cxs2), dtype=float)
            for fx, fy in [(40,35),(80,35),(40,65),(80,65),(60,50)]:
                w = np.exp(-((cxs2 - fx)**2 + (cys2 - fy)**2) / (25.0**2))
                weights = np.maximum(weights, w * 2.0)
        else:
            # Fill the whole map
            weights = np.ones(len(cxs2), dtype=float)
            # Prefer areas with fewer existing zones
            zone_density = dilate(zone_tiles, 4).astype(float)
            weights *= (1.0 - 0.5 * zone_density[cys2, cxs2])
            weights = np.maximum(weights, 0.01)

        # Weighted sampling: pick highest-weight candidates first
        order = np.argsort(-weights)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- FALLBACK 1: wire toward the centroid of empty map (expand power grid) ----
    empty_ys, empty_xs = np.where(em & ~near_power)
    if len(empty_xs) > 0:
        # Find centroid of empty+unpowered region
        cx = int(np.mean(empty_xs))
        cy = int(np.mean(empty_ys))
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            dists = np.abs(wire_xs_arr - cx) + np.abs(wire_ys_arr - cy)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if cx == bwx else (1 if cx > bwx else -1)
            dy = 0 if cy == bwy else (1 if cy > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK 2: extend any existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17 + pop) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants + wire spines + flanking roads"""
    actions = []
    # Coal plants at center and sides
    for px in [20, 59, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire spines at key rows
    for wy in [20, 40, 50, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 40, 59, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for wy in [20, 40, 50, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% res, 28% com, 22% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [20, 40, 59, 80, 100]

    # Reactive: find where power grid currently reaches
    powered_area = near_power
    road_area = near_road

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    phase = step % 10

    # === REACTIVE POWER EXTENSION ===
    # If there are zones without power, wire toward them
    if phase == 0:
        unpowered_zones = zone_tiles & ~powered_area
        zone_ys, zone_xs = np.where(unpowered_zones)
        if len(zone_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs)
                tx, ty = int(zone_xs[idx]), int(zone_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # === REACTIVE ROAD EXTENSION ===
    # Find empty cells near power but no road, adjacent to existing road
    elif phase == 1:
        needs_road = em & powered_area & ~rm
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(powered_area[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # === REACTIVE WIRE ALONG WIRE ROWS ===
    elif phase == 2:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]))
                    right = wx < WORLD_W - 1 and (bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # === REACTIVE WIRE ALONG WIRE COLS ===
    elif phase == 3:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy - 1, wc]) or bool(pm[wy - 1, wc]))
                    dn = wy < WORLD_H - 1 and (bool(wm[wy + 1, wc]) or bool(pm[wy + 1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # === ROADS FLANKING WIRE ROWS ===
    elif phase == 4:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # === ROADS FLANKING WIRE COLS ===
    elif phase == 5:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # === ADD POWER PLANTS WHERE NEEDED ===
    elif phase == 6:
        # Reactively add plants where power coverage is low
        # Check each quadrant for power plants
        quadrants = [
            (10, 10), (60, 10), (110, 10),
            (10, 50), (60, 50), (110, 50),
            (10, 90), (60, 90), (110, 90),
        ]
        for qx, qy in quadrants:
            x0, x1 = max(0, qx - 25), min(WORLD_W, qx + 25)
            y0, y1 = max(0, qy - 25), min(WORLD_H, qy + 25)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find empty spot near a wire
                wire_ys_q, wire_xs_q = np.where((wm | pm)[y0:y1, x0:x1])
                if len(wire_xs_q) > 0:
                    # Place plant adjacent to a wire
                    for i in range(len(wire_xs_q)):
                        wx_abs = int(wire_xs_q[i]) + x0
                        wy_abs = int(wire_ys_q[i]) + y0
                        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (-3, 0)]:
                            px2, py2 = wx_abs + dx2, wy_abs + dy2
                            if ib(px2, py2) and bool(em[py2, px2]):
                                return (Tool.COALPOWER, px2, py2)
                else:
                    # No wire nearby, place plant at quadrant center if empty
                    if ib(qx, qy) and bool(em[qy, qx]):
                        return (Tool.COALPOWER, qx, qy)

    # === CIVIC SERVICES (reactive to pop) ===
    elif phase == 7:
        if pop > 30:
            fire_spots = [(5, 5), (30, 5), (60, 5), (90, 5), (115, 5),
                          (5, 30), (30, 30), (60, 30), (90, 30), (115, 30),
                          (5, 55), (30, 55), (90, 55), (115, 55),
                          (5, 75), (30, 75), (60, 75), (90, 75), (115, 75),
                          (5, 95), (30, 95), (60, 95), (90, 95), (115, 95)]
            for sx, sy in fire_spots:
                sy = min(sy, 99)
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 150:
            police_spots = [(15, 15), (60, 15), (105, 15),
                            (15, 45), (60, 45), (105, 45),
                            (15, 70), (60, 70), (105, 70),
                            (15, 90), (60, 90), (105, 90)]
            for sx, sy in police_spots:
                sy = min(sy, 99)
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 600:
            for sx, sy in [(30, 30), (90, 30), (30, 70), (90, 70), (60, 50)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 1000:
            for nx2, ny2 in [(5, 50), (115, 50), (60, 5), (60, 95)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 2000:
            for sx, sy in [(5, 95), (115, 95), (5, 5), (115, 5)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 3000:
            for sx, sy in [(50, 5), (70, 5), (50, 95), (70, 95)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # === CROSS-STREET ROADS ===
    elif phase == 8:
        # Add roads between wire rows to expand coverage
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(powered_area[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx - 1])) or
                           (rx < WORLD_W - 1 and bool(rm[mid_y, rx + 1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # === ZONE PLACEMENT (main closed-loop action) ===
    # Build candidate mask: empty + near road + near power, keep away from borders/corridors
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: prefer cells near existing zones (reactive clustering)
        # and near center of powered+road coverage
        tool = pick_tool()

        # Reactive: prioritize near existing same-type zones for clustering
        if res_count + com_count + ind_count > 0:
            zone_ys_all, zone_xs_all = np.where(zone_tiles)
            # Distance to nearest zone (promotes clustering)
            # Use a subsample for speed
            sample_size = min(len(zone_xs_all), 50)
            sk = (step * 7) % max(len(zone_xs_all), 1)
            sample_idx = [(sk + i * 3) % len(zone_xs_all) for i in range(sample_size)]
            szx = zone_xs_all[sample_idx]
            szy = zone_ys_all[sample_idx]

            best_score = np.full(len(cxs2), 999999.0)
            for i in range(len(szx)):
                d = np.abs(cxs2 - szx[i]).astype(float) + np.abs(cys2 - szy[i]).astype(float)
                best_score = np.minimum(best_score, d)

            # Blend: close to existing zones but not too close
            # Penalize if too close (<4) to encourage spread
            too_close = best_score < 4
            best_score[too_close] += 50

            order = np.argsort(best_score)
        else:
            # No zones yet: pick center region
            center_dist = np.abs(cxs2 - 60).astype(float) + np.abs(cys2 - 50).astype(float)
            order = np.argsort(center_dist)

        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 400:
                break

    # Parks for land value near zones
    if pop > 100 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            # Reactive: place near existing zones
            zone_ys_p, zone_xs_p = np.where(zone_tiles)
            if len(zone_xs_p) > 0:
                best_d = np.full(len(pxs), 999999.0)
                for i in range(min(30, len(zone_xs_p))):
                    d = np.abs(pxs - zone_xs_p[i]).astype(float) + np.abs(pys - zone_ys_p[i]).astype(float)
                    best_d = np.minimum(best_d, d)
                # Pick one that is close to zones but not on a zone
                good = (best_d > 1) & (best_d < 8)
                good_idx = np.where(good)[0]
                if len(good_idx) > 0:
                    idx = (step * 31 + pop) % len(good_idx)
                    return (Tool.PARK, int(pxs[good_idx[idx]]), int(pys[good_idx[idx]]))

    # Fallback: extend wire from any existing wire toward map center
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 60)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            # Prefer direction toward map center
            cx_dir = 1 if wx2 < 60 else -1
            cy_dir = 1 if wy2 < 50 else -1
            for dx3, dy3 in [(cx_dir, 0), (0, cy_dir), (1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and road grid seeds"""
    placements = []
