def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    def in_bounds(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Initialize state
    if 'initialized' not in state:
        state['initialized'] = True
        state['wire_phase'] = 'expand'
        state['extra_plants'] = 0

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    pop = obs.city_pop

    # Zone tool picker: balanced mix with more commercial/industrial
    def pick_tool():
        t = max(total_zones, 1)
        i_r = ind_count / t
        c_r = com_count / t
        r_r = res_count / t
        # Target: 25% industrial, 35% commercial, 40% residential
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Find all plants
    plant_ys, plant_xs = np.where(pm)
    has_plant = len(plant_xs) > 0

    if not has_plant:
        return (Tool.COALPOWER, 35, 50)

    # Primary anchor points: two clusters
    # Left cluster around x=37, Right cluster around x=77
    clusters = [
        {'cx': 37, 'cy': 50, 'px': 35, 'py': 50},
        {'cx': 77, 'cy': 50, 'px': 75, 'py': 50},
    ]

    # Add additional plants when needed
    if state['extra_plants'] < 1 and (total_zones > 15 or pop > 400):
        # Third plant in middle-top area
        p3x, p3y = 56, 35
        if in_bounds(p3x, p3y) and bool(em[p3y, p3x]):
            state['extra_plants'] = 1
            return (Tool.COALPOWER, p3x, p3y)
        # Wire path to third plant
        for wy in range(p3y + 3, 50):
            if in_bounds(56, wy) and (bool(em[wy, 56]) or bool(wm[wy, 56])) and not bool(pm[wy, 56]):
                return (Tool.WIRE, 56, wy)

    if state['extra_plants'] < 2 and (total_zones > 40 or pop > 1200):
        p4x, p4y = 56, 65
        if in_bounds(p4x, p4y) and bool(em[p4y, p4x]):
            state['extra_plants'] = 2
            return (Tool.COALPOWER, p4x, p4y)
        for wy in range(51, p4y - 2):
            if in_bounds(56, wy) and (bool(em[wy, 56]) or bool(wm[wy, 56])) and not bool(pm[wy, 56]):
                return (Tool.WIRE, 56, wy)

    # Build wire spines for each cluster
    pop_factor = min(25, pop // 20)
    spine_top = max(5, 50 - 18 - pop_factor)
    spine_bot = min(WORLD_H - 5, 50 + 18 + pop_factor)

    for cl in clusters:
        wire_col = cl['cx'] + 2  # wire column right of cluster center
        wire_rows = [r for r in range(WORLD_H) if in_bounds(wire_col, r) and bool(wm[r, wire_col])]

        if not wire_rows:
            # Seed wire adjacent to plant
            for dy in range(-3, 4):
                ny = cl['cy'] + dy
                if in_bounds(wire_col, ny) and (bool(em[ny, wire_col]) or bool(wm[ny, wire_col])) and not bool(pm[ny, wire_col]):
                    return (Tool.WIRE, wire_col, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if in_bounds(wire_col, nr) and (bool(em[nr, wire_col]) or bool(wm[nr, wire_col])) and not bool(pm[nr, wire_col]):
                    return (Tool.WIRE, wire_col, nr)

        # Build horizontal wire branches every 6 rows
        if wire_rows:
            for branch_y in range(spine_top, spine_bot + 1, 6):
                # Check if branch exists already
                branch_exists = any(in_bounds(bx, branch_y) and bool(wm[branch_y, bx])
                                    for bx in range(wire_col - 8, wire_col + 8))
                if not branch_exists and in_bounds(wire_col, branch_y) and bool(wm[branch_y, wire_col]):
                    # Extend branch left and right
                    for bx_off in range(1, 9):
                        bx_l = wire_col - bx_off
                        bx_r = wire_col + bx_off
                        if in_bounds(bx_l, branch_y) and (bool(em[branch_y, bx_l]) or bool(wm[branch_y, bx_l])) and not bool(pm[branch_y, bx_l]):
                            return (Tool.WIRE, bx_l, branch_y)
                        if in_bounds(bx_r, branch_y) and (bool(em[branch_y, bx_r]) or bool(wm[branch_y, bx_r])) and not bool(pm[branch_y, bx_r]):
                            return (Tool.WIRE, bx_r, branch_y)

        # Roads flanking the wire spine
        road_col_l = wire_col - 1
        road_col_r = wire_col + 1
        if wire_rows:
            step_off = (obs.step * 3 + cl['cx']) % max(len(wire_rows), 1)
            for idx in range(min(len(wire_rows), 4)):
                wr = wire_rows[(step_off + idx) % len(wire_rows)]
                if in_bounds(road_col_l, wr) and bool(em[wr, road_col_l]) and not bool(pm[wr, road_col_l]):
                    return (Tool.ROAD, road_col_l, wr)
                if in_bounds(road_col_r, wr) and bool(em[wr, road_col_r]) and not bool(pm[wr, road_col_r]):
                    return (Tool.ROAD, road_col_r, wr)

    # Horizontal road connectors between clusters every 8 rows
    for conn_y in range(spine_top, spine_bot + 1, 8):
        for cx_road in range(39, 75):
            if in_bounds(cx_road, conn_y) and bool(em[conn_y, cx_road]) and not bool(pm[conn_y, cx_road]):
                # Only if wire is nearby
                nbr_has_wire = any(
                    in_bounds(cx_road + ddx, conn_y + ddy) and bool(wm[conn_y + ddy, cx_road + ddx])
                    for ddx in range(-3, 4) for ddy in range(-3, 4) if in_bounds(cx_road + ddx, conn_y + ddy)
                )
                if nbr_has_wire:
                    return (Tool.ROAD, cx_road, conn_y)

    # Proximity masks for zone placement
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not in_bounds(nc2, nr2):
                    return False
                if not (bool(em[nr2, nc2]) or bool(zone_tiles[nr2, nc2])):
                    return False
        return True

    # Place zones near roads and power
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer locations near both clusters
        mid_x = 56
        dists = np.abs(cxs - mid_x) // 3 + np.abs(cys - 50) // 4
        order = np.argsort(dists)
        step_off = int(obs.step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 120:
                break

    # Extend roads near wire
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = int(obs.step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 30)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if in_bounds(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Services based on population
    if pop > 150:
        for fpos in [(55, 38), (55, 62), (25, 50), (85, 50)]:
            fsx, fsy = fpos
            if in_bounds(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)
    if pop > 400:
        for ppos in [(45, 38), (65, 62), (25, 45), (85, 45)]:
            psx, psy = ppos
            if in_bounds(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)
    if pop > 800:
        for spos in [(56, 30), (56, 70), (20, 55), (90, 55)]:
            ssx, ssy = spos
            if in_bounds(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    # Expand wire laterally from existing wire endpoints
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = int(obs.step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 25)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if in_bounds(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire crosses and road grids."""
    actions = []
    # Two plants: one at (35, 30), one at (85, 70) - spread across map
    for (cx, cy) in [(35, 30), (85, 70)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for d in range(1, 12):
            actions.append((Tool.WIRE, cx + d, cy))
            actions.append((Tool.WIRE, cx - d, cy))
            actions.append((Tool.WIRE, cx, cy + d))
            actions.append((Tool.WIRE, cx, cy - d))
        for dx in range(-10, 11):
            actions.append((Tool.ROAD, cx + dx, cy - 3))
            actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone mix: 45% RES, 30% COM, 25% IND
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 3x3 neighborhood grid, 9 anchors spread across map
    all_anchors = [
        (25, 20), (60, 20), (95, 20),
        (25, 50), (60, 50), (95, 50),
        (25, 80), (60, 80), (95, 80),
    ]

    def num_active():
        if pop < 50:   return 2
        if pop < 200:  return 4
        if pop < 500:  return 6
        if pop < 900:  return 8
        return 9

    n_active = min(num_active(), len(all_anchors))
    # Spread active anchors evenly across list
    if n_active >= len(all_anchors):
        active_anchors = all_anchors[:]
    else:
        indices = [int(i * len(all_anchors) / n_active) for i in range(n_active)]
        active_anchors = [all_anchors[i] for i in indices]

    # === POWER PROXIMITY MASK ===
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # === ROAD PROXIMITY MASK ===
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: ENSURE POWER PLANTS near each active anchor ===
    if funds > 1500:
        for (px, py) in active_anchors:
            y0 = max(0, py - 8); y1 = min(WORLD_H, py + 9)
            x0 = max(0, px - 8); x1 = min(WORLD_W, px + 9)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if r > 0 and abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE CROSS at each anchor ===
    spine = min(12, 6 + pop // 60)
    for (px, py) in active_anchors:
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # === PHASE 3: CONNECT WIRES BETWEEN ANCHORS (horizontally) ===
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx2 in range(x1a + 1, x2a):
                if ib(cx2, yl) and bool(em[yl, cx2]) and not bool(pm[yl, cx2]):
                    return (Tool.WIRE, cx2, yl)

    # === PHASE 4: CONNECT WIRES BETWEEN ANCHORS (vertically) ===
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy2 in range(y1a + 1, y2a):
                if ib(xl, cy2) and bool(em[cy2, xl]) and not bool(pm[cy2, xl]):
                    return (Tool.WIRE, xl, cy2)

    # === PHASE 5: ROADS flanking wire at each anchor ===
    for (px, py) in active_anchors:
        for road_dy in [-3, 3]:
            ry = py + road_dy
            if not ib(px, ry): continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # === PHASE 6: VERTICAL ROADS connecting row anchors ===
    if pop > 20:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1a = col_anchors[i]
                _, y2a = col_anchors[i + 1]
                for road_x in [xl + 4, xl - 4]:
                    for cy2 in range(y1a, y2a + 1):
                        if ib(road_x, cy2) and bool(em[cy2, road_x]) and not bool(pm[cy2, road_x]):
                            return (Tool.ROAD, road_x, cy2)

    # === PHASE 7: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Cluster near existing zones when there are some
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 8: EXTEND ROADS from existing road network ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 9: CIVIC SERVICES ===
    if pop > 50:
        fire_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (15, 75), (45, 75), (75, 75), (105, 75),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (20, 25), (60, 25), (100, 25),
            (20, 55), (60, 55), (100, 55),
            (20, 85), (60, 85), (100, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 10), (60, 10), (100, 10),
            (20, 90), (60, 90), (100, 90),
            (10, 50), (110, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 3000:
        nuclear_locs = [
            (10, 5), (110, 5), (10, 94), (110, 94),
            (60, 5), (60, 94), (5, 50), (115, 50),
            (35, 15), (85, 15), (35, 85), (85, 85),
            (20, 35), (100, 35), (20, 65), (100, 65),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 900:
        airport_locs = [(10, 8), (100, 8), (10, 88), (100, 88),
                        (55, 5), (55, 92)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: extend wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: place plant near uncovered anchor ===
    for (hx5, hy5) in active_anchors:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    # === LAST RESORT: road near zone ===
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

