    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid of neighborhood centers: more columns spread across map
    nh_cols = [8, 20, 32, 44, 56, 68, 80, 92, 104, 116]
    nh_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 8
        if pop < 500:   return 16
        if pop < 1000:  return 28
        if pop < 2000:  return 42
        if pop < 4000:  return 60
        if pop < 7000:  return 70
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 8), min(WORLD_W, hx + 9)
        y0, y1 = max(0, hy - 8), min(WORLD_H, hy + 9)
        if bool(np.any(pm[y0:y1, x0:x1])):
            continue
        for r in range(14):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = hx + dx, hy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: BUILD WIRE GRID (cross pattern per hood) ----
    spine_range = 12

    # Rotate through hoods based on step
    n_hoods = max(len(active_hoods), 1)
    # Each hood gets some steps
    for idx_h, (hx, hy) in enumerate(active_hoods):
        # Only work on a subset per step to spread effort
        if (step + idx_h) % n_hoods >= max(1, n_hoods // 3 + 1):
            continue

        # Vertical wire spine
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy):
                continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]):
                continue
            if not bool(em[wy, hx]):
                continue
            adj = False
            for ady in [-1, 1]:
                ay = wy + ady
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    adj = True
                    break
            if not adj:
                for adx in [-1, 1]:
                    ax = hx + adx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, hx, wy)
            # Bootstrap if no wire in column yet
            col_has_wire = any(
                bool(wm[hy + d2, hx]) for d2 in range(-spine_range, spine_range + 1)
                if ib(hx, hy + d2)
            )
            if not col_has_wire:
                for d2 in [-1, 1]:
                    ay = hy + d2
                    if ib(hx, ay) and bool(em[ay, hx]) and not bool(pm[ay, hx]):
                        return (Tool.WIRE, hx, ay)

        # Horizontal wire spine
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy):
                continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]):
                continue
            if not bool(em[hy, wx]):
                continue
            adj = False
            for adx2 in [-1, 1]:
                ax2 = wx + adx2
                if ib(ax2, hy) and (bool(wm[hy, ax2]) or bool(pm[hy, ax2])):
                    adj = True
                    break
            if not adj:
                for ady2 in [-1, 1]:
                    ay2 = hy + ady2
                    if ib(wx, ay2) and (bool(wm[ay2, wx]) or bool(pm[ay2, wx])):
                        adj = True
                        break
            if adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN HOODS ----
    hood_set = set(active_hoods)
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in [(hx1 + 12, hy1), (hx1 + 12, hy1)]:
            if (hx2, hy2) in hood_set:
                for cx in range(hx1 + 1, hx2):
                    if not ib(cx, hy1): continue
                    if bool(wm[hy1, cx]) or bool(pm[hy1, cx]) or not bool(em[hy1, cx]):
                        continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
        for (hx2, hy2) in [(hx1, hy1 + 12)]:
            if (hx2, hy2) in hood_set:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]) or not bool(em[cy2, hx1]):
                        continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS FLANKING WIRE SPINES ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h * 3) % n_hoods >= max(1, n_hoods // 3 + 1):
            continue

        # Roads on both sides of vertical spine
        for rx in [hx - 2, hx + 2]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

        # Roads on both sides of horizontal spine
        for ry2 in [hy - 2, hy + 2]:
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

        # Also roads 1 tile from spine (denser road grid)
        for rx in [hx - 1, hx + 1]:
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 5: ZONE PLACEMENT (closed-loop: react to current road+power) ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road coverage within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage within 6 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary starting offset by step to avoid always picking same spot
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- PHASE 6: EXTEND ROADS from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: CIVIC SERVICES (pop-gated) ----
    if pop > 80:
        fire_spots = [
            (8, 10), (32, 10), (56, 10), (80, 10), (104, 10),
            (8, 35), (32, 35), (56, 35), (80, 35), (104, 35),
            (8, 60), (32, 60), (56, 60), (80, 60), (104, 60),
            (8, 82), (32, 82), (56, 82), (80, 82), (104, 82),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (20, 20), (50, 20), (80, 20), (110, 20),
            (20, 50), (50, 50), (80, 50), (110, 50),
            (20, 75), (50, 75), (80, 75), (110, 75),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 30), (80, 30), (30, 65), (80, 65),
            (55, 15), (55, 85), (5, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (58, 5), (58, 95), (5, 50), (115, 50),
            (28, 5), (88, 5), (28, 95), (88, 95),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        airports = [(48, 5), (68, 5), (48, 94), (68, 94), (5, 46), (113, 46)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # ---- PHASE 8: PARKS near populated zones ----
    if pop > 150 and step % 4 == 0:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 60)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2),
                                  (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- LAST RESORT: road near zone ----
    zone_tiles2 = resm | comm | indm
    zone_arr_y, zone_arr_x = np.where(zone_tiles2)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants connected by wires, with road grid seeds"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire backbone
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Seed roads parallel to main wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Vertical road seeds
    for y in range(1, 99):
        actions.append((Tool.ROAD, 28, y))
        actions.append((Tool.ROAD, 32, y))
        actions.append((Tool.ROAD, 88, y))
        actions.append((Tool.ROAD, 92, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Balanced zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Dense grid of power plants: 5 columns x 4 rows
    plant_positions = []
    for row in range(4):
        for col in range(5):
            px = 12 + col * 24  # 12, 36, 60, 84, 108
            py = 13 + row * 25  # 13, 38, 63, 88
            plant_positions.append((px, py))

    # Wire corridors: denser horizontal and vertical
    wire_rows = [13, 25, 38, 50, 63, 75, 88]
    wire_cols = [12, 24, 36, 48, 60, 72, 84, 96, 108]

    # ---- PHASE 1: ENSURE PLANTS EXIST ----
    for px, py in plant_positions:
        x0, x1 = max(0, px-8), min(WORLD_W, px+9)
        y0, y1 = max(0, py-8), min(WORLD_H, py+9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 9

    if phase == 0:
        # Horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_has_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy, wr, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
                    if ib(bpx, wr) and bool(em[wr, bpx]):
                        return (Tool.WIRE, bpx, wr)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_has_power[wx]):
                        if (wx > 0 and bool(row_has_power[wx-1])) or \
                           (wx < WORLD_W-1 and bool(row_has_power[wx+1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_has_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2, wc, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
                    if ib(wc, bpy2) and bool(em[bpy2, wc]):
                        return (Tool.WIRE, wc, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_has_power[wy]):
                        if (wy > 0 and bool(col_has_power[wy-1])) or \
                           (wy < WORLD_H-1 and bool(col_has_power[wy+1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wires (both sides)
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wires (both sides)
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Connect roads between horizontal wire rows (vertical connector roads)
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx+1]
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    for mid_y in range(wr1+2, wr2-1):
                        if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                            adj = (ib(rcx, mid_y-1) and bool(rm[mid_y-1, rcx])) or \
                                  (ib(rcx, mid_y+1) and bool(rm[mid_y+1, rcx]))
                            if adj:
                                return (Tool.ROAD, rcx, mid_y)

    elif phase == 5:
        # Connect roads between vertical wire cols (horizontal connector roads)
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx+1]
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    for mid_x in range(wc1+2, wc2-1):
                        if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                            adj = (ib(mid_x-1, ry) and bool(rm[ry, mid_x-1])) or \
                                  (ib(mid_x+1, ry) and bool(rm[ry, mid_x+1]))
                            if adj:
                                return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Wire intersections between corridors
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc-1])) or (wc < WORLD_W-1 and bool(wm[wr, wc+1]))
                col_ok = (wr > 0 and bool(wm[wr-1, wc])) or (wr < WORLD_H-1 and bool(wm[wr+1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 7:
        # Extend road network toward powered unpaved regions
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H-3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W-3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # Wire toward unpowered road areas
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 4)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            # Prefer clustering near existing zones
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            # Slight center preference
            scores[i] += 0.5 / (1.0 + abs(x - 60)/60.0 + abs(y - 50)/50.0)
            # Prefer fully powered and roaded
            scores[i] += 1.0 if bool(near_power[y, x]) else 0.0

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_positions = [
            (12, 6), (36, 6), (60, 6), (84, 6), (108, 6),
            (12, 31), (36, 31), (60, 31), (84, 31), (108, 31),
            (12, 56), (36, 56), (60, 56), (84, 56), (108, 56),
            (12, 81), (36, 81), (60, 81), (84, 81), (108, 81),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (24, 19), (48, 19), (72, 19), (96, 19),
            (24, 44), (48, 44), (72, 44), (96, 44),
            (24, 69), (48, 69), (72, 69), (96, 69),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (24, 32), (72, 32), (24, 69), (72, 69),
            (48, 19), (96, 19), (48, 81), (96, 81),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (6, 6), (114, 6), (6, 94), (114, 94),
            (60, 6), (6, 50), (114, 50), (60, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value when city is established
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire from existing wire toward unpowered roads ----
    needs_power2 = rm & ~near_power
    npys2, npxs2 = np.where(needs_power2)
    if len(npxs2) > 0:
        ti = (step * 23) % len(npxs2)
        tx2, ty2 = int(npxs2[ti]), int(npys2[ti])
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            dists2 = np.abs(wire_xs2 - tx2) + np.abs(wire_ys2 - ty2)
            best_wi2 = np.argmin(dists2)
            bwx2, bwy2 = int(wire_xs2[best_wi2]), int(wire_ys2[best_wi2])
            dx2 = 0 if tx2 == bwx2 else (1 if tx2 > bwx2 else -1)
            dy2 = 0 if ty2 == bwy2 else (1 if ty2 > bwy2 else -1)
            for nx3, ny3 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: extend roads from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wire spines + flanking roads."""
    actions = []
    # Central power plant at (60, 50)
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Additional plants at cardinal extremes for coverage
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    actions.append((Tool.COALPOWER, 60, 20))
    actions.append((Tool.COALPOWER, 60, 80))
    # Roads flanking horizontal spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    # Roads flanking vertical spine
    for y in range(1, 99):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone mix: 55% residential, 25% commercial, 20% industrial
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Grid of neighborhoods across map
    def make_hoods():
        hoods = []
        # Denser grid: 9 cols x 8 rows
        for col in range(9):
            for row in range(8):
                cx = 7 + col * 13
                cy = 7 + row * 12
                hoods.append((cx, cy))
        return hoods

    all_hoods = make_hoods()
    # Sort by distance from center
    all_hoods.sort(key=lambda h: abs(h[0]-60) + abs(h[1]-50))

    def get_active_hoods():
        if pop < 50:
            return all_hoods[:6]
        elif pop < 200:
            return all_hoods[:15]
        elif pop < 500:
            return all_hoods[:28]
        elif pop < 1000:
            return all_hoods[:45]
        elif pop < 2000:
            return all_hoods[:60]
        else:
            return all_hoods

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Wire corridors
    # More wire rows and cols for better coverage
    wire_rows = [13, 25, 37, 50, 62, 74, 86]
    wire_cols = [7, 20, 33, 46, 60, 73, 86, 100, 113]

    # === CLOSED-LOOP PHASES ===

    # Phase A: Ensure power plants near active hoods (scan for missing coverage)
    # Every ~15 steps, check if active hoods have nearby plant
    if step % 15 < 4:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 18), min(WORLD_W, hx + 19)
            y0, y1 = max(0, hy - 18), min(WORLD_H, hy + 19)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find closest empty cell for a plant
                for r in range(2, 15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # Phase B: Extend horizontal wire corridors (reactive: extend from existing wire/plant)
    if step % 10 in (0, 1):
        for wr in wire_rows:
            # Find leftmost gap and try to fill from existing wire
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left_ok = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right_ok = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left_ok or right_ok) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase C: Extend vertical wire corridors
    if step % 10 in (2, 3):
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up_ok = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn_ok = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up_ok or dn_ok) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase D: Roads flanking wire rows
    if step % 10 == 4:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (1 <= ry <= WORLD_H - 2):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    # Phase E: Roads flanking wire cols
    if step % 10 == 5:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (1 <= rcx <= WORLD_W - 2):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    # Phase F: Cross roads between wire rows (horizontal connectors)
    if step % 10 == 6:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj and bool(near_power[mid_y, rx]):
                        return (Tool.ROAD, rx, mid_y)

    # Phase G: Cross roads between wire cols (vertical connectors)
    if step % 10 == 7:
        for wci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wci], wire_cols[wci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj and bool(near_power[ry, mid_x]):
                        return (Tool.ROAD, mid_x, ry)

    # Civic services - reactive to population
    if pop > 80:
        fire_spots = [(x, y) for y in range(12, 100, 18) for x in range(12, 120, 22)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(x, y) for y in range(18, 100, 22) for x in range(18, 120, 26)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(28, 28), (88, 28), (28, 68), (88, 68), (58, 48), (15, 48), (103, 48)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(5, 50), (113, 50), (60, 5), (60, 93), (5, 5), (113, 5), (5, 93), (113, 93), (30, 25), (90, 75)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5, 93), (113, 93), (5, 5), (113, 5), (60, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(48, 5), (72, 5), (48, 90), (72, 90), (5, 48)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # === ZONE PLACEMENT (main closed-loop action) ===
    # Find candidate cells: empty, near road, near power
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire corridors themselves
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to nearest active hood
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use step + pop offset to vary placement and avoid getting stuck
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks for land value
    if pop > 150 and step % 4 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 9) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend roads from existing roads into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Wire toward unpowered active hoods
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Extend any existing wire to expand power coverage
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: place coal plant near unpowered active hood
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle with wire spines."""
    actions = []
    # Three power plants spread across map
    plants = [(30, 50), (60, 25), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Wire cross
        for d in range(-5, 6):
            actions.append((Tool.WIRE, px + d, py))
            actions.append((Tool.WIRE, px, py + d))
        # Initial roads nearby
        for d in range(-5, 6):
            actions.append((Tool.ROAD, px + d, py - 3))
            actions.append((Tool.ROAD, px + d, py + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 35% industrial, 25% commercial, 40% residential
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.35:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of anchors - 5 columns x 5 rows
    all_anchors = []
    for ax in [15, 35, 60, 85, 105]:
        for ay in [15, 30, 50, 70, 85]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:    return 3
        if pop < 150:   return 5
        if pop < 300:   return 8
        if pop < 500:   return 12
        if pop < 800:   return 16
        if pop < 1200:  return 20
        if pop < 2000:  return 22
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    wire_half = min(18, 5 + pop // 10)
    vert_half = min(12, 4 + pop // 15)

    # ---- WIRE EXPANSION: horizontal spines ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    # ---- WIRE EXPANSION: vertical spines ----
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- WIRE CONNECTIONS between anchors in same column ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    # ---- WIRE CONNECTIONS between anchors in same row ----
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD GRID: horizontal roads offset from wire, and vertical connector roads ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        # Roads at ay-3 and ay+3 (offset 3 instead of 2 to leave room for zones)
        for road_y_off in [-3, 3]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx+ddx, road_y) and bool(rm[road_y, cx+ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y-1) and bool(wm[road_y-1, cx])) or \
                               (ib(cx, road_y+1) and bool(wm[road_y+1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # ---- VERTICAL ROADS: flanking vertical wire spines ----
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-3, 3]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy+ddy) and bool(rm[cy+ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x-1, cy) and bool(wm[cy, road_x-1])) or \
                               (ib(road_x+1, cy) and bool(wm[cy, road_x+1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: near roads and wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_spots = [
            (8, 8), (35, 8), (62, 8), (92, 8), (112, 8),
            (8, 28), (35, 28), (62, 28), (92, 28), (112, 28),
            (8, 48), (35, 48), (62, 48), (92, 48), (112, 48),
            (8, 68), (35, 68), (62, 68), (92, 68), (112, 68),
            (8, 88), (35, 88), (62, 88), (92, 88), (112, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (12, 12), (40, 12), (70, 12), (100, 12),
            (12, 40), (40, 40), (70, 40), (100, 40),
            (12, 60), (40, 60), (70, 60), (100, 60),
            (12, 80), (40, 80), (70, 80), (100, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(22, 5), (58, 5), (98, 5), (22, 92), (58, 92), (98, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        # Nuclear plants for more power
        for (nx2, ny2) in [(5, 5), (115, 5), (5, 93), (115, 93), (60, 93)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for (ax2, ay2) in [(55, 5), (5, 48), (115, 48), (55, 93)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for (sx2, sy2) in [(5, 90), (115, 90), (58, 95), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for x in range(45, 76):
        if x != cx:
            actions.append((Tool.WIRE, x, cy))
    # Vertical wire spine
    for y in range(35, 66):
        if y != cy:
            actions.append((Tool.WIRE, cx, y))
    # Corner plants for wider coverage
    for px, py in [(20, 20), (100, 20), (20, 80), (100, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Roads flanking center wire
    for d in range(-8, 9):
        actions.append((Tool.ROAD, cx - 2, cy + d))
        actions.append((Tool.ROAD, cx + 2, cy + d))
        actions.append((Tool.ROAD, cx + d, cy - 2))
        actions.append((Tool.ROAD, cx + d, cy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        src = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= src[:-d, :]
            result[:-d, :] |= src[d:, :]
            result[:, d:] |= src[:, :-d]
            result[:, :-d] |= src[:, d:]
        return result

    nbr_power = dilate(wm | pm, 5)
    nbr_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.27:
            return Tool.INDUSTRIAL
        if cr < 0.27:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Active neighborhood grid — unlock more as pop grows
    all_hoods = []
    for hy in range(12, 95, 14):
        for hx in range(12, 115, 14):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 3
        if pop < 200:   return 8
        if pop < 500:   return 16
        if pop < 1000:  return 25
        if pop < 2000:  return 36
        if pop < 4000:  return 50
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    stride = max(1, len(all_hoods) // n_active)
    active_hoods = all_hoods[::stride][:n_active]

    hood_idx = step % max(len(active_hoods), 1)
    hx_cur, hy_cur = active_hoods[hood_idx]

    # === PHASE 1: Ensure each active hood has a power plant nearby ===
    if funds > 1200:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
            y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: Wire spines for current hood ===
    spine_range = 10
    hx, hy = hx_cur, hy_cur

    # Vertical spine at column hx
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine at row hy
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # === PHASE 3: Connect wires between neighboring hoods ===
    for i_h in range(min(len(active_hoods), 8)):
        hx1, hy1 = active_hoods[(hood_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            if abs(hy2 - hy1) <= 2 and 4 <= abs(hx2 - hx1) <= 20 and hx2 > hx1:
                mid_y = (hy1 + hy2) // 2
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            if abs(hx2 - hx1) <= 2 and 4 <= abs(hy2 - hy1) <= 18 and hy2 > hy1:
                mid_x = (hx1 + hx2) // 2
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # === PHASE 4: Roads flanking wire spines ===
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx]

    for rx in [hx - 2, hx + 2]:
        if not ib(rx, hy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if not (bool(em[ry, rx]) or bool(zone_tiles[ry, rx])): continue
            if bool(pm[ry, rx]): continue
            if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy - 2, hy + 2]:
        if not ib(hx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if not (bool(em[ry2, rcx]) or bool(zone_tiles[ry2, rcx])): continue
            if bool(pm[ry2, rcx]): continue
            if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # === PHASE 5: Zone placement ===
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Distance to nearest active hood
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride2 = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride2):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: Extend roads into powered areas ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (sk + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === CIVIC SERVICES ===
    if pop > 30:
        fire_grid = [(fx, fy) for fy in range(12, 95, 16) for fx in range(12, 115, 16)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(14, 90, 18) for px2 in range(14, 110, 18)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 4 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 19 + pop) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 350:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 900:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (50, 6), (80, 6), (50, 93), (80, 93)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: extend wire from plant ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === FALLBACK: extend wire from existing wires ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: place new plant near unpowered active hood ===
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 12):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

