    # 3 coal plants along a horizontal spine
    for px in [30, 60, 90]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at x=30,60,90
    for y in range(1, 99):
        for wx in [30, 60, 90]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking the horizontal spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
