def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # ---- CLOSED-LOOP: scan current map and react ----

    # 1) If any active neighborhood lacks a power plant nearby, place one
    # Active neighborhoods scale with population
    all_hoods = []
    for col in range(8):
        for row in range(9):
            cx = 8 + col * 15
            cy = 6 + row * 11
            all_hoods.append((cx, cy))

    if pop < 100:
        n_hoods = 7
    elif pop < 300:
        n_hoods = 15
    elif pop < 600:
        n_hoods = 28
    elif pop < 1200:
        n_hoods = 45
    elif pop < 2500:
        n_hoods = 60
    else:
        n_hoods = len(all_hoods)

    # Pick active hoods: spread evenly
    step_sz = max(1, len(all_hoods) // n_hoods)
    active_hoods = all_hoods[::step_sz][:n_hoods]

    # 2) Check for unpowered active hoods and wire/plant toward them
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered_hoods:
        # Find nearest wire/plant to each unpowered hood and extend toward it
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered_hoods[0]
            dists = np.abs(wire_xs_arr - tx).astype(float) + np.abs(wire_ys_arr - ty).astype(float)
            best_wi = int(np.argmin(dists))
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            # Step toward target
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            # Try horizontal then vertical
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)
        # If no wire exists near hood, place coal plant
        for hx, hy in unpowered_hoods:
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = hx+dx, hy+dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)

    # 3) Extend roads from existing roads into powered areas
    # Prioritize extending roads into areas near active hoods
    if step % 3 in (0, 1):
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            # Find road tiles near active hoods
            best_road = None
            best_score = 1e9
            sk = (step * 11 + pop * 7) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        # Score by proximity to active hoods
                        score = min(abs(nx2-hx)+abs(ny2-hy) for hx,hy in active_hoods)
                        if score < best_score:
                            best_score = score
                            best_road = (nx2, ny2)
            if best_road:
                return (Tool.ROAD, best_road[0], best_road[1])

    # 4) Extend wire from existing wire/plant toward unpowered road areas
    if step % 3 == 2:
        # Find road tiles that lack power
        road_no_power_mask = rm & ~near_power
        rny, rnx = np.where(road_no_power_mask)
        if len(rnx) > 0:
            wire_ys2, wire_xs2 = np.where(wm | pm)
            if len(wire_xs2) > 0:
                # Pick closest unpowered road tile
                idx = (step * 17 + pop * 3) % len(rnx)
                tx, ty = int(rnx[idx]), int(rny[idx])
                dists = np.abs(wire_xs2 - tx).astype(float) + np.abs(wire_ys2 - ty).astype(float)
                bwi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs2[bwi]), int(wire_ys2[bwi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # 5) Civic services based on population
    if pop > 80:
        fire_spots = [(x, y) for y in range(10, 100, 20) for x in range(10, 120, 25)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(x, y) for y in range(15, 100, 25) for x in range(15, 120, 28)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(10, 10), (110, 10), (10, 90), (110, 90), (60, 5), (60, 93), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10), (60, 93)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3500:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # 6) Zone placement: find tiles near road AND power, closest to active hoods
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    cand_mask = em & near_road & near_power
    # Keep buffer from map edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use step+pop offset for variety
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # 7) Parks for land value improvement
    if pop > 100 and step % 5 == 0:
        pys, pxs = np.where(em & near_road & near_power)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # 8) Extend any wire into empty space (keep power grid growing)
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13 + pop) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire connections + roads."""
    actions = []
    # Plant 1 at center-left
    actions.append((Tool.COALPOWER, 40, 50))
    # Plant 2 at center-right
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire spine connecting plants horizontally
    for x in range(38, 83):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for dy in range(-6, 7):
        actions.append((Tool.WIRE, 40, 50 + dy))
        actions.append((Tool.WIRE, 80, 50 + dy))
    # Roads flanking wire spines
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, 39, 50 + dy))
        actions.append((Tool.ROAD, 41, 50 + dy))
        actions.append((Tool.ROAD, 79, 50 + dy))
        actions.append((Tool.ROAD, 81, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)
    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(wm | pm, 6)

    # ---- NEIGHBORHOOD GRID: 6 cols x 4 rows = 24 neighborhoods ----
    neighborhood_configs = []
    for col_i, cx in enumerate([20, 40, 60, 80, 100, 115]):
        for row_i, cy in enumerate([15, 35, 65, 85]):
            neighborhood_configs.append((cx, cy, col_i * 4 + row_i))

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 3
        if pop < 500:   return 6
        if pop < 900:   return 9
        if pop < 1500:  return 12
        if pop < 2500:  return 16
        if pop < 4000:  return 20
        return 24

    active = neighborhood_configs[:num_active()]

    # ---- 1. ENSURE POWER PLANTS for each active neighborhood ----
    for (cx, cy, idx) in active:
        x0, x1 = max(0, cx - 8), min(WORLD_W, cx + 9)
        y0, y1 = max(0, cy - 8), min(WORLD_H, cy + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Place a coal plant near neighborhood center
        for r in range(0, 10):
            placed = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    nx, ny = cx + dx, cy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if placed:
                break

    # ---- 2. BUILD WIRE SPINES: extend wire from each plant toward neighborhood center ----
    for (cx, cy, idx) in active:
        # Find nearest wire or plant
        wire_near = False
        for r in range(1, 5):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    nx, ny = cx+dx, cy+dy
                    if ib(nx, ny) and (bool(wm[ny, nx]) or bool(pm[ny, nx])):
                        wire_near = True
                        break
                if wire_near:
                    break
            if wire_near:
                break

        # Extend vertical wire spine at cx
        wire_col = [r for r in range(WORLD_H) if ib(cx, r) and bool(wm[r, cx])]
        spine_top = max(2, cy - 20)
        spine_bot = min(WORLD_H - 3, cy + 20)

        if not wire_col:
            # Start wire at center
            for dy in range(-3, 4):
                ny = cy + dy
                if ib(cx, ny) and bool(em[ny, cx]) and not bool(pm[ny, cx]):
                    return (Tool.WIRE, cx, ny)
        else:
            min_wr = min(wire_col)
            max_wr = max(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(cx, nr) and (bool(em[nr, cx]) or bool(wm[nr, cx])) and not bool(pm[nr, cx]):
                    return (Tool.WIRE, cx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(cx, nr) and (bool(em[nr, cx]) or bool(wm[nr, cx])) and not bool(pm[nr, cx]):
                    return (Tool.WIRE, cx, nr)

    # ---- 3. HORIZONTAL WIRE CONNECTIONS between neighborhoods in same row ----
    row_groups = {}
    for (cx, cy, idx) in active:
        if cy not in row_groups:
            row_groups[cy] = []
        row_groups[cy].append(cx)
    for row_y, wcs in row_groups.items():
        if len(wcs) < 2:
            continue
        wcs_sorted = sorted(wcs)
        for i in range(len(wcs_sorted) - 1):
            wc1, wc2 = wcs_sorted[i], wcs_sorted[i + 1]
            for conn_x in range(wc1 + 1, wc2):
                if ib(conn_x, row_y) and bool(em[row_y, conn_x]) and not bool(pm[row_y, conn_x]):
                    return (Tool.WIRE, conn_x, row_y)

    # ---- 4. BUILD ROADS flanking wire spines (left and right) ----
    for (cx, cy, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(cx, r) and bool(wm[r, cx])]
        if not wire_col:
            continue
        rl, rr = cx - 1, cx + 1
        cycle = (step + idx * 7) % max(len(wire_col), 1)
        for offset in range(min(len(wire_col), 12)):
            wr = wire_col[(cycle + offset) % len(wire_col)]
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 5. HORIZONTAL ROADS connecting neighborhoods ----
    for (cx, cy, idx) in active:
        # Extend horizontal road at cy near wire
        for dx in range(-10, 11):
            rx = cx + dx
            if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]) and not bool(wm[cy, rx]):
                near_w = any(
                    ib(rx + d, cy) and (bool(wm[cy, rx + d]) or bool(pm[cy, rx + d]))
                    for d in [-1, 1]
                )
                if near_w:
                    return (Tool.ROAD, rx, cy)

    # ---- 6. ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Keep balanced mix: ~20% industrial, ~25% commercial, ~55% residential
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (cx, cy, idx) in active:
            d = np.abs(cxs_arr.astype(float) - cx) + np.abs(cys_arr.astype(float) - cy)
            best_dist = np.minimum(best_dist, d)

        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            stride = max(1, len(road_xs_arr) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs_arr), stride):
                d = (np.abs(cxs_arr - road_xs_arr[i]) + np.abs(cys_arr - road_ys_arr[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Score: closer to neighborhood center and road is better
        score = best_dist * 0.7 + road_dist * 1.8
        order = np.argsort(score)
        step_off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- 7. EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- 8. CIVIC SERVICES (reactive to current population) ----
    if pop > 100:
        firestations = [
            (25, 15), (55, 15), (85, 15), (110, 15),
            (25, 45), (55, 45), (85, 45), (110, 45),
            (25, 75), (55, 75), (85, 75), (110, 75),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        polices = [
            (30, 30), (65, 30), (95, 30),
            (30, 60), (65, 60), (95, 60),
            (15, 50), (110, 50),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (35, 10), (75, 10), (35, 90), (75, 90),
            (10, 25), (110, 25), (10, 75), (110, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        # Add nuclear plants for extra power capacity
        nuke_locs = [(20, 20), (100, 20), (20, 80), (100, 80),
                     (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 7), min(WORLD_W, nx2 + 8)
                y0, y1 = max(0, ny2 - 7), min(WORLD_H, ny2 + 8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 85), (110, 85), (5, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airport_locs = [(8, 8), (98, 8), (8, 82), (98, 82)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- 9. FALLBACK: extend wire laterally from existing wires ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- 10. FALLBACK: road near power plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a row with wire and road spines."""
    actions = []
    # Three power plants along y=50
    plants = [(30, 50), (60, 50), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-8, 9):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire at +/-3 rows
        for dx in range(-8, 9):
            actions.append((Tool.ROAD, px + dx, py - 3))
            actions.append((Tool.ROAD, px + dx, py + 3))
        # Vertical roads at +/-3 cols
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 3, py + dy))
            actions.append((Tool.ROAD, px + 3, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target mix: 50% residential, 25% commercial, 25% industrial
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of anchors covering more of the map
    all_anchors = []
    for ax in [15, 30, 45, 60, 75, 90, 105]:
        for ay in [15, 30, 45, 60, 75, 85]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 6
        if pop < 300:  return 9
        if pop < 500:  return 14
        if pop < 800:  return 20
        if pop < 1200: return 28
        if pop < 2000: return 35
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    wire_half = min(22, 7 + pop // 10)
    vert_half = min(15, 5 + pop // 15)

    # ---- WIRE EXPANSION: horizontal spines ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    # ---- WIRE EXPANSION: vertical spines ----
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- WIRE CONNECTIONS between anchors in same column ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    # ---- WIRE CONNECTIONS between anchors in same row ----
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: grid roads at +/-3 from wire spines ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-3, 3]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx+ddx, road_y) and bool(rm[road_y, cx+ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y-1) and bool(wm[road_y-1, cx])) or \
                               (ib(cx, road_y+1) and bool(wm[road_y+1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # ---- VERTICAL ROADS flanking vertical wire spines ----
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-3, 3]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy+ddy) and bool(rm[cy+ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x-1, cy) and bool(wm[cy, road_x-1])) or \
                               (ib(road_x+1, cy) and bool(wm[cy, road_x+1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_spots = [
            (7, 7), (35, 7), (62, 7), (90, 7), (112, 7),
            (7, 25), (35, 25), (62, 25), (90, 25), (112, 25),
            (7, 45), (35, 45), (62, 45), (90, 45), (112, 45),
            (7, 65), (35, 65), (62, 65), (90, 65), (112, 65),
            (7, 85), (35, 85), (62, 85), (90, 85), (112, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (12, 12), (40, 12), (68, 12), (96, 12),
            (12, 40), (40, 40), (68, 40), (96, 40),
            (12, 68), (40, 68), (68, 68), (96, 68),
            (12, 90), (40, 90), (68, 90), (96, 90),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(20, 5), (60, 5), (100, 5), (20, 93), (60, 93), (100, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        for (nx2, ny2) in [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5), (60, 94)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for (ax2, ay2) in [(55, 6), (5, 50), (115, 50), (55, 92)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for (sx2, sy2) in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Closed-loop city builder: reacts to current tile_map each step
# Key improvements over parent:
# - Truly reactive: scans existing infrastructure before placing
# - Compact 3-neighborhood cluster strategy with BFS-like expansion
# - Road grid first, then wire along roads, then zones in powered+roaded cells
# - Better RCI targeting: heavy residential early, balanced later

def init(obs, state):
    """Bootstrap: one central coal plant + cross of wires + surrounding roads."""
    actions = []
    cx, cy = 60, 50
    # Central power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the wire cross
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    DIRS4 = [(1,0),(-1,0),(0,1),(0,-1)]

    # ---- PHASE 1: Ensure power plant exists near map center ----
    # If no plant anywhere, place one
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # ---- PHASE 2: Extend wire from existing wire/plant toward unpowered roads ----
    # Find road tiles not adjacent to wire/plant -> extend wire toward them
    # Build neighbor-of-wire mask
    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-1, 2):
        for dx in range(-1, 2):
            if dx == 0 and dy == 0:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Build wider power reach mask (zones need power within ~3 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Road reach mask (zones need road within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- STRATEGY: Grow roads outward from existing road network ----
    # Then wire outward from existing wire/plant adjacent to roads
    # Then place zones where both road and power reach

    # Target neighborhood centers in a ring pattern expanding from center
    # Based on current pop, determine how many neighborhoods to activate
    def num_hoods():
        if pop < 200:   return 6
        if pop < 500:   return 12
        if pop < 1000:  return 20
        if pop < 2000:  return 30
        if pop < 5000:  return 50
        if pop < 10000: return 80
        return 120

    # Grid of neighborhood centers, dense spacing
    spacing = 9  # 9-tile spacing between centers
    nh_cols = list(range(5, WORLD_W - 4, spacing))
    nh_rows = list(range(5, WORLD_H - 4, spacing))
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    n_active = min(num_hoods(), len(all_hoods))
    # Select hoods closest to center first
    cx_map, cy_map = 60, 50
    hood_dists = [(abs(hx - cx_map) + abs(hy - cy_map), hx, hy) for hx, hy in all_hoods]
    hood_dists.sort()
    active_hoods = [(hx, hy) for _, hx, hy in hood_dists[:n_active]]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        """Check 3x3 area centered at (zx,zy) is all empty or zone."""
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 2a: Place roads adjacent to existing roads toward active hoods ----
    # For each active hood, if it doesn't have road nearby, grow road toward it
    road_ys, road_xs = np.where(rm)

    if len(road_xs) > 0 and step % 3 != 0:  # mostly grow roads
        # Find hood that needs road most
        for hx, hy in active_hoods:
            if not bool(nbr_road[hy, hx]):
                # Find nearest road tile and extend toward hood
                dists = np.abs(road_xs - hx) + np.abs(road_ys - hy)
                nearest_idx = int(np.argmin(dists))
                rx, ry = int(road_xs[nearest_idx]), int(road_ys[nearest_idx])
                # Step toward hood
                dx_sign = 0 if hx == rx else (1 if hx > rx else -1)
                dy_sign = 0 if hy == ry else (1 if hy > ry else -1)
                # Try horizontal first, then vertical
                candidates = []
                if dx_sign != 0:
                    candidates.append((rx + dx_sign, ry))
                if dy_sign != 0:
                    candidates.append((rx, ry + dy_sign))
                for nx, ny in candidates:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # ---- PHASE 2b: Extend wire from existing wire toward roads that lack power ----
    # Find road tiles that have no power nearby - extend wire toward them
    unpowered_roads = rm & ~nbr_power
    unpow_ys, unpow_xs = np.where(unpowered_roads)

    wire_ys, wire_xs = np.where(wm | pm)

    if len(unpow_xs) > 0 and len(wire_xs) > 0:
        # Pick first unpowered road and extend wire toward it
        # Find closest wire-to-unpowered pair
        target_idx = (step * 7) % len(unpow_xs)
        tx, ty = int(unpow_xs[target_idx]), int(unpow_ys[target_idx])
        dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
        near_idx = int(np.argmin(dists))
        wx, wy = int(wire_xs[near_idx]), int(wire_ys[near_idx])
        # Step wire toward target
        dx_sign = 0 if tx == wx else (1 if tx > wx else -1)
        dy_sign = 0 if ty == wy else (1 if ty > wy else -1)
        candidates = []
        if dx_sign != 0:
            candidates.append((wx + dx_sign, wy))
        if dy_sign != 0:
            candidates.append((wx, wy + dy_sign))
        for nx, ny in candidates:
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: Place zones in powered+roaded empty cells ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 50% res, 25% com, 25% ind early; balance later
        if pop < 500:
            if ir < 0.20: return Tool.INDUSTRIAL
            if cr < 0.20: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if ir < 0.25: return Tool.INDUSTRIAL
            if cr < 0.25: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    cand_mask = em & nbr_road & nbr_power
    # Keep border margin for 3x3 zones
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Sort by distance to nearest active hood
        best_dist = np.full(len(cxs_arr), 999999.0)
        for hx, hy in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[i]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 4: Add more power plants if needed ----
    # If any active hood lacks power entirely, place a plant near it
    for hx, hy in active_hoods:
        x0, x1 = max(0, hx-10), min(WORLD_W, hx+11)
        y0, y1 = max(0, hy-10), min(WORLD_H, hy+11)
        if not np.any(pm[y0:y1, x0:x1]):
            # Place a plant at an empty spot near hood
            for r in range(1, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = hx+dx, hy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            if pop > 3000 and funds > 15000:
                                return (Tool.NUCLEARPOWER, nx, ny)
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 5: Civic services ----
    if pop > 100:
        fire_spots = [(hx+3, hy+3) for hx, hy in active_hoods[:max(1, n_active//4)]]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [(hx-3, hy-3) for hx, hy in active_hoods[:max(1, n_active//4)]]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [(hx, hy-4) for hx, hy in active_hoods[::5]]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for sx, sy in [(10, 90), (110, 90), (10, 10), (110, 10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        for sx, sy in [(45, 8), (75, 8), (45, 92), (75, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 6: Extend roads from existing network into empty powered areas ----
    if len(road_xs) > 0:
        step_k = (step * 11) % len(road_xs)
        for offset in range(min(len(road_xs), 100)):
            k = (step_k + offset * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in DIRS4:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: Extend wire from existing wire into empty areas ----
    wire_all_ys, wire_all_xs = np.where(wm)
    if len(wire_all_xs) > 0:
        step_k2 = (step * 13) % len(wire_all_xs)
        for offset in range(min(len(wire_all_xs), 80)):
            k = (step_k2 + offset * 5) % len(wire_all_xs)
            wx2, wy2 = int(wire_all_xs[k]), int(wire_all_ys[k])
            for dx3, dy3 in DIRS4:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- PHASE 8: Parks near zones for land value ----
    if pop > 200 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_power
        py_arr, px_arr = np.where(park_cands)
        if len(px_arr) > 0:
            idx2 = (step * 19) % len(px_arr)
            return (Tool.PARK, int(px_arr[idx2]), int(py_arr[idx2]))

    return None

