def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 8

    # === PHASE 0: Ensure power plants distributed across map ===
    if phase == 0:
        plant_positions = []
        for py in range(15, WORLD_H - 5, 20):
            for px in range(15, WORLD_W - 5, 20):
                plant_positions.append((px, py))
        for px, py in plant_positions:
            x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
            y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 1: Extend wire toward unpowered zones ===
    if phase == 1:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        wire_ys_a, wire_xs_a = np.where(power_src)
        if len(uz_xs) > 0 and len(wire_xs_a) > 0:
            best_dist = 999999
            best_zone = None
            sample = min(len(uz_xs), 30)
            for i in range(sample):
                idx = (step * 17 + i * 7) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                d = int(np.min(dists))
                if d < best_dist:
                    best_dist = d
                    best_zone = (tx, ty)
            if best_zone is not None:
                tx, ty = best_zone
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

        # Extend wire into unpowered empty regions adjacent to power
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False

        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            unpowered_empty = em & ~near_power & ~zone_tiles
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                best_dist2 = 1e9
                best_k = 0
                sample_indices = np.linspace(0, len(upxs) - 1, min(30, len(upxs)), dtype=int)
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_indices)
                    if d < best_dist2:
                        best_dist2 = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # === PHASE 2: Build/extend road grid ===
    if phase == 2:
        # Connect unroaded zones to road first
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

        # Extend road grid (every 6 tiles) into powered areas
        road_grid_targets = []
        for gy in range(6, 97, 6):
            for gx in range(6, 115, 6):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        if road_grid_targets:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted

            road_cand = em & adj_to_road & near_power & ~zone_tiles
            road_cand[0:2, :] = False
            road_cand[WORLD_H - 2:, :] = False
            road_cand[:, 0:2] = False
            road_cand[:, WORLD_W - 2:] = False

            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                best_dist3 = 1e9
                best_k3 = 0
                targets_sample = road_grid_targets[:30]
                for i in range(min(len(rxs2), 400)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist3:
                        best_dist3 = d
                        best_k3 = i
                return (Tool.ROAD, int(rxs2[best_k3]), int(rys2[best_k3]))
            else:
                for gx, gy in road_grid_targets[:10]:
                    if bool(em[gy, gx]):
                        return (Tool.ROAD, gx, gy)

    # === PHASE 3: Civic services ===
    if phase == 3:
        if pop > 25:
            fire_grid = [(fx, fy) for fy in range(10, 95, 15) for fx in range(10, 115, 15)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        if pop > 150:
            police_grid = [(px2, py2) for py2 in range(15, 90, 18) for px2 in range(15, 110, 18)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        if pop > 300 and step % 8 == 3:
            park_cands = em & near_road & near_power & ~zone_tiles
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 31 + pop) % len(pxs3)
                return (Tool.PARK, int(pxs3[idx]), int(pys3[idx]))

        if pop > 500:
            stadium_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                            (60, 50), (15, 50), (105, 50), (60, 15), (60, 85)]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        if pop > 800:
            nuke_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                         (60, 10), (60, 90), (10, 50), (110, 50),
                         (35, 15), (85, 15), (35, 85), (85, 85)]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                    y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        if pop > 2000:
            seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 94)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # === PHASES 4-7: Zone placement (main loop) ===
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Score: prefer close to road, prefer spreading from existing zones
        score = road_dist * 1.0 + np.maximum(0, 8 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

