def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # Zone ratio: 50% RES, 30% COM, 20% IND — more commercial than parent
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            # Balanced bootstrap
            if ind_count < 3:
                return Tool.INDUSTRIAL
            if com_count < 3:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 5000:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.50:
                return Tool.RESIDENTIAL
            if ir < 0.18:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.32:
                return Tool.COMMERCIAL
            if rr < 0.52:
                return Tool.RESIDENTIAL
            if ir < 0.15:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PHASE 1: Add power plants to underserved areas ===
    if step % 6 == 0:
        # Check 4 quadrant anchor points first
        anchors = [(20, 25), (100, 25), (20, 75), (100, 75),
                   (40, 15), (80, 15), (40, 85), (80, 85),
                   (10, 50), (110, 50)]
        for ax, ay in anchors:
            x0, x1 = max(0, ax - 10), min(WORLD_W, ax + 11)
            y0, y1 = max(0, ay - 10), min(WORLD_H, ay + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                # Find closest empty spot
                for r in range(0, 6):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = ax + dx, ay + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 2: Nuclear power when population warrants ===
    if step % 6 == 1 and pop > 500:
        nuke_locs = [
            (20, 50), (100, 50),
            (60, 20), (60, 80),
            (35, 35), (85, 35), (35, 65), (85, 65),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    # === PHASE 3: Wire extension toward unpowered zones ===
    if step % 6 == 2:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                best_dist = 999999
                best_zone = None
                sample = min(len(uz_xs), 15)
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

        # Also extend wire grid - dense horizontal lines every 8 rows
        for wy in range(8, WORLD_H - 8, 8):
            for wx in range(1, WORLD_W - 1):
                if bool(em[wy, wx]) and not bool(rm[wy, wx]):
                    # Check if adjacent to existing power
                    adj = False
                    for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)]:
                        nwx, nwy = wx+ddx, wy+ddy
                        if ib(nwx, nwy) and bool(power_src[nwy, nwx]):
                            adj = True
                            break
                    if adj:
                        return (Tool.WIRE, wx, wy)

    # === PHASE 4: Road extension ===
    if step % 6 == 3:
        # Dense road grid: every 4 tiles
        road_grid_targets = []
        for gy in range(4, WORLD_H - 4, 4):
            for gx in range(4, WORLD_W - 4, 4):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        # Connect unroaded zones first
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

        if road_grid_targets:
            # Find road candidate adjacent to existing road and near target
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted

            road_cand = em & adj_to_road & near_power & ~zone_tiles
            road_cand[0:2, :] = False
            road_cand[WORLD_H - 2:, :] = False
            road_cand[:, 0:2] = False
            road_cand[:, WORLD_W - 2:] = False

            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                targets_sample = road_grid_targets[:40]
                best_dist = 1e9
                best_k = 0
                for i in range(min(len(rxs2), 400)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))

    # === PHASE 5: Civic services ===
    if step % 6 == 4:
        # Fire stations every 10 tiles
        if pop > 10:
            fire_grid = [(fx, fy) for fy in range(8, 95, 10) for fx in range(8, 115, 10)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        # Police stations
        if pop > 50:
            police_grid = [(px2, py2) for py2 in range(12, 90, 12) for px2 in range(12, 110, 12)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        # Stadiums boost residential significantly
        if pop > 300:
            stadium_locs = [
                (30, 25), (60, 25), (90, 25),
                (30, 50), (90, 50),
                (30, 75), (60, 75), (90, 75),
            ]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        # Airports
        if pop > 1000:
            airport_locs = [(5, 5), (105, 5), (5, 90), (105, 90)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        # Seaports
        if pop > 1500:
            seaport_locs = [(5, 40), (5, 60), (115, 40), (115, 60), (55, 3), (65, 3), (55, 96), (65, 96)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

        # Parks for land value
        if pop > 200 and step % 8 == 4:
            park_cands = em & near_road & near_power & ~zone_tiles
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 31 + pop * 13) % len(pxs3)
                return (Tool.PARK, int(pxs3[idx]), int(pys3[idx]))

    # === PHASE 6: Zone placement ===
    # Candidate: empty, near road, near power, not edge
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Score: prefer close to road, not too crowded
        score = road_dist * 1.2 + np.maximum(0, 5 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: power plants + wire spines + road corridors"""
    actions = []
    # 4 coal plants at strategic positions
    for px, py in [(20, 50), (60, 20), (100, 50), (60, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for y in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, y))
    # Vertical wire spines
    for x in [20, 60, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, x, y))
    # Roads flanking wire spines (horizontal)
    for y in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, y - 1))
            actions.append((Tool.ROAD, x, y + 1))
    # Roads flanking wire spines (vertical)
    for x in [20, 60, 100]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, x - 1, y))
            actions.append((Tool.ROAD, x + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target ratios: 50% res, 30% com, 20% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [20, 50, 80]
    wire_cols = [20, 60, 100]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- CLOSED-LOOP REACTIVE DECISIONS ---

    # 1. Repair broken wire spines (highest priority)
    # Check horizontal wire rows
    for wr in wire_rows:
        for wx in range(1, WORLD_W - 1):
            if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                # Check if neighbors have wire/plant (connectivity check)
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    if bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Check vertical wire cols
    for wc in wire_cols:
        for wy in range(1, WORLD_H - 1):
            if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    if bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # 2. Repair roads alongside wire spines
    for wr in wire_rows:
        for offset in [-1, 1]:
            ry = wr + offset
            if not (0 < ry < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    for wc in wire_cols:
        for offset in [-1, 1]:
            rcx = wc + offset
            if not (0 < rcx < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]):
                    return (Tool.ROAD, rcx, ry)

    # 3. Add cross-roads between wire rows to enable more zone placement
    phase = step % 10

    if phase == 3:
        # Cross-streets between wire rows
        for i in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[i], wire_rows[i+1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 4:
        # Cross-streets between wire cols
        for i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[i], wire_cols[i+1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 5:
        # Extend roads near existing roads reactively
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 6:
        # Wire toward zones not yet powered
        unpowered_zones = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpowered_zones)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 19) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 7:
        # Civic buildings based on pop
        if pop > 10:
            fire_spots = [
                (10,10),(35,10),(65,10),(95,10),(115,10),
                (10,30),(35,30),(95,30),(115,30),
                (10,50),(115,50),
                (10,70),(35,70),(95,70),(115,70),
                (10,90),(35,90),(65,90),(95,90),(115,90),
                (50,40),(70,40),(50,60),(70,60)
            ]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

    elif phase == 8:
        if pop > 80:
            police_spots = [
                (15,15),(45,15),(75,15),(105,15),
                (15,40),(45,40),(75,40),(105,40),
                (15,60),(45,60),(75,60),(105,60),
                (15,85),(45,85),(75,85),(105,85)
            ]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

    elif phase == 9:
        if pop > 400:
            for sx, sy in [(35,35),(85,35),(35,65),(85,65),(60,50)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)
        if pop > 700:
            for nx2, ny2 in [(5,50),(115,50),(60,5),(60,95)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)
        if pop > 1200:
            for sx, sy in [(5,5),(115,5),(5,95),(115,95)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 2000:
            for sx, sy in [(50,5),(70,5),(50,92),(70,92)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # 4. Reactively add power plants near areas that need them
    if step % 5 == 2:
        # Find area with road+empty but no power
        need_power = rm & ~near_power
        nys, nxs = np.where(need_power)
        if len(nxs) > 0:
            idx = (step * 7) % len(nxs)
            tx, ty = int(nxs[idx]), int(nys[idx])
            # Find nearest empty cell for plant
            for r in range(2, 20):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = tx+dx, ty+dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)

    # 5. Main zone placement — fully reactive
    # Build candidate mask: empty, near road, near power, away from edges/spines
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score candidates by distance to nearest zone (prefer clustering)
        if total_zones > 1:
            zone_ys_all, zone_xs_all = np.where(zone_tiles)
            if len(zone_xs_all) > 0:
                # Vectorized min distance to existing zones
                scores = np.full(len(cxs2), 999999.0)
                # Sample zones for speed
                sample_n = min(len(zone_xs_all), 50)
                sample_idx = np.linspace(0, len(zone_xs_all)-1, sample_n, dtype=int)
                for si in sample_idx:
                    zx_s = zone_xs_all[si]
                    zy_s = zone_ys_all[si]
                    d = np.abs(cxs2 - zx_s).astype(float) + np.abs(cys2 - zy_s).astype(float)
                    scores = np.minimum(scores, d)
                order = np.argsort(scores)
            else:
                order = np.arange(len(cxs2))
        else:
            # No zones yet — pick center of map
            cx_map, cy_map = WORLD_W // 2, WORLD_H // 2
            dist_center = np.abs(cxs2 - cx_map).astype(float) + np.abs(cys2 - cy_map).astype(float)
            order = np.argsort(dist_center)

        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # 6. Fallback: extend wire toward nearest road without power
    road_no_power = rm & ~near_power
    rys, rxs = np.where(road_no_power)
    if len(rxs) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 23) % len(rxs)
            tx, ty = int(rxs[idx]), int(rys[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # 7. Fallback: extend any existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # 8. Fallback: extend any road
    road_ys_fb, road_xs_fb = np.where(rm)
    if len(road_xs_fb) > 0:
        sk3 = (step * 31) % len(road_xs_fb)
        for off in range(min(len(road_xs_fb), 60)):
            k = (sk3 + off * 3) % len(road_xs_fb)
            rx4, ry4 = int(road_xs_fb[k]), int(road_ys_fb[k])
            for dx4, dy4 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx4, ny4 = rx4+dx4, ry4+dy4
                if ib(nx4, ny4) and bool(em[ny4, nx4]) and not bool(pm[ny4, nx4]):
                    return (Tool.ROAD, nx4, ny4)

    return None

# Strategy: Two separate neighborhood clusters connected by a highway
# Key changes from parent:
# 1. Two clusters: west (40,45) and east (80,45), each with their own power
# 2. Explicit grid roads (every 3 rows, every 4 cols) within each cluster
# 3. Heavier residential bias early, then balanced R/C/I
# 4. Wire backbone along row 45 and cols 40, 80
# 5. Civic services placed proactively near both clusters

def init(obs, state):
    actions = []
    # West cluster: coal plant
    actions.append((Tool.COALPOWER, 38, 45))
    # Wire east from west plant along row 45
    for x in range(39, 85):
        actions.append((Tool.WIRE, x, 45))
    # East cluster: nuclear plant
    actions.append((Tool.NUCLEARPOWER, 82, 45))
    # Wire vertical from row 45 up and down for west cluster
    for y in range(38, 53):
        actions.append((Tool.WIRE, 40, y))
    # Wire vertical for east cluster
    for y in range(38, 53):
        actions.append((Tool.WIRE, 80, y))
    # Initial roads for west cluster (horizontal)
    for x in range(36, 56):
        actions.append((Tool.ROAD, x, 42))
        actions.append((Tool.ROAD, x, 48))
    # Initial roads for east cluster (horizontal)
    for x in range(66, 86):
        actions.append((Tool.ROAD, x, 42))
        actions.append((Tool.ROAD, x, 48))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    plant_count = int(np.sum(pm))

    # Two cluster centers
    clusters = [(40, 45), (80, 45)]

    # Adaptive radius per cluster
    if pop < 200:
        radius = 12
    elif pop < 800:
        radius = 20
    elif pop < 2000:
        radius = 30
    else:
        radius = 40

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                # Allow placement on empty or existing zone tiles
                if not bool(em[nr, nc]) and not bool(resm[nr, nc]) and not bool(comm[nr, nc]) and not bool(indm[nr, nc]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Early game: industry for jobs
        if pop < 300:
            if ir < 0.3:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        # Mid game: balanced
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === PHASE 1: More power plants as city grows ===
    if pop > 300 and plant_count < 3:
        candidates = [(40, 70), (80, 70), (40, 20), (80, 20), (60, 45)]
        for px, py in candidates:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 1000 and plant_count < 5:
        candidates = [(20, 45), (100, 45), (60, 70), (60, 20)]
        for px, py in candidates:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 3000 and plant_count < 7:
        candidates = [(15, 25), (105, 25), (15, 70), (105, 70)]
        for px, py in candidates:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    # === PHASE 2: Wire grid (backbone + cluster-local) ===
    if step % 4 == 0:
        # Horizontal wire along key rows
        wire_rows = [45, 30, 60, 20, 70]
        for wr in wire_rows:
            dist = min(abs(wr - 45), abs(wr - 45))
            if dist > radius + 10:
                continue
            prev_power = False
            for wx in range(1, WORLD_W - 1):
                if bool(pm[wr, wx]) or bool(wm[wr, wx]):
                    prev_power = True
                    continue
                if prev_power and bool(em[wr, wx]):
                    # Only extend within active zone
                    near = any(abs(wx - cx) + abs(wr - cy) <= radius + 15 for cx, cy in clusters)
                    if near:
                        return (Tool.WIRE, wx, wr)
                else:
                    prev_power = False

        # Vertical wire at cluster x-coords and between
        wire_cols = [40, 80, 60, 20, 100]
        for wc in wire_cols:
            near = any(abs(wc - cx) <= radius + 15 for cx, _ in clusters)
            if not near:
                continue
            prev_power = False
            for wy in range(1, WORLD_H - 1):
                if bool(pm[wy, wc]) or bool(wm[wy, wc]):
                    prev_power = True
                    continue
                if prev_power and bool(em[wy, wc]):
                    near2 = any(abs(wc - cx) + abs(wy - cy) <= radius + 15 for cx, cy in clusters)
                    if near2:
                        return (Tool.WIRE, wc, wy)
                else:
                    prev_power = False

    # === PHASE 3: Road grid within each cluster ===
    # Build a dense grid: horiz roads every 3 rows, vert every 4 cols
    if step % 4 == 1:
        road_row_spacing = 3
        for cx, cy in clusters:
            y_min = max(2, cy - radius)
            y_max = min(WORLD_H - 2, cy + radius)
            # Snap to grid
            road_ys = list(range(y_min - (y_min % road_row_spacing), y_max, road_row_spacing))
            for ry in road_ys:
                if abs(ry - cy) > radius:
                    continue
                x_range = radius - abs(ry - cy) // 2
                for rx in range(max(2, cx - x_range), min(WORLD_W - 2, cx + x_range)):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        adj = False
                        for adx in [-1, 1]:
                            ax = rx + adx
                            if ib(ax, ry) and bool(rm[ry, ax]):
                                adj = True
                        if adj or rx == cx:
                            return (Tool.ROAD, rx, ry)

    elif step % 4 == 2:
        road_col_spacing = 4
        for cx, cy in clusters:
            x_min = max(2, cx - radius)
            x_max = min(WORLD_W - 2, cx + radius)
            road_xs = list(range(x_min - (x_min % road_col_spacing), x_max, road_col_spacing))
            for rxc in road_xs:
                if abs(rxc - cx) > radius:
                    continue
                y_range = radius - abs(rxc - cx) // 2
                for ry in range(max(2, cy - y_range), min(WORLD_H - 2, cy + y_range)):
                    if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                        adj = False
                        for ady in [-1, 1]:
                            ay = ry + ady
                            if ib(rxc, ay) and bool(rm[ay, rxc]):
                                adj = True
                        if adj or ry == cy:
                            return (Tool.ROAD, rxc, ry)

    # === PHASE 4: Zone placement ===
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone tiles: near road + power + within cluster radius
    ys_arr = np.arange(WORLD_H).reshape(-1, 1)
    xs_arr = np.arange(WORLD_W).reshape(1, -1)

    # Build cluster distance mask
    cluster_near = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for cx, cy in clusters:
        dist = np.abs(ys_arr - cy) + np.abs(xs_arr - cx)
        cluster_near |= (dist <= radius)

    cand_mask = em & nbr_road & nbr_power & cluster_near
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Sort by min distance to nearest cluster center
        min_dists = np.minimum(
            np.abs(cxs_arr - clusters[0][0]) + np.abs(cys_arr - clusters[0][1]),
            np.abs(cxs_arr - clusters[1][0]) + np.abs(cys_arr - clusters[1][1])
        )
        order = np.argsort(min_dists)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === CIVIC SERVICES: spread across both clusters ===
    if pop > 100:
        fire_spots = [
            (35, 38), (45, 38), (35, 52), (45, 52),
            (75, 38), (85, 38), (75, 52), (85, 52),
            (55, 45), (65, 45),
            (40, 30), (80, 30), (40, 60), (80, 60),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (38, 42), (48, 42), (38, 48), (48, 48),
            (78, 42), (88, 42), (78, 48), (88, 48),
            (58, 42), (68, 42),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for sx, sy in [(40, 35), (80, 35), (40, 55), (80, 55), (60, 35), (60, 55)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for sx, sy in [(10, 80), (110, 80), (10, 10), (110, 10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for sx, sy in [(15, 50), (105, 50), (60, 10), (60, 85)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 200 and step % 5 == 0:
        park_ys2, park_xs2 = np.where(em & nbr_road & nbr_power & cluster_near)
        if len(park_xs2) > 0:
            idx = (step * 19) % len(park_xs2)
            return (Tool.PARK, int(park_xs2[idx]), int(park_ys2[idx]))

    # === FALLBACKS ===
    # Extend road from existing roads (within cluster radius)
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 100)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            near = any(abs(rx2 - cx) + abs(ry2 - cy) <= radius + 5 for cx, cy in clusters)
            if not near:
                continue
            for dx2, dy2 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Extend wire from existing wire/plant
    if step % 4 == 3:
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            sk2 = (step * 13) % len(wire_xs2)
            for off in range(min(len(wire_xs2), 80)):
                k = (sk2 + off * 5) % len(wire_xs2)
                wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        near = any(abs(nx3 - cx) + abs(ny3 - cy) <= radius + 20 for cx, cy in clusters)
                        if near:
                            return (Tool.WIRE, nx3, ny3)

    # Emergency: no power near clusters
    for cx, cy in clusters:
        if not bool(nbr_power[cy, cx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants + cross wire spines + flanking roads"""
    actions = []
    # Three power plants: left, center, right
    for px, py in [(15, 50), (60, 50), (105, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [15, 40, 60, 80, 105]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows (one road per side)
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
            actions.append((Tool.ROAD, x, wy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Infrastructure design
    wire_rows = [25, 50, 75]
    wire_cols = [15, 40, 60, 80, 105]
    road_offsets = [-2, 2]  # roads 2 away from wire rows

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            # Early game: lots of industry to generate tax base
            if ir < 0.33: return Tool.INDUSTRIAL
            if cr < 0.22: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.25: return Tool.INDUSTRIAL
            if cr < 0.30: return Tool.COMMERCIAL
            if rr < 0.45: return Tool.RESIDENTIAL
            return Tool.RESIDENTIAL
        else:
            # Late game: more commercial/residential for population
            if cr < 0.35: return Tool.COMMERCIAL
            if rr < 0.50: return Tool.RESIDENTIAL
            if ir < 0.15: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ===== REACTIVE INFRASTRUCTURE REPAIR =====

    # 1. Fix gaps in wire rows reactively
    if step % 6 == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])))
                    right = (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # 2. Fix gaps in wire cols reactively
    if step % 6 == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc])))
                    dn = (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # 3. Fix road gaps near wire rows
    if step % 6 == 2:
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        # Only place if adjacent road exists or wire above/below
                        adj_road = (
                            (rx > 0 and bool(rm[ry, rx-1])) or
                            (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                            (ry > 0 and bool(rm[ry-1, rx])) or
                            (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        )
                        has_wire_near = (
                            bool(wm[wr, rx]) or bool(pm[wr, rx]) if 0 <= wr < WORLD_H else False
                        )
                        if (adj_road or rx <= 2) and has_wire_near:
                            return (Tool.ROAD, rx, ry)

    # 4. Fix vertical roads near wire cols
    if step % 6 == 3:
        for wc in wire_cols:
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        adj_road = (
                            (ry > 0 and bool(rm[ry-1, rcx])) or
                            (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                            bool(rm[ry, max(0, rcx-1)]) or
                            bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        )
                        has_wire_near = (
                            bool(wm[ry, wc]) or bool(pm[ry, wc]) if 0 <= wc < WORLD_W else False
                        )
                        if (adj_road or ry <= 2) and has_wire_near:
                            return (Tool.ROAD, rcx, ry)

    # 5. Reactively connect unpowered zones to nearest wire
    if step % 6 == 4:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 30)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # 6. Reactively connect unroaded zones to nearest road
    if step % 6 == 5:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bwy else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ===== CIVIC SERVICES =====
    if pop > 20:
        fire_spots = [
            (7, 7), (40, 7), (70, 7), (100, 7), (112, 7),
            (7, 33), (112, 33), (7, 58), (112, 58),
            (7, 82), (112, 82), (7, 92), (40, 92), (70, 92), (100, 92),
            (30, 50), (60, 28), (90, 28), (60, 72), (90, 72),
            (20, 15), (50, 15), (80, 15), (20, 85), (50, 85), (80, 85),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (20, 20), (55, 20), (85, 20), (110, 20),
            (20, 45), (55, 45), (85, 45), (110, 45),
            (20, 65), (55, 65), (85, 65), (110, 65),
            (20, 85), (55, 85), (85, 85), (110, 85),
            (10, 55), (60, 10), (60, 90),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (32, 18), (88, 18), (32, 82), (88, 82),
            (60, 50), (10, 50), (110, 50), (60, 12), (60, 88),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (10, 50), (110, 50), (60, 5), (60, 95),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10), (60, 95), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(45, 5), (75, 5), (45, 92), (75, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 60 and step % 10 == 7:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ===== ZONE PLACEMENT =====
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Avoid infrastructure rows/cols (keep clearance)
    for wr in wire_rows:
        cand_mask[max(0, wr-2):min(WORLD_H, wr+3), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-2):min(WORLD_W, wc+3)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active centers that adapt by population
        if pop < 100:
            # Focus on central cluster first
            active_centers = [
                (60, 50), (45, 50), (75, 50), (60, 35), (60, 65),
                (45, 35), (75, 35), (45, 65), (75, 65),
                (30, 50), (90, 50), (60, 20), (60, 80),
            ]
        elif pop < 500:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 12 + col * 16
                    cy = 12 + row * 18
                    active_centers.append((cx, cy))
        else:
            # Full coverage
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 7 + col * 11
                    cy = 7 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road toward powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 100)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 60)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plant + nuclear, wire cross, initial road grid"""
    actions = []
    # Coal plant at center
    actions.append((Tool.COALPOWER, 58, 50))
    # Wire horizontally from coal
    for x in range(59, 75):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically from coal
    for y in range(44, 57):
        actions.append((Tool.WIRE, 58, y))
    # Nuclear plant to the right
    actions.append((Tool.NUCLEARPOWER, 75, 50))
    # Initial horizontal roads to serve zones
    for x in range(52, 70):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    # Initial vertical roads
    for y in range(46, 55):
        actions.append((Tool.ROAD, 52, y))
        actions.append((Tool.ROAD, 69, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    cx, cy = 60, 50  # city center

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Growth radius
    if pop < 200:
        max_radius = 18
    elif pop < 600:
        max_radius = 32
    elif pop < 1500:
        max_radius = 50
    elif pop < 4000:
        max_radius = 70
    else:
        max_radius = 85

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Early: build industry for jobs, then balance
        if pop < 300 and ir < 0.35:
            return Tool.INDUSTRIAL
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ── Build neighbor proximity maps ──────────────────────────────────
    # Road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power proximity (within 4 tiles from wire or plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    ys_arr = np.arange(WORLD_H).reshape(-1, 1)
    xs_arr = np.arange(WORLD_W).reshape(1, -1)
    dist_from_center = np.abs(ys_arr - cy) + np.abs(xs_arr - cx)

    plant_count = int(np.sum(pm))

    # ── PHASE 1: Add more power plants as city grows ───────────────────
    if pop > 400 and plant_count < 3:
        for px, py in [(35, 50), (85, 50), (60, 25), (60, 75), (40, 30), (80, 30), (40, 70), (80, 70)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 1500 and plant_count < 5:
        for px, py in [(20, 50), (100, 50), (60, 15), (60, 85), (25, 30), (95, 30), (25, 70), (95, 70)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 3000 and plant_count < 8:
        for px, py in [(15, 25), (105, 25), (15, 75), (105, 75), (60, 10), (60, 90)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    # ── PHASE 2: Extend wire from power sources ────────────────────────
    # Key wire corridors to spread power
    wire_corridors = [
        # Main cross
        [(x, 50) for x in range(1, WORLD_W - 1)],
        [(60, y) for y in range(1, WORLD_H - 1)],
        # Secondary horizontals
        [(x, 25) for x in range(1, WORLD_W - 1)],
        [(x, 75) for x in range(1, WORLD_W - 1)],
        [(x, 37) for x in range(1, WORLD_W - 1)],
        [(x, 62) for x in range(1, WORLD_W - 1)],
        # Secondary verticals
        [(35, y) for y in range(1, WORLD_H - 1)],
        [(85, y) for y in range(1, WORLD_H - 1)],
        [(47, y) for y in range(1, WORLD_H - 1)],
        [(73, y) for y in range(1, WORLD_H - 1)],
    ]

    if step % 3 == 0:
        for corridor in wire_corridors:
            prev_powered = False
            for (wx, wy) in corridor:
                if not ib(wx, wy):
                    continue
                if bool(pm[wy, wx]) or bool(wm[wy, wx]):
                    prev_powered = True
                    continue
                if prev_powered and bool(em[wy, wx]):
                    dist = abs(wx - cx) + abs(wy - cy)
                    if dist <= max_radius + 25:
                        return (Tool.WIRE, wx, wy)
                else:
                    prev_powered = False

    # ── PHASE 3: Road grid ─────────────────────────────────────────────
    # Horizontal roads every 4 rows, vertical roads every 5 cols
    if step % 3 == 1:
        road_ys = list(range(cy - max_radius, cy + max_radius + 1, 4))
        for ry in road_ys:
            if not (1 <= ry < WORLD_H - 1):
                continue
            if abs(ry - cy) > max_radius:
                continue
            x_span = min(max_radius, 55)
            for rx in range(max(1, cx - x_span), min(WORLD_W - 1, cx + x_span)):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only extend if adjacent to existing road
                    has_adj = False
                    for adx in [-1, 1]:
                        ax = rx + adx
                        if ib(ax, ry) and bool(rm[ry, ax]):
                            has_adj = True
                    if has_adj or rx == cx:
                        return (Tool.ROAD, rx, ry)

    elif step % 3 == 2:
        road_xs = list(range(cx - max_radius, cx + max_radius + 1, 5))
        for rxc in road_xs:
            if not (1 <= rxc < WORLD_W - 1):
                continue
            if abs(rxc - cx) > max_radius:
                continue
            y_span = min(max_radius, 45)
            for ry in range(max(1, cy - y_span), min(WORLD_H - 1, cy + y_span)):
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    has_adj = False
                    for ady in [-1, 1]:
                        ay = ry + ady
                        if ib(rxc, ay) and bool(rm[ay, rxc]):
                            has_adj = True
                    if has_adj or ry == cy:
                        return (Tool.ROAD, rxc, ry)

    # ── PHASE 4: Zone placement ────────────────────────────────────────
    cand_mask = em & nbr_road & nbr_power & (dist_from_center <= max_radius)
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_c, cxs_c = np.where(cand_mask)
    if len(cxs_c) > 0:
        dists = np.abs(cxs_c - cx) + np.abs(cys_c - cy)
        order = np.argsort(dists)
        tool = pick_tool()
        # Use step to vary starting point so we don't always pick the same spot
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_c[k]), int(cys_c[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ── CIVIC SERVICES ─────────────────────────────────────────────────
    if pop > 120:
        fire_spots = [
            (48, 38), (72, 38), (48, 62), (72, 62),
            (60, 32), (60, 68), (36, 50), (84, 50),
            (32, 35), (88, 35), (32, 65), (88, 65),
            (45, 25), (75, 25), (45, 75), (75, 75),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [
            (52, 42), (68, 42), (52, 58), (68, 58),
            (42, 50), (78, 50), (60, 42), (60, 58),
            (38, 38), (82, 38), (38, 62), (82, 62),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for (sx, sy) in [(55, 44), (65, 44), (55, 56), (65, 56), (48, 50), (72, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for (sx, sy) in [(10, 88), (108, 88), (10, 12), (108, 12)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        for (sx, sy) in [(12, 50), (107, 50), (60, 8), (60, 91)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 250 and step % 9 == 0:
        park_ys2, park_xs2 = np.where(em & nbr_road & nbr_power)
        if len(park_xs2) > 0:
            idx = (step * 19) % len(park_xs2)
            return (Tool.PARK, int(park_xs2[idx]), int(park_ys2[idx]))

    # ── FALLBACK: Extend roads from existing road edges ────────────────
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 100)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            dist = abs(rx2 - cx) + abs(ry2 - cy)
            if dist > max_radius + 5:
                continue
            for dx2, dy2 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ── FALLBACK: Extend wire from existing wire/plant edges ───────────
    wire_ys2, wire_xs2 = np.where(wm | pm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 80)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    dist = abs(nx3 - cx) + abs(ny3 - cy)
                    if dist <= max_radius + 20:
                        return (Tool.WIRE, nx3, ny3)

    # Last resort: plant coal if center has no power
    if not bool(nbr_power[cy, cx]):
        for r in range(1, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap two coal plants with wire connections and initial roads."""
    actions = []
    # Left cluster center at (30, 50), Right cluster center at (90, 50)
    for cx, cy in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Horizontal wire spine
        for dx in range(-6, 7):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        # Vertical wire spine
        for dy in range(-6, 7):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking horizontal wire
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, cx + dx, cy - 1))
            actions.append((Tool.ROAD, cx + dx, cy + 1))
        # Roads flanking vertical wire
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Connect the two clusters with a wire bridge at y=50
    for x in range(37, 84):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Two main clusters + satellite clusters as pop grows
    # Base neighborhoods around two power plants
    base_hoods = [
        # Left cluster
        (30, 35), (30, 50), (30, 65),
        (18, 42), (18, 58),
        (42, 42), (42, 58),
        # Right cluster
        (90, 35), (90, 50), (90, 65),
        (78, 42), (78, 58),
        (102, 42), (102, 58),
        # Middle connector
        (60, 35), (60, 50), (60, 65),
        # Top/bottom rows
        (30, 20), (60, 20), (90, 20),
        (30, 80), (60, 80), (90, 80),
    ]

    def num_active():
        if pop < 100:   return 3
        if pop < 300:   return 7
        if pop < 600:   return 12
        if pop < 1000:  return 16
        if pop < 2000:  return 20
        if pop < 4000:  return len(base_hoods)
        return len(base_hoods)

    n_active = min(num_active(), len(base_hoods))
    active_hoods = base_hoods[:n_active]

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # PHASE 1: ensure each active hood has a power plant nearby
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
        y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: grow wire toward uncovered hoods
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            for (tx, ty) in uncovered:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    hood_cycle = step % max(len(active_hoods), 1)

    # PHASE 3: build roads around each active hood
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        spine = 7
        # Horizontal roads flanking wire
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for sign in [1, -1]:
                for dist in range(0, spine + 1):
                    rcx = hx + sign * dist
                    if not ib(rcx, ry2): continue
                    if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                        if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                            return (Tool.ROAD, rcx, ry2)
        # Vertical roads flanking wire
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for sign in [1, -1]:
                for dist in range(0, spine + 1):
                    rcy = hy + sign * dist
                    if not ib(rx, rcy): continue
                    if bool(em[rcy, rx]) and not bool(pm[rcy, rx]):
                        if bool(wm[rcy, hx]) or bool(pm[rcy, hx]):
                            return (Tool.ROAD, rx, rcy)

    # PHASE 4: extend wire spines
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        spine = 7
        for sign in [1, -1]:
            for dist in range(1, spine + 1):
                wy2 = hy + sign * dist
                if not ib(hx, wy2): continue
                if bool(wm[wy2, hx]) or bool(pm[wy2, hx]): continue
                if not bool(em[wy2, hx]): continue
                for ay in [wy2 - 1, wy2 + 1]:
                    if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                        return (Tool.WIRE, hx, wy2)
        for sign in [1, -1]:
            for dist in range(1, spine + 1):
                wx2 = hx + sign * dist
                if not ib(wx2, hy): continue
                if bool(wm[hy, wx2]) or bool(pm[hy, wx2]): continue
                if not bool(em[hy, wx2]): continue
                for ax in [wx2 - 1, wx2 + 1]:
                    if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                        return (Tool.WIRE, wx2, hy)

    # PHASE 5: zone placement with different mix
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 40% RES, 35% COM, 25% IND (more commercial and industrial)
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 6: extend roads into powered empty areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # PHASE 7: civic services
    if pop > 80:
        for fx in range(12, WORLD_W, 18):
            for fy in range(12, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        for px2 in range(15, WORLD_W, 22):
            for py2 in range(15, WORLD_H, 22):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 500:
        for sx in range(20, WORLD_W, 30):
            for sy in range(20, WORLD_H, 30):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(8, 88), (112, 88), (8, 12), (112, 12), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(35, 8), (85, 8), (35, 92), (85, 92)]
        for (ax, ay) in airports:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    # Add nuclear power for high populations
    if pop > 1200 and step % 3 == 0:
        nuclear_spots = [(30, 50), (90, 50), (60, 25), (60, 75),
                         (15, 25), (15, 75), (105, 25), (105, 75),
                         (60, 50), (30, 10), (90, 10), (30, 90), (90, 90)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks to boost land value
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Final fallback: coal near uncovered hood
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + grid of wires + initial roads."""
    actions = []
    # Two coal plants at strategic positions
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines at rows 20, 40, 60, 80
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at cols 30, 60, 90
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads adjacent to wire rows (one row above/below each wire row)
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
            actions.append((Tool.ROAD, x, wy + 2))
    # Vertical roads at cols flanking wire cols
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, wx - 2, y))
            actions.append((Tool.ROAD, wx + 2, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 60, 80]
    wire_cols = [30, 60, 90]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Balanced mix: aim for ~35% res, ~35% com, ~30% ind
        if pop < 100:
            # Early: need industry + some commercial to generate demand
            if ir < 0.35:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 500:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if ir < 0.30:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        elif pop < 2000:
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if ir < 0.25:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            # High pop: maximize residential + commercial
            if rr < 0.50:
                return Tool.RESIDENTIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    phase = step % 10

    # Phase 0: Ensure power plants cover quadrants
    if phase == 0:
        plant_targets = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx, ny = px + dx, py + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # Phase 1: Fill horizontal wire rows
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill vertical wire cols
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads flanking wire rows (offset by 2 to avoid overwriting wire)
    if phase == 3:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                               (ry > 0 and bool(rm[ry-1, rx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                        if adj or rx == 1:
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Roads flanking vertical wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                               (rcx > 0 and bool(rm[ry, rcx-1])) or
                               (rcx < WORLD_W-1 and bool(rm[ry, rcx+1])))
                        if adj or ry == 1:
                            return (Tool.ROAD, rcx, ry)

    # Phase 5: Wire unpowered zones reactively
    if phase == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx, ny in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # Phase 6: Road to unroaded zones reactively
    if phase == 6:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx, ny in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # Phase 7: Extend road into powered areas
    if phase == 7:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = rx2 + dx, ry2 + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(near_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # Phase 8: Add mid-row cross streets reactively
    if phase == 8:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            if not (0 < mid_y < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])) or
                           (mid_y > 0 and bool(rm[mid_y-1, rx])) or
                           (mid_y < WORLD_H-1 and bool(rm[mid_y+1, rx])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 9: Extend wire
    if phase == 9:
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            sk2 = (step * 13) % len(wire_xs3)
            for off in range(min(len(wire_xs3), 100)):
                k = (sk2 + off * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = wx2+dx, wy2+dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- CIVIC SERVICES scaled to population ----
    if pop > 20:
        fire_spots = [
            (5,5),(30,5),(60,5),(90,5),(115,5),
            (5,25),(115,25),(5,50),(115,50),
            (5,75),(115,75),(5,95),(30,95),(60,95),(90,95),(115,95),
            (35,50),(65,50),(20,30),(80,30),(20,70),(80,70),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (15,15),(45,15),(75,15),(105,15),
            (15,35),(45,35),(75,35),(105,35),
            (15,55),(45,55),(75,55),(105,55),
            (15,75),(45,75),(75,75),(105,75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [(25,20),(65,20),(105,20),(25,70),(65,70),(105,70),(45,50),(85,50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        # Switch to nuclear for more power coverage
        nuke_spots = [
            (10,50),(50,50),(110,50),
            (30,10),(90,10),(30,90),(90,90),
            (60,10),(60,90),(10,25),(110,25),(10,75),(110,75),
        ]
        for nx, ny in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1000:
        seaports = [(5,95),(115,95),(5,5),(115,5),(60,95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value reactively
    if pop > 60 and step % 5 == 2:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            px, py = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py, px]):
                return (Tool.PARK, px, py)

    # ---- ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Protect wire spine corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            lo, hi = max(0, wr-1), min(WORLD_H, wr+2)
            cand_mask[lo:hi, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            lo, hi = max(0, wc-1), min(WORLD_W, wc+2)
            cand_mask[:, lo:hi] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active expansion centers adapt to population growth
        if pop < 150:
            # Start near center
            active_centers = [
                (60, 50), (45, 50), (75, 50), (60, 30), (60, 70),
                (30, 30), (90, 30), (30, 70), (90, 70),
            ]
        elif pop < 500:
            # Expand to fill grid sections
            active_centers = []
            for row in range(5):
                for col in range(6):
                    cx = 15 + col * 18
                    cy = 12 + row * 18
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 8 + col * 13
                    cy = 8 + row * 13
                    active_centers.append((cx, cy))
        else:
            # Dense coverage
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary starting offset by step+pop so it's genuinely reactive
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % max(len(road_xs), 1)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(near_power[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % max(len(wire_xs3), 1)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2+dx, wy2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

