def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    # Two cluster centers
    cx1, cy1 = 55, 45
    cx2, cy2 = 75, 55

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Adaptive radius based on population
    if pop < 300:
        max_radius = 22
    elif pop < 1000:
        max_radius = 38
    elif pop < 3000:
        max_radius = 55
    else:
        max_radius = 70

    # Neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    ys_arr = np.arange(WORLD_H).reshape(-1, 1)
    xs_arr = np.arange(WORLD_W).reshape(1, -1)
    # Distance from nearest cluster center
    dist_c1 = np.abs(ys_arr - cy1) + np.abs(xs_arr - cx1)
    dist_c2 = np.abs(ys_arr - cy2) + np.abs(xs_arr - cx2)
    dist_arr = np.minimum(dist_c1, dist_c2)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    plant_count = int(np.sum(pm))

    # === PHASE 1: Add more power plants as city grows ===
    if pop > 500 and plant_count < 3:
        for px, py in [(40, 55), (90, 45), (65, 35), (65, 65)]:
            if ib(px, py) and bool(em[py, px]):
                clear = all(
                    ib(px+dx, py+dy) and bool(em[py+dy, px+dx])
                    for dx in range(-1,2) for dy in range(-1,2)
                )
                if clear:
                    return (Tool.COALPOWER, px, py)

    if pop > 1500 and plant_count < 4:
        for px, py in [(35, 40), (95, 60), (35, 60), (95, 40)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    if pop > 3000 and plant_count < 6:
        for px, py in [(20, 35), (100, 65), (20, 65), (100, 35), (65, 25), (65, 75)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    # === PHASE 2: Wire extension ===
    if step % 4 == 0:
        wire_ys, wire_xs = np.where((wm | pm) & (dist_arr <= max_radius + 12))
        if len(wire_xs) > 0:
            best = None
            best_score = -1
            sk = (step * 7) % len(wire_xs)
            for i in range(min(len(wire_xs), 80)):
                k = (sk + i) % len(wire_xs)
                wx, wy = int(wire_xs[k]), int(wire_ys[k])
                for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx, ny = wx+dx, wy+dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        d = int(dist_arr[ny, nx])
                        if d <= max_radius + 15:
                            # Score: prefer tiles near roads
                            score = int(nbr_road[ny, nx]) * 10 - d
                            if score > best_score:
                                best_score = score
                                best = (Tool.WIRE, nx, ny)
            if best:
                return best

    # === PHASE 3: Road grid - denser grid ===
    if step % 4 == 1:
        # Horizontal roads every 4 rows
        for ry in range(30, 72, 4):
            if dist_arr[ry, 65] > max_radius + 5:
                continue
            x_lo = max(2, 65 - max_radius)
            x_hi = min(WORLD_W - 2, 65 + max_radius)
            for rx in range(x_lo, x_hi):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    adj = ((ib(rx-1,ry) and bool(rm[ry,rx-1])) or
                           (ib(rx+1,ry) and bool(rm[ry,rx+1])))
                    if adj and bool(nbr_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif step % 4 == 2:
        # Vertical roads every 5 cols
        for rxc in range(35, 90, 5):
            if dist_arr[50, rxc] > max_radius + 5:
                continue
            y_lo = max(2, 50 - max_radius)
            y_hi = min(WORLD_H - 2, 50 + max_radius)
            for ry in range(y_lo, y_hi):
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    adj = ((ib(rxc,ry-1) and bool(rm[ry-1,rxc])) or
                           (ib(rxc,ry+1) and bool(rm[ry+1,rxc])))
                    if adj and bool(nbr_power[ry, rxc]):
                        return (Tool.ROAD, rxc, ry)

    # === ZONE TYPE SELECTION: target 40% RES, 35% COM, 25% IND ===
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Bootstrap industry first for demand
        if pop < 200 and ir < 0.30:
            return Tool.INDUSTRIAL
        if pop < 500 and ir < 0.25:
            return Tool.INDUSTRIAL
        # Balance toward targets
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === PHASE 4: Zone placement ===
    cand_mask = em & nbr_road & nbr_power & (dist_arr <= max_radius)
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        dists = dist_arr[cys_arr, cxs_arr]
        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 3) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === CIVIC SERVICES ===
    if pop > 150:
        for sx, sy in [(45, 38), (85, 38), (45, 62), (85, 62), (65, 30), (65, 70)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        for sx, sy in [(50, 44), (80, 44), (50, 56), (80, 56), (65, 38), (65, 62)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        for sx, sy in [(55, 40), (75, 40), (55, 60), (75, 60)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for sx, sy in [(30, 30), (100, 30), (30, 70), (100, 70)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        for sx, sy in [(15, 50), (105, 50), (65, 15), (65, 85)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 300 and step % 7 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power & (dist_arr <= max_radius))
        if len(park_xs) > 0:
            idx = (step * 11) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # === FALLBACKS ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 80)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            if int(dist_arr[ry2, rx2]) > max_radius + 5:
                continue
            for dx, dy in [(0,1),(1,0),(0,-1),(-1,0)]:
                nx, ny = rx2+dx, ry2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if bool(nbr_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    wire_ys2, wire_xs2 = np.where(wm | pm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 80)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx2+dx, wy2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if int(dist_arr[ny, nx]) <= max_radius + 18:
                        return (Tool.WIRE, nx, ny)

    # Emergency coal if no power at center
    if not bool(nbr_power[50, 65]):
        for r in range(1, 12):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = 65+dx, 50+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

