    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 60, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 300:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1500:
            if ir < 0.22:
                return Tool.INDUSTRIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.40:
                return Tool.COMMERCIAL
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # 1. Fix unpowered zones - wire toward nearest power source
    if step % 5 == 0:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 60)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # 2. Fix zones without road access
    if step % 5 == 1:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 3. Repair missing wire on key rows
    if step % 5 == 2:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]) if wx > 0 else False
                    right = bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]) if wx < WORLD_W - 1 else False
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)
        # Also repair vertical wire on key cols
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = bool(wm[wy2 - 1, wc]) or bool(pm[wy2 - 1, wc]) if wy2 > 0 else False
                    dn = bool(wm[wy2 + 1, wc]) or bool(pm[wy2 + 1, wc]) if wy2 < WORLD_H - 1 else False
                    if up or dn:
                        if bool(em[wy2, wc]):
                            return (Tool.WIRE, wc, wy2)

    # 4. Power plant placement - ensure coverage across grid
    if step % 5 == 3:
        # Check each block between wire rows/cols for a plant
        all_band_xs = [0] + wire_cols + [WORLD_W]
        all_band_ys = [0] + wire_rows + [WORLD_H]
        for bi in range(len(all_band_ys) - 1):
            for bj in range(len(all_band_xs) - 1):
                y0, y1 = all_band_ys[bi], all_band_ys[bi + 1]
                x0, x1 = all_band_xs[bj], all_band_xs[bj + 1]
                block_h = y1 - y0
                block_w = x1 - x0
                # Only add plant if block is large enough and has zones
                if block_h < 8 or block_w < 8:
                    continue
                has_plant = bool(np.any(pm[y0:y1, x0:x1]))
                has_zones = bool(np.any(zone_tiles[y0:y1, x0:x1]))
                if not has_plant and has_zones:
                    # Place plant near center of block
                    cx = (x0 + x1) // 2
                    cy = (y0 + y1) // 2
                    for r in range(0, 8):
                        placed = False
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = cx + dx, cy + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        tool_c = Tool.NUCLEARPOWER if pop > 800 else Tool.COALPOWER
                                        return (tool_c, nx2, ny2)
                        if placed:
                            break

    # 5. Repair roads flanking wire rows/cols
    if step % 5 == 4:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        adj = (rx > 0 and bool(rm[ry, rx - 1])) or \
                              (rx < WORLD_W - 1 and bool(rm[ry, rx + 1])) or \
                              (ry > 0 and bool(rm[ry - 1, rx])) or \
                              (ry < WORLD_H - 1 and bool(rm[ry + 1, rx]))
                        if adj or rx == 1:
                            return (Tool.ROAD, rx, ry)
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        adj = (ry > 0 and bool(rm[ry - 1, rcx])) or \
                              (ry < WORLD_H - 1 and bool(rm[ry + 1, rcx])) or \
                              bool(rm[ry, max(0, rcx - 1)]) or \
                              bool(rm[ry, min(WORLD_W - 1, rcx + 1)])
                        if adj or ry == 1:
                            return (Tool.ROAD, rcx, ry)

    # === CIVIC SERVICES (pop-gated) ===
    if pop > 15:
        fire_spots = [
            (10, 10), (50, 10), (90, 10), (110, 10),
            (10, 35), (110, 35), (10, 55), (110, 55),
            (10, 90), (50, 90), (90, 90), (110, 90),
            (50, 50), (70, 50), (30, 50), (90, 50),
            (30, 25), (70, 25), (30, 75), (70, 75),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (25, 15), (65, 15), (105, 15),
            (25, 35), (65, 35), (105, 35),
            (25, 55), (65, 55), (105, 55),
            (25, 75), (65, 75), (105, 75),
            (25, 92), (65, 92), (105, 92),
            (10, 50), (45, 28), (85, 28), (45, 72), (85, 72),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 250:
        stadium_spots = [
            (15, 12), (75, 12), (15, 88), (75, 88),
            (45, 50), (5, 50), (110, 50), (45, 10), (45, 90),
            (30, 30), (70, 30), (30, 70), (70, 70),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5, 48), (113, 48), (58, 3), (58, 95),
            (12, 18), (104, 18), (12, 78), (104, 78),
            (38, 10), (78, 10), (38, 88), (78, 88),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 95), (113, 95), (5, 5), (113, 5), (58, 95), (58, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(48, 5), (68, 5), (48, 90), (68, 90), (5, 44), (113, 44)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 50 and step % 7 == 3:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === ZONE PLACEMENT: dense, reactive ===
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Avoid wire rows/cols themselves
    for wr in wire_rows:
        for off in range(-1, 2):
            if 0 <= wr + off < WORLD_H:
                cand_mask[wr + off, :] = False
    for wc in wire_cols:
        for off in range(-1, 2):
            if 0 <= wc + off < WORLD_W:
                cand_mask[:, wc + off] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Build a grid of zone centers in the blocks between wire rows/cols
        active_centers = []
        band_xs = [0] + wire_cols + [WORLD_W]
        band_ys = [0] + wire_rows + [WORLD_H]

        for bi in range(len(band_ys) - 1):
            for bj in range(len(band_xs) - 1):
                y0, y1 = band_ys[bi], band_ys[bi + 1]
                x0, x1 = band_xs[bj], band_xs[bj + 1]
                block_h = y1 - y0
                block_w = x1 - x0
                if block_h < 5 or block_w < 5:
                    continue
                # Place zone centers in a 4x4 grid within the block
                # Offset from boundary to avoid wire adjacency
                margin_y = 2
                margin_x = 2
                inner_h = block_h - 2 * margin_y
                inner_w = block_w - 2 * margin_x
                rows_n = max(1, inner_h // 4)
                cols_n = max(1, inner_w // 4)
                for ri in range(rows_n):
                    for ci in range(cols_n):
                        cy = y0 + margin_y + (ri * inner_h) // max(rows_n, 1) + inner_h // (2 * max(rows_n, 1))
                        cx = x0 + margin_x + (ci * inner_w) // max(cols_n, 1) + inner_w // (2 * max(cols_n, 1))
                        active_centers.append((cx, cy))

        if len(active_centers) == 0:
            # Fallback uniform grid
            for row in range(8):
                for col in range(10):
                    active_centers.append((6 + col * 11, 6 + row * 11))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road adjacent to existing powered road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire cross + flanking roads"""
    actions = []
    # Central coal plant at (60, 50)
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    # Roads flanking vertical wire
    for y in range(1, 99):
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
    # Corner power plants
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 20, 80))
    actions.append((Tool.COALPOWER, 100, 80))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 30% ind, 30% com, 40% res
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # ---- CLOSED-LOOP: OBSERVE MAP AND REACT ----

    # 1. Ensure power plant coverage: if any 25x25 region has no plant, add one
    # Scan quadrants reactively
    quadrant_size_x = 30
    quadrant_size_y = 25
    for qy in range(0, WORLD_H - 5, quadrant_size_y):
        for qx in range(0, WORLD_W - 5, quadrant_size_x):
            x0 = max(0, qx)
            x1 = min(WORLD_W, qx + quadrant_size_x)
            y0 = max(0, qy)
            y1 = min(WORLD_H, qy + quadrant_size_y)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                cx = (x0 + x1) // 2
                cy = (y0 + y1) // 2
                # Find empty spot near center
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # 2. CLOSED-LOOP wire extension: find frontiers of wire/plant, extend toward unconnected roads
    # Find roads that lack power
    needs_power = rm & ~near_power
    npys, npxs = np.where(needs_power)
    if len(npxs) > 0:
        # Pick a target road without power
        ti = (step * 23 + pop * 7) % len(npxs)
        tx, ty = int(npxs[ti]), int(npys[ti])
        # Find nearest wire or plant
        wire_or_plant = wm | pm
        wop_ys, wop_xs = np.where(wire_or_plant)
        if len(wop_xs) > 0:
            dists = np.abs(wop_xs - tx) + np.abs(wop_ys - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wop_xs[best_wi]), int(wop_ys[best_wi])
            # Step toward target with wire
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            # Try to extend wire one step toward target
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy), (bwx + dx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # 3. CLOSED-LOOP road extension: find wire frontier, extend roads along it
    # Find empty tiles adjacent to wire that don't have roads
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0 and step % 3 != 0:  # alternate with zone placement
        # Find spots near wire but lacking roads
        needs_road = (near_power) & (~near_road) & em
        needs_road[0:3, :] = False
        needs_road[WORLD_H-3:, :] = False
        needs_road[:, 0:3] = False
        needs_road[:, WORLD_W-3:] = False
        nrys, nrxs = np.where(needs_road)
        if len(nrxs) > 0:
            ti = (step * 17 + pop * 5) % len(nrxs)
            tx, ty = int(nrxs[ti]), int(nrys[ti])
            # Find nearest road
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 4. CLOSED-LOOP zone placement
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        road_near = dilate(rm, 1)

        # Score candidates: prefer near existing zones and roads
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            s = 0.0
            if bool(zone_near[y, x]):
                s += 2.0
            if bool(road_near[y, x]):
                s += 1.0
            # Prefer interior of map
            dist_edge = min(x, WORLD_W - 1 - x, y, WORLD_H - 1 - y)
            s += dist_edge * 0.01
            scores[i] = s

        order = np.argsort(-scores)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # 5. CIVIC SERVICES (reactive to population)
    if pop > 40:
        # Fire stations: reactively place where empty and near road+power
        fire_grid = []
        for fy in range(10, WORLD_H - 10, 20):
            for fx in range(10, WORLD_W - 10, 20):
                fire_grid.append((fx, fy))
        for sx, sy in fire_grid:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_grid = []
        for py2 in range(15, WORLD_H - 15, 25):
            for px2 in range(15, WORLD_W - 15, 25):
                police_grid.append((px2, py2))
        for sx, sy in police_grid:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 30), (90, 30), (30, 70), (90, 70),
            (60, 20), (60, 80), (15, 50), (105, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 10), (10, 50), (110, 50), (60, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # 6. Parks to boost land value near populated zones
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power & dilate(zone_tiles, 3)
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # 7. Fallback: extend wire from existing wire toward empty powered-adjacent areas
    wm_ys, wm_xs = np.where(wm)
    if len(wm_xs) > 0:
        step_k2 = (step * 13 + pop) % len(wm_xs)
        for offset in range(min(len(wm_xs), 60)):
            k = (step_k2 + offset * 5) % len(wm_xs)
            wx2, wy2 = int(wm_xs[k]), int(wm_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # 8. Fallback: extend roads near zones
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19 + pop) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 4 coal plants + wire grid + road grid"""
    actions = []
    # Coal plants at key positions
    for px, py in [(30, 30), (90, 30), (30, 70), (90, 70)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [30, 50, 70]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows
    for wy in [30, 50, 70]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
