def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    wire_rows = [30, 50, 70]
    wire_cols = [30, 60, 90]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.32:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.38:
                return Tool.COMMERCIAL
            if rr < 0.42:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- Step 1: Fix unpowered zones ---
    if step % 7 == 0:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 50)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # --- Step 2: Fix zones without road access ---
    if step % 7 == 1:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- Step 3: Repair wire rows ---
    if step % 7 == 2:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]) if wx > 0 else False
                    right = bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]) if wx < WORLD_W - 1 else False
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # --- Step 4: Repair wire cols ---
    if step % 7 == 3:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = bool(wm[wy2 - 1, wc]) or bool(pm[wy2 - 1, wc]) if wy2 > 0 else False
                    dn = bool(wm[wy2 + 1, wc]) or bool(pm[wy2 + 1, wc]) if wy2 < WORLD_H - 1 else False
                    if up or dn:
                        if bool(em[wy2, wc]):
                            return (Tool.WIRE, wc, wy2)

    # --- Step 5: Power plant coverage ---
    if step % 7 == 4:
        plant_targets = []
        for py in range(15, WORLD_H - 5, 25):
            for px in range(15, WORLD_W - 5, 30):
                plant_targets.append((px, py))
        for ppx, ppy in plant_targets:
            x0, x1 = max(0, ppx - 15), min(WORLD_W, ppx + 16)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = ppx + dx, ppy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    tool_choice = Tool.NUCLEARPOWER if pop > 500 else Tool.COALPOWER
                                    return (tool_choice, nx2, ny2)

    # --- Step 6: Repair roads flanking wire rows ---
    if step % 7 == 5:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx - 1])) or \
                                  (rx < WORLD_W - 1 and bool(rm[ry, rx + 1])) or \
                                  (ry > 0 and bool(rm[ry - 1, rx])) or \
                                  (ry < WORLD_H - 1 and bool(rm[ry + 1, rx]))
                            if adj or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    # --- Step 6b: Repair roads flanking wire cols ---
    if step % 7 == 6:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry - 1, rcx])) or \
                                  (ry < WORLD_H - 1 and bool(rm[ry + 1, rcx])) or \
                                  bool(rm[ry, max(0, rcx - 1)]) or \
                                  bool(rm[ry, min(WORLD_W - 1, rcx + 1)])
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # === CIVIC SERVICES (pop-gated) ===
    if pop > 20:
        fire_spots = [
            (10, 10), (40, 10), (70, 10), (100, 10),
            (10, 40), (100, 40), (10, 60), (100, 60),
            (10, 90), (40, 90), (70, 90), (100, 90),
            (40, 50), (70, 50), (55, 25), (55, 75),
            (25, 50), (85, 50), (55, 45), (55, 55),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 45), (55, 45), (85, 45), (115, 45),
            (25, 65), (55, 65), (85, 65), (115, 65),
            (25, 85), (55, 85), (85, 85), (10, 50),
            (45, 25), (75, 25), (45, 75), (75, 75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (20, 15), (80, 15), (20, 85), (80, 85),
            (50, 50), (10, 50), (110, 50), (50, 10), (50, 90),
            (35, 35), (65, 35), (35, 65), (65, 65),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (15, 20), (105, 20), (15, 80), (105, 80),
            (40, 10), (80, 10), (40, 90), (80, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 60 and step % 9 == 4:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === ZONE PLACEMENT ===
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc + 2] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Score candidates: prefer near existing zones (density) and near road
        zone_ys, zone_xs = np.where(zone_tiles)
        road_ys_a, road_xs_a = np.where(rm)

        if pop < 100:
            active_centers = [
                (45, 40), (45, 60), (75, 40), (75, 60),
                (15, 40), (15, 60), (105, 40), (105, 60),
                (45, 15), (75, 15), (45, 85), (75, 85),
            ]
        elif pop < 500:
            active_centers = []
            block_xs = [15, 45, 75, 105]
            block_ys = [15, 40, 60, 85]
            for bx in block_xs:
                for by in block_ys:
                    active_centers.append((bx, by))
            for bx in [5, 22, 38, 52, 68, 82, 98, 112]:
                for by in [20, 40, 60, 80]:
                    active_centers.append((bx, by))
        else:
            active_centers = []
            for row in range(10):
                for col in range(13):
                    cx = 4 + col * 9
                    cy = 4 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Boost density: prefer spots near existing zones
        if len(zone_xs) > 0:
            min_zone_d = np.full(len(cxs), 9999.0)
            stride = max(1, len(zone_xs) // 80)
            for i in range(0, len(zone_xs), stride):
                d = np.abs(cxs - zone_xs[i]).astype(float) + np.abs(cys - zone_ys[i]).astype(float)
                min_zone_d = np.minimum(min_zone_d, d)
            # Penalize being too close (overlap) or too far
            density_bonus = np.where(min_zone_d < 4, 500.0,
                            np.where(min_zone_d > 20, min_zone_d * 0.3, 0.0))
            best_dist = best_dist + density_bonus

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road toward powered area
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 150)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Combined strategy: horizontal spine city with dense zone packing
# Key ideas from Parent B (winner): horizontal spines, multiple plants, early civics
# Key ideas from Parent A: neighborhood grid, broader map coverage

def init(obs, state):
    """Bootstrap: central coal plant + horizontal wire spine + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Flanking roads
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    # Vertical wire cross
    for dy in range(-4, 5):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Horizontal spines at various y-levels
    spine_ys = [15, 28, 42, 56, 70, 83]
    spine_x_start = 5
    spine_x_end = 114

    # Power plant target x positions per spine
    plant_xs = [18, 40, 62, 84, 106]

    def num_active_spines():
        if pop < 30:    return 1
        if pop < 150:   return 2
        if pop < 400:   return 3
        if pop < 900:   return 4
        if pop < 2000:  return 5
        return len(spine_ys)

    n_spines = min(num_active_spines(), len(spine_ys))
    active_spines = spine_ys[:n_spines]

    # ---- PHASE 1: ENSURE POWER PLANTS on each active spine ----
    for spine_y in active_spines:
        y0, y1 = max(0, spine_y - 6), min(WORLD_H, spine_y + 7)
        # Check for plants near each plant_x
        for px in plant_xs:
            x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = px + dx, spine_y + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (horizontal) ----
    for si, spine_y in enumerate(active_spines):
        if step % max(n_spines, 1) != si % max(n_spines, 1):
            continue
        for wx in range(spine_x_start, spine_x_end + 1):
            if not ib(wx, spine_y):
                continue
            if bool(wm[spine_y, wx]) or bool(pm[spine_y, wx]):
                continue
            if not bool(em[spine_y, wx]):
                continue
            # Place wire if adjacent to existing wire or plant
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, spine_y) and (bool(wm[spine_y, ax]) or bool(pm[spine_y, ax])):
                    return (Tool.WIRE, wx, spine_y)

    # ---- PHASE 3: VERTICAL WIRE CONNECTORS between adjacent spines ----
    connector_xs = list(range(10, WORLD_W, 12))
    for si in range(len(active_spines) - 1):
        y1s, y2s = active_spines[si], active_spines[si + 1]
        for cx in connector_xs:
            if not ib(cx, y1s):
                continue
            for wy in range(y1s + 1, y2s):
                if not ib(cx, wy):
                    continue
                if bool(wm[wy, cx]) or bool(pm[wy, cx]):
                    continue
                if not bool(em[wy, cx]):
                    continue
                for adj in [-1, 1]:
                    ay = wy + adj
                    if ib(cx, ay) and (bool(wm[ay, cx]) or bool(pm[ay, cx])):
                        return (Tool.WIRE, cx, wy)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for si, spine_y in enumerate(active_spines):
        if (step + si) % max(n_spines // 2 + 1, 1) != 0:
            continue
        for road_y in [spine_y - 1, spine_y + 1]:
            if not ib(0, road_y):
                continue
            for rx in range(spine_x_start, spine_x_end + 1):
                if not ib(rx, road_y):
                    continue
                if bool(rm[road_y, rx]) or bool(pm[road_y, rx]):
                    continue
                if not bool(em[road_y, rx]):
                    continue
                if bool(wm[spine_y, rx]) or bool(pm[spine_y, rx]):
                    return (Tool.ROAD, rx, road_y)

    # ---- PHASE 5: CROSS ROADS (vertical connectors) ----
    for cx in connector_xs:
        for si in range(len(active_spines) - 1):
            y1s, y2s = active_spines[si], active_spines[si + 1]
            for ry in range(y1s + 2, y2s - 1):
                if not ib(cx, ry):
                    continue
                if bool(rm[ry, cx]) or bool(pm[ry, cx]):
                    continue
                if not bool(em[ry, cx]):
                    continue
                for adj in [-1, 1]:
                    ay = ry + adj
                    if ib(cx, ay) and bool(rm[ay, cx]):
                        return (Tool.ROAD, cx, ry)

    # ---- COMPUTE NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 35% RES, 35% IND, 30% COM
        if ir < 0.33:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: closest to any active spine
        best_dist = np.full(len(cxs), 999999.0)
        for sy in active_spines:
            d = np.abs(cys - sy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (early placement) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 20) for fy in range(15, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W, 25) for py2 in range(20, WORLD_H, 25)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [
            (25, 22), (60, 22), (95, 22),
            (25, 52), (60, 52), (95, 52),
            (25, 82), (60, 82), (95, 82),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 96), (60, 4)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(40, 5), (80, 5), (40, 93), (80, 93), (5, 40), (5, 60), (113, 40), (113, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high pop ----
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [
            (60, 50), (25, 22), (95, 22), (25, 82), (95, 82),
            (10, 50), (110, 50), (60, 8), (60, 92),
            (40, 37), (80, 37), (40, 67), (80, 67)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 200 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant near uncovered spine ----
    for spine_y in active_spines:
        if not bool(nbr_power[spine_y, 60]):
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = 60 + dx, spine_y + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: place a central coal plant + wire spine + initial road cross"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire horizontally from plant
    for x in range(61, 75):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically from plant
    for y in range(40, 50):
        actions.append((Tool.WIRE, 60, y))
    # Initial road grid seeds
    actions.append((Tool.ROAD, 60, 44))
    actions.append((Tool.ROAD, 60, 45))
    actions.append((Tool.ROAD, 65, 44))
    actions.append((Tool.ROAD, 55, 44))
    return actions[:20]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- State tracking ---
    if 'phase' not in state:
        state['phase'] = 0
        state['wire_target'] = None
        state['road_frontier'] = []

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        # Keep good balance: 30% ind, 25% com, rest res
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE A: Ensure enough power plants ---
    # Plant grid: place plants every 20 tiles in a grid
    plant_grid = []
    for py in range(20, 85, 20):
        for px in range(20, 105, 20):
            plant_grid.append((px, py))

    # Check how many plants exist; add more proactively
    plant_count = int(np.sum(pm))
    zones_per_plant = max(total_zones / max(plant_count, 1), 0)
    need_more_plants = (plant_count == 0) or (zones_per_plant > 30)

    if need_more_plants:
        for px, py in plant_grid:
            if not ib(px, py):
                continue
            x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
            y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)

    # --- PHASE B: Wire from existing power toward unpowered plants ---
    # Find all plant locations
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        # Find plants not yet in the power network (not near existing wire/plant network)
        for i in range(len(pwr_xs)):
            ppx, ppy = int(pwr_xs[i]), int(pwr_ys[i])
            # Check if this plant is isolated (no wire within 5 tiles)
            x0, x1 = max(0, ppx - 5), min(WORLD_W, ppx + 6)
            y0, y1 = max(0, ppy - 5), min(WORLD_H, ppy + 6)
            local_wire = wm[y0:y1, x0:x1]
            if not np.any(local_wire):
                # Try to place a wire adjacent to this plant
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = ppx + dx, ppy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # --- PHASE C: Extend wire network BFS-style toward unpowered zones ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H - 3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W - 3:] = False

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0:
        # Find unpowered plants to wire toward
        unpowered_plants = []
        for px2, py2 in plant_grid:
            if ib(px2, py2) and np.any(pm[max(0, py2 - 2):min(WORLD_H, py2 + 3),
                                          max(0, px2 - 2):min(WORLD_W, px2 + 3)]):
                if not bool(near_power[py2, px2]):
                    unpowered_plants.append((px2, py2))

        unpowered_zones = zone_tiles & ~near_power
        zys_u, zxs_u = np.where(unpowered_zones)

        targets = list(unpowered_plants)
        if len(zxs_u) > 0:
            stride = max(1, len(zxs_u) // 20)
            for i in range(0, len(zxs_u), stride):
                targets.append((int(zxs_u[i]), int(zys_u[i])))

        if targets:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx2, cy2 = int(wxs[i]), int(wys[i])
                d = min(abs(cx2 - tx) + abs(cy2 - ty) for tx, ty in targets[:30])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE D: Build dense road grid in powered areas ---
    # Road grid every 4 tiles (denser than parent's 6)
    road_rows = list(range(7, 97, 4))
    road_cols = list(range(7, 115, 4))

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_targets = []
    for gy in road_rows:
        for gx in road_cols:
            if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]):
                road_targets.append((gx, gy))

    if road_targets:
        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:3, :] = False
        road_cand[WORLD_H - 3:, :] = False
        road_cand[:, 0:3] = False
        road_cand[:, WORLD_W - 3:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            sample_targets = road_targets[:40]
            for i in range(len(rxs2)):
                cx3, cy3 = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx3 - gx) + abs(cy3 - gy) for gx, gy in sample_targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Direct placement on grid targets adjacent to existing roads
            for gx, gy in road_targets[:15]:
                if bool(em[gy, gx]) and bool(adj_to_road[gy, gx]):
                    return (Tool.ROAD, gx, gy)
            # Or just place at nearest grid target
            for gx, gy in road_targets[:5]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE E: Zone placement with good scoring ---
    def zone_clear(zx, zy):
        """3x3 area must be free of roads, wires, plants"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if rm[nr, nc] or wm[nr, nc] or pm[nr, nc]:
                    return False
        return True

    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H - 5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W - 5:] = False

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs_arr))

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer very close to road, moderate spread from existing zones
            score = road_dist * 2.0 - zone_dist * 0.5
        else:
            score = road_dist

        order = np.argsort(score)
        # Vary placement to spread city
        off = (step * 7 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE F: Civic services ---
    if pop > 200:
        for fy in range(12, 90, 10):
            for fx in range(12, 110, 10):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(near_power[fy, fx]) and bool(near_road[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 400:
        for py2 in range(15, 88, 12):
            for px2 in range(15, 108, 12):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(near_power[py2, px2]) and bool(near_road[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for py3 in range(10, 92, 8):
            for px3 in range(10, 112, 8):
                if ib(px3, py3) and bool(em[py3, px3]) and bool(near_road[py3, px3]):
                    return (Tool.PARK, px3, py3)

    if pop > 900:
        for stx, sty in [(25, 25), (85, 25), (25, 75), (85, 75), (55, 50), (55, 25), (55, 75)]:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75), (40, 50), (80, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 6), min(WORLD_W, nx + 7)
                y0, y1 = max(0, ny - 6), min(WORLD_H, ny + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2500:
        for apx, apy in [(55, 8), (75, 8), (8, 50), (110, 50), (60, 90)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3500:
        for spx, spy in [(10, 50), (110, 50), (60, 8), (60, 91)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend wire from nearest plant ---
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px4, py4 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx4, ny4 = px4 + dx4, py4 + dy4
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.WIRE, nx4, ny4)

    # --- Fallback: place road near plant ---
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px5, py5 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx5, dy5 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
            nx5, ny5 = px5 + dx5, py5 + dy5
            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                return (Tool.ROAD, nx5, ny5)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle + initial wire/road grid"""
    actions = []
    # Central power plants at key positions
    for px, py in [(59, 50), (20, 20), (100, 20), (20, 80), (100, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at 4 levels
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 45, 75, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire spines
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 40% res, 35% com, 25% ind - more commercial than parent
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 60, 80]
    wire_cols = [20, 45, 75, 100]

    # Denser neighborhood grid with tighter spacing
    nh_positions = []
    for row in range(7):
        for col in range(9):
            cx = 8 + col * 12
            cy = 8 + row * 13
            cy = min(cy, 94)
            cx = min(cx, 114)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            # Start near center
            return [(59, 50), (47, 50), (71, 50), (59, 38), (59, 62),
                    (47, 38), (71, 38), (47, 62), (71, 62)]
        elif pop < 500:
            return nh_positions[15:45]
        elif pop < 1500:
            return nh_positions[5:55]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                cell_empty = bool(em[nr, nc])
                cell_zone = bool(zone_tiles[nr, nc])
                if not cell_empty and not cell_zone:
                    return False
        return True

    phase = step % 14

    # Ensure power plants near active hoods
    if step % 6 == 0:
        for (hx, hy) in active_hoods[:6]:
            x0, x1 = max(0, hx - 18), min(WORLD_W, hx + 19)
            y0, y1 = max(0, hy - 18), min(WORLD_H, hy + 19)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(2, 20):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    powered_here = bool(wm[wr, rx]) or bool(pm[wr, rx])
                    if powered_here and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    powered_here = bool(wm[ry, wc]) or bool(pm[ry, wc])
                    if powered_here and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add diagonal cross-streets between wire rows (midpoints)
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire cols at midpoints
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend road from existing road (grow road network)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 9) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Additional road: second ring around active hoods
        if pop > 200:
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                sk = (step * 19) % len(road_xs)
                for off in range(min(len(road_xs), 150)):
                    k = (sk + off * 11) % len(road_xs)
                    rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                    for dx2, dy2 in [(0,2),(0,-2),(2,0),(-2,0),(1,1),(1,-1),(-1,1),(-1,-1)]:
                        nx2, ny2 = rx2+dx2, ry2+dy2
                        if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                            return (Tool.ROAD, nx2, ny2)

    elif phase in (9, 10, 11, 12, 13):
        # Civic services scaled with population
        if pop > 15:
            fire_spots = [
                (8,8),(30,8),(55,8),(80,8),(108,8),
                (8,30),(30,30),(55,30),(80,30),(108,30),
                (8,50),(108,50),
                (8,70),(30,70),(55,70),(80,70),(108,70),
                (8,90),(30,90),(55,90),(80,90),(108,90)
            ]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 80:
            police_spots = [
                (20,15),(60,15),(95,15),
                (20,45),(60,45),(95,45),
                (20,65),(60,65),(95,65),
                (20,90),(60,90),(95,90)
            ]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            # Stadiums attract more people
            stadium_spots = [(35,25),(85,25),(35,75),(85,75),(59,50),(20,50),(100,50)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 700:
            nuke_spots = [(5,50),(113,50),(59,5),(59,93),(5,5),(113,5),(5,93),(113,93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            seaports = [(5,93),(113,93),(5,5),(113,5),(59,93)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1800:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(113,43),(5,57),(113,57)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (main closed-loop action) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep away from wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use population and step to vary starting point (closed-loop)
        offset = (step * 11 + pop * 5 + com_count * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks for land value boost
    if pop > 30 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx,bwy),(bwx,bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads for initial zones."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 5)
    near_road = dilate(rm, 3)

    # ---- NEIGHBORHOOD GRID: active hoods scale with population ----
    nh_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    nh_rows = [10, 24, 38, 52, 66, 80, 94]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 2
        if pop < 200:  return 6
        if pop < 500:  return 12
        if pop < 1000: return 20
        if pop < 2000: return 30
        if pop < 4000: return 42
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    # ---- PHASE 1: Ensure each active hood has a power plant nearby ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Extend wire toward uncovered active hoods ----
    uncovered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if uncovered:
        wire_ys, wire_xs = np.where(power_src)
        if len(wire_xs) > 0:
            for (tx, ty) in uncovered:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
                dx = 1 if tx > wx else (-1 if tx < wx else 0)
                dy = 1 if ty > wy else (-1 if ty < wy else 0)
                for ddx, ddy in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: Build wire grid - horizontal spines at hood rows ----
    hood_cycle = step % max(len(active_hoods), 1)
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Horizontal wire spine at hy
        row_wp = wm[hy, :] | pm[hy, :]
        if row_wp.any():
            idxs = np.where(row_wp)[0]
            left = int(idxs[0])
            right = int(idxs[-1])
            if left > 2 and bool(em[hy, left - 1]) and not bool(pm[hy, left - 1]):
                return (Tool.WIRE, left - 1, hy)
            if right < WORLD_W - 3 and bool(em[hy, right + 1]) and not bool(pm[hy, right + 1]):
                return (Tool.WIRE, right + 1, hy)
        # Vertical wire spine at hx
        col_wp = wm[:, hx] | pm[:, hx]
        if col_wp.any():
            idxs = np.where(col_wp)[0]
            top = int(idxs[0])
            bot = int(idxs[-1])
            if top > 2 and bool(em[top - 1, hx]) and not bool(pm[top - 1, hx]):
                return (Tool.WIRE, hx, top - 1)
            if bot < WORLD_H - 3 and bool(em[bot + 1, hx]) and not bool(pm[bot + 1, hx]):
                return (Tool.WIRE, hx, bot + 1)

    # ---- PHASE 4: Roads flanking wire spines ----
    for idx_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_cycle + idx_h) % len(active_hoods)]
        # Roads at hx-2, hx+2 (flanking vertical wire at hx)
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy): continue
            # Extend road vertically along this column
            col_rd = rm[:, rx]
            if col_rd.any():
                idxs = np.where(col_rd)[0]
                top = int(idxs[0]); bot = int(idxs[-1])
                if top > 2 and bool(em[top - 1, rx]) and not bool(pm[top - 1, rx]) and bool(near_power[top - 1, rx]):
                    return (Tool.ROAD, rx, top - 1)
                if bot < WORLD_H - 3 and bool(em[bot + 1, rx]) and not bool(pm[bot + 1, rx]) and bool(near_power[bot + 1, rx]):
                    return (Tool.ROAD, rx, bot + 1)
            elif bool(near_power[hy, rx]) and bool(em[hy, rx]) and not bool(pm[hy, rx]):
                return (Tool.ROAD, rx, hy)
        # Roads at hy-2, hy+2 (flanking horizontal wire at hy)
        for ry in [hy - 2, hy + 2]:
            if not ib(hx, ry): continue
            row_rd = rm[ry, :]
            if row_rd.any():
                idxs = np.where(row_rd)[0]
                left = int(idxs[0]); right = int(idxs[-1])
                if left > 2 and bool(em[ry, left - 1]) and not bool(pm[ry, left - 1]) and bool(near_power[ry, left - 1]):
                    return (Tool.ROAD, left - 1, ry)
                if right < WORLD_W - 3 and bool(em[ry, right + 1]) and not bool(pm[ry, right + 1]) and bool(near_power[ry, right + 1]):
                    return (Tool.ROAD, right + 1, ry)
            elif bool(near_power[ry, hx]) and bool(em[ry, hx]) and not bool(pm[ry, hx]):
                return (Tool.ROAD, hx, ry)

    # ---- PHASE 5: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:3, :] = False
    zone_cand[WORLD_H - 3:, :] = False
    zone_cand[:, 0:3] = False
    zone_cand[:, WORLD_W - 3:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]): return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        # Also score by road proximity
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
            score = best_dist * 0.5 + road_dist * 0.5
        else:
            score = best_dist
        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: Extend roads into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: Civic services ----
    if pop > 80:
        for fx in range(12, WORLD_W, 20):
            for fy in range(12, WORLD_H, 20):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for px2 in range(16, WORLD_W, 24):
            for py2 in range(16, WORLD_H, 24):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 150 and step % 3 == 0:
        park_ys, park_xs = np.where(em & near_road & near_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 600:
        for sx in range(25, WORLD_W, 30):
            for sy in range(25, WORLD_H, 30):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        airport_spots = [(40, 6), (80, 6), (40, 93), (80, 93), (6, 44), (113, 44)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_spots = [(8, 85), (112, 85), (8, 15), (112, 15), (60, 95), (60, 5)]
        for sx, sy in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000 and step % 5 == 0:
        nuclear_spots = [(30, 20), (90, 20), (30, 80), (90, 80), (60, 10), (60, 90)]
        for nx2, ny2 in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- FALLBACK: Extend wire adjacent to existing power ----
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted
    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False; wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False; wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)
    if len(wxs_c) > 0:
        # Prefer wire toward uncovered active hoods
        uncov2 = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
        if uncov2:
            best_d = 1e9; best_k = 0
            for i in range(len(wxs_c)):
                cx2, cy2 = int(wxs_c[i]), int(wys_c[i])
                d = min(abs(cx2 - hx) + abs(cy2 - hy) for hx, hy in uncov2)
                if d < best_d:
                    best_d = d; best_k = i
            return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
        else:
            k = step % len(wxs_c)
            return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- FALLBACK: new coal plant near uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants connected by wires, with roads on both sides."""
    actions = []
    # Plant 1 at (40, 50)
    actions.append((Tool.COALPOWER, 40, 50))
    # Plant 2 at (80, 50)
    actions.append((Tool.COALPOWER, 80, 50))
    # Horizontal wire connecting both plants
    for x in range(38, 83):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for dy in range(-6, 7):
        actions.append((Tool.WIRE, 40, 50 + dy))
        actions.append((Tool.WIRE, 80, 50 + dy))
    # Roads flanking wire spines
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, 39, 50 + dy))
        actions.append((Tool.ROAD, 41, 50 + dy))
        actions.append((Tool.ROAD, 79, 50 + dy))
        actions.append((Tool.ROAD, 81, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    # Define 6 neighborhoods in a 3x2 grid pattern
    # Each: (center_x, center_y, wire_col, road_left, road_right)
    neighborhood_configs = [
        (30, 25, 30, 29, 31, 0),
        (60, 25, 60, 59, 61, 1),
        (90, 25, 90, 89, 91, 2),
        (30, 75, 30, 29, 31, 3),
        (60, 75, 60, 59, 61, 4),
        (90, 75, 90, 89, 91, 5),
    ]

    def num_active():
        if pop < 100:  return 1
        if pop < 300:  return 2
        if pop < 600:  return 3
        if pop < 1000: return 4
        if pop < 1800: return 5
        return 6

    active = neighborhood_configs[:num_active()]

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- 1. ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr, idx) in active:
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Place plant
        for r in range(0, 10):
            placed = False
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)
            if placed:
                break

    # ---- 2. BUILD VERTICAL WIRE SPINES ----
    pop_ext = min(25, pop // 40)
    for (px, py, wc, rl, rr, idx) in active:
        spine_top = max(2, py - 20 - pop_ext)
        spine_bot = min(WORLD_H - 3, py + 20 + pop_ext)
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            for dy in range(-6, 7):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE CONNECTIONS between neighborhoods in same row ----
    row_groups = {}
    for (px, py, wc, rl, rr, idx) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append((wc, py))
    for row_y, wc_list in row_groups.items():
        if len(wc_list) < 2:
            continue
        wcs_sorted = sorted([w for w, _ in wc_list])
        for i in range(len(wcs_sorted) - 1):
            wc1, wc2 = wcs_sorted[i], wcs_sorted[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- 4. VERTICAL WIRE CONNECTIONS between top/bottom neighborhoods ----
    col_groups = {}
    for (px, py, wc, rl, rr, idx) in active:
        if wc not in col_groups:
            col_groups[wc] = []
        col_groups[wc].append(py)
    for wc_x, pys in col_groups.items():
        if len(pys) < 2:
            continue
        pys_sorted = sorted(pys)
        for i in range(len(pys_sorted) - 1):
            py1, py2 = pys_sorted[i], pys_sorted[i + 1]
            for cy in range(py1 + 1, py2):
                if ib(wc_x, cy) and bool(em[cy, wc_x]) and not bool(pm[cy, wc_x]):
                    return (Tool.WIRE, wc_x, cy)

    # ---- 5. BUILD ROADS flanking wire spines ----
    for (px, py, wc, rl, rr, idx) in active:
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = (step + idx * 11) % max(len(wire_rows), 1)
        for offset in range(min(len(wire_rows), 15)):
            wr = wire_rows[(cycle + offset) % len(wire_rows)]
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 6. HORIZONTAL ROADS near wire spines ----
    for (px, py, wc, rl, rr, idx) in active:
        for dx in range(-10, 11):
            rx = wc + dx
            if ib(rx, py) and bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near_w = any(
                    ib(rx + d, py) and (bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near_w:
                    return (Tool.ROAD, rx, py)

    # ---- 7. ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 20% industrial, 25% commercial, 55% residential
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(wm | pm, 6)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr, idx) in active:
            d = np.abs(cxs.astype(float) - wc) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)

        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            stride = max(1, len(road_xs_arr) // 100)
            road_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(road_xs_arr), stride):
                d = (np.abs(cxs - road_xs_arr[i]) + np.abs(cys - road_ys_arr[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs), 5.0)

        score = best_dist * 0.7 + road_dist * 1.8
        order = np.argsort(score)
        step_off = (step * 13) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- 8. EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- 9. CIVIC SERVICES ----
    if pop > 200:
        firestations = [
            (25, 25), (55, 25), (85, 25),
            (25, 75), (55, 75), (85, 75),
            (25, 50), (95, 50),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        polices = [
            (40, 30), (70, 30), (40, 70), (70, 70),
            (15, 50), (105, 50), (60, 15), (60, 85),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [
            (50, 10), (70, 10), (50, 90), (70, 90),
            (10, 40), (110, 40), (10, 60), (110, 60),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Nuclear plants in corners/edges away from coal plants
        nuke_locs = [(15, 15), (105, 15), (15, 85), (105, 85),
                     (60, 5), (60, 95), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5, 85), (115, 85), (5, 15), (115, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airport_locs = [(5, 5), (100, 5), (5, 88), (100, 88)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- 10. FALLBACK: extend wire ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 17) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 50)):
            k = (step_k2 + offset * 7) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- 11. FALLBACK: road near power plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, 2), (2, -2), (-2, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire backbone + initial roads"""
    actions = []
    # Central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines at y=20, 50, 80
    for wy in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at x=30, 60, 90
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for wy in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    # Roads flanking vertical wire spines
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            if y not in [20, 50, 80]:  # don't overwrite horizontal roads
                actions.append((Tool.ROAD, wx - 1, y))
                actions.append((Tool.ROAD, wx + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Infrastructure layout
    wire_rows = [20, 50, 80]
    wire_cols = [30, 60, 90]
    # Secondary road corridors between wire spines
    road_rows = [10, 30, 40, 60, 70, 90]
    road_cols = [15, 45, 75, 105]

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.20:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Phase rotation for infrastructure maintenance
    phase = step % 8

    # --- PHASE 0: Repair horizontal wire spines ---
    if phase == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    if bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # --- PHASE 1: Repair vertical wire spines ---
    if phase == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    if bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # --- PHASE 2: Repair roads flanking wire rows ---
    if phase == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # --- PHASE 3: Add secondary road corridors ---
    if phase == 3:
        for rr_y in road_rows:
            if not (0 < rr_y < WORLD_H):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr_y, rx]) and not bool(pm[rr_y, rx]):
                    # Only place if near power
                    if bool(near_power[rr_y, rx]):
                        return (Tool.ROAD, rx, rr_y)
        # Vertical secondary roads
        for rc_x in road_cols:
            if not (0 < rc_x < WORLD_W):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc_x]) and not bool(pm[ry, rc_x]):
                    if bool(near_power[ry, rc_x]):
                        return (Tool.ROAD, rc_x, ry)

    # --- PHASE 4: Add coal plants where coverage is thin ---
    if phase == 4:
        # Grid of target positions
        for py in range(15, WORLD_H - 5, 25):
            for px in range(15, WORLD_W - 5, 25):
                x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
                y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    # Place plant at or near target
                    for r in range(0, 8):
                        placed = False
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)
                        if placed:
                            break

    # --- PHASE 5: Wire unpowered zones toward grid ---
    if phase == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- PHASE 6: Road to unroaded zones ---
    if phase == 6:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES ---
    if pop > 20:
        fire_spots = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 35), (45, 35), (75, 35), (105, 35),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 45), (55, 45), (85, 45), (115, 45),
            (25, 65), (55, 65), (85, 65), (115, 65),
            (10, 30), (10, 70), (110, 30), (110, 70),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (10, 50), (110, 50), (60, 10), (60, 90),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- ZONE PLACEMENT ---
    # Candidate cells: empty, near road, near power, away from edges/infra
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Protect infrastructure corridors
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):min(WORLD_H, wr + 2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):min(WORLD_W, wc + 2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Build active zone centers based on pop
        if pop < 150:
            active_centers = [
                (60, 50), (45, 50), (75, 50), (60, 38), (60, 62),
                (45, 38), (75, 38), (45, 62), (75, 62),
                (30, 50), (90, 50),
            ]
        elif pop < 800:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 8 + col * 15
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(9):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire grid + road grid in central region"""
    actions = []
    # Two coal plants centrally placed
    for px, py in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [35, 50, 65]:
        for x in range(5, 115):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [30, 60, 90]:
        for y in range(5, 95):
            actions.append((Tool.WIRE, wx, y))
    # Roads along key corridors
    for wy in [35, 50, 65]:
        for x in range(5, 115):
            actions.append((Tool.ROAD, x, wy - 3))
            actions.append((Tool.ROAD, x, wy + 3))
    for wx in [30, 60, 90]:
        for y in range(5, 95):
            actions.append((Tool.ROAD, wx - 3, y))
            actions.append((Tool.ROAD, wx + 3, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    wire_rows = [35, 50, 65]
    wire_cols = [30, 60, 90]

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        # Maintain a balanced mix: more residential, some commercial, some industrial
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            # Early game: need industry + some residential to bootstrap
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 500:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 2000:
            if cr < 0.40:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.15:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            # Large city: mostly residential + commercial
            if cr < 0.38:
                return Tool.COMMERCIAL
            if rr < 0.50:
                return Tool.RESIDENTIAL
            return Tool.COMMERCIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- STEP 1: Repair horizontal wire spines ---
    if step % 6 == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    if bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # --- STEP 2: Repair vertical wire spines ---
    if step % 6 == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    if bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # --- STEP 3: Connect unpowered zones ---
    if step % 6 == 2:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 13) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- STEP 4: Connect unroaded zones ---
    if step % 6 == 3:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- STEP 5: Expand power plants reactively ---
    if step % 6 == 4:
        # Add more plants as needed in quadrants
        plant_targets = []
        for py in range(10, WORLD_H - 5, 20):
            for px in range(10, WORLD_W - 5, 25):
                plant_targets.append((px, py))
        for ppx, ppy in plant_targets:
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 10), min(WORLD_H, ppy + 11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            has_zones = bool(np.any(zone_tiles[y0:y1, x0:x1]))
            if not has_plant and has_zones:
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = ppx + dx, ppy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    tool_c = Tool.NUCLEARPOWER if pop > 300 else Tool.COALPOWER
                                    return (tool_c, nx2, ny2)

    # --- STEP 6: Repair road flanks ---
    if step % 6 == 5:
        for wr in wire_rows:
            for offset in [-3, 3]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                               (ry > 0 and bool(rm[ry-1, rx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                        if adj or rx <= 2:
                            return (Tool.ROAD, rx, ry)

    # --- CIVIC SERVICES: reactive, population-gated ---
    if pop > 20:
        fire_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (15, 75), (45, 75), (75, 75), (105, 75),
            (55, 30), (55, 70), (30, 55), (80, 55),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (20, 20), (55, 20), (85, 20), (110, 20),
            (20, 55), (110, 55), (20, 80), (55, 80),
            (85, 80), (110, 80), (40, 40), (75, 40),
            (40, 70), (75, 70),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (25, 20), (85, 20), (25, 78), (85, 78),
            (55, 50), (15, 50), (105, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (15, 25), (105, 25), (15, 75), (105, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 9 == 7:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 29 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- ZONE PLACEMENT: dense grid approach, closed-loop ---
    cand_mask = em & near_road & near_power
    # Exclude borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire spines
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Use different cluster centers than parent - fill all quadrants evenly
        if pop < 200:
            # Start in center quadrants
            active_centers = [
                (45, 42), (45, 57), (75, 42), (75, 57),
                (15, 42), (15, 57), (105, 42), (105, 57),
                (45, 20), (75, 20), (45, 78), (75, 78),
            ]
        elif pop < 800:
            # Expand to fill more of the map
            active_centers = []
            for bx in range(8, WORLD_W - 5, 10):
                for by in range(8, WORLD_H - 5, 10):
                    active_centers.append((bx, by))
        else:
            # Dense fine grid
            active_centers = []
            for row in range(12):
                for col in range(14):
                    cx = 5 + col * 8
                    cy = 5 + row * 8
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Bonus for placing near existing zones (density)
        zone_near = dilate(zone_tiles, 6)
        zone_bonus = np.where(zone_near[cys, cxs], -4.0, 0.0)
        combined_score = best_dist + zone_bonus

        order = np.argsort(combined_score)
        tool = pick_tool()
        offset = (step * 11 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered empty area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 80)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 50)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
