def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # ---- PHASE: Ensure enough power plants ----
    # One plant per ~30x30 region
    plant_grid_xs = list(range(15, WORLD_W - 10, 30))
    plant_grid_ys = list(range(15, WORLD_H - 10, 30))
    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            x0, x1 = max(0, ppx - 14), min(WORLD_W, ppx + 15)
            y0, y1 = max(0, ppy - 14), min(WORLD_H, ppy + 15)
            if not np.any(pm[y0:y1, x0:x1]):
                # Find empty cell near grid point
                for r in range(0, 10):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # Determine action phase based on step
    phase = step % 10

    if phase == 0:
        # Extend wire horizontally from existing power sources
        # Find rows with some power, extend outward
        power_rows = [20, 35, 50, 65, 80]
        for wr in power_rows:
            row_power = wm[wr, :] | pm[wr, :]
            if not row_power.any():
                # Try to connect from nearest plant
                pys_a, pxs_a = np.where(pm)
                if len(pxs_a) > 0:
                    idx = np.argmin(np.abs(pys_a - wr))
                    sy = int(pys_a[idx])
                    sx = int(pxs_a[idx])
                    # Step toward target row
                    if sy != wr:
                        dy2 = 1 if wr > sy else -1
                        ny2 = sy + dy2
                        if ib(sx, ny2) and bool(em[ny2, sx]) and not bool(pm[ny2, sx]):
                            return (Tool.WIRE, sx, ny2)
            else:
                indices = np.where(row_power)[0]
                left = int(indices[0])
                right = int(indices[-1])
                if left > 2 and bool(em[wr, left - 1]) and not bool(pm[wr, left - 1]):
                    return (Tool.WIRE, left - 1, wr)
                if right < WORLD_W - 3 and bool(em[wr, right + 1]) and not bool(pm[wr, right + 1]):
                    return (Tool.WIRE, right + 1, wr)

    elif phase == 1:
        # Extend wire vertically
        power_cols = [15, 30, 45, 60, 75, 90, 105]
        for wc in power_cols:
            col_power = wm[:, wc] | pm[:, wc]
            if not col_power.any():
                pys_a, pxs_a = np.where(pm)
                if len(pxs_a) > 0:
                    idx = np.argmin(np.abs(pxs_a - wc))
                    sy = int(pys_a[idx])
                    sx = int(pxs_a[idx])
                    if sx != wc:
                        dx2 = 1 if wc > sx else -1
                        nx2 = sx + dx2
                        if ib(nx2, sy) and bool(em[sy, nx2]) and not bool(pm[sy, nx2]):
                            return (Tool.WIRE, nx2, sy)
            else:
                indices = np.where(col_power)[0]
                top = int(indices[0])
                bot = int(indices[-1])
                if top > 2 and bool(em[top - 1, wc]) and not bool(pm[top - 1, wc]):
                    return (Tool.WIRE, wc, top - 1)
                if bot < WORLD_H - 3 and bool(em[bot + 1, wc]) and not bool(pm[bot + 1, wc]):
                    return (Tool.WIRE, wc, bot + 1)

    elif phase == 2:
        # Extend roads horizontally (parallel to wire, offset by 2)
        road_rows_target = [22, 37, 48, 52, 67, 82]
        for rr in road_rows_target:
            if rr <= 0 or rr >= WORLD_H - 1:
                continue
            row_rd = rm[rr, :]
            if not row_rd.any():
                # Seed from nearest power
                pys_a, pxs_a = np.where(pm)
                if len(pxs_a) > 0:
                    idx = np.argmin(np.abs(pys_a - rr))
                    sx = int(pxs_a[idx])
                    if ib(sx, rr) and bool(em[rr, sx]) and not bool(pm[rr, sx]):
                        return (Tool.ROAD, sx, rr)
            else:
                indices = np.where(row_rd)[0]
                left = int(indices[0])
                right = int(indices[-1])
                if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
                    return (Tool.ROAD, left - 1, rr)
                if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
                    return (Tool.ROAD, right + 1, rr)

    elif phase == 3:
        # Extend roads vertically
        road_cols_target = [18, 33, 48, 63, 78, 93, 108]
        for rc in road_cols_target:
            if rc <= 0 or rc >= WORLD_W - 1:
                continue
            col_rd = rm[:, rc]
            if not col_rd.any():
                pys_a, pxs_a = np.where(pm)
                if len(pys_a) > 0:
                    idx = np.argmin(np.abs(pxs_a - rc))
                    sy = int(pys_a[idx])
                    if ib(rc, sy) and bool(em[sy, rc]) and not bool(pm[sy, rc]):
                        return (Tool.ROAD, rc, sy)
            else:
                indices = np.where(col_rd)[0]
                top = int(indices[0])
                bot = int(indices[-1])
                if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
                    return (Tool.ROAD, rc, top - 1)
                if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
                    return (Tool.ROAD, rc, bot + 1)

    elif phase == 4:
        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpowered_zones)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                idx2 = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx2]), int(zone_ys_u[idx2])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx2 = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy2 = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx2, bwy), (bwx, bwy + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 5:
        # Road extension toward unserved zones
        unserved = zone_tiles & ~near_road
        us_ys, us_xs = np.where(unserved)
        if len(us_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx2 = (step * 13) % len(us_xs)
                tx, ty = int(us_xs[idx2]), int(us_ys[idx2])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx2 = 0 if tx == brx else (1 if tx > brx else -1)
                dy2 = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx2, bry), (brx, bry + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 6:
        # Proactively wire empty areas near roads that lack power
        # Find road tiles that have no nearby power
        unpower_roads = rm & ~near_power
        ur_ys, ur_xs = np.where(unpower_roads)
        if len(ur_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                idx2 = (step * 7) % len(ur_xs)
                tx, ty = int(ur_xs[idx2]), int(ur_ys[idx2])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx2 = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy2 = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx2, bwy), (bwx, bwy + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 7:
        # Civic services
        if pop > 15:
            fire_spots = [
                (12, 12), (60, 12), (108, 12),
                (12, 50), (60, 50), (108, 50),
                (12, 88), (60, 88), (108, 88),
            ]
            for (sx, sy) in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 80:
            police_spots = [
                (25, 25), (60, 25), (95, 25),
                (25, 60), (60, 60), (95, 60),
                (25, 85), (60, 85), (95, 85),
            ]
            for (sx, sy) in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 250:
            for (sx, sy) in [(40, 40), (80, 40), (40, 65), (80, 65)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 500:
            nuke_spots = [
                (8, 8), (112, 8), (8, 92), (112, 92),
                (60, 8), (60, 92),
            ]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    x0, x1 = max(0, nx2 - 15), min(WORLD_W, nx2 + 16)
                    y0, y1 = max(0, ny2 - 15), min(WORLD_H, ny2 + 16)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 700:
            for (sx, sy) in [(5, 90), (113, 90), (5, 5), (113, 5)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1200:
            for (sx, sy) in [(50, 5), (70, 5), (50, 92), (70, 92)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase == 8:
        # Parks near zones for land value
        if pop > 30 and step % 4 == 0:
            park_cands = em & near_road & near_power
            pys_p, pxs_p = np.where(park_cands)
            if len(pxs_p) > 0:
                idx3 = (step * 31 + pop) % len(pxs_p)
                return (Tool.PARK, int(pxs_p[idx3]), int(pys_p[idx3]))

    else:
        # Extra wire extension from existing wires into unpowered regions
        wire_ys_b, wire_xs_b = np.where(wm)
        if len(wire_xs_b) > 0:
            step_k2 = (step * 13) % len(wire_xs_b)
            for offset in range(min(len(wire_xs_b), 50)):
                k = (step_k2 + offset * 7) % len(wire_xs_b)
                wx2, wy2 = int(wire_xs_b[k]), int(wire_ys_b[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        if not bool(near_power[ny3, nx3]):
                            return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT ----
    # Only block actual wire/road rows/cols, not a big margin
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]
    road_rows = [22, 37, 48, 52, 67, 82]
    road_cols = [18, 33, 48, 63, 78, 93, 108]
    avoid_rows = set(wire_rows + road_rows)
    avoid_cols = set(wire_cols + road_cols)

    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False

    for wr in avoid_rows:
        for offset in range(-1, 2):
            r = wr + offset
            if 0 <= r < WORLD_H:
                cand_mask[r, :] = False
    for wc in avoid_cols:
        for offset in range(-1, 2):
            c = wc + offset
            if 0 <= c < WORLD_W:
                cand_mask[:, c] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_ys_z, zone_xs_z = np.where(zone_tiles)
        road_ys_z, road_xs_z = np.where(rm)

        if len(road_xs_z) > 0:
            rd_stride = max(1, len(road_xs_z) // 60)
            road_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(road_xs_z), rd_stride):
                d = (np.abs(cxs2 - road_xs_z[i]) + np.abs(cys2 - road_ys_z[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float)

        if len(zone_xs_z) > 0:
            zn_stride = max(1, len(zone_xs_z) // 60)
            min_zone_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(zone_xs_z), zn_stride):
                d = (np.abs(cxs2 - zone_xs_z[i]) + np.abs(cys2 - zone_ys_z[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer density: close to existing zones but not overlapping
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist < 10, 0.0,
                                           min_zone_dist * 0.5))
        else:
            # No zones: prefer center area
            zone_score = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.4
        order = np.argsort(score)
        off = (step * 11 + pop % 17) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- FALLBACK: place road near plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(4, 0), (-4, 0), (0, 4), (0, -4), (6, 0), (-6, 0), (0, 6), (0, -6)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Linear "strip" city layout with dedicated power trunk line
# Key differences from parent:
# - Single horizontal power trunk at y=50 with roads at y=48 and y=52
# - Zones placed in strips above and below the trunk
# - More aggressive RCI balance (50% res, 25% com, 25% ind)
# - Civic services placed earlier and more densely
# - Zone clusters built outward from center systematically

def init(obs, state):
    """Bootstrap: central power plant + horizontal trunk wire + flanking roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire trunk left and right from plant
    for x in range(10, 60):
        actions.append((Tool.WIRE, x, 50))
    for x in range(62, 112):
        actions.append((Tool.WIRE, x, 50))
    # Roads flanking the trunk (zone access roads)
    for x in range(10, 112):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Track which hoods we've "activated" in state
    if 'hood_idx' not in state:
        state['hood_idx'] = 0

    # Grid of neighborhoods arranged in strips
    # Vertical strips with horizontal road/wire connections
    # Plant positions every 20 cols
    plant_xs = [10, 30, 50, 70, 90, 110]
    # Row groups: zones above trunk (rows 42-46) and below (rows 54-58)
    # and further strips at rows 36-40, 60-64, 30-34, 66-70
    strip_ys_above = [45, 39, 33, 27, 21, 15]
    strip_ys_below = [55, 61, 67, 73, 79, 85]

    # All zone center candidates: columns every 4, rows in strips
    # zone centers placed between road rows
    zone_cols = list(range(13, 112, 4))

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 50% res, 25% com, 25% ind
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool((resm | comm | indm)[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 1: Ensure enough power plants ----
    # Add plants as population grows
    needed_plants = 1
    if pop > 200:  needed_plants = 2
    if pop > 600:  needed_plants = 3
    if pop > 1200: needed_plants = 4
    if pop > 2000: needed_plants = 5
    if pop > 3000: needed_plants = 6

    current_plants = int(np.sum(pm))
    if current_plants < needed_plants:
        for px in plant_xs:
            py = 50
            # Check if area near this x has a plant
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Find empty spot near px, py=50
                for dy in [0, -2, 2, -4, 4]:
                    for dx in [0, -2, 2, -4, 4]:
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            tool = Tool.NUCLEARPOWER if (pop > 3000 and funds > 15000) else Tool.COALPOWER
                            return (tool, nx, ny)

    # ---- PHASE 2: Extend wire trunk and connect plants ----
    # Wire at y=50 across the full map
    trunk_y = 50
    for x in range(5, 115):
        if not ib(x, trunk_y): continue
        if bool(em[trunk_y, x]) and not bool(pm[trunk_y, x]):
            # Check if adjacent wire or plant exists
            for adx in [-1, 1]:
                ax = x + adx
                if ib(ax, trunk_y) and (bool(wm[trunk_y, ax]) or bool(pm[trunk_y, ax])):
                    return (Tool.WIRE, x, trunk_y)

    # ---- PHASE 3: Extend roads along strip_ys ----
    # Main roads at y=48 and y=52 (flanking trunk)
    road_rows = [48, 52]
    # Secondary roads for upper/lower strips
    if pop > 100:
        road_rows += [44, 56]
    if pop > 300:
        road_rows += [40, 60]
    if pop > 600:
        road_rows += [36, 64]
    if pop > 1000:
        road_rows += [32, 68]
    if pop > 1500:
        road_rows += [28, 72]
    if pop > 2000:
        road_rows += [24, 76]
    if pop > 3000:
        road_rows += [20, 80]

    for ry in road_rows:
        for rx in range(5, 115):
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                for adx in [-1, 1]:
                    ax = rx + adx
                    if ib(ax, ry) and bool(rm[ry, ax]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Vertical connector roads (every 10 cols) ----
    # Connect horizontal roads to trunk
    connector_xs = list(range(10, 115, 10))
    for cx in connector_xs:
        # Connect from trunk y to nearest road row
        for ry in road_rows:
            if ry == trunk_y: continue
            step_dir = 1 if ry > trunk_y else -1
            for cy in range(trunk_y + step_dir, ry + step_dir, step_dir):
                if not ib(cx, cy): continue
                if bool(em[cy, cx]) and not bool(pm[cy, cx]):
                    # Check if adjacent road or wire
                    for ady in [-1, 1]:
                        ay = cy + ady
                        if ib(cx, ay) and (bool(rm[ay, cx]) or bool(wm[ay, cx]) or bool(pm[ay, cx])):
                            return (Tool.ROAD, cx, cy)

    # ---- PHASE 5: Wire verticals to power upper/lower strips ----
    # Vertical wires from trunk to strip zones
    wire_vert_xs = list(range(10, 115, 8))
    for wx in wire_vert_xs:
        # Upward wires
        for wy in range(trunk_y - 1, max(10, trunk_y - 40), -1):
            if not ib(wx, wy): continue
            if bool(em[wy, wx]) and not bool(pm[wy, wx]) and not bool(rm[wy, wx]):
                # Only extend if adjacent wire/plant below
                if ib(wx, wy + 1) and (bool(wm[wy + 1, wx]) or bool(pm[wy + 1, wx])):
                    return (Tool.WIRE, wx, wy)
                break
        # Downward wires
        for wy in range(trunk_y + 1, min(90, trunk_y + 40)):
            if not ib(wx, wy): continue
            if bool(em[wy, wx]) and not bool(pm[wy, wx]) and not bool(rm[wy, wx]):
                if ib(wx, wy - 1) and (bool(wm[wy - 1, wx]) or bool(pm[wy - 1, wx])):
                    return (Tool.WIRE, wx, wy)
                break

    # ---- PHASE 6: Place zones near roads with power ----
    # Build road neighbor and power neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    # Avoid edges
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False
    # Avoid the trunk wire row itself
    cand_mask[trunk_y, :] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()
        # Sort candidates by distance from trunk (prioritize close rows first)
        dist_from_trunk = np.abs(cys - trunk_y)
        order = np.argsort(dist_from_trunk)
        for i in range(min(len(order), 500)):
            k = order[i]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: Civic services ----
    if pop > 50:
        # Fire stations along trunk
        fire_spots = [(x, 45) for x in range(20, 110, 20)] + \
                     [(x, 55) for x in range(20, 110, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(x, 43) for x in range(15, 110, 20)] + \
                       [(x, 57) for x in range(15, 110, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(30, 38), (60, 38), (90, 38), (30, 62), (60, 62), (90, 62)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(10, 90), (60, 90), (110, 90), (10, 10), (60, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(20, 10), (80, 10), (20, 88), (80, 88)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 8: Parks near road+power for land value ----
    if pop > 100 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: extend road from existing road ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 5) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: new coal plant if area unpowered ----
    check_spots = [(60, 30), (60, 70), (30, 50), (90, 50), (30, 30), (90, 30), (30, 70), (90, 70)]
    for (sx, sy) in check_spots:
        if ib(sx, sy) and not bool(nbr_power[sy, sx]):
            for dy in range(-3, 4):
                for dx in range(-3, 4):
                    nx, ny = sx + dx, sy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    return None

