def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 45% res, 30% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire corridors at rows 25, 50, 75 and cols 30, 60, 90
    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure enough power plants distributed across map
    if phase == 0:
        plant_targets = [
            (10, 10), (60, 10), (110, 10),
            (10, 50), (60, 50), (110, 50),
            (10, 90), (60, 90), (110, 90),
            (30, 30), (90, 30), (30, 70), (90, 70),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill wire row gaps
    if phase == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Build roads adjacent to wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        if has_wire and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Build roads adjacent to wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                   bool(rm[ry, max(0, rcx-1)]) or \
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if has_wire and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # Phase 5: Add mid-block horizontal roads between wire rows
    if phase == 5:
        mid_rows = [(wire_rows[i] + wire_rows[i+1]) // 2 for i in range(len(wire_rows)-1)]
        mid_rows += [10, 90]  # top/bottom mid sections
        for mr in mid_rows:
            if mr <= 0 or mr >= WORLD_H - 1:
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                    adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mr)

    # Phase 6: Add mid-block vertical roads between wire cols
    if phase == 6:
        mid_cols = [(wire_cols[i] + wire_cols[i+1]) // 2 for i in range(len(wire_cols)-1)]
        mid_cols += [15, 105]
        for mc in mid_cols:
            if mc <= 0 or mc >= WORLD_W - 1:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                    adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mc]))
                    if adj:
                        return (Tool.ROAD, mc, ry)

    # Phase 7: Wire unpowered zones
    if phase == 7:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Wire roads without power
    if phase == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Civic: fire stations early
    if pop > 10:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 30), (115, 30),
            (5, 50), (115, 50),
            (5, 70), (115, 70),
            (5, 95), (60, 95), (115, 95),
            (30, 20), (90, 20), (30, 80), (90, 80),
            (45, 50), (75, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (20, 12), (50, 12), (80, 12), (110, 12),
            (20, 37), (50, 37), (80, 37), (110, 37),
            (20, 63), (50, 63), (80, 63), (110, 63),
            (20, 88), (50, 88), (80, 88), (110, 88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 250:
        stadium_spots = [
            (20, 20), (70, 20), (20, 70), (70, 70),
            (45, 45), (95, 45), (45, 80), (95, 80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 400:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5, 92), (115, 92), (5, 8), (115, 8)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value when pop is decent
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scale active zone centers based on pop
        if pop < 100:
            # Start small in center
            active_centers = [
                (45, 35), (60, 35), (75, 35),
                (45, 50), (60, 50), (75, 50),
                (45, 65), (60, 65), (75, 65),
            ]
        elif pop < 400:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 15 + col * 14
                    cy = 12 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 1000:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 10 + col * 11
                    cy = 8 + row * 11
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 1000)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + initial roads."""
    actions = []
    # Two coal plants
    for cx, cy in [(38, 50), (78, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire horizontally
        for dx in range(-5, 6):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        # Wire vertically
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking wire column
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 1, cy + dy))
            actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- NEIGHBORHOOD ANCHORS ----
    # 5 columns x 4 rows = 20 neighborhoods
    anchors = []
    for col_i, cx in enumerate([18, 38, 58, 78, 98]):
        for row_i, cy in enumerate([18, 38, 58, 78]):
            anchors.append((cx, cy, col_i * 4 + row_i))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 3
        if pop < 350:   return 5
        if pop < 700:   return 8
        if pop < 1200:  return 12
        if pop < 2000:  return 16
        return 20

    active = anchors[:num_active()]

    # ---- PHASE 1: ENSURE POWER PLANTS per active anchor ----
    for (px, py, idx) in active:
        has_plant = False
        for dx in range(-8, 9):
            for dy in range(-8, 9):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: EXTEND WIRE toward uncovered active anchors ----
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0:
        for (px, py, idx) in active:
            dists = np.abs(wire_xs.astype(float) - px) + np.abs(wire_ys.astype(float) - py)
            min_dist = float(np.min(dists))
            if min_dist > 4:
                closest_k = np.argmin(dists)
                wx, wy = int(wire_xs[closest_k]), int(wire_ys[closest_k])
                dx = 1 if px > wx else (-1 if px < wx else 0)
                dy = 1 if py > wy else (-1 if py < wy else 0)
                for (ddx, ddy) in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: EXTEND WIRE VERTICALLY along anchor columns ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_col:
            for dy in range(-6, 7):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_col)
            max_wr = max(wire_col)
            ext = min(28, 10 + pop // 60)
            spine_top = max(2, py - ext)
            spine_bot = min(WORLD_H - 3, py + ext)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 4: HORIZONTAL WIRE CONNECTIONS between anchors in same row ----
    row_groups = {}
    for (px, py, idx) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append(px)

    for row_y, group in row_groups.items():
        group_sorted = sorted(group)
        for i in range(len(group_sorted) - 1):
            x1, x2 = group_sorted[i], group_sorted[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- PHASE 5: BUILD ROADS FLANKING WIRE SPINES ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and (bool(wm[r, px]) or bool(pm[r, px]))]
        if not wire_col:
            continue
        rl, rr = px - 1, px + 1
        cycle_off = (step + idx * 11) % max(len(wire_col), 1)
        for k in range(min(len(wire_col), 12)):
            wr = wire_col[(cycle_off + k) % len(wire_col)]
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- PHASE 6: HORIZONTAL ROADS connecting neighborhoods ----
    for (px, py, idx) in active:
        for dx in range(-12, 13):
            rx = px + dx
            if not ib(rx, py):
                continue
            if bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near = any(
                    ib(rx + d, py) and (bool(rm[py, rx + d]) or bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near:
                    return (Tool.ROAD, rx, py)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 7: ZONE PLACEMENT ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.20:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.18:
                return Tool.INDUSTRIAL
            if cr < 0.22:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.28:
                return Tool.COMMERCIAL
            if rr < 0.50:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, idx) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 3 + pop) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 8: EXTEND ROADS along existing roads toward wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 7) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 9) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 100:
        firestations = [
            (28, 18), (48, 18), (68, 18), (88, 18),
            (28, 38), (48, 38), (68, 38), (88, 38),
            (28, 58), (48, 58), (68, 58), (88, 58),
            (28, 78), (48, 78), (68, 78), (88, 78),
            (8, 28), (108, 28), (8, 68), (108, 68),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        polices = [
            (38, 28), (58, 28), (78, 28), (98, 28),
            (38, 48), (58, 48), (78, 48), (98, 48),
            (38, 68), (58, 68), (78, 68), (98, 68),
            (18, 48), (108, 48),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 10), (70, 10), (110, 10),
            (30, 90), (70, 90), (110, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10), (60, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92),
                    (5, 45), (115, 45)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 10: NUCLEAR PLANT for high pop ----
    if pop > 2500:
        nuclear_spots = [
            (10, 50), (110, 50), (60, 5), (60, 95),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 200 and step % 5 == 0:
        park_cands = em & nbr_road & nbr_wire
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx2 = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx2]), int(pys[idx2]))

    # ---- FALLBACK: Extend wire from any wire tile ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 50)):
            k = (step_k2 + offset * 7) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + initial wire grid + roads to seed the city."""
    actions = []
    # Two main power plants - one center-left, one center-right
    plants = [(30, 50), (90, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire horizontally between plants through center
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically from each plant
    for px, py in plants:
        for dy in range(1, 12):
            actions.append((Tool.WIRE, px, py - dy))
            actions.append((Tool.WIRE, px, py + dy))
    # Roads parallel to wire spines
    for px, py in plants:
        for dy in range(1, 10):
            actions.append((Tool.ROAD, px + 2, py - dy))
            actions.append((Tool.ROAD, px - 2, py - dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
            actions.append((Tool.ROAD, px - 2, py + dy))
    return actions[:20]  # keep small


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.astype(bool).copy()
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    # Current zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Pick zone type to balance: 50% res, 25% com, 25% ind
    def pick_tool():
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Power and road proximity masks
    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Check if a 3x3 zone area is clear
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # --- STRATEGY: Grow outward from existing infrastructure ---
    # Priority 1: Ensure power plants exist and are spread
    # Find unpowered large regions and add coal plants
    power_mask = wm | pm
    if not np.any(power_mask):
        # Emergency: place coal plant at center
        return (Tool.COALPOWER, 60, 50)

    # Priority 2: Extend wires from existing wire/plant cells
    # toward areas that need power (far from current power)
    # Find frontier: empty cells adjacent to wire/plant
    wire_frontier = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_mask_bool = power_mask.astype(bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(power_mask_bool)
        if dy > 0:
            shifted[dy:, :] = power_mask_bool[:-dy, :]
        elif dy < 0:
            shifted[:dy, :] = power_mask_bool[-dy:, :]
        elif dx > 0:
            shifted[:, dx:] = power_mask_bool[:, :-dx]
        elif dx < 0:
            shifted[:, :dx] = power_mask_bool[:, -dx:]
        wire_frontier |= shifted
    wire_frontier &= em  # only empty cells

    # Priority 3: Extend roads from existing roads
    road_frontier = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    rm_bool = rm.astype(bool)
    for dy, dx in [(-1,0),(1,0),(0,-1),(0,1)]:
        shifted = np.zeros_like(rm_bool)
        if dy > 0:
            shifted[dy:, :] = rm_bool[:-dy, :]
        elif dy < 0:
            shifted[:dy, :] = rm_bool[-dy:, :]
        elif dx > 0:
            shifted[:, dx:] = rm_bool[:, :-dx]
        elif dx < 0:
            shifted[:, :dx] = rm_bool[:, -dx:]
        road_frontier |= shifted
    road_frontier &= em & ~pm.astype(bool)

    # Determine phase based on step modulo
    phase = step % 8

    # Phase 0-1: Wire extension - grow power network outward
    if phase in (0, 1):
        # Find wire frontier cells farthest from existing power (expand coverage)
        fw_ys, fw_xs = np.where(wire_frontier & ~near_power)
        if len(fw_xs) > 0:
            # Pick cell that extends power toward empty areas
            # Score by distance from center of existing power
            pm_ys, pm_xs = np.where(power_mask_bool)
            if len(pm_xs) > 0:
                cx = float(np.mean(pm_xs))
                cy = float(np.mean(pm_ys))
                dists = np.sqrt((fw_xs - cx)**2 + (fw_ys - cy)**2)
                # Pick moderately far cell (not too close, not edge)
                order = np.argsort(-dists)
                for i in order[:50]:
                    wx, wy = int(fw_xs[i]), int(fw_ys[i])
                    if ib(wx, wy):
                        return (Tool.WIRE, wx, wy)
        # Extend existing wire frontiers
        fw_ys2, fw_xs2 = np.where(wire_frontier)
        if len(fw_xs2) > 0:
            idx = (step * 17 + pop * 3) % len(fw_xs2)
            return (Tool.WIRE, int(fw_xs2[idx]), int(fw_ys2[idx]))

    # Phase 2-3: Road extension in powered areas
    if phase in (2, 3):
        # Roads in powered areas that aren't already roaded
        powered_road_frontier = road_frontier & near_power
        if np.any(powered_road_frontier):
            fr_ys, fr_xs = np.where(powered_road_frontier)
            if len(fr_xs) > 0:
                # Prefer roads near zones for connectivity
                zone_near = dilate(zone_tiles, 4)
                pref = powered_road_frontier & zone_near
                if np.any(pref):
                    p_ys, p_xs = np.where(pref)
                    idx = (step * 13 + pop * 7) % len(p_xs)
                    return (Tool.ROAD, int(p_xs[idx]), int(p_ys[idx]))
                idx = (step * 13 + pop * 7) % len(fr_xs)
                return (Tool.ROAD, int(fr_xs[idx]), int(fr_ys[idx]))

        # Extend roads into unpowered areas to prepare for wire
        all_road_frontier = road_frontier
        if np.any(all_road_frontier):
            fr_ys, fr_xs = np.where(all_road_frontier)
            if len(fr_xs) > 0:
                idx = (step * 19) % len(fr_xs)
                return (Tool.ROAD, int(fr_xs[idx]), int(fr_ys[idx]))

    # Phase 4-6: Zone placement (main growth engine)
    if phase in (4, 5, 6):
        # Good zone locations: empty, near power, near road
        cand = em & near_power & near_road
        # Avoid map edges
        cand[:3, :] = False
        cand[WORLD_H-3:, :] = False
        cand[:, :3] = False
        cand[:, WORLD_W-3:] = False
        # Avoid plant tiles
        cand &= ~pm.astype(bool)

        c_ys, c_xs = np.where(cand)
        if len(c_xs) > 0:
            tool = pick_tool()
            # Sort candidates by distance to nearest existing zone (cluster zones together)
            if total_zones > 1:
                z_ys, z_xs = np.where(zone_tiles)
                # For each candidate, find min distance to existing zone
                best_dists = np.full(len(c_xs), 9999.0)
                for i in range(min(len(z_xs), 200)):
                    d = np.abs(c_xs - z_xs[i]) + np.abs(c_ys - z_ys[i])
                    best_dists = np.minimum(best_dists, d.astype(float))
                # Prefer cells at distance 3-8 from existing zones (not too close, not isolated)
                good = (best_dists >= 3) & (best_dists <= 10)
                if np.any(good):
                    gc_xs = c_xs[good]
                    gc_ys = c_ys[good]
                    offset = (step * 11 + pop * 5) % len(gc_xs)
                    for i in range(min(len(gc_xs), 300)):
                        k = (offset + i) % len(gc_xs)
                        zx, zy = int(gc_xs[k]), int(gc_ys[k])
                        if zone_clear(zx, zy):
                            return (tool, zx, zy)

            # Fallback: any candidate
            offset = (step * 11 + pop * 5) % len(c_xs)
            for i in range(min(len(c_xs), 300)):
                k = (offset + i) % len(c_xs)
                zx, zy = int(c_xs[k]), int(c_ys[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)

    # Phase 7: Infrastructure and civic buildings
    if phase == 7:
        # Add more coal plants if coverage is insufficient
        powered_fraction = float(np.sum(near_power)) / (WORLD_W * WORLD_H)
        if powered_fraction < 0.3 and funds > 5000:
            # Place coal plant in large unpowered empty area
            unpow_em = em & ~near_power & ~pm.astype(bool)
            u_ys, u_xs = np.where(unpow_em)
            if len(u_xs) > 0:
                # Far from existing plants
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    best_dists = np.full(len(u_xs), 9999.0)
                    for i in range(len(plant_xs)):
                        d = np.abs(u_xs - plant_xs[i]) + np.abs(u_ys - plant_ys[i])
                        best_dists = np.minimum(best_dists, d.astype(float))
                    farthest = np.argmax(best_dists)
                    px, py = int(u_xs[farthest]), int(u_ys[farthest])
                    if ib(px, py):
                        return (Tool.COALPOWER, px, py)

        # Civic: fire stations
        if pop > 200:
            fire_grid = [(x, y) for y in range(15, WORLD_H-5, 22) for x in range(15, WORLD_W-5, 25)]
            for sx, sy in fire_grid:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        # Civic: police stations
        if pop > 500:
            police_grid = [(x, y) for y in range(20, WORLD_H-5, 25) for x in range(20, WORLD_W-5, 30)]
            for sx, sy in police_grid:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        # Nuclear for more power at high pop
        if pop > 1500 and funds > 15000:
            nuke_spots = [(10,10),(110,10),(10,90),(110,90),(60,10),(60,90),(10,50),(110,50)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        # Stadiums
        if pop > 800 and funds > 5000:
            stad_spots = [(25,25),(95,25),(25,75),(95,75),(60,50)]
            for sx, sy in stad_spots:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        # Seaport
        if pop > 2000 and funds > 3000:
            for sx, sy in [(10,90),(110,90),(10,10),(110,10)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        # Airport
        if pop > 4000 and funds > 10000:
            for ax, ay in [(50,10),(70,10),(50,88),(70,88)]:
                if ib(ax, ay) and bool(em[ay, ax]):
                    return (Tool.AIRPORT, ax, ay)

    # Fallback: try zone placement broadly
    cand2 = em & near_power & near_road & ~pm.astype(bool)
    cand2[:3, :] = False
    cand2[WORLD_H-3:, :] = False
    cand2[:, :3] = False
    cand2[:, WORLD_W-3:] = False
    c2_ys, c2_xs = np.where(cand2)
    if len(c2_xs) > 0:
        tool = pick_tool()
        offset = (step * 7 + pop * 11) % len(c2_xs)
        for i in range(min(len(c2_xs), 200)):
            k = (offset + i) % len(c2_xs)
            zx, zy = int(c2_xs[k]), int(c2_ys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Last resort: extend wire from nearest power source toward empty area
    fw2_ys, fw2_xs = np.where(wire_frontier)
    if len(fw2_xs) > 0:
        idx = step % len(fw2_xs)
        return (Tool.WIRE, int(fw2_xs[idx]), int(fw2_ys[idx]))

    # Absolute last: extend road
    rf2_ys, rf2_xs = np.where(road_frontier & ~pm.astype(bool))
    if len(rf2_xs) > 0:
        idx = step % len(rf2_xs)
        return (Tool.ROAD, int(rf2_xs[idx]), int(rf2_ys[idx]))

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire/road grid"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 75))
    # Vertical wire spines
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Roads adjacent to wire rows
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    # Roads adjacent to wire cols
    for y in range(1, 99):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
        actions.append((Tool.ROAD, 59, y))
        actions.append((Tool.ROAD, 61, y))
        actions.append((Tool.ROAD, 89, y))
        actions.append((Tool.ROAD, 91, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 50% res, 30% com, 20% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # REACTIVE: check what's actually missing on the map each step

    # 1) Ensure power plants distributed — check coverage gaps reactively
    plant_targets = [
        (10, 10), (60, 10), (110, 10),
        (10, 50), (60, 50), (110, 50),
        (10, 90), (60, 90), (110, 90),
        (30, 30), (90, 30), (30, 70), (90, 70),
    ]
    # Only place plants every ~20 steps to avoid overwhelming
    if step % 20 == 0:
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # 2) Reactively fill wire row gaps (scan for disconnected segments)
    if step % 4 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    # Check neighbors for wire/plant
                    left = bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    # 3) Reactively fill wire col gaps
    if step % 4 == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = bool(wm[wy-1, wc]) or bool(pm[wy-1, wc])
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # 4) Reactively build roads along wire rows
    if step % 4 == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]) and not bool(rm[ry, rx]):
                        has_wire_above = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        if has_wire_above and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # 5) Wire: connect unpowered zones reactively
    if step % 7 == 0:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17 + pop) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # 6) Add mid-block roads between wire corridors (reactive: only if powered nearby)
    if step % 6 == 5:
        mid_rows = [12, 37, 62, 87]
        mid_cols = [15, 45, 75, 105]
        for mr in mid_rows:
            if 0 < mr < WORLD_H - 1:
                for rx in range(1, WORLD_W - 1):
                    if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                        adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                              (rx < WORLD_W-1 and bool(rm[mr, rx+1]))
                        if adj:
                            return (Tool.ROAD, rx, mr)
        for mc in mid_cols:
            if 0 < mc < WORLD_W - 1:
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                        adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                              (ry < WORLD_H-1 and bool(rm[ry+1, mc]))
                        if adj:
                            return (Tool.ROAD, mc, ry)

    # Civic buildings — placed reactively based on pop thresholds
    if pop > 10:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 30), (115, 30),
            (5, 50), (115, 50),
            (5, 70), (115, 70),
            (5, 95), (60, 95), (115, 95),
            (30, 20), (90, 20), (30, 80), (90, 80),
            (45, 50), (75, 50), (20, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (20, 12), (50, 12), (80, 12), (110, 12),
            (20, 37), (50, 37), (80, 37), (110, 37),
            (20, 63), (50, 63), (80, 63), (110, 63),
            (20, 88), (50, 88), (80, 88), (110, 88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (20, 20), (70, 20), (20, 70), (70, 70),
            (45, 45), (95, 45), (45, 80), (95, 80),
            (15, 45), (105, 45),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
            (40, 5), (80, 5),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 92), (115, 92), (5, 8), (115, 8)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Reactive: expand zone placement center as population grows
        if pop < 100:
            active_centers = [
                (45, 35), (60, 35), (75, 35),
                (45, 50), (60, 50), (75, 50),
                (45, 65), (60, 65), (75, 65),
            ]
        elif pop < 500:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 12 + col * 13
                    cy = 10 + row * 13
                    active_centers.append((cx, cy))
        elif pop < 1500:
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 8 + col * 10
                    cy = 6 + row * 10
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(11):
                for col in range(13):
                    cx = 4 + col * 9
                    cy = 4 + row * 9
                    active_centers.append((cx, cy))

        # Find closest active center for each candidate
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary offset based on both step and population for reactivity
        offset = (step * 7 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 1500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road reactively
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11 + pop) % len(road_xs)
        for off in range(min(len(road_xs), 500)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13 + pop) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 200)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and road grid."""
    actions = []
    # Two power plants side by side for redundancy
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Wire connecting them
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Wire spines outward from each plant
    for d in range(1, 12):
        actions.append((Tool.WIRE, 40, 50 - d))
        actions.append((Tool.WIRE, 40, 50 + d))
        actions.append((Tool.WIRE, 80, 50 - d))
        actions.append((Tool.WIRE, 80, 50 + d))
    # Horizontal roads flanking the wire spine
    for x in range(28, 55):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    for x in range(68, 95):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% RES, 30% COM, 20% IND
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Neighborhood anchors - expand as population grows
    all_anchors = [
        (40, 50), (80, 50),           # initial two plants
        (40, 25), (80, 25),           # upper row
        (40, 75), (80, 75),           # lower row
        (60, 50),                      # center
        (20, 50), (100, 50),          # far sides
        (20, 25), (100, 25),
        (20, 75), (100, 75),
        (60, 25), (60, 75),
    ]

    def num_active():
        if pop < 100:  return 2
        if pop < 300:  return 4
        if pop < 600:  return 6
        if pop < 1000: return 8
        if pop < 1500: return 10
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANTS at each anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find nearest empty spot
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE CONNECTIVITY: connect all active anchors ----
    # First connect horizontally within rows
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx in range(x1a + 1, x2a):
                if ib(cx, yl) and bool(em[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # Connect vertically between rows
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy in range(y1a + 1, y2a):
                if ib(xl, cy) and bool(em[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- WIRE SPINES from each anchor ----
    spine = min(12, 4 + pop // 40)
    for (px, py) in active_anchors:
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- ROAD GRID around each anchor ----
    road_offsets = [-4, -3, 3, 4]
    for (px, py) in active_anchors:
        for road_dy in road_offsets:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)
        for road_dx in road_offsets:
            rx = px + road_dx
            if not ib(rx, py):
                continue
            for dy in range(-spine, spine + 1):
                ry = py + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- VERTICAL ROADS connecting anchor rows ----
    if pop > 50:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                _, y1a = col_anchors[i]
                _, y2a = col_anchors[i + 1]
                for road_x in [xl + 4, xl - 4]:
                    for cy in range(y1a, y2a + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- BUILD ZONE CANDIDATE MASK ----
    # Zones need road access within 2 tiles and wire/plant within 5 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = (np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use a rotating offset based on step to avoid getting stuck
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES scaled to pop ----
    if pop > 100:
        fire_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
            (35, 35), (75, 35), (35, 65), (75, 65),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (25, 15), (65, 15), (105, 15),
            (25, 55), (65, 55), (105, 55),
            (25, 85), (65, 85), (105, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # ---- PARKS to boost land value ----
    if pop > 200:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 50)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, 3), (3, -3), (-3, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    if pop > 700:
        stadium_spots = [(15, 10), (60, 10), (105, 10), (15, 90), (60, 90), (105, 90)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        nuclear_spots = [(10, 10), (110, 10), (10, 90), (110, 90), (60, 5)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        airport_spots = [(55, 8), (10, 50), (110, 50), (55, 92)]
        for (ax, ay) in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 4000:
        seaport_spots = [(10, 95), (110, 95), (60, 97), (10, 5), (110, 5)]
        for (sx2, sy2) in seaport_spots:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near existing zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire grid + road grid."""
    actions = []
    cx, cy = 60, 50
    # Place central coal power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-15, 16):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-15, 16):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking horizontal spine
    for dx in range(-12, 13):
        actions.append((Tool.ROAD, cx + dx, cy - 3))
        actions.append((Tool.ROAD, cx + dx, cy + 3))
    # Roads flanking vertical spine
    for dy in range(-12, 13):
        actions.append((Tool.ROAD, cx - 3, cy + dy))
        actions.append((Tool.ROAD, cx + 3, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID (denser than parent) ----
    all_hoods = []
    for hy in range(10, 95, 12):
        for hx in range(10, 115, 12):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 9
        if pop < 500:   return 16
        if pop < 1000:  return 25
        if pop < 2000:  return 36
        if pop < 4000:  return 50
        if pop < 7000:  return 65
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Sort hoods by distance to center to grow outward
    cx_map, cy_map = 60, 50
    all_hoods_sorted = sorted(all_hoods, key=lambda h: abs(h[0]-cx_map) + abs(h[1]-cy_map))
    active_hoods = all_hoods_sorted[:n_active]

    # ---- POWER/ROAD COVERAGE MAPS ----
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        src = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= src[:-d, :]
            result[:-d, :] |= src[d:, :]
            result[:, d:] |= src[:, :-d]
            result[:, :-d] |= src[:, d:]
        return result

    nbr_power = dilate(wm | pm, 5)
    nbr_road = dilate(rm, 2)

    # ---- ZONE TOOL SELECTION ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- ZONE CLEAR CHECK ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                t = tm[nr, nc]
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine_range = 12

    # ---- PHASE 1: POWER PLANTS for active hoods ----
    if funds > 2000:
        for (ahx, ahy) in active_hoods:
            x0, x1 = max(0, ahx - 12), min(WORLD_W, ahx + 13)
            y0, y1 = max(0, ahy - 12), min(WORLD_H, ahy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = ahx + dx, ahy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    # Vertical spine at hx
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine at hy
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRES BETWEEN HOODS ----
    for i_h in range(min(len(active_hoods), 10)):
        hx1, hy1 = active_hoods[(hood_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            if abs(hy2 - hy1) <= 3 and 4 <= abs(hx2 - hx1) <= 25 and hx2 > hx1:
                mid_y = (hy1 + hy2) // 2
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, mid_y): continue
                    if bool(wm[mid_y, cx2]) or bool(pm[mid_y, cx2]): continue
                    if not bool(em[mid_y, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, cx2, mid_y)
            if abs(hx2 - hx1) <= 3 and 4 <= abs(hy2 - hy1) <= 20 and hy2 > hy1:
                mid_x = (hx1 + hx2) // 2
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(mid_x, cy2): continue
                    if bool(wm[cy2, mid_x]) or bool(pm[cy2, mid_x]): continue
                    if not bool(em[cy2, mid_x]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, cy2)

    # ---- PHASE 4: ROADS flanking spines (offset ±3 for wider zone space) ----
    road_idx = step % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_idx]

    for rx in [rhx - 3, rhx + 3]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [rhy - 3, rhy + 3]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ahx2, ahy2) in active_hoods:
            d = np.abs(cxs - ahx2) + np.abs(cys - ahy2)
            best_dist = np.minimum(best_dist, d)

        # Cluster bonus
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        tool = pick_tool()
        # Vary offset by step to avoid replaying same location
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_grid = [(fx, fy) for fy in range(10, 95, 14)
                     for fx in range(10, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 120:
        police_grid = [(px2, py2) for py2 in range(12, 90, 16)
                       for px2 in range(12, 110, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 19 + pop) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (25, 25), (60, 15), (95, 25),
            (25, 75), (60, 85), (95, 75),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (50, 6), (80, 6), (50, 93), (80, 93)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from existing plants ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 60)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                             (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: plant near unpowered hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 15):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads along vertical wire
    for dy in range(-7, 8):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Flanking roads along horizontal wire
    for dx in range(-7, 8):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID ----
    # Dense grid: 8 cols x 7 rows = 56 neighborhoods
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 22, 34, 46, 58, 70, 82]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 5
        if pop < 400:   return 10
        if pop < 800:   return 16
        if pop < 1500:  return 24
        if pop < 3000:  return 36
        if pop < 6000:  return 48
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        # Pick evenly spaced hoods from the full list
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- DILATE HELPER ----
    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    nbr_power = dilate(power_src, 5)
    nbr_road = dilate(rm, 3)

    # ---- PHASE 1: ENSURE POWER PLANTS for active hoods ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE INFRASTRUCTURE ----
    # Build wire spines; process one hood per step for responsiveness
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)
    for i_h in range(len(active_hoods)):
        hx, hy = active_hoods[(hood_idx + i_h) % len(active_hoods)]

        # Vertical wire spine at column hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Horizontal wire spine at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)
        break  # One hood per step

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    conn_idx = (step // max(len(active_hoods), 1)) % max(len(active_hoods), 1)
    h_spacing = 14  # approximate column spacing
    v_spacing = 12  # approximate row spacing
    for i_h in range(len(active_hoods)):
        hx1, hy1 = active_hoods[(conn_idx + i_h) % len(active_hoods)]
        for hx2, hy2 in active_hoods:
            # Horizontal connection (same row, adjacent cols)
            if hy1 == hy2 and 10 <= abs(hx2 - hx1) <= 18 and hx2 > hx1:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical connection (same col, adjacent rows)
            if hx1 == hx2 and 8 <= abs(hy2 - hy1) <= 16 and hy2 > hy1:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)
        break  # One hood per step

    # ---- PHASE 4: ROADS along wire spines ----
    road_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[road_idx]

    # Roads flanking vertical spine (at hx-1 and hx+1)
    for rx in [hx - 1, hx + 1]:
        if not ib(rx, hy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(pm[ry, rx]): continue
            if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                return (Tool.ROAD, rx, ry)

    # Roads flanking horizontal spine (at hy-1 and hy+1)
    for ry2 in [hy - 1, hy + 1]:
        if not ib(hx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx + dx
            if not ib(rcx, ry2): continue
            if bool(rm[ry2, rcx]): continue
            if not bool(em[ry2, rcx]) and not bool(zone_tiles[ry2, rcx]): continue
            if bool(pm[ry2, rcx]): continue
            if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Also factor in road proximity
        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            stride = max(1, len(road_xs_arr) // 100)
            road_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(road_xs_arr), stride):
                d = (np.abs(cxs - road_xs_arr[i]) + np.abs(cys - road_ys_arr[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs), 5.0)

        score = best_dist * 0.7 + road_dist * 1.5
        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 6: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        for fx in range(12, WORLD_W - 2, 16):
            for fy in range(12, WORLD_H - 2, 16):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(nbr_road[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 300:
        for px2 in range(14, WORLD_W - 2, 18):
            for py2 in range(14, WORLD_H - 2, 18):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(nbr_road[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 800:
        for sx in range(20, WORLD_W - 5, 28):
            for sy in range(20, WORLD_H - 5, 28):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50),
                     (15, 15), (105, 15), (15, 85), (105, 85)]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 7), min(WORLD_W, nx2 + 8)
                y0, y1 = max(0, ny2 - 7), min(WORLD_H, ny2 + 8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaport_spots = [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95)]
        for (sx, sy) in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airport_spots = [(20, 6), (50, 6), (80, 6), (20, 94), (50, 94), (80, 94)]
        for (sx, sy) in airport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value occasionally
    if pop > 150 and step % 5 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 19) % len(park_xs2)
            py3, px3 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px3, py3) and bool(em[py3, px3]):
                return (Tool.PARK, px3, py3)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered active hood ----
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 12):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = hx3 + dx4, hy3 + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    # ---- FALLBACK: road near plant ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

# Strategy: Grid-based city with multiple power plants distributed across the map
# Key changes from parent:
# 1. Grid road network (horizontal + vertical) instead of just horizontal spines
# 2. More aggressive zone placement with 40/35/25 RES/COM/IND ratio (more commercial)
# 3. Nuclear power plants placed earlier and more frequently
# 4. Zones placed directly adjacent to roads (1 tile, not 2-4)
# 5. Multiple coal plants distributed to ensure full coverage before nuclear

def init(obs, state):
    """Bootstrap: central coal plant + cross wire + immediate roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire from plant
    for dx in range(1, 12):
        actions.append((Tool.WIRE, cx + dx, cy))
        actions.append((Tool.WIRE, cx - dx, cy))
    # Vertical wire from plant
    for dy in range(1, 10):
        actions.append((Tool.WIRE, cx, cy + dy))
        actions.append((Tool.WIRE, cx, cy - dy))
    # Roads immediately flanking the wire spine
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 2))
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid layout: major roads every 6 tiles, power spines every 12 tiles
    # Horizontal road rows and vertical road cols form a grid
    # Power plants at grid intersections every 24 tiles

    road_ys = list(range(8, WORLD_H - 4, 6))   # horizontal roads
    road_xs = list(range(8, WORLD_W - 4, 6))   # vertical roads

    # Power plant positions: at intersections of every 4th road line
    plant_positions = []
    for i, ry in enumerate(road_ys[::4]):
        for j, rx in enumerate(road_xs[::4]):
            plant_positions.append((rx, ry))

    # Progressive growth: how many plant positions to activate
    def n_active_plants():
        if pop < 100: return 2
        if pop < 500: return 4
        if pop < 1500: return 7
        if pop < 3000: return 12
        return len(plant_positions)

    n_plants = min(n_active_plants(), len(plant_positions))
    active_plants = plant_positions[:n_plants]

    # ---- PHASE 1: PLACE POWER PLANTS ----
    for px, py in active_plants:
        x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
        y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID connecting plants to road network ----
    # Horizontal wire at each plant row
    active_plant_ys = sorted(set(py for _, py in active_plants))
    active_plant_xs = sorted(set(px for px, _ in active_plants))

    # Lay wires horizontally across plant rows
    if step % 4 == 0:
        for wy in active_plant_ys:
            for wx in range(5, WORLD_W - 4):
                if not ib(wx, wy): continue
                if bool(wm[wy, wx]) or bool(pm[wy, wx]): continue
                if not bool(em[wy, wx]): continue
                # Only extend if adjacent to wire or plant
                for adj_dx in [-1, 1]:
                    ax = wx + adj_dx
                    if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                        return (Tool.WIRE, wx, wy)

    # Lay wires vertically across plant cols
    if step % 4 == 1:
        for wx in active_plant_xs:
            for wy in range(5, WORLD_H - 4):
                if not ib(wx, wy): continue
                if bool(wm[wy, wx]) or bool(pm[wy, wx]): continue
                if not bool(em[wy, wx]): continue
                for adj_dy in [-1, 1]:
                    ay = wy + adj_dy
                    if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                        return (Tool.WIRE, wx, wy)

    # ---- PHASE 3: HORIZONTAL ROADS at road_ys ----
    if step % 4 == 2:
        # Only lay roads within powered areas
        nbr_power_h = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2 in range(-5, 6):
            for dx2 in range(-5, 6):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
                nbr_power_h[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power_h[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        for ry in road_ys:
            for rx in range(5, WORLD_W - 4):
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]) or bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                if not bool(nbr_power_h[ry, rx]): continue
                # Extend if adjacent to road
                for adj in [-1, 1]:
                    ax = rx + adj
                    if ib(ax, ry) and bool(rm[ry, ax]):
                        return (Tool.ROAD, rx, ry)
            # Bootstrap road start near plant
            for px, py in active_plants:
                if abs(py - ry) <= 3:
                    for rx2 in range(max(5, px - 2), min(WORLD_W - 4, px + 3)):
                        if ib(rx2, ry) and bool(em[ry, rx2]) and not bool(pm[ry, rx2]):
                            return (Tool.ROAD, rx2, ry)

    # ---- PHASE 4: VERTICAL ROADS at road_xs ----
    if step % 4 == 3:
        nbr_power_v = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2 in range(-5, 6):
            for dx2 in range(-5, 6):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
                nbr_power_v[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
                nbr_power_v[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

        for rx in road_xs:
            for ry in range(5, WORLD_H - 4):
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]) or bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                if not bool(nbr_power_v[ry, rx]): continue
                for adj in [-1, 1]:
                    ay = ry + adj
                    if ib(rx, ay) and bool(rm[ay, rx]):
                        return (Tool.ROAD, rx, ry)

    # ---- BUILD POWER+ROAD MAPS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    def pick_tool():
        # Target: 40% RES, 35% COM, 25% IND
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Prefer cells close to a road intersection (both road_xs and road_ys nearby)
        def dist_to_road_grid(cx_arr, cy_arr):
            # distance to nearest horizontal road
            h_dists = np.array([min(abs(cy - ry) for ry in road_ys) for cy in cy_arr])
            v_dists = np.array([min(abs(cx - rx) for rx in road_xs) for cx in cx_arr])
            return h_dists + v_dists

        scores = dist_to_road_grid(cxs, cys)
        order = np.argsort(scores)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 100)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx2, ry2 = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- NUCLEAR POWER (earlier: pop > 500) ----
    if pop > 500 and step % 2 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (15, 50), (105, 50), (60, 15), (60, 85),
            (45, 38), (75, 38), (45, 62), (75, 62),
            (20, 10), (100, 10), (20, 90), (100, 90),
            (60, 35), (60, 65), (35, 50), (85, 50),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(18, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(25, 22), (60, 22), (95, 22), (25, 52), (60, 52), (95, 52), (25, 82), (60, 82), (95, 82)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 96), (60, 4)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 5), (80, 5), (40, 93), (80, 93), (5, 40), (5, 60), (113, 40), (113, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 300 and step % 4 == 1:
        park_ys_arr, park_xs_arr = np.where(em & nbr_road & nbr_power)
        if len(park_xs_arr) > 0:
            idx = (step * 23) % len(park_xs_arr)
            py2, px2 = int(park_ys_arr[idx]), int(park_xs_arr[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant if no power nearby ----
    for px, py in active_plants:
        if not bool(nbr_power[py, px]):
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

