def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        # Target: 50% res, 30% com, 20% ind
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure power plants exist and are spaced well ---
    # Plant grid every 20 tiles
    plant_positions = []
    for py in range(15, 90, 20):
        for px in range(15, 110, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire expansion - connect unpowered areas reactively ---
    # Find tiles adjacent to existing power that are empty
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Find unpowered plants first
        unpowered_plants = [(px, py) for px, py in plant_positions
                            if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Connect wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered plant positions (future plants)
        unpowered_future = [(px, py) for px, py in plant_positions
                            if ib(px, py) and not bool(near_power[py, px])]
        if unpowered_future:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_future[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Road grid - dense grid every 6 tiles ---
    # Build roads reactively: only where power exists, connected to existing roads
    road_grid_targets = []
    for gy in range(6, 95, 6):
        for gx in range(6, 116, 6):
            road_grid_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:40]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Place road directly at target if empty
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement - reactive, close to roads and power ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: close to road, but also spread out from existing zones
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer spreading: penalize being too close to existing zones
            spread_bonus = np.clip(zone_dist, 0, 12)
        else:
            spread_bonus = np.zeros(len(cxs_arr))

        # Score: minimize road dist, maximize spread from zones
        score = road_dist * 2.0 - spread_bonus * 1.5

        order = np.argsort(score)

        # Pick tool based on ratios, with step-based cycling for variety
        tool = pick_tool()
        # Force variety: if ratios OK, cycle by step
        if tool == Tool.RESIDENTIAL:
            step_mod = step % 10
            if step_mod >= 7:
                tool = Tool.COMMERCIAL
            elif step_mod >= 9:
                tool = Tool.INDUSTRIAL

        off = (step * 17 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 100:
        fire_positions = [(fx, fy) for fy in range(10, 95, 12) for fx in range(10, 115, 12)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_positions = [(px2, py2) for py2 in range(12, 92, 15) for px2 in range(12, 112, 15)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_positions = [(pkx, pky) for pky in range(8, 95, 8) for pkx in range(8, 115, 8)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        stadium_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                        (60, 15), (60, 85), (15, 50), (105, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91),
                        (8, 30), (110, 30), (8, 65), (110, 65)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: extend roads from power plants ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plant at center + wire cross + flanking roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from center
    for d in range(1, 8):
        actions.append((Tool.WIRE, 60 + d, 50))
        actions.append((Tool.WIRE, 60 - d, 50))
        actions.append((Tool.WIRE, 60, 50 + d))
        actions.append((Tool.WIRE, 60, 50 - d))
    # Flanking roads along wire cross
    for d in range(-6, 7):
        actions.append((Tool.ROAD, 59, 50 + d))
        actions.append((Tool.ROAD, 61, 50 + d))
        actions.append((Tool.ROAD, 60 + d, 49))
        actions.append((Tool.ROAD, 60 + d, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Fast dilation using numpy shifts
    def dilate(mask, r):
        result = mask.astype(bool).copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 3)
    zone_tiles = resm | comm | indm

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30: return Tool.INDUSTRIAL
            if cr < 0.25: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.25: return Tool.INDUSTRIAL
            if cr < 0.28: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30: return Tool.COMMERCIAL
            if rr < 0.45: return Tool.RESIDENTIAL
            if ir < 0.20: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]): return False
        return True

    # --- NEIGHBORHOOD ANCHORS: distributed across map ---
    # Progressive unlock based on population
    all_hoods = [(x, y) for y in [15, 38, 62, 85] for x in [15, 35, 60, 85, 105]]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 3
        if pop < 300:  return 5
        if pop < 600:  return 8
        if pop < 1000: return 12
        if pop < 2000: return 15
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / n_active
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # --- PHASE 0: Ensure each active hood has a power plant nearby ---
    for hx, hy in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            # Place coal plant at or near hood center
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # --- PHASE 1: Extend wire from existing wire/plant toward uncovered hoods ---
    # Find hoods not yet near power
    for hx, hy in active_hoods:
        if not bool(near_power[hy, hx]):
            # Walk wire from nearest wire/plant toward hood
            wys, wxs = np.where(wm | pm)
            if len(wxs) > 0:
                dists = np.abs(wxs - hx) + np.abs(wys - hy)
                bi = np.argmin(dists)
                bwx, bwy = int(wxs[bi]), int(wys[bi])
                dx = 0 if hx == bwx else (1 if hx > bwx else -1)
                dy = 0 if hy == bwy else (1 if hy > bwy else -1)
                for nx, ny in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # --- PHASE 2: Wire horizontal and vertical spines for each active hood ---
    spine_range = 12
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Vertical spine at hx
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj in [-1, 1]:
            ay = wy + adj
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    # Horizontal spine at hy
    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj in [-1, 1]:
            ax = wx + adj
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # --- PHASE 3: Connect wires between nearby hoods ---
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 35:
                for cx in range(min(hx1, hx2) + 1, max(hx1, hx2)):
                    if not ib(cx, hy1): continue
                    if bool(wm[hy1, cx]) or bool(pm[hy1, cx]): continue
                    if not bool(em[hy1, cx]): continue
                    for adx in [-1, 1]:
                        ax = cx + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx, hy1)
            if hx1 == hx2 and abs(hy2 - hy1) <= 35:
                for cy in range(min(hy1, hy2) + 1, max(hy1, hy2)):
                    if not ib(hx1, cy): continue
                    if bool(wm[cy, hx1]) or bool(pm[cy, hx1]): continue
                    if not bool(em[cy, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy)

    # --- PHASE 4: Roads flanking wire spines ---
    for offset_r in [0, 1]:
        for rx_off in [-1, 1]:
            rx = hx + rx_off
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                    return (Tool.ROAD, rx, ry)
        for ry_off in [-1, 1]:
            ry = hy + ry_off
            if not ib(hx, ry): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry): continue
                if not bool(em[ry, rcx]) or bool(pm[ry, rcx]): continue
                if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                    return (Tool.ROAD, rcx, ry)

    # --- PHASE 5: Reactively wire unpowered zones ---
    unpowered_zones = zone_tiles & ~near_power
    uz_ys, uz_xs = np.where(unpowered_zones)
    if len(uz_xs) > 0:
        wys2, wxs2 = np.where(wm | pm)
        if len(wxs2) > 0:
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            dists = np.abs(wxs2 - tx) + np.abs(wys2 - ty)
            bi = np.argmin(dists)
            bwx, bwy = int(wxs2[bi]), int(wys2[bi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx, ny in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # --- PHASE 6: Reactively road unroaded zones ---
    unroaded_zones = zone_tiles & ~near_road
    uz_ys2, uz_xs2 = np.where(unroaded_zones)
    if len(uz_xs2) > 0:
        rys, rxs = np.where(rm)
        if len(rxs) > 0:
            idx = (step * 19) % len(uz_xs2)
            tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
            dists = np.abs(rxs - tx) + np.abs(rys - ty)
            bi = np.argmin(dists)
            brx, bry = int(rxs[bi]), int(rys[bi])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx, ny in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # --- PHASE 7: Extend roads into powered areas ---
    rys3, rxs3 = np.where(rm)
    if len(rxs3) > 0:
        sk = (step * 11) % len(rxs3)
        for off in range(min(len(rxs3), 150)):
            k = (sk + off * 7) % len(rxs3)
            rx2, ry2 = int(rxs3[k]), int(rys3[k])
            for ddx, ddy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + ddx, ry2 + ddy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(near_power[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # --- CIVIC SERVICES ---
    if pop > 50:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 18) for fy in range(10, WORLD_H, 18)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px, py) for px in range(12, WORLD_W, 22) for py in range(12, WORLD_H, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        for sx, sy in [(30, 25), (90, 25), (30, 75), (90, 75), (60, 50), (15, 50), (105, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [(15, 15), (105, 15), (15, 85), (105, 85), (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx, ny in nuke_spots:
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1500:
        for sx, sy in [(8, 90), (112, 90), (8, 10), (112, 10), (60, 95), (60, 5)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        for sx, sy in [(45, 6), (75, 6), (45, 93), (75, 93), (6, 45), (113, 45)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 7 == 3:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- ZONE PLACEMENT: closed-loop reactive ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for ahx, ahy in active_hoods:
            d = np.abs(cxs - ahx).astype(float) + np.abs(cys - ahy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- FALLBACK: extend wire from existing wire ---
    wys4, wxs4 = np.where(wm)
    if len(wxs4) > 0:
        sk2 = (step * 13) % len(wxs4)
        for off in range(min(len(wxs4), 100)):
            k = (sk2 + off * 5) % len(wxs4)
            wx2, wy2 = int(wxs4[k]), int(wys4[k])
            for ddx, ddy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2 + ddx, wy2 + ddy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    for dy in range(-4, 5):
        actions.append((Tool.ROAD, cx - 3, cy + dy))
        actions.append((Tool.ROAD, cx + 3, cy + dy))
    for dx in range(-4, 5):
        actions.append((Tool.ROAD, cx + dx, cy - 3))
        actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID ----
    # Spread across map in a grid pattern
    nh_cols = [15, 35, 55, 75, 95, 110]
    nh_rows = [15, 32, 50, 68, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:   return 2
        if pop < 150:  return 4
        if pop < 300:  return 7
        if pop < 600:  return 12
        if pop < 1000: return 18
        if pop < 2000: return 24
        if pop < 4000: return 30
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and funds > 400:
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES from plants to hoods ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        for (hx, hy) in active_hoods:
            wx0, wx1 = max(0, hx - 3), min(WORLD_W, hx + 4)
            wy0, wy1 = max(0, hy - 3), min(WORLD_H, hy + 4)
            has_wire = bool(np.any(wm[wy0:wy1, wx0:wx1])) or bool(np.any(pm[wy0:wy1, wx0:wx1]))
            if has_wire:
                continue
            col_tiles = [r for r in range(WORLD_H) if ib(hx, r) and (bool(wm[r, hx]) or bool(pm[r, hx]))]
            if col_tiles:
                if hy > max(col_tiles):
                    nr = max(col_tiles) + 1
                    if ib(hx, nr) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)
                elif hy < min(col_tiles):
                    nr = min(col_tiles) - 1
                    if ib(hx, nr) and bool(em[nr, hx]):
                        return (Tool.WIRE, hx, nr)
            row_tiles = [c for c in range(WORLD_W) if ib(c, hy) and (bool(wm[hy, c]) or bool(pm[hy, c]))]
            if row_tiles:
                if hx > max(row_tiles):
                    nc = max(row_tiles) + 1
                    if ib(nc, hy) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)
                elif hx < min(row_tiles):
                    nc = min(row_tiles) - 1
                    if ib(nc, hy) and bool(em[hy, nc]):
                        return (Tool.WIRE, nc, hy)

    # ---- PHASE 3: EXTEND WIRE SPINES ----
    spine_range = 18
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 4: CONNECT ADJACENT HOODS WITH WIRES ----
    for i_h, (hx1, hy1) in enumerate(active_hoods):
        for j_h, (hx2, hy2) in enumerate(active_hoods):
            if j_h <= i_h: continue
            if hy1 == hy2 and 0 < hx2 - hx1 <= 25:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and 0 < hy2 - hy1 <= 25:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 5: ROADS flanking wire spines ----
    road_hood_idx = (step + len(active_hoods) // 2) % max(len(active_hoods), 1)
    rhx, rhy = active_hoods[road_hood_idx]

    for rx in [rhx - 3, rhx + 3]:
        if not ib(rx, rhy): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = rhy + dy
            if not ib(rx, ry): continue
            if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                if bool(wm[ry, rhx]) or bool(pm[ry, rhx]):
                    return (Tool.ROAD, rx, ry)

    for ry2 in [rhy - 3, rhy + 3]:
        if not ib(rhx, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = rhx + dx
            if not ib(rcx, ry2): continue
            if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                if bool(wm[rhy, rcx]) or bool(pm[rhy, rcx]):
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 6: ZONE PLACEMENT ----
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25: return Tool.INDUSTRIAL
        if cr < 0.25: return Tool.COMMERCIAL
        if rr < 0.50: return Tool.RESIDENTIAL
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (within 4 tiles of wire/plant)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx_a, hy_a) in active_hoods:
            d = np.abs(cxs - hx_a) + np.abs(cys - hy_a)
            best_dist = np.minimum(best_dist, d)

        # Zone clustering bonus
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS FROM EXISTING NETWORK ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(14, WORLD_W - 4, 18)
                      for fy in range(14, WORLD_H - 4, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W - 4, 22)
                        for py2 in range(20, WORLD_H - 4, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(30, 25), (60, 15), (90, 25),
                    (20, 50), (100, 50),
                    (30, 75), (60, 85), (90, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 800 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (40, 25), (80, 25), (40, 75), (80, 75),
            (25, 50), (95, 50),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 8), min(WORLD_W, npx + 9)
            y0b, y1b = max(0, npy - 8), min(WORLD_H, npy + 9)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 700:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1500:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        sk = (step * 11) % len(pxs2)
        for offset in range(min(len(pxs2), 60)):
            k = (sk + offset * 7) % len(pxs2)
            px2, py2 = int(pxs2[k]), int(pys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plant + wire cross + initial road ring"""
    actions = []
    # Coal plant at center
    actions.append((Tool.COALPOWER, 58, 50))
    # Wire horizontal from plant
    for x in range(59, 80):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertical from plant
    for y in range(40, 61):
        actions.append((Tool.WIRE, 58, y))
    # Nuclear plant to the right
    actions.append((Tool.NUCLEARPOWER, 80, 50))
    # Initial road ring (3x3 clearance around plants avoided)
    for x in range(50, 70):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    for y in range(45, 56):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 69, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    cx, cy = 58, 50  # center / power hub

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # --- Compute neighbor masks for road and power ---
    # nbr_road: any road tile within 2 cells
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # nbr_power: wire or plant within 5 cells
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Distance from center
    ys_arr = np.arange(WORLD_H).reshape(-1, 1)
    xs_arr = np.arange(WORLD_W).reshape(1, -1)
    dist_map = np.abs(ys_arr - cy) + np.abs(xs_arr - cx)

    # Zone counts
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    plant_count = int(np.sum(pm))

    # Active radius grows with population
    if pop < 200:
        max_radius = 20
    elif pop < 800:
        max_radius = 35
    elif pop < 2000:
        max_radius = 55
    else:
        max_radius = 75

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Need industry early for jobs
        if pop < 300 and ir < 0.35:
            return Tool.INDUSTRIAL
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # === PHASE 1: Ensure adequate power plants ===
    # Reactively add plants when population grows
    if pop > 300 and plant_count < 2:
        for px, py in [(35, 50), (80, 30), (80, 70), (35, 30), (35, 70)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 1000 and plant_count < 4:
        for px, py in [(30, 50), (90, 50), (58, 20), (58, 80)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 3000 and plant_count < 6:
        for px, py in [(20, 25), (100, 25), (20, 75), (100, 75), (58, 10), (58, 90)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    # === PHASE 2: Wire extension (reactive - extend from existing power) ===
    # Build wire grid: horizontal every 4 rows, vertical every 5 cols
    # Only extend wire where it connects to existing power
    if step % 3 == 0:
        # Key wire corridors
        wire_rows = [25, 30, 35, 40, 45, 50, 55, 60, 65, 70, 75]
        wire_cols = [30, 35, 40, 45, 50, 55, 58, 60, 65, 70, 75, 80, 85, 90]

        # Horizontal wire lines
        for wy in wire_rows:
            if abs(wy - cy) > max_radius + 5:
                continue
            # Scan left from center
            for wx in range(cx, max(1, cx - max_radius - 10), -1):
                if not ib(wx, wy): continue
                if bool(pm[wy, wx]) or bool(wm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    # Check if adjacent to power
                    adj_pow = False
                    for dx in [1, -1]:
                        ax = wx + dx
                        if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                            adj_pow = True
                    if adj_pow:
                        return (Tool.WIRE, wx, wy)
                elif not bool(pm[wy, wx]):
                    break
            # Scan right from center
            for wx in range(cx, min(WORLD_W - 1, cx + max_radius + 10)):
                if not ib(wx, wy): continue
                if bool(pm[wy, wx]) or bool(wm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    adj_pow = False
                    for dx in [1, -1]:
                        ax = wx + dx
                        if ib(ax, wy) and (bool(wm[wy, ax]) or bool(pm[wy, ax])):
                            adj_pow = True
                    if adj_pow:
                        return (Tool.WIRE, wx, wy)
                elif not bool(pm[wy, wx]):
                    break

    elif step % 3 == 1:
        # Vertical wire lines
        wire_cols_v = [30, 40, 50, 58, 65, 75, 85, 95]
        for wx in wire_cols_v:
            if abs(wx - cx) > max_radius + 5:
                continue
            for wy in range(cy, max(1, cy - max_radius - 10), -1):
                if not ib(wx, wy): continue
                if bool(pm[wy, wx]) or bool(wm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    adj_pow = False
                    for dy in [1, -1]:
                        ay = wy + dy
                        if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                            adj_pow = True
                    if adj_pow:
                        return (Tool.WIRE, wx, wy)
                elif not bool(pm[wy, wx]):
                    break
            for wy in range(cy, min(WORLD_H - 1, cy + max_radius + 10)):
                if not ib(wx, wy): continue
                if bool(pm[wy, wx]) or bool(wm[wy, wx]):
                    continue
                if bool(em[wy, wx]):
                    adj_pow = False
                    for dy in [1, -1]:
                        ay = wy + dy
                        if ib(wx, ay) and (bool(wm[ay, wx]) or bool(pm[ay, wx])):
                            adj_pow = True
                    if adj_pow:
                        return (Tool.WIRE, wx, wy)
                elif not bool(pm[wy, wx]):
                    break

    # === PHASE 3: Road network (reactive grid) ===
    # Horizontal roads every 4 rows
    if step % 3 == 2:
        road_ys = list(range(28, 73, 4))
        for ry in road_ys:
            if abs(ry - cy) > max_radius:
                continue
            # Extend road from center outward, connecting to existing roads
            for rx in range(cx, min(WORLD_W - 1, cx + max_radius)):
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]): continue
                if bool(pm[ry, rx]): break
                if bool(em[ry, rx]):
                    # adjacent road?
                    adj = any(ib(rx+dx, ry) and bool(rm[ry, rx+dx]) for dx in [-1, 1])
                    adj |= any(ib(rx, ry+dy) and bool(rm[ry+dy, rx]) for dy in [-1, 1])
                    if adj or rx == cx:
                        return (Tool.ROAD, rx, ry)
                else:
                    break
            for rx in range(cx, max(1, cx - max_radius), -1):
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]): continue
                if bool(pm[ry, rx]): break
                if bool(em[ry, rx]):
                    adj = any(ib(rx+dx, ry) and bool(rm[ry, rx+dx]) for dx in [-1, 1])
                    adj |= any(ib(rx, ry+dy) and bool(rm[ry+dy, rx]) for dy in [-1, 1])
                    if adj or rx == cx:
                        return (Tool.ROAD, rx, ry)
                else:
                    break

        # Vertical roads every 5 cols
        road_xs = list(range(33, 86, 5))
        for rxc in road_xs:
            if abs(rxc - cx) > max_radius:
                continue
            for ry in range(cy, min(WORLD_H - 1, cy + max_radius)):
                if not ib(rxc, ry): continue
                if bool(rm[ry, rxc]): continue
                if bool(pm[ry, rxc]): break
                if bool(em[ry, rxc]):
                    adj = any(ib(rxc, ry+dy) and bool(rm[ry+dy, rxc]) for dy in [-1, 1])
                    adj |= any(ib(rxc+dx, ry) and bool(rm[ry, rxc+dx]) for dx in [-1, 1])
                    if adj or ry == cy:
                        return (Tool.ROAD, rxc, ry)
                else:
                    break
            for ry in range(cy, max(1, cy - max_radius), -1):
                if not ib(rxc, ry): continue
                if bool(rm[ry, rxc]): continue
                if bool(pm[ry, rxc]): break
                if bool(em[ry, rxc]):
                    adj = any(ib(rxc, ry+dy) and bool(rm[ry+dy, rxc]) for dy in [-1, 1])
                    adj |= any(ib(rxc+dx, ry) and bool(rm[ry, rxc+dx]) for dx in [-1, 1])
                    if adj or ry == cy:
                        return (Tool.ROAD, rxc, ry)
                else:
                    break

    # === PHASE 4: Zone placement (primary action) ===
    # Find candidates: empty, near road, near power, within radius
    cand_mask = (em & nbr_road & nbr_power &
                 (dist_map <= max_radius) &
                 ~pm)
    # Safety margins
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        dists = dist_map[cys_arr, cxs_arr]
        order = np.argsort(dists)
        tool = pick_tool()
        # Vary starting point to avoid always hitting same spot
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: Civic services (reactive to population) ===
    if pop > 100:
        fire_spots = [
            (48, 38), (72, 38), (48, 62), (72, 62),
            (58, 32), (58, 68), (38, 50), (82, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (52, 42), (68, 42), (52, 58), (68, 58),
            (42, 50), (78, 50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for sx, sy in [(55, 47), (63, 47), (55, 53), (63, 53)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for sx, sy in [(10, 88), (110, 88), (10, 12), (110, 12)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for sx, sy in [(15, 50), (105, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks boost land value reactively
    if pop > 200 and step % 8 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # === FALLBACK: extend road from any existing road ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 100)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            if dist_map[ry2, rx2] > max_radius + 5:
                continue
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if bool(nbr_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # Fallback: extend wire from existing power
    pow_ys, pow_xs = np.where(wm | pm)
    if len(pow_xs) > 0:
        sk2 = (step * 13) % len(pow_xs)
        for off in range(min(len(pow_xs), 80)):
            k = (sk2 + off * 5) % len(pow_xs)
            wx2, wy2 = int(pow_xs[k]), int(pow_ys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2 + dx, wy2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if dist_map[ny, nx] <= max_radius + 15:
                        return (Tool.WIRE, nx, ny)

    # Emergency: place coal if no power near center
    if not bool(nbr_power[cy, cx]):
        for r in range(1, 10):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = cx+dx, cy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
