def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire grid rows/cols - denser than parent for better coverage
    wire_rows = [8, 16, 24, 32, 40, 50, 58, 66, 74, 82, 90]
    wire_cols = [8, 18, 28, 38, 48, 60, 72, 82, 92, 102, 112]

    # Road rows/cols adjacent to wire rows (offset by ±1)
    road_offsets = [-1, 1]

    phase = step % 10

    # Phase 0: Ensure power plants where power is lacking near roads
    if phase == 0:
        no_power_road = rm & ~near_power
        np_ys, np_xs = np.where(no_power_road)
        if len(np_xs) > 0:
            cx = int(np.mean(np_xs))
            cy = int(np.mean(np_ys))
            for r in range(0, 10):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = cx+dx, cy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # Phase 1: Fill wire row gaps (reactive: only fill adjacent to existing wire/plant)
    if phase == 1:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H-1):
                continue
            for wx in range(1, WORLD_W-1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left_ok = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right_ok = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left_ok or right_ok:
                        if bool(em[wr, wx]) or bool(rm[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W-1):
                continue
            for wy in range(1, WORLD_H-1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up_ok = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn_ok = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up_ok or dn_ok:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # Phase 3: Build road rows adjacent to wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H-1):
                    continue
                for rx in range(1, WORLD_W-1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        wire_nearby = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   bool(rm[max(0,ry-1), rx]) or bool(rm[min(WORLD_H-1,ry+1), rx])
                        if wire_nearby and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Build road cols adjacent to wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W-1):
                    continue
                for ry in range(1, WORLD_H-1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        wire_nearby = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = bool(rm[max(0,ry-1), rcx]) or bool(rm[min(WORLD_H-1,ry+1), rcx]) or \
                                   bool(rm[ry, max(0, rcx-1)]) or bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if wire_nearby and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # Phase 5: Connect road grid with cross-roads (horizontal)
    if phase == 5:
        for ci in range(len(wire_cols)-1):
            c1, c2 = wire_cols[ci], wire_cols[ci+1]
            for wri in range(len(wire_rows)-1):
                r1, r2 = wire_rows[wri], wire_rows[wri+1]
                mid_y = (r1 + r2) // 2
                for rx in range(c1+2, c2-1):
                    if bool(em[mid_y, rx]) and not bool(pm[mid_y, rx]):
                        adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                              (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                        if adj and bool(near_power[mid_y, rx]):
                            return (Tool.ROAD, rx, mid_y)

    # Phase 6: Connect road grid with cross-roads (vertical)
    if phase == 6:
        for wi in range(len(wire_rows)-1):
            r1, r2 = wire_rows[wi], wire_rows[wi+1]
            for wci in range(len(wire_cols)-1):
                c1, c2 = wire_cols[wci], wire_cols[wci+1]
                mid_x = (c1 + c2) // 2
                for ry in range(r1+2, r2-1):
                    if bool(em[ry, mid_x]) and not bool(pm[ry, mid_x]):
                        adj = (ry > 0 and bool(rm[ry-1, mid_x])) or \
                              (ry < WORLD_H-1 and bool(rm[ry+1, mid_x]))
                        if adj and bool(near_power[ry, mid_x]):
                            return (Tool.ROAD, mid_x, ry)

    # Phase 7: Wire unpowered zones reactively
    if phase == 7:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best = np.argmin(dists)
                bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx, ny in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # Phase 8: Wire unpowered roads
    if phase == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys2, wire_xs2 = np.where(wm | pm)
            if len(wire_xs2) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
                best = np.argmin(dists)
                bwx, bwy = int(wire_xs2[best]), int(wire_ys2[best])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx, ny in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # ---- CIVIC SERVICES (reactive on pop thresholds) ----
    if pop > 20:
        fire_spots = [
            (5,5),(115,5),(5,95),(115,95),
            (30,5),(90,5),(30,95),(90,95),
            (5,30),(115,30),(5,70),(115,70),
            (5,50),(115,50),
            (30,25),(90,25),(30,75),(90,75),
            (60,15),(60,85),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (20,12),(50,12),(80,12),(110,12),
            (20,35),(50,35),(80,35),(110,35),
            (20,55),(50,55),(80,55),(110,55),
            (20,78),(50,78),(80,78),(110,78),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (25,20),(85,20),(25,80),(85,80),
            (55,12),(100,12),(55,88),(100,88),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        # Upgrade to nuclear for higher capacity
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
            (30,50),(90,50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for sx, sy in [(5,92),(115,92),(5,8),(115,8)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        for sx, sy in [(50,5),(70,5),(50,92),(70,92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks boost land value when we have population
    if pop > 300 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- PRIMARY ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors themselves (zone clearance)
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Adaptive density: finer grid as city grows
        if pop < 200:
            step_size = 8
        elif pop < 800:
            step_size = 6
        elif pop < 2000:
            step_size = 4
        else:
            step_size = 3

        active_centers = [(cx, cy) for cy in range(5, WORLD_H-5, step_size)
                                    for cx in range(5, WORLD_W-5, step_size)]
        if not active_centers:
            active_centers = [(60, 50)]

        # Prefer candidates near target zone centers
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

