def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.28:
                return Tool.INDUSTRIAL
            if cr < 0.22:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.32:
                return Tool.COMMERCIAL
            if rr < 0.48:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PRIORITY 1: Fix unpowered zones — extend wire toward them ===
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        uz_ys, uz_xs = np.where(unpowered_zones)
        wire_ys, wire_xs = np.where(power_src)
        if len(wire_xs) > 0 and len(uz_xs) > 0:
            tidx = (step * 7) % len(uz_xs)
            tx, ty = int(uz_xs[tidx]), int(uz_ys[tidx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best = np.argmin(dists)
            bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === PRIORITY 2: Fix zones with no road access ===
    zones_no_road = zone_tiles & ~near_road
    if np.any(zones_no_road):
        zr_ys, zr_xs = np.where(zones_no_road)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0 and len(zr_xs) > 0:
            tidx = (step * 11) % len(zr_xs)
            tx, ty = int(zr_xs[tidx]), int(zr_ys[tidx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best = np.argmin(dists)
            brx, bry = int(road_xs[best]), int(road_ys[best])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    phase = step % 8

    # === PHASE 0: Extend horizontal wire rows ===
    if phase == 0:
        target_rows = [15, 25, 35, 50, 65, 75, 85]
        for wr in target_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1])))
                    right = (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    # === PHASE 1: Extend vertical wire columns ===
    elif phase == 1:
        target_cols = [15, 30, 45, 60, 75, 90, 105]
        for wc in target_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc])))
                    dn = (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # === PHASE 2: Roads flanking horizontal wire rows ===
    elif phase == 2:
        target_rows = [15, 25, 35, 50, 65, 75, 85]
        for wr in target_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # === PHASE 3: Roads flanking vertical wire columns ===
    elif phase == 3:
        target_cols = [15, 30, 45, 60, 75, 90, 105]
        for wc in target_cols:
            for offset in [-1, 1]:
                cx = wc + offset
                if not (0 < cx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, cx]):
                        return (Tool.ROAD, cx, ry)

    # === PHASE 4: Place power plants where needed ===
    elif phase == 4:
        plant_candidates = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 35), (45, 35), (75, 35), (105, 35),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 85), (45, 85), (75, 85), (105, 85),
            (30, 50), (60, 50), (90, 50),
        ]
        for ppx, ppy in plant_candidates:
            x0, x1 = max(0, ppx - 15), min(WORLD_W, ppx + 15)
            y0, y1 = max(0, ppy - 15), min(WORLD_H, ppy + 15)
            if not np.any(pm[y0:y1, x0:x1]):
                wire_in_region = bool(np.any(power_src[y0:y1, x0:x1]))
                zone_in_region = bool(np.any(zone_tiles[y0:y1, x0:x1]))
                if wire_in_region or zone_in_region:
                    for r in range(0, 7):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = ppx + dx, ppy + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 5: Civic services ===
    elif phase == 5:
        if pop > 30:
            fire_spots = [
                (6, 6), (113, 6), (6, 93), (113, 93),
                (35, 6), (65, 6), (95, 6),
                (6, 30), (113, 30), (6, 70), (113, 70),
                (35, 93), (65, 93), (95, 93),
                (35, 50), (65, 50), (95, 50),
            ]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 150:
            police_spots = [
                (20, 20), (50, 20), (80, 20), (110, 20),
                (20, 40), (50, 40), (80, 40), (110, 40),
                (20, 60), (50, 60), (80, 60), (110, 60),
                (20, 80), (50, 80), (80, 80), (110, 80),
            ]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadium_spots = [(30, 20), (90, 20), (30, 80), (90, 80),
                             (60, 50), (15, 50), (105, 50)]
            for sx, sy in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [
                (10, 10), (110, 10), (10, 90), (110, 90),
                (60, 10), (60, 90), (10, 50), (110, 50),
                (35, 15), (85, 15), (35, 85), (85, 85),
            ]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2-6), min(WORLD_W, nx2+7)
                    y0, y1 = max(0, ny2-6), min(WORLD_H, ny2+7)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            seaports = [(5, 94), (114, 94), (5, 5), (114, 5), (60, 94)]
            for sx, sy in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2500:
            airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # === PHASE 6: Parks for land value ===
    elif phase == 6:
        if pop > 100:
            park_cands = em & near_road & near_power
            pys, pxs = np.where(park_cands)
            if len(pxs) > 0:
                idx = (step * 31 + pop) % len(pxs)
                return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # === PHASE 7: Extend road grid into powered areas ===
    elif phase == 7:
        road_grid_targets = []
        for gy in range(6, 97, 6):
            for gx in range(6, 115, 6):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))
        if road_grid_targets:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted
            road_cand = em & adj_to_road & near_power & ~zone_tiles
            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                best_dist3 = 1e9
                best_k3 = 0
                targets_sample = road_grid_targets[:30]
                for i in range(min(len(rxs2), 300)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist3:
                        best_dist3 = d
                        best_k3 = i
                return (Tool.ROAD, int(rxs2[best_k3]), int(rys2[best_k3]))

    # === MAIN ZONE PLACEMENT (all phases fall through here) ===
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            # prefer center of existing zone cluster
            zone_cx = float(np.mean(zone_xs2))
            zone_cy = float(np.mean(zone_ys2))
            dist_to_center = np.abs(cxs_arr - zone_cx) + np.abs(cys_arr - zone_cy)
            # Penalize too-close placement (avoid stacking)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Score: close to road, near cluster center, not on top of zones
            score = road_dist * 1.0 + dist_to_center * 0.3 + np.maximum(0, 6 - zone_dist) * 2.0
        else:
            dist_center = np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)
            score = road_dist * 1.0 + dist_center * 0.3

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 80)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire + road grid starter."""
    actions = []
    # Plant 1 at left cluster center
    cx1, cy1 = 30, 50
    actions.append((Tool.COALPOWER, cx1, cy1))
    # Wire horizontally from plant 1
    for dx in range(-3, 4):
        if dx != 0:
            actions.append((Tool.WIRE, cx1 + dx, cy1))
    # Wire vertically from plant 1
    for dy in range(-3, 4):
        if dy != 0:
            actions.append((Tool.WIRE, cx1, cy1 + dy))
    # Plant 2 at right cluster center
    cx2, cy2 = 85, 50
    actions.append((Tool.COALPOWER, cx2, cy2))
    for dx in range(-3, 4):
        if dx != 0:
            actions.append((Tool.WIRE, cx2 + dx, cy2))
    for dy in range(-3, 4):
        if dy != 0:
            actions.append((Tool.WIRE, cx2, cy2 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # Grid-based neighborhood anchors: 6 columns x 5 rows = 30 neighborhoods
    # Offset columns so wire spines don't overlap zone columns
    anchors = []
    col_xs = [15, 30, 50, 70, 90, 108]
    row_ys = [15, 30, 50, 68, 85]
    for ci, cx in enumerate(col_xs):
        for ri, cy in enumerate(row_ys):
            anchors.append((cx, cy, ci * len(row_ys) + ri))

    def num_active():
        if pop < 50:    return 2
        if pop < 200:   return 4
        if pop < 500:   return 6
        if pop < 1000:  return 10
        if pop < 2000:  return 16
        if pop < 3500:  return 22
        return 30

    active = anchors[:num_active()]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    for (px, py, idx) in active:
        has_plant = False
        for dx in range(-6, 7):
            for dy in range(-6, 7):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: GROW WIRE TOWARD ACTIVE ANCHORS ----
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0:
        for (px, py, idx) in active:
            dists = np.abs(wire_xs.astype(float) - px) + np.abs(wire_ys.astype(float) - py)
            min_dist = float(dists.min())
            if min_dist > 4:
                closest_k = int(np.argmin(dists))
                wx, wy = int(wire_xs[closest_k]), int(wire_ys[closest_k])
                dx = 1 if px > wx else (-1 if px < wx else 0)
                dy = 1 if py > wy else (-1 if py < wy else 0)
                for (ddx, ddy) in [(dx, 0), (0, dy), (dx, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: EXTEND WIRE VERTICALLY FOR EACH ANCHOR SPINE ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            for dy in range(-5, 6):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            min_wr = min(wire_col)
            max_wr = max(wire_col)
            ext = min(20, 6 + pop // 100)
            spine_top = max(2, py - ext)
            spine_bot = min(WORLD_H - 3, py + ext)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 4: HORIZONTAL WIRE CONNECTIONS between adjacent anchors same row ----
    row_groups = {}
    for (px, py, idx) in active:
        key = py
        if key not in row_groups:
            row_groups[key] = []
        row_groups[key].append(px)

    for row_y, group in row_groups.items():
        group_sorted = sorted(group)
        for i in range(len(group_sorted) - 1):
            x1, x2 = group_sorted[i], group_sorted[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- PHASE 5: BUILD ROAD GRID flanking wire spines ----
    # Use 2 road columns on each side of wire spine
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            continue
        # Roads at px-1 and px+1 (adjacent) and horizontal roads at anchor row
        cycle_off = (step + idx * 13) % max(len(wire_col), 1)
        for k in range(min(len(wire_col), 8)):
            wr = wire_col[(cycle_off + k) % len(wire_col)]
            for side in [px - 1, px + 1]:
                if ib(side, wr) and bool(em[wr, side]) and not bool(pm[wr, side]):
                    return (Tool.ROAD, side, wr)

    # ---- PHASE 6: HORIZONTAL ROADS connecting neighborhoods ----
    for (px, py, idx) in active:
        # Horizontal road at anchor row
        for dx in range(-12, 13):
            rx = px + dx
            if not ib(rx, py):
                continue
            if bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near = any(
                    ib(rx + d, py) and (bool(rm[py, rx + d]) or bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near:
                    return (Tool.ROAD, rx, py)

    # ---- PHASE 7: ZONE PLACEMENT with balanced RCI mix ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% residential, 25% commercial, 25% industrial
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        if rr < 0.50:
            return Tool.RESIDENTIAL
        # Cycle through extras
        choice = (step // 3) % 3
        return [Tool.RESIDENTIAL, Tool.COMMERCIAL, Tool.INDUSTRIAL][choice]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, idx) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 8: EXTEND ROADS along existing roads toward wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 7) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 9) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 100:
        firestations = [
            (22, 22), (45, 22), (68, 22), (95, 22),
            (22, 42), (45, 42), (68, 42), (95, 42),
            (22, 62), (45, 62), (68, 62), (95, 62),
            (22, 80), (45, 80), (68, 80), (95, 80),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        polices = [
            (35, 32), (60, 32), (85, 32),
            (35, 55), (60, 55), (85, 55),
            (35, 75), (60, 75), (85, 75),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 900:
        stadiums = [
            (25, 10), (65, 10), (105, 10),
            (25, 90), (65, 90), (105, 90),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- PHASE 10: NUCLEAR PLANT for high pop ----
    if pop > 2000:
        nuke_spots = [
            (55, 50), (25, 25), (95, 25), (25, 75), (95, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- FALLBACK: Extend wire from any wire tile ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 11) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 50)):
            k = (step_k2 + offset * 7) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: three coal plants forming a triangle + wire spines + roads."""
    actions = []
    # Three plants: top-left, top-right, bottom-center
    plants = [(25, 20), (95, 20), (60, 75)]
    for (cx, cy) in plants:
        actions.append((Tool.COALPOWER, cx, cy))
        # Wire cross from each plant
        for dx in range(-8, 9):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking vertical wire
        for dy in range(-7, 8):
            actions.append((Tool.ROAD, cx - 3, cy + dy))
            actions.append((Tool.ROAD, cx + 3, cy + dy))
        # Roads flanking horizontal wire
        for dx in range(-7, 8):
            actions.append((Tool.ROAD, cx + dx, cy - 3))
            actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Denser grid of neighborhoods: 6 cols x 5 rows = 30 hoods
    all_hoods = []
    for hy in range(12, 95, 17):
        for hx in range(12, 115, 17):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:   return 4
        if pop < 150:  return 8
        if pop < 400:  return 14
        if pop < 800:  return 20
        if pop < 1500: return 26
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: ENSURE POWER PLANTS near every active hood ===
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
            y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 16):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE CONNECTIONS between plants and hoods ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 14

    x0p, x1p = max(0, hx - 18), min(WORLD_W, hx + 19)
    y0p, y1p = max(0, hy - 18), min(WORLD_H, hy + 19)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0
        best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d
                best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)

        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spines
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        min_wr, max_wr = min(col_wire), max(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        min_wc, max_wc = min(row_wire), max(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: ROADS flanking wire spines ===
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 4
    # Roads at offset 2 and 4 from wire for denser zones
    for rx in [hx3 - 2, hx3 + 2, hx3 - 4, hx3 + 4]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::4]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 2, hy3 + 2, hy3 - 4, hy3 + 4]:
        if not ib(hx3, ry): continue
        cyc2 = (step + 2) % 4
        for wc in row_wire3[cyc2::4]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # === PHASE 4: INTER-HOOD ROAD CONNECTIONS ===
    if step % 4 < 2:
        for i, (hx1, hy1) in enumerate(active_hoods):
            for (hx2, hy2) in active_hoods[i+1:]:
                dist = abs(hx1-hx2) + abs(hy1-hy2)
                if dist > 30: continue
                if abs(hy1 - hy2) <= 4:
                    mid_y = (hy1 + hy2) // 2
                    step_conn = step % max(abs(hx2-hx1), 1)
                    cx2 = min(hx1, hx2) + step_conn
                    if ib(cx2, mid_y) and bool(em[mid_y, cx2]) and not bool(pm[mid_y, cx2]):
                        if not bool(rm[mid_y, cx2]):
                            return (Tool.ROAD, cx2, mid_y)
                if abs(hx1 - hx2) <= 4:
                    mid_x = (hx1 + hx2) // 2
                    step_conn = step % max(abs(hy2-hy1), 1)
                    cy2 = min(hy1, hy2) + step_conn
                    if ib(mid_x, cy2) and bool(em[cy2, mid_x]) and not bool(pm[cy2, mid_x]):
                        if not bool(rm[cy2, mid_x]):
                            return (Tool.ROAD, mid_x, cy2)

    # === PHASE 5: ZONE PLACEMENT - heavy commercial/industrial bias ===
    def pick_tool():
        # Target mix: 35% RES, 35% COM, 30% IND
        # Commercial and industrial drive population through demand
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Dynamic: early game more industrial, mid more commercial, later balanced
        if pop < 200:
            if ir < 0.35: return Tool.INDUSTRIAL
            if cr < 0.35: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if cr < 0.38: return Tool.COMMERCIAL
            if ir < 0.30: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35: return Tool.COMMERCIAL
            if ir < 0.28: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4) + np.abs(cys - hy4)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                # Less clustering than parent to spread zones
                score = best_dist * 0.6 + zone_prox * 0.4
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 11 + pop * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 6: EXTEND ROADS FROM EXISTING NETWORK ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 7: CIVIC SERVICES ===
    if pop > 15:
        fire_grid = [(fx, fy) for fy in range(10, 95, 12)
                     for fx in range(10, 115, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_grid = [(px2, py2) for py2 in range(14, 92, 14)
                       for px2 in range(14, 112, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 120 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 19) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 200:
        stadium_locs = [
            (20, 15), (60, 10), (100, 15),
            (20, 85), (60, 90), (100, 85),
            (10, 50), (110, 50), (60, 50),
            (35, 30), (85, 30), (35, 70), (85, 70),
            (40, 50), (80, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear plants: placed earlier than parent (pop > 400)
    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 15), (85, 15), (35, 85), (85, 85),
            (20, 45), (100, 45), (20, 55), (100, 55),
            (45, 8), (75, 8), (45, 92), (75, 92),
            (15, 25), (105, 25), (15, 75), (105, 75),
            (50, 30), (70, 30), (50, 70), (70, 70),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 300:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 93), (5, 45), (113, 45)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === PHASE 8: WIRE CONNECTIONS between hoods ===
    for i, (hx1, hy1) in enumerate(active_hoods):
        for (hx2, hy2) in active_hoods[i+1:]:
            if abs(hx1-hx2) + abs(hy1-hy2) > 35: continue
            if abs(hy1 - hy2) <= 4:
                mid_y = (hy1 + hy2) // 2
                for cx3 in range(min(hx1,hx2)+1, max(hx1,hx2)):
                    if ib(cx3, mid_y) and bool(em[mid_y, cx3]) and not bool(pm[mid_y, cx3]):
                        if not bool(wm[mid_y, cx3]):
                            return (Tool.WIRE, cx3, mid_y)
            if abs(hx1 - hx2) <= 4:
                mid_x = (hx1 + hx2) // 2
                for cy3 in range(min(hy1,hy2)+1, max(hy1,hy2)):
                    if ib(mid_x, cy3) and bool(em[cy3, mid_x]) and not bool(pm[cy3, mid_x]):
                        if not bool(wm[cy3, mid_x]):
                            return (Tool.WIRE, mid_x, cy3)

    # === FALLBACK: extend wire from plants ===
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 80)):
            k = (sk + offset * 7) % len(pxs)
            px3, py3 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0),(0,2),(0,-2),(2,0),(-2,0)]:
                nx3, ny3 = px3 + dx2, py3 + dy2
                if ib(nx3, ny3) and bool(em[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 17) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 100)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 18):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    if pop > 1000 and step % 3 == 0 and funds > 5000:
        nuc_spots = [(30, 30), (90, 30), (30, 70), (90, 70),
                     (60, 50), (15, 15), (105, 15), (15, 85), (105, 85)]
        for nx6, ny6 in nuc_spots:
            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                return (Tool.NUCLEARPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire grid + flanking roads."""
    actions = []
    # Four coal plants at strategic positions
    for px, py in [(30, 50), (90, 50), (60, 20), (60, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [20, 35, 50, 65, 80]:
        for x in range(2, 118):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 40, 60, 80, 100]:
        for y in range(2, 98):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows
    for wy in [20, 35, 50, 65, 80]:
        for x in range(2, 118):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 300:
            if ir < 0.28:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1200:
            if ir < 0.22:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.48:
                return Tool.RESIDENTIAL
            return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 5

    # Phase 0: Fix wire gaps on key rows/cols (reactive)
    if phase == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = wy2 > 0 and (bool(wm[wy2-1, wc]) or bool(pm[wy2-1, wc]))
                    dn = wy2 < WORLD_H-1 and (bool(wm[wy2+1, wc]) or bool(pm[wy2+1, wc]))
                    if (up or dn) and bool(em[wy2, wc]):
                        return (Tool.WIRE, wc, wy2)

    # Phase 1: Fix road gaps flanking wire rows (reactive)
    if phase == 1:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and (bool(wm[wr, rx]) or bool(pm[wr, rx])):
                        adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                               (ry > 0 and bool(rm[ry-1, rx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                        if adj or rx <= 2:
                            return (Tool.ROAD, rx, ry)

    # Phase 2: Fix unpowered zones by extending wire
    if phase == 2:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                sample = min(len(uz_xs), 20)
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # Phase 3: Fix zones without road access
    if phase == 3:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 4: Power plant placement if region unpowered
    if phase == 4:
        for py2 in range(10, WORLD_H - 10, 20):
            for px2 in range(10, WORLD_W - 10, 20):
                x0, x1 = max(0, px2 - 10), min(WORLD_W, px2 + 11)
                y0, y1 = max(0, py2 - 10), min(WORLD_H, py2 + 11)
                has_plant = bool(np.any(pm[y0:y1, x0:x1]))
                if not has_plant:
                    has_zones = bool(np.any(zone_tiles[y0:y1, x0:x1]))
                    if has_zones or pop > 400:
                        for r in range(0, 8):
                            for dy in range(-r, r + 1):
                                for dx in range(-r, r + 1):
                                    if abs(dx) == r or abs(dy) == r or r == 0:
                                        nx2, ny2 = px2 + dx, py2 + dy
                                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                            return (Tool.COALPOWER, nx2, ny2)

    # === CIVIC SERVICES (reactive to population) ===
    if pop > 30:
        fire_spots = [
            (8, 8), (40, 8), (70, 8), (100, 8),
            (8, 30), (115, 30), (8, 55), (115, 55),
            (8, 75), (115, 75), (8, 92), (40, 92), (70, 92), (100, 92),
            (40, 50), (70, 50), (25, 50), (55, 28), (85, 28),
            (55, 72), (85, 72), (100, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (25, 12), (55, 12), (85, 12), (112, 12),
            (25, 42), (55, 42), (85, 42), (112, 42),
            (25, 62), (55, 62), (85, 62), (112, 62),
            (25, 88), (55, 88), (85, 88), (112, 88),
            (12, 50), (105, 50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (32, 28), (92, 28), (32, 72), (92, 72),
            (62, 50), (12, 50), (108, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 5), (85, 5), (35, 95), (85, 95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 8 == 7:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === ZONE PLACEMENT (main closed-loop action) ===
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False
    # Protect wire/road spine corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr - 1):min(WORLD_H, wr + 2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc - 1):min(WORLD_W, wc + 2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active expansion centers scale with population
        if pop < 200:
            active_centers = [
                (50, 43), (30, 43), (70, 43), (50, 57), (30, 57), (70, 57),
                (50, 28), (30, 28), (70, 28), (50, 72), (30, 72), (70, 72),
                (10, 50), (90, 50), (110, 50),
            ]
        elif pop < 800:
            active_centers = []
            for row in range(5):
                for col in range(6):
                    cx = 10 + col * 20
                    cy = 10 + row * 18
                    active_centers.append((cx, cy))
        elif pop < 2000:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 7 + col * 13
                    cy = 7 + row * 13
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 150)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: place a coal plant near wire if nothing else works
    for wr in wire_rows:
        for wx2 in range(5, WORLD_W - 5, 20):
            x0, x1 = max(0, wx2 - 8), min(WORLD_W, wx2 + 9)
            y0, y1 = max(0, wr - 8), min(WORLD_H, wr + 9)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                if ib(wx2, wr) and bool(em[wr, wx2]):
                    return (Tool.COALPOWER, wx2, wr)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire and road spines."""
    actions = []
    # Two central power plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for d in range(-8, 9):
            actions.append((Tool.WIRE, px + d, py))
        # Vertical wire spine
        for d in range(-6, 7):
            actions.append((Tool.WIRE, px, py + d))
        # Roads above and below wire spine
        for d in range(-8, 9):
            actions.append((Tool.ROAD, px + d, py - 3))
            actions.append((Tool.ROAD, px + d, py + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 30% industrial, 25% commercial, 45% residential
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Anchors in a denser grid - 6 columns x 5 rows
    all_anchors = []
    for ax in [20, 40, 60, 80, 100, 115]:
        for ay in [15, 30, 50, 70, 85]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 6
        if pop < 300:   return 10
        if pop < 500:   return 15
        if pop < 800:   return 20
        if pop < 1200:  return 25
        if pop < 2000:  return 28
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- CLOSED-LOOP: Ensure power plant near each active anchor ----
    # Check actual power grid state via powered_zones and plant positions
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 15); y1 = min(WORLD_H, ay + 16)
        x0 = max(0, ax - 15); x1 = min(WORLD_W, ax + 16)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            # Find nearest empty spot for a plant
            for r in range(2, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # Dynamic wire reach based on pop
    wire_half = min(20, 6 + pop // 8)
    vert_half = min(14, 5 + pop // 12)

    # ---- CLOSED-LOOP: Extend wire horizontally from existing wire/plant ----
    # Scan each anchor row, extend wire outward from power source
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        # Scan left to right looking for gap to fill
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            # Check if adjacent to power
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    # ---- CLOSED-LOOP: Extend wire vertically ----
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- Wire connections between anchors in same column ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1a = col_anchors[i]
            _, y2a = col_anchors[i + 1]
            for cy in range(y1a + 1, y2a):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    # ---- Wire connections between anchors in same row ----
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1a, _ = row_anchors[i]
            x2a, _ = row_anchors[i + 1]
            for cx in range(x1a + 1, x2a):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- CLOSED-LOOP: Build roads adjacent to existing roads/wire ----
    # Roads at offset ±3 from wire spine (horizontal)
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-3, 3]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx+ddx, road_y) and bool(rm[road_y, cx+ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y-1) and bool(wm[road_y-1, cx])) or \
                               (ib(cx, road_y+1) and bool(wm[road_y+1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # Vertical roads flanking wire spines
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-3, 3]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy+ddy) and bool(rm[cy+ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x-1, cy) and bool(wm[cy, road_x-1])) or \
                               (ib(road_x+1, cy) and bool(wm[cy, road_x+1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- CLOSED-LOOP: Zone placement near roads and wire ----
    # Build neighbor masks from actual tile_map
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone positions: empty, near road AND near wire
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer close to active anchors
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary starting point by step to avoid always placing same zone
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CLOSED-LOOP: Extend roads from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES: placed reactively when pop thresholds hit ----
    if pop > 20:
        fire_spots = [
            (8, 8), (35, 8), (62, 8), (92, 8), (112, 8),
            (8, 28), (35, 28), (62, 28), (92, 28), (112, 28),
            (8, 48), (35, 48), (62, 48), (92, 48), (112, 48),
            (8, 68), (35, 68), (62, 68), (92, 68), (112, 68),
            (8, 88), (35, 88), (62, 88), (92, 88), (112, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (12, 12), (40, 12), (70, 12), (100, 12),
            (12, 40), (40, 40), (70, 40), (100, 40),
            (12, 60), (40, 60), (70, 60), (100, 60),
            (12, 80), (40, 80), (70, 80), (100, 80),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        for (sx, sy) in [(22, 5), (58, 5), (98, 5), (22, 92), (58, 92), (98, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        for (nx2, ny2) in [(5, 5), (115, 5), (5, 93), (115, 93), (60, 93), (60, 5)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        for (ax2, ay2) in [(55, 5), (5, 48), (115, 48), (55, 93)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 1800:
        for (sx2, sy2) in [(5, 90), (115, 90), (58, 95), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones to boost land value ----
    if pop > 60:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with wire cross and road grid."""
    actions = []
    # Single central plant at (60, 50)
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending outward
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-10, 11):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads at ±3 from center (horizontal and vertical)
    for d in range(-8, 9):
        actions.append((Tool.ROAD, cx + d, cy - 3))
        actions.append((Tool.ROAD, cx + d, cy + 3))
        actions.append((Tool.ROAD, cx - 3, cy + d))
        actions.append((Tool.ROAD, cx + 3, cy + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target ratio: 40% RES, 35% COM, 25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        if rr < 0.38:
            return Tool.RESIDENTIAL
        t = step % 6
        if t < 3: return Tool.RESIDENTIAL
        if t < 5: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    # Grid of neighborhoods: 4 columns x 4 rows
    nh_cols = [20, 45, 75, 100]
    nh_rows = [18, 38, 62, 82]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 30:    return 1
        if pop < 100:   return 2
        if pop < 300:   return 4
        if pop < 700:   return 6
        if pop < 1500:  return 10
        if pop < 3000:  return 14
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick evenly spaced hoods
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_sz = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_sz)] for i in range(n_active)]

    power_src = wm | pm

    # Dilation for power (radius 5, Manhattan)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            if abs(dx2) + abs(dy2) > 5:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Dilation for road (radius 2)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            if abs(dx2) + abs(dy2) > 2:
                continue
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            if r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: ENSURE POWER PLANTS NEAR ACTIVE HOODS ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 18), min(WORLD_W, hx + 19)
        y0, y1 = max(0, hy - 18), min(WORLD_H, hy + 19)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE SPINES — connect plant to each active hood ===
    spine_range = 10
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0p, x1p = max(0, hx - 22), min(WORLD_W, hx + 23)
    y0p, y1p = max(0, hy - 22), min(WORLD_H, hy + 23)
    plant_ys_l, plant_xs_l = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs_l) > 0:
        px_l = int(plant_xs_l[0]) + x0p
        py_l = int(plant_ys_l[0]) + y0p
        # Wire vertical then horizontal toward hood
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spine at hood center
    for dy3 in range(-spine_range, spine_range + 1):
        wy = hy + dy3
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj_dy in [-1, 1]:
            ay = wy + adj_dy
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    for dx3 in range(-spine_range, spine_range + 1):
        wx = hx + dx3
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj_dx in [-1, 1]:
            ax = wx + adj_dx
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # === PHASE 3: ROAD GRID around each active hood ===
    road_idx = step % max(len(active_hoods), 1)
    hx_r, hy_r = active_hoods[road_idx]

    # Horizontal roads at ±3 from hood center
    for ry_off in [-3, 3, -6, 6]:
        ry = hy_r + ry_off
        if not ib(hx_r, ry): continue
        for dx4 in range(-spine_range, spine_range + 1):
            rcx = hx_r + dx4
            if not ib(rcx, ry): continue
            if bool(rm[ry, rcx]): continue
            if bool(pm[ry, rcx]): continue
            if not bool(em[ry, rcx]) and not bool(zone_tiles[ry, rcx]): continue
            # Only place if near wire/power
            if bool(nbr_power[ry, rcx]):
                return (Tool.ROAD, rcx, ry)

    # Vertical roads at ±3 from hood center
    for rx_off in [-3, 3, -6, 6]:
        rx = hx_r + rx_off
        if not ib(rx, hy_r): continue
        for dy4 in range(-spine_range, spine_range + 1):
            rcy = hy_r + dy4
            if not ib(rx, rcy): continue
            if bool(rm[rcy, rx]): continue
            if bool(pm[rcy, rx]): continue
            if not bool(em[rcy, rx]) and not bool(zone_tiles[rcy, rx]): continue
            if bool(nbr_power[rcy, rx]):
                return (Tool.ROAD, rx, rcy)

    # === PHASE 4: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    # Keep away from borders
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        # Also prefer near existing zones (clustering)
        if total_zones > 6:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = (np.abs(cxs - zxs2[i]).astype(float) +
                          np.abs(cys - zys2[i]).astype(float))
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.4 + zone_prox * 0.6
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: EXTEND ROADS INTO POWERED EMPTY AREAS ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx5, dy5 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx5, ry2 + dy5
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # === CIVIC SERVICES (closed-loop: only place when pop thresholds hit) ===
    if pop > 50:
        for fy in range(12, WORLD_H, 18):
            for fx in range(12, WORLD_W, 18):
                if (ib(fx, fy) and bool(em[fy, fx]) and
                        bool(nbr_power[fy, fx]) and bool(nbr_road[fy, fx])):
                    # Check not already a fire station nearby
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        for py2 in range(15, WORLD_H, 22):
            for px2 in range(15, WORLD_W, 22):
                if (ib(px2, py2) and bool(em[py2, px2]) and
                        bool(nbr_power[py2, px2]) and bool(nbr_road[py2, px2])):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 500 and funds > 3000:
        nuclear_locs = [
            (8, 8), (112, 8), (8, 92), (112, 92),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (30, 25), (90, 25), (30, 75), (90, 75),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 8), min(WORLD_W, npx + 9)
            y0b, y1b = max(0, npy - 8), min(WORLD_H, npy + 9)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        stadium_locs = [
            (30, 30), (90, 30), (30, 70), (90, 70),
            (60, 20), (60, 80), (15, 50), (105, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(nbr_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700 and funds > 4000:
        airport_locs = [
            (10, 10), (100, 10), (10, 88), (100, 88),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 600 and funds > 2000:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # === FALLBACK: EXTEND WIRE FROM EXISTING ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx6, dy6 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx6, wy2 + dy6
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and
                        not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: NEW PLANT FOR UNCOVERED HOOD ===
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 20):
                for dy7 in range(-r2, r2 + 1):
                    for dx7 in range(-r2, r2 + 1):
                        if abs(dx7) == r2 or abs(dy7) == r2:
                            nx4, ny4 = hx3 + dx7, hy3 + dy7
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire grid + road grid for dense coverage"""
    actions = []
    # Three power plants spread across the map
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Horizontal wire spines at y=20, 40, 60, 80
    for y in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, y))
    # Vertical wire spines at x=20, 40, 60, 80, 100
    for x in [20, 40, 60, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, x, y))
    # Roads adjacent to horizontal wires
    for wy in [20, 40, 60, 80]:
        for offset in [-1, 1]:
            ry = wy + offset
            if 0 < ry < 99:
                for x in range(1, 119):
                    actions.append((Tool.ROAD, x, ry))
    # Roads adjacent to vertical wires
    for wx in [20, 40, 60, 80, 100]:
        for offset in [-1, 1]:
            rx = wx + offset
            if 0 < rx < 119:
                for y in range(1, 99):
                    actions.append((Tool.ROAD, rx, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target ratio: 50% res, 25% com, 25% ind — balanced economy
    def pick_tool():
        rr = res_count / total_zones
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ind_count == 0 or ir < 0.25:
            return Tool.INDUSTRIAL
        if com_count == 0 or cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 60, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    mod = step % 12

    # Priority 1: Fix gaps in horizontal wire rows
    if mod == 0:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Priority 2: Fix gaps in vertical wire cols
    if mod == 1:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Priority 3: Roads along horizontal wire rows
    if mod == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or rx == 1
                            if adj:
                                return (Tool.ROAD, rx, ry)

    # Priority 4: Roads along vertical wire cols
    if mod == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or ry == 1
                            if adj:
                                return (Tool.ROAD, rcx, ry)

    # Priority 5: Add power plants if coverage gaps
    if mod == 4:
        plant_targets = []
        for px in [10, 30, 50, 70, 90, 110]:
            for py in [10, 30, 50, 70, 90]:
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 20), min(WORLD_W, px + 21)
            y0, y1 = max(0, py - 20), min(WORLD_H, py + 21)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Priority 6: Wire unpowered zones reactively
    if mod == 5:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Priority 7: Additional cross roads between wire rows/cols
    if mod == 6:
        # Horizontal cross streets between wire rows
        for ri in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[ri], wire_rows[ri + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    if mod == 7:
        # Vertical cross streets between wire cols
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ry > 0 and bool(rm[ry-1, mid_x])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # ---- CIVIC SERVICES ---- (reactive to population)
    if pop > 20:
        fire_spots = [
            (5,5),(35,5),(65,5),(95,5),(115,5),
            (5,50),(35,50),(85,50),(115,50),
            (5,95),(35,95),(65,95),(95,95),(115,95),
            (5,25),(115,25),(5,75),(115,75),
            (50,25),(70,25),(50,75),(70,75),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (15,10),(45,10),(75,10),(105,10),
            (15,35),(45,35),(75,35),(105,35),
            (15,65),(45,65),(75,65),(105,65),
            (15,90),(45,90),(75,90),(105,90),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [(30,10),(70,10),(110,10),(30,90),(70,90),(110,90),(60,50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        # Upgrade to nuclear power for more capacity
        nuke_spots = [
            (10,50),(110,50),(60,10),(60,90),
            (10,25),(110,25),(10,75),(110,75),
            (35,50),(85,50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5,90),(115,5),(5,5),(115,90),(60,95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [(50,5),(60,5),(70,5),(50,93),(60,93),(70,93)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT — closed-loop, reacts to population ----
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire and road corridors (only avoid exact wire row/col, not neighbors)
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Build a dense grid of zone centers between wire rows/cols
        # Cells between wires: rows [20,40,60,80], cols [20,40,60,80,100]
        # Zone center positions in each cell
        active_centers = []

        # Use population-dependent spread
        if pop < 60:
            # Start with center cluster
            active_centers = [(50, 50), (60, 50), (70, 50), (50, 30), (70, 30)]
        elif pop < 200:
            # Expand to fill cells near center
            row_bands = [(21, 39), (41, 59), (61, 79)]
            col_bands = [(21, 39), (41, 59), (61, 79), (81, 99)]
            for (y0, y1) in row_bands:
                for (x0, x1) in col_bands:
                    # Place 2 zone centers per cell
                    cx = (x0 + x1) // 2
                    cy = (y0 + y1) // 2
                    active_centers.append((cx, cy))
                    active_centers.append((cx - 3, cy - 3))
                    active_centers.append((cx + 3, cy + 3))
        elif pop < 800:
            # Fill all cells with multiple zone spots
            row_bands = [(3, 18), (21, 38), (41, 58), (61, 78), (81, 97)]
            col_bands = [(3, 18), (21, 38), (41, 58), (61, 78), (81, 98), (101, 117)]
            for (y0, y1) in row_bands:
                for (x0, x1) in col_bands:
                    for fy in [0.33, 0.66]:
                        for fx in [0.33, 0.66]:
                            cx = int(x0 + (x1 - x0) * fx)
                            cy = int(y0 + (y1 - y0) * fy)
                            active_centers.append((cx, cy))
        else:
            # Very dense: fill entire map
            for row in range(7):
                for col in range(9):
                    cx = 8 + col * 12
                    cy = 8 + row * 12
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 13 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 1000)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Parks to boost land value
    if pop > 40 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: single coal plant + wire/road cross to seed the city"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines outward from plant
    for x in range(62, 90, 2):
        actions.append((Tool.WIRE, x, 50))
    for x in range(58, 32, -2):
        actions.append((Tool.WIRE, x, 50))
    for y in range(52, 70, 2):
        actions.append((Tool.WIRE, 60, y))
    for y in range(48, 32, -2):
        actions.append((Tool.WIRE, 60, y))
    # Initial road grid near center
    for x in range(40, 82):
        actions.append((Tool.ROAD, x, 45))
        actions.append((Tool.ROAD, x, 55))
    for y in range(38, 62):
        actions.append((Tool.ROAD, 45, y))
        actions.append((Tool.ROAD, 75, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure enough coal plants spread across map ---
    # Target ~1 plant per 20x20 region
    plant_positions = []
    for py in range(12, 95, 18):
        for px in range(12, 115, 18):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Extend wire from existing power sources toward unpowered plants ---
    # Find plant locations that aren't connected to power network
    pyr, pxr = np.where(pm)

    # Wire expansion: BFS-like - place wire adjacent to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, 0:3] = False
    wire_cand[:, WORLD_W-3:] = False

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0:
        # Find unpowered plants to wire toward
        unpowered_plants = [(int(pxr[i]), int(pyr[i])) for i in range(len(pxr))
                            if not bool(near_power[pyr[i], pxr[i]])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - px) + abs(cy - py) for px, py in unpowered_plants)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:50], zys[:50]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered road grid targets
        # Wire expansion to cover more area - extend toward nearest plant_position without power
        unpowered_grid = [(px, py) for px, py in plant_positions
                          if ib(px, py) and not bool(near_power[py, px])]
        if unpowered_grid:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in unpowered_grid[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Road network - reactive expansion ---
    # Build roads in a grid pattern, extending from existing roads
    road_grid_targets = []
    # Horizontal roads every 6 tiles
    for gy in range(8, 96, 6):
        for gx in range(5, 116):
            road_grid_targets.append((gx, gy))
    # Vertical roads every 6 tiles
    for gx in range(8, 116, 6):
        for gy in range(5, 96):
            road_grid_targets.append((gx, gy))

    # Filter to powered, empty targets adjacent to existing roads
    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm
    road_cand[0:3, :] = False
    road_cand[WORLD_H-3:, :] = False
    road_cand[:, 0:3] = False
    road_cand[:, WORLD_W-3:] = False

    # Find road grid targets that need roads
    uncovered_road = [(gx, gy) for gx, gy in road_grid_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road and np.any(road_cand):
        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets = uncovered_road[:30]
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))

    # If no road adjacent candidates, start a new road segment from plant
    if uncovered_road:
        for gx, gy in uncovered_road[:10]:
            if ib(gx, gy) and bool(em[gy, gx]) and bool(near_power[gy, gx]):
                return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement - reactive, near roads and power ---
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, 0:5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        """Check 3x3 area around center is placeable"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                # Allow empty or existing zone tiles
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer close to roads (road access), spread evenly
        road_ys, road_xs = np.where(rm)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 150)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs_arr))

        # Spread factor: prefer areas not crowded with existing zones
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Want close to roads but not too crowded
            score = road_dist * 1.5 - zone_dist * 0.3
        else:
            # Start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services based on population ---
    if pop > 100:
        fire_locs = [(fx, fy) for fy in range(10, 95, 10) for fx in range(10, 115, 10)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_locs = [(px2, py2) for py2 in range(15, 90, 12) for px2 in range(15, 110, 12)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        park_locs = [(px3, py3) for py3 in range(12, 90, 8) for px3 in range(12, 110, 8)]
        for pkx, pky in park_locs:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 800:
        stadium_locs = [(30, 20), (90, 20), (30, 70), (90, 70), (60, 45)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75), (60, 15), (60, 85)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 6), min(WORLD_W, nx + 7)
                y0, y1 = max(0, ny - 6), min(WORLD_H, ny + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: road from nearest plant ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (5, 0), (-5, 0)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Fallback: wire from plant ---
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with dense wire grid and road grid"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Horizontal wire spines at rows 20, 40, 60, 80
    for wr in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wr))
    # Vertical wire spines at cols 20, 40, 60, 80, 100
    for wc in [20, 40, 60, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wc, y))
    # Roads adjacent to wire rows (above and below)
    for wr in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wr - 1))
            actions.append((Tool.ROAD, x, wr + 1))
    # Roads adjacent to wire cols (left and right)
    for wc in [20, 40, 60, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, wc - 1, y))
            actions.append((Tool.ROAD, wc + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 50% res, 30% com, 20% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 60, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure power plants spread across map
    if phase == 0:
        plant_targets = [
            (20, 10), (60, 10), (100, 10),
            (20, 30), (60, 30), (100, 30),
            (20, 50), (60, 50), (100, 50),
            (20, 70), (60, 70), (100, 70),
            (20, 90), (60, 90), (100, 90),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill wire row gaps
    if phase == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Build roads adjacent to wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        if has_wire and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Build roads adjacent to wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                   bool(rm[ry, max(0, rcx-1)]) or \
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if has_wire and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # Phase 5: Add mid-block horizontal roads between wire rows
    if phase == 5:
        mid_rows = [10, 30, 50, 70, 90]
        for mr in mid_rows:
            if mr <= 0 or mr >= WORLD_H - 1:
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                    adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mr)

    # Phase 6: Add mid-block vertical roads between wire cols
    if phase == 6:
        mid_cols = [10, 30, 50, 70, 90, 110]
        for mc in mid_cols:
            if mc <= 0 or mc >= WORLD_W - 1:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                    adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mc]))
                    if adj:
                        return (Tool.ROAD, mc, ry)

    # Phase 7: Wire unpowered zones
    if phase == 7:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Wire roads without power
    if phase == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 9: Nuclear plants when pop grows
    if phase == 9 and pop > 500:
        nuke_spots = [
            (10, 50), (110, 50), (60, 10), (60, 90),
            (10, 20), (110, 20), (10, 80), (110, 80),
            (40, 50), (80, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Civic buildings: fire stations early and often
    if pop > 5:
        fire_spots = [
            (10, 10), (35, 10), (60, 10), (85, 10), (110, 10),
            (10, 30), (35, 30), (85, 30), (110, 30),
            (10, 50), (110, 50),
            (10, 70), (35, 70), (85, 70), (110, 70),
            (10, 90), (35, 90), (60, 90), (85, 90), (110, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 40:
        police_spots = [
            (22, 22), (52, 22), (82, 22), (112, 22),
            (22, 42), (52, 42), (82, 42), (112, 42),
            (22, 62), (52, 62), (82, 62), (112, 62),
            (22, 82), (52, 82), (82, 82), (112, 82),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (30, 15), (70, 15), (30, 55), (70, 55),
            (50, 35), (90, 35), (50, 75), (90, 75),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop, denser grid ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/road corridors themselves
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Progressive expansion: more zones as pop grows
        if pop < 50:
            active_centers = [
                (50, 30), (60, 30), (70, 30),
                (50, 50), (60, 50), (70, 50),
                (50, 70), (60, 70), (70, 70),
            ]
        elif pop < 200:
            active_centers = []
            for row in range(5):
                for col in range(6):
                    cx = 25 + col * 15
                    cy = 15 + row * 15
                    active_centers.append((cx, cy))
        elif pop < 600:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 12 + col * 12
                    cy = 10 + row * 12
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 8 + col * 10
                    cy = 7 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 1000)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

