def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 40% res, 35% com, 25% ind — more commercial than parent
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [20, 45, 75, 100]

    # Denser neighborhood grid — 5 rows x 7 cols
    nh_positions = []
    for row in range(5):
        for col in range(7):
            cx = 10 + col * 17
            cy = 10 + row * 20
            cy = min(cy, 92)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            # Start with central cluster
            return [(60, 50), (43, 50), (77, 50), (60, 30), (60, 70)]
        elif pop < 400:
            return nh_positions[10:28]
        elif pop < 1000:
            return nh_positions[5:30]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 14

    # Ensure power plants near active neighborhoods
    if step % 6 == 0:
        for (hx, hy) in active_hoods[:6]:
            x0, x1 = max(0, hx - 22), min(WORLD_W, hx + 23)
            y0, y1 = max(0, hy - 22), min(WORLD_H, hy + 23)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(2, 28):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross-streets between wire rows at midpoints
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire cols
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ry > 0 and bool(rm[ry-1, mid_x])) or (ry < WORLD_H-1 and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend road from existing road
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Fire stations — prioritize them earlier for land value
        if pop > 10:
            fire_spots = [
                (8,8),(32,8),(56,8),(80,8),(104,8),
                (8,28),(32,28),(56,28),(80,28),(104,28),
                (8,48),(56,48),(104,48),
                (8,68),(32,68),(56,68),(80,68),(104,68),
                (8,90),(32,90),(56,90),(80,90),(104,90),
            ]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

    elif phase == 9:
        # Police stations
        if pop > 80:
            police_spots = [
                (20,15),(60,15),(98,15),
                (20,45),(60,45),(98,45),
                (20,72),(60,72),(98,72),
                (20,92),(60,92),(98,92),
            ]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

    elif phase == 10:
        # Stadiums and nuclear power for high population
        if pop > 400:
            stadium_spots = [(35,25),(85,25),(35,75),(85,75),(60,50)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 700:
            nuke_spots = [(5,50),(115,50),(60,5),(60,95),(5,5),(115,5),(5,95),(115,95)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    elif phase == 11:
        # Parks for land value boost
        if pop > 30:
            park_cands = em & near_road & near_power
            pys, pxs = np.where(park_cands)
            if len(pxs) > 0:
                idx = (step * 31 + pop) % len(pxs)
                return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    elif phase == 12:
        # Seaports and airports for high pop
        if pop > 1000:
            seaports = [(5,95),(115,95),(5,5),(115,5)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 1800:
            airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(115,45)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase == 13:
        # Extra wire extension from existing wires
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            sk2 = (step * 13) % len(wire_xs3)
            for off in range(min(len(wire_xs3), 100)):
                k = (sk2 + off * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx3, ny3 = wx2+dx3, wy2+dy3
                    if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT (main closed-loop action) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders and wire/road corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx,bwy),(bwx,bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + roads."""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Roads above and below spine
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    # --- Ensure power plants grid (reactive to current pm) ---
    # More dense: one plant per ~25-col x 30-row region
    plant_grid_xs = list(range(15, WORLD_W - 10, 25))
    plant_grid_ys = list(range(15, WORLD_H - 10, 30))
    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 14), min(WORLD_H, ppy + 15)
            if not np.any(pm[y0:y1, x0:x1]):
                for r in range(0, 8):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # --- REACTIVE WIRE EXTENSION ---
    # Find power sources and extend wire toward areas lacking power
    def extend_wire_toward(tx, ty):
        """Extend wire one step from nearest wire/plant toward (tx, ty)."""
        wire_ys, wire_xs = np.where(power_src)
        if len(wire_xs) == 0:
            return None
        dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
        best = int(np.argmin(dists))
        bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
        dx = 0 if tx == bwx else (1 if tx > bwx else -1)
        dy = 0 if ty == bwy else (1 if ty > bwy else -1)
        for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)
        return None

    def extend_road_toward(tx, ty):
        """Extend road one step from nearest road toward (tx, ty)."""
        road_ys, road_xs = np.where(rm)
        if len(road_xs) == 0:
            return None
        dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
        best = int(np.argmin(dists))
        brx, bry = int(road_xs[best]), int(road_ys[best])
        dx = 0 if tx == brx else (1 if tx > brx else -1)
        dy = 0 if ty == bry else (1 if ty > bry else -1)
        for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)
        return None

    phase = step % 12

    if phase in (0, 1):
        # Extend wire along horizontal spines reactively
        wire_rows = [20, 35, 50, 65, 80]
        for wr in wire_rows:
            row_power = wm[wr, :] | pm[wr, :]
            if row_power.any():
                indices = np.where(row_power)[0]
                left = int(indices[0])
                right = int(indices[-1])
                if left > 2 and bool(em[wr, left - 1]) and not bool(pm[wr, left - 1]):
                    return (Tool.WIRE, left - 1, wr)
                if right < WORLD_W - 3 and bool(em[wr, right + 1]) and not bool(pm[wr, right + 1]):
                    return (Tool.WIRE, right + 1, wr)
            else:
                # Try to route wire to this row
                r = extend_wire_toward(60, wr)
                if r:
                    return r

    elif phase in (2, 3):
        # Extend wire along vertical spines reactively
        wire_cols = [15, 30, 45, 60, 75, 90, 105]
        for wc in wire_cols:
            col_power = wm[:, wc] | pm[:, wc]
            if col_power.any():
                indices = np.where(col_power)[0]
                top = int(indices[0])
                bot = int(indices[-1])
                if top > 2 and bool(em[top - 1, wc]) and not bool(pm[top - 1, wc]):
                    return (Tool.WIRE, wc, top - 1)
                if bot < WORLD_H - 3 and bool(em[bot + 1, wc]) and not bool(pm[bot + 1, wc]):
                    return (Tool.WIRE, wc, bot + 1)
            else:
                r = extend_wire_toward(wc, 50)
                if r:
                    return r

    elif phase in (4, 5):
        # Extend roads along horizontal routes
        road_rows_target = [23, 38, 47, 53, 68, 83]
        for rr in road_rows_target:
            if rr <= 0 or rr >= WORLD_H - 1:
                continue
            row_rd = rm[rr, :]
            if row_rd.any():
                indices = np.where(row_rd)[0]
                left = int(indices[0])
                right = int(indices[-1])
                if left > 3 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
                    return (Tool.ROAD, left - 1, rr)
                if right < WORLD_W - 4 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
                    return (Tool.ROAD, right + 1, rr)
            else:
                r = extend_road_toward(60, rr)
                if r:
                    return r

    elif phase in (6, 7):
        # Extend roads along vertical routes
        road_cols_target = [20, 35, 50, 65, 80, 95]
        for rc in road_cols_target:
            if rc <= 0 or rc >= WORLD_W - 1:
                continue
            col_rd = rm[:, rc]
            if col_rd.any():
                indices = np.where(col_rd)[0]
                top = int(indices[0])
                bot = int(indices[-1])
                if top > 3 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
                    return (Tool.ROAD, rc, top - 1)
                if bot < WORLD_H - 4 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
                    return (Tool.ROAD, rc, bot + 1)
            else:
                r = extend_road_toward(rc, 50)
                if r:
                    return r

    elif phase == 8:
        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpowered_zones)
        if len(zone_xs_u) > 0:
            idx2 = (step * 17) % len(zone_xs_u)
            tx, ty = int(zone_xs_u[idx2]), int(zone_ys_u[idx2])
            r = extend_wire_toward(tx, ty)
            if r:
                return r

    elif phase == 9:
        # Road toward unserved zones
        unserved = zone_tiles & ~near_road
        us_ys, us_xs = np.where(unserved)
        if len(us_xs) > 0:
            idx2 = (step * 13) % len(us_xs)
            tx, ty = int(us_xs[idx2]), int(us_ys[idx2])
            r = extend_road_toward(tx, ty)
            if r:
                return r

    elif phase == 10:
        # Civic services - reactive to population
        if pop > 15:
            fire_spots = [
                (12, 12), (60, 12), (108, 12),
                (12, 50), (60, 50), (108, 50),
                (12, 88), (60, 88), (108, 88),
            ]
            for (sx, sy) in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 80:
            police_spots = [
                (25, 25), (60, 25), (95, 25),
                (25, 60), (60, 60), (95, 60),
                (25, 85), (60, 85), (95, 85),
            ]
            for (sx, sy) in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 250:
            for (sx, sy) in [(40, 40), (80, 40), (40, 65), (80, 65)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 500:
            nuke_spots = [(8, 8), (112, 8), (8, 92), (112, 92), (60, 8), (60, 92)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    x0, x1 = max(0, nx2 - 15), min(WORLD_W, nx2 + 16)
                    y0, y1 = max(0, ny2 - 15), min(WORLD_H, ny2 + 16)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 700:
            for (sx, sy) in [(5, 90), (113, 90), (5, 5), (113, 5)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1200:
            for (sx, sy) in [(50, 5), (70, 5), (50, 92), (70, 92)]:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase == 11:
        # Parks for land value
        if pop > 30:
            park_cands = em & near_road & near_power
            pys_p, pxs_p = np.where(park_cands)
            if len(pxs_p) > 0:
                idx3 = (step * 31 + pop % 17) % len(pxs_p)
                return (Tool.PARK, int(pxs_p[idx3]), int(pys_p[idx3]))

    # ---- ZONE PLACEMENT (always attempted) ----
    # Avoid placing zones on wire/road rows/cols
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]
    road_rows = [23, 38, 47, 53, 68, 83]
    road_cols = [20, 35, 50, 65, 80, 95]
    avoid_rows = set(wire_rows + road_rows)
    avoid_cols = set(wire_cols + road_cols)

    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False

    for wr in avoid_rows:
        for offset in range(-1, 2):
            r = wr + offset
            if 0 <= r < WORLD_H:
                cand_mask[r, :] = False
    for wc in avoid_cols:
        for offset in range(-1, 2):
            c = wc + offset
            if 0 <= c < WORLD_W:
                cand_mask[:, c] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_ys_z, zone_xs_z = np.where(zone_tiles)
        road_ys_z, road_xs_z = np.where(rm)

        if len(road_xs_z) > 0:
            rd_stride = max(1, len(road_xs_z) // 60)
            road_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(road_xs_z), rd_stride):
                d = (np.abs(cxs2 - road_xs_z[i]) + np.abs(cys2 - road_ys_z[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float)

        if len(zone_xs_z) > 0:
            zn_stride = max(1, len(zone_xs_z) // 60)
            min_zone_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(zone_xs_z), zn_stride):
                d = (np.abs(cxs2 - zone_xs_z[i]) + np.abs(cys2 - zone_ys_z[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Prefer density: close to existing zones but not overlapping
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist < 8, 0.0,
                                           min_zone_dist * 0.3))
        else:
            zone_score = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float)

        score = road_dist * 1.2 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 11 + pop % 17) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- FALLBACK: extend road/wire from plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        # Try placing wire first, then road
        for dist in [3, 5, 7]:
            for dx2, dy2 in [(dist, 0), (-dist, 0), (0, dist), (0, -dist)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)
        for dx2, dy2 in [(4, 0), (-4, 0), (0, 4), (0, -4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spine + flanking roads."""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(55, 66):
        if x != 60:
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(45, 56):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    # Initial roads near center
    actions.append((Tool.ROAD, 58, 48))
    actions.append((Tool.ROAD, 62, 48))
    actions.append((Tool.ROAD, 58, 52))
    actions.append((Tool.ROAD, 62, 52))
    # Corner plants for broad coverage
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 20, 80))
    actions.append((Tool.COALPOWER, 100, 80))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if rm[nr, nc] or wm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    power_src = wm | pm
    near_power = dilate(power_src, 6)
    near_road = dilate(rm, 3)

    # Wire grid rows and cols
    wire_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    wire_cols = [10, 25, 40, 55, 70, 85, 100, 115]
    road_offsets = [-2, 2]  # roads parallel to wire corridors

    # ---- PHASE 0: Ensure plants distributed across map ----
    # Grid: one plant per ~30x25 cell
    plant_grid_xs = list(range(15, WORLD_W - 10, 30))
    plant_grid_ys = list(range(12, WORLD_H - 10, 25))
    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            x0, x1 = max(0, ppx - 13), min(WORLD_W, ppx + 14)
            y0, y1 = max(0, ppy - 11), min(WORLD_H, ppy + 12)
            if not np.any(pm[y0:y1, x0:x1]):
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    # ---- PHASE 1: Extend horizontal wire corridors ----
    if phase == 0:
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = int(np.argmin(dists))
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                indices = np.where(row_power)[0]
                left = int(indices[0])
                right = int(indices[-1])
                if left > 2 and bool(em[wr, left - 1]) and not bool(pm[wr, left - 1]):
                    return (Tool.WIRE, left - 1, wr)
                if right < WORLD_W - 3 and bool(em[wr, right + 1]) and not bool(pm[wr, right + 1]):
                    return (Tool.WIRE, right + 1, wr)

    # ---- PHASE 2: Extend vertical wire corridors ----
    elif phase == 1:
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = int(np.argmin(dists))
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx else -1
                    for nx in range(bpx + step_x, wc + step_x, step_x):
                        if ib(nx, bpy) and bool(em[bpy, nx]) and not bool(pm[bpy, nx]):
                            return (Tool.WIRE, nx, bpy)
            else:
                indices = np.where(col_power)[0]
                top = int(indices[0])
                bot = int(indices[-1])
                if top > 2 and bool(em[top - 1, wc]) and not bool(pm[top - 1, wc]):
                    return (Tool.WIRE, wc, top - 1)
                if bot < WORLD_H - 3 and bool(em[bot + 1, wc]) and not bool(pm[bot + 1, wc]):
                    return (Tool.WIRE, wc, bot + 1)

    # ---- PHASE 3: Roads parallel to horizontal wire rows ----
    elif phase == 2:
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in road_offsets:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                # Extend from existing road or seeded from wire
                row_rd = rm[ry, :]
                if not np.any(row_rd):
                    # Seed a road at wire position
                    for wx in range(WORLD_W):
                        if bool(row_wire[wx]) and bool(em[ry, wx]) and not bool(pm[ry, wx]):
                            return (Tool.ROAD, wx, ry)
                else:
                    idx_rd = np.where(row_rd)[0]
                    left = int(idx_rd[0])
                    right = int(idx_rd[-1])
                    if left > 2 and bool(em[ry, left - 1]) and not bool(pm[ry, left - 1]):
                        return (Tool.ROAD, left - 1, ry)
                    if right < WORLD_W - 3 and bool(em[ry, right + 1]) and not bool(pm[ry, right + 1]):
                        return (Tool.ROAD, right + 1, ry)

    # ---- PHASE 4: Roads parallel to vertical wire cols ----
    elif phase == 3:
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in road_offsets:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                col_rd = rm[:, rcx]
                if not np.any(col_rd):
                    for wy in range(WORLD_H):
                        if bool(col_wire[wy]) and bool(em[wy, rcx]) and not bool(pm[wy, rcx]):
                            return (Tool.ROAD, rcx, wy)
                else:
                    idx_rd = np.where(col_rd)[0]
                    top = int(idx_rd[0])
                    bot = int(idx_rd[-1])
                    if top > 2 and bool(em[top - 1, rcx]) and not bool(pm[top - 1, rcx]):
                        return (Tool.ROAD, rcx, top - 1)
                    if bot < WORLD_H - 4 and bool(em[bot + 1, rcx]) and not bool(pm[bot + 1, rcx]):
                        return (Tool.ROAD, rcx, bot + 1)

    # ---- PHASE 5: Wire to unpowered roads ----
    elif phase == 4:
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx2 = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy2 = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx2, bwy), (bwx, bwy + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 6: Road toward unserved zones ----
    elif phase == 5:
        unserved = zone_tiles & ~near_road
        us_ys, us_xs = np.where(unserved)
        if len(us_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx2 = (step * 13) % len(us_xs)
                tx, ty = int(us_xs[idx2]), int(us_ys[idx2])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx2 = 0 if tx == brx else (1 if tx > brx else -1)
                dy2 = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx2, bry), (brx, bry + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 7: Dense road grid in powered areas ----
    elif phase == 6:
        road_grid_cands = []
        for gy in range(6, WORLD_H - 6, 4):
            for gx in range(6, WORLD_W - 6, 4):
                if not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_cands.append((gx, gy))
        if road_grid_cands:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm, dtype=bool)
                if dy2 == -1: shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1: shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1: shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted
            for gx, gy in road_grid_cands:
                if bool(adj_to_road[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 8: Civic services ----
    elif phase == 7:
        if pop > 50:
            fire_positions = [
                (15, 10), (45, 10), (75, 10), (105, 10),
                (15, 34), (45, 34), (75, 34), (105, 34),
                (15, 58), (45, 58), (75, 58), (105, 58),
                (15, 82), (45, 82), (75, 82), (105, 82),
            ]
            for sx, sy in fire_positions:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 200:
            police_positions = [
                (30, 22), (60, 22), (90, 22),
                (15, 46), (45, 46), (75, 46), (105, 46),
                (30, 70), (60, 70), (90, 70),
            ]
            for sx, sy in police_positions:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 500:
            stadiums = [(30, 33), (90, 33), (30, 69), (90, 69)]
            for sx, sy in stadiums:
                if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [
                (5, 5), (115, 5), (5, 94), (115, 94),
                (60, 5), (5, 50), (115, 50), (60, 94),
            ]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    x0, x1 = max(0, nx2 - 15), min(WORLD_W, nx2 + 16)
                    y0, y1 = max(0, ny2 - 15), min(WORLD_H, ny2 + 16)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
            for sx, sy in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 3000:
            airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- PHASE 9: Parks ----
    elif phase == 8:
        if pop > 100 and step % 5 == 0:
            park_cands = em & near_road & near_power
            park_cands[0:3, :] = False
            park_cands[WORLD_H - 3:, :] = False
            park_cands[:, 0:3] = False
            park_cands[:, WORLD_W - 3:] = False
            pys4, pxs4 = np.where(park_cands)
            if len(pxs4) > 0:
                idx = (step * 31 + pop) % len(pxs4)
                return (Tool.PARK, int(pxs4[idx]), int(pys4[idx]))

    else:  # phase == 9: wire extension
        wire_ys_b, wire_xs_b = np.where(wm)
        if len(wire_xs_b) > 0:
            step_k2 = (step * 13) % len(wire_xs_b)
            for offset in range(min(len(wire_xs_b), 60)):
                k = (step_k2 + offset * 7) % len(wire_xs_b)
                wx2, wy2 = int(wire_xs_b[k]), int(wire_ys_b[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        if not bool(near_power[ny3, nx3]):
                            return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT (closed-loop, main objective) ----
    avoid_rows = set(wire_rows)
    avoid_cols = set(wire_cols)
    # Also avoid road parallel offsets
    for wr in wire_rows:
        for off in road_offsets:
            avoid_rows.add(wr + off)
    for wc in wire_cols:
        for off in road_offsets:
            avoid_cols.add(wc + off)

    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False
    for wr in avoid_rows:
        for off2 in range(-1, 2):
            r = wr + off2
            if 0 <= r < WORLD_H:
                cand_mask[r, :] = False
    for wc in avoid_cols:
        for off2 in range(-1, 2):
            c = wc + off2
            if 0 <= c < WORLD_W:
                cand_mask[:, c] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_ys_z, zone_xs_z = np.where(zone_tiles)
        road_ys_z, road_xs_z = np.where(rm)

        # Score: prefer close to existing zones (density) and near roads
        if len(road_xs_z) > 0:
            rd_stride = max(1, len(road_xs_z) // 80)
            road_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(road_xs_z), rd_stride):
                d = (np.abs(cxs2 - road_xs_z[i]) + np.abs(cys2 - road_ys_z[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float)

        if len(zone_xs_z) > 0:
            zn_stride = max(1, len(zone_xs_z) // 80)
            min_zone_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(zone_xs_z), zn_stride):
                d = (np.abs(cxs2 - zone_xs_z[i]) + np.abs(cys2 - zone_ys_z[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Reward being near zones (compact growth) but not overlapping
            zone_score = np.where(min_zone_dist < 3, 1000.0,
                                  np.where(min_zone_dist < 8, 0.0, min_zone_dist * 0.3))
        else:
            # No zones yet: prefer center
            zone_score = (np.abs(cxs2 - 60) + np.abs(cys2 - 50)).astype(float) * 0.3

        score = road_dist * 1.2 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 11 + pop % 17) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- FALLBACK: extend road from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: new coal plant near unpowered area ----
    all_hoods = [(cx, cy) for cy in range(8, 100, 12) for cx in range(8, 120, 15)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 10):
