                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                              (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                              bool(rm[ry, max(0, rcx-1)]) or \
                              bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if adj or ry == 1:
                            return (Tool.ROAD, rcx, ry)

    # ---- PHASE 5: CROSS ROADS BETWEEN WIRE ROWS ----
    if step % 10 == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi+1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # ---- PHASE 6: WIRE TOWARD UNPOWERED ZONES ----
    if step % 10 == 6:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 7: ROADS TOWARD UNPOWERED ZONES ----
    if step % 10 == 7:
        unpowered_zones = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: ADDITIONAL INTERMEDIATE ROADS ----
    if step % 10 == 8:
        # Add roads between wire col positions
        for wi in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wi], wire_cols[wi+1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ry > 0 and bool(rm[ry-1, mid_x])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_spots = [
            (10, 10), (50, 10), (90, 10), (110, 10),
            (10, 40), (110, 40), (10, 60), (110, 60),
            (10, 90), (50, 90), (90, 90), (110, 90),
            (30, 25), (70, 25), (30, 75), (70, 75),
            (50, 50), (70, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (25, 15), (60, 15), (95, 15),
            (25, 45), (60, 45), (95, 45),
            (25, 65), (60, 65), (95, 65),
            (25, 85), (60, 85), (95, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 250:
        stadium_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 5), (85, 5), (35, 95), (85, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10), (60, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(45, 5), (75, 5), (45, 93), (75, 93), (5, 45), (113, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 150 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:4, :] = False
        park_cands[WORLD_H-4:, :] = False
        park_cands[:, 0:4] = False
        park_cands[:, WORLD_W-4:] = False
        for wr in wire_rows:
            park_cands[max(0, wr-1):wr+2, :] = False
        for wc in wire_cols:
            park_cands[:, max(0, wc-1):wc+2] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (primary closed-loop) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Avoid wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scale active neighborhood centers with population
        if pop < 100:
            # Start with central clusters
            active_centers = [(cx, cy) for cy in [30, 50, 70]
                              for cx in [25, 50, 75, 100]]
        elif pop < 300:
            active_centers = [(cx, cy) for cy in [20, 40, 60, 80]
                              for cx in [15, 35, 55, 75, 95, 110]]
        elif pop < 700:
            active_centers = [(cx, cy) for cy in [15, 30, 45, 60, 75, 90]
                              for cx in [12, 28, 44, 60, 76, 92, 108]]
        else:
            # Full dense coverage
            active_centers = [(cx, cy) for cy in range(8, 100, 10)
                              for cx in range(10, 120, 10)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # ---- FALLBACK: extend road from existing road into powered area ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new coal plant near unpowered neighborhood ----
    all_hoods = [(cx, cy) for cy in range(8, 100, 10) for cx in range(10, 120, 10)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spine + initial roads"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spines horizontal
    for x in range(62, 110):
        actions.append((Tool.WIRE, x, 50))
    for x in range(10, 58):
        actions.append((Tool.WIRE, x, 50))
    # Wire spine vertical
    for y in range(10, 48):
        actions.append((Tool.WIRE, 60, y))
    for y in range(52, 90):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads (horizontal at y=46, y=54; vertical at x=35, x=85)
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(40, 62):
        actions.append((Tool.ROAD, 35, y))
        actions.append((Tool.ROAD, 85, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure enough power plants ----
    # Place coal plants on a coarser grid; only if no plant nearby
    plant_positions = []
    for py in range(12, 92, 22):
        for px in range(12, 112, 22):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Extend wire from existing power toward unpowered areas ----
    # Find adjacency to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[98:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, 118:] = False

    wys, wxs = np.where(wire_cand)

    # Check for unpowered plants
    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and np.any(pm[max(0,py-1):py+2, max(0,px-1):px+2])
                        and not bool(near_power[py, px])]

    if len(wxs) > 0:
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward empty unpowered areas if total zones still growing
        if total_zones < 300:
            unpowered_empty = em & ~near_power
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                rng_idx = list(range(0, min(len(upxs), 80), max(1, min(len(upxs), 80) // 30)))
                best_dist = 1e9
                best_k = 0
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in rng_idx)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Extend road grid ----
    # Roads every 5 tiles for denser coverage
    road_targets = []
    for gy in range(5, 96, 5):
        for gx in range(5, 116, 5):
            if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]):
                road_targets.append((gx, gy))

    if road_targets:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[98:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, 118:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = road_targets[:40]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in road_targets[:10]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[96:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, 116:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Power proximity bonus: prefer tiles close to power
        pwr_ys, pwr_xs = np.where(power_src)
        if len(pwr_xs) > 0:
            stride4 = max(1, len(pwr_xs) // 60)
            pwr_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(pwr_xs), stride4):
                d = (np.abs(cxs_arr - pwr_xs[i]) + np.abs(cys_arr - pwr_ys[i])).astype(float)
                pwr_dist = np.minimum(pwr_dist, d)
        else:
            pwr_dist = np.full(len(cxs_arr), 10.0)

        # Score: close to road, close to power, spread from existing zones
        score = road_dist * 1.0 + np.maximum(0, 12 - zone_dist) * 2.0 + pwr_dist * 0.5

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Adaptive tool selection based on current ratios
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        # Target ratio: 50% res, 25% com, 25% ind
        if ir < 0.20:
            tool = Tool.INDUSTRIAL
        elif cr < 0.22:
            tool = Tool.COMMERCIAL
        elif rr < 0.45:
            tool = Tool.RESIDENTIAL
        else:
            # Cycle based on step
            step_mod = step % 8
            if step_mod < 4:
                tool = Tool.RESIDENTIAL
            elif step_mod < 6:
                tool = Tool.COMMERCIAL
            else:
                tool = Tool.INDUSTRIAL

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services based on population ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(8, 93, 12) for fx in range(8, 112, 12)]
        near_road_ext = dilate(rm, 5)
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road_ext[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 120:
        police_grid = [(px2, py2) for py2 in range(10, 92, 14) for px2 in range(10, 112, 14)]
        near_road_ext = dilate(rm, 5)
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road_ext[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_grid = [(pkx, pky) for pky in range(8, 94, 10) for pkx in range(8, 114, 10)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        # Additional nuclear plants for growing power demand
        nuke_locs = [(20, 25), (100, 25), (20, 75), (100, 75),
                     (60, 15), (60, 85), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 8), min(WORLD_W, nx + 9)
                y0, y1 = max(0, ny - 8), min(WORLD_H, ny + 9)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(10, 50), (110, 50), (60, 5), (60, 92)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: wire or road near plants ----
    pwr_ys2, pwr_xs2 = np.where(pm)
    if len(pwr_xs2) > 0:
        k = step % len(pwr_xs2)
        px3, py3 = int(pwr_xs2[k]), int(pwr_ys2[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and a road grid."""
    actions = []
    # Plant 1: left cluster center
    actions.append((Tool.COALPOWER, 30, 50))
    # Plant 2: right cluster center
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting the two plants horizontally
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines from each plant
    for dy in range(-12, 13):
        if dy != 0:
            actions.append((Tool.WIRE, 30, 50 + dy))
            actions.append((Tool.WIRE, 90, 50 + dy))
    # Roads flanking vertical spines (left cluster)
    for dy in range(-11, 12):
        actions.append((Tool.ROAD, 29, 50 + dy))
        actions.append((Tool.ROAD, 31, 50 + dy))
    # Roads flanking vertical spines (right cluster)
    for dy in range(-11, 12):
        actions.append((Tool.ROAD, 89, 50 + dy))
        actions.append((Tool.ROAD, 91, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        # Target ratio: 40% res, 35% com, 25% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Two main clusters + top/bottom extensions as pop grows
    # Each cluster: center + surrounding zones on a grid
    clusters = [
        (30, 50),   # left
        (90, 50),   # right
    ]
    if pop > 300:
        clusters += [(30, 25), (90, 25)]
    if pop > 600:
        clusters += [(30, 75), (90, 75)]
    if pop > 1000:
        clusters += [(60, 25), (60, 75)]
    if pop > 1500:
        clusters += [(60, 50)]

    # Power/road proximity
    power_src = wm | pm
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for d in range(1, 7):
        nbr_power[d:, :] |= power_src[:-d, :]
        nbr_power[:-d, :] |= power_src[d:, :]
        nbr_power[:, d:] |= power_src[:, :-d]
        nbr_power[:, :-d] |= power_src[:, d:]
    nbr_power |= power_src

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for d in range(1, 4):
        nbr_road[d:, :] |= rm[:-d, :]
        nbr_road[:-d, :] |= rm[d:, :]
        nbr_road[:, d:] |= rm[:, :-d]
        nbr_road[:, :-d] |= rm[:, d:]
    nbr_road |= rm

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # PHASE 1: Ensure each cluster has a power plant nearby
    for (cx, cy) in clusters:
        x0, x1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        y0, y1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Wire from plants toward cluster centers
    hood_idx = step % max(len(clusters), 1)
    hx, hy = clusters[hood_idx]
    x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
    y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0
        # Wire along column then row
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)
        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # PHASE 3: Horizontal grid of roads at cluster row ± offsets
    # Build a 3-road-wide horizontal band around each cluster
    hood_idx2 = (step + 1) % max(len(clusters), 1)
    hx2, hy2 = clusters[hood_idx2]
    spine_range = 14

    for road_offset in [-2, 2, -5, 5, -8, 8, -11, 11]:
        ry = hy2 + road_offset
        if not ib(hx2, ry): continue
        for dx in range(-spine_range, spine_range + 1):
            rx = hx2 + dx
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]): continue
            if not bool(em[ry, rx]): continue
            # Only place road if adjacent to existing road or wire
            has_adj = any(
                ib(rx + ax, ry + ay) and (bool(rm[ry + ay, rx + ax]) or bool(wm[ry + ay, rx + ax]) or bool(pm[ry + ay, rx + ax]))
                for ax, ay in [(-1, 0), (1, 0), (0, -1), (0, 1)]
            )
            if has_adj:
                return (Tool.ROAD, rx, ry)

    # PHASE 4: Vertical roads along cluster columns
    hood_idx3 = (step + 2) % max(len(clusters), 1)
    hx3, hy3 = clusters[hood_idx3]
    for col_offset in [-2, 2, -5, 5, -8, 8, -11, 11]:
        rx = hx3 + col_offset
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if bool(pm[ry, rx]): continue
            if not bool(em[ry, rx]): continue
            has_adj = any(
                ib(rx + ax, ry + ay) and (bool(rm[ry + ay, rx + ax]) or bool(wm[ry + ay, rx + ax]) or bool(pm[ry + ay, rx + ax]))
                for ax, ay in [(-1, 0), (1, 0), (0, -1), (0, 1)]
            )
            if has_adj:
                return (Tool.ROAD, rx, ry)

    # PHASE 5: Inter-cluster wire connections
    for i, (hx1, hy1) in enumerate(clusters):
        for j, (hx2c, hy2c) in enumerate(clusters):
            if i >= j: continue
            # Connect horizontally if same row
            if hy1 == hy2c:
                mnx, mxx = min(hx1, hx2c), max(hx1, hx2c)
                for cx2 in range(mnx + 1, mxx):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Connect vertically if same column
            if hx1 == hx2c:
                mny, mxy = min(hy1, hy2c), max(hy1, hy2c)
                for cy2 in range(mny + 1, mxy):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # PHASE 6: Zone placement - prioritize near clusters, needs road+power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in clusters:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 7: Extend roads from existing road into powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # CIVIC: Fire stations
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 20) for fy in range(15, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    # CIVIC: Police stations
    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 24) for py2 in range(18, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    # CIVIC: Stadiums
    if pop > 600:
        stadiums = [(30, 25), (90, 25), (30, 75), (90, 75), (60, 50)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # CIVIC: Seaports
    if pop > 1200:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # Nuclear power upgrade
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(30, 50), (90, 50), (30, 25), (90, 25), (30, 75), (90, 75), (60, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Airports for large cities
    if pop > 3000:
        airports = [(10, 50), (110, 50), (60, 10), (60, 90)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 400 and step % 6 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 23 + pop) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # Fallback: extend wire from existing wire
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Final fallback: new plant at uncovered cluster
    for (hx, hy) in clusters:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# Different strategy: denser neighborhood grid, better road connectivity,
# more balanced zone mix, and more aggressive early expansion

def init(obs, state):
    """Bootstrap: two coal plants at 1/3 and 2/3 of map, connected by wire."""
    actions = []
    # Plant 1: left side
    actions.append((Tool.COALPOWER, 35, 50))
    # Plant 2: right side
    actions.append((Tool.COALPOWER, 85, 50))
    # Wire connecting them horizontally through center
    for x in range(36, 85):
        actions.append((Tool.WIRE, x, 50))
    # Initial roads flanking the wire
    for x in range(30, 91):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Denser neighborhood grid: 8 cols x 6 rows = 48 neighborhoods
    # Spaced 14 apart so neighborhoods are tighter
    nh_cols = [10, 24, 38, 52, 66, 80, 94, 108]
    nh_rows = [10, 25, 40, 55, 70, 85]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    # Progressive unlock based on population
    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 8
        if pop < 800:   return 14
        if pop < 1500:  return 20
        if pop < 3000:  return 30
        if pop < 6000:  return 40
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Spread active hoods evenly across the map
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- PHASE 1: ENSURE POWER PLANTS near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find nearest empty spot for coal plant
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID - vertical and horizontal spines ----
    # Each hood gets both a vertical and horizontal wire spine
    spine_range = 8
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical wire at hx
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            # Check adjacency to existing wire/plant
            has_adj = False
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    has_adj = True
                    break
            if has_adj:
                return (Tool.WIRE, hx, wy)
        # Horizontal wire at hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            has_adj = False
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    has_adj = True
                    break
            if has_adj:
                return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    # Horizontal connections (same row, adjacent cols separated by 14)
    for (hx1, hy1) in active_hoods:
        for (hx2, hy2) in active_hoods:
            if hy1 == hy2 and 10 <= hx2 - hx1 <= 20:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    has_adj = False
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            has_adj = True
                            break
                    if has_adj:
                        return (Tool.WIRE, cx2, hy1)
            # Vertical connections
            if hx1 == hx2 and 10 <= hy2 - hy1 <= 20:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    has_adj = False
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            has_adj = True
                            break
                    if has_adj:
                        return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS - grid roads flanking wires ----
    # Place roads at hx-1, hx+1 (flanking vertical spines)
    # and hy-1, hy+1 (flanking horizontal spines)
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step // 2 + idx_h) % max(len(active_hoods), 1) > len(active_hoods) // 2:
            continue
        for rx in [hx - 2, hx + 2]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        for ry2 in [hy - 2, hy + 2]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT with balanced mix ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 50% RES, 25% COM, 25% IND (good population balance)
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.23:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road coverage mask (within 2 tiles for tighter zones)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power coverage mask (within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers: need road + power nearby
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest active hood (closer = better)
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Vary starting point to avoid repeating same candidate
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(18, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 20), (90, 20), (30, 80), (90, 80),
                    (60, 50), (15, 50), (105, 50), (60, 20), (60, 80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(10, 92), (110, 92), (10, 8), (110, 8), (60, 95), (60, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        airports = [(40, 7), (80, 7), (40, 93), (80, 93), (7, 40), (7, 70)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for large cities ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [(60, 50), (25, 25), (95, 25), (25, 75), (95, 75),
                         (60, 12), (60, 88), (10, 50), (110, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 19) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

