def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- SPINE LAYOUT ----
    # Multiple horizontal spines at different y-levels
    spine_ys = [15, 28, 41, 54, 67, 80, 93]
    spine_x_start = 4
    spine_x_end = 116
    connector_xs = list(range(10, WORLD_W, 10))  # denser connectors

    def num_active_spines():
        if pop < 100:  return 2
        if pop < 300:  return 3
        if pop < 600:  return 4
        if pop < 1200: return 5
        if pop < 2500: return 6
        return len(spine_ys)

    n_spines = min(num_active_spines(), len(spine_ys))
    # Center the active spines around the middle
    all_spines = spine_ys
    active_spines = all_spines[:n_spines]

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);  r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);  c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS on each active spine ----
    # Place plants at multiple x positions per spine for better coverage
    plant_xs_per_spine = [15, 40, 65, 90, 110]
    for spine_y in active_spines:
        y0, y1 = max(0, spine_y - 6), min(WORLD_H, spine_y + 7)
        for px in plant_xs_per_spine:
            x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = px + dx, spine_y + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES (horizontal) ----
    for si, spine_y in enumerate(active_spines):
        if step % max(n_spines, 1) != si % max(n_spines, 1):
            continue
        for wx in range(spine_x_start, spine_x_end + 1):
            if not ib(wx, spine_y): continue
            if bool(wm[spine_y, wx]) or bool(pm[spine_y, wx]): continue
            if not bool(em[spine_y, wx]): continue
            # Extend if adjacent to existing wire/plant
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, spine_y) and (bool(wm[spine_y, ax]) or bool(pm[spine_y, ax])):
                    return (Tool.WIRE, wx, spine_y)

    # ---- PHASE 3: VERTICAL WIRE CONNECTORS between adjacent spines ----
    for si in range(len(active_spines) - 1):
        y1s, y2s = active_spines[si], active_spines[si + 1]
        for cx in connector_xs:
            if not ib(cx, y1s): continue
            for wy in range(y1s + 1, y2s):
                if not ib(cx, wy): continue
                if bool(wm[wy, cx]) or bool(pm[wy, cx]): continue
                if not bool(em[wy, cx]): continue
                for adj in [-1, 1]:
                    ay = wy + adj
                    if ib(cx, ay) and (bool(wm[ay, cx]) or bool(pm[ay, cx])):
                        return (Tool.WIRE, cx, wy)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for si, spine_y in enumerate(active_spines):
        for road_y in [spine_y - 1, spine_y + 1]:
            if not ib(0, road_y): continue
            for rx in range(spine_x_start, spine_x_end + 1):
                if not ib(rx, road_y): continue
                if bool(rm[road_y, rx]) or bool(pm[road_y, rx]): continue
                if not bool(em[road_y, rx]): continue
                if bool(wm[spine_y, rx]) or bool(pm[spine_y, rx]):
                    return (Tool.ROAD, rx, road_y)

    # ---- PHASE 5: CROSS ROADS (vertical, between spines) ----
    for cx in connector_xs:
        for si in range(len(active_spines) - 1):
            y1s, y2s = active_spines[si], active_spines[si + 1]
            for ry in range(y1s + 2, y2s - 1):
                if not ib(cx, ry): continue
                if bool(rm[ry, cx]) or bool(pm[ry, cx]): continue
                if not bool(em[ry, cx]): continue
                for adj in [-1, 1]:
                    ay = ry + adj
                    if ib(cx, ay) and bool(rm[ay, cx]):
                        return (Tool.ROAD, cx, ry)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 45% RES, 30% IND, 25% COM
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score candidates: closer to a spine = better, but spread across spines
        best_dist = np.full(len(cxs_arr), 999999.0)
        for sy in active_spines:
            d = np.abs(cys_arr - sy)
            best_dist = np.minimum(best_dist, d)
        # Also factor in horizontal centering (prefer mid-map)
        cx_dist = np.abs(cxs_arr - 60) / 60.0
        score = best_dist + cx_dist * 2
        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (placed reactively based on population) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 15) for fy in range(10, WORLD_H, 15)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 20) for py2 in range(15, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 96), (60, 4)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(35, 5), (85, 5), (35, 93), (85, 93), (5, 35), (5, 65), (113, 35), (113, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high-pop areas ----
    if pop > 1500 and step % 4 == 0:
        nuclear_spots = [
            (60, 35), (60, 65), (20, 50), (100, 50),
            (40, 22), (80, 22), (40, 78), (80, 78),
            (10, 35), (110, 35), (10, 65), (110, 65),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value (reactive: only where road+power present) ----
    if pop > 200 and step % 5 == 0:
        park_ys_arr, park_xs_arr = np.where(em & nbr_road & nbr_power)
        if len(park_xs_arr) > 0:
            idx = (step * 23) % len(park_xs_arr)
            py2, px2 = int(park_ys_arr[idx]), int(park_xs_arr[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered spine ----
    for spine_y in active_spines:
        if not bool(nbr_power[spine_y, 60]):
            for r in range(0, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = 60 + dx, spine_y + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

