def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 50% res, 30% com, 20% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- CLOSED-LOOP REACTIVE DECISIONS ---

    # Step 1: Reactively place coal plants where power is absent
    # Check if large areas lack power - place plants there
    region_size = 30
    if step % 15 == 0:
        # Scan for regions without power plants nearby
        plant_targets = [
            (10, 10), (60, 10), (110, 10),
            (10, 50), (60, 50), (110, 50),
            (10, 90), (60, 90), (110, 90),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (45, 45), (75, 45), (45, 65), (75, 65),
        ]
        for px, py in plant_targets:
            x0 = max(0, px - 15)
            x1 = min(WORLD_W, px + 16)
            y0 = max(0, py - 15)
            y1 = min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Find empty spot near target
                for r in range(0, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px+dx, py+dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Step 2: Reactively extend wires from existing wire/plant toward unpowered zones
    if step % 20 == 1:
        # Find unpowered zones and wire toward them
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                # Step toward target
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Step 3: Reactively fill wire corridor gaps (scan actual map)
    if step % 20 == 2:
        for wr in wire_rows:
            for wx in range(1, WORLD_W-1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left_has = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right_has = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left_has or right_has:
                        return (Tool.WIRE, wx, wr)
        for wc in wire_cols:
            for wy in range(1, WORLD_H-1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up_has = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn_has = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up_has or dn_has:
                        return (Tool.WIRE, wc, wy)

    # Step 4: Reactively fill road gaps adjacent to wires
    if step % 20 == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H-1):
                    continue
                for rx in range(1, WORLD_W-1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1]))
                        if has_wire and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    if step % 20 == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W-1):
                    continue
                for ry in range(1, WORLD_H-1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx]))
                        if has_wire and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # Step 5: Additional horizontal roads between wire rows
    if step % 20 == 5:
        extra_road_rows = [12, 37, 62, 87]
        for mr in extra_road_rows:
            if mr <= 0 or mr >= WORLD_H-1:
                continue
            for rx in range(1, WORLD_W-1):
                if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                    adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mr)

    # Step 6: Additional vertical roads between wire cols
    if step % 20 == 6:
        extra_road_cols = [15, 45, 75, 105]
        for mc in extra_road_cols:
            if mc <= 0 or mc >= WORLD_W-1:
                continue
            for ry in range(1, WORLD_H-1):
                if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                    adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mc]))
                    if adj:
                        return (Tool.ROAD, mc, ry)

    # Step 7: Extend road from existing road into powered empty areas
    if step % 20 == 7:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Step 8: Reactively wire roads that lack power
    if step % 20 == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- CIVIC BUILDINGS (reactive: only if not already placed nearby) ---
    # Fire stations: place if pop > 10 and spot is empty
    if pop > 10:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 30), (60, 30), (115, 30),
            (5, 50), (60, 50), (115, 50),
            (5, 70), (60, 70), (115, 70),
            (5, 95), (60, 95), (115, 95),
            (20, 18), (45, 18), (75, 18), (100, 18),
            (20, 40), (45, 40), (75, 40), (100, 40),
            (20, 60), (45, 60), (75, 60), (100, 60),
            (20, 82), (45, 82), (75, 82), (100, 82),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (15, 12), (45, 12), (75, 12), (105, 12),
            (15, 37), (45, 37), (75, 37), (105, 37),
            (15, 62), (45, 62), (75, 62), (105, 62),
            (15, 87), (45, 87), (75, 87), (105, 87),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (20, 20), (70, 20), (110, 20),
            (20, 50), (70, 50), (110, 50),
            (20, 80), (70, 80), (110, 80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power when pop is large
    if pop > 500:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
            (30, 10), (90, 10), (30, 90), (90, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 92), (115, 92), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near roads/power for land value
    if pop > 150 and step % 7 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- REACTIVE ZONE PLACEMENT ---
    # Candidate cells: empty, near road, near power
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/road spine corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):min(WORLD_W,wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Define active zone centers based on current pop (reactive)
        if pop < 80:
            active_centers = [
                (45, 35), (60, 35), (75, 35),
                (45, 50), (60, 50), (75, 50),
                (45, 65), (60, 65), (75, 65),
            ]
        elif pop < 300:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 12 + col * 14
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 800:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 8 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 4 + row * 9
                    active_centers.append((cx, cy))

        # Score candidates by distance to nearest active center
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Also prefer candidates closer to existing zones (cluster building)
        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                # For each candidate find nearest zone
                zone_bonus = np.full(len(cxs), 0.0)
                # Vectorized: min dist to any zone
                for i in range(0, len(zone_xs), 50):
                    chunk_xs = zone_xs[i:i+50]
                    chunk_ys = zone_ys[i:i+50]
                    d_chunk = np.min(
                        np.abs(cxs[:, None] - chunk_xs[None, :]) + 
                        np.abs(cys[:, None] - chunk_ys[None, :]),
                        axis=1
                    ).astype(float)
                    zone_bonus = np.maximum(zone_bonus, 20.0 - np.minimum(d_chunk, 20.0))
                best_dist = best_dist - zone_bonus * 0.3

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plant + initial wires and roads to seed the city"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire spine east
    for x in range(61, 75):
        actions.append((Tool.WIRE, x, 50))
    # Wire spine west
    for x in range(59, 45, -1):
        actions.append((Tool.WIRE, x, 50))
    # Wire spine south
    for y in range(51, 65):
        actions.append((Tool.WIRE, 60, y))
    # Wire spine north
    for y in range(49, 35, -1):
        actions.append((Tool.WIRE, 60, y))
    # Initial roads near center
    for x in range(45, 76):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(36, 65):
        actions.append((Tool.ROAD, 46, y))
        actions.append((Tool.ROAD, 74, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy().astype(bool)
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def adj_mask(mask):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        result[1:, :] |= mask[:-1, :]
        result[:-1, :] |= mask[1:, :]
        result[:, 1:] |= mask[:, :-1]
        result[:, :-1] |= mask[:, 1:]
        return result

    # --- PHASE 1: Ensure coal plants spread across map ---
    # One plant per ~20x20 block
    plant_grid = []
    for py in range(14, 95, 20):
        for px in range(14, 115, 20):
            plant_grid.append((px, py))

    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire expansion from power sources ---
    adj_power = adj_mask(power_src)
    wire_cand = em & ~rm & ~zone_tiles & adj_power
    # Keep border safe
    wire_cand[:3, :] = False
    wire_cand[WORLD_H-3:, :] = False
    wire_cand[:, :3] = False
    wire_cand[:, WORLD_W-3:] = False

    # Find plants not near power network (isolated)
    pyr, pxr = np.where(pm)
    if len(pxr) > 0:
        unpowered_plants = [(int(pxr[i]), int(pyr[i])) for i in range(len(pxr))
                            if not bool(near_power[pyr[i], pxr[i]])]
    else:
        unpowered_plants = []

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        # Place wire that minimizes distance to nearest unpowered plant
        best_dist = 1e9
        best_k = 0
        for i in range(len(wxs)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - px2) + abs(cy - py2) for px2, py2 in unpowered_plants)
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    if len(wxs) > 0:
        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            sample = list(zip(zxs[:60], zys[:60]))
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx2) + abs(cy - zy2) for zx2, zy2 in sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered plant grid positions
        unpowered_grid = [(gx, gy) for gx, gy in plant_grid
                          if ib(gx, gy) and not bool(near_power[gy, gx])]
        if unpowered_grid:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in unpowered_grid[:15])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Road network expansion ---
    # Grid roads every 5 tiles
    road_grid = []
    for gy in range(6, 96, 5):
        for gx in range(5, 116):
            road_grid.append((gx, gy))
    for gx in range(6, 116, 5):
        for gy in range(5, 96):
            road_grid.append((gx, gy))

    adj_road = adj_mask(rm)
    # Road candidates: adjacent to road, near power, not zone/wire
    road_cand = em & adj_road & near_power & ~zone_tiles & ~wm
    road_cand[:3, :] = False
    road_cand[WORLD_H-3:, :] = False
    road_cand[:, :3] = False
    road_cand[:, WORLD_W-3:] = False

    # Find road grid positions that need roads but are powered
    needed_roads = [(gx, gy) for gx, gy in road_grid
                    if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if needed_roads and np.any(road_cand):
        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets = needed_roads[:40]
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))

    # Start new road segment from powered empty grid points
    if needed_roads:
        for gx, gy in needed_roads[:20]:
            if ib(gx, gy) and bool(em[gy, gx]) and bool(near_power[gy, gx]):
                return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement ---
    zone_cand = em & near_road & near_power
    zone_cand[:5, :] = False
    zone_cand[WORLD_H-5:, :] = False
    zone_cand[:, :5] = False
    zone_cand[:, WORLD_W-5:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride = max(1, len(road_xs) // 200)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs_arr))

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride2 = max(1, len(zone_xs) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride2):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer close to roads, not too crowded
            score = road_dist * 1.5 - zone_dist * 0.5
        else:
            # Start near center
            score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        order = np.argsort(score)
        off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic buildings as city grows ---
    if pop > 200:
        fire_locs = [(fx, fy) for fy in range(8, 95, 12) for fx in range(8, 115, 12)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]) and bool(near_road[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 500:
        police_locs = [(px2, py2) for py2 in range(10, 90, 14) for px2 in range(10, 110, 14)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]) and bool(near_road[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 800:
        park_locs = [(px3, py3) for py3 in range(10, 92, 9) for px3 in range(10, 112, 9)]
        for pkx, pky in park_locs:
            if ib(pkx, pky) and bool(em[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 1200:
        stadium_locs = [(30, 20), (90, 20), (30, 75), (90, 75), (60, 48)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1500:
        nuke_locs = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 15), (60, 85)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 7), min(WORLD_W, nx + 8)
                y0, y1 = max(0, ny - 7), min(WORLD_H, ny + 8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 3000:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 4000:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: road adjacent to plant ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(4, 0), (-4, 0), (0, 4), (0, -4), (6, 0), (-6, 0)]:
            nx2, ny2 = px3 + dx2, py3 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # --- Fallback: wire from plant ---
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px4, py4 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px4 + dx3, py4 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
