def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        # Target ratio: 50% RES, 25% COM, 25% IND
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # PHASE 1: Ensure enough power plants (one per ~20x20 region)
    plant_xs = list(range(15, WORLD_W - 5, 22))
    plant_ys = list(range(15, WORLD_H - 5, 22))
    for ppy in plant_ys:
        for ppx in plant_xs:
            if not ib(ppx, ppy):
                continue
            x0, x1 = max(0, ppx - 11), min(WORLD_W, ppx + 12)
            y0, y1 = max(0, ppy - 11), min(WORLD_H, ppy + 12)
            if not np.any(pm[y0:y1, x0:x1]):
                if bool(em[ppy, ppx]):
                    return (Tool.COALPOWER, ppx, ppy)

    # PHASE 2: Wire grid - rows at 15, 37, 59, 81 (every ~22 rows)
    # and cols at 15, 37, 59, 81, 103
    wire_rows = list(range(15, WORLD_H - 5, 22))
    wire_cols = list(range(15, WORLD_W - 5, 22))

    # Extend horizontal wires
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not row_power.any():
            pys_arr, pxs_arr = np.where(pm)
            if len(pxs_arr) > 0:
                idx = np.argmin(np.abs(pys_arr - wr))
                sx = int(pxs_arr[idx])
                if ib(sx, wr) and bool(em[wr, sx]):
                    return (Tool.WIRE, sx, wr)
            if ib(30, wr) and bool(em[wr, 30]):
                return (Tool.WIRE, 30, wr)
            continue
        indices = np.where(row_power)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 2 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 2 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)

    # Extend vertical wires
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not col_power.any():
            if ib(wc, 50) and bool(em[50, wc]):
                return (Tool.WIRE, wc, 50)
            continue
        indices = np.where(col_power)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 2 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 2 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)

    # PHASE 3: Road grid - roads at rows offset +7 from wire rows
    # This creates strips between wire rows for zone placement
    road_rows = sorted(set(wr + 7 for wr in wire_rows if 4 < wr + 7 < WORLD_H - 4))
    road_cols = sorted(set(wc + 7 for wc in wire_cols if 4 < wc + 7 < WORLD_W - 4))
    # Also add a second road between wire rows
    road_rows2 = sorted(set(wr - 7 for wr in wire_rows if 4 < wr - 7 < WORLD_H - 4))
    road_cols2 = sorted(set(wc - 7 for wc in wire_cols if 4 < wc - 7 < WORLD_W - 4))
    all_road_rows = sorted(set(road_rows + road_rows2))
    all_road_cols = sorted(set(road_cols + road_cols2))

    for rr in all_road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            start_x = 10
            if ib(start_x, rr) and bool(em[rr, start_x]) and not bool(pm[rr, start_x]):
                return (Tool.ROAD, start_x, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 4 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)

    for rc in all_road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            if ib(rc, 10) and bool(em[10, rc]) and not bool(pm[10, rc]):
                return (Tool.ROAD, rc, 10)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 4 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)

    # PHASE 4: Zone placement - closed-loop reactive
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Block infrastructure rows/cols
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for rr in all_road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, max(0, wc-1):min(WORLD_W, wc+2)] = False
    for rc in all_road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = np.abs(cxs_arr - road_xs[i]).astype(float) + np.abs(cys_arr - road_ys[i]).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            zn_stride = max(1, len(zone_xs) // 100)
            min_zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = np.abs(cxs_arr - zone_xs[i]).astype(float) + np.abs(cys_arr - zone_ys[i]).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Penalize zones too close together (< 3) or too far (> 20)
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                                  np.where(min_zone_dist > 20, min_zone_dist * 0.3, 0.0))
        else:
            # Prefer center of map initially
            zone_score = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        # Prefer near road, cluster tightly but not too tight
        score = road_dist * 2.0 + zone_score * 0.5
        order = np.argsort(score)
        # Use step + pop for variety
        off = (step * 7 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # PHASE 5: Civic services reactive to population
    if pop > 50:
        fire_ys = list(range(18, WORLD_H - 5, 15))
        fire_xs = list(range(18, WORLD_W - 5, 20))
        for fsy in fire_ys:
            for fsx in fire_xs:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and not bool(pm[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        pol_ys = list(range(20, WORLD_H - 5, 15))
        pol_xs = list(range(20, WORLD_W - 5, 20))
        for psy in pol_ys:
            for psx in pol_xs:
                if ib(psx, psy) and bool(em[psy, psx]) and not bool(pm[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 400:
        park_ys = list(range(12, WORLD_H - 5, 11))
        park_xs = list(range(12, WORLD_W - 5, 13))
        for pky in park_ys:
            for pkx in park_xs:
                if ib(pkx, pky) and bool(em[pky, pkx]) and not bool(pm[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 700:
        stad_spots = [(35, 20), (85, 20), (35, 80), (85, 80), (60, 50)]
        for stx, sty in stad_spots:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuc_spots = [(nx, ny) for ny in range(12, 90, 22) for nx in range(12, 110, 22)]
        for npx, npy in nuc_spots:
            if ib(npx, npy) and bool(em[npy, npx]):
                x0, x1 = max(0, npx - 12), min(WORLD_W, npx + 13)
                y0, y1 = max(0, npy - 12), min(WORLD_H, npy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2500:
        airport_spots = [(60, 8), (60, 91), (8, 50), (111, 50)]
        for apx, apy in airport_spots:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3500:
        seaport_spots = [(8, 50), (111, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_spots:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # PHASE 6: Wire extension toward unpowered zones
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)

    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # PHASE 7: Road extension toward unserved zones
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1: shifted[:-1, :] = rm[1:, :]
        elif dy == 1: shifted[1:, :] = rm[:-1, :]
        elif dx == -1: shifted[:, :-1] = rm[:, 1:]
        elif dx == 1: shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[0:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, 0:2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # Fallback: place road near a plant
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(7, 0), (-7, 0), (0, 7), (0, -7), (5, 0), (-5, 0), (0, 5), (0, -5)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spine + initial roads."""
    actions = []
    cx, cy = 60, 50
    # Central coal power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine above center road
    for dx in range(-15, 16):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy - 1))
    # Vertical wire spine left of center column
    for dy in range(-12, 13):
        if dy != 0:
            actions.append((Tool.WIRE, cx - 1, cy + dy))
    # Initial horizontal road through center
    for dx in range(-15, 16):
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    # Initial vertical road
    for dy in range(-10, 11):
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # ---- PRECOMPUTE NEIGHBOR MASKS ----
    # Power proximity (wire or plant within 3 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy in range(-3, 4):
        for dx in range(-3, 4):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Road proximity (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT ----
    plant_count = int(np.sum(pm))
    # How many plants do we need based on pop?
    needed_plants = 1 + pop // 300

    if plant_count < needed_plants:
        # Place a new plant away from existing ones
        # Try candidate positions in a grid
        best_plant = None
        for py in range(15, 90, 20):
            for px in range(15, 110, 25):
                if not ib(px, py): continue
                # Check no plant within 15 tiles
                y0, y1 = max(0, py-15), min(WORLD_H, py+16)
                x0, x1 = max(0, px-15), min(WORLD_W, px+16)
                if bool(np.any(pm[y0:y1, x0:x1])): continue
                # Prefer empty spots
                if bool(em[py, px]):
                    best_plant = (px, py)
                    break
            if best_plant: break
        if best_plant:
            return (Tool.COALPOWER, best_plant[0], best_plant[1])

    # ---- PHASE 2: EXTEND WIRE FROM POWER SOURCES ----
    # Find frontier: empty tiles adjacent to existing wire/plant, not already powered
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)

    # Strategy: extend wire toward unpowered road tiles
    # Find roads without power nearby
    unpowered_roads = rm & ~nbr_power
    if bool(np.any(unpowered_roads)):
        road_locs = np.where(unpowered_roads)
        if len(road_locs[0]) > 0:
            # Pick nearest unpowered road to any wire
            # Find nearest wire to the centroid of unpowered roads
            cr_y = int(np.mean(road_locs[0]))
            cr_x = int(np.mean(road_locs[1]))

            # Find wire tile nearest to that centroid
            if len(wire_xs_arr) > 0:
                dists = (wire_xs_arr - cr_x)**2 + (wire_ys_arr - cr_y)**2
                k = int(np.argmin(dists))
                wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
                # Step wire toward target
                dx_step = 1 if cr_x > wx else (-1 if cr_x < wx else 0)
                dy_step = 1 if cr_y > wy else (-1 if cr_y < wy else 0)
                # Try horizontal first, then vertical
                for (ddx, ddy) in [(dx_step, 0), (0, dy_step), (dx_step, dy_step)]:
                    if ddx == 0 and ddy == 0: continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # Extend wire outward from any power source to reach more map area
    if len(wire_xs_arr) > 0:
        # Target: build wire grid at regular intervals
        # Horizontal wire lines at y = 20, 35, 50, 65, 80
        target_wire_ys = [20, 35, 50, 65, 80]
        target_wire_xs = [15, 35, 55, 75, 95, 110]

        for twy in target_wire_ys:
            for twx in target_wire_xs:
                if not ib(twx, twy): continue
                if bool(wm[twy, twx]) or bool(pm[twy, twx]): continue
                if not bool(em[twy, twx]): continue
                # Check if adjacent to wire/plant
                for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                    ax, ay = twx+adx, twy+ady
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        return (Tool.WIRE, twx, twy)

        # Generic extension: find an empty tile adjacent to wire that extends coverage
        step_k = (step * 7) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 40)):
            k = (step_k + offset * 3) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx2+adx, wy2+ady
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Only extend if it reaches new area (not already powered near)
                    # Check if this new wire would connect to something unpowered
                    y0,y1 = max(0,ny-4), min(WORLD_H,ny+5)
                    x0,x1 = max(0,nx-4), min(WORLD_W,nx+5)
                    has_unserved_road = bool(np.any(rm[y0:y1,x0:x1] & ~nbr_power[y0:y1,x0:x1]))
                    if has_unserved_road:
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: EXTEND ROADS ----
    # Target road positions: a grid
    target_road_ys = [22, 37, 52, 67, 82]  # one below wire lines
    target_road_xs = [17, 37, 57, 77, 97, 112]

    # Build roads adjacent to existing roads, prioritizing powered areas
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 60)):
            k = (step_k + offset * 5) % len(road_xs_arr)
            rx, ry = int(road_xs_arr[k]), int(road_ys_arr[k])
            for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = rx+adx, ry+ady
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Only extend road if there's power nearby
                    if bool(nbr_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # Place roads on target lines
    for try_ry in target_road_ys:
        for try_rx in range(10, 112):
            if not ib(try_rx, try_ry): continue
            if bool(rm[try_ry, try_rx]) or bool(pm[try_ry, try_rx]): continue
            if not bool(em[try_ry, try_rx]): continue
            if not bool(nbr_power[try_ry, try_rx]): continue
            # Adjacent to existing road?
            for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                ax, ay = try_rx+adx, try_ry+ady
                if ib(ax, ay) and bool(rm[ay, ax]):
                    return (Tool.ROAD, try_rx, try_ry)

    for try_rx in target_road_xs:
        for try_ry in range(15, 88):
            if not ib(try_rx, try_ry): continue
            if bool(rm[try_ry, try_rx]) or bool(pm[try_ry, try_rx]): continue
            if not bool(em[try_ry, try_rx]): continue
            if not bool(nbr_power[try_ry, try_rx]): continue
            for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                ax, ay = try_rx+adx, try_ry+ady
                if ib(ax, ay) and bool(rm[ay, ax]):
                    return (Tool.ROAD, try_rx, try_ry)

    # ---- PHASE 4: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 40% RES, 30% COM, 30% IND
        if rr < 0.38:
            return Tool.RESIDENTIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        if ir < 0.28:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone positions: empty, near road AND near power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to city center (60, 50) - build compact first
        cx_c, cy_c = 60, 50
        dist_to_center = np.sqrt((cxs - cx_c)**2 + (cys - cy_c)**2)
        order = np.argsort(dist_to_center)
        # Vary starting point slightly each step to avoid getting stuck
        offset = (step * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES (reactive: place when pop thresholds met) ----
    if pop > 80:
        # Fire stations at grid points
        for fy in range(22, 90, 18):
            for fx in range(17, 112, 22):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for py2 in range(30, 85, 20):
            for px2 in range(25, 108, 25):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        stadiums = [(30, 25), (90, 25), (30, 75), (90, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        seaports = [(8, 85), (112, 85), (8, 15), (112, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(40, 8), (80, 8), (40, 92), (80, 92)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR UPGRADE ----
    if pop > 1200 and step % 3 == 0:
        nuclear_spots = [
            (20, 50), (100, 50), (60, 15), (60, 85),
            (35, 35), (85, 35), (35, 65), (85, 65)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 400 and step % 4 == 0:
        park_cands = np.where(em & nbr_road)
        if len(park_cands[0]) > 0:
            idx = (step * 19) % len(park_cands[0])
            py3 = int(park_cands[0][idx])
            px3 = int(park_cands[1][idx])
            if ib(px3, py3) and bool(em[py3, px3]):
                return (Tool.PARK, px3, py3)

    # ---- FALLBACK: extend wire anywhere ----
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for adx, ady in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+adx, wy2+ady
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant ----
    if plant_count < 2:
        for r in range(2, 20):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = 60+dx, 50+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + cross wire grid + roads beside wires"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [15, 45, 75, 105]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads beside horizontal wire rows (above and below)
    for wy in [25, 50, 75]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
            actions.append((Tool.ROAD, x, wy + 2))
    # Roads beside vertical wire cols (left and right)
    for wx in [15, 45, 75, 105]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, wx - 2, y))
            actions.append((Tool.ROAD, wx + 2, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    wire_rows = [25, 50, 75]
    wire_cols = [15, 45, 75, 105]

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            # Start with balanced mix: more industrial/commercial early
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # High pop: push residential and commercial
            if cr < 0.40:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.15:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- Reactive: fix unpowered zones ---
    if step % 6 == 0:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 30)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # --- Reactive: fix zones without road access ---
    if step % 6 == 1:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- Reactive: repair horizontal wire rows ---
    if step % 6 == 2:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = (wx > 0) and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = (wx < WORLD_W-1) and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # --- Reactive: repair vertical wire cols ---
    if step % 6 == 3:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = (wy2 > 0) and (bool(wm[wy2-1, wc]) or bool(pm[wy2-1, wc]))
                    dn = (wy2 < WORLD_H-1) and (bool(wm[wy2+1, wc]) or bool(pm[wy2+1, wc]))
                    if (up or dn) and bool(em[wy2, wc]):
                        return (Tool.WIRE, wc, wy2)

    # --- Reactive: add power plants if needed ---
    if step % 6 == 4:
        plant_targets = [(30, 25), (90, 25), (30, 75), (90, 75), (60, 50),
                         (15, 50), (105, 50), (60, 20), (60, 80)]
        for px, py in plant_targets:
            x0, x1 = max(0, px-12), min(WORLD_W, px+13)
            y0, y1 = max(0, py-10), min(WORLD_H, py+11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    placed = False
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px+dx, py+dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if placed:
                        break

    # --- Reactive: repair roads beside wire rows ---
    if step % 6 == 5:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and (bool(wm[wr, rx]) or bool(pm[wr, rx])):
                        adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                               (ry > 0 and bool(rm[ry-1, rx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rx])) or
                               rx <= 2)
                        if adj:
                            return (Tool.ROAD, rx, ry)

    # --- Civic services gated on population ---
    if pop > 30:
        fire_spots = [
            (8, 8), (40, 8), (70, 8), (100, 8),
            (8, 35), (115, 35), (8, 60), (115, 60),
            (8, 88), (40, 88), (70, 88), (100, 88),
            (30, 50), (60, 35), (90, 35), (60, 65), (90, 65),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (22, 12), (52, 12), (82, 12), (112, 12),
            (22, 37), (52, 37), (82, 37), (112, 37),
            (22, 62), (52, 62), (82, 62), (112, 62),
            (22, 87), (52, 87), (82, 87), (112, 87),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [
            (30, 15), (90, 15), (30, 85), (90, 85),
            (60, 50), (15, 35), (105, 35), (15, 65), (105, 65),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (8, 50), (112, 50), (60, 8), (60, 92),
            (8, 25), (112, 25), (8, 75), (112, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(55, 5), (65, 5), (55, 92), (65, 92), (5, 48), (115, 48)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 10 == 7:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- Zone placement: main closed-loop logic ---
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Avoid wire corridors (protect infrastructure)
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Neighborhood centers: use a denser grid that avoids wire corridors
        # Focus zones in pockets between wire rows/cols
        if pop < 300:
            # Build in central cluster first
            active_centers = [
                (30, 12), (60, 12), (90, 12),
                (30, 37), (60, 37), (90, 37),
                (30, 62), (60, 62), (90, 62),
                (30, 87), (60, 87), (90, 87),
            ]
        elif pop < 1000:
            # Expand across the map
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 10 + row * 18
                    active_centers.append((cx, cy))
        else:
            # Dense saturation
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 6 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road toward powered empty tiles
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 100)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 60)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place coal plant + wire spine + flanking roads."""
    actions = []
    cx, cy = 60, 50
    # Primary plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire horizontally from plant
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Wire vertically from plant
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking wire spine
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- NEIGHBORHOOD ANCHORS: 5 cols x 5 rows = 25 ----
    anchors = []
    for col_i, cx in enumerate([15, 35, 55, 75, 95]):
        for row_i, cy in enumerate([15, 32, 50, 68, 85]):
            anchors.append((cx, cy, col_i * 5 + row_i))

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 3
        if pop < 500:   return 5
        if pop < 1000:  return 8
        if pop < 2000:  return 12
        if pop < 3500:  return 18
        return 25

    active = anchors[:num_active()]

    # ---- PHASE 1: ENSURE POWER PLANTS for each active neighborhood ----
    for (px, py, idx) in active:
        has_plant = False
        for dx in range(-6, 7):
            for dy in range(-6, 7):
                nx, ny = px + dx, py + dy
                if ib(nx, ny) and bool(pm[ny, nx]):
                    has_plant = True
                    break
            if has_plant:
                break
        if not has_plant:
            # Try to place coal plant near anchor
            for r in range(0, 12):
                found = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r == 0 or abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                if found:
                    break

    # ---- PHASE 2: CONNECT WIRE from plant to uncovered active anchors ----
    wire_ys, wire_xs = np.where(wm | pm)
    if len(wire_xs) > 0:
        for (px, py, idx) in active:
            dists = np.abs(wire_xs.astype(float) - px) + np.abs(wire_ys.astype(float) - py)
            min_dist = float(dists.min())
            if min_dist > 3:
                closest_k = np.argmin(dists)
                wx, wy = int(wire_xs[closest_k]), int(wire_ys[closest_k])
                # Step toward anchor
                dx = 1 if px > wx else (-1 if px < wx else 0)
                dy = 1 if py > wy else (-1 if py < wy else 0)
                for (ddx, ddy) in [(dx, 0), (0, dy)]:
                    if ddx == 0 and ddy == 0:
                        continue
                    nx, ny = wx + ddx, wy + ddy
                    if ib(nx, ny) and not bool(pm[ny, nx]) and (bool(em[ny, nx]) or bool(wm[ny, nx])):
                        return (Tool.WIRE, nx, ny)

    # ---- PHASE 3: EXTEND WIRE VERTICAL SPINE for each active anchor ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            for dy in range(-5, 6):
                ny = py + dy
                if ib(px, ny) and bool(em[ny, px]) and not bool(pm[ny, px]):
                    return (Tool.WIRE, px, ny)
        else:
            ext = min(25, 10 + pop // 60)
            spine_top = max(2, py - ext)
            spine_bot = min(WORLD_H - 3, py + ext)
            max_wr = max(wire_col)
            min_wr = min(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(px, nr) and not bool(pm[nr, px]) and (bool(em[nr, px]) or bool(wm[nr, px])):
                    return (Tool.WIRE, px, nr)

    # ---- PHASE 4: HORIZONTAL WIRE between adjacent anchors in same row ----
    row_groups = {}
    for (px, py, idx) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append(px)

    for row_y, group in row_groups.items():
        group_sorted = sorted(group)
        for i in range(len(group_sorted) - 1):
            x1, x2 = group_sorted[i], group_sorted[i + 1]
            mid_x = (x1 + x2) // 2
            # Check if gap is already wired
            gap_wired = all(bool(wm[row_y, cx]) or bool(pm[row_y, cx]) for cx in range(x1 + 1, x2))
            if not gap_wired:
                # Find first unwired spot near midpoint
                for cx in range(x1 + 1, x2):
                    if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                        return (Tool.WIRE, cx, row_y)

    # ---- PHASE 5: ROADS flanking wire spines ----
    for (px, py, idx) in active:
        wire_col = [r for r in range(WORLD_H) if ib(px, r) and bool(wm[r, px])]
        if not wire_col:
            continue
        cycle_off = (step + idx * 13) % max(len(wire_col), 1)
        for k in range(min(len(wire_col), 12)):
            wr = wire_col[(cycle_off + k) % len(wire_col)]
            for side in [px - 1, px + 1]:
                if ib(side, wr) and bool(em[wr, side]) and not bool(pm[wr, side]):
                    return (Tool.ROAD, side, wr)

    # ---- PHASE 6: HORIZONTAL ROADS connecting neighborhoods ----
    for (px, py, idx) in active:
        for dx in range(-12, 13):
            rx = px + dx
            if not ib(rx, py):
                continue
            if bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near = any(
                    ib(rx + d, py) and (bool(rm[py, rx + d]) or bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near:
                    return (Tool.ROAD, rx, py)

    # ---- PHASE 7: ZONE PLACEMENT ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Want ~15% industrial, ~25% commercial, rest residential
        if ir < 0.15:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-6, 7):
        for dx in range(-6, 7):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, idx) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 5) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- PHASE 8: EXTEND ROADS along existing road toward wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 7) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 60)):
            k = (step_k + offset * 11) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 200:
        firestations = [
            (25, 15), (45, 15), (65, 15), (85, 15),
            (25, 35), (45, 35), (65, 35), (85, 35),
            (25, 55), (45, 55), (65, 55), (85, 55),
            (25, 75), (45, 75), (65, 75), (85, 75),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 600:
        polices = [
            (35, 25), (55, 25), (75, 25), (95, 25),
            (35, 45), (55, 45), (75, 45), (95, 45),
            (35, 65), (55, 65), (75, 65), (95, 65),
            (35, 85), (55, 85), (75, 85), (95, 85),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1200:
        stadiums = [
            (25, 10), (60, 10), (95, 10),
            (25, 90), (60, 90), (95, 90),
            (10, 50), (110, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(10, 90), (110, 90), (10, 10), (110, 10)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- PHASE 10: NUCLEAR PLANT for high pop ----
    if pop > 3000:
        for (px, py, idx) in active:
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.NUCLEARPOWER, nx, ny)

    # ---- FALLBACK: Extend wire from any wire tile ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 17) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 50)):
            k = (step_k2 + offset * 9) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: compact central power + road/wire grid for fast start"""
    actions = []
    # Two coal plants near center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines
    for wr in [30, 50, 70]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wr))
    # Vertical wire spines
    for wc in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wc, y))
    # Roads along wire rows (offset by 2 to leave zone space)
    for wr in [28, 32, 48, 52, 68, 72]:
        if 0 < wr < 99:
            for x in range(1, 119):
                actions.append((Tool.ROAD, x, wr))
    # Roads along wire cols
    for wc in [28, 32, 58, 62, 88, 92]:
        if 0 < wc < 119:
            for y in range(1, 99):
                actions.append((Tool.ROAD, wc, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 40% res, 35% com, 25% ind (more commercial than parent)
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [30, 50, 70]
    wire_cols = [30, 60, 90]
    road_rows = [28, 32, 48, 52, 68, 72]
    road_cols = [28, 32, 58, 62, 88, 92]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 16

    # Phase 0: Add coal plants if power is sparse
    if phase == 0:
        plant_targets = [
            (30, 50), (90, 50),
            (30, 20), (90, 20),
            (30, 80), (90, 80),
            (60, 35), (60, 65),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fix wire row gaps
    if phase == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    if bool(em[wr, wx]):
                        left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                        right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                        if left or right or wx == 1:
                            return (Tool.WIRE, wx, wr)

    # Phase 2: Fix wire col gaps
    if phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    if bool(em[wy, wc]):
                        up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                        dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                        if up or dn or wy == 1:
                            return (Tool.WIRE, wc, wy)

    # Phase 3: Fix road row gaps
    if phase == 3:
        for rr2 in road_rows:
            if not (0 < rr2 < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr2, rx]) and not bool(pm[rr2, rx]) and not bool(wm[rr2, rx]):
                    adj = (rx > 0 and bool(rm[rr2, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr2, rx+1]))
                    if adj or rx == 1:
                        if bool(near_power[rr2, rx]) or rx < 5:
                            return (Tool.ROAD, rx, rr2)

    # Phase 4: Fix road col gaps
    if phase == 4:
        for rc2 in road_cols:
            if not (0 < rc2 < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc2]) and not bool(pm[ry, rc2]) and not bool(wm[ry, rc2]):
                    adj = (ry > 0 and bool(rm[ry-1, rc2])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc2]))
                    if adj or ry == 1:
                        if bool(near_power[ry, rc2]) or ry < 5:
                            return (Tool.ROAD, rc2, ry)

    # Phase 5: Add extra horizontal roads for zone access
    if phase == 5:
        extra_rows = [10, 15, 20, 25, 40, 45, 60, 65, 80, 85, 90, 95]
        for mr in extra_rows:
            if mr <= 0 or mr >= WORLD_H - 1:
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                    adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mr, rx+1])) or \
                          (bool(rm[mr-1, rx]) if mr > 0 else False) or \
                          (bool(rm[mr+1, rx]) if mr < WORLD_H-1 else False)
                    if adj:
                        return (Tool.ROAD, rx, mr)

    # Phase 6: Add extra vertical roads
    if phase == 6:
        extra_cols = [10, 15, 20, 45, 50, 75, 80, 100, 105, 110]
        for mc in extra_cols:
            if mc <= 0 or mc >= WORLD_W - 1:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                    adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mc])) or \
                          (bool(rm[ry, mc-1]) if mc > 0 else False) or \
                          (bool(rm[ry, mc+1]) if mc < WORLD_W-1 else False)
                    if adj:
                        return (Tool.ROAD, mc, ry)

    # Phase 7: Wire unpowered zones
    if phase == 7:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Nuclear power when pop grows
    if phase == 8 and pop > 300:
        nuke_spots = [
            (15, 50), (105, 50), (60, 15), (60, 85),
            (15, 25), (105, 25), (15, 75), (105, 75),
            (45, 50), (75, 50), (60, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Civic buildings: fire stations early
    if pop > 2:
        fire_spots = [
            (10, 10), (40, 10), (70, 10), (100, 10),
            (10, 40), (40, 40), (70, 40), (100, 40),
            (10, 60), (40, 60), (70, 60), (100, 60),
            (10, 85), (40, 85), (70, 85), (100, 85),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 30:
        police_spots = [
            (20, 20), (50, 20), (80, 20), (110, 20),
            (20, 45), (50, 45), (80, 45), (110, 45),
            (20, 65), (50, 65), (80, 65), (110, 65),
            (20, 88), (50, 88), (80, 88), (110, 88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150:
        stadium_spots = [
            (25, 15), (65, 15), (100, 15),
            (25, 55), (65, 55), (100, 55),
            (25, 80), (65, 80), (100, 80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1200:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 60 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop, priority-based ----
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False
    # Exclude wire corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Expand coverage based on population
        if pop < 30:
            # Start near center with tight cluster
            active_centers = [
                (55, 40), (60, 40), (65, 40),
                (55, 55), (60, 55), (65, 55),
                (55, 70), (60, 70), (65, 70),
            ]
        elif pop < 150:
            # Two neighborhoods
            active_centers = []
            for row in range(4):
                for col in range(5):
                    cx = 20 + col * 20
                    cy = 20 + row * 18
                    active_centers.append((cx, cy))
                    active_centers.append((cx + 65, cy))
        elif pop < 500:
            # Three strips
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 10 + col * 14
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        else:
            # Full grid
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 8 + col * 10
                    cy = 7 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary starting offset by step and pop for closed-loop variety
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road near power
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 9) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

