        cr = com_count / total_zones
        rr = res_count / total_zones
        # ~35% res, ~35% com, ~30% ind
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire grid structure - horizontal rows and vertical cols
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [6, 18, 30, 42, 54, 66, 78, 90, 102, 114]

    # ---- PHASE 0: Reactively place coal plants in unpowered areas ----
    if step % 4 == 0:
        # Find unpowered regions that have empty space
        unpowered_empty = em & ~near_power
        if np.any(unpowered_empty):
            # Find candidate plant locations near wire cols/rows
            plant_targets = [(px, py) for py in [20, 35, 50, 65, 80]
                             for px in [18, 42, 66, 90, 114]]
            for px, py in plant_targets:
                x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
                y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
                # Only place if no plant nearby
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    # Check if this area needs power
                    if bool(np.any(unpowered_empty[max(0,py-8):py+9, max(0,px-8):px+9])):
                        for r in range(8):
                            placed = False
                            for dy in range(-r, r + 1):
                                for dx in range(-r, r + 1):
                                    if abs(dx) == r or abs(dy) == r or r == 0:
                                        nx2, ny2 = px + dx, py + dy
                                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                            return (Tool.COALPOWER, nx2, ny2)
                                        placed = True
                            if placed:
                                break

    # ---- PHASE 1: Extend horizontal wire rows reactively ----
    if step % 5 == 1:
        for wr in wire_rows:
            # Check if row is partially wired - extend it
            row_has_power = bool(np.any(pm[wr, :] | wm[wr, :]))
            if row_has_power:
                for wx in range(1, WORLD_W - 1):
                    if bool(wm[wr, wx]) or bool(pm[wr, wx]):
                        continue
                    if not bool(em[wr, wx]):
                        continue
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)
            else:
                # Connect this row to nearest plant/wire via vertical wire
                for wc in wire_cols:
                    if bool(wm[wr, wc]) or bool(pm[wr, wc]):
                        continue
                    # Search vertically for existing wire/plant
                    for dy in [1, -1]:
                        ny2 = wr + dy
                        if ib(wc, ny2) and (bool(wm[ny2, wc]) or bool(pm[ny2, wc])):
                            if bool(em[wr, wc]):
                                return (Tool.WIRE, wc, wr)

    # ---- PHASE 2: Extend vertical wire cols reactively ----
    if step % 5 == 2:
        for wc in wire_cols:
            col_has_power = bool(np.any(pm[:, wc] | wm[:, wc]))
            if col_has_power:
                for wy in range(1, WORLD_H - 1):
                    if bool(wm[wy, wc]) or bool(pm[wy, wc]):
                        continue
                    if not bool(em[wy, wc]):
                        continue
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: Extend roads alongside wire rows ----
    if step % 5 == 3:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (1 <= ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Only place road where wire row is powered above/below
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  bool(rm[max(0,ry-1), rx]) or bool(rm[min(WORLD_H-1,ry+1), rx])
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Roads alongside wire cols + extend from existing road ----
    if step % 5 == 4:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (1 <= rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = bool(rm[max(0,ry-1), rcx]) or \
                                  bool(rm[min(WORLD_H-1,ry+1), rcx]) or \
                                  (rcx > 0 and bool(rm[ry, rcx-1])) or \
                                  (rcx < WORLD_W-1 and bool(rm[ry, rcx+1]))
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

        # Also extend road into powered empty areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 400)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 20:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 18) for fy in range(10, WORLD_H, 18)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 22) for py2 in range(14, WORLD_H, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 250:
        stadium_spots = [(25, 12), (65, 12), (105, 12),
                         (25, 45), (65, 45), (105, 45),
                         (25, 75), (65, 75), (105, 75),
                         (25, 90), (65, 90), (105, 90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 400:
        nuke_spots = [(10, 50), (110, 50), (60, 10), (60, 90),
                      (10, 20), (110, 20), (10, 80), (110, 80),
                      (35, 10), (85, 10), (35, 90), (85, 90)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 700:
        seaports = [(5, 92), (115, 92), (5, 8), (115, 8),
                    (60, 5), (60, 95), (5, 50), (115, 50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1200:
        airports = [(50, 5), (70, 5), (50, 93), (70, 93),
                    (5, 44), (110, 44), (5, 56), (110, 56)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 3 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop, reactive ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Reactively pick zone center based on pop
        if pop < 80:
            active_centers = [(cx, cy) for cy in [47, 53] for cx in [25, 45, 60, 75, 95]]
        elif pop < 250:
            active_centers = [(cx, cy) for cy in [28, 40, 47, 53, 62, 72]
                              for cx in [12, 32, 52, 72, 92, 112]]
        elif pop < 600:
            active_centers = [(cx, cy) for cy in [15, 25, 38, 48, 55, 65, 75, 85]
                              for cx in [10, 25, 40, 55, 70, 85, 100, 115]]
        else:
            active_centers = [(cx, cy) for cy in range(7, 100, 6)
                              for cx in range(6, 120, 6)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use population-reactive offset for variety
        offset = (step * 13 + pop * 11) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- FALLBACK: extend road from existing into powered area ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 17) % len(road_xs2)
        for off in range(min(len(road_xs2), 200)):
            k = (sk + off * 9) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 19) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place coal plant near unpowered zone ----
    all_hoods = [(cx, cy) for cy in range(10, 100, 10) for cx in range(6, 120, 10)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + road grid"""
    actions = []
    # Two central coal plants
    for px, py in [(58, 48), (58, 52)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [32, 50, 68]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 50, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows
    for wy in [32, 50, 68]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 2))
            actions.append((Tool.ROAD, x, wy + 2))
    # Roads flanking wire cols
    for wx in [20, 50, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, wx - 2, y))
            actions.append((Tool.ROAD, wx + 2, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    wire_rows = [32, 50, 68]
    wire_cols = [20, 50, 80, 100]

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 300:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.35:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.42:
                return Tool.COMMERCIAL
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if ir < 0.18:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- Priority 1: Repair wire spines (most critical for power) ---
    if step % 6 == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    if bool(em[wr, wx]):
                        # Check neighbor connectivity
                        has_neighbor = (
                            (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))) or
                            (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                        )
                        if has_neighbor:
                            return (Tool.WIRE, wx, wr)

    if step % 6 == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    if bool(em[wy, wc]):
                        has_neighbor = (
                            (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or
                            (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                        )
                        if has_neighbor:
                            return (Tool.WIRE, wc, wy)

    # --- Priority 2: Fix road spines ---
    if step % 6 == 2:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                               (ry > 0 and bool(rm[ry-1, rx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                        if adj or rx == 1:
                            return (Tool.ROAD, rx, ry)

    if step % 6 == 3:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                               bool(rm[ry, max(0, rcx-1)]) or
                               bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                        if adj or ry == 1:
                            return (Tool.ROAD, rcx, ry)

    # --- Priority 3: Connect unpowered zones to wire ---
    if step % 6 == 4:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                best_zone = None
                best_dist = 999999
                for i in range(min(len(uz_xs), 40)):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # --- Priority 4: Connect unroaded zones ---
    if step % 6 == 5:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- Add power plants reactively where needed ---
    if step % 8 == 0:
        # Scan grid for areas with zones but no nearby power
        plant_grid = []
        for py in range(10, WORLD_H - 5, 18):
            for px in range(10, WORLD_W - 5, 18):
                plant_grid.append((px, py))
        for ppx, ppy in plant_grid:
            x0, x1 = max(0, ppx - 14), min(WORLD_W, ppx + 15)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            has_zones = bool(np.any(zone_tiles[y0:y1, x0:x1]))
            if not has_plant and has_zones:
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = ppx + dx, ppy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    tool_choice = Tool.NUCLEARPOWER if pop > 600 else Tool.COALPOWER
                                    return (tool_choice, nx2, ny2)

    # --- Civic services (population-gated) ---
    if pop > 20:
        fire_spots = [
            (10, 10), (40, 10), (70, 10), (100, 10),
            (10, 40), (100, 40), (10, 60), (100, 60),
            (10, 85), (40, 85), (70, 85), (100, 85),
            (35, 50), (65, 50), (50, 25), (50, 75),
            (25, 50), (90, 50), (15, 30), (15, 70),
            (105, 30), (105, 70),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (20, 15), (55, 15), (85, 15), (112, 15),
            (20, 44), (55, 44), (85, 44), (112, 44),
            (20, 60), (55, 60), (85, 60), (112, 60),
            (20, 80), (55, 80), (85, 80), (112, 80),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (25, 12), (85, 12), (25, 86), (85, 86),
            (55, 50), (10, 50), (110, 50),
            (40, 35), (70, 35), (40, 65), (70, 65),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (15, 20), (105, 20), (15, 80), (105, 80),
            (35, 8), (85, 8), (35, 92), (85, 92),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(48, 5), (72, 5), (48, 93), (72, 93), (5, 45), (115, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 80 and step % 13 == 7:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- Zone placement: reactive, dense, near power+road ---
    cand_mask = em & near_road & near_power
    # Exclude borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire spines
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Build active centers based on population
        if pop < 200:
            # Focus on center
            active_centers = [
                (35, 41), (35, 59), (65, 41), (65, 59),
                (95, 41), (95, 59), (35, 20), (65, 20),
                (95, 20), (35, 78), (65, 78), (95, 78),
                (12, 41), (12, 59), (112, 41), (112, 59),
            ]
        elif pop < 800:
            active_centers = []
            for bx in [9, 18, 27, 36, 45, 55, 65, 74, 83, 92, 109, 116]:
                for by in [9, 18, 27, 38, 44, 56, 62, 74, 83, 92]:
                    active_centers.append((bx, by))
        else:
            # Fine grid covering whole map
            active_centers = []
            for row in range(11):
                for col in range(14):
                    cx = 4 + col * 8
                    cy = 4 + row * 8
                    active_centers.append((cx, cy))

        # Score candidates
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Prefer dense areas
        zone_near = dilate(zone_tiles, 5)
        zone_bonus = np.where(zone_near[cys, cxs], -4.0, 0.0)
        combined_score = best_dist + zone_bonus

        order = np.argsort(combined_score)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road toward powered empty area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 100)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 60)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
