def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Target plant grid: 5 cols x 4 rows = 20 positions
    plant_positions = []
    for row in range(4):
        for col in range(5):
            px = 12 + col * 24   # 12, 36, 60, 84, 108
            py = 12 + row * 26   # 12, 38, 64, 90
            plant_positions.append((px, py))

    # Wire corridor layout
    wire_rows = [6, 18, 30, 42, 54, 66, 78, 90]
    wire_cols = [6, 18, 30, 42, 54, 66, 78, 90, 102, 114]

    # ---- PHASE 1: ENSURE PLANTS ----
    # Only place plants as needed based on population
    n_plants_needed = 1
    if pop > 50:   n_plants_needed = 4
    if pop > 200:  n_plants_needed = 8
    if pop > 500:  n_plants_needed = 12
    if pop > 1000: n_plants_needed = 16
    if pop > 2000: n_plants_needed = 20

    for px, py in plant_positions[:n_plants_needed]:
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE CORRIDORS ----
    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                # Seed from nearest plant
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        l = wx > 0 and bool(row_power[wx - 1])
                        r2 = wx < WORLD_W - 1 and bool(row_power[wx + 1])
                        if (l or r2) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx else -1
                    for nx in range(bpx + step_x, wc + step_x, step_x):
                        if ib(nx, bpy) and bool(em[bpy, nx]) and not bool(pm[bpy, nx]):
                            return (Tool.WIRE, nx, bpy)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        u = wy > 0 and bool(col_power[wy - 1])
                        d = wy < WORLD_H - 1 and bool(col_power[wy + 1])
                        if (u or d) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking horizontal wire corridors
        for wr in wire_rows:
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_power[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking vertical wire corridors
        for wc in wire_cols:
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_power[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Connect wire corridors at intersections
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and (bool(wm[wr, wc-1]) or bool(pm[wr, wc-1]))) or \
                         (wc < WORLD_W-1 and (bool(wm[wr, wc+1]) or bool(pm[wr, wc+1])))
                col_ok = (wr > 0 and (bool(wm[wr-1, wc]) or bool(pm[wr-1, wc]))) or \
                         (wr < WORLD_H-1 and (bool(wm[wr+1, wc]) or bool(pm[wr+1, wc])))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 5:
        # Cross-connect roads between wire rows (vertical connectors)
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    # Fill gap between roads
                    for ry in range(wr1 + 2, wr2 - 1):
                        if ib(rcx, ry) and bool(em[ry, rcx]) and bool(near_power[ry, rcx]):
                            adj = (ib(rcx, ry-1) and bool(rm[ry-1, rcx])) or \
                                  (ib(rcx, ry+1) and bool(rm[ry+1, rcx]))
                            if adj:
                                return (Tool.ROAD, rcx, ry)

    elif phase == 6:
        # Cross-connect roads between wire cols (horizontal connectors)
        for wc_idx in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[wc_idx], wire_cols[wc_idx + 1]
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    for rx in range(wc1 + 2, wc2 - 1):
                        if ib(rx, ry) and bool(em[ry, rx]) and bool(near_power[ry, rx]):
                            adj = (ib(rx-1, ry) and bool(rm[ry, rx-1])) or \
                                  (ib(rx+1, ry) and bool(rm[ry, rx+1]))
                            if adj:
                                return (Tool.ROAD, rx, ry)

    elif phase == 7:
        # Extend roads toward powered but unroaded areas
        target_mask = near_power & ~near_road & em
        target_mask[0:3, :] = False
        target_mask[WORLD_H-3:, :] = False
        target_mask[:, 0:3] = False
        target_mask[:, WORLD_W-3:] = False
        tys, txs = np.where(target_mask)
        road_ys, road_xs = np.where(rm)
        if len(txs) > 0 and len(road_xs) > 0:
            ti = (step * 17) % len(txs)
            tx, ty = int(txs[ti]), int(tys[ti])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Wire toward unpowered roads
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    else:
        # Extend existing roads outward
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            step_k = (step * 11) % len(road_xs2)
            for offset in range(min(len(road_xs2), 120)):
                k = (step_k + offset * 7) % len(road_xs2)
                rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                       not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid placing zones on wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 1.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.3 / (1.0 + abs(x - 60) / 60.0 + abs(y - 50) / 50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 700:
                break

    # ---- CIVIC SERVICES ----
    if pop > 50:
        fire_positions = [
            (12, 6), (36, 6), (60, 6), (84, 6), (108, 6),
            (12, 32), (36, 32), (60, 32), (84, 32), (108, 32),
            (12, 58), (36, 58), (60, 58), (84, 58), (108, 58),
            (12, 84), (36, 84), (60, 84), (84, 84), (108, 84),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_positions = [
            (24, 19), (48, 19), (72, 19), (96, 19),
            (12, 45), (36, 45), (60, 45), (84, 45), (108, 45),
            (24, 71), (48, 71), (72, 71), (96, 71),
            (12, 87), (60, 87), (108, 87),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 30), (90, 30), (30, 70), (90, 70),
            (60, 20), (60, 80), (10, 50), (110, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
            (30, 50), (90, 50), (30, 25), (90, 25),
            (30, 75), (90, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 97)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 5), (80, 5), (40, 92), (80, 92),
                    (5, 30), (5, 70), (115, 30), (115, 70)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant near uncovered area ----
    plant_ys_all, plant_xs_all = np.where(pm)
    if len(plant_xs_all) == 0:
        if ib(60, 50) and bool(em[50, 60]):
            return (Tool.COALPOWER, 60, 50)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spine + road grid"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at x=30 and x=90
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Roads flanking the horizontal wire spine (denser - every 4 instead of 2)
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    # Vertical roads flanking wire spines
    for y in range(1, 99):
        actions.append((Tool.ROAD, 27, y))
        actions.append((Tool.ROAD, 33, y))
        actions.append((Tool.ROAD, 87, y))
        actions.append((Tool.ROAD, 93, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.20:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if ir < 0.22:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1500:
            if cr < 0.32:
                return Tool.COMMERCIAL
            if rr < 0.48:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.38:
                return Tool.COMMERCIAL
            if rr < 0.42:
                return Tool.RESIDENTIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def adj_mask(mask):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        result[1:, :] |= mask[:-1, :]
        result[:-1, :] |= mask[1:, :]
        result[:, 1:] |= mask[:, :-1]
        result[:, :-1] |= mask[:, 1:]
        return result & ~mask

    phase = step % 8

    # === PHASE 0: Ensure power plants distributed across regions ===
    if phase == 0:
        plant_spacing = 22
        for py in range(10, WORLD_H - 5, plant_spacing):
            for px in range(10, WORLD_W - 5, plant_spacing):
                x0, x1 = max(0, px - 11), min(WORLD_W, px + 12)
                y0, y1 = max(0, py - 11), min(WORLD_H, py + 12)
                if not np.any(pm[y0:y1, x0:x1]):
                    for r in range(0, 10):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 1: Extend wire toward unpowered areas ===
    if phase == 1:
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            wire_adj = adj_mask(power_src) & em & ~zone_tiles
            wire_adj[0:2, :] = False
            wire_adj[WORLD_H-2:, :] = False
            wire_adj[:, 0:2] = False
            wire_adj[:, WORLD_W-2:] = False
            wys, wxs = np.where(wire_adj)
            if len(wxs) > 0:
                sample_indices = np.linspace(0, len(upxs)-1, min(25, len(upxs)), dtype=int)
                best_score = -1
                best_k = 0
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_indices)
                    score = 1000 - d
                    if score > best_score:
                        best_score = score
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # === PHASE 2: Extend wire from plants toward road grid ===
    if phase == 2:
        unp_roads = rm & ~near_power
        upr_ys, upr_xs = np.where(unp_roads)
        if len(upr_xs) > 0:
            wire_adj2 = adj_mask(power_src) & em & ~zone_tiles
            wys2, wxs2 = np.where(wire_adj2)
            if len(wxs2) > 0:
                idx = (step * 13) % len(upr_xs)
                tx, ty = int(upr_xs[idx]), int(upr_ys[idx])
                best_dist = 1e9
                best_k = 0
                for i in range(min(len(wxs2), 200)):
                    cx, cy = int(wxs2[i]), int(wys2[i])
                    d = abs(cx - tx) + abs(cy - ty)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.WIRE, int(wxs2[best_k]), int(wys2[best_k]))

    # === PHASE 3: Extend road network on a tighter grid ===
    if phase == 3:
        # Tighter road grid spacing (every 4 instead of 6) for better zone access
        road_grid_targets = []
        for gy in range(4, 97, 4):
            for gx in range(4, 115, 4):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        if road_grid_targets:
            road_adj = adj_mask(rm) & em & near_power & ~zone_tiles
            road_adj[0:2, :] = False
            road_adj[WORLD_H-2:, :] = False
            road_adj[:, 0:2] = False
            road_adj[:, WORLD_W-2:] = False
            rys2, rxs2 = np.where(road_adj)
            if len(rxs2) > 0:
                targets_sample = road_grid_targets[:60]
                best_dist = 1e9
                best_k = 0
                for i in range(min(len(rxs2), 500)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
            else:
                for gx, gy in road_grid_targets[:5]:
                    if bool(em[gy, gx]):
                        return (Tool.ROAD, gx, gy)

        # Connect unroaded zones
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # === PHASE 4: Civic services ===
    if phase == 4:
        if pop > 20:
            fire_grid = [(fx, fy) for fy in range(8, 95, 10) for fx in range(8, 115, 10)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        if pop > 80:
            police_grid = [(px2, py2) for py2 in range(10, 90, 12) for px2 in range(10, 110, 12)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        if pop > 250 and step % 8 == 4:
            park_cands = em & near_road & near_power & ~zone_tiles
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 31 + pop) % len(pxs3)
                px2, py2 = int(pxs3[idx]), int(pys3[idx])
                return (Tool.PARK, px2, py2)

        if pop > 350:
            stadium_locs = [(30, 20), (90, 20), (30, 80), (90, 80),
                            (60, 50), (10, 50), (110, 50), (60, 10), (60, 85),
                            (45, 35), (75, 35), (45, 65), (75, 65),
                            (20, 35), (100, 35), (20, 65), (100, 65)]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        if pop > 600:
            nuke_locs = [(10, 20), (110, 20), (10, 80), (110, 80),
                         (60, 8), (60, 92), (8, 50), (112, 50),
                         (35, 12), (85, 12), (35, 88), (85, 88),
                         (20, 5), (100, 5), (20, 95), (100, 95)]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                    y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            airport_locs = [(8, 8), (102, 8), (8, 88), (102, 88), (55, 8), (55, 88)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        if pop > 1500:
            seaport_locs = [(4, 50), (116, 50), (60, 4), (60, 96)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # === PHASE 5, 6, 7: Zone placement (more steps devoted to zoning) ===
    # Zones need power + road within 3 tiles
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 100)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 100)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.full(len(cxs_arr), 10.0)

        # Score: prefer close to road, moderate spacing from other zones
        # Use tighter spacing (4 instead of 6) to pack more zones
        score = road_dist * 1.2 + np.maximum(0, 4 - zone_dist) * 2.5

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road in powered areas ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire/road cross pattern"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine connecting them
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Roads adjacent to wire spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    # Vertical roads adjacent to vertical wire spines
    for y in range(1, 99):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
        actions.append((Tool.ROAD, 89, y))
        actions.append((Tool.ROAD, 91, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Target mix: 40% res, 30% com, 30% ind for balanced growth
    def pick_tool():
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Wire grid: horizontal rows and vertical columns
    # Use a tighter grid than parent: every 12 rows/cols
    wire_rows = list(range(8, 99, 12))   # 8,20,32,44,56,68,80,92
    wire_cols = list(range(8, 120, 12))  # 8,20,32,44,56,68,80,92,104,116

    phase = step % 20

    # Phase 0: Add more coal plants if needed
    if phase == 0:
        plant_targets = []
        for py in range(10, 95, 25):
            for px in range(15, 115, 30):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 18), min(WORLD_W, px + 19)
            y0, y1 = max(0, py - 18), min(WORLD_H, py + 19)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill horizontal wire rows
    if phase == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    if bool(em[wr, wx]):
                        # Check connectivity
                        left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                        right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                        if left or right:
                            return (Tool.WIRE, wx, wr)

    # Phase 2: Fill vertical wire cols
    if phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    if bool(em[wy, wc]):
                        up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                        dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                        if up or dn:
                            return (Tool.WIRE, wc, wy)

    # Phase 3: Roads adjacent to wire rows (both sides)
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        if has_wire and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Roads adjacent to wire cols (both sides)
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                   bool(rm[ry, max(0, rcx-1)]) or \
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        if has_wire and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # Phase 5: Cross-roads between wire rows at mid-points
    if phase == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 6: Cross-roads between wire cols
    if phase == 6:
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = (ry > 0 and bool(rm[ry-1, mid_x])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    # Phase 7: Wire unpowered zones
    if phase == 7:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17 + pop * 5) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Fill wire gaps for roads without power
    if phase == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23 + pop * 7) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Civic services based on population thresholds
    if pop > 10:
        fire_spots = [
            (5,5),(60,5),(115,5),
            (5,25),(115,25),
            (5,50),(115,50),
            (5,75),(115,75),
            (5,95),(60,95),(115,95),
            (30,15),(90,15),(30,85),(90,85),
            (30,50),(90,50),(60,30),(60,70),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (15,10),(45,10),(75,10),(105,10),
            (15,30),(45,30),(75,30),(105,30),
            (15,50),(45,50),(75,50),(105,50),
            (15,70),(45,70),(75,70),(105,70),
            (15,90),(45,90),(75,90),(105,90),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        # Nuclear plants for more power capacity
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (5, 50), (115, 50), (60, 5), (60, 95),
            (30, 5), (90, 5), (30, 95), (90, 95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 250:
        stadium_spots = [
            (20,15),(60,15),(100,15),
            (20,50),(60,50),(100,50),
            (20,85),(60,85),(100,85),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        seaports = [(5, 92), (115, 92), (5, 8), (115, 8)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 29 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop primary action ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors themselves
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Cluster around intersection points of wire grid - denser than parent
        if pop < 100:
            # Start near center
            active_centers = [(60, 50), (45, 44), (75, 44), (45, 56), (75, 56)]
        elif pop < 400:
            # Expand to a 3x3 neighborhood grid
            active_centers = []
            for row in range(4):
                for col in range(5):
                    cx = 20 + col * 20
                    cy = 20 + row * 20
                    active_centers.append((cx, cy))
        elif pop < 1000:
            # Full neighborhood coverage
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 10 + col * 13
                    cy = 10 + row * 13
                    active_centers.append((cx, cy))
        else:
            # Max coverage
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 6 + col * 10
                    cy = 6 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary offset by both step and population for diversity
        offset = (step * 11 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 1000)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13 + pop * 3) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17 + pop * 11) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

# Strategy: Dense grid layout with multiple power plants, balanced zone mix
# Key differences from parent:
# 1. Denser road grid (every 6 tiles instead of flanking spines)
# 2. More balanced R/C/I (40/30/30)
# 3. Power plants placed proactively in a grid pattern
# 4. Simpler, more reliable infrastructure first

def init(obs, state):
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross through center
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Horizontal roads near center
    for x in range(50, 72):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    # Vertical roads near center
    for y in range(44, 57):
        actions.append((Tool.ROAD, 57, y))
        actions.append((Tool.ROAD, 63, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone mix: 40% residential, 30% commercial, 30% industrial
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Dense grid layout: roads every 7 cols/rows, power plants at intersections
    # Road grid lines (horizontal)
    road_rows = list(range(10, 95, 7))
    # Road grid lines (vertical)
    road_cols = list(range(10, 115, 7))

    # Power plant positions: every ~28 tiles at grid intersections
    plant_grid_rows = list(range(10, 95, 28))
    plant_grid_cols = list(range(10, 115, 28))

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # Phase: ensure power plants at grid intersections
    if step % 12 < 2:
        for py in plant_grid_rows:
            for px in plant_grid_cols:
                if not ib(px, py):
                    continue
                # Check if there's already a plant nearby (within 15 tiles)
                x0, x1 = max(0, px-15), min(WORLD_W, px+16)
                y0, y1 = max(0, py-15), min(WORLD_H, py+16)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    # Find empty spot near this grid intersection
                    for r in range(0, 10):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx) != r and abs(dy) != r:
                                    continue
                                nx2, ny2 = px+dx, py+dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase: lay horizontal road grid
    if step % 12 in (2, 3):
        for rr in road_rows:
            for rx in range(1, WORLD_W-1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    # Connect if adjacent road or wire power plant present
                    left = rx > 0 and (bool(rm[rr, rx-1]) or bool(pm[rr, rx-1]))
                    right = rx < WORLD_W-1 and (bool(rm[rr, rx+1]) or bool(pm[rr, rx+1]))
                    if left or right:
                        return (Tool.ROAD, rx, rr)

    # Phase: lay vertical road grid
    if step % 12 in (4, 5):
        for rc in road_cols:
            for ry in range(1, WORLD_H-1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    up = ry > 0 and (bool(rm[ry-1, rc]) or bool(pm[ry-1, rc]))
                    dn = ry < WORLD_H-1 and (bool(rm[ry+1, rc]) or bool(pm[ry+1, rc]))
                    if up or dn:
                        return (Tool.ROAD, rc, ry)

    # Phase: wire grid connecting power plants to roads (wire along road_rows+1)
    if step % 12 in (6, 7):
        for rr in road_rows:
            # Wire one row above road
            wy = rr - 1
            if 0 < wy < WORLD_H-1:
                for wx in range(1, WORLD_W-1):
                    if bool(em[wy, wx]) and not bool(pm[wy, wx]) and not bool(wm[wy, wx]):
                        # Place wire if adjacent to existing wire or plant
                        left = wx > 0 and (bool(wm[wy, wx-1]) or bool(pm[wy, wx-1]))
                        right = wx < WORLD_W-1 and (bool(wm[wy, wx+1]) or bool(pm[wy, wx+1]))
                        adj_plant_below = bool(pm[rr, wx]) if rr < WORLD_H else False
                        adj_plant_above = bool(pm[wy-1, wx]) if wy > 0 else False
                        if left or right or adj_plant_below or adj_plant_above:
                            return (Tool.WIRE, wx, wy)

    # Phase: vertical wires connecting power plant rows
    if step % 12 in (8, 9):
        for rc in road_cols:
            # Wire one col to the left of road col
            wxc = rc - 1
            if 0 < wxc < WORLD_W-1:
                for wy in range(1, WORLD_H-1):
                    if bool(em[wy, wxc]) and not bool(pm[wy, wxc]) and not bool(wm[wy, wxc]):
                        up = wy > 0 and (bool(wm[wy-1, wxc]) or bool(pm[wy-1, wxc]))
                        dn = wy < WORLD_H-1 and (bool(wm[wy+1, wxc]) or bool(pm[wy+1, wxc]))
                        if up or dn:
                            return (Tool.WIRE, wxc, wy)

    # Civic buildings based on population
    if pop > 100 and step % 15 == 0:
        for sy in range(15, 90, 22):
            for sx in range(15, 110, 26):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 300 and step % 15 == 1:
        for sy in range(18, 90, 25):
            for sx in range(18, 110, 30):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 600 and step % 20 == 0:
        for sx, sy in [(35, 35), (85, 35), (35, 65), (85, 65), (60, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        for nx2, ny2 in [(5, 5), (113, 5), (5, 93), (113, 93), (60, 5), (60, 93)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        for sx, sy in [(5, 93), (113, 5), (5, 5), (113, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        for sx, sy in [(50, 5), (70, 5), (50, 93), (70, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Main zone placement: find candidate spots near roads and power
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid road rows themselves (need those clear for road infrastructure)
    for rr in road_rows:
        cand_mask[max(0, rr):rr+1, :] = False
    for rc in road_cols:
        cand_mask[:, max(0, rc):rc+1] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by distance to center (prefer dense center cluster first)
        cx, cy = 60, 50
        if pop < 100:
            # Focus on center
            dists = np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float)
        elif pop < 500:
            # Expand to mid-range
            dists = np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float)
            # Prefer 20-50 tile range
            mid = np.abs(dists - 35)
            dists = mid
        else:
            # Fill everywhere, prefer farther out
            dists = -( np.abs(cxs2 - cx).astype(float) + np.abs(cys2 - cy).astype(float) )

        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 13 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 400:
                break

    # Parks to improve land value
    if pop > 200 and step % 7 == 0:
        park_cand = em & near_road & near_power
        pys, pxs = np.where(park_cand)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend roads into powered but unconnected areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 17) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 11) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Extend wires to reach unpowered zones
    wire_ys3, wire_xs3 = np.where(wm | pm)
    if len(wire_xs3) > 0:
        # Find unpowered road tiles
        unpowered_road = rm & ~near_power
        uys, uxs = np.where(unpowered_road)
        if len(uxs) > 0:
            tidx = (step * 23) % len(uxs)
            tx, ty = int(uxs[tidx]), int(uys[tidx])
            dists = np.abs(wire_xs3 - tx).astype(float) + np.abs(wire_ys3 - ty).astype(float)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs3[best_wi]), int(wire_ys3[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Last resort: place coal plant near unpowered area
    unpowered_road2 = rm & ~near_power
    uys2, uxs2 = np.where(unpowered_road2)
    if len(uxs2) > 0:
        tidx2 = (step * 31) % len(uxs2)
        tx2, ty2 = int(uxs2[tidx2]), int(uys2[tidx2])
        for r in range(1, 12):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx) == r or abs(dy) == r:
                        nx2, ny2 = tx2+dx, ty2+dy
                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                            return (Tool.COALPOWER, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + dense wire grid + road grid"""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at key columns
    for wc in [10, 30, 50, 70, 90, 110]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wc, y))
    # Roads flanking horizontal wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target: 50% res, 30% com, 20% ind — more commercial than parent
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Wire cols and rows — denser grid than parent
    wire_cols = [10, 30, 50, 70, 90, 110]
    wire_rows = [10, 25, 40, 50, 60, 75, 90]

    # Grid of neighborhood centers — 6 cols x 7 rows
    nh_positions = []
    for row_i in range(7):
        for col_i in range(6):
            cx = 10 + col_i * 20
            cy = 10 + row_i * 13
            cy = min(cy, 94)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            return nh_positions[18:24]  # middle rows
        elif pop < 500:
            return nh_positions[12:36]
        elif pop < 1500:
            return nh_positions[6:42]
        elif pop < 3000:
            return nh_positions[0:42]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 16

    # Closed-loop: add power plants if neighborhoods lack power
    if step % 5 == 0:
        for (hx, hy) in active_hoods[:8]:
            x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
            y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(3, 22):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if found:
                        break

    if phase == 0:
        # Extend horizontal wire rows
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire cols
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Horizontal cross-streets between wire rows
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical cross-streets between wire cols
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend road from existing road toward active hoods
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 9) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 19) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase in (8, 9):
        # Civic services — fire stations early and often
        if pop > 10:
            fire_spots = [
                (5, 5),(25, 5),(45, 5),(65, 5),(85, 5),(105, 5),
                (5, 20),(25, 20),(45, 20),(65, 20),(85, 20),(105, 20),
                (5, 35),(25, 35),(45, 35),(65, 35),(85, 35),(105, 35),
                (5, 65),(25, 65),(45, 65),(65, 65),(85, 65),(105, 65),
                (5, 80),(25, 80),(45, 80),(65, 80),(85, 80),(105, 80),
                (5, 95),(25, 95),(45, 95),(65, 95),(85, 95),(105, 95),
            ]
            for sx, sy in fire_spots:
                sy = min(sy, 97)
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

    elif phase == 10:
        if pop > 60:
            police_spots = [
                (15, 12),(55, 12),(95, 12),
                (15, 37),(55, 37),(95, 37),
                (15, 62),(55, 62),(95, 62),
                (15, 87),(55, 87),(95, 87),
            ]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

    elif phase == 11:
        if pop > 300:
            stadium_spots = [(20, 20),(60, 20),(100, 20),(20, 75),(60, 75),(100, 75)]
            for sx, sy in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    elif phase == 12:
        if pop > 600:
            nuke_spots = [(5, 50),(115, 50),(60, 5),(60, 95)]
            for nx2, ny2 in nuke_spots:
                ny2 = min(ny2, 97)
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    elif phase == 13:
        if pop > 900:
            seaports = [(5, 94),(115, 94),(5, 3),(115, 3)]
            for sx, sy in seaports:
                sy = min(sy, 97)
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

    elif phase == 14:
        if pop > 1500:
            airports = [(45, 5),(75, 5),(45, 93),(75, 93)]
            for sx, sy in airports:
                sy = min(sy, 97)
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase == 15:
        # Parks for land value boost
        if pop > 50:
            park_cands = em & near_road & near_power
            pys, pxs = np.where(park_cands)
            if len(pxs) > 0:
                idx = (step * 37 + pop) % len(pxs)
                return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (main closed-loop action) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders and wire/road corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary starting offset by step and pop to avoid repeating same spot
        offset = (step * 11 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

