def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- REACTIVE: extend wire network from existing wires toward unpowered roads ---
    # Find roads that have no power nearby - extend wire toward them
    road_no_power = rm & ~near_power
    rp_ys, rp_xs = np.where(road_no_power)
    if len(rp_xs) > 0 and step % 5 == 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 17) % len(rp_xs)
            tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            # Try to step wire toward unpowered road
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- REACTIVE: add secondary coal plants when power network is sparse ---
    if step % 7 == 1:
        # Check each quadrant for power coverage
        quadrants = [
            (30, 25), (90, 25), (30, 75), (90, 75),
            (15, 50), (105, 50), (60, 15), (60, 85),
            (15, 25), (105, 25), (15, 75), (105, 75),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for qx, qy in quadrants:
            x0, x1 = max(0, qx-12), min(WORLD_W, qx+13)
            y0, y1 = max(0, qy-12), min(WORLD_H, qy+13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # No plant nearby - place one if there's space
                # Find closest empty spot
                for r in range(0, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = qx+dx, qy+dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # --- REACTIVE: extend roads from existing roads into powered-but-unroaded areas ---
    powered_no_road = near_power & em & ~rm & ~wm & ~pm
    powered_no_road[0:3, :] = False
    powered_no_road[WORLD_H-3:, :] = False
    powered_no_road[:, 0:3] = False
    powered_no_road[:, WORLD_W-3:] = False

    if step % 3 == 0:
        pnr_ys, pnr_xs = np.where(powered_no_road)
        if len(pnr_xs) > 0:
            # Find spots adjacent to existing roads
            road_adj = dilate(rm, 1) & powered_no_road
            ra_ys, ra_xs = np.where(road_adj)
            if len(ra_xs) > 0:
                idx = (step * 13 + pop * 5) % len(ra_xs)
                return (Tool.ROAD, int(ra_xs[idx]), int(ra_ys[idx]))

    # --- REACTIVE: extend wire from existing wires into road areas needing power ---
    wire_adj_to_road = dilate(wm | pm, 1) & rm & ~near_power
    wa_ys, wa_xs = np.where(wire_adj_to_road)
    if len(wa_xs) > 0 and step % 4 == 2:
        idx = (step * 19) % len(wa_xs)
        tx, ty = int(wa_xs[idx]), int(wa_ys[idx])
        # Place wire adjacent to this road tile touching a wire
        for ddx, ddy in [(0,1),(0,-1),(1,0),(-1,0)]:
            nx2, ny2 = tx+ddx, ty+ddy
            if ib(nx2, ny2) and (bool(wm[ny2, nx2]) or bool(pm[ny2, nx2])):
                # wire already there, extend further
                for ddx2, ddy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nnx, nny = tx+ddx2, ty+ddy2
                    if ib(nnx, nny) and bool(em[nny, nnx]):
                        return (Tool.WIRE, nnx, nny)
        if bool(em[ty, tx]):
            return (Tool.WIRE, tx, ty)

    # --- CIVIC BUILDINGS: reactive to population ---
    if pop > 5:
        fire_spots = [
            (10, 10), (35, 10), (60, 10), (85, 10), (110, 10),
            (10, 30), (35, 30), (85, 30), (110, 30),
            (10, 50), (110, 50),
            (10, 70), (35, 70), (85, 70), (110, 70),
            (10, 90), (35, 90), (60, 90), (85, 90), (110, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 40:
        police_spots = [
            (22, 22), (52, 22), (82, 22), (112, 22),
            (22, 42), (52, 42), (82, 42), (112, 42),
            (22, 62), (52, 62), (82, 62), (112, 62),
            (22, 82), (52, 82), (82, 82), (112, 82),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (30, 15), (70, 15), (30, 55), (70, 55),
            (50, 35), (90, 35), (50, 75), (90, 75),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (10, 50), (110, 50), (60, 10), (60, 90),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 80 and step % 6 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- ZONE PLACEMENT: purely reactive - place zones where road+power already exist ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score candidates by distance to nearest road (prefer close to roads)
        road_dist = np.zeros((WORLD_H, WORLD_W), dtype=np.float32)
        road_ys_all, road_xs_all = np.where(rm)

        tool = pick_tool()

        # Find candidate closest to an existing zone (clustering) or to center
        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            # Pick random candidate weighted toward zone clusters
            idx = (step * 7 + pop * 11) % len(cxs)
            # Try candidates near existing zones
            best_z_dist = np.full(len(cxs), 999999.0)
            if len(zone_xs) > 0:
                sample_zones = min(len(zone_xs), 20)
                for i in range(sample_zones):
                    zi = (step * 3 + i * 7) % len(zone_xs)
                    zx2, zy2 = int(zone_xs[zi]), int(zone_ys[zi])
                    d = np.abs(cxs - zx2).astype(float) + np.abs(cys - zy2).astype(float)
                    best_z_dist = np.minimum(best_z_dist, d)
            order = np.argsort(best_z_dist)
        else:
            # Expand outward from center
            center_x, center_y = WORLD_W // 2, WORLD_H // 2
            dists = np.abs(cxs - center_x).astype(float) + np.abs(cys - center_y).astype(float)
            order = np.argsort(dists)

        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- FALLBACK: extend road from existing road into powered area ---
    road_ys_fb, road_xs_fb = np.where(rm)
    if len(road_xs_fb) > 0:
        sk = (step * 11) % len(road_xs_fb)
        for off in range(min(len(road_xs_fb), 200)):
            k = (sk + off * 7) % len(road_xs_fb)
            rx2, ry2 = int(road_xs_fb[k]), int(road_ys_fb[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- FALLBACK: extend wire from existing wire ---
    wire_ys_fb, wire_xs_fb = np.where(wm)
    if len(wire_xs_fb) > 0:
        sk2 = (step * 13) % len(wire_xs_fb)
        for off in range(min(len(wire_xs_fb), 100)):
            k = (sk2 + off * 5) % len(wire_xs_fb)
            wx2, wy2 = int(wire_xs_fb[k]), int(wire_ys_fb[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire spines and initial roads for two neighborhoods."""
    actions = []
    # Two main power plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for d in range(-8, 9):
            actions.append((Tool.WIRE, px + d, py))
        # Vertical wire spine
        for d in range(-8, 9):
            actions.append((Tool.WIRE, px, py + d))
        # Roads flanking wire spine
        for d in range(-8, 9):
            actions.append((Tool.ROAD, px + d, py - 4))
            actions.append((Tool.ROAD, px + d, py + 4))
        for d in range(-8, 9):
            actions.append((Tool.ROAD, px - 4, py + d))
            actions.append((Tool.ROAD, px + 4, py + d))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 30% industrial, 30% commercial, 40% residential
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        if i_r < 0.30:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Denser grid of anchors - 6 columns x 6 rows for more coverage
    all_anchors = []
    for ax in [20, 40, 60, 80, 100, 115]:
        for ay in [15, 30, 45, 60, 75, 88]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 8
        if pop < 300:   return 12
        if pop < 500:   return 16
        if pop < 800:   return 20
        if pop < 1200:  return 28
        if pop < 2000:  return 32
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 14); y1 = min(WORLD_H, ay + 15)
        x0 = max(0, ax - 14); x1 = min(WORLD_W, ax + 15)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    wire_half = min(20, 6 + pop // 8)
    vert_half = min(14, 5 + pop // 12)

    # ---- WIRE EXPANSION: horizontal spines ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    # ---- WIRE EXPANSION: vertical spines ----
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- WIRE CONNECTIONS between anchors in same column ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    # ---- WIRE CONNECTIONS between anchors in same row ----
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD GRID: roads at offset ±4 from wire spine (slightly wider than parent's ±3) ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-4, 4]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx+ddx, road_y) and bool(rm[road_y, cx+ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y-1) and bool(wm[road_y-1, cx])) or \
                               (ib(cx, road_y+1) and bool(wm[road_y+1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # ---- VERTICAL ROADS: flanking vertical wire spines ----
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-4, 4]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy+ddy) and bool(rm[cy+ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x-1, cy) and bool(wm[cy, road_x-1])) or \
                               (ib(road_x+1, cy) and bool(wm[cy, road_x+1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: near roads and wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (earlier thresholds for better land value) ----
    if pop > 20:
        fire_spots = [
            (5, 5), (30, 5), (60, 5), (90, 5), (115, 5),
            (5, 25), (30, 25), (60, 25), (90, 25), (115, 25),
            (5, 48), (30, 48), (60, 48), (90, 48), (115, 48),
            (5, 68), (30, 68), (60, 68), (90, 68), (115, 68),
            (5, 88), (30, 88), (60, 88), (90, 88), (115, 88),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (10, 10), (45, 10), (75, 10), (110, 10),
            (10, 38), (45, 38), (75, 38), (110, 38),
            (10, 62), (45, 62), (75, 62), (110, 62),
            (10, 85), (45, 85), (75, 85), (110, 85),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        for (sx, sy) in [(20, 3), (60, 3), (100, 3), (20, 94), (60, 94), (100, 94)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        # Nuclear plants for more power coverage
        for (nx2, ny2) in [(5, 50), (115, 50), (60, 3), (60, 94), (30, 3), (90, 3)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        for (ax2, ay2) in [(5, 3), (115, 3), (5, 94), (115, 94), (60, 50)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 1800:
        for (sx2, sy2) in [(5, 94), (115, 94), (60, 94), (5, 3), (115, 3)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones for land value ----
    if pop > 60:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire grid + road network"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines
    for wy in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for wy in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    # Roads flanking vertical wire spines
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            if y not in [19, 20, 21, 49, 50, 51, 79, 80, 81]:
                actions.append((Tool.ROAD, wx - 1, y))
                actions.append((Tool.ROAD, wx + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Infrastructure layout matching init
    wire_rows = [20, 50, 80]
    wire_cols = [30, 60, 90]

    # Dilation for proximity checks
    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            if ir < 0.30:
                return Tool.INDUSTRIAL
            if cr < 0.20:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 600:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 8

    # --- PHASE 0: Repair/extend horizontal wire spines ---
    if phase == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)

    # --- PHASE 1: Repair/extend vertical wire spines ---
    if phase == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)

    # --- PHASE 2: Repair roads flanking wire rows ---
    if phase == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # --- PHASE 3: Roads flanking vertical wire spines ---
    if phase == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        # Don't block wire row roads
                        skip = False
                        for wr in wire_rows:
                            if abs(ry - wr) <= 1:
                                skip = True
                                break
                        if not skip:
                            return (Tool.ROAD, rcx, ry)

    # --- PHASE 4: Add coal plants where coverage is thin ---
    if phase == 4:
        for py in range(15, WORLD_H - 5, 30):
            for px in range(15, WORLD_W - 5, 30):
                x0, x1 = max(0, px - 14), min(WORLD_W, px + 15)
                y0, y1 = max(0, py - 14), min(WORLD_H, py + 15)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    for r in range(0, 10):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # --- PHASE 5: Wire unpowered zones toward grid ---
    if phase == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- PHASE 6: Road to unroaded zones ---
    if phase == 6:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: Secondary cross roads ---
    if phase == 7:
        secondary_rows = [10, 30, 40, 60, 70, 90]
        secondary_cols = [15, 45, 75, 105]
        for rr_y in secondary_rows:
            if not (0 < rr_y < WORLD_H):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr_y, rx]) and not bool(pm[rr_y, rx]) and bool(near_power[rr_y, rx]):
                    return (Tool.ROAD, rx, rr_y)
        for rc_x in secondary_cols:
            if not (0 < rc_x < WORLD_W):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc_x]) and not bool(pm[ry, rc_x]) and bool(near_power[ry, rc_x]):
                    return (Tool.ROAD, rc_x, ry)

    # --- CIVIC SERVICES (closed-loop: place when pop threshold met) ---
    if pop > 20:
        fire_spots = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 35), (45, 35), (75, 35), (105, 35),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 45), (55, 45), (85, 45), (115, 45),
            (25, 65), (55, 65), (85, 65), (115, 65),
            (10, 30), (10, 70), (110, 30), (110, 70),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (10, 50), (110, 50), (60, 10), (60, 90),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 6 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- ZONE PLACEMENT ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Protect wire corridors
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):min(WORLD_H, wr + 2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):min(WORLD_W, wc + 2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Active centers scale with population
        if pop < 150:
            active_centers = [
                (60, 50), (45, 50), (75, 50), (60, 38), (60, 62),
                (45, 38), (75, 38), (45, 62), (75, 62),
                (30, 50), (90, 50), (30, 30), (90, 30), (30, 70), (90, 70),
            ]
        elif pop < 800:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 8 + col * 15
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: place plant for uncovered active centers
    if pop < 200:
        for cx, cy in [(60, 50), (30, 50), (90, 50)]:
            x0, x1 = max(0, cx - 14), min(WORLD_W, cx + 15)
            y0, y1 = max(0, cy - 14), min(WORLD_H, cy + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx, ny = cx + dx, cy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + horizontal wire spines + flanking roads."""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines at key rows
    for wy in [25, 40, 55, 70]:
        for x in range(2, 118):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines connecting horizontal ones
    for wx in [15, 35, 55, 75, 95, 110]:
        for y in range(2, 98):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking each wire row
    for wy in [25, 40, 55, 70]:
        for x in range(2, 118):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    wire_rows = [25, 40, 55, 70]
    wire_cols = [15, 35, 55, 75, 95, 110]

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30: return Tool.INDUSTRIAL
            if cr < 0.25: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.22: return Tool.INDUSTRIAL
            if cr < 0.30: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.38: return Tool.COMMERCIAL
            if rr < 0.45: return Tool.RESIDENTIAL
            return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    mod = step % 8

    # PHASE 0: Repair horizontal wire rows
    if mod == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # PHASE 1: Repair vertical wire cols
    if mod == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            for wy2 in range(1, WORLD_H - 1):
                if not bool(wm[wy2, wc]) and not bool(pm[wy2, wc]):
                    up = wy2 > 0 and (bool(wm[wy2-1, wc]) or bool(pm[wy2-1, wc]))
                    dn = wy2 < WORLD_H-1 and (bool(wm[wy2+1, wc]) or bool(pm[wy2+1, wc]))
                    if (up or dn) and bool(em[wy2, wc]):
                        return (Tool.WIRE, wc, wy2)

    # PHASE 2: Repair road rows flanking wire rows
    if mod == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]):
                        adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                               (rx < WORLD_W-1 and bool(rm[ry, rx+1])))
                        on_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        if (adj or rx <= 2) and on_wire:
                            return (Tool.ROAD, rx, ry)

    # PHASE 3: Add vertical roads flanking wire cols
    if mod == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]):
                        on_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj = ((ry > 0 and bool(rm[ry-1, rcx])) or
                               (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                               (rcx > 0 and bool(rm[ry, rcx-1])) or
                               (rcx < WORLD_W-1 and bool(rm[ry, rcx+1])))
                        if on_wire and (adj or ry <= 2):
                            return (Tool.ROAD, rcx, ry)

    # PHASE 4: Power zones that lack power — extend wire toward unpowered zones
    if mod == 4:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                sample = min(len(uz_xs), 15)
                best_zone = None
                best_dist = 999999
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

    # PHASE 5: Road access for unroaded zones
    if mod == 5:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx2 = 0 if tx == brx else (1 if tx > brx else -1)
                dy2 = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx2, bry), (brx, bry + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # PHASE 6: Add coal plants where regions lack power
    if mod == 6:
        # Find grid cells with zones but no nearby plant
        for py in range(12, WORLD_H - 12, 22):
            for px in range(12, WORLD_W - 12, 22):
                x0, x1 = max(0, px - 11), min(WORLD_W, px + 12)
                y0, y1 = max(0, py - 11), min(WORLD_H, py + 12)
                has_plant = bool(np.any(pm[y0:y1, x0:x1]))
                if not has_plant:
                    has_zones = bool(np.any(zone_tiles[y0:y1, x0:x1]))
                    if has_zones or (pop > 300 and step > 200):
                        for r in range(0, 10):
                            for dy in range(-r, r + 1):
                                for dx in range(-r, r + 1):
                                    if abs(dx) == r or abs(dy) == r or r == 0:
                                        nx2, ny2 = px + dx, py + dy
                                        if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                            return (Tool.COALPOWER, nx2, ny2)

    # PHASE 7: Parks for land value
    if mod == 7 and pop > 80:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # === CIVIC SERVICES ===
    if pop > 20:
        fire_spots = [
            (8, 8), (55, 8), (110, 8),
            (8, 33), (55, 33), (110, 33),
            (8, 47), (55, 47), (110, 47),
            (8, 62), (55, 62), (110, 62),
            (8, 85), (55, 85), (110, 85),
            (30, 18), (80, 18), (30, 78), (80, 78),
            (30, 50), (80, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (20, 15), (50, 15), (80, 15), (110, 15),
            (20, 38), (50, 38), (80, 38), (110, 38),
            (20, 57), (50, 57), (80, 57), (110, 57),
            (20, 80), (50, 80), (80, 80), (110, 80),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (28, 20), (88, 20), (28, 75), (88, 75),
            (58, 47),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        nuke_spots = [
            (10, 12), (108, 12), (10, 88), (108, 88),
            (58, 8), (58, 92), (5, 48), (113, 48),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        for sx, sy in [(5, 95), (113, 95), (5, 5), (113, 5)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        for sx, sy in [(48, 5), (68, 5), (48, 92), (68, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # === ZONE PLACEMENT ===
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Avoid placing on the wire/road spines themselves
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Reactive neighborhood centers based on current population
        if pop < 150:
            active_centers = [
                (45, 32), (25, 32), (65, 32), (45, 47), (25, 47), (65, 47),
                (45, 62), (25, 62), (65, 62),
            ]
        elif pop < 600:
            active_centers = []
            for row in range(4):
                for col in range(6):
                    cx = 10 + col * 20
                    cy = 10 + row * 22
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 7 + col * 13
                    cy = 7 + row * 12
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary starting offset by step+pop for reactivity
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 100)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 60)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last resort: place a coal plant somewhere empty
    for wr in wire_rows:
        for wx in range(5, WORLD_W - 5, 18):
            x0, x1 = max(0, wx - 8), min(WORLD_W, wx + 9)
            y0, y1 = max(0, wr - 8), min(WORLD_H, wr + 9)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                if ib(wx, wr) and bool(em[wr, wx]):
                    return (Tool.COALPOWER, wx, wr)

    return None

def init(obs, state):
