def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target zone mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Denser grid of wire rows and cols for better coverage
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]

    # Plant positions distributed across map
    plant_positions = []
    for row in range(5):
        for col in range(5):
            px = 12 + col * 24
            py = 10 + row * 20
            plant_positions.append((px, py))

    # ---- PHASE 0: Ensure plants exist across map ----
    for px, py in plant_positions:
        x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
        y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 8

    # ---- PHASE 1: Extend horizontal wire corridors ----
    if phase == 0:
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = int(np.argmin(dists))
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        left = wx > 0 and bool(row_power[wx - 1])
                        right = wx < WORLD_W - 1 and bool(row_power[wx + 1])
                        if (left or right) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # ---- PHASE 2: Extend vertical wire corridors ----
    elif phase == 1:
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = int(np.argmin(dists))
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2 + step_x, wc + step_x, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        up = wy > 0 and bool(col_power[wy - 1])
                        dn = wy < WORLD_H - 1 and bool(col_power[wy + 1])
                        if (up or dn) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: Roads parallel to horizontal wire corridors ----
    elif phase == 2:
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-2, 2]:  # Roads 2 tiles away from wire for zone space
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Roads parallel to vertical wire corridors ----
    elif phase == 3:
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # ---- PHASE 5: Wire intersection connectors ----
    elif phase == 4:
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc - 1])) or \
                         (wc < WORLD_W - 1 and bool(wm[wr, wc + 1]))
                col_ok = (wr > 0 and bool(wm[wr - 1, wc])) or \
                         (wr < WORLD_H - 1 and bool(wm[wr + 1, wc]))
                if (row_ok or col_ok) and bool(em[wr, wc]) and not bool(pm[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    # ---- PHASE 6: Cross-connect vertical roads ----
    elif phase == 5:
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            mid_y = (wr1 + wr2) // 2
            for wc in wire_cols:
                for offset in [-2, 2]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                        adj = (ib(rcx, mid_y - 1) and bool(rm[mid_y - 1, rcx])) or \
                              (ib(rcx, mid_y + 1) and bool(rm[mid_y + 1, rcx]))
                        if adj:
                            return (Tool.ROAD, rcx, mid_y)

    # ---- PHASE 7: Extend roads toward powered unroaded areas ----
    elif phase == 6:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H - 3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W - 3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 8: Wire toward unpowered roads ----
    else:  # phase == 7
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to pop) ----
    if pop > 50:
        # Denser fire station grid
        fire_positions = [
            (20, 15), (50, 15), (80, 15), (110, 15),
            (20, 35), (50, 35), (80, 35), (110, 35),
            (20, 55), (50, 55), (80, 55), (110, 55),
            (20, 75), (50, 75), (80, 75), (110, 75),
            (20, 92), (50, 92), (80, 92), (110, 92),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (35, 25), (65, 25), (95, 25),
            (20, 45), (50, 45), (80, 45), (110, 45),
            (35, 65), (65, 65), (95, 65),
            (20, 85), (50, 85), (80, 85), (110, 85),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (30, 30), (90, 30), (30, 70), (90, 70),
            (60, 15), (60, 85), (10, 50), (110, 50),
            (45, 50), (75, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Switch some coal to nuclear for better power
        nuke_spots = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (5, 50), (115, 50), (60, 95),
            (35, 50), (85, 50), (60, 25), (60, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10), (60, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(45, 5), (75, 5), (45, 92), (75, 92), (5, 40), (110, 40)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value near zones
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        # Prefer parks near existing zones
        zone_near = dilate(zone_tiles, 3)
        park_cands &= zone_near
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (primary closed-loop) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    # Avoid wire corridors and their immediate neighbors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 3.0 if bool(zone_near[y, x]) else 0.0
            # Prefer away from center to spread city (more population capacity)
            dist_from_center = abs(x - 60) / 60.0 + abs(y - 50) / 50.0
            scores[i] += 1.0 * dist_from_center
            # Bonus for being near roads (better connectivity)
            scores[i] += 0.5 if bool(rm[y, x]) else 0.0

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- FALLBACK: extend road from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: new coal plant near unpowered area ----
    all_hoods = [(cx, cy) for cy in range(10, 100, 10) for cx in range(10, 120, 12)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants on horizontal spine + initial wire/road grid"""
    actions = []
    # Coal plants at key positions
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    # Horizontal wire spines
    for x in range(1, 119):
        for wy in [10, 30, 50, 70, 90]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for y in range(1, 99):
        for wx in [10, 30, 60, 90, 110]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows
    for x in range(1, 119):
        for wy in [10, 30, 50, 70, 90]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    wire_rows = [10, 30, 50, 70, 90]
    wire_cols = [10, 30, 60, 90, 110]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 35% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- REACTIVE: Check actual power coverage and fill gaps ---
    # If a region has roads but no power, run wire to it
    unpowered_roads = rm & ~near_power
    if np.any(unpowered_roads):
        # Find nearest wire to an unpowered road tile
        ury, urx = np.where(unpowered_roads)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0 and len(urx) > 0:
            # Pick first unpowered road tile
            idx = (step * 7) % len(urx)
            tx, ty = int(urx[idx]), int(ury[idx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best = np.argmin(dists)
            bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
            # Step wire toward target
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            candidates = []
            if dx != 0:
                candidates.append((bwx + dx, bwy))
            if dy != 0:
                candidates.append((bwx, bwy + dy))
            for nx2, ny2 in candidates:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- REACTIVE: Check if wire corridors are complete ---
    phase = step % 10

    if phase == 0:
        # Repair/extend horizontal wire rows
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Repair/extend vertical wire cols
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Repair roads adjacent to wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Only add road if wire is present here
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Add vertical cross-roads between wire cols
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 4:
        # Extend roads to connect road network
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 100)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 5:
        # REACTIVE: Add coal plants where power is absent near populated zones
        zone_ys, zone_xs = np.where(zone_tiles & ~near_power)
        if len(zone_xs) > 0:
            idx = (step * 13) % len(zone_xs)
            tx, ty = int(zone_xs[idx]), int(zone_ys[idx])
            # Place plant nearby
            for r in range(3, 20):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = tx+dx, ty+dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)

    elif phase in (6, 7, 8, 9):
        # Civic services based on observed population
        if pop > 30:
            fire_spots = [(8,8),(30,8),(60,8),(90,8),(110,8),
                          (8,28),(30,28),(60,28),(90,28),(110,28),
                          (8,48),(60,48),(110,48),
                          (8,68),(30,68),(60,68),(90,68),(110,68),
                          (8,88),(30,88),(60,88),(90,88),(110,88)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 150:
            police_spots = [(20,15),(60,15),(100,15),
                            (20,45),(60,45),(100,45),
                            (20,65),(60,65),(100,65),
                            (20,85),(60,85),(100,85)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 500:
            stadium_spots = [(35,25),(85,25),(35,75),(85,75),(60,50)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 800:
            nuke_spots = [(5,50),(113,50),(60,5),(60,93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            seaports = [(5,93),(113,93)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2500:
            airports = [(50,5),(70,5),(50,92),(70,92)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- MAIN: REACTIVE ZONE PLACEMENT ----
    # Find candidate cells: empty, near road AND near power
    cand_mask = em & near_road & near_power
    # Keep away from borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep away from wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # REACTIVE: score by how well-powered and road-connected they are
        # Count nearby road tiles (more = better for growth)
        road_density = dilate(rm, 3).astype(float)
        power_density = dilate(wm | pm, 4).astype(float)

        # Pick best zone candidate
        scores = road_density[cys2, cxs2] + power_density[cys2, cxs2]
        # Add slight randomness to explore
        noise = np.array([(hash((int(cx)*1000+int(cy)+step)) % 100) / 1000.0
                          for cx, cy in zip(cxs2, cys2)])
        scores = scores + noise

        order = np.argsort(-scores)  # descending
        tool = pick_tool()
        checked = 0
        for i in order:
            zx, zy = int(cxs2[i]), int(cys2[i])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # Parks for land value near existing zones
    if pop > 100 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend wire toward empty powered-road areas
    unpowered_road = rm & ~near_power
    ur_ys, ur_xs = np.where(unpowered_road)
    if len(ur_xs) > 0:
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            idx2 = (step * 17) % len(ur_xs)
            tx2, ty2 = int(ur_xs[idx2]), int(ur_ys[idx2])
            dists2 = np.abs(wire_xs2 - tx2) + np.abs(wire_ys2 - ty2)
            best2 = np.argmin(dists2)
            bwx2, bwy2 = int(wire_xs2[best2]), int(wire_ys2[best2])
            dx2 = 0 if tx2 == bwx2 else (1 if tx2 > bwx2 else -1)
            dy2 = 0 if ty2 == bwy2 else (1 if ty2 > bwy2 else -1)
            for nx3, ny3 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Last fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

