def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Dynamic zone mix: 50% res, 30% com, 20% ind early; shift toward more com late
    def pick_tool():
        if pop < 500:
            # Early: build industrial base first for jobs
            if ind_count / total_zones < 0.25:
                return Tool.INDUSTRIAL
            if com_count / total_zones < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 2000:
            # Mid: balanced with more commercial
            if com_count / total_zones < 0.35:
                return Tool.COMMERCIAL
            if ind_count / total_zones < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL
        else:
            # Late: heavily residential for max population
            if com_count / total_zones < 0.30:
                return Tool.COMMERCIAL
            if ind_count / total_zones < 0.15:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [20, 40, 60, 80, 100]

    # Neighborhood centers in a tighter grid for denser development
    nh_positions = []
    for row in range(7):
        for col in range(9):
            cx = 8 + col * 13
            cy = 8 + row * 13
            cx = min(cx, 116)
            cy = min(cy, 96)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        # Expand more aggressively based on pop
        if pop < 100:
            return [(60, 50), (47, 50), (73, 50), (60, 37), (60, 63)]
        elif pop < 400:
            return nh_positions[18:45]
        elif pop < 1000:
            return nh_positions[9:54]
        elif pop < 2000:
            return nh_positions[3:60]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 14

    # Ensure power plants near active neighborhoods
    if step % 6 == 0:
        for (hx, hy) in active_hoods[:6]:
            x0, x1 = max(0, hx - 22), min(WORLD_W, hx + 23)
            y0, y1 = max(0, hy - 22), min(WORLD_H, hy + 23)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(2, 25):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if found:
                        break

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross-streets between wire rows at midpoints
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire cols
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend road from existing roads, prioritizing near unpowered zones
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 19) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Additional wire connections diagonal-ish to extend coverage
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            sk2 = (step * 17) % len(wire_xs3)
            for off in range(min(len(wire_xs3), 100)):
                k = (sk2 + off * 11) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                    nx3, ny3 = wx2+dx3, wy2+dy3
                    if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                        # Only extend if not near a road (avoid redundancy)
                        if not bool(near_road[ny3, nx3]):
                            return (Tool.WIRE, nx3, ny3)

    elif phase in (9, 10, 11, 12, 13):
        # Civic services based on population
        if pop > 15:
            fire_spots = [
                (5,5),(35,5),(65,5),(95,5),(115,5),
                (5,25),(35,25),(65,25),(95,25),(115,25),
                (5,45),(35,45),(95,45),(115,45),
                (5,55),(35,55),(95,55),(115,55),
                (5,75),(35,75),(65,75),(95,75),(115,75),
                (5,95),(35,95),(65,95),(95,95),(115,95),
            ]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 80:
            police_spots = [
                (15,10),(55,10),(90,10),(115,10),
                (15,30),(55,30),(90,30),(115,30),
                (15,55),(55,55),(90,55),(115,55),
                (15,75),(55,75),(90,75),(115,75),
                (15,92),(55,92),(90,92),(115,92),
            ]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadium_spots = [(25,25),(95,25),(25,75),(95,75),(60,50),(60,10),(60,90)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 700:
            nuke_spots = [(5,50),(115,50),(60,5),(60,95),(5,5),(115,5),(5,95),(115,95),(30,10),(90,10),(30,90),(90,90)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            seaports = [(5,95),(115,95),(5,5),(115,5),(5,50),(115,50)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1800:
            airports = [(45,5),(75,5),(45,92),(75,92),(5,40),(115,40),(5,60),(115,60)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT (main closed-loop action) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders and wire corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use a different offset strategy to get more variety in placement
        offset = (step * 11 + pop * 5) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks for land value boost
    if pop > 30 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx,bwy),(bwx,bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Small bootstrap: central power plant + wire cross + road cross"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire horizontally from plant
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically from plant
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Road horizontal spine (offset from wire)
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 47))
    # Road vertical spine (offset from wire)
    for y in range(1, 99):
        actions.append((Tool.ROAD, 57, y))
    # A few extra power plants
    for px, py in [(10, 50), (110, 50), (60, 10), (60, 90), (30, 25), (90, 25), (30, 75), (90, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- CLOSED-LOOP REACTIVE DECISIONS ----

    # 1. If there are unpowered areas with roads, extend wire toward them
    # Find road tiles not near power
    road_no_power = rm & ~near_power
    rp_count = int(np.sum(road_no_power))

    if rp_count > 0 and step % 5 in (0, 1):
        # Find nearest wire to each unpowered road segment
        rp_ys, rp_xs = np.where(road_no_power)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            idx = (step * 17) % len(rp_xs)
            tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            bi = np.argmin(dists)
            bwx, bwy = int(wire_xs[bi]), int(wire_ys[bi])
            # Step toward target
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            candidates = []
            if dx != 0:
                candidates.append((bwx + dx, bwy))
            if dy != 0:
                candidates.append((bwx, bwy + dy))
            if dx != 0 and dy != 0:
                candidates.append((bwx + dx, bwy + dy))
            for nx2, ny2 in candidates:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # 2. Reactively extend roads into powered-but-unroaded areas
    powered_no_road = near_power & ~near_road & em
    powered_no_road[0:3, :] = False
    powered_no_road[WORLD_H-3:, :] = False
    powered_no_road[:, 0:3] = False
    powered_no_road[:, WORLD_W-3:] = False

    pnr_count = int(np.sum(powered_no_road))
    if pnr_count > 0 and step % 7 in (2, 3):
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            pnr_ys, pnr_xs = np.where(powered_no_road)
            idx = (step * 13) % len(road_xs)
            # Pick a road tile and extend it
            rx, ry = int(road_xs[idx]), int(road_ys[idx])
            for dx2, dy2 in [(0, 3), (0, -3), (3, 0), (-3, 0), (0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx + dx2, ry + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 3. Check if we need more power plants (scan for large powered=0 areas)
    plant_count = int(np.sum(pm))
    # Heuristic: add plants when few zones are powered relative to total
    zone_count = res_count + com_count + ind_count
    powered_zones = obs.powered_zones

    if zone_count > 0 and powered_zones < zone_count * 0.7 and step % 11 == 4:
        # Find a good spot for a new power plant (near wire but empty)
        wire_ys2, wire_xs2 = np.where(wm)
        if len(wire_xs2) > 0:
            # Try to find empty spot near wire that isn't too close to existing plant
            for r in range(3, 15):
                for attempt in range(20):
                    idx = (step * 31 + attempt * 7) % len(wire_xs2)
                    wx2, wy2 = int(wire_xs2[idx]), int(wire_ys2[idx])
                    # Check if no plant nearby
                    x0, x1 = max(0, wx2-10), min(WORLD_W, wx2+11)
                    y0, y1 = max(0, wy2-10), min(WORLD_H, wy2+11)
                    if not bool(np.any(pm[y0:y1, x0:x1])):
                        if ib(wx2, wy2) and bool(em[wy2, wx2]):
                            return (Tool.COALPOWER, wx2, wy2)

    # 4. Civic services (fire, police, stadium) scaled to population
    if pop > 10 and step % 20 == 5:
        fire_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
            (40, 35), (80, 35), (40, 65), (80, 65),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100 and step % 20 == 8:
        police_spots = [
            (15, 15), (45, 15), (75, 15), (105, 15),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (15, 75), (45, 75), (75, 75), (105, 75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400 and step % 30 == 10:
        stadium_spots = [
            (30, 30), (90, 30), (30, 70), (90, 70), (60, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800 and step % 25 == 12:
        nuke_spots = [
            (5, 5), (115, 5), (5, 95), (115, 95),
            (5, 50), (115, 50), (60, 5), (60, 95),
            (30, 50), (90, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500 and step % 40 == 15:
        seaports = [(5, 90), (115, 90), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000 and step % 50 == 20:
        airports = [(50, 5), (70, 5), (5, 45), (110, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # 5. Parks for land value when city is growing
    if pop > 200 and step % 6 == 3:
        park_cands = em & near_road & near_power
        park_cands[0:2, :] = False
        park_cands[WORLD_H-2:, :] = False
        park_cands[:, 0:2] = False
        park_cands[:, WORLD_W-2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 29 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # 6. MAIN: Zone placement - closed loop, scan for best spots near existing infra
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Score candidates: prefer spots near existing zones (clustering) and near roads
        # Use multiple active centers based on current zone distribution
        if zone_count > 0:
            zy_all, zx_all = np.where(zone_tiles)
            # Sample a few zone centers to cluster around
            n_samp = min(len(zx_all), 8)
            step_seed = (step * 37) % max(len(zx_all), 1)
            sample_idxs = [(step_seed + i * 13) % len(zx_all) for i in range(n_samp)]
            active_centers = [(int(zx_all[i]), int(zy_all[i])) for i in sample_idxs]
        else:
            # Default centers spread across map
            active_centers = [
                (60, 50), (40, 40), (80, 40), (40, 60), (80, 60),
                (20, 30), (100, 30), (20, 70), (100, 70),
            ]

        # Also add road-adjacent spots as centers to expand along roads
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            r_idx = (step * 19) % len(road_xs3)
            active_centers.append((int(road_xs3[r_idx]), int(road_ys3[r_idx])))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Prefer closer spots but add some variety
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # 7. If no good zone spot, try to extend road from existing road
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off in range(min(len(road_xs4), 200)):
            k = (sk + off * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # 8. Extend wire if nothing else to do
    wire_ys5, wire_xs5 = np.where(wm | pm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off in range(min(len(wire_xs5), 100)):
            k = (sk2 + off * 5) % len(wire_xs5)
            wx3, wy3 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx3 + dx3, wy3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with wire cross and flanking roads."""
    actions = []
    cx, cy = 60, 50
    # Central power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross
    for d in range(1, 12):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Flanking roads
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 3))
        actions.append((Tool.ROAD, cx + dx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Active anchors scale with population
    all_anchors = [
        (60, 50),
        (30, 50), (90, 50),
        (60, 25), (60, 75),
        (30, 25), (90, 25),
        (30, 75), (90, 75),
        (15, 50), (105, 50),
        (15, 25), (105, 25),
        (15, 75), (105, 75),
        (45, 12), (75, 12),
        (45, 88), (75, 88),
    ]

    def num_active():
        if pop < 50: return 1
        if pop < 150: return 3
        if pop < 300: return 5
        if pop < 600: return 9
        if pop < 1000: return 11
        if pop < 2000: return 15
        return len(all_anchors)

    active_anchors = all_anchors[:num_active()]
    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- ENSURE POWER PLANTS at each active anchor ----
    for (px, py) in active_anchors:
        y0 = max(0, py - 6); y1 = min(WORLD_H, py + 7)
        x0 = max(0, px - 6); x1 = min(WORLD_W, px + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if r > 0 and abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    spine = min(12, 4 + pop // 40)

    # ---- WIRE CROSS at each anchor ----
    for (px, py) in active_anchors:
        for dx in range(-spine, spine + 1):
            wx, wy = px + dx, py
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)
        for dy in range(-spine, spine + 1):
            wx, wy = px, py + dy
            if ib(wx, wy) and bool(em[wy, wx]) and not bool(pm[wy, wx]):
                return (Tool.WIRE, wx, wy)

    # ---- CONNECT POWER horizontally between anchors ----
    y_levels = sorted(set(py for (_, py) in active_anchors))
    for yl in y_levels:
        row_anchors = sorted([(px, py) for (px, py) in active_anchors if py == yl])
        for i in range(len(row_anchors) - 1):
            x1a = row_anchors[i][0]
            x2a = row_anchors[i + 1][0]
            for cx in range(x1a + 1, x2a):
                if ib(cx, yl) and bool(em[yl, cx]) and not bool(pm[yl, cx]):
                    return (Tool.WIRE, cx, yl)

    # ---- CONNECT POWER vertically between anchors ----
    x_cols = sorted(set(px for (px, _) in active_anchors))
    for xl in x_cols:
        col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            y1a = col_anchors[i][1]
            y2a = col_anchors[i + 1][1]
            for cy in range(y1a + 1, y2a):
                if ib(xl, cy) and bool(em[cy, xl]) and not bool(pm[cy, xl]):
                    return (Tool.WIRE, xl, cy)

    # ---- ROAD GRID: horizontal roads flanking each wire row ----
    for (px, py) in active_anchors:
        for road_dy in [-3, 3]:
            ry = py + road_dy
            if not ib(px, ry):
                continue
            for dx in range(-spine, spine + 1):
                rx = px + dx
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- VERTICAL ROADS connecting row pairs ----
    if pop > 50:
        for xl in x_cols:
            col_anchors = sorted([(px, py) for (px, py) in active_anchors if px == xl], key=lambda a: a[1])
            for i in range(len(col_anchors) - 1):
                y1a = col_anchors[i][1]
                y2a = col_anchors[i + 1][1]
                for road_x in [xl + 4, xl - 4]:
                    for cy in range(y1a, y2a + 1):
                        if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                            return (Tool.ROAD, road_x, cy)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py) in active_anchors:
            d = np.abs(cxs - px).astype(float) + np.abs(cys - py).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % max(len(road_xs), 1)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 80:
        fire_spots = [
            (15, 20), (45, 20), (75, 20), (105, 20),
            (15, 50), (45, 50), (75, 50), (105, 50),
            (15, 80), (45, 80), (75, 80), (105, 80),
            (30, 35), (60, 35), (90, 35),
            (30, 65), (60, 65), (90, 65),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [
            (20, 15), (60, 15), (100, 15),
            (20, 40), (60, 40), (100, 40),
            (20, 60), (60, 60), (100, 60),
            (20, 85), (60, 85), (100, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200 and step % 4 == 0:
        # Parks to boost land value
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    if pop > 700:
        stadium_spots = [
            (25, 12), (75, 12), (25, 88), (75, 88),
            (10, 50), (110, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 20), (115, 20), (5, 80), (115, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        airport_spots = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for ax, ay in airport_spots:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.AIRPORT, ax, ay)

    if pop > 3000:
        seaport_spots = [(5, 92), (115, 92), (5, 8), (115, 8)]
        for sx, sy in seaport_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # ---- WIRE UNPOWERED ZONES ----
    unpowered = zone_tiles & ~near_power
    uz_ys, uz_xs = np.where(unpowered)
    if len(uz_xs) > 0:
        wire_ys_a, wire_xs_a = np.where(wm | pm)
        if len(wire_xs_a) > 0:
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- EXTEND WIRE from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % max(len(wire_xs3), 1)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

# Improved city builder with denser infrastructure and better zone coverage
# Key changes from parent:
# 1. More compact neighborhood layout (3x3 grid = 9 neighborhoods, denser)
# 2. Better road grid (both horizontal AND vertical roads, not just flanking wires)
# 3. Different zone mix: 35% res, 35% com, 30% ind (more commercial)
# 4. Horizontal wire runs between plants, not just vertical spines
# 5. Earlier zone placement (less infrastructure-first waiting)

def init(obs, state):
    """Bootstrap: 2 coal plants with cross-wire layout and road grid."""
    actions = []
    # Two plants: left-center and right-center
    for px, py in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Horizontal wire from left plant to right plant at center
    # Connect the two plants with horizontal wire
    for cx in range(32, 89):
        actions.append((Tool.WIRE, cx, 50))
    # Initial roads flanking left plant
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, 29, 50 + dy))
        actions.append((Tool.ROAD, 31, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 35% res, 35% com, 30% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        if rr < 0.35:
            return Tool.RESIDENTIAL
        # Cycle based on step
        t = step % 3
        if t == 0: return Tool.RESIDENTIAL
        if t == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    # 3x3 grid = 9 neighborhoods, more compact
    nh_cols = [20, 60, 100]
    nh_rows = [20, 50, 80]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 6
        if pop < 800:   return 8
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS ----
    power_src = wm | pm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
        y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: HORIZONTAL WIRE between plants at hood rows ----
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        row_hoods.sort(key=lambda h: h[0])
        for i in range(len(row_hoods) - 1):
            hx1 = row_hoods[i][0]
            hx2 = row_hoods[i + 1][0]
            for cx2 in range(hx1 + 1, hx2):
                if ib(cx2, hy_row) and bool(em[hy_row, cx2]) and not bool(pm[hy_row, cx2]) and not bool(wm[hy_row, cx2]):
                    return (Tool.WIRE, cx2, hy_row)

    # ---- PHASE 3: VERTICAL WIRE between hood rows (same column) ----
    for hx_col in nh_cols:
        col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
        col_hoods.sort(key=lambda h: h[1])
        for i in range(len(col_hoods) - 1):
            hy1 = col_hoods[i][1]
            hy2 = col_hoods[i + 1][1]
            for cy2 in range(hy1 + 1, hy2):
                if ib(hx_col, cy2) and bool(em[cy2, hx_col]) and not bool(pm[cy2, hx_col]) and not bool(wm[cy2, hx_col]):
                    return (Tool.WIRE, hx_col, cy2)

    # ---- PHASE 4: ROAD GRID - horizontal roads at hood rows ±4 ----
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        if not row_hoods:
            continue
        row_hoods.sort(key=lambda h: h[0])
        xl = max(2, row_hoods[0][0] - 6)
        xr = min(WORLD_W - 3, row_hoods[-1][0] + 6)
        for horiz_y in [hy_row - 4, hy_row + 4]:
            if not ib(xl, horiz_y):
                continue
            for cx3 in range(xl, xr + 1):
                if ib(cx3, horiz_y) and bool(em[horiz_y, cx3]) and not bool(pm[horiz_y, cx3]):
                    return (Tool.ROAD, cx3, horiz_y)

    # ---- PHASE 5: ROAD GRID - vertical roads at hood cols ±4 ----
    for hx_col in nh_cols:
        col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
        if not col_hoods:
            continue
        col_hoods.sort(key=lambda h: h[1])
        yt = max(2, col_hoods[0][1] - 6)
        yb = min(WORLD_H - 3, col_hoods[-1][1] + 6)
        for vert_x in [hx_col - 4, hx_col + 4]:
            if not ib(vert_x, yt):
                continue
            for cy3 in range(yt, yb + 1):
                if ib(vert_x, cy3) and bool(em[cy3, vert_x]) and not bool(pm[cy3, vert_x]):
                    return (Tool.ROAD, vert_x, cy3)

    # ---- PHASE 6: ZONE PLACEMENT (earlier, more aggressive) ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS near powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- PHASE 8: CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy)
                      for fx in range(10, WORLD_W, 20)
                      for fy in range(10, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2)
                        for px2 in range(12, WORLD_W, 24)
                        for py2 in range(12, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (20, 8), (60, 8), (100, 8),
            (20, 92), (60, 92), (100, 92),
            (8, 50), (112, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (6, 6), (114, 6), (6, 94), (114, 94),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (30, 6), (90, 6), (30, 94), (90, 94),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2000:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [
            (40, 5), (80, 5), (40, 94), (80, 94),
            (5, 35), (5, 65), (115, 35), (115, 65),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 3 + i * 17) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # ---- FALLBACK: new plant near uncovered hood ----
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: place 3 coal plants with wire connections and seed roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(52, 70):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(42, 59):
        actions.append((Tool.WIRE, 60, y))
    # Seed roads offset from wire spines
    for x in range(52, 70):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(42, 59):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    # Left plant
    actions.append((Tool.COALPOWER, 25, 50))
    for x in range(18, 33):
        actions.append((Tool.WIRE, x, 50))
    # Right plant
