    for x in range(88, 103):
        if x < WORLD_W:
            actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # ---- HELPER: build adjacency-expanded masks ----
    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_power = expand_mask(wm | pm, 4)

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Check if each major region has a plant; if not, place one
    if funds > 3000:
        # Use a 3x3 grid of regions
        region_centers = [(x, y) for y in range(20, 90, 25) for x in range(20, 110, 25)]
        for (hx, hy) in region_centers:
            x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
            y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find nearest empty tile
                for r in range(15):
                    for angle_i in range(4 * (2 * r + 1)):
                        # Spiral outward
                        if r == 0:
                            nx, ny = hx, hy
                        else:
                            side = angle_i // (2 * r)
                            pos = angle_i % (2 * r)
                            if side == 0:   nx, ny = hx - r + pos, hy - r
                            elif side == 1: nx, ny = hx + r, hy - r + pos
                            elif side == 2: nx, ny = hx + r - pos, hy + r
                            else:           nx, ny = hx - r, hy + r - pos
                        if ib(nx, ny) and bool(em[ny, nx]):
                            tool = Tool.NUCLEARPOWER if (funds > 15000 and pop > 2000) else Tool.COALPOWER
                            return (tool, nx, ny)

    # ---- PHASE 2: EXTEND WIRES FROM PLANTS TO REACH ZONES ----
    # Find plants and extend wires toward uncovered areas
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        # Look for empty tiles adjacent to existing wires/plants that need coverage
        wire_or_plant = wm | pm
        # Find frontier: empty tiles adjacent to wire/plant
        frontier_mask = em & expand_mask(wire_or_plant, 1) & ~wire_or_plant
        # Priority: cells far from existing power coverage
        not_powered_road = rm & ~nbr_power
        if bool(np.any(not_powered_road)):
            # Find closest wire frontier to unpowered road
            fr_ys, fr_xs = np.where(frontier_mask)
            unp_ys, unp_xs = np.where(not_powered_road)
            if len(fr_xs) > 0 and len(unp_xs) > 0:
                # Pick a random unpowered road tile
                idx = (step * 17 + pop * 3) % len(unp_xs)
                tx, ty = int(unp_xs[idx]), int(unp_ys[idx])
                # Find closest frontier wire position
                dists = np.abs(fr_xs - tx) + np.abs(fr_ys - ty)
                best = np.argmin(dists)
                wx, wy = int(fr_xs[best]), int(fr_ys[best])
                if bool(em[wy, wx]):
                    return (Tool.WIRE, wx, wy)

        # Generic wire extension from plant
        sk = (step * 11) % len(pxs)
        for offset in range(min(len(pxs), 30)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 3: EXTEND WIRE NETWORK ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        # Extend wires toward areas that have roads but no power
        not_powered_road = rm & ~nbr_power
        if bool(np.any(not_powered_road)):
            unp_ys, unp_xs = np.where(not_powered_road)
            idx = (step * 13 + pop * 7) % len(unp_xs)
            tx, ty = int(unp_xs[idx]), int(unp_ys[idx])
            # BFS-like: find wire tile closest to target
            dists = np.abs(wxs_arr - tx) + np.abs(wys_arr - ty)
            best_k = np.argmin(dists)
            wx2, wy2 = int(wxs_arr[best_k]), int(wys_arr[best_k])
            # Step toward target
            dx_sign = np.sign(tx - wx2)
            dy_sign = np.sign(ty - wy2)
            candidates = []
            if dx_sign != 0: candidates.append((wx2 + dx_sign, wy2))
            if dy_sign != 0: candidates.append((wx2, wy2 + dy_sign))
            for nx3, ny3 in candidates:
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

        # Fallback: extend from any wire
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 40)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- PHASE 4: ROAD NETWORK ----
    # Extend roads adjacent to wires/plants (roads near power)
    powered_empty = em & nbr_power & ~wm & ~pm
    # Find road-adjacent empty tiles that are powered
    near_road_powered = powered_empty & expand_mask(rm, 1)
    if bool(np.any(near_road_powered)):
        nrp_ys, nrp_xs = np.where(near_road_powered)
        idx = (step * 19 + pop * 11) % len(nrp_xs)
        rx2, ry2 = int(nrp_xs[idx]), int(nrp_ys[idx])
        return (Tool.ROAD, rx2, ry2)

    # Extend road from existing road network into powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # Vary zone type with step to avoid monotony
        if i_r < 0.20:
            return Tool.INDUSTRIAL
        if c_r < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: prefer tiles close to existing zones (clustering) and near roads
        score = np.full(len(cxs), 0.0)

        # Proximity to existing zones
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score += zone_prox * 0.7

        # Proximity to roads (prefer tiles directly next to road)
        road_prox = np.full(len(cxs), 0.0)
        for i in range(len(cxs)):
            cx2, cy2 = int(cxs[i]), int(cys[i])
            adj_road = sum(1 for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]
                          if ib(cx2+dx, cy2+dy) and bool(rm[cy2+dy, cx2+dx]))
            road_prox[i] = -adj_road  # more adjacent road = better (lower score)
        score += road_prox * 2.0

        # Add small random offset to avoid repetition
        off = (step * 7 + pop * 3) % max(len(cxs), 1)
        order = np.argsort(score)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: CIVIC SERVICES ----
    if pop > 10:
        fire_grid = [(fx, fy) for fy in range(15, 95, 18)
                     for fx in range(15, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 50:
        police_grid = [(px2, py2) for py2 in range(15, 95, 20)
                       for px2 in range(15, 115, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 120 and step % 3 == 0:
        park_ys, park_xs = np.where(em & nbr_road)
        if len(park_xs) > 0:
            idx = (step * 17 + pop) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [
            (20, 20), (60, 15), (100, 20),
            (20, 80), (60, 85), (100, 80),
            (15, 50), (105, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 500 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy):
                continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 400:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 700:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire spines + flanking roads."""
    actions = []
    # Two cluster centers
    for cx, cy in [(40, 50), (80, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        # Horizontal wire spine
        for dx in range(-6, 7):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        # Vertical wire spine
        for dy in range(-5, 6):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Flanking roads
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, cx + dx, cy - 2))
            actions.append((Tool.ROAD, cx + dx, cy + 2))
        for dy in range(-4, 5):
            actions.append((Tool.ROAD, cx - 2, cy + dy))
            actions.append((Tool.ROAD, cx + 2, cy + dy))
    # Wire bridge between clusters
    for x in range(47, 73):
        actions.append((Tool.WIRE, x, 50))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 35% RES, 35% IND, 30% COM
        if ir < 0.33:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Active neighborhoods - progressively unlock more
    nh_cols = [20, 40, 60, 80, 100]
    nh_rows = [20, 35, 50, 65, 80]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 100:  return 2
        if pop < 300:  return 4
        if pop < 600:  return 8
        if pop < 1200: return 12
        if pop < 2500: return 18
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    active_hoods = all_hoods[:n_active]

    power_src = wm | pm

    # Dilate power mask (radius 5)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            if abs(dx) + abs(dy) > 5:
                continue
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            if r1 > r0 and c1 > c0:
                nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    # Dilate road mask (radius 2)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            if r1 > r0 and c1 > c0:
                nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: ENSURE POWER PLANTS NEAR ACTIVE HOODS ===
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE SPINES TO EACH ACTIVE HOOD ===
    spine_range = 7
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    # Find nearest plant and wire toward hood
    x0p, x1p = max(0, hx - 15), min(WORLD_W, hx + 16)
    y0p, y1p = max(0, hy - 15), min(WORLD_H, hy + 16)
    plant_ys_l, plant_xs_l = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs_l) > 0:
        px_l = int(plant_xs_l[0]) + x0p
        py_l = int(plant_ys_l[0]) + y0p
        # Wire vertically from plant to hood y-level
        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        # Wire horizontally from plant to hood x-level
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spine at hood center
    for dy in range(-spine_range, spine_range + 1):
        wy = hy + dy
        if not ib(hx, wy): continue
        if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
        if not bool(em[wy, hx]): continue
        for adj in [-1, 1]:
            ay = wy + adj
            if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                return (Tool.WIRE, hx, wy)

    for dx in range(-spine_range, spine_range + 1):
        wx = hx + dx
        if not ib(wx, hy): continue
        if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
        if not bool(em[hy, wx]): continue
        for adj in [-1, 1]:
            ax = wx + adj
            if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                return (Tool.WIRE, wx, hy)

    # === PHASE 3: ROADS FLANKING WIRE SPINES ===
    road_idx = step % max(len(active_hoods), 1)
    hx_r, hy_r = active_hoods[road_idx]

    for rx in [hx_r - 2, hx_r + 2]:
        if not ib(rx, hy_r): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy_r + dy
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]) or bool(pm[ry, rx]): continue
            if not bool(em[ry, rx]) and not bool(zone_tiles[ry, rx]): continue
            if bool(wm[ry, hx_r]) or bool(pm[ry, hx_r]):
                return (Tool.ROAD, rx, ry)

    for ry in [hy_r - 2, hy_r + 2]:
        if not ib(hx_r, ry): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx_r + dx
            if not ib(rcx, ry): continue
            if bool(rm[ry, rcx]) or bool(pm[ry, rcx]): continue
            if not bool(em[ry, rcx]) and not bool(zone_tiles[ry, rcx]): continue
            if bool(wm[hy_r, rcx]) or bool(pm[hy_r, rcx]):
                return (Tool.ROAD, rcx, ry)

    # === PHASE 4: ZONE PLACEMENT ===
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to active hoods + proximity to existing zones
        best_dist = np.full(len(cxs), 999999.0)
        for (hx2, hy2) in active_hoods:
            d = np.abs(cxs - hx2) + np.abs(cys - hy2)
            best_dist = np.minimum(best_dist, d)

        score = best_dist.copy()
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.6 + zone_prox * 0.4

        order = np.argsort(score)
        off = (step * 11 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: EXTEND ROADS INTO POWERED EMPTY AREAS ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx, ry2 + dy
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # === CIVIC SERVICES (reactive to pop) ===
    if pop > 80:
        for fx in range(12, WORLD_W, 18):
            for fy in range(12, WORLD_H, 18):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(nbr_power[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 200:
        for px2 in range(14, WORLD_W, 20):
            for py2 in range(14, WORLD_H, 20):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(nbr_power[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 150 and step % 3 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 17) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 400:
        stadium_locs = [
            (25, 25), (60, 20), (95, 25),
            (25, 75), (60, 80), (95, 75),
            (20, 50), (100, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 2000:
        seaport_locs = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (5, 75), (115, 25), (115, 75),
        ]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 500 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (35, 15), (85, 15), (35, 85), (85, 85),
            (60, 5), (60, 95),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 1000:
        airport_locs = [
            (12, 12), (100, 12), (12, 85), (100, 85),
        ]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: EXTEND WIRE FROM EXISTING ===
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx, wy2 + dy
                if (ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3])):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: NEW PLANT FOR UNCOVERED HOOD ===
    for (hx3, hy3) in active_hoods:
        if not bool(nbr_power[hy3, hx3]):
            for r2 in range(1, 14):
                for dy in range(-r2, r2 + 1):
                    for dx in range(-r2, r2 + 1):
                        if abs(dx) == r2 or abs(dy) == r2:
                            nx4, ny4 = hx3 + dx, hy3 + dy
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + cross wire grid + roads"""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 75))
    # Vertical wire spines
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Roads flanking horizontal wire spines
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 50% res, 30% com, 20% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    wire_cols = [30, 60, 90]
    wire_rows = [25, 50, 75]

    # Dense grid of neighborhood centers
    nh_positions = []
    for row_i in range(6):
        for col_i in range(7):
            cx = 8 + col_i * 16
            cy = 8 + row_i * 16
            cx = min(cx, WORLD_W - 5)
            cy = min(cy, WORLD_H - 5)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 50:
            return [(30, 50), (60, 50), (90, 50), (30, 25), (60, 25), (90, 25)]
        elif pop < 200:
            return nh_positions[:20]
        elif pop < 600:
            return nh_positions[:28]
        elif pop < 1500:
            return nh_positions[:36]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 16

    # Ensure power coverage
    if step % 5 == 0:
        for (hx, hy) in active_hoods[:12]:
            x0, x1 = max(0, hx - 20), min(WORLD_W, hx + 21)
            y0, y1 = max(0, hy - 20), min(WORLD_H, hy + 21)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(3, 22):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx2, ny2 = hx + dx, hy + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    if phase == 0:
        # Extend horizontal wire rows
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire cols
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Horizontal mid-roads between wire rows
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)
        # Also roads above/below map edges
        for wr_extra in [12, 88]:
            for rx in range(1, WORLD_W - 1):
                if bool(em[wr_extra, rx]) and bool(near_power[wr_extra, rx]) and not bool(pm[wr_extra, rx]):
                    adj = ((rx > 0 and bool(rm[wr_extra, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[wr_extra, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, wr_extra)

    elif phase == 5:
        # Vertical mid-roads between wire cols
        for ci in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[ci], wire_cols[ci + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)
        # Side verticals
        for cx_extra in [10, 110]:
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, cx_extra]) and bool(near_power[ry, cx_extra]) and not bool(pm[ry, cx_extra]):
                    adj = ((ry > 0 and bool(rm[ry-1, cx_extra])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, cx_extra])))
                    if adj:
                        return (Tool.ROAD, cx_extra, ry)

    elif phase == 6:
        # Extend road from existing roads toward powered areas
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 9) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zone tiles
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 19) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Add extra wire rows for outer coverage
        extra_wire_rows = [12, 37, 62, 87]
        for ewr in extra_wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[ewr, wx]) and not bool(pm[ewr, wx]) and bool(em[ewr, wx]):
                    left = wx > 0 and (bool(wm[ewr, wx-1]) or bool(pm[ewr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[ewr, wx+1]) or bool(pm[ewr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, ewr)

    elif phase in (9, 10, 11, 12, 13, 14, 15):
        # Civic services scaled to population
        if pop > 10:
            fire_spots = [(5,5),(35,5),(65,5),(95,5),(115,5),
                          (5,20),(35,20),(65,20),(95,20),(115,20),
                          (5,40),(115,40),
                          (5,60),(35,60),(65,60),(95,60),(115,60),
                          (5,80),(35,80),(65,80),(95,80),(115,80),
                          (5,95),(35,95),(65,95),(95,95),(115,95)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 60:
            police_spots = [(15,12),(45,12),(75,12),(105,12),
                            (15,37),(45,37),(75,37),(105,37),
                            (15,62),(45,62),(75,62),(105,62),
                            (15,87),(45,87),(75,87),(105,87)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 300:
            stadium_spots = [(20,18),(70,18),(20,68),(70,68),(45,43),(95,43)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 600:
            nuke_spots = [(5,50),(115,50),(60,5),(60,94),(5,25),(115,75)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 900:
            seaports = [(5,92),(115,92),(5,5),(115,5)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1500:
            airports = [(45,5),(75,5),(45,92),(75,92)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Keep away from wire/road spines
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # Parks for land value
    if pop > 20 and step % 3 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx, hy) for (hx, hy) in active_hoods if not bool(near_power[hy, hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire spine + initial roads"""
    actions = []
    # Central power plant at (60, 50)
    actions.append((Tool.COALPOWER, 60, 50))
