        actions.append((Tool.ROAD, 62, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Check power plants on grid, place if missing ----
    # Denser grid of plants every 20 tiles
    plant_positions = []
    for py in range(12, 92, 20):
        for px in range(12, 112, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 7), min(WORLD_W, px + 8)
        y0, y1 = max(0, py - 7), min(WORLD_H, py + 8)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Reactively extend wire from existing power toward unpowered zones ----
    # Find adjacency to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    # Identify unpowered plants to connect first
    unpowered_plants = [(ppx, ppy) for ppx, ppy in plant_positions
                        if ib(ppx, ppy) and np.any(pm[max(0,ppy-1):ppy+2, max(0,ppx-1):ppx+2])
                        and not bool(near_power[ppy, ppx])]

    if len(wxs) > 0:
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Extend wire toward unpowered plant grid positions
        for ppx2, ppy2 in plant_positions:
            if not ib(ppx2, ppy2): continue
            if not bool(near_power[ppy2, ppx2]) and len(wxs) > 0:
                best_dist = 1e9
                best_k = 0
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = abs(cx - ppx2) + abs(cy - ppy2)
                    if d < best_dist:
                        best_dist = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Reactive road grid extending from existing roads ----
    # Build roads on a 5-tile grid (denser than parent's 6)
    road_grid_targets = []
    for gy in range(5, 98, 5):
        for gx in range(5, 118, 5):
            road_grid_targets.append((gx, gy))

    # Find grid targets not yet covered, near power
    uncovered = [(gx, gy) for gx, gy in road_grid_targets
                 if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered:
        # Find road-adjacent empty tiles and extend toward uncovered targets
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered[:40]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Direct placement if near power
            for gx, gy in uncovered[:10]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement (reactive to current power+road coverage) ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Score: close to road, spread from existing zones, prefer powered
        pwr_score = near_power[cys_arr, cxs_arr].astype(float) * 3.0
        score = road_dist * 1.0 + np.maximum(0, 8 - zone_dist) * 2.0 - pwr_score

        order = np.argsort(score)
        # Use step+pop to vary starting offset (reactive to pop changes)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Tool selection based on current ratios (reactive)
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        # Cycle: mostly residential, then commercial, then industrial
        step_mod = step % 10
        if ir < 0.18:
            tool = Tool.INDUSTRIAL
        elif cr < 0.22:
            tool = Tool.COMMERCIAL
        elif step_mod < 6:
            tool = Tool.RESIDENTIAL
        elif step_mod < 8:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled reactively to population ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(7, 95, 9) for fx in range(7, 115, 9)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 120:
        police_grid = [(px2, py2) for py2 in range(10, 92, 11) for px2 in range(10, 112, 11)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_grid = [(pkx, pky) for pky in range(8, 95, 8) for pkx in range(8, 115, 8)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (60, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        nuke_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-5), min(WORLD_W, nx+6)
                y0, y1 = max(0, ny-5), min(WORLD_H, ny+6)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 90)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: wire near plant, or road near plant ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 0), (0, 3)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

