def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 35% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- CLOSED-LOOP REACTIVE DECISIONS ---

    # 1. If there are regions without power plants, place one nearby unpowered zones
    # Find unpowered zones and place a plant close to them
    unpowered_zones = zone_tiles & ~near_power
    uz_ys, uz_xs = np.where(unpowered_zones)
    if len(uz_xs) > 5 and step % 25 == 1:
        # Find centroid of unpowered zones
        cx = int(np.mean(uz_xs))
        cy = int(np.mean(uz_ys))
        # Try to place coal plant nearby in empty space
        for r in range(0, 15):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) != r and abs(dy) != r:
                        continue
                    nx, ny = cx + dx, cy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # 2. Extend wire from existing power sources toward empty powered-adjacent zones
    # Find the frontier: empty tiles adjacent to wires/plants
    wire_or_plant = wm | pm
    wp_ys, wp_xs = np.where(wire_or_plant)

    # Priority: connect wire toward unpowered zones
    if len(uz_xs) > 0 and step % 3 == 0:
        if len(wp_xs) > 0:
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            dists = np.abs(wp_xs - tx).astype(float) + np.abs(wp_ys - ty).astype(float)
            best = np.argmin(dists)
            bwx, bwy = int(wp_xs[best]), int(wp_ys[best])
            # Step toward target
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            candidates = []
            if dx != 0:
                candidates.append((bwx + dx, bwy))
            if dy != 0:
                candidates.append((bwx, bwy + dy))
            if dx != 0 and dy != 0:
                candidates.append((bwx + dx, bwy + dy))
            for nx, ny in candidates:
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # 3. Build roads: extend roads toward zones without road access
    unroaded_zones = zone_tiles & ~near_road
    urz_ys, urz_xs = np.where(unroaded_zones)
    road_ys, road_xs = np.where(rm)
    if len(urz_xs) > 0 and len(road_xs) > 0 and step % 4 == 1:
        idx = (step * 13) % len(urz_xs)
        tx, ty = int(urz_xs[idx]), int(urz_ys[idx])
        dists = np.abs(road_xs - tx).astype(float) + np.abs(road_ys - ty).astype(float)
        best = np.argmin(dists)
        brx, bry = int(road_xs[best]), int(road_ys[best])
        dx = 0 if tx == brx else (1 if tx > brx else -1)
        dy = 0 if ty == bry else (1 if ty > bry else -1)
        for nx, ny in [(brx + dx, bry), (brx, bry + dy)]:
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    # 4. Add new power plants when power coverage is low
    powered_ratio = obs.powered_zones / max(total_zones, 1)
    if powered_ratio < 0.7 and total_zones > 5 and step % 20 == 3:
        # Place coal plant in most empty region
        best_score = -1
        best_pos = None
        for py in range(10, 90, 20):
            for px in range(10, 110, 25):
                x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
                y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    score = int(np.sum(em[y0:y1, x0:x1]))
                    if score > best_score and bool(em[py, px]):
                        best_score = score
                        best_pos = (px, py)
        if best_pos:
            return (Tool.COALPOWER, best_pos[0], best_pos[1])

    # 5. Build new horizontal/vertical road corridors reactively
    # Find the row/column with most powered empty tiles and build road there
    if step % 7 == 2:
        powered_empty = em & near_power
        # Score each row
        row_scores = np.sum(powered_empty, axis=1)
        # Avoid existing road rows
        for ry in np.argsort(-row_scores):
            ry = int(ry)
            if ry < 2 or ry >= WORLD_H - 2:
                continue
            if np.sum(rm[ry, :]) > 10:
                continue  # already has roads
            # Build road along this row
            for rx in range(1, WORLD_W - 1):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                          (ry > 0 and bool(rm[ry-1, rx])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                    if adj or rx == 1:
                        return (Tool.ROAD, rx, ry)
            break

    if step % 7 == 5:
        powered_empty = em & near_power
        col_scores = np.sum(powered_empty, axis=0)
        for cx in np.argsort(-col_scores):
            cx = int(cx)
            if cx < 2 or cx >= WORLD_W - 2:
                continue
            if np.sum(rm[:, cx]) > 10:
                continue
            for cy in range(1, WORLD_H - 1):
                if bool(em[cy, cx]) and not bool(pm[cy, cx]):
                    adj = (cy > 0 and bool(rm[cy-1, cx])) or \
                          (cy < WORLD_H-1 and bool(rm[cy+1, cx])) or \
                          (cx > 0 and bool(rm[cy, cx-1])) or \
                          (cx < WORLD_W-1 and bool(rm[cy, cx+1]))
                    if adj or cy == 1:
                        return (Tool.ROAD, cx, cy)
            break

    # 6. Wire extension: connect wire toward all power-needing roads
    road_no_power = rm & ~near_power
    rnp_ys, rnp_xs = np.where(road_no_power)
    if len(rnp_xs) > 0 and len(wp_xs) > 0 and step % 3 == 2:
        idx = (step * 23) % len(rnp_xs)
        tx, ty = int(rnp_xs[idx]), int(rnp_ys[idx])
        dists = np.abs(wp_xs - tx).astype(float) + np.abs(wp_ys - ty).astype(float)
        best = np.argmin(dists)
        bwx, bwy = int(wp_xs[best]), int(wp_ys[best])
        dx = 0 if tx == bwx else (1 if tx > bwx else -1)
        dy = 0 if ty == bwy else (1 if ty > bwy else -1)
        for nx, ny in [(bwx + dx, bwy), (bwx, bwy + dy)]:
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # 7. Civic services based on population
    if pop > 20:
        fire_spots = [(20,20),(50,20),(80,20),(110,20),
                      (20,50),(50,50),(80,50),(110,50),
                      (20,80),(50,80),(80,80),(110,80)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [(15,15),(45,15),(75,15),(105,15),
                        (15,45),(45,45),(75,45),(105,45),
                        (15,75),(45,75),(75,75),(105,75)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(30,25),(70,25),(30,65),(70,65),(50,45),(90,45)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_spots = [(20,50),(100,50),(60,20),(60,80),(40,35),(80,65)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5,90),(115,90),(5,10),(115,10)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50,5),(70,5),(50,92),(70,92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value when pop is moderate
    if pop > 200 and step % 6 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # 8. PRIMARY: Zone placement in powered+roaded empty areas
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Pick active centers based on current pop — grow outward as city grows
        if pop < 100:
            centers = [(60, 50), (50, 47), (70, 53), (55, 44), (65, 56),
                       (45, 50), (75, 50), (60, 42), (60, 58)]
        elif pop < 500:
            centers = []
            for row in range(5):
                for col in range(7):
                    centers.append((15 + col * 15, 15 + row * 17))
        elif pop < 2000:
            centers = []
            for row in range(7):
                for col in range(9):
                    centers.append((10 + col * 12, 10 + row * 12))
        else:
            centers = []
            for row in range(10):
                for col in range(12):
                    centers.append((5 + col * 10, 5 + row * 9))

        best_dist = np.full(len(cxs), 999999.0)
        for hx, hy in centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    if len(wp_xs) > 0:
        sk2 = (step * 13) % len(wp_xs)
        for off in range(min(len(wp_xs), 100)):
            k = (sk2 + off * 5) % len(wp_xs)
            wx2, wy2 = int(wp_xs[k]), int(wp_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
