def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target zone ratios: 50% RES, 25% COM, 25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    near_power = dilate(wm | pm, 8)
    near_road = dilate(rm, 3)

    # Grid of wire corridors — denser than parent
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]

    # Power plants distributed across map
    plant_positions = [
        (15, 15), (60, 15), (105, 15),
        (15, 50), (60, 50), (105, 50),
        (15, 85), (60, 85), (105, 85),
        (35, 30), (85, 30), (35, 70), (85, 70),
    ]

    # ---- PHASE 0: Ensure plants exist ----
    for px, py in plant_positions:
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    # ---- PHASE 1: Extend horizontal wire corridors ----
    if phase == 0:
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = int(np.argmin(dists))
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        left = wx > 0 and bool(row_power[wx - 1])
                        right = wx < WORLD_W - 1 and bool(row_power[wx + 1])
                        if (left or right) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # ---- PHASE 2: Extend vertical wire corridors ----
    elif phase == 1:
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = int(np.argmin(dists))
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2 + step_x, wc + step_x, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        up = wy > 0 and bool(col_power[wy - 1])
                        dn = wy < WORLD_H - 1 and bool(col_power[wy + 1])
                        if (up or dn) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: Roads parallel to horizontal wire corridors ----
    elif phase == 2:
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-2, 2]:  # Two tiles away from wire
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: Roads parallel to vertical wire corridors ----
    elif phase == 3:
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-2, 2]:  # Two tiles away from wire
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # ---- PHASE 5: Connect wire corridors at intersections ----
    elif phase == 4:
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc - 1] or pm[wr, wc - 1])) or \
                         (wc < WORLD_W - 1 and bool(wm[wr, wc + 1] or pm[wr, wc + 1]))
                col_ok = (wr > 0 and bool(wm[wr - 1, wc] or pm[wr - 1, wc])) or \
                         (wr < WORLD_H - 1 and bool(wm[wr + 1, wc] or pm[wr + 1, wc]))
                if (row_ok or col_ok) and bool(em[wr, wc]) and not bool(pm[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    # ---- PHASE 6: Cross roads between wire rows ----
    elif phase == 5:
        for wr_idx in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[wr_idx], wire_rows[wr_idx + 1]
            for wc in wire_cols:
                for offset in [-2, 2]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    for mid_y in range(wr1 + 1, wr2):
                        if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                            adj = (ib(rcx, mid_y - 1) and bool(rm[mid_y - 1, rcx])) or \
                                  (ib(rcx, mid_y + 1) and bool(rm[mid_y + 1, rcx]))
                            if adj:
                                return (Tool.ROAD, rcx, mid_y)

    # ---- PHASE 7: Zone placement (primary growth) ----
    elif phase in (6, 7):
        cand_mask = em & near_road & near_power
        cand_mask[0:3, :] = False
        cand_mask[WORLD_H - 3:, :] = False
        cand_mask[:, 0:3] = False
        cand_mask[:, WORLD_W - 3:] = False
        # Avoid wire corridor rows and cols
        for wr in wire_rows:
            if 0 <= wr < WORLD_H:
                cand_mask[max(0, wr - 1):wr + 2, :] = False
        for wc in wire_cols:
            if 0 <= wc < WORLD_W:
                cand_mask[:, max(0, wc - 1):wc + 2] = False

        cys2, cxs2 = np.where(cand_mask)
        if len(cxs2) > 0:
            zone_near = dilate(zone_tiles, 5)
            scores = np.zeros(len(cxs2), dtype=float)
            for i in range(len(cxs2)):
                x, y = int(cxs2[i]), int(cys2[i])
                scores[i] = 3.0 if bool(zone_near[y, x]) else 0.0
                # Prefer areas away from center to spread city evenly
                dist_center = abs(x - 60) / 60.0 + abs(y - 50) / 50.0
                scores[i] += 0.3 * dist_center

            order = np.argsort(-scores)
            offset = (step * 7 + pop * 3) % max(len(order), 1)
            tool = pick_tool()
            checked = 0
            for i in range(len(order)):
                k = order[(offset + i) % len(order)]
                zx, zy = int(cxs2[k]), int(cys2[k])
                if zone_clear(zx, zy):
                    return (tool, zx, zy)
                checked += 1
                if checked > 800:
                    break

    # ---- PHASE 8: Wire unpowered roads ----
    elif phase == 8:
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 9: Extend roads toward powered unroaded areas ----
    elif phase == 9:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H - 3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W - 3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to pop) ----
    if pop > 50:
        fire_positions = [
            (10, 10), (40, 10), (70, 10), (100, 10),
            (10, 35), (40, 35), (70, 35), (100, 35),
            (10, 60), (40, 60), (70, 60), (100, 60),
            (10, 85), (40, 85), (70, 85), (100, 85),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (25, 20), (55, 20), (85, 20),
            (10, 45), (40, 45), (70, 45), (100, 45),
            (25, 70), (55, 70), (85, 70),
            (10, 90), (40, 90), (70, 90), (100, 90),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (25, 30), (85, 30), (25, 70), (85, 70),
            (55, 20), (55, 80), (10, 55), (105, 55),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        # Upgrade to nuclear for more power
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
            (30, 50), (90, 50), (60, 25), (60, 75),
            (35, 30), (85, 30), (35, 70), (85, 70),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 5), (60, 94)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92), (5, 45), (110, 45)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (fallback / primary any phase) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 3.0 if bool(zone_near[y, x]) else 0.0
            dist_center = abs(x - 60) / 60.0 + abs(y - 50) / 50.0
            scores[i] += 0.3 * dist_center

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- FALLBACK: extend road from existing roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: new coal plant near unpowered area ----
    all_hoods = [(cx, cy) for cy in range(8, 100, 10) for cx in range(8, 120, 12)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross extending outward
    for d in range(1, 8):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Roads flanking the vertical wire spine
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD GRID: 8 cols x 6 rows = 48 neighborhoods ----
    nh_cols = [8, 22, 36, 50, 64, 78, 92, 106]
    nh_rows = [8, 24, 40, 56, 72, 88]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 30:    return 2
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 700:   return 14
        if pop < 1500:  return 22
        if pop < 3000:  return 32
        if pop < 6000:  return 40
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods
    else:
        step_size = len(all_hoods) / n_active
        active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR POWER/ROAD MASKS (REACTIVE) ----
    # These reflect current map state - truly closed-loop
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANTS for each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 10), min(WORLD_W, hx + 11)
        y0, y1 = max(0, hy - 10), min(WORLD_H, hy + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Try anchor first
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: EXTEND WIRE FROM EXISTING WIRE/PLANT (reactive BFS-style) ----
    # For each active hood, extend wire spine toward it if not powered
    spine_range = 10
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if step % max(len(active_hoods), 1) != idx_h % max(len(active_hoods), 1):
            continue
        # Vertical wire spine at column hx, centered on hy
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(wm[wy, hx]) or bool(pm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj_dy in [-1, 1]:
                ay = wy + adj_dy
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)
        # Horizontal wire spine at row hy
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(wm[hy, wx]) or bool(pm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj_dx in [-1, 1]:
                ax = wx + adj_dx
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # ---- PHASE 3: CONNECT WIRE BETWEEN ADJACENT HOODS ----
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            # Horizontal neighbors
            if hy1 == hy2 and hx2 == hx1 + 14:
                for cx2 in range(hx1 + 1, hx2):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            # Vertical neighbors
            if hx1 == hx2 and hy2 == hy1 + 16:
                for cy2 in range(hy1 + 1, hy2):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # ---- PHASE 4: ROADS flanking wire spines (reactive: only where wire exists) ----
    for idx_h, (hx, hy) in enumerate(active_hoods):
        if (step + idx_h) % max(len(active_hoods) // 2 + 1, 1) != 0:
            continue
        for rx in [hx - 1, hx + 1]:
            if not ib(rx, hy): continue
            for dy in range(-spine_range, spine_range + 1):
                ry = hy + dy
                if not ib(rx, ry): continue
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Only place road where wire spine actually exists
                    if bool(wm[ry, hx]) or bool(pm[ry, hx]):
                        return (Tool.ROAD, rx, ry)
        for ry2 in [hy - 1, hy + 1]:
            if not ib(hx, ry2): continue
            for dx in range(-spine_range, spine_range + 1):
                rcx = hx + dx
                if not ib(rcx, ry2): continue
                if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                    if bool(wm[hy, rcx]) or bool(pm[hy, rcx]):
                        return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT (reactive: based on current power+road coverage) ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        # Target: 45% RES, 28% COM, 27% IND
        if ir < 0.24:
            return Tool.INDUSTRIAL
        if cr < 0.26:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate zone centers: empty, near road, near power (from current map)
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered empty areas (reactive) ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (triggered by observed population) ----
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 16) for fy in range(12, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(14, WORLD_W, 20) for py2 in range(14, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [(30, 30), (90, 30), (30, 70), (90, 70),
                    (60, 15), (60, 85), (15, 50), (105, 50),
                    (45, 50), (75, 50), (60, 30), (60, 70)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 5), (30, 95), (90, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(45, 6), (75, 6), (45, 94), (75, 94),
                    (6, 45), (6, 65), (114, 45), (114, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear power for high-pop (reactive: only if spot empty)
    if pop > 2000 and step % 3 == 0:
        nuclear_spots = [
            (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
            (8, 50), (112, 50), (60, 8), (60, 92),
            (20, 50), (100, 50), (50, 20), (70, 20),
            (20, 20), (100, 20), (20, 80), (100, 80),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 150 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from any existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place plant near unpowered hood ----
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            if ib(hx, hy) and bool(em[hy, hx]):
                return (Tool.COALPOWER, hx, hy)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power plants + wire spines + road grid"""
    actions = []
    # Place coal plants at key locations
    for px, py in [(30, 50), (90, 50), (60, 25), (60, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at tighter spacing
    for wy in [25, 40, 55, 70, 85]:
        for x in range(2, 118):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [15, 35, 55, 75, 95, 110]:
        for y in range(2, 98):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking wire rows
    for wy in [25, 40, 55, 70, 85]:
        for x in range(2, 118):
            actions.append((Tool.ROAD, x, wy - 1))
