def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.33:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30:
                return Tool.COMMERCIAL
            if rr < 0.50:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PRIORITY 0: Add more power plants if needed ===
    plant_positions = list(zip(*np.where(pm))) if np.any(pm) else []
    n_plants = len(plant_positions)
    # One plant per ~30 zones, minimum 2
    needed_plants = max(2, total_zones // 30)
    if n_plants < needed_plants:
        # Find good spot: near wire, empty, away from other plants
        if np.any(wm):
            wire_ys, wire_xs = np.where(wm)
            # Try candidate positions on wire grid
            for attempt in range(50):
                idx = (step * 17 + attempt * 7) % len(wire_xs)
                cx, cy = int(wire_xs[idx]), int(wire_ys[idx])
                # Try to place plant near wire
                for r in range(2, 8):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = cx + dx, cy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    # Check not too close to other plants
                                    too_close = False
                                    for ppy, ppx in plant_positions:
                                        if abs(nx - ppx) + abs(ny - ppy) < 15:
                                            too_close = True
                                            break
                                    if not too_close:
                                        return (Tool.COALPOWER, nx, ny)

    # === PRIORITY 1: Extend wire from existing power toward unpowered areas ===
    unpowered_em = em & ~near_power
    if np.any(wm | pm) and np.any(unpowered_em):
        wire_union = wm | pm
        wu_ys, wu_xs = np.where(wire_union)
        up_ys, up_xs = np.where(unpowered_em)
        if len(wu_xs) > 0 and len(up_xs) > 0:
            # Pick a target unpowered empty cell
            tidx = (step * 7) % len(up_xs)
            tx, ty = int(up_xs[tidx]), int(up_ys[tidx])
            dists = np.abs(wu_xs - tx) + np.abs(wu_ys - ty)
            best = np.argmin(dists)
            bwx, bwy = int(wu_xs[best]), int(wu_ys[best])
            # Step wire one tile toward target
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            candidates = []
            if dx != 0:
                candidates.append((bwx + dx, bwy))
            if dy != 0:
                candidates.append((bwx, bwy + dy))
            for nx2, ny2 in candidates:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === PRIORITY 2: Extend road toward zones lacking road access ===
    zones_no_road = zone_tiles & ~near_road
    if np.any(zones_no_road) and np.any(rm):
        zr_ys, zr_xs = np.where(zones_no_road)
        road_ys, road_xs = np.where(rm)
        tidx = (step * 11) % len(zr_xs)
        tx, ty = int(zr_xs[tidx]), int(zr_ys[tidx])
        dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
        best = np.argmin(dists)
        brx, bry = int(road_xs[best]), int(road_ys[best])
        dx = 0 if tx == brx else (1 if tx > brx else -1)
        dy = 0 if ty == bry else (1 if ty > bry else -1)
        candidates = []
        if dx != 0:
            candidates.append((brx + dx, bry))
        if dy != 0:
            candidates.append((brx, bry + dy))
        for nx2, ny2 in candidates:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    # === PRIORITY 3: Extend road into powered areas (reactive expansion) ===
    powered_empty = em & near_power & ~near_road
    if np.any(powered_empty) and np.any(rm):
        road_ys, road_xs = np.where(rm)
        pe_ys, pe_xs = np.where(powered_empty)
        if len(pe_xs) > 0 and len(road_xs) > 0:
            tidx = (step * 13) % len(pe_xs)
            tx, ty = int(pe_xs[tidx]), int(pe_ys[tidx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best = np.argmin(dists)
            brx, bry = int(road_xs[best]), int(road_ys[best])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            candidates = []
            if dx != 0:
                candidates.append((brx + dx, bry))
            if dy != 0:
                candidates.append((brx, bry + dy))
            for nx2, ny2 in candidates:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PRIORITY 4: Civic services ===
    if pop > 50:
        fire_spots = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (10, 30), (40, 10), (80, 10), (110, 30),
            (10, 70), (40, 90), (80, 90), (110, 70),
            (40, 50), (80, 50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [(10, 10), (110, 10), (10, 90), (110, 90),
                      (60, 5), (60, 95), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 150 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 29 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # === PRIORITY 5: Zone placement ===
    cand_mask = em & near_road & near_power
    # Avoid map borders (3 tile margin for 3x3 zones)
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Don't place zones directly on roads or wires
    cand_mask[rm] = False
    cand_mask[wm] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        tool = pick_tool()
        # Score: prefer spots near existing zones (clustering) but also spread
        if np.any(zone_tiles):
            zone_ys_arr, zone_xs_arr = np.where(zone_tiles)
            zone_cx = float(np.mean(zone_xs_arr))
            zone_cy = float(np.mean(zone_ys_arr))
            dist_to_center = np.abs(cxs2 - zone_cx) + np.abs(cys2 - zone_cy)
            # Mix: some clustering, some spreading
            if pop < 500:
                score = dist_to_center  # expand outward
            else:
                score = -dist_to_center  # fill gaps
            order = np.argsort(score)
        else:
            dist_center = np.abs(cxs2 - 60) + np.abs(cys2 - 50)
            order = np.argsort(dist_center)

        offset = (step * 11 + pop * 5) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # === FALLBACK: wire extension from any power source ===
    if np.any(wm | pm):
        wu_ys, wu_xs = np.where(wm | pm)
        if len(wu_xs) > 0:
            k = (step * 19) % len(wu_xs)
            bwx, bwy = int(wu_xs[k]), int(wu_ys[k])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = bwx + dx2, bwy + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # === FALLBACK: road extension ===
    if np.any(rm):
        road_ys2, road_xs2 = np.where(rm)
        k = (step * 23) % len(road_xs2)
        rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
        for dx2, dy2 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
            nx2, ny2 = rx2 + dx2, ry2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + seed roads"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at row 50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at cols 30, 60, 90
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Horizontal wire spines at rows 25, 75
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 75))
    # Roads adjacent to wire rows
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- PHASE 1: Ensure power plants spread across map ---
    # Dense grid: every 20 cols, 20 rows, skip if plant already nearby
    if step % 5 == 0:
        plant_grid_xs = list(range(10, WORLD_W - 5, 20))
        plant_grid_ys = list(range(10, WORLD_H - 5, 20))
        for ppy in plant_grid_ys:
            for ppx in plant_grid_xs:
                if not ib(ppx, ppy):
                    continue
                x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
                y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    if bool(em[ppy, ppx]):
                        return (Tool.COALPOWER, ppx, ppy)

    # --- PHASE 2: Fill wire corridor gaps ---
    if step % 20 == 2:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left_has = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right_has = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left_has or right_has:
                        return (Tool.WIRE, wx, wr)
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up_has = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn_has = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up_has or dn_has:
                        return (Tool.WIRE, wc, wy)

    # --- PHASE 3: Wire toward unpowered zones ---
    if step % 20 == 1:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- PHASE 4: Fill road gaps adjacent to wire rows ---
    if step % 20 == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1]))
                        if has_wire and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    if step % 20 == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx]))
                        if has_wire and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # --- PHASE 5: Additional road rows for denser coverage ---
    if step % 20 == 5:
        extra_road_rows = [12, 37, 62, 87]
        for mr in extra_road_rows:
            if mr <= 0 or mr >= WORLD_H - 1:
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                    adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mr)

    if step % 20 == 6:
        extra_road_cols = [15, 45, 75, 105]
        for mc in extra_road_cols:
            if mc <= 0 or mc >= WORLD_W - 1:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                    adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mc]))
                    if adj:
                        return (Tool.ROAD, mc, ry)

    # --- PHASE 6: Extend road from existing road into powered empty areas ---
    if step % 20 == 7:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- PHASE 7: Wire roads that lack power ---
    if step % 20 == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- CIVIC BUILDINGS (reactive, population-gated) ---
    if pop > 10:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 30), (60, 30), (115, 30),
            (5, 50), (60, 50), (115, 50),
            (5, 70), (60, 70), (115, 70),
            (5, 95), (60, 95), (115, 95),
            (20, 18), (45, 18), (75, 18), (100, 18),
            (20, 40), (45, 40), (75, 40), (100, 40),
            (20, 60), (45, 60), (75, 60), (100, 60),
            (20, 82), (45, 82), (75, 82), (100, 82),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (15, 12), (45, 12), (75, 12), (105, 12),
            (15, 37), (45, 37), (75, 37), (105, 37),
            (15, 62), (45, 62), (75, 62), (105, 62),
            (15, 87), (45, 87), (75, 87), (105, 87),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (20, 20), (70, 20), (110, 20),
            (20, 50), (70, 50), (110, 50),
            (20, 80), (70, 80), (110, 80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5, 50), (115, 50), (60, 5), (60, 95),
            (5, 25), (115, 25), (5, 75), (115, 75),
            (30, 10), (90, 10), (30, 90), (90, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2-12), min(WORLD_W, nx2+13)
                y0, y1 = max(0, ny2-12), min(WORLD_H, ny2+13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 92), (115, 92), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near roads/power for land value boost
    if pop > 150 and step % 7 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- ZONE PLACEMENT (closed-loop, reactive) ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Exclude wire/road spine corridors to protect infrastructure
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Define active zone centers based on current pop (reactive scaling)
        if pop < 80:
            active_centers = [
                (45, 35), (60, 35), (75, 35),
                (45, 50), (60, 50), (75, 50),
                (45, 65), (60, 65), (75, 65),
            ]
        elif pop < 300:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 12 + col * 14
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 800:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 8 + col * 11
                    cy = 6 + row * 11
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 4 + row * 9
                    active_centers.append((cx, cy))

        # Score by distance to nearest active center
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Bonus for clustering near existing zones
        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_bonus = np.full(len(cxs), 0.0)
                for i in range(0, len(zone_xs), max(1, len(zone_xs) // 100)):
                    chunk_xs = zone_xs[i:i+1]
                    chunk_ys = zone_ys[i:i+1]
                    d_chunk = (np.abs(cxs - chunk_xs[0]).astype(float) +
                               np.abs(cys - chunk_ys[0]).astype(float))
                    zone_bonus = np.maximum(zone_bonus, 20.0 - np.minimum(d_chunk, 20.0))
                best_dist = best_dist - zone_bonus * 0.3

        # Road proximity bonus
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            road_dist = np.full(len(cxs), 9999.0)
            stride = max(1, len(road_xs2) // 100)
            for i in range(0, len(road_xs2), stride):
                d = (np.abs(cxs - road_xs2[i]).astype(float) +
                     np.abs(cys - road_ys2[i]).astype(float))
                road_dist = np.minimum(road_dist, d)
            best_dist = best_dist + road_dist * 1.5

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- Fallback: extend road from existing road into powered areas ---
    road_ys3, road_xs3 = np.where(rm)
    if len(road_xs3) > 0:
        sk = (step * 11) % len(road_xs3)
        for off in range(min(len(road_xs3), 300)):
            k = (sk + off * 7) % len(road_xs3)
            rx2, ry2 = int(road_xs3[k]), int(road_ys3[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire from existing wire ---
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

