def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy().astype(bool)
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = (wm | pm).astype(bool)
    near_power = dilate(power_src, 6)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Wire/road corridor definitions (reactive: built from current map state)
    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]
    road_rows = [13, 24, 26, 37, 49, 51, 62, 74, 76, 87]

    # ---- STEP 1: Ensure power plants are spread across the map ----
    # Check 5x5 grid of neighborhoods for nearby plants
    for row in range(5):
        for col in range(5):
            cx = 12 + col * 24
            cy = 10 + row * 20
            x0, x1 = max(0, cx - 14), min(WORLD_W, cx + 15)
            y0, y1 = max(0, cy - 14), min(WORLD_H, cy + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                # Place a coal plant here if empty
                for r in range(1, 15):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = cx + dx, cy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # ---- STEP 2: Extend horizontal wire corridors (reactive: gap-filling) ----
    if step % 6 == 0:
        for wr in wire_rows:
            row_has_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_wire):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_has_wire[wx]):
                    left = bool(row_has_wire[wx - 1]) if wx > 0 else False
                    right = bool(row_has_wire[wx + 1]) if wx < WORLD_W - 1 else False
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # ---- STEP 3: Extend vertical wire corridors ----
    if step % 6 == 1:
        for wc in wire_cols:
            col_has_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_wire):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_has_wire[wy]):
                    up = bool(col_has_wire[wy - 1]) if wy > 0 else False
                    down = bool(col_has_wire[wy + 1]) if wy < WORLD_H - 1 else False
                    if (up or down) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # ---- STEP 4: Build horizontal roads (reactive: fill gaps near power) ----
    if step % 6 == 2:
        for ry in road_rows:
            if not (0 < ry < WORLD_H - 1):
                continue
            row_road = rm[ry, :]
            if int(np.sum(row_road)) >= 110:
                continue
            # First try to extend existing road
            for rx in range(1, WORLD_W - 1):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    left = rx > 0 and bool(rm[ry, rx - 1])
                    right = rx < WORLD_W - 1 and bool(rm[ry, rx + 1])
                    if left or right:
                        return (Tool.ROAD, rx, ry)
            # Then start near power
            for rx in range(1, WORLD_W - 1):
                if bool(em[ry, rx]) and bool(near_power[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # ---- STEP 5: Build vertical connector roads ----
    if step % 6 == 3:
        road_vcols = list(range(6, 119, 8))
        for cx in road_vcols:
            for cy in range(4, 96):
                if bool(em[cy, cx]) and bool(near_power[cy, cx]):
                    up = cy > 0 and bool(rm[cy - 1, cx])
                    down = cy < WORLD_H - 1 and bool(rm[cy + 1, cx])
                    if up or down:
                        return (Tool.ROAD, cx, cy)

    # ---- STEP 6: Connect unpowered zones with wire ----
    if step % 6 == 4:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            # Find wire/plant tiles, extend toward unpowered zone
            pwr_ys, pwr_xs = np.where(power_src)
            if len(pwr_xs) > 0:
                # Pick a random unpowered zone
                zi = (step * 7) % len(zxs)
                tzx, tzy = int(zxs[zi]), int(zys[zi])
                dists = np.abs(pwr_xs - tzx) + np.abs(pwr_ys - tzy)
                best = np.argmin(dists)
                bwx, bwy = int(pwr_xs[best]), int(pwr_ys[best])
                dx = 0 if tzx == bwx else (1 if tzx > bwx else -1)
                dy = 0 if tzy == bwy else (1 if tzy > bwy else -1)
                for nwx, nwy in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nwx, nwy) and bool(em[nwy, nwx]) and not bool(pm[nwy, nwx]):
                        return (Tool.WIRE, nwx, nwy)

    # ---- ZONE PLACEMENT (main action, every step if possible) ----
    cand_mask = (em & near_road & near_power).astype(bool)
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False
    # Don't zone on or adjacent to wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score candidates: prefer near roads and distributed
        # Active hoods based on population
        if pop < 300:
            hoods = [(60, 50)]
        elif pop < 800:
            hoods = [(36, 37), (84, 37), (60, 50), (36, 62), (84, 62)]
        else:
            hoods = [(12 + c * 24, 10 + r * 20) for r in range(5) for c in range(5)]

        best_dist = np.full(len(cxs2), 999999.0)
        for hx, hy in hoods:
            d = (np.abs(cxs2 - hx) + np.abs(cys2 - hy)).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- CIVIC SERVICES based on population ----
    if pop > 80:
        fire_locs = [(fx, fy) for fy in range(8, 95, 14) for fx in range(8, 115, 18)]
        for fsx, fsy in fire_locs:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 250:
        police_locs = [(px2, py2) for py2 in range(10, 92, 16) for px2 in range(10, 112, 22)]
        for psx, psy in police_locs:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        stadiums = [(45, 45), (75, 45), (45, 65), (75, 65),
                    (15, 45), (105, 45), (15, 65), (105, 65)]
        for stx, sty in stadiums:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 100 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    if pop > 800:
        nuke_spots = [(5, 5), (115, 5), (5, 94), (115, 94),
                      (60, 5), (60, 94), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2 - 5), min(WORLD_W, nx2 + 6)
                y0, y1 = max(0, ny2 - 5), min(WORLD_H, ny2 + 6)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(10, 94), (110, 94), (10, 5), (110, 5)]
        for spx, spy in seaports:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 2000:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90)]
        for apx, apy in airports:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend road from existing road near power ----
    rys2, rxs2 = np.where(rm)
    if len(rxs2) > 0:
        k = (step * 11) % len(rxs2)
        for offset2 in range(min(len(rxs2), 60)):
            ki = (k + offset2 * 7) % len(rxs2)
            rx2, ry2 = int(rxs2[ki]), int(rys2[ki])
            for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing power ----
    pwr_ys2, pwr_xs2 = np.where(power_src)
    if len(pwr_xs2) > 0:
        k2 = (step * 13) % len(pwr_xs2)
        for offset3 in range(min(len(pwr_xs2), 50)):
            ki2 = (k2 + offset3 * 5) % len(pwr_xs2)
            wx2, wy2 = int(pwr_xs2[ki2]), int(pwr_ys2[ki2])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spines + flanking roads"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines at y=20, 50, 80
    for wy in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at x=30, 60, 90
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for wy in [20, 50, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    # Roads flanking vertical wire spines (skip wire-row zones)
    for wx in [30, 60, 90]:
        for y in range(1, 99):
            if not any(abs(y - wr) <= 1 for wr in [20, 50, 80]):
                actions.append((Tool.ROAD, wx - 1, y))
                actions.append((Tool.ROAD, wx + 1, y))
    return actions[:500]  # cap to avoid overrun


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    wire_rows = [20, 50, 80]
    wire_cols = [30, 60, 90]

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.30: return Tool.INDUSTRIAL
            if cr < 0.20: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.25: return Tool.INDUSTRIAL
            if cr < 0.25: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30: return Tool.COMMERCIAL
            if rr < 0.45: return Tool.RESIDENTIAL
            if ir < 0.20: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]): return False
        return True

    phase = step % 10

    # PHASE 0: Repair horizontal wire spines
    if phase == 0:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    return (Tool.WIRE, wx, wr)

    # PHASE 1: Repair vertical wire spines
    if phase == 1:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    return (Tool.WIRE, wc, wy)

    # PHASE 2: Repair roads flanking wire rows
    if phase == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H): continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # PHASE 3: Repair roads flanking vertical wire spines
    if phase == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W): continue
                for ry in range(1, WORLD_H - 1):
                    skip = any(abs(ry - wr) <= 1 for wr in wire_rows)
                    if not skip and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # PHASE 4: Add secondary roads for better coverage
    if phase == 4:
        secondary_rows = [10, 30, 40, 60, 70, 90]
        secondary_cols = [15, 45, 75, 105]
        for rr_y in secondary_rows:
            if not (0 < rr_y < WORLD_H): continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr_y, rx]) and not bool(pm[rr_y, rx]) and bool(near_power[rr_y, rx]):
                    return (Tool.ROAD, rx, rr_y)
        for rc_x in secondary_cols:
            if not (0 < rc_x < WORLD_W): continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc_x]) and not bool(pm[ry, rc_x]) and bool(near_power[ry, rc_x]):
                    return (Tool.ROAD, rc_x, ry)

    # PHASE 5: Add coal plants where power coverage thin
    if phase == 5:
        for py in range(15, WORLD_H - 5, 30):
            for px in range(15, WORLD_W - 5, 30):
                x0, x1 = max(0, px - 14), min(WORLD_W, px + 15)
                y0, y1 = max(0, py - 14), min(WORLD_H, py + 15)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    for r in range(10):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # PHASE 6: Wire unpowered zones to grid
    if phase == 6:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # PHASE 7: Road to unroaded zones
    if phase == 7:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # PHASE 8: Upgrade to nuclear when pop allows
    if phase == 8 and pop > 1000:
        nuke_spots = [
            (10, 50), (110, 50), (60, 10), (60, 90),
            (10, 20), (110, 20), (10, 80), (110, 80),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # PHASE 9: Extend wire toward uncovered areas
    if phase == 9:
        uncov = near_road & ~near_power & em
        uys, uxs = np.where(uncov)
        if len(uxs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 23) % len(uxs)
                tx, ty = int(uxs[idx]), int(uys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- CIVIC SERVICES ---
    if pop > 20:
        fire_spots = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 35), (45, 35), (75, 35), (105, 35),
            (15, 65), (45, 65), (75, 65), (105, 65),
            (15, 90), (45, 90), (75, 90), (105, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (25, 15), (55, 15), (85, 15), (115, 15),
            (25, 45), (55, 45), (85, 45), (115, 45),
            (25, 65), (55, 65), (85, 65), (115, 65),
            (10, 30), (10, 70), (110, 30), (110, 70),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadium_spots = [(25, 25), (95, 25), (25, 75), (95, 75), (60, 50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(5, 95), (115, 95), (5, 5), (115, 5), (60, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 6 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- ZONE PLACEMENT (closed-loop core) ---
    cand_mask = em & near_road & near_power
    # Protect borders and wire corridors
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):min(WORLD_H, wr + 2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):min(WORLD_W, wc + 2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Build active centers based on population
        if pop < 200:
            active_centers = [
                (60, 50), (45, 50), (75, 50), (60, 38), (60, 62),
                (45, 38), (75, 38), (45, 62), (75, 62),
                (30, 50), (90, 50), (30, 30), (90, 30), (30, 70), (90, 70),
            ]
        elif pop < 1000:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 8 + col * 15
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: add power plant near uncovered active zones
    if pop < 500:
        for cx, cy in [(60, 50), (30, 50), (90, 50), (60, 25), (60, 75)]:
            x0, x1 = max(0, cx - 14), min(WORLD_W, cx + 15)
            y0, y1 = max(0, cy - 14), min(WORLD_H, cy + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx, ny = cx + dx, cy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire cross and flanking roads."""
    actions = []
    # Two power plants, one left-center, one right-center
    for cx, cy in [(40, 50), (80, 50)]:
        actions.append((Tool.COALPOWER, cx, cy))
        for dx in range(-8, 9):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        for dx in range(-8, 9):
            actions.append((Tool.ROAD, cx + dx, cy - 3))
            actions.append((Tool.ROAD, cx + dx, cy + 3))
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, cx - 3, cy + dy))
            actions.append((Tool.ROAD, cx + 3, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Active neighborhood anchors, scaled with population
    all_anchors = []
    for ax in [20, 40, 60, 80, 100]:
        for ay in [20, 35, 50, 65, 80]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 300:   return 6
        if pop < 500:   return 9
        if pop < 800:   return 12
        if pop < 1200:  return 16
        if pop < 2000:  return 20
        return len(all_anchors)

    n_active = min(num_active(), len(all_anchors))
    active_anchors = all_anchors[:n_active]

    # ---- PHASE 1: ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 10); y1 = min(WORLD_H, ay + 11)
        x0 = max(0, ax - 10); x1 = min(WORLD_W, ax + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant and funds > 500:
            if ib(ax, ay) and bool(em[ay, ax]):
                return (Tool.COALPOWER, ax, ay)
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES - extend toward each active anchor ----
    wire_half = min(20, 6 + pop // 12)
    vert_half = min(14, 4 + pop // 18)

    for (ax, ay) in active_anchors:
        # Check if anchor already has wire/power nearby
        wx0, wx1 = max(0, ax - 3), min(WORLD_W, ax + 4)
        wy0, wy1 = max(0, ay - 3), min(WORLD_H, ay + 4)
        has_wire = bool(np.any(wm[wy0:wy1, wx0:wx1])) or bool(np.any(pm[wy0:wy1, wx0:wx1]))
        if has_wire:
            continue
        # Extend wire along column at ax toward ay
        col_wires = [r for r in range(WORLD_H) if ib(ax, r) and (bool(wm[r, ax]) or bool(pm[r, ax]))]
        if col_wires:
            if ay > max(col_wires):
                nr = max(col_wires) + 1
                if ib(ax, nr) and bool(em[nr, ax]):
                    return (Tool.WIRE, ax, nr)
            elif ay < min(col_wires):
                nr = min(col_wires) - 1
                if ib(ax, nr) and bool(em[nr, ax]):
                    return (Tool.WIRE, ax, nr)
        # Extend wire along row at ay toward ax
        row_wires = [c for c in range(WORLD_W) if ib(c, ay) and (bool(wm[ay, c]) or bool(pm[ay, c]))]
        if row_wires:
            if ax > max(row_wires):
                nc = max(row_wires) + 1
                if ib(nc, ay) and bool(em[ay, nc]):
                    return (Tool.WIRE, nc, ay)
            elif ax < min(row_wires):
                nc = min(row_wires) - 1
                if ib(nc, ay) and bool(em[ay, nc]):
                    return (Tool.WIRE, nc, ay)

    # ---- PHASE 3: Extend horizontal/vertical wire spines ----
    for (ax, ay) in active_anchors:
        # Horizontal wire spine
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay): continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]): continue
            if not bool(em[ay, cx]): continue
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    return (Tool.WIRE, cx, ay)

    for (ax, ay) in active_anchors:
        # Vertical wire spine
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy): continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]): continue
            if not bool(em[cy, ax]): continue
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    return (Tool.WIRE, ax, cy)

    # ---- PHASE 4: Connect anchors with wires (horizontal neighbors) ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax2, ay2) for (ax2, ay2) in active_anchors if ax2 == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy - 1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy + 1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax2, ay2) for (ax2, ay2) in active_anchors if ay2 == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx - 1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx + 1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- PHASE 5: ROADS flanking wire spines ----
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-3, 3]:
            road_y = ay + road_y_off
            if not ib(ax, road_y): continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y): continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx + ddx, road_y) and bool(rm[road_y, cx + ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y - 1) and (bool(wm[road_y-1, cx]) or bool(pm[road_y-1, cx]))) or \
                               (ib(cx, road_y + 1) and (bool(wm[road_y+1, cx]) or bool(pm[road_y+1, cx])))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-3, 3]:
            road_x = ax + road_x_off
            if not ib(road_x, ay): continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy): continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy + ddy) and bool(rm[cy + ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x - 1, cy) and (bool(wm[cy, road_x-1]) or bool(pm[cy, road_x-1]))) or \
                               (ib(road_x + 1, cy) and (bool(wm[cy, road_x+1]) or bool(pm[cy, road_x+1])))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 6: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)

        # Zone clustering bonus
        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: EXTEND ROADS from existing network near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if (ib(nx2, ny2) and bool(em[ny2, nx2]) and
                        not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2])):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 40:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W - 4, 22)
                      for fy in range(10, WORLD_H - 4, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W - 4, 24)
                        for py2 in range(15, WORLD_H - 4, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(30, 25), (60, 15), (90, 25),
                    (20, 50), (100, 50),
                    (30, 75), (60, 85), (90, 75)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 300 and step % 3 == 0:
        park_candidates = np.where(em & nbr_road & nbr_wire)
        park_ys_arr, park_xs_arr = park_candidates
        if len(park_xs_arr) > 0:
            idx = (step * 17) % len(park_xs_arr)
            py2, px2 = int(park_ys_arr[idx]), int(park_xs_arr[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 1000 and funds > 5000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 8), (60, 92), (8, 50), (112, 50),
            (40, 25), (80, 25), (40, 75), (80, 75),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 6), min(WORLD_W, npx + 7)
            y0b, y1b = max(0, npy - 6), min(WORLD_H, npy + 7)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 700:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1500:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 90)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from existing wire/plant ----
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants + wire spines + flanking roads"""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines at x=30 and x=90
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 90, y))
    # Roads flanking horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    # Additional horizontal wires at y=25 and y=75
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 75))
    # Roads flanking those
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 300:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 1000:
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.20:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 8

    # === PHASE 0: Ensure power plants across map ===
    if phase == 0:
        plant_positions = []
        for py in range(15, WORLD_H - 5, 20):
            for px in range(15, WORLD_W - 5, 20):
                plant_positions.append((px, py))
        for px, py in plant_positions:
            x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
            y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
            if not np.any(pm[y0:y1, x0:x1]):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # === PHASE 1: Extend wire to unpowered zones and regions ===
    if phase == 1:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                best_dist = 999999
                best_zone = None
                sample = min(len(uz_xs), 30)
                for i in range(sample):
                    idx = (step * 17 + i * 7) % len(uz_xs)
                    tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    d = int(np.min(dists))
                    if d < best_dist:
                        best_dist = d
                        best_zone = (tx, ty)
                if best_zone is not None:
                    tx, ty = best_zone
                    dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                    best_wi = np.argmin(dists)
                    bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                    dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                    dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                    for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                        if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                            return (Tool.WIRE, nx2, ny2)

        # Extend wire toward unpowered empty regions
        adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(power_src)
            if dy2 == -1:   shifted[:-1, :] = power_src[1:, :]
            elif dy2 == 1:  shifted[1:, :] = power_src[:-1, :]
            elif dx2 == -1: shifted[:, :-1] = power_src[:, 1:]
            elif dx2 == 1:  shifted[:, 1:] = power_src[:, :-1]
            adj_to_power |= shifted

        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False
        wire_cand[WORLD_H - 2:, :] = False
        wire_cand[:, 0:2] = False
        wire_cand[:, WORLD_W - 2:] = False

        wys, wxs = np.where(wire_cand)
        if len(wxs) > 0:
            unpowered_empty = em & ~near_power & ~zone_tiles
            upys, upxs = np.where(unpowered_empty)
            if len(upxs) > 0:
                best_dist2 = 1e9
                best_k = 0
                sample_indices = np.linspace(0, len(upxs) - 1, min(30, len(upxs)), dtype=int)
                for i in range(min(len(wxs), 300)):
                    cx, cy = int(wxs[i]), int(wys[i])
                    d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_indices)
                    if d < best_dist2:
                        best_dist2 = d
                        best_k = i
                return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # === PHASE 2: Build road grid ===
    if phase == 2:
        # Connect unroaded zones to road
        unroaded = zone_tiles & ~near_road
        uz_ys2, uz_xs2 = np.where(unroaded)
        if len(uz_xs2) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs2)
                tx, ty = int(uz_xs2[idx]), int(uz_ys2[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

        # Extend road grid every 6 tiles in powered areas
        road_grid_targets = []
        for gy in range(6, 97, 6):
            for gx in range(6, 115, 6):
                if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid_targets.append((gx, gy))

        if road_grid_targets:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1:   shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1:  shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1:  shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted

            road_cand = em & adj_to_road & near_power & ~zone_tiles
            road_cand[0:2, :] = False
            road_cand[WORLD_H - 2:, :] = False
            road_cand[:, 0:2] = False
            road_cand[:, WORLD_W - 2:] = False

            rys2, rxs2 = np.where(road_cand)
            if len(rxs2) > 0:
                best_dist3 = 1e9
                best_k3 = 0
                targets_sample = road_grid_targets[:30]
                for i in range(min(len(rxs2), 400)):
                    cx, cy = int(rxs2[i]), int(rys2[i])
                    d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                    if d < best_dist3:
                        best_dist3 = d
                        best_k3 = i
                return (Tool.ROAD, int(rxs2[best_k3]), int(rys2[best_k3]))
            else:
                for gx, gy in road_grid_targets[:10]:
                    if bool(em[gy, gx]):
                        return (Tool.ROAD, gx, gy)

    # === PHASE 3: Civic services and upgrades ===
    if phase == 3:
        if pop > 20:
            fire_grid = [(fx, fy) for fy in range(10, 95, 15) for fx in range(10, 115, 15)]
            for fsx, fsy in fire_grid:
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

        if pop > 100:
            police_grid = [(px2, py2) for py2 in range(15, 90, 18) for px2 in range(15, 110, 18)]
            for psx, psy in police_grid:
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

        if pop > 300 and step % 8 == 3:
            park_cands = em & near_road & near_power & ~zone_tiles
            pys3, pxs3 = np.where(park_cands)
            if len(pxs3) > 0:
                idx = (step * 31 + pop) % len(pxs3)
                return (Tool.PARK, int(pxs3[idx]), int(pys3[idx]))

        if pop > 500:
            stadium_locs = [(30, 25), (90, 25), (30, 75), (90, 75),
                            (60, 50), (15, 50), (105, 50), (60, 15), (60, 85)]
            for stx, sty in stadium_locs:
                if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

        if pop > 800:
            # Upgrade to nuclear power in regions that have only coal
            nuke_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                         (60, 10), (60, 90), (10, 50), (110, 50),
                         (35, 15), (85, 15), (35, 85), (85, 85)]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                    y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1500:
            airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
            for apx, apy in airport_locs:
                if ib(apx, apy) and bool(em[apy, apx]):
                    return (Tool.AIRPORT, apx, apy)

        if pop > 2000:
            seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 94)]
            for spx, spy in seaport_locs:
                if ib(spx, spy) and bool(em[spy, spx]):
                    return (Tool.SEAPORT, spx, spy)

    # === PHASES 4-7: Zone placement (main loop, multiple phases devoted to this) ===
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W - 4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        road_ys3, road_xs3 = np.where(rm)
        if len(road_xs3) > 0:
            stride2 = max(1, len(road_xs3) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs3), stride2):
                d = (np.abs(cxs_arr - road_xs3[i]) + np.abs(cys_arr - road_ys3[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 1:
            zone_ys2, zone_xs2 = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs2) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs2), stride3):
                d = (np.abs(cxs_arr - zone_xs2[i]) + np.abs(cys_arr - zone_ys2[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Prefer close to road, prefer spreading out from existing zones
        score = road_dist * 1.0 + np.maximum(0, 8 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)
        tool = pick_tool()

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # === FALLBACK: extend road from existing road into powered area ===
    road_ys4, road_xs4 = np.where(rm)
    if len(road_xs4) > 0:
        sk = (step * 11) % len(road_xs4)
        for off2 in range(min(len(road_xs4), 100)):
            k = (sk + off2 * 7) % len(road_xs4)
            rx2, ry2 = int(road_xs4[k]), int(road_ys4[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === FALLBACK: extend wire from existing wire ===
    wire_ys5, wire_xs5 = np.where(wm)
    if len(wire_xs5) > 0:
        sk2 = (step * 13) % len(wire_xs5)
        for off3 in range(min(len(wire_xs5), 60)):
            k = (sk2 + off3 * 5) % len(wire_xs5)
            wx2, wy2 = int(wire_xs5[k]), int(wire_ys5[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + dense wire grid + flanking roads."""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spines at rows 25, 50, 75
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 25))
        actions.append((Tool.WIRE, x, 50))
        actions.append((Tool.WIRE, x, 75))
    # Vertical wire spines at cols 30, 60, 90
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 90, y))
    # Roads flanking wire rows
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 24))
        actions.append((Tool.ROAD, x, 26))
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
        actions.append((Tool.ROAD, x, 74))
        actions.append((Tool.ROAD, x, 76))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    wire_rows = [25, 50, 75]
    wire_cols = [30, 60, 90]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    power_src = wm | pm
    near_power = dilate(power_src, 5)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- PHASE 0: Spread coal plants across map ---
    if step % 5 == 0:
        plant_grid_xs = list(range(10, WORLD_W - 5, 20))
        plant_grid_ys = list(range(10, WORLD_H - 5, 20))
        for ppy in plant_grid_ys:
            for ppx in plant_grid_xs:
                if not ib(ppx, ppy):
                    continue
                x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
                y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
                if not np.any(pm[y0:y1, x0:x1]):
                    if bool(em[ppy, ppx]):
                        return (Tool.COALPOWER, ppx, ppy)
                    # Search nearby empty spot
                    for r in range(1, 8):
                        for dy in range(-r, r+1):
                            for dx in range(-r, r+1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx, ny = ppx+dx, ppy+dy
                                    if ib(nx, ny) and bool(em[ny, nx]):
                                        return (Tool.COALPOWER, nx, ny)

    # --- PHASE 1: Fill wire corridor gaps (reactive) ---
    if step % 10 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # --- PHASE 2: Wire toward unpowered zones ---
    if step % 10 == 2:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- PHASE 3: Fill road gaps adjacent to wire rows ---
    if step % 10 == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1]))
                        if has_wire and (adj_road or rx == 1):
                            return (Tool.ROAD, rx, ry)

    # --- PHASE 4: Fill road gaps adjacent to wire cols ---
    if step % 10 == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx]))
                        if has_wire and (adj_road or ry == 1):
                            return (Tool.ROAD, rcx, ry)

    # --- PHASE 5: Extra road rows for denser coverage ---
    if step % 10 == 5:
        extra_road_rows = [10, 15, 37, 40, 62, 85, 90]
        for mr in extra_road_rows:
            if mr <= 0 or mr >= WORLD_H - 1:
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                    adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mr)

    # --- PHASE 6: Extra road cols ---
    if step % 10 == 6:
        extra_road_cols = [15, 45, 75, 105]
        for mc in extra_road_cols:
            if mc <= 0 or mc >= WORLD_W - 1:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                    adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mc]))
                    if adj:
                        return (Tool.ROAD, mc, ry)

    # --- PHASE 7: Extend road from existing road into powered empty areas ---
    if step % 10 == 7:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- PHASE 8: Wire unpowered roads ---
    if step % 10 == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = int(np.argmin(dists))
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- CIVIC BUILDINGS (population-gated, reactive) ---
    if pop > 10:
        fire_spots = [
            (5,5),(60,5),(115,5),(5,30),(60,30),(115,30),
            (5,50),(115,50),(5,70),(60,70),(115,70),
            (5,95),(60,95),(115,95),
            (20,18),(45,18),(75,18),(100,18),
            (20,40),(45,40),(75,40),(100,40),
            (20,60),(45,60),(75,60),(100,60),
            (20,82),(45,82),(75,82),(100,82),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (15,12),(45,12),(75,12),(105,12),
            (15,37),(45,37),(75,37),(105,37),
            (15,62),(45,62),(75,62),(105,62),
            (15,87),(45,87),(75,87),(105,87),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (20,20),(70,20),(110,20),
            (20,50),(70,50),(110,50),
            (20,80),(70,80),(110,80),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
            (30,10),(90,10),(30,90),(90,90),
            (50,50),(70,50),(60,30),(60,70),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                x0, x1 = max(0, nx2-12), min(WORLD_W, nx2+13)
                y0, y1 = max(0, ny2-12), min(WORLD_H, ny2+13)
                if not np.any(pm[y0:y1, x0:x1]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5,92),(115,92),(5,5),(115,5),(60,5),(60,95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(50,5),(70,5),(50,92),(70,92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 7 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        for wr in wire_rows:
            park_cands[max(0,wr-1):min(WORLD_H,wr+2), :] = False
        for wc in wire_cols:
            park_cands[:, max(0,wc-1):min(WORLD_W,wc+2)] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- ZONE PLACEMENT (closed-loop, reactive) ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):min(WORLD_W,wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Reactive active centers scaled by population
        if pop < 80:
            active_centers = [
                (45,35),(60,35),(75,35),
                (45,50),(60,50),(75,50),
                (45,65),(60,65),(75,65),
            ]
        elif pop < 300:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    active_centers.append((12 + col*14, 10 + row*14))
        elif pop < 800:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    active_centers.append((8 + col*11, 6 + row*11))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    active_centers.append((5 + col*10, 4 + row*9))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Clustering bonus near existing zones
        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            if len(zone_xs) > 0:
                zone_bonus = np.zeros(len(cxs))
                stride = max(1, len(zone_xs) // 80)
                for i in range(0, len(zone_xs), stride):
                    d_chunk = (np.abs(cxs - zone_xs[i]).astype(float) +
                               np.abs(cys - zone_ys[i]).astype(float))
                    zone_bonus = np.maximum(zone_bonus, 20.0 - np.minimum(d_chunk, 20.0))
                best_dist = best_dist - zone_bonus * 0.3

        # Road proximity bonus
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            road_dist = np.full(len(cxs), 9999.0)
            stride = max(1, len(road_xs2) // 80)
            for i in range(0, len(road_xs2), stride):
                d = (np.abs(cxs - road_xs2[i]).astype(float) +
                     np.abs(cys - road_ys2[i]).astype(float))
                road_dist = np.minimum(road_dist, d)
            best_dist = best_dist + road_dist * 1.5

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- Fallback: extend road into powered areas ---
    road_ys3, road_xs3 = np.where(rm)
    if len(road_xs3) > 0:
        sk = (step * 11) % len(road_xs3)
        for off in range(min(len(road_xs3), 300)):
            k = (sk + off * 7) % len(road_xs3)
            rx2, ry2 = int(road_xs3[k]), int(road_ys3[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- Fallback: extend wire from existing wire ---
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- Fallback: new plant near unpowered neighborhood ---
    all_hoods = [(cx, cy) for cy in range(6, 100, 9) for cx in range(7, 120, 12)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 3 coal plants in a triangle + wire/road spine"""
    actions = []
    # Central power plants
    for px, py in [(30, 50), (90, 50), (60, 20), (60, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at key rows
    for wy in [20, 35, 50, 65, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at key cols
    for wx in [20, 40, 60, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire rows
    for wy in [20, 35, 50, 65, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    # Roads flanking vertical wire cols
    for wx in [20, 40, 60, 80, 100]:
        for y in range(1, 99):
            actions.append((Tool.ROAD, wx - 1, y))
            actions.append((Tool.ROAD, wx + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 40% res, 35% com, 25% ind for higher pop density
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [20, 40, 60, 80, 100]

    # Grid of neighborhoods between wire rows/cols
    # Place zones in the "blocks" between wires
    nh_positions = []
    for row_i, wr in enumerate([27, 42, 57, 72]):  # midpoints between wire rows
        for col_i, wc in enumerate([29, 49, 69, 89]):  # midpoints between wire cols
            nh_positions.append((wc, wr))
    # Extra outer neighborhoods
    for cx in [10, 30, 50, 70, 90, 110]:
        for cy in [10, 87]:
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 100:
            return [(60, 50), (40, 50), (80, 50), (60, 35), (60, 65)]
        elif pop < 500:
            return nh_positions[:12]
        elif pop < 1500:
            return nh_positions[:20]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 14

    # Dynamic: add more power plants if unpowered zones exist
    if step % 7 == 0:
        zone_ys, zone_xs = np.where(zone_tiles & ~near_power)
        if len(zone_xs) > 0:
            idx = (step * 13) % len(zone_xs)
            tx, ty = int(zone_xs[idx]), int(zone_ys[idx])
            # Find empty spot near unpowered zone
            for r in range(3, 20):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = tx + dx, ty + dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Add diagonal cross-roads between neighborhoods for better connectivity
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx-1])) or (rx < WORLD_W-1 and bool(rm[mid_y, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire cols at midpoints
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry-1, mid_x])) or (ry < WORLD_H-1 and bool(rm[ry+1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # Extend road from existing roads (closed-loop: follow what exists)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase in (8, 9):
        # Civic services - react to population thresholds
        if pop > 20:
            fire_spots = [(10,10),(50,10),(90,10),(110,10),
                          (10,30),(50,30),(90,30),(110,30),
                          (10,55),(50,55),(90,55),(110,55),
                          (10,75),(50,75),(90,75),(110,75),
                          (10,90),(50,90),(90,90),(110,90)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 150:
            police_spots = [(25,15),(65,15),(105,15),
                            (25,45),(65,45),(105,45),
                            (25,70),(65,70),(105,70),
                            (25,90),(65,90),(105,90)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadium_spots = [(35,25),(85,25),(35,70),(85,70),(60,47)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 700:
            nuke_spots = [(5,50),(113,50),(60,5),(60,93),(5,5),(113,93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            seaports = [(5,90),(110,90)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1800:
            airports = [(5,5),(113,5),(5,90),(113,90)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase in (10, 11):
        # Parks to boost land value near dense zones
        if pop > 100:
            park_mask = em & near_road & near_power
            # Prefer spots near high zone density
            zone_density = dilate(zone_tiles.astype(float) > 0, 4)
            park_mask &= zone_density
            pys, pxs = np.where(park_mask)
            if len(pxs) > 0:
                idx = (step * 23 + pop * 7) % len(pxs)
                return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (closed-loop main action) ----
    cand_mask = em & near_road & near_power
    # Keep away from borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep away from wire rows (don't zone on wires)
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score by proximity to active hoods
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use pop-dependent offset for variety
        offset = (step * 11 + pop * 5) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Fallback: wire toward unpowered hoods
    unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
    if unpowered:
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            tx, ty = unpowered[0]
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Fallback: extend any wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: place first coal plant + wire spine + flanking roads at center."""
    actions = []
    # Primary plant at center
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire spine vertically from plant
    for dy in range(-5, 6):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Wire horizontally
    for dx in range(-3, 4):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Flanking roads
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    # ---- NEIGHBORHOOD PLAN ----
    # 4 columns x 3 rows = 12 neighborhoods
    # Each: (anchor_x, anchor_y, wire_col, road_left, road_right, idx)
    neighborhoods = []
    for col_i, cx in enumerate([20, 45, 75, 100]):
        for row_i, cy in enumerate([20, 50, 80]):
            neighborhoods.append((cx, cy, cx, cx - 1, cx + 1, col_i * 3 + row_i))

    def num_active():
        if pop < 100:   return 2
        if pop < 300:   return 3
        if pop < 600:   return 4
        if pop < 1000:  return 6
        if pop < 1800:  return 8
        if pop < 3000:  return 10
        return 12

    active = neighborhoods[:num_active()]

    # ---- BUILD NEIGHBOR PROXIMITY MASKS (for wire and road) ----
    def expand_mask(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-radius, radius + 1):
            for dx in range(-radius, radius + 1):
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_road = expand_mask(rm, 2)
    nbr_wire = expand_mask(wm | pm, 5)

    # ---- 1. ENSURE POWER PLANTS ----
    for (px, py, wc, rl, rr, idx) in active:
        has_plant = bool(np.any(pm[max(0,py-5):min(WORLD_H,py+6), max(0,px-5):min(WORLD_W,px+6)]))
        if not has_plant:
            # Place at anchor if empty
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Search nearby
            for r in range(1, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. WIRE SPINES: grow wire vertically from each plant ----
    wire_ext = min(22, 10 + pop // 80)
    for (px, py, wc, rl, rr, idx) in active:
        spine_top = max(2, py - wire_ext)
        spine_bot = min(WORLD_H - 3, py + wire_ext)

        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]

        if not wire_rows:
            # Seed wire next to plant
            for dy in range(-1, 2):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE CROSS-CONNECTIONS ----
    # Connect wire spines in same row with horizontal wires
    row_groups = {}
    for (px, py, wc, rl, rr, idx) in active:
        row_groups.setdefault(py, []).append(wc)

    for row_y, wcs in row_groups.items():
        if len(wcs) < 2:
            continue
        wcs_sorted = sorted(wcs)
        for i in range(len(wcs_sorted) - 1):
            wc1, wc2 = wcs_sorted[i], wcs_sorted[i + 1]
            # Only connect if both spines reach this row
            if not bool(wm[row_y, wc1]) and not bool(pm[row_y, wc1]):
                continue
            if not bool(wm[row_y, wc2]) and not bool(pm[row_y, wc2]):
                continue
            for cx in range(wc1 + 1, wc2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- 4. FLANKING ROADS along wire spines ----
    for (px, py, wc, rl, rr, idx) in active:
        wire_rows = sorted([r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])])
        if not wire_rows:
            continue
        # Use step to vary which rows we fill roads
        cycle = (step + idx * 11) % len(wire_rows)
        for offset in range(min(len(wire_rows), 6)):
            wr = wire_rows[(cycle + offset) % len(wire_rows)]
            for road_x in [rl, rr]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- 5. HORIZONTAL CONNECTING ROADS ----
    # Add cross roads connecting neighborhoods at their center rows
    for (px, py, wc, rl, rr, idx) in active:
        for dx in range(-10, 11):
            rx = wc + dx
            if not ib(rx, py):
                continue
            if bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                # Place only if adjacent to existing road or wire
                near = any(
                    ib(rx + d, py) and (bool(rm[py, rx + d]) or bool(wm[py, rx + d]) or bool(pm[py, rx + d]))
                    for d in [-1, 1]
                )
                if near:
                    return (Tool.ROAD, rx, py)

    # ---- 6. ZONE PLACEMENT ----
    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        # Zone is 3x3; center at zx,zy means cells from zx-1..zx+1, zy-1..zy+1
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Candidate cells: empty, near road AND near wire/plant
    cand_mask = em & nbr_road & nbr_wire
    # Keep borders clear
    cand_mask[:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by closeness to active wire columns
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr, idx) in active:
            d = np.abs(cxs.astype(float) - wc) * 1.0 + np.abs(cys.astype(float) - py) * 1.5
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 13) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # ---- 7. ROAD EXTENSION near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k = (step * 17) % max(len(road_xs), 1)
        for offset in range(min(len(road_xs), 50)):
            k = (step_k + offset * 9) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- 8. CIVIC SERVICES ----
    if pop > 150:
        firestations = [
            (30, 20), (60, 20), (90, 20),
            (30, 50), (90, 50),
            (30, 80), (60, 80), (90, 80),
        ]
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        polices = [
            (25, 35), (55, 35), (85, 35),
            (25, 65), (55, 65), (85, 65),
        ]
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadiums = [(40, 10), (80, 10), (40, 90), (80, 90)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        seaports = [(10, 90), (110, 90)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        # Add nuclear plants near existing wire clusters for more power
        wire_ys2, wire_xs2 = np.where(wm)
        if len(wire_xs2) > 0:
            k = (step * 7) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(3, 0), (-3, 0), (0, 3), (0, -3)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    # ---- 9. WIRE EXTENSION FALLBACK ----
    wire_ys, wire_xs = np.where(wm)
    if len(wire_xs) > 0:
        step_k2 = (step * 19) % max(len(wire_xs), 1)
        for offset in range(min(len(wire_xs), 40)):
            k = (step_k2 + offset * 7) % len(wire_xs)
            wx, wy = int(wire_xs[k]), int(wire_ys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

