def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    def adj_mask(mask):
        """One-step dilation (4-connected adjacency)."""
        r = np.zeros_like(mask)
        r[1:, :] |= mask[:-1, :]
        r[:-1, :] |= mask[1:, :]
        r[:, 1:] |= mask[:, :-1]
        r[:, :-1] |= mask[:, 1:]
        return r

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # -- PHASE 1: Ensure power plants on a grid --
    plant_grid = []
    for py in range(18, 90, 20):
        for px in range(15, 110, 20):
            plant_grid.append((px, py))

    # Place a plant if none nearby
    for px, py in plant_grid:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
        y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # -- PHASE 2: Extend wire BFS-style from existing power to uncovered grid zones --
    adj_power = adj_mask(power_src)
    wire_cand = em & ~rm & ~zone_tiles & adj_power
    # Don't wire over edges
    wire_cand[0:3, :] = False; wire_cand[97:, :] = False
    wire_cand[:, 0:3] = False; wire_cand[:, 117:] = False

    wys, wxs = np.where(wire_cand)

    if len(wxs) > 0:
        # Find plants not yet near power
        uncovered_plants = [(px, py) for px, py in plant_grid
                            if ib(px, py) and np.any(pm[max(0,py-2):min(WORLD_H,py+3),
                                                        max(0,px-2):min(WORLD_W,px+3)])
                            and not bool(near_power[py, px])]
        # Find road segments not yet powered
        unpowered_roads = rm & ~near_power
        ur_ys, ur_xs = np.where(unpowered_roads)

        targets = [(px, py) for px, py in uncovered_plants]
        if len(ur_xs) > 0:
            stride = max(1, len(ur_xs) // 20)
            for i in range(0, len(ur_xs), stride):
                targets.append((int(ur_xs[i]), int(ur_ys[i])))

        if targets:
            best_dist = 1e9
            best_k = 0
            for i in range(len(wxs)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - tx) + abs(cy - ty) for tx, ty in targets[:30])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # -- PHASE 3: Build road grid in powered areas --
    # Denser grid: roads every 5 tiles
    road_rows = list(range(8, 95, 5))
    road_cols = list(range(8, 115, 5))

    road_targets = []
    for gy in road_rows:
        for gx in road_cols:
            if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and not bool(zone_tiles[gy, gx]):
                road_targets.append((gx, gy))

    if road_targets:
        adj_road = adj_mask(rm)
        road_cand = em & adj_road & near_power & ~zone_tiles & ~wm & ~pm
        road_cand[0:3, :] = False; road_cand[97:, :] = False
        road_cand[:, 0:3] = False; road_cand[:, 117:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            sample_targets = road_targets[:40]
            for i in range(len(rxs2)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in sample_targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in road_targets[:10]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # -- PHASE 4: Zone placement --
    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if rm[nr, nc] or wm[nr, nc] or pm[nr, nc]:
                    return False
        return True

    # Zone candidates: near road AND near power, in empty cells
    zone_cand = em & near_road & near_power
    zone_cand[0:5, :] = False; zone_cand[95:, :] = False
    zone_cand[:, 0:5] = False; zone_cand[:, 115:] = False

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs_arr))

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Prefer close to road, some spread from existing zones
            score = road_dist * 1.5 - zone_dist * 0.2
        else:
            score = road_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 5) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # -- PHASE 5: Civic services based on population --
    if pop > 80:
        for fy in range(13, 90, 10):
            for fx in range(13, 110, 10):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(near_power[fy, fx]) and bool(near_road[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for py2 in range(18, 85, 12):
            for px2 in range(18, 105, 12):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(near_power[py2, px2]) and bool(near_road[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 500:
        for py3 in range(10, 90, 8):
            for px3 in range(10, 110, 8):
                if ib(px3, py3) and bool(em[py3, px3]) and bool(near_road[py3, px3]):
                    return (Tool.PARK, px3, py3)

    if pop > 700:
        for stx, sty in [(25, 25), (85, 25), (25, 75), (85, 75), (55, 50), (45, 35), (75, 65)]:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]) and bool(near_road[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75), (40, 50), (80, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        for apx, apy in [(55, 8), (75, 8), (8, 45), (110, 45), (60, 90)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 3000:
        for spx, spy in [(10, 50), (110, 50), (60, 8), (60, 91)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # -- Fallback: wire from plant outward --
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px4, py4 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx4, ny4 = px4 + dx4, py4 + dy4
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.WIRE, nx4, ny4)

    # -- Fallback: road from plant --
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px5, py5 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx5, dy5 in [(5, 0), (-5, 0), (0, 5), (0, -5), (3, 3), (-3, -3)]:
            nx5, ny5 = px5 + dx5, py5 + dy5
            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                return (Tool.ROAD, nx5, ny5)

    return None

def init(obs, state):
    """Bootstrap: three coal plants in a triangle + wire spines + roads."""
    actions = []
    # Three power centers: top-left, top-right, bottom-center
    centers = [(30, 25), (90, 25), (60, 70)]
    for (cx, cy) in centers:
        actions.append((Tool.COALPOWER, cx, cy))
        # Horizontal wire spine
        for dx in range(-6, 7):
            if dx != 0:
                actions.append((Tool.WIRE, cx + dx, cy))
        # Vertical wire spine
        for dy in range(-6, 7):
            if dy != 0:
                actions.append((Tool.WIRE, cx, cy + dy))
        # Roads flanking wire spines
        for dy in range(-5, 6):
            actions.append((Tool.ROAD, cx - 2, cy + dy))
            actions.append((Tool.ROAD, cx + 2, cy + dy))
        for dx in range(-5, 6):
            actions.append((Tool.ROAD, cx + dx, cy - 2))
            actions.append((Tool.ROAD, cx + dx, cy + 2))
    # Wire connecting the three centers horizontally
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 25))
    # Wire connecting top-center to bottom-center
    for y in range(26, 70):
        actions.append((Tool.WIRE, 60, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Precompute neighbor masks
    power_src = wm | pm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === REACTIVE: fix unpowered zones ===
    unpowered_zones = zone_tiles & ~nbr_power
    if np.any(unpowered_zones):
        uzys, uzxs = np.where(unpowered_zones)
        if np.any(wm):
            wys_arr, wxs_arr = np.where(wm)
            idx = (step * 7) % len(uzxs)
            tz, ty = int(uzxs[idx]), int(uzys[idx])
            dists = np.abs(wxs_arr - tz) + np.abs(wys_arr - ty)
            ki = np.argmin(dists)
            wx0, wy0 = int(wxs_arr[ki]), int(wys_arr[ki])
            if abs(wx0 - tz) >= abs(wy0 - ty):
                nx = wx0 + (1 if tz > wx0 else -1)
                ny = wy0
            else:
                nx = wx0
                ny = wy0 + (1 if ty > wy0 else -1)
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # === REACTIVE: fix unroaded zones ===
    unroaded_zones = zone_tiles & ~nbr_road
    if np.any(unroaded_zones):
        urys, urxs = np.where(unroaded_zones)
        if np.any(rm):
            rys_arr, rxs_arr = np.where(rm)
            idx = (step * 11) % len(urxs)
            tz, ty = int(urxs[idx]), int(urys[idx])
            dists = np.abs(rxs_arr - tz) + np.abs(rys_arr - ty)
            ki = np.argmin(dists)
            rx0, ry0 = int(rxs_arr[ki]), int(rys_arr[ki])
            if abs(rx0 - tz) >= abs(ry0 - ty):
                nx = rx0 + (1 if tz > rx0 else -1)
                ny = ry0
            else:
                nx = rx0
                ny = ry0 + (1 if ty > ry0 else -1)
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    # === NEIGHBORHOOD GRID: denser, more hoods ===
    all_hoods = []
    for hy in range(10, 98, 14):
        for hx in range(10, 118, 14):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:   return 4
        if pop < 200:  return 8
        if pop < 500:  return 16
        if pop < 1000: return 28
        if pop < 2000: return 42
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # === PHASE 1: ENSURE POWER PLANTS near every active hood ===
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
            y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 14):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: Wire from plant toward hood (L-path) ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 12

    x0p, x1p = max(0, hx - 20), min(WORLD_W, hx + 21)
    y0p, y1p = max(0, hy - 20), min(WORLD_H, hy + 21)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0; best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d; best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spine
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        max_wr = max(col_wire); min_wr = min(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        max_wc = max(row_wire); min_wc = min(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: ROADS flanking wire spines ===
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 2
    for rx in [hx3 - 2, hx3 + 2]:
        if not ib(rx, hy3): continue
        for wr in col_wire3[cyc::2]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    for ry in [hy3 - 2, hy3 + 2]:
        if not ib(hx3, ry): continue
        cyc2 = (step + 1) % 2
        for wc in row_wire3[cyc2::2]:
            if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                return (Tool.ROAD, wc, ry)

    # === PHASE 4: ZONE PLACEMENT with better mix ===
    # Target: 35% industrial, 30% commercial, 35% residential
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4) + np.abs(cys - hy4)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: EXTEND ROADS reactively ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 6: CIVIC SERVICES (earlier trigger thresholds) ===
    if pop > 10:
        fire_grid = [(fx, fy) for fy in range(8, 96, 14) for fx in range(8, 114, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 50:
        police_grid = [(px2, py2) for py2 in range(12, 92, 16) for px2 in range(12, 110, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 200:
        stadium_locs = [
            (20, 15), (60, 12), (100, 15),
            (20, 85), (60, 87), (100, 85),
            (12, 50), (108, 50),
            (40, 30), (80, 30), (40, 70), (80, 70),
            (60, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power when population grows
    if pop > 300 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 30), (60, 70),
            (30, 50), (90, 50), (60, 40), (60, 60),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 93), (5, 45), (113, 45)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: extend wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 60)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    return None

def init(obs, state):
    """Bootstrap: place coal plants and seed wire+road spines."""
    actions = []
    # Three coal plants spread across the map
    actions.append((Tool.COALPOWER, 20, 50))
    actions.append((Tool.COALPOWER, 60, 50))
    actions.append((Tool.COALPOWER, 100, 50))
    # Seed wire connections from plants vertically
    for py in [50]:
        for px in [20, 60, 100]:
            for dy in range(-3, 4):
                actions.append((Tool.WIRE, px + 2, py + dy))
    # Seed roads flanking wire
    for py in [50]:
        for px in [20, 60, 100]:
            wc = px + 2
            for dy in range(-3, 4):
                actions.append((Tool.ROAD, wc - 1, py + dy))
                actions.append((Tool.ROAD, wc + 1, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.22:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Dilate helper using numpy shifts
    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 1: Ensure power plants exist at anchor positions ----
    plant_anchors = []
    if pop < 200:
        plant_anchors = [(20, 50), (60, 50), (100, 50)]
    elif pop < 600:
        plant_anchors = [(20, 50), (60, 50), (100, 50), (20, 25), (60, 25), (100, 25)]
    elif pop < 1500:
        plant_anchors = [(20, 50), (60, 50), (100, 50),
                         (20, 25), (60, 25), (100, 25),
                         (20, 75), (60, 75), (100, 75)]
    else:
        plant_anchors = [(20, 50), (60, 50), (100, 50),
                         (20, 25), (60, 25), (100, 25),
                         (20, 75), (60, 75), (100, 75),
                         (40, 50), (80, 50)]

    for (px, py) in plant_anchors:
        # Check if plant exists within 15 tiles
        x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
        y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Place plant at or near anchor
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: Build wire spines from each plant outward ----
    # Find all plant locations
    plant_ys, plant_xs = np.where(pm)

    if len(plant_xs) > 0:
        # For each plant, extend wire vertically and horizontally
        # Pick a plant to work on based on step
        p_idx = (step * 3) % len(plant_xs)
        for pi in range(len(plant_xs)):
            pid = (p_idx + pi) % len(plant_xs)
            px, py = int(plant_xs[pid]), int(plant_ys[pid])

            # Try to extend wire in 4 directions from existing wire near plant
            # Find nearest wire to this plant
            wire_ys_arr, wire_xs_arr = np.where(wm)

            # Check if wire exists near this plant
            local_wires = [(int(wire_xs_arr[i]), int(wire_ys_arr[i]))
                           for i in range(len(wire_xs_arr))
                           if abs(int(wire_xs_arr[i]) - px) + abs(int(wire_ys_arr[i]) - py) < 20]

            if not local_wires:
                # Place wire adjacent to plant
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1),
                                (2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx, ny = px + dx, py + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)
            else:
                # Extend wire spine outward: prefer vertical (N/S) coverage
                # Find extent of wire from plant
                local_ys = [w[1] for w in local_wires if abs(w[0] - px) < 4]
                local_xs = [w[0] for w in local_wires if abs(w[1] - py) < 4]

                # Determine target spine column (wire column near plant)
                wc = px + 2 if ib(px + 2, py) else px
                spine_top = max(2, py - 30)
                spine_bot = min(WORLD_H - 3, py + 30)

                if local_ys:
                    min_wy = min(local_ys)
                    max_wy = max(local_ys)
                    # Extend downward
                    if max_wy < spine_bot:
                        ny = max_wy + 1
                        if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                            return (Tool.WIRE, wc, ny)
                    # Extend upward
                    if min_wy > spine_top:
                        ny = min_wy - 1
                        if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                            return (Tool.WIRE, wc, ny)

    # ---- PHASE 3: Build horizontal wire connections between plant spines ----
    # Connect wire spines at same-Y plant groups
    plant_pairs = []
    for i in range(len(plant_xs)):
        for j in range(i + 1, len(plant_xs)):
            px1, py1 = int(plant_xs[i]), int(plant_ys[i])
            px2, py2 = int(plant_xs[j]), int(plant_ys[j])
            if abs(py1 - py2) < 10 and abs(px1 - px2) < 60:
                plant_pairs.append((px1, py1, px2, py2))

    for (px1, py1, px2, py2) in plant_pairs:
        mid_y = (py1 + py2) // 2
        min_x = min(px1, px2)
        max_x = max(px1, px2)
        # Check if horizontal wire connection exists
        wire_count = int(np.sum(wm[mid_y, min_x:max_x]))
        if wire_count < (max_x - min_x) // 2:
            for cx in range(min_x + 1, max_x):
                if bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]):
                    # Only if adjacent to existing wire
                    adj_wire = (ib(cx - 1, mid_y) and (bool(wm[mid_y, cx - 1]) or bool(pm[mid_y, cx - 1]))) or \
                               (ib(cx + 1, mid_y) and (bool(wm[mid_y, cx + 1]) or bool(pm[mid_y, cx + 1])))
                    if adj_wire:
                        return (Tool.WIRE, cx, mid_y)

    # ---- PHASE 4: Build roads flanking wire spines ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        # Build roads on both sides of wire
        cycle = step % 6
        step_k = (step * 7 + cycle * 100) % max(len(wire_xs_arr), 1)
        for off in range(min(len(wire_xs_arr), 50)):
            k = (step_k + off * 3) % len(wire_xs_arr)
            wx, wy = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx, dy in [(-1, 0), (1, 0)]:
                rx, ry = wx + dx, wy + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Check adjacent to existing road for connectivity
                    adj_road = (ib(rx - 1, ry) and bool(rm[ry, rx - 1])) or \
                               (ib(rx + 1, ry) and bool(rm[ry, rx + 1])) or \
                               (ib(rx, ry - 1) and bool(rm[ry - 1, rx])) or \
                               (ib(rx, ry + 1) and bool(rm[ry + 1, rx]))
                    if adj_road or int(np.sum(rm)) < 5:
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 5: Extend roads to reach more empty land near wire ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        step_k2 = (step * 11) % max(len(road_xs), 1)
        for off in range(min(len(road_xs), 60)):
            k = (step_k2 + off * 7) % len(road_xs)
            rx, ry = int(road_xs[k]), int(road_ys[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx + dx, ry + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(near_power[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- PHASE 6: Place civic services ----
    if pop > 100:
        fire_spots = [
            (10, 30), (40, 30), (70, 30), (100, 30),
            (10, 50), (40, 50), (70, 50), (100, 50),
            (10, 70), (40, 70), (70, 70), (100, 70),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [
            (25, 25), (55, 25), (85, 25),
            (25, 50), (55, 50), (85, 50),
            (25, 75), (55, 75), (85, 75),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        stadium_spots = [(30, 12), (70, 12), (110, 12),
                         (30, 88), (70, 88), (110, 88)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        nuke_spots = [(10, 50), (50, 10), (90, 10), (50, 90), (90, 90)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PHASE 7: Zone placement — dense, near roads and power ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Determine target zone centers based on population
        if pop < 100:
            centers = [(22, 50), (62, 50), (102, 50)]
        elif pop < 400:
            centers = [(22, 48), (62, 48), (102, 48),
                       (22, 52), (62, 52), (102, 52),
                       (22, 30), (62, 30), (102, 30),
                       (22, 70), (62, 70), (102, 70)]
        elif pop < 1200:
            centers = []
            for px in [22, 40, 62, 80, 102]:
                for py in [20, 35, 50, 65, 80]:
                    centers.append((px, py))
        else:
            centers = []
            for col in range(8):
                for row in range(7):
                    cx = 10 + col * 15
                    cy = 10 + row * 13
                    centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in centers:
            d = (np.abs(cxs - hx) + np.abs(cys - hy)).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 13 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- FALLBACK: place wire from existing wire toward empty areas ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk = (step * 17) % max(len(wire_xs3), 1)
        for off in range(min(len(wire_xs3), 50)):
            k = (sk + off * 5) % len(wire_xs3)
            wx, wy = int(wire_xs3[k]), int(wire_ys3[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

