    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- PHASE 1: Ensure enough power plants ----
    # Place coal plants on a grid every 20 tiles
    plant_positions = []
    for py in range(12, 92, 20):
        for px in range(12, 112, 20):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Wire to connect power plants and reach zones ----
    # Find tiles adjacent to existing power
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:   shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:  shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:  shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    # Keep border safe
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)

    # Identify unpowered plants
    unpowered_plants = [(px, py) for px, py in plant_positions
                        if ib(px, py) and np.any(pm[max(0,py-2):min(WORLD_H,py+3), max(0,px-2):min(WORLD_W,px+3)])
                        and not bool(near_power[py, px])]

    if len(wxs) > 0:
        if unpowered_plants:
            # Wire toward nearest unpowered plant
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(15, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered empty areas (if not many zones yet)
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0 and total_zones < 300:
            # Sample random targets
            sample_size = min(40, len(upxs))
            rng_idx = [(step * 7 + i * 13) % len(upxs) for i in range(sample_size)]
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 400)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in rng_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # ---- PHASE 3: Road grid (denser: every 6 tiles) ----
    # Build road segments connected to existing roads, aimed at unpowered road grid points
    road_grid_pts = []
    for gy in range(6, 97, 6):
        for gx in range(6, 115, 6):
            road_grid_pts.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_grid_pts
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        # Find road candidates adjacent to existing road
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1:   shifted[:-1, :] = rm[1:, :]
            elif dy == 1:  shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1:  shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets = uncovered_road[:40]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Direct placement if empty
            for gx, gy in uncovered_road[:10]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- PHASE 4: Zone placement ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride3 = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride3):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        # Prefer close to road, spread from existing zones
        score = road_dist * 1.5 + np.maximum(0, 12 - zone_dist) * 2.0

        order = np.argsort(score)
        off = (step * 19 + pop * 7) % max(len(order), 1)

        # Tool selection based on ratios and step cycle
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        rr = res_count / max(total_zones, 1)

        # Bias toward residential, then commercial, then industrial
        step_mod = step % 10
        if ir < 0.18:
            tool = Tool.INDUSTRIAL
        elif cr < 0.22:
            tool = Tool.COMMERCIAL
        elif step_mod < 6:
            tool = Tool.RESIDENTIAL
        elif step_mod < 8:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic services scaled to population ----
    if pop > 50:
        fire_grid = [(fx, fy) for fy in range(9, 95, 12) for fx in range(9, 115, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 120:
        police_grid = [(px2, py2) for py2 in range(14, 92, 14) for px2 in range(14, 112, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_grid = [(pkx, pky) for pky in range(10, 95, 10) for pkx in range(10, 115, 10)]
        for pkx, pky in park_grid:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 500:
        stadium_locs = [(25, 25), (65, 25), (95, 25),
                        (25, 50), (65, 50), (95, 50),
                        (25, 75), (65, 75), (95, 75)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        nuke_locs = [(25, 20), (95, 20), (25, 80), (95, 80),
                     (60, 10), (60, 88), (10, 50), (110, 50),
                     (45, 45), (75, 45), (45, 65), (75, 65)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 7), min(WORLD_W, nx + 8)
                y0, y1 = max(0, ny - 7), min(WORLD_H, ny + 8)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1200:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1800:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 90)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- Fallback: extend roads near power plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, -2), (4, 0), (0, 4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + flanking roads."""
    actions = []
    # Primary plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross from plant
    for dx in range(-6, 7):
        actions.append((Tool.WIRE, 60 + dx, 50))
    for dy in range(-6, 7):
        actions.append((Tool.WIRE, 60, 50 + dy))
    # Roads flanking wire column
    for dy in range(-6, 7):
        actions.append((Tool.ROAD, 59, 50 + dy))
        actions.append((Tool.ROAD, 61, 50 + dy))
    # Horizontal roads at center row
    for dx in range(-6, 7):
        actions.append((Tool.ROAD, 60 + dx, 49))
        actions.append((Tool.ROAD, 60 + dx, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    # ---- NEIGHBORHOOD GRID: 5 cols x 4 rows = 20 neighborhoods ----
    # Spread neighborhoods more evenly across the map
    neighborhood_configs = []
    for col_i, cx in enumerate([15, 38, 60, 82, 105]):
        for row_i, cy in enumerate([15, 38, 62, 85]):
            neighborhood_configs.append((cx, cy, cx, cx - 1, cx + 1, col_i * 4 + row_i))

    def num_active():
        if pop < 50:    return 1
        if pop < 200:   return 2
        if pop < 500:   return 4
        if pop < 900:   return 6
        if pop < 1500:  return 9
        if pop < 2500:  return 12
        if pop < 4000:  return 16
        return 20

    active = neighborhood_configs[:num_active()]

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 3)

    # ---- 1. ENSURE POWER PLANTS for each active neighborhood ----
    for (px, py, wc, rl, rr, idx) in active:
        x0, x1 = max(0, px - 8), min(WORLD_W, px + 9)
        y0, y1 = max(0, py - 8), min(WORLD_H, py + 9)
        if not np.any(pm[y0:y1, x0:x1]):
            # Find closest empty spot
            placed = False
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- 2. BUILD WIRE SPINES (vertical) for each neighborhood ----
    pop_ext = min(25, pop // 40)
    for (px, py, wc, rl, rr, idx) in active:
        spine_top = max(2, py - 20 - pop_ext)
        spine_bot = min(WORLD_H - 3, py + 20 + pop_ext)
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            for dy in range(-5, 6):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_rows)
            max_wr = max(wire_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE CONNECTIONS between same-row neighborhoods ----
    row_groups = {}
    for (px, py, wc, rl, rr, idx) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append(wc)
    for row_y, wcs in row_groups.items():
        if len(wcs) < 2:
            continue
        wcs_sorted = sorted(wcs)
        for i in range(len(wcs_sorted) - 1):
            wc1, wc2 = wcs_sorted[i], wcs_sorted[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- 4. BUILD ROADS flanking wire spines (both sides) ----
    for (px, py, wc, rl, rr, idx) in active:
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows:
            continue
        cycle = (step + idx * 7) % max(len(wire_rows), 1)
        for offset in range(min(len(wire_rows), 15)):
            wr = wire_rows[(cycle + offset) % len(wire_rows)]
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # ---- 5. HORIZONTAL ROADS connecting neighborhoods in a row ----
    # Place horizontal roads at cy-1 and cy+1 rows to form grid
    for (px, py, wc, rl, rr, idx) in active:
        for road_y in [py - 1, py + 1]:
            if not ib(wc, road_y):
                continue
            for dx in range(-10, 11):
                rx = wc + dx
                if ib(rx, road_y) and bool(em[road_y, rx]) and not bool(pm[road_y, rx]) and not bool(wm[road_y, rx]):
                    # Place road if adjacent to existing road or near wire
                    near_r = any(
                        ib(rx + d, road_y) and bool(rm[road_y, rx + d])
                        for d in [-1, 1]
                    ) or any(
                        ib(rx, road_y + d) and bool(rm[road_y + d, rx])
                        for d in [-1, 1]
                    )
                    near_w = bool(dilate(wm | pm, 2)[road_y, rx])
                    if near_r or near_w:
                        return (Tool.ROAD, rx, road_y)

    # ---- 6. ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Neighborhood proximity masks
    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(wm | pm, 6)

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, wc, rl, rr, idx) in active:
            d = np.abs(cxs.astype(float) - wc) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)

        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            stride = max(1, len(road_xs_arr) // 100)
            road_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(road_xs_arr), stride):
                d = (np.abs(cxs - road_xs_arr[i]) + np.abs(cys - road_ys_arr[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs), 5.0)

        # Prefer positions closer to roads and not too far from power
        score = best_dist * 0.6 + road_dist * 2.0
        order = np.argsort(score)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # ---- 7. EXTEND ROADS near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- 8. CIVIC SERVICES ----
    if pop > 100:
        firestations = []
        for col_i, cx in enumerate([20, 45, 75, 100]):
            for row_i, cy in enumerate([20, 50, 80]):
                firestations.append((cx + 3, cy + 3))
        for (sx, sy) in firestations:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        polices = []
        for col_i, cx in enumerate([15, 38, 60, 82, 105]):
            for row_i, cy in enumerate([15, 38, 62, 85]):
                polices.append((cx - 3, cy - 3))
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (40, 10), (80, 10), (40, 90), (80, 90),
            (10, 30), (110, 30), (10, 70), (110, 70),
            (20, 50), (100, 50),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 600:
        nuke_locs = [
            (25, 20), (95, 20), (25, 80), (95, 80),
            (60, 10), (60, 90), (10, 50), (110, 50),
            (40, 40), (80, 40), (40, 60), (80, 60),
        ]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(10, 85), (110, 85), (10, 15), (110, 15)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- 9. FALLBACK: extend wire laterally ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # ---- 10. FALLBACK: road near power plants ----
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, -2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + initial roads."""
    actions = []
    cx, cy = 60, 50
    # Central coal power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross - horizontal
    for dx in range(-8, 9):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Wire cross - vertical
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Two roads flanking the wire (above and below center)
    for dx in range(-8, 9):
        actions.append((Tool.ROAD, cx + dx, cy - 2))
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 40% RES, 30% COM, 30% IND
        if rr < 0.38:
            return Tool.RESIDENTIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        if ir < 0.28:
            return Tool.INDUSTRIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 5)
    near_road = dilate(rm, 3)

    # ---- PHASE 0: ENSURE ENOUGH POWER PLANTS ----
    # Scale number of needed plants with population
    needed_plants = max(2, 1 + pop // 200)
    plant_count = int(np.sum(pm))

    if plant_count < needed_plants:
        # Grid of candidate plant positions
        plant_candidates = []
        for py in range(20, 90, 20):
            for px in range(20, 110, 20):
                plant_candidates.append((px, py))
        # Also add center and corners
        for pos in [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75)]:
            plant_candidates.append(pos)
        for px, py in plant_candidates:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not np.any(pm[y0:y1, x0:x1]):
                for r in range(0, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 1: EXTEND WIRE FROM PLANTS ----
    # Determine active grid scale based on population
    if pop < 200:
        road_ys = [48, 52]
        road_xs = [55, 65]
    elif pop < 500:
        road_ys = [45, 50, 55]
        road_xs = [50, 60, 70]
    elif pop < 1000:
        road_ys = [35, 45, 55, 65]
        road_xs = [40, 55, 65, 80]
    else:
        road_ys = [25, 35, 45, 55, 65, 75]
        road_xs = [25, 40, 55, 65, 80, 95]

    # Wire rows: one tile above each road row
    wire_rows = [ry - 1 for ry in road_ys]
    wire_cols = [rx - 1 for rx in road_xs]

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire spines
        for wr in wire_rows:
            if not (0 < wr < WORLD_H - 1):
                continue
            row_wire = wm[wr, :] | pm[wr, :]
            indices = np.where(row_wire)[0]
            if len(indices) == 0:
                # Start wire from nearest plant
                pys_a, pxs_a = np.where(pm)
                if len(pxs_a) > 0:
                    idx = np.argmin(np.abs(pys_a - wr))
                    sx = int(pxs_a[idx])
                    if ib(sx, wr) and bool(em[wr, sx]):
                        return (Tool.WIRE, sx, wr)
            else:
                left = int(indices[0])
                right = int(indices[-1])
                if left > 3 and bool(em[wr, left - 1]) and not bool(pm[wr, left - 1]):
                    return (Tool.WIRE, left - 1, wr)
                if right < WORLD_W - 4 and bool(em[wr, right + 1]) and not bool(pm[wr, right + 1]):
                    return (Tool.WIRE, right + 1, wr)

    elif phase == 1:
        # Extend vertical wire spines
        for wc in wire_cols:
            if not (0 < wc < WORLD_W - 1):
                continue
            col_wire = wm[:, wc] | pm[:, wc]
            indices = np.where(col_wire)[0]
            if len(indices) == 0:
                pys_a, pxs_a = np.where(pm)
                if len(pys_a) > 0:
                    idx = np.argmin(np.abs(pxs_a - wc))
                    sy = int(pys_a[idx])
                    if ib(wc, sy) and bool(em[sy, wc]):
                        return (Tool.WIRE, wc, sy)
            else:
                top = int(indices[0])
                bot = int(indices[-1])
                if top > 3 and bool(em[top - 1, wc]) and not bool(pm[top - 1, wc]):
                    return (Tool.WIRE, wc, top - 1)
                if bot < WORLD_H - 4 and bool(em[bot + 1, wc]) and not bool(pm[bot + 1, wc]):
                    return (Tool.WIRE, wc, bot + 1)

    elif phase == 2:
        # Roads adjacent to horizontal wire spines
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [1, -1]:
                ry = wr + offset
                if not (1 < ry < WORLD_H - 2):
                    continue
                for rx in range(3, WORLD_W - 3):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads adjacent to vertical wire spines
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [1, -1]:
                rcx = wc + offset
                if not (1 < rcx < WORLD_W - 2):
                    continue
                for ry in range(3, WORLD_H - 3):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Extend horizontal roads
        for rr in road_ys:
            if not (0 < rr < WORLD_H - 1):
                continue
            row_rd = rm[rr, :]
            indices = np.where(row_rd)[0]
            if len(indices) == 0:
                # seed from power area
                pys_a, pxs_a = np.where(pm)
                if len(pxs_a) > 0:
                    idx = np.argmin(np.abs(pys_a - rr))
                    sx = int(pxs_a[idx])
                    if ib(sx, rr) and bool(em[rr, sx]) and not bool(pm[rr, sx]):
                        return (Tool.ROAD, sx, rr)
            else:
                left = int(indices[0])
                right = int(indices[-1])
                if left > 4 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
                    return (Tool.ROAD, left - 1, rr)
                if right < WORLD_W - 5 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
                    return (Tool.ROAD, right + 1, rr)

    elif phase == 5:
        # Extend vertical roads
        for rc in road_xs:
            if not (0 < rc < WORLD_W - 1):
                continue
            col_rd = rm[:, rc]
            indices = np.where(col_rd)[0]
            if len(indices) == 0:
                pys_a, pxs_a = np.where(pm)
                if len(pys_a) > 0:
                    idx = np.argmin(np.abs(pxs_a - rc))
                    sy = int(pys_a[idx])
                    if ib(rc, sy) and bool(em[sy, rc]) and not bool(pm[sy, rc]):
                        return (Tool.ROAD, rc, sy)
            else:
                indices2 = np.where(col_rd)[0]
                top = int(indices2[0])
                bot = int(indices2[-1])
                if top > 4 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
                    return (Tool.ROAD, rc, top - 1)
                if bot < WORLD_H - 5 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
                    return (Tool.ROAD, rc, bot + 1)

    elif phase == 6:
        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpowered_zones)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(power_src)
            if len(wire_xs_a) > 0:
                idx2 = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx2]), int(zone_ys_u[idx2])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx2 = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy2 = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx2, bwy), (bwx, bwy + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 7:
        # Road toward unserved zones
        unserved = zone_tiles & ~near_road
        us_ys, us_xs = np.where(unserved)
        if len(us_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx2 = (step * 13) % len(us_xs)
                tx, ty = int(us_xs[idx2]), int(us_ys[idx2])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx2 = 0 if tx == brx else (1 if tx > brx else -1)
                dy2 = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx2, bry), (brx, bry + dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 8:
        # Civic services based on population
        if pop > 40:
            fire_grid = [
                (20, 20), (60, 20), (100, 20),
                (20, 50), (60, 50), (100, 50),
                (20, 80), (60, 80), (100, 80),
                (40, 35), (80, 35), (40, 65), (80, 65),
            ]
            for sx, sy in fire_grid:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 150:
            police_grid = [
                (25, 25), (60, 25), (95, 25),
                (25, 55), (60, 55), (95, 55),
                (25, 85), (60, 85), (95, 85),
            ]
            for sx, sy in police_grid:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadiums = [
                (35, 35), (85, 35), (35, 65), (85, 65),
                (60, 20), (60, 80),
            ]
            for sx, sy in stadiums:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 600:
            nuke_spots = [
                (10, 10), (110, 10), (10, 90), (110, 90),
                (60, 10), (60, 90), (10, 50), (110, 50),
            ]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    x0, x1 = max(0, nx2 - 15), min(WORLD_W, nx2 + 16)
                    y0, y1 = max(0, ny2 - 15), min(WORLD_H, ny2 + 16)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            seaports = [(5, 90), (113, 90), (5, 5), (113, 5), (60, 5), (60, 93)]
            for sx, sy in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2000:
            airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    else:
        # Parks for land value
        if pop > 80 and step % 6 == 0:
            park_cands = em & near_road & near_power
            pys_p, pxs_p = np.where(park_cands)
            if len(pxs_p) > 0:
                idx3 = (step * 29 + pop % 17) % len(pxs_p)
                return (Tool.PARK, int(pxs_p[idx3]), int(pys_p[idx3]))

    # ---- ZONE PLACEMENT (primary goal every step) ----
    # Build candidate mask: near road AND near power AND empty
    cand_mask = em & near_road & near_power
    # Keep buffer from edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    # Avoid placing zones ON wire/road rows (leave infrastructure intact)
    avoid_rows = set(wire_rows + road_ys)
    avoid_cols = set(wire_cols + road_xs)
    for wr in avoid_rows:
        for offset in range(-1, 2):
            r = wr + offset
            if 0 <= r < WORLD_H:
                cand_mask[r, :] = False
    for wc in avoid_cols:
        for offset in range(-1, 2):
            c = wc + offset
            if 0 <= c < WORLD_W:
                cand_mask[:, c] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Score: prefer close to center + close to existing zones (density)
        cx_c, cy_c = 60, 50
        dist_center = np.sqrt((cxs2 - cx_c)**2 + (cys2 - cy_c)**2)

        zone_ys_z, zone_xs_z = np.where(zone_tiles)
        if len(zone_xs_z) > 0:
            stride = max(1, len(zone_xs_z) // 60)
            min_zone_dist = np.full(len(cxs2), 9999.0)
            for i in range(0, len(zone_xs_z), stride):
                d = (np.abs(cxs2 - zone_xs_z[i]) + np.abs(cys2 - zone_ys_z[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Slightly penalize being too far from zones (want density) but not overlap
            zone_score = np.where(min_zone_dist < 3, 200.0,
                                  np.where(min_zone_dist > 25, min_zone_dist * 0.4, 0.0))
        else:
            zone_score = dist_center * 0.5

        score = dist_center * 1.0 + zone_score * 0.6
        order = np.argsort(score)
        off = (step * 11 + pop % 13) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- FALLBACK: extend road near existing power ----
    road_ys_b, road_xs_b = np.where(rm)
    if len(road_xs_b) > 0:
        step_k = (step * 11) % len(road_xs_b)
        for offset in range(min(len(road_xs_b), 80)):
            k = (step_k + offset * 7) % len(road_xs_b)
            rx2, ry2 = int(road_xs_b[k]), int(road_ys_b[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_b, wire_xs_b = np.where(wm)
    if len(wire_xs_b) > 0:
        step_k2 = (step * 13) % len(wire_xs_b)
        for offset in range(min(len(wire_xs_b), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_b)
            wx2, wy2 = int(wire_xs_b[k]), int(wire_ys_b[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place a coal plant near center ----
    for r in range(1, 20):
        for dy in range(-r, r + 1):
            for dx in range(-r, r + 1):
                if abs(dx) == r or abs(dy) == r:
                    nx, ny = 60 + dx, 50 + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: one coal plant at center with cross wire and road frame."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-15, 16):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-15, 16):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Road frame around the cross
    for d in range(-13, 14):
        actions.append((Tool.ROAD, cx - 3, cy + d))
        actions.append((Tool.ROAD, cx + 3, cy + d))
        actions.append((Tool.ROAD, cx + d, cy - 3))
        actions.append((Tool.ROAD, cx + d, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of anchor points - denser spacing for more zones
    all_anchors = []
    for ay in range(12, 95, 12):
        for ax in range(12, 112, 12):
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:    return 4
        if pop < 200:   return 9
        if pop < 500:   return 18
        if pop < 1000:  return 30
        if pop < 2000:  return 45
        if pop < 4000:  return 60
        return len(all_anchors)

    n_active = min(num_active(), len(all_anchors))
    active_anchors = all_anchors[:n_active]

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        src = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= src[:-d, :]
            result[:-d, :] |= src[d:, :]
            result[:, d:] |= src[:, :-d]
            result[:, :-d] |= src[:, d:]
        return result

    nbr_power = dilate(wm | pm, 5)
    nbr_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANT near each active anchor ----
    if funds > 1000:
        for (ax, ay) in active_anchors:
            y0 = max(0, ay - 10); y1 = min(WORLD_H, ay + 11)
            x0 = max(0, ax - 10); x1 = min(WORLD_W, ax + 11)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ax + dx, ay + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE SPINES ----
    wire_half = min(20, 7 + pop // 12)
    vert_half = min(14, 5 + pop // 18)

    anchor_idx = step % max(len(active_anchors), 1)
    for i_offset in range(min(len(active_anchors), 6)):
        ax, ay = active_anchors[(anchor_idx + i_offset) % len(active_anchors)]
        # Horizontal wire spine
        spine_l = max(2, ax - wire_half)
        spine_r = min(WORLD_W - 3, ax + wire_half)
        for cx2 in range(spine_l, spine_r + 1):
            if not ib(cx2, ay): continue
            if bool(wm[ay, cx2]) or bool(pm[ay, cx2]): continue
            if not bool(em[ay, cx2]): continue
            for ddx in [-1, 1]:
                nx = cx2 + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    return (Tool.WIRE, cx2, ay)

        # Vertical wire spine
        spine_t = max(2, ay - vert_half)
        spine_b = min(WORLD_H - 3, ay + vert_half)
        for cy2 in range(spine_t, spine_b + 1):
            if not ib(ax, cy2): continue
            if bool(wm[cy2, ax]) or bool(pm[cy2, ax]): continue
            if not bool(em[cy2, ax]): continue
            for ddy in [-1, 1]:
                ny = cy2 + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    return (Tool.WIRE, ax, cy2)

    # ---- PHASE 3: CONNECT WIRES BETWEEN ADJACENT ANCHORS ----
    col_groups = {}
    for (ax, ay) in active_anchors:
        col_groups.setdefault(ax, []).append(ay)
    for col_x, ys_list in col_groups.items():
        ys_list_s = sorted(ys_list)
        for i in range(len(ys_list_s) - 1):
            y1c, y2c = ys_list_s[i], ys_list_s[i+1]
            for cy2 in range(y1c + 1, y2c):
                if ib(col_x, cy2) and bool(em[cy2, col_x]) and not bool(pm[cy2, col_x]):
                    adj = ((ib(col_x, cy2-1) and (bool(wm[cy2-1, col_x]) or bool(pm[cy2-1, col_x]))) or
                           (ib(col_x, cy2+1) and (bool(wm[cy2+1, col_x]) or bool(pm[cy2+1, col_x]))))
                    if adj:
                        return (Tool.WIRE, col_x, cy2)

    row_groups = {}
    for (ax, ay) in active_anchors:
        row_groups.setdefault(ay, []).append(ax)
    for row_y, xs_list in row_groups.items():
        xs_list_s = sorted(xs_list)
        for i in range(len(xs_list_s) - 1):
            x1c, x2c = xs_list_s[i], xs_list_s[i+1]
            for cx2 in range(x1c + 1, x2c):
                if ib(cx2, row_y) and bool(em[row_y, cx2]) and not bool(pm[row_y, cx2]):
                    adj = ((ib(cx2-1, row_y) and (bool(wm[row_y, cx2-1]) or bool(pm[row_y, cx2-1]))) or
                           (ib(cx2+1, row_y) and (bool(wm[row_y, cx2+1]) or bool(pm[row_y, cx2+1]))))
                    if adj:
                        return (Tool.WIRE, cx2, row_y)

    # ---- PHASE 4: ROADS flanking wire spines ----
    road_idx = step % max(len(active_anchors), 1)
    for i_off in range(min(len(active_anchors), 6)):
        ax, ay = active_anchors[(road_idx + i_off) % len(active_anchors)]
        spine_l = max(2, ax - wire_half)
        spine_r = min(WORLD_W - 3, ax + wire_half)
        spine_t = max(2, ay - vert_half)
        spine_b = min(WORLD_H - 3, ay + vert_half)

        # Roads flanking horizontal wire spine (both sides)
        for road_y_off in [-2, 2]:
            road_y = ay + road_y_off
            if not ib(ax, road_y): continue
            for cx2 in range(spine_l, spine_r + 1):
                if not ib(cx2, road_y): continue
                if bool(rm[road_y, cx2]): continue
                if not bool(em[road_y, cx2]) and not bool(zone_tiles[road_y, cx2]): continue
                if bool(pm[road_y, cx2]): continue
                adj_road = any(ib(cx2+ddx, road_y) and bool(rm[road_y, cx2+ddx]) for ddx in [-1, 1])
                adj_wire = (ib(cx2, road_y-1) and bool(wm[road_y-1, cx2])) or \
                           (ib(cx2, road_y+1) and bool(wm[road_y+1, cx2]))
                if adj_road or adj_wire:
                    return (Tool.ROAD, cx2, road_y)

        # Roads flanking vertical wire spine
        for road_x_off in [-2, 2]:
            road_x = ax + road_x_off
            if not ib(road_x, ay): continue
            for cy2 in range(spine_t, spine_b + 1):
                if not ib(road_x, cy2): continue
                if bool(rm[cy2, road_x]): continue
                if not bool(em[cy2, road_x]) and not bool(zone_tiles[cy2, road_x]): continue
                if bool(pm[cy2, road_x]): continue
                adj_road = any(ib(road_x, cy2+ddy) and bool(rm[cy2+ddy, road_x]) for ddy in [-1, 1])
                adj_wire = (ib(road_x-1, cy2) and bool(wm[cy2, road_x-1])) or \
                           (ib(road_x+1, cy2) and bool(wm[cy2, road_x+1]))
                if adj_road or adj_wire:
                    return (Tool.ROAD, road_x, cy2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]): return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float)
            best_dist = np.minimum(best_dist, d)

        score = best_dist.copy()
        # Cluster bonus: prefer placing near existing zones
        if total_zones > 3:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 100)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                # Prefer nearby but not too close (avoid overlap)
                too_close = zone_prox < 3
                score = best_dist * 0.55 + zone_prox * 0.45
                score[too_close] += 1000

        order = np.argsort(score)
        tool = pick_tool()
        # Use current observation state for offset (reactive)
        offset = (step * 7 + pop * 3 + obs.powered_zones * 11) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 6: EXTEND ROADS near powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11 + pop) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 150)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 30:
        fire_grid = [(fx, fy) for fy in range(8, 95, 14) for fx in range(8, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(10, 92, 16) for px2 in range(10, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 4 == 0:
        park_cand = em & nbr_road & nbr_power
        park_ys2, park_xs2 = np.where(park_cand)
        if len(park_xs2) > 0:
            idx = (step * 17 + pop * 5) % len(park_xs2)
            py2, px2 = int(park_ys2[idx]), int(park_xs2[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 300:
        stadium_locs = [(20, 20), (60, 15), (100, 20), (20, 80), (60, 85), (100, 80),
                        (15, 50), (105, 50), (40, 40), (80, 40), (40, 60), (80, 60)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600 and funds > 3000:
        nuclear_locs = [(10, 10), (110, 10), (10, 90), (110, 90),
                        (60, 5), (60, 95), (5, 50), (115, 50),
                        (35, 20), (85, 20), (35, 80), (85, 80),
                        (30, 50), (90, 50), (60, 30), (60, 70)]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 500:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 800:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (50, 6), (80, 6), (50, 93), (80, 93)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- FALLBACK: extend wire from plant ----
    pys, pxs = np.where(pm)
    if len(pxs) > 0:
        sk = (step * 11 + pop) % max(len(pxs), 1)
        for offset in range(min(len(pxs), 80)):
            k = (sk + offset * 7) % len(pxs)
            px2, py2 = int(pxs[k]), int(pys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0),
                              (0, 2), (0, -2), (2, 0), (-2, 0)]:
                nx2, ny2 = px2 + dx2, py2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wires ----
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13 + pop) % max(len(wxs_arr), 1)
        for offset in range(min(len(wxs_arr), 100)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: place plant near unpowered anchor ----
    for (ax, ay) in active_anchors:
        if not bool(nbr_power[ay, ax]):
            for r2 in range(1, 12):
                for dy4 in range(-r2, r2 + 1):
                    for dx4 in range(-r2, r2 + 1):
                        if abs(dx4) == r2 or abs(dy4) == r2:
                            nx4, ny4 = ax + dx4, ay + dy4
                            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                return (Tool.COALPOWER, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants, horizontal wire spine, flanking roads."""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        if x not in [30, 90]:
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(1, 99):
        if y != 50:
            actions.append((Tool.WIRE, 30, y))
            actions.append((Tool.WIRE, 90, y))
    # Flanking roads
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire/road corridor definitions
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 10

    # Phase 0: Ensure distributed power plants
    if phase == 0:
        plant_targets = [(px, py) for py in [15, 35, 50, 65, 85]
                         for px in [15, 45, 75, 105]]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(12):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Fill wire row gaps (connected to existing wire/plant)
    if phase == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]) or not bool(em[wr, wx]):
                    continue
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if bool(wm[wy, wc]) or bool(pm[wy, wc]) or not bool(em[wy, wc]):
                    continue
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    return (Tool.WIRE, wc, wy)

    # Phase 3: Roads flanking wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (1 <= ry <= WORLD_H - 2):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if not bool(em[ry, rx]) or bool(pm[ry, rx]):
                        continue
                    has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                    adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                          rx == 1
                    if has_wire and adj:
                        return (Tool.ROAD, rx, ry)

    # Phase 4: Roads flanking wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (1 <= rcx <= WORLD_W - 2):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if not bool(em[ry, rcx]) or bool(pm[ry, rcx]):
                        continue
                    has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                    adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                          ry == 1
                    if has_wire and adj:
                        return (Tool.ROAD, rcx, ry)

    # Phase 5: Cross-roads between wire rows (mid-block roads)
    if phase == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi+1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 6: Wire toward unpowered zones (reactive!)
    if phase == 6:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 7: Wire toward unpowered roads (reactive!)
    if phase == 7:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = int(np.argmin(dists))
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Extend road from existing road into powered area
    if phase == 8:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 300)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Phase 9: Place nuclear power when rich and populated
    if phase == 9 and pop > 400:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
            (30,5),(90,5),(30,95),(90,95),
            (50,50),(70,50),(60,30),(60,70),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # --- CIVIC SERVICES (reactive to population thresholds) ---
    if pop > 20:
        fire_spots = [
            (7,7),(37,7),(67,7),(97,7),
            (7,22),(117,22),(7,42),(117,42),
            (7,57),(117,57),(7,72),(117,72),
            (7,87),(37,87),(67,87),(97,87),
            (25,27),(55,27),(85,27),(25,72),(55,72),(85,72),
            (40,50),(80,50),(60,15),(60,85),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (20,12),(50,12),(80,12),(110,12),
            (20,37),(50,37),(80,37),(110,37),
            (20,62),(50,62),(80,62),(110,62),
            (20,87),(50,87),(80,87),(110,87),
            (35,50),(65,50),(95,50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (25,15),(60,15),(95,15),
            (25,45),(60,45),(95,45),
            (25,65),(60,65),(95,65),
            (25,85),(60,85),(95,85),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        seaports = [(5,92),(115,92),(5,8),(115,8),(60,5),(60,95),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1200:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45),(5,55),(110,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        for wr in wire_rows:
            park_cands[max(0,wr-1):wr+2, :] = False
        for wc in wire_cols:
            park_cands[:, max(0,wc-1):wc+2] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- ZONE PLACEMENT (primary closed-loop decision) ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Adaptive active centers: grow coverage as population increases
        if pop < 80:
            active_centers = [(cx, cy) for cy in [50]
                              for cx in [15, 35, 55, 75, 95, 115]]
        elif pop < 200:
            active_centers = [(cx, cy) for cy in [35, 50, 65]
                              for cx in [15, 30, 45, 60, 75, 90, 105]]
        elif pop < 500:
            active_centers = [(cx, cy) for cy in [15, 25, 35, 45, 55, 65, 75, 85]
                              for cx in [10, 22, 37, 52, 67, 82, 97, 112]]
        else:
            active_centers = [(cx, cy) for cy in range(6, 100, 9)
                              for cx in range(7, 120, 12)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: place coal plant near unpowered neighborhood
    all_hoods = [(cx, cy) for cy in range(6, 100, 9) for cx in range(7, 120, 12)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wire + roads."""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(30, 91):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(25, 76):
        actions.append((Tool.WIRE, 60, y))
    # Horizontal roads flanking wire
    for x in range(30, 91):
        if x != 60:
            actions.append((Tool.ROAD, x, 49))
            actions.append((Tool.ROAD, x, 51))
    # Vertical roads flanking wire
    for y in range(25, 76):
        if y != 50:
            actions.append((Tool.ROAD, 59, y))
            actions.append((Tool.ROAD, 61, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    nbr_road = dilate(rm, 2)
    nbr_wire = dilate(power_src, 6)
    near_road = dilate(rm, 3)

    # Grid of neighborhoods expanding outward from center
    # Start with center cluster, expand as population grows
    def num_neighborhoods():
        if pop < 100:   return 4
        if pop < 300:   return 8
        if pop < 600:   return 12
        if pop < 1000:  return 16
        if pop < 1800:  return 20
        if pop < 3000:  return 25
        return 30

    # Neighborhood centers arranged in a grid pattern
    # covering the map more systematically
    all_neighborhoods = []
    centers_x = [20, 40, 60, 80, 100]
    centers_y = [15, 30, 50, 70, 85]
    # Spiral order from center outward
    ordered = []
    cx_mid, cy_mid = 60, 50
    for cx in centers_x:
        for cy in centers_y:
            dist = abs(cx - cx_mid) + abs(cy - cy_mid)
            ordered.append((dist, cx, cy))
    ordered.sort()
    all_neighborhoods = [(cx, cy) for (_, cx, cy) in ordered]

    active_n = min(num_neighborhoods(), len(all_neighborhoods))
    active = all_neighborhoods[:active_n]

    # ---- 1. ENSURE POWER PLANTS for active neighborhoods ----
    for (cx, cy) in active:
        x0, x1 = max(0, cx - 10), min(WORLD_W, cx + 11)
        y0, y1 = max(0, cy - 10), min(WORLD_H, cy + 11)
        if np.any(pm[y0:y1, x0:x1]):
            continue
        # Place coal plant near neighborhood center
        for r in range(0, 12):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    nx, ny = cx + dx, cy + dy
                    if ib(nx, ny) and bool(em[ny, nx]):
                        return (Tool.COALPOWER, nx, ny)

    # ---- 2. WIRE GRID: connect plants to neighborhoods ----
    # Extend wire along column cx and row cy for each neighborhood
    for (cx, cy) in active:
        spine_top = max(2, cy - 18)
        spine_bot = min(WORLD_H - 3, cy + 18)
        spine_left = max(2, cx - 18)
        spine_right = min(WORLD_W - 3, cx + 18)

        # Vertical wire at cx
        for ny in range(spine_top, spine_bot + 1):
            if ib(cx, ny) and bool(em[ny, cx]) and not bool(pm[ny, cx]):
                return (Tool.WIRE, cx, ny)

        # Horizontal wire at cy
        for nx in range(spine_left, spine_right + 1):
            if ib(nx, cy) and bool(em[cy, nx]) and not bool(pm[cy, nx]):
                return (Tool.WIRE, nx, cy)

    # ---- 3. INTER-NEIGHBORHOOD WIRE CONNECTIONS ----
    # Connect horizontally adjacent neighborhoods at their y-level
    row_groups = {}
    for (cx, cy) in active:
        if cy not in row_groups:
            row_groups[cy] = []
        row_groups[cy].append(cx)
    for row_y, wcs in row_groups.items():
        wcs_sorted = sorted(wcs)
        for i in range(len(wcs_sorted) - 1):
            wc1, wc2 = wcs_sorted[i], wcs_sorted[i + 1]
            for conn_x in range(wc1 + 1, wc2):
                if ib(conn_x, row_y) and bool(em[row_y, conn_x]) and not bool(pm[row_y, conn_x]):
                    return (Tool.WIRE, conn_x, row_y)

    # Connect vertically adjacent neighborhoods
    col_groups = {}
    for (cx, cy) in active:
        if cx not in col_groups:
            col_groups[cx] = []
        col_groups[cx].append(cy)
    for col_x, ycs in col_groups.items():
        ycs_sorted = sorted(ycs)
        for i in range(len(ycs_sorted) - 1):
            yc1, yc2 = ycs_sorted[i], ycs_sorted[i + 1]
            for conn_y in range(yc1 + 1, yc2):
                if ib(col_x, conn_y) and bool(em[conn_y, col_x]) and not bool(pm[conn_y, col_x]):
                    return (Tool.WIRE, col_x, conn_y)

    # ---- 4. ROADS along wire spines ----
    for (cx, cy) in active:
        spine_top = max(2, cy - 18)
        spine_bot = min(WORLD_H - 3, cy + 18)
        spine_left = max(2, cx - 18)
        spine_right = min(WORLD_W - 3, cx + 18)

        # Roads flanking vertical wire at cx
        for ny in range(spine_top, spine_bot + 1):
            if bool(wm[ny, cx]) or bool(pm[ny, cx]):
                for rx in [cx - 1, cx + 1]:
                    if ib(rx, ny) and bool(em[ny, rx]) and not bool(pm[ny, rx]):
                        return (Tool.ROAD, rx, ny)

        # Roads flanking horizontal wire at cy
        for nx in range(spine_left, spine_right + 1):
            if bool(wm[cy, nx]) or bool(pm[cy, nx]):
                for ry in [cy - 1, cy + 1]:
                    if ib(nx, ry) and bool(em[ry, nx]) and not bool(pm[ry, nx]):
                        return (Tool.ROAD, nx, ry)

    # ---- 5. ZONE PLACEMENT ----
    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 30% industrial, 30% commercial, 40% residential
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (cx, cy) in active:
            d = np.abs(cxs_arr.astype(float) - cx) + np.abs(cys_arr.astype(float) - cy)
            best_dist = np.minimum(best_dist, d)

        road_ys_arr, road_xs_arr = np.where(rm)
        if len(road_xs_arr) > 0:
            stride = max(1, len(road_xs_arr) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs_arr), stride):
                d = (np.abs(cxs_arr - road_xs_arr[i]) + np.abs(cys_arr - road_ys_arr[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        score = best_dist * 0.5 + road_dist * 2.0
        order = np.argsort(score)
        step_off = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 400:
                break

    # ---- 6. EXTEND ROADS near wires ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx, ny = rx2 + dx, ry2 + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_wire[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # ---- 7. CIVIC SERVICES ----
    if pop > 80:
        firestations = [
            (20, 20), (50, 20), (80, 20), (110, 20),
            (20, 50), (50, 50), (80, 50), (110, 50),
            (20, 80), (50, 80), (80, 80), (110, 80),
        ]
        for (sx, sy) in firestations:
            nr = dilate(rm, 2)
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nr[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        polices = [
            (30, 35), (70, 35), (105, 35),
            (30, 65), (70, 65), (105, 65),
            (15, 50), (105, 50),
        ]
        nr2 = dilate(rm, 2)
        for (sx, sy) in polices:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nr2[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadiums = [
            (35, 12), (85, 12), (35, 88), (85, 88),
            (10, 35), (110, 35), (10, 65), (110, 65),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_locs = [(15, 15), (105, 15), (15, 85), (105, 85),
                     (60, 5), (60, 95), (5, 50), (115, 50)]
        for nx2, ny2 in nuke_locs:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 8), min(WORLD_W, nx2 + 9)
                y0, y1 = max(0, ny2 - 8), min(WORLD_H, ny2 + 9)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 90), (110, 90), (5, 5), (110, 5)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airport_locs = [(10, 10), (95, 10), (10, 80), (95, 80)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- 8. PARKS to boost land value ----
    if pop > 200:
        nr3 = dilate(rm, 1)
        park_cands = []
        for (cx, cy) in active:
            for dy in range(-15, 16, 5):
                for dx in range(-15, 16, 5):
                    px, py = cx + dx, cy + dy
                    if ib(px, py) and bool(em[py, px]) and bool(nr3[py, px]):
                        park_cands.append((px, py))
        if park_cands:
            k = step % len(park_cands)
            return (Tool.PARK, park_cands[k][0], park_cands[k][1])

    # ---- 9. FALLBACK: extend wire from existing wires ----
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        step_k2 = (step * 13) % max(len(wire_xs2), 1)
        for offset in range(min(len(wire_xs2), 40)):
            k = (step_k2 + offset * 5) % len(wire_xs2)
            wx, wy = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx + dx, wy + dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

# Strategy: Grid-based city with multiple power plants, dense zone packing
# Key changes from parent:
# 1. Grid layout with vertical AND horizontal roads forming proper city blocks
# 2. 40/35/25 RES/IND/COM ratio (more residential for pop)
# 3. Power plants distributed across the map from the start
# 4. Zones placed directly adjacent to roads (1 tile away, not 2)
# 5. More aggressive civic service placement
# 6. Nuclear plants added earlier

def init(obs, state):
    """Bootstrap: central coal plant + cross wire + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire cross
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads above and below
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 2))
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    # Vertical roads left and right
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid layout: roads every 4 tiles, creating 3x3 blocks for zones
    # Road rows at: 10, 14, 18, 22, ... up to 90
    # Road cols at: 10, 14, 18, 22, ... up to 110
    road_rows = list(range(10, 91, 5))
    road_cols = list(range(10, 111, 5))

    # Power plant positions (distributed)
    power_positions = [
        (30, 30), (90, 30), (30, 70), (90, 70),
        (60, 20), (60, 80), (20, 50), (100, 50),
        (45, 45), (75, 45), (45, 65), (75, 65),
    ]

    # Progressive number of power plants
    def num_plants_needed():
        if pop < 100: return 2
        if pop < 500: return 4
        if pop < 1000: return 6
        if pop < 2000: return 8
        return len(power_positions)

    # ---- PHASE 1: Place power plants ----
    n_plants_needed = num_plants_needed()
    plant_ys, plant_xs = np.where(pm)
    n_existing_plants = len(plant_xs) if len(plant_xs) > 0 else 0

    if n_existing_plants < n_plants_needed:
        for (px, py) in power_positions[:n_plants_needed]:
            # Check if already has plant nearby
            y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
            x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant and ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: Build wire grid connecting plants ----
    # Wire runs along road_rows and road_cols where no road yet
    # First build horizontal wire spines
    active_rows = road_rows[:min(len(road_rows), 4 + pop // 100)]
    active_cols = road_cols[:min(len(road_cols), 4 + pop // 100)]

    # Extend wires along key rows
    for wy in active_rows[::2]:  # Every other row for wire
        for wx in range(5, WORLD_W - 5):
            if not ib(wx, wy): continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]): continue
            if not bool(em[wy, wx]): continue
            # Place wire if adjacent to existing wire or plant
            for adj_x in [wx - 1, wx + 1]:
                if ib(adj_x, wy) and (bool(wm[wy, adj_x]) or bool(pm[wy, adj_x])):
                    return (Tool.WIRE, wx, wy)
            for adj_y in [wy - 1, wy + 1]:
                if ib(wx, adj_y) and (bool(wm[adj_y, wx]) or bool(pm[adj_y, wx])):
                    return (Tool.WIRE, wx, wy)

    # Vertical wire connectors along key cols
    for wx in active_cols[::2]:
        for wy in range(5, WORLD_H - 5):
            if not ib(wx, wy): continue
            if bool(wm[wy, wx]) or bool(pm[wy, wx]) or bool(rm[wy, wx]): continue
            if not bool(em[wy, wx]): continue
            for adj_y in [wy - 1, wy + 1]:
                if ib(wx, adj_y) and (bool(wm[adj_y, wx]) or bool(pm[adj_y, wx])):
                    return (Tool.WIRE, wx, wy)

    # ---- PHASE 3: Build road grid ----
    # Horizontal roads
    for ry in active_rows:
        for rx in range(5, WORLD_W - 5):
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]) or bool(pm[ry, rx]): continue
            if not bool(em[ry, rx]): continue
            # Place road if adjacent to road or at start of row with wire nearby
            has_adj_road = False
            for adj_x in [rx - 1, rx + 1]:
                if ib(adj_x, ry) and bool(rm[ry, adj_x]):
                    has_adj_road = True
            if has_adj_road:
                return (Tool.ROAD, rx, ry)

    # Vertical roads
    for rx in active_cols:
        for ry in range(5, WORLD_H - 5):
            if not ib(rx, ry): continue
            if bool(rm[ry, rx]) or bool(pm[ry, rx]): continue
            if not bool(em[ry, rx]): continue
            has_adj_road = False
            for adj_y in [ry - 1, ry + 1]:
                if ib(rx, adj_y) and bool(rm[adj_y, rx]):
                    has_adj_road = True
            if has_adj_road:
                return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # Target: 40% RES, 35% IND, 25% COM
        if ir < 0.33:
            return Tool.INDUSTRIAL
        if cr < 0.23:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # Road neighbor mask (within 1 tile for tight packing)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power neighbor mask (within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers: near roads AND power
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to center of map (prefer central dense building)
        cx_map, cy_map = 60, 50
        dist_to_center = np.sqrt((cxs - cx_map)**2 + (cys - cy_map)**2)
        order = np.argsort(dist_to_center)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 5: EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(20, WORLD_W, 18) for fy in range(20, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(22, WORLD_W, 22) for py2 in range(22, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 25), (60, 25), (90, 25),
            (30, 50), (60, 50), (90, 50),
            (30, 75), (60, 75), (90, 75),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear power earlier
    if pop > 800 and step % 4 == 0:
        nuclear_spots = [
            (15, 15), (105, 15), (15, 85), (105, 85),
            (60, 15), (60, 85), (15, 50), (105, 50),
            (40, 35), (80, 35), (40, 65), (80, 65),
            (55, 50), (65, 50),
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 5), (80, 5), (40, 93), (80, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS ----
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place new coal plant if no power nearby ----
    for (px, py) in power_positions:
        if ib(px, py) and not bool(nbr_power[py, px]):
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

