def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        r_r = res_count / total_zones
        if i_r < 0.22:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- Ensure at least one power plant ---
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    plant_ys, plant_xs = np.where(pm)
    # Primary plant
    px = int(np.median(plant_xs))
    py = int(np.median(plant_ys))

    # --- Compute proximity masks reactively ---
    def dilate(mask, r):
        result = mask.astype(bool).copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Determine how far spine should extend based on pop
    pop_factor = min(40, pop // 10)
    spine_top = max(3, py - 20 - pop_factor)
    spine_bot = min(WORLD_H - 4, py + 20 + pop_factor)
    spine_left = max(3, px - 20 - pop_factor)
    spine_right = min(WORLD_W - 4, px + 20 + pop_factor)

    # --- Multiple wire spines: vertical at several x positions ---
    # Determine active spine columns based on pop
    base_col = px + 2
    extra_cols = []
    if pop > 300:
        extra_cols.append(base_col + 15)
    if pop > 700:
        extra_cols.append(base_col - 15)
    if pop > 1200:
        extra_cols.append(base_col + 30)
    if pop > 1800:
        extra_cols.append(base_col - 30)

    all_spine_cols = [base_col] + extra_cols

    # --- Place additional power plants reactively ---
    # Count plants
    n_plants = len(plant_xs)
    if pop > 200 and n_plants < 2:
        p2x = px + 20
        p2y = py
        if ib(p2x, p2y) and bool(em[p2y, p2x]):
            return (Tool.COALPOWER, p2x, p2y)
    if pop > 600 and n_plants < 3:
        p3x = px - 20
        p3y = py
        if ib(p3x, p3y) and bool(em[p3y, p3x]):
            return (Tool.COALPOWER, p3x, p3y)
    if pop > 1200 and n_plants < 4:
        p4x = px + 20
        p4y = py + 20
        if ib(p4x, p4y) and bool(em[p4y, p4x]):
            return (Tool.NUCLEARPOWER, p4x, p4y)
    if pop > 2000 and n_plants < 5:
        p5x = px - 20
        p5y = py + 20
        if ib(p5x, p5y) and bool(em[p5y, p5x]):
            return (Tool.NUCLEARPOWER, p5x, p5y)

    # --- Build/extend wire spines reactively ---
    phase = step % 6

    if phase == 0:
        # Extend vertical wire spines
        for sc in all_spine_cols:
            if not ib(sc, 0):
                continue
            col_wire = [r for r in range(WORLD_H) if bool(wm[r, sc]) or bool(pm[r, sc])]
            if not col_wire:
                # Seed near plant
                for dy in range(-3, 4):
                    ny = py + dy
                    if ib(sc, ny) and bool(em[ny, sc]) and not bool(pm[ny, sc]):
                        return (Tool.WIRE, sc, ny)
            else:
                max_wr = max(col_wire)
                min_wr = min(col_wire)
                if max_wr < spine_bot:
                    nr = max_wr + 1
                    if ib(sc, nr) and bool(em[nr, sc]) and not bool(pm[nr, sc]):
                        return (Tool.WIRE, sc, nr)
                if min_wr > spine_top:
                    nr = min_wr - 1
                    if ib(sc, nr) and bool(em[nr, sc]) and not bool(pm[nr, sc]):
                        return (Tool.WIRE, sc, nr)

    elif phase == 1:
        # Build flanking roads along wire spines
        for sc in all_spine_cols:
            if not ib(sc, 0):
                continue
            col_wire = [r for r in range(WORLD_H) if bool(wm[r, sc])]
            for wr in col_wire:
                for road_c in [sc - 1, sc + 1]:
                    if ib(road_c, wr) and bool(em[wr, road_c]) and not bool(pm[wr, road_c]):
                        return (Tool.ROAD, road_c, wr)

    elif phase == 2:
        # Horizontal wire connecting spines at py level
        if len(all_spine_cols) > 1:
            for i in range(len(all_spine_cols) - 1):
                c1 = min(all_spine_cols[i], all_spine_cols[i+1])
                c2 = max(all_spine_cols[i], all_spine_cols[i+1])
                for wc in range(c1 + 1, c2):
                    if ib(wc, py) and bool(em[py, wc]) and not bool(pm[py, wc]) and not bool(wm[py, wc]):
                        return (Tool.WIRE, wc, py)

    elif phase == 3:
        # Horizontal roads at wire/road intersections
        for sc in all_spine_cols:
            col_wire = [r for r in range(WORLD_H) if bool(wm[r, sc])]
            if col_wire:
                mid_r = col_wire[len(col_wire)//2]
                # Extend roads horizontally from spine
                for road_c_off in range(2, 8):
                    for sign in [1, -1]:
                        road_x = sc + sign * road_c_off
                        if ib(road_x, mid_r) and bool(em[mid_r, road_x]) and not bool(pm[mid_r, road_x]):
                            # Only extend if adjacent to existing road
                            adj_road = (ib(road_x-1, mid_r) and bool(rm[mid_r, road_x-1])) or \
                                       (ib(road_x+1, mid_r) and bool(rm[mid_r, road_x+1]))
                            if adj_road:
                                return (Tool.ROAD, road_x, mid_r)

    elif phase == 4:
        # Extend roads outward from existing road endpoints
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            step_k = (step * 11) % len(road_xs)
            for offset in range(min(len(road_xs), 50)):
                k = (step_k + offset * 7) % len(road_xs)
                rx, ry = int(road_xs[k]), int(road_ys[k])
                for dx, dy in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx, ny = rx + dx, ry + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(near_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    else:
        # Wire extension from existing wire
        wire_ys, wire_xs = np.where(wm)
        if len(wire_xs) > 0:
            step_k = (step * 13) % len(wire_xs)
            for offset in range(min(len(wire_xs), 40)):
                k = (step_k + offset * 5) % len(wire_xs)
                wx, wy = int(wire_xs[k]), int(wire_ys[k])
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx, ny = wx + dx, wy + dy
                    if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                        return (Tool.WIRE, nx, ny)

    # --- Zone placement: reactive to current power/road coverage ---
    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Priority: closest to any spine column
        dists = np.full(len(cxs), 999999.0)
        for sc in all_spine_cols:
            d = np.abs(cxs - sc).astype(float) + np.abs(cys - py).astype(float) * 0.3
            dists = np.minimum(dists, d)
        order = np.argsort(dists)
        step_off = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        tool = pick_tool()
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 200:
                break

    # --- Civic services ---
    if pop > 100:
        fire_spots = [(px - 12, py - 12), (px + 12, py - 12),
                      (px - 12, py + 12), (px + 12, py + 12),
                      (px, py - 20), (px, py + 20)]
        for fsx, fsy in fire_spots:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        police_spots = [(px - 8, py - 8), (px + 8, py - 8),
                        (px - 8, py + 8), (px + 8, py + 8)]
        for psx, psy in police_spots:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 700:
        stadiums = [(px - 20, py), (px + 20, py),
                    (px, py - 20), (px, py + 20)]
        for ssx, ssy in stadiums:
            if ib(ssx, ssy) and bool(em[ssy, ssx]):
                return (Tool.STADIUM, ssx, ssy)

    if pop > 1500:
        seaports = [(px + 30, py + 30), (px - 30, py + 30),
                    (px + 30, py - 30), (px - 30, py - 30)]
        for spx, spy in seaports:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 2500:
        airports = [(px + 35, py + 35), (px - 35, py + 35)]
        for apx, apy in airports:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # Parks for land value
    if pop > 200 and step % 7 == 0:
        park_cand = em & near_road & near_power
        pys2, pxs2 = np.where(park_cand)
        if len(pxs2) > 0:
            idx = (step * 31 + pop) % len(pxs2)
            return (Tool.PARK, int(pxs2[idx]), int(pys2[idx]))

    # Fallback: wire toward unpowered zone area
    unpowered = zone_tiles & ~near_power
    if np.any(unpowered):
        uys, uxs = np.where(unpowered)
        # Find nearest wire
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            tx, ty = int(uxs[0]), int(uys[0])
            dists2 = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
            best = np.argmin(dists2)
            bwx, bwy = int(wire_xs2[best]), int(wire_ys2[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx, ny in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

