def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 45% res, 30% com, 25% ind - more commercial/industrial than parent
    def pick_tool():
        r_r = res_count / total_zones
        c_r = com_count / total_zones
        i_r = ind_count / total_zones
        if i_r < 0.25:
            return Tool.INDUSTRIAL
        if c_r < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Anchors arranged in a tighter grid around center, expanding outward with pop
    # Use a spiral-like expansion from center
    base_anchors = [
        (55, 45),   # center
        (35, 45), (75, 45),  # left/right
        (55, 25), (55, 65),  # up/down
        (35, 25), (75, 25), (35, 65), (75, 65),  # corners
        (15, 45), (95, 45),  # far left/right
        (55, 10), (55, 80),  # far up/down
        (15, 25), (95, 25), (15, 65), (95, 65),  # outer corners
        (110, 45), (10, 10), (110, 10), (10, 80), (110, 80),
        (55, 90), (30, 90), (80, 90),
    ]

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 3
        if pop < 350:  return 5
        if pop < 600:  return 7
        if pop < 900:  return 9
        if pop < 1200: return 12
        if pop < 1800: return 15
        return len(base_anchors)

    n_active = num_active()
    active_anchors = base_anchors[:n_active]

    # ---- ENSURE POWER PLANTS near each anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 10); y1 = min(WORLD_H, ay + 11)
        x0 = max(0, ax - 10); x1 = min(WORLD_W, ax + 11)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE GRID: both horizontal and vertical spines ----
    wire_half = min(20, 6 + pop // 12)
    for (ax, ay) in active_anchors:
        # Horizontal wire
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            for dx in range(-2, 3):
                nx = ax + dx
                if ib(nx, ay) and bool(em[ay, nx]) and not bool(pm[ay, nx]):
                    return (Tool.WIRE, nx, ay)
        else:
            min_wc = min(wire_in_row); max_wc = max(wire_in_row)
            if max_wc < spine_right:
                nc = max_wc + 1
                if ib(nc, ay) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)
            if min_wc > spine_left:
                nc = min_wc - 1
                if ib(nc, ay) and not bool(pm[ay, nc]):
                    return (Tool.WIRE, nc, ay)

    vert_half = min(15, 5 + pop // 15)
    for (ax, ay) in active_anchors:
        # Vertical wire
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            for dy in range(-2, 3):
                ny = ay + dy
                if ib(ax, ny) and bool(em[ny, ax]) and not bool(pm[ny, ax]):
                    return (Tool.WIRE, ax, ny)
        else:
            min_wr = min(wire_in_col); max_wr = max(wire_in_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(ax, nr) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(ax, nr) and not bool(pm[nr, ax]):
                    return (Tool.WIRE, ax, nr)

    # ---- INTER-ANCHOR WIRE CONNECTIONS ----
    # Connect anchors in same column
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]; _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    return (Tool.WIRE, col_x, cy)

    # Connect anchors in same row
    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]; x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: roads offset from wire, using +/-2 and +/-4 ----
    road_offsets = [-3, 3]  # roads at offset 3 from wire spine (different from parent's 2)
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        wire_in_row = [c for c in range(spine_left, spine_right + 1)
                       if ib(c, ay) and bool(wm[ay, c])]
        if not wire_in_row:
            continue
        cycle = (step + idx * 7) % max(len(wire_in_row), 1)
        for wc in wire_in_row[cycle::3]:
            for road_y in [ay - 3, ay + 3]:
                if ib(wc, road_y) and bool(em[road_y, wc]) and not bool(pm[road_y, wc]):
                    return (Tool.ROAD, wc, road_y)

    # Vertical road flanks
    for idx, (ax, ay) in enumerate(active_anchors):
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        wire_in_col = [r for r in range(spine_top, spine_bot + 1)
                       if ib(ax, r) and bool(wm[r, ax])]
        if not wire_in_col:
            continue
        cycle = (step + idx * 5) % max(len(wire_in_col), 1)
        for wr in wire_in_col[cycle::3]:
            for road_x in [ax - 3, ax + 3]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # Horizontal cross roads connecting same-row anchors
    for row_y in ys_set:
        row_anchors_list = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        if len(row_anchors_list) >= 2:
            for horiz_y_off in [-4, 4]:
                horiz_y = row_y + horiz_y_off
                x_start = row_anchors_list[0][0] - 4
                x_end = row_anchors_list[-1][0] + 4
                for cx in range(max(2, x_start), min(WORLD_W - 2, x_end + 1)):
                    if ib(cx, horiz_y) and bool(em[horiz_y, cx]) and not bool(pm[horiz_y, cx]):
                        return (Tool.ROAD, cx, horiz_y)

    # Vertical cross roads connecting same-col anchors
    for col_x in xs_set:
        col_anchors_list = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        if len(col_anchors_list) >= 2:
            for vert_x_off in [-4, 4]:
                vert_x = col_x + vert_x_off
                y_start = col_anchors_list[0][1] - 4
                y_end = col_anchors_list[-1][1] + 4
                for cy in range(max(2, y_start), min(WORLD_H - 2, y_end + 1)):
                    if ib(vert_x, cy) and bool(em[cy, vert_x]) and not bool(pm[cy, vert_x]):
                        return (Tool.ROAD, vert_x, cy)

    # ---- BUILD NEIGHBOR MASKS ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 11) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 600:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 13) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 9) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES: fire stations early, police later ----
    if pop > 30:
        fire_spots = [
            (8, 10), (32, 10), (56, 10), (80, 10), (104, 10),
            (8, 32), (32, 32), (56, 32), (80, 32), (104, 32),
            (8, 54), (32, 54), (56, 54), (80, 54), (104, 54),
            (8, 76), (32, 76), (56, 76), (80, 76), (104, 76),
            (8, 90), (32, 90), (56, 90), (80, 90), (104, 90),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = [
            (12, 6), (38, 6), (62, 6), (88, 6), (112, 6),
            (12, 28), (38, 28), (62, 28), (88, 28), (112, 28),
            (12, 50), (38, 50), (62, 50), (88, 50), (112, 50),
            (12, 72), (38, 72), (62, 72), (88, 72), (112, 72),
            (12, 88), (38, 88), (62, 88), (88, 88), (112, 88),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (22, 6), (60, 6), (98, 6),
            (22, 91), (60, 91), (98, 91),
            (6, 48), (114, 48),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Switch to nuclear power when population supports it
    if pop > 600:
        nuke_spots = [
            (6, 6), (114, 6), (6, 93), (114, 93),
            (58, 6), (58, 93),
            (6, 50), (114, 50),
            (28, 6), (88, 6),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for asp in [(56, 7), (6, 50), (114, 50), (56, 91)]:
            ax2, ay2 = asp
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for sp in [(6, 94), (114, 94), (60, 96), (6, 6), (114, 6)]:
            sx2, sy2 = sp
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones to boost land value ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 5 + i * 19) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 2), (-2, 2), (2, -2), (-2, -2), (3, 0), (-3, 0), (0, 3), (0, -3)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 17) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 7) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: extend roads ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 23) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 0), (-2, 0)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire grid + flanking roads."""
    actions = []
    # Two central coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        if x not in [30, 90]:
            actions.append((Tool.WIRE, x, 50))
    # Roads flanking wire spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Vertical wires from plants
    for y in range(1, 99):
        if y != 50:
            actions.append((Tool.WIRE, 30, y))
            actions.append((Tool.WIRE, 90, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        # More industrial early, then balance
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Wire grid: horizontal every 8 rows, vertical every 12 cols
    wire_rows = list(range(8, 100, 8))   # denser
    wire_cols = list(range(12, 120, 12)) # denser

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- PHASE 0: Spread coal plants across map reactively ---
    if step % 6 == 0:
        plant_targets = [(px, py) for py in [10, 25, 40, 55, 70, 85]
                         for px in [12, 36, 60, 84, 108]]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(15):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # --- PHASE 1: Extend wire rows reactively (grow from existing wire/plant) ---
    if step % 6 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]) or bool(rm[wr, wx]):
                    continue
                if not bool(em[wr, wx]):
                    continue
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    return (Tool.WIRE, wx, wr)

    # --- PHASE 2: Extend wire cols reactively ---
    if step % 6 == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if bool(wm[wy, wc]) or bool(pm[wy, wc]) or bool(rm[wy, wc]):
                    continue
                if not bool(em[wy, wc]):
                    continue
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    return (Tool.WIRE, wc, wy)

    # --- PHASE 3: Roads flanking wire rows ---
    if step % 6 == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  (ry > 0 and bool(rm[ry-1, rx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # --- PHASE 4: Roads flanking wire cols ---
    if step % 6 == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

    # --- PHASE 5: Wire toward unpowered zones ---
    if step % 6 == 5:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- CIVIC SERVICES (reactive to pop) ---
    if pop > 15:
        fire_spots = [
            (7,7),(37,7),(67,7),(97,7),(117,7),
            (7,22),(117,22),(7,42),(117,42),
            (7,57),(117,57),(7,72),(117,72),
            (7,87),(37,87),(67,87),(97,87),(117,87),
            (25,27),(55,27),(85,27),(25,72),(55,72),(85,72),
            (40,50),(80,50),(60,15),(60,85),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 50:
        police_spots = [
            (20,12),(50,12),(80,12),(110,12),
            (20,37),(50,37),(80,37),(110,37),
            (20,62),(50,62),(80,62),(110,62),
            (20,87),(50,87),(80,87),(110,87),
            (35,50),(65,50),(95,50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 150:
        stadium_spots = [
            (25,15),(60,15),(95,15),
            (25,45),(60,45),(95,45),
            (25,65),(60,65),(95,65),
            (25,85),(60,85),(95,85),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 300:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
            (50,50),(70,50),(60,30),(60,70),
            (30,5),(90,5),(30,95),(90,95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 600:
        seaports = [(5,90),(115,90),(5,10),(115,10),(60,5),(60,95),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1000:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45),(5,55),(110,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value near zones
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        for wr in wire_rows:
            park_cands[max(0,wr-1):wr+2, :] = False
        for wc in wire_cols:
            park_cands[:, max(0,wc-1):wc+2] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- ZONE PLACEMENT: primary closed-loop reactive ---
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Reactive neighborhood centers based on observed zone density
        # Find where zones already exist and expand outward
        zone_ys, zone_xs = np.where(zone_tiles)
        if len(zone_xs) > 0 and pop > 50:
            # Use existing zone centroids as attraction centers
            # Sample a few zone locations as seeds
            n_centers = min(20, len(zone_xs))
            step_seed = (step * 13) % max(len(zone_xs), 1)
            active_centers = []
            for i in range(n_centers):
                ki = (step_seed + i * 7) % len(zone_xs)
                active_centers.append((int(zone_xs[ki]), int(zone_ys[ki])))
            # Also add grid centers
            active_centers += [(cx, cy) for cy in range(6, 100, 10)
                                for cx in range(7, 120, 14)]
        else:
            # Initial: focus on well-powered/roaded areas
            if pop < 100:
                active_centers = [(cx, cy) for cy in [48, 52]
                                  for cx in range(7, 120, 8)]
            else:
                active_centers = [(cx, cy) for cy in range(6, 100, 10)
                                  for cx in range(7, 120, 14)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # --- FALLBACK: extend road from existing road into powered area ---
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- FALLBACK: extend wire from existing wire ---
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- FALLBACK: plant near unpowered area ---
    all_hoods = [(cx, cy) for cy in range(6, 100, 10) for cx in range(7, 120, 14)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 15):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

# City builder v3: Radial neighborhood layout with dense road grids
# Key changes from parent:
# - Radial/spoke layout instead of rectangular grid
# - Each neighborhood has its own internal road grid (not just spine flanking)
# - More balanced zone mix with stronger commercial emphasis
# - Earlier civic services placement
# - Better power distribution with wires along roads

def init(obs, state):
    """Bootstrap: two coal plants + initial wire + road cross."""
    actions = []
    # Primary plant at center
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire spokes outward
    for d in range(1, 8):
        actions.append((Tool.WIRE, cx + d, cy))
        actions.append((Tool.WIRE, cx - d, cy))
        actions.append((Tool.WIRE, cx, cy + d))
        actions.append((Tool.WIRE, cx, cy - d))
    # Initial roads along wire
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # ---- NEIGHBORHOOD CLUSTERS ----
    # Each cluster has a center; we build a local road grid + zones around it
    # Using a radial layout: center + 8 spokes at varying distances
    clusters = [
        # Center cluster
        (60, 50),
        # Inner ring (distance ~20)
        (60, 30), (60, 70),
        (40, 50), (80, 50),
        (45, 35), (75, 35),
        (45, 65), (75, 65),
        # Outer ring (distance ~35)
        (25, 50), (95, 50),
        (60, 15), (60, 85),
        (30, 25), (90, 25),
        (30, 75), (90, 75),
        # Far corners
        (15, 15), (105, 15),
        (15, 85), (105, 85),
        (15, 50), (105, 50),
        (60, 8),  (60, 92),
    ]

    def num_active():
        if pop < 50:    return 1
        if pop < 150:   return 3
        if pop < 400:   return 5
        if pop < 800:   return 9
        if pop < 1500:  return 13
        if pop < 3000:  return 17
        if pop < 6000:  return 21
        return len(clusters)

    n_active = min(num_active(), len(clusters))
    active_clusters = clusters[:n_active]

    # ---- PHASE 1: POWER PLANTS ----
    # Each cluster needs a plant nearby
    for (cx, cy) in active_clusters:
        x0, x1 = max(0, cx - 12), min(WORLD_W, cx + 13)
        y0, y1 = max(0, cy - 12), min(WORLD_H, cy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE NETWORK ----
    # Strategy: wire runs along horizontal/vertical axes through each cluster center
    # Build wires connecting cluster to nearest plant
    for ci, (cx, cy) in enumerate(active_clusters):
        # Only process a subset each step to avoid doing too much computation
        if step % max(len(active_clusters), 1) != ci % max(len(active_clusters), 1):
            continue

        # Wire horizontal line through cluster center
        for dx in range(-9, 10):
            wx = cx + dx
            if not ib(wx, cy): continue
            if bool(wm[cy, wx]) or bool(pm[cy, wx]): continue
            if not bool(em[cy, wx]): continue
            # Check adjacent for wire/plant
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, cy) and (bool(wm[cy, ax]) or bool(pm[cy, ax])):
                    return (Tool.WIRE, wx, cy)

        # Wire vertical line through cluster center
        for dy in range(-9, 10):
            wy = cy + dy
            if not ib(cx, wy): continue
            if bool(wm[wy, cx]) or bool(pm[wy, cx]): continue
            if not bool(em[wy, cx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(cx, ay) and (bool(wm[ay, cx]) or bool(pm[ay, cx])):
                    return (Tool.WIRE, cx, wy)

    # ---- PHASE 3: INTER-CLUSTER WIRE CONNECTIONS ----
    # Connect pairs of nearby clusters with wire bridges
    for i, (cx1, cy1) in enumerate(active_clusters):
        for j, (cx2, cy2) in enumerate(active_clusters[i+1:], i+1):
            dist = abs(cx1-cx2) + abs(cy1-cy2)
            if dist > 45: continue  # too far

            # Try horizontal then vertical bridge at midpoint
            if abs(cy1 - cy2) <= 5:
                # Roughly same row - connect horizontally
                mid_y = (cy1 + cy2) // 2
                x_lo, x_hi = min(cx1, cx2), max(cx1, cx2)
                for wx in range(x_lo, x_hi + 1):
                    if not ib(wx, mid_y): continue
                    if bool(wm[mid_y, wx]) or bool(pm[mid_y, wx]): continue
                    if not bool(em[mid_y, wx]): continue
                    for adj in [-1, 1]:
                        ax = wx + adj
                        if ib(ax, mid_y) and (bool(wm[mid_y, ax]) or bool(pm[mid_y, ax])):
                            return (Tool.WIRE, wx, mid_y)
            if abs(cx1 - cx2) <= 5:
                # Roughly same col - connect vertically
                mid_x = (cx1 + cx2) // 2
                y_lo, y_hi = min(cy1, cy2), max(cy1, cy2)
                for wy in range(y_lo, y_hi + 1):
                    if not ib(mid_x, wy): continue
                    if bool(wm[wy, mid_x]) or bool(pm[wy, mid_x]): continue
                    if not bool(em[wy, mid_x]): continue
                    for adj in [-1, 1]:
                        ay = wy + adj
                        if ib(mid_x, ay) and (bool(wm[ay, mid_x]) or bool(pm[ay, mid_x])):
                            return (Tool.WIRE, mid_x, wy)

    # ---- PHASE 4: ROAD GRID WITHIN CLUSTERS ----
    # Build a local 3-road cross (+) in each cluster
    # Roads at cx-2, cx, cx+2 (vertical) and cy-2, cy, cy+2 (horizontal)
    # Wire runs at cx, cy; roads flank at cx±1 and cy±1

    for ci, (cx, cy) in enumerate(active_clusters):
        if (step + ci) % max(len(active_clusters), 2) not in range(max(1, len(active_clusters) // 2)):
            continue

        road_range = 8

        # Vertical roads flanking wire at cx
        for rx in [cx - 1, cx + 1]:
            if not ib(rx, cy): continue
            for dy in range(-road_range, road_range + 1):
                ry = cy + dy
                if not ib(rx, ry): continue
                if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
                # Road adjacent to wire or road
                wire_nearby = (ib(rx+1, ry) and (bool(wm[ry, rx+1]) or bool(pm[ry, rx+1]))) or \
                              (ib(rx-1, ry) and (bool(wm[ry, rx-1]) or bool(pm[ry, rx-1])))
                road_nearby = any(ib(rx+ddx, ry+ddy) and bool(rm[ry+ddy, rx+ddx])
                                  for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)])
                if wire_nearby or road_nearby:
                    return (Tool.ROAD, rx, ry)

        # Horizontal roads flanking wire at cy
        for ry in [cy - 1, cy + 1]:
            if not ib(cx, ry): continue
            for dx in range(-road_range, road_range + 1):
                rcx = cx + dx
                if not ib(rcx, ry): continue
                if not bool(em[ry, rcx]) or bool(pm[ry, rcx]): continue
                wire_nearby = (ib(rcx, ry+1) and (bool(wm[ry+1, rcx]) or bool(pm[ry+1, rcx]))) or \
                              (ib(rcx, ry-1) and (bool(wm[ry-1, rcx]) or bool(pm[ry-1, rcx])))
                road_nearby = any(ib(rcx+ddx, ry+ddy) and bool(rm[ry+ddy, rcx+ddx])
                                  for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)])
                if wire_nearby or road_nearby:
                    return (Tool.ROAD, rcx, ry)

        # Additional parallel roads for more zone coverage
        for offset in [3, -3]:
            rx2 = cx + offset
            if not ib(rx2, cy): continue
            for dy in range(-road_range + 2, road_range - 1):
                ry = cy + dy
                if not ib(rx2, ry): continue
                if not bool(em[ry, rx2]) or bool(pm[ry, rx2]): continue
                road_nearby = any(ib(rx2+ddx, ry+ddy) and bool(rm[ry+ddy, rx2+ddx])
                                  for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)])
                if road_nearby:
                    return (Tool.ROAD, rx2, ry)

            ry2 = cy + offset
            if not ib(cx, ry2): continue
            for dx in range(-road_range + 2, road_range - 1):
                rcx = cx + dx
                if not ib(rcx, ry2): continue
                if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
                road_nearby = any(ib(rcx+ddx, ry2+ddy) and bool(rm[ry2+ddy, rcx+ddx])
                                  for ddx, ddy in [(1,0),(-1,0),(0,1),(0,-1)])
                if road_nearby:
                    return (Tool.ROAD, rcx, ry2)

    # ---- PHASE 5: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 40% RES, 35% COM, 25% IND - more commercial than parent
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Neighbor road mask (within 2 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Neighbor power mask (wire or plant within 4 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Candidate zone centers
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_clusters:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    # Fire stations - earlier than parent (pop > 50)
    if pop > 50:
        fire_spots = [(fx, fy) for fx in range(10, WORLD_W, 14) for fy in range(10, WORLD_H, 14)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(12, WORLD_W, 18) for py2 in range(12, WORLD_H, 18)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [(35, 25), (85, 25), (35, 75), (85, 75),
                    (60, 50), (15, 50), (105, 50),
                    (60, 20), (60, 80), (20, 20), (100, 20),
                    (20, 80), (100, 80)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 90), (112, 90), (8, 10), (112, 10),
                    (60, 95), (60, 5), (25, 95), (95, 95)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 8), (80, 8), (40, 92), (80, 92),
                    (8, 40), (8, 60), (112, 40), (112, 60)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrade
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                         (10, 50), (110, 50), (60, 10), (60, 90),
                         (45, 38), (75, 38), (45, 62), (75, 62)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant at uncovered cluster ----
    for (cx, cy) in active_clusters:
        if not bool(nbr_power[cy, cx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire and road grid foundation"""
    actions = []
    # Two coal plants for initial power
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires connecting plants
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Roads above and below center wire
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 40% res, 35% com, 25% ind (more commercial than parent)
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Grid layout: horizontal wire rows every 12 tiles, vertical cols every 15 tiles
    wire_rows = [8, 20, 32, 44, 56, 68, 80, 92]
    wire_cols = [8, 20, 35, 50, 65, 80, 95, 110]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Priority 0: Place coal plants in quadrants that lack one
    if step % 10 == 0:
        # Dense grid of plant coverage targets
        plant_targets = [
            (30, 50), (90, 50),   # center row
            (15, 20), (55, 20), (95, 20),   # top third
            (15, 80), (55, 80), (95, 80),   # bottom third
            (30, 35), (90, 35), (30, 65), (90, 65),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 16)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 16)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Priority 1: Fill horizontal wire rows
    if step % 10 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Priority 2: Fill vertical wire cols
    if step % 10 == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # Priority 3: Roads parallel to wire rows (one row above each wire row)
    if step % 10 == 3:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]) and not bool(wm[ry, rx]):
                        near_wire = (ry > 0 and (bool(wm[ry-1, rx]) or bool(pm[ry-1, rx]))) or \
                                    (ry < WORLD_H-1 and (bool(wm[ry+1, rx]) or bool(pm[ry+1, rx])))
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        if near_wire or adj_road:
                            return (Tool.ROAD, rx, ry)

    # Priority 4: Roads parallel to wire cols
    if step % 10 == 4:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]) and not bool(wm[ry, rcx]):
                        near_wire = (rcx > 0 and (bool(wm[ry, rcx-1]) or bool(pm[ry, rcx-1]))) or \
                                    (rcx < WORLD_W-1 and (bool(wm[ry, rcx+1]) or bool(pm[ry, rcx+1])))
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                   bool(rm[ry, max(0, rcx-1)]) or \
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if near_wire or adj_road:
                            return (Tool.ROAD, rcx, ry)

    # Priority 5: Cross streets in mid-blocks
    if step % 10 == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Priority 6: Wire unpowered zones
    if step % 10 == 6:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Priority 7: Wire roads without power
    if step % 10 == 7:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 15:
        fire_spots = [
            (8, 8), (40, 8), (70, 8), (100, 8),
            (8, 30), (115, 30), (8, 50), (115, 50),
            (8, 70), (115, 70), (8, 92), (40, 92), (70, 92), (100, 92),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (55, 50), (65, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (20, 15), (60, 15), (100, 15),
            (20, 45), (60, 45), (100, 45),
            (20, 65), (60, 65), (100, 65),
            (20, 85), (60, 85), (100, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (25, 25), (75, 25), (25, 75), (75, 75),
            (50, 10), (50, 90), (10, 50), (110, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    # Nuclear plants when pop grows (more power needed)
    if pop > 500:
        nuke_spots = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (10, 50), (110, 50), (60, 10), (60, 90),
            (30, 10), (90, 10), (30, 90), (90, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 85), (110, 85), (5, 15), (110, 15)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [(45, 5), (65, 5), (45, 94), (65, 94)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 150 and step % 6 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep zones away from wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Scale active centers by population
        if pop < 100:
            # Focus on center cross to bootstrap
            active_centers = [
                (60, 50), (45, 50), (75, 50), (60, 38), (60, 62),
                (45, 38), (75, 38), (45, 62), (75, 62)
            ]
        elif pop < 500:
            # Two neighborhoods: center and edge rings
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 12 + col * 16
                    cy = 12 + row * 19
                    active_centers.append((cx, cy))
        elif pop < 1500:
            # Expand to full grid coverage
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 7 + col * 13
                    cy = 7 + row * 13
                    active_centers.append((cx, cy))
        else:
            # Dense full coverage
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 5 + col * 11
                    cy = 5 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 9) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: coal plants + wire/road grid skeleton"""
    actions = []
    # Central coal plants
    for px, py in [(20, 50), (59, 50), (99, 50), (59, 20), (59, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for wy in [20, 40, 50, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines
    for wx in [20, 40, 59, 79, 99]:
        for y in range(1, 99):
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wire spines
    for wy in [20, 40, 60, 80]:
        for x in range(1, 119):
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [20, 40, 59, 79, 99]
    sec_wire_rows = [10, 30, 70, 90]
    sec_wire_cols = [10, 30, 70, 90, 110]

    # Neighborhood grid for zone targeting - 7 rows x 8 cols
    nh_positions = []
    for row in range(7):
        for col in range(8):
            cx = min(7 + col * 15, 116)
            cy = min(7 + row * 13, 94)
            nh_positions.append((cx, cy))

    def get_active_hoods():
        if pop < 50:
            return [nh_positions[i] for i in [18, 19, 26, 27, 17, 20]]
        elif pop < 200:
            return nh_positions[12:40]
        elif pop < 600:
            return nh_positions[6:50]
        elif pop < 1500:
            return nh_positions[3:53]
        else:
            return nh_positions

    active_hoods = get_active_hoods()

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- REACTIVE POWER PLANT PLACEMENT ---
    # If active hoods lack nearby plants, place one
    check_hoods = active_hoods[:8]
    for (hx, hy) in check_hoods:
        x0, x1 = max(0, hx - 22), min(WORLD_W, hx + 23)
        y0, y1 = max(0, hy - 22), min(WORLD_H, hy + 23)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(2, 22):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = hx + dx, hy + dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                return (Tool.COALPOWER, nx2, ny2)

    phase = step % 16

    if phase == 0:
        # Extend horizontal wire spines
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for wx in range(1, WORLD_W - 1):
                if not bool(row_wire[wx]):
                    left = bool(row_wire[wx-1]) if wx > 0 else False
                    right = bool(row_wire[wx+1]) if wx < WORLD_W-1 else False
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire spines
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for wy in range(1, WORLD_H - 1):
                if not bool(col_wire[wy]):
                    up = bool(col_wire[wy-1]) if wy > 0 else False
                    down = bool(col_wire[wy+1]) if wy < WORLD_H-1 else False
                    if (up or down) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads flanking horizontal wire spines
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads flanking vertical wire spines
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Secondary wire rows
        for wr in sec_wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                for wc in wire_cols:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_wire[wx]):
                        left = bool(row_wire[wx-1]) if wx > 0 else False
                        right = bool(row_wire[wx+1]) if wx < WORLD_W-1 else False
                        if (left or right) and bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    elif phase == 5:
        # Secondary vertical wire cols
        for wc in sec_wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                for wr in wire_rows:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_wire[wy]):
                        up = bool(col_wire[wy-1]) if wy > 0 else False
                        down = bool(col_wire[wy+1]) if wy < WORLD_H-1 else False
                        if (up or down) and bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    elif phase == 6:
        # Cross-street horizontal roads between wire rows
        all_wire_rows = sorted(wire_rows + sec_wire_rows)
        for i in range(len(all_wire_rows) - 1):
            r1, r2 = all_wire_rows[i], all_wire_rows[i+1]
            mid_y = (r1 + r2) // 2
            for rx in range(2, WORLD_W - 2):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                    adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                          (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 7:
        # Cross-street vertical roads between wire cols
        all_wire_cols = sorted(wire_cols + sec_wire_cols)
        for i in range(len(all_wire_cols) - 1):
            c1, c2 = all_wire_cols[i], all_wire_cols[i+1]
            mid_x = (c1 + c2) // 2
            for ry in range(2, WORLD_H - 2):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                    adj = (ib(mid_x, ry-1) and bool(rm[ry-1, mid_x])) or \
                          (ib(mid_x, ry+1) and bool(rm[ry+1, mid_x]))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 8:
        # Extend road from existing road near power
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 150)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 9:
        # Wire toward unpowered zones
        zone_ys_u, zone_xs_u = np.where(zone_tiles & ~near_power)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 10:
        # Wire toward unpowered active hoods
        unpowered = [(hx,hy) for (hx,hy) in active_hoods if not bool(near_power[hy,hx])]
        if unpowered:
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                tx, ty = unpowered[0]
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best = np.argmin(dists)
                bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 11:
        # Fire stations reactive to population
        if pop > 20:
            fire_spots = [(5,5),(35,5),(65,5),(95,5),(115,5),
                          (5,25),(35,25),(65,25),(95,25),(115,25),
                          (5,50),(65,50),(115,50),
                          (5,70),(35,70),(65,70),(95,70),(115,70),
                          (5,93),(35,93),(65,93),(95,93),(115,93)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)
        if pop > 100:
            police_spots = [(15,15),(45,15),(75,15),(105,15),
                            (15,45),(45,45),(75,45),(105,45),
                            (15,75),(45,75),(75,75),(105,75)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

    elif phase == 12:
        # Stadiums and nuclear power
        if pop > 300:
            stadium_spots = [(35,35),(85,35),(35,65),(85,65),
                             (10,50),(110,50),(60,20),(60,80)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)
        if pop > 500:
            nuke_spots = [(5,5),(113,5),(5,93),(113,93),
                          (59,5),(59,93),(5,50),(113,50),
                          (40,50),(79,50),(59,30),(59,70)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    elif phase == 13:
        # Seaports and airports
        if pop > 800:
            seaports = [(5,93),(113,93),(5,5),(113,5),(59,5),(59,93),(30,93),(90,93)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)
        if pop > 1500:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(5,57),(113,43),(113,57)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    elif phase == 14:
        # Roads adjacent to secondary wire rows
        for wr in sec_wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    else:  # phase == 15
        # Roads adjacent to secondary wire cols
        for wc in sec_wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # ---- ZONE PLACEMENT (main closed-loop action) ----
    avoid_rows = wire_rows + sec_wire_rows
    avoid_cols = wire_cols + sec_wire_cols

    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    for wr in avoid_rows:
        cand_mask[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for wc in avoid_cols:
        cand_mask[:, max(0,wc-1):min(WORLD_W,wc+2)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        best_dist = np.full(len(cxs2), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs2 - hx).astype(float) + np.abs(cys2 - hy).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 1000:
                break

    # Parks for land value
    if pop > 50 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: extend road from zones
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Small bootstrap: 3 coal plants + wire connections + road starters"""
    actions = []
    # Three power plants: center, NW quadrant, SE quadrant
    plants = [(60, 50), (30, 25), (90, 75)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
    # Wire from each plant outward (horizontal + vertical short spines)
    for px, py in plants:
        for dx in range(-8, 9):
            if dx != 0:
                actions.append((Tool.WIRE, px + dx, py))
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
    # Seed roads adjacent to wire spines (horizontal)
    for px, py in plants:
        actions.append((Tool.ROAD, px - 5, py + 2))
        actions.append((Tool.ROAD, px + 5, py + 2))
        actions.append((Tool.ROAD, px - 5, py - 2))
        actions.append((Tool.ROAD, px + 5, py - 2))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # --- STEP 1: Ensure enough power plants spread across map ---
    # Check every 20x20 region, place plant if none nearby
    if step % 3 == 0:
        plant_ys, plant_xs = np.where(pm)
        for py in range(15, WORLD_H - 15, 20):
            for px in range(15, WORLD_W - 15, 20):
                # Check if any plant within 15 tiles
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - px) + np.abs(plant_ys - py)
                    if np.min(dists) < 18:
                        continue
                # Place plant at first empty spot near target
                for r in range(0, 10):
                    placed = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r and r > 0:
                                continue
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # --- STEP 2: Extend wires reactively from power sources ---
    # Find frontier: cells adjacent to powered (wm|pm) that are empty
    if step % 3 == 1:
        powered_src = wm | pm
        # Dilate by 1 to find frontier
        frontier = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        src_ys, src_xs = np.where(powered_src)
        if len(src_xs) > 0:
            for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                ny_arr = src_ys + dy
                nx_arr = src_xs + dx
                valid = (ny_arr >= 0) & (ny_arr < WORLD_H) & (nx_arr >= 0) & (nx_arr < WORLD_W)
                for i in range(len(src_xs)):
                    if valid[i]:
                        ny2, nx2 = int(ny_arr[i]), int(nx_arr[i])
                        if bool(em[ny2, nx2]):
                            frontier[ny2, nx2] = True

            # Among frontier, pick one closest to an unpowered zone or road
            unpowered = zone_tiles & ~near_power
            unpowered_road = rm & ~near_power
            targets = unpowered | unpowered_road
            tys, txs = np.where(targets)
            f_ys, f_xs = np.where(frontier)
            if len(f_xs) > 0 and len(txs) > 0:
                # Pick frontier cell closest to a target
                # Sample to keep fast
                sample_t = min(len(txs), 50)
                t_idx = np.linspace(0, len(txs) - 1, sample_t, dtype=int)
                best_score = 999999
                best_fx, best_fy = -1, -1
                for ti in t_idx:
                    tx, ty = int(txs[ti]), int(tys[ti])
                    dists = np.abs(f_xs - tx) + np.abs(f_ys - ty)
                    mi = np.argmin(dists)
                    if dists[mi] < best_score:
                        best_score = int(dists[mi])
                        best_fx, best_fy = int(f_xs[mi]), int(f_ys[mi])
                if best_fx >= 0:
                    return (Tool.WIRE, best_fx, best_fy)
            elif len(f_xs) > 0:
                # Just extend wire in a useful direction (toward center or map edges)
                # Pick frontier cell farthest from existing power
                idx = (step * 7) % len(f_xs)
                return (Tool.WIRE, int(f_xs[idx]), int(f_ys[idx]))

    # --- STEP 3: Extend roads reactively ---
    if step % 3 == 2:
        # Find roads, extend toward powered empty areas lacking roads
        road_ys, road_xs = np.where(rm)
        powered_empty = em & near_power & ~near_road
        pe_ys, pe_xs = np.where(powered_empty)
        if len(road_xs) > 0 and len(pe_xs) > 0:
            sample_pe = min(len(pe_xs), 30)
            pe_idx = np.linspace(0, len(pe_xs) - 1, sample_pe, dtype=int)
            best_score = 999999
            best_rx, best_ry = -1, -1
            best_tx, best_ty = -1, -1
            for pi in pe_idx:
                tx, ty = int(pe_xs[pi]), int(pe_ys[pi])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                mi = np.argmin(dists)
                d = int(dists[mi])
                if d < best_score:
                    best_score = d
                    best_rx, best_ry = int(road_xs[mi]), int(road_ys[mi])
                    best_tx, best_ty = tx, ty
            if best_rx >= 0:
                # Step toward target
                dx = 0 if best_tx == best_rx else (1 if best_tx > best_rx else -1)
                dy = 0 if best_ty == best_ry else (1 if best_ty > best_ry else -1)
                for nx2, ny2 in [(best_rx + dx, best_ry), (best_rx, best_ry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- Civic services scaled to pop ---
    if pop > 5:
        fire_spots = [
            (8, 8), (58, 8), (110, 8), (8, 50), (110, 50),
            (8, 92), (58, 92), (110, 92), (33, 25), (83, 25),
            (33, 75), (83, 75), (58, 50), (20, 40), (95, 40),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 50:
        police_spots = [
            (15, 12), (45, 12), (75, 12), (105, 12),
            (15, 37), (45, 37), (75, 37), (105, 37),
            (15, 62), (45, 62), (75, 62), (105, 62),
            (15, 87), (45, 87), (75, 87), (105, 87),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (28, 18), (78, 18), (28, 48), (78, 48),
            (28, 72), (78, 72), (53, 30), (103, 30),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 350:
        nuke_spots = [
            (60, 50), (30, 25), (90, 75), (90, 25), (30, 75),
            (10, 50), (110, 50), (60, 15), (60, 85),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 700:
        seaports = [(5, 90), (115, 90), (5, 10), (115, 10)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1200:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near dense powered+roaded zones
    if pop > 80 and step % 7 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:2, :] = False
        park_cands[WORLD_H - 2:, :] = False
        park_cands[:, 0:2] = False
        park_cands[:, WORLD_W - 2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # --- ZONE PLACEMENT: reactive, closed-loop ---
    # Candidate: empty, near road, near power, away from edges
    cand_mask = em & near_road & near_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        tool = pick_tool()
        # Prioritize cells closest to existing zones (cluster growth)
        if total_zones > 1:
            zone_ys, zone_xs = np.where(zone_tiles)
            # Sample existing zones
            sample_z = min(len(zone_xs), 20)
            z_idx = np.linspace(0, len(zone_xs) - 1, sample_z, dtype=int)
            best_dist = np.full(len(cxs), 999999.0)
            for zi in z_idx:
                zx2, zy2 = int(zone_xs[zi]), int(zone_ys[zi])
                d = np.abs(cxs - zx2).astype(float) + np.abs(cys - zy2).astype(float)
                best_dist = np.minimum(best_dist, d)
            order = np.argsort(best_dist)
        else:
            # No zones yet: pick closest to center
            cx_c, cy_c = WORLD_W // 2, WORLD_H // 2
            d = np.abs(cxs - cx_c).astype(float) + np.abs(cys - cy_c).astype(float)
            order = np.argsort(d)

        offset = (step * 13 + pop * 7) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend wire from existing wire toward empty powered area
    wire_ys2, wire_xs2 = np.where(wm | pm)
    if len(wire_xs2) > 0:
        sk = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 100)):
            k = (sk + off * 7) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: extend road
    r_ys, r_xs = np.where(rm)
    if len(r_xs) > 0:
        sk2 = (step * 11) % len(r_xs)
        for off in range(min(len(r_xs), 100)):
            k = (sk2 + off * 5) % len(r_xs)
            rx2, ry2 = int(r_xs[k]), int(r_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

# Strategy: Grid-based city with multiple power plants, dense zone packing
# Key differences from parent:
# 1. Grid road network (horizontal + vertical) instead of just horizontal spines
# 2. Zones placed in blocks between roads
# 3. More aggressive zone placement (50% RES, 30% COM, 20% IND early; balance later)
# 4. Power plants distributed across the grid
# 5. Earlier nuclear power upgrade

def init(obs, state):
    """Bootstrap: central coal plant + initial road grid segment."""
    actions = []
    cx, cy = 60, 50
    # Place power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire spine going left and right
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Wire spine going up and down
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Initial road grid: two horizontal roads
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 2))
        actions.append((Tool.ROAD, cx + dx, cy + 2))
    # Two vertical roads
    for dy in range(-8, 9):
        actions.append((Tool.ROAD, cx - 2, cy + dy))
        actions.append((Tool.ROAD, cx + 2, cy + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid layout: roads every 6 tiles in both directions
    # This creates 5x5 tile blocks between roads for zone placement
    road_xs = list(range(8, WORLD_W - 5, 6))   # vertical roads
    road_ys = list(range(8, WORLD_H - 5, 6))   # horizontal roads

    # Power plant positions: distributed across grid intersections
    plant_positions = [
        (60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
        (60, 20), (60, 80), (15, 50), (105, 50),
        (45, 42), (75, 42), (45, 60), (75, 60),
    ]

    # Determine how many grid areas to activate based on pop
    def grid_radius():
        if pop < 50:    return 10
        if pop < 200:   return 20
        if pop < 500:   return 35
        if pop < 1000:  return 50
        if pop < 2000:  return 70
        return 100

    gr = grid_radius()
    cx0, cy0 = 60, 50  # center

    # Active road_xs and road_ys within grid radius
    active_rxs = [x for x in road_xs if abs(x - cx0) <= gr]
    active_rys = [y for y in road_ys if abs(y - cy0) <= gr]

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Check if we have enough plants for the active area
    plant_count = int(np.sum(pm))
    needed_plants = max(1, len(active_rxs) * len(active_rys) // 40)
    if plant_count < needed_plants:
        for px, py in plant_positions:
            if not ib(px, py): continue
            # Check if plant exists nearby
            x0, x1 = max(0, px - 5), min(WORLD_W, px + 6)
            y0, y1 = max(0, py - 5), min(WORLD_H, py + 6)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                if bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)
                # Try nearby empty spot
                for r in range(1, 6):
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) != r and abs(dy) != r: continue
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID (connect plants to roads) ----
    # Lay wires along horizontal road lines (at road_y positions) and vertical
    # Priority: wire at intersections and along roads to power zones

    # Wire along horizontal spines at each active road_y
    wire_phase = step % 4
    if wire_phase == 0:
        for ry in active_rys:
            for rx in range(max(5, min(active_rxs) - 3), min(WORLD_W - 3, max(active_rxs) + 4)):
                if not ib(rx, ry): continue
                if bool(wm[ry, rx]) or bool(pm[ry, rx]) or bool(rm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                # Check adjacent wire or plant
                for ax, ay in [(rx-1,ry),(rx+1,ry),(rx,ry-1),(rx,ry+1)]:
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        return (Tool.WIRE, rx, ry)

    # Wire along vertical spines
    if wire_phase == 1:
        for rx in active_rxs:
            for ry in range(max(5, min(active_rys) - 3), min(WORLD_H - 3, max(active_rys) + 4)):
                if not ib(rx, ry): continue
                if bool(wm[ry, rx]) or bool(pm[ry, rx]) or bool(rm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                for ax, ay in [(rx-1,ry),(rx+1,ry),(rx,ry-1),(rx,ry+1)]:
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        return (Tool.WIRE, rx, ry)

    # ---- PHASE 3: ROAD GRID ----
    road_phase = step % 4
    if road_phase == 2:
        # Horizontal roads
        for ry in active_rys:
            row_min = max(5, min(active_rxs) - 2)
            row_max = min(WORLD_W - 3, max(active_rxs) + 3)
            for rx in range(row_min, row_max + 1):
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]) or bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                # Place road adjacent to existing road or at start
                for ax, ay in [(rx-1,ry),(rx+1,ry)]:
                    if ib(ax, ay) and bool(rm[ay, ax]):
                        return (Tool.ROAD, rx, ry)
                # Also place if wire is here (road replaces wire for connectivity)
                # Actually don't - wire is power, road is access, keep both

    if road_phase == 3:
        # Vertical roads
        for rx in active_rxs:
            col_min = max(5, min(active_rys) - 2)
            col_max = min(WORLD_H - 3, max(active_rys) + 3)
            for ry in range(col_min, col_max + 1):
                if not ib(rx, ry): continue
                if bool(rm[ry, rx]) or bool(pm[ry, rx]): continue
                if not bool(em[ry, rx]): continue
                for ax, ay in [(rx,ry-1),(rx,ry+1)]:
                    if ib(ax, ay) and bool(rm[ay, ax]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        rr = res_count / total_zones
        cr = com_count / total_zones
        ir = ind_count / total_zones
        # Target: 50% RES, 30% COM, 20% IND (more commercial than parent)
        if pop < 500:
            # Early: mostly RES + COM
            if rr < 0.50: return Tool.RESIDENTIAL
            if cr < 0.30: return Tool.COMMERCIAL
            return Tool.INDUSTRIAL
        else:
            # Later: balanced
            if ir < 0.22: return Tool.INDUSTRIAL
            if cr < 0.30: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by distance from center (closer = better early, more spread later)
        dist_from_center = np.sqrt((cys_arr - cy0)**2 + (cxs_arr - cx0)**2)
        # Prefer mid-range distances for variety
        if pop < 500:
            order = np.argsort(dist_from_center)  # close first
        else:
            order = np.argsort(dist_from_center)  # still close first but more spread
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys_arr, road_xs_arr = np.where(rm)
    if len(road_xs_arr) > 0:
        step_k = (step * 11) % max(len(road_xs_arr), 1)
        for offset in range(min(len(road_xs_arr), 60)):
            k = (step_k + offset * 7) % len(road_xs_arr)
            rx2, ry2 = int(road_xs_arr[k]), int(road_ys_arr[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(nbr_power[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(15, WORLD_W, 22) for py2 in range(15, WORLD_H, 22)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [(25,22),(60,22),(95,22),(25,52),(60,52),(95,52),(25,78),(60,78),(95,78)]
        for sx, sy in stadiums:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        seaports = [(8,92),(112,92),(8,8),(112,8),(60,96),(60,4)]
        for sx, sy in seaports:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [(40,5),(80,5),(40,93),(80,93),(5,40),(5,60),(113,40),(113,60)]
        for sx, sy in airports:
            if ib(sx,sy) and bool(em[sy,sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER (earlier upgrade) ----
    if pop > 800 and step % 2 == 0:
        nuclear_spots = [
            (60,50),(30,25),(90,25),(30,75),(90,75),
            (60,20),(60,80),(15,50),(105,50),
            (45,38),(75,38),(45,62),(75,62),
            (10,15),(110,15),(10,85),(110,85),
        ]
        for nx2, ny2 in nuclear_spots:
            if ib(nx2,ny2) and bool(em[ny2,nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value ----
    if pop > 300 and step % 4 == 0:
        park_ys_arr, park_xs_arr = np.where(em & nbr_road & nbr_power)
        if len(park_xs_arr) > 0:
            idx = (step * 17) % len(park_xs_arr)
            py2, px2 = int(park_ys_arr[idx]), int(park_xs_arr[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new coal plant ----
    for px, py in plant_positions:
        if ib(px, py) and bool(em[py, px]):
            return (Tool.COALPOWER, px, py)

    return None

def init(obs, state):
    """Bootstrap: two nuclear plants in center with cross wire + road grid"""
    actions = []
    # Two coal plants near center
    actions.append((Tool.COALPOWER, 40, 50))
    actions.append((Tool.COALPOWER, 80, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(1, 99):
        actions.append((Tool.WIRE, 40, y))
    for y in range(1, 99):
        actions.append((Tool.WIRE, 80, y))
    # A few horizontal roads
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 45))
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 55))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Different zone mix: 45% res, 30% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Grid layout: 3 horizontal road corridors per band, wire every 10 rows
    # Bands at y: 20, 35, 50, 65, 80
    # Roads flanking each band at y-2, y+2
    # Wire at y: 10, 20, 30, 40, 50, 60, 70, 80, 90
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]
    # Roads between wire corridors
    road_rows = [17, 23, 27, 33, 37, 43, 47, 53, 57, 63, 67, 73, 77, 83, 87, 93]
    road_cols = [10, 20, 35, 50, 65, 80, 95, 110]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure coal/nuclear plants spread across map
    if phase == 0:
        plant_grid = []
        for py in range(15, 95, 20):
            for px in range(15, 115, 20):
                plant_grid.append((px, py))
        for px, py in plant_grid:
            x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
            y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1-2: Fill horizontal wire rows
    if phase in (1, 2):
        target_rows = wire_rows if phase == 1 else [15, 25, 35, 45, 55, 65, 75, 85, 95]
        for wr in target_rows:
            if wr >= WORLD_H:
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    has_adj = (wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))) or \
                              (wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1])))
                    if has_adj and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 3-4: Fill vertical wire cols
    if phase in (3, 4):
        target_cols = wire_cols if phase == 3 else [5, 22, 37, 52, 67, 82, 97, 112]
        for wc in target_cols:
            if wc >= WORLD_W:
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    has_adj = (wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))) or \
                              (wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc])))
                    if has_adj and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 5-6: Build horizontal roads
    if phase == 5:
        for rr in road_rows:
            if rr >= WORLD_H:
                continue
            # Build from left to right
            for rx in range(1, WORLD_W - 1):
                if bool(em[rr, rx]) and not bool(pm[rr, rx]):
                    adj = (rx > 0 and bool(rm[rr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[rr, rx+1])) or \
                          (rr > 0 and bool(rm[rr-1, rx])) or \
                          (rr < WORLD_H-1 and bool(rm[rr+1, rx]))
                    if adj or rx == 1:
                        return (Tool.ROAD, rx, rr)

    # Phase 6: Build vertical roads
    if phase == 6:
        for rc in road_cols:
            if rc >= WORLD_W:
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, rc]) and not bool(pm[ry, rc]):
                    adj = (ry > 0 and bool(rm[ry-1, rc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, rc])) or \
                          (rc > 0 and bool(rm[ry, rc-1])) or \
                          (rc < WORLD_W-1 and bool(rm[ry, rc+1]))
                    if adj or ry == 1:
                        return (Tool.ROAD, rc, ry)

    # Phase 7: Wire unpowered zones
    if phase == 7:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 8: Wire roads without power
    if phase == 8:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 9: Upgrade coal to nuclear when pop grows
    if phase == 9 and pop > 800:
        nuke_spots = [
            (60, 5), (60, 95), (5, 50), (115, 50),
            (20, 20), (100, 20), (20, 80), (100, 80),
            (40, 5), (80, 5), (40, 95), (80, 95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Civic buildings - scale with population
    if pop > 10:
        fire_spots = [
            (5, 5), (60, 5), (115, 5),
            (5, 30), (115, 30),
            (5, 50), (115, 50),
            (5, 70), (115, 70),
            (5, 95), (60, 95), (115, 95),
            (30, 20), (60, 20), (90, 20),
            (30, 50), (90, 50),
            (30, 80), (60, 80), (90, 80),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (15, 10), (45, 10), (75, 10), (105, 10),
            (15, 35), (45, 35), (75, 35), (105, 35),
            (15, 60), (45, 60), (75, 60), (105, 60),
            (15, 85), (45, 85), (75, 85), (105, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [
            (20, 15), (60, 15), (100, 15),
            (20, 45), (60, 45), (100, 45),
            (20, 75), (60, 75), (100, 75),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(5, 90), (115, 90), (60, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 90), (70, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 7) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (closed-loop primary action) ----
    # Build in two neighborhoods: left half and right half, reacting to pop
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    # Exclude wire/road rows from zoning
    all_wire_rows = wire_rows + [15, 25, 35, 45, 55, 65, 75, 85, 95]
    all_road_rows = road_rows
    for wr in all_wire_rows + all_road_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols + [5, 22, 37, 52, 67, 82, 97, 112]:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            cand_mask[:, max(0, rc-1):min(WORLD_W, rc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Two-neighborhood approach: left cluster (x<60) and right cluster (x>=60)
        # Build left first, then expand right as pop grows
        if pop < 100:
            # Dense left-center cluster
            active_centers = [
                (30, 50), (30, 40), (30, 60),
                (45, 50), (45, 40), (45, 60),
                (20, 50), (20, 40), (20, 60),
            ]
        elif pop < 400:
            # Full left half
            active_centers = []
            for row in range(6):
                for col in range(4):
                    cx = 12 + col * 12
                    cy = 15 + row * 14
                    active_centers.append((cx, cy))
        elif pop < 900:
            # Both halves medium density
            active_centers = []
            for row in range(7):
                for col in range(8):
                    cx = 10 + col * 14
                    cy = 12 + row * 12
                    active_centers.append((cx, cy))
        elif pop < 2000:
            # Dense full map
            active_centers = []
            for row in range(9):
                for col in range(10):
                    cx = 8 + col * 11
                    cy = 8 + row * 10
                    active_centers.append((cx, cy))
        else:
            # Maximum coverage
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and road stubs."""
    actions = []
    # Left cluster power plant at (30, 50)
    actions.append((Tool.COALPOWER, 30, 50))
    # Right cluster power plant at (90, 50)
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine connecting both plants through center
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire from left plant
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 30, y))
    # Vertical wire from right plant
    for y in range(44, 57):
        if y != 50:
            actions.append((Tool.WIRE, 90, y))
    # Roads flanking left plant
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 29, 50 + dy))
        actions.append((Tool.ROAD, 31, 50 + dy))
    # Roads flanking right plant
    for dy in range(-3, 4):
        actions.append((Tool.ROAD, 89, 50 + dy))
        actions.append((Tool.ROAD, 91, 50 + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # More balanced mix: 25% industrial, 30% commercial, 45% residential
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if bool(pm[nr, nc]):
                    return False
                if bool(rm[nr, nc]) or bool(wm[nr, nc]):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # 6 neighborhoods in 2 rows x 3 cols layout
    # Row 1: y=30, Row 2: y=70, Cols: x=20, 60, 100
    neighborhood_configs = []
    for col_i, cx in enumerate([20, 60, 100]):
        for row_i, cy in enumerate([25, 50, 75]):
            neighborhood_configs.append((cx, cy, col_i * 3 + row_i))

    def num_active():
        if pop < 50:   return 1
        if pop < 200:  return 2
        if pop < 500:  return 3
        if pop < 900:  return 5
        if pop < 1500: return 7
        if pop < 2500: return 9
        return 9

    active = neighborhood_configs[:num_active()]

    # ---- 1. ENSURE POWER PLANTS for each active neighborhood ----
    for (px, py, idx) in active:
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        if not np.any(pm[y0:y1, x0:x1]):
            for r in range(0, 15):
                placed = False
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)
                if placed:
                    break

    # ---- 2. BUILD WIRE SPINES (vertical) for each active neighborhood ----
    for (px, py, idx) in active:
        wc = px
        pop_ext = min(18, pop // 50)
        spine_top = max(2, py - 18 - pop_ext)
        spine_bot = min(WORLD_H - 3, py + 18 + pop_ext)

        wire_rows_here = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        plant_here = [r for r in range(WORLD_H) if ib(wc, r) and bool(pm[r, wc])]
        all_power_rows = sorted(set(wire_rows_here + plant_here))

        if not all_power_rows:
            plant_ys, plant_xs = np.where(pm)
            if len(plant_xs) > 0:
                dists = np.abs(plant_xs - wc) + np.abs(plant_ys - py)
                best = int(np.argmin(dists))
                bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                if bpx != wc:
                    step_x = 1 if wc > bpx else -1
                    nx = bpx + step_x
                    if ib(nx, bpy) and bool(em[bpy, nx]) and not bool(pm[bpy, nx]):
                        return (Tool.WIRE, nx, bpy)
                else:
                    step_y = 1 if py > bpy else -1
                    ny = bpy + step_y
                    if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                        return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(all_power_rows)
            max_wr = max(all_power_rows)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and (bool(em[nr, wc]) or bool(wm[nr, wc])) and not bool(pm[nr, wc]):
                    return (Tool.WIRE, wc, nr)

    # ---- 3. HORIZONTAL WIRE CONNECTIONS between same-row neighborhoods ----
    row_groups = {}
    for (px, py, idx) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append(px)
    for row_y, wcs in row_groups.items():
        if len(wcs) < 2:
            continue
        wcs_sorted = sorted(wcs)
        for i in range(len(wcs_sorted) - 1):
            wc1, wc2 = wcs_sorted[i], wcs_sorted[i + 1]
            for cx in range(wc1 + 1, wc2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # ---- 4. BUILD ROADS flanking wire spines (both sides) ----
    for (px, py, idx) in active:
        wc = px
        rl, rr = wc - 2, wc + 2  # roads 2 tiles away from wire
        wire_rows_here = [r for r in range(WORLD_H) if ib(wc, r) and bool(wm[r, wc])]
        if not wire_rows_here:
            continue
        cycle = (step + idx * 7) % max(len(wire_rows_here), 1)
        for offset in range(min(len(wire_rows_here), 20)):
            wr = wire_rows_here[(cycle + offset) % len(wire_rows_here)]
            for road_x in [rl, rr]:
                if ib(road_x, wr) and bool(em[wr, road_x]) and not bool(pm[wr, road_x]):
                    return (Tool.ROAD, road_x, wr)

    # ---- 5. HORIZONTAL ROADS connecting neighborhoods ----
    for (px, py, idx) in active:
        # Road corridor at py-2 and py+2 (parallel to wire spine)
        for road_y in [py - 2, py + 2]:
            if not (0 < road_y < WORLD_H - 1):
                continue
            for dx in range(-15, 16):
                rx = px + dx
                if ib(rx, road_y) and bool(em[road_y, rx]) and not bool(pm[road_y, rx]):
                    near_w = any(
                        ib(rx + d, road_y) and (bool(wm[road_y, rx + d]) or bool(pm[road_y, rx + d])
                                                 or bool(rm[road_y, rx + d]))
                        for d in [-1, 1]
                    )
                    if near_w:
                        return (Tool.ROAD, rx, road_y)

    # ---- 6. CROSS ROADS connecting top and bottom neighborhoods ----
    for col_i, cx in enumerate([20, 60, 100]):
        # Vertical road corridors at cx-2 and cx+2
        for road_x in [cx - 2, cx + 2]:
            if not (0 < road_x < WORLD_W - 1):
                continue
            col_road = [r for r in range(WORLD_H) if ib(road_x, r) and bool(rm[r, road_x])]
            col_wire = [r for r in range(WORLD_H) if ib(cx, r) and bool(wm[r, cx])]
            if not col_wire:
                continue
            # Find gaps in vertical road adjacent to wire
            for wy in col_wire:
                if ib(road_x, wy) and bool(em[wy, road_x]) and not bool(pm[wy, road_x]):
                    adj_road = any(
                        ib(road_x, wy + d) and bool(rm[wy + d, road_x])
                        for d in [-1, 1]
                    )
                    if adj_road or (len(col_road) == 0 and len(col_wire) > 0):
                        return (Tool.ROAD, road_x, wy)

    # ---- 7. PHASE-BASED infrastructure ----
    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        wire_rows_targets = [25, 50, 75]
        for wr in wire_rows_targets:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(row_power[wx]):
                    left = wx > 0 and bool(row_power[wx - 1])
                    right = wx < WORLD_W - 1 and bool(row_power[wx + 1])
                    if (left or right) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        wire_cols_targets = [20, 60, 100]
        for wc in wire_cols_targets:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(col_power[wy]):
                    up = wy > 0 and bool(col_power[wy - 1])
                    dn = wy < WORLD_H - 1 and bool(col_power[wy + 1])
                    if (up or dn) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads at row y=25 horizontal
        for road_y in [23, 27, 48, 52, 73, 77]:
            row_wire = None
            for wy in [25, 50, 75]:
                if abs(road_y - wy) <= 4:
                    row_wire = wm[wy, :] | pm[wy, :]
                    break
            if row_wire is None:
                continue
            if not np.any(row_wire):
                continue
            for rx in range(5, WORLD_W - 5):
                if bool(row_wire[rx]) and bool(em[road_y, rx]) and not bool(pm[road_y, rx]):
                    return (Tool.ROAD, rx, road_y)

    elif phase == 3:
        # Wire toward unpowered roads
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys2, wire_xs2 = np.where(wm | pm)
            if len(wire_xs2) > 0:
                dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
                bi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs2[bi]), int(wire_ys2[bi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 4:
        # Extend roads toward powered unroaded areas
        road_ys2, road_xs2 = np.where(rm)
        if len(road_xs2) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H - 3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W - 3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists2 = np.abs(road_xs2 - tx) + np.abs(road_ys2 - ty)
                best_ri = int(np.argmin(dists2))
                brx, bry = int(road_xs2[best_ri]), int(road_ys2[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx3, ny3 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.ROAD, nx3, ny3)

    elif phase == 5:
        # Dense road grid near power - grid spacing 3 for denser network
        for gy in range(5, WORLD_H - 5, 3):
            for gx in range(5, WORLD_W - 5, 3):
                if not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    adj = any(
                        ib(gx + dx2, gy + dy2) and bool(rm[gy + dy2, gx + dx2])
                        for dx2, dy2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]
                    )
                    if adj:
                        return (Tool.ROAD, gx, gy)

    elif phase == 6:
        # Wire intersection connectors at neighborhood centers
        for (px, py, idx) in active:
            for wr in [py]:
                for wc in [px]:
                    if not ib(wc, wr):
                        continue
                    if bool(em[wr, wc]) and not bool(pm[wr, wc]):
                        row_ok = (wc > 0 and bool(wm[wr, wc - 1])) or \
                                 (wc < WORLD_W - 1 and bool(wm[wr, wc + 1]))
                        col_ok = (wr > 0 and bool(wm[wr - 1, wc])) or \
                                 (wr < WORLD_H - 1 and bool(wm[wr + 1, wc]))
                        if row_ok or col_ok:
                            return (Tool.WIRE, wc, wr)

    elif phase == 7:
        # Add nuclear power when pop is high enough (cleaner, more powerful)
        if pop > 1000:
            nuke_locs = [
                (5, 5), (115, 5), (5, 94), (115, 94),
                (60, 5), (5, 50), (115, 50), (60, 94),
                (40, 15), (80, 15), (40, 85), (80, 85),
            ]
            for nx2, ny2 in nuke_locs:
                if ib(nx2, ny2):
                    x0, x1 = max(0, nx2 - 8), min(WORLD_W, nx2 + 9)
                    y0, y1 = max(0, ny2 - 8), min(WORLD_H, ny2 + 9)
                    if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                        return (Tool.NUCLEARPOWER, nx2, ny2)

    elif phase == 8:
        # Wire corridors to connect nuclear plants back to grid
        wire_ys3, wire_xs3 = np.where(wm | pm)
        if len(wire_xs3) > 0:
            # Find isolated power cells
            all_pm_ys, all_pm_xs = np.where(pm)
            for pi in range(len(all_pm_xs)):
                px2, py2 = int(all_pm_xs[pi]), int(all_pm_ys[pi])
                # Check if this plant is connected to main grid
                x0, x1 = max(0, px2 - 3), min(WORLD_W, px2 + 4)
                y0, y1 = max(0, py2 - 3), min(WORLD_H, py2 + 4)
                local_wire = np.any(wm[y0:y1, x0:x1])
                if not local_wire:
                    # Wire toward nearest existing wire
                    dists = np.abs(wire_xs3 - px2) + np.abs(wire_ys3 - py2)
                    bi = int(np.argmin(dists))
                    bwx, bwy = int(wire_xs3[bi]), int(wire_ys3[bi])
                    dx = 0 if px2 == bwx else (1 if bwx > px2 else -1)
                    dy = 0 if py2 == bwy else (1 if bwy > py2 else -1)
                    nx2 = px2 + dx
                    ny2 = py2 + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    else:  # phase == 9
        # Extra vertical roads at spacing
        for (px, py, idx) in active:
            for road_x in [px - 3, px + 3]:
                if not (0 < road_x < WORLD_W - 1):
                    continue
                for dy in range(-15, 16):
                    road_y = py + dy
                    if not ib(road_x, road_y):
                        continue
                    if bool(em[road_y, road_x]) and not bool(pm[road_y, road_x]):
                        # Only if near wire
                        nw = any(
                            ib(road_x + d, road_y) and (bool(wm[road_y, road_x + d]) or bool(pm[road_y, road_x + d]))
                            for d in [-3, -2, -1, 1, 2, 3]
                        ) or any(
                            ib(road_x, road_y + d) and (bool(rm[road_y + d, road_x]))
                            for d in [-1, 1]
                        )
                        if nw:
                            return (Tool.ROAD, road_x, road_y)

    # ---- 8. CIVIC SERVICES (react to population level) ----
    if pop > 60:
        fire_positions = [
            (15, 10), (55, 10), (95, 10),
            (15, 38), (55, 38), (95, 38),
            (15, 62), (55, 62), (95, 62),
            (15, 88), (55, 88), (95, 88),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_positions = [
            (35, 15), (65, 15), (95, 15),
            (20, 42), (50, 42), (80, 42), (110, 42),
            (35, 68), (65, 68), (95, 68),
            (20, 88), (80, 88),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (40, 30), (80, 30), (40, 70), (80, 70),
            (60, 10), (60, 90), (20, 50), (100, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_road[sy, sx]):
