    # Find frontier: empty cells adjacent to power source
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    # Keep border safe
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    # Look for unpowered plants to wire up first
    unpowered_plants = [(int(plant_xs[k]), int(plant_ys[k])) for k in range(len(plant_xs))
                        if not bool(near_power[int(plant_ys[k]), int(plant_xs[k])])]

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0 and unpowered_plants:
        best_dist = 1e9
        best_k = 0
        for i in range(min(len(wxs), 300)):
            cx, cy = int(wxs[i]), int(wys[i])
            d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:5])
            if d < best_dist:
                best_dist = d
                best_k = i
        return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Wire toward unpowered zones
    if len(wxs) > 0:
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(min(20, len(zxs))))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Wire toward large unpowered empty areas
    if len(wxs) > 0:
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0 and len(wxs) > 0:
            # Sample some unpowered empty cells
            sample_idx = np.arange(0, len(upxs), max(1, len(upxs)//50))
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 200)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 2: Build road grid reactively ---
    # Road grid spacing depends on population density
    road_spacing = 6 if pop < 500 else 5

    road_targets = []
    for gy in range(road_spacing, WORLD_H - road_spacing, road_spacing):
        for gx in range(road_spacing, WORLD_W - road_spacing, road_spacing):
            road_targets.append((gx, gy))

    # Find road targets that are powered but lack road
    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        # Find candidate road cells adjacent to existing roads
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:30]
            for i in range(min(len(rxs2), 400)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Place road directly at target if empty
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 3: Zone placement (closed-loop, reactive) ---
    def zone_clear(zx, zy):
        """Check if 3x3 area centered at (zx,zy) is placeable"""
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    cys_arr, cxs_arr = np.where(zone_cand)

    if len(cxs_arr) > 0:
        # Score: prefer close to roads, not too close to other zones
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.full(len(cxs_arr), 10.0)

        # Prefer close to road, spread from existing zones
        score = road_dist * 2.0 + np.maximum(0, 6 - zone_dist) * 3.0

        order = np.argsort(score)
        off = (step * 17 + pop * 3) % max(len(order), 1)

        # Determine zone tool based on current ratios
        def pick_tool():
            if total_zones == 0:
                return Tool.RESIDENTIAL
            ir = ind_count / max(total_zones, 1)
            cr = com_count / max(total_zones, 1)
            rr = res_count / max(total_zones, 1)
            # Target: 50% res, 30% com, 20% ind
            if ir < 0.20:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL

        # Use step-based cycling but override with ratio correction
        step_cycle = step % 10
        if step_cycle < 5:
            tool = Tool.RESIDENTIAL
        elif step_cycle < 8:
            tool = Tool.COMMERCIAL
        else:
            tool = Tool.INDUSTRIAL

        # Override if ratios are off
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.15 or cr < 0.20:
            tool = pick_tool()

        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 4: Civic services scaled to population ---
    if pop > 100:
        for fy in range(12, 90, 14):
            for fx in range(12, 110, 14):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(near_road[fy, fx]) and bool(near_power[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 300:
        for py2 in range(15, 90, 15):
            for px2 in range(15, 108, 15):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(near_road[py2, px2]) and bool(near_power[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 500:
        for pky in range(8, 92, 8):
            for pkx in range(8, 112, 8):
                if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 800:
        stadium_locs = [(25, 20), (95, 20), (25, 80), (95, 80),
                        (60, 15), (60, 85), (10, 50), (110, 50),
                        (45, 40), (75, 40), (45, 60), (75, 60)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(20, 20), (100, 20), (20, 80), (100, 80),
                     (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (65, 8), (55, 90), (65, 90),
                        (8, 40), (110, 40), (8, 60), (110, 60)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91),
                        (15, 25), (105, 25), (15, 75), (105, 75)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: roads near power plants ---
    if len(plant_xs) > 0:
        k = step % len(plant_xs)
        px3, py3 = int(plant_xs[k]), int(plant_ys[k])
        for dx3, dy3 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.ROAD, nx3, ny3)
        for dx4, dy4 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx4, ny4 = px3 + dx4, py3 + dy4
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.WIRE, nx4, ny4)

    return None

def init(obs, state):
    """Bootstrap: two coal plants connected by wire, with road access."""
    actions = []
    # Primary coal plant at center-left
    actions.append((Tool.COALPOWER, 40, 50))
    # Secondary coal plant at center-right
    actions.append((Tool.COALPOWER, 80, 50))
    # Horizontal wire connecting them through center
    for x in range(41, 80):
        actions.append((Tool.WIRE, x, 50))
    # Roads above and below the wire spine
    for x in range(35, 86, 3):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    # Vertical wires down from plants
    for y in range(45, 50):
        actions.append((Tool.WIRE, 40, y))
        actions.append((Tool.WIRE, 80, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 50% RES, 25% COM, 25% IND
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if rm[nr, nc] or wm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    near_power = dilate(wm | pm, 7)
    near_road = dilate(rm, 2)

    # Use a denser grid: wire rows every 12, wire cols every 15
    wire_rows = [8, 20, 32, 44, 56, 68, 80, 92]
    wire_cols = [8, 23, 38, 53, 68, 83, 98, 113]

    # Plant grid: 3x3 grid spread across map
    plant_positions = [
        (20, 16), (60, 16), (100, 16),
        (20, 50), (60, 50), (100, 50),
        (20, 84), (60, 84), (100, 84),
        # Edge plants
        (5, 33), (115, 33), (5, 67), (115, 67),
    ]

    # ---- PHASE 0: Ensure plants exist across map ----
    for px, py in plant_positions:
        x0, x1 = max(0, px - 10), min(WORLD_W, px + 11)
        y0, y1 = max(0, py - 10), min(WORLD_H, py + 11)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 12

    # ---- PHASE 0-1: Horizontal wire corridors ----
    if phase in (0, 1):
        for wr in wire_rows:
            if wr >= WORLD_H:
                continue
            row_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = int(np.argmin(dists))
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_power[wx]):
                        left = wx > 0 and bool(row_power[wx - 1])
                        right = wx < WORLD_W - 1 and bool(row_power[wx + 1])
                        if (left or right) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # ---- PHASE 2-3: Vertical wire corridors ----
    elif phase in (2, 3):
        for wc in wire_cols:
            if wc >= WORLD_W:
                continue
            col_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = int(np.argmin(dists))
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2 + step_x, wc + step_x, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_power[wy]):
                        up = wy > 0 and bool(col_power[wy - 1])
                        dn = wy < WORLD_H - 1 and bool(col_power[wy + 1])
                        if (up or dn) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ---- PHASE 4-5: Roads parallel to horizontal wire corridors (BOTH sides) ----
    elif phase in (4, 5):
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1, -2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # ---- PHASE 6-7: Roads parallel to vertical wire corridors ----
    elif phase in (6, 7):
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1, -2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    # ---- PHASE 8: Wire intersection connectors ----
    elif phase == 8:
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc - 1])) or \
                         (wc < WORLD_W - 1 and bool(wm[wr, wc + 1]))
                col_ok = (wr > 0 and bool(wm[wr - 1, wc])) or \
                         (wr < WORLD_H - 1 and bool(wm[wr + 1, wc]))
                if (row_ok or col_ok) and bool(em[wr, wc]) and not bool(pm[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    # ---- PHASE 9: Wire toward unpowered roads ----
    elif phase == 9:
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 10: Extend roads toward powered unroaded areas ----
    elif phase == 10:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            target_mask = near_power & ~near_road & em
            target_mask[0:3, :] = False
            target_mask[WORLD_H - 3:, :] = False
            target_mask[:, 0:3] = False
            target_mask[:, WORLD_W - 3:] = False
            tys, txs = np.where(target_mask)
            if len(txs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = int(np.argmin(dists))
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- PHASE 11: Dense road grid near power ----
    else:
        road_grid = []
        for gy in range(5, WORLD_H - 5, 3):
            for gx in range(5, WORLD_W - 5, 3):
                if not bool(rm[gy, gx]) and bool(near_power[gy, gx]) and bool(em[gy, gx]):
                    road_grid.append((gx, gy))
        if road_grid:
            adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
            for dy2, dx2 in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                shifted = np.zeros_like(rm)
                if dy2 == -1: shifted[:-1, :] = rm[1:, :]
                elif dy2 == 1: shifted[1:, :] = rm[:-1, :]
                elif dx2 == -1: shifted[:, :-1] = rm[:, 1:]
                elif dx2 == 1: shifted[:, 1:] = rm[:, :-1]
                adj_to_road |= shifted
            for gx, gy in road_grid:
                if bool(adj_to_road[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- CIVIC SERVICES (reactive) ----
    if pop > 50:
        fire_positions = [
            (18, 8), (53, 8), (88, 8), (113, 8),
            (18, 28), (53, 28), (88, 28), (113, 28),
            (18, 44), (53, 44), (88, 44), (113, 44),
            (18, 60), (53, 60), (88, 60), (113, 60),
            (18, 76), (53, 76), (88, 76), (113, 76),
            (18, 92), (53, 92), (88, 92), (113, 92),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_positions = [
            (35, 14), (75, 14), (35, 38), (75, 38),
            (35, 62), (75, 62), (35, 86), (75, 86),
            (10, 26), (110, 26), (10, 74), (110, 74),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 26), (90, 26), (30, 74), (90, 74),
            (60, 10), (60, 90), (10, 50), (110, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(near_power[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (40, 5), (80, 5), (40, 94), (80, 94),
            (5, 33), (115, 33), (5, 67), (115, 67),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1500:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks near roads to boost land value
    if pop > 150 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H - 3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W - 3:] = False
        pys4, pxs4 = np.where(park_cands)
        if len(pxs4) > 0:
            idx = (step * 31 + pop * 3) % len(pxs4)
            return (Tool.PARK, int(pxs4[idx]), int(pys4[idx]))

    # ---- ZONE PLACEMENT (closed-loop, primary objective) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H - 4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W - 4:] = False
    # Avoid wire corridors (2-tile buffer)
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0, wr - 2):min(WORLD_H, wr + 3), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0, wc - 2):min(WORLD_W, wc + 3)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 3)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            # Prefer clustering near existing zones
            scores[i] = 3.0 if bool(zone_near[y, x]) else 0.0
            # Slight preference for map center
            scores[i] += 1.0 / (1.0 + abs(x - 60) / 60.0 + abs(y - 50) / 50.0)
            # Bonus for being near road + power intersection (well-served)
            scores[i] += 0.5 * (1.0 if bool(near_road[y, x]) else 0.0)

        order = np.argsort(-scores)
        # Use step-based offset to avoid always picking same spot
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- FALLBACK: extend road from existing roads into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: new coal plant near unpowered area ----
    all_hoods = [(cx, cy) for cy in range(8, 100, 14) for cx in range(8, 120, 18)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + cross roads"""
    actions = []
    # Two coal plants: left-center and right-center
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire connecting them horizontally through center
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(42, 50):
        actions.append((Tool.WIRE, 30, y))
    for y in range(51, 58):
        actions.append((Tool.WIRE, 30, y))
    for y in range(42, 50):
        actions.append((Tool.WIRE, 90, y))
    for y in range(51, 58):
        actions.append((Tool.WIRE, 90, y))
    # Horizontal roads above and below wire spine
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 43))
        actions.append((Tool.ROAD, x, 57))
    # Vertical roads at plants
    for y in range(38, 63):
        actions.append((Tool.ROAD, 30, y))
        actions.append((Tool.ROAD, 90, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure power plants cover the map densely ---
    # Use a reactive grid: check if area near candidate is already covered
    for py in range(10, 95, 20):
        for px in range(10, 115, 20):
            if not ib(px, py):
                continue
            x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
            y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
            if not np.any(pm[y0:y1, x0:x1]):
                # No plant nearby — place one if empty
                if bool(em[py, px]):
                    return (Tool.COALPOWER, px, py)
                # Try nearby cells
                for dy in range(-2, 3):
                    for dx in range(-2, 3):
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Extend wire from existing power sources toward unpowered zones ---
    # Find cells adjacent to power that are empty and not road
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    # Unpowered zones need wire extended to them
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False; wire_cand[WORLD_H-2:, :] = False
        wire_cand[:, 0:2] = False; wire_cand[:, WORLD_W-2:] = False
        wys, wxs = np.where(wire_cand)
        zys, zxs = np.where(unpowered_zones)
        if len(wxs) > 0 and len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            sample_z = min(20, len(zxs))
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(zxs[j])) + abs(cy - int(zys[j])) for j in range(sample_z))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # Also extend wire toward large unpowered empty areas
    unpowered_empty = em & ~near_power
    if np.any(unpowered_empty):
        wire_cand = em & ~rm & ~zone_tiles & adj_to_power
        wire_cand[0:2, :] = False; wire_cand[WORLD_H-2:, :] = False
        wire_cand[:, 0:2] = False; wire_cand[:, WORLD_W-2:] = False
        wys, wxs = np.where(wire_cand)
        upys, upxs = np.where(unpowered_empty)
        if len(wxs) > 0 and len(upxs) > 0:
            rng = np.random.RandomState(step % 997)
            sample_idx = rng.choice(len(upxs), min(30, len(upxs)), replace=False)
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Build roads reactively — extend toward powered unpaved areas ---
    # Road grid every 6 tiles
    road_grid = []
    for gy in range(6, 97, 6):
        for gx in range(6, 117, 6):
            road_grid.append((gx, gy))

    powered_unroaded = [(gx, gy) for gx, gy in road_grid
                        if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if powered_unroaded:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False; road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False; road_cand[:, WORLD_W-2:] = False
        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            targets_sample = powered_unroaded[:30]
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            # Place directly at target if empty
            for gx, gy in powered_unroaded[:5]:
                if bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement — close to roads and power, mixed zoning ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False; zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False; zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer close to road, some spread from existing zones
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.full(len(cxs_arr), 0.0)

        # Score: close to road is good, not too close to other zones (spread out)
        score = road_dist * 1.0 + np.maximum(0, 6 - zone_dist) * 1.5

        order = np.argsort(score)
        # Pick tool based on population ratios (reactive)
        tool = pick_tool()
        # But vary by step to avoid mono-culture
        step_mod = step % 10
        if total_zones > 10:
            if step_mod < 5:
                tool = Tool.RESIDENTIAL
            elif step_mod < 7:
                tool = Tool.COMMERCIAL
            else:
                tool = Tool.INDUSTRIAL
            # Override if ratios are far off
            if ind_count / max(total_zones, 1) < 0.15 or com_count / max(total_zones, 1) < 0.20:
                tool = pick_tool()

        off = (step * 17 + pop * 3) % max(len(order), 1)
        for i in range(min(len(order), 600)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services based on population ---
    if pop > 100:
        for fsy in range(9, 96, 9):
            for fsx in range(9, 116, 9):
                if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 300:
        for psy in range(12, 92, 12):
            for psx in range(12, 112, 12):
                if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 500:
        for pky in range(8, 96, 8):
            for pkx in range(8, 116, 8):
                if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 700:
        stadium_locs = [(25, 20), (95, 20), (25, 80), (95, 80),
                        (60, 15), (60, 85), (15, 50), (105, 50)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1200:
        nuke_locs = [(60, 50), (20, 25), (100, 25), (20, 75), (100, 75),
                     (40, 10), (80, 10), (40, 90), (80, 90)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 2000:
        airport_locs = [(55, 8), (75, 8), (55, 91), (75, 91)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: wire/road near existing power plants ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (4, 0), (0, 4), (2, 2), (-2, 2)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px2 + dx3, py2 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire cross through center
    for x in range(55, 66):
        actions.append((Tool.WIRE, x, 50))
    for y in range(45, 56):
        actions.append((Tool.WIRE, 60, y))
    # Horizontal roads near center
    for x in range(50, 72):
        actions.append((Tool.ROAD, x, 47))
