def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Zone mix: 50% residential, 25% commercial, 25% industrial
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        m = mask.astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= m[:-d, :]
            result[:-d, :] |= m[d:, :]
            result[:, d:] |= m[:, :-d]
            result[:, :-d] |= m[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Tighter grid: roads every 6 tiles, wires in between
    road_rows = list(range(8, 96, 6))
    road_cols = list(range(8, 116, 6))

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    # ---- CLOSED-LOOP REACTIVE PHASES ----

    # Phase 1: Ensure power plants exist near unpowered road areas
    # Count plants
    plant_count = int(np.sum(pm))
    unpowered_road = rm & ~near_power
    upr_count = int(np.sum(unpowered_road))

    if upr_count > 10 and step % 8 < 2:
        # Find centroid of unpowered roads and place a plant nearby
        uys, uxs = np.where(unpowered_road)
        if len(uxs) > 0:
            tidx = (step * 31) % len(uxs)
            tx, ty = int(uxs[tidx]), int(uys[tidx])
            for r in range(2, 15):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) == r or abs(dy) == r:
                            nx2, ny2 = tx+dx, ty+dy
                            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                # Check no plant within 20 tiles
                                x0, x1 = max(0, nx2-20), min(WORLD_W, nx2+21)
                                y0, y1 = max(0, ny2-20), min(WORLD_H, ny2+21)
                                if not bool(np.any(pm[y0:y1, x0:x1])):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 2: Extend wires from plants/wires toward unpowered roads
    if step % 8 in (2, 3) and upr_count > 5:
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            uys2, uxs2 = np.where(unpowered_road)
            if len(uxs2) > 0:
                tidx2 = (step * 23 + 7) % len(uxs2)
                tx2, ty2 = int(uxs2[tidx2]), int(uys2[tidx2])
                dists = np.abs(wire_xs - tx2).astype(float) + np.abs(wire_ys - ty2).astype(float)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx2 == bwx else (1 if tx2 > bwx else -1)
                dy = 0 if ty2 == bwy else (1 if ty2 > bwy else -1)
                # Try to step toward target
                candidates = []
                if dx != 0:
                    candidates.append((bwx+dx, bwy))
                if dy != 0:
                    candidates.append((bwx, bwy+dy))
                for nx2, ny2 in candidates:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 3: Extend road grid reactively - find road endpoints and extend
    if step % 8 in (4, 5):
        # Extend horizontal roads along road_rows
        for rr in road_rows:
            # Find leftmost and rightmost road on this row
            row_road = np.where(rm[rr, :])[0]
            if len(row_road) == 0:
                # No road on this row yet - try to start one near a power source
                if bool(near_power[rr, 60]) and bool(em[rr, 60]):
                    return (Tool.ROAD, 60, rr)
                continue
            # Extend left
            lx = int(row_road[0]) - 1
            if ib(lx, rr) and bool(em[rr, lx]) and not bool(pm[rr, lx]) and lx >= 2:
                return (Tool.ROAD, lx, rr)
            # Extend right
            rx = int(row_road[-1]) + 1
            if ib(rx, rr) and bool(em[rr, rx]) and not bool(pm[rr, rx]) and rx <= WORLD_W-3:
                return (Tool.ROAD, rx, rr)

        # Extend vertical roads along road_cols
        for rc in road_cols:
            col_road = np.where(rm[:, rc])[0]
            if len(col_road) == 0:
                if bool(near_power[50, rc]) and bool(em[50, rc]):
                    return (Tool.ROAD, rc, 50)
                continue
            # Extend up
            ty3 = int(col_road[0]) - 1
            if ib(rc, ty3) and bool(em[ty3, rc]) and not bool(pm[ty3, rc]) and ty3 >= 2:
                return (Tool.ROAD, rc, ty3)
            # Extend down
            by = int(col_road[-1]) + 1
            if ib(rc, by) and bool(em[by, rc]) and not bool(pm[by, rc]) and by <= WORLD_H-3:
                return (Tool.ROAD, rc, by)

    # Phase 4: Connect road rows with vertical connectors reactively
    if step % 8 == 6:
        # Find road row pairs that are not connected
        for i in range(len(road_rows)-1):
            r1, r2 = road_rows[i], road_rows[i+1]
            # Find columns where both rows have roads
            r1_cols = set(np.where(rm[r1, :])[0].tolist())
            r2_cols = set(np.where(rm[r2, :])[0].tolist())
            common = sorted(r1_cols & r2_cols)
            for cx in common:
                # Check if there's a vertical connection between them
                mid_y = (r1 + r2) // 2
                if bool(em[mid_y, cx]) and not bool(pm[mid_y, cx]) and not bool(rm[mid_y, cx]):
                    return (Tool.ROAD, cx, mid_y)

    # Civic buildings based on population
    if pop > 200 and step % 20 == 0:
        for sy in range(15, 90, 25):
            for sx in range(15, 110, 30):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

    if pop > 500 and step % 20 == 1:
        for sy in range(20, 90, 28):
            for sx in range(20, 110, 35):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

    if pop > 800 and step % 25 == 0:
        for sx, sy in [(35, 35), (85, 35), (35, 65), (85, 65)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1500:
        for nx2, ny2 in [(5, 5), (113, 5), (5, 93), (113, 93)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 3000:
        for sx, sy in [(5, 93), (113, 5)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 5000:
        for sx, sy in [(50, 5), (70, 93)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Main zone placement: find candidate spots near roads and power
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Don't place zones on road rows/cols
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            cand_mask[rr, :] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            cand_mask[:, rc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        cx_c, cy_c = 60, 50
        if pop < 200:
            dists = np.abs(cxs2 - cx_c).astype(float) + np.abs(cys2 - cy_c).astype(float)
            order = np.argsort(dists)
        elif pop < 1000:
            # Fill mid-range
            dists = np.abs(cxs2 - cx_c).astype(float) + np.abs(cys2 - cy_c).astype(float)
            order = np.argsort(np.abs(dists - 30))
        else:
            # Spread out
            dists = np.abs(cxs2 - cx_c).astype(float) + np.abs(cys2 - cy_c).astype(float)
            order = np.argsort(-dists)

        tool = pick_tool()
        offset = (step * 13 + pop * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 300:
                break

    # Parks to boost land value near powered road areas
    if pop > 300 and step % 9 == 0:
        park_cand = em & near_road & near_power
        pys, pxs = np.where(park_cand)
        if len(pxs) > 0:
            idx = (step * 41 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Extend roads to reach powered empty areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 17) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 11) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: wire from existing wire/plant toward unpowered roads
    wire_ys3, wire_xs3 = np.where(wm | pm)
    unpowered_road2 = rm & ~near_power
    uys3, uxs3 = np.where(unpowered_road2)
    if len(wire_xs3) > 0 and len(uxs3) > 0:
        tidx3 = (step * 37) % len(uxs3)
        tx3, ty3 = int(uxs3[tidx3]), int(uys3[tidx3])
        dists3 = np.abs(wire_xs3 - tx3).astype(float) + np.abs(wire_ys3 - ty3).astype(float)
        best3 = np.argmin(dists3)
        bwx3, bwy3 = int(wire_xs3[best3]), int(wire_ys3[best3])
        dx3 = 0 if tx3 == bwx3 else (1 if tx3 > bwx3 else -1)
        dy3 = 0 if ty3 == bwy3 else (1 if ty3 > bwy3 else -1)
        for nx2, ny2 in [(bwx3+dx3, bwy3), (bwx3, bwy3+dy3)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def init(obs, state):
