def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target ~40% res, 30% com, 30% ind for a balanced city
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.28:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 8)
    near_road = dilate(rm, 2)

    # Four quadrant layout with different neighborhood focuses:
    # NW quadrant: residential heavy
    # NE quadrant: commercial heavy
    # SW quadrant: industrial heavy
    # SE quadrant: mixed

    # Wire grid: horizontal at fixed rows, vertical at fixed cols
    # Using a denser grid than the parent
    wire_rows = [12, 24, 36, 48, 62, 74, 86, 98]
    wire_rows = [r for r in wire_rows if r < WORLD_H - 1]
    wire_cols = [10, 25, 40, 55, 65, 80, 95, 110]
    wire_cols = [c for c in wire_cols if c < WORLD_W - 1]

    # Additional power plants at strategic locations
    plant_grid = [
        (30, 50), (90, 50),   # already in init
        (15, 15), (60, 15), (105, 15),
        (15, 85), (60, 85), (105, 85),
        (15, 50), (105, 50),
    ]

    # ---- PHASE 1: ENSURE PLANTS EXIST ----
    for px, py in plant_grid:
        x0, x1 = max(0, px-6), min(WORLD_W, px+7)
        y0, y1 = max(0, py-6), min(WORLD_H, py+7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    phase = step % 10

    if phase == 0:
        # Extend horizontal wire corridors
        for wr in wire_rows:
            row_has_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_ys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                    step_y = 1 if wr > bpy else -1
                    for ny in range(bpy + step_y, wr + step_y, step_y):
                        if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                            return (Tool.WIRE, bpx, ny)
            else:
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_has_power[wx]):
                        if (wx > 0 and bool(row_has_power[wx-1])) or \
                           (wx < WORLD_W-1 and bool(row_has_power[wx+1])):
                            if bool(em[wr, wx]) and not bool(pm[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors
        for wc in wire_cols:
            col_has_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_power):
                plant_ys, plant_xs = np.where(pm)
                if len(plant_xs) > 0:
                    dists = np.abs(plant_xs - wc)
                    best = np.argmin(dists)
                    bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                    step_x = 1 if wc > bpx2 else -1
                    for nx in range(bpx2 + step_x, wc + step_x, step_x):
                        if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                            return (Tool.WIRE, nx, bpy2)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_has_power[wy]):
                        if (wy > 0 and bool(col_has_power[wy-1])) or \
                           (wy < WORLD_H-1 and bool(col_has_power[wy+1])):
                            if bool(em[wy, wc]) and not bool(pm[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads along horizontal wire corridors (both sides)
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(row_wire[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads along vertical wire corridors (both sides)
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Connect wire intersections
        for wr in wire_rows:
            for wc in wire_cols:
                if not ib(wc, wr):
                    continue
                row_ok = (wc > 0 and bool(wm[wr, wc-1])) or (wc < WORLD_W-1 and bool(wm[wr, wc+1]))
                col_ok = (wr > 0 and bool(wm[wr-1, wc])) or (wr < WORLD_H-1 and bool(wm[wr+1, wc]))
                if row_ok and col_ok and bool(em[wr, wc]):
                    return (Tool.WIRE, wc, wr)

    elif phase == 5:
        # Additional horizontal cross roads between wire rows
        for i in range(len(wire_rows) - 1):
            wr1, wr2 = wire_rows[i], wire_rows[i+1]
            # Place road in the gap between the corridor roads
            mid_y = (wr1 + wr2) // 2
            for wc in wire_cols:
                for offset in [-1, 1]:
                    rcx = wc + offset
                    if not (0 < rcx < WORLD_W - 1):
                        continue
                    if ib(rcx, mid_y) and bool(em[mid_y, rcx]) and bool(near_power[mid_y, rcx]):
                        adj = (ib(rcx, mid_y-1) and bool(rm[mid_y-1, rcx])) or \
                              (ib(rcx, mid_y+1) and bool(rm[mid_y+1, rcx]))
                        if adj:
                            return (Tool.ROAD, rcx, mid_y)

    elif phase == 6:
        # Additional vertical cross roads between wire cols
        for i in range(len(wire_cols) - 1):
            wc1, wc2 = wire_cols[i], wire_cols[i+1]
            mid_x = (wc1 + wc2) // 2
            for wr in wire_rows:
                for offset in [-1, 1]:
                    ry = wr + offset
                    if not (0 < ry < WORLD_H - 1):
                        continue
                    if ib(mid_x, ry) and bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]):
                        adj = (ib(mid_x-1, ry) and bool(rm[ry, mid_x-1])) or \
                              (ib(mid_x+1, ry) and bool(rm[ry, mid_x+1]))
                        if adj:
                            return (Tool.ROAD, mid_x, ry)

    elif phase == 7:
        # Wire toward unpowered roads
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    elif phase == 8:
        # Extend roads into powered areas
        target_mask = near_power & ~near_road & em
        target_mask[0:3, :] = False
        target_mask[WORLD_H-3:, :] = False
        target_mask[:, 0:3] = False
        target_mask[:, WORLD_W-3:] = False
        tys, txs = np.where(target_mask)
        road_ys, road_xs = np.where(rm)
        if len(txs) > 0 and len(road_xs) > 0:
            ti = (step * 17) % len(txs)
            tx, ty = int(txs[ti]), int(tys[ti])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    else:
        # Extend wire from existing wire
        wire_ys3, wire_xs3 = np.where(wm)
        if len(wire_xs3) > 0:
            step_k2 = (step * 13) % len(wire_xs3)
            for offset in range(min(len(wire_xs3), 60)):
                k = (step_k2 + offset * 5) % len(wire_xs3)
                wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2+dx3, wy2+dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        return (Tool.WIRE, nx3, ny3)

    # ---- ZONE PLACEMENT with quadrant-based tool selection ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 4)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.5 / (1.0 + abs(x - 60)/60.0 + abs(y - 50)/50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                # Quadrant-based zoning for diversity
                # NW (x<60, y<50): more residential
                # NE (x>=60, y<50): more commercial
                # SW (x<60, y>=50): more industrial
                # SE (x>=60, y>=50): balanced
                if zx < 60 and zy < 50:
                    # NW: 50% res, 25% com, 25% ind
                    r = (step * 3 + i) % 4
                    if r < 2:
                        tool = Tool.RESIDENTIAL
                    elif r == 2:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                elif zx >= 60 and zy < 50:
                    # NE: 25% res, 50% com, 25% ind
                    r = (step * 3 + i) % 4
                    if r == 0:
                        tool = Tool.RESIDENTIAL
                    elif r < 3:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                elif zx < 60 and zy >= 50:
                    # SW: 25% res, 25% com, 50% ind
                    r = (step * 3 + i) % 4
                    if r == 0:
                        tool = Tool.RESIDENTIAL
                    elif r == 1:
                        tool = Tool.COMMERCIAL
                    else:
                        tool = Tool.INDUSTRIAL
                else:
                    # SE: balanced via global ratio
                    tool = pick_tool()
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- CIVIC SERVICES (react to population) ----
    if pop > 50:
        fire_positions = [
            (18, 10), (50, 10), (80, 10), (110, 10),
            (18, 35), (50, 35), (80, 35), (110, 35),
            (18, 60), (50, 60), (80, 60), (110, 60),
            (18, 85), (50, 85), (80, 85), (110, 85),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (35, 20), (65, 20), (95, 20),
            (20, 45), (50, 45), (80, 45), (110, 45),
            (35, 70), (65, 70), (95, 70),
            (20, 90), (50, 90), (80, 90),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (35, 30), (85, 30), (35, 70), (85, 70),
            (60, 20), (60, 80), (12, 55), (108, 55),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 4), (70, 4), (50, 93), (70, 93)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value near dense zones
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power & dilate(zone_tiles, 3)
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire toward unpowered roads ----
    needs_power = rm & ~near_power
    npys, npxs = np.where(needs_power)
    if len(npxs) > 0:
        ti = (step * 23) % len(npxs)
        tx, ty = int(npxs[ti]), int(npys[ti])
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend roads ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with compact grid of roads and wires"""
    actions = []
    # Central power plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spines at rows 20, 40, 60, 80
    for wr in [20, 40, 60, 80]:
        for x in range(2, 118):
            actions.append((Tool.WIRE, x, wr))
    # Vertical wire spines at cols 20, 40, 60, 80, 100
    for wc in [20, 40, 60, 80, 100]:
        for y in range(2, 98):
            actions.append((Tool.WIRE, wc, y))
    # Roads adjacent to wire rows (above and below each)
    for wr in [20, 40, 60, 80]:
        for x in range(2, 118):
            actions.append((Tool.ROAD, x, wr - 1))
            actions.append((Tool.ROAD, x, wr + 1))
    # Roads adjacent to wire cols (left and right)
    for wc in [20, 40, 60, 80, 100]:
        for y in range(2, 98):
            actions.append((Tool.ROAD, wc - 1, y))
            actions.append((Tool.ROAD, wc + 1, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 50% res, 25% com, 25% ind — more commercial than parent
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    wire_rows = [20, 40, 60, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    phase = step % 20

    # Phase 0: Ensure power plants distributed across map
    if phase == 0:
        # More plant targets spread evenly
        plant_targets = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 15), min(WORLD_W, px + 15)
            y0, y1 = max(0, py - 15), min(WORLD_H, py + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(0, 12):
                    found = False
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)
                    if found:
                        break

    # Phase 1: Fill wire row gaps
    if phase == 1:
        for wr in wire_rows:
            for wx in range(2, WORLD_W - 2):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Fill wire col gaps
    if phase == 2:
        for wc in wire_cols:
            for wy in range(2, WORLD_H - 2):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Build roads adjacent to wire rows
    if phase == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (1 < ry < WORLD_H - 2):
                    continue
                for rx in range(2, WORLD_W - 2):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        has_wire = bool(wm[wr, rx]) or bool(pm[wr, rx])
                        adj_road = (rx > 0 and bool(rm[ry, rx-1])) or \
                                   (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                   (ry > 0 and bool(rm[ry-1, rx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        if has_wire and (adj_road or rx == 2):
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Build roads adjacent to wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (1 < rcx < WORLD_W - 2):
                    continue
                for ry in range(2, WORLD_H - 2):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        has_wire = bool(wm[ry, wc]) or bool(pm[ry, wc])
                        adj_road = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                   (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                   bool(rm[ry, max(0, rcx-1)]) or \
                                   bool(rm[ry, min(WORLD_W-1, rcx+1)])
                        if has_wire and (adj_road or ry == 2):
                            return (Tool.ROAD, rcx, ry)

    # Phase 5: Wire roads without power (extend wire toward unpowered areas)
    if phase == 5:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = np.argmin(dists)
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 6: Mid-block roads between wire rows
    if phase == 6:
        mid_rows = []
        for i in range(len(wire_rows)-1):
            mid_rows.append((wire_rows[i] + wire_rows[i+1]) // 2)
        mid_rows += [10, 90]
        for mr in mid_rows:
            if mr <= 1 or mr >= WORLD_H - 2:
                continue
            for rx in range(2, WORLD_W - 2):
                if bool(em[mr, rx]) and bool(near_power[mr, rx]) and not bool(pm[mr, rx]):
                    adj = (rx > 0 and bool(rm[mr, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mr, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mr)

    # Phase 7: Mid-block roads between wire cols
    if phase == 7:
        mid_cols = []
        for i in range(len(wire_cols)-1):
            mid_cols.append((wire_cols[i] + wire_cols[i+1]) // 2)
        mid_cols += [10, 110]
        for mc in mid_cols:
            if mc <= 1 or mc >= WORLD_W - 2:
                continue
            for ry in range(2, WORLD_H - 2):
                if bool(em[ry, mc]) and bool(near_power[ry, mc]) and not bool(pm[ry, mc]):
                    adj = (ry > 0 and bool(rm[ry-1, mc])) or \
                          (ry < WORLD_H-1 and bool(rm[ry+1, mc]))
                    if adj:
                        return (Tool.ROAD, mc, ry)

    # Phase 8: Wire unpowered zones
    if phase == 8:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Civic buildings scaled with population
    if pop > 10:
        fire_spots = [
            (10, 10), (55, 10), (110, 10),
            (10, 30), (55, 30), (110, 30),
            (10, 50), (110, 50),
            (10, 70), (55, 70), (110, 70),
            (10, 90), (55, 90), (110, 90),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (30, 10), (70, 10), (30, 30), (70, 30),
            (30, 50), (70, 50), (110, 50),
            (30, 70), (70, 70), (30, 90), (70, 90),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (30, 25), (80, 25), (30, 75), (80, 75),
            (55, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 350:
        nuke_spots = [
            (10, 50), (110, 50), (60, 10), (60, 90),
            (10, 25), (110, 25), (10, 75), (110, 75),
            (35, 50), (85, 50),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 700:
        seaports = [(5, 5), (115, 5), (5, 95), (115, 95)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1200:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 80 and step % 6 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:4, :] = False
        park_cands[WORLD_H-4:, :] = False
        park_cands[:, 0:4] = False
        park_cands[:, WORLD_W-4:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop * 3) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: closed-loop ----
    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    # Exclude wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Denser grid of zone centers — 4 wire rows & 5 wire cols create 5x6 blocks
        # Place zones in blocks between corridors
        if pop < 150:
            # Start in central cluster
            active_centers = []
            for row in range(3):
                for col in range(4):
                    cx = 30 + col * 20
                    cy = 30 + row * 20
                    active_centers.append((cx, cy))
        elif pop < 500:
            # Expand to full grid
            active_centers = []
            for row in range(5):
                for col in range(6):
                    cx = 10 + col * 20
                    cy = 10 + row * 18
                    active_centers.append((cx, cy))
        elif pop < 1200:
            # Dense grid
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 8 + col * 11
                    cy = 8 + row * 11
                    active_centers.append((cx, cy))
        else:
            # Maximum density
            active_centers = []
            for row in range(11):
                for col in range(13):
                    cx = 5 + col * 9
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 1000)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing road
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire/road cross."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Flanking roads
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # --- Fast dilation ---
    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    nbr_road = dilate(rm, 2)
    nbr_power = dilate(wm | pm, 4)
    power_src = wm | pm

    # --- Spine layout: horizontal spines ---
    spine_ys = [12, 25, 38, 50, 62, 75, 88]

    def num_active_spines():
        if pop < 30:   return 1
        if pop < 100:  return 2
        if pop < 300:  return 3
        if pop < 600:  return 4
        if pop < 1200: return 5
        if pop < 2000: return 6
        return len(spine_ys)

    n_spines = min(num_active_spines(), len(spine_ys))
    active_spines = spine_ys[:n_spines]

    sx_start = 4
    sx_end = 116

    # --- PHASE 1: Ensure each active spine has at least one power plant ---
    for sy in active_spines:
        y0, y1 = max(0, sy - 7), min(WORLD_H, sy + 8)
        if np.any(pm[y0:y1, sx_start:sx_end]):
            continue
        # Place plant near spine center
        for px in [60, 30, 90, 15, 105]:
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, sy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- PHASE 2: Extend wire along each active spine ---
    for si, sy in enumerate(active_spines):
        if step % max(n_spines, 1) != si % max(n_spines, 1):
            continue
        # Extend wire left and right from existing wire/plant on this spine
        row_wire = np.where(wm[sy, :] | pm[sy, :])[0]
        if len(row_wire) == 0:
            continue
        leftmost = int(row_wire.min())
        rightmost = int(row_wire.max())
        # Try extending right
        for nx in range(rightmost + 1, sx_end + 1):
            if not ib(nx, sy): break
            if bool(wm[sy, nx]) or bool(pm[sy, nx]): continue
            if bool(em[sy, nx]):
                return (Tool.WIRE, nx, sy)
            break
        # Try extending left
        for nx in range(leftmost - 1, sx_start - 1, -1):
            if not ib(nx, sy): break
            if bool(wm[sy, nx]) or bool(pm[sy, nx]): continue
            if bool(em[sy, nx]):
                return (Tool.WIRE, nx, sy)
            break

    # --- PHASE 3: Vertical wire connectors between adjacent spines ---
    connector_xs = list(range(10, WORLD_W, 15))
    for si in range(len(active_spines) - 1):
        y1s, y2s = active_spines[si], active_spines[si + 1]
        for cx in connector_xs:
            if not ib(cx, y1s): continue
            # Check both spines have wire at cx
            top_has = bool(wm[y1s, cx]) or bool(pm[y1s, cx])
            bot_has = bool(wm[y2s, cx]) or bool(pm[y2s, cx])
            if not (top_has or bot_has): continue
            for wy in range(y1s + 1, y2s):
                if not ib(cx, wy): continue
                if bool(wm[wy, cx]) or bool(pm[wy, cx]): continue
                if not bool(em[wy, cx]): continue
                # Only place if adjacent to existing wire
                for adj in [-1, 1]:
                    ay = wy + adj
                    if ib(cx, ay) and (bool(wm[ay, cx]) or bool(pm[ay, cx])):
                        return (Tool.WIRE, cx, wy)

    # --- PHASE 4: Roads flanking wire spines ---
    for si, sy in enumerate(active_spines):
        for road_y in [sy - 1, sy + 1]:
            if not ib(0, road_y): continue
            row_wire = np.where(wm[sy, :] | pm[sy, :])[0]
            if len(row_wire) == 0: continue
            # Place road where wire exists on spine
            for wx in row_wire:
                wx = int(wx)
                if not ib(wx, road_y): continue
                if bool(rm[road_y, wx]) or bool(pm[road_y, wx]): continue
                if bool(em[road_y, wx]):
                    return (Tool.ROAD, wx, road_y)

    # --- PHASE 5: Cross roads between spines ---
    for cx in connector_xs:
        for si in range(len(active_spines) - 1):
            y1s, y2s = active_spines[si], active_spines[si + 1]
            for ry in range(y1s + 2, y2s - 1):
                if not ib(cx, ry): continue
                if bool(rm[ry, cx]) or bool(pm[ry, cx]): continue
                if not bool(em[ry, cx]): continue
                for adj in [-1, 1]:
                    ay = ry + adj
                    if ib(cx, ay) and bool(rm[ay, cx]):
                        return (Tool.ROAD, cx, ry)

    # --- PHASE 6: Zone placement ---
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by proximity to active spines
        best_dist = np.full(len(cxs_arr), 999999.0)
        for sy in active_spines:
            d = np.abs(cys_arr - sy).astype(float)
            best_dist = np.minimum(best_dist, d)
        # Also weight by proximity to roads
        road_dist = np.full(len(cxs_arr), 3.0)
        rys, rxs = np.where(rm)
        if len(rxs) > 0:
            stride = max(1, len(rxs) // 80)
            for i in range(0, len(rxs), stride):
                d = (np.abs(cxs_arr - rxs[i]) + np.abs(cys_arr - rys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        score = best_dist * 0.6 + road_dist * 1.5
        order = np.argsort(score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # --- EXTEND ROADS into powered empty areas ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- CIVIC SERVICES (reactive to population) ---
    if pop > 80:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 18) for fy in range(15, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W, 22) for py2 in range(20, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]) and bool(nbr_road[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadiums = [
            (20, 20), (60, 20), (100, 20),
            (20, 50), (60, 50), (100, 50),
            (20, 80), (60, 80), (100, 80),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        # Nuclear power to boost capacity
        nuke_spots = [
            (30, 12), (90, 12), (30, 88), (90, 88),
            (10, 50), (110, 50), (60, 5), (60, 95),
            (50, 25), (70, 25), (50, 75), (70, 75),
        ]
        for (nx2, ny2) in nuke_spots:
            if ib(nx2, ny2):
                x0, x1 = max(0, nx2 - 6), min(WORLD_W, nx2 + 7)
                y0, y1 = max(0, ny2 - 6), min(WORLD_H, ny2 + 7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 90), (113, 90), (5, 5), (113, 5), (60, 95), (60, 3)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(35, 5), (85, 5), (35, 93), (85, 93)]
        for (apx, apy) in airports:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # --- Parks for land value ---
    if pop > 200 and step % 4 == 0:
        park_ys_a, park_xs_a = np.where(em & nbr_road & nbr_power)
        if len(park_xs_a) > 0:
            idx = (step * 19) % len(park_xs_a)
            py2, px2 = int(park_ys_a[idx]), int(park_xs_a[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- FALLBACK: extend wire from existing wire ---
    wire_ys_a, wire_xs_a = np.where(wm)
    if len(wire_xs_a) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_a), 1)
        for offset in range(min(len(wire_xs_a), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_a)
            wx2, wy2 = int(wire_xs_a[k]), int(wire_ys_a[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # --- FALLBACK: new coal plant near uncovered spine ---
    for sy in active_spines:
        if not bool(nbr_power[sy, 60]):
            for r in range(0, 10):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = 60 + dx, sy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

