    # Four coal plants at strategic positions
    for px, py in [(20, 20), (90, 20), (20, 75), (90, 75)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines at rows 20, 50, 80
    for wy in [20, 50, 80]:
        for x in range(1, 119):
