def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            if ir < 0.33:
                return Tool.INDUSTRIAL
            if cr < 0.25:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.25:
                return Tool.INDUSTRIAL
            if cr < 0.28:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.32:
                return Tool.COMMERCIAL
            if rr < 0.45:
                return Tool.RESIDENTIAL
            if ir < 0.23:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Infrastructure spine definitions
    wire_rows = [20, 35, 50, 65, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- PRIORITY 1: Repair/extend wire spines reactively ---
    if step % 8 == 0:
        for wr in wire_rows:
            if not (0 < wr < WORLD_H):
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        return (Tool.WIRE, wx, wr)

    if step % 8 == 1:
        for wc in wire_cols:
            if not (0 < wc < WORLD_W):
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        return (Tool.WIRE, wc, wy)

    # --- PRIORITY 2: Repair/extend road spines reactively ---
    if step % 8 == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj_road = ((rx > 0 and bool(rm[ry, rx-1])) or
                                        (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                                        (ry > 0 and bool(rm[ry-1, rx])) or
                                        (ry < WORLD_H-1 and bool(rm[ry+1, rx])))
                            if adj_road or rx <= 2:
                                return (Tool.ROAD, rx, ry)

    if step % 8 == 3:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj_road = ((ry > 0 and bool(rm[ry-1, rcx])) or
                                        (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or
                                        bool(rm[ry, max(0, rcx-1)]) or
                                        bool(rm[ry, min(WORLD_W-1, rcx+1)]))
                            if adj_road or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # --- PRIORITY 3: Reactively place power plants where coverage missing ---
    if step % 8 == 4:
        # Grid of candidate plant locations
        for py in range(15, WORLD_H - 5, 20):
            for px in range(15, WORLD_W - 5, 22):
                x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
                y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
                # Check if there's already a plant nearby
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    # Try to place one near this location on wire
                    for r in range(0, 8):
                        placed = False
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)
                        if placed:
                            break

    # --- PRIORITY 4: Wire unpowered zones to nearest power ---
    if step % 8 == 5:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # --- PRIORITY 5: Road to unroaded zones ---
    if step % 8 == 6:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bwy else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # --- CIVIC BUILDINGS (pop-gated) ---
    if pop > 30:
        fire_spots = [
            (5, 5), (40, 5), (75, 5), (110, 5),
            (5, 30), (110, 30), (5, 50), (110, 50),
            (5, 70), (110, 70), (5, 90), (40, 90), (75, 90), (110, 90),
            (30, 45), (60, 45), (90, 45), (30, 55), (60, 55), (90, 55),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [
            (15, 12), (45, 12), (75, 12), (105, 12),
            (15, 40), (45, 40), (75, 40), (105, 40),
            (15, 60), (45, 60), (75, 60), (105, 60),
            (15, 88), (45, 88), (75, 88), (105, 88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (30, 25), (90, 25), (30, 75), (90, 75),
            (60, 50), (15, 50), (105, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (10, 50), (110, 50), (60, 8), (60, 90),
            (10, 25), (110, 25), (10, 75), (110, 75),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5, 90), (110, 90), (5, 8), (110, 8)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50, 8), (70, 8), (50, 90), (70, 90)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 9 == 4:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # --- REACTIVE ZONE PLACEMENT ---
    # Candidate cells: empty, near road, near power
    cand_mask = em & near_road & near_power
    # Margin from edges
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid infrastructure corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Build active center targets based on population
        if pop < 150:
            active_centers = [
                (60, 42), (45, 42), (75, 42), (60, 28), (60, 58),
                (30, 42), (90, 42), (45, 28), (75, 28), (45, 58), (75, 58),
            ]
        elif pop < 600:
            active_centers = []
            for row in range(4):
                for col in range(6):
                    cx = 15 + col * 18
                    cy = 13 + row * 22
                    active_centers.append((cx, cy))
        elif pop < 2000:
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 10 + col * 14
                    cy = 10 + row * 14
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(8):
                for col in range(10):
                    cx = 8 + col * 11
                    cy = 7 + row * 11
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        # Use powered_zones as secondary sort signal for more reactivity
        powered_bonus = obs.powered_zones if hasattr(obs, 'powered_zones') else 0
        order = np.argsort(best_dist)
        tool = pick_tool()
        # Vary offset with pop for high reactivity
        offset = (step * 7 + pop * 3 + powered_bonus) % max(len(order), 1)

        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road from existing into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11 + pop) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire from existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13 + pop) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants connected by wire spine, initial roads"""
    actions = []
    # Two central power plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Roads flanking the horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    # Cross roads at wire col positions
    for y in range(1, 99):
        actions.append((Tool.ROAD, 29, y))
        actions.append((Tool.ROAD, 31, y))
        actions.append((Tool.ROAD, 89, y))
        actions.append((Tool.ROAD, 91, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Different zone mix: 40% res, 30% com, 30% ind (more balanced than parent)
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 100:
            # Bootstrap with more industrial
            if ir < 0.35:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.28:
                return Tool.INDUSTRIAL
            if cr < 0.30:
                return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            # High pop: shift to commercial/residential
            if cr < 0.35:
                return Tool.COMMERCIAL
            if rr < 0.40:
                return Tool.RESIDENTIAL
            if ir < 0.25:
                return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    # Infrastructure layout: denser grid of horizontal corridors
    # Wire rows at y = 10, 22, 34, 46, 58, 70, 82, 94
    # Wire cols at x = 15, 30, 45, 60, 75, 90, 105
    wire_rows = [10, 22, 34, 46, 58, 70, 82, 94]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Infrastructure repair: wire rows
    if step % 8 == 0:
        for wr in wire_rows:
            if wr <= 0 or wr >= WORLD_H:
                continue
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Infrastructure repair: wire cols
    if step % 8 == 1:
        for wc in wire_cols:
            if wc <= 0 or wc >= WORLD_W:
                continue
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # Roads above wire rows
    if step % 8 == 2:
        for wr in wire_rows:
            ry = wr - 1
            if not (0 < ry < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                        adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                              (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                              bool(rm[max(0,ry-1), rx]) or bool(rm[min(WORLD_H-1,ry+1), rx])
                        if adj or rx <= 2:
                            return (Tool.ROAD, rx, ry)

    # Roads below wire rows
    if step % 8 == 3:
        for wr in wire_rows:
            ry = wr + 1
            if not (0 < ry < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                        adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                              (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                              bool(rm[max(0,ry-1), rx]) or bool(rm[min(WORLD_H-1,ry+1), rx])
                        if adj or rx <= 2:
                            return (Tool.ROAD, rx, ry)

    # Vertical roads flanking wire cols
    if step % 8 == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry <= 2:
                                return (Tool.ROAD, rcx, ry)

    # Power plants: reactive placement in underserved regions
    if step % 8 == 5:
        # Place coal plants at denser intervals than parent
        plant_targets = []
        for py in range(10, WORLD_H - 5, 16):
            for px in range(10, WORLD_W - 5, 18):
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 9), min(WORLD_W, px + 10)
            y0, y1 = max(0, py - 9), min(WORLD_H, py + 10)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                for r in range(0, 7):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Wire to unpowered zones
    if step % 8 == 6:
        unpowered = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Road to unroaded zones
    if step % 8 == 7:
        unroaded = zone_tiles & ~near_road
        uz_ys, uz_xs = np.where(unroaded)
        if len(uz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (population-gated) ----
    if pop > 20:
        fire_spots = [
            (8,8),(40,8),(70,8),(100,8),(115,8),
            (8,28),(115,28),(8,48),(115,48),
            (8,68),(115,68),(8,90),(40,90),(70,90),(100,90),(115,90),
            (40,48),(70,28),(70,68),(55,15),(85,15),(55,82),(85,82),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 100:
        police_spots = [
            (18,18),(48,18),(78,18),(108,18),
            (18,38),(48,38),(78,38),(108,38),
            (18,58),(48,58),(78,58),(108,58),
            (18,78),(48,78),(78,78),(108,78),
            (12,50),(60,12),(60,88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadium_spots = [(25,20),(95,20),(25,80),(95,80),(60,50),(12,50),(108,50),(60,8),(60,90)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        # Switch to nuclear for more power coverage
        nuke_spots = [
            (12,50),(108,50),(60,8),(60,92),
            (12,22),(108,22),(12,78),(108,78),
            (37,12),(83,12),(37,88),(83,88),
            (37,50),(83,50),(60,35),(60,65),
            (25,35),(95,35),(25,65),(95,65),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5,94),(114,94),(5,6),(114,6),(60,94),(60,6),(5,50),(114,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        airports = [(48,6),(72,6),(48,90),(72,90),(6,42),(114,42),(6,55),(114,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value when pop is high
    if pop > 150 and step % 5 == 2:
        park_cands_mask = em & near_road & near_power
        pys, pxs = np.where(park_cands_mask)
        if len(pxs) > 0:
            idx = (step * 29 + pop) % len(pxs)
            px2, py2 = int(pxs[idx]), int(pys[idx])
            if not bool(zone_tiles[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    # Avoid borders
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road infrastructure corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):min(WORLD_H, wr+2), :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):min(WORLD_W, wc+2)] = False

    cys, cxs = np.where(cand_mask)

    if len(cxs) > 0:
        # Different neighborhood centers: two clusters (left and right halves)
        # plus middle, expanding outward as pop grows
        if pop < 150:
            # Two initial clusters: left-center and right-center
            active_centers = [
                (30, 50), (90, 50),
                (30, 35), (90, 35),
                (30, 65), (90, 65),
                (60, 50), (60, 35), (60, 65),
            ]
        elif pop < 600:
            # Four quadrant clusters
            active_centers = []
            for row in range(6):
                for col in range(8):
                    cx = 8 + col * 14
                    cy = 8 + row * 16
                    active_centers.append((cx, cy))
        else:
            # Full map dense grid
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 6 + col * 10
                    cy = 6 + row * 10
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 11 + pop * 5) % max(len(order), 1)

        for i in range(min(len(order), 700)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # Fallback: extend road into powered area
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 200)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Fallback: extend wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 100)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: two coal plants in different corners, with wire + road crosses."""
    actions = []
    # Plant 1: top-left cluster
    cx1, cy1 = 30, 25
    actions.append((Tool.COALPOWER, cx1, cy1))
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx1 + dx, cy1))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx1, cy1 + dy))
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx1 - 3, cy1 + dy))
        actions.append((Tool.ROAD, cx1 + 3, cy1 + dy))
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, cx1 + dx, cy1 - 3))
        actions.append((Tool.ROAD, cx1 + dx, cy1 + 3))

    # Plant 2: bottom-right cluster
    cx2, cy2 = 90, 75
    actions.append((Tool.COALPOWER, cx2, cy2))
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx2 + dx, cy2))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx2, cy2 + dy))
    for dy in range(-5, 6):
        actions.append((Tool.ROAD, cx2 - 3, cy2 + dy))
        actions.append((Tool.ROAD, cx2 + 3, cy2 + dy))
    for dx in range(-5, 6):
        actions.append((Tool.ROAD, cx2 + dx, cy2 - 3))
        actions.append((Tool.ROAD, cx2 + dx, cy2 + 3))

    # Connect the two plants with a wire spine
    for wx in range(cx1 + 7, cx2 - 6):
        actions.append((Tool.WIRE, wx, cy1))
    for wy in range(cy1 + 1, cy2):
        actions.append((Tool.WIRE, cx2, wy))

    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # === NEIGHBOR MASKS ===
    power_src = wm | pm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-4, 5):
        for dx2 in range(-4, 5):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === FIX UNPOWERED ZONES ===
    unpowered_zones = zone_tiles & ~nbr_power
    if np.any(unpowered_zones):
        uzys, uzxs = np.where(unpowered_zones)
        if np.any(wm):
            wys_arr, wxs_arr = np.where(wm)
            idx = (step * 7) % len(uzxs)
            tz, ty = int(uzxs[idx]), int(uzys[idx])
            dists = np.abs(wxs_arr - tz) + np.abs(wys_arr - ty)
            ki = np.argmin(dists)
            wx0, wy0 = int(wxs_arr[ki]), int(wys_arr[ki])
            if abs(wx0 - tz) >= abs(wy0 - ty):
                nx = wx0 + (1 if tz > wx0 else -1)
                ny = wy0
            else:
                nx = wx0
                ny = wy0 + (1 if ty > wy0 else -1)
            if ib(nx, ny) and bool(em[ny, nx]):
                return (Tool.WIRE, nx, ny)

    # === FIX UNROADED ZONES ===
    unroaded_zones = zone_tiles & ~nbr_road
    if np.any(unroaded_zones):
        urys, urxs = np.where(unroaded_zones)
        if np.any(rm):
            rys_arr, rxs_arr = np.where(rm)
            idx = (step * 11) % len(urxs)
            tz, ty = int(urxs[idx]), int(urys[idx])
            dists = np.abs(rxs_arr - tz) + np.abs(rys_arr - ty)
            ki = np.argmin(dists)
            rx0, ry0 = int(rxs_arr[ki]), int(rys_arr[ki])
            if abs(rx0 - tz) >= abs(ry0 - ty):
                nx = rx0 + (1 if tz > rx0 else -1)
                ny = ry0
            else:
                nx = rx0
                ny = ry0 + (1 if ty > ry0 else -1)
            if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                return (Tool.ROAD, nx, ny)

    # === NEIGHBORHOOD GRID: denser, more neighborhoods ===
    # 7 cols x 6 rows = 42 neighborhoods
    all_hoods = []
    for hy in range(10, 98, 15):
        for hx in range(10, 118, 15):
            all_hoods.append((hx, hy))

    def num_active():
        if pop < 50:   return 4
        if pop < 200:  return 8
        if pop < 500:  return 16
        if pop < 1000: return 24
        if pop < 2000: return 35
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        indices = [int(i * len(all_hoods) / n_active) for i in range(n_active)]
        active_hoods = [all_hoods[i] for i in indices]

    # === PHASE 1: ENSURE POWER PLANTS near every active hood ===
    if funds > 1500:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
            y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(1, 14):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx, ny = hx + dx, hy + dy
                                if ib(nx, ny) and bool(em[ny, nx]):
                                    return (Tool.COALPOWER, nx, ny)

    # === PHASE 2: WIRE from nearest plant toward current hood ===
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    spine = 12

    x0p, x1p = max(0, hx - 20), min(WORLD_W, hx + 21)
    y0p, y1p = max(0, hy - 20), min(WORLD_H, hy + 21)
    plant_ys, plant_xs = np.where(pm[y0p:y1p, x0p:x1p])

    if len(plant_xs) > 0:
        best_i = 0; best_d = 99999
        for pi in range(len(plant_xs)):
            px_c = int(plant_xs[pi]) + x0p
            py_c = int(plant_ys[pi]) + y0p
            d = abs(px_c - hx) + abs(py_c - hy)
            if d < best_d:
                best_d = d; best_i = pi
        px_l = int(plant_xs[best_i]) + x0p
        py_l = int(plant_ys[best_i]) + y0p

        if py_l != hy:
            sdir = 1 if hy > py_l else -1
            for wy in range(py_l + sdir, hy + sdir, sdir):
                if not ib(px_l, wy): continue
                if bool(pm[wy, px_l]) or bool(wm[wy, px_l]): continue
                if not bool(em[wy, px_l]): continue
                return (Tool.WIRE, px_l, wy)
        if px_l != hx:
            sdir = 1 if hx > px_l else -1
            for wx in range(px_l + sdir, hx + sdir, sdir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

    # Extend wire spine from existing wire at this hood
    col_wire = [r for r in range(max(0, hy - spine), min(WORLD_H, hy + spine + 1))
                if ib(hx, r) and bool(wm[r, hx])]
    if col_wire:
        max_wr = max(col_wire); min_wr = min(col_wire)
        bot_target = min(WORLD_H - 3, hy + spine)
        top_target = max(2, hy - spine)
        if max_wr < bot_target:
            nr = max_wr + 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)
        if min_wr > top_target:
            nr = min_wr - 1
            if ib(hx, nr) and not bool(pm[nr, hx]) and bool(em[nr, hx]):
                return (Tool.WIRE, hx, nr)

    row_wire = [c for c in range(max(0, hx - spine), min(WORLD_W, hx + spine + 1))
                if ib(c, hy) and bool(wm[hy, c])]
    if row_wire:
        max_wc = max(row_wire); min_wc = min(row_wire)
        right_target = min(WORLD_W - 3, hx + spine)
        left_target = max(2, hx - spine)
        if max_wc < right_target:
            nc = max_wc + 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)
        if min_wc > left_target:
            nc = min_wc - 1
            if ib(nc, hy) and not bool(pm[hy, nc]) and bool(em[hy, nc]):
                return (Tool.WIRE, nc, hy)

    # === PHASE 3: ROADS flanking wire spines ===
    # Use offset +/- 2 AND +/- 4 for wider road coverage
    hood_idx2 = (step + 1) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    col_wire3 = [r for r in range(max(0, hy3 - spine), min(WORLD_H, hy3 + spine + 1))
                 if ib(hx3, r) and bool(wm[r, hx3])]
    row_wire3 = [c for c in range(max(0, hx3 - spine), min(WORLD_W, hx3 + spine + 1))
                 if ib(c, hy3) and bool(wm[hy3, c])]

    cyc = step % 2
    road_offsets = [2, 4]  # two lanes of roads on each side
    for roff in road_offsets:
        for rx in [hx3 - roff, hx3 + roff]:
            if not ib(rx, hy3): continue
            for wr in col_wire3[cyc::2]:
                if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                    return (Tool.ROAD, rx, wr)
        for ry in [hy3 - roff, hy3 + roff]:
            if not ib(hx3, ry): continue
            cyc2 = (step + 1) % 2
            for wc in row_wire3[cyc2::2]:
                if ib(wc, ry) and bool(em[ry, wc]) and not bool(pm[ry, wc]):
                    return (Tool.ROAD, wc, ry)

    # === PHASE 4: ZONE PLACEMENT with better commercial/industrial mix ===
    def pick_tool():
        # Target: 30% industrial, 35% commercial, 35% residential
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2): return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4) + np.abs(cys - hy4)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs), 999999.0)
                stride = max(1, len(zxs2) // 80)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs - zxs2[i]).astype(float) + np.abs(cys - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.35 + zone_prox * 0.65
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 500)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: EXTEND ROADS from existing network into powered area ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # === PHASE 6: CIVIC SERVICES ===
    if pop > 15:
        fire_grid = [(fx, fy) for fy in range(12, 95, 14) for fx in range(12, 115, 14)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 60:
        police_grid = [(px2, py2) for py2 in range(15, 92, 16) for px2 in range(15, 112, 16)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 100 and step % 3 == 0:
        park_cands_y, park_cands_x = np.where(em & nbr_road & nbr_power)
        if len(park_cands_x) > 0:
            idx = (step * 17) % len(park_cands_x)
            py2, px2 = int(park_cands_y[idx]), int(park_cands_x[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    if pop > 200:
        stadium_locs = [
            (20, 15), (60, 12), (100, 15),
            (20, 85), (60, 88), (100, 85),
            (12, 50), (108, 50),
            (40, 30), (80, 30), (40, 70), (80, 70),
            (60, 50),
        ]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    # Nuclear power for high-pop support
    if pop > 400 and funds > 3000:
        nuclear_locs = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (60, 5), (60, 95), (5, 50), (115, 50),
            (35, 20), (85, 20), (35, 80), (85, 80),
            (20, 50), (100, 50), (60, 30), (60, 70),
            (45, 45), (75, 45), (45, 65), (75, 65),
        ]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx - 5), min(WORLD_W, npx + 6)
            y0b, y1b = max(0, npy - 5), min(WORLD_H, npy + 6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 350:
        seaport_locs = [(5, 50), (115, 50), (60, 5), (60, 95),
                        (5, 25), (5, 75), (115, 25), (115, 75),
                        (30, 5), (90, 5), (30, 95), (90, 95)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 600:
        airport_locs = [(10, 10), (100, 10), (10, 85), (100, 85),
                        (55, 5), (55, 92), (5, 45), (113, 45),
                        (50, 50)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: extend wire from existing wire ===
    wys_arr, wxs_arr = np.where(wm)
    if len(wxs_arr) > 0:
        sk2 = (step * 13) % len(wxs_arr)
        for offset in range(min(len(wxs_arr), 80)):
            k = (sk2 + offset * 5) % len(wxs_arr)
            wx2, wy2 = int(wxs_arr[k]), int(wys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # === FALLBACK: new plant for uncovered hood ===
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 18):
                for dy5 in range(-r, r + 1):
                    for dx5 in range(-r, r + 1):
                        if abs(dx5) == r or abs(dy5) == r:
                            nx5, ny5 = hx5 + dx5, hy5 + dy5
                            if ib(nx5, ny5) and bool(em[ny5, nx5]):
                                return (Tool.COALPOWER, nx5, ny5)

    # More nuclear at very high pop
    if pop > 1000 and step % 2 == 0 and funds > 4000:
        nuc_spots = [(30, 30), (90, 30), (30, 70), (90, 70),
                     (60, 50), (15, 15), (105, 15), (15, 85), (105, 85),
                     (50, 20), (70, 20), (50, 80), (70, 80)]
        for nx6, ny6 in nuc_spots:
            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                return (Tool.NUCLEARPOWER, nx6, ny6)

    return None

# Different strategy: denser grid, more commercial/industrial, ring roads around zones
# Uses a 4x5 grid (cols x rows) with horizontal wire backbones and road rings

def init(obs, state):
    """Bootstrap: 2 coal plants with horizontal wire spines and initial roads."""
    actions = []
    # Two plants: left and right halves
    for px, py in [(30, 50), (90, 50)]:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-15, 16):
            if dx != 0:
                actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire from plant
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Roads above and below spine
        for dx in range(-15, 16):
            actions.append((Tool.ROAD, px + dx, py - 4))
            actions.append((Tool.ROAD, px + dx, py + 4))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # 4 columns x 5 rows = 20 neighborhoods
    nh_cols = [18, 42, 78, 102]
    nh_rows = [15, 35, 55, 75, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 2
        if pop < 150:   return 4
        if pop < 400:   return 7
        if pop < 800:   return 11
        if pop < 1500:  return 16
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    # Pick active hoods spread across grid
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # ---- BUILD NEIGHBOR MASKS ----
    power_src = wm | pm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # ---- PHASE 1: ENSURE POWER PLANT near each active hood ----
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
        y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 15):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: HORIZONTAL WIRE BACKBONE per hood row ----
    # Each hood row gets a horizontal wire at hy connecting all same-row hoods
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        if len(row_hoods) < 1:
            continue
        row_hoods.sort(key=lambda h: h[0])
        xl = row_hoods[0][0]
        xr = row_hoods[-1][0]
        # Find nearest plant to anchor wire
        plant_in_row = False
        for rx2 in range(max(0, xl - 20), min(WORLD_W, xr + 21)):
            if bool(pm[hy_row, rx2]):
                plant_in_row = True
                break
        # Lay horizontal wire across all columns
        for cx2 in range(max(2, xl - 4), min(WORLD_W - 2, xr + 5)):
            if ib(cx2, hy_row) and bool(em[hy_row, cx2]) and not bool(pm[hy_row, cx2]) and not bool(wm[hy_row, cx2]):
                return (Tool.WIRE, cx2, hy_row)

    # ---- PHASE 3: VERTICAL WIRE connecting rows at each column ----
    for hx_col in nh_cols:
        col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
        col_hoods.sort(key=lambda h: h[1])
        for i in range(len(col_hoods) - 1):
            hy1 = col_hoods[i][1]
            hy2 = col_hoods[i + 1][1]
            for cy2 in range(hy1 + 1, hy2):
                if ib(hx_col, cy2) and bool(em[cy2, hx_col]) and not bool(pm[cy2, hx_col]) and not bool(wm[cy2, hx_col]):
                    return (Tool.WIRE, hx_col, cy2)

    # ---- PHASE 4: ROAD RINGS around each neighborhood ----
    # Place roads in a rectangle around each active hood (±5 in x, ±4 in y)
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]
    ring_dx = 6
    ring_dy = 5
    # Top and bottom horizontals
    for cx in range(hx - ring_dx, hx + ring_dx + 1):
        for ry in [hy - ring_dy, hy + ring_dy]:
            if ib(cx, ry) and bool(em[ry, cx]) and not bool(pm[ry, cx]):
                return (Tool.ROAD, cx, ry)
    # Left and right verticals
    for cy in range(hy - ring_dy, hy + ring_dy + 1):
        for rx in [hx - ring_dx, hx + ring_dx]:
            if ib(rx, cy) and bool(em[cy, rx]) and not bool(pm[cy, rx]):
                return (Tool.ROAD, rx, cy)

    # ---- PHASE 5: CROSS-ROADS within hood (horizontal + vertical roads through center) ----
    # Horizontal road at hy±2
    for hy_off in [-2, 2]:
        road_y = hy + hy_off
        for cx in range(hx - ring_dx + 1, hx + ring_dx):
            if ib(cx, road_y) and bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                return (Tool.ROAD, cx, road_y)
    # Vertical road at hx±2
    for hx_off in [-2, 2]:
        road_x = hx + hx_off
        for cy in range(hy - ring_dy + 1, hy + ring_dy):
            if ib(road_x, cy) and bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                return (Tool.ROAD, road_x, cy)

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- PHASE 7: INTER-HOOD ROADS connecting hood rings ----
    if pop > 50:
        for hy_row in nh_rows:
            row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
            row_hoods.sort(key=lambda h: h[0])
            for i in range(len(row_hoods) - 1):
                hx1 = row_hoods[i][0] + ring_dx
                hx2 = row_hoods[i + 1][0] - ring_dx
                for cx3 in range(hx1, hx2 + 1):
                    for ry2 in [hy_row - 2, hy_row + 2]:
                        if ib(cx3, ry2) and bool(em[ry2, cx3]) and not bool(pm[ry2, cx3]):
                            return (Tool.ROAD, cx3, ry2)

    if pop > 100 and len(nh_rows) >= 2:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1] + ring_dy
                hy2 = col_hoods[i + 1][1] - ring_dy
                for cy3 in range(hy1, hy2 + 1):
                    for rx2 in [hx_col - 2, hx_col + 2]:
                        if ib(rx2, cy3) and bool(em[cy3, rx2]) and not bool(pm[cy3, rx2]):
                            return (Tool.ROAD, rx2, cy3)

    # ---- PHASE 8: EXTEND ROADS near powered zones ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # ---- PHASE 9: CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(15, WORLD_W, 25) for fy in range(15, WORLD_H, 25)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2) for px2 in range(20, WORLD_W, 30) for py2 in range(20, WORLD_H, 30)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [(25, 8), (65, 8), (105, 8), (25, 92), (65, 92), (105, 92)]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (6, 6), (114, 6), (6, 94), (114, 94),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (30, 6), (90, 6), (30, 94), (90, 94),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2000:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(40, 5), (80, 5), (40, 94), (80, 94), (5, 35), (5, 65), (115, 35), (115, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- PARKS for land value ----
    if pop > 150 and step % 4 == 0:
        zone_tiles2 = resm | comm | indm
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles2)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 20)):
                k = (step * 3 + i * 17) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # ---- FALLBACK: new plant near uncovered hood ----
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 15):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: coal plants at key positions with wire spine and flanking roads."""
    actions = []
    # Plants at strategic positions across the map
    for cx in [20, 60, 100]:
        actions.append((Tool.COALPOWER, cx, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        if x not in [20, 60, 100]:
            actions.append((Tool.WIRE, x, 50))
    # Vertical wire spines
    for y in range(1, 99):
        if y != 50:
            actions.append((Tool.WIRE, 20, y))
            actions.append((Tool.WIRE, 60, y))
            actions.append((Tool.WIRE, 100, y))
    # Flanking roads
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Proximity masks — react to current map state
    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Wire/road grid definitions
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [15, 30, 45, 60, 75, 90, 105]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- PHASE 0: ENSURE POWER PLANTS spread across map ----
    # Reactive: only place if region lacks a plant
    if step % 8 == 0:
        plant_targets = []
        for py in [10, 30, 50, 70, 90]:
            for px in [15, 45, 75, 105]:
                plant_targets.append((px, py))
        for px, py in plant_targets:
            x0, x1 = max(0, px - 14), min(WORLD_W, px + 15)
            y0, y1 = max(0, py - 14), min(WORLD_H, py + 15)
            if not bool(np.any(pm[y0:y1, x0:x1])):
                for r in range(14):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # ---- PHASE 1: FILL WIRE ROW GAPS ----
    # Scan current map for breaks in wire rows; extend connected segments
    if step % 8 == 1:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if bool(wm[wr, wx]) or bool(pm[wr, wx]) or bool(rm[wr, wx]):
                    continue
                if not bool(em[wr, wx]):
                    continue
                left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                if left or right:
                    return (Tool.WIRE, wx, wr)

    # ---- PHASE 2: FILL WIRE COL GAPS ----
    if step % 8 == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if bool(wm[wy, wc]) or bool(pm[wy, wc]) or bool(rm[wy, wc]):
                    continue
                if not bool(em[wy, wc]):
                    continue
                up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                dn = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                if up or dn:
                    return (Tool.WIRE, wc, wy)

    # ---- PHASE 3: ROADS FLANKING WIRE ROWS ----
    if step % 8 == 3:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            adj = (rx > 0 and bool(rm[ry, rx-1])) or \
                                  (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or \
                                  (ry > 0 and bool(rm[ry-1, rx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                            if adj or rx == 1:
                                return (Tool.ROAD, rx, ry)

    # ---- PHASE 4: ROADS FLANKING WIRE COLS ----
    if step % 8 == 4:
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        if bool(wm[ry, wc]) or bool(pm[ry, wc]):
                            adj = (ry > 0 and bool(rm[ry-1, rcx])) or \
                                  (ry < WORLD_H-1 and bool(rm[ry+1, rcx])) or \
                                  bool(rm[ry, max(0, rcx-1)]) or \
                                  bool(rm[ry, min(WORLD_W-1, rcx+1)])
                            if adj or ry == 1:
                                return (Tool.ROAD, rcx, ry)

    # ---- PHASE 5: CROSS STREETS BETWEEN WIRE ROWS ----
    if step % 8 == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi+1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or \
                          (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # ---- PHASE 6: WIRE TOWARD UNPOWERED ZONES ----
    if step % 8 == 6:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = int(np.argmin(dists))
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- PHASE 7: WIRE TOWARD UNPOWERED ROADS ----
    if step % 8 == 7:
        road_no_power = rm & ~near_power
        rp_ys, rp_xs = np.where(road_no_power)
        if len(rp_xs) > 0:
            wire_ys_b, wire_xs_b = np.where(wm | pm)
            if len(wire_xs_b) > 0:
                idx = (step * 23) % len(rp_xs)
                tx, ty = int(rp_xs[idx]), int(rp_ys[idx])
                dists = np.abs(wire_xs_b - tx) + np.abs(wire_ys_b - ty)
                best_wi2 = int(np.argmin(dists))
                bwx2, bwy2 = int(wire_xs_b[best_wi2]), int(wire_ys_b[best_wi2])
                dx2 = 0 if tx == bwx2 else (1 if tx > bwx2 else -1)
                dy2 = 0 if ty == bwy2 else (1 if ty > bwy2 else -1)
                for nx2, ny2 in [(bwx2+dx2, bwy2), (bwx2, bwy2+dy2)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 20:
        fire_spots = [
            (7,7),(37,7),(67,7),(97,7),(117,7),
            (7,22),(117,22),(7,37),(117,37),
            (7,52),(117,52),(7,67),(117,67),
            (7,82),(37,82),(67,82),(97,82),(117,82),
            (25,27),(55,27),(85,27),(25,72),(55,72),(85,72),
            (40,50),(80,50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 60:
        police_spots = [
            (20,12),(50,12),(80,12),(110,12),
            (20,37),(50,37),(80,37),(110,37),
            (20,62),(50,62),(80,62),(110,62),
            (20,87),(50,87),(80,87),(110,87),
            (35,50),(65,50),(95,50),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 200:
        stadium_spots = [
            (25,15),(60,15),(95,15),
            (25,45),(60,45),(95,45),
            (25,65),(60,65),(95,65),
            (25,85),(60,85),(95,85),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 400:
        nuke_spots = [
            (5,50),(115,50),(60,5),(60,95),
            (5,25),(115,25),(5,75),(115,75),
            (5,10),(115,10),(5,90),(115,90),
            (30,5),(90,5),(30,95),(90,95),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 700:
        seaports = [(5,90),(115,90),(5,10),(115,10),(60,5),(60,95),(5,50),(115,50)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1200:
        airports = [(50,5),(70,5),(50,92),(70,92),(5,45),(110,45),(5,55),(110,55)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value — reactive to map state
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        for wr in wire_rows:
            park_cands[max(0, wr-1):wr+2, :] = False
        for wc in wire_cols:
            park_cands[:, max(0, wc-1):wc+2] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT: primary closed-loop action ----
    # Candidate tiles must be empty, near road, near power
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road corridors
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Adaptive neighborhood centers scale with population
        if pop < 80:
            active_centers = [(cx, cy) for cy in [50] for cx in [15, 35, 55, 75, 95, 115]]
        elif pop < 200:
            active_centers = [(cx, cy) for cy in [35, 50, 65]
                              for cx in [15, 30, 45, 60, 75, 90, 105]]
        elif pop < 500:
            active_centers = [(cx, cy) for cy in [15, 25, 35, 45, 55, 65, 75, 85]
                              for cx in [10, 22, 37, 52, 67, 82, 97, 112]]
        else:
            # Full dense coverage
            active_centers = [(cx, cy) for cy in range(6, 100, 9)
                              for cx in range(7, 120, 12)]

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- FALLBACK: extend road from existing road into powered area ----
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 11) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 7) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place coal plant near unpowered neighborhood ----
    all_hoods = [(cx, cy) for cy in range(6, 100, 9) for cx in range(7, 120, 12)]
    for (hx, hy) in all_hoods:
        if not bool(near_power[hy, hx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: two coal plants connected by wires, with initial roads."""
    actions = []
    # Left cluster plant at (30, 50)
    actions.append((Tool.COALPOWER, 30, 50))
    # Right cluster plant at (90, 50)
    actions.append((Tool.COALPOWER, 90, 50))
    # Wire between them along row 50
    for x in range(31, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for dy in range(1, 8):
        actions.append((Tool.WIRE, 30, 50 - dy))
        actions.append((Tool.WIRE, 30, 50 + dy))
        actions.append((Tool.WIRE, 90, 50 - dy))
        actions.append((Tool.WIRE, 90, 50 + dy))
    # Initial roads flanking the horizontal wire spine
    for x in range(25, 95):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Two-cluster layout: left cluster around (30,50), right cluster around (90,50)
    # Additional clusters added as population grows
    # Cluster centers with their associated power plant positions
    cluster_defs = [
        # (cluster_cx, cluster_cy, plant_x, plant_y)
        (30, 50, 30, 50),
        (90, 50, 90, 50),
        (60, 25, 60, 25),
        (60, 75, 60, 75),
        (15, 25, 15, 25),
        (105, 25, 105, 25),
        (15, 75, 15, 75),
        (105, 75, 105, 75),
        (45, 15, 45, 15),
        (75, 15, 75, 15),
        (45, 85, 45, 85),
        (75, 85, 75, 85),
    ]

    def num_active_clusters():
        if pop < 100:   return 2
        if pop < 400:   return 3
        if pop < 800:   return 4
        if pop < 1500:  return 6
        if pop < 3000:  return 8
        if pop < 5000:  return 10
        return len(cluster_defs)

    n_clusters = min(num_active_clusters(), len(cluster_defs))
    active_clusters = cluster_defs[:n_clusters]

    # Neighborhood grid: zones arranged around each cluster center
    def hood_zones(cx, cy, radius=10):
        """Return zone center candidates around cluster center."""
        spots = []
        for dr in range(-radius, radius + 1, 4):
            for dc in range(-radius, radius + 1, 4):
                zx, zy = cx + dc, cy + dr
                if ib(zx, zy) and 2 <= zx <= WORLD_W - 3 and 2 <= zy <= WORLD_H - 3:
                    spots.append((zx, zy))
        return spots

    # Build neighbor masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-5, 6):
        for dx in range(-5, 6):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # PHASE 1: Ensure each active cluster has a power plant
    for (cx, cy, px, py) in active_clusters:
        x0, x1 = max(0, cx - 8), min(WORLD_W, cx + 9)
        y0, y1 = max(0, cy - 8), min(WORLD_H, cy + 9)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            # Find nearby empty spot
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = px + dx, py + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Connect clusters with wire (extend wire toward uncovered clusters)
    wire_ys, wire_xs = np.where(wm | pm)
    uncovered_clusters = [(cx, cy) for (cx, cy, px, py) in active_clusters
                          if not bool(nbr_power[cy, cx])]
    if uncovered_clusters and len(wire_xs) > 0:
        for (tx, ty) in uncovered_clusters:
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best_k = int(np.argmin(dists))
            wx, wy = int(wire_xs[best_k]), int(wire_ys[best_k])
            dx = 1 if tx > wx else (-1 if tx < wx else 0)
            dy = 1 if ty > wy else (-1 if ty < wy else 0)
            for ddx, ddy in [(dx, 0), (0, dy), (dx, dy)]:
                if ddx == 0 and ddy == 0: continue
                nx, ny = wx + ddx, wy + ddy
                if ib(nx, ny) and not bool(pm[ny, nx]):
                    if bool(em[ny, nx]) or bool(wm[ny, nx]):
                        if bool(em[ny, nx]):
                            return (Tool.WIRE, nx, ny)

    # PHASE 3: Build roads around each active cluster (ring/cross pattern)
    # For each cluster, build roads in a cross pattern at distance 3-6 from center
    hood_cycle = step % max(n_clusters, 1)
    for idx_c in range(n_clusters):
        cx, cy, px, py = active_clusters[(hood_cycle + idx_c) % n_clusters]
        # Horizontal road at cy-2 and cy+2 (flanking the cluster)
        for road_y in [cy - 3, cy + 3]:
            if not ib(cx, road_y): continue
            for dx in range(-8, 9):
                rx, ry = cx + dx, road_y
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(nbr_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)
        # Vertical road at cx-3 and cx+3
        for road_x in [cx - 3, cx + 3]:
            if not ib(road_x, cy): continue
            for dy in range(-8, 9):
                rx, ry = road_x, cy + dy
                if ib(rx, ry) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    if bool(nbr_power[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    # PHASE 4: Extend wire spines within clusters
    for idx_c in range(n_clusters):
        cx, cy, px, py = active_clusters[(hood_cycle + idx_c) % n_clusters]
        for sign in [1, -1]:
            for dist in range(1, 10):
                # Vertical wire spine
                wy_pos = cy + sign * dist
                if ib(cx, wy_pos) and bool(em[wy_pos, cx]) and not bool(pm[wy_pos, cx]):
                    for ay in [wy_pos - 1, wy_pos + 1]:
                        if ib(cx, ay) and (bool(wm[ay, cx]) or bool(pm[ay, cx])):
                            return (Tool.WIRE, cx, wy_pos)
                # Horizontal wire spine
                wx_pos = cx + sign * dist
                if ib(wx_pos, cy) and bool(em[cy, wx_pos]) and not bool(pm[cy, wx_pos]):
                    for ax in [wx_pos - 1, wx_pos + 1]:
                        if ib(ax, cy) and (bool(wm[cy, ax]) or bool(pm[cy, ax])):
                            return (Tool.WIRE, wx_pos, cy)

    # PHASE 5: Zone placement with target ratios
    # Target: 40% RES, 35% COM, 25% IND (more commercial than parent)
    zone_tiles = resm | comm | indm

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        if ir < 0.22:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        if rr < 0.38:
            return Tool.RESIDENTIAL
        # Cycle based on step
        cyc = step % 3
        if cyc == 0: return Tool.RESIDENTIAL
        if cyc == 1: return Tool.COMMERCIAL
        return Tool.INDUSTRIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score by proximity to active cluster centers
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (cx, cy, px, py) in active_clusters:
            d = np.abs(cxs_arr - cx) + np.abs(cys_arr - cy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 200)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 6: Extend roads in powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # PHASE 7: Civic services based on population
    if pop > 80:
        for fx in range(15, WORLD_W, 20):
            for fy in range(15, WORLD_H, 20):
                if ib(fx, fy) and bool(em[fy, fx]) and bool(nbr_power[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 250:
        for px2 in range(20, WORLD_W, 25):
            for py2 in range(20, WORLD_H, 25):
                if ib(px2, py2) and bool(em[py2, px2]) and bool(nbr_power[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 600:
        for sx in range(30, WORLD_W, 35):
            for sy in range(30, WORLD_H, 35):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(60, 92), (10, 92), (110, 92), (10, 8), (110, 8), (60, 8)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(35, 8), (85, 8), (35, 92), (85, 92)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear power for high population
    if pop > 1500 and step % 3 == 0:
        nuclear_spots = [(60, 50), (30, 50), (90, 50), (60, 25), (60, 75),
                         (15, 25), (105, 25), (15, 75), (105, 75)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value boost
    if pop > 100 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 23) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire from existing wire/plant
    wire_ys_arr, wire_xs_arr = np.where(wm | pm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 60)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new coal plant near uncovered cluster
    for (cx, cy, px, py) in active_clusters:
        if not bool(nbr_power[cy, cx]):
            for r in range(1, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = cx + dx, cy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + cross wire spines + flanking roads."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-12, 13):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire spine
    for dy in range(-12, 13):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Roads flanking the vertical wire spine
    for dy in range(-11, 12):
        actions.append((Tool.ROAD, cx - 1, cy + dy))
        actions.append((Tool.ROAD, cx + 1, cy + dy))
    # Roads flanking the horizontal wire spine
    for dx in range(-11, 12):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # More neighborhoods, denser grid
    nh_cols = [15, 35, 55, 75, 95, 115]
    nh_rows = [15, 35, 55, 75, 95]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 200:   return 4
        if pop < 600:   return 8
        if pop < 1500:  return 14
        if pop < 3000:  return 20
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / n_active
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    power_src = wm | pm

    def dilate(mask, radius):
        result = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy2 in range(-radius, radius + 1):
            for dx2 in range(-radius, radius + 1):
                sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
                sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
                r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
                c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
                result[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return result

    nbr_power = dilate(power_src, 6)
    nbr_road = dilate(rm, 3)

    spine_range = 16

    # PHASE 1: Each active hood must have a nearby power plant
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 12), min(WORLD_W, hx + 13)
        y0, y1 = max(0, hy - 12), min(WORLD_H, hy + 13)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Wire from plants toward hood centers
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 16), min(WORLD_W, hx + 17)
    y0, y1 = max(0, hy - 16), min(WORLD_H, hy + 17)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0

        # Wire vertical leg from plant to hood
        if py_local != hy:
            step_dir = 1 if hy > py_local else -1
            for wy in range(py_local + step_dir, hy + step_dir, step_dir):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        # Wire horizontal leg
        if px_local != hx:
            step_dir = 1 if hx > px_local else -1
            for wx in range(px_local + step_dir, hx + step_dir, step_dir):
                if not ib(wx, hy): continue
                if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
                if not bool(em[hy, wx]): continue
                return (Tool.WIRE, wx, hy)

        # Extend vertical wire spine from hood
        for dy in range(-spine_range, spine_range + 1):
            wy = hy + dy
            if not ib(hx, wy): continue
            if bool(pm[wy, hx]) or bool(wm[wy, hx]): continue
            if not bool(em[wy, hx]): continue
            for adj in [-1, 1]:
                ay = wy + adj
                if ib(hx, ay) and (bool(wm[ay, hx]) or bool(pm[ay, hx])):
                    return (Tool.WIRE, hx, wy)

        # Extend horizontal wire spine from hood
        for dx in range(-spine_range, spine_range + 1):
            wx = hx + dx
            if not ib(wx, hy): continue
            if bool(pm[hy, wx]) or bool(wm[hy, wx]): continue
            if not bool(em[hy, wx]): continue
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, hy) and (bool(wm[hy, ax]) or bool(pm[hy, ax])):
                    return (Tool.WIRE, wx, hy)

    # PHASE 3: Roads flanking wire spines
    hood_idx2 = (step + 3) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]

    for rx in [hx3 - 1, hx3 + 1]:
        if not ib(rx, hy3): continue
        for dy in range(-spine_range, spine_range + 1):
            ry = hy3 + dy
            if not ib(rx, ry): continue
            if not bool(em[ry, rx]) or bool(pm[ry, rx]): continue
            if bool(wm[ry, hx3]) or bool(pm[ry, hx3]):
                return (Tool.ROAD, rx, ry)

    for ry2 in [hy3 - 1, hy3 + 1]:
        if not ib(hx3, ry2): continue
        for dx in range(-spine_range, spine_range + 1):
            rcx = hx3 + dx
            if not ib(rcx, ry2): continue
            if not bool(em[ry2, rcx]) or bool(pm[ry2, rcx]): continue
            if bool(wm[hy3, rcx]) or bool(pm[hy3, rcx]):
                return (Tool.ROAD, rcx, ry2)

    # PHASE 4: Connect hoods via wires (inter-hood wiring)
    for i, (hx1, hy1) in enumerate(active_hoods):
        for j, (hx2, hy2) in enumerate(active_hoods):
            if i >= j: continue
            if hy1 == hy2 and abs(hx2 - hx1) <= 35:
                mnx, mxx = min(hx1, hx2), max(hx1, hx2)
                for cx2 in range(mnx + 1, mxx):
                    if not ib(cx2, hy1): continue
                    if bool(wm[hy1, cx2]) or bool(pm[hy1, cx2]): continue
                    if not bool(em[hy1, cx2]): continue
                    for adx in [-1, 1]:
                        ax = cx2 + adx
                        if ib(ax, hy1) and (bool(wm[hy1, ax]) or bool(pm[hy1, ax])):
                            return (Tool.WIRE, cx2, hy1)
            if hx1 == hx2 and abs(hy2 - hy1) <= 35:
                mny, mxy = min(hy1, hy2), max(hy1, hy2)
                for cy2 in range(mny + 1, mxy):
                    if not ib(hx1, cy2): continue
                    if bool(wm[cy2, hx1]) or bool(pm[cy2, hx1]): continue
                    if not bool(em[cy2, hx1]): continue
                    for ady in [-1, 1]:
                        ay = cy2 + ady
                        if ib(hx1, ay) and (bool(wm[ay, hx1]) or bool(pm[ay, hx1])):
                            return (Tool.WIRE, hx1, cy2)

    # PHASE 5: Zone placement
    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 35% res, 35% com, 30% ind
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs - hx) + np.abs(cys - hy)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        # Use a cycling offset to avoid always placing same zone type in same spot
        offset = (step * 11) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 6: Extend roads into powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # PHASE 7: Civic services based on population
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 16) for fy in range(12, WORLD_H, 16)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 400:
        police_spots = [(px2, py2) for px2 in range(16, WORLD_W, 20) for py2 in range(16, WORLD_H, 20)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 700:
        stadiums = [(24, 25), (96, 25), (24, 75), (96, 75),
                    (60, 15), (60, 85), (12, 50), (108, 50),
                    (48, 50), (72, 50), (36, 35), (84, 35)]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(6, 94), (114, 94), (6, 6), (114, 6), (60, 97), (60, 3)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(40, 5), (80, 5), (40, 94), (80, 94),
                    (5, 40), (5, 70), (114, 40), (114, 70)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Nuclear upgrade for mature cities
    if pop > 2000 and step % 3 == 0:
        nuclear_spots = [(60, 50), (12, 12), (108, 12), (12, 88), (108, 88),
                         (35, 38), (85, 38), (35, 62), (85, 62),
                         (60, 25), (60, 75), (25, 50), (95, 50)]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # Parks for land value
    if pop > 200 and step % 4 == 0:
        park_cands = em & nbr_road & nbr_power
        park_ys, park_xs = np.where(park_cands)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # Fallback: extend wire from existing wire/plant
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % len(wire_xs_arr)
        for offset in range(min(len(wire_xs_arr), 100)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: new plant at uncovered hood
    for (hx, hy) in active_hoods:
        if not bool(nbr_power[hy, hx]):
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire and road grid."""
    actions = []
    # Two central power plants
    plants = [(40, 50), (80, 50)]
    for px, py in plants:
        actions.append((Tool.COALPOWER, px, py))
        # Horizontal wire spine
        for dx in range(-8, 9):
            actions.append((Tool.WIRE, px + dx, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            actions.append((Tool.WIRE, px, py + dy))
        # Roads flanking wire (above and below)
        for dx in range(-8, 9):
            actions.append((Tool.ROAD, px + dx, py - 2))
            actions.append((Tool.ROAD, px + dx, py + 2))
        # Vertical roads flanking wire (left and right)
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        i_r = ind_count / total_zones
        c_r = com_count / total_zones
        # More residential bias for population
        if i_r < 0.15:
            return Tool.INDUSTRIAL
        if c_r < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Grid of anchors - more anchors for wider coverage
    all_anchors = []
    for ax in [15, 30, 45, 60, 75, 90, 105]:
        for ay in [15, 28, 41, 54, 67, 80, 93]:
            all_anchors.append((ax, ay))

    def num_active():
        if pop < 50:   return 3
        if pop < 150:  return 6
        if pop < 300:  return 9
        if pop < 500:  return 14
        if pop < 800:  return 20
        if pop < 1500: return 28
        if pop < 2500: return 36
        return len(all_anchors)

    n_active = num_active()
    active_anchors = all_anchors[:n_active]

    # ---- ENSURE POWER PLANT near each active anchor ----
    for (ax, ay) in active_anchors:
        y0 = max(0, ay - 12); y1 = min(WORLD_H, ay + 13)
        x0 = max(0, ax - 12); x1 = min(WORLD_W, ax + 13)
        has_plant = np.any(pm[y0:y1, x0:x1])
        if not has_plant:
            # Place plant at anchor if empty enough
            for r in range(1, 14):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = ax + dx, ay + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- WIRE EXPANSION: extend wire spines reactively ----
    wire_half = min(22, 7 + pop // 10)
    vert_half = min(16, 5 + pop // 15)

    for (ax, ay) in active_anchors:
        # Horizontal wire spine
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for cx in range(spine_left, spine_right + 1):
            if not ib(cx, ay):
                continue
            if bool(wm[ay, cx]) or bool(pm[ay, cx]):
                continue
            adj_powered = False
            for ddx in [-1, 1]:
                nx = cx + ddx
                if ib(nx, ay) and (bool(wm[ay, nx]) or bool(pm[ay, nx])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[ay, cx]):
                return (Tool.WIRE, cx, ay)

    for (ax, ay) in active_anchors:
        # Vertical wire spine
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for cy in range(spine_top, spine_bot + 1):
            if not ib(ax, cy):
                continue
            if bool(wm[cy, ax]) or bool(pm[cy, ax]):
                continue
            adj_powered = False
            for ddy in [-1, 1]:
                ny = cy + ddy
                if ib(ax, ny) and (bool(wm[ny, ax]) or bool(pm[ny, ax])):
                    adj_powered = True
                    break
            if adj_powered and bool(em[cy, ax]):
                return (Tool.WIRE, ax, cy)

    # ---- WIRE CONNECTIONS between anchors in same column/row ----
    xs_set = sorted(set(ax for (ax, ay) in active_anchors))
    for col_x in xs_set:
        col_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ax == col_x], key=lambda a: a[1])
        for i in range(len(col_anchors) - 1):
            _, y1 = col_anchors[i]
            _, y2 = col_anchors[i + 1]
            for cy in range(y1 + 1, y2):
                if ib(col_x, cy) and bool(em[cy, col_x]) and not bool(pm[cy, col_x]):
                    adj = (ib(col_x, cy-1) and (bool(wm[cy-1, col_x]) or bool(pm[cy-1, col_x]))) or \
                          (ib(col_x, cy+1) and (bool(wm[cy+1, col_x]) or bool(pm[cy+1, col_x])))
                    if adj:
                        return (Tool.WIRE, col_x, cy)

    ys_set = sorted(set(ay for (ax, ay) in active_anchors))
    for row_y in ys_set:
        row_anchors = sorted([(ax, ay) for (ax, ay) in active_anchors if ay == row_y], key=lambda a: a[0])
        for i in range(len(row_anchors) - 1):
            x1, _ = row_anchors[i]
            x2, _ = row_anchors[i + 1]
            for cx in range(x1 + 1, x2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    adj = (ib(cx-1, row_y) and (bool(wm[row_y, cx-1]) or bool(pm[row_y, cx-1]))) or \
                          (ib(cx+1, row_y) and (bool(wm[row_y, cx+1]) or bool(pm[row_y, cx+1])))
                    if adj:
                        return (Tool.WIRE, cx, row_y)

    # ---- ROAD BUILDING: build a cross-hatch grid near wire ----
    # Roads at offsets -2 and +2 from wire spines (horizontal)
    for (ax, ay) in active_anchors:
        spine_left = max(2, ax - wire_half)
        spine_right = min(WORLD_W - 3, ax + wire_half)
        for road_y_off in [-2, 2]:
            road_y = ay + road_y_off
            if not ib(ax, road_y):
                continue
            for cx in range(spine_left, spine_right + 1):
                if not ib(cx, road_y):
                    continue
                if bool(em[road_y, cx]) and not bool(pm[road_y, cx]):
                    adj_road = any(ib(cx+ddx, road_y) and bool(rm[road_y, cx+ddx]) for ddx in [-1, 1])
                    adj_wire = (ib(cx, road_y-1) and bool(wm[road_y-1, cx])) or \
                               (ib(cx, road_y+1) and bool(wm[road_y+1, cx]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, cx, road_y)

    # Vertical roads flanking vertical spines
    for (ax, ay) in active_anchors:
        spine_top = max(2, ay - vert_half)
        spine_bot = min(WORLD_H - 3, ay + vert_half)
        for road_x_off in [-2, 2]:
            road_x = ax + road_x_off
            if not ib(road_x, ay):
                continue
            for cy in range(spine_top, spine_bot + 1):
                if not ib(road_x, cy):
                    continue
                if bool(em[cy, road_x]) and not bool(pm[cy, road_x]):
                    adj_road = any(ib(road_x, cy+ddy) and bool(rm[cy+ddy, road_x]) for ddy in [-1, 1])
                    adj_wire = (ib(road_x-1, cy) and bool(wm[cy, road_x-1])) or \
                               (ib(road_x+1, cy) and bool(wm[cy, road_x+1]))
                    if adj_road or adj_wire:
                        return (Tool.ROAD, road_x, cy)

    # ---- BUILD NEIGHBOR MASKS for zone placement ----
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_wire = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_wire[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_wire[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- ZONE PLACEMENT: near roads and wire ----
    cand_mask = em & nbr_road & nbr_wire
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (ax, ay) in active_anchors:
            d = (np.abs(cxs - ax).astype(float) + np.abs(cys - ay).astype(float))
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 800:
                break

    # ---- EXTEND ROADS from existing roads near wire ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 120)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_wire[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive: place when needed) ----
    if pop > 30:
        fire_spots = []
        for fy in [10, 28, 46, 64, 82]:
            for fx in [8, 25, 42, 59, 76, 93, 110]:
                fire_spots.append((fx, fy))
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_spots = []
        for py2 in [5, 23, 41, 59, 77, 95]:
            for px2 in [5, 22, 39, 56, 73, 90, 107]:
                police_spots.append((px2, py2))
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        for (sx, sy) in [(20, 5), (60, 5), (100, 5), (20, 92), (60, 92), (100, 92),
                         (5, 40), (5, 60), (115, 40), (115, 60)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        # Add nuclear power for extra capacity
        for (nx2, ny2) in [(5, 5), (115, 5), (5, 94), (115, 94), (60, 5), (60, 94),
                           (5, 50), (115, 50)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for (ax2, ay2) in [(55, 6), (5, 50), (115, 50), (55, 92), (30, 6), (90, 6)]:
            if ib(ax2, ay2) and bool(em[ay2, ax2]):
                return (Tool.AIRPORT, ax2, ay2)

    if pop > 2000:
        for (sx2, sy2) in [(5, 93), (115, 93), (60, 97), (5, 5), (115, 5)]:
            if ib(sx2, sy2) and bool(em[sy2, sx2]):
                return (Tool.SEAPORT, sx2, sy2)

    # ---- PARKS near zones ----
    if pop > 80:
        zone_map = resm | comm | indm
        zone_ys2, zone_xs2 = np.where(zone_map)
        if len(zone_xs2) > 0:
            for i in range(min(len(zone_xs2), 30)):
                k = (step * 3 + i * 17) % len(zone_xs2)
                zx2, zy2 = int(zone_xs2[k]), int(zone_ys2[k])
                for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
                    nx2, ny2 = zx2 + dx2, zy2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.PARK, nx2, ny2)

    # ---- FALLBACK: extend wire from any wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_arr_y, zone_arr_x = np.where(zone_tiles)
    if len(zone_arr_x) > 0:
        k = (step * 19) % len(zone_arr_x)
        zx2, zy2 = int(zone_arr_x[k]), int(zone_arr_y[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2 + dx2, zy2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central coal plant + wire/road cross."""
    actions = []
    cx, cy = 60, 50
    actions.append((Tool.COALPOWER, cx, cy))
    # Horizontal wire spine
    for dx in range(-10, 11):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    # Vertical wire cross
    for dy in range(-8, 9):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Initial roads flanking wire
    for dx in range(-10, 11):
        actions.append((Tool.ROAD, cx + dx, cy - 1))
        actions.append((Tool.ROAD, cx + dx, cy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Spines: use tighter spacing for denser packing
    spine_ys = [12, 24, 36, 48, 60, 72, 84, 96]
    spine_x_start = 4
    spine_x_end = 116

    def num_active_spines():
        if pop < 30:   return 1
        if pop < 150:  return 2
        if pop < 400:  return 3
        if pop < 800:  return 4
        if pop < 1500: return 5
        if pop < 3000: return 6
        if pop < 5000: return 7
        return len(spine_ys)

    n_spines = min(num_active_spines(), len(spine_ys))
    active_spines = spine_ys[:n_spines]

    # Connector columns (vertical wire/road connectors)
    connector_xs = list(range(8, WORLD_W, 12))

    # ---- PHASE 1: ENSURE POWER PLANTS ----
    # Place coal plant near each spine center if no plant nearby
    plant_positions = [(60, sy) for sy in active_spines]
    plant_positions += [(30, sy) for sy in active_spines]
    plant_positions += [(90, sy) for sy in active_spines]

    for (px, py) in plant_positions:
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            # Find empty spot near px,py
            for r in range(0, 8):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px + dx, py + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: EXTEND WIRE SPINES ----
    # For each active spine, extend wire along horizontal line
    for si, spine_y in enumerate(active_spines):
        if step % max(n_spines, 1) != si % max(n_spines, 1):
            continue
        # Scan left to right, place wire adjacent to existing wire/plant
        for wx in range(spine_x_start, spine_x_end + 1):
            if not ib(wx, spine_y): continue
            if bool(wm[spine_y, wx]) or bool(pm[spine_y, wx]):
                continue
            if not bool(em[spine_y, wx]):
                continue
            # Check if adjacent to wire or plant
            for adj in [-1, 1]:
                ax = wx + adj
                if ib(ax, spine_y) and (bool(wm[spine_y, ax]) or bool(pm[spine_y, ax])):
                    return (Tool.WIRE, wx, spine_y)

    # ---- PHASE 3: VERTICAL WIRE CONNECTORS ----
    for si in range(len(active_spines) - 1):
        y1s, y2s = active_spines[si], active_spines[si + 1]
        for cx in connector_xs:
            for wy in range(y1s + 1, y2s):
                if not ib(cx, wy): continue
                if bool(wm[wy, cx]) or bool(pm[wy, cx]): continue
                if not bool(em[wy, cx]): continue
                for adj in [-1, 1]:
                    ay = wy + adj
                    if ib(cx, ay) and (bool(wm[ay, cx]) or bool(pm[ay, cx])):
                        return (Tool.WIRE, cx, wy)

    # ---- PHASE 4: ROADS flanking wire spines ----
    for si, spine_y in enumerate(active_spines):
        for road_y in [spine_y - 1, spine_y + 1]:
            if not ib(0, road_y): continue
            for rx in range(spine_x_start, spine_x_end + 1):
                if not ib(rx, road_y): continue
                if bool(rm[road_y, rx]) or bool(pm[road_y, rx]): continue
                if not bool(em[road_y, rx]): continue
                if bool(wm[spine_y, rx]) or bool(pm[spine_y, rx]):
                    return (Tool.ROAD, rx, road_y)

    # ---- PHASE 5: VERTICAL ROAD CONNECTORS ----
    for cx in connector_xs:
        for si in range(len(active_spines) - 1):
            y1s, y2s = active_spines[si], active_spines[si + 1]
            for ry in range(y1s + 2, y2s - 1):
                if not ib(cx, ry): continue
                if bool(rm[ry, cx]) or bool(pm[ry, cx]): continue
                if not bool(em[ry, cx]): continue
                for adj in [-1, 1]:
                    ay = ry + adj
                    if ib(cx, ay) and bool(rm[ay, cx]):
                        return (Tool.ROAD, cx, ry)

    # ---- COMPUTE NEIGHBOR MASKS for zone placement ----
    # Road within 2 tiles
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power within 3 tiles
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # ---- PHASE 6: ZONE PLACEMENT ----
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% RES, 35% IND, 25% COM
        if ir < 0.33:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by distance to nearest active spine (closer = better)
        best_dist = np.full(len(cxs), 999999.0)
        for sy in active_spines:
            d = np.abs(cys - sy)
            best_dist = np.minimum(best_dist, d)
        # Also score by distance to nearest road (for tighter packing)
        order = np.argsort(best_dist)
        tool = pick_tool()
        offset = (step * 7) % max(len(order), 1)
        for i in range(min(len(order), 300)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 60)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(nbr_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES ----
    if pop > 60:
        fire_spots = [(fx, fy) for fx in range(12, WORLD_W, 18) for fy in range(12, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 200:
        police_spots = [(px2, py2) for px2 in range(18, WORLD_W, 22) for py2 in range(18, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (20, 18), (55, 18), (90, 18),
            (20, 48), (55, 48), (90, 48),
            (20, 78), (55, 78), (90, 78),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 900:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 96), (60, 4)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [(35, 5), (75, 5), (35, 93), (75, 93), (5, 35), (5, 65), (113, 35), (113, 65)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for high pop ----
    if pop > 1200 and step % 2 == 0:
        nuclear_spots = [
            (30, sy) for sy in active_spines
        ] + [
            (60, sy) for sy in active_spines
        ] + [
            (90, sy) for sy in active_spines
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS ----
    if pop > 150 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: new plant ----
    for spine_y in active_spines:
        if not bool(nbr_power[spine_y, 60]):
            for r in range(0, 12):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r:
                            nx, ny = 60 + dx, spine_y + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    return None

