def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # --- Precompute neighbor masks ---
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-4, 5):
        for dx in range(-4, 5):
            sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H - dy)
            sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W - dx)
            r0 = max(0, dy);   r1 = min(WORLD_H, WORLD_H + dy)
            c0 = max(0, dx);   c1 = min(WORLD_W, WORLD_W + dx)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    # Adaptive coverage radius
    if pop < 200:
        max_r = 25
    elif pop < 600:
        max_r = 40
    elif pop < 2000:
        max_r = 60
    elif pop < 5000:
        max_r = 80
    else:
        max_r = 100

    # Hood grid: active neighborhoods expand with population
    all_hoods = [(hx, hy) for hy in range(10, 100, 12) for hx in range(10, 120, 12)]

    if pop < 100:    n_active = 4
    elif pop < 300:  n_active = 10
    elif pop < 800:  n_active = 24
    elif pop < 2000: n_active = 50
    elif pop < 5000: n_active = 80
    else:            n_active = len(all_hoods)

    if n_active >= len(all_hoods):
        active_hoods = all_hoods[:]
    else:
        stride = max(1, len(all_hoods) // n_active)
        active_hoods = all_hoods[::stride][:n_active]

    # Zone tool selection
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if pop < 400 and ir < 0.30:
            return Tool.INDUSTRIAL
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # === PHASE 1: Power plants — ensure coverage ===
    plant_count = int(np.sum(pm))
    # Add plants near hoods that lack nearby power
    if funds > 2000:
        for (hx, hy) in active_hoods:
            x0, x1 = max(0, hx-10), min(WORLD_W, hx+11)
            y0, y1 = max(0, hy-10), min(WORLD_H, hy+11)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find empty spot near hood
                for r in range(1, 10):
                    placed = False
                    for dy in range(-r, r+1):
                        for dx in range(-r, r+1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = hx+dx, hy+dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                use_nuclear = (funds > 8000 and pop > 1500)
                                return (Tool.NUCLEARPOWER if use_nuclear else Tool.COALPOWER, nx, ny)
                    if placed:
                        break

    # === PHASE 2: Wire extension — grow wire from existing wire/plant ===
    # Build wire corridors: extend wire toward uncovered hoods
    if step % 4 in (0, 1):
        wire_pm = wm | pm
        wys, wxs = np.where(wire_pm)
        if len(wxs) > 0:
            # For each active hood lacking wire coverage, extend toward it
            for (hx, hy) in active_hoods:
                x0, x1 = max(0, hx-6), min(WORLD_W, hx+7)
                y0, y1 = max(0, hy-6), min(WORLD_H, hy+7)
                has_wire = bool(np.any(wire_pm[y0:y1, x0:x1]))
                if not has_wire:
                    # Find nearest wire and extend one step toward hood
                    dists = np.abs(wxs - hx) + np.abs(wys - hy)
                    k = int(np.argmin(dists))
                    wx0, wy0 = int(wxs[k]), int(wys[k])
                    # Step toward hood
                    dx = np.sign(hx - wx0)
                    dy = np.sign(hy - wy0)
                    # Try horizontal first
                    for (ddx, ddy) in [(dx, 0), (0, dy), (dx, dy)]:
                        nx, ny = wx0 + ddx, wy0 + ddy
                        if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                            return (Tool.WIRE, nx, ny)

        # Also extend wire from existing wire along grid lines
        sk = (step * 7) % max(len(wxs), 1) if len(wxs) > 0 else 0
        for i in range(min(len(wxs), 80)):
            k = (sk + i) % len(wxs)
            wx2, wy2 = int(wxs[k]), int(wys[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2+dx, wy2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    # Prefer extending toward unpowered hoods
                    for (hx, hy) in active_hoods:
                        d_cur = abs(wx2-hx) + abs(wy2-hy)
                        d_new = abs(nx-hx) + abs(ny-hy)
                        if d_new < d_cur:
                            return (Tool.WIRE, nx, ny)

    # === PHASE 3: Road grid — reactive extension ===
    # Roads parallel to wire spines at offset ±2, or grid roads
    if step % 4 == 2:
        # Horizontal road grid lines
        road_rows = list(range(14, 97, 8))
        for ry in road_rows:
            x0 = max(2, 10)
            x1 = min(WORLD_W-2, 110)
            for rx in range(x0, x1):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]) and bool(nbr_power[ry, rx]):
                    # Extend from adjacent road
                    has_adj = (ib(rx-1, ry) and bool(rm[ry, rx-1])) or \
                              (ib(rx+1, ry) and bool(rm[ry, rx+1]))
                    if has_adj:
                        return (Tool.ROAD, rx, ry)

    if step % 4 == 3:
        # Vertical road grid lines
        road_cols = list(range(14, 117, 8))
        for rxc in road_cols:
            y0 = max(2, 10)
            y1 = min(WORLD_H-2, 90)
            for ry in range(y0, y1):
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]) and bool(nbr_power[ry, rxc]):
                    has_adj = (ib(rxc, ry-1) and bool(rm[ry-1, rxc])) or \
                              (ib(rxc, ry+1) and bool(rm[ry+1, rxc]))
                    if has_adj:
                        return (Tool.ROAD, rxc, ry)

    # === PHASE 4: Zone placement ===
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        # Score: proximity to active hoods + clustering with existing zones
        best_dist = np.full(len(cxs_arr), 999999.0)
        for (hx, hy) in active_hoods:
            d = np.abs(cxs_arr - hx) + np.abs(cys_arr - hy)
            best_dist = np.minimum(best_dist, d)

        if total_zones > 5:
            zys2, zxs2 = np.where(zone_tiles)
            if len(zxs2) > 0:
                zone_prox = np.full(len(cxs_arr), 999999.0)
                stride = max(1, len(zxs2) // 200)
                for i in range(0, len(zxs2), stride):
                    d2 = np.abs(cxs_arr - zxs2[i]).astype(float) + \
                         np.abs(cys_arr - zys2[i]).astype(float)
                    zone_prox = np.minimum(zone_prox, d2)
                score = best_dist * 0.5 + zone_prox * 0.5
            else:
                score = best_dist
        else:
            score = best_dist

        order = np.argsort(score)
        off = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === PHASE 5: Extend road from existing network ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 80)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx, dy in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx, ny = rx2+dx, ry2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]) and bool(nbr_power[ny, nx]):
                    return (Tool.ROAD, nx, ny)

    # === CIVIC SERVICES ===
    if pop > 80:
        fire_grid = [(fx, fy) for fy in range(18, 95, 18) for fx in range(18, 115, 18)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 200:
        police_grid = [(px2, py2) for py2 in range(20, 95, 20) for px2 in range(20, 115, 20)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 150 and step % 5 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 17) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    if pop > 500:
        for stx, sty in [(20,20),(60,15),(100,20),(20,80),(60,85),(100,80),(40,40),(80,40),(40,60),(80,60)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 1000 and funds > 5000:
        nuclear_locs = [(10,10),(110,10),(10,90),(110,90),(35,20),(85,20),(35,80),(85,80),
                        (20,50),(100,50),(60,25),(60,75)]
        for npx, npy in nuclear_locs:
            if not ib(npx, npy): continue
            x0b, x1b = max(0, npx-5), min(WORLD_W, npx+6)
            y0b, y1b = max(0, npy-5), min(WORLD_H, npy+6)
            if not bool(np.any(pm[y0b:y1b, x0b:x1b])) and bool(em[npy, npx]):
                return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 600:
        for spx, spy in [(5,50),(115,50),(60,5),(60,95),(5,30),(5,70),(115,30),(115,70)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1200:
        for apx, apy in [(10,10),(100,10),(10,85),(100,85),(55,5),(55,90)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # === FALLBACK: extend wire from plants/wire ===
    wys3, wxs3 = np.where(wm | pm)
    if len(wxs3) > 0:
        sk2 = (step * 13) % len(wxs3)
        for off in range(min(len(wxs3), 80)):
            k = (sk2 + off * 5) % len(wxs3)
            wx2, wy2 = int(wxs3[k]), int(wys3[k])
            for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx, ny = wx2+dx, wy2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    return None

# Strategy: Grid-based city with multiple power plants, dense road grid,
# and aggressive zone placement. Uses a proper grid layout instead of spines.
# Key differences from parent:
# 1. True road GRID (horizontal + vertical streets) instead of spines
# 2. More aggressive zone placement in every grid cell
# 3. Better power distribution with plants at grid intersections
# 4. Target 40% RES / 35% COM / 25% IND mix (more commercial)
# 5. React to obs.funded_zones and powered_zones to add more plants

def init(obs, state):
    """Bootstrap: central coal plant + wire cross + road grid start."""
    actions = []
    cx, cy = 60, 50
    # Central power plant
    actions.append((Tool.COALPOWER, cx, cy))
    # Wire cross to distribute power
    for dx in range(-6, 7):
        if dx != 0:
            actions.append((Tool.WIRE, cx + dx, cy))
    for dy in range(-6, 7):
        if dy != 0:
            actions.append((Tool.WIRE, cx, cy + dy))
    # Initial road grid (two roads near center)
    for rx in range(52, 70):
        actions.append((Tool.ROAD, rx, cy - 3))
        actions.append((Tool.ROAD, rx, cy + 3))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Grid layout: road every 6 tiles, zones fill in between
    # Horizontal roads at: 14, 20, 26, 32, 38, 44, 50, 56, 62, 68, 74, 80, 86
    # Vertical roads at: 10, 17, 24, 31, 38, 45, 52, 59, 66, 73, 80, 87, 94, 101, 108
    H_ROADS = list(range(14, 90, 6))   # y positions of horizontal roads
    V_ROADS = list(range(10, 115, 7))  # x positions of vertical roads

    # Power plants at grid intersections (every ~3rd intersection)
    PLANT_POSITIONS = [
        (vx, hy) for i, vx in enumerate(V_ROADS[1::3])
                  for j, hy in enumerate(H_ROADS[1::3])
    ]

    # Progressive expansion based on population
    def active_h_roads():
        if pop < 100:   return H_ROADS[4:8]
        if pop < 300:   return H_ROADS[3:9]
        if pop < 700:   return H_ROADS[2:10]
        if pop < 1500:  return H_ROADS[1:11]
        return H_ROADS

    def active_v_roads():
        if pop < 100:   return V_ROADS[4:9]
        if pop < 300:   return V_ROADS[3:11]
        if pop < 700:   return V_ROADS[2:12]
        if pop < 1500:  return V_ROADS[1:13]
        return V_ROADS

    ah = active_h_roads()
    av = active_v_roads()

    # ---- PHASE 1: ENSURE POWER PLANTS near zone clusters ----
    # Check if active grid region is powered
    if ah and av:
        y_min, y_max = min(ah) - 3, max(ah) + 3
        x_min, x_max = min(av) - 3, max(av) + 3
        power_count = int(np.sum(pm[max(0,y_min):min(WORLD_H,y_max),
                                     max(0,x_min):min(WORLD_W,x_max)]))
        # Need 1 plant per ~200 area tiles
        area = (y_max - y_min) * (x_max - x_min)
        needed_plants = max(1, area // 400)
        if power_count < needed_plants * 9:  # each plant ~3x3
            # Find a good spot for a plant (at V/H road intersections)
            for px, py in PLANT_POSITIONS:
                if not ib(px, py): continue
                # Check nearby for existing plant
                y0, y1 = max(0, py-5), min(WORLD_H, py+6)
                x0, x1 = max(0, px-5), min(WORLD_W, px+6)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    if bool(em[py, px]):
                        return (Tool.COALPOWER, px, py)

    # ---- PHASE 2: HORIZONTAL ROADS ----
    phase = step % 4
    if phase == 0:
        for hy in ah:
            for vx in av:
                # Place road segment between consecutive V_ROADS
                vi = av.index(vx) if vx in av else -1
                if vi >= 0 and vi < len(av) - 1:
                    x_start, x_end = vx, av[vi + 1]
                    for rx in range(x_start, x_end + 1):
                        if not ib(rx, hy): continue
                        if bool(rm[hy, rx]): continue
                        if bool(pm[hy, rx]): continue
                        if bool(em[hy, rx]):
                            return (Tool.ROAD, rx, hy)

    # ---- PHASE 3: VERTICAL ROADS ----
    if phase == 1:
        for vx in av:
            for hy in ah:
                hi = ah.index(hy) if hy in ah else -1
                if hi >= 0 and hi < len(ah) - 1:
                    y_start, y_end = hy, ah[hi + 1]
                    for ry in range(y_start, y_end + 1):
                        if not ib(vx, ry): continue
                        if bool(rm[ry, vx]): continue
                        if bool(pm[ry, vx]): continue
                        if bool(em[ry, vx]):
                            return (Tool.ROAD, vx, ry)

    # ---- PHASE 4: WIRE NETWORK ----
    # Run wire along roads to distribute power
    if phase == 2:
        # Wire along H_ROADS near plants
        for hy in ah:
            for vx in av:
                if not ib(vx, hy): continue
                if bool(wm[hy, vx]) or bool(pm[hy, vx]): continue
                if not bool(em[hy, vx]) and not bool(rm[hy, vx]): continue
                # Only place wire if adjacent to power source
                for adj in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ax, ay = vx + adj[0], hy + adj[1]
                    if ib(ax, ay) and (bool(wm[ay, ax]) or bool(pm[ay, ax])):
                        if bool(em[hy, vx]):
                            return (Tool.WIRE, vx, hy)

    # Build neighbor masks for zone placement
    # Road adjacency (within 3 tiles)
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # Power adjacency (wire or plant within 5 tiles)
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2); r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2); c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= wm[sr0:sr1, sc0:sc1]
            nbr_power[r0:r1, c0:c1] |= pm[sr0:sr1, sc0:sc1]

    zone_tiles = resm | comm | indm

    def pick_tool():
        # Target: 40% RES, 35% COM, 25% IND
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.23:
            return Tool.INDUSTRIAL
        if cr < 0.33:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    # ---- PHASE 5: ZONE PLACEMENT ----
    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score by proximity to grid center roads (prefer cells between road intersections)
        # Find cell center between roads
        best_score = np.zeros(len(cxs))
        for i, (cx2, cy2) in enumerate(zip(cxs, cys)):
            # Prefer locations snapped to grid midpoints
            h_dist = min(abs(cy2 - hy) for hy in (ah if ah else [50]))
            v_dist = min(abs(cx2 - vx) for vx in (av if av else [60]))
            # Ideal zone center is ~3 tiles from road
            h_score = -abs(h_dist - 3)
            v_score = -abs(v_dist - 3)
            best_score[i] = h_score + v_score

        order = np.argsort(-best_score)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- EXTEND ROADS into powered empty areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 100)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- EXTEND WIRE from existing wire/plants ----
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 80)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- CIVIC SERVICES ----
    if pop > 100:
        fire_spots = [(fx, fy) for fx in range(20, WORLD_W, 18) for fy in range(20, WORLD_H, 18)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(px2, py2) for px2 in range(25, WORLD_W, 22) for py2 in range(25, WORLD_H, 22)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadiums = [
            (30, 26), (65, 26), (100, 26),
            (30, 55), (65, 55), (100, 55),
            (30, 82), (65, 82), (100, 82),
        ]
        for (sx, sy) in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        seaports = [(8, 92), (112, 92), (8, 8), (112, 8), (60, 96)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(40, 5), (80, 5), (40, 93), (80, 93)]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # ---- NUCLEAR POWER for late game ----
    if pop > 2000 and step % 4 == 0:
        nuclear_spots = [
            (35, 35), (85, 35), (35, 65), (85, 65),
            (60, 20), (60, 80), (15, 50), (105, 50)
        ]
        for (nx2, ny2) in nuclear_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    # ---- PARKS for land value boost ----
    if pop > 300 and step % 4 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power)
        if len(park_xs) > 0:
            idx = (step * 19) % len(park_xs)
            py2, px2 = int(park_ys[idx]), int(park_xs[idx])
            if ib(px2, py2) and bool(em[py2, px2]):
                return (Tool.PARK, px2, py2)

    # ---- FALLBACK: place coal plant if no power ----
    if not bool(np.any(pm)):
        return (Tool.COALPOWER, 60, 50)

    return None

def init(obs, state):
    """Bootstrap: central cluster with power plant, wires, and roads"""
    actions = []
    # Place coal plants at strategic positions
    for px, py in [(60, 50), (20, 50), (100, 50), (60, 20), (60, 80)]:
        actions.append((Tool.COALPOWER, px, py))
    # Horizontal wire spines
    for x in range(1, 119):
        for wy in [20, 50, 80]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines connecting horizontal ones
    for y in range(1, 99):
        for wx in [20, 60, 100]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal wires
    for x in range(1, 119):
        for wy in [20, 50, 80]:
            for offset in [-1, 1]:
                ry = wy + offset
                if 0 < ry < 99:
                    actions.append((Tool.ROAD, x, ry))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    # Key infrastructure rows/cols
    wire_rows = [20, 50, 80]
    wire_cols = [20, 60, 100]
    sec_wire_rows = [35, 65, 10, 90]
    sec_wire_cols = [40, 80, 10, 110]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # STEP 1: Reactively check if primary wire rows are complete
    # Fill gaps in horizontal wires
    if step % 10 == 0:
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and not bool(rm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx-1]) or bool(pm[wr, wx-1]))
                    right = wx < WORLD_W-1 and (bool(wm[wr, wx+1]) or bool(pm[wr, wx+1]))
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Fill gaps in vertical wires
    if step % 10 == 1:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and not bool(rm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy-1, wc]) or bool(pm[wy-1, wc]))
                    down = wy < WORLD_H-1 and (bool(wm[wy+1, wc]) or bool(pm[wy+1, wc]))
                    if up or down:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # STEP 2: Fix road gaps along wire row flanks
    if step % 10 == 2:
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if not bool(rm[ry, rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Only if adjacent wire exists
                        if bool(wm[wr, rx]) or bool(pm[wr, rx]):
                            return (Tool.ROAD, rx, ry)

    # STEP 3: Secondary wire rows (expand coverage)
    if step % 10 == 3:
        for wr in sec_wire_rows:
            row_has_wire = np.any(wm[wr, :])
            if not row_has_wire:
                # Start from a wire col
                for wc in wire_cols:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                # Extend existing wire
                for wx in range(1, WORLD_W - 1):
                    if not bool(wm[wr, wx]) and bool(em[wr, wx]) and not bool(pm[wr, wx]):
                        left = wx > 0 and bool(wm[wr, wx-1])
                        right = wx < WORLD_W-1 and bool(wm[wr, wx+1])
                        if left or right:
                            return (Tool.WIRE, wx, wr)

    # STEP 4: Secondary vertical wire cols
    if step % 10 == 4:
        for wc in sec_wire_cols:
            col_has_wire = np.any(wm[:, wc])
            if not col_has_wire:
                for wr in wire_rows:
                    if ib(wc, wr) and bool(em[wr, wc]):
                        return (Tool.WIRE, wc, wr)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(wm[wy, wc]) and bool(em[wy, wc]) and not bool(pm[wy, wc]):
                        up = wy > 0 and bool(wm[wy-1, wc])
                        down = wy < WORLD_H-1 and bool(wm[wy+1, wc])
                        if up or down:
                            return (Tool.WIRE, wc, wy)

    # STEP 5: Extend roads reactively from existing roads near power
    if step % 10 == 5:
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 13 + pop * 7) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                    nx2, ny2 = rx2+dx2, ry2+dy2
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # STEP 6: Wire toward unpowered zones
    if step % 10 == 6:
        unpow_zones = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpow_zones)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # STEP 7: Civic services
    if step % 10 == 7:
        if pop > 10:
            fire_spots = [(5,5),(35,5),(65,5),(95,5),(115,5),
                          (5,25),(35,25),(65,25),(95,25),(115,25),
                          (5,50),(65,50),(115,50),
                          (5,70),(35,70),(65,70),(95,70),(115,70),
                          (5,93),(35,93),(65,93),(95,93),(115,93)]
            for sx, sy in fire_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 80:
            police_spots = [(15,15),(45,15),(75,15),(105,15),
                            (15,45),(45,45),(75,45),(105,45),
                            (15,75),(45,75),(75,75),(105,75)]
            for sx, sy in police_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 300:
            stadium_spots = [(35,35),(85,35),(35,65),(85,65),(60,50)]
            for sx, sy in stadium_spots:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 600:
            nuke_spots = [(5,5),(113,5),(5,93),(113,93),(60,5),(60,93),(5,50),(113,50)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2,ny2) and bool(em[ny2,nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            seaports = [(5,93),(113,93),(30,93),(90,93),(5,5),(113,5)]
            for sx, sy in seaports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 2000:
            airports = [(48,5),(72,5),(48,90),(72,90),(5,43),(5,57),(113,43),(113,57)]
            for sx, sy in airports:
                if ib(sx,sy) and bool(em[sy,sx]):
                    return (Tool.AIRPORT, sx, sy)

    # STEP 8: Cross-streets (mid-row roads connecting wire flanks)
    if step % 10 == 8:
        all_wire_rows = sorted(wire_rows + sec_wire_rows)
        for i in range(len(all_wire_rows) - 1):
            r1, r2 = all_wire_rows[i], all_wire_rows[i+1]
            mid_y = (r1 + r2) // 2
            for rx in range(2, WORLD_W - 2):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]):
                    adj = (ib(rx-1, mid_y) and bool(rm[mid_y, rx-1])) or \
                          (ib(rx+1, mid_y) and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # --- ZONE PLACEMENT (main closed-loop action) ---
    avoid_rows = sorted(wire_rows + sec_wire_rows)
    avoid_cols = sorted(wire_cols + sec_wire_cols)

    cand_mask = em & near_road & near_power
    cand_mask[0:4, :] = False
    cand_mask[WORLD_H-4:, :] = False
    cand_mask[:, 0:4] = False
    cand_mask[:, WORLD_W-4:] = False
    for wr in avoid_rows:
        cand_mask[max(0,wr-1):wr+2, :] = False
    for wc in avoid_cols:
        cand_mask[:, max(0,wc-1):wc+2] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        # Focus near center clusters, prefer near existing zones
        cx_center = WORLD_W // 2
        cy_center = WORLD_H // 2
        # Score: distance to center (weighted) + bonus for near existing zones
        dist_center = np.abs(cxs2 - cx_center).astype(float) + np.abs(cys2 - cy_center).astype(float)

        # Also attract to areas with existing zones (for clustering)
        zone_ys_e, zone_xs_e = np.where(zone_tiles)
        if len(zone_xs_e) > 0:
            near_zone = np.zeros(len(cxs2))
            for i in range(len(cxs2)):
                d = np.min(np.abs(zone_xs_e - cxs2[i]) + np.abs(zone_ys_e - cys2[i]))
                near_zone[i] = d
            score = dist_center * 0.3 + near_zone * 0.7
        else:
            score = dist_center

        order = np.argsort(score)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks for land value boost
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: extend any wire to reach more area
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3,ny3) and bool(em[ny3,nx3]) and not bool(pm[ny3,nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # Fallback: extend road from zone tiles
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2,0),(-2,0),(0,2),(0,-2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: central power plant + wire grid + roads"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(1, 99):
        actions.append((Tool.WIRE, 60, y))
    # Roads flanking spines
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 48))
        actions.append((Tool.ROAD, x, 52))
    for y in range(1, 99):
        actions.append((Tool.ROAD, 58, y))
        actions.append((Tool.ROAD, 62, y))
    # Corner power plants
    actions.append((Tool.COALPOWER, 20, 20))
    actions.append((Tool.COALPOWER, 100, 20))
    actions.append((Tool.COALPOWER, 20, 80))
    actions.append((Tool.COALPOWER, 100, 80))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # Wire corridor grid - denser than parent
    wire_rows = [10, 20, 30, 40, 50, 60, 70, 80, 90]
    wire_cols = [10, 22, 34, 46, 58, 70, 82, 94, 106, 118]

    # ---- PHASE 1: ENSURE PLANTS NEAR WIRE INTERSECTIONS ----
    plant_positions = [
        (10, 10), (58, 10), (106, 10),
        (10, 50), (58, 50), (106, 50),
        (10, 90), (58, 90), (106, 90),
    ]
    for px, py in plant_positions:
        x0, x1 = max(0, px-7), min(WORLD_W, px+8)
        y0, y1 = max(0, py-7), min(WORLD_H, py+8)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- CLOSED-LOOP WIRE EXTENSION ----
    # Find wire frontiers: wire-adjacent empty tiles not on plants
    # Extend wires along corridors reactively

    # Check horizontal wire rows: extend any gap adjacent to existing wire
    for wr in wire_rows:
        if wr >= WORLD_H:
            continue
        row_power = wm[wr, :] | pm[wr, :]
        if not np.any(row_power):
            # No wire on this row: connect from nearest plant
            plant_ys, plant_xs = np.where(pm)
            if len(plant_xs) > 0:
                dists = np.abs(plant_ys - wr)
                best = np.argmin(dists)
                bpx, bpy = int(plant_xs[best]), int(plant_ys[best])
                step_y = 1 if wr > bpy else -1
                for ny in range(bpy + step_y, wr + step_y, step_y):
                    if ib(bpx, ny) and bool(em[ny, bpx]) and not bool(pm[ny, bpx]):
                        return (Tool.WIRE, bpx, ny)
        else:
            # Extend gaps in this row
            for wx in range(1, WORLD_W - 1):
                if not bool(row_power[wx]) and not bool(pm[wr, wx]):
                    left = bool(row_power[wx-1]) if wx > 0 else False
                    right = bool(row_power[wx+1]) if wx < WORLD_W-1 else False
                    if left or right:
                        if bool(em[wr, wx]):
                            return (Tool.WIRE, wx, wr)

    # Check vertical wire cols: extend any gap adjacent to existing wire
    for wc in wire_cols:
        if wc >= WORLD_W:
            continue
        col_power = wm[:, wc] | pm[:, wc]
        if not np.any(col_power):
            plant_ys, plant_xs = np.where(pm)
            if len(plant_xs) > 0:
                dists = np.abs(plant_xs - wc)
                best = np.argmin(dists)
                bpx2, bpy2 = int(plant_xs[best]), int(plant_ys[best])
                step_x = 1 if wc > bpx2 else -1
                for nx in range(bpx2 + step_x, wc + step_x, step_x):
                    if ib(nx, bpy2) and bool(em[bpy2, nx]) and not bool(pm[bpy2, nx]):
                        return (Tool.WIRE, nx, bpy2)
        else:
            for wy in range(1, WORLD_H - 1):
                if not bool(col_power[wy]) and not bool(pm[wy, wc]):
                    up = bool(col_power[wy-1]) if wy > 0 else False
                    dn = bool(col_power[wy+1]) if wy < WORLD_H-1 else False
                    if up or dn:
                        if bool(em[wy, wc]):
                            return (Tool.WIRE, wc, wy)

    # ---- CLOSED-LOOP ROAD EXTENSION ----
    # Roads run parallel to wire corridors, offset by 1
    road_offsets = [-1, 1, -2, 2]

    # Horizontal roads flanking wire rows
    for wr in wire_rows:
        row_power = wm[wr, :] | pm[wr, :]
        if not np.any(row_power):
            continue
        for offset in road_offsets[:2]:
            ry = wr + offset
            if not (1 <= ry < WORLD_H - 1):
                continue
            for rx in range(1, WORLD_W - 1):
                if bool(row_power[rx]) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    return (Tool.ROAD, rx, ry)

    # Vertical roads flanking wire cols
    for wc in wire_cols:
        col_power = wm[:, wc] | pm[:, wc]
        if not np.any(col_power):
            continue
        for offset in road_offsets[:2]:
            rcx = wc + offset
            if not (1 <= rcx < WORLD_W - 1):
                continue
            for ry in range(1, WORLD_H - 1):
                if bool(col_power[ry]) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                    return (Tool.ROAD, rcx, ry)

    # Connect road network: extend roads toward powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        target_mask = near_power & ~near_road & em
        target_mask[:3, :] = False
        target_mask[WORLD_H-3:, :] = False
        target_mask[:, :3] = False
        target_mask[:, WORLD_W-3:] = False
        tys, txs = np.where(target_mask)
        if len(txs) > 0:
            ti = (step * 17 + pop) % len(txs)
            tx, ty = int(txs[ti]), int(tys[ti])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best_ri = np.argmin(dists)
            brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- ZONE PLACEMENT ----
    cand_mask = em & near_road & near_power
    cand_mask[:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, :3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Keep zones away from wire corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[wr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, wc] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        road_near = dilate(rm, 3)

        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            # Prefer near existing zones (density)
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            # Prefer near roads (connectivity)
            scores[i] += 1.0 if bool(road_near[y, x]) else 0.0
            # Center preference slight
            scores[i] += 0.5 / (1.0 + abs(x - 60)/60.0 + abs(y - 50)/50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 50:
        fire_positions = [
            (15, 9), (45, 9), (75, 9), (105, 9),
            (15, 35), (45, 35), (75, 35), (105, 35),
            (15, 60), (45, 60), (75, 60), (105, 60),
            (15, 85), (45, 85), (75, 85), (105, 85),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (30, 22), (60, 22), (90, 22),
            (15, 45), (45, 45), (75, 45), (105, 45),
            (30, 68), (60, 68), (90, 68),
            (15, 88), (45, 88), (75, 88), (105, 88),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 500:
        stadiums = [
            (30, 32), (90, 32), (30, 68), (90, 68),
            (60, 20), (60, 80),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (5, 5), (115, 5), (5, 94), (115, 94),
            (60, 5), (5, 50), (115, 50), (60, 94),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(50, 5), (70, 5), (50, 92), (70, 92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks reactively to boost land value
    if pop > 100 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: wire toward unpowered roads ----
    needs_power = rm & ~near_power
    npys, npxs = np.where(needs_power)
    if len(npxs) > 0:
        ti = (step * 23) % len(npxs)
        tx, ty = int(npxs[ti]), int(npys[ti])
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend roads near existing powered roads ----
    road_ys2, road_xs2 = np.where(rm & near_power)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zones ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire spine and road grid"""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine at y=50
    for x in range(1, 119):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires at key columns
    for y in range(1, 99):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Roads above and below wire spine
    for x in range(1, 119):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    # Target mix: 45% res, 30% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    # Wire/road grid layout - denser than parent
    wire_rows = [8, 18, 28, 38, 48, 58, 68, 78, 88, 97]
    wire_cols = [8, 18, 30, 42, 54, 66, 78, 90, 102, 112]

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- REACTIVE INFRASTRUCTURE ----
    # Step mod determines action type, but each checks current map state

    phase = step % 12

    # Phase 0: Check if any region lacks a power plant and add one
    if phase == 0:
        plant_targets = [
            (30, 50), (90, 50),
            (15, 20), (55, 20), (95, 20),
            (15, 80), (55, 80), (95, 80),
            (30, 35), (90, 35), (30, 65), (90, 65),
            (60, 10), (60, 90),
        ]
        for px, py in plant_targets:
            x0, x1 = max(0, px - 18), min(WORLD_W, px + 19)
            y0, y1 = max(0, py - 18), min(WORLD_H, py + 19)
            has_plant = bool(np.any(pm[y0:y1, x0:x1]))
            if not has_plant:
                # Find nearest empty cell
                for r in range(0, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r or r == 0:
                                nx2, ny2 = px + dx, py + dy
                                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                    return (Tool.COALPOWER, nx2, ny2)

    # Phase 1: Extend wire from existing wire/plant toward gaps
    if phase == 1:
        # Find wire rows that are incomplete
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]) and bool(em[wr, wx]):
                    # Check if adjacent to existing wire/plant
                    if (bool(wm[wr, max(0, wx-1)]) or bool(pm[wr, max(0, wx-1)]) or
                        bool(wm[wr, min(WORLD_W-1, wx+1)]) or bool(pm[wr, min(WORLD_W-1, wx+1)]) or
                        bool(wm[max(0, wr-1), wx]) or bool(pm[max(0, wr-1), wx]) or
                        bool(wm[min(WORLD_H-1, wr+1), wx]) or bool(pm[min(WORLD_H-1, wr+1), wx])):
                        return (Tool.WIRE, wx, wr)

    # Phase 2: Extend wire columns
    if phase == 2:
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]) and bool(em[wy, wc]):
                    if (bool(wm[max(0, wy-1), wc]) or bool(pm[max(0, wy-1), wc]) or
                        bool(wm[min(WORLD_H-1, wy+1), wc]) or bool(pm[min(WORLD_H-1, wy+1), wc]) or
                        bool(wm[wy, max(0, wc-1)]) or bool(pm[wy, max(0, wc-1)]) or
                        bool(wm[wy, min(WORLD_W-1, wc+1)]) or bool(pm[wy, min(WORLD_W-1, wc+1)])):
                        return (Tool.WIRE, wc, wy)

    # Phase 3: Roads parallel to wire rows (2 tiles away)
    if phase == 3:
        for wr in wire_rows:
            for offset in [-2, 2]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        # Only extend road if adjacent to existing road or near wire
                        near_wire_here = (
                            (ry > 0 and (bool(wm[ry-1, rx]) or bool(pm[ry-1, rx]))) or
                            (ry < WORLD_H-1 and (bool(wm[ry+1, rx]) or bool(pm[ry+1, rx])))
                        )
                        adj_road = (
                            (rx > 0 and bool(rm[ry, rx-1])) or
                            (rx < WORLD_W-1 and bool(rm[ry, rx+1])) or
                            (ry > 0 and bool(rm[ry-1, rx])) or
                            (ry < WORLD_H-1 and bool(rm[ry+1, rx]))
                        )
                        if near_wire_here or adj_road:
                            return (Tool.ROAD, rx, ry)

    # Phase 4: Roads parallel to wire cols
    if phase == 4:
        for wc in wire_cols:
            for offset in [-2, 2]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry2 in range(1, WORLD_H - 1):
                    if bool(em[ry2, rcx]) and not bool(pm[ry2, rcx]):
                        near_wire_here = (
                            (rcx > 0 and (bool(wm[ry2, rcx-1]) or bool(pm[ry2, rcx-1]))) or
                            (rcx < WORLD_W-1 and (bool(wm[ry2, rcx+1]) or bool(pm[ry2, rcx+1])))
                        )
                        adj_road = (
                            (ry2 > 0 and bool(rm[ry2-1, rcx])) or
                            (ry2 < WORLD_H-1 and bool(rm[ry2+1, rcx])) or
                            bool(rm[ry2, max(0, rcx-1)]) or
                            bool(rm[ry2, min(WORLD_W-1, rcx+1)])
                        )
                        if near_wire_here or adj_road:
                            return (Tool.ROAD, rcx, ry2)

    # Phase 5: Cross-connect roads between wire row corridors
    if phase == 5:
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = (rx > 0 and bool(rm[mid_y, rx-1])) or (rx < WORLD_W-1 and bool(rm[mid_y, rx+1]))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    # Phase 6: Wire to unpowered zones (reactive)
    if phase == 6:
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                idx = (step * 17) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy), (bwx+dx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # Phase 7: Road to zones without road access
    if phase == 7:
        no_road_zones = zone_tiles & ~near_road
        nrz_ys, nrz_xs = np.where(no_road_zones)
        if len(nrz_xs) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 19) % len(nrz_xs)
                tx, ty = int(nrz_xs[idx]), int(nrz_ys[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC SERVICES (reactive to population) ----
    if pop > 10:
        fire_spots = [
            (8, 8), (40, 8), (70, 8), (100, 8),
            (8, 30), (115, 30), (8, 50), (115, 50),
            (8, 70), (115, 70), (8, 92), (40, 92), (70, 92), (100, 92),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (55, 50), (65, 50),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 80:
        police_spots = [
            (20, 15), (60, 15), (100, 15),
            (20, 45), (60, 45), (100, 45),
            (20, 65), (60, 65), (100, 65),
            (20, 85), (60, 85), (100, 85),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        stadium_spots = [
            (25, 25), (75, 25), (25, 75), (75, 75),
            (50, 10), (50, 90), (10, 50), (110, 50),
        ]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 500:
        nuke_spots = [
            (10, 10), (110, 10), (10, 90), (110, 90),
            (10, 50), (110, 50), (60, 10), (60, 90),
            (30, 10), (90, 10), (30, 90), (90, 90),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1000:
        seaports = [(5, 85), (110, 85), (5, 15), (110, 15)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 1800:
        airports = [(45, 5), (65, 5), (45, 94), (65, 94)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 100 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[0:3, :] = False
        park_cands[WORLD_H-3:, :] = False
        park_cands[:, 0:3] = False
        park_cands[:, WORLD_W-3:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 37 + pop * 5) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- ZONE PLACEMENT (main loop) ----
    # Build candidate mask: empty cells near both road and power
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/road spines
    for wr in wire_rows:
        cand_mask[max(0, wr-1):wr+2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc-1):wc+2] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Define active zone centers based on population
        if pop < 100:
            # Focus on center cross
            active_centers = [
                (60, 50), (45, 50), (75, 50), (60, 38), (60, 62),
                (45, 38), (75, 38), (45, 62), (75, 62),
                (30, 50), (90, 50), (60, 25), (60, 75),
            ]
        elif pop < 300:
            active_centers = []
            for row in range(5):
                for col in range(7):
                    cx = 10 + col * 16
                    cy = 10 + row * 20
                    active_centers.append((cx, cy))
        elif pop < 800:
            active_centers = []
            for row in range(7):
                for col in range(9):
                    cx = 7 + col * 13
                    cy = 7 + row * 13
                    active_centers.append((cx, cy))
        elif pop < 2000:
            active_centers = []
            for row in range(9):
                for col in range(11):
                    cx = 5 + col * 11
                    cy = 5 + row * 10
                    active_centers.append((cx, cy))
        else:
            active_centers = []
            for row in range(10):
                for col in range(12):
                    cx = 5 + col * 10
                    cy = 5 + row * 9
                    active_centers.append((cx, cy))

        best_dist = np.full(len(cxs), 999999.0)
        for (hx, hy) in active_centers:
            d = np.abs(cxs - hx).astype(float) + np.abs(cys - hy).astype(float)
            best_dist = np.minimum(best_dist, d)

        order = np.argsort(best_dist)
        tool = pick_tool()
        # Use population and step to vary which candidate we pick (reactivity)
        offset = (step * 11 + pop * 7) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- FALLBACKS ----
    # Extend road from existing roads into powered areas
    road_ys, road_xs = np.where(rm)
    if len(road_xs) > 0:
        sk = (step * 13) % len(road_xs)
        for off in range(min(len(road_xs), 300)):
            k = (sk + off * 9) % len(road_xs)
            rx2, ry2 = int(road_xs[k]), int(road_ys[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # Extend wire from existing wires
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 17) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 150)):
            k = (sk2 + off * 7) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spines + flanking roads."""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire at y=50 connecting plants
    for x in range(25, 95):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires at x=30, 60, 90
    for y in range(30, 70):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 60, y))
        actions.append((Tool.WIRE, 90, y))
    # Roads flanking the horizontal wire
    for x in range(25, 95):
        actions.append((Tool.ROAD, x, 49))
        actions.append((Tool.ROAD, x, 51))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    near_power = dilate(wm | pm, 4)
    near_road = dilate(rm, 2)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        rr = res_count / total_zones
        if pop < 200:
            if ir < 0.25: return Tool.INDUSTRIAL
            if cr < 0.20: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        elif pop < 800:
            if ir < 0.20: return Tool.INDUSTRIAL
            if cr < 0.28: return Tool.COMMERCIAL
            return Tool.RESIDENTIAL
        else:
            if cr < 0.30: return Tool.COMMERCIAL
            if rr < 0.50: return Tool.RESIDENTIAL
            if ir < 0.20: return Tool.INDUSTRIAL
            return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr): return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # --- NEIGHBORHOOD GRID ---
    # 4 columns x 4 rows = up to 16 neighborhoods
    neighborhood_configs = []
    for col_i, cx in enumerate([20, 45, 75, 100]):
        for row_i, cy in enumerate([15, 38, 62, 85]):
            neighborhood_configs.append((cx, cy, col_i * 4 + row_i))

    def num_active():
        if pop < 50:   return 1
        if pop < 150:  return 2
        if pop < 300:  return 4
        if pop < 600:  return 6
        if pop < 1000: return 8
        if pop < 1800: return 12
        return 16

    active = neighborhood_configs[:num_active()]

    # --- PRIORITY 1: Ensure power plants for each active neighborhood ---
    for (px, py, idx) in active:
        has_plant = bool(np.any(pm[max(0,py-5):min(WORLD_H,py+6),
                                   max(0,px-5):min(WORLD_W,px+6)]))
        if not has_plant:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)
            for r in range(1, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # --- PRIORITY 2: Build vertical wire spines for each active neighborhood ---
    pop_ext = min(16, 4 + pop // 80)
    for (px, py, idx) in active:
        wc = px
        spine_top = max(2, py - pop_ext)
        spine_bot = min(WORLD_H - 3, py + pop_ext)
        wire_col = [r for r in range(WORLD_H) if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]
        if not wire_col:
            for dy in range(-5, 6):
                ny = py + dy
                if ib(wc, ny) and bool(em[ny, wc]) and not bool(pm[ny, wc]):
                    return (Tool.WIRE, wc, ny)
        else:
            min_wr = min(wire_col)
            max_wr = max(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(wc, nr) and not bool(pm[nr, wc]) and (bool(em[nr, wc]) or bool(wm[nr, wc])):
                    return (Tool.WIRE, wc, nr)

    # --- PRIORITY 3: Horizontal wire connections between same-row neighborhoods ---
    row_groups = {}
    for (px, py, idx) in active:
        if py not in row_groups:
            row_groups[py] = []
        row_groups[py].append(px)
    for row_y, cols in row_groups.items():
        if len(cols) < 2:
            continue
        cols_sorted = sorted(cols)
        for i in range(len(cols_sorted)-1):
            wc1, wc2 = cols_sorted[i], cols_sorted[i+1]
            for cx in range(wc1+1, wc2):
                if ib(cx, row_y) and bool(em[row_y, cx]) and not bool(pm[row_y, cx]):
                    return (Tool.WIRE, cx, row_y)

    # --- PRIORITY 4: Roads flanking wire spines ---
    for (px, py, idx) in active:
        wc = px
        rl, rr = wc - 1, wc + 1
        wire_rows = [r for r in range(WORLD_H) if ib(wc, r) and (bool(wm[r, wc]) or bool(pm[r, wc]))]
        if not wire_rows:
            continue
        cycle = (step + idx * 7) % max(len(wire_rows), 1)
        for offset in range(min(len(wire_rows), 10)):
            wr = wire_rows[(cycle + offset) % len(wire_rows)]
            if ib(rl, wr) and bool(em[wr, rl]) and not bool(pm[wr, rl]):
                return (Tool.ROAD, rl, wr)
            if ib(rr, wr) and bool(em[wr, rr]) and not bool(pm[wr, rr]):
                return (Tool.ROAD, rr, wr)

    # --- PRIORITY 5: Horizontal roads at anchor Y connecting neighborhoods ---
    for (px, py, idx) in active:
        wc = px
        for dx in range(-6, 7):
            rx = wc + dx
            if ib(rx, py) and bool(em[py, rx]) and not bool(pm[py, rx]) and not bool(wm[py, rx]):
                near_w = any(ib(rx+d, py) and (bool(wm[py, rx+d]) or bool(pm[py, rx+d])) for d in [-1, 1])
                if near_w:
                    return (Tool.ROAD, rx, py)

    # --- PRIORITY 6: Connect unpowered zones via wire ---
    unpowered_zones = zone_tiles & ~near_power
    if np.any(unpowered_zones):
        uz_ys, uz_xs = np.where(unpowered_zones)
        wire_ys, wire_xs = np.where(wm | pm)
        if len(wire_xs) > 0:
            tidx = (step * 7) % len(uz_xs)
            tx, ty = int(uz_xs[tidx]), int(uz_ys[tidx])
            dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
            best = np.argmin(dists)
            bwx, bwy = int(wire_xs[best]), int(wire_ys[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- PRIORITY 7: Road toward zones without road access ---
    zones_no_road = zone_tiles & ~near_road
    if np.any(zones_no_road):
        zr_ys, zr_xs = np.where(zones_no_road)
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            tidx = (step * 11) % len(zr_xs)
            tx, ty = int(zr_xs[tidx]), int(zr_ys[tidx])
            dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
            best = np.argmin(dists)
            brx, bry = int(road_xs[best]), int(road_ys[best])
            dx = 0 if tx == brx else (1 if tx > brx else -1)
            dy = 0 if ty == bry else (1 if ty > bry else -1)
            for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # --- PRIORITY 8: Zone placement ---
    # Build proximity masks
    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy in range(-2, 3):
        for dx in range(-2, 3):
            sr0=max(0,-dy); sr1=min(WORLD_H,WORLD_H-dy)
            sc0=max(0,-dx); sc1=min(WORLD_W,WORLD_W-dx)
            r0=max(0,dy); r1=min(WORLD_H,WORLD_H+dy)
            c0=max(0,dx); c1=min(WORLD_W,WORLD_W+dx)
            nbr_road[r0:r1,c0:c1] |= rm[sr0:sr1,sc0:sc1]

    cand_mask = em & nbr_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Score: closer to active neighborhood anchors
        best_dist = np.full(len(cxs), 999999.0)
        for (px, py, idx) in active:
            d = np.abs(cxs.astype(float) - px) + np.abs(cys.astype(float) - py)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        step_off = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(step_off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (pick_tool(), zx, zy)
            checked += 1
            if checked > 200:
                break

    # --- CIVIC SERVICES (pop-gated) ---
    if pop > 50:
        fire_spots = [(sx, sy) for sx in [15,40,70,100] for sy in [8,35,62,90]]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 300:
        police_spots = [(sx, sy) for sx in [25,55,85,110] for sy in [20,50,80]]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        stadium_spots = [(30,25),(90,25),(30,75),(90,75),(60,50)]
        for sx, sy in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1200:
        nuke_spots = [(10,50),(110,50),(60,5),(60,95),(10,25),(110,25),(10,75),(110,75)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 2000:
        seaports = [(5,94),(115,94),(5,5),(115,5),(60,94)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 3000:
        airports = [(50,5),(70,5),(50,92),(70,92)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 7 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx2 = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx2]), int(pys[idx2]))

    # --- FALLBACK: extend wire toward unpowered empty areas ---
    no_power_em = em & ~near_power
    if np.any(no_power_em):
        np_ys, np_xs = np.where(no_power_em)
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            tidx = (step * 13) % len(np_xs)
            tx, ty = int(np_xs[tidx]), int(np_ys[tidx])
            dists = np.abs(wire_xs2 - tx) + np.abs(wire_ys2 - ty)
            best = np.argmin(dists)
            bwx, bwy = int(wire_xs2[best]), int(wire_ys2[best])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # --- FALLBACK: extend road near wire ---
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 50)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0,1),(0,-1),(1,0),(-1,0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2,ny2) and bool(em[ny2,nx2]) and not bool(pm[ny2,nx2]) and bool(near_power[ny2,nx2]):
                    return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants + wire spine + initial roads."""
    actions = []
    # Two coal plants
    actions.append((Tool.COALPOWER, 30, 50))
    actions.append((Tool.COALPOWER, 90, 50))
    # Horizontal wire spine between them
    for x in range(32, 90):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wires from each plant
    for y in range(44, 57):
        actions.append((Tool.WIRE, 30, y))
        actions.append((Tool.WIRE, 90, y))
    # Roads above and below wire spine
    for x in range(10, 110):
        actions.append((Tool.ROAD, x, 47))
        actions.append((Tool.ROAD, x, 53))
    return actions[:40]


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy().astype(bool)
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 4)
    near_road = dilate(rm, 3)

    def pick_tool():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.28:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- STEP 1: Ensure power plants are distributed ----
    # One plant per ~25x25 region
    plant_grid_xs = list(range(20, WORLD_W - 10, 25))
    plant_grid_ys = list(range(20, WORLD_H - 10, 25))
    for ppy in plant_grid_ys:
        for ppx in plant_grid_xs:
            x0, x1 = max(0, ppx - 12), min(WORLD_W, ppx + 13)
            y0, y1 = max(0, ppy - 12), min(WORLD_H, ppy + 13)
            if not np.any(pm[y0:y1, x0:x1]):
                # Find empty spot near grid point
                for r in range(0, 8):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) != r and abs(dy) != r:
                                continue
                            nx, ny = ppx + dx, ppy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # ---- STEP 2: Expand wire network reactively ----
    # Wire adjacent to existing power toward unpowered areas
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src, dtype=bool)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    # Every few steps, extend wire toward road tiles lacking power
    if step % 3 != 2:
        unpower_roads = rm & ~near_power
        ur_ys, ur_xs = np.where(unpower_roads)
        if len(ur_xs) > 0:
            wire_cand = em & adj_to_power & ~zone_tiles
            wire_cand[0:3, :] = False; wire_cand[WORLD_H-3:, :] = False
            wire_cand[:, 0:3] = False; wire_cand[:, WORLD_W-3:] = False
            wys, wxs = np.where(wire_cand)
            if len(wxs) > 0:
                # Pick wire candidate closest to an unpowered road tile
                idx = (step * 17) % len(ur_xs)
                tx, ty = int(ur_xs[idx]), int(ur_ys[idx])
                dists = np.abs(wxs - tx) + np.abs(wys - ty)
                best = int(np.argmin(dists))
                return (Tool.WIRE, int(wxs[best]), int(wys[best]))

        # Also wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        uz_ys, uz_xs = np.where(unpowered_zones)
        if len(uz_xs) > 0:
            wire_cand = em & adj_to_power & ~zone_tiles
            wire_cand[0:3, :] = False; wire_cand[WORLD_H-3:, :] = False
            wire_cand[:, 0:3] = False; wire_cand[:, WORLD_W-3:] = False
            wys, wxs = np.where(wire_cand)
            if len(wxs) > 0:
                idx = (step * 13) % len(uz_xs)
                tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
                dists = np.abs(wxs - tx) + np.abs(wys - ty)
                best = int(np.argmin(dists))
                return (Tool.WIRE, int(wxs[best]), int(wys[best]))

    # ---- STEP 3: Expand road network reactively ----
    # Road grid targets: every 6 tiles
    road_targets = []
    for gy in range(8, WORLD_H - 5, 6):
        for gx in range(8, WORLD_W - 5, 6):
            road_targets.append((gx, gy))

    uncovered = [(gx, gy) for gx, gy in road_targets
                 if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm, dtype=bool)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles & ~wm
        road_cand[0:3, :] = False; road_cand[WORLD_H-3:, :] = False
        road_cand[:, 0:3] = False; road_cand[:, WORLD_W-3:] = False

        rys, rxs = np.where(road_cand)
        if len(rxs) > 0:
            best_dist = 1e9
            best_k = 0
            sample = uncovered[:30]
            for i in range(len(rxs)):
                cx, cy = int(rxs[i]), int(rys[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs[best_k]), int(rys[best_k]))
        else:
            # Direct road placement
            for gx, gy in uncovered[:5]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # ---- STEP 4: Zone placement (closed-loop) ----
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False; zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False; zone_cand[:, WORLD_W-4:] = False

    cys, cxs = np.where(zone_cand)
    if len(cxs) > 0:
        # Score candidates: prefer close to roads, reasonable spread
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            rd_stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(road_xs), rd_stride):
                d = (np.abs(cxs - road_xs[i]) + np.abs(cys - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.zeros(len(cxs))

        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            zn_stride = max(1, len(zone_xs) // 80)
            min_zone_dist = np.full(len(cxs), 9999.0)
            for i in range(0, len(zone_xs), zn_stride):
                d = (np.abs(cxs - zone_xs[i]) + np.abs(cys - zone_ys[i])).astype(float)
                min_zone_dist = np.minimum(min_zone_dist, d)
            # Penalize overlap, prefer density clusters
            zone_score = np.where(min_zone_dist < 3, 2000.0,
                         np.where(min_zone_dist < 8, 0.0,
                                  min_zone_dist * 0.3))
        else:
            zone_score = (np.abs(cxs - 60) + np.abs(cys - 50)).astype(float)

        score = road_dist * 1.5 + zone_score * 0.5
        order = np.argsort(score)
        off = (step * 11 + (pop % 23)) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- STEP 5: Civic services tiered by population ----
    if pop > 20:
        fire_grid = [(fx, fy) for fy in range(10, 95, 12) for fx in range(10, 115, 12)]
        for fsx, fsy in fire_grid:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 100:
        police_grid = [(px2, py2) for py2 in range(15, 90, 14) for px2 in range(15, 110, 14)]
        for psx, psy in police_grid:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 200:
        park_cand = em & near_road & near_power
        pys_p, pxs_p = np.where(park_cand)
        if len(pxs_p) > 0:
            idx3 = (step * 31 + pop % 19) % len(pxs_p)
            return (Tool.PARK, int(pxs_p[idx3]), int(pys_p[idx3]))

    if pop > 400:
        for stx, sty in [(35, 35), (85, 35), (35, 70), (85, 70), (60, 50)]:
            if ib(stx, sty) and bool(em[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 600:
        nuke_spots = [(10, 10), (110, 10), (10, 90), (110, 90), (60, 10), (60, 90)]
        for nx, ny in nuke_spots:
            if ib(nx, ny):
                x0, x1 = max(0, nx - 8), min(WORLD_W, nx + 9)
                y0, y1 = max(0, ny - 8), min(WORLD_H, ny + 9)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1000:
        for spx, spy in [(8, 50), (112, 50), (60, 5), (60, 94)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    if pop > 1500:
        for apx, apy in [(50, 5), (70, 5), (50, 93), (70, 93)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    # ---- Fallback: extend wire or road from plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (5, 0), (-5, 0), (0, 5), (0, -5)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)
        for dx2, dy2 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.WIRE, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: 2 coal plants with wire spines and flanking roads."""
    actions = []
    # 2 plants at strategic locations
    for px in [30, 90]:
        py = 50
        actions.append((Tool.COALPOWER, px, py))
        # Vertical wire spine
        for dy in range(-8, 9):
            if dy != 0:
                actions.append((Tool.WIRE, px, py + dy))
        # Flanking roads
        for dy in range(-8, 9):
            actions.append((Tool.ROAD, px - 2, py + dy))
            actions.append((Tool.ROAD, px + 2, py + dy))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    # Zone mix: 50% res, 25% com, 25% ind
    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # Denser grid: 6 cols x 5 rows = 30 neighborhoods
    nh_cols = [15, 33, 55, 77, 99, 113]
    nh_rows = [10, 28, 50, 72, 90]
    all_hoods = [(c, r) for r in nh_rows for c in nh_cols]

    def num_active():
        if pop < 50:    return 4
        if pop < 150:   return 7
        if pop < 400:   return 12
        if pop < 800:   return 18
        if pop < 1500:  return 24
        return len(all_hoods)

    n_active = min(num_active(), len(all_hoods))
    step_size = len(all_hoods) / max(n_active, 1)
    active_hoods = [all_hoods[int(i * step_size)] for i in range(n_active)]

    # Build neighbor masks
    power_src = wm | pm

    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-6, 7):
        for dx2 in range(-6, 7):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-3, 4):
        for dx2 in range(-3, 4):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # PHASE 1: Ensure a power plant near each active hood
    for (hx, hy) in active_hoods:
        x0, x1 = max(0, hx - 14), min(WORLD_W, hx + 15)
        y0, y1 = max(0, hy - 14), min(WORLD_H, hy + 15)
        if not bool(np.any(pm[y0:y1, x0:x1])):
            for r in range(0, 16):
                for dy in range(-r, r + 1):
                    for dx in range(-r, r + 1):
                        if abs(dx) == r or abs(dy) == r or r == 0:
                            nx, ny = hx + dx, hy + dy
                            if ib(nx, ny) and bool(em[ny, nx]):
                                return (Tool.COALPOWER, nx, ny)

    # PHASE 2: Wire spine - extend wire from existing wire/plant toward uncovered hoods
    # Find hoods without power coverage
    unpowered_hoods = [(hx, hy) for (hx, hy) in active_hoods if not bool(nbr_power[hy, hx])]

    if unpowered_hoods:
        # Find nearest wire/plant to each unpowered hood and extend toward it
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        if len(wire_xs_arr) > 0:
            uh = unpowered_hoods[step % len(unpowered_hoods)]
            uhx, uhy = uh
            # Find closest wire
            dists = np.abs(wire_xs_arr - uhx) + np.abs(wire_ys_arr - uhy)
            best_k = int(np.argmin(dists))
            wx_near, wy_near = int(wire_xs_arr[best_k]), int(wire_ys_arr[best_k])
            # Step toward unpowered hood from the nearest wire
            dx_sign = 1 if uhx > wx_near else (-1 if uhx < wx_near else 0)
            dy_sign = 1 if uhy > wy_near else (-1 if uhy < wy_near else 0)
            # Try horizontal first, then vertical
            for (ddx, ddy) in [(dx_sign, 0), (0, dy_sign), (dx_sign, dy_sign)]:
                if ddx == 0 and ddy == 0:
                    continue
                nx, ny = wx_near + ddx, wy_near + ddy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    return (Tool.WIRE, nx, ny)

    # PHASE 3: Extend wire spines to cover all active hoods
    spine_half = min(20, 6 + pop // 25)
    hood_idx = step % max(len(active_hoods), 1)
    hx, hy = active_hoods[hood_idx]

    x0, x1 = max(0, hx - 15), min(WORLD_W, hx + 16)
    y0, y1 = max(0, hy - 15), min(WORLD_H, hy + 16)
    plant_ys, plant_xs = np.where(pm[y0:y1, x0:x1])
    if len(plant_xs) > 0:
        px_local = int(plant_xs[0]) + x0
        py_local = int(plant_ys[0]) + y0
        spine_top = max(2, hy - spine_half)
        spine_bot = min(WORLD_H - 3, hy + spine_half)

        # Wire from plant to hood vertically
        if py_local != hy:
            sd = 1 if hy > py_local else -1
            for wy in range(py_local + sd, hy + sd, sd):
                if not ib(px_local, wy): continue
                if bool(pm[wy, px_local]) or bool(wm[wy, px_local]): continue
                if not bool(em[wy, px_local]): continue
                return (Tool.WIRE, px_local, wy)

        # Extend vertical spine from hood
        wire_col = [r for r in range(spine_top, spine_bot + 1)
                    if ib(hx, r) and bool(wm[r, hx])]
        if not wire_col:
            for dy in range(-4, 5):
                ny = hy + dy
                if ib(hx, ny) and bool(em[ny, hx]) and not bool(pm[ny, hx]):
                    return (Tool.WIRE, hx, ny)
        else:
            max_wr = max(wire_col)
            min_wr = min(wire_col)
            if max_wr < spine_bot:
                nr = max_wr + 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)
            if min_wr > spine_top:
                nr = min_wr - 1
                if ib(hx, nr) and bool(em[nr, hx]) and not bool(pm[nr, hx]):
                    return (Tool.WIRE, hx, nr)

    # PHASE 4: Horizontal wire connecting same-row hoods
    for hy_row in nh_rows:
        row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
        row_hoods.sort(key=lambda h: h[0])
        for i in range(len(row_hoods) - 1):
            hx1 = row_hoods[i][0]
            hx2 = row_hoods[i + 1][0]
            for cx2 in range(hx1 + 1, hx2):
                if ib(cx2, hy_row) and bool(em[hy_row, cx2]) and not bool(pm[hy_row, cx2]) and not bool(wm[hy_row, cx2]):
                    return (Tool.WIRE, cx2, hy_row)

    # PHASE 5: Vertical wire connecting same-column hoods
    if n_active >= 4:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for cy2 in range(hy1 + 1, hy2):
                    if ib(hx_col, cy2) and bool(em[cy2, hx_col]) and not bool(pm[cy2, hx_col]) and not bool(wm[cy2, hx_col]):
                        return (Tool.WIRE, hx_col, cy2)

    # PHASE 6: Roads flanking wire spines (reactive: only where wire exists)
    hood_idx2 = (step + 3) % max(len(active_hoods), 1)
    hx3, hy3 = active_hoods[hood_idx2]
    spine_top3 = max(2, hy3 - spine_half)
    spine_bot3 = min(WORLD_H - 3, hy3 + spine_half)

    wire_col3 = [r for r in range(spine_top3, spine_bot3 + 1)
                 if ib(hx3, r) and (bool(wm[r, hx3]) or bool(pm[r, hx3]))]
    cycle = step % 3
    for wr in wire_col3[cycle::3]:
        for rx in [hx3 - 2, hx3 + 2]:
            if ib(rx, wr) and bool(em[wr, rx]) and not bool(pm[wr, rx]):
                return (Tool.ROAD, rx, wr)

    # PHASE 7: Horizontal roads at hood rows
    if pop > 20:
        for hy_row in nh_rows:
            row_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hy2 == hy_row]
            if len(row_hoods) < 2:
                continue
            row_hoods.sort(key=lambda h: h[0])
            xl = row_hoods[0][0] - 2
            xr = row_hoods[-1][0] + 2
            for horiz_y in [hy_row - 4, hy_row + 4]:
                for cx3 in range(max(2, xl), min(WORLD_W - 2, xr + 1)):
                    if ib(cx3, horiz_y) and bool(em[horiz_y, cx3]) and not bool(pm[horiz_y, cx3]):
                        return (Tool.ROAD, cx3, horiz_y)

    # PHASE 8: Vertical roads connecting hood rows
    if pop > 60 and len(nh_rows) >= 2:
        for hx_col in nh_cols:
            col_hoods = [(hx2, hy2) for (hx2, hy2) in active_hoods if hx2 == hx_col]
            col_hoods.sort(key=lambda h: h[1])
            for i in range(len(col_hoods) - 1):
                hy1 = col_hoods[i][1]
                hy2 = col_hoods[i + 1][1]
                for rx2 in [hx_col - 4, hx_col + 4]:
                    for cy3 in range(hy1, hy2 + 1):
                        if ib(rx2, cy3) and bool(em[cy3, rx2]) and not bool(pm[cy3, rx2]):
                            adj_road = any(
                                ib(ax, ay) and bool(rm[ay, ax])
                                for ax, ay in [(rx2-1,cy3),(rx2+1,cy3),(rx2,cy3-1),(rx2,cy3+1)]
                            )
                            if adj_road or cy3 == hy1 or cy3 == hy2:
                                return (Tool.ROAD, rx2, cy3)

    # PHASE 9: Zone placement - reactive to current power+road coverage
    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr2, nc2 = zy + dr, zx + dc
                if not ib(nc2, nr2):
                    return False
                if not bool(em[nr2, nc2]) and not bool(zone_tiles[nr2, nc2]):
                    return False
        return True

    cand_mask = em & nbr_road & nbr_power
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W - 2:] = False

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        best_dist = np.full(len(cxs), 999999.0)
        for (hx4, hy4) in active_hoods:
            d = np.abs(cxs - hx4).astype(float) + np.abs(cys - hy4).astype(float)
            best_dist = np.minimum(best_dist, d)
        order = np.argsort(best_dist)
        offset = (step * 7) % max(len(order), 1)
        tool = pick_tool()
        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # PHASE 10: Extend roads near powered areas
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % max(len(road_xs2), 1)
        for offset in range(min(len(road_xs2), 200)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx3, ry3 = int(road_xs2[k]), int(road_ys2[k])
            for dx3, dy3 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx3, ny3 = rx3 + dx3, ry3 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]) and bool(nbr_power[ny3, nx3]):
                    return (Tool.ROAD, nx3, ny3)

    # PHASE 11: Civic services
    if pop > 60:
        fire_spots = [(fx, fy)
                      for fx in range(10, WORLD_W, 20)
                      for fy in range(10, WORLD_H, 20)]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 250:
        police_spots = [(px2, py2)
                        for px2 in range(12, WORLD_W, 24)
                        for py2 in range(12, WORLD_H, 24)]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 600:
        stadium_spots = [
            (20, 8), (60, 8), (100, 8),
            (20, 92), (60, 92), (100, 92),
            (8, 50), (112, 50),
        ]
        for (sx, sy) in stadium_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 1000:
        nuke_spots = [
            (6, 6), (114, 6), (6, 94), (114, 94),
            (60, 6), (60, 94), (6, 50), (114, 50),
            (30, 6), (90, 6), (30, 94), (90, 94),
        ]
        for (nx4, ny4) in nuke_spots:
            if ib(nx4, ny4) and bool(em[ny4, nx4]):
                return (Tool.NUCLEARPOWER, nx4, ny4)

    if pop > 2000:
        seaports = [(5, 94), (115, 94), (5, 5), (115, 5), (60, 97)]
        for (sx, sy) in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [
            (40, 5), (80, 5), (40, 94), (80, 94),
            (5, 35), (5, 65), (115, 35), (115, 65),
        ]
        for (sx, sy) in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 150 and step % 4 == 0:
        zone_arr_y2, zone_arr_x2 = np.where(zone_tiles)
        if len(zone_arr_x2) > 0:
            for i in range(min(len(zone_arr_x2), 40)):
                k = (step * 3 + i * 17) % len(zone_arr_x2)
                zx2, zy2 = int(zone_arr_x2[k]), int(zone_arr_y2[k])
                for dx4, dy4 in [(2, 0), (-2, 0), (0, 2), (0, -2), (3, 3), (-3, -3)]:
                    nx4, ny4 = zx2 + dx4, zy2 + dy4
                    if ib(nx4, ny4) and bool(em[ny4, nx4]):
                        return (Tool.PARK, nx4, ny4)

    # Fallback: extend wire from existing wire
    wire_ys_arr, wire_xs_arr = np.where(wm)
    if len(wire_xs_arr) > 0:
        step_k2 = (step * 13) % max(len(wire_xs_arr), 1)
        for offset in range(min(len(wire_xs_arr), 150)):
            k = (step_k2 + offset * 5) % len(wire_xs_arr)
            wx2, wy2 = int(wire_xs_arr[k]), int(wire_ys_arr[k])
            for dx5, dy5 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx5, ny5 = wx2 + dx5, wy2 + dy5
                if ib(nx5, ny5) and bool(em[ny5, nx5]) and not bool(pm[ny5, nx5]):
                    return (Tool.WIRE, nx5, ny5)

    # Fallback: new plant near uncovered hood
    for (hx5, hy5) in active_hoods:
        if not bool(nbr_power[hy5, hx5]):
            for r in range(1, 16):
                for dy6 in range(-r, r + 1):
                    for dx6 in range(-r, r + 1):
                        if abs(dx6) == r or abs(dy6) == r:
                            nx6, ny6 = hx5 + dx6, hy5 + dy6
                            if ib(nx6, ny6) and bool(em[ny6, nx6]):
                                return (Tool.COALPOWER, nx6, ny6)

    return None

def init(obs, state):
    """Bootstrap: two coal plants with wire connections and starter roads."""
    acts = []
    # Left plant
    acts.append((Tool.COALPOWER, 35, 50))
    # Right plant
    acts.append((Tool.COALPOWER, 75, 50))
    # Wire spine between plants along row 50
    for x in range(36, 75):
        acts.append((Tool.WIRE, x, 50))
    # Roads flanking the wire spine
    for x in range(33, 79):
        acts.append((Tool.ROAD, x, 49))
        acts.append((Tool.ROAD, x, 51))
