def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    zone_tiles = resm | comm | indm

    # Central hub
    cx, cy = 60, 50

    # Active radius grows with population
    if pop < 100:
        max_radius = 18
    elif pop < 300:
        max_radius = 28
    elif pop < 800:
        max_radius = 42
    elif pop < 2000:
        max_radius = 60
    else:
        max_radius = 80

    def pick_tool():
        t = total_zones
        ir = ind_count / t
        cr = com_count / t
        if pop < 300 and ir < 0.33:
            return Tool.INDUSTRIAL
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.32:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # Build neighbor masks
    nbr_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    power_src = wm | pm
    for dy2 in range(-5, 6):
        for dx2 in range(-5, 6):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_power[r0:r1, c0:c1] |= power_src[sr0:sr1, sc0:sc1]

    nbr_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy2 in range(-2, 3):
        for dx2 in range(-2, 3):
            sr0 = max(0, -dy2); sr1 = min(WORLD_H, WORLD_H - dy2)
            sc0 = max(0, -dx2); sc1 = min(WORLD_W, WORLD_W - dx2)
            r0 = max(0, dy2);   r1 = min(WORLD_H, WORLD_H + dy2)
            c0 = max(0, dx2);   c1 = min(WORLD_W, WORLD_W + dx2)
            nbr_road[r0:r1, c0:c1] |= rm[sr0:sr1, sc0:sc1]

    # === PHASE 1: Add power plants as city grows ===
    plant_count = int(np.sum(pm))

    if pop > 400 and plant_count < 3:
        for px, py in [(30, 50), (90, 50), (60, 20), (60, 80), (40, 30), (80, 70)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 1500 and plant_count < 5:
        for px, py in [(20, 25), (100, 25), (20, 75), (100, 75), (60, 10), (60, 90)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    if pop > 3000 and plant_count < 7:
        for px, py in [(15, 50), (105, 50), (40, 10), (80, 10), (40, 90), (80, 90)]:
            if ib(px, py) and bool(em[py, px]):
                return (Tool.NUCLEARPOWER, px, py)

    # === PHASE 2: Wire network along axes ===
    if step % 4 == 0:
        # Main wire lines: horizontal and vertical spines, plus secondaries
        wire_lines = [
            [(x, 50) for x in range(1, WORLD_W - 1)],
            [(60, y) for y in range(1, WORLD_H - 1)],
            [(x, 25) for x in range(1, WORLD_W - 1)],
            [(x, 75) for x in range(1, WORLD_W - 1)],
            [(30, y) for y in range(1, WORLD_H - 1)],
            [(90, y) for y in range(1, WORLD_H - 1)],
            [(x, 37) for x in range(1, WORLD_W - 1)],
            [(x, 63) for x in range(1, WORLD_W - 1)],
            [(45, y) for y in range(1, WORLD_H - 1)],
            [(75, y) for y in range(1, WORLD_H - 1)],
        ]
        for line in wire_lines:
            prev_power = False
            for (wx, wy) in line:
                if not ib(wx, wy):
                    continue
                if bool(pm[wy, wx]) or bool(wm[wy, wx]):
                    prev_power = True
                    continue
                dist = abs(wx - cx) + abs(wy - cy)
                if prev_power and bool(em[wy, wx]) and dist <= max_radius + 25:
                    return (Tool.WIRE, wx, wy)
                else:
                    prev_power = False

    # === PHASE 3: Road grid ===
    if step % 4 == 1:
        # Horizontal roads every 4 rows from center
        road_ys = list(range(26, 76, 4))
        for ry in road_ys:
            if abs(ry - cy) > max_radius:
                continue
            x_range = min(max_radius + 5, WORLD_W // 2 - 1)
            for rx in range(max(1, cx - x_range), min(WORLD_W - 1, cx + x_range)):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    adj = (ib(rx-1, ry) and bool(rm[ry, rx-1])) or \
                          (ib(rx+1, ry) and bool(rm[ry, rx+1]))
                    if adj or rx == cx:
                        return (Tool.ROAD, rx, ry)

    elif step % 4 == 2:
        # Vertical roads every 5 cols
        road_xs = list(range(30, 91, 5))
        for rxc in road_xs:
            if abs(rxc - cx) > max_radius:
                continue
            y_range = min(max_radius + 5, WORLD_H // 2 - 1)
            for ry in range(max(1, cy - y_range), min(WORLD_H - 1, cy + y_range)):
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    adj = (ib(rxc, ry-1) and bool(rm[ry-1, rxc])) or \
                          (ib(rxc, ry+1) and bool(rm[ry+1, rxc]))
                    if adj or ry == cy:
                        return (Tool.ROAD, rxc, ry)

    # === PHASE 4: Zone placement ===
    ys_idx = np.arange(WORLD_H).reshape(-1, 1) * np.ones((1, WORLD_W))
    xs_idx = np.arange(WORLD_W).reshape(1, -1) * np.ones((WORLD_H, 1))
    dist_from_center = np.abs(ys_idx - cy) + np.abs(xs_idx - cx)

    cand_mask = em & nbr_road & nbr_power & (dist_from_center <= max_radius)
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys_arr, cxs_arr = np.where(cand_mask)
    if len(cxs_arr) > 0:
        dists = np.abs(cxs_arr - cx) + np.abs(cys_arr - cy)
        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 3) % max(len(order), 1)
        for i in range(min(len(order), 500)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === CIVIC SERVICES ===
    if pop > 120:
        fire_spots = [
            (45, 38), (75, 38), (45, 62), (75, 62),
            (60, 32), (60, 68), (35, 50), (85, 50),
            (30, 30), (90, 30), (30, 70), (90, 70),
            (20, 50), (100, 50), (60, 15), (60, 85),
        ]
        for (sx, sy) in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 350:
        police_spots = [
            (50, 42), (70, 42), (50, 58), (70, 58),
            (42, 50), (78, 50), (60, 42), (60, 58),
            (35, 35), (85, 35), (35, 65), (85, 65),
        ]
        for (sx, sy) in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 800:
        for (sx, sy) in [(54, 44), (66, 44), (54, 56), (66, 56),
                          (40, 44), (80, 44), (40, 56), (80, 56)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 2000:
        for (sx, sy) in [(10, 85), (110, 85), (10, 15), (110, 15),
                          (60, 5), (60, 94)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 4000:
        for (sx, sy) in [(15, 50), (105, 50), (60, 8), (60, 92)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value
    if pop > 250 and step % 6 == 0:
        park_cands = em & nbr_road & nbr_power & (dist_from_center <= max_radius)
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 17) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # === FALLBACKS ===
    # Extend road from existing roads near power
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 100)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            dist = abs(rx2 - cx) + abs(ry2 - cy)
            if dist > max_radius + 5:
                continue
            for dx2, dy2 in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    if bool(nbr_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # Extend wire from existing wire/plant
    if step % 4 == 3:
        wire_ys2, wire_xs2 = np.where(wm | pm)
        if len(wire_xs2) > 0:
            sk2 = (step * 13) % len(wire_xs2)
            for off in range(min(len(wire_xs2), 80)):
                k = (sk2 + off * 5) % len(wire_xs2)
                wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
                for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx3, ny3 = wx2 + dx3, wy2 + dy3
                    if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                        dist = abs(nx3 - cx) + abs(ny3 - cy)
                        if dist <= max_radius + 20:
                            return (Tool.WIRE, nx3, ny3)

    # Last resort: coal plant near center if no power
    if not bool(nbr_power[cy, cx]):
        for r in range(1, 10):
            for dy in range(-r, r + 1):
                for dx in range(-r, r + 1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = cx + dx, cy + dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

