def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    near_power = dilate(wm | pm, 5)
    near_road = dilate(rm, 2)

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    # ---- STEP 1: Ensure power plant coverage across map ----
    # Check neighborhoods every ~8 steps
    if step % 8 == 0:
        # Grid of neighborhood centers
        for py in range(12, WORLD_H - 10, 18):
            for px in range(12, WORLD_W - 10, 20):
                # If no plant within 20 tiles
                x0, x1 = max(0, px - 20), min(WORLD_W, px + 21)
                y0, y1 = max(0, py - 20), min(WORLD_H, py + 21)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    # Find nearest empty spot
                    for r in range(1, 15):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # ---- STEP 2: Extend wires from existing plants/wires ----
    # Every 3 steps, try to grow wires outward
    if step % 6 == 1:
        # Find wire/plant frontier and extend toward unpowered empty
        wire_src = wm | pm
        src_ys, src_xs = np.where(wire_src)
        if len(src_xs) > 0:
            # Find empty tiles not near power
            unpow_em = em & ~near_power
            u_ys, u_xs = np.where(unpow_em)
            if len(u_xs) > 0:
                # Pick a random unpowered target
                idx = (step * 23 + pop * 7) % len(u_xs)
                tx, ty = int(u_xs[idx]), int(u_ys[idx])
                # Find nearest wire source
                dists = np.abs(src_xs - tx) + np.abs(src_ys - ty)
                bi = int(np.argmin(dists))
                bwx, bwy = int(src_xs[bi]), int(src_ys[bi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                # Prefer diagonal then horizontal/vertical step
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy), (bwx + dx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- STEP 3: Extend roads ----
    # Grow roads into powered areas not yet served
    if step % 6 == 2:
        powered_no_road = near_power & em & ~near_road
        p_ys, p_xs = np.where(powered_no_road)
        if len(p_xs) > 0:
            # Find existing road frontier
            r_ys, r_xs = np.where(rm)
            if len(r_xs) > 0:
                idx = (step * 17 + pop * 5) % len(p_xs)
                tx, ty = int(p_xs[idx]), int(p_ys[idx])
                dists = np.abs(r_xs - tx) + np.abs(r_ys - ty)
                bi = int(np.argmin(dists))
                brx, bry = int(r_xs[bi]), int(r_ys[bi])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ---- CIVIC: fire, police, stadium based on pop ----
    if pop > 50 and step % 7 == 3:
        # Fire stations
        for fy in range(10, WORLD_H, 22):
            for fx in range(10, WORLD_W, 22):
                if ib(fx, fy) and bool(em[fy, fx]):
                    return (Tool.FIRESTATION, fx, fy)

    if pop > 150 and step % 7 == 4:
        for py2 in range(15, WORLD_H, 28):
            for px2 in range(15, WORLD_W, 28):
                if ib(px2, py2) and bool(em[py2, px2]):
                    return (Tool.POLICESTATION, px2, py2)

    if pop > 300 and step % 11 == 5:
        for sy in range(20, WORLD_H, 35):
            for sx in range(20, WORLD_W, 35):
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

    if pop > 500 and step % 13 == 6:
        nuke_spots = [(15, 15), (105, 15), (15, 85), (105, 85),
                      (60, 15), (60, 85), (15, 50), (105, 50)]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 800:
        for sx, sy in [(5, 90), (115, 90), (5, 5), (115, 5)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    # Parks to boost land value
    if pop > 100 and step % 5 == 0:
        park_cand = em & near_road & near_power
        park_cand[:3, :] = False; park_cand[WORLD_H-3:, :] = False
        park_cand[:, :3] = False; park_cand[:, WORLD_W-3:] = False
        pys2, pxs2 = np.where(park_cand)
        if len(pxs2) > 0:
            idx = (step * 31 + pop * 3) % len(pxs2)
            return (Tool.PARK, int(pxs2[idx]), int(pys2[idx]))

    # ---- MAIN: Zone placement ----
    # Candidate: empty, near road, near power
    cand = em & near_road & near_power
    cand[:3, :] = False; cand[WORLD_H-3:, :] = False
    cand[:, :3] = False; cand[:, WORLD_W-3:] = False

    c_ys, c_xs = np.where(cand)
    if len(c_xs) > 0:
        tool = pick_tool()

        # Score candidates: prefer central cluster areas
        if pop < 200:
            # Focus near wire spine
            scores = np.abs(c_ys - 50).astype(float)
        elif pop < 500:
            # Spread to rows near roads
            scores = np.minimum(
                np.abs(c_ys - 35).astype(float),
                np.abs(c_ys - 65).astype(float)
            )
        else:
            # Use whole map - score by distance to map grid points
            center_y = ((c_ys // 10) * 10 + 5).astype(float)
            center_x = ((c_xs // 10) * 10 + 5).astype(float)
            scores = np.abs(c_ys - center_y) + np.abs(c_xs - center_x)

        order = np.argsort(scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 800)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(c_xs[k]), int(c_ys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ---- FALLBACK: place wire toward unpowered zones ----
    unpowered_z = zone_tiles & ~near_power
    uz_ys, uz_xs = np.where(unpowered_z)
    if len(uz_xs) > 0:
        ws_ys, ws_xs = np.where(wm | pm)
        if len(ws_xs) > 0:
            idx = (step * 17) % len(uz_xs)
            tx, ty = int(uz_xs[idx]), int(uz_ys[idx])
            dists = np.abs(ws_xs - tx) + np.abs(ws_ys - ty)
            bi = int(np.argmin(dists))
            bwx, bwy = int(ws_xs[bi]), int(ws_ys[bi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    w_ys, w_xs = np.where(wm)
    if len(w_xs) > 0:
        sk = (step * 13) % len(w_xs)
        for off in range(min(len(w_xs), 80)):
            k = (sk + off * 5) % len(w_xs)
            wx2, wy2 = int(w_xs[k]), int(w_ys[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- FALLBACK: place coal plant near unpowered area ----
    for py3 in range(10, WORLD_H, 15):
        for px3 in range(10, WORLD_W, 20):
            if not bool(near_power[py3, px3]):
                for r in range(1, 10):
                    for dy in range(-r, r + 1):
                        for dx in range(-r, r + 1):
                            if abs(dx) == r or abs(dy) == r:
                                nx4, ny4 = px3 + dx, py3 + dy
                                if ib(nx4, ny4) and bool(em[ny4, nx4]):
                                    return (Tool.COALPOWER, nx4, ny4)

    return None

