def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.20:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if pm[nr, nc]:
                    return False
                if not (bool(em[nr, nc]) or bool(zone_tiles[nr, nc])):
                    return False
        return True

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- PHASE 1: ENSURE POWER PLANTS EXIST ACROSS MAP ----
    # Denser grid: 5x4 plants
    plant_targets = []
    for row in range(4):
        for col in range(5):
            px = 12 + col * 24   # 12, 36, 60, 84, 108
            py = 12 + row * 26   # 12, 38, 64, 90
            plant_targets.append((px, py))

    for px, py in plant_targets:
        x0, x1 = max(0, px-7), min(WORLD_W, px+8)
        y0, y1 = max(0, py-7), min(WORLD_H, py+8)
        has_plant = bool(np.any(pm[y0:y1, x0:x1]))
        if not has_plant:
            for r in range(0, 8):
                for dy in range(-r, r+1):
                    for dx in range(-r, r+1):
                        if abs(dx) != r and abs(dy) != r:
                            continue
                        nx, ny = px+dx, py+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    # ---- PHASE 2: WIRE GRID ----
    # Horizontal wire every ~13 rows, vertical wire every ~12 cols
    wire_rows = list(range(6, WORLD_H-4, 13))   # ~7 rows
    wire_cols = list(range(6, WORLD_W-4, 12))   # ~9 cols

    # Road rows/cols: adjacent to wire (offset by +2, avoid overwriting wire)
    road_offsets = [-2, 2]

    phase = step % 6

    if phase == 0:
        # Extend horizontal wire rows reactively
        for wr in wire_rows:
            row_has_power = wm[wr, :] | pm[wr, :]
            if not np.any(row_has_power):
                # Find closest plant and start wire toward wr
                pys, pxs = np.where(pm)
                if len(pxs) > 0:
                    dists = np.abs(pys - wr)
                    best = np.argmin(dists)
                    bpx, bpy = int(pxs[best]), int(pys[best])
                    step_y = 1 if wr > bpy else -1
                    cy = bpy + step_y
                    while cy != wr:
                        if ib(bpx, cy) and bool(em[cy, bpx]):
                            return (Tool.WIRE, bpx, cy)
                        cy += step_y
                    if ib(bpx, wr) and bool(em[wr, bpx]):
                        return (Tool.WIRE, bpx, wr)
            else:
                # BFS-style: extend existing wire leftward and rightward
                for wx in range(1, WORLD_W - 1):
                    if not bool(row_has_power[wx]):
                        if (wx > 0 and bool(row_has_power[wx-1])) or \
                           (wx < WORLD_W-1 and bool(row_has_power[wx+1])):
                            if bool(em[wr, wx]):
                                return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire cols reactively
        for wc in wire_cols:
            col_has_power = wm[:, wc] | pm[:, wc]
            if not np.any(col_has_power):
                pys, pxs = np.where(pm)
                if len(pxs) > 0:
                    dists = np.abs(pxs - wc)
                    best = np.argmin(dists)
                    bpx, bpy = int(pxs[best]), int(pys[best])
                    step_x = 1 if wc > bpx else -1
                    cx = bpx + step_x
                    while cx != wc:
                        if ib(cx, bpy) and bool(em[bpy, cx]):
                            return (Tool.WIRE, cx, bpy)
                        cx += step_x
                    if ib(wc, bpy) and bool(em[bpy, wc]):
                        return (Tool.WIRE, wc, bpy)
            else:
                for wy in range(1, WORLD_H - 1):
                    if not bool(col_has_power[wy]):
                        if (wy > 0 and bool(col_has_power[wy-1])) or \
                           (wy < WORLD_H-1 and bool(col_has_power[wy+1])):
                            if bool(em[wy, wc]):
                                return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads parallel to horizontal wire rows (+2 and -2 offset)
        for wr in wire_rows:
            row_wire = wm[wr, :] | pm[wr, :]
            if not np.any(row_wire):
                continue
            for offset in road_offsets:
                ry = wr + offset
                if not (2 <= ry <= WORLD_H - 3):
                    continue
                for rx in range(2, WORLD_W - 2):
                    if bool(row_wire[rx]) and bool(em[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads parallel to vertical wire cols
        for wc in wire_cols:
            col_wire = wm[:, wc] | pm[:, wc]
            if not np.any(col_wire):
                continue
            for offset in road_offsets:
                rcx = wc + offset
                if not (2 <= rcx <= WORLD_W - 3):
                    continue
                for ry in range(2, WORLD_H - 2):
                    if bool(col_wire[ry]) and bool(em[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Connect road network: extend roads toward powered regions without roads
        needs_road = near_power & ~near_road & em
        needs_road[0:3, :] = False
        needs_road[WORLD_H-3:, :] = False
        needs_road[:, 0:3] = False
        needs_road[:, WORLD_W-3:] = False
        tys, txs = np.where(needs_road)
        if len(txs) > 0:
            road_ys, road_xs = np.where(rm)
            if len(road_xs) > 0:
                ti = (step * 17) % len(txs)
                tx, ty = int(txs[ti]), int(tys[ti])
                dists = np.abs(road_xs - tx) + np.abs(road_ys - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs[best_ri]), int(road_ys[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx+dx, bry), (brx, bry+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    else:
        # Extend wire toward unpowered road regions
        needs_power = rm & ~near_power
        npys, npxs = np.where(needs_power)
        if len(npxs) > 0:
            ti = (step * 23) % len(npxs)
            tx, ty = int(npxs[ti]), int(npys[ti])
            wire_ys, wire_xs = np.where(wm | pm)
            if len(wire_xs) > 0:
                dists = np.abs(wire_xs - tx) + np.abs(wire_ys - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs[best_wi]), int(wire_ys[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx+dx, bwy), (bwx, bwy+dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- ZONE PLACEMENT (primary goal) ----
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H-3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W-3:] = False
    # Avoid wire/plant corridors
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            cand_mask[max(0,wr-1):min(WORLD_H,wr+2), :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            cand_mask[:, max(0,wc-1):min(WORLD_W,wc+2)] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        zone_near = dilate(zone_tiles, 5)
        scores = np.zeros(len(cxs2), dtype=float)
        for i in range(len(cxs2)):
            x, y = int(cxs2[i]), int(cys2[i])
            scores[i] = 2.0 if bool(zone_near[y, x]) else 0.0
            scores[i] += 0.5 / (1.0 + abs(x - 60)/60.0 + abs(y - 50)/50.0)

        order = np.argsort(-scores)
        offset = (step * 7 + pop * 3) % max(len(order), 1)
        tool = pick_tool()
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 500:
                break

    # ---- CIVIC SERVICES based on observed population ----
    if pop > 30:
        fire_positions = [
            (12, 6), (36, 6), (60, 6), (84, 6), (108, 6),
            (12, 32), (36, 32), (60, 32), (84, 32), (108, 32),
            (12, 58), (36, 58), (60, 58), (84, 58), (108, 58),
            (12, 84), (36, 84), (60, 84), (84, 84), (108, 84),
        ]
        for sx, sy in fire_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 150:
        police_positions = [
            (24, 19), (48, 19), (72, 19), (96, 19),
            (12, 45), (36, 45), (60, 45), (84, 45), (108, 45),
            (24, 71), (48, 71), (72, 71), (96, 71),
        ]
        for sx, sy in police_positions:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 400:
        stadiums = [
            (30, 26), (90, 26), (30, 74), (90, 74),
            (60, 13), (60, 87), (15, 50), (105, 50),
        ]
        for sx, sy in stadiums:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 800:
        nuke_spots = [
            (6, 6), (114, 6), (6, 93), (114, 93),
            (60, 6), (6, 50), (114, 50), (60, 93),
        ]
        for nx2, ny2 in nuke_spots:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        seaports = [(5, 93), (114, 93), (5, 6), (114, 6)]
        for sx, sy in seaports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2500:
        airports = [(48, 6), (72, 6), (48, 91), (72, 91)]
        for sx, sy in airports:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks to boost land value reactively
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ---- FALLBACK: extend roads from existing roads toward powered areas ----
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        step_k = (step * 11) % len(road_xs2)
        for offset in range(min(len(road_xs2), 80)):
            k = (step_k + offset * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2+dx2, ry2+dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and \
                   not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ---- FALLBACK: extend wire from existing wire ----
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        step_k2 = (step * 13) % len(wire_xs3)
        for offset in range(min(len(wire_xs3), 50)):
            k = (step_k2 + offset * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2+dx3, wy2+dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    # ---- LAST RESORT: road near zone tiles ----
    zone_ys, zone_xs = np.where(zone_tiles)
    if len(zone_xs) > 0:
        k = (step * 19) % len(zone_xs)
        zx2, zy2 = int(zone_xs[k]), int(zone_ys[k])
        for dx2, dy2 in [(2, 0), (-2, 0), (0, 2), (0, -2)]:
            nx2, ny2 = zx2+dx2, zy2+dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

def init(obs, state):
    """Bootstrap: coal plant + wire cross + initial road grid"""
    actions = []
    # Coal plant at center
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire horizontal from coal plant
    for x in range(54, 88):
        if x != 60:
            actions.append((Tool.WIRE, x, 50))
    # Wire vertical
    for y in range(36, 65):
        if y != 50:
            actions.append((Tool.WIRE, 60, y))
    # Nuclear plant offset
    actions.append((Tool.NUCLEARPOWER, 75, 50))
    # Seed roads: horizontal at y=46,54, vertical at x=50,70
    for x in range(48, 74):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    for y in range(46, 55):
        actions.append((Tool.ROAD, 50, y))
        actions.append((Tool.ROAD, 70, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    powered = obs.powered_zones

    cx, cy = 60, 50

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count

    # Adaptive radius based on pop
    if pop < 200:
        max_radius = 18
    elif pop < 800:
        max_radius = 30
    elif pop < 2000:
        max_radius = 45
    elif pop < 5000:
        max_radius = 60
    else:
        max_radius = 80

    # Distance array from center
    ys_arr = np.arange(WORLD_H).reshape(-1, 1)
    xs_arr = np.arange(WORLD_W).reshape(1, -1)
    dist_arr = np.abs(ys_arr - cy) + np.abs(xs_arr - cx)

    # --- Neighbor masks ---
    def dilate(mask, r):
        out = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy in range(-r, r+1):
            for dx in range(-r, r+1):
                if abs(dx)+abs(dy) > r:
                    continue
                sr0 = max(0, -dy); sr1 = min(WORLD_H, WORLD_H-dy)
                sc0 = max(0, -dx); sc1 = min(WORLD_W, WORLD_W-dx)
                r0 = max(0, dy); r1 = min(WORLD_H, WORLD_H+dy)
                c0 = max(0, dx); c1 = min(WORLD_W, WORLD_W+dx)
                out[r0:r1, c0:c1] |= mask[sr0:sr1, sc0:sc1]
        return out

    nbr_road = dilate(rm, 2)
    nbr_power = dilate(wm | pm, 5)

    zone_tiles = resm | comm | indm

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy+dr, zx+dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    def pick_tool():
        t = max(total_zones, 1)
        ir = ind_count / t
        cr = com_count / t
        rr = res_count / t
        # Target: 30% ind, 25% com, 45% res
        if ir < 0.30:
            return Tool.INDUSTRIAL
        if cr < 0.25:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    plant_count = int(np.sum(pm))

    # === PHASE 1: Power plants ===
    if pop > 400 and plant_count < 2:
        for px, py in [(45, 50), (75, 36), (45, 64), (75, 64)]:
            if ib(px, py):
                clear = all(ib(px+dx, py+dy) and bool(em[py+dy, px+dx])
                            for dx in range(-1,2) for dy in range(-1,2))
                if clear:
                    return (Tool.COALPOWER, px, py)

    if pop > 1000 and plant_count < 3:
        for px, py in [(40, 36), (80, 36), (40, 64), (80, 64)]:
            if ib(px, py):
                clear = all(ib(px+dx, py+dy) and bool(em[py+dy, px+dx])
                            for dx in range(-1,2) for dy in range(-1,2))
                if clear:
                    return (Tool.NUCLEARPOWER, px, py)

    if pop > 3000 and plant_count < 5:
        for px, py in [(25, 30), (95, 30), (25, 70), (95, 70)]:
            if ib(px, py):
                clear = all(ib(px+dx, py+dy) and bool(em[py+dy, px+dx])
                            for dx in range(-1,2) for dy in range(-1,2))
                if clear:
                    return (Tool.NUCLEARPOWER, px, py)

    # === PHASE 2: Wire extension - reactive BFS-like frontier ===
    # Every 4 steps, extend wire toward zones that need power
    if step % 4 == 0:
        # Find empty cells adjacent to wire/plant, ordered by dist
        wire_front_mask = em & ~pm & (dist_arr <= max_radius + 15)
        # Adjacent to existing wire or plant
        adj_power_src = dilate(wm | pm, 1)
        wire_cands = wire_front_mask & adj_power_src
        wy_arr, wx_arr = np.where(wire_cands)
        if len(wx_arr) > 0:
            dists = dist_arr[wy_arr, wx_arr]
            # Prefer cells that are near zones needing power
            # Score: close to existing road & zone, within radius
            scores = dists.astype(float)
            # Prefer cells also near roads (more useful wire)
            road_near = nbr_road[wy_arr, wx_arr]
            scores -= road_near.astype(float) * 3
            order = np.argsort(scores)
            off = (step * 7) % max(len(order), 1)
            for i in range(min(len(order), 80)):
                k = order[(off + i) % len(order)]
                wx, wy = int(wx_arr[k]), int(wy_arr[k])
                if bool(em[wy, wx]) and not bool(pm[wy, wx]):
                    return (Tool.WIRE, wx, wy)

    # === PHASE 3: Road network - grid pattern, reactive extension ===
    # Build road grid: horizontal every 4 rows (y=34,38,42,46,50,54,58,62,66)
    #                  vertical every 5 cols (x=40,45,50,55,60,65,70,75,80)
    road_row_ys = list(range(34, 67, 4))
    road_col_xs = list(range(38, 83, 5))

    if step % 4 == 1:
        # Extend horizontal roads
        for ry in road_row_ys:
            if abs(ry - cy) > max_radius + 5:
                continue
            x_lo = max(2, cx - max_radius)
            x_hi = min(WORLD_W - 3, cx + max_radius)
            for rx in range(x_lo, x_hi):
                if bool(em[ry, rx]) and not bool(pm[ry, rx]):
                    # Connected to existing road on left or right
                    adj = ((rx > 0 and bool(rm[ry, rx-1])) or
                           (rx < WORLD_W-1 and bool(rm[ry, rx+1])))
                    if adj:
                        return (Tool.ROAD, rx, ry)

    elif step % 4 == 2:
        # Extend vertical roads
        for rxc in road_col_xs:
            if abs(rxc - cx) > max_radius + 5:
                continue
            y_lo = max(2, cy - max_radius)
            y_hi = min(WORLD_H - 3, cy + max_radius)
            for ry in range(y_lo, y_hi):
                if bool(em[ry, rxc]) and not bool(pm[ry, rxc]):
                    adj = ((ry > 0 and bool(rm[ry-1, rxc])) or
                           (ry < WORLD_H-1 and bool(rm[ry+1, rxc])))
                    if adj:
                        return (Tool.ROAD, rxc, ry)

    # === PHASE 4: Zone placement ===
    cand_mask = em & nbr_road & nbr_power & (dist_arr <= max_radius)
    cand_mask[0:2, :] = False
    cand_mask[WORLD_H-2:, :] = False
    cand_mask[:, 0:2] = False
    cand_mask[:, WORLD_W-2:] = False

    cys2, cxs2 = np.where(cand_mask)
    if len(cxs2) > 0:
        dists = dist_arr[cys2, cxs2]
        order = np.argsort(dists)
        tool = pick_tool()
        off = (step * 5) % max(len(order), 1)
        for i in range(min(len(order), 400)):
            k = order[(off + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # === CIVIC SERVICES ===
    if pop > 150:
        fire_spots = [(48, 38), (72, 38), (48, 62), (72, 62),
                      (60, 34), (60, 66), (36, 50), (84, 50),
                      (55, 44), (65, 44), (55, 56), (65, 56)]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 500:
        police_spots = [(52, 42), (68, 42), (52, 58), (68, 58),
                        (44, 50), (76, 50), (60, 40), (60, 60)]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 1000:
        for sx, sy in [(57, 44), (63, 44), (57, 56), (63, 56),
                       (50, 50), (70, 50)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 3000:
        for sx, sy in [(10, 88), (110, 88), (10, 12), (110, 12)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 6000:
        for sx, sy in [(15, 50), (105, 50), (60, 10), (60, 90)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for land value boost
    if pop > 300 and step % 7 == 0:
        park_ys, park_xs = np.where(em & nbr_road & nbr_power & (dist_arr <= max_radius))
        if len(park_xs) > 0:
            idx = (step * 11) % len(park_xs)
            return (Tool.PARK, int(park_xs[idx]), int(park_ys[idx]))

    # === FALLBACK: extend roads from existing road network ===
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11) % len(road_xs2)
        for off in range(min(len(road_xs2), 80)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            if int(dist_arr[ry2, rx2]) > max_radius + 8:
                continue
            for dx, dy in [(0,1),(1,0),(0,-1),(-1,0)]:
                nx, ny = rx2+dx, ry2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if bool(nbr_power[ny, nx]):
                        return (Tool.ROAD, nx, ny)

    # === FALLBACK: extend wire from existing wire/plant ===
    wire_ys2, wire_xs2 = np.where(wm | pm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 80)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx, dy in [(1,0),(-1,0),(0,1),(0,-1)]:
                nx, ny = wx2+dx, wy2+dy
                if ib(nx, ny) and bool(em[ny, nx]) and not bool(pm[ny, nx]):
                    if int(dist_arr[ny, nx]) <= max_radius + 20:
                        return (Tool.WIRE, nx, ny)

    # Emergency: place coal plant near center if no power
    if not bool(nbr_power[cy, cx]):
        for r in range(1, 12):
            for dy in range(-r, r+1):
                for dx in range(-r, r+1):
                    if abs(dx) == r or abs(dy) == r:
                        nx, ny = cx+dx, cy+dy
                        if ib(nx, ny) and bool(em[ny, nx]):
                            return (Tool.COALPOWER, nx, ny)

    return None

def init(obs, state):
    """Bootstrap: central power plants + wire/road spine"""
    actions = []
    # Coal plants at key positions
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 50))
    for px in [20, 60, 100]:
        actions.append((Tool.COALPOWER, px, 20))
        actions.append((Tool.COALPOWER, px, 80))
    # Horizontal wire spines at key rows
    for x in range(1, 119):
        for wy in [20, 40, 50, 60, 80]:
            actions.append((Tool.WIRE, x, wy))
    # Vertical wire spines at key cols
    for y in range(1, 99):
        for wx in [20, 40, 60, 80, 100]:
            actions.append((Tool.WIRE, wx, y))
    # Roads flanking horizontal spines
    for x in range(1, 119):
        for wy in [20, 40, 50, 60, 80]:
            actions.append((Tool.ROAD, x, wy - 1))
            actions.append((Tool.ROAD, x, wy + 1))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)
    zone_tiles = resm | comm | indm

    wire_rows = [20, 40, 50, 60, 80]
    wire_cols = [20, 40, 60, 80, 100]

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        # Target: 40% res, 35% com, 25% ind
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 6)
    near_road = dilate(rm, 2)

    # ---- REACTIVE: Check powered zones vs total zones ----
    powered_frac = obs.powered_zones / max(total_zones, 1) if total_zones > 0 else 1.0

    # ---- REACTIVE: If many zones unpowered, prioritize wiring ----
    if powered_frac < 0.6 and total_zones > 5:
        # Find unpowered zone tiles, wire toward nearest wire/plant
        unpowered_mask = zone_tiles & ~near_power
        zone_ys_u, zone_xs_u = np.where(unpowered_mask)
        if len(zone_xs_u) > 0:
            wire_ys_a, wire_xs_a = np.where(wm | pm)
            if len(wire_xs_a) > 0:
                # Pick a random unpowered zone to fix
                idx = (step * 17) % len(zone_xs_u)
                tx, ty = int(zone_xs_u[idx]), int(zone_ys_u[idx])
                dists = np.abs(wire_xs_a - tx) + np.abs(wire_ys_a - ty)
                best_wi = np.argmin(dists)
                bwx, bwy = int(wire_xs_a[best_wi]), int(wire_ys_a[best_wi])
                dx = 0 if tx == bwx else (1 if tx > bwx else -1)
                dy = 0 if ty == bwy else (1 if ty > bwy else -1)
                for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.WIRE, nx2, ny2)

    # ---- REACTIVE: If zones lack road access, extend roads ----
    if total_zones > 3:
        no_road_mask = zone_tiles & ~near_road
        zone_ys_nr, zone_xs_nr = np.where(no_road_mask)
        if len(zone_xs_nr) > 0:
            road_ys_a, road_xs_a = np.where(rm)
            if len(road_xs_a) > 0:
                idx = (step * 13) % len(zone_xs_nr)
                tx, ty = int(zone_xs_nr[idx]), int(zone_ys_nr[idx])
                dists = np.abs(road_xs_a - tx) + np.abs(road_ys_a - ty)
                best_ri = np.argmin(dists)
                brx, bry = int(road_xs_a[best_ri]), int(road_ys_a[best_ri])
                dx = 0 if tx == brx else (1 if tx > brx else -1)
                dy = 0 if ty == bry else (1 if ty > bry else -1)
                for nx2, ny2 in [(brx + dx, bry), (brx, bry + dy)]:
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    phase = step % 14

    # ---- REACTIVE infra phases ----
    if phase == 0:
        # Extend horizontal wire corridors reactively
        for wr in wire_rows:
            for wx in range(1, WORLD_W - 1):
                if not bool(wm[wr, wx]) and not bool(pm[wr, wx]):
                    left = wx > 0 and (bool(wm[wr, wx - 1]) or bool(pm[wr, wx - 1]))
                    right = wx < WORLD_W - 1 and (bool(wm[wr, wx + 1]) or bool(pm[wr, wx + 1]))
                    if (left or right) and bool(em[wr, wx]):
                        return (Tool.WIRE, wx, wr)

    elif phase == 1:
        # Extend vertical wire corridors reactively
        for wc in wire_cols:
            for wy in range(1, WORLD_H - 1):
                if not bool(wm[wy, wc]) and not bool(pm[wy, wc]):
                    up = wy > 0 and (bool(wm[wy - 1, wc]) or bool(pm[wy - 1, wc]))
                    dn = wy < WORLD_H - 1 and (bool(wm[wy + 1, wc]) or bool(pm[wy + 1, wc]))
                    if (up or dn) and bool(em[wy, wc]):
                        return (Tool.WIRE, wc, wy)

    elif phase == 2:
        # Roads above/below wire rows
        for wr in wire_rows:
            for offset in [-1, 1]:
                ry = wr + offset
                if not (0 < ry < WORLD_H - 1):
                    continue
                for rx in range(1, WORLD_W - 1):
                    if (bool(wm[wr, rx]) or bool(pm[wr, rx])) and bool(em[ry, rx]) and not bool(pm[ry, rx]):
                        return (Tool.ROAD, rx, ry)

    elif phase == 3:
        # Roads left/right of wire cols
        for wc in wire_cols:
            for offset in [-1, 1]:
                rcx = wc + offset
                if not (0 < rcx < WORLD_W - 1):
                    continue
                for ry in range(1, WORLD_H - 1):
                    if (bool(wm[ry, wc]) or bool(pm[ry, wc])) and bool(em[ry, rcx]) and not bool(pm[ry, rcx]):
                        return (Tool.ROAD, rcx, ry)

    elif phase == 4:
        # Cross-streets at midpoints between wire rows
        for wi in range(len(wire_rows) - 1):
            r1, r2 = wire_rows[wi], wire_rows[wi + 1]
            mid_y = (r1 + r2) // 2
            for rx in range(1, WORLD_W - 1):
                if bool(em[mid_y, rx]) and bool(near_power[mid_y, rx]) and not bool(pm[mid_y, rx]):
                    adj = ((rx > 0 and bool(rm[mid_y, rx - 1])) or
                           (rx < WORLD_W - 1 and bool(rm[mid_y, rx + 1])))
                    if adj:
                        return (Tool.ROAD, rx, mid_y)

    elif phase == 5:
        # Vertical roads between wire cols
        for wc_i in range(len(wire_cols) - 1):
            c1, c2 = wire_cols[wc_i], wire_cols[wc_i + 1]
            mid_x = (c1 + c2) // 2
            for ry in range(1, WORLD_H - 1):
                if bool(em[ry, mid_x]) and bool(near_power[ry, mid_x]) and not bool(pm[ry, mid_x]):
                    adj = ((ry > 0 and bool(rm[ry - 1, mid_x])) or
                           (ry < WORLD_H - 1 and bool(rm[ry + 1, mid_x])))
                    if adj:
                        return (Tool.ROAD, mid_x, ry)

    elif phase == 6:
        # REACTIVE: Extend road from existing road toward empty powered area
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            sk = (step * 11) % len(road_xs)
            for off in range(min(len(road_xs), 200)):
                k = (sk + off * 7) % len(road_xs)
                rx2, ry2 = int(road_xs[k]), int(road_ys[k])
                for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                    nx2, ny2 = rx2 + dx2, ry2 + dy2
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    elif phase == 7:
        # REACTIVE: Place power plant if any neighborhood has no nearby plant
        # Check a grid of positions for power coverage gaps
        for cy in range(10, 95, 18):
            for cx in range(10, 115, 20):
                x0, x1 = max(0, cx - 18), min(WORLD_W, cx + 19)
                y0, y1 = max(0, cy - 18), min(WORLD_H, cy + 19)
                has_plant = bool(np.any(pm[y0:y1, x0:x1]))
                if not has_plant:
                    # Find empty spot near center
                    for r in range(2, 20):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r:
                                    nx2, ny2 = cx + dx, cy + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    elif phase in (8, 9):
        # Civic services based on observed population
        if pop > 20:
            fire_spots = [(5, 5), (30, 5), (60, 5), (90, 5), (115, 5),
                          (5, 30), (30, 30), (60, 30), (90, 30), (115, 30),
                          (5, 50), (30, 50), (90, 50), (115, 50),
                          (5, 70), (30, 70), (60, 70), (90, 70), (115, 70),
                          (5, 93), (30, 93), (60, 93), (90, 93), (115, 93)]
            for sx, sy in fire_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.FIRESTATION, sx, sy)

        if pop > 150:
            police_spots = [(15, 12), (55, 12), (95, 12),
                            (15, 45), (55, 45), (95, 45),
                            (15, 65), (55, 65), (95, 65),
                            (15, 88), (55, 88), (95, 88)]
            for sx, sy in police_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.POLICESTATION, sx, sy)

        if pop > 400:
            stadium_spots = [(35, 25), (85, 25), (35, 75), (85, 75), (60, 50)]
            for sx, sy in stadium_spots:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.STADIUM, sx, sy)

        if pop > 700:
            nuke_spots = [(5, 50), (115, 50), (60, 5), (60, 93),
                          (5, 5), (115, 5), (5, 93), (115, 93)]
            for nx2, ny2 in nuke_spots:
                if ib(nx2, ny2) and bool(em[ny2, nx2]):
                    return (Tool.NUCLEARPOWER, nx2, ny2)

        if pop > 1000:
            seaports = [(5, 93), (115, 93), (5, 5), (115, 5)]
            for sx, sy in seaports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.SEAPORT, sx, sy)

        if pop > 1800:
            airports = [(50, 5), (70, 5), (50, 90), (70, 90), (5, 45), (115, 45)]
            for sx, sy in airports:
                if ib(sx, sy) and bool(em[sy, sx]):
                    return (Tool.AIRPORT, sx, sy)

    # ---- MAIN ZONE PLACEMENT: REACTIVE ----
    # Build candidate mask based on CURRENT map state
    cand_mask = em & near_road & near_power
    cand_mask[0:3, :] = False
    cand_mask[WORLD_H - 3:, :] = False
    cand_mask[:, 0:3] = False
    cand_mask[:, WORLD_W - 3:] = False
    for wr in wire_rows:
        cand_mask[max(0, wr - 1):wr + 2, :] = False
    for wc in wire_cols:
        cand_mask[:, max(0, wc - 1):wc + 2] = False

    # REACTIVE: Score candidates by density of existing zones nearby
    # (prefer filling in gaps near existing development)
    cys2, cxs2 = np.where(cand_mask)

    if len(cxs2) > 0:
        def zone_clear(zx, zy):
            for dr in range(-1, 2):
                for dc in range(-1, 2):
                    nr, nc = zy + dr, zx + dc
                    if not ib(nc, nr):
                        return False
                    if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                        return False
            return True

        tool = pick_tool()

        # REACTIVE scoring: prefer spots near existing zones (infill)
        # but also near power/road (already filtered)
        # Use distance to nearest existing zone as secondary score
        if total_zones > 0:
            zone_ys_all, zone_xs_all = np.where(zone_tiles)
            # Score = distance to nearest zone (prefer close = infill)
            # But also want some spread, so use a blend
            scores = np.zeros(len(cxs2))
            if len(zone_xs_all) > 0:
                # Batch distance to nearest zone
                for i in range(0, len(cxs2), 500):
                    batch_x = cxs2[i:i + 500]
                    batch_y = cys2[i:i + 500]
                    # Min dist to any zone
                    min_dists = np.full(len(batch_x), 9999.0)
                    for j in range(min(len(zone_xs_all), 50)):
                        d = np.abs(batch_x - zone_xs_all[j]).astype(float) + np.abs(batch_y - zone_ys_all[j]).astype(float)
                        min_dists = np.minimum(min_dists, d)
                    scores[i:i + len(batch_x)] = min_dists

            # Prefer spots 3-8 tiles from existing zones (adjacent but not overlapping)
            # penalize too close (<3) or too far (>20)
            ideal_dist = 6.0
            adjusted = np.abs(scores - ideal_dist)
            order = np.argsort(adjusted)
        else:
            # No zones yet: pick closest to center
            center_x, center_y = 60, 50
            dists = np.abs(cxs2 - center_x).astype(float) + np.abs(cys2 - center_y).astype(float)
            order = np.argsort(dists)

        offset = (step * 7 + pop * 3) % max(len(order), 1)
        checked = 0
        for i in range(len(order)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs2[k]), int(cys2[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)
            checked += 1
            if checked > 600:
                break

    # Parks for land value when pop exists
    if pop > 80 and step % 4 == 0:
        park_cands = em & near_road & near_power
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 31 + pop) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # Fallback: wire toward unpowered area
    unpowered_area = em & ~near_power
    if bool(np.any(unpowered_area)):
        wire_ys_arr, wire_xs_arr = np.where(wm | pm)
        unp_ys, unp_xs = np.where(unpowered_area)
        if len(wire_xs_arr) > 0 and len(unp_xs) > 0:
            idx2 = (step * 19) % len(unp_xs)
            tx, ty = int(unp_xs[idx2]), int(unp_ys[idx2])
            dists = np.abs(wire_xs_arr - tx) + np.abs(wire_ys_arr - ty)
            best_wi = np.argmin(dists)
            bwx, bwy = int(wire_xs_arr[best_wi]), int(wire_ys_arr[best_wi])
            dx = 0 if tx == bwx else (1 if tx > bwx else -1)
            dy = 0 if ty == bwy else (1 if ty > bwy else -1)
            for nx2, ny2 in [(bwx + dx, bwy), (bwx, bwy + dy)]:
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                    return (Tool.WIRE, nx2, ny2)

    # Last fallback: extend any existing wire
    wire_ys3, wire_xs3 = np.where(wm)
    if len(wire_xs3) > 0:
        sk2 = (step * 13) % len(wire_xs3)
        for off in range(min(len(wire_xs3), 80)):
            k = (sk2 + off * 5) % len(wire_xs3)
            wx2, wy2 = int(wire_xs3[k]), int(wire_ys3[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central coal plant with wire spine and road grid"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Wire horizontally across the center
    for x in range(62, 110):
        actions.append((Tool.WIRE, x, 50))
    for x in range(12, 58):
        actions.append((Tool.WIRE, x, 50))
    # Wire vertically
    for y in range(35, 48):
        actions.append((Tool.WIRE, 60, y))
    for y in range(52, 65):
        actions.append((Tool.WIRE, 60, y))
    # Main roads forming a cross
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 40))
        actions.append((Tool.ROAD, x, 60))
    for y in range(5, 95):
        actions.append((Tool.ROAD, 40, y))
        actions.append((Tool.ROAD, 80, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    step = obs.step
    pop = obs.city_pop
    funds = obs.funds

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, radius):
        result = mask.copy()
        for d in range(1, radius + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 3)
    near_road = dilate(rm, 2)

    # Target zone mix: 40% res, 35% com, 25% ind
    def pick_tool_ratio():
        if total_zones == 0:
            return Tool.RESIDENTIAL
        ir = ind_count / max(total_zones, 1)
        cr = com_count / max(total_zones, 1)
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.35:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # --- PHASE 1: Ensure enough coal plants spread across map ---
    # Place plants in a denser grid than parent: every 15 tiles
    plant_grid_spacing = 15
    plant_positions = []
    for py in range(10, 95, plant_grid_spacing):
        for px in range(10, 115, plant_grid_spacing):
            plant_positions.append((px, py))

    for px, py in plant_positions:
        if not ib(px, py):
            continue
        x0, x1 = max(0, px - 6), min(WORLD_W, px + 7)
        y0, y1 = max(0, py - 6), min(WORLD_H, py + 7)
        if not np.any(pm[y0:y1, x0:x1]):
            if bool(em[py, px]):
                return (Tool.COALPOWER, px, py)

    # --- PHASE 2: Wire network - connect plants and reach unpowered areas ---
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1: shifted[:-1, :] = power_src[1:, :]
        elif dy == 1: shifted[1:, :] = power_src[:-1, :]
        elif dx == -1: shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1: shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    wire_cand = em & ~rm & ~zone_tiles & adj_to_power
    wire_cand[0:2, :] = False
    wire_cand[WORLD_H-2:, :] = False
    wire_cand[:, 0:2] = False
    wire_cand[:, WORLD_W-2:] = False

    wys, wxs = np.where(wire_cand)
    if len(wxs) > 0:
        # Wire toward unpowered plants first
        unpowered_plants = [(px, py) for px, py in plant_positions
                            if ib(px, py) and bool(pm[py, px]) and not bool(near_power[py, px])]
        if unpowered_plants:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - ppx) + abs(cy - ppy) for ppx, ppy in unpowered_plants[:10])
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire toward unpowered zones
        unpowered_zones = zone_tiles & ~near_power
        zys, zxs = np.where(unpowered_zones)
        if len(zxs) > 0:
            best_dist = 1e9
            best_k = 0
            for i in range(min(len(wxs), 500)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - zx) + abs(cy - zy) for zx, zy in zip(zxs[:20], zys[:20]))
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

        # Wire outward to unpowered empty areas
        unpowered_empty = em & ~near_power
        upys, upxs = np.where(unpowered_empty)
        if len(upxs) > 0:
            best_dist = 1e9
            best_k = 0
            rng = np.random.default_rng(step)
            sample_idx = rng.choice(len(upxs), min(50, len(upxs)), replace=False)
            for i in range(min(len(wxs), 300)):
                cx, cy = int(wxs[i]), int(wys[i])
                d = min(abs(cx - int(upxs[j])) + abs(cy - int(upys[j])) for j in sample_idx)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.WIRE, int(wxs[best_k]), int(wys[best_k]))

    # --- PHASE 3: Dense road grid every 6 tiles (denser than parent's 4-tile) ---
    # Use 6-tile spacing for roads so zones can pack between them
    road_spacing = 6
    road_targets = []
    for gy in range(road_spacing, 100 - road_spacing + 1, road_spacing):
        for gx in range(road_spacing, 120 - road_spacing + 1, road_spacing):
            road_targets.append((gx, gy))

    uncovered_road = [(gx, gy) for gx, gy in road_targets
                      if ib(gx, gy) and not bool(rm[gy, gx]) and bool(near_power[gy, gx])]

    if uncovered_road:
        adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
        for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            shifted = np.zeros_like(rm)
            if dy == -1: shifted[:-1, :] = rm[1:, :]
            elif dy == 1: shifted[1:, :] = rm[:-1, :]
            elif dx == -1: shifted[:, :-1] = rm[:, 1:]
            elif dx == 1: shifted[:, 1:] = rm[:, :-1]
            adj_to_road |= shifted

        road_cand = em & adj_to_road & near_power & ~zone_tiles
        road_cand[0:2, :] = False
        road_cand[WORLD_H-2:, :] = False
        road_cand[:, 0:2] = False
        road_cand[:, WORLD_W-2:] = False

        rys2, rxs2 = np.where(road_cand)
        if len(rxs2) > 0:
            best_dist = 1e9
            best_k = 0
            targets_sample = uncovered_road[:40]
            for i in range(min(len(rxs2), 500)):
                cx, cy = int(rxs2[i]), int(rys2[i])
                d = min(abs(cx - gx) + abs(cy - gy) for gx, gy in targets_sample)
                if d < best_dist:
                    best_dist = d
                    best_k = i
            return (Tool.ROAD, int(rxs2[best_k]), int(rys2[best_k]))
        else:
            for gx, gy in uncovered_road[:10]:
                if ib(gx, gy) and bool(em[gy, gx]):
                    return (Tool.ROAD, gx, gy)

    # --- PHASE 4: Zone placement with commercial/industrial bias ---
    zone_cand = em & near_road & near_power
    zone_cand[0:4, :] = False
    zone_cand[WORLD_H-4:, :] = False
    zone_cand[:, 0:4] = False
    zone_cand[:, WORLD_W-4:] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        if total_zones > 0:
            zone_ys, zone_xs = np.where(zone_tiles)
            stride = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
        else:
            zone_dist = np.zeros(len(cxs_arr))

        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            stride2 = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride2):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = np.full(len(cxs_arr), 5.0)

        # Score: prefer close to road, spread out from existing zones
        score = road_dist * 1.2 + np.maximum(0, 10 - zone_dist) * 1.8
        order = np.argsort(score)
        off = (step * 13 + pop * 7) % max(len(order), 1)

        # Zone cycling: 4 com, 3 res, 3 ind per 10-step cycle (more commercial than parent)
        step_mod = step % 10
        if step_mod < 4:
            tool = Tool.COMMERCIAL
        elif step_mod < 7:
            tool = Tool.RESIDENTIAL
        else:
            tool = Tool.INDUSTRIAL
        # Override with ratio-based pick if ratios very off
        tool = pick_tool_ratio() if (
            ind_count / max(total_zones, 1) < 0.15 or
            com_count / max(total_zones, 1) < 0.25
        ) else tool

        for i in range(min(len(order), 800)):
            k = order[(off + i) % len(order)]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # --- PHASE 5: Civic services scaled to population ---
    if pop > 50:
        fire_positions = [(fx, fy) for fy in range(8, 95, 8) for fx in range(8, 115, 8)]
        for fsx, fsy in fire_positions:
            if ib(fsx, fsy) and bool(em[fsy, fsx]) and bool(near_road[fsy, fsx]) and bool(near_power[fsy, fsx]):
                return (Tool.FIRESTATION, fsx, fsy)

    if pop > 120:
        police_positions = [(px2, py2) for py2 in range(10, 92, 10) for px2 in range(10, 112, 10)]
        for psx, psy in police_positions:
            if ib(psx, psy) and bool(em[psy, psx]) and bool(near_road[psy, psx]) and bool(near_power[psy, psx]):
                return (Tool.POLICESTATION, psx, psy)

    if pop > 250:
        park_positions = [(pkx, pky) for pky in range(8, 95, 8) for pkx in range(8, 115, 8)]
        for pkx, pky in park_positions:
            if ib(pkx, pky) and bool(em[pky, pkx]) and bool(near_road[pky, pkx]):
                return (Tool.PARK, pkx, pky)

    if pop > 400:
        stadium_locs = [(20, 20), (60, 20), (100, 20),
                        (20, 50), (60, 50), (100, 50),
                        (20, 80), (60, 80), (100, 80)]
        for stx, sty in stadium_locs:
            if ib(stx, sty) and bool(em[sty, stx]) and bool(near_power[sty, stx]):
                return (Tool.STADIUM, stx, sty)

    if pop > 700:
        # Upgrade to nuclear power
        nuke_locs = [(60, 50), (30, 25), (90, 25), (30, 75), (90, 75),
                     (60, 10), (60, 90), (10, 50), (110, 50)]
        for nx, ny in nuke_locs:
            if ib(nx, ny):
                x0, x1 = max(0, nx-6), min(WORLD_W, nx+7)
                y0, y1 = max(0, ny-6), min(WORLD_H, ny+7)
                if not np.any(pm[y0:y1, x0:x1]) and bool(em[ny, nx]):
                    return (Tool.NUCLEARPOWER, nx, ny)

    if pop > 1000:
        airport_locs = [(50, 8), (70, 8), (50, 90), (70, 90),
                        (8, 30), (110, 30), (8, 70), (110, 70)]
        for apx, apy in airport_locs:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 1500:
        seaport_locs = [(10, 50), (110, 50), (60, 8), (60, 91)]
        for spx, spy in seaport_locs:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # --- Fallback: lay roads/wires near existing plants ---
    pwr_ys, pwr_xs = np.where(pm)
    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px2, py2 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx2, dy2 in [(3, 0), (-3, 0), (0, 3), (0, -3), (2, 2), (-2, -2), (4, 0), (0, 4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    if len(pwr_xs) > 0:
        k = step % len(pwr_xs)
        px3, py3 = int(pwr_xs[k]), int(pwr_ys[k])
        for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1), (2, 0), (0, 2)]:
            nx3, ny3 = px3 + dx3, py3 + dy3
            if ib(nx3, ny3) and bool(em[ny3, nx3]):
                return (Tool.WIRE, nx3, ny3)

    return None

def init(obs, state):
    """Bootstrap: central power plant + cross of wires + seed roads"""
    actions = []
    # Central coal plant
    actions.append((Tool.COALPOWER, 60, 50))
    # Horizontal wire spine
    for x in range(10, 110):
        actions.append((Tool.WIRE, x, 50))
    # Vertical wire spine
    for y in range(10, 90):
        actions.append((Tool.WIRE, 60, y))
    # Horizontal roads offset from wire
    for x in range(5, 115):
        actions.append((Tool.ROAD, x, 46))
        actions.append((Tool.ROAD, x, 54))
    # Vertical roads offset from wire
    for y in range(5, 95):
        actions.append((Tool.ROAD, 56, y))
        actions.append((Tool.ROAD, 64, y))
    return actions


def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    n_steps = obs.n_steps

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = res_count + com_count + ind_count
    zone_tiles = resm | comm | indm

    def dilate(mask, r):
        result = mask.copy()
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    power_src = wm | pm
    near_power = dilate(power_src, 2)
    near_road = dilate(rm, 2)

    def pick_tool():
        tz = max(total_zones, 1)
        ir = ind_count / tz
        cr = com_count / tz
        if ir < 0.20:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    # ---- PHASE 0: Ensure we have at least one power plant ----
    if not np.any(pm):
        return (Tool.COALPOWER, 60, 50)

    # ---- PHASE 1: Add more power plants if city grows ----
    # Place coal plants on a grid, only if area lacks power source
    plant_positions = [(x, y) for y in range(20, 85, 20) for x in range(20, 105, 20)]
    for ppx, ppy in plant_positions:
        x0, x1 = max(0, ppx - 9), min(WORLD_W, ppx + 10)
        y0, y1 = max(0, ppy - 9), min(WORLD_H, ppy + 10)
        if not np.any(pm[y0:y1, x0:x1]):
            if ib(ppx, ppy) and bool(em[ppy, ppx]):
                return (Tool.COALPOWER, ppx, ppy)

    # ---- PHASE 2: Extend wire network reactively ----
    # Find power frontier (tiles adjacent to power source that are empty)
    adj_to_power = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(power_src)
        if dy == -1:
            shifted[:-1, :] = power_src[1:, :]
        elif dy == 1:
            shifted[1:, :] = power_src[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = power_src[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = power_src[:, :-1]
        adj_to_power |= shifted

    # Wire target rows/cols for grid coverage
    wire_rows = list(range(20, WORLD_H - 5, 10))
    wire_cols = list(range(20, WORLD_W - 5, 10))

    # For each wire row, extend wire across if not connected
    for wr in wire_rows:
        # Check if row has any power
        row_powered = wm[wr, :] | pm[wr, :]
        if not row_powered.any():
            # Place a wire connecting to vertical power if possible
            col_powered = np.where((wm[:, :] | pm[:, :]).any(axis=0))[0]
            if len(col_powered) > 0:
                best_col = int(col_powered[np.argmin(np.abs(col_powered - 60))])
                if ib(best_col, wr) and bool(em[wr, best_col]) and bool(adj_to_power[wr, best_col]):
                    return (Tool.WIRE, best_col, wr)
            continue
        # Extend left
        indices = np.where(row_powered)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 5 and bool(em[wr, left - 1]):
            return (Tool.WIRE, left - 1, wr)
        if right < WORLD_W - 6 and bool(em[wr, right + 1]):
            return (Tool.WIRE, right + 1, wr)
        # Fill gaps
        for x in range(left + 1, right):
            if bool(em[wr, x]):
                return (Tool.WIRE, x, wr)

    for wc in wire_cols:
        col_powered = wm[:, wc] | pm[:, wc]
        if not col_powered.any():
            row_powered = np.where((wm | pm).any(axis=1))[0]
            if len(row_powered) > 0:
                best_row = int(row_powered[np.argmin(np.abs(row_powered - 50))])
                if ib(wc, best_row) and bool(em[best_row, wc]) and bool(adj_to_power[best_row, wc]):
                    return (Tool.WIRE, wc, best_row)
            continue
        indices = np.where(col_powered)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 5 and bool(em[top - 1, wc]):
            return (Tool.WIRE, wc, top - 1)
        if bot < WORLD_H - 6 and bool(em[bot + 1, wc]):
            return (Tool.WIRE, wc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, wc]):
                return (Tool.WIRE, wc, y)

    # ---- PHASE 3: Road network - roads parallel to wires ----
    # Road rows offset by 4 from wire rows, road cols offset by 4 from wire cols
    road_rows = sorted(set(
        r for wr in wire_rows for r in [wr - 4, wr + 4]
        if 3 < r < WORLD_H - 3
    ))
    road_cols = sorted(set(
        c for wc in wire_cols for c in [wc - 4, wc + 4]
        if 3 < c < WORLD_W - 3
    ))

    for rr in road_rows:
        row_rd = rm[rr, :]
        if not row_rd.any():
            # Start road at center if empty and not on plant
            cx = 60
            if ib(cx, rr) and bool(em[rr, cx]) and not bool(pm[rr, cx]):
                return (Tool.ROAD, cx, rr)
            continue
        indices = np.where(row_rd)[0]
        left = int(indices[0])
        right = int(indices[-1])
        if left > 4 and bool(em[rr, left - 1]) and not bool(pm[rr, left - 1]):
            return (Tool.ROAD, left - 1, rr)
        if right < WORLD_W - 5 and bool(em[rr, right + 1]) and not bool(pm[rr, right + 1]):
            return (Tool.ROAD, right + 1, rr)
        for x in range(left + 1, right):
            if bool(em[rr, x]) and not bool(pm[rr, x]):
                return (Tool.ROAD, x, rr)

    for rc in road_cols:
        col_rd = rm[:, rc]
        if not col_rd.any():
            cy = 50
            if ib(rc, cy) and bool(em[cy, rc]) and not bool(pm[cy, rc]):
                return (Tool.ROAD, rc, cy)
            continue
        indices = np.where(col_rd)[0]
        top = int(indices[0])
        bot = int(indices[-1])
        if top > 4 and bool(em[top - 1, rc]) and not bool(pm[top - 1, rc]):
            return (Tool.ROAD, rc, top - 1)
        if bot < WORLD_H - 5 and bool(em[bot + 1, rc]) and not bool(pm[bot + 1, rc]):
            return (Tool.ROAD, rc, bot + 1)
        for y in range(top + 1, bot):
            if bool(em[y, rc]) and not bool(pm[y, rc]):
                return (Tool.ROAD, rc, y)

    # ---- PHASE 4: Zone placement ----
    # Candidate tiles: empty, near road (within 2), near power (within 2)
    zone_cand = em & near_road & near_power
    # Buffer from edges
    zone_cand[:4, :] = False
    zone_cand[WORLD_H - 4:, :] = False
    zone_cand[:, :4] = False
    zone_cand[:, WORLD_W - 4:] = False
    # Don't place on infrastructure rows/cols (wire and road rows)
    for wr in wire_rows:
        if 0 <= wr < WORLD_H:
            zone_cand[wr, :] = False
    for rr in road_rows:
        if 0 <= rr < WORLD_H:
            zone_cand[rr, :] = False
    for wc in wire_cols:
        if 0 <= wc < WORLD_W:
            zone_cand[:, wc] = False
    for rc in road_cols:
        if 0 <= rc < WORLD_W:
            zone_cand[:, rc] = False

    def zone_clear(zx, zy):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not bool(em[nr, nc]) and not bool(zone_tiles[nr, nc]):
                    return False
        return True

    cys_arr, cxs_arr = np.where(zone_cand)
    if len(cxs_arr) > 0:
        # Score: prefer tiles close to roads AND close to existing zones (density)
        road_ys, road_xs = np.where(rm)
        zone_ys, zone_xs = np.where(zone_tiles)

        if len(road_xs) > 0:
            stride = max(1, len(road_xs) // 80)
            road_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(road_xs), stride):
                d = (np.abs(cxs_arr - road_xs[i]) + np.abs(cys_arr - road_ys[i])).astype(float)
                road_dist = np.minimum(road_dist, d)
        else:
            road_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)

        if len(zone_xs) > 0:
            stride2 = max(1, len(zone_xs) // 80)
            zone_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(zone_xs), stride2):
                d = (np.abs(cxs_arr - zone_xs[i]) + np.abs(cys_arr - zone_ys[i])).astype(float)
                zone_dist = np.minimum(zone_dist, d)
            # Penalty for being too close (overlapping zones) or too far
            zone_score = np.where(zone_dist < 3, 500.0, np.where(zone_dist > 20, zone_dist * 0.3, 0.0))
        else:
            center_dist = (np.abs(cxs_arr - 60) + np.abs(cys_arr - 50)).astype(float)
            zone_score = center_dist * 0.2

        # Power proximity bonus
        pw_ys, pw_xs = np.where(power_src)
        if len(pw_xs) > 0:
            stride3 = max(1, len(pw_xs) // 50)
            pw_dist = np.full(len(cxs_arr), 9999.0)
            for i in range(0, len(pw_xs), stride3):
                d = (np.abs(cxs_arr - pw_xs[i]) + np.abs(cys_arr - pw_ys[i])).astype(float)
                pw_dist = np.minimum(pw_dist, d)
        else:
            pw_dist = np.zeros(len(cxs_arr))

        score = road_dist * 2.0 + zone_score * 0.5 + pw_dist * 0.5
        order = np.argsort(score)

        tool = pick_tool()
        # Try top candidates
        for i in range(min(len(order), 300)):
            k = order[i]
            zx2, zy2 = int(cxs_arr[k]), int(cys_arr[k])
            if zone_clear(zx2, zy2):
                return (tool, zx2, zy2)

    # ---- PHASE 5: Civic buildings based on pop ----
    if pop > 50:
        for fsy in range(14, 90, 15):
            for fsx in range(14, 110, 20):
                if ib(fsx, fsy) and bool(em[fsy, fsx]):
                    return (Tool.FIRESTATION, fsx, fsy)

    if pop > 150:
        for psy in range(12, 90, 18):
            for psx in range(12, 110, 22):
                if ib(psx, psy) and bool(em[psy, psx]):
                    return (Tool.POLICESTATION, psx, psy)

    if pop > 300:
        for pky in range(10, 92, 10):
            for pkx in range(10, 112, 12):
                if ib(pkx, pky) and bool(em[pky, pkx]):
                    return (Tool.PARK, pkx, pky)

    if pop > 600:
        for sty in range(20, 85, 30):
            for stx in range(20, 105, 35):
                if ib(stx, sty) and bool(em[sty, stx]):
                    return (Tool.STADIUM, stx, sty)

    if pop > 1000:
        for npy in range(15, 90, 25):
            for npx in range(15, 110, 25):
                if ib(npx, npy) and bool(em[npy, npx]):
                    x0, x1 = max(0, npx - 10), min(WORLD_W, npx + 11)
                    y0, y1 = max(0, npy - 10), min(WORLD_H, npy + 11)
                    if not np.any(pm[y0:y1, x0:x1]):
                        return (Tool.NUCLEARPOWER, npx, npy)

    if pop > 2000:
        for apx, apy in [(55, 7), (65, 7), (55, 92), (65, 92)]:
            if ib(apx, apy) and bool(em[apy, apx]):
                return (Tool.AIRPORT, apx, apy)

    if pop > 2500:
        for spx, spy in [(7, 50), (112, 50), (60, 4), (60, 95)]:
            if ib(spx, spy) and bool(em[spy, spx]):
                return (Tool.SEAPORT, spx, spy)

    # ---- PHASE 6: Wire toward unpowered zones ----
    unpowered_zones = zone_tiles & ~near_power
    uzys, uzxs = np.where(unpowered_zones)
    wire_cand = em & adj_to_power & ~zone_tiles & ~rm
    wire_cand[:2, :] = False
    wire_cand[WORLD_H - 2:, :] = False
    wire_cand[:, :2] = False
    wire_cand[:, WORLD_W - 2:] = False
    wys_c, wxs_c = np.where(wire_cand)

    if len(wxs_c) > 0 and len(uzxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(uzxs) // 20)
        for i in range(len(wxs_c)):
            cx, cy = int(wxs_c[i]), int(wys_c[i])
            d = min(abs(cx - int(uzxs[j])) + abs(cy - int(uzys[j])) for j in range(0, len(uzxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.WIRE, int(wxs_c[best_k]), int(wys_c[best_k]))
    elif len(wxs_c) > 0:
        k = step % len(wxs_c)
        return (Tool.WIRE, int(wxs_c[k]), int(wys_c[k]))

    # ---- PHASE 7: Road toward unserved zones ----
    unserved_zones = zone_tiles & ~near_road
    usys, usxs = np.where(unserved_zones)

    adj_to_road = np.zeros((WORLD_H, WORLD_W), dtype=bool)
    for dy, dx in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        shifted = np.zeros_like(rm)
        if dy == -1:
            shifted[:-1, :] = rm[1:, :]
        elif dy == 1:
            shifted[1:, :] = rm[:-1, :]
        elif dx == -1:
            shifted[:, :-1] = rm[:, 1:]
        elif dx == 1:
            shifted[:, 1:] = rm[:, :-1]
        adj_to_road |= shifted

    road_cand2 = em & adj_to_road & ~zone_tiles & ~pm & ~wm
    road_cand2[:2, :] = False
    road_cand2[WORLD_H - 2:, :] = False
    road_cand2[:, :2] = False
    road_cand2[:, WORLD_W - 2:] = False
    rys_c, rxs_c = np.where(road_cand2)

    if len(rxs_c) > 0 and len(usxs) > 0:
        best_d = 1e9
        best_k = 0
        stride = max(1, len(usxs) // 20)
        for i in range(len(rxs_c)):
            cx, cy = int(rxs_c[i]), int(rys_c[i])
            d = min(abs(cx - int(usxs[j])) + abs(cy - int(usys[j])) for j in range(0, len(usxs), stride))
            if d < best_d:
                best_d = d
                best_k = i
        return (Tool.ROAD, int(rxs_c[best_k]), int(rys_c[best_k]))

    # ---- Fallback: extend road from nearest plant ----
    pys2, pxs2 = np.where(pm)
    if len(pxs2) > 0:
        k = step % len(pxs2)
        px2, py2 = int(pxs2[k]), int(pys2[k])
        for dx2, dy2 in [(6, 0), (-6, 0), (0, 6), (0, -6), (4, 0), (-4, 0), (0, 4), (0, -4)]:
            nx2, ny2 = px2 + dx2, py2 + dy2
            if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                return (Tool.ROAD, nx2, ny2)

    return None

