def act(obs, state):
    tm = obs.tile_map
    em = empty_mask(tm)
    wm = wire_mask(tm)
    rm = road_mask(tm)
    pm = plant_mask(tm)
    resm = res_mask(tm)
    comm = com_mask(tm)
    indm = ind_mask(tm)

    pop = obs.city_pop
    step = obs.step
    funds = obs.funds
    powered = obs.powered_zones

    def ib(x, y):
        return 0 <= x < WORLD_W and 0 <= y < WORLD_H

    def dilate(mask, r):
        result = mask.copy().astype(bool)
        for d in range(1, r + 1):
            result[d:, :] |= mask[:-d, :]
            result[:-d, :] |= mask[d:, :]
            result[:, d:] |= mask[:, :-d]
            result[:, :-d] |= mask[:, d:]
        return result

    near_power = dilate(wm | pm, 3)
    near_road = dilate(rm, 2)

    res_count = int(np.sum(resm))
    com_count = int(np.sum(comm))
    ind_count = int(np.sum(indm))
    total_zones = max(res_count + com_count + ind_count, 1)

    def pick_tool():
        ir = ind_count / total_zones
        cr = com_count / total_zones
        if ir < 0.25:
            return Tool.INDUSTRIAL
        if cr < 0.30:
            return Tool.COMMERCIAL
        return Tool.RESIDENTIAL

    def zone_clear(zx, zy):
        for dr in range(-1, 2):
            for dc in range(-1, 2):
                nr, nc = zy + dr, zx + dc
                if not ib(nc, nr):
                    return False
                if not (bool(em[nr, nc]) or bool(resm[nr, nc]) or bool(comm[nr, nc]) or bool(indm[nr, nc])):
                    return False
        return True

    # ── POWER COVERAGE: place plant in uncovered region ──────────────────────
    if step % 15 == 0:
        for py in range(10, 95, 20):
            for px in range(10, 115, 20):
                x0, x1 = max(0, px - 12), min(WORLD_W, px + 13)
                y0, y1 = max(0, py - 12), min(WORLD_H, py + 13)
                if not bool(np.any(pm[y0:y1, x0:x1])):
                    for r in range(15):
                        for dy in range(-r, r + 1):
                            for dx in range(-r, r + 1):
                                if abs(dx) == r or abs(dy) == r or r == 0:
                                    nx2, ny2 = px + dx, py + dy
                                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                                        return (Tool.COALPOWER, nx2, ny2)

    # ── WIRE EXTENSION: grow power network toward uncovered empty areas ───────
    if step % 4 in (1, 2):
        power_src = wm | pm
        fy_arr, fx_arr = np.where(power_src)
        if len(fx_arr) > 0:
            n_sample = min(len(fx_arr), 120)
            sh = (step * 41 + pop * 3) % max(len(fx_arr), 1)
            candidates = []
            for i in range(n_sample):
                k = (sh + i * 17) % len(fx_arr)
                fx, fy = int(fx_arr[k]), int(fy_arr[k])
                for dx, dy in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    nx2, ny2 = fx + dx, fy + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(near_power[ny2, nx2]):
                        candidates.append((nx2, ny2))
            if candidates:
                # Prefer direction toward map areas with no power
                best, best_score = None, -1
                pm_ys, pm_xs = np.where(power_src)
                cx_p = float(np.mean(pm_xs)) if len(pm_xs) > 0 else 60.0
                cy_p = float(np.mean(pm_ys)) if len(pm_ys) > 0 else 50.0
                for cx, cy in candidates[:40]:
                    score = abs(cx - cx_p) + abs(cy - cy_p)
                    if score > best_score:
                        best_score = score
                        best = (cx, cy)
                if best:
                    return (Tool.WIRE, best[0], best[1])

    # ── ROAD EXTENSION: grow road grid into powered areas ─────────────────────
    if step % 6 in (3, 4):
        road_ys, road_xs = np.where(rm)
        if len(road_xs) > 0:
            n_sample = min(len(road_xs), 150)
            sk = (step * 19 + pop) % len(road_xs)
            # Try to extend roads in a grid pattern (prefer alternating axes)
            for i in range(n_sample):
                k = (sk + i * 13) % len(road_xs)
                rx, ry = int(road_xs[k]), int(road_ys[k])
                # Prefer grid-aligned directions based on position
                dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]
                for dx, dy in dirs:
                    nx2, ny2 = rx + dx, ry + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]):
                        if bool(near_power[ny2, nx2]):
                            return (Tool.ROAD, nx2, ny2)
        else:
            # No roads — seed near center
            for dx in range(-8, 9):
                for dy in range(-8, 9):
                    nx2, ny2 = 60 + dx, 50 + dy
                    if ib(nx2, ny2) and bool(em[ny2, nx2]):
                        return (Tool.ROAD, nx2, ny2)

    # ── ROAD GRID: build regular grid roads through powered unpaved areas ─────
    if step % 8 == 5:
        # Place roads on a 4-cell grid spacing to create blocks
        grid_spacing = 4
        best_road = None
        best_dist = 9999
        for gy in range(grid_spacing, WORLD_H - grid_spacing, grid_spacing):
            for gx in range(grid_spacing, WORLD_W - grid_spacing, grid_spacing):
                if ib(gx, gy) and bool(em[gy, gx]) and bool(near_power[gy, gx]) and not bool(pm[gy, gx]):
                    dist = abs(gx - 60) + abs(gy - 50)
                    if dist < best_dist:
                        best_dist = dist
                        best_road = (gx, gy)
        if best_road:
            return (Tool.ROAD, best_road[0], best_road[1])

    # ── CIVIC SERVICES ────────────────────────────────────────────────────────
    # Fire stations spread across map
    if pop > 5:
        fire_spots = [
            (10, 10), (35, 10), (60, 10), (85, 10), (110, 10),
            (10, 30), (110, 30), (10, 50), (110, 50),
            (10, 70), (110, 70), (10, 90), (35, 90), (60, 90), (85, 90), (110, 90),
            (30, 25), (55, 25), (80, 25),
            (30, 50), (55, 50), (80, 50),
            (30, 75), (55, 75), (80, 75),
        ]
        for sx, sy in fire_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.FIRESTATION, sx, sy)

    if pop > 50:
        police_spots = [
            (20, 15), (45, 15), (70, 15), (95, 15),
            (20, 40), (45, 40), (70, 40), (95, 40),
            (20, 65), (45, 65), (70, 65), (95, 65),
            (20, 88), (45, 88), (70, 88), (95, 88),
        ]
        for sx, sy in police_spots:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.POLICESTATION, sx, sy)

    if pop > 300:
        for sx, sy in [(25, 20), (80, 20), (25, 50), (80, 50), (25, 78), (80, 78), (50, 35), (100, 35), (50, 65), (100, 65)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.STADIUM, sx, sy)

    if pop > 700:
        for nx2, ny2 in [(15, 50), (105, 50), (60, 15), (60, 85), (30, 15), (90, 15), (30, 85), (90, 85)]:
            if ib(nx2, ny2) and bool(em[ny2, nx2]):
                return (Tool.NUCLEARPOWER, nx2, ny2)

    if pop > 1200:
        for sx, sy in [(5, 90), (115, 90), (5, 10), (115, 10)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.SEAPORT, sx, sy)

    if pop > 2000:
        for sx, sy in [(48, 5), (72, 5), (48, 94), (72, 94)]:
            if ib(sx, sy) and bool(em[sy, sx]):
                return (Tool.AIRPORT, sx, sy)

    # Parks for happiness
    if pop > 80 and step % 5 == 0:
        park_cands = em & near_road & near_power
        park_cands[:2, :] = False
        park_cands[WORLD_H - 2:, :] = False
        park_cands[:, :2] = False
        park_cands[:, WORLD_W - 2:] = False
        pys, pxs = np.where(park_cands)
        if len(pxs) > 0:
            idx = (step * 29 + pop * 11) % len(pxs)
            return (Tool.PARK, int(pxs[idx]), int(pys[idx]))

    # ── ZONE PLACEMENT: react to current power+road coverage ─────────────────
    cand_mask = em & near_road & near_power
    cand_mask[:2, :] = False
    cand_mask[WORLD_H - 2:, :] = False
    cand_mask[:, :2] = False
    cand_mask[:, WORLD_W - 2:] = False
    cand_mask &= ~(wm | rm | pm)

    cys, cxs = np.where(cand_mask)
    if len(cxs) > 0:
        # Determine target placement strategy based on pop
        if pop < 80:
            # Focus on center cluster
            cx_target, cy_target = 60, 50
            dists = np.abs(cxs - cx_target).astype(float) + np.abs(cys - cy_target).astype(float)
        elif pop < 400:
            # Expand in rings
            ring_r = 15 + pop // 15
            dists = np.abs(np.abs(cxs - 60) + np.abs(cys - 50) - ring_r).astype(float)
        else:
            # Fill least-populated quadrant
            q_counts = [
                int(np.sum(resm[:50, :60] + comm[:50, :60] + indm[:50, :60])),
                int(np.sum(resm[:50, 60:] + comm[:50, 60:] + indm[:50, 60:])),
                int(np.sum(resm[50:, :60] + comm[50:, :60] + indm[50:, :60])),
                int(np.sum(resm[50:, 60:] + comm[50:, 60:] + indm[50:, 60:])),
            ]
            min_q = int(np.argmin(q_counts))
            cx_target = 30 if min_q in (0, 2) else 90
            cy_target = 25 if min_q in (0, 1) else 75
            dists = np.abs(cxs - cx_target).astype(float) + np.abs(cys - cy_target).astype(float)

        order = np.argsort(dists)
        tool = pick_tool()
        offset = (step * 7 + pop * 3) % max(len(order), 1)

        for i in range(min(len(order), 600)):
            k = order[(offset + i) % len(order)]
            zx, zy = int(cxs[k]), int(cys[k])
            if zone_clear(zx, zy):
                return (tool, zx, zy)

    # ── FALLBACK: extend road into powered area ───────────────────────────────
    road_ys2, road_xs2 = np.where(rm)
    if len(road_xs2) > 0:
        sk = (step * 11 + pop) % len(road_xs2)
        for off in range(min(len(road_xs2), 200)):
            k = (sk + off * 7) % len(road_xs2)
            rx2, ry2 = int(road_xs2[k]), int(road_ys2[k])
            for dx2, dy2 in [(0, 1), (0, -1), (1, 0), (-1, 0)]:
                nx2, ny2 = rx2 + dx2, ry2 + dy2
                if ib(nx2, ny2) and bool(em[ny2, nx2]) and not bool(pm[ny2, nx2]) and bool(near_power[ny2, nx2]):
                    return (Tool.ROAD, nx2, ny2)

    # ── FALLBACK: extend wire ─────────────────────────────────────────────────
    wire_ys2, wire_xs2 = np.where(wm)
    if len(wire_xs2) > 0:
        sk2 = (step * 13 + pop) % len(wire_xs2)
        for off in range(min(len(wire_xs2), 100)):
            k = (sk2 + off * 5) % len(wire_xs2)
            wx2, wy2 = int(wire_xs2[k]), int(wire_ys2[k])
            for dx3, dy3 in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nx3, ny3 = wx2 + dx3, wy2 + dy3
                if ib(nx3, ny3) and bool(em[ny3, nx3]) and not bool(pm[ny3, nx3]):
                    return (Tool.WIRE, nx3, ny3)

    return None

